/**
 * Simple echo-style client: reads a line from the console, sends it
 * with DataOutputStream, then prints whatever comes back until the
 * user types "stop".
 */
public class Client {

    private static final String HOST = "localhost";
    private static final int PORT = 4444;

    public static void main(String[] args) {
        Socket connection = null;
        DataInputStream fromServer = null;
        DataOutputStream toServer = null;
        BufferedReader console = null;

        try {
            System.out.println("Sunucuya baglanmaya calisiliyor...");
            connection = new Socket(HOST, PORT);
            System.out.println("Sunucuya basariyla baglanildi!");

            fromServer = new DataInputStream(connection.getInputStream());
            toServer = new DataOutputStream(connection.getOutputStream());
            console = new BufferedReader(new InputStreamReader(System.in));

            String typed = "";
            String echoed;

            while (!typed.equals("stop")) {
                System.out.print("Sunucuya gondermek icin bir mesaj girin: ");
                typed = console.readLine();
                toServer.writeUTF(typed);
                toServer.flush();

                echoed = fromServer.readUTF();
                System.out.println("Sunucudan gelen mesaj: " + echoed);
            }

        } catch (Exception e) {
            System.err.println("Bir hata olustu: " + e.getMessage());
            e.printStackTrace();
        } finally {
            closeQuietly(fromServer, toServer, console, connection);
        }
    }

    private static void closeQuietly(DataInputStream in, DataOutputStream out, BufferedReader reader, Socket socket) {
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            if (reader != null) reader.close();
            if (socket != null) socket.close();
            System.out.println("Baglanti kapatildi.");
        } catch (Exception e) {
            System.err.println("Kaynaklar kapatilirken bir hata olustu: " + e.getMessage());
        }
    }
}

public class Islecler {

    public static void main(String[] args) {

        int p = 10;
        int q = 20;
        int r = 30;

        // Arithmetic operators
        int addResult = p + q;      // 30
        int subResult = q - p;      // 10
        int mulResult = p * q;      // 200
        int divResult = q / p;      // 2
        int modResult = q % p;      // 0

        // Relational operators
        boolean isEqual = p == q;             // false
        boolean isNotEqual = p != q;          // true
        boolean isGreater = q > p;            // true
        boolean isLess = p < q;               // true
        boolean isGreaterOrEqual = p >= r;    // false
        boolean isLessOrEqual = p <= q;       // true

        // Logical operators
        boolean andResult = (p < q) && (q < r);   // true
        boolean orResult = (p < q) || (q > r);    // true
        boolean notResult = !(p < q);             // false

        // Report every computed value.
        System.out.println("Toplam: " + addResult);
        System.out.println("Fark: " + subResult);
        System.out.println("Carpim: " + mulResult);
        System.out.println("Bolum: " + divResult);
        System.out.println("Kalan: " + modResult);
        System.out.println("esitMi: " + isEqual);
        System.out.println("esitDegilMi: " + isNotEqual);
        System.out.println("buyukMu: " + isGreater);
        System.out.println("kucukMu: " + isLess);
        System.out.println("buyukVeyaEsitMi: " + isGreaterOrEqual);
        System.out.println("kucukVeyaEsitMi: " + isLessOrEqual);
        System.out.println("veSonuc: " + andResult);
        System.out.println("veyaSonuc: " + orResult);
        System.out.println("degilSonuc: " + notResult);
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Algorithm explanation
 * https://www.educative.io/edpresso/longest-palindromic-subsequence-algorithm
 */
public final class LongestPalindromicSubsequence {
    private LongestPalindromicSubsequence() {
    }

    public static void main(String[] args) {
        String a = "BBABCBCAB";
        String b = "BABCBAB";

        String aLPS = lps(a);
        String bLPS = lps(b);

        System.out.println(a + " => " + aLPS);
        System.out.println(b + " => " + bLPS);
    }

    public static String lps(String original) throws IllegalArgumentException {
        StringBuilder reverse = new StringBuilder(original);
        reverse = reverse.reverse();
        return recursiveLPS(original, reverse.toString());
    }

    private static String recursiveLPS(String original, String reverse) {
        String bestResult = "";

        // no more chars, then return empty
        if (original.length() == 0 || reverse.length() == 0) {
            bestResult = "";
        } else {
            // if the last chars match, then remove it from both strings and recur
            if (original.charAt(original.length() - 1) == reverse.charAt(reverse.length() - 1)) {
                String bestSubResult = recursiveLPS(original.substring(0, original.length() - 1), reverse.substring(0, reverse.length() - 1));

                bestResult = reverse.charAt(reverse.length() - 1) + bestSubResult;
            } else {
                // otherwise (1) ignore the last character of reverse, and recur on original and
                // updated reverse again (2) ignore the last character of original and recur on the
                // updated original and reverse again then select the best result from these two
                // subproblems.

                String bestSubResult1 = recursiveLPS(original, reverse.substring(0, reverse.length() - 1));
                String bestSubResult2 = recursiveLPS(original.substring(0, original.length() - 1), reverse);
                if (bestSubResult1.length() > bestSubResult2.length()) {
                    bestResult = bestSubResult1;
                } else {
                    bestResult = bestSubResult2;
                }
            }
        }

        return bestResult;
    }
}

