        }

        // Yuzler basamagi varsa eklenir
        if (yuz > 0) {
            if (yuz == 1) {
                sonuc += "yuz ";
            } else if (yuz == 2) {
                sonuc += "iki yuz ";
            } else if (yuz == 3) {
                sonuc += "uc yuz ";
            } else if (yuz == 4) {
