public class TicTacToeGUI {

    private static final int BOARD_SIZE = 3;
    private static final String BLANK = " ";

    private final JFrame window;              // top-level application window
    private final JButton[][] cells;          // grid of clickable cells
    private char turnMarker;                  // symbol of whichever player is up next

    public TicTacToeGUI() {
        window = new JFrame("Tic-Tac-Toe");
        cells = new JButton[BOARD_SIZE][BOARD_SIZE];
        turnMarker = 'X';
        buildInterface();
    }

    private void buildInterface() {
        window.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        window.setSize(400, 400);
        window.setLayout(new GridLayout(BOARD_SIZE, BOARD_SIZE));

        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                JButton cellButton = new JButton(BLANK);
                cellButton.setFont(new Font("Arial", Font.PLAIN, 60));
                cells[row][col] = cellButton;
                window.add(cellButton);

                final int fixedRow = row;
                final int fixedCol = col;
                cellButton.addActionListener(new ActionListener() {
                    @Override
                    public void actionPerformed(ActionEvent event) {
                        handleCellClick(fixedRow, fixedCol);
                    }
                });
            }
        }

        window.setVisible(true);
    }

    private void handleCellClick(int row, int col) {
        if (!cells[row][col].getText().equals(BLANK)) {
            return; // cell already taken, ignore the click
        }

        cells[row][col].setText(String.valueOf(turnMarker));

        if (hasWinner()) {
            JOptionPane.showMessageDialog(window, "Tebrikler, " + turnMarker + " kazandi!");
            resetBoard();
        } else if (isDraw()) {
            JOptionPane.showMessageDialog(window, "Oyun berabere bitti!");
            resetBoard();
        } else {
            turnMarker = (turnMarker == 'X') ? 'O' : 'X';
        }
    }

    private boolean hasWinner() {
        String marker = String.valueOf(turnMarker);

        for (int i = 0; i < BOARD_SIZE; i++) {
            if (cells[i][0].getText().equals(marker) &&
                cells[i][1].getText().equals(marker) &&
                cells[i][2].getText().equals(marker)) {
                return true;
            }
            if (cells[0][i].getText().equals(marker) &&
                cells[1][i].getText().equals(marker) &&
                cells[2][i].getText().equals(marker)) {
                return true;
            }
        }

        if (cells[0][0].getText().equals(marker) &&
            cells[1][1].getText().equals(marker) &&
            cells[2][2].getText().equals(marker)) {
            return true;
        }

        return cells[0][2].getText().equals(marker) &&
               cells[1][1].getText().equals(marker) &&
               cells[2][0].getText().equals(marker);
    }

    private boolean isDraw() {
        for (JButton[] rowOfButtons : cells) {
            for (JButton button : rowOfButtons) {
                if (button.getText().equals(BLANK)) {
                    return false;
                }
            }
        }
        return true;
    }

    private void resetBoard() {
        for (JButton[] rowOfButtons : cells) {
            for (JButton button : rowOfButtons) {
                button.setText(BLANK);
            }
        }
        turnMarker = 'X';
    }

    public static void main(String[] args) {
        new TicTacToeGUI();
    }
}

package array;

public class SayiOkuma {

    public static void main(String[] args) {

        System.out.println(sayiOkunusu(1234));  // Sayinin okunusunu yazdir

        System.out.println(sayiOkunusu(7248));  

        System.out.println(sayiOkunusu(297));  

        System.out.println(sayiOkunusu(505));  

        System.out.println(sayiOkunusu(300));  
    }

    // Sayinin okunusunu donduren fonksiyon
    public static String sayiOkunusu(int sayi) {
        // Eger sayi 0 ise "sifir" dondurulur
        if (sayi == 0) return "sifir";

        // Birler, onlar, yuzler ve binler basamagi icin diziler
        String[] birler = {"", "bir", "iki", "uc", "dort", "bes", "alti", "yedi", "sekiz", "dokuz"};
        String[] onlar = {"", "on", "yirmi", "otuz", "kirk", "elli", "altmis", "yetmis", "seksen", "doksan"};
        String[] yuzler = {"", "yuz"};  // Yuzler icin sadece "yuz" kelimesi var
        String[] binler = {"", "bin"};  // Binler icin sadece "bin" kelimesi var

        // Sonuc metnini tutacak degisken
        String sonuc = "";

        // Binler basamagini ayirma
        int bin = sayi / 1000;
        // Yuzler basamagini ayirma
        int yuz = (sayi / 100) % 10;
        // Onlar basamagini ayirma
        int on = (sayi / 10) % 10;
        // Birler basamagini ayirma
        int bir = sayi % 10;

        // Binler basamagi varsa eklenir
        if (bin > 0) {
            // Binler basamagi 1'den buyukse, sayinin okunusu da eklenir
            if (bin > 1) sonuc += birler[bin] + " ";
            sonuc += binler[1] + " ";  // "bin" kelimesi eklenir
        }

        // Yuzler basamagi varsa eklenir
        if (yuz > 0) {
            // Yuzler basamagi 1'den buyukse, sayinin okunusu da eklenir
            if (yuz > 1) sonuc += birler[yuz] + " ";
            sonuc += yuzler[1] + " ";  // "yuz" kelimesi eklenir
        }

        // Onlar basamagi varsa eklenir
        if (on > 0) {
            sonuc += onlar[on] + " ";  // Onlar basamaginin okunusu eklenir
        }

        // Birler basamagi varsa eklenir
        if (bir > 0) {
            sonuc += birler[bir];  // Birler basamaginin okunusu eklenir
        }

        return sonuc;
    }
}

