/**
 * Skip list is a data structure that allows {@code O(log n)} search complexity
 * as well as {@code O(log n)} insertion complexity within an ordered sequence
 * of {@code n} elements. Thus it can get the best features of a sorted array
 * (for searching) while maintaining a linked list-like structure that allows
 * insertion, which is not possible with a static array.
 * <p>
 * A skip list is built in layers. The bottom layer is an ordinary ordered
 * linked list. Each higher layer acts as an "express lane" for the lists
 * below.
 * <pre>
 * [ ] ------> [ ] --> [ ]
 * [ ] --> [ ] [ ] --> [ ]
 * [ ] [ ] [ ] [ ] [ ] [ ]
 *  H   0   1   2   3   4
 * </pre>
 *
 * @param <E> type of elements
 * @see <a href="https://en.wikipedia.org/wiki/Skip_list">Wiki. Skip list</a>
 */
@SuppressWarnings({"rawtypes", "unchecked"})
public class SkipList<E extends Comparable<E>> {

    /**
     * Node before first node.
     */
    private final Node<E> head;

    /**
     * Maximum layers count.
     * Calculated by {@link #heightStrategy}.
     */
    private final int height;

    /**
     * Function for determining height of new nodes.
     * @see HeightStrategy
     */
    private final HeightStrategy heightStrategy;

    /**
     * Current count of elements in list.
     */
    private int size;

    private static final int DEFAULT_CAPACITY = 100;

    public SkipList() {
        this(DEFAULT_CAPACITY, new BernoulliHeightStrategy());
    }

    public SkipList(int expectedCapacity, HeightStrategy heightStrategy) {
        this.heightStrategy = heightStrategy;
        this.height = heightStrategy.height(expectedCapacity);
        this.head = new Node<>(null, this.height);
        this.size = 0;
    }

    public void add(E e) {
        Objects.requireNonNull(e);
        Node<E> current = head;
        int layer = height;
        Node<E>[] toFix = new Node[height + 1];

        while (layer >= 0) {
            Node<E> next = current.next(layer);
            if (next == null || next.getValue().compareTo(e) > 0) {
                toFix[layer] = current;
                layer--;
            } else {
                current = next;
            }
        }
        int nodeHeight = heightStrategy.nodeHeight(height);
        Node<E> node = new Node<>(e, nodeHeight);
        for (int i = 0; i <= nodeHeight; i++) {
            if (toFix[i].next(i) != null) {
                node.setNext(i, toFix[i].next(i));
                toFix[i].next(i).setPrevious(i, node);
            }

            toFix[i].setNext(i, node);
            node.setPrevious(i, toFix[i]);
        }
        size++;
    }

    public E get(int index) {
        int counter = -1; // head index
        Node<E> current = head;
        while (counter != index) {
            current = current.next(0);
            counter++;
        }
        return current.value;
    }

    public void remove(E e) {
        Objects.requireNonNull(e);
        Node<E> current = head;
        int layer = height;

        while (layer >= 0) {
            Node<E> next = current.next(layer);
            if (e.equals(current.getValue())) {
                break;
            } else if (next == null || next.getValue().compareTo(e) > 0) {
                layer--;
            } else {
                current = next;
            }
        }
        for (int i = 0; i <= layer; i++) {
            current.previous(i).setNext(i, current.next(i));
            if (current.next(i) != null) {
                current.next(i).setPrevious(i, current.previous(i));
            }
        }
        size--;
    }

    /**
     * A search for a target element begins at the head element in the top
     * list, and proceeds horizontally until the current element is greater
     * than or equal to the target. If the current element is equal to the
     * target, it has been found. If the current element is greater than the
     * target, or the search reaches the end of the linked list, the procedure
     * is repeated after returning to the previous element and dropping down
     * vertically to the next lower list.
     *
     * @param e element whose presence in this list is to be tested
     * @return true if this list contains the specified element
     */
    public boolean contains(E e) {
        Objects.requireNonNull(e);
        Node<E> current = head;
        int layer = height;

        while (layer >= 0) {
            Node<E> next = current.next(layer);
            if (e.equals(current.getValue())) {
                return true;
            } else if (next == null || next.getValue().compareTo(e) > 0) {
                layer--;
            } else {
                current = next;
            }
        }
        return false;
    }

    public int size() {
        return size;
    }

    /**
     * Print height distribution of the nodes in a manner:
     * <pre>
     * [ ] --- --- [ ] --- [ ]
     * [ ] --- [ ] [ ] --- [ ]
     * [ ] [ ] [ ] [ ] [ ] [ ]
     *  H   0   1   2   3   4
     * </pre>
     * Values of nodes is not presented.
     *
     * @return string representation
     */
    @Override
    public String toString() {
        List<boolean[]> layers = new ArrayList<>();
        int sizeWithHeader = size + 1;
        for (int i = 0; i <= height; i++) {
            layers.add(new boolean[sizeWithHeader]);
        }

        Node<E> current = head;
        int position = 0;
        while (current != null) {
            for (int i = 0; i <= current.height; i++) {
                layers.get(i)[position] = true;
            }
            current = current.next(0);
            position++;
        }

        Collections.reverse(layers);
        String result = layers.stream()
                            .map(layer -> {
                                StringBuilder acc = new StringBuilder();
                                for (boolean b : layer) {
                                    if (b) {
                                        acc.append("[ ]");
                                    } else {
                                        acc.append("---");
                                    }
                                    acc.append(" ");
                                }
                                return acc.toString();
                            })
                            .collect(Collectors.joining("\n"));
        String positions = IntStream.range(0, sizeWithHeader - 1).mapToObj(i -> String.format("%3d", i)).collect(Collectors.joining(" "));

        return result + String.format("%n H %s%n", positions);
    }

    /**
     * Value container.
     * Each node have pointers to the closest nodes left and right from current
     * on each layer of nodes height.
     * @param <E> type of elements
     */
    private static class Node<E> {

        private final E value;
        private final int height;
        private final List<Node<E>> forward;
        private final List<Node<E>> backward;

        @SuppressWarnings("unchecked")
        Node(E value, int height) {
            this.value = value;
            this.height = height;

            // predefined size lists with null values in every cell
            this.forward = Arrays.asList(new Node[height + 1]);
            this.backward = Arrays.asList(new Node[height + 1]);
        }

        public Node<E> next(int layer) {
            checkLayer(layer);
            return forward.get(layer);
        }

        public void setNext(int layer, Node<E> node) {
            forward.set(layer, node);
        }

        public void setPrevious(int layer, Node<E> node) {
            backward.set(layer, node);
        }

        public Node<E> previous(int layer) {
            checkLayer(layer);
            return backward.get(layer);
        }

        public E getValue() {
            return value;
        }

        private void checkLayer(int layer) {
            if (layer < 0 || layer > height) {
                throw new IllegalArgumentException();
            }
        }
    }

    /**
     * Height strategy is a way of calculating maximum height for skip list
     * and height for each node.
     * @see BernoulliHeightStrategy
     */
    public interface HeightStrategy {
        int height(int expectedSize);
        int nodeHeight(int heightCap);
    }

    /**
     * In most common skip list realisation element in layer {@code i} appears
     * in layer {@code i+1} with some fixed probability {@code p}.
     * Two commonly used values for {@code p} are 1/2 and 1/4.
     * Probability of appearing element in layer {@code i} could be calculated
     * with <code>P = p<sup>i</sup>(1 - p)</code>
     * <p>
     * Maximum height that would give the best search complexity
     * calculated by <code>log<sub>1/p</sub>n</code>
     * where {@code n} is an expected count of elements in list.
     */
    public static class BernoulliHeightStrategy implements HeightStrategy {

        private final double probability;

        private static final double DEFAULT_PROBABILITY = 0.5;
        private static final Random RANDOM = new Random();

        public BernoulliHeightStrategy() {
            this.probability = DEFAULT_PROBABILITY;
        }

        public BernoulliHeightStrategy(double probability) {
            if (probability <= 0 || probability >= 1) {
                throw new IllegalArgumentException("Probability should be from 0 to 1. But was: " + probability);
            }
            this.probability = probability;
        }

        @Override
        public int height(int expectedSize) {
            long height = Math.round(Math.log10(expectedSize) / Math.log10(1 / probability));
            if (height > Integer.MAX_VALUE) {
                throw new IllegalArgumentException();
            }
            return (int) height;
        }

        @Override
        public int nodeHeight(int heightCap) {
            int level = 0;
            double border = 100 * (1 - probability);
            while (((RANDOM.nextInt(Integer.MAX_VALUE) % 100) + 1) > border) {
                if (level + 1 >= heightCap) {
                    return level;
                }
                level++;
            }
            return level;
        }
    }
}

package com.thealgorithms.datastructures.heaps;

/**
 * The {@code FibonacciHeap} class implements a Fibonacci Heap data structure,
 * which is a collection of trees that satisfy the minimum heap property.
 * This heap allows for efficient merging of heaps, as well as faster
 * decrease-key and delete operations compared to other heap data structures.
 *
 * <p>Key features of the Fibonacci Heap include:
 * <ul>
 *   <li>Amortized O(1) time complexity for insert and decrease-key operations.</li>
 *   <li>Amortized O(log n) time complexity for delete and delete-min operations.</li>
 *   <li>Meld operation that combines two heaps in O(1) time.</li>
 *   <li>Potential function that helps analyze the amortized time complexity.</li>
 * </ul>
 *
 * <p>This implementation maintains additional statistics such as the total number
 * of link and cut operations performed during the lifetime of the heap, which can
 * be accessed through static methods.
 *
 * <p>The Fibonacci Heap is composed of nodes represented by the inner class
 * {@code HeapNode}. Each node maintains a key, rank, marked status, and pointers
 * to its children and siblings. Nodes can be linked and cut as part of the heap
 * restructuring processes.
 *
 * @see HeapNode
 */
public class FibonacciHeap {

private static final double PHI_RATIO = (1 + Math.sqrt(5)) / 2;
private HeapNode minimumNode;
private static int linkOperations = 0;
private static int cutOperations = 0;
private int treeCount = 0;
private int totalElements = 0;
private int markedNodeCount = 0;

public FibonacciHeap() {
this.minimumNode = null;
}

public FibonacciHeap(int initialKey) {
this.minimumNode = new HeapNode(initialKey);
this.treeCount++;
this.totalElements++;
}

public boolean isEmpty() {
return (this.minimumNode == null);
}

/**
 * Creates a node (of type HeapNode) which contains the given key, and inserts it into the heap.
 *
 * @pre key>=0
 * @post (numOfnodes = = $prev numOfnodes + 1)
 * @post empty == false
 * $ret = the HeapNode we inserted
 */
public HeapNode insert(int inputKey) {
HeapNode newNode = new HeapNode(inputKey);
if (this.isEmpty()) {
this.minimumNode = newNode;
} else {
minimumNode.setNext(newNode);
updateMinimum(newNode);
}
this.totalElements++;
this.treeCount++;
return newNode;
}

/**
 * Delete the node containing the minimum key in the heap
 * updates new min
 *
 * @post (numOfnodes = = $prev numOfnodes - 1)
 */
public void deleteMin() {
if (this.isEmpty()) {
return;
}
if (this.totalElements == 1) {
this.minimumNode = null;
this.treeCount--;
this.totalElements--;
return;
}
if (this.minimumNode.child != null) {
HeapNode currentChild = this.minimumNode.child;
HeapNode firstChild = currentChild;
currentChild.parent = null;
while (currentChild.next != firstChild) {
currentChild = currentChild.next;
currentChild.parent = null;
}
}
if (this.treeCount > 1) {
(this.minimumNode.prev).next = this.minimumNode.next;
(this.minimumNode.next).prev = this.minimumNode.prev;
if (this.minimumNode.child != null) {
(this.minimumNode.prev).setNext(this.minimumNode.child);
}
} else {
this.minimumNode = this.minimumNode.child;
}
this.totalElements--;
consolidateTrees(this.minimumNode.getNext());
}

/**
 * Return the node of the heap whose key is minimal.
 * $ret == null if (empty==true)
 */
public HeapNode findMin() {
return this.minimumNode;
}

/**
 * Meld the heap with heap2
 *
 * @pre heap2 != null
 * @post (numOfnodes = = $prev numOfnodes + heap2.numOfnodes)
 */
public void merge(FibonacciHeap otherHeap) {
if (otherHeap.isEmpty()) {
return;
}
if (this.isEmpty()) {
this.minimumNode = otherHeap.minimumNode;
} else {
this.minimumNode.setNext(otherHeap.minimumNode);
updateMinimum(otherHeap.minimumNode);
}
this.treeCount += otherHeap.treeCount;
this.totalElements += otherHeap.totalElements;
}

/**
 * Return the number of elements in the heap
 * $ret == 0 if heap is empty
 */
public int getSize() {
return this.totalElements;
}

/**
 * Return a counters array, where the value of the i-th index is the number of trees with rank i
 * in the heap. returns an empty array for an empty heap
 */
public int[] getRankDistribution() {
if (this.isEmpty()) {
return new int[0];
}
int maxRank = (int) Math.floor(Math.log(this.getSize()) / Math.log(PHI_RATIO)) + 1;
int[] rankCounts = new int[maxRank];
rankCounts[this.minimumNode.rank]++;
HeapNode currentNode = this.minimumNode.next;
while (currentNode != this.minimumNode) {
rankCounts[currentNode.rank]++;
currentNode = currentNode.next;
}
return rankCounts;
}

/**
 * Deletes the node x from the heap (using decreaseKey(x) to -1)
 *
 * @pre heap contains x
 * @post (numOfnodes = = $prev numOfnodes - 1)
 */
public void delete(HeapNode targetNode) {
decreaseKey(targetNode, targetNode.getKey() + 1);
deleteMin();
}

/**
 * The function decreases the key of the node x by delta.
 *
 * @pre x.key >= delta (we don't realize it when calling from delete())
 * @pre heap contains x
 */
private void decreaseKey(HeapNode targetNode, int deltaValue) {
int updatedKey = targetNode.getKey() - deltaValue;
targetNode.key = updatedKey;
if (targetNode.isRoot()) {
updateMinimum(targetNode);
return;
}
if (targetNode.getKey() >= targetNode.parent.getKey()) {
return;
}
HeapNode previousParent = targetNode.parent;
cutNode(targetNode);
cascadeCut(previousParent);
}

/**
 * returns the current potential of the heap, which is:
 * Potential = #trees + 2*#markedNodes
 */
public int getPotential() {
return treeCount + (2 * markedNodeCount);
}

/**
 * This static function returns the total number of link operations made during the run-time of
 * the program. A link operation is the operation which gets as input two trees of the same
 * rank, and generates a tree of rank bigger by one.
 */
public static int getTotalLinks() {
return linkOperations;
}

/**
 * This static function returns the total number of cut operations made during the run-time of
 * the program. A cut operation is the operation which disconnects a subtree from its parent
 * (during decreaseKey/delete methods).
 */
public static int getTotalCuts() {
return cutOperations;
}

private void updateMinimum(HeapNode candidateNode) {
if (candidateNode.getKey() < this.minimumNode.getKey()) {
this.minimumNode = candidateNode;
}
}

private void cascadeCut(HeapNode currentNode) {
if (!currentNode.isMarked()) {
currentNode.mark();
if (!currentNode.isRoot()) {
this.markedNodeCount++;
}
} else {
if (currentNode.isRoot()) {
return;
}
HeapNode previousParent = currentNode.parent;
cutNode(currentNode);
cascadeCut(previousParent);
}
}

private void cutNode(HeapNode targetNode) {
targetNode.parent.rank--;
if (targetNode.marked) {
this.markedNodeCount--;
targetNode.marked = false;
}
if (targetNode.parent.child == targetNode) {
if (targetNode.next == targetNode) {
targetNode.parent.child = null;
} else {
targetNode.parent.child = targetNode.next;
}
}
targetNode.prev.next = targetNode.next;
targetNode.next.prev = targetNode.prev;
targetNode.next = targetNode;
targetNode.prev = targetNode;
targetNode.parent = null;
this.minimumNode.setNext(targetNode);
updateMinimum(targetNode);
this.treeCount++;
cutOperations++;
}

private void consolidateTrees(HeapNode startNode) {
HeapNode[] rankBuckets = distributeByRank(startNode);
this.minimumNode = rebuildFromBuckets(rankBuckets);
}

private HeapNode[] distributeByRank(HeapNode startNode) {
int maxRank = (int) Math.floor(Math.log(this.getSize()) / Math.log(PHI_RATIO)) + 1;
HeapNode[] rankBuckets = new HeapNode[maxRank];
startNode.prev.next = null;
HeapNode current = startNode;
while (current != null) {
HeapNode nextNode = current.next;
current.next = current;
current.prev = current;
while (rankBuckets[current.rank] != null) {
current = linkNodes(current, rankBuckets[current.rank]);
rankBuckets[current.rank - 1] = null;
}
rankBuckets[current.rank] = current;
current = nextNode;
}
return rankBuckets;
}

private HeapNode rebuildFromBuckets(HeapNode[] rankBuckets) {
HeapNode newMinimum = null;
this.treeCount = 0;
for (int rankIndex = 0; rankIndex < rankBuckets.length; rankIndex++) {
if (rankBuckets[rankIndex] != null) {
this.treeCount++;
if (newMinimum == null) {
newMinimum = rankBuckets[rankIndex];
newMinimum.next = newMinimum;
newMinimum.prev = newMinimum;
} else {
newMinimum.setNext(rankBuckets[rankIndex]);
if (rankBuckets[rankIndex].getKey() < newMinimum.getKey()) {
newMinimum = rankBuckets[rankIndex];
}
}
}
}
return newMinimum;
}

private HeapNode linkNodes(HeapNode firstNode, HeapNode secondNode) {
if (firstNode.getKey() > secondNode.getKey()) {
HeapNode tempNode = firstNode;
firstNode = secondNode;
secondNode = tempNode;
}
if (firstNode.child == null) {
firstNode.child = secondNode;
} else {
firstNode.child.setNext(secondNode);
}
secondNode.parent = firstNode;
firstNode.rank++;
linkOperations++;
return firstNode;
}

/**
 * public class HeapNode
 * each HeapNode belongs to a heap (Inner class)
 */
public class HeapNode {

public int key;
private int rank;
private boolean marked;
private HeapNode child;
private HeapNode next;
private HeapNode prev;
private HeapNode parent;

public HeapNode(int nodeKey) {
this.key = nodeKey;
this.marked = false;
this.next = this;
this.prev = this;
}

public int getKey() {
return this.key;
}

private boolean isMarked() {
return this.marked;
}

private void mark() {
if (this.isRoot()) {
return;
}
this.marked = true;
}

private void setNext(HeapNode nextNode) {
HeapNode oldNext = this.next;
this.next = nextNode;
this.next.prev.next = oldNext;
oldNext.prev = nextNode.prev;
this.next.prev = this;
}

private HeapNode getNext() {
return this.next;
}

private boolean isRoot() {
return (this.parent == null);
}
}
}

public class PrimeNumberChecker {
    /**
     * Checks whether a number is prime using trial division
     * up to the square root of the number.
     */
    public static boolean isPrime(int number) {
        if (number < 2) {
            return false;
        }
        for (int i = 2; i * i <= number; i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int num = scanner.nextInt();
        if (isPrime(num)) {
            System.out.println(num + " is a prime number");
        } else {
            System.out.println(num + " is not a prime number");
        }
        scanner.close();
    }
}

package syntax;

public class AtamaIslemleri {

    public static void main(String[] args) {
        // Starting values for the walkthrough of compound assignment operators.
        int a = 5;
        int b = 10;
        int c = 15;

        a = a + b;
        System.out.println("Toplama ve Atama: x = " + a + " y = " + b); // a = 15

        a -= b;
        System.out.println("Cikarma ve Atama: x = " + a + " y = " + b); // a = 5

        a *= 2;
        System.out.println("Carpma ve Atama: x = " + a + " y = " + b); // a = 10

        a /= 4;
        System.out.println("Bolme ve Atama: x = " + a + " y = " + b); // a = 2

        a %= 3;
        System.out.println("Mod ve Atama: x = " + a + " y = " + b); // a = 2

        a += c;
        System.out.println("Toplama ve Atama (x + z): x = " + a + " z = " + c); // a = 17

        a *= c;
        System.out.println("Carpma ve Atama (x * z): x = " + a + " z = " + c); // a = 255

        a = c / a;
        System.out.println("Bolme ve Atama (z / x): x = " + a + " z = " + c); // a = 0

        a = b % (a + 1);
        System.out.println("Mod ve Atama (y % (x + 1)): x = " + a + " y = " + b); // a = 0

        a = 10;
        b += a;
        System.out.println("Toplama ve Atama (y + x): x = " + a + " y = " + b); // b = 20

        b /= a;
        System.out.println("Bolme ve Atama (y / x): x = " + a + " y = " + b); // b = 2

        a = -a;
        System.out.println("Negatif deger: x = " + a); // a = -10
    }
}

// Digital Root hesaplamasi: bir sayinin rakamlari tek basamak kalana dek tekrar tekrar toplanir.
package whileloop;

import java.util.Scanner;

public class DijitalKok {

	public static void main(String[] args) {

		// Kullanicidan analiz edilecek sayi alinir
		Scanner girisAraci = new Scanner(System.in);
		System.out.print("Bir sayi giriniz: ");
		int girilenSayi = girisAraci.nextInt();

		int guncelDeger = girilenSayi;

		// Deger tek basamakli hale gelene kadar rakamlarini toplamaya devam ederiz
		while (guncelDeger >= 10) {
			int digitToplami = 0;
			for (int kalan = guncelDeger; kalan > 0; kalan /= 10) {
				digitToplami += kalan % 10;
			}
			guncelDeger = digitToplami;
		}

		System.out.println("Dijital kok: " + guncelDeger);

		girisAraci.close();
	}
}

