/*
 * Demonstrates method overloading: several "topla/cikar/carp/bol"
 * variants that accept different parameter types/counts.
 */
public class HesapMakinesi {

    int sonIslemSonucu = 0; // holds the result of the last add operation

    // Adds two integers, remembering the result.
    public int topla(int x, int y) {
        sonIslemSonucu = x + y;
        return sonIslemSonucu;
    }

    // Adds two doubles without touching memory.
    public double topla(double x, double y) {
        return x + y;
    }

    // Adds three integers together.
    public int topla(int x, int y, int z) {
        return x + y + z;
    }

    // Sums every element of an integer array.
    public int topla(int[] degerler) {
        int birikimSonucu = 0;
        for (int tekDeger : degerler) {
            birikimSonucu = birikimSonucu + tekDeger;
        }
        return birikimSonucu;
    }

    public int cikar(int x, int y) {
        return x - y;
    }

    public double cikar(double x, double y) {
        return x - y;
    }

    public int carp(int x, int y) {
        return x * y;
    }

    public double carp(double x, double y) {
        return x * y;
    }

    public int bol(int x, int y) {
        if (y == 0) {
            throw new ArithmeticException("Bolme islemi icin bolen sifir olamaz!");
        }
        return x / y;
    }

    public double bol(double x, double y) {
        if (y == 0.0) {
            throw new ArithmeticException("Bolme islemi icin bolen sifir olamaz!");
        }
        return x / y;
    }

    public static void main(String[] args) {
        HesapMakinesi makine = new HesapMakinesi();

        int toplamIkiTam = makine.topla(5, 3);
        double toplamIkiOndalik = makine.topla(3.5, 2.7);
        int toplamUcTam = makine.topla(4, 6, 8);

        int[] diziDegerleri = {1, 2, 3, 4, 5};
        int diziToplami = makine.topla(diziDegerleri);

        int cikarmaTam = makine.cikar(10, 4);
        double cikarmaOndalik = makine.cikar(7.8, 2.4);

        int carpmaTam = makine.carp(3, 5);
        double carpmaOndalik = makine.carp(2.5, 4.0);

        int bolmeTam = makine.bol(20, 4);
        double bolmeOndalik = makine.bol(9.0, 3.0);

        System.out.println("Sonuc 1: " + toplamIkiTam);
        System.out.println("Sonuc 2: " + toplamIkiOndalik);
        System.out.println("Sonuc 3: " + toplamUcTam);
        System.out.println("Sonuc 4 (Dizi toplama): " + diziToplami);
        System.out.println("Sonuc 5 (cikarma): " + cikarmaTam);
        System.out.println("Sonuc 6 (Double cikarma): " + cikarmaOndalik);
        System.out.println("Sonuc 7 (carpma): " + carpmaTam);
        System.out.println("Sonuc 8 (Double carpma): " + carpmaOndalik);
        System.out.println("Sonuc 9 (Bolme): " + bolmeTam);
        System.out.println("Sonuc 10 (Double bolme): " + bolmeOndalik);
    }
}

/**
 * @author Varun Upadhyay (<a href="https://github.com/varunu28">...</a>)
 */
public final class AnyBaseToDecimal {
    private static final int CHAR_OFFSET_FOR_DIGIT = '0';
    private static final int CHAR_OFFSET_FOR_UPPERCASE = 'A' - 10;

    private AnyBaseToDecimal() {
    }

    /**
     * Convert any radix to a decimal number.
     *
     * @param input the string to be converted
     * @param radix the radix (base) of the input string
     * @return the decimal equivalent of the input string
     * @throws NumberFormatException if the input string or radix is invalid
     */
    public static int convertToDecimal(String input, int radix) {
        int result = 0;
        int power = 1;

        for (int i = input.length() - 1; i >= 0; i--) {
            int digit = valOfChar(input.charAt(i));
            if (digit >= radix) {
                throw new NumberFormatException("For input string: " + input);
            }
            result += digit * power;
            power *= radix;
        }
        return result;
    }

    /**
     * Convert a character to its integer value.
     *
     * @param character the character to be converted
     * @return the integer value represented by the character
     * @throws NumberFormatException if the character is not an uppercase letter or a digit
     */
    private static int valOfChar(char character) {
        if (Character.isDigit(character)) {
            return character - CHAR_OFFSET_FOR_DIGIT;
        } else if (Character.isUpperCase(character)) {
            return character - CHAR_OFFSET_FOR_UPPERCASE;
        } else {
            throw new NumberFormatException("invalid character:" + character);
        }
    }
}

/*
 * Base type describing a generic animal with a name, age and
 * a health score. Subclasses override konus() to speak differently.
 */
public class Hayvan {

	private String ad;      // the animal's name
	private int yasBilgisi;    // the animal's age in years
	private double saglikPuani; // health score, starts at full health

	public Hayvan(String ad, int yasBilgisi) {
		this.ad = ad;
		this.yasBilgisi = yasBilgisi;
		this.saglikPuani = 100.0; // every animal starts fully healthy
	}

	public String getIsim() {
		return ad;
	}

	public int getYas() {
		return yasBilgisi;
	}

	public double getSaglik() {
		return saglikPuani;
	}

	// Default sound; subclasses are expected to override this.
	public void konus() {
		System.out.println("Bu hayvan konusur.");
	}

	// Feeding increases health by the given amount, when valid.
	public void yemekYe(double miktar) {
		if (miktar > 0) {
			saglikPuani = saglikPuani + miktar;
			System.out.println(ad + " yemek yedi. Saglik: " + saglikPuani);
		} else {
			System.out.println("Gecersiz miktar.");
		}
	}

	// Sleeping restores a fixed amount of health.
	public void uyu() {
		saglikPuani = saglikPuani + 5;
		System.out.println(ad + " uyudu. Saglik: " + saglikPuani);
	}

	// Prints out the animal's age in a friendly sentence.
	public void yasHesapla() {
		System.out.println(ad + " " + yasBilgisi + " yasinda.");
	}

	@Override
	public String toString() {
		return "Hayvan Ismi: " + ad + ", Yas: " + yasBilgisi + ", Saglik Durumu: " + saglikPuani;
	}
}

package player;

/**
 * A player's tournament performance and resulting grade bonus.
 */
public class TournamentIncome extends Player implements GradeBonus {

    private int totalMatches;
    private int battle;
    private double[] points;
    private double income;

    public TournamentIncome(int totalMatches, int battle, double[] points, double income) {
        this.income = income;
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(int totalMatches, int battle, double[] points, double income, String name) {
        super(name);
        this.income = income;
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(int totalMatches, int battle, double[] points) {
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(double income, String name) {
        super(name);
        this.income = income;
    }

    public TournamentIncome() {
    }

    public int getTotalMatches() {
        return totalMatches;
    }

    public void setTotalMatches(int totalMatches) {
        this.totalMatches = totalMatches;
    }

    public int getBattle() {
        return battle;
    }

    public void setBattle(int battle) {
        this.battle = battle;
    }

    public double[] getPoints() {
        return points;
    }

    public void setPoints(double[] points) {
        this.points = points;
    }

    public double getIncome() {
        return income;
    }

    public void setIncome(double income) {
        this.income = income;
    }

    @Override
    public void displayDetails() {
        System.out.println("Name player: " + getName());
        System.out.println("Grade bonus: " + calculateGradeBonus() + "%");
        System.out.println("Income: " + income + "$");
    }

    @Override
    public double calculateGradeBonus() {
        double totalPoint = 0;
        double money = 1000000;
        if (points == null) {
            System.out.println("Please enter points");
            return 0;
        }
        for (double point : points) {
            totalPoint += point;
        }
        if (totalPoint < totalMatches * 100 * 0.3) {
            return GRADE_D_BONUS_PERCENT * money / 100;
        } else if (totalPoint < totalMatches * 100 * 0.4) {
            return GRADE_C_BONUS_PERCENT * money / 100;
        } else if (totalPoint < totalMatches * 100 * 0.5) {
            return GRADE_B_BONUS_PERCENT * money / 100;
        } else {
            return GRADE_A_BONUS_PERCENT * money / 100;
        }
    }
}

package com.thealgorithms.conversions;

/**
 * This class converts Decimal numbers to Octal Numbers
 */
public final class DecimalToOctal {
    private static final int OCTAL_BASE = 8;
    private static final int INITIAL_OCTAL_VALUE = 0;
    private static final int INITIAL_PLACE_VALUE = 1;

    private DecimalToOctal() {
    }

    /**
     * Converts a decimal number to its octal equivalent.
     *
     * @param decimal The decimal number to convert.
     * @return The octal equivalent as an integer.
     * @throws IllegalArgumentException if the decimal number is negative.
     */
    public static int convertToOctal(int decimal) {
        if (decimal < 0) {
            throw new IllegalArgumentException("Decimal number cannot be negative.");
        }

        int octal = INITIAL_OCTAL_VALUE;
        int placeValue = INITIAL_PLACE_VALUE;

        while (decimal != 0) {
            int remainder = decimal % OCTAL_BASE;
            octal += remainder * placeValue;
            decimal /= OCTAL_BASE;
            placeValue *= 10;
        }

        return octal;
    }
}

package com.ankan.generics.comparing;

public class Student implements Comparable<Student>{
    int rollno;
    float marks;

    public Student(int rollno, float marks) {
        this.rollno = rollno;
        this.marks = marks;
    }

    @Override
    public String toString() {
        return marks + "";
    }

    /**
     * Compares this object with the specified object for order.  Returns a
     * negative integer, zero, or a positive integer as this object is less
     * than, equal to, or greater than the specified object.
     *
     * <p>The implementor must ensure {@link Integer#signum
     * signum}{@code (x.compareTo(y)) == -signum(y.compareTo(x))} for
     * all {@code x} and {@code y}.  (This implies that {@code
     * x.compareTo(y)} must throw an exception if and only if {@code
     * y.compareTo(x)} throws an exception.)
     *
     * <p>The implementor must also ensure that the relation is transitive:
     * {@code (x.compareTo(y) > 0 && y.compareTo(z) > 0)} implies
     * {@code x.compareTo(z) > 0}.
     *
     * <p>Finally, the implementor must ensure that {@code
     * x.compareTo(y)==0} implies that {@code signum(x.compareTo(z))
     * == signum(y.compareTo(z))}, for all {@code z}.
     *
     * @param o the object to be compared.
     * @return a negative integer, zero, or a positive integer as this object
     * is less than, equal to, or greater than the specified object.
     * @throws NullPointerException if the specified object is null
     * @throws ClassCastException   if the specified object's type prevents it
     *                              from being compared to this object.
     * @apiNote It is strongly recommended, but <i>not</i> strictly required that
     * {@code (x.compareTo(y)==0) == (x.equals(y))}.  Generally speaking, any
     * class that implements the {@code Comparable} interface and violates
     * this condition should clearly indicate this fact.  The recommended
     * language is "Note: this class has a natural ordering that is
     * inconsistent with equals."
     */
    @Override
    public int compareTo(Student o) {
        System.out.println("in compareTo method");
        int diff = (int)(this.marks - o.marks);
        // if diff == 0; means both are equal
        // if diff < 1; means o is bigger else o is smal
        return diff;
    }
}

public class ArrayListOrnegi {

    public static void main(String[] args) {

        ArrayList<String> katilimcilar = new ArrayList<>();

        katilimcilar.add("Alice");
        katilimcilar.add("Bob");
        katilimcilar.add("Charlie");
        katilimcilar.add("Dave");
        katilimcilar.add("Eve");

        System.out.println("Orijinal liste: " + katilimcilar);

        // Index 3'teki degeri degistir
        katilimcilar.set(3, "Carol");
        System.out.println("Degistirilmis liste: " + katilimcilar);

        // Son elemani listeden cikar
        katilimcilar.remove(4);
        System.out.println("Degistirilmis liste: " + katilimcilar);

        // Belirli bir konuma yeni eleman ekle
        katilimcilar.add(2, "Frank");
        System.out.println("Degistirilmis liste: " + katilimcilar);

        int bobunKonumu = katilimcilar.indexOf("Bob");
