package com.thealgorithms.compression;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * An implementation of the Lempel-Ziv 78 (LZ78) compression algorithm.
 * <p>
 * LZ78 is a dictionary-based lossless data compression algorithm. It processes
 * input data sequentially, building a dictionary of phrases encountered so far.
 * It outputs pairs (dictionary_index, next_character), representing
 * the longest match found in the dictionary plus the character that follows it.
 * </p>
 * <p>
 * This implementation builds the dictionary dynamically during compression.
 * The dictionary index 0 represents the empty string (no prefix).
 * </p>
 * <p>
 * Time Complexity: O(n) on average for compression and decompression, assuming
 * efficient dictionary lookups (using a HashMap), where n is the
 * length of the input string.
 * </p>
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/LZ77_and_LZ78#LZ78">Wikipedia: LZ78</a></li>
 * </ul>
 * </p>
 */
public final class LZ78 {

/**
 * Special character used to mark end of stream when needed.
 */
private static final char STREAM_END_MARKER = '\u0000';

/**
 * Private constructor to prevent instantiation of this utility class.
 */
private LZ78() {
}

/**
 * Represents a token in the LZ78 compressed output.
 * Stores the index of the matching prefix in the dictionary and the next character.
 * Index 0 represents the empty string (no prefix).
 */
public record CompressionUnit(int dictionaryIndex, char followingChar) {
}

/**
 * A node in the dictionary trie structure.
 * Each node represents a phrase and can have child nodes for extended phrases.
 */
private static final class TrieNode {
Map<Character, TrieNode> childNodes = new HashMap<>();
int assignedIndex = -1;
}

/**
 * Compresses the input text using the LZ78 algorithm.
 *
 * @param sourceText The input string to compress. Must not be null.
 * @return A list of {@link CompressionUnit} objects representing the compressed data.
 */
public static List<CompressionUnit> compress(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
return new ArrayList<>();
}
List<CompressionUnit> encodedOutput = new ArrayList<>();
TrieNode rootNode = new TrieNode();
int nextIndex = 1;
TrieNode currentNode = rootNode;
int currentMatchIndex = 0;
for (int position = 0; position < sourceText.length(); position++) {
char currentSymbol = sourceText.charAt(position);
if (currentNode.childNodes.containsKey(currentSymbol)) {
currentNode = currentNode.childNodes.get(currentSymbol);
currentMatchIndex = currentNode.assignedIndex;
} else {
encodedOutput.add(new CompressionUnit(currentMatchIndex, currentSymbol));
TrieNode newDictionaryNode = new TrieNode();
newDictionaryNode.assignedIndex = nextIndex++;
currentNode.childNodes.put(currentSymbol, newDictionaryNode);
currentNode = rootNode;
currentMatchIndex = 0;
}
}
if (currentNode != rootNode) {
encodedOutput.add(new CompressionUnit(currentMatchIndex, STREAM_END_MARKER));
}
return encodedOutput;
}

/**
 * Decompresses a list of LZ78 tokens back into the original string.
 *
 * @param encodedData The list of {@link CompressionUnit} objects. Must not be null.
 * @return The original, uncompressed string.
 */
public static String decompress(List<CompressionUnit> encodedData) {
if (encodedData == null || encodedData.isEmpty()) {
return "";
}
StringBuilder decodedText = new StringBuilder();
Map<Integer, String> phraseDictionary = new HashMap<>();
int nextIndex = 1;
for (CompressionUnit currentUnit : encodedData) {
String prefixValue = (currentUnit.dictionaryIndex() == 0) ? "" : phraseDictionary.get(currentUnit.dictionaryIndex());
if (currentUnit.followingChar() == STREAM_END_MARKER) {
decodedText.append(prefixValue);
} else {
String fullPhrase = prefixValue + currentUnit.followingChar();
decodedText.append(fullPhrase);
phraseDictionary.put(nextIndex++, fullPhrase);
}
}
return decodedText.toString();
}
}

public class KarsilastirmaIslemleri {

    public static void main(String[] args) {

        // Fixed values used to illustrate every relational operator.
        int valueA = 10;
        int valueB = 20;

        System.out.println("sayi1, sayi2'ye esit mi? " + (valueA == valueB));       // false
        System.out.println("sayi1, sayi2'ye esit degil mi? " + (valueA != valueB)); // true
        System.out.println("sayi1, sayi2'den buyuk mu? " + (valueA > valueB));      // false
        System.out.println("sayi1, sayi2'den kucuk mu? " + (valueA < valueB));      // true
        System.out.println("sayi1, sayi2'den buyuk veya esit mi? " + (valueA >= valueB)); // false
        System.out.println("sayi1, sayi2'den kucuk veya esit mi? " + (valueA <= valueB)); // true

        // Now gather several inputs from the user and compare them.
        Scanner input = new Scanner(System.in);

        System.out.println("Lutfen yasinizi girin:");
        int age = input.nextInt();
        System.out.println("Yasiniz 18'den buyuk mu? " + (age > 18));

        System.out.println("Lutfen adinizi girin:");
        String name = input.next();
        System.out.println("Adiniz Ali mi? " + name.equals("Ali"));

        System.out.println("Lutfen 5 ile 15 arasinda bir sayi girin:");
        int rangedNumber = input.nextInt();
        System.out.println("Girilen sayi 5'ten buyuk mu? " + (rangedNumber > 5));
        System.out.println("Girilen sayi 15'ten kucuk mu? " + (rangedNumber < 15));

        System.out.println("Lutfen bir karakter girin:");
        char letter = input.next().charAt(0);
        System.out.println("Girilen karakter A mi? " + (letter == 'A'));

        input.close();
    }
}

