public class SayiOkuma {

	// Basamak degerlerine karsilik gelen Turkce kelimeler, index sifirdan basladigi icin ilk eleman kullanilmaz
	private static final String[] BIRLER_KELIME = {
			"", "bir", "iki", "uc", "dort", "bes", "alti", "yedi", "sekiz", "dokuz"
	};

	private static final String[] ONLAR_KELIME = {
			"", "on", "yirmi", "otuz", "kirk", "elli", "altmis", "yetmis", "seksen", "doksan"
	};

	private static final String[] YUZLER_KELIME = {
			"", "yuz", "iki yuz", "uc yuz", "dort yuz", "bes yuz", "alti yuz", "yedi yuz", "sekiz yuz", "dokuz yuz"
	};

	private static final String[] BINLER_KELIME = {
			"", "bin", "iki bin", "uc bin", "dort bin", "bes bin", "alti bin", "yedi bin", "sekiz bin", "dokuz bin"
	};

	public static void main(String[] args) {

		System.out.println(sayiyiYaziyaCevir(1234));

		System.out.println(sayiyiYaziyaCevir(7248));

		System.out.println(sayiyiYaziyaCevir(297));

		System.out.println(sayiyiYaziyaCevir(505));

		System.out.println(sayiyiYaziyaCevir(300));
	}

	// 0-9999 arasindaki bir sayiyi Turkce okunusuna cevirir
	public static String sayiyiYaziyaCevir(int deger) {
		if (deger == 0) {
			return "sifir";
		}

		int binBasamagi = deger / 1000;
		int yuzBasamagi = (deger / 100) % 10;
		int onBasamagi = (deger / 10) % 10;
		int birBasamagi = deger % 10;

		StringBuilder metin = new StringBuilder();

		metin.append(BINLER_KELIME[binBasamagi]);
		if (binBasamagi > 0) {
			metin.append(" ");
		}

		metin.append(YUZLER_KELIME[yuzBasamagi]);
		if (yuzBasamagi > 0) {
			metin.append(" ");
		}

		metin.append(ONLAR_KELIME[onBasamagi]);
		if (onBasamagi > 0) {
			metin.append(" ");
		}

		metin.append(BIRLER_KELIME[birBasamagi]);

		return metin.toString();
	}
}

/**
 * In number theory, an abundant number or excessive number is a positive integer for which
 * the sum of its proper divisors is greater than the number.
 * Equivalently, it is a number for which the sum of proper divisors (or aliquot sum) is greater than n.
 *
 * The integer 12 is the first abundant number. Its proper divisors are 1, 2, 3, 4 and 6 for a total of 16.
 *
 * Wiki: https://en.wikipedia.org/wiki/Abundant_number
 */
public final class AbundantNumber {

    private AbundantNumber() {
    }

    // Function to calculate sum of all divisors including n
    private static int sumOfDivisors(int n) {
        int sum = 1 + n; // 1 and n are always divisors
        for (int i = 2; i <= n / 2; i++) {
            if (n % i == 0) {
                sum += i; // adding divisor to sum
            }
        }
        return sum;
    }

    // Common validation method
    private static void validatePositiveNumber(int number) {
        if (number <= 0) {
            throw new IllegalArgumentException("Number must be positive.");
        }
    }

    /**
     * Check if {@code number} is an Abundant number or not by checking sum of divisors > 2n
     *
     * @param number the number
     * @return {@code true} if {@code number} is an Abundant number, otherwise false
     */
    public static boolean isAbundant(int number) {
        validatePositiveNumber(number);

        return sumOfDivisors(number) > 2 * number;
    }

    /**
     * Check if {@code number} is an Abundant number or not by checking Aliquot Sum > n
     *
     * @param number the number
     * @return {@code true} if {@code number} is a Abundant number, otherwise false
     */
    public static boolean isAbundantNumber(int number) {
        validatePositiveNumber(number);

        return AliquotSum.getAliquotSum(number) > number;
    }
}

/**
 * Demonstrates inheritance and method overriding.
 */
class Animal {
    protected String name;

    public Animal(String name) {
        this.name = name;
    }

    public void makeSound() {
        System.out.println(name + " makes a sound");
    }
}

class Dog extends Animal {
    public Dog(String name) {
        super(name);
    }

    @Override
    public void makeSound() {
        System.out.println(name + " barks: Woof!");
    }
}

class Cat extends Animal {
    public Cat(String name) {
        super(name);
    }

    @Override
    public void makeSound() {
        System.out.println(name + " meows: Meow!");
    }
}

public class InheritanceDemo {
    public static void main(String[] args) {
        Animal[] animals = {
            new Dog("Rex"),
            new Cat("Whiskers"),
            new Animal("Generic")
        };

        for (Animal animal : animals) {
            animal.makeSound();
        }
    }
}

package Resizable;

import GeometricObject.*;

/**
 * A circle implementing GeometricObject.
 */
public class Circle implements GeometricObject {

    protected double radius;

    public Circle(double radius) {
        this.radius = radius;
    }

    public Circle() {
    }

    public double getRadius() {
        return radius;
    }

    public void setRadius(double radius) {
        this.radius = radius;
    }

    @Override
    public String toString() {
        return "Circle[radius=" + radius + ']';
    }

    @Override
    public double getArea() {
        return Math.PI * radius * radius;
    }

    @Override
    public double getPerimeter() {
        return 2 * Math.PI * radius;
    }
}

