/**
 * This class provides a method to determine whether two integers have
 * different signs. It utilizes the XOR operation on the two numbers:
 *
 * - If two numbers have different signs, their most significant bits
 *   (sign bits) will differ, resulting in a negative XOR result.
 * - If two numbers have the same sign, the XOR result will be non-negative.
 *
 * Time Complexity: O(1) - Constant time operation.
 * Space Complexity: O(1) - No extra space used.
 *
 * @author Bama Charan Chhandogi
 */
public final class NumbersDifferentSigns {
    private NumbersDifferentSigns() {
    }

    /**
     * Determines if two integers have different signs using bitwise XOR.
     *
     * @param num1 the first integer
     * @param num2 the second integer
     * @return true if the two numbers have different signs, false otherwise
     */
    public static boolean differentSigns(int num1, int num2) {
        return (num1 ^ num2) < 0;
    }
}

import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;

/** Basit bir 4x4 dugme duzenli GUI hesap makinesi. */
public class HesapMakinesi extends JFrame {

    private static final long serialVersionUID = 1L;

    private final JTextField ekran;
    private String aktifOperator = "";
    private double kayitliDeger = 0;
    private boolean yeniGirisBekleniyor = false;

    private static final String[] TUS_DIZILIMI = {
            "7", "8", "9", "/",
            "4", "5", "6", "x",
            "1", "2", "3", "-",
            "0", "AC", "=", "+"
    };

    public HesapMakinesi() {
        setTitle("Hesap Makinesi");
        setSize(300, 400);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        ekran = new JTextField();
        ekran.setEditable(false);
        ekran.setFont(new Font("Arial", Font.PLAIN, 24));
        ekran.setPreferredSize(new Dimension(0, 50));
        add(ekran, BorderLayout.NORTH);

        JPanel tusTakimi = new JPanel(new GridLayout(4, 4));
        TusDinleyicisi dinleyici = new TusDinleyicisi();
        for (String etiket : TUS_DIZILIMI) {
            JButton tus = new JButton(etiket);
            tus.addActionListener(dinleyici);
            tusTakimi.add(tus);
        }

        add(tusTakimi, BorderLayout.CENTER);
    }

    /** Rakam, operator, esittir ve temizle tuslarina tepki verir. */
    private class TusDinleyicisi implements ActionListener {

        @Override
        public void actionPerformed(ActionEvent e) {
            String basilan = e.getActionCommand();

            if (basilan.matches("[0-9]")) {
                rakamGirildi(basilan);
            } else if (basilan.equals("AC")) {
                ekran.setText("");
            } else if (basilan.matches("[+\\-x/]")) {
                operatorSecildi(basilan);
            } else if (basilan.equals("=")) {
                sonucuHesaplaVeGoster();
            }
        }

        private void rakamGirildi(String rakam) {
            if (yeniGirisBekleniyor) {
                ekran.setText("");
                yeniGirisBekleniyor = false;
            }
            ekran.setText(ekran.getText() + rakam);
        }

        private void operatorSecildi(String operator) {
            aktifOperator = operator;
            kayitliDeger = Double.parseDouble(ekran.getText());
            yeniGirisBekleniyor = true;
        }

        private void sonucuHesaplaVeGoster() {
            double girilenIkinciDeger = Double.parseDouble(ekran.getText());
            double sonuc = 0;

            switch (aktifOperator) {
                case "+":
                    sonuc = kayitliDeger + girilenIkinciDeger;
                    break;
                case "-":
                    sonuc = kayitliDeger - girilenIkinciDeger;
                    break;
                case "x":
                    sonuc = kayitliDeger * girilenIkinciDeger;
                    break;
                case "/":
                    sonuc = kayitliDeger / girilenIkinciDeger;
                    break;
                default:
                    break;
            }

            ekran.setText(String.valueOf(sonuc));
            yeniGirisBekleniyor = true;
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            HesapMakinesi uygulama = new HesapMakinesi();
            uygulama.setVisible(true);
        });
    }
}

package com.thealgorithms.maths;

public final class BinaryPow {
    private BinaryPow() {
    }

    /**
     * Calculate a^p using binary exponentiation
     * [Binary-Exponentiation](https://cp-algorithms.com/algebra/binary-exp.html)
     *
     * @param a the base for exponentiation
     * @param p the exponent - must be greater than 0
     * @return a^p
     */
    public static int binPow(int a, int p) {
        int res = 1;
        while (p > 0) {
            if ((p & 1) == 1) {
                res = res * a;
            }
            a = a * a;
            p >>>= 1;
        }
        return res;
    }
}

public class FileReadWriteDemo {
    public static void main(String[] args) {
        String fileName = "notes.txt";

        // Write lines to the file
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(fileName))) {
            writer.write("First line");
            writer.newLine();
            writer.write("Second line");
            writer.newLine();
        } catch (IOException e) {
            System.out.println("Write error: " + e.getMessage());
            return;
        }

        // Read the file back
        try (BufferedReader reader = new BufferedReader(new FileReader(fileName))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println("Read: " + line);
            }
        } catch (IOException e) {
            System.out.println("Read error: " + e.getMessage());
        }
    }
}

