/**
 * A generic collection that allows adding and iterating over elements but does not support
 * element removal. This class implements a simple bag data structure, which can hold duplicate
 * elements and provides operations to check for membership and the size of the collection.
 *
 * <p>Bag is not thread-safe and should not be accessed by multiple threads concurrently.
 *
 * @param <ElementType> the type of elements in this bag
 */
public class Bag<ElementType> implements Iterable<ElementType> {

private Node<ElementType> headNode;
private int elementCount;

private static final class Node<ElementType> {
private ElementType itemData;
private Node<ElementType> nextNode;
}

/**
 * Constructs an empty bag.
 * <p>This initializes the bag with zero elements.
 */
public Bag() {
headNode = null;
elementCount = 0;
}

/**
 * Checks if the bag is empty.
 *
 * @return {@code true} if the bag contains no elements; {@code false} otherwise
 */
public boolean isEmpty() {
return elementCount == 0;
}

/**
 * Returns the number of elements in the bag.
 *
 * @return the number of elements currently in the bag
 */
public int size() {
return elementCount;
}

/**
 * Adds an element to the bag.
 *
 * <p>This method adds the specified element to the bag. Duplicates are allowed, and the
 * bag will maintain the order in which elements are added.
 *
 * @param elementValue the element to add; must not be {@code null}
 */
public void add(ElementType elementValue) {
Node<ElementType> newNode = new Node<>();
newNode.itemData = elementValue;
newNode.nextNode = headNode;
headNode = newNode;
elementCount++;
}

/**
 * Checks if the bag contains a specific element.
 *
 * <p>This method uses the {@code equals} method of the element to determine membership.
 *
 * @param targetElement the element to check for; must not be {@code null}
 * @return {@code true} if the bag contains the specified element; {@code false} otherwise
 */
public boolean contains(ElementType targetElement) {
for (ElementType currentItem : this) {
if (currentItem.equals(targetElement)) {
return true;
}
}
return false;
}

/**
 * Returns an iterator over the elements in this bag.
 *
 * <p>The iterator provides a way to traverse the elements in the order they were added.
 *
 * @return an iterator that iterates over the elements in the bag
 */
@Override
public Iterator<ElementType> iterator() {
return new SequentialIterator<>(headNode);
}

private static class SequentialIterator<ElementType> implements Iterator<ElementType> {

private Node<ElementType> currentPosition;

SequentialIterator(Node<ElementType> startNode) {
this.currentPosition = startNode;
}

@Override
public boolean hasNext() {
return currentPosition != null;
}

@Override
public ElementType next() {
if (!hasNext()) {
throw new NoSuchElementException("No more elements in the bag.");
}
ElementType retrievedItem = currentPosition.itemData;
currentPosition = currentPosition.nextNode;
return retrievedItem;
}
}
}

package com.ankan.singleton;

