/**
 * Converts text to the NATO phonetic alphabet.
 * Examples:
 * "ABC" -> "Alpha Bravo Charlie"
 * "Hello" -> "Hotel Echo Lima Lima Oscar"
 * "123" -> "One Two Three"
 * "A1B2C3" -> "Alpha One Bravo Two Charlie Three"
 *
 * @author Hardvan
 */
public final class PhoneticAlphabetConverter {
private PhoneticAlphabetConverter() {
}

private static final Map<Character, String> PHONETIC_MAPPING = new HashMap<>();

static {
PHONETIC_MAPPING.put('A', "Alpha");
PHONETIC_MAPPING.put('B', "Bravo");
PHONETIC_MAPPING.put('C', "Charlie");
PHONETIC_MAPPING.put('D', "Delta");
PHONETIC_MAPPING.put('E', "Echo");
PHONETIC_MAPPING.put('F', "Foxtrot");
PHONETIC_MAPPING.put('G', "Golf");
PHONETIC_MAPPING.put('H', "Hotel");
PHONETIC_MAPPING.put('I', "India");
PHONETIC_MAPPING.put('J', "Juliett");
PHONETIC_MAPPING.put('K', "Kilo");
PHONETIC_MAPPING.put('L', "Lima");
PHONETIC_MAPPING.put('M', "Mike");
PHONETIC_MAPPING.put('N', "November");
PHONETIC_MAPPING.put('O', "Oscar");
PHONETIC_MAPPING.put('P', "Papa");
PHONETIC_MAPPING.put('Q', "Quebec");
PHONETIC_MAPPING.put('R', "Romeo");
PHONETIC_MAPPING.put('S', "Sierra");
PHONETIC_MAPPING.put('T', "Tango");
PHONETIC_MAPPING.put('U', "Uniform");
PHONETIC_MAPPING.put('V', "Victor");
PHONETIC_MAPPING.put('W', "Whiskey");
PHONETIC_MAPPING.put('X', "X-ray");
PHONETIC_MAPPING.put('Y', "Yankee");
PHONETIC_MAPPING.put('Z', "Zulu");
PHONETIC_MAPPING.put('0', "Zero");
PHONETIC_MAPPING.put('1', "One");
PHONETIC_MAPPING.put('2', "Two");
PHONETIC_MAPPING.put('3', "Three");
PHONETIC_MAPPING.put('4', "Four");
PHONETIC_MAPPING.put('5', "Five");
PHONETIC_MAPPING.put('6', "Six");
PHONETIC_MAPPING.put('7', "Seven");
PHONETIC_MAPPING.put('8', "Eight");
PHONETIC_MAPPING.put('9', "Nine");
}

/**
 * Converts text to the NATO phonetic alphabet.
 * Steps:
 * 1. Convert the text to uppercase.
 * 2. Iterate over each character in the text.
 * 3. Get the phonetic equivalent of the character from the map.
 * 4. Append the phonetic equivalent to the result.
 * 5. Append a space to separate the phonetic equivalents.
 * 6. Return the result.
 *
 * @param sourceText the text to convert
 * @return the NATO phonetic alphabet
 */
public static String textToPhonetic(String sourceText) {
StringBuilder phoneticResult = new StringBuilder();
for (char currentChar : sourceText.toUpperCase().toCharArray()) {
if (Character.isWhitespace(currentChar)) {
continue;
}
phoneticResult.append(PHONETIC_MAPPING.getOrDefault(currentChar, String.valueOf(currentChar))).append(" ");
}
return phoneticResult.toString().trim();
}
}

/**
 * An implementation of the Lempel-Ziv-Welch (LZW) algorithm.
 *
 * <p>
 * LZW is a universal lossless data compression algorithm created by Abraham
 * Lempel, Jacob Ziv, and Terry Welch. It works by building a dictionary of
 * strings encountered during compression and replacing occurrences of those
 * strings with a shorter code.
 * </p>
 *
 * <p>
 * This implementation handles standard ASCII characters and provides methods for
 * both compression and decompression.
 * <ul>
 * <li>Compressing "TOBEORNOTTOBEORTOBEORNOT" results in a list of integer
 * codes.</li>
 * <li>Decompressing that list of codes results back in the original
 * string.</li>
 * </ul>
 * </p>
 *
 * <p>
 * Time Complexity: O(n) for both compression and decompression, where n is the
 * length of the input string.
 * </p>
 *
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Lempel%E2%80%93Ziv%E2%80%93Welch">Wikipedia:
 * Lempel–Ziv–Welch</a></li>
 * </ul>
 * </p>
 */
public final class LZW {

    /**
     * Private constructor to prevent instantiation of this utility class.
     */
    private LZW() {
    }

    /**
     * Compresses a string using the LZW algorithm.
     *
     * @param uncompressed The string to be compressed. Can be null.
     * @return A list of integers representing the compressed data. Returns an empty
     * list if the input is null or empty.
     */
    public static List<Integer> compress(String uncompressed) {
        if (uncompressed == null || uncompressed.isEmpty()) {
            return new ArrayList<>();
        }

        // Initialize dictionary with single characters (ASCII 0-255)
        int dictSize = 256;
        Map<String, Integer> dictionary = new HashMap<>();
        for (int i = 0; i < dictSize; i++) {
            dictionary.put("" + (char) i, i);
        }

        String w = "";
        List<Integer> result = new ArrayList<>();
        for (char c : uncompressed.toCharArray()) {
            String wc = w + c;
            if (dictionary.containsKey(wc)) {
                // If the new string is in the dictionary, extend the current string
                w = wc;
            } else {
                // Otherwise, output the code for the current string
                result.add(dictionary.get(w));
                // Add the new string to the dictionary
                dictionary.put(wc, dictSize++);
                // Start a new current string
                w = "" + c;
            }
        }

        // Output the code for the last remaining string
        result.add(dictionary.get(w));
        return result;
    }

    /**
     * Decompresses a list of integers back into a string using the LZW algorithm.
     *
     * @param compressed A list of integers representing the compressed data. Can be
     *                   null.
     * @return The original, uncompressed string. Returns an empty string if the
     * input is null or empty.
     */
    public static String decompress(List<Integer> compressed) {
        if (compressed == null || compressed.isEmpty()) {
            return "";
        }

        // Initialize dictionary with single characters (ASCII 0-255)
        int dictSize = 256;
        Map<Integer, String> dictionary = new HashMap<>();
        for (int i = 0; i < dictSize; i++) {
            dictionary.put(i, "" + (char) i);
        }

        // Decompress the first code
        String w = "" + (char) (int) compressed.removeFirst();
        StringBuilder result = new StringBuilder(w);

        for (int k : compressed) {
            String entry;
            if (dictionary.containsKey(k)) {
                // The code is in the dictionary
                entry = dictionary.get(k);
            } else if (k == dictSize) {
                // Special case for sequences like "ababab"
                entry = w + w.charAt(0);
            } else {
                throw new IllegalArgumentException("Bad compressed k: " + k);
            }

            result.append(entry);

            // Add new sequence to the dictionary
            dictionary.put(dictSize++, w + entry.charAt(0));

            w = entry;
        }
        return result.toString();
    }
}

/**
 * ECC - Elliptic Curve Cryptography
 * Elliptic Curve Cryptography is a public-key cryptography method that uses the algebraic structure of
 * elliptic curves over finite fields. ECC provides a higher level of security with smaller key sizes compared
 * to other public-key methods like RSA, making it particularly suitable for environments where computational
 * resources are limited, such as mobile devices and embedded systems.
 *
 * This class implements elliptic curve cryptography, providing encryption and decryption
 * functionalities based on public and private key pairs.
 *
 * @author xuyang
 */
public class ECC {

private BigInteger privateKeyData;
private ECPoint publicKeyPoint;
private EllipticCurve activeCurve;
private ECPoint basePointG;

public ECC(int keySizeBits) {
generateNewKeys(keySizeBits);
}

public EllipticCurve getCurve() {
return activeCurve;
}

public void setCurve(EllipticCurve curveData) {
this.activeCurve = curveData;
}

public BigInteger getPrivateKey() {
return privateKeyData;
}

public void setPrivateKey(BigInteger privateKeyValue) {
this.privateKeyData = privateKeyValue;
}

/**
 * Encrypts the message using the public key.
 * The message is transformed into an ECPoint and encrypted with elliptic curve operations.
 *
 * @param inputMessage The plain message to be encrypted
 * @return The encrypted message as an array of ECPoints (R, S)
 */
public ECPoint[] encrypt(String inputMessage) {
BigInteger messageValue = new BigInteger(inputMessage.getBytes());
SecureRandom randomGenerator = new SecureRandom();
BigInteger randomScalar = new BigInteger(activeCurve.getFieldSize(), randomGenerator);
ECPoint rPointValue = basePointG.multiply(randomScalar, activeCurve.getPrimeModulus(), activeCurve.getCurveCoefficientA());
ECPoint sPointValue = publicKeyPoint.multiply(randomScalar, activeCurve.getPrimeModulus(), activeCurve.getCurveCoefficientA()).add(activeCurve.encodeMessage(messageValue), activeCurve.getPrimeModulus(), activeCurve.getCurveCoefficientA());
return new ECPoint[] {rPointValue, sPointValue};
}

/**
 * Decrypts the encrypted message using the private key.
 * The decryption process is the reverse of encryption, recovering the original message.
 *
 * @param encryptedData The encrypted message as an array of ECPoints (R, S)
 * @return The decrypted plain message as a String
 */
public String decrypt(ECPoint[] encryptedData) {
ECPoint rPointValue = encryptedData[0];
ECPoint sPointValue = encryptedData[1];
ECPoint decodedPoint = sPointValue.subtract(rPointValue.multiply(privateKeyData, activeCurve.getPrimeModulus(), activeCurve.getCurveCoefficientA()), activeCurve.getPrimeModulus(), activeCurve.getCurveCoefficientA());
BigInteger restoredMessage = activeCurve.decodeMessage(decodedPoint);
return new String(restoredMessage.toByteArray());
}

/**
 * Generates a new public-private key pair for encryption and decryption.
 *
 * @param keySize The size (in bits) of the keys to generate
 */
public final void generateNewKeys(int keySize) {
SecureRandom randomSource = new SecureRandom();
activeCurve = new EllipticCurve(keySize);
basePointG = activeCurve.getBasePoint();
privateKeyData = new BigInteger(keySize, randomSource);
publicKeyPoint = basePointG.multiply(privateKeyData, activeCurve.getPrimeModulus(), activeCurve.getCurveCoefficientA());
}

/**
 * Class representing an elliptic curve with the form y^2 = x^3 + ax + b.
 */
public static class EllipticCurve {
private final BigInteger coefficientA;
private final BigInteger coefficientB;
private final BigInteger primeModulus;
private final ECPoint basePointGenerator;

public EllipticCurve(BigInteger aValue, BigInteger bValue, BigInteger primeValue, ECPoint basePointValue) {
this.coefficientA = aValue;
this.coefficientB = bValue;
this.primeModulus = primeValue;
this.basePointGenerator = basePointValue;
}

public EllipticCurve(int keySize) {
SecureRandom randomSource = new SecureRandom();
this.primeModulus = BigInteger.probablePrime(keySize, randomSource);
this.coefficientA = new BigInteger(keySize, randomSource);
this.coefficientB = new BigInteger(keySize, randomSource);
this.basePointGenerator = new ECPoint(BigInteger.valueOf(4), BigInteger.valueOf(8));
}

public ECPoint getBasePoint() {
return basePointGenerator;
}

public BigInteger getPrimeModulus() {
return primeModulus;
}

public BigInteger getCurveCoefficientA() {
return coefficientA;
}

public BigInteger getCurveCoefficientB() {
return coefficientB;
}

public int getFieldSize() {
return primeModulus.bitLength();
}

public ECPoint encodeMessage(BigInteger messageValue) {
return new ECPoint(messageValue, messageValue);
}

public BigInteger decodeMessage(ECPoint pointData) {
return pointData.getX();
}
}

/**
 * Class representing a point on the elliptic curve.
 */
public static class ECPoint {
private final BigInteger xCoordinate;
private final BigInteger yCoordinate;

public ECPoint(BigInteger xValue, BigInteger yValue) {
this.xCoordinate = xValue;
this.yCoordinate = yValue;
}

public BigInteger getX() {
return xCoordinate;
}

public BigInteger getY() {
return yCoordinate;
}

@Override
public String toString() {
return "ECPoint(x=" + xCoordinate.toString() + ", y=" + yCoordinate.toString() + ")";
}

/**
 * Add two points on the elliptic curve.
 */
public ECPoint add(ECPoint otherPoint, BigInteger primeValue, BigInteger aCoefficient) {
if (this.xCoordinate.equals(BigInteger.ZERO) && this.yCoordinate.equals(BigInteger.ZERO)) {
return otherPoint;
}
if (otherPoint.xCoordinate.equals(BigInteger.ZERO) && otherPoint.yCoordinate.equals(BigInteger.ZERO)) {
return this;
}
BigInteger slopeValue;
if (this.equals(otherPoint)) {
slopeValue = this.xCoordinate.pow(2).multiply(BigInteger.valueOf(3)).add(aCoefficient).multiply(this.yCoordinate.multiply(BigInteger.valueOf(2)).modInverse(primeValue)).mod(primeValue);
} else {
slopeValue = otherPoint.yCoordinate.subtract(this.yCoordinate).multiply(otherPoint.xCoordinate.subtract(this.xCoordinate).modInverse(primeValue)).mod(primeValue);
}
BigInteger newX = slopeValue.pow(2).subtract(this.xCoordinate).subtract(otherPoint.xCoordinate).mod(primeValue);
BigInteger newY = slopeValue.multiply(this.xCoordinate.subtract(newX)).subtract(this.yCoordinate).mod(primeValue);
return new ECPoint(newX, newY);
}

/**
 * Subtract two points on the elliptic curve.
 */
public ECPoint subtract(ECPoint otherPoint, BigInteger primeValue, BigInteger aCoefficient) {
ECPoint negatedPoint = new ECPoint(otherPoint.xCoordinate, primeValue.subtract(otherPoint.yCoordinate));
return this.add(negatedPoint, primeValue, aCoefficient);
}

/**
 * Multiply a point by a scalar (repeated addition).
 */
public ECPoint multiply(BigInteger scalarValue, BigInteger primeValue, BigInteger aCoefficient) {
ECPoint resultPoint = new ECPoint(BigInteger.ZERO, BigInteger.ZERO);
ECPoint currentPoint = this;
while (scalarValue.signum() > 0) {
if (scalarValue.testBit(0)) {
resultPoint = resultPoint.add(currentPoint, primeValue, aCoefficient);
}
currentPoint = currentPoint.add(currentPoint, primeValue, aCoefficient);
scalarValue = scalarValue.shiftRight(1);
}
return resultPoint;
}
}
}

public final class LevelOrderTraversal {
    private LevelOrderTraversal() {
    }

    public static List<List<Integer>> traverse(BinaryTree.Node root) {
        if (root == null) {
            return List.of();
        }

        List<List<Integer>> result = new ArrayList<>();

        Queue<BinaryTree.Node> q = new LinkedList<>();
        q.add(root);
        while (!q.isEmpty()) {
            int nodesOnLevel = q.size();
            List<Integer> level = new LinkedList<>();
            for (int i = 0; i < nodesOnLevel; i++) {
                BinaryTree.Node tempNode = q.poll();
                level.add(tempNode.data);

                if (tempNode.left != null) {
                    q.add(tempNode.left);
                }

                if (tempNode.right != null) {
                    q.add(tempNode.right);
                }
            }
            result.add(level);
        }
        return result;
    }

    /* Print nodes at the given level */
    public static void printGivenLevel(BinaryTree.Node root, int level) {
        if (root == null) {
            System.out.println("Root node must not be null! Exiting.");
            return;
        }
        if (level == 1) {
            System.out.print(root.data + " ");
        } else if (level > 1) {
            printGivenLevel(root.left, level - 1);
            printGivenLevel(root.right, level - 1);
        }
    }
}

/**
 * This class provides a solution to the Tiling Problem using divide-and-conquer.
 * <p>
 * The Tiling Problem involves filling a 2^n x 2^n board with a single missing
 * square using L-shaped tiles (each tile covers exactly three squares).
 * The algorithm recursively divides the board into four quadrants, places an
 * L-shaped tile in the appropriate quadrant, and fills the remaining areas.
 *
 * <p>Applications:
 * - Used in graphics and image processing.
 * - Helpful in solving puzzles and tiling problems in competitive programming.
 *
 * @author Hardvan
 */
public final class TilingProblem {
    private TilingProblem() {
    }

    /**
     * A counter used to label the L-shaped tiles placed on the board.
     */
    private static int tile = 1;

    /**
     * A 2D array representing the board to be tiled.
     */
    private static int[][] board;

    /**
     * Solves the tiling problem for a 2^n x 2^n board with one missing square.
     *
     * @param size The size of the board (must be a power of 2).
     * @param missingRow The row index of the missing square.
     * @param missingCol The column index of the missing square.
     * @return A 2D array representing the tiled board with L-shaped tiles.
     */
    public static int[][] solveTiling(int size, int missingRow, int missingCol) {
        board = new int[size][size];
        fillBoard(size, 0, 0, missingRow, missingCol);
        return board;
    }

    /**
     * Recursively fills the board with L-shaped tiles.
     *
     * <p>The board is divided into four quadrants. Depending on the location of
     * the missing square, an L-shaped tile is placed at the center of the board
     * to cover three of the four quadrants. The process is then repeated for
     * each quadrant until the entire board is filled.
     *
     * @param size The current size of the sub-board.
     * @param row The starting row index of the current sub-board.
     * @param col The starting column index of the current sub-board.
     * @param missingRow The row index of the missing square within the board.
     * @param missingCol The column index of the missing square within the board.
     */
    private static void fillBoard(int size, int row, int col, int missingRow, int missingCol) {
        if (size == 1) {
            return;
        }

        int half = size / 2;
        int t = tile++;

        // Top-left quadrant
        if (missingRow < row + half && missingCol < col + half) {
            fillBoard(half, row, col, missingRow, missingCol);
        } else {
            board[row + half - 1][col + half - 1] = t;
            fillBoard(half, row, col, row + half - 1, col + half - 1);
        }

        // Top-right quadrant
        if (missingRow < row + half && missingCol >= col + half) {
            fillBoard(half, row, col + half, missingRow, missingCol);
        } else {
            board[row + half - 1][col + half] = t;
            fillBoard(half, row, col + half, row + half - 1, col + half);
        }

        // Bottom-left quadrant
        if (missingRow >= row + half && missingCol < col + half) {
            fillBoard(half, row + half, col, missingRow, missingCol);
        } else {
            board[row + half][col + half - 1] = t;
            fillBoard(half, row + half, col, row + half, col + half - 1);
        }

        // Bottom-right quadrant
        if (missingRow >= row + half && missingCol >= col + half) {
            fillBoard(half, row + half, col + half, missingRow, missingCol);
        } else {
            board[row + half][col + half] = t;
            fillBoard(half, row + half, col + half, row + half, col + half);
        }
    }
}

import java.util.Scanner;

public class LinearSearch {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter array size: ");
        int n = scanner.nextInt();
        int[] arr = new int[n];
        System.out.println("Enter " + n + " elements:");
        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
        }
        System.out.print("Enter element to search: ");
        int key = scanner.nextInt();

        int foundIndex = -1;
        for (int i = 0; i < n; i++) {
            if (arr[i] == key) {
                foundIndex = i;
                break;
            }
        }

        if (foundIndex >= 0) {
            System.out.println("Element found at index " + foundIndex);
        } else {
            System.out.println("Element not found");
        }
        scanner.close();
    }
}

