package com.thealgorithms.datastructures.graphs;

import java.util.Arrays;
import java.util.Set;
import java.util.TreeSet;
import org.apache.commons.lang3.tuple.Pair;

/**
 * Dijkstra's algorithm for finding the shortest path from a single source vertex to all other vertices in a graph.
 */
public class DijkstraOptimizedAlgorithm {

private final int vertexCount;

/**
 * Constructs a Dijkstra object with the given number of vertices.
 *
 * @param vertexCount The number of vertices in the graph.
 */
public DijkstraOptimizedAlgorithm(int vertexCount) {
this.vertexCount = vertexCount;
}

/**
 * Executes Dijkstra's algorithm on the provided graph to find the shortest paths from the source vertex to all other vertices.
 *
 * The graph is represented as an adjacency matrix where {@code graph[i][j]} represents the weight of the edge from vertex {@code i}
 * to vertex {@code j}. A value of 0 indicates no edge exists between the vertices.
 *
 * @param weightMatrix The graph represented as an adjacency matrix.
 * @param startVertex The source vertex.
 * @return An array where the value at each index {@code i} represents the shortest distance from the source vertex to vertex {@code i}.
 * @throws IllegalArgumentException if the source vertex is out of range.
 */
public int[] computeShortestPaths(int[][] weightMatrix, int startVertex) {
if (startVertex < 0 || startVertex >= vertexCount) {
throw new IllegalArgumentException("Incorrect source");
}
int[] distanceValues = new int[vertexCount];
boolean[] visitedFlags = new boolean[vertexCount];
Set<Pair<Integer, Integer>> pendingNodes = new TreeSet<>();
Arrays.fill(distanceValues, Integer.MAX_VALUE);
Arrays.fill(visitedFlags, false);
distanceValues[startVertex] = 0;
pendingNodes.add(Pair.of(0, startVertex));
while (!pendingNodes.isEmpty()) {
Pair<Integer, Integer> currentEntry = pendingNodes.iterator().next();
pendingNodes.remove(currentEntry);
int currentVertex = currentEntry.getRight();
visitedFlags[currentVertex] = true;
for (int neighborIndex = 0; neighborIndex < vertexCount; neighborIndex++) {
if (!visitedFlags[neighborIndex] &&
weightMatrix[currentVertex][neighborIndex] != 0 &&
distanceValues[currentVertex] != Integer.MAX_VALUE &&
distanceValues[currentVertex] + weightMatrix[currentVertex][neighborIndex] < distanceValues[neighborIndex]) {
pendingNodes.remove(Pair.of(distanceValues[neighborIndex], neighborIndex));
distanceValues[neighborIndex] = distanceValues[currentVertex] + weightMatrix[currentVertex][neighborIndex];
pendingNodes.add(Pair.of(distanceValues[neighborIndex], neighborIndex));
}
}
}
return distanceValues;
}
}
