/**
 * A class representing the adjacency list of a directed graph. The adjacency list
 * maintains a mapping of vertices to their adjacent vertices.
 *
 * @param <VertexType> the type of vertices, extending Comparable to ensure that vertices
 * can be compared
 */
class AdjacencyList<VertexType extends Comparable<VertexType>> {

Map<VertexType, ArrayList<VertexType>> adjacencyMap;

/**
 * Constructor to initialize the adjacency list.
 */
AdjacencyList() {
adjacencyMap = new LinkedHashMap<>();
}

/**
 * Adds a directed edge from one vertex to another in the adjacency list.
 * If the vertex does not exist, it will be added to the list.
 *
 * @param startVertex the starting vertex of the directed edge
 * @param endVertex   the destination vertex of the directed edge
 */
void addDirectedEdge(VertexType startVertex, VertexType endVertex) {
if (!adjacencyMap.containsKey(startVertex)) {
adjacencyMap.put(startVertex, new ArrayList<>());
}
adjacencyMap.get(startVertex).add(endVertex);
if (!adjacencyMap.containsKey(endVertex)) {
adjacencyMap.put(endVertex, new ArrayList<>());
}
}

/**
 * Retrieves the list of adjacent vertices for a given vertex.
 *
 * @param sourceVertex the vertex whose adjacent vertices are to be fetched
 * @return an ArrayList of adjacent vertices for sourceVertex
 */
ArrayList<VertexType> getNeighbors(VertexType sourceVertex) {
return adjacencyMap.get(sourceVertex);
}

/**
 * Retrieves the set of all vertices present in the graph.
 *
 * @return a set containing all vertices in the graph
 */
Set<VertexType> getAllVertices() {
return adjacencyMap.keySet();
}
}

/**
 * A class that performs topological sorting on a directed graph using Kahn's algorithm.
 *
 * @param <VertexType> the type of vertices, extending Comparable to ensure that vertices
 * can be compared
 */
class TopologicalSort<VertexType extends Comparable<VertexType>> {

AdjacencyList<VertexType> inputGraph;
Map<VertexType, Integer> inDegreeMap;

/**
 * Constructor to initialize the topological sorting class with a given graph.
 *
 * @param inputGraph the directed graph represented as an adjacency list
 */
TopologicalSort(AdjacencyList<VertexType> inputGraph) {
this.inputGraph = inputGraph;
}

/**
 * Calculates the in-degree of all vertices in the graph. The in-degree is
 * the number of edges directed into a vertex.
 */
void computeInDegrees() {
inDegreeMap = new HashMap<>();
for (VertexType currentVertex : inputGraph.getAllVertices()) {
inDegreeMap.putIfAbsent(currentVertex, 0);
for (VertexType neighborVertex : inputGraph.getNeighbors(currentVertex)) {
inDegreeMap.put(neighborVertex, inDegreeMap.getOrDefault(neighborVertex, 0) + 1);
}
}
}

/**
 * Returns an ArrayList containing the vertices of the graph arranged in
 * topological order. Topological sorting ensures that for any directed edge
 * (u, v), vertex u appears before vertex v in the ordering.
 *
 * @return an ArrayList of vertices in topological order
 * @throws IllegalStateException if the graph contains a cycle
 */
ArrayList<VertexType> getTopologicalOrder() {
computeInDegrees();
Queue<VertexType> processingQueue = new LinkedList<>();
for (var degreeEntry : inDegreeMap.entrySet()) {
if (degreeEntry.getValue() == 0) {
processingQueue.add(degreeEntry.getKey());
}
}
ArrayList<VertexType> sortedOrder = new ArrayList<>();
int processedCount = 0;
while (!processingQueue.isEmpty()) {
VertexType currentVertex = processingQueue.poll();
sortedOrder.add(currentVertex);
processedCount++;
for (VertexType neighborVertex : inputGraph.getNeighbors(currentVertex)) {
inDegreeMap.put(neighborVertex, inDegreeMap.get(neighborVertex) - 1);
if (inDegreeMap.get(neighborVertex) == 0) {
processingQueue.add(neighborVertex);
}
}
}
if (processedCount != inputGraph.getAllVertices().size()) {
throw new IllegalStateException("Graph contains a cycle, topological sort not possible");
}
return sortedOrder;
}
}

/**
 * A driver class that sorts a given graph in topological order using Kahn's algorithm.
 */
public final class KahnsAlgorithm {
private KahnsAlgorithm() {
}

public static void main(String[] args) {
AdjacencyList<String> sampleGraph = new AdjacencyList<>();
sampleGraph.addDirectedEdge("a", "b");
sampleGraph.addDirectedEdge("c", "a");
sampleGraph.addDirectedEdge("a", "d");
sampleGraph.addDirectedEdge("b", "d");
sampleGraph.addDirectedEdge("c", "u");
sampleGraph.addDirectedEdge("u", "b");
TopologicalSort<String> sorter = new TopologicalSort<>(sampleGraph);
for (String vertexName : sorter.getTopologicalOrder()) {
System.out.print(vertexName + " ");
}
}
}

import java.util.Scanner;

public class VowelCounter {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String input = scanner.nextLine();

        int vowelCount = 0;
