/**
 * A date holder printed as a full weekday/month name.
 */
public class MyDate {

    private int year;
    private int month;
    private int day;

    public MyDate(int year, int month, int day) {
        this.year = year;
        this.month = month;
        this.day = day;
    }

    public int getYear() {
        return year;
    }

    public void setYear(int year) {
        this.year = year;
    }

    public int getMonth() {
        return month;
    }

    public void setMonth(int month) {
        this.month = month;
    }

    public int getDay() {
        return day;
    }

    public void setDay(int day) {
        this.day = day;
    }

    @Override
    public String toString() {
        String iso = year + "-" + month + "-" + day;
        Date parsed = null;
        try {
            parsed = new SimpleDateFormat("yyyy-MM-dd").parse(iso);
        } catch (ParseException ex) {
            Logger.getLogger(MyDate.class.getName()).log(Level.SEVERE, null, ex);
        }
        return new SimpleDateFormat("EEEE d MMM yyyy").format(parsed);
    }

    public MyDate nextYear() {
        year++;
        return this;
    }

    public MyDate nextMonth() {
        month++;
        return this;
    }

    public MyDate nextDay() {
        day++;
        return this;
    }

    public MyDate previousYear() {
        year--;
        return this;
    }

    public MyDate previousMonth() {
        month--;
        return this;
    }

    public MyDate previousDay() {
        day--;
        return this;
    }
}

class TestMyDate {

    public static boolean isLeapYear(int year) {
        if (year % 400 == 0) {
            return true;
        }
        return year % 4 == 0 && year % 100 != 0;
    }

    public static boolean isValidDate(int year, int month, int day) {
        String iso = year + "-" + month + "-" + day;
        SimpleDateFormat fmt = new SimpleDateFormat("yyyy-MM-dd");
        fmt.setLenient(false);
        try {
            fmt.parse(iso);
        } catch (ParseException pe) {
            return false;
        }
        return true;
    }

    public static int getDayOfWeek(int year, int month, int day) {
        String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
        String iso = year + "-" + month + "-" + day;
        Date parsed = null;
        try {
            parsed = new SimpleDateFormat("yyyy-MM-dd").parse(iso);
        } catch (ParseException ex) {
            Logger.getLogger(MyDate.class.getName()).log(Level.SEVERE, null, ex);
        }
        String name = new SimpleDateFormat("EEEE").format(parsed);
        int index = 0;
        for (String day2 : weekdays) {
            if (day2.equals(name)) {
                break;
            }
            index++;
        }
        return index;
    }

    public static void main(String[] args) {
        MyDate d1 = new MyDate(2012, 2, 28);
        System.out.println(d1);
        System.out.println(d1.nextDay());
        System.out.println(d1.nextDay());
        System.out.println(d1.nextMonth());
        System.out.println(d1.nextYear());

        MyDate d2 = new MyDate(2012, 1, 2);
        System.out.println(d2);
        System.out.println(d2.previousDay());
        System.out.println(d2.previousDay());
        System.out.println(d2.previousMonth());
        System.out.println(d2.previousYear());

        MyDate d3 = new MyDate(2012, 2, 29);
        System.out.println(d3.previousYear());
        MyDate d4 = new MyDate(2099, 11, 31);
        MyDate d5 = new MyDate(2011, 2, 29);
        System.out.println(d4);
        System.out.println(d5);
        System.out.println(getDayOfWeek(2099, 10, 31));
        System.out.println(isValidDate(2099, 10, 32));
    }
}

package com.thealgorithms.devutils.nodes;

import java.util.Collection;

/**
 * {@link TreeNode} extension that holds a {@link Collection} of references to
 * child Nodes.
 *
 * @param <E> The type of the data held in the Node.
 *
 * @author <a href="https://github.com/aitorfi">aitorfi</a>
 */
public class LargeTreeNode<E> extends TreeNode<E> {

    /**
     * {@link Collection} that holds the Nodes' child nodes.
     */
    private Collection<LargeTreeNode<E>> childNodes;

    /**
     * Empty constructor.
     */
    public LargeTreeNode() {
        super();
    }

    /**
     * Initializes the Nodes' data.
     *
     * @param data Value to which data will be initialized.
     * @see TreeNode#TreeNode(Object)
     */
    public LargeTreeNode(E data) {
        super(data);
    }

    /**
     * Initializes the Nodes' data and parent node reference.
     *
     * @param data Value to which data will be initialized.
     * @param parentNode Value to which the nodes' parent reference will be set.
     * @see TreeNode#TreeNode(Object, Node)
     */
    public LargeTreeNode(E data, LargeTreeNode<E> parentNode) {
        super(data, parentNode);
    }

    /**
     * Initializes the Nodes' data and parent and child nodes references.
     *
     * @param data Value to which data will be initialized.
     * @param parentNode Value to which the nodes' parent reference will be set.
     * @param childNodes {@link Collection} of child Nodes.
     * @see TreeNode#TreeNode(Object, Node)
     */
    public LargeTreeNode(E data, LargeTreeNode<E> parentNode, Collection<LargeTreeNode<E>> childNodes) {
        super(data, parentNode);
        this.childNodes = childNodes;
    }

    /**
     * @return True if the node is a leaf node, otherwise false.
     * @see TreeNode#isLeafNode()
     */
    @Override
    public boolean isLeafNode() {
        return (childNodes == null || childNodes.isEmpty());
    }

    public Collection<LargeTreeNode<E>> getChildNodes() {
        return childNodes;
    }

    public void setChildNodes(Collection<LargeTreeNode<E>> childNodes) {
        this.childNodes = childNodes;
    }
}

final class ProductCipher {
    private ProductCipher() {
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            System.out.println("Enter the input to be encrypted: ");
            String substitutionInput = sc.nextLine();
            System.out.println(" ");
            System.out.println("Enter a number: ");
            int n = sc.nextInt();

            // Substitution encryption
            StringBuffer substitutionOutput = new StringBuffer();
            for (int i = 0; i < substitutionInput.length(); i++) {
                char c = substitutionInput.charAt(i);
                substitutionOutput.append((char) (c + 5));
            }
            System.out.println(" ");
            System.out.println("Substituted text: ");
            System.out.println(substitutionOutput);

            // Transposition encryption
            String transpositionInput = substitutionOutput.toString();
            int modulus = transpositionInput.length() % n;
            if (modulus != 0) {
                modulus = n - modulus;

                for (; modulus != 0; modulus--) {
                    transpositionInput += "/";
                }
            }
            StringBuffer transpositionOutput = new StringBuffer();
            System.out.println(" ");
            System.out.println("Transposition Matrix: ");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < transpositionInput.length() / n; j++) {
                    char c = transpositionInput.charAt(i + (j * n));
                    System.out.print(c);
                    transpositionOutput.append(c);
                }
                System.out.println();
            }
            System.out.println(" ");
            System.out.println("Final encrypted text: ");
            System.out.println(transpositionOutput);

            // Transposition decryption
            n = transpositionOutput.length() / n;
            StringBuffer transpositionPlaintext = new StringBuffer();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < transpositionOutput.length() / n; j++) {
                    char c = transpositionOutput.charAt(i + (j * n));
                    transpositionPlaintext.append(c);
                }
            }

            // Substitution decryption
            StringBuffer plaintext = new StringBuffer();
            for (int i = 0; i < transpositionPlaintext.length(); i++) {
                char c = transpositionPlaintext.charAt(i);
                plaintext.append((char) (c - 5));
            }

            System.out.println("Plaintext: ");
            System.out.println(plaintext);
        }
    }
}

