/**
 *
 * @author GIA KINH
 */
public class MovablePoint implements Movable{
    private int x;
    private int y;
    private int xSpeed;
    private int ySpeed;

    public MovablePoint() {
    }

    public MovablePoint(int x, int y, int xSpeed, int ySpeed) {
        this.x = x;
        this.y = y;
        this.xSpeed = xSpeed;
        this.ySpeed = ySpeed;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int getxSpeed() {
        return xSpeed;
    }

    public void setxSpeed(int xSpeed) {
        this.xSpeed = xSpeed;
    }

    public int getySpeed() {
        return ySpeed;
    }

    public void setySpeed(int ySpeed) {
        this.ySpeed = ySpeed;
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ") speed=" + xSpeed + "," + ySpeed + ')';
    }

    @Override
    public void moveUp() {
       this.y-=this.ySpeed;
    }

    @Override
    public void moveDown() {
        this.y+=this.ySpeed;
    }

    @Override
    public void moveLeft() {
        this.x-=this.xSpeed;
    }

    @Override
    public void moveRight() {
        this.x+=this.xSpeed;
    }
}

// Hesap Makinesi GUI uygulamasi
public class HesapMakinesi extends JFrame {

	private static final long serialVersionUID = 1L;
	private JTextField metinKutusu; // Sayi ve sonuclarin gosterilecegi metin kutusu
    private String operator; // Secilen matematiksel operator (+, -, x, /)
    private double birinciSayi; // Ilk operand
    private boolean operatorTiklandi; // Operator secildiginde durumu tutar

    // Yapici metot: Arayuz olusturulur
    public HesapMakinesi() {
        setTitle("Hesap Makinesi"); // Pencere basligi
        setSize(300, 400); // Pencere boyutu
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE); // Cikis islemi
        setLayout(new BorderLayout()); // Cerceve duzeni

        operator = "";
        birinciSayi = 0;
        operatorTiklandi = false;

        // Metin kutusunu olustur ve ust bolgeye ekle
        metinKutusu = new JTextField();
        metinKutusu.setEditable(false); // Kullanici dogrudan metin kutusuna yazamaz
        metinKutusu.setFont(new Font("Arial", Font.PLAIN, 24)); // Daha buyuk bir yazi tipi
        metinKutusu.setPreferredSize(new Dimension(0, 50)); // Metin kutusunun yuksekligini arttir
        add(metinKutusu, BorderLayout.NORTH);

        // Buton panelini olustur
        JPanel butonPaneli = new JPanel();
        butonPaneli.setLayout(new GridLayout(4, 4)); // 4x4 duzen

        // Butonlarin metinlerini tanimla
        String[] butonlar = {
                "7", "8", "9", "/",
                "4", "5", "6", "x",
                "1", "2", "3", "-",
                "0", "AC", "=", "+"
        };

        // Her buton icin dongu ile islem yap
        for (String buton : butonlar) {
            JButton btn = new JButton(buton); // Butonu olustur
            btn.addActionListener(new ButonTiklamaDinleyicisi()); // Tiklama olayini dinle
            butonPaneli.add(btn); // Butonu panele ekle
        }

        add(butonPaneli, BorderLayout.CENTER); // Buton panelini orta bolgeye ekle
    }

    // Butonlara tiklandiginda yapilacak islemler
    private class ButonTiklamaDinleyicisi implements ActionListener {

        public void actionPerformed(ActionEvent e) {

            String komut = e.getActionCommand(); // Tiklanan butonun metni alinir

            if (komut.matches("[0-9]")) { // Eger bir sayi ise
                if (operatorTiklandi) { // Eger daha once operator tiklandiysa
                    metinKutusu.setText(""); // Metin kutusunu temizle
                    operatorTiklandi = false;
                }
                metinKutusu.setText(metinKutusu.getText() + komut); // Sayiyi ekle
            } else if (komut.equals("AC")) { // Eger "AC" (Temizle) tiklandiysa
                metinKutusu.setText(""); // Metin kutusunu temizle
            } else if (komut.matches("[+\\-x/]")) { // Eger bir operator tiklandiysa
                operator = komut; // Operatoru kaydet
                birinciSayi = Double.parseDouble(metinKutusu.getText()); // Ilk sayiyi kaydet
                operatorTiklandi = true; // Operator tiklandigini isaretle
            } else if (komut.equals("=")) { // Eger "=" tiklandiysa
                double ikinciSayi = Double.parseDouble(metinKutusu.getText()); // Ikinci sayiyi al
                double sonuc = 0; // Sonuc degiskeni

                // Operatore gore islem yap
                switch (operator) {
                    case "+":
                        sonuc = birinciSayi + ikinciSayi;
                        break;
                    case "-":
                        sonuc = birinciSayi - ikinciSayi;
                        break;
                    case "x":
                        sonuc = birinciSayi * ikinciSayi;
                        break;
                    case "/":
                        sonuc = birinciSayi / ikinciSayi;
                        break;
                }

                metinKutusu.setText(String.valueOf(sonuc)); // Sonucu goster
                operatorTiklandi = true; // Yeni islem icin hazirla
            }
        }
    }

    // Ana metot: Uygulamayi baslatir
    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            public void run() {
                HesapMakinesi hesapMakinesi = new HesapMakinesi(); // Hesap makinesi olustur
                hesapMakinesi.setVisible(true); // Gorunur yap
            }
        });
    }
}

package com.thealgorithms.datastructures.crdt;

import java.time.Instant;
import java.util.HashMap;
import java.util.Map;

/**
 * Last-Write-Wins Element Set (LWWElementSet) is a state-based CRDT (Conflict-free Replicated Data
 * Type) designed for managing sets in a distributed and concurrent environment. It supports the
 * addition and removal of elements, using timestamps to determine the order of operations. The set
 * is split into two subsets: the add set for elements to be added and the remove set for elements
 * to be removed. The LWWElementSet ensures that the most recent operation (based on the timestamp)
 * wins in the case of concurrent operations.
 *
 * @param <ElementType> The type of the elements in the LWWElementSet.
 * @author <a href="https://github.com/itakurah">itakurah (GitHub)</a>, <a
 * href="https://www.linkedin.com/in/niklashoefflin/">Niklas Hoefflin (LinkedIn)</a>
 * @see <a href="https://en.wikipedia.org/wiki/Conflict-free_replicated_data_type">Conflict free
 * replicated data type (Wikipedia)</a>
 * @see <a href="https://inria.hal.science/inria-00555588v1/document">A comprehensive study of
 * Convergent and Commutative Replicated Data Types</a>
 */
class LWWElementSet<ElementType> {
final Map<ElementType, TimedElement<ElementType>> addedElements;
final Map<ElementType, TimedElement<ElementType>> removedElements;

/**
 * Constructs an empty LWWElementSet. This constructor initializes the addSet and removeSet as
 * empty HashMaps. The addSet stores elements that are added, and the removeSet stores elements
 * that are removed.
 */
LWWElementSet() {
this.addedElements = new HashMap<>();
this.removedElements = new HashMap<>();
}

/**
 * Adds an element to the addSet with the current timestamp. This method stores the element in the
 * addSet, ensuring that the element is added to the set with an associated timestamp that
 * represents the time of the addition.
 *
 * @param elementKey The key of the element to be added.
 */
public void add(ElementType elementKey) {
addedElements.put(elementKey, new TimedElement<>(elementKey, Instant.now()));
}

/**
 * Removes an element by adding it to the removeSet with the current timestamp. This method adds
 * the element to the removeSet, marking it as removed with the current timestamp.
 *
 * @param elementKey The key of the element to be removed.
 */
public void remove(ElementType elementKey) {
removedElements.put(elementKey, new TimedElement<>(elementKey, Instant.now()));
}

/**
 * Checks if an element is in the LWWElementSet. An element is considered present if it exists in
 * the addSet and either does not exist in the removeSet, or its add timestamp is later than any
 * corresponding remove timestamp.
 *
 * @param searchKey The key of the element to be checked.
 * @return {@code true} if the element is present in the set (i.e., its add timestamp is later
 * than its remove timestamp, or it is not in the remove set), {@code false} otherwise (i.e.,
 * the element has been removed or its remove timestamp is later than its add timestamp).
 */
public boolean contains(ElementType searchKey) {
TimedElement<ElementType> addEntry = addedElements.get(searchKey);
TimedElement<ElementType> removeEntry = removedElements.get(searchKey);
return addEntry != null && (removeEntry == null || addEntry.getTimestamp().isAfter(removeEntry.getTimestamp()));
}

/**
 * Merges another LWWElementSet into this set. This method takes the union of both the add-sets
 * and remove-sets from the two sets, resolving conflicts by keeping the element with the latest
 * timestamp. If an element appears in both the add-set and remove-set of both sets, the one with
 * the later timestamp will be retained.
 *
 * @param otherSet The LWWElementSet to merge with the current set.
 */
public void mergeWith(LWWElementSet<ElementType> otherSet) {
for (Map.Entry<ElementType, TimedElement<ElementType>> entryItem : otherSet.addedElements.entrySet()) {
addedElements.merge(entryItem.getKey(), entryItem.getValue(), this::resolveTimestampConflict);
}
for (Map.Entry<ElementType, TimedElement<ElementType>> entryItem : otherSet.removedElements.entrySet()) {
removedElements.merge(entryItem.getKey(), entryItem.getValue(), this::resolveTimestampConflict);
}
}

/**
 * Resolves conflicts between two elements by selecting the one with the later timestamp. This
 * method is used when merging two LWWElementSets to ensure that the most recent operation (based
 * on timestamps) is kept.
 *
 * @param firstElement The first element.
 * @param secondElement The second element.
 * @return The element with the later timestamp.
 */
private TimedElement<ElementType> resolveTimestampConflict(TimedElement<ElementType> firstElement, TimedElement<ElementType> secondElement) {
return firstElement.getTimestamp().isAfter(secondElement.getTimestamp()) ? firstElement : secondElement;
}
}

/**
 * Represents an element in the LWWElementSet, consisting of a key and a timestamp. This class is
 * used to store the elements in both the add and remove sets with their respective timestamps.
 *
 * @param <ElementType> The type of the key associated with the element.
 */
class TimedElement<ElementType> {
private final ElementType elementKey;
private final Instant operationTimestamp;

/**
 * Constructs a new Element with the specified key and timestamp.
 *
 * @param elementKey       The key of the element.
 * @param operationTimestamp The timestamp associated with the element.
 */
TimedElement(ElementType elementKey, Instant operationTimestamp) {
this.elementKey = elementKey;
this.operationTimestamp = operationTimestamp;
}

public ElementType getElementKey() {
return elementKey;
}

public Instant getTimestamp() {
return operationTimestamp;
}
}

package com.thealgorithms.dynamicprogramming;

import java.util.Scanner;
/**
 * This file contains an implementation of finding the nth CATALAN NUMBER using
 * dynamic programming : <a href="https://en.wikipedia.org/wiki/Catalan_number">Wikipedia</a>
 *
 * Time Complexity: O(n^2) Space Complexity: O(n)
 *
 * @author <a href="https://github.com/amritesh19">AMRITESH ANAND</a>
 */
public final class CatalanNumber {
    private CatalanNumber() {
    }

    /**
     * This method finds the nth Catalan number
     *
     * @param n input n which determines the nth Catalan number n should be less
     * than equal to 50 as 50th Catalan number is 6,533,841,209,031,609,592 for
     * n > 50, BigInteger class should be used instead long
     *
     * @return catalanArray[n] the nth Catalan number
     */
    static long findNthCatalan(int n) {
        // Array to store the results of subproblems i.e Catalan numbers from [1...n-1]
        long[] catalanArray = new long[n + 1];

        // Initialising C₀ = 1 and C₁ = 1
        catalanArray[0] = 1;
        catalanArray[1] = 1;

        /*
         * The Catalan numbers satisfy the recurrence relation C₀=1 and Cn = Σ
         * (Ci * Cn-1-i), i = 0 to n-1 , n > 0
         */
        for (int i = 2; i <= n; i++) {
            catalanArray[i] = 0;
            for (int j = 0; j < i; j++) {
                catalanArray[i] += catalanArray[j] * catalanArray[i - j - 1];
            }
        }

        return catalanArray[n];
    }

    // Main method
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        System.out.println("Enter the number n to find nth Catalan number (n <= 50)");
        int n = sc.nextInt();
        System.out.println(n + "th Catalan number is " + findNthCatalan(n));

        sc.close();
    }
}

package com.thealgorithms.conversions;

/**
 * A utility class to convert between Cartesian and Polar coordinate systems.
 *
 * <p>This class provides methods to perform the following conversions:
 * <ul>
 *   <li>Cartesian to Polar coordinates</li>
 *   <li>Polar to Cartesian coordinates</li>
 * </ul>
 *
 * <p>The class is final and cannot be instantiated.
 */
public final class CoordinateConverter {

private CoordinateConverter() {
}

/**
 * Converts Cartesian coordinates to Polar coordinates.
 *
 * @param coordX the x-coordinate in the Cartesian system; must be a finite number
 * @param coordY the y-coordinate in the Cartesian system; must be a finite number
 * @return an array where the first element is the radius (r) and the second element is the angle (theta) in degrees
 * @throws IllegalArgumentException if coordX or coordY is not a finite number
 */
public static double[] cartesianToPolar(double coordX, double coordY) {
if (!Double.isFinite(coordX) || !Double.isFinite(coordY)) {
throw new IllegalArgumentException("x and y must be finite numbers.");
}
double radiusValue = Math.sqrt(coordX * coordX + coordY * coordY);
double angleDegrees = Math.toDegrees(Math.atan2(coordY, coordX));
return new double[] {radiusValue, angleDegrees};
}

/**
 * Converts Polar coordinates to Cartesian coordinates.
 *
 * @param radiusValue the radius in the Polar system; must be non-negative
 * @param angleDegrees the angle (theta) in degrees in the Polar system; must be a finite number
 * @return an array where the first element is the x-coordinate and the second element is the y-coordinate in the Cartesian system
 * @throws IllegalArgumentException if radiusValue is negative or angleDegrees is not a finite number
 */
public static double[] polarToCartesian(double radiusValue, double angleDegrees) {
if (radiusValue < 0) {
throw new IllegalArgumentException("Radius (r) must be non-negative.");
}
if (!Double.isFinite(angleDegrees)) {
throw new IllegalArgumentException("Theta (angle) must be a finite number.");
}
double angleRadians = Math.toRadians(angleDegrees);
double coordX = radiusValue * Math.cos(angleRadians);
double coordY = radiusValue * Math.sin(angleRadians);
return new double[] {coordX, coordY};
}
}

