        RATES.put("EUR", 0.92);
        RATES.put("GBP", 0.79);
        RATES.put("JPY", 149.5);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Amount in USD: ");
        double amount = scanner.nextDouble();
        System.out.print("Target currency (EUR/GBP/JPY): ");
