package com.thealgorithms.dynamicprogramming;

/*
Given the following grid with length m and width n:
\---\---\---\ (n)
\ 1 \ 3 \ 1 \
\---\---\---\
\ 1 \ 5 \ 1 \
\---\---\---\
\ 4 \ 2 \ 1 \
\---\---\---\
(m)
Find the path where its sum is the smallest.

The Time Complexity of your algorithm should be smaller than or equal to O(mn).
The Space Complexity of your algorithm should be smaller than or equal to O(n).
You can only move from the top left corner to the down right corner.
You can only move one step down or right.

EXAMPLE:
INPUT: grid = [[1,3,1],[1,5,1],[4,2,1]]
OUTPUT: 7
EXPLANATIONS: 1 + 3 + 1 + 1 + 1 = 7

For more information see https://www.geeksforgeeks.org/maximum-path-sum-matrix/
 */
public final class MinimumPathSum {

    private MinimumPathSum() {
    }

    public static int minimumPathSum(final int[][] grid) {
        int numRows = grid.length;
        int numCols = grid[0].length;

        if (numCols == 0) {
            return 0;
        }

        int[] dp = new int[numCols];

        // Initialize the first element of the dp array
        dp[0] = grid[0][0];

        // Calculate the minimum path sums for the first row
        for (int col = 1; col < numCols; col++) {
            dp[col] = dp[col - 1] + grid[0][col];
        }

        // Calculate the minimum path sums for the remaining rows
        for (int row = 1; row < numRows; row++) {
            // Update the minimum path sum for the first column
            dp[0] += grid[row][0];

            for (int col = 1; col < numCols; col++) {
                // Choose the minimum path sum from the left or above
                dp[col] = Math.min(dp[col - 1], dp[col]) + grid[row][col];
            }
        }

        // Return the minimum path sum for the last cell in the grid
        return dp[numCols - 1];
    }
}

class AdjacencyListGraph<E extends Comparable<E>> {

    ArrayList<Vertex> vertices;

    AdjacencyListGraph() {
        vertices = new ArrayList<>();
    }

    private class Vertex {

        E data;
        ArrayList<Vertex> adjacentVertices;

        Vertex(E data) {
            adjacentVertices = new ArrayList<>();
            this.data = data;
        }

        public boolean addAdjacentVertex(Vertex to) {
            for (Vertex v : adjacentVertices) {
                if (v.data.compareTo(to.data) == 0) {
                    return false; // the edge already exists
                }
            }
            return adjacentVertices.add(to); // this will return true;
        }

        public boolean removeAdjacentVertex(E to) {
            // use indexes here so it is possible to
            // remove easily without implementing
            // equals method that ArrayList.remove(Object o) uses
            for (int i = 0; i < adjacentVertices.size(); i++) {
                if (adjacentVertices.get(i).data.compareTo(to) == 0) {
                    adjacentVertices.remove(i);
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * this method removes an edge from the graph between two specified
     * vertices
     *
     * @param from the data of the vertex the edge is from
     * @param to the data of the vertex the edge is going to
     * @return returns false if the edge doesn't exist, returns true if the edge
     * exists and is removed
     */
    public boolean removeEdge(E from, E to) {
        Vertex fromV = null;
        for (Vertex v : vertices) {
            if (from.compareTo(v.data) == 0) {
                fromV = v;
                break;
            }
        }
        if (fromV == null) {
            return false;
        }
        return fromV.removeAdjacentVertex(to);
    }

    /**
     * this method adds an edge to the graph between two specified vertices
     *
     * @param from the data of the vertex the edge is from
     * @param to the data of the vertex the edge is going to
     * @return returns true if the edge did not exist, return false if it
     * already did
     */
    public boolean addEdge(E from, E to) {
        Vertex fromV = null;
        Vertex toV = null;
        for (Vertex v : vertices) {
            if (from.compareTo(v.data) == 0) { // see if from vertex already exists
                fromV = v;
            } else if (to.compareTo(v.data) == 0) { // see if to vertex already exists
                toV = v;
            }
            if (fromV != null && toV != null) {
                break; // both nodes exist so stop searching
            }
        }
        if (fromV == null) {
            fromV = new Vertex(from);
            vertices.add(fromV);
        }
        if (toV == null) {
            toV = new Vertex(to);
            vertices.add(toV);
        }
        return fromV.addAdjacentVertex(toV);
    }

    /**
     * this gives a list of vertices in the graph and their adjacencies
     *
     * @return returns a string describing this graph
     */
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Vertex v : vertices) {
            sb.append("Vertex: ");
            sb.append(v.data);
            sb.append("\n");
            sb.append("Adjacent vertices: ");
            for (Vertex v2 : v.adjacentVertices) {
                sb.append(v2.data);
                sb.append(" ");
            }
            sb.append("\n");
        }
        return sb.toString();
    }
}

public final class Graphs {
    private Graphs() {
    }

    public static void main(String[] args) {
        AdjacencyListGraph<Integer> graph = new AdjacencyListGraph<>();
        assert graph.addEdge(1, 2);
        assert graph.addEdge(1, 5);
        assert graph.addEdge(2, 5);
        assert !graph.addEdge(1, 2);
        assert graph.addEdge(2, 3);
        assert graph.addEdge(3, 4);
        assert graph.addEdge(4, 1);
        assert !graph.addEdge(2, 3);
        System.out.println(graph);
    }
}

public class FizzBuzz {
    public static void main(String[] args) {
        for (int i = 1; i <= 30; i++) {
            if (i % 15 == 0) {
                System.out.println("FizzBuzz");
            } else if (i % 3 == 0) {
                System.out.println("Fizz");
            } else if (i % 5 == 0) {
                System.out.println("Buzz");
            } else {
                System.out.println(i);
            }
        }
    }
}

import org.junit.Test; 
import static org.junit.Assert.assertEquals;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.BeforeEach;

/*
 * Java'da JUnit testleri:
 * 
 * Eclipse Properties -> Java Build Path -> Libraries -> Add Library -> JUnit -> JUnit 3/4
 * 
 * */

public class CalculatorTest {

	private Calculator calculator = new Calculator();

	@BeforeEach
	public void setUp() {
		// Calculator nesnesini her testten once olustur
		calculator = new Calculator();
	}

	@Test
	public void testAdd() {
		// Toplama islemini test et
		assertEquals(5, calculator.add(2, 3)); // 2 + 3 = 5
		assertEquals(-1, calculator.add(-2, 1)); // -2 + 1 = -1
		assertEquals(0, calculator.add(-2, 2)); // -2 + 2 = 0
	}

	@Test
	public void testSubtract() {
		// Cikarma islemini test et
		assertEquals(1, calculator.subtract(3, 2)); // 3 - 2 = 1
		assertEquals(-3, calculator.subtract(-2, 1)); // -2 - 1 = -3
		assertEquals(0, calculator.subtract(2, 2)); // 2 - 2 = 0
	}

	@Test
	public void testMultiply() {
		// Carpma islemini test et
		assertEquals(6, calculator.multiply(2, 3)); // 2 * 3 = 6
		assertEquals(-2, calculator.multiply(-2, 1)); // -2 * 1 = -2
		assertEquals(0, calculator.multiply(0, 2)); // 0 * 2 = 0
	}

	@Test
	public void testDivide() {
		// Bolme islemini test et
		assertEquals(2, calculator.divide(6, 3)); // 6 / 3 = 2
		assertEquals(-2, calculator.divide(-4, 2)); // -4 / 2 = -2

		// Sifira bolme hatasini test et
		Exception exception = assertThrows(IllegalArgumentException.class, () -> {
			calculator.divide(1, 0); // 1 / 0 -> Hata
		});

		// Hata mesajinin dogrulugunu kontrol et
		assertEquals("Sifira bolme yapilamaz.", exception.getMessage());
	}

	@Test
	public void testModulus() {
		// Modulus islemini test et
		assertEquals(1, calculator.modulus(5, 2)); // 5 % 2 = 1
		assertEquals(0, calculator.modulus(4, 2)); // 4 % 2 = 0
		assertEquals(-1, calculator.modulus(-5, 2)); // -5 % 2 = -1
		assertEquals(0, calculator.modulus(0, 5)); // 0 % 5 = 0
	}

	@Test
	public void testFactorial() {
		// Faktoriyel islemini test et
		assertEquals(120, calculator.factorial(5)); // 5! = 120
		assertEquals(1, calculator.factorial(0)); // 0! = 1
		assertEquals(1, calculator.factorial(1)); // 1! = 1
		assertThrows(IllegalArgumentException.class, () -> calculator.factorial(-1)); // -1! -> Hata
	}

	@Test
	public void testMax() {
		// En buyuk sayiyi test et
		assertEquals(5, calculator.max(3, 5)); // max(3, 5) = 5
		assertEquals(-3, calculator.max(-3, -5)); // max(-3, -5) = -3
		assertEquals(7, calculator.max(7, 7)); // max(7, 7) = 7
	}

	@Test
	public void testMin() {
		// En kucuk sayiyi test et
		assertEquals(3, calculator.min(3, 5)); // min(3, 5) = 3
		assertEquals(-5, calculator.min(-3, -5)); // min(-3, -5) = -5
		assertEquals(7, calculator.min(7, 7)); // min(7, 7) = 7
	}

	@Test
	public void testAverage() {
		// Ortalama islemini test et
		assertEquals(3.0, calculator.average(2, 4), 0.001); // average(2, 4) = 3.0
		assertEquals(5.5, calculator.average(5, 6), 0.001); // average(5, 6) = 5.5
		assertEquals(-2.0, calculator.average(-4, -0), 0.001); // average(-4, 0) = -2.0
	}

	@Test
	public void testPower() {
		// Us alma islemini test et
		assertEquals(8, calculator.power(2, 3), 0.001); // 2^3 = 8
		assertEquals(1, calculator.power(5, 0), 0.001); // 5^0 = 1
		assertEquals(-8, calculator.power(-2, 3), 0.001); // (-2)^3 = -8
		assertEquals(0.25, calculator.power(2, -2), 0.001); // 2^-2 = 0.25
	}

	@Test
	public void testSqrt() {
		// Karekok islemini test et
		assertEquals(3, calculator.squareRoot(9), 0.001); // sqrt(9) = 3
		assertEquals(2, calculator.squareRoot(4), 0.001); // sqrt(4) = 2

		// Negatif sayi icin hata bekle
		Exception exception = assertThrows(IllegalArgumentException.class, () -> {
			calculator.squareRoot(-4); // sqrt(-4) -> Hata
		});

		// Hata mesajinin dogrulugunu kontrol et
		assertEquals("Negatif sayilarin karekoku hesaplanamaz.", exception.getMessage());
	}
}

public class KesirliSayiToplama {

	public static void main(String[] args) {

		// Kullanicidan ondalikli iki deger okuyoruz
		Scanner girisOkuyucu = new Scanner(System.in);

		System.out.println("Birinci sayiyi giriniz: ");
		double ilkDeger = girisOkuyucu.nextDouble();

		System.out.println("ikinci sayiyi giriniz: ");
		double ikinciDeger = girisOkuyucu.nextDouble();

		girisOkuyucu.close();

		// Toplami ayri bir metotta hesaplatiyoruz
		double sonuc = topla(ilkDeger, ikinciDeger);

		System.out.println(ilkDeger + " ile " + ikinciDeger + " toplami: " + sonuc);
	}

	private static double topla(double a, double b) {
		return a + b;
	}
}

public class KartNumarasiDogrulayici {

    // Tek bir sayinin basamaklarini toplar (orn: 47 -> 4+7 = 11)
    private static int basamakToplamiHesapla(int deger) {
        int birikim = 0;
        int kalan = deger;
        while (kalan != 0) {
            birikim = birikim + (kalan % 10);
            kalan /= 10;
        }
        return birikim;
    }

    // Hata ayiklama amacli dizi gosterimi
    private static void diziyiGoster(int[] veriler) {
        StringBuilder sb = new StringBuilder("Dizi: ");
        for (int deger : veriler) {
            sb.append(deger).append(' ');
        }
        System.out.println(sb.toString().trim());
    }

    // Karakter dizisindeki her rakami int dizisine cevirir
    private static int[] karakterleriSayiyaCevir(String numara) {
        int uzunluk = numara.length();
        int[] rakamlar = new int[uzunluk];

        for (int pozisyon = 0; pozisyon < uzunluk; pozisyon++) {
            char karakter = numara.charAt(pozisyon);
            rakamlar[pozisyon] = karakter - '0';
        }

        diziyiGoster(rakamlar);
        return rakamlar;
    }

    // Luhn algoritmasi geregi sagdan itibaren her ikinci haneyi ikiye katlar
    private static int[] ikinciHaneleriKatla(int[] rakamlar) {
        int pozisyon = rakamlar.length - 2;
        while (pozisyon >= 0) {
            rakamlar[pozisyon] = rakamlar[pozisyon] * 2;
            pozisyon -= 2;
        }

        diziyiGoster(rakamlar);
        return rakamlar;
    }

    // Dizideki tum degerlerin toplamini verir
    private static int hepsiniTopla(int[] rakamlar) {
        int genelToplam = 0;
        for (int deger : rakamlar) {
            genelToplam += deger;
        }
        System.out.println("Dizi elemanlar toplami: " + genelToplam);
        return genelToplam;
    }

    // Luhn kontrolune gore kart numarasinin gecerliligini belirler
    private static boolean luhnKontroluGecerliMi(String numara) {
        int[] rakamlar = karakterleriSayiyaCevir(numara);
        rakamlar = ikinciHaneleriKatla(rakamlar);

        for (int i = 0; i < rakamlar.length; i++) {
            rakamlar[i] = basamakToplamiHesapla(rakamlar[i]);
        }

        int nihaiToplam = hepsiniTopla(rakamlar);
        return (nihaiToplam % 10) == 0;
    }

    // Ornek kart numaralari uzerinde toplu test calistirir
    private static void ornekleriTestEt() {
        String[] ornekKartlar = {
            "4532015112830366", "6011514433546201", "378282246310005",
            "1234567890123456", "1111222333334444"
        };

        for (String kart : ornekKartlar) {
            String durum = luhnKontroluGecerliMi(kart) ? "Gecerli" : "Gecersiz";
            System.out.println(kart + " -> " + durum);
            System.out.println();
        }
    }

    // Kullanicidan kart numarasi ister, format dogrulamasi yapar ve sonucu bildirir
    private static void kullanicidanKartAl() {
        Scanner tarayici = new Scanner(System.in);
        System.out.println("\nKart numaranizi giriniz:");
        String girilenNumara = tarayici.next();

        while (!girilenNumara.matches("\\d{13,19}")) {
            System.out.println("Lutfen gecerli bir kart numarasi giriniz (13-19 hane):");
            girilenNumara = tarayici.next();
        }
        tarayici.close();

        if (luhnKontroluGecerliMi(girilenNumara)) {
            System.out.println("Kart numarasi dogru.");
        } else {
            System.out.println("Kart numarasi yanlis.");
        }
    }

    public static void main(String[] args) {
        ornekleriTestEt();
        kullanicidanKartAl();
    }
}

public class MantiksalIslemler {

	public static void main(String[] args) {

		boolean dogru = true;  // dogru degiskeni true olarak tanimlandi
		boolean yanlis = false; // yanlis degiskeni false olarak tanimlandi

		// "VE" Mantiksal Operatoru (&&)
		boolean veSonuc = dogru && yanlis; // dogru VE yanlis operatoru ile karsilastirildi
		System.out.println("VE Mantiksal Operatori (&&): " + veSonuc); // false

		// "VEYA" Mantiksal Operatoru (||)
		boolean veyaSonuc = dogru || yanlis; // dogru VEYA yanlis operatoru ile karsilastirildi
		System.out.println("VEYA Mantiksal Operatori (||): " + veyaSonuc); // true

		// "DEGiL" Mantiksal Operatoru (!)
		boolean degilSonuc = !dogru; // dogru degil ise sonuc alindi
		System.out.println("DEGiL Mantiksal Operatori (!): " + degilSonuc); // false

		// Karmasik mantiksal ifadeler
		boolean karmaSonuc = (dogru && yanlis) || (dogru || !yanlis); // karmasik mantiksal ifade
		System.out.println("Karmasik Mantiksal ifade: " + karmaSonuc); // true
	}
}

package com.thealgorithms.conversions;

import java.util.Map;

/**
 * A utility class to convert integers to their English word representation.
 *
 * <p>The class supports conversion of numbers from 0 to 2,147,483,647
 * (the maximum value of a 32-bit signed integer). It divides the number
 * into groups of three digits (thousands, millions, billions, etc.) and
 * translates each group into words.</p>
 *
 * <h2>Example Usage</h2>
 * <pre>
 *   IntegerToEnglish.integerToEnglishWords(12345);
 *   // Output: "Twelve Thousand Three Hundred Forty Five"
 * </pre>
 *
 * <p>This class uses two maps:</p>
 * <ul>
 *   <li>BASE_NUMBERS_MAP: Holds English words for numbers 0-20, multiples of 10 up to 90, and 100.</li>
 *   <li>THOUSAND_POWER_MAP: Maps powers of 1000 (e.g., Thousand, Million, Billion).</li>
 * </ul>
 */
public final class IntegerToEnglish {

private static final Map<Integer, String> BASIC_NUMBERS = Map.ofEntries(
Map.entry(0, ""), Map.entry(1, "One"), Map.entry(2, "Two"), Map.entry(3, "Three"),
Map.entry(4, "Four"), Map.entry(5, "Five"), Map.entry(6, "Six"), Map.entry(7, "Seven"),
Map.entry(8, "Eight"), Map.entry(9, "Nine"), Map.entry(10, "Ten"), Map.entry(11, "Eleven"),
Map.entry(12, "Twelve"), Map.entry(13, "Thirteen"), Map.entry(14, "Fourteen"),
Map.entry(15, "Fifteen"), Map.entry(16, "Sixteen"), Map.entry(17, "Seventeen"),
Map.entry(18, "Eighteen"), Map.entry(19, "Nineteen"), Map.entry(20, "Twenty"),
Map.entry(30, "Thirty"), Map.entry(40, "Forty"), Map.entry(50, "Fifty"),
Map.entry(60, "Sixty"), Map.entry(70, "Seventy"), Map.entry(80, "Eighty"),
Map.entry(90, "Ninety"), Map.entry(100, "Hundred")
);

private static final Map<Integer, String> THOUSAND_GROUPS = Map.of(
1, "Thousand", 2, "Million", 3, "Billion"
);

private IntegerToEnglish() {
}

/**
 * Converts numbers less than 1000 into English words.
 *
 * @param numericValue the integer value (0-999) to convert
 * @return the English word representation of the input number
 */
private static String convertGroupToWords(int numericValue) {
int remainderPart = numericValue % 100;
StringBuilder wordBuilder = new StringBuilder();
if (remainderPart <= 20) {
wordBuilder.append(BASIC_NUMBERS.get(remainderPart));
} else if (BASIC_NUMBERS.containsKey(remainderPart)) {
wordBuilder.append(BASIC_NUMBERS.get(remainderPart));
} else {
int tensValue = remainderPart / 10;
int unitsValue = remainderPart % 10;
String tensSegment = BASIC_NUMBERS.getOrDefault(tensValue * 10, "");
String unitsSegment = BASIC_NUMBERS.getOrDefault(unitsValue, "");
wordBuilder.append(tensSegment);
if (!unitsSegment.isEmpty()) {
wordBuilder.append(" ").append(unitsSegment);
}
}
int hundredsPart = numericValue / 100;
if (hundredsPart > 0) {
if (wordBuilder.length() > 0) {
wordBuilder.insert(0, " ");
}
wordBuilder.insert(0, String.format("%s Hundred", BASIC_NUMBERS.get(hundredsPart)));
}
return wordBuilder.toString().trim();
}

/**
 * Converts a non-negative integer to its English word representation.
 *
 * @param sourceNumber the integer to convert (0-2,147,483,647)
 * @return the English word representation of the input number
 */
public static String integerToEnglishWords(int sourceNumber) {
if (sourceNumber == 0) {
return "Zero";
}
StringBuilder finalResult = new StringBuilder();
int groupIndex = 0;
int remainingValue = sourceNumber;
while (remainingValue > 0) {
int currentGroup = remainingValue % 1000;
remainingValue /= 1000;
if (currentGroup > 0) {
String groupText = convertGroupToWords(currentGroup);
if (!groupText.isEmpty()) {
if (groupIndex > 0) {
groupText += " " + THOUSAND_GROUPS.get(groupIndex);
}
if (finalResult.length() > 0) {
finalResult.insert(0, " ");
}
finalResult.insert(0, groupText);
}
}
groupIndex++;
}
return finalResult.toString().trim();
}
}

/**
 * An implementation of the Run-Length Encoding (RLE) algorithm.
 *
 * <p>Run-Length Encoding is a simple form of lossless data compression in which
 * runs of data (sequences in which the same data value occurs in many
 * consecutive data elements) are stored as a single data value and count,
 * rather than as the original run.
 *
 * <p>This implementation provides methods for both compressing and decompressing
 * a string. For example:
 * <ul>
 * <li>Compressing "AAAABBBCCDAA" results in "4A3B2C1D2A".</li>
 * <li>Decompressing "4A3B2C1D2A" results in "AAAABBBCCDAA".</li>
 * </ul>
 *
 * <p>Time Complexity: O(n) for both compression and decompression, where n is the
 * length of the input string.
 *
 * <p>References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Run-length_encoding">Wikipedia: Run-length encoding</a></li>
 * </ul>
 */
public final class RunLengthEncoding {

    /**
     * Private constructor to prevent instantiation of this utility class.
     */
    private RunLengthEncoding() {
    }

    /**
     * Compresses a string using the Run-Length Encoding algorithm.
     *
     * @param text The string to be compressed. Must not be null.
     * @return The compressed string. Returns an empty string if the input is empty.
     */
    public static String compress(String text) {
        if (text == null || text.isEmpty()) {
            return "";
        }

        StringBuilder compressed = new StringBuilder();
        int count = 1;

        for (int i = 0; i < text.length(); i++) {
            // Check if it's the last character or if the next character is different
            if (i == text.length() - 1 || text.charAt(i) != text.charAt(i + 1)) {
                compressed.append(count);
                compressed.append(text.charAt(i));
                count = 1; // Reset count for the new character
            } else {
                count++;
            }
        }
        return compressed.toString();
    }

    /**
     * Decompresses a string that was compressed using the Run-Length Encoding algorithm.
     *
     * @param compressedText The compressed string. Must not be null.
     * @return The original, uncompressed string.
     */
    public static String decompress(String compressedText) {
        if (compressedText == null || compressedText.isEmpty()) {
            return "";
        }

        StringBuilder decompressed = new StringBuilder();
        int count = 0;

        for (char ch : compressedText.toCharArray()) {
            if (Character.isDigit(ch)) {
                // Build the number for runs of 10 or more (e.g., "12A")
                count = count * 10 + ch - '0';
            } else {
                // Append the character 'count' times
                decompressed.append(String.valueOf(ch).repeat(Math.max(0, count)));
                count = 0; // Reset count for the next sequence
            }
        }
        return decompressed.toString();
    }
}

