package objects;

public class Dikdortgen {

	private double uzunluk;      // Dikdortgenin uzunluk ozelligi
	private double genislik;     // Dikdortgenin genislik ozelligi

	// Yapici metot: Dikdortgen nesnesini baslatir ve uzunluk ve genislik ozelliklerini ayarlar
	public Dikdortgen(double uzunluk, double genislik) {
		this.uzunluk = uzunluk;
		this.genislik = genislik;
	}

	// Alan hesaplama metodu
	public double alanHesapla() {
		return uzunluk * genislik;
	}

	// cevre hesaplama metodu
	public double cevreHesapla() {
		return 2 * (uzunluk + genislik);
	}

	// Alani guncelleyen metot
	public void alanGuncelle(double yeniUzunluk, double yeniGenislik) {
		this.uzunluk = yeniUzunluk;
		this.genislik = yeniGenislik;
	}

	// Nesnenin tum bilgilerini donduren metot
	public String toString() {
		return "Uzunluk: " + uzunluk + ", Genislik: " + genislik + ", Alan: " + alanHesapla() + ", Cevre: " + cevreHesapla();
	}

	// Ana metod (main method) icinde kullanimi
	public static void main(String[] args) {

		// Farkli dikdortgenler olusturuluyor
		Dikdortgen dikdortgen1 = new Dikdortgen(10.0, 5.0); // Dikdortgen nesnesi
		Dikdortgen dikdortgen2 = new Dikdortgen(3.0, 7.0); // Diger dikdortgen nesnesi
		Dikdortgen kare = new Dikdortgen(4.0, 4.0); // Bir kare olusturuluyor (uzunluk = genislik)

		// Alan ve cevre hesaplaniyor
		System.out.println("Dikdortgen 1: " + dikdortgen1);  // toString() ile gosterim
		System.out.println("Dikdortgen 2: " + dikdortgen2);
		System.out.println("Kare: " + kare);

		// Dikdortgenin boyutlari guncelleniyor
		dikdortgen1.alanGuncelle(12.0, 6.0);  // Boyutlar guncelleniyor
		System.out.println("Guncellenmis Dikdortgen 1: " + dikdortgen1); // Yeni boyutlari gosteriyoruz

		// Alan ve cevreye ek olarak bazi ozel hesaplamalar yapilabilir
		double diagonal1 = dikdortgen1.hipotenusHesapla();  // Hipotenus (diagonal) hesaplaniyor
		double diagonal2 = dikdortgen2.hipotenusHesapla();
		double diagonalKare = kare.hipotenusHesapla();

		System.out.println("Dikdortgen 1'in Hipotenusu: " + diagonal1);
		System.out.println("Dikdortgen 2'nin Hipotenusu: " + diagonal2);
		System.out.println("Karenin Hipotenusu: " + diagonalKare);

		// Dikdortgenlerin karsilastirilmasi
		if (dikdortgen1.alanHesapla() > dikdortgen2.alanHesapla()) {
			System.out.println("Dikdortgen 1'in alani, Dikdortgen 2'den buyuktur.");
		} else if (dikdortgen1.alanHesapla() < dikdortgen2.alanHesapla()) {
			System.out.println("Dikdortgen 2'nin alani, Dikdortgen 1'den buyuktur.");
		} else {
			System.out.println("Dikdortgen 1 ve Dikdortgen 2'nin alanlari esittir.");
		}
	}

	// Hipotenus hesaplama (dikdortgenin capraz uzunlugu)
	public double hipotenusHesapla() {
		return Math.sqrt(Math.pow(uzunluk, 2) + Math.pow(genislik, 2));  // Pisagor teoremi kullanilarak hipotenus hesaplanir
	}
}

public class Faktoriyel {

    // 'faktoriyelAl' metodu, verilen sayinin faktoriyelini hesaplar
    int faktoriyelAl(int sayi) {
        int sonuc = 1;  // Faktoriyel sonucunu tutacak degisken, baslangicta 1 olmali
        // Sayi 0'dan buyuk oldugu surece dongu devam eder
        while(sayi > 0) {
            // Sonuc degiskenini her adimda sayi ile carp
            sonuc *= sayi;
            // Sayi her seferinde 1 azaltilir
            sayi--;
        }
        // Faktoriyel hesaplandiktan sonra sonuc dondurulur
        return sonuc;
    }

    public static void main(String[] args) {

        // Kullanicidan girdi almak icin Scanner nesnesi olustur
        Scanner okuyucu = new Scanner(System.in);

        // Kullanicidan bir sayi girmesini iste
        System.out.println("Lutfen bir sayi giriniz");
        int sayi = okuyucu.nextInt();  // Kullanicinin girdigi sayiyi al

        // Faktoriyel sinifindan bir nesne olustur
        Faktoriyel bulucu = new Faktoriyel();

        // 'faktoriyelAl' metodunu cagirarak sayinin faktoriyelini hesapla
        int sonuc = bulucu.faktoriyelAl(sayi);

        // Hesaplanan faktoriyel sonucunu ekrana yazdir
        System.out.println("Sonuc = " + sonuc);

        // Scanner nesnesini kapat
        okuyucu.close();
    }
}

package com.thealgorithms.bitmanipulation;

/**
 * This class contains a method to check if the binary representation of a number is a palindrome.
 * <p>
 *     A binary palindrome is a number whose binary representation is the same when read from left to right and right to left.
 *     For example, the number 9 has a binary representation of 1001, which is a palindrome.
 *     The number 10 has a binary representation of 1010, which is not a palindrome.
 * </p>
 *
 * @author Hardvan
 * @see <a href="https://en.wikipedia.org/wiki/Binary_palindrome">Binary Palindrome (Wikipedia)</a>
 */
public final class BinaryPalindromeCheck {

    // Private constructor to prevent instantiation (utility class)
    private BinaryPalindromeCheck() {
        throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
    }

    /**
     * Checks if the binary representation of a number is a palindrome.
     * 
     * <p>A binary palindrome reads the same forwards and backwards when
     * written in base-2 (binary) format without leading zeros.</p>
     * 
     * <p><b>Examples:</b></p>
     * <ul>
     *   <li>9 (1001) → true</li>
     *   <li>5 (101) → true</li>
     *   <li>10 (1010) → false</li>
     *   <li>0 (0) → true (by convention)</li>
     *   <li>1 (1) → true</li>
     * </ul>
     *
     * @param number The number to check (can be any non-negative integer)
     * @return {@code true} if the binary representation is a palindrome, {@code false} otherwise
     */
    public static boolean isBinaryPalindrome(int number) {
        // Handle edge case: 0 is considered a palindrome (binary representation "0")
        if (number < 0) {
            return false; // Negative numbers have a '-' sign, not considered binary palindromes
        }

        // Special case: single bit numbers are always palindromes
        if (number == 0 || number == 1) {
            return true;
        }

        int reversedBits = reverseBitsPreservingLength(number);
        return number == reversedBits;
    }

    /**
     * Alternative implementation that checks binary palindrome without reversing all bits.
     * This method uses two-pointer technique on the binary representation.
     * More efficient as it stops early when a mismatch is found.
     *
     * @param number The number to check
     * @return {@code true} if the binary representation is a palindrome, {@code false} otherwise
     */
    public static boolean isBinaryPalindromeTwoPointer(int number) {
        if (number < 0) {
            return false;
        }

        if (number == 0 || number == 1) {
            return true;
        }

        // Find the most significant bit position
        int mostSignificantBit = Integer.highestOneBit(number);

        int leftBitMask = mostSignificantBit;
        int rightBitMask = 1;

        // Compare bits from both ends moving toward the center
        while (leftBitMask > rightBitMask) {
            int leftBit = (number & leftBitMask) == 0 ? 0 : 1;
            int rightBit = (number & rightBitMask) == 0 ? 0 : 1;

            if (leftBit != rightBit) {
                return false;
            }

            leftBitMask >>= 1;
            rightBitMask <<= 1;
        }

        return true;
    }

    /**
     * Helper function to reverse all the bits of an integer while preserving the original bit length.
     * 
     * <p><b>Example:</b>
     * <br>Input: 13 (binary: 1101)
     * <br>Output: 11 (binary: 1011)</p>
     *
     * @param number The number to reverse the bits of
     * @return The number with bits reversed (leading zeros are not preserved)
     */
    private static int reverseBitsPreservingLength(int number) {
        int reversedResult = 0;

        // Count the number of bits to preserve (excluding leading zeros)
        int tempNumber = number;
        int bitCount = 0;
        while (tempNumber > 0) {
            bitCount++;
            tempNumber >>= 1;
        }

        // Reverse the bits
        tempNumber = number;
        for (int bitIndex = 0; bitIndex < bitCount; bitIndex++) {
            reversedResult <<= 1;
            reversedResult |= (tempNumber & 1);
            tempNumber >>= 1;
        }

        return reversedResult;
    }

    /**
     * Returns the binary representation of a number as a string.
     * Useful for debugging and visualization.
     *
     * @param number The number to convert
     * @return Binary string without leading zeros
     */
    public static String getBinaryString(int number) {
        if (number < 0) {
            return Integer.toBinaryString(number); // Shows 32-bit representation for negatives
        }
        if (number == 0) {
            return "0";
        }
        return Integer.toBinaryString(number);
    }

    /**
     * Checks if a binary string is a palindrome (utility method).
     *
     * @param binaryString The binary string to check
     * @return {@code true} if the string is a palindrome, {@code false} otherwise
     */
    public static boolean isBinaryStringPalindrome(String binaryString) {
        if (binaryString == null || binaryString.isEmpty()) {
            return false;
        }

        int leftIndex = 0;
        int rightIndex = binaryString.length() - 1;

        while (leftIndex < rightIndex) {
            if (binaryString.charAt(leftIndex) != binaryString.charAt(rightIndex)) {
                return false;
            }
            leftIndex++;
            rightIndex--;
        }
        return true;
    }
}

