/*
 * byte turu, -128 ile 127 araligindaki tam sayilari tutabilen en kucuk
 * sayisal veri turudur. Asagida bu turun sinir degerleri, temel
 * aritmetik islemleri ve bit duzeyinde islemleri gosterilmektedir.
 */

public class ByteVeriTuruOrnegi {

    public static void main(String[] args) {

        // Byte turunun alabilecegi en kucuk ve en buyuk degerler
        byte enKucuk = Byte.MIN_VALUE;
        byte enBuyuk = Byte.MAX_VALUE;

        System.out.println("Byte veri turunun en kucuk degeri: " + enKucuk);
        System.out.println("Byte veri turunun en buyuk degeri: " + enBuyuk);

        byte ilk = 80;
        byte ikinci = 50;

        // Dort islem sonucu byte sinirlarini asabilecegi icin cast gerekiyor
        byte toplamSonuc = (byte) (ilk + ikinci);
        System.out.println("Toplam: " + toplamSonuc);

        byte farkSonuc = (byte) (ilk - ikinci);
        System.out.println("Fark: " + farkSonuc);

        byte carpimSonuc = (byte) (ilk * ikinci);
        System.out.println("Carpim: " + carpimSonuc);

        byte bolumSonuc = (byte) (ilk / ikinci);
        System.out.println("Bolum: " + bolumSonuc);

        byte kalanSonuc = (byte) (ilk % ikinci);
        System.out.println("Kalan: " + kalanSonuc);

        // Ust sinira esitlik kontrolu
        byte esikDeger = 127;
        System.out.println("Sinir Kontrol: " + esikDeger);
        boolean sinirdaMi = (esikDeger == Byte.MAX_VALUE);
        System.out.println(sinirdaMi ? "Sinirda bir deger var." : "Sinirda degil.");

        // Bit duzeyinde islemler (AND, OR, XOR, NOT)
        byte bitA = 5;  // 00000101
        byte bitB = 3;  // 00000011

        byte veSonucu = (byte) (bitA & bitB);
        System.out.println("AND islemi sonucu: " + veSonucu);

        byte veyaSonucu = (byte) (bitA | bitB);
        System.out.println("OR islemi sonucu: " + veyaSonucu);

        byte xorSonucu = (byte) (bitA ^ bitB);
        System.out.println("XOR islemi sonucu: " + xorSonucu);

        byte tersSonucu = (byte) (~bitA);
        System.out.println("NOT islemi sonucu: " + tersSonucu);
    }
}

/**
 * Reads lines from the console, sends each one to the uppercasing
 * server, and prints back whatever the server replies with.
 */
public class CapitalizeClient {

    private static final String HOST = "localhost";
    private static final int PORT = 59898;

    public static void main(String[] args) throws Exception {

        try (var connection = new Socket(HOST, PORT)) {

            System.out.println("Metin satirlarini girin, cikis yapmak icin Ctrl+D veya Ctrl+C kullanin");

            try (var keyboard = new Scanner(System.in)) {
                var fromServer = new Scanner(connection.getInputStream());
                var toServer = new PrintWriter(connection.getOutputStream(), true);

                while (keyboard.hasNextLine()) {
                    toServer.println(keyboard.nextLine());
                    System.out.println(fromServer.nextLine());
                }
            }
        }
    }
}

