    public String toString() {
        return code +", "+name+", "+mark;
    }

    @Override
    public int compareTo(Student t) {
        return -(this.getMark() - t.getMark());
    }   
}

// Swing/AWT tabanli serbest el cizim uygulamasi
import java.awt.BorderLayout;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.awt.Graphics;

import java.util.ArrayList;
import java.util.List;

import javax.swing.SwingUtilities;
import javax.swing.WindowConstants;
import javax.swing.JFrame;
import javax.swing.JPanel;

/** Fare ile serbest cizim yapilabilen minimal bir panel bileseni. */
public class BasitCizimPaneli extends JPanel {
    private static final long serialVersionUID = -3630443364990545965L;

    // Her biri bir surukleme hareketine karsilik gelen nokta dizileri
    private final List<List<Point>> cizimKatmanlari = new ArrayList<>();

    public BasitCizimPaneli() {
        addMouseMotionListener(new MouseMotionAdapter() {
            @Override
            public void mouseDragged(MouseEvent olay) {
                // Aktif cizginin son parcasina yeni nokta ekle
                sonCizgi().add(new Point(olay.getX(), olay.getY()));
                repaint(0, 0, getWidth(), getHeight());
            }
        });

        addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent olay) {
                // Fareye basildiginda yeni bir cizgi baslat
                List<Point> yeniCizgi = new ArrayList<>();
                yeniCizgi.add(new Point(olay.getX(), olay.getY()));
                cizimKatmanlari.add(yeniCizgi);
            }
        });
    }

    private List<Point> sonCizgi() {
        return cizimKatmanlari.get(cizimKatmanlari.size() - 1);
    }

    @Override
    public void paintComponent(Graphics tuval) {
        super.paintComponent(tuval);
        for (List<Point> cizgi : cizimKatmanlari) {
            noktalariBirlestirerekCiz(tuval, cizgi);
        }
    }

    private void noktalariBirlestirerekCiz(Graphics tuval, List<Point> noktalar) {
        Point onceki = noktalar.get(0);
        for (Point simdiki : noktalar) {
            tuval.drawLine(onceki.x, onceki.y, simdiki.x, simdiki.y);
            onceki = simdiki;
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame pencere = new JFrame("Basit Cizim Programi");
            pencere.getContentPane().add(new BasitCizimPaneli(), BorderLayout.CENTER);
            pencere.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
            pencere.setSize(400, 300);
            pencere.setVisible(true);
        });
    }
}

public class SayiFormatiHatasi {

    public static void main(String[] args) {

        // Giris argumanlarini simule eden bir dizi tanimlandi
        String[] girisDizisi = {"10.1", "0"}; // Burada farkli degerlerle denenebilir

        try {
            // Diziden degerleri al ve tamsayi olarak ayristir
            int x = Integer.parseInt(girisDizisi[0]);
            int y = Integer.parseInt(girisDizisi[1]);

            // Iki sayiyi bol ve sonucu yazdir
            int z = x / y;
            System.out.println("Sonuc: " + z);

        } catch (NumberFormatException e) {
            // Eger girilen veri tamsayi degilse bu istisna firlatilir
            System.out.println("Gecersiz giris: Lutfen sadece tamsayi giriniz.");
            System.out.println("Istisna mesaji: " + e.getMessage());
            e.printStackTrace(); // Istisna izini yazdir

        } catch (ArithmeticException e) {
            // Eger bolme islemi sifira bolme icermisse bu istisna firlatilir
            System.out.println("Sifira bolme hatasi olustu!");
            System.out.println("Istisna mesaji: " + e.getMessage());
            e.printStackTrace(); // Istisna izini yazdir

        } catch (ArrayIndexOutOfBoundsException e) {
            // Eger dizi eksikse bu istisna firlatilir
            System.out.println("Eksik giris: Lutfen iki sayi giriniz.");
            System.out.println("Istisna mesaji: " + e.getMessage());
            e.printStackTrace(); // Istisna izini yazdir

        } finally {
            // Bu blok her zaman calisir
            System.out.println("Finally bloguna girildi!");
        }

        // Ek bir ornek: Istisna firlatmayan normal bir akisi test et
        try {
            basariliAkisTesti();
        } catch (Exception e) {
            System.out.println("Beklenmeyen bir hata: " + e.getMessage());
        }
    }

    /**
     * Basarili bir akis senaryosunu test eder.
     */
    public static void basariliAkisTesti() {
        System.out.println("Basarili akis testi calisiyor.");
        int a = 10;
        int b = 5;
        int sonuc = a / b;
        System.out.println("10 / 5 = " + sonuc);
        System.out.println("Her sey yolunda, istisna firlatilmadi!");
    }
}

/**
 * Walks a directory tree and strips Turkish-specific accented letters
 * out of every ".java" source file it finds (except files starting
 * with "Turkce"), replacing them with their plain ASCII equivalents.
 */
public class TurkceKarakterDegistirici {

    private static final Map<String, String> DEGISIM_TABLOSU = new LinkedHashMap<>();
    static {
        DEGISIM_TABLOSU.put("ü", "u");
        DEGISIM_TABLOSU.put("Ü", "U");
        DEGISIM_TABLOSU.put("ğ", "g");
        DEGISIM_TABLOSU.put("Ğ", "G");
        DEGISIM_TABLOSU.put("ı", "i");
        DEGISIM_TABLOSU.put("İ", "I");
        DEGISIM_TABLOSU.put("ş", "s");
        DEGISIM_TABLOSU.put("Ş", "S");
        DEGISIM_TABLOSU.put("ç", "c");
        DEGISIM_TABLOSU.put("Ç", "C");
        DEGISIM_TABLOSU.put("ö", "o");
        DEGISIM_TABLOSU.put("Ö", "O");
    }

    /** Belirtilen klasoru ve tum alt klasorlerini gezerek uygun dosyalari isler. */
    public static void agaciGez(File baslangicNoktasi) {
        File[] icerik = baslangicNoktasi.listFiles();
        if (icerik == null) {
            return;
        }

        for (File oge : icerik) {
            if (oge.isDirectory()) {
                agaciGez(oge);
            } else if (isleneceklerdenMi(oge)) {
                dosyayiTemizle(oge);
            }
        }
    }

    private static boolean isleneceklerdenMi(File oge) {
        return oge.isFile()
                && oge.getName().endsWith(".java")
                && !oge.getName().startsWith("Turkce");
    }

    /** Bir Java dosyasindaki Turkce karakterleri ayiklayip degisiklikleri diske yansitir. */
    private static void dosyayiTemizle(File hedefDosya) {
        try {
            List<String> satirlar = Files.readAllLines(hedefDosya.toPath(), StandardCharsets.UTF_8);
            boolean herhangiBirSatirDegisti = false;

            for (int satirIndex = 0; satirIndex < satirlar.size(); satirIndex++) {
                String eski = satirlar.get(satirIndex);
                String yeni = karakterleriCevir(eski);

                if (!eski.equals(yeni)) {
                    satirlar.set(satirIndex, yeni);
                    System.out.println("Dosya: " + hedefDosya.getAbsolutePath()
                            + " - Satir " + (satirIndex + 1) + " degistirildi.");
                    herhangiBirSatirDegisti = true;
                }
            }

            if (herhangiBirSatirDegisti) {
                Files.write(hedefDosya.toPath(), satirlar, StandardCharsets.UTF_8);
            }
        } catch (IOException hata) {
            System.out.println("Hata: " + hata.getMessage());
        }
    }

    private static String karakterleriCevir(String satir) {
        String sonuc = satir;
        for (Map.Entry<String, String> kural : DEGISIM_TABLOSU.entrySet()) {
            sonuc = sonuc.replace(kural.getKey(), kural.getValue());
        }
        return sonuc;
    }

    public static void main(String[] args) {
        File ustDizin = new File(System.getProperty("user.dir")).getParentFile();
        agaciGez(ustDizin);
    }
}

