/**
 * The {@code LFUCache} class implements a Least Frequently Used (LFU) cache.
 * An LFU cache evicts the least frequently used item when the cache reaches its capacity.
 * It maintains a mapping of keys to nodes, where each node contains the key, its associated value,
 * and a frequency count that tracks how many times the item has been accessed. A doubly linked list
 * is used to efficiently manage the ordering of items based on their usage frequency.
 *
 * <p>This implementation is designed to provide O(1) time complexity for both the {@code get} and
 * {@code put} operations, which is achieved through the use of a hashmap for quick access and a
 * doubly linked list for maintaining the order of item frequencies.</p>
 *
 * <p>
 * Reference: <a href="https://en.wikipedia.org/wiki/Least_frequently_used">LFU Cache - Wikipedia</a>
 * </p>
 *
 * @param <KeyType> The type of keys maintained by this cache.
 * @param <ValueType> The type of mapped values.
 *
 * @author Akshay Dubey (https://github.com/itsAkshayDubey)
 */
public class LFUCache<KeyType, ValueType> {

/**
 * The {@code CacheNode} class represents an element in the LFU cache.
 * Each node contains a key, a value, and a frequency count.
 * It also has pointers to the previous and next nodes in the doubly linked list.
 */
private class CacheNode {
private final KeyType nodeKey;
private ValueType nodeValue;
private int accessFrequency;
private CacheNode prevNode;
private CacheNode nextNode;

/**
 * Constructs a new {@code CacheNode} with the specified key, value, and frequency.
 *
 * @param inputKey The key associated with this node.
 * @param inputValue The value stored in this node.
 * @param initialFrequency The frequency of usage of this node.
 */
CacheNode(KeyType inputKey, ValueType inputValue, int initialFrequency) {
this.nodeKey = inputKey;
this.nodeValue = inputValue;
this.accessFrequency = initialFrequency;
}
}

private CacheNode headNode;
private CacheNode tailNode;
private final Map<KeyType, CacheNode> storageMap;
private final int maxCapacity;
private static final int DEFAULT_CAPACITY = 100;

/**
 * Constructs an LFU cache with the default capacity.
 */
public LFUCache() {
this(DEFAULT_CAPACITY);
}

/**
 * Constructs an LFU cache with the specified capacity.
 *
 * @param storageCapacity The maximum number of items that the cache can hold.
 * @throws IllegalArgumentException if the specified capacity is less than or equal to zero.
 */
public LFUCache(int storageCapacity) {
if (storageCapacity <= 0) {
throw new IllegalArgumentException("Capacity must be greater than zero.");
}
this.maxCapacity = storageCapacity;
this.storageMap = new HashMap<>();
}

/**
 * Retrieves the value associated with the given key from the cache.
 * If the key exists, the node's frequency is incremented, and the node is repositioned
 * in the linked list based on its updated frequency.
 *
 * @param searchKey The key whose associated value is to be returned.
 * @return The value associated with the key, or {@code null} if the key is not present in the cache.
 */
public ValueType get(KeyType searchKey) {
CacheNode targetNode = storageMap.get(searchKey);
if (targetNode == null) {
return null;
}
removeNodeFromList(targetNode);
targetNode.accessFrequency += 1;
insertNodeByFrequency(targetNode);
return targetNode.nodeValue;
}

/**
 * Inserts or updates a key-value pair in the cache.
 * If the key already exists, the value is updated and its frequency is incremented.
 * If the cache is full, the least frequently used item is removed before inserting the new item.
 *
 * @param insertKey The key associated with the value to be inserted or updated.
 * @param insertValue The value to be inserted or updated.
 */
public void put(KeyType insertKey, ValueType insertValue) {
if (storageMap.containsKey(insertKey)) {
CacheNode existingNode = storageMap.get(insertKey);
existingNode.nodeValue = insertValue;
existingNode.accessFrequency += 1;
removeNodeFromList(existingNode);
insertNodeByFrequency(existingNode);
} else {
if (storageMap.size() >= maxCapacity) {
storageMap.remove(this.headNode.nodeKey);
removeNodeFromList(headNode);
}
CacheNode newNode = new CacheNode(insertKey, insertValue, 1);
insertNodeByFrequency(newNode);
storageMap.put(insertKey, newNode);
}
}

/**
 * Adds a node to the linked list in the correct position based on its frequency.
 * The linked list is ordered by frequency, with the least frequently used node at the head.
 *
 * @param targetNode The node to be inserted into the list.
 */
private void insertNodeByFrequency(CacheNode targetNode) {
if (tailNode != null && headNode != null) {
CacheNode currentPointer = this.headNode;
while (true) {
if (currentPointer.accessFrequency > targetNode.accessFrequency) {
if (currentPointer == headNode) {
targetNode.nextNode = currentPointer;
currentPointer.prevNode = targetNode;
this.headNode = targetNode;
break;
} else {
targetNode.nextNode = currentPointer;
targetNode.prevNode = currentPointer.prevNode;
currentPointer.prevNode.nextNode = targetNode;
currentPointer.prevNode = targetNode;
break;
}
} else {
currentPointer = currentPointer.nextNode;
if (currentPointer == null) {
tailNode.nextNode = targetNode;
targetNode.prevNode = tailNode;
targetNode.nextNode = null;
tailNode = targetNode;
break;
}
}
}
} else {
tailNode = targetNode;
headNode = tailNode;
}
}

/**
 * Removes a node from the doubly linked list.
 * This method ensures that the pointers of neighboring nodes are properly updated.
 *
 * @param targetNode The node to be removed from the list.
 */
private void removeNodeFromList(CacheNode targetNode) {
if (targetNode.prevNode != null) {
targetNode.prevNode.nextNode = targetNode.nextNode;
} else {
this.headNode = targetNode.nextNode;
}
if (targetNode.nextNode != null) {
targetNode.nextNode.prevNode = targetNode.prevNode;
} else {
this.tailNode = targetNode.prevNode;
}
}
}

package com.thealgorithms.conversions;

public final class BinaryToOctal {
private static final int BITS_PER_GROUP = 3;
private static final int BINARY_RADIX = 2;
private static final int DECIMAL_RADIX = 10;

private BinaryToOctal() {
}

/**
 * This method converts a binary number to an octal number.
 *
 * @param binaryInput The binary number
 * @return The octal number
 * @throws IllegalArgumentException if the input is not a valid binary number
 */
public static String convertBinaryToOctal(int binaryInput) {
if (binaryInput == 0) {
return "0";
}
if (!String.valueOf(binaryInput).matches("[01]+")) {
throw new IllegalArgumentException("Input is not a valid binary number.");
}
StringBuilder octalResult = new StringBuilder();
int remainingValue = binaryInput;
int powerMultiplier = 1;
while (remainingValue != 0) {
int octalDigit = 0;
for (int bitPos = 0; bitPos < BITS_PER_GROUP && remainingValue != 0; bitPos++) {
int currentBit = remainingValue % DECIMAL_RADIX;
remainingValue /= DECIMAL_RADIX;
octalDigit += currentBit * powerMultiplier;
powerMultiplier *= BINARY_RADIX;
}
octalResult.insert(0, octalDigit);
powerMultiplier = 1;
}
return octalResult.toString();
}
}

public class ContinueOrnegi {

    // Tek ve cift sayilari ayiran ornek
    public static void tekVeCiftSayilar() {
        System.out.println("Tek ve Cift Sayilar Ornegi:");
        for (int i = 1; i <= 10; i++) {
            if (i % 2 == 0) { // Cift sayilar kontrol edilir
                System.out.println("Cift sayi: " + i);
                continue; // Cift sayilar icin kalan kod atlanir
            }
            System.out.println("Tek sayi: " + i);
        }
    }

    // 3 ve 5'in katlarini atlayan ornek
    public static void ucVeBesKatlari() {
        System.out.println("\n3 ve 5'in Katlarini Atlayan Ornek:");
        for (int i = 1; i <= 15; i++) {
            if (i % 3 == 0 || i % 5 == 0) { // 3 veya 5'in kati kontrol edilir
                System.out.println("Atlanan sayi: " + i);
                continue; // 3 veya 5'in katlari icin kalan kod atlanir
            }
            System.out.println("Gecerli sayi: " + i);
        }
    }

    // Ic ice dongulerde continue kullanimi
    public static void icIceDonguler() {
        System.out.println("\nIc Ice Dongulerde Continue Ornegi:");
        for (int i = 1; i <= 3; i++) {
            for (int j = 1; j <= 3; j++) {
                if (i == j) { // i ve j esit oldugunda atlanir
                    System.out.println("i: " + i + ", j: " + j + " -> Continue uygulandi");
                    continue; // Bu sart saglandiginda ic dongu bir sonraki iterasyona gecer
                }
                System.out.println("i: " + i + ", j: " + j);
            }
        }
    }

    public static void main(String[] args) {
        // Tek ve cift sayilarin ayristirildigi ornek
        tekVeCiftSayilar();

        // 3 ve 5'in katlarini atlayan ornek
        ucVeBesKatlari();

        // Ic ice dongulerde continue kullanimi
        icIceDonguler();
    }
}

