/**
 * A menu of string-processing exercises applied to one input string.
 */
public class Number_String {

    public static void menu() {
        System.out.println("1. search words \"me\", \"why\", \"well\"");
        System.out.println("2. \"you\" word appear in @str how many times?");
        System.out.println("3. Replace the first character of each word by its UPPER CASE");
        System.out.println("4. Replace the first character of each word by its LOWER CASE, and the last character of each word by its UPPER CASE");
        System.out.println("5. Extract @str string to an array of words, then display those words by increasing order.");
        System.out.println("6. Give a character named c, remove from @str the first character which is equals to c. ");
        System.out.println("7. Count how many words in @str, display “empty string” if @str is an empty string.");
        System.out.println("8. Print all letters of @str only.");
        System.out.println("9. Reserve @str.");
        System.out.println("10. Replace all letter ‘a’ by ‘A’ and ‘b’ by ‘B’.");
        System.out.println("11. How many upper letters in @str?");
        System.out.println("12. Show menu");
        System.out.println("0. exit");
    }

    public static boolean checkMeWhyWell(String string) {
        String lower = string.toLowerCase();
        return lower.contains("me") && lower.contains("why") && lower.contains("well");
    }

    public static int countWordYou(String string) {
        StringTokenizer tokenizer = new StringTokenizer(string, " ");
        int count = 0;
        while (tokenizer.hasMoreTokens()) {
            if (tokenizer.nextToken().equalsIgnoreCase("you")) {
                count++;
            }
        }
        return count;
    }

    public static String upperFisrtCharWord(String string) {
        StringTokenizer tokenizer = new StringTokenizer(string, " ");
        StringBuilder result = new StringBuilder();
        while (tokenizer.hasMoreTokens()) {
            String word = tokenizer.nextToken();
            result.append(word.substring(0, 1).toUpperCase()).append(word.substring(1).toLowerCase()).append(" ");
        }
        return result.toString().trim();
    }

    public static String upperLastCharWord(String string) {
        StringTokenizer tokenizer = new StringTokenizer(string, " ");
        StringBuilder result = new StringBuilder();
        while (tokenizer.hasMoreTokens()) {
            String word = tokenizer.nextToken();
            result.append(word.substring(0, word.length() - 1).toLowerCase())
                    .append(word.substring(word.length() - 1).toUpperCase())
                    .append(" ");
        }
        return result.toString().trim();
    }

    public static void sortWord(String string) {
        String[] words = string.trim().replaceAll("\\s+", " ").split(" ");
        ArrayList<String> list = new ArrayList<>(Arrays.asList(words));
        Collections.sort(list);
        System.out.println("After string sort word: " + list.toString());
    }

    public static String removeCharString(String string, char c) {
        StringBuilder builder = new StringBuilder(string);
        int index = string.indexOf(c);
        if (index != -1) {
            builder.deleteCharAt(index);
            return builder.toString();
        }
        System.out.println("Can not found character");
        return string;
    }

    public static int countWords(String string) {
        if (string.isEmpty()) {
            System.out.println("Empty String");
            return 0;
        }
        return string.trim().split("\\s+").length;
    }

    public static void showAllLetters(String string) {
        char[] chars = string.replaceAll("[^a-zA-Z]", "").toCharArray();
        ArrayList<Character> seen = new ArrayList<>();
        for (char c : chars) {
            if (!seen.contains(c)) {
                seen.add(c);
            }
        }
        System.out.println("All letters: " + Arrays.toString(seen.toArray()));
    }

    public static String reserveString(String string) {
        return new StringBuilder(string).reverse().toString();
    }

    public static String replaceLetterAandB(String string) {
        return string.replaceAll("a", "A").replaceAll("b", "B");
    }

    public static int countUpperLetter(String string) {
        String[] parts = string.trim().replaceAll("[^A-Z]", " ").replaceAll("\\s+", " ").split(" ");
        return parts.length;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String string = scanner.nextLine();
        menu();
        while (true) {
            System.out.print("Select option: ");
            int choice = scanner.nextInt();
            switch (choice) {
                case 1:
                    System.out.println("String have contains \"me\", \"why\", \"well\"? " + checkMeWhyWell(string));
                    break;
                case 2:
                    System.out.println("Have " + countWordYou(string) + " word \"you\" in string");
                    break;
                case 3:
                    string = upperFisrtCharWord(string);
                    System.out.println("After String: " + string);
                    break;
                case 4:
                    string = upperLastCharWord(string);
                    System.out.println("After String: " + string);
                    break;
                case 5:
                    sortWord(string);
                    break;
                case 6:
                    System.out.print("Enter char: ");
                    char c = scanner.next().charAt(0);
                    string = removeCharString(string, c);
                    System.out.println("After string remove char: " + string);
                    break;
                case 7:
                    int count = countWords(string);
                    if (count > 0) {
                        System.out.println("Words in string: " + count);
                    }
                    break;
                case 8:
                    showAllLetters(string);
                    break;
                case 9:
                    System.out.println("Reserve string: " + reserveString(string));
                    break;
                case 10:
                    string = replaceLetterAandB(string);
                    System.out.println("After string: " + string);
                    break;
                case 11:
                    System.out.println("Have upper letter: " + countUpperLetter(string));
                    break;
                case 12:
                    menu();
                    break;
                case 0:
                    break;
                default:
                    System.out.println("Please enter [0->12]");
                    break;
            }
            if (choice == 0) {
                break;
            }
        }
    }
}

public class BasamakSayisi { // Ana sinif

    public static void main(String[] args) {

        // Kullanicidan bir sayi almak icin Scanner nesnesi olusturur.
        Scanner scanner = new Scanner(System.in);

        // Kullanicidan bir sayi girmesini ister. Bu sayinin basamak sayisi hesaplanir.
        System.out.println("Bir sayi giriniz:");
        int sayi = scanner.nextInt(); // Kullanicinin girdigi sayiyi okur ve 'sayi' degiskenine atar.

        // Basamak sayisini tutmak icin bir degisken tanimlar ve baslangic degerini 0 olarak belirler.
        int basamakSayisi = 0;

        // 'while' dongusu, sayinin basamaklarini saymak icin kullanilir.
        // Dongu, sayi 0'dan buyuk oldugu surece devam eder.
        while(sayi > 0) {

            // Sayinin son basamagi "sayi / 10" islemiyle silinir (ornegin 1234 -> 123).
            sayi = sayi / 10;

            // Her islemde bir basamak silindigi icin 'basamakSayisi' bir artirilir.
            basamakSayisi++;
        }

        // Sayinin kac basamaktan olustugunu ekrana yazdirir.
        System.out.println("Basamak sayisi: " + basamakSayisi);

        // Scanner nesnesini kapatir. Kaynak yonetimi acisindan onemli bir adimdir.
        scanner.close();
    }
}

/**
 * A thread-safe generic cache implementation using the Last-In-First-Out eviction policy.
 * <p>
 * The cache holds a fixed number of entries, defined by its capacity. When the cache is full and a
 * new entry is added, the youngest entry in the cache is selected and evicted to make space.
 * <p>
 * Optionally, entries can have a time-to-live (TTL) in milliseconds. If a TTL is set, entries will
 * automatically expire and be removed upon access or insertion attempts.
 * <p>
 * Features:
 * <ul>
 *     <li>Removes youngest entry when capacity is exceeded</li>
 *     <li>Optional TTL (time-to-live in milliseconds) per entry or default TTL for all entries</li>
 *     <li>Thread-safe access using locking</li>
 *     <li>Hit and miss counters for cache statistics</li>
 *     <li>Eviction listener callback support</li>
 * </ul>
 *
 * @param <KeyType> the type of keys maintained by this cache
 * @param <ValueType> the type of mapped values
 * See <a href="https://en.wikipedia.org/wiki/Cache_replacement_policies#Last_in_first_out_(LIFO)_or_First_in_last_out_(FILO)">LIFO</a>
 * @author Kevin Babu (<a href="https://www.github.com/KevinMwita7">GitHub</a>)
 */
public final class LIFOCache<KeyType, ValueType> {

private final int maxCapacity;
private final long globalTTL;
private final Map<KeyType, TimedValue<ValueType>> storageMap;
private final Lock accessLock;
private final Deque<KeyType> keyStack;
private long hitCount = 0;
private long missCount = 0;
private final BiConsumer<KeyType, ValueType> removalListener;
private final EvictionHandler<KeyType, ValueType> evictionHandler;

/**
 * Internal structure to store value + expiry timestamp.
 *
 * @param <ValueType> the type of the value being cached
 */
private static class TimedValue<ValueType> {
ValueType storedValue;
long expirationTime;

/**
 * Constructs a new {@code TimedValue} with the specified value and time-to-live (TTL).
 * If TTL is 0, the entry is kept indefinitely, that is, unless it is the first value,
 * then it will be removed according to the LIFO principle
 *
 * @param valueData     the value to cache
 * @param ttlMillis the time-to-live in milliseconds
 */
TimedValue(ValueType valueData, long ttlMillis) {
this.storedValue = valueData;
if (ttlMillis == 0) {
this.expirationTime = Long.MAX_VALUE;
} else {
this.expirationTime = System.currentTimeMillis() + ttlMillis;
}
}

/**
 * Checks if the cache entry has expired.
 *
 * @return {@code true} if the current time is past the expiration time; {@code false} otherwise
 */
boolean isExpired() {
return System.currentTimeMillis() > expirationTime;
}
}

/**
 * Constructs a new {@code LIFOCache} instance using the provided {@link Builder}.
 *
 * <p>This constructor initializes the cache with the specified capacity and default TTL,
 * sets up internal data structures (a {@code HashMap} for cache entries,
 * {an @code ArrayDeque}, for key storage, and configures eviction.
 *
 * @param configBuilder the {@code Builder} object containing configuration parameters
 */
private LIFOCache(Builder<KeyType, ValueType> configBuilder) {
this.maxCapacity = configBuilder.maxCapacity;
this.globalTTL = configBuilder.globalTTL;
this.storageMap = new HashMap<>(configBuilder.maxCapacity);
this.keyStack = new ArrayDeque<>(configBuilder.maxCapacity);
this.accessLock = new ReentrantLock();
this.removalListener = configBuilder.removalListener;
this.evictionHandler = configBuilder.evictionHandler;
}

/**
 * Retrieves the value associated with the specified key from the cache.
 *
 * <p>If the key is not present or the corresponding entry has expired, this method
 * returns {@code null}. If an expired entry is found, it will be removed and the
 * eviction listener (if any) will be notified. Cache hit-and-miss statistics are
 * also updated accordingly.
 *
 * @param searchKey the key whose associated value is to be returned; must not be {@code null}
 * @return the cached value associated with the key, or {@code null} if not present or expired
 * @throws IllegalArgumentException if {@code searchKey} is {@code null}
 */
public ValueType get(KeyType searchKey) {
if (searchKey == null) {
throw new IllegalArgumentException("Key must not be null");
}
accessLock.lock();
try {
evictionHandler.onAccess(this);
final TimedValue<ValueType> targetEntry = storageMap.get(searchKey);
if (targetEntry == null || targetEntry.isExpired()) {
if (targetEntry != null) {
storageMap.remove(searchKey);
keyStack.remove(searchKey);
notifyRemoval(searchKey, targetEntry.storedValue);
}
missCount++;
return null;
}
hitCount++;
return targetEntry.storedValue;
} finally {
accessLock.unlock();
}
}

/**
 * Adds a key-value pair to the cache using the default time-to-live (TTL).
 *
 * <p>The key may overwrite an existing entry. The actual insertion is delegated
 * to the overloaded {@link #put(KeyType, ValueType, long)} method.
 *
 * @param insertKey   the key to cache the value under
 * @param insertValue the value to be cached
 */
public void put(KeyType insertKey, ValueType insertValue) {
put(insertKey, insertValue, globalTTL);
}

/**
 * Adds a key-value pair to the cache with a specified time-to-live (TTL).
 *
 * <p>If the key already exists, its value is removed, re-inserted at tail and its TTL is reset.
 * If the key does not exist and the cache is full, the youngest entry is evicted to make space.
 * Expired entries are also cleaned up prior to any eviction. The eviction listener
 * is notified when an entry gets evicted.
 *
 * @param insertKey        the key to associate with the cached value; must not be {@code null}
 * @param insertValue      the value to be cached; must not be {@code null}
 * @param timeToLiveMillis  the time-to-live for this entry in milliseconds; must be >= 0
 * @throws IllegalArgumentException if {@code insertKey} or {@code insertValue} is {@code null}, or if {@code timeToLiveMillis} is negative
 */
public void put(KeyType insertKey, ValueType insertValue, long timeToLiveMillis) {
if (insertKey == null || insertValue == null) {
throw new IllegalArgumentException("Key and value must not be null");
}
if (timeToLiveMillis < 0) {
throw new IllegalArgumentException("TTL must be >= 0");
}
accessLock.lock();
try {
keyStack.remove(insertKey);
final TimedValue<ValueType> existingEntry = storageMap.remove(insertKey);
if (existingEntry != null && !existingEntry.isExpired()) {
notifyRemoval(insertKey, existingEntry.storedValue);
}
removeExpiredEntries();
if (storageMap.size() >= maxCapacity) {
final KeyType youngestKey = keyStack.pollLast();
final TimedValue<ValueType> removedEntry = storageMap.remove(youngestKey);
notifyRemoval(youngestKey, removedEntry.storedValue);
}
keyStack.add(insertKey);
storageMap.put(insertKey, new TimedValue<>(insertValue, timeToLiveMillis));
} finally {
accessLock.unlock();
}
}

/**
 * Removes all expired entries from the cache.
 *
 * <p>This method iterates through the list of cached keys and checks each associated
 * entry for expiration. Expired entries are removed the cache map. For each eviction,
 * the eviction listener is notified.
 */
private int removeExpiredEntries() {
int removedCount = 0;
final Iterator<KeyType> keyIterator = keyStack.iterator();
while (keyIterator.hasNext()) {
final KeyType currentKey = keyIterator.next();
final TimedValue<ValueType> currentEntry = storageMap.get(currentKey);
if (currentEntry != null && currentEntry.isExpired()) {
keyIterator.remove();
storageMap.remove(currentKey);
notifyRemoval(currentKey, currentEntry.storedValue);
removedCount++;
}
}
return removedCount;
}

/**
 * Removes the specified key and its associated entry from the cache.
 *
 * @param targetKey the key to remove from the cache;
 * @return the value associated with the key;  or {@code null} if no such key exists
 */
public ValueType removeKey(KeyType targetKey) {
if (targetKey == null) {
throw new IllegalArgumentException("Key cannot be null");
}
accessLock.lock();
try {
final TimedValue<ValueType> removedEntry = storageMap.remove(targetKey);
keyStack.remove(targetKey);
if (removedEntry == null) {
return null;
}
notifyRemoval(targetKey, removedEntry.storedValue);
return removedEntry.storedValue;
} finally {
accessLock.unlock();
}
}

/**
 * Notifies the eviction listener, if one is registered, that a key-value pair has been evicted.
 *
 * <p>If the {@code removalListener} is not {@code null}, it is invoked with the provided key
 * and value. Any exceptions thrown by the listener are caught and logged to standard error,
 * preventing them from disrupting cache operations.
 *
 * @param evictedKey   the key that was evicted
 * @param evictedValue the value that was associated with the evicted key
 */
private void notifyRemoval(KeyType evictedKey, ValueType evictedValue) {
if (removalListener != null) {
try {
removalListener.accept(evictedKey, evictedValue);
} catch (Exception executionError) {
System.err.println("Eviction listener failed: " + executionError.getMessage());
}
}
}

/**
 * Returns the number of successful cache lookups (hits).
 *
 * @return the number of cache hits
 */
public long getHitCount() {
accessLock.lock();
try {
return hitCount;
} finally {
accessLock.unlock();
}
}

/**
 * Returns the number of failed cache lookups (misses), including expired entries.
 *
 * @return the number of cache misses
 */
public long getMissCount() {
accessLock.lock();
try {
return missCount;
} finally {
accessLock.unlock();
}
}

/**
 * Returns the current number of entries in the cache, excluding expired ones.
 *
 * @return the current cache size
 */
public int getCurrentSize() {
accessLock.lock();
try {
evictionHandler.onAccess(this);
int activeCount = 0;
for (TimedValue<ValueType> entryData : storageMap.values()) {
if (!entryData.isExpired()) {
++activeCount;
}
}
return activeCount;
} finally {
accessLock.unlock();
}
}

/**
 * Removes all entries from the cache, regardless of their expiration status.
 *
 * <p>This method clears the internal cache map entirely, resets the hit-and-miss counters,
 * and notifies the eviction listener (if any) for each removed entry.
 * Note that expired entries are treated the same as active ones for the purpose of clearing.
 *
 * <p>This operation acquires the internal lock to ensure thread safety.
 */
public void clearAll() {
accessLock.lock();
try {
for (Map.Entry<KeyType, TimedValue<ValueType>> entryItem : storageMap.entrySet()) {
notifyRemoval(entryItem.getKey(), entryItem.getValue().storedValue);
}
keyStack.clear();
storageMap.clear();
hitCount = 0;
missCount = 0;
} finally {
accessLock.unlock();
}
}

/**
 * Returns a set of all keys currently stored in the cache that have not expired.
 *
 * <p>This method iterates through the cache and collects the keys of all non-expired entries.
 * Expired entries are ignored but not removed. If you want to ensure expired entries are cleaned up,
 * consider invoking {@link EvictionHandler#onAccess(LIFOCache)} or calling {@link #removeExpiredEntries()} manually.
 *
 * <p>This operation acquires the internal lock to ensure thread safety.
 *
 * @return a set containing all non-expired keys currently in the cache
 */
public Set<KeyType> getAllActiveKeys() {
accessLock.lock();
try {
final Set<KeyType> activeKeys = new HashSet<>();
for (Map.Entry<KeyType, TimedValue<ValueType>> entryItem : storageMap.entrySet()) {
if (!entryItem.getValue().isExpired()) {
activeKeys.add(entryItem.getKey());
}
}
return activeKeys;
} finally {
accessLock.unlock();
}
}

/**
 * Returns the current {@link EvictionHandler} used by this cache instance.

 * @return the eviction strategy currently assigned to this cache
 */
public EvictionHandler<KeyType, ValueType> getEvictionHandler() {
return evictionHandler;
}

/**
 * Returns a string representation of the cache, including metadata and current non-expired entries.
 *
 * <p>The returned string includes the cache's capacity, current size (excluding expired entries),
 * hit-and-miss counts, and a map of all non-expired key-value pairs. This method acquires a lock
 * to ensure thread-safe access.
 *
 * @return a string summarizing the state of the cache
 */
@Override
public String toString() {
accessLock.lock();
try {
final Map<KeyType, ValueType> visibleEntries = new LinkedHashMap<>();
for (Map.Entry<KeyType, TimedValue<ValueType>> entryItem : storageMap.entrySet()) {
if (!entryItem.getValue().isExpired()) {
visibleEntries.put(entryItem.getKey(), entryItem.getValue().storedValue);
}
}
return String.format("Cache(capacity=%d, size=%d, hits=%d, misses=%d, entries=%s)", maxCapacity, visibleEntries.size(), hitCount, missCount, visibleEntries);
} finally {
accessLock.unlock();
}
}

/**
 * A strategy interface for controlling when expired entries are evicted from the cache.
 *
 * <p>Implementations decide whether and when to trigger {@link LIFOCache#removeExpiredEntries()} based
 * on cache usage patterns. This allows for flexible eviction behaviour such as periodic cleanup,
 * or no automatic cleanup.
 *
 * @param <KeyType> the type of keys maintained by the cache
 * @param <ValueType> the type of cached values
 */
public interface EvictionHandler<KeyType, ValueType> {
/**
 * Called on each cache access (e.g., {@link LIFOCache#get(Object)}) to optionally trigger eviction.
 *
 * @param targetCache the cache instance on which this strategy is applied
 * @return the number of expired entries evicted during this access
 */
int onAccess(LIFOCache<KeyType, ValueType> targetCache);
}

/**
 * An eviction strategy that performs eviction of expired entries on each call.
 *
 * @param <KeyType> the type of keys
 * @param <ValueType> the type of values
 */
public static class ImmediateEvictionHandler<KeyType, ValueType> implements EvictionHandler<KeyType, ValueType> {
@Override
public int onAccess(LIFOCache<KeyType, ValueType> targetCache) {
return targetCache.removeExpiredEntries();
}
}

/**
 * An eviction strategy that triggers eviction on every fixed number of accesses.
 *
 * <p>This deterministic strategy ensures cleanup occurs at predictable intervals,
 * ideal for moderately active caches where memory usage is a concern.
 *
 * @param <KeyType> the type of keys
 * @param <ValueType> the type of values
 */
public static class PeriodicEvictionHandler<KeyType, ValueType> implements EvictionHandler<KeyType, ValueType> {
private final int accessInterval;
private final AtomicInteger accessCounter = new AtomicInteger();

/**
 * Constructs a periodic eviction strategy.
 *
 * @param intervalSteps the number of accesses between evictions; must be > 0
 * @throws IllegalArgumentException if {@code intervalSteps} is less than or equal to 0
 */
public PeriodicEvictionHandler(int intervalSteps) {
if (intervalSteps <= 0) {
throw new IllegalArgumentException("Interval must be > 0");
}
this.accessInterval = intervalSteps;
}

@Override
public int onAccess(LIFOCache<KeyType, ValueType> targetCache) {
if (accessCounter.incrementAndGet() % accessInterval == 0) {
return targetCache.removeExpiredEntries();
}
return 0;
}
}

/**
 * A builder for constructing a {@link LIFOCache} instance with customizable settings.
 *
 * <p>Allows configuring capacity, default TTL, eviction listener, and a pluggable eviction
 * strategy. Call {@link #build()} to create the configured cache instance.
 *
 * @param <KeyType> the type of keys maintained by the cache
 * @param <ValueType> the type of values stored in the cache
 */
public static class Builder<KeyType, ValueType> {
private final int maxCapacity;
private long globalTTL = 0;
private BiConsumer<KeyType, ValueType> removalListener;
private EvictionHandler<KeyType, ValueType> evictionHandler = new LIFOCache.ImmediateEvictionHandler<>();

/**
 * Creates a new {@code Builder} with the specified cache capacity.
 *
 * @param capacityLimit the maximum number of entries the cache can hold; must be > 0
 * @throws IllegalArgumentException if {@code capacityLimit} is less than or equal to 0
 */
public Builder(int capacityLimit) {
if (capacityLimit <= 0) {
throw new IllegalArgumentException("Capacity must be > 0");
}
this.maxCapacity = capacityLimit;
}

/**
 * Sets the default time-to-live (TTL) in milliseconds for cache entries.
 *
 * @param ttlValue the TTL duration in milliseconds; must be >= 0
 * @return this builder instance for chaining
 * @throws IllegalArgumentException if {@code ttlValue} is negative
 */
public Builder<KeyType, ValueType> defaultTTL(long ttlValue) {
if (ttlValue < 0) {
throw new IllegalArgumentException("Default TTL must be >= 0");
}
this.globalTTL = ttlValue;
return this;
}

/**
 * Sets an eviction listener to be notified when entries are evicted from the cache.
 *
 * @param listenerCallback a {@link BiConsumer} that accepts evicted keys and values; must not be {@code null}
 * @return this builder instance for chaining
 * @throws IllegalArgumentException if {@code listenerCallback} is {@code null}
 */
public Builder<KeyType, ValueType> evictionListener(BiConsumer<KeyType, ValueType> listenerCallback) {
if (listenerCallback == null) {
throw new IllegalArgumentException("Listener must not be null");
}
this.removalListener = listenerCallback;
return this;
}

/**
 * Builds and returns a new {@link LIFOCache} instance with the configured parameters.
 *
 * @return a fully configured {@code LIFOCache} instance
 */
public LIFOCache<KeyType, ValueType> build() {
return new LIFOCache<>(this);
}

/**
 * Sets the eviction strategy used to determine when to clean up expired entries.
 *
 * @param strategyHandler an {@link EvictionHandler} implementation; must not be {@code null}
 * @return this builder instance
 * @throws IllegalArgumentException if {@code strategyHandler} is {@code null}
 */
public Builder<KeyType, ValueType> evictionStrategy(EvictionHandler<KeyType, ValueType> strategyHandler) {
if (strategyHandler == null) {
throw new IllegalArgumentException("Eviction strategy must not be null");
}
this.evictionHandler = strategyHandler;
return this;
}
}
}

/**
 * Converts an IPv4 address to its binary equivalent and vice-versa.
 * IP to Binary: Converts an IPv4 address to its binary equivalent.
 * Example: 127.3.4.5 -> 01111111.00000011.00000100.00000101
 *
 * Binary to IP: Converts a binary equivalent to an IPv4 address.
 * Example: 01111111.00000011.00000100.00000101 -> 127.3.4.5
 *
 * @author Hardvan
 */
public final class IPConverter {
private IPConverter() {
}

/**
 * Converts an IPv4 address to its binary equivalent.
 * @param ipAddress The IPv4 address to convert.
 * @return The binary equivalent of the IPv4 address.
 */
public static String ipToBinary(String ipAddress) {
StringBuilder binaryResult = new StringBuilder();
for (String octetSegment : ipAddress.split("\\.")) {
binaryResult.append(octetToBinary(Integer.parseInt(octetSegment))).append(".");
}
return binaryResult.substring(0, binaryResult.length() - 1);
}

/**
 * Converts a single octet to its 8-bit binary representation.
 * @param octetValue The octet to convert (0-255).
 * @return The 8-bit binary representation as a String.
 */
private static String octetToBinary(int octetValue) {
char[] binaryDigits = {'0', '0', '0', '0', '0', '0', '0', '0'};
int tempValue = octetValue;
for (int bitPos = 7; bitPos >= 0; bitPos--) {
if ((tempValue & 1) == 1) {
binaryDigits[bitPos] = '1';
}
tempValue >>>= 1;
}
return new String(binaryDigits);
}

/**
 * Converts a binary equivalent to an IPv4 address.
 * @param binaryString The binary equivalent to convert.
 * @return The IPv4 address of the binary equivalent.
 */
public static String binaryToIP(String binaryString) {
StringBuilder ipResult = new StringBuilder();
for (String octetString : binaryString.split("\\.")) {
ipResult.append(Integer.parseInt(octetString, 2)).append(".");
}
return ipResult.substring(0, ipResult.length() - 1);
}
}

import java.io.*;

/*
 * 
 * Bu ornekte, Calisan adinda bir sinif Serializable arayuzunu gerceklemektedir.
 * Bu sayede Calisan sinifindan olusturulan bir nesne ObjectOutputStream sinifi 
 * kullanilarak bir dosyaya serilestirilebilir. Daha sonra bu nesne, 
 * ObjectInputStream sinifi kullanilarak deserialization yoluyla dosyadan okunabilir.
 * Deserialization sonucu nesnenin orijinal durumu geri yuklenmektedir.
 * 
 */

public class Serilestirme {

	public static void main(String[] args) {

		// Yeni bir Calisan nesnesi olustur
		Calisan calisan = new Calisan("Ahmet Yilmaz", 54321, "Yazilim Muhendisi");

		// Nesneyi serilestir
		try {
			FileOutputStream dosyaCikisi = new FileOutputStream("calisan.ser");
			ObjectOutputStream cikisAkimi = new ObjectOutputStream(dosyaCikisi);
			cikisAkimi.writeObject(calisan);
			cikisAkimi.close();
			dosyaCikisi.close();
			System.out.println("Calisan nesnesi calisan.ser dosyasina serilestirildi.");
		} catch (IOException e) {
			e.printStackTrace();
		}

		// Nesneyi deserializasyon ile geri yukle
		Calisan geriYuklenenCalisan = null;
		try {
			FileInputStream dosyaGirisi = new FileInputStream("calisan.ser");
			ObjectInputStream girisAkimi = new ObjectInputStream(dosyaGirisi);
			geriYuklenenCalisan = (Calisan) girisAkimi.readObject();
			girisAkimi.close();
			dosyaGirisi.close();
		} catch (IOException e) {
			e.printStackTrace();
			return;
		} catch (ClassNotFoundException c) {
			System.out.println("Calisan sinifi bulunamadi.");
			c.printStackTrace();
			return;
		}

		// Geri yuklenen calisan bilgilerini yazdir
		System.out.println("Geri Yuklenen Calisan...");
		System.out.println("Isim: " + geriYuklenenCalisan.getIsim());
		System.out.println("ID: " + geriYuklenenCalisan.getID());
		System.out.println("Unvan: " + geriYuklenenCalisan.getUnvan());
	}
}

class Calisan implements Serializable {

	private static final long serialVersionUID = 1L;
	private String isim;
	private int ID;
	private String unvan;

	public Calisan(String isim, int ID, String unvan) {
		this.isim = isim;
		this.ID = ID;
		this.unvan = unvan;
	}

	public String getIsim() {
		return isim;
	}

	public int getID() {
		return ID;
	}

	public String getUnvan() {
		return unvan;
	}
}

package array;

public class DiziElemanErisim {

    // Cift indisli elemanlari yazdirir
    static void yaz1(int[] dizi) {
    	System.out.print("Cift indisli elemanlar: ");
        for (int i = 0; i < dizi.length; i++) {
            if (i % 2 == 0) {
                System.out.print(dizi[i] + " ");
            }
        }
        System.out.println();
    }

    // i miktarda atlayan indisli elemanlari yazdirir
    static void yaz2(int[] dizi) {
    	System.out.print("i artan indislerdeki elemanlar: ");
        for (int i = 1; i < dizi.length; i += i) { // i += i hatali bir ifade
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }

    // Dizinin tek sayi olan elemanlarini yazdirir
    static void yaz3(int[] dizi) {
    	System.out.print("Tek sayi elemanlar: ");
        for (int i = 1; i < dizi.length; i++) {
            if (dizi[i] % 2 == 0)
                continue;
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }

    // 3'e tam bolunen bir elemana rastlayana kadar elemanlari yazdirir
    static void yaz4(int[] dizi) {
    	System.out.print("Ucun kati bir elemana kadar: ");
    	for (int i = 1; i < dizi.length; i++) {
            if (dizi[i] % 3 == 0)
                break;
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }

    // Tum elemanlari yazdirir
    static void yazTum(int[] dizi) {
    	System.out.print("Tum elemanlar: ");
        for (int i = 0; i < dizi.length; i++) {
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }

    public static void main(String[] args) {

        // Ornek bir dizi
        int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        yazTum(dizi);
        yaz1(dizi);
        yaz2(dizi);
        yaz3(dizi);
        yaz4(dizi);

    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * This class refers to the Optimal Job Scheduling problem with the following constrains:
 *  - precedence relation between the processes
 *  - machine pair dependent transportation delays
 *
 * https://en.wikipedia.org/wiki/Optimal_job_scheduling
 *
 * @author georgioct@csd.auth.gr
 */
public class OptimalJobScheduling {

    private final int numberProcesses;
    private final int numberMachines;
    private final int[][] run;
    private final int[][] transfer;
    private final int[][] cost;

    /**
     * Constructor of the class.
     * @param numberProcesses ,refers to the number of precedent processes(N)
     * @param numberMachines ,refers to the number of different machines in our disposal(M)
     * @param run , N*M matrix refers to the cost of running each process to each machine
     * @param transfer ,M*M symmetric matrix refers to the transportation delay for each pair of
     *     machines
     */
    public OptimalJobScheduling(int numberProcesses, int numberMachines, int[][] run, int[][] transfer) {
        this.numberProcesses = numberProcesses;
        this.numberMachines = numberMachines;
        this.run = run;
        this.transfer = transfer;
        this.cost = new int[numberProcesses][numberMachines];
    }

    /**
     * Function which computes the cost of process scheduling to a number of VMs.
     */
    public void execute() {
        this.calculateCost();
        this.showResults();
    }

    /**
     * Function which computes the cost of running each Process to each and every Machine
     */
    private void calculateCost() {

        for (int i = 0; i < numberProcesses; i++) { // for each Process

            for (int j = 0; j < numberMachines; j++) { // for each Machine

                cost[i][j] = runningCost(i, j);
            }
        }
    }

    /**
     * Function which returns the minimum cost of running a certain Process to a certain Machine.In
     * order for the Machine to execute the Process ,he requires the output of the previously
     * executed Process, which may have been executed to the same Machine or some other.If the
     * previous Process has been executed to another Machine,we have to transfer her result, which
     * means extra cost for transferring the data from one Machine to another(if the previous
     * Process has been executed to the same Machine, there is no transport cost).
     *
     * @param process ,refers to the Process
     * @param machine ,refers to the Machine
     * @return the minimum cost of executing the process to the certain machine.
     */
    private int runningCost(int process, int machine) {

        if (process == 0) { // refers to the first process,which does not require for a previous one
            // to have been executed
            return run[process][machine];
        } else {

            int[] runningCosts = new int[numberMachines]; // stores the costs of executing our Process depending on
            // the Machine the previous one was executed

            for (int k = 0; k < numberMachines; k++) { // computes the cost of executing the previous
                // process to each and every Machine
                runningCosts[k] = cost[process - 1][k] + transfer[k][machine] + run[process][machine]; // transferring the result to our Machine and executing
                // the Process to our Machine
            }
            return findMin(runningCosts); // returns the minimum running cost
        }
    }

    /**
     * Function used in order to return the minimum Cost.
     * @param costArr ,an Array of size M which refers to the costs of executing a Process to each
     *     Machine
     * @return the minimum cost
     */
    private int findMin(int[] costArr) {

        int min = 0;

        for (int i = 1; i < costArr.length; i++) {

            if (costArr[i] < costArr[min]) {
                min = i;
            }
        }
        return costArr[min];
    }

    /**
     * Method used in order to present the overall costs.
     */
    private void showResults() {

        for (int i = 0; i < numberProcesses; i++) {

            for (int j = 0; j < numberMachines; j++) {
                System.out.print(cost[i][j]);
                System.out.print(" ");
            }

            System.out.println();
        }
        System.out.println();
    }

    /**
     * Getter for the running Cost of i process on j machine.
     */
    public int getCost(int process, int machine) {
        return cost[process][machine];
    }
}

package twodimensional;

import java.util.Random;

/*
 * Randomized maze generator.
 *
 * This class fills a 2D grid with either wall cells ('#') or open path
 * cells ('.') using a simple probability check for each position, then
 * prints the resulting grid to standard output.
 */

public class Labirent {

    private static final int COLUMN_COUNT = 10;      // how many columns the grid has
    private static final int ROW_COUNT = 10;          // how many rows the grid has
    private static final char WALL_SYMBOL = '#';       // symbol used for blocked cells
    private static final char PATH_SYMBOL = '.';       // symbol used for open cells
    private static final double WALL_CHANCE = 0.3;     // probability a cell becomes a wall

    private static char[][] grid; // holds the generated maze layout

    public static void main(String[] args) {
        grid = buildRandomGrid();
        renderGrid();
    }

    // Builds a grid where each cell is randomly chosen to be a wall or a path.
    private static char[][] buildRandomGrid() {
        Random randomizer = new Random();
        char[][] freshGrid = new char[ROW_COUNT][COLUMN_COUNT];

        for (int row = 0; row < ROW_COUNT; row++) {
            for (int col = 0; col < COLUMN_COUNT; col++) {
                boolean isWall = randomizer.nextDouble() < WALL_CHANCE;
                freshGrid[row][col] = isWall ? WALL_SYMBOL : PATH_SYMBOL;
            }
        }

        return freshGrid;
    }

    // Prints every row of the grid, separating cells with a single space.
    private static void renderGrid() {
        StringBuilder lineBuffer;
        for (int row = 0; row < ROW_COUNT; row++) {
            lineBuffer = new StringBuilder();
            for (int col = 0; col < COLUMN_COUNT; col++) {
                lineBuffer.append(grid[row][col]).append(' ');
            }
            System.out.println(lineBuffer.toString().trim());
        }
    }
}

public class BreakOrnegi {

    // For dongusu icerisinde break ifadesinin nasil calistigini gosterir
    public static void forOrnegiGoster() {
        System.out.println("For dongusu ornegi:");
        int sayac = 1;
        for (; sayac <= 10; sayac++) {
            if (sayac == 5) { // sayac 5'e ulastiginda dongu durur
                System.out.println("Dongu 5 degerinde kirildi!");
                break;
            }
            System.out.println("Dongu adimi: " + sayac);
        }
    }

    // While dongusu icinde break kullanilan ornek
    public static void whileOrnegiGoster() {
        System.out.println("\nWhile dongusu ornegi:");
        int sayac = 1;
        while (true) {
            if (sayac > 10) {
                break;
            }
            if (sayac == 7) { // sayac 7 oldugunda dongu sonlanir
                System.out.println("Dongu 7 degerinde kirildi!");
                break;
            }
            System.out.println("Dongu adimi: " + sayac);
            sayac++;
        }
    }

    // Ic ice yerlestirilmis donguler icerisinde break kullanimi
    public static void icIceOrnegiGoster() {
        System.out.println("\nIc ice donguler ornegi:");
        for (int disSayac = 1; disSayac <= 4; disSayac++) {
            int icSayac = 1;
            while (icSayac <= 4) {
                if (icSayac == 2) { // ic dongu belli bir noktada durdurulur
                    System.out.println("Ic dongu j = 2 de kirildi (i = " + disSayac + ")");
                    break;
                }
                System.out.println("i: " + disSayac + ", j: " + icSayac);
                icSayac++;
            }
        }
    }

    public static void main(String[] args) {
        // Sirasiyla ornekleri calistir
        forOrnegiGoster();
        whileOrnegiGoster();
        icIceOrnegiGoster();
    }
}

package collections;
import java.util.ArrayList;
import java.util.List;

public class Fibonacci {

    // Fibonacci dizisini iteratif olarak bulan metod
    public static int fibonacci(int sayi) {
        // Fibonacci sayilarini tutacak liste olustur
        List<Integer> liste = new ArrayList<>();
        // Ilk iki Fibonacci sayisini listeye ekle
        liste.add(0);
        liste.add(1);
        // Fibonacci dizisini iteratif olarak hesapla
        for (int i = 2; i < sayi + 1; i++) {
            // Onceki iki sayinin toplamini listeye ekle
            liste.add(liste.get(i - 2) + liste.get(i - 1));
        }
        // Istenen Fibonacci sayisini geri dondur
        return liste.get(sayi);
    }

    public static void main(String[] args) {

        // 10. Fibonacci sayisini hesapla
        int sonuc = fibonacci(10);
        // Sonucu ekrana yazdir
        System.out.println(sonuc);
    }
}

/**
 * Implementation of the Gale-Shapley Algorithm for Stable Matching.
 * Problem link: https://en.wikipedia.org/wiki/Stable_marriage_problem
 */
public final class GaleShapley {

    private GaleShapley() {
    }

    /**
     * Function to find stable matches between men and women.
     *
     * @param womenPrefs A map containing women's preferences where each key is a woman and the value is an array of men in order of preference.
     * @param menPrefs   A map containing men's preferences where each key is a man and the value is an array of women in order of preference.
     * @return A map containing stable matches where the key is a woman and the value is her matched man.
     */
    public static Map<String, String> stableMatch(Map<String, LinkedList<String>> womenPrefs, Map<String, LinkedList<String>> menPrefs) {
        // Initialize all men as free
        Map<String, String> engagements = new HashMap<>();
        LinkedList<String> freeMen = new LinkedList<>(menPrefs.keySet());

        // While there are free men
        while (!freeMen.isEmpty()) {
            String man = freeMen.poll(); // Get the first free man
            LinkedList<String> manPref = menPrefs.get(man); // Get the preferences of the man

            // Check if manPref is null or empty
            if (manPref == null || manPref.isEmpty()) {
                continue; // Skip if no preferences
            }

            // Propose to the first woman in the man's preference list
            String woman = manPref.poll();
            String fiance = engagements.get(woman);

            // If the woman is not engaged, engage her with the current man
            if (fiance == null) {
                engagements.put(woman, man);
            } else {
                // If the woman prefers the current man over her current fiance
                LinkedList<String> womanPrefList = womenPrefs.get(woman);

                // Check if womanPrefList is null
                if (womanPrefList == null) {
                    continue; // Skip if no preferences for the woman
                }

                if (womanPrefList.indexOf(man) < womanPrefList.indexOf(fiance)) {
                    engagements.put(woman, man);
                    freeMen.add(fiance); // Previous fiance becomes free
                } else {
                    // Woman rejects the new proposal, the man remains free
                    freeMen.add(man);
                }
            }
        }
        return engagements; // Return the stable matches
    }
}

public class BmiCalculator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter weight (kg): ");
        double weight = scanner.nextDouble();
        System.out.print("Enter height (m): ");
        double height = scanner.nextDouble();

        double bmi = weight / (height * height);
        System.out.printf("Your BMI: %.1f%n", bmi);

        if (bmi < 18.5) {
            System.out.println("Category: underweight");
        } else if (bmi < 25) {
            System.out.println("Category: normal");
        } else if (bmi < 30) {
            System.out.println("Category: overweight");
        } else {
            System.out.println("Category: obesity");
        }
        scanner.close();
    }
}

/**
 * The A5Cipher class implements the A5/1 stream cipher, which is a widely used
 * encryption algorithm, particularly in mobile communications.
 *
 * This implementation uses a key stream generator to produce a stream of bits
 * that are XORed with the plaintext bits to produce the ciphertext.
 *
 * <p>
 * For more details about the A5/1 algorithm, refer to
 * <a href="https://en.wikipedia.org/wiki/A5/1">Wikipedia</a>.
 * </p>
 */
public class A5Cipher {

    private final A5KeyStreamGenerator keyStreamGenerator;
    private static final int KEY_STREAM_LENGTH = 228; // Length of the key stream in bits (28.5 bytes)

    /**
     * Constructs an A5Cipher instance with the specified session key and frame counter.
     *
     * @param sessionKey a BitSet representing the session key used for encryption.
     * @param frameCounter a BitSet representing the frame counter that helps in key stream generation.
     */
    public A5Cipher(BitSet sessionKey, BitSet frameCounter) {
        keyStreamGenerator = new A5KeyStreamGenerator();
        keyStreamGenerator.initialize(sessionKey, frameCounter);
    }

    /**
     * Encrypts the given plaintext bits using the A5/1 cipher algorithm.
     *
     * This method generates a key stream and XORs it with the provided plaintext
     * bits to produce the ciphertext.
     *
     * @param plainTextBits a BitSet representing the plaintext bits to be encrypted.
     * @return a BitSet containing the encrypted ciphertext bits.
     */
    public BitSet encrypt(BitSet plainTextBits) {
        // create a copy
        var result = new BitSet(KEY_STREAM_LENGTH);
        result.xor(plainTextBits);

        var key = keyStreamGenerator.getNextKeyStream();
        result.xor(key);

        return result;
    }

    /**
     * Resets the internal counter of the key stream generator.
     *
     * This method can be called to re-initialize the state of the key stream
     * generator, allowing for new key streams to be generated for subsequent
     * encryptions.
     */
    public void resetCounter() {
        keyStreamGenerator.reInitialize();
    }
}

package twodimensional;

import java.util.Random;

/*
 * Rastgele bir labirent olusturur:
 * 
 * Program, iki boyutlu bir diziyi rastgele olarak duvarlar ('#') ve yollar ('.') ile doldurarak bir labirent olusturur. 
 */

public class Labirent {
    private static final int GENISLIK = 10; // Labirentin genisligi
    private static final int YUKSEKLIK = 10; // Labirentin yuksekligi
    private static final char DUVAR = '#'; // Duvarlari temsil eden karakter
    private static final char YOL = '.'; // Yollari temsil eden karakter

    private static char[][] labirent; // Labirenti tutan iki boyutlu dizi

    public static void main(String[] args) {
        // Rastgele labirent olustur
        labirent = labirentOlustur();

        // Labirenti yazdir
        labirentiYazdir();
    }

