package com.thealgorithms.maths.Prime;

/*
 * Java program for liouville lambda function
 * For any positive integer n, define λ(n) as the sum of the primitive nth roots of unity.
 * It has values in {−1, 1} depending on the factorization of n into prime factors:
 *   λ(n) = +1 if n is a positive integer with an even number of prime factors.
 *   λ(n) = −1 if n is a positive integer with an odd number of prime factors.
 * Wikipedia: https://en.wikipedia.org/wiki/Liouville_function
 *
 * Author: Akshay Dubey (https://github.com/itsAkshayDubey)
 *
 * */

public final class LiouvilleLambdaFunction {
    private LiouvilleLambdaFunction() {
    }

    /**
     * This method returns λ(n) of given number n
     *
     * @param number Integer value which λ(n) is to be calculated
     * @return  1 when number has even number of prime factors
     *         -1 when number has odd number of prime factors
     * @throws IllegalArgumentException when number is negative
     */
    public static int liouvilleLambda(int number) {
        if (number <= 0) {
            // throw exception when number is less than or is zero
            throw new IllegalArgumentException("Number must be greater than zero.");
        }

        // return 1 if size of prime factor list is even, -1 otherwise
        return PrimeFactorization.pfactors(number).size() % 2 == 0 ? 1 : -1;
    }
}

package com.thealgorithms.datastructures.bags;

import java.util.Iterator;
import java.util.NoSuchElementException;

/**
 * A generic collection that allows adding and iterating over elements but does not support
 * element removal. This class implements a simple bag data structure, which can hold duplicate
 * elements and provides operations to check for membership and the size of the collection.
 *
 * <p>Bag is not thread-safe and should not be accessed by multiple threads concurrently.
 *
 * @param <ElementType> the type of elements in this bag
 */
public class Bag<ElementType> implements Iterable<ElementType> {

private Node<ElementType> headNode;
private int elementCount;

private static final class Node<ElementType> {
private ElementType itemData;
private Node<ElementType> nextNode;
}

/**
 * Constructs an empty bag.
 * <p>This initializes the bag with zero elements.
 */
public Bag() {
headNode = null;
elementCount = 0;
}

/**
 * Checks if the bag is empty.
 *
 * @return {@code true} if the bag contains no elements; {@code false} otherwise
 */
public boolean isEmpty() {
return elementCount == 0;
}

/**
 * Returns the number of elements in the bag.
 *
 * @return the number of elements currently in the bag
 */
public int size() {
return elementCount;
}

/**
 * Adds an element to the bag.
 *
 * <p>This method adds the specified element to the bag. Duplicates are allowed, and the
 * bag will maintain the order in which elements are added.
 *
 * @param elementValue the element to add; must not be {@code null}
 */
public void add(ElementType elementValue) {
Node<ElementType> newNode = new Node<>();
newNode.itemData = elementValue;
newNode.nextNode = headNode;
headNode = newNode;
elementCount++;
}

/**
 * Checks if the bag contains a specific element.
 *
 * <p>This method uses the {@code equals} method of the element to determine membership.
 *
 * @param targetElement the element to check for; must not be {@code null}
 * @return {@code true} if the bag contains the specified element; {@code false} otherwise
 */
public boolean contains(ElementType targetElement) {
for (ElementType currentItem : this) {
if (currentItem.equals(targetElement)) {
return true;
}
}
return false;
}

/**
 * Returns an iterator over the elements in this bag.
 *
 * <p>The iterator provides a way to traverse the elements in the order they were added.
 *
 * @return an iterator that iterates over the elements in the bag
 */
@Override
public Iterator<ElementType> iterator() {
return new SequentialIterator<>(headNode);
}

private static class SequentialIterator<ElementType> implements Iterator<ElementType> {

private Node<ElementType> currentPosition;

SequentialIterator(Node<ElementType> startNode) {
this.currentPosition = startNode;
}

@Override
public boolean hasNext() {
return currentPosition != null;
}

@Override
public ElementType next() {
if (!hasNext()) {
throw new NoSuchElementException("No more elements in the bag.");
}
ElementType retrievedItem = currentPosition.itemData;
currentPosition = currentPosition.nextNode;
return retrievedItem;
}
}
}

package com.thealgorithms.datastructures.trees;

public class LazySegmentTree {

    /**
     * Lazy Segment Tree
     *
     * @see
     *	<a href="https://www.geeksforgeeks.org/lazy-propagation-in-segment-tree/">
     */
    static class Node {

        private final int start;
        private final int end; // start and end of the segment represented by this node
        private int value; // value is the sum of all elements in the range [start, end)
        private int lazy; // lazied value that should be added to children nodes
        Node left;
        Node right; // left and right children

        Node(int start, int end, int value) {
            this.start = start;
            this.end = end;
            this.value = value;
            this.lazy = 0;
            this.left = null;
            this.right = null;
        }

        /**
         * Update the value of this node with the given value diff.
         *
         * @param diff The value to add to every index of this node range.
         */
        public void applyUpdate(int diff) {
            this.lazy += diff;
            this.value += (this.end - this.start) * diff;
        }

        /**
         * Shift the lazy value of this node to its children.
         */
        public void shift() {
            if (lazy == 0) {
                return;
            }
            if (this.left == null && this.right == null) {
                return;
            }
            this.value += this.lazy;
            if (this.left != null) {
                this.left.applyUpdate(this.lazy);
            }
            if (this.right != null) {
                this.right.applyUpdate(this.lazy);
            }
            this.lazy = 0;
        }

        /**
         * Create a new node that is the sum of this node and the given node.
         *
         * @param left The left Node of merging
         * @param right The right Node of merging
         * @return The new Node.
         */
        static Node merge(Node left, Node right) {
            if (left == null) {
                return right;
            }
            if (right == null) {
                return left;
            }
            Node result = new Node(left.start, right.end, left.value + right.value);
            result.left = left;
            result.right = right;
            return result;
        }

        public int getValue() {
            return value;
        }

        public Node getLeft() {
            return left;
        }

        public Node getRight() {
            return right;
        }
    }

    private final Node root;

    /**
     * Create a new LazySegmentTree with the given array.
     *
     * @param array The array to create the LazySegmentTree from.
     */
    public LazySegmentTree(int[] array) {
        this.root = buildTree(array, 0, array.length);
    }

    /**
     * Build a new LazySegmentTree from the given array in O(n) time.
     *
     * @param array The array to build the LazySegmentTree from.
     * @param start The start index of the current node.
     * @param end The end index of the current node.
     * @return The root of the new LazySegmentTree.
     */
    private Node buildTree(int[] array, int start, int end) {
        if (end - start < 2) {
            return new Node(start, end, array[start]);
        }
        int mid = (start + end) >> 1;
        Node left = buildTree(array, start, mid);
        Node right = buildTree(array, mid, end);
        return Node.merge(left, right);
    }

    /**
     * Update the value of given range with the given value diff in O(log n) time.
     *
     * @param left The left index of the range to update.
     * @param right The right index of the range to update.
     * @param diff The value to add to every index of the range.
     * @param curr The current node.
     */
    private void updateRange(int left, int right, int diff, Node curr) {
        if (left <= curr.start && curr.end <= right) {
            curr.applyUpdate(diff);
            return;
        }
        if (left >= curr.end || right <= curr.start) {
            return;
        }
        curr.shift();
        updateRange(left, right, diff, curr.left);
        updateRange(left, right, diff, curr.right);
        Node merge = Node.merge(curr.left, curr.right);
        curr.value = merge.value;
    }

    /**
     * Get Node of given range in O(log n) time.
     *
     * @param left The left index of the range to update.
     * @param right The right index of the range to update.
     * @return The Node representing the sum of the given range.
     */
    private Node getRange(int left, int right, Node curr) {
        if (left <= curr.start && curr.end <= right) {
            return curr;
        }
        if (left >= curr.end || right <= curr.start) {
            return null;
        }
        curr.shift();
        return Node.merge(getRange(left, right, curr.left), getRange(left, right, curr.right));
    }

    public int getRange(int left, int right) {
        Node result = getRange(left, right, root);
        return result == null ? 0 : result.getValue();
    }

    public void updateRange(int left, int right, int diff) {
        updateRange(left, right, diff, root);
    }

    public Node getRoot() {
        return root;
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.Arrays;

/**
 * Given a set of points and a number k.
 * The goal is to minimize the maximum distance between any point and its nearest center.
 * Each point is assigned to the nearest center.
 * The distance between two points is the Euclidean distance.
 * The problem is NP-hard.
 *
 * @author Hardvan
 */
public final class KCenters {
    private KCenters() {
    }

    /**
     * Finds the maximum distance to the nearest center given k centers.
     * Steps:
     * 1. Initialize an array {@code selected} of size n and an array {@code maxDist} of size n.
     * 2. Set the first node as selected and update the maxDist array.
     * 3. For each center, find the farthest node from the selected centers.
     * 4. Update the maxDist array.
     * 5. Return the maximum distance to the nearest center.
     *
     * @param distances matrix representing distances between nodes
     * @param k         the number of centers
     * @return the maximum distance to the nearest center
     */
    public static int findKCenters(int[][] distances, int k) {
        int n = distances.length;
        boolean[] selected = new boolean[n];
        int[] maxDist = new int[n];

        Arrays.fill(maxDist, Integer.MAX_VALUE);

        selected[0] = true;
        for (int i = 1; i < n; i++) {
            maxDist[i] = Math.min(maxDist[i], distances[0][i]);
        }

        for (int centers = 1; centers < k; centers++) {
            int farthest = -1;
            for (int i = 0; i < n; i++) {
                if (!selected[i] && (farthest == -1 || maxDist[i] > maxDist[farthest])) {
                    farthest = i;
                }
            }
            selected[farthest] = true;
            for (int i = 0; i < n; i++) {
                maxDist[i] = Math.min(maxDist[i], distances[farthest][i]);
            }
        }

        int result = 0;
        for (int dist : maxDist) {
            result = Math.max(result, dist);
        }
        return result;
    }
}

package com.thealgorithms.compression;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedList;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Implementation of the Move-to-Front (MTF) transform and its inverse.
 * <p>
 * MTF is a data transformation algorithm that encodes each symbol in the input
 * as its current position in a dynamically-maintained list, then moves that symbol
 * to the front of the list. This transformation is particularly effective when used
 * after the Burrows-Wheeler Transform (BWT), as BWT groups similar characters together.
 * </p>
 *
 * <p>The transform converts runs of repeated characters into sequences of small integers
 * (often zeros), which are highly compressible by subsequent entropy encoding algorithms
 * like Run-Length Encoding (RLE) or Huffman coding. This technique is used in the
 * bzip2 compression algorithm.
 * </p>
 *
 * <p><b>How it works:</b>
 * <ol>
 *   <li>Maintain a list of symbols (the alphabet), initially in a fixed order</li>
 *   <li>For each input symbol:
 *     <ul>
 *       <li>Output its current index in the list</li>
 *       <li>Move that symbol to the front of the list</li>
 *     </ul>
 *   </li>
 * </ol>
 * This means frequently occurring symbols quickly move to the front and are encoded
 * with small indices (often 0), while rare symbols remain near the back.
 * </p>
 *
 * <p><b>Time Complexity:</b>
 * <ul>
 *   <li>Forward transform: O(n × m) where n is input length and m is alphabet size</li>
 *   <li>Inverse transform: O(n × m)</li>
 * </ul>
 * Note: Using {@link LinkedList} for O(1) insertions and O(m) search operations.
 * </p>
 *
 * <p><b>Example:</b></p>
 * <pre>
 * Input:    "annb$aa"
 * Alphabet: "$abn" (initial order)
 * Output:   [1, 3, 0, 3, 3, 3, 0]
 *
 * Step-by-step:
 * - 'a': index 1 in [$,a,b,n] → output 1, list becomes [a,$,b,n]
 * - 'n': index 3 in [a,$,b,n] → output 3, list becomes [n,a,$,b]
 * - 'n': index 0 in [n,a,$,b] → output 0, list stays [n,a,$,b]
 * - 'b': index 3 in [n,a,$,b] → output 3, list becomes [b,n,a,$]
 * - etc.
 *
 * Notice how repeated 'n' characters produce zeros after the first occurrence!
 * </pre>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Move-to-front_transform">Move-to-front transform (Wikipedia)</a>
 */
public final class MoveToFront {

    private MoveToFront() {
    }

    /**
     * Performs the forward Move-to-Front transform.
     * <p>
     * Converts the input string into a list of integers, where each integer represents
     * the position of the corresponding character in a dynamically-maintained alphabet list.
     * </p>
     *
     * <p><b>Note:</b> All characters in the input text must exist in the provided alphabet,
     * otherwise an {@link IllegalArgumentException} is thrown. The alphabet should contain
     * all unique characters that may appear in the input.</p>
     *
     * @param text the input string to transform; if empty, returns an empty list
     * @param initialAlphabet a string containing the initial ordered set of symbols
     *                        (e.g., "$abn" or the full ASCII set); must not be empty
     *                        when {@code text} is non-empty
     * @return a list of integers representing the transformed data, where each integer
     *         is the index of the corresponding input character in the current alphabet state
     * @throws IllegalArgumentException if {@code text} is non-empty and {@code initialAlphabet}
     *                                  is {@code null} or empty
     * @throws IllegalArgumentException if any character in {@code text} is not found in
     *                                  {@code initialAlphabet}
     */
    public static List<Integer> transform(String text, String initialAlphabet) {
        if (text == null || text.isEmpty()) {
            return new ArrayList<>();
        }
        if (initialAlphabet == null || initialAlphabet.isEmpty()) {
            throw new IllegalArgumentException("Alphabet cannot be null or empty when text is not empty.");
        }

        List<Integer> output = new ArrayList<>(text.length());

        // Use LinkedList for O(1) add-to-front and O(n) remove operations
        // This is more efficient than ArrayList for the move-to-front pattern
        List<Character> alphabet = initialAlphabet.chars().mapToObj(c -> (char) c).collect(Collectors.toCollection(LinkedList::new));

        for (char c : text.toCharArray()) {
            int index = alphabet.indexOf(c);
            if (index == -1) {
                throw new IllegalArgumentException("Symbol '" + c + "' not found in the initial alphabet.");
            }

            output.add(index);

            // Move the character to the front
            Character symbol = alphabet.remove(index);
            alphabet.addFirst(symbol);
        }
        return output;
    }

    /**
     * Performs the inverse Move-to-Front transform.
     * <p>
     * Reconstructs the original string from the list of indices produced by the
     * forward transform. This requires the exact same initial alphabet that was
     * used in the forward transform.
     * </p>
     *
     * <p><b>Important:</b> The {@code initialAlphabet} parameter must be identical
     * to the one used in the forward transform, including character order, or the
     * output will be incorrect.</p>
     *
     * @param indices The list of integers from the forward transform.
     * @param initialAlphabet the exact same initial alphabet string used for the forward transform;
     *                        if {@code null} or empty, returns an empty string
     * @return the original, untransformed string
     * @throws IllegalArgumentException if any index in {@code indices} is negative or
     *                                  exceeds the current alphabet size
     */
    public static String inverseTransform(Collection<Integer> indices, String initialAlphabet) {
        if (indices == null || indices.isEmpty() || initialAlphabet == null || initialAlphabet.isEmpty()) {
            return "";
        }

        StringBuilder output = new StringBuilder(indices.size());

        // Use LinkedList for O(1) add-to-front and O(n) remove operations
        List<Character> alphabet = initialAlphabet.chars().mapToObj(c -> (char) c).collect(Collectors.toCollection(LinkedList::new));

        for (int index : indices) {
            if (index < 0 || index >= alphabet.size()) {
                throw new IllegalArgumentException("Index " + index + " is out of bounds for the current alphabet of size " + alphabet.size() + ".");
            }

            // Get the symbol at the index
            char symbol = alphabet.get(index);
            output.append(symbol);

            // Move the symbol to the front (mirroring the forward transform)
            alphabet.remove(index);
            alphabet.addFirst(symbol);
        }
        return output.toString();
    }
}

/**
 * Provides methods to reverse a stack using recursion.
 *
 * <p>This class includes methods to reverse the order of elements in a stack
 * without using additional data structures. Elements are inserted at the bottom
 * of the stack to achieve the reverse order.
 *
 * <p>Example usage:
 * <pre>
 *     Stack<Integer> stack = new Stack<>();
 *     stack.push(1);
 *     stack.push(2);
 *     stack.push(3);
 *     ReverseStack.reverseStack(stack);
 * </pre>
 * After calling {@code reverseStack(stack)}, the stack's order is reversed.
 *
 * <p>This class is final and has a private constructor to prevent instantiation.
 *
 * @author Ishika Agarwal, 2021
 */
public final class ReverseStack {
    private ReverseStack() {
    }

    /**
     * Reverses the order of elements in the given stack using recursion.
     * Steps:
     * 1. Check if the stack is empty. If so, return.
     * 2. Pop the top element from the stack.
     * 3. Recursively reverse the remaining stack.
     * 4. Insert the originally popped element at the bottom of the reversed stack.
     *
     * @param stack the stack to reverse; should not be null
     */
    public static void reverseStack(Stack<Integer> stack) {
        if (stack == null) {
            throw new IllegalArgumentException("Stack cannot be null");
        }
        if (stack.isEmpty()) {
            return;
        }

        int element = stack.pop();
        reverseStack(stack);
        insertAtBottom(stack, element);
    }

    /**
     * Inserts the specified element at the bottom of the stack.
     *
     * <p>This method is a helper for {@link #reverseStack(Stack)}.
     *
     * Steps:
     * 1. If the stack is empty, push the element and return.
     * 2. Remove the top element from the stack.
     * 3. Recursively insert the new element at the bottom of the stack.
     * 4. Push the removed element back onto the stack.
     *
     * @param stack the stack in which to insert the element; should not be null
     * @param element the element to insert at the bottom of the stack
     */
    private static void insertAtBottom(Stack<Integer> stack, int element) {
        if (stack.isEmpty()) {
            stack.push(element);
            return;
        }

        int topElement = stack.pop();
        insertAtBottom(stack, element);
        stack.push(topElement);
    }
}

package com.thealgorithms.bitmanipulation;

import java.util.List;

/**
 * Implements various Boolean algebra gates (AND, OR, NOT, XOR, NAND, NOR)
 */
public final class BooleanAlgebraGates {

    private BooleanAlgebraGates() {
        // Prevent instantiation
    }

    /**
     * Represents a Boolean gate that takes multiple inputs and returns a result.
     */
    interface BooleanGate {
        /**
         * Evaluates the gate with the given inputs.
         *
         * @param inputs The input values for the gate.
         * @return The result of the evaluation.
         */
        boolean evaluate(List<Boolean> inputs);
    }

    /**
     * AND Gate implementation.
     * Returns true if all inputs are true; otherwise, false.
     */
    static class ANDGate implements BooleanGate {
        @Override
        public boolean evaluate(List<Boolean> inputs) {
            for (boolean input : inputs) {
                if (!input) {
                    return false;
                }
            }
            return true;
        }
    }

    /**
     * OR Gate implementation.
     * Returns true if at least one input is true; otherwise, false.
     */
    static class ORGate implements BooleanGate {
        @Override
        public boolean evaluate(List<Boolean> inputs) {
            for (boolean input : inputs) {
                if (input) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * NOT Gate implementation (Unary operation).
     * Negates a single input value.
     */
    static class NOTGate {
        /**
         * Evaluates the negation of the input.
         *
         * @param input The input value to be negated.
         * @return The negated value.
         */
        public boolean evaluate(boolean input) {
            return !input;
        }
    }

    /**
     * XOR Gate implementation.
     * Returns true if an odd number of inputs are true; otherwise, false.
     */
    static class XORGate implements BooleanGate {
        @Override
        public boolean evaluate(List<Boolean> inputs) {
            boolean result = false;
            for (boolean input : inputs) {
                result ^= input;
            }
            return result;
        }
    }

    /**
     * NAND Gate implementation.
     * Returns true if at least one input is false; otherwise, false.
     */
    static class NANDGate implements BooleanGate {
        @Override
        public boolean evaluate(List<Boolean> inputs) {
            return !new ANDGate().evaluate(inputs); // Equivalent to negation of AND
        }
    }

    /**
     * NOR Gate implementation.
     * Returns true if all inputs are false; otherwise, false.
     */
    static class NORGate implements BooleanGate {
        @Override
        public boolean evaluate(List<Boolean> inputs) {
            return !new ORGate().evaluate(inputs); // Equivalent to negation of OR
        }
    }
}

package com.ankan.inheritance.polymorphism;

public class Main {
    public static void main(String[] args) {
        // Creating reference variables of type Shapes (parent class)
        Shapes genericShapeReference = new Shapes();      // Points to Shapes object
        Shapes circleShapeReference = new Circle();       // Points to Circle object (Upcasting)
        Shapes squareShapeReference = new Square();       // Points to Square object (Upcasting)

        // The area() method call is determined at runtime, not compile time
        // This demonstrates Dynamic Method Dispatch and Runtime Polymorphism

        // genericShapeReference.calculateArea(); // Would call Shapes version (commented)

        // Even though the reference type is Shapes, the actual object type determines which method runs
        squareShapeReference.calculateArea(); 

        // Key concept: Reference variable type determines WHAT can be accessed
        // Actual object type determines WHICH overridden method executes
        // This process is known as Upcasting (assigning subclass object to superclass reference)
        // Java uses a mechanism called ***Dynamic Method Dispatch*** to resolve overridden methods at runtime
    }
}

package com.thealgorithms.audiofilters;

/**
 * N-Order IIR Filter Assumes inputs are normalized to [-1, 1]
 *
 * Based on the difference equation from
 * <a href="https://en.wikipedia.org/wiki/Infinite_impulse_response">Wikipedia link</a>
 */
public class IIRFilter {

    private final int order;
    private final double[] coeffsA;
    private final double[] coeffsB;
    private final double[] historyX;
    private final double[] historyY;

    /**
     * Construct an IIR Filter
     *
     * @param order the filter's order
     * @throws IllegalArgumentException if order is zero or less
     */
    public IIRFilter(int order) throws IllegalArgumentException {
        if (order < 1) {
            throw new IllegalArgumentException("order must be greater than zero");
        }

        this.order = order;
        coeffsA = new double[order + 1];
        coeffsB = new double[order + 1];

        // Sane defaults
        coeffsA[0] = 1.0;
        coeffsB[0] = 1.0;

        historyX = new double[order];
        historyY = new double[order];
    }

    /**
     * Set coefficients
     *
     * @param aCoeffs Denominator coefficients
     * @param bCoeffs Numerator coefficients
     * @throws IllegalArgumentException if {@code aCoeffs} or {@code bCoeffs} is
     * not of size {@code order}, or if {@code aCoeffs[0]} is 0.0
     */
    public void setCoeffs(double[] aCoeffs, double[] bCoeffs) throws IllegalArgumentException {
        if (aCoeffs.length != order) {
            throw new IllegalArgumentException("aCoeffs must be of size " + order + ", got " + aCoeffs.length);
        }

        if (aCoeffs[0] == 0.0) {
            throw new IllegalArgumentException("aCoeffs.get(0) must not be zero");
        }

        if (bCoeffs.length != order) {
            throw new IllegalArgumentException("bCoeffs must be of size " + order + ", got " + bCoeffs.length);
        }

        for (int i = 0; i < order; i++) {
            coeffsA[i] = aCoeffs[i];
            coeffsB[i] = bCoeffs[i];
        }
    }

    /**
     * Process a single sample
     *
     * @param sample the sample to process
     * @return the processed sample
     */
    public double process(double sample) {
        double result = 0.0;

        // Process
        for (int i = 1; i <= order; i++) {
            result += (coeffsB[i] * historyX[i - 1] - coeffsA[i] * historyY[i - 1]);
        }
        result = (result + coeffsB[0] * sample) / coeffsA[0];

        // Feedback
        for (int i = order - 1; i > 0; i--) {
            historyX[i] = historyX[i - 1];
            historyY[i] = historyY[i - 1];
        }

        historyX[0] = sample;
        historyY[0] = result;

        return result;
    }
}

