package MyTime;

import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 *
 * @author GIA KINH
 */
public class MyTime {
    private int hour;
    private int minute;
    private int second;

    public MyTime(int hour, int minute, int second) {
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    public int getHour() {
        return hour;
    }

    public void setHour(int hour) {
        this.hour = hour;
    }

    public int getMinute() {
        return minute;
    }

    public void setMinute(int minute) {
        this.minute = minute;
    }

    public int getSecond() {
        return second;
    }

    public void setSecond(int second) {
        this.second = second;
    }

    public void setTime(int hour, int minute, int second){
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    @Override
    public String toString() {
        String timeString = String.format("%d:%d:%d", hour, minute, second);
        Date time= null;
        try {
            time = new SimpleDateFormat("HH:mm:ss").parse(timeString);
        } catch (ParseException ex) {
            Logger.getLogger(MyTime.class.getName()).log(Level.SEVERE, null, ex);
        }
        timeString = new SimpleDateFormat("HH:mm:ss").format(time);
        return timeString;
    }

    public MyTime nextHour(){
        this.hour++;
        return this;
    }

    public MyTime nextMinute(){
        this.minute++;
        return this;
    }

    public MyTime nextSecond(){
        this.second++;
        return this;
    }


    public MyTime previousHour(){
        this.hour--;
        return this;
    }

    public MyTime previousMinute(){
        this.minute--;
        return this;
    }

    public MyTime previousSecond(){
        this.second--;
        return this;
    }   
}

class TestMyTime{
    public static void main(String[] args) {
        MyTime myTime = new MyTime(23,59,59);
        System.out.println(myTime);
        myTime.nextHour();
        System.out.println(myTime);
        myTime.nextSecond();
        System.out.println(myTime);
    }
}

/**
 * Generates all UNIQUE permutations of a string, even when duplicate characters exist.
 *
 * Example:
 *   Input: "AAB"
 *   Output: ["AAB", "ABA", "BAA"]
 *
 * Time Complexity: O(n! * n)
 */
public final class UniquePermutation {

    private UniquePermutation() {
        // Prevent instantiation
        throw new UnsupportedOperationException("Utility class");
    }

    public static List<String> generateUniquePermutations(String input) {
        List<String> result = new ArrayList<>();
        if (input == null) {
            return result;
        }

        char[] chars = input.toCharArray();
        Arrays.sort(chars); // important: sort to detect duplicates

        backtrack(chars, new boolean[chars.length], new StringBuilder(), result);
        return result;
    }

    private static void backtrack(char[] chars, boolean[] used, StringBuilder current, List<String> result) {

        if (current.length() == chars.length) {
            result.add(current.toString());
            return;
        }

        for (int i = 0; i < chars.length; i++) {

            // skip duplicates
            if (i > 0 && chars[i] == chars[i - 1] && !used[i - 1]) {
                continue;
            }

            if (!used[i]) {
                used[i] = true;
                current.append(chars[i]);

                backtrack(chars, used, current, result);

                // undo changes
                used[i] = false;
                current.deleteCharAt(current.length() - 1);
            }
        }
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * The Needleman–Wunsch algorithm performs global sequence alignment between two strings.
 * It computes the optimal alignment score using dynamic programming,
 * given a scoring scheme for matches, mismatches, and gaps.
 *
 * Time Complexity: O(n * m)
 * Space Complexity: O(n * m)
 */
public final class NeedlemanWunsch {

    private NeedlemanWunsch() {
        // Utility Class
    }

    /**
     * Computes the Needleman–Wunsch global alignment score between two strings.
     *
     * @param s1 the first string
     * @param s2 the second string
     * @param matchScore score for a character match
     * @param mismatchPenalty penalty for a mismatch (should be negative)
     * @param gapPenalty penalty for inserting a gap (should be negative)
     * @return the optimal alignment score
     */
    public static int align(String s1, String s2, int matchScore, int mismatchPenalty, int gapPenalty) {
        if (s1 == null || s2 == null) {
            throw new IllegalArgumentException("Input strings must not be null.");
        }

        int n = s1.length();
        int m = s2.length();

        int[][] dp = new int[n + 1][m + 1];

        // Initialize gap penalties for first row and column
        for (int i = 0; i <= n; i++) {
            dp[i][0] = i * gapPenalty;
        }
        for (int j = 0; j <= m; j++) {
            dp[0][j] = j * gapPenalty;
        }

        // Fill the DP matrix
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                int matchOrMismatch = (s1.charAt(i - 1) == s2.charAt(j - 1)) ? matchScore : mismatchPenalty;

                dp[i][j] = Math.max(Math.max(dp[i - 1][j - 1] + matchOrMismatch, // match/mismatch
                                        dp[i - 1][j] + gapPenalty // deletion (gap in s2)
                                        ),
                    dp[i][j - 1] + gapPenalty // insertion (gap in s1)
                );
            }
        }

        return dp[n][m];
    }
}

package userdefined;

// Custom checked exception used to demonstrate user-defined error types.
public class OzellesmisIstisna extends Exception {

    // Version marker required for Serializable compatibility
    private static final long serialVersionUID = 1L;

    // The descriptive text carried by this exception
    private final String detail;

    // Constructor forwards the message to the base Exception and keeps a copy
    public OzellesmisIstisna(String detail) {
        super(detail);
        this.detail = detail;
    }

    @Override
    public String getMessage() {
        return detail;
    }

    /**
     * Demonstrates several scenarios involving this custom exception.
     */
    public static void main(String[] args) {

        System.out.println("1. Ornek: Basit bir istisna firlatma ve yakalama");
        try {
            throw new OzellesmisIstisna("Bu bir ozel istisnadir");
        } catch (OzellesmisIstisna ex) {
            System.out.println("Hata Mesaji: " + ex.getMessage());
        }

        System.out.println("2. Ornek: Istisna baska bir metot icinde firlatiliyor");
        try {
            triggerFailure();
        } catch (OzellesmisIstisna ex) {
            System.out.println("Metottan Gelen Hata: " + ex.getMessage());
        }

        System.out.println("3. Ornek: Birden fazla istisna durumunu kontrol etme");
        try {
            validateNonNegative(-5);
        } catch (OzellesmisIstisna ex) {
            System.out.println("Kontrol Hatasi: " + ex.getMessage());
        }

        System.out.println("4. Ornek: Normal akis");
        try {
            validateNonNegative(10);
            System.out.println("Hata yok, islem basariyla tamamlandi!");
        } catch (OzellesmisIstisna ex) {
            System.out.println("Hata: " + ex.getMessage());
        }
    }

    /**
     * Always raises the custom exception; used to show propagation.
     * @throws OzellesmisIstisna unconditionally
     */
    public static void triggerFailure() throws OzellesmisIstisna {
        throw new OzellesmisIstisna("Bu metot her zaman bir istisna firlatir!");
    }

    /**
     * Rejects negative numbers by throwing the custom exception.
     * @param value number to validate
     * @throws OzellesmisIstisna if value is negative
     */
    public static void validateNonNegative(int value) throws OzellesmisIstisna {
        if (value < 0) {
            throw new OzellesmisIstisna("Gecersiz sayi: " + value + ". Sifirdan kucuk olamaz.");
        }
    }
}

package com.thealgorithms.audiofilters;

/**
 * Exponential Moving Average (EMA) Filter for smoothing audio signals.
 *
 * <p>This filter applies an exponential moving average to a sequence of audio
 * signal values, making it useful for smoothing out rapid fluctuations.
 * The smoothing factor (alpha) controls the degree of smoothing.
 *
 * <p>Based on the definition from
 * <a href="https://en.wikipedia.org/wiki/Moving_average">Wikipedia link</a>.
 */
public class EMAFilter {
    private final double alpha;
    private double emaValue;
    /**
     * Constructs an EMA filter with a given smoothing factor.
     *
     * @param alpha Smoothing factor (0 < alpha <= 1)
     * @throws IllegalArgumentException if alpha is not in (0, 1]
     */
    public EMAFilter(double alpha) {
        if (alpha <= 0 || alpha > 1) {
            throw new IllegalArgumentException("Alpha must be between 0 and 1.");
        }
        this.alpha = alpha;
        this.emaValue = 0.0;
    }
    /**
     * Applies the EMA filter to an audio signal array.
     *
     * @param audioSignal Array of audio samples to process
     * @return Array of processed (smoothed) samples
     */
    public double[] apply(double[] audioSignal) {
        if (audioSignal.length == 0) {
            return new double[0];
        }
        double[] emaSignal = new double[audioSignal.length];
        emaValue = audioSignal[0];
        emaSignal[0] = emaValue;
        for (int i = 1; i < audioSignal.length; i++) {
            emaValue = alpha * audioSignal[i] + (1 - alpha) * emaValue;
            emaSignal[i] = emaValue;
        }
        return emaSignal;
    }
}

