public class ChatServer {

    // Tum client isimlerini saklar, boylece tekrar eden isimler engellenebilir.
    private static Set<String> names = new HashSet<>();

    // Tum client'lar icin PrintWriter'lari saklar, yayini yapmak icin kullanilir.
    private static Set<PrintWriter> writers = new HashSet<>();

    // Main metod, server'i baslatir
    public static void main(String[] args) throws Exception {
        System.out.println("Chat server calisiyor...");
        var pool = Executors.newFixedThreadPool(500); // 500 thread'lik bir havuz olusturur

        try (var listener = new ServerSocket(59001)) { // Sunucuyu dinlemeye baslar
            System.out.println(listener.getInetAddress().toString());
            while (true) {
                // Her client baglantisi icin yeni bir thread baslatir
                pool.execute(new Handler(listener.accept()));
            }
        }
    }

    // Handler sinifi, her client icin yeni bir thread olarak calisir
    private static class Handler implements Runnable {
        private String name; // Client'in adi
        private Socket socket; // Client ile baglanti icin socket
        private PrintWriter out; // Client'a mesaj gondermek icin PrintWriter

        public Handler(Socket socket) {
            this.socket = socket;
        }

        // Her bir client icin run metodu calistirilir
        public void run() {
            try (var in = new Scanner(socket.getInputStream())) { // Client'tan gelen veriyi okur
                out = new PrintWriter(socket.getOutputStream(), true); // Client'a veri gondermek icin cikti stream'i

                // Kullanicidan benzersiz bir isim alana kadar istek yapmaya devam et.
                while (true) {
                    out.println("SUBMITNAME"); // isim iste
                    name = in.nextLine(); // Kullanicinin ismini al
                    if (name == null) {
                        return; // isim bossa cik
                    }
                    synchronized (names) { // Erisim kontrolu icin synchronized
                        // Eger isim bos degilse ve daha once alinmamissa, ismi kabul et
                        if (!name.isBlank() && !names.contains(name)) {
                            names.add(name); // isimleri ekle
                            break; // Donguden cik
                        }
                    }
                }

                out.println("NAMEACCEPTED " + name); // isim kabul edildi mesajini gonder
                // Tum client'lara, yeni bir kullanicinin katildigini bildir
                for (PrintWriter writer : writers) {
                    writer.println("MESSAGE " + name + " katildi");
                }
                writers.add(out); // Yeni client'in PrintWriter'ini ekle

                // Client'tan gelen mesajlari al ve yayini yap.
                while (true) {
                    String input = in.nextLine(); // Client'tan mesaj al
                    if (input.toLowerCase().startsWith("/quit")) { // "/quit" komutunu gorurse cik
                        return;
                    }
                    // Mesaji tum client'lara yayinla
                    for (PrintWriter writer : writers) {
                        writer.println("MESSAGE " + name + ": " + input);
                    }
                }
            } catch (Exception e) {
                System.out.println(e); // Hata mesajini yazdir
            } finally {
                // Baglanti sonlandiginda kaynaklari temizle
                if (out != null) {
                    writers.remove(out); // cikis yapan client'in PrintWriter'ini listeden cikar
                }
                if (name != null) {
                    System.out.println(name + " ayriliyor"); // Client'in ayrildigini konsola yaz
                    names.remove(name); // isimler listesinden cikar
                    // Tum client'lara, bu kullanicinin ayrildigini bildir
                    for (PrintWriter writer : writers) {
                        writer.println("MESSAGE " + name + " ayrildi");
                    }
                }
                try {
                    socket.close(); // Socket'i kapat
                } catch (IOException e) {
                    System.out.println("Socket kapatilirken hata: " + e.getMessage()); // Socket kapanirken hata olursa mesaj yaz
                }
            }
        }
    }
}

// Example of a regular class (outside class cannot be static)
// Only inner classes can be static

// class Test { 
//     static String sharedName;  // Static variable - shared across ALL instances
//     public Test(String personName) {
//         Test.sharedName = personName;  // PROBLEM: This overwrites for ALL objects
//     }
// }

public class InnerClasses { 
    // Outer classes cannot be declared static in Java
    // Only inner classes (classes defined inside another class) can be static

    // Static Inner Class Example
    // When an inner class is static, it does NOT depend on the instance of the parent class
    // It can be instantiated independently without creating an outer class object first
    static class Person {
        String personName;  // Instance variable - each Person object has its own copy

        // Constructor for the static inner class
        public Person(String name) {
            this.personName = name;  // 'this' refers to the current Person object
        }

        // Method to display person's name
        public void displayName() {
            System.out.println("Person name: " + personName);
        }
    }

    public static void main(String[] args) {
        // Creating independent objects of the static inner class
        // No outer class instance needed because the inner class is static
        Person firstPerson = new Person("Kunal");
        Person secondPerson = new Person("Rahul");

        // Each object has its own independent 'personName' field
        // Unlike the commented example at the top (which used static variable causing overwrite)
        System.out.println("--- Static Inner Class Demonstration ---");
        System.out.println("First person's name: " + firstPerson.personName);   // Output: Kunal
        System.out.println("Second person's name: " + secondPerson.personName); // Output: Rahul

        // Demonstrating that they are independent objects
        System.out.println("\nAre both references pointing to same object? " + (firstPerson == secondPerson));
        System.out.println("First person hashcode: " + firstPerson.hashCode());
        System.out.println("Second person hashcode: " + secondPerson.hashCode());

        /* 
        Important Difference: Static vs Non-Static Inner Classes
        ========================================================

        When the inner class (Test) is NOT static, we need an instance of the enclosing class:

        InnerClasses outerInstance = new InnerClasses();
        InnerClasses.Person personObject = outerInstance.new Person("Kunal");

        Why? Because non-static inner classes have an implicit reference to the outer class instance.

        Static inner classes do NOT have this reference, so they can be created independently.
        */

        // Demonstration of why static variables can cause problems (commented)
        // If we used static String name (like in commented Test class above):
        // Test first = new Test("Kunal");
        // Test second = new Test("Rahul");
        // System.out.println(first.name);  // Would print "Rahul" (overwritten!)
        // System.out.println(second.name); // Would print "Rahul"

        /*
        Key Concepts Explained:
        =======================

        1. Static Inner Classes:
           - Can be instantiated without an outer class instance
           - Cannot access non-static members of the outer class directly
           - Are independent of the outer class instance

        2. Non-Static Inner Classes:
           - Require an instance of the outer class to be created
           - Have access to all members (including non-static) of the outer class
           - Maintain an implicit reference to the outer class instance

        3. Static Variables in Regular Classes:
           - Static variables are SHARED across all instances of a class
           - Modifying a static variable affects ALL objects
           - Belong to the class itself, not to any specific object

        4. Why Outer Classes Cannot Be Static:
           - 'static' at class level only makes sense for inner classes
           - Top-level classes are implicitly at the package level
           - Making a top-level class static would be redundant
        */
    }
}

package com.thealgorithms.ciphers;

/**
 * A Java implementation of Caesar Cipher. /It is a type of substitution cipher
 * in which each letter in the plaintext is replaced by a letter some fixed
 * number of positions down the alphabet. /
 *
 * @author FAHRI YARDIMCI
 * @author khalil2535
 */
public class Caesar {
    private static char normalizeShift(final int shift) {
        return (char) (shift % 26);
    }

    /**
     * Encrypt text by shifting every Latin char by add number shift for ASCII
     * Example : A + 1 -> B
     *
     * @return Encrypted message
     */
    public String encode(String message, int shift) {
        StringBuilder encoded = new StringBuilder();

        final char shiftChar = normalizeShift(shift);

        final int length = message.length();
        for (int i = 0; i < length; i++) {
            //            int current = message.charAt(i); //using char to shift characters because
            //            ascii
            // is in-order latin alphabet
            char current = message.charAt(i); // Java law : char + int = char

            if (isCapitalLatinLetter(current)) {
                current += shiftChar;
                encoded.append((char) (current > 'Z' ? current - 26 : current)); // 26 = number of latin letters
            } else if (isSmallLatinLetter(current)) {
                current += shiftChar;
                encoded.append((char) (current > 'z' ? current - 26 : current)); // 26 = number of latin letters
            } else {
                encoded.append(current);
            }
        }
        return encoded.toString();
    }

    /**
     * Decrypt message by shifting back every Latin char to previous the ASCII
     * Example : B - 1 -> A
     *
     * @return message
     */
    public String decode(String encryptedMessage, int shift) {
        StringBuilder decoded = new StringBuilder();

        final char shiftChar = normalizeShift(shift);

        final int length = encryptedMessage.length();
        for (int i = 0; i < length; i++) {
            char current = encryptedMessage.charAt(i);
            if (isCapitalLatinLetter(current)) {
                current -= shiftChar;
                decoded.append((char) (current < 'A' ? current + 26 : current)); // 26 = number of latin letters
            } else if (isSmallLatinLetter(current)) {
                current -= shiftChar;
                decoded.append((char) (current < 'a' ? current + 26 : current)); // 26 = number of latin letters
            } else {
                decoded.append(current);
            }
        }
        return decoded.toString();
    }

    /**
     * @return true if character is capital Latin letter or false for others
     */
    private static boolean isCapitalLatinLetter(char c) {
        return c >= 'A' && c <= 'Z';
    }

    /**
     * @return true if character is small Latin letter or false for others
     */
    private static boolean isSmallLatinLetter(char c) {
        return c >= 'a' && c <= 'z';
    }

    /**
     *  @return string array which contains all the possible decoded combination.
     */
    public String[] bruteforce(String encryptedMessage) {
        String[] listOfAllTheAnswers = new String[27];
        for (int i = 0; i <= 26; i++) {
            listOfAllTheAnswers[i] = decode(encryptedMessage, i);
        }

        return listOfAllTheAnswers;
    }
}

/**
 * Exponential Moving Average (EMA) Filter for smoothing audio signals.
 *
 * <p>This filter applies an exponential moving average to a sequence of audio
 * signal values, making it useful for smoothing out rapid fluctuations.
 * The smoothing factor (alpha) controls the degree of smoothing.
 *
 * <p>Based on the definition from
 * <a href="https://en.wikipedia.org/wiki/Moving_average">Wikipedia link</a>.
 */
public class EMAFilter {
    private final double alpha;
    private double emaValue;
    /**
     * Constructs an EMA filter with a given smoothing factor.
     *
     * @param alpha Smoothing factor (0 < alpha <= 1)
     * @throws IllegalArgumentException if alpha is not in (0, 1]
     */
    public EMAFilter(double alpha) {
        if (alpha <= 0 || alpha > 1) {
            throw new IllegalArgumentException("Alpha must be between 0 and 1.");
        }
        this.alpha = alpha;
        this.emaValue = 0.0;
    }
    /**
     * Applies the EMA filter to an audio signal array.
     *
     * @param audioSignal Array of audio samples to process
     * @return Array of processed (smoothed) samples
     */
    public double[] apply(double[] audioSignal) {
        if (audioSignal.length == 0) {
            return new double[0];
        }
        double[] emaSignal = new double[audioSignal.length];
        emaValue = audioSignal[0];
        emaSignal[0] = emaValue;
        for (int i = 1; i < audioSignal.length; i++) {
            emaValue = alpha * audioSignal[i] + (1 - alpha) * emaValue;
            emaSignal[i] = emaValue;
        }
        return emaSignal;
    }
}

package com.ankan.generics;

import java.util.ArrayList;
import java.util.function.Consumer;

public class LambdaFunctions {
    public static void main(String[] args) {
        // lambda functions are one-line/in-line function
        ArrayList<Integer> arr = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            arr.add(i + 1);
        }

//        arr.forEach((item) -> System.out.println(item * 2)); Consumer Type

        Consumer<Integer> fun = (item) -> System.out.println(item * 2);
        arr.forEach(fun);

        Operation sum = (a, b) -> a + b;
        Operation prod = (a, b) -> a * b;
        Operation sub = (a, b) -> a - b;

        LambdaFunctions myCalculator = new LambdaFunctions();
        System.out.println(myCalculator.operate(5, 3, sum));
        System.out.println(myCalculator.operate(5, 3, prod));
        System.out.println(myCalculator.operate(5, 3, sub));
    }
    private int operate(int a, int b, Operation op) {
        return op.operation(a, b);
    }
}
interface Operation {
    int operation(int a, int b);
}

package com.thealgorithms.geometry;

import java.awt.Point;
import java.util.ArrayList;
import java.util.List;

/**
 * The {@code BresenhamLine} class implements the Bresenham's line algorithm,
 * which is an efficient way to determine the points of a straight line
 * between two given points in a 2D space.
 *
 * <p>This algorithm uses integer arithmetic to calculate the points,
 * making it suitable for rasterization in computer graphics.</p>
 *
 * For more information, please visit {@link https://en.wikipedia.org/wiki/Bresenham%27s_line_algorithm}
 */
public final class BresenhamLine {

    private BresenhamLine() {
        // Private constructor to prevent instantiation.
    }

    /**
     * Finds the list of points that form a straight line between two endpoints.
     *
     * @param x0 the x-coordinate of the starting point
     * @param y0 the y-coordinate of the starting point
     * @param x1 the x-coordinate of the ending point
     * @param y1 the y-coordinate of the ending point
     * @return a {@code List<Point>} containing all points on the line
     */
    public static List<Point> findLine(int x0, int y0, int x1, int y1) {
        List<Point> line = new ArrayList<>();

        // Calculate differences and steps for each axis
        int dx = Math.abs(x1 - x0); // Change in x
        int dy = Math.abs(y1 - y0); // Change in y
        int sx = (x0 < x1) ? 1 : -1; // Step in x direction
        int sy = (y0 < y1) ? 1 : -1; // Step in y direction
        int err = dx - dy; // Initial error term

        // Loop until we reach the endpoint
        while (true) {
            line.add(new Point(x0, y0)); // Add current point to the line

            // Check if we've reached the endpoint
            if (x0 == x1 && y0 == y1) {
                break; // Exit loop if endpoint is reached
            }

            // Calculate error term doubled for decision making
            final int e2 = err * 2;

            // Adjust x coordinate if necessary
            if (e2 > -dy) {
                err -= dy; // Update error term
                x0 += sx; // Move to next point in x direction
            }

            // Adjust y coordinate if necessary
            if (e2 < dx) {
                err += dx; // Update error term
                y0 += sy; // Move to next point in y direction
            }
        }

        return line; // Return the list of points forming the line
    }
}

/**
 * This class is the nodes of the SinglyLinked List. They consist of a value and
