/**
 * DynamicProgramming solution for the Egg Dropping Puzzle
 */
public final class EggDropping {
    private EggDropping() {
    }

    // min trials with n eggs and m floors
    public static int minTrials(int n, int m) {
        int[][] eggFloor = new int[n + 1][m + 1];
        int result;
        int x;

        for (int i = 1; i <= n; i++) {
            eggFloor[i][0] = 0; // Zero trial for zero floor.
            eggFloor[i][1] = 1; // One trial for one floor
        }

        // j trials for only 1 egg
        for (int j = 1; j <= m; j++) {
            eggFloor[1][j] = j;
        }

        // Using bottom-up approach in DP
        for (int i = 2; i <= n; i++) {
            for (int j = 2; j <= m; j++) {
                eggFloor[i][j] = Integer.MAX_VALUE;
                for (x = 1; x <= j; x++) {
                    result = 1 + Math.max(eggFloor[i - 1][x - 1], eggFloor[i][j - x]);

                    // choose min of all values for particular x
                    if (result < eggFloor[i][j]) {
                        eggFloor[i][j] = result;
                    }
                }
            }
        }

        return eggFloor[n][m];
    }

    public static void main(String[] args) {
        int n = 2;
        int m = 4;
        // result outputs min no. of trials in worst case for n eggs and m floors
        int result = minTrials(n, m);
        System.out.println(result);
    }
}

public class SifiraBolmeHatasi {

    public static void main(String[] args) {

        // Simulated input pair, second value causes a division-by-zero
        String[] values = {"10", "0"};

        try {
            int numerator = Integer.parseInt(values[0]);
            int denominator = Integer.parseInt(values[1]);

            int result = numerator / denominator;
            System.out.println("Sonuc: " + result);

        } catch (NumberFormatException nfe) {
            System.out.println("Gecersiz giris: Lutfen sadece tamsayi giriniz.");
            System.out.println("Istisna mesaji: " + nfe.getMessage());
            nfe.printStackTrace();

        } catch (ArithmeticException ae) {
            System.out.println("Sifira bolme hatasi olustu!");
            System.out.println("Istisna mesaji: " + ae.getMessage());
            ae.printStackTrace();

        } catch (ArrayIndexOutOfBoundsException aioobe) {
            System.out.println("Eksik giris: Lutfen iki sayi giriniz.");
            System.out.println("Istisna mesaji: " + aioobe.getMessage());
            aioobe.printStackTrace();

        } finally {
            System.out.println("Finally bloguna girildi!");
        }

        try {
            successfulPathDemo();
        } catch (Exception unexpected) {
            System.out.println("Beklenmeyen bir hata: " + unexpected.getMessage());
        }
    }

    /**
     * Runs a division that is guaranteed to succeed.
     */
    public static void successfulPathDemo() {
        System.out.println("Basarili akis testi calisiyor.");
        int a = 10;
        int b = 5;
        int outcome = a / b;
        System.out.println("10 / 5 = " + outcome);
        System.out.println("Her sey yolunda, istisna firlatilmadi!");
    }
}

