/**
 * This example program shows how AES encryption and decryption can be done in
 * Java. Please note that secret key and encrypted text is unreadable binary and
 * hence in the following program we display it in hexadecimal format of the
 * underlying bytes.
 */
public final class AESEncryption {
private AESEncryption() {
}

private static final char[] HEX_SYMBOLS = "0123456789ABCDEF".toCharArray();
private static Cipher aesCipherInstance;

/**
 * 1. Generate a plain text for encryption 2. Get a secret key (printed in
 * hexadecimal form). In actual use this must be encrypted and kept safe.
 * The same key is required for decryption.
 */
public static void main(String[] args) throws Exception {
String inputMessage = "Hello World";
SecretKey secretKeyData = getSecretEncryptionKey();
byte[] encryptedBytes = encryptText(inputMessage, secretKeyData);
String decryptedMessage = decryptText(encryptedBytes, secretKeyData);
System.out.println("Original Text:" + inputMessage);
System.out.println("AES Key (Hex Form):" + bytesToHex(secretKeyData.getEncoded()));
System.out.println("Encrypted Text (Hex Form):" + bytesToHex(encryptedBytes));
System.out.println("Decryption successful. Decrypted text matches original: " + decryptedMessage.equals(inputMessage));
}

/**
 * gets the AES encryption key. In your actual programs, this should be
 * safely stored.
 *
 * @return secKey (Secret key that we encrypt using it)
 * @throws NoSuchAlgorithmException (from KeyGenrator)
 */
public static SecretKey getSecretEncryptionKey() throws NoSuchAlgorithmException {
KeyGenerator keyGenerator = KeyGenerator.getInstance("AES");
keyGenerator.init(128);
return keyGenerator.generateKey();
}

/**
 * Encrypts plainText in AES using the secret key
 *
 * @return byteCipherText (The encrypted text)
 * @throws NoSuchPaddingException (from Cipher)
 * @throws NoSuchAlgorithmException (from Cipher)
 * @throws InvalidKeyException (from Cipher)
 * @throws BadPaddingException (from Cipher)
 * @throws IllegalBlockSizeException (from Cipher)
 */
public static byte[] encryptText(String inputData, SecretKey secretKeyData) throws NoSuchAlgorithmException, NoSuchPaddingException, InvalidKeyException, IllegalBlockSizeException, BadPaddingException {
aesCipherInstance = Cipher.getInstance("AES/GCM/NoPadding");
aesCipherInstance.init(Cipher.ENCRYPT_MODE, secretKeyData);
return aesCipherInstance.doFinal(inputData.getBytes());
}

/**
 * Decrypts encrypted byte array using the key used for encryption.
 *
 * @return plainText
 */
public static String decryptText(byte[] encryptedData, SecretKey secretKeyData) throws NoSuchAlgorithmException, NoSuchPaddingException, InvalidKeyException, IllegalBlockSizeException, BadPaddingException, InvalidAlgorithmParameterException {
Cipher decryptionCipher = Cipher.getInstance("AES/GCM/NoPadding");
GCMParameterSpec gcmSpec = new GCMParameterSpec(128, aesCipherInstance.getIV());
decryptionCipher.init(Cipher.DECRYPT_MODE, secretKeyData, gcmSpec);
byte[] decodedBytes = decryptionCipher.doFinal(encryptedData);
return new String(decodedBytes);
}

/**
 * Convert a binary byte array into readable hex form Old library is
 * deprecated on OpenJdk 11 and this is faster regarding other solution is
 * using StringBuilder
 *
 * @return hexHash
 */
public static String bytesToHex(byte[] binaryData) {
char[] hexCharsResult = new char[binaryData.length * 2];
for (int position = 0; position < binaryData.length; position++) {
int byteValue = binaryData[position] & 0xFF;
hexCharsResult[position * 2] = HEX_SYMBOLS[byteValue >>> 4];
hexCharsResult[position * 2 + 1] = HEX_SYMBOLS[byteValue & 0x0F];
}
return new String(hexCharsResult);
}
}

public class EklemeliSiralama {

    public static void sirala(int[] dizi) {
        // Diziyi sirala
        for (int i = 1; i < dizi.length; i++) {
            int gecici = dizi[i];
            int j = i - 1;

            // Elemani dogru konuma yerlestir
            while (j >= 0 && dizi[j] > gecici) {
                dizi[j + 1] = dizi[j];
                j--;
            }
            dizi[j + 1] = gecici;
        }
    }

    public static void main(String[] args) {
        // 10 rastgele elemandan olusan bir dizi olustur
        int[] sayilar = new int[20];
        for (int i = 0; i < sayilar.length; i++) {
            sayilar[i] = (int)(Math.random() * 100);
        }

        System.out.print("Orjinal: ");
        for (int i = 0; i < sayilar.length; i++) {
            System.out.print(sayilar[i] + " ");
        }
        System.out.println();

        // Diziyi sirala
        EklemeliSiralama.sirala(sayilar);

        System.out.print("Sirali : ");
        // Siralanmis diziyi yazdir
        for (int i = 0; i < sayilar.length; i++) {
            System.out.print(sayilar[i] + " ");
        }
        System.out.println();
    }
}

/**
 * Node class represents a graph node in the M-Coloring problem.
 * Each node is initially assigned color 1 and contains a set of edges
 * representing its adjacent nodes (neighbors in the graph).
 *
 * @author Bama Charan Chhandogi (https://github.com/BamaCharanChhandogi)
 */
class GraphNode {
    int assignedColor = 1;      // Initial color for each node (starts with color 1)
    Set<Integer> neighborEdges = new HashSet<>();   // Set of adjacent node indices

    /**
     * Returns the current color of this node.
     *
     * @return The color value assigned to this node
     */
    public int getAssignedColor() {
        return assignedColor;
    }

    /**
     * Sets the color of this node and updates the maximum color if needed.
     *
     * @param newColor New color value to assign
     * @return The new color value
     */
    public int setAssignedColor(int newColor) {
        this.assignedColor = newColor;
        return this.assignedColor;
    }

    /**
     * Increments the node's color by 1 (used when color conflict is detected).
     *
     * @return The new color value after increment
     */
    public int incrementColor() {
        this.assignedColor++;
        return this.assignedColor;
    }

    /**
     * Adds an edge to another node.
     *
     * @param neighborIndex Index of the neighboring node
     */
    public void addNeighbor(int neighborIndex) {
        neighborEdges.add(neighborIndex);
    }

    /**
     * Checks if this node has a neighbor with the specified index.
     *
     * @param nodeIndex Index to check
     * @return true if neighbor exists, false otherwise
     */
    public boolean hasNeighbor(int nodeIndex) {
        return neighborEdges.contains(nodeIndex);
    }

    /**
     * Returns the number of neighbors (degree) of this node.
     *
     * @return The number of adjacent nodes
     */
    public int getDegree() {
        return neighborEdges.size();
    }
}

/**
 * M-Coloring algorithm solves the Graph Coloring problem:
 * Determine if it's possible to color a graph using at most M colors such that
 * no two adjacent nodes share the same color.
 * 
 * <p><b>Problem Statement:</b><br>
 * Given an undirected graph and a number M, determine if the graph can be
 * colored with at most M colors such that no two adjacent vertices have
 * the same color.</p>
 * 
 * <p><b>Algorithm Explanation:</b><br>
 * This implementation uses BFS traversal with greedy coloring:
 * <ol>
 *   <li>Start with all nodes having color 1</li>
 *   <li>Traverse the graph using BFS</li>
 *   <li>When an adjacent node has same color, increment its color</li>
 *   <li>Track maximum color used</li>
 *   <li>If max color exceeds M, coloring is impossible</li>
 * </ol>
 * </p>
 * 
 * <p><b>Time Complexity:</b> O(V + E) where V is vertices and E is edges</p>
 * 
 * <p><b>Space Complexity:</b> O(V) for visited array and queue</p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Graph_coloring">Graph Coloring (Wikipedia)</a>
 */
public final class MColoring {

    // Private constructor to prevent instantiation (utility class)
    private MColoring() {
        throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
    }

    /**
     * Determines whether it's possible to color the graph using at most M colors.
     * 
     * <p>The algorithm uses BFS traversal to process all components of the graph
     * (handling disconnected graphs). When two adjacent nodes share the same color,
     * the neighbor's color is incremented.</p>
     *
     * @param graphNodes List of nodes representing the graph (index 0 is unused, nodes start from 1)
     * @param totalNodes The total number of nodes in the graph (n)
     * @param maxAllowedColors The maximum number of allowed colors (M)
     * @return true if the graph can be colored using ≤ M colors, false otherwise
     * @throws IllegalArgumentException if graphNodes is null or size is invalid
     */
    public static boolean canColorGraph(ArrayList<GraphNode> graphNodes, int totalNodes, int maxAllowedColors) {
        // Validate input parameters
        if (graphNodes == null) {
            throw new IllegalArgumentException("Graph nodes list cannot be null");
        }

        if (totalNodes < 1) {
            throw new IllegalArgumentException("Total nodes must be at least 1");
        }

        if (maxAllowedColors < 1) {
            throw new IllegalArgumentException("Maximum colors must be at least 1");
        }

        if (graphNodes.size() < totalNodes + 1) {
            throw new IllegalArgumentException("Graph nodes list size insufficient for total nodes");
        }

        // Visited array keeps track of whether each node has been processed in BFS
        int[] visitedStatus = new int[totalNodes + 1];  // Index 0 unused, nodes 1..n

        // Track the maximum number of colors used so far
        int currentMaxColors = 1;

        // Special case: Single node can always be colored with 1 color
        if (totalNodes == 1) {
            return maxAllowedColors >= 1;
        }

        // Process all nodes to handle disconnected graphs
        for (int startNode = 1; startNode <= totalNodes; startNode++) {
            // Skip already visited nodes
            if (visitedStatus[startNode] > 0) {
                continue;
            }

            // Start BFS from this unvisited node
            visitedStatus[startNode] = 1;  // Mark as visited
            Queue<Integer> bfsQueue = new LinkedList<>();
            bfsQueue.add(startNode);

            // BFS traversal to process connected component
            while (!bfsQueue.isEmpty()) {
                int currentNode = bfsQueue.poll();
                GraphNode currentGraphNode = graphNodes.get(currentNode);

                // Check all adjacent nodes (neighbors)
                for (int neighborNode : currentGraphNode.neighborEdges) {
                    GraphNode neighborGraphNode = graphNodes.get(neighborNode);

                    // Color conflict resolution: if adjacent nodes share same color,
                    // increment the neighbor's color to avoid conflict
                    if (currentGraphNode.assignedColor == neighborGraphNode.assignedColor) {
                        neighborGraphNode.incrementColor();
                    }

                    // Update the maximum number of colors used
                    currentMaxColors = Math.max(currentMaxColors, 
                                                Math.max(currentGraphNode.assignedColor, 
                                                        neighborGraphNode.assignedColor));

                    // Early termination: if colors exceed limit, no solution exists
                    if (currentMaxColors > maxAllowedColors) {
                        return false;
                    }

                    // Add unvisited neighbor to queue for further processing
                    if (visitedStatus[neighborNode] == 0) {
                        visitedStatus[neighborNode] = 1;
                        bfsQueue.add(neighborNode);
                    }
                }
            }
        }

        // All nodes processed without exceeding color limit
        return true;
    }

    /**
     * Determines the minimum number of colors needed to color the graph
     * (the chromatic number) using a greedy BFS approach.
     * 
     * <p>Note: This is a heuristic approximation and may not always find the
     * true chromatic number for complex graphs. For exact computation,
     * use backtracking-based algorithms.</p>
     *
     * @param graphNodes List of nodes representing the graph
     * @param totalNodes The total number of nodes in the graph
     * @return The chromatic number (minimum colors needed)
     */
    public static int findChromaticNumber(ArrayList<GraphNode> graphNodes, int totalNodes) {
        // Make a deep copy to avoid modifying the original graph
        ArrayList<GraphNode> workingCopy = deepCopyGraph(graphNodes, totalNodes);

        int lowerBound = 1;
        int upperBound = totalNodes;  // Worst case: complete graph needs n colors

        // Binary search to find the smallest M that works
        while (lowerBound < upperBound) {
            int midColor = (lowerBound + upperBound) / 2;

            // Reset colors for testing (since algorithm modifies colors)
            resetNodeColors(workingCopy);

            if (canColorGraph(workingCopy, totalNodes, midColor)) {
                upperBound = midColor;  // Try with fewer colors
            } else {
                lowerBound = midColor + 1;  // Need more colors
            }
        }

        return lowerBound;
    }

    /**
     * Constructs a graph from adjacency list representation.
     * This is a convenience method for creating test graphs.
     *
     * @param adjacencyList Adjacency list where index i contains neighbors of node i
     * @param totalNodes Number of nodes in the graph
     * @return ArrayList of GraphNode objects representing the graph
     */
    public static ArrayList<GraphNode> buildGraphFromAdjacencyList(int[][] adjacencyList, int totalNodes) {
        ArrayList<GraphNode> graphNodes = new ArrayList<>(totalNodes + 1);

        // Initialize nodes (index 0 is dummy)
        graphNodes.add(null);  // Index 0 unused
        for (int nodeIndex = 1; nodeIndex <= totalNodes; nodeIndex++) {
            graphNodes.add(new GraphNode());
        }

        // Add edges to the graph
        for (int nodeIndex = 1; nodeIndex <= totalNodes; nodeIndex++) {
            for (int neighbor : adjacencyList[nodeIndex]) {
                graphNodes.get(nodeIndex).addNeighbor(neighbor);
            }
        }

        return graphNodes;
    }

    /**
     * Creates a deep copy of the graph nodes array.
     *
     * @param sourceNodes Original graph nodes
     * @param totalNodes Number of nodes
     * @return New ArrayList with copied nodes
     */
    private static ArrayList<GraphNode> deepCopyGraph(ArrayList<GraphNode> sourceNodes, int totalNodes) {
        ArrayList<GraphNode> copiedNodes = new ArrayList<>(totalNodes + 1);
        copiedNodes.add(null);  // Index 0 placeholder

        for (int nodeIndex = 1; nodeIndex <= totalNodes; nodeIndex++) {
            GraphNode originalNode = sourceNodes.get(nodeIndex);
            GraphNode newNode = new GraphNode();
            newNode.setAssignedColor(originalNode.getAssignedColor());

            // Copy all neighbors
            for (int neighbor : originalNode.neighborEdges) {
                newNode.addNeighbor(neighbor);
            }
            copiedNodes.add(newNode);
        }

        return copiedNodes;
    }

    /**
     * Resets all node colors to 1 (initial state).
     *
     * @param graphNodes Graph nodes to reset
     */
    private static void resetNodeColors(ArrayList<GraphNode> graphNodes) {
        for (int nodeIndex = 1; nodeIndex < graphNodes.size(); nodeIndex++) {
            if (graphNodes.get(nodeIndex) != null) {
                graphNodes.get(nodeIndex).setAssignedColor(1);
            }
        }
    }

    /**
     * Utility method to print the resulting colors of all nodes.
     *
     * @param graphNodes Graph nodes with assigned colors
     * @param totalNodes Number of nodes
     */
    public static void printColoringSolution(ArrayList<GraphNode> graphNodes, int totalNodes) {
        System.out.println("Graph Coloring Solution:");
        for (int nodeIndex = 1; nodeIndex <= totalNodes; nodeIndex++) {
            System.out.println("Node " + nodeIndex + " -> Color " + graphNodes.get(nodeIndex).getAssignedColor());
        }
    }
}

/*
COMPREHENSIVE DOCUMENTATION
===========================

GRAPH COLORING PROBLEM
======================

Problem Definition:
------------------
Given an undirected graph G = (V, E) and a number M, determine if it's possible
to assign colors to vertices such that:
1. Each vertex gets exactly one color
2. No two adjacent vertices share the same color
3. Total number of colors used ≤ M

Chromatic Number:
---------------
The chromatic number χ(G) is the smallest number of colors needed to color the graph.
Examples:
- Bipartite graph: χ = 2
- Complete graph K_n: χ = n
- Tree: χ = 2 (if |V| > 1)
- Cycle C_n: χ = 2 if n even, 3 if n odd

ALGORITHM VISUALIZATION
=======================

Example Graph:
-------------
    1 --- 2
    |     |
    3 --- 4

Adjacency:
1: [2, 3]
2: [1, 4]
3: [1, 4]
4: [2, 3]

Execution Steps:
---------------
Initialize all nodes with color 1

BFS from node 1:
- Current: node1 (color1=1)
  Check neighbors: node2 (color1=1) → conflict → node2.color = 2
                  node3 (color1=1) → conflict → node3.color = 2
  MaxColors = 2

- Current: node2 (color2=2)
  Check neighbor node4 (color1=1) → no conflict (2 ≠ 1)
  MaxColors remains 2

- Current: node3 (color2=2)
  Check neighbor node4 (color1=1) → no conflict (2 ≠ 1)

- Current: node4 (color1=1)
  No unprocessed neighbors

Result: Colors = {1:1, 2:2, 3:2, 4:1} → 2 colors needed

TIME COMPLEXITY ANALYSIS
=======================

| Operation | Complexity | Explanation |
|-----------|------------|-------------|
| BFS Traversal | O(V + E) | Each vertex and edge processed once |
| Color Check | O(1) per edge | Simple integer comparison |
| Color Increment | O(1) per conflict | Only when colors match |
| Overall | O(V + E) | Linear in graph size |

For disconnected graphs: Still O(V + E) total across all components.

SPACE COMPLEXITY
===============

| Component | Space Usage | Description |
|-----------|-------------|-------------|
| visited[] | O(V) | Array tracking processed nodes |
| Queue | O(V) | BFS queue (worst case: all vertices) |
| Graph storage | O(V + E) | Adjacency lists |
| Total | O(V + E) | Linear in graph size |

SPECIAL CASES
=============

| Graph Type | M Required | Algorithm Behavior |
|------------|------------|-------------------|
| Empty graph | 1 | All nodes color 1 |
| Complete graph | V | Each node gets unique color |
| Bipartite | 2 | Colors alternate between groups |
| Single node | 1 | Trivial coloring |
| Triangle | 3 | Colors: 1,2,3 |
| Star (K1,n) | 2 | Center color 1, leaves color 2 |

COMPARISON WITH OTHER APPROACHES
===============================

| Algorithm | Time Complexity | Space Complexity | Optimal? |
|-----------|----------------|------------------|----------|
| BFS Greedy (this) | O(V+E) | O(V) | No (heuristic) |
| Backtracking | O(M^V) | O(V) | Yes |
| DSATUR | O(V^2) | O(V) | Near-optimal |
| Branch & Bound | O(2^V) | O(V) | Yes (for small V) |

PRACTICAL APPLICATIONS
======================

1. Map Coloring:
   - Coloring countries/regions on a map
   - 4-color theorem guarantees 4 colors suffice

2. Register Allocation in Compilers:
   - Assign variables to CPU registers
   - Interference graph coloring

3. Scheduling Problems:
   - Exam scheduling (no student takes two exams at once)
   - Frequency assignment (avoid interference)

4. Timetabling:
   - Course scheduling with no conflicts
   - Employee shift assignment

5. Sudoku Solver:
   - Special case of graph coloring (9x9 grid)

6. Social Network Analysis:
   - Community detection via coloring
   - Conflict resolution

7. Wireless Networks:
   - Channel assignment to avoid interference
   - Frequency allocation

GRAPH COLORING THEOREMS
=======================

| Theorem | Statement |
|---------|-----------|
| 4-Color Theorem | Every planar graph is 4-colorable |
| Brooks' Theorem | χ(G) ≤ Δ except for complete graphs/odd cycles |
| Mycielski Construction | Creates triangle-free graphs with high chromatic number |
| Greedy Coloring Bound | χ(G) ≤ Δ + 1 (by greedy algorithm) |

WHY THIS ALGORITHM IS NOT OPTIMAL
================================

This greedy BFS algorithm is a heuristic that produces an upper bound on the
chromatic number but may not find the minimum. Example where it fails:

Graph: Even cycle C4 (square) with a diagonal
- Optimal coloring: 3 colors
- Greedy BFS might use: 4 colors

For exact solution, use backtracking (exponential time) for small graphs,
or branch-and-bound for medium graphs.

MODIFICATIONS FOR BETTER RESULTS
===============================

1. Vertex Ordering Heuristics:
   - Color highest-degree vertices first
   - More likely to find minimal coloring

2. DSATUR Algorithm:
   - Always color vertex with most differently-colored neighbors

3. Iterated Greedy:
   - Run multiple times with different vertex orders
   - Keep best solution

SAMPLE USAGE
===========

public static void main(String[] args) {
    // Create graph with 4 nodes
    ArrayList<GraphNode> graph = new ArrayList<>();
    graph.add(null);  // Index 0 unused

    for (int i = 1; i <= 4; i++) {
        graph.add(new GraphNode());
    }

    // Build edges (undirected)
    graph.get(1).addNeighbor(2);
    graph.get(1).addNeighbor(3);
    graph.get(2).addNeighbor(4);
    graph.get(3).addNeighbor(4);
    graph.get(2).addNeighbor(1);
    graph.get(3).addNeighbor(1);
    graph.get(4).addNeighbor(2);
    graph.get(4).addNeighbor(3);

    // Check if 2 colors are enough
    boolean possible = MColoring.canColorGraph(graph, 4, 2);
    System.out.println("Can color with 2 colors? " + possible);

    // Find chromatic number
    int chromaticNum = MColoring.findChromaticNumber(graph, 4);
    System.out.println("Chromatic number: " + chromaticNum);

    // Print solution
    MColoring.printColoringSolution(graph, 4);
}

FURTHER READING
===============

1. "Graph Coloring Problems" by Tommy R. Jensen and Bjarne Toft
2. "A Guide to Graph Colouring" by R. M. R. Lewis
3. "The Four-Color Theorem" by Rudolf Fritsch and Gerda Fritsch
4. "Computational Graph Theory" by Gottfried Tinhofer
*/

public class Fibonacci {

    // n. Fibonacci sayisini asagidan yukariya (iteratif) hesaplar
    public static int fibonacci(int n) {
        List<Integer> hesaplananlar = new ArrayList<>();
        hesaplananlar.add(0);
        hesaplananlar.add(1);

        int sayac = 2;
        while (sayac <= n) {
            int oncekiIki = hesaplananlar.get(sayac - 2);
            int oncekiBir = hesaplananlar.get(sayac - 1);
            hesaplananlar.add(oncekiIki + oncekiBir);
            sayac++;
        }

        return hesaplananlar.get(n);
    }

    public static void main(String[] args) {
        int hedefIndeks = 10;
        int deger = fibonacci(hedefIndeks);
        System.out.println(deger);
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.HashMap;

@SuppressWarnings({"rawtypes", "unchecked"})
final class LongestArithmeticSubsequence {
    private LongestArithmeticSubsequence() {
    }

    /**
     * Returns the length of the longest arithmetic subsequence in the given array.
     *
     * A sequence seq is arithmetic if seq[i + 1] - seq[i] are all the same value
     * (for 0 <= i < seq.length - 1).
     *
     * @param nums the input array of integers
     * @return the length of the longest arithmetic subsequence
     */
    public static int getLongestArithmeticSubsequenceLength(int[] nums) {
        if (nums == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }

        if (nums.length <= 1) {
            return nums.length;
        }

        HashMap<Integer, Integer>[] dp = new HashMap[nums.length];
        int maxLength = 2;

        // fill the dp array
        for (int i = 0; i < nums.length; i++) {
            dp[i] = new HashMap<>();
            for (int j = 0; j < i; j++) {
                final int diff = nums[i] - nums[j];
                dp[i].put(diff, dp[j].getOrDefault(diff, 1) + 1);
                maxLength = Math.max(maxLength, dp[i].get(diff));
            }
        }

        return maxLength;
    }
}

/**
 * This class provides a method to merge multiple sorted arrays into a single sorted array.
 * It utilizes a min-heap to efficiently retrieve the smallest elements from each array.
 *
 * Time Complexity: O(n * log k), where n is the total number of elements across all arrays
 * and k is the number of arrays.
 *
 * Space Complexity: O(k) for the heap, where k is the number of arrays.
 *
 * @author Hardvan
 */
public final class MergeKSortedArrays {
    private MergeKSortedArrays() {
    }

    /**
     * Merges k sorted arrays into one sorted array using a min-heap.
     * Steps:
     * 1. Create a min-heap to store elements in the format: {value, array index, element index}
     * 2. Add the first element from each array to the heap
     * 3. While the heap is not empty, remove the smallest element from the heap
     *   and add it to the result array. If there are more elements in the same array,
     *   add the next element to the heap.
     *   Continue until all elements have been processed.
     *   The result array will contain all elements in sorted order.
     * 4. Return the result array.
     *
     * @param arrays a 2D array, where each subarray is sorted in non-decreasing order
     * @return a single sorted array containing all elements from the input arrays
     */
    public static int[] mergeKArrays(int[][] arrays) {
        PriorityQueue<int[]> minHeap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));

        int totalLength = 0;
        for (int i = 0; i < arrays.length; i++) {
            if (arrays[i].length > 0) {
                minHeap.offer(new int[] {arrays[i][0], i, 0});
                totalLength += arrays[i].length;
            }
        }

        int[] result = new int[totalLength];
        int index = 0;
        while (!minHeap.isEmpty()) {
            int[] top = minHeap.poll();
            result[index++] = top[0];

            if (top[2] + 1 < arrays[top[1]].length) {
                minHeap.offer(new int[] {arrays[top[1]][top[2] + 1], top[1], top[2] + 1});
            }
        }

        return result;
    }
}

