final class ProductCipher {
private ProductCipher() {
}

public static void main(String[] args) {
try (Scanner inputScanner = new Scanner(System.in)) {
System.out.println("Enter the input to be encrypted: ");
String rawInputText = inputScanner.nextLine();
System.out.println(" ");
System.out.println("Enter a number: ");
int shiftNumber = inputScanner.nextInt();

StringBuilder substitutedText = new StringBuilder();
for (int charIndex = 0; charIndex < rawInputText.length(); charIndex++) {
char currentChar = rawInputText.charAt(charIndex);
substitutedText.append((char) (currentChar + 5));
}
System.out.println(" ");
System.out.println("Substituted text: ");
System.out.println(substitutedText);

String transpositionInput = substitutedText.toString();
int paddingNeeded = transpositionInput.length() % shiftNumber;
if (paddingNeeded != 0) {
paddingNeeded = shiftNumber - paddingNeeded;
for (; paddingNeeded != 0; paddingNeeded--) {
transpositionInput += "/";
}
}
StringBuilder transposedOutput = new StringBuilder();
System.out.println(" ");
System.out.println("Transposition Matrix: ");
for (int rowPos = 0; rowPos < shiftNumber; rowPos++) {
for (int colPos = 0; colPos < transpositionInput.length() / shiftNumber; colPos++) {
char currentChar = transpositionInput.charAt(rowPos + (colPos * shiftNumber));
System.out.print(currentChar);
transposedOutput.append(currentChar);
}
System.out.println();
}
System.out.println(" ");
System.out.println("Final encrypted text: ");
System.out.println(transposedOutput);

int columnCount = transposedOutput.length() / shiftNumber;
StringBuilder transposedDecoded = new StringBuilder();
for (int rowPos = 0; rowPos < columnCount; rowPos++) {
for (int colPos = 0; colPos < transposedOutput.length() / columnCount; colPos++) {
char currentChar = transposedOutput.charAt(rowPos + (colPos * columnCount));
transposedDecoded.append(currentChar);
}
}

StringBuilder originalDecoded = new StringBuilder();
for (int charIndex = 0; charIndex < transposedDecoded.length(); charIndex++) {
char currentChar = transposedDecoded.charAt(charIndex);
originalDecoded.append((char) (currentChar - 5));
}

System.out.println("Plaintext: ");
System.out.println(originalDecoded);
}
}
}

import java.io.*;

/*
 * Kucuk bir gosterim: Personel adli sinif Serializable'i implemente eder,
 * boylece bir nesne ObjectOutputStream araciligiyla diske yazilabilir
 * (serialize) ve sonrasinda ObjectInputStream ile geri okunabilir
 * (deserialize). Geri okunan nesne, yazilan nesneyle ayni alan degerlerine
 * sahip olmalidir.
 */

public class Serilestirme {

    private static final String DOSYA_ADI = "calisan.ser";

    public static void main(String[] args) {
        Personel orijinal = new Personel("Ahmet Yilmaz", 54321, "Yazilim Muhendisi");

        diskeYaz(orijinal);

        Personel okunan = diskeninOku();
        if (okunan == null) {
            return;
        }

        System.out.println("Geri Yuklenen Calisan...");
        System.out.println("Isim: " + okunan.adiniGetir());
        System.out.println("ID: " + okunan.numarasiniGetir());
        System.out.println("Unvan: " + okunan.unvaniniGetir());
    }

    private static void diskeYaz(Personel p) {
        try (FileOutputStream fos = new FileOutputStream(DOSYA_ADI);
             ObjectOutputStream oos = new ObjectOutputStream(fos)) {
            oos.writeObject(p);
            System.out.println("Calisan nesnesi " + DOSYA_ADI + " dosyasina serilestirildi.");
        } catch (IOException hata) {
            hata.printStackTrace();
        }
    }

    private static Personel diskeninOku() {
        try (FileInputStream fis = new FileInputStream(DOSYA_ADI);
             ObjectInputStream ois = new ObjectInputStream(fis)) {
            return (Personel) ois.readObject();
        } catch (IOException hata) {
            hata.printStackTrace();
            return null;
        } catch (ClassNotFoundException hata) {
            System.out.println("Calisan sinifi bulunamadi.");
            hata.printStackTrace();
            return null;
        }
    }
}

/** Basit, serilestirilebilir bir personel kaydi. */
class Personel implements Serializable {

    private static final long serialVersionUID = 1L;

    private final String ad;
    private final int sicilNo;
    private final String pozisyon;

    public Personel(String ad, int sicilNo, String pozisyon) {
        this.ad = ad;
        this.sicilNo = sicilNo;
        this.pozisyon = pozisyon;
    }

    public String adiniGetir() {
        return ad;
    }

    public int numarasiniGetir() {
        return sicilNo;
    }

    public String unvaniniGetir() {
        return pozisyon;
    }
}

package LineSub;

/**
 * A line segment that extends Point to reuse the "begin" coordinate,
 * while composing a second Point for the "end" coordinate.
 */
public class LineSub extends Point {

    private Point endPoint;

    public LineSub(Point begin, Point end) {
        super(begin.getX(), begin.getY());
        this.endPoint = end;
    }

    public LineSub(int beginX, int beginY, int endX, int endY) {
        super(beginX, beginY);
        this.endPoint = new Point(endX, endY);
    }

    @Override
    public String toString() {
        return "LineSub[begin=" + super.toString() + ",end=" + endPoint + ']';
    }

    public Point getBegin() {
        return new Point(getX(), getY());
    }

    public Point getEnd() {
        return endPoint;
    }

    public void setBegin(int beginX, int beginY) {
        setXY(beginX, beginY);
    }

    public void setEnd(int endX, int endY) {
        endPoint.setXY(endX, endY);
    }

    public int getBeginX() {
        return getX();
    }

    public int getBeginY() {
        return getY();
    }

    public int getEndX() {
        return endPoint.getX();
    }

    public int getEndY() {
        return endPoint.getY();
    }

    public void setBeginX(int beginX) {
        setX(beginX);
    }

    public void setBeginY(int beginY) {
        setY(beginY);
    }

    public void setBeginXY(int beginX, int beginY) {
        setXY(beginX, beginY);
    }

    public void setEndX(int endX) {
        endPoint.setX(endX);
    }

    public void setEndY(int endY) {
        endPoint.setY(endY);
    }

    public void setEndXY(int endX, int endY) {
        endPoint.setXY(endX, endY);
    }

    public int getLength() {
        int dx = endPoint.getX() - getX();
        int dy = endPoint.getY() - getY();
        double distance = Math.sqrt(dx * dx + dy * dy);
        return (int) distance;
    }

    public double getGradient() {
        int dx = endPoint.getX() - getX();
        int dy = endPoint.getY() - getY();
        return Math.atan2(dy, dx);
    }
}

class TestLineSub {
    public static void main(String[] args) {
        LineSub lineSub = new LineSub(8, 9, 6, 7);
        System.out.println(lineSub.getBegin());
        System.out.println(lineSub.getEnd());
        System.out.println(lineSub.getLength());
        System.out.println(lineSub.getGradient());
    }
}

