public class EvenOddSeparator {
    public static void main(String[] args) {
        int[] numbers = {15, 22, 8, 31, 44, 7, 60, 13};

        System.out.print("Even: ");
        for (int number : numbers) {
            if (number % 2 == 0) {
                System.out.print(number + " ");
            }
        }

        System.out.print("\nOdd: ");
        for (int number : numbers) {
            if (number % 2 != 0) {
                System.out.print(number + " ");
            }
        }
        System.out.println();
    }
}

