    private int oyuncuX = 0; // Oyuncunun baslangic satiri
    private int oyuncuY = 0; // Oyuncunun baslangic sutunu
    private int oncekiUzaklik; // Onceki uzaklik

    public HazineAvcisi() {
        Random random = new Random();
        hazineX = random.nextInt(IZGARA_BOYUTU); // Rastgele satir
        hazineY = random.nextInt(IZGARA_BOYUTU); // Rastgele sutun

        // Baslangic uzakligini hesapla
        oncekiUzaklik = Math.abs(hazineX - oyuncuX) + Math.abs(hazineY - oyuncuY);

        // Oyun arayuzunu baslat
        cerceve = new JFrame("Hazine Avcisi");
        cerceve.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        cerceve.setSize(500, 500);
        cerceve.setLayout(new GridLayout(IZGARA_BOYUTU, IZGARA_BOYUTU));

        // Dugme izgarasini olustur
        dugmeler = new JButton[IZGARA_BOYUTU][IZGARA_BOYUTU];
        for (int i = 0; i < IZGARA_BOYUTU; i++) {
            for (int j = 0; j < IZGARA_BOYUTU; j++) {
                JButton dugme = new JButton();
                dugme.setBackground(Color.LIGHT_GRAY);
                dugme.setFont(new Font("Arial", Font.BOLD, 16));
                dugmeler[i][j] = dugme;
                cerceve.add(dugme);
            }
        }

        // Oyuncunun baslangic pozisyonunu isaretle
        dugmeler[oyuncuX][oyuncuY].setBackground(Color.YELLOW);
        dugmeler[oyuncuX][oyuncuY].setText("🚶");

        // Klavye dinleyicisi ekle
        cerceve.addKeyListener(new KeyListener() {
            @Override
            public void keyTyped(KeyEvent e) {}

            @Override
            public void keyPressed(KeyEvent e) {
                hareketEt(e.getKeyCode());
            }

            @Override
            public void keyReleased(KeyEvent e) {}
        });

        cerceve.setFocusable(true); // Klavye girisine odaklanmayi etkinlestir
        cerceve.setVisible(true);
    }

    // Oyuncunun hareketini isleyen metot
    private void hareketEt(int tusKodu) {
        int yeniX = oyuncuX;
        int yeniY = oyuncuY;

        // Yon tuslarina gore hareket
        switch (tusKodu) {
            case KeyEvent.VK_UP: // Yukari
                if (oyuncuX > 0) yeniX--;
                break;
            case KeyEvent.VK_DOWN: // Asagi
                if (oyuncuX < IZGARA_BOYUTU - 1) yeniX++;
                break;
            case KeyEvent.VK_LEFT: // Sol
                if (oyuncuY > 0) yeniY--;
                break;
            case KeyEvent.VK_RIGHT: // Sag
                if (oyuncuY < IZGARA_BOYUTU - 1) yeniY++;
                break;
        }

        // Oyuncu ayni yerde kalmissa islem yapma
        if (yeniX == oyuncuX && yeniY == oyuncuY) return;

        // Yeni uzakligi hesapla
        int yeniUzaklik = Math.abs(hazineX - yeniX) + Math.abs(hazineY - yeniY);

        // Eski pozisyonu sifirla
        dugmeler[oyuncuX][oyuncuY].setBackground(Color.LIGHT_GRAY);
        dugmeler[oyuncuX][oyuncuY].setText("");

        // Yeni pozisyonu isaretle
        oyuncuX = yeniX;
        oyuncuY = yeniY;
        dugmeler[oyuncuX][oyuncuY].setBackground(Color.YELLOW);
        dugmeler[oyuncuX][oyuncuY].setText("🚶");

        // Kazanma durumu
        if (oyuncuX == hazineX && oyuncuY == hazineY) {
            dugmeler[oyuncuX][oyuncuY].setBackground(Color.GREEN);
            dugmeler[oyuncuX][oyuncuY].setText("💎");
            JOptionPane.showMessageDialog(cerceve, "Tebrikler! Hazineyi buldunuz!");
            oyunuSifirla();
            return;
        }

        // Uzaklik kontrolu
        if (yeniUzaklik > oncekiUzaklik) {
            JOptionPane.showMessageDialog(cerceve, "Yanlis yondesiniz!");
        } else {
            JOptionPane.showMessageDialog(cerceve, "Hazineye yaklasiyorsunuz!");
        }

        oncekiUzaklik = yeniUzaklik; // Uzakligi guncelle
    }

    // Oyunu sifirla
    private void oyunuSifirla() {
        Random random = new Random();
        hazineX = random.nextInt(IZGARA_BOYUTU); // Yeni hazine konumu
        hazineY = random.nextInt(IZGARA_BOYUTU);

        oyuncuX = 0; // Oyuncu baslangic noktasina doner
        oyuncuY = 0;
        oncekiUzaklik = Math.abs(hazineX - oyuncuX) + Math.abs(hazineY - oyuncuY);

        // Tum dugmeleri sifirla
        for (int i = 0; i < IZGARA_BOYUTU; i++) {
            for (int j = 0; j < IZGARA_BOYUTU; j++) {
                dugmeler[i][j].setText("");
                dugmeler[i][j].setBackground(Color.LIGHT_GRAY);
            }
        }

        // Oyuncunun baslangic pozisyonunu isaretle
        dugmeler[oyuncuX][oyuncuY].setBackground(Color.YELLOW);
        dugmeler[oyuncuX][oyuncuY].setText("🚶");
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(HazineAvcisi::new);
    }
}

/**
 * A queue implementation using two stacks. This class provides methods to
 * enqueue (add) elements to the end of the queue and dequeue (remove)
 * elements from the front, while utilizing two internal stacks to manage
 * the order of elements.
 *
 * @param <T> The type of elements held in this queue.
 */
@SuppressWarnings("unchecked")
public class QueueByTwoStacks<T> {

    private final Stack<T> enqueueStk;
    private final Stack<T> dequeueStk;

    /**
     * Constructor that initializes two empty stacks for the queue.
     * The `enqueueStk` is used to push elements when enqueuing, and
     * the `dequeueStk` is used to pop elements when dequeuing.
     */
    public QueueByTwoStacks() {
        enqueueStk = new Stack<>();
        dequeueStk = new Stack<>();
    }

    /**
     * Adds an element to the end of the queue. This method pushes the element
     * onto the `enqueueStk`.
     *
     * @param item The element to be added to the queue.
     */
    public void put(T item) {
        enqueueStk.push(item);
    }

    /**
     * Removes and returns the element at the front of the queue.
     * If `dequeueStk` is empty, it transfers all elements from
     * `enqueueStk` to `dequeueStk` to maintain the correct FIFO
     * (First-In-First-Out) order before popping.
     *
     * @return The element at the front of the queue.
     * @throws NoSuchElementException If the queue is empty.
     */
    public T get() {
        if (dequeueStk.isEmpty()) {
            while (!enqueueStk.isEmpty()) {
                dequeueStk.push(enqueueStk.pop());
            }
        }
        if (dequeueStk.isEmpty()) {
            throw new NoSuchElementException("Queue is empty");
        }
        return dequeueStk.pop();
    }

    /**
     * Returns the total number of elements currently in the queue.
     * This is the sum of the sizes of both stacks.
     *
     * @return The number of elements in the queue.
     */
    public int size() {
        return enqueueStk.size() + dequeueStk.size();
    }

    /**
     * Returns a string representation of the queue, showing the elements
     * in the correct order (from front to back).
     * The `dequeueStk` is first cloned, and then all elements from the
     * `enqueueStk` are added to the cloned stack in reverse order to
     * represent the queue accurately.
     *
     * @return A string representation of the queue.
     */
    @Override
    public String toString() {
        Stack<T> tempStack = (Stack<T>) dequeueStk.clone();
        while (!enqueueStk.isEmpty()) {
            tempStack.push(enqueueStk.pop());
        }
        return "Queue(" + tempStack + ")";
    }
}

package com.ankan.singleton;

// This class demonstrates that SubClass is NOT a subclass of A
// It simply creates an object reference to demonstrate access rights
public class NotSubClass {

    // Attempting to access SubClass from a different package (singleton vs access)
    SubClass referenceObject = new SubClass(45, "Sample Name");

    // Direct field access would cause compilation error because:
    // - SubClass extends A (from com.ankan.access package)
    // - numValue (or original 'num') is protected in class A
    // - Protected members are accessible in subclasses, BUT NotSubClass does NOT extend A
    // - Therefore, protected fields are NOT accessible here

    // int retrievedNumber = referenceObject.numValue;  // COMPILATION ERROR
    // Explanation: NotSubClass is not in the same package as A and does not extend A
    // So protected members are not visible - only public getters can access them

    // The correct way to access would be:
    // int correctAccess = referenceObject.getNumValue();  // Using public getter method
}

public record ADTFraction(int numerator, int denominator) {
    /**
     * Initializes a newly created {@code ADTFraction} object so that it represents
     * a fraction with the {@code numerator} and {@code denominator} provided as arguments.
     *
     * @param numerator   The fraction numerator
     * @param denominator The fraction denominator
     */
    public ADTFraction {
        if (denominator == 0) {
            throw new IllegalArgumentException("Denominator cannot be 0");
        }
    }

    /**
     * Add two fractions.
     *
     * @param fraction the {@code ADTFraction} to add
     * @return A new {@code ADTFraction} containing the result of the operation
     */
    public ADTFraction plus(ADTFraction fraction) {
        var numerator = this.denominator * fraction.numerator + this.numerator * fraction.denominator;
        var denominator = this.denominator * fraction.denominator;
        return new ADTFraction(numerator, denominator);
    }

    /**
     * Multiply fraction by a number.
     *
     * @param number the number to multiply
     * @return A new {@code ADTFraction} containing the result of the operation
     */
    public ADTFraction times(int number) {
        return times(new ADTFraction(number, 1));
    }

    /**
     * Multiply two fractions.
     *
     * @param fraction the {@code ADTFraction} to multiply
     * @return A new {@code ADTFraction} containing the result of the operation
     */
    public ADTFraction times(ADTFraction fraction) {
        var numerator = this.numerator * fraction.numerator;
        var denominator = this.denominator * fraction.denominator;
        return new ADTFraction(numerator, denominator);
    }

    /**
     * Generates the reciprocal of the fraction.
     *
     * @return A new {@code ADTFraction} with the {@code numerator} and {@code denominator} switched
     */
    public ADTFraction reciprocal() {
        return new ADTFraction(this.denominator, this.numerator);
    }

    /**
     * Calculates the result of the fraction.
     *
     * @return The numerical result of the division between {@code numerator} and {@code
     *     denominator}
     */
    public float value() {
        return (float) this.numerator / this.denominator;
    }

    /**
     * Returns a string representation of this {@code ADTFraction} in the format
     * {@code numerator}/{@code denominator}.
     *
     * @return A string representation of this {@code ADTFraction}
     */
    @Override
    public String toString() {
        return String.format("%d/%d", this.numerator, this.denominator);
    }
}

// Hayvan sinifi

public class Hayvan {

	private String isim;  // Hayvanin ismi
	private int yas;      // Hayvanin yasi
	private double saglik;  // Hayvanin saglik durumu

	// Hayvan sinifi kurucusu (constructor)
	public Hayvan(String isim, int yas) {
		this.isim = isim;
		this.yas = yas;
		this.saglik = 100.0; // Varsayilan saglik degeri 100
	}

	// Hayvanin ismini almak icin getter metodu
	public String getIsim() {
		return isim;
	}

	// Hayvanin yasini almak icin getter metodu
	public int getYas() {
		return yas;
	}

	// Hayvanin sagligini almak icin getter metodu
	public double getSaglik() {
		return saglik;
	}

	// Hayvani konusturma metodu
	public void konus() {
		System.out.println("Bu hayvan konusur.");
	}

	// Hayvani yemek yedirme metodu
	public void yemekYe(double miktar) {
		if (miktar > 0) {
			saglik += miktar;  // Saglik miktar kadar artar
			System.out.println(isim + " yemek yedi. Saglik: " + saglik);
		} else {
			System.out.println("Gecersiz miktar.");
		}
	}

	// Hayvani uyutma metodu
	public void uyu() {
		saglik += 5;  // Uyuma saglik uzerine artirma
		System.out.println(isim + " uyudu. Saglik: " + saglik);
	}

	// Hayvanin yasini gosterme
	public void yasHesapla() {
		System.out.println(isim + " " + yas + " yasinda.");
	}

	// ToString metodu - Hayvanin ozelliklerini string olarak dondurur
	@Override
	public String toString() {
		return "Hayvan Ismi: " + isim + ", Yas: " + yas + ", Saglik Durumu: " + saglik;
	}
}

