package com.thealgorithms.datastructures.trees;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public final class LevelOrderTraversal {
    private LevelOrderTraversal() {
    }

    public static List<List<Integer>> traverse(BinaryTree.Node root) {
        if (root == null) {
            return List.of();
        }

        List<List<Integer>> result = new ArrayList<>();

        Queue<BinaryTree.Node> q = new LinkedList<>();
        q.add(root);
        while (!q.isEmpty()) {
            int nodesOnLevel = q.size();
            List<Integer> level = new LinkedList<>();
            for (int i = 0; i < nodesOnLevel; i++) {
                BinaryTree.Node tempNode = q.poll();
                level.add(tempNode.data);

                if (tempNode.left != null) {
                    q.add(tempNode.left);
                }

                if (tempNode.right != null) {
                    q.add(tempNode.right);
                }
            }
            result.add(level);
        }
        return result;
    }

    /* Print nodes at the given level */
    public static void printGivenLevel(BinaryTree.Node root, int level) {
        if (root == null) {
            System.out.println("Root node must not be null! Exiting.");
            return;
        }
        if (level == 1) {
            System.out.print(root.data + " ");
        } else if (level > 1) {
            printGivenLevel(root.left, level - 1);
            printGivenLevel(root.right, level - 1);
        }
    }
}

public class RandomString {

    /**
     * Generates a random lowercase string of the specified length.
     * 
     * @param desiredLength The length of the random string to generate
     * @return A randomly generated string containing only lowercase English letters (a-z)
     * 
     * Example: generateRandomString(5) might return "abcde", "xyzab", "random", etc.
     */
    static String generateRandomString(int desiredLength) {
        // Create a StringBuffer with the exact capacity needed (no resizing required)
        StringBuffer stringBuilder = new StringBuffer(desiredLength);

        // Random number generator for selecting characters
        Random randomGenerator = new Random();

        // Generate each character in the string
        for (int indexPosition = 0; indexPosition < desiredLength; indexPosition++) {
            // Generate random integer between 97 and 122 (ASCII values for 'a' to 'z')
            // Formula: 97 + (random value between 0 and 25)
            // - 97 is ASCII code for 'a'
            // - rand.nextFloat() * 26 gives a value between 0.0 and 26.0
            // - Casting to int truncates to a whole number between 0 and 25
            int asciiCode = 97 + (int) (randomGenerator.nextFloat() * 26);

            // Convert ASCII code to character and append to buffer
            stringBuilder.append((char) asciiCode);
        }

        // Convert the mutable StringBuffer to an immutable String
        return stringBuilder.toString();
    }

    /**
     * Alternative method using Random.nextInt() for better readability.
     * This is a more modern approach than using nextFloat().
     */
    static String generateRandomStringAlternative(int desiredLength) {
        StringBuffer stringBuilder = new StringBuffer(desiredLength);
        Random randomGenerator = new Random();

        for (int indexPosition = 0; indexPosition < desiredLength; indexPosition++) {
            // nextInt(26) generates a random integer from 0 to 25
            // Adding 97 gives the ASCII value for 'a' through 'z'
            char randomLowercaseLetter = (char) (97 + randomGenerator.nextInt(26));
            stringBuilder.append(randomLowercaseLetter);
        }

        return stringBuilder.toString();
    }

    /**
     * Generates a random string with custom character set (uppercase, lowercase, digits, etc.)
     * 
     * @param desiredLength The length of the random string
     * @param includeUppercase Whether to include uppercase letters (A-Z)
     * @param includeDigits Whether to include digits (0-9)
     * @return Randomly generated string based on specified rules
     */
    static String generateCustomRandomString(int desiredLength, boolean includeUppercase, boolean includeDigits) {
        String characters = "abcdefghijklmnopqrstuvwxyz";

        if (includeUppercase) {
            characters += "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        }
        if (includeDigits) {
            characters += "0123456789";
        }

        StringBuffer stringBuilder = new StringBuffer(desiredLength);
        Random randomGenerator = new Random();

        for (int indexPosition = 0; indexPosition < desiredLength; indexPosition++) {
            int randomIndex = randomGenerator.nextInt(characters.length());
            stringBuilder.append(characters.charAt(randomIndex));
        }

        return stringBuilder.toString();
    }
}

/*
TECHNICAL EXPLANATION - Random String Generation
================================================

How the Original Algorithm Works:
---------------------------------
1. Start with ASCII value 97 (which corresponds to character 'a')
2. Generate random float between 0.0 and 1.0
3. Multiply by 26 to get range [0.0, 26.0)
4. Cast to int to get integer between 0 and 25
5. Add to 97 to get ASCII value between 97 and 122 ('a' to 'z')
6. Cast to char and append to buffer

ASCII Reference for Lowercase Letters:
---------------------------------------
a = 97    g = 103   m = 109   s = 115   y = 121
b = 98    h = 104   n = 110   t = 116   z = 122
c = 99    i = 105   o = 111   u = 117
d = 100   j = 106   p = 112   v = 118
e = 101   k = 107   q = 113   w = 119
f = 102   l = 108   r = 114   x = 120

Why StringBuffer/Builder is Appropriate Here:
----------------------------------------------
- Multiple string concatenations (in loop) would create many intermediate String objects
- StringBuffer/Builder allows efficient in-place modification
- Pre-allocating capacity (size) prevents dynamic resizing

StringBuffer vs StringBuilder for This Use Case:
------------------------------------------------
- This method is NOT shared across threads (called from single thread)
- StringBuilder would be faster because it's not synchronized
- StringBuffer was used for thread-safety (though not needed here)

Performance Comparison (for 1000 iterations, length 10):
--------------------------------------------------------
| Approach | Objects Created | Approximate Time |
|----------|----------------|------------------|
| String Concatenation (+) | 1000+ | Slower |
| StringBuffer | 1 | Medium |
| StringBuilder | 1 | Fastest |

When to Use Each:
-----------------
✅ Use String (immutable): Single concatenation or compile-time known strings
✅ Use StringBuilder: Single-threaded, frequent modifications
✅ Use StringBuffer: Multi-threaded, frequent modifications
*/

/**
 * A line segment composed of two MyPoint endpoints.
 */
class MyPoint {
    private int x;
    private int y;

    public MyPoint() {
    }

    public MyPoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int[] getXY() {
        return new int[]{x, y};
    }

    public void setXY(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public double distance(int x, int y) {
        return Math.sqrt(Math.pow(x - this.x, 2) + Math.pow(y - this.y, 2));
    }

    public double distance(MyPoint another) {
        return Math.sqrt(Math.pow(another.x - x, 2) + Math.pow(another.y - y, 2));
    }

    public double distance() {
        return Math.sqrt(Math.pow(-x, 2) + Math.pow(-y, 2));
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ')';
    }
}

public class MyLine {
    private MyPoint begin;
    private MyPoint end;

    public MyLine(int x1, int y1, int x2, int y2) {
        this.begin = new MyPoint(x1, y1);
        this.end = new MyPoint(x2, y2);
    }

    public MyLine(MyPoint begin, MyPoint end) {
        this.begin = begin;
        this.end = end;
    }

    public MyPoint getBegin() {
        return begin;
    }

    public void setBegin(MyPoint begin) {
        this.begin = begin;
    }

    public MyPoint getEnd() {
        return end;
    }

    public void setEnd(MyPoint end) {
        this.end = end;
    }

    public void setBeginX(int x) {
        begin.setX(x);
    }

    public int getBeginX() {
        return begin.getX();
    }

    public void setBeginY(int y) {
        begin.setY(y);
    }

    public int getBeginY() {
        return begin.getY();
    }

    public void setEndX(int x) {
        end.setX(x);
    }

    public int getEndX() {
        return end.getX();
    }

    public void setEndY(int y) {
        end.setY(y);
    }

    public int getEndY() {
        return end.getY();
    }

    public void setBeginXY(int x, int y) {
        begin.setXY(x, y);
    }

    public int[] getBeginXY() {
        return begin.getXY();
    }

    public void setEndXY(int x, int y) {
        end.setXY(x, y);
    }

    public int[] getEndXY() {
        return end.getXY();
    }

    public double getLength() {
        return begin.distance(end);
    }

    public double getGradient() {
        return Math.atan2(end.getY() - begin.getY(), end.getX() - begin.getX());
    }

    @Override
    public String toString() {
        return "MyLine[begin=" + begin + ",end=" + end + ']';
    }
}

class TestMyLine {
    public static void main(String[] args) {
        MyLine myLine = new MyLine(new MyPoint(0, 1), new MyPoint(3, 4));
        System.out.println(myLine.getLength());
        System.out.println(myLine.getGradient());
        System.out.println(myLine.toString());
        System.out.println(Arrays.toString(myLine.getBeginXY()));
        System.out.println(Arrays.toString(myLine.getEndXY()));
    }
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

/**
 * Implementation of a graph in a matrix form Also known as an adjacency matrix
 * representation [Adjacency matrix -
 * Wikipedia](https://en.wikipedia.org/wiki/Adjacency_matrix)
 *
 * @author Unknown
 */
public final class MatrixGraphs {
    private MatrixGraphs() {
    }

    public static void main(String[] args) {
        AdjacencyMatrixGraph graph = new AdjacencyMatrixGraph(10);
        graph.addEdge(1, 2);
        graph.addEdge(1, 5);
        graph.addEdge(2, 5);
        graph.addEdge(1, 2);
        graph.addEdge(2, 3);
        graph.addEdge(3, 4);
        graph.addEdge(4, 1);
        graph.addEdge(2, 3);
        graph.addEdge(3, 9);
        graph.addEdge(9, 1);
        graph.addEdge(9, 8);
        graph.addEdge(1, 8);
        graph.addEdge(5, 6);
        System.out.println("The graph matrix:");
        System.out.println(graph);
        System.out.println("Depth first order beginning at node '1':");
        System.out.println(graph.depthFirstOrder(1));
        System.out.println("Breadth first order beginning at node '1':");
        System.out.println(graph.breadthFirstOrder(1));
    }
}

/**
 * AdjacencyMatrixGraph Implementation
 */
class AdjacencyMatrixGraph {

    /**
     * The number of vertices in the graph
     */
    private int vertexCount;

    /**
     * The number of edges in the graph
     */
    private int edgeCount;

    /**
     * The adjacency matrix for the graph
     */
    private int[][] adjMatrix;

    /**
     * Static variables to define whether or not an edge exists in the adjacency
     * matrix
     */
    static final int EDGE_EXIST = 1;
    static final int EDGE_NONE = 0;

    /**
     * Constructor
     */
    AdjacencyMatrixGraph(int givenNumberOfVertices) {
        this.setNumberOfVertices(givenNumberOfVertices);
        this.setNumberOfEdges(0);
        this.setAdjacency(new int[givenNumberOfVertices][givenNumberOfVertices]);
        for (int i = 0; i < givenNumberOfVertices; i++) {
            for (int j = 0; j < givenNumberOfVertices; j++) {
                this.adjacency()[i][j] = AdjacencyMatrixGraph.EDGE_NONE;
            }
        }
    }

    /**
     * Updates the number of vertices in the graph
     *
     * @param newNumberOfVertices the new number of vertices
     */
    private void setNumberOfVertices(int newNumberOfVertices) {
        this.vertexCount = newNumberOfVertices;
    }

    /**
     * Getter for `this.vertexCount`
     *
     * @return the number of vertices in the graph
     */
    public int numberOfVertices() {
        return this.vertexCount;
    }

    /**
     * Updates the number of edges in the graph
     *
     * @param newNumberOfEdges the new number of edges
     *
     */
    private void setNumberOfEdges(int newNumberOfEdges) {
        this.edgeCount = newNumberOfEdges;
    }

    /**
     * Getter for `this.edgeCount`
     *
     * @return the number of edges
     */
    public int numberOfEdges() {
        return this.edgeCount;
    }

    /**
     * Sets a new matrix as the adjacency matrix
     *
     * @param newAdjacency the new adjaceny matrix
     */
    private void setAdjacency(int[][] newAdjacency) {
        this.adjMatrix = newAdjacency;
    }

    /**
     * Getter for the adjacency matrix
     *
     * @return the adjacency matrix
     */
    private int[][] adjacency() {
        return this.adjMatrix;
    }

    /**
     * Checks if two vertices are connected by an edge
     *
     * @param from the parent vertex to check for adjacency
     * @param to the child vertex to check for adjacency
     * @return whether or not the vertices are adjacent
     */
    private boolean adjacencyOfEdgeDoesExist(int from, int to) {
        return (this.adjacency()[from][to] != AdjacencyMatrixGraph.EDGE_NONE);
    }

    /**
     * Checks if a particular vertex exists in a graph
     *
     * @param aVertex the vertex to check for existence
     * @return whether or not the vertex exists
     */
    public boolean vertexDoesExist(int aVertex) {
        return aVertex >= 0 && aVertex < this.numberOfVertices();
    }

    /**
     * Checks if two vertices are connected by an edge
     *
     * @param from the parent vertex to check for adjacency
     * @param to the child vertex to check for adjacency
     * @return whether or not the vertices are adjacent
     */
    public boolean edgeDoesExist(int from, int to) {
        if (this.vertexDoesExist(from) && this.vertexDoesExist(to)) {
            return (this.adjacencyOfEdgeDoesExist(from, to));
        }

        return false;
    }

    /**
     * This method adds an edge to the graph between two specified vertices
     *
     * @param from the data of the vertex the edge is from
     * @param to the data of the vertex the edge is going to
     * @return returns true if the edge did not exist, return false if it
     * already did
     */
    public boolean addEdge(int from, int to) {
        if (this.vertexDoesExist(from) && this.vertexDoesExist(to)) {
            if (!this.adjacencyOfEdgeDoesExist(from, to)) {
                this.adjacency()[from][to] = AdjacencyMatrixGraph.EDGE_EXIST;
                this.adjacency()[to][from] = AdjacencyMatrixGraph.EDGE_EXIST;
                this.setNumberOfEdges(this.numberOfEdges() + 1);
                return true;
            }
        }

        return false;
    }

    /**
     * this method removes an edge from the graph between two specified vertices
     *
     * @param from the data of the vertex the edge is from
     * @param to the data of the vertex the edge is going to
     * @return returns false if the edge doesn't exist, returns true if the edge
     * exists and is removed
     */
    public boolean removeEdge(int from, int to) {
        if (this.vertexDoesExist(from) && this.vertexDoesExist(to)) {
            if (this.adjacencyOfEdgeDoesExist(from, to)) {
                this.adjacency()[from][to] = AdjacencyMatrixGraph.EDGE_NONE;
                this.adjacency()[to][from] = AdjacencyMatrixGraph.EDGE_NONE;
                this.setNumberOfEdges(this.numberOfEdges() - 1);
                return true;
            }
        }
        return false;
    }

    /**
     * This method returns a list of the vertices in a depth first order
     * beginning with the specified vertex
     *
     * @param startVertex the vertex to begin the traversal
     * @return the list of the ordered vertices
     */
    public List<Integer> depthFirstOrder(int startVertex) {
        // If the startVertex is invalid, return an empty list
        if (startVertex >= vertexCount || startVertex < 0) {
            return new ArrayList<>();
        }

        // Create an array to track the visited vertices
        boolean[] visited = new boolean[vertexCount];

        // Create a list to keep track of the order of our traversal
        ArrayList<Integer> orderList = new ArrayList<>();

        // Perform our DFS algorithm
        depthFirstOrder(startVertex, visited, orderList);

        return orderList;
    }

    /**
     * Helper method for public depthFirstOrder(int) that will perform a depth
     * first traversal recursively on the graph
     *
     * @param currentVertex the currently exploring vertex
     * @param visited the array of values denoting whether or not that vertex
     * has been visited
     * @param orderList the list to add vertices to as they are visited
     */
    private void depthFirstOrder(int currentVertex, boolean[] visited, List<Integer> orderList) {
        // If this vertex has already been visited, do nothing and return
        if (visited[currentVertex]) {
            return;
        }

        // Visit the currentVertex by marking it as visited and adding it
        // to the orderList
        visited[currentVertex] = true;
        orderList.add(currentVertex);

        // Get the adjacency array for this vertex
        int[] adjacent = adjMatrix[currentVertex];
        for (int i = 0; i < adjacent.length; i++) { // we are considering exploring, recurse on it // If an edge exists between the
                                                    // currentVertex and the vertex
            if (adjacent[i] == AdjacencyMatrixGraph.EDGE_EXIST) {
                depthFirstOrder(i, visited, orderList);
            }
        }
    }

    /**
     * This method returns a list of the vertices in a breadth first order
     * beginning with the specified vertex
     *
     * @param startVertex the vertext to begin the traversal
     * @return the list of the ordered vertices
     */
    public List<Integer> breadthFirstOrder(int startVertex) {
        // If the specified startVertex is invalid, return an empty list
        if (startVertex >= vertexCount || startVertex < 0) {
            return new ArrayList<>();
        }

        // Create an array to keep track of the visited vertices
        boolean[] visited = new boolean[vertexCount];

        // Create a list to keep track of the ordered vertices
        ArrayList<Integer> orderList = new ArrayList<>();

        // Create a queue for our BFS algorithm and add the startVertex
        // to the queue
        Queue<Integer> queue = new LinkedList<>();
        queue.add(startVertex);

        // Continue until the queue is empty
        while (!queue.isEmpty()) {
            // Remove the first vertex in the queue
            int currentVertex = queue.poll();

            // If we've visited this vertex, skip it
            if (visited[currentVertex]) {
                continue;
            }

            // We now visit this vertex by adding it to the orderList and
            // marking it as visited
            orderList.add(currentVertex);
            visited[currentVertex] = true;

            // Get the adjacency array for the currentVertex and
            // check each node
            int[] adjacent = adjMatrix[currentVertex];
            for (int vertex = 0; vertex < adjacent.length; vertex++) { // vertex we are considering exploring, we add it to the queue // If an
                                                                       // edge exists between the current vertex and the
                if (adjacent[vertex] == AdjacencyMatrixGraph.EDGE_EXIST) {
                    queue.add(vertex);
                }
            }
        }

        return orderList;
    }

    /**
     * this gives a list of vertices in the graph and their adjacencies
     *
     * @return returns a string describing this graph
     */
    public String toString() {
        StringBuilder s = new StringBuilder("    ");
        for (int i = 0; i < this.numberOfVertices(); i++) {
            s.append(i).append(" ");
        }
        s.append(" \n");

        for (int i = 0; i < this.numberOfVertices(); i++) {
            s.append(i).append(" : ");
            for (int j = 0; j < this.numberOfVertices(); j++) {
                s.append(this.adjMatrix[i][j]).append(" ");
            }
            s.append("\n");
        }
        return s.toString();
    }
}

package collections;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Loto {

    // Havuzdaki sayilari karistirip istenen adette cekilis yapar
    public static Integer[] cekilisYap(int havuzBuyuklugu, int kacTaneCekilecek) {
        List<Integer> havuz = new ArrayList<>();

        for (int deger = 1; deger <= havuzBuyuklugu; deger++) {
            havuz.add(deger);
        }

        Collections.shuffle(havuz);

        Integer[] secilenler = new Integer[kacTaneCekilecek];
        for (int i = 0; i < kacTaneCekilecek; i++) {
            secilenler[i] = havuz.get(i);
        }

        return secilenler;
    }

    public static void main(String[] args) {
        Integer[] cekilenNumaralar = cekilisYap(49, 6);

        StringBuilder cikti = new StringBuilder();
        for (Integer numara : cekilenNumaralar) {
            cikti.append(numara).append(' ');
        }
        System.out.print(cikti);
    }
}

package unchecked;

public class SayiFormatiHatasi {

    public static void main(String[] args) {

        // Simulated input values; the first one is not a valid integer
        String[] rawValues = {"10.1", "0"};

        try {
            int a = Integer.parseInt(rawValues[0]);
            int b = Integer.parseInt(rawValues[1]);

            int outcome = a / b;
            System.out.println("Sonuc: " + outcome);

        } catch (NumberFormatException nfe) {
            System.out.println("Gecersiz giris: Lutfen sadece tamsayi giriniz.");
            System.out.println("Istisna mesaji: " + nfe.getMessage());
            nfe.printStackTrace();

        } catch (ArithmeticException ae) {
            System.out.println("Sifira bolme hatasi olustu!");
            System.out.println("Istisna mesaji: " + ae.getMessage());
            ae.printStackTrace();

        } catch (ArrayIndexOutOfBoundsException aioobe) {
            System.out.println("Eksik giris: Lutfen iki sayi giriniz.");
            System.out.println("Istisna mesaji: " + aioobe.getMessage());
            aioobe.printStackTrace();

        } finally {
            System.out.println("Finally bloguna girildi!");
        }

        try {
            demonstrateCleanRun();
        } catch (Exception unexpected) {
            System.out.println("Beklenmeyen bir hata: " + unexpected.getMessage());
        }
    }

    /**
     * A division that succeeds without raising any exception.
     */
    public static void demonstrateCleanRun() {
        System.out.println("Basarili akis testi calisiyor.");
        int x = 10;
        int y = 5;
        int result = x / y;
        System.out.println("10 / 5 = " + result);
        System.out.println("Her sey yolunda, istisna firlatilmadi!");
    }
}

// One thread per connected client; simply echoes back whatever it reads
class ConnectionWorker extends Thread {
    private DataInputStream fromClient;
    private DataOutputStream toClient;
    private final Socket clientSocket;
    private final BufferedReader console = new BufferedReader(new InputStreamReader(System.in));

    public ConnectionWorker(Socket clientSocket) {
        this.clientSocket = clientSocket;
        try {
            fromClient = new DataInputStream(clientSocket.getInputStream());
            toClient = new DataOutputStream(clientSocket.getOutputStream());
        } catch (IOException e) {
            e.printStackTrace();
            System.out.println("Istemci baglantisi olusturulurken hata meydana geldi: " + e.getMessage());
        }
    }

    @Override
    public void run() {
        try {
            String received = "";
            while (!received.equals("stop")) {
                received = fromClient.readUTF();
                System.out.println("Istemciden alinan mesaj: " + received);
                toClient.writeUTF(received);
                toClient.flush();
            }
        } catch (IOException e) {
            System.out.println("Istemci ile baglanti koptu: " + e.getMessage());
        } finally {
            try {
                clientSocket.close();
                System.out.println("Istemci soketi kapatildi.");
            } catch (IOException e) {
                System.out.println("Soket kapatilirken hata meydana geldi: " + e.getMessage());
            }
        }
    }
}

/**
 * Accepts connections forever, spinning up a ConnectionWorker thread
 * for each client that connects.
 */
public class Server {

    private static final int PORT = 4444;

    public static void main(String[] args) throws IOException {
        ServerSocket listener = new ServerSocket(PORT);
        System.out.println("Sunucu baslatildi ve baglanti bekleniyor...");

        while (true) {
            Socket clientSocket = null;
            try {
                clientSocket = listener.accept();
                System.out.println("Yeni bir istemci baglandi: " + clientSocket);

                Thread worker = new ConnectionWorker(clientSocket);
                worker.start();

            } catch (Exception e) {
                System.out.println("Baglanti sirasinda hata meydana geldi: " + e.getMessage());
                if (clientSocket != null && !clientSocket.isClosed()) {
                    clientSocket.close();
                    System.out.println("Baglanti hatali soket kapatildi.");
                }
                listener.close();
                e.printStackTrace();
                break;
            }
        }
    }
}

package com.thealgorithms.conversions;

/**
 * Class for converting an octal number to a decimal number. Octal numbers are based on 8, using digits from 0 to 7.
 *
 */
public final class OctalToDecimal {
    private static final int OCTAL_BASE = 8;

    private OctalToDecimal() {
    }

    /**
     * Converts a given octal number (as a string) to its decimal representation.
     * If the input is not a valid octal number (i.e., contains characters other than 0-7),
     * the method throws an IllegalArgumentException.
     *
     * @param inputOctal The octal number as a string
     * @return The decimal equivalent of the octal number
     * @throws IllegalArgumentException if the input is not a valid octal number
     */
    public static int convertOctalToDecimal(String inputOctal) {
        if (inputOctal == null || inputOctal.isEmpty()) {
            throw new IllegalArgumentException("Input cannot be null or empty");
        }

        int decimalValue = 0;

        for (int i = 0; i < inputOctal.length(); i++) {
            char currentChar = inputOctal.charAt(i);

            if (currentChar < '0' || currentChar > '7') {
                throw new IllegalArgumentException("Incorrect input: Expecting an octal number (digits 0-7)");
            }

            int currentDigit = currentChar - '0';
            decimalValue = decimalValue * OCTAL_BASE + currentDigit;
        }

        return decimalValue;
    }
}

