package forloop;

public class KuvvetTablosu {

    public static void main(String[] args) {

        // Basliklari hizali sekilde yazdir
        System.out.printf("%8s %8s %8s %8s %8s %8s%n", "Sayi", "^1", "^2", "^3", "^4", "^5");
        // Ayirici cizgi
        System.out.println("-------------------------------------------------------");

        // 1'den 10'a kadar her sayi icin kuvvet degerlerini hesapla
        int taban = 1;
        while (taban <= 10) {
            System.out.printf("%9d", taban);
            // Kuvvetleri 1'den 5'e kadar hesaplayan ic dongu
            for (int us = 1; us <= 5; us++) {
                System.out.printf("%9d", (int) Math.pow(taban, us));
            }
            // Bir sonraki sayiya gecmeden once satir atla
            System.out.println();
            taban++;
        }
    }
}

