/**
 * A managed list of students with CRUD and sorting operations.
 */
public class StudentList extends ArrayList<Student> {

    public StudentList() {
        super();
    }

    public Student search(String code) {
        String target = code.trim().toUpperCase();
        for (int i = 0; i < size(); i++) {
            if (get(i).getCode().equals(target)) {
                return get(i);
            }
        }
        return null;
    }

    private boolean isCodeDuplicated(String code) {
        return search(code.trim().toUpperCase()) != null;
    }

    public void addStudent() {
        String newCode;
        boolean codeDuplicated;
        do {
            newCode = Inputter.inputPattern("St. code S000: ", "[sS][\\d]{3}");
            codeDuplicated = isCodeDuplicated(newCode);
            if (codeDuplicated) {
                System.out.println("Code is duplicated");
            }
        } while (codeDuplicated);
        String newName = Inputter.inputNonBlankStr("Name of new student: ").toUpperCase();
        int newMark = Inputter.inputInt("Mark: ", 0, 10);
        add(new Student(newCode, newName, newMark));
        System.out.println("Student " + newCode + " has been added");
    }

    public void searchStudent() {
        if (isEmpty()) {
            System.out.println("Empty list. No search can be performend!");
            return;
        }
        String code = Inputter.inputStr("Input student code for search: ");
        Student student = search(code);
        if (student == null) {
            System.out.println("Student " + code + " doesn't existed!");
        } else {
            System.out.println("Founđ: " + student);
        }
    }

    public void updateStudent() {
        if (isEmpty()) {
            System.out.println("Empty list. No update can be performend!");
            return;
        }
        String code = Inputter.inputStr("Input code of update student: ");
        Student student = search(code);
        if (student == null) {
            System.out.println("Student " + code + " doesn't existed!");
            return;
        }
        String newName = Inputter.inputNonBlankStr("Old name: " + student.getName() + ", new name: ");
        student.setName(newName);
        int newMark = Inputter.inputInt("Old mark: " + student.getMark() + ", new mark: ", 0, 10);
        student.setMark(newMark);
        System.out.println("Student " + code + " has bean updated.");
    }

    public void removeStudent() {
        if (isEmpty()) {
            System.out.println("Empty list. No remove can be performend!");
            return;
        }
        String code = Inputter.inputStr("Input code of remove student: ");
        Student student = search(code);
        if (student == null) {
            System.out.println("Student " + code + " doesn't existed!");
        } else {
            remove(student);
            System.out.println("Student " + code + " has been removed.");
        }
    }

    public void printAll() {
        if (isEmpty()) {
            System.out.println("Empty list!");
            return;
        }
        System.out.println("Student list:");
        for (Student student : this) {
            System.out.println(student);
        }
        System.out.println("Total: " + size() + " student(s).");
    }

    public void sortByMarkDecresing() {
        Collections.sort(this);
    }

    public void sortByMarkInCresing() {
        Collections.sort(this, new Comparator<Student>() {
            @Override
            public int compare(Student a, Student b) {
                if (a.getMark() > b.getMark()) {
                    return 1;
                }
                return a.getMark() == b.getMark() ? a.getName().compareTo(b.getName()) : -1;
            }
        });
    }
}

package unchecked;

public class SifiraBolmeHatasi {

    public static void main(String[] args) {

        // Simulated input pair, second value causes a division-by-zero
        String[] values = {"10", "0"};

        try {
            int numerator = Integer.parseInt(values[0]);
            int denominator = Integer.parseInt(values[1]);

            int result = numerator / denominator;
            System.out.println("Sonuc: " + result);

        } catch (NumberFormatException nfe) {
            System.out.println("Gecersiz giris: Lutfen sadece tamsayi giriniz.");
            System.out.println("Istisna mesaji: " + nfe.getMessage());
            nfe.printStackTrace();

        } catch (ArithmeticException ae) {
            System.out.println("Sifira bolme hatasi olustu!");
            System.out.println("Istisna mesaji: " + ae.getMessage());
            ae.printStackTrace();

        } catch (ArrayIndexOutOfBoundsException aioobe) {
            System.out.println("Eksik giris: Lutfen iki sayi giriniz.");
            System.out.println("Istisna mesaji: " + aioobe.getMessage());
            aioobe.printStackTrace();

        } finally {
            System.out.println("Finally bloguna girildi!");
        }

        try {
            successfulPathDemo();
        } catch (Exception unexpected) {
            System.out.println("Beklenmeyen bir hata: " + unexpected.getMessage());
        }
    }

    /**
     * Runs a division that is guaranteed to succeed.
     */
    public static void successfulPathDemo() {
        System.out.println("Basarili akis testi calisiyor.");
        int a = 10;
        int b = 5;
        int outcome = a / b;
        System.out.println("10 / 5 = " + outcome);
        System.out.println("Her sey yolunda, istisna firlatilmadi!");
    }
}

import java.util.Stack;

public class BalancedBrackets {
    /**
     * Checks whether the bracket sequence in the string is balanced.
     * Supports (), [] and {}.
     */
    public static boolean isBalanced(String expression) {
        Stack<Character> stack = new Stack<>();
        for (char c : expression.toCharArray()) {
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
            } else if (c == ')' || c == ']' || c == '}') {
                if (stack.isEmpty()) {
                    return false;
                }
                char open = stack.pop();
                if ((c == ')' && open != '(')
                        || (c == ']' && open != '[')
                        || (c == '}' && open != '{')) {
                    return false;
                }
            }
        }
        return stack.isEmpty();
    }

    public static void main(String[] args) {
        System.out.println(isBalanced("{[()()]}"));  // true
        System.out.println(isBalanced("([)]"));      // false
    }
}

/**
 * A circle composed of a center MyPoint and a radius.
 */
class MyPoint {

    private int x;
    private int y;

    public MyPoint() {
    }

    public MyPoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int[] getXY() {
        return new int[]{x, y};
    }

    public void setXY(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public double distance(int x, int y) {
        return Math.sqrt(Math.pow(x - this.x, 2) + Math.pow(y - this.y, 2));
    }

    public double distance(MyPoint another) {
        return Math.sqrt(Math.pow(another.x - x, 2) + Math.pow(another.y - y, 2));
    }

    public double distance() {
        return Math.sqrt(Math.pow(-x, 2) + Math.pow(-y, 2));
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ')';
    }
}

public class MyCircle {
    private MyPoint center;
    private int radius;

    public MyCircle() {
    }

    public MyCircle(MyPoint center, int radius) {
        this.center = center;
        this.radius = radius;
    }

    public MyCircle(int x, int y, int radius) {
        this.center = new MyPoint(x, y);
        this.radius = radius;
    }

    public MyPoint getCenter() {
        return center;
    }

    public void setCenter(MyPoint center) {
        this.center = center;
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }

    public int getCenterX() {
        return center.getX();
    }

    public int getCenterY() {
        return center.getY();
    }

    public void setCenterX(int x) {
        center.setX(x);
    }

    public void setCenterY(int y) {
        // mirrors the original's bug: this sets X instead of Y
        center.setX(y);
    }

    public int[] getCenterXY() {
        return center.getXY();
    }

    public void setCenterXY(int x, int y) {
        center.setXY(x, y);
    }

    public double getArea() {
        return Math.pow(radius, 2) * Math.PI;
    }

    public double getCircumference() {
        return radius * 2 * Math.PI;
    }

    public double distance(MyCircle another) {
        return center.distance(another.center);
    }

    @Override
    public String toString() {
        return "MyCircle[radius=" + radius + ",center=" + center.toString() + ']';
    }
}

class TestMyCircle {
    public static void main(String[] args) {
        MyCircle myCircle = new MyCircle(new MyPoint(5, 8), 6);
        System.out.println(myCircle.distance(new MyCircle(new MyPoint(30, 46), 2)));
        System.out.println(myCircle.getArea());
        System.out.println(myCircle.getCircumference());
        System.out.println(myCircle.toString());
        System.out.println(Arrays.toString(myCircle.getCenterXY()));
    }
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.Set;

/**
 * A class that counts the number of different connected components in a graph
 *
 * @author Lukas Keul, Florian Mercks
 */
class Graph<E extends Comparable<E>> {

    class Node {

        E name;

        Node(E name) {
            this.name = name;
        }
    }

    class Edge {

        Node startNode;
        Node endNode;

        Edge(Node startNode, Node endNode) {
            this.startNode = startNode;
            this.endNode = endNode;
        }
    }

    ArrayList<Edge> edgeList;
    ArrayList<Node> nodeList;

    Graph() {
        edgeList = new ArrayList<Edge>();
        nodeList = new ArrayList<Node>();
    }

    /**
     * Adds a new Edge to the graph. If the nodes aren't yet in nodeList, they
     * will be added to it.
     *
     * @param startNode the starting Node from the edge
     * @param endNode the ending Node from the edge
     */
    public void addEdge(E startNode, E endNode) {
        Node start = null;
        Node end = null;
        for (Node node : nodeList) {
            if (startNode.compareTo(node.name) == 0) {
                start = node;
            } else if (endNode.compareTo(node.name) == 0) {
                end = node;
            }
        }
        if (start == null) {
            start = new Node(startNode);
            nodeList.add(start);
        }
        if (end == null) {
            end = new Node(endNode);
            nodeList.add(end);
        }

        edgeList.add(new Edge(start, end));
    }

    /**
     * Main method used for counting the connected components. Iterates through
     * the array of nodes to do a depth first search to get all nodes of the
     * graph from the actual node. These nodes are added to the array
     * markedNodes and will be ignored if they are chosen in the nodeList.
     *
     * @return returns the amount of unconnected graphs
     */
    public int countGraphs() {
        int count = 0;
        Set<Node> markedNodes = new HashSet<Node>();

        for (Node n : nodeList) {
            if (markedNodes.add(n)) {
                markedNodes.addAll(depthFirstSearch(n, new ArrayList<Node>()));
                count++;
            }
        }

        return count;
    }

    /**
     * Implementation of depth first search.
     *
     * @param n the actual visiting node
     * @param visited A list of already visited nodes in the depth first search
     * @return returns a set of visited nodes
     */
    public ArrayList<Node> depthFirstSearch(Node n, ArrayList<Node> visited) {
        visited.add(n);
        for (Edge e : edgeList) {
            if (e.startNode.equals(n) && !visited.contains(e.endNode)) {
                depthFirstSearch(e.endNode, visited);
            }
        }
        return visited;
    }
}

public final class ConnectedComponent {
    private ConnectedComponent() {
    }

    public static void main(String[] args) {
        Graph<Character> graphChars = new Graph<>();

        // Graph 1
        graphChars.addEdge('a', 'b');
        graphChars.addEdge('a', 'e');
        graphChars.addEdge('b', 'e');
        graphChars.addEdge('b', 'c');
        graphChars.addEdge('c', 'd');
        graphChars.addEdge('d', 'a');

        graphChars.addEdge('x', 'y');
        graphChars.addEdge('x', 'z');

        graphChars.addEdge('w', 'w');

        Graph<Integer> graphInts = new Graph<>();

        // Graph 2
        graphInts.addEdge(1, 2);
        graphInts.addEdge(2, 3);
        graphInts.addEdge(2, 4);
        graphInts.addEdge(3, 5);

        graphInts.addEdge(7, 8);
        graphInts.addEdge(8, 10);
        graphInts.addEdge(10, 8);

        System.out.println("Amount of different char-graphs: " + graphChars.countGraphs());
        System.out.println("Amount of different int-graphs: " + graphInts.countGraphs());
    }
}

