public class ArtanSiraDortSayi {

	public static void main(String[] args) {

		Scanner okuyucu = new Scanner(System.in);

		System.out.print("Birinci sayiyi girin: ");
		int a = okuyucu.nextInt();

		System.out.print("ikinci sayiyi girin: ");
		int b = okuyucu.nextInt();

		System.out.print("ucuncu sayiyi girin: ");
		int c = okuyucu.nextInt();

		System.out.print("Dorduncu sayiyi girin: ");
		int d = okuyucu.nextInt();

		okuyucu.close();

		// Dort degeri diziye koyup dongu ile siraliyoruz (secmeli siralama mantigi)
		int[] degerler = { a, b, c, d };

		for (int i = 0; i < degerler.length; i++) {
			int enKucukIndex = i;
			for (int j = i + 1; j < degerler.length; j++) {
				if (degerler[j] < degerler[enKucukIndex]) {
					enKucukIndex = j;
				}
			}
			if (enKucukIndex != i) {
				int gecici = degerler[i];
				degerler[i] = degerler[enKucukIndex];
				degerler[enKucukIndex] = gecici;
			}
		}

		System.out.println("Artan sirayla: " + degerler[0] + ", " + degerler[1] + ", " + degerler[2] + ", " + degerler[3]);
	}
}

