/**
 *
 * @author GIA KINH
 */
public class MyTime {
    private int hour;
    private int minute;
    private int second;

    public MyTime(int hour, int minute, int second) {
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    public int getHour() {
        return hour;
    }

    public void setHour(int hour) {
        this.hour = hour;
    }

    public int getMinute() {
        return minute;
    }

    public void setMinute(int minute) {
        this.minute = minute;
    }

    public int getSecond() {
        return second;
    }

    public void setSecond(int second) {
        this.second = second;
    }

    public void setTime(int hour, int minute, int second){
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    @Override
    public String toString() {
        String timeString = String.format("%d:%d:%d", hour, minute, second);
        Date time= null;
        try {
            time = new SimpleDateFormat("HH:mm:ss").parse(timeString);
        } catch (ParseException ex) {
            Logger.getLogger(MyTime.class.getName()).log(Level.SEVERE, null, ex);
        }
        timeString = new SimpleDateFormat("HH:mm:ss").format(time);
        return timeString;
    }

    public MyTime nextHour(){
        this.hour++;
        return this;
    }

    public MyTime nextMinute(){
        this.minute++;
        return this;
    }

    public MyTime nextSecond(){
        this.second++;
        return this;
    }


    public MyTime previousHour(){
        this.hour--;
        return this;
    }

    public MyTime previousMinute(){
        this.minute--;
        return this;
    }

    public MyTime previousSecond(){
        this.second--;
        return this;
    }   
}

class TestMyTime{
    public static void main(String[] args) {
        MyTime myTime = new MyTime(23,59,59);
        System.out.println(myTime);
        myTime.nextHour();
        System.out.println(myTime);
        myTime.nextSecond();
        System.out.println(myTime);
    }
}

package com.thealgorithms.maths;

import java.util.Arrays;

public final class AbsoluteMin {
    private AbsoluteMin() {
    }

    /**
     * Compares the numbers given as arguments to get the absolute min value.
     *
     * @param numbers The numbers to compare
     * @return The absolute min value
     */
    public static int getMinValue(int... numbers) {
        if (numbers.length == 0) {
            throw new IllegalArgumentException("Numbers array cannot be empty");
        }

        var absMinWrapper = new Object() { int value = numbers[0]; };

        Arrays.stream(numbers).skip(1).filter(number -> Math.abs(number) <= Math.abs(absMinWrapper.value)).forEach(number -> absMinWrapper.value = Math.min(absMinWrapper.value, number));

        return absMinWrapper.value;
    }
}

package chat;

import java.io.IOException;
import java.io.PrintWriter;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;
import java.util.concurrent.Executors;

/**
 * Broadcast-style chat server. Every connected client gets a unique
 * screen name and every message a client sends is relayed to everyone.
 */
public class ChatServer {

    private static final int PORT = 59001;
    private static final int POOL_SIZE = 500;

    // Names currently taken, guards against duplicates
    private static final Set<String> takenNames = new HashSet<>();

    // Output streams for every connected client, used to broadcast
    private static final Set<PrintWriter> subscribers = new HashSet<>();

    public static void main(String[] args) throws Exception {
        System.out.println("Chat server calisiyor...");
        var workers = Executors.newFixedThreadPool(POOL_SIZE);

        try (var serverSocket = new ServerSocket(PORT)) {
            System.out.println(serverSocket.getInetAddress().toString());
            while (true) {
                workers.execute(new ClientSession(serverSocket.accept()));
            }
        }
    }

    // One instance per connected client; owns the negotiation and relay loop
    private static class ClientSession implements Runnable {
        private String screenName;
        private final Socket socket;
        private PrintWriter out;

        ClientSession(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try (var in = new Scanner(socket.getInputStream())) {
                out = new PrintWriter(socket.getOutputStream(), true);

                negotiateName(in);

                out.println("NAMEACCEPTED " + screenName);
                announce(screenName + " katildi");
                subscribers.add(out);

                relayMessages(in);
            } catch (Exception e) {
                System.out.println(e);
            } finally {
                cleanup();
            }
        }

        // Keeps asking for a name until it gets a unique, non-blank one
        private void negotiateName(Scanner in) {
            while (true) {
                out.println("SUBMITNAME");
                screenName = in.nextLine();
                if (screenName == null) {
                    return;
                }
                synchronized (takenNames) {
                    if (!screenName.isBlank() && !takenNames.contains(screenName)) {
                        takenNames.add(screenName);
                        break;
                    }
                }
            }
        }

        // Reads chat lines until the client asks to quit, broadcasting each one
        private void relayMessages(Scanner in) {
            while (true) {
                String message = in.nextLine();
                if (message.toLowerCase().startsWith("/quit")) {
                    return;
                }
                announce(screenName + ": " + message);
            }
        }

        private void announce(String text) {
            for (PrintWriter subscriber : subscribers) {
                subscriber.println("MESSAGE " + text);
            }
        }

        private void cleanup() {
            if (out != null) {
                subscribers.remove(out);
            }
            if (screenName != null) {
                System.out.println(screenName + " ayriliyor");
                takenNames.remove(screenName);
                announce(screenName + " ayrildi");
            }
            try {
                socket.close();
            } catch (IOException e) {
                System.out.println("Socket kapatilirken hata: " + e.getMessage());
            }
        }
    }
}

/**
 * A Java implementation of Caesar Cipher. /It is a type of substitution cipher
 * in which each letter in the plaintext is replaced by a letter some fixed
 * number of positions down the alphabet. /
 *
 * @author FAHRI YARDIMCI
 * @author khalil2535
 */
public class Caesar {
    private static char normalizeShift(final int shift) {
        return (char) (shift % 26);
    }

    /**
     * Encrypt text by shifting every Latin char by add number shift for ASCII
     * Example : A + 1 -> B
     *
     * @return Encrypted message
     */
    public String encode(String message, int shift) {
        StringBuilder encoded = new StringBuilder();

        final char shiftChar = normalizeShift(shift);

        final int length = message.length();
        for (int i = 0; i < length; i++) {
            //            int current = message.charAt(i); //using char to shift characters because
            //            ascii
            // is in-order latin alphabet
            char current = message.charAt(i); // Java law : char + int = char

            if (isCapitalLatinLetter(current)) {
                current += shiftChar;
                encoded.append((char) (current > 'Z' ? current - 26 : current)); // 26 = number of latin letters
            } else if (isSmallLatinLetter(current)) {
                current += shiftChar;
                encoded.append((char) (current > 'z' ? current - 26 : current)); // 26 = number of latin letters
            } else {
                encoded.append(current);
            }
        }
        return encoded.toString();
    }

    /**
     * Decrypt message by shifting back every Latin char to previous the ASCII
     * Example : B - 1 -> A
     *
     * @return message
     */
    public String decode(String encryptedMessage, int shift) {
        StringBuilder decoded = new StringBuilder();

        final char shiftChar = normalizeShift(shift);

        final int length = encryptedMessage.length();
        for (int i = 0; i < length; i++) {
            char current = encryptedMessage.charAt(i);
            if (isCapitalLatinLetter(current)) {
                current -= shiftChar;
                decoded.append((char) (current < 'A' ? current + 26 : current)); // 26 = number of latin letters
            } else if (isSmallLatinLetter(current)) {
                current -= shiftChar;
                decoded.append((char) (current < 'a' ? current + 26 : current)); // 26 = number of latin letters
            } else {
                decoded.append(current);
            }
        }
        return decoded.toString();
    }

    /**
     * @return true if character is capital Latin letter or false for others
     */
    private static boolean isCapitalLatinLetter(char c) {
        return c >= 'A' && c <= 'Z';
    }

    /**
     * @return true if character is small Latin letter or false for others
     */
    private static boolean isSmallLatinLetter(char c) {
        return c >= 'a' && c <= 'z';
    }

    /**
     *  @return string array which contains all the possible decoded combination.
     */
    public String[] bruteforce(String encryptedMessage) {
        String[] listOfAllTheAnswers = new String[27];
        for (int i = 0; i <= 26; i++) {
            listOfAllTheAnswers[i] = decode(encryptedMessage, i);
        }

        return listOfAllTheAnswers;
    }
}

