public class MatrixMultiplication {
    public static int[][] multiply(int[][] a, int[][] b) {
        int rows = a.length;
        int cols = b[0].length;
        int common = b.length;

        int[][] result = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                for (int k = 0; k < common; k++) {
                    result[i][j] += a[i][k] * b[k][j];
                }
            }
        }
        return result;
    }

    public static void main(String[] args) {
        int[][] first = {{1, 2}, {3, 4}};
        int[][] second = {{5, 6}, {7, 8}};

        int[][] product = multiply(first, second);
        for (int[] row : product) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

/**
 * A class providing algorithms to compute the convex hull of a set of points
 * using brute-force and recursive methods.
 *
 * Convex hull: The smallest convex polygon that contains all the given points.
 *
 * Algorithms provided:
 * 1. Brute-Force Method
 * 2. Recursive (Divide-and-Conquer) Method
 *
 * @author Hardvan
 */
public final class ConvexHull {
    private ConvexHull() {
    }

    private static boolean checkPointOrientation(Point i, Point j, Point k) {
        int detK = Point.orientation(i, j, k);
        if (detK > 0) {
            return true; // pointsLeftOfIJ
        } else if (detK < 0) {
            return false; // pointsRightOfIJ
        } else {
            return k.compareTo(i) >= 0 && k.compareTo(j) <= 0;
        }
    }

    public static List<Point> convexHullBruteForce(List<Point> points) {
        Set<Point> convexSet = new TreeSet<>(Comparator.naturalOrder());

        for (int i = 0; i < points.size() - 1; i++) {
            for (int j = i + 1; j < points.size(); j++) {
                boolean allPointsOnOneSide = true;
                boolean leftSide = checkPointOrientation(points.get(i), points.get(j), points.get((i + 1) % points.size()));

                for (int k = 0; k < points.size(); k++) {
                    if (k != i && k != j && checkPointOrientation(points.get(i), points.get(j), points.get(k)) != leftSide) {
                        allPointsOnOneSide = false;
                        break;
                    }
                }

                if (allPointsOnOneSide) {
                    convexSet.add(points.get(i));
                    convexSet.add(points.get(j));
                }
            }
        }

        return new ArrayList<>(convexSet);
    }

    /**
     * Computes the convex hull using a recursive divide-and-conquer approach.
     * Returns points in counter-clockwise order starting from the bottom-most, left-most point.
     *
     * @param points the input points
     * @return the convex hull points in counter-clockwise order
     */
    public static List<Point> convexHullRecursive(List<Point> points) {
        if (points.size() < 3) {
            List<Point> result = new ArrayList<>(points);
            Collections.sort(result);
            return result;
        }

        Collections.sort(points);
        Set<Point> convexSet = new HashSet<>();
        Point leftMostPoint = points.getFirst();
        Point rightMostPoint = points.getLast();

        convexSet.add(leftMostPoint);
        convexSet.add(rightMostPoint);

        List<Point> upperHull = new ArrayList<>();
        List<Point> lowerHull = new ArrayList<>();

        for (int i = 1; i < points.size() - 1; i++) {
            int det = Point.orientation(leftMostPoint, rightMostPoint, points.get(i));
            if (det > 0) {
                upperHull.add(points.get(i));
            } else if (det < 0) {
                lowerHull.add(points.get(i));
            }
        }

        constructHull(upperHull, leftMostPoint, rightMostPoint, convexSet);
        constructHull(lowerHull, rightMostPoint, leftMostPoint, convexSet);

        // Convert to list and sort in counter-clockwise order
        return sortCounterClockwise(new ArrayList<>(convexSet));
    }

    private static void constructHull(Collection<Point> points, Point left, Point right, Set<Point> convexSet) {
        if (!points.isEmpty()) {
            Point extremePoint = null;
            int extremePointDistance = Integer.MIN_VALUE;
            List<Point> candidatePoints = new ArrayList<>();

            for (Point p : points) {
                int det = Point.orientation(left, right, p);
                if (det > 0) {
                    candidatePoints.add(p);
                    if (det > extremePointDistance) {
                        extremePointDistance = det;
                        extremePoint = p;
                    }
                }
            }

            if (extremePoint != null) {
                constructHull(candidatePoints, left, extremePoint, convexSet);
                convexSet.add(extremePoint);
                constructHull(candidatePoints, extremePoint, right, convexSet);
            }
        }
    }

    /**
     * Sorts convex hull points in counter-clockwise order starting from
     * the bottom-most, left-most point.
     *
     * @param hullPoints the unsorted convex hull points
     * @return the points sorted in counter-clockwise order
     */
    private static List<Point> sortCounterClockwise(List<Point> hullPoints) {
        if (hullPoints.size() <= 2) {
            Collections.sort(hullPoints);
            return hullPoints;
        }

        // Find the bottom-most, left-most point (pivot)
        Point pivot = hullPoints.getFirst();
        for (Point p : hullPoints) {
            if (p.y() < pivot.y() || (p.y() == pivot.y() && p.x() < pivot.x())) {
                pivot = p;
            }
        }

        // Sort other points by polar angle with respect to pivot
        final Point finalPivot = pivot;
        List<Point> sorted = new ArrayList<>(hullPoints);
        sorted.remove(finalPivot);

        sorted.sort((p1, p2) -> {
            int crossProduct = Point.orientation(finalPivot, p1, p2);

            if (crossProduct == 0) {
                // Collinear points: sort by distance from pivot (closer first for convex hull)
                long dist1 = distanceSquared(finalPivot, p1);
                long dist2 = distanceSquared(finalPivot, p2);
                return Long.compare(dist1, dist2);
            }

            // Positive cross product means p2 is counter-clockwise from p1
            // We want counter-clockwise order, so if p2 is CCW from p1, p1 should come first
            return -crossProduct;
        });

        // Build result with pivot first, filtering out intermediate collinear points
        List<Point> result = new ArrayList<>();
        result.add(finalPivot);

        if (!sorted.isEmpty()) {
            // This loop iterates through the points sorted by angle.
            // For points that are collinear with the pivot, we only want the one that is farthest away.
            // The sort places closer points first.
            for (int i = 0; i < sorted.size() - 1; i++) {
                // Check the orientation of the pivot, the current point, and the next point.
                int orientation = Point.orientation(finalPivot, sorted.get(i), sorted.get(i + 1));

                // If the orientation is not 0, it means the next point (i+1) is at a new angle.
                // Therefore, the current point (i) must be the farthest point at its angle. We keep it.
                if (orientation != 0) {
                    result.add(sorted.get(i));
                }
                // If the orientation is 0, the points are collinear. We discard the current point (i)
                // because it is closer to the pivot than the next point (i+1).
            }
            // Always add the very last point from the sorted list. It is either the only point
            // at its angle, or it's the farthest among a set of collinear points.
            result.add(sorted.getLast());
        }

        return result;
    }

    /**
     * Computes the squared distance between two points to avoid floating point operations.
     */
    private static long distanceSquared(Point p1, Point p2) {
        long dx = (long) p1.x() - p2.x();
        long dy = (long) p1.y() - p2.y();
        return dx * dx + dy * dy;
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/**
 * Given tree is traversed in an 'inorder' way: LEFT -> ROOT -> RIGHT.
 * Below are given the recursive and iterative implementations.
 *
 * Complexities:
 * Recursive: O(n) - time, O(n) - space, where 'n' is the number of nodes in a tree.
 *
 * Iterative: O(n) - time, O(h) - space, where 'n' is the number of nodes in a tree
 * and 'h' is the height of a binary tree.
 * In the worst case 'h' can be O(n) if tree is completely unbalanced, for instance:
 * 5
 *  \
 *   6
 *    \
 *     7
 *      \
 *       8
 *
 * @author Albina Gimaletdinova on 21/02/2023
 */
public final class InorderTraversal {
    private InorderTraversal() {
    }
    public static List<Integer> recursiveInorder(BinaryTree.Node root) {
        List<Integer> result = new ArrayList<>();
        recursiveInorder(root, result);
        return result;
    }

    public static List<Integer> iterativeInorder(BinaryTree.Node root) {
        List<Integer> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        Deque<BinaryTree.Node> stack = new ArrayDeque<>();
        while (!stack.isEmpty() || root != null) {
            while (root != null) {
                stack.push(root);
                root = root.left;
            }
            root = stack.pop();
            result.add(root.data);
            root = root.right;
        }
        return result;
    }

    private static void recursiveInorder(BinaryTree.Node root, List<Integer> result) {
        if (root == null) {
            return;
        }
        recursiveInorder(root.left, result);
        result.add(root.data);
        recursiveInorder(root.right, result);
    }
}

public class NumberGuessingGame {
    public static void main(String[] args) {
        Random random = new Random();
        Scanner scanner = new Scanner(System.in);
        int secret = random.nextInt(100) + 1;
        int attempts = 0;

        System.out.println("Guess a number between 1 and 100!");

        while (true) {
            System.out.print("Your guess: ");
            int guess = scanner.nextInt();
            attempts++;

            if (guess < secret) {
                System.out.println("Too low!");
            } else if (guess > secret) {
                System.out.println("Too high!");
            } else {
                System.out.println("Correct! Attempts: " + attempts);
                break;
            }
        }
        scanner.close();
    }
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * This class implements Johnson's algorithm for finding all-pairs shortest paths in a weighted,
 * directed graph that may contain negative edge weights.
 *
 * Johnson's algorithm works by using the Bellman-Ford algorithm to compute a transformation of the
 * input graph that removes all negative weights, allowing Dijkstra's algorithm to be used for
 * efficient shortest path computations.
 *
 * Time Complexity: O(V^2 * log(V) + V*E)
 * Space Complexity: O(V^2)
 *
 * Where V is the number of vertices and E is the number of edges in the graph.
 *
 * For more information, please visit {@link https://en.wikipedia.org/wiki/Johnson%27s_algorithm}
 */
public final class JohnsonsAlgorithm {

private static final double INFINITY_VALUE = Double.POSITIVE_INFINITY;

private JohnsonsAlgorithm() {
}

/**
 * Executes Johnson's algorithm on the given graph.
 * Steps:
 * 1. Add a new vertex to the graph and run Bellman-Ford to compute modified weights
 * 2. Reweight the graph using the modified weights
 * 3. Run Dijkstra's algorithm for each vertex to compute the shortest paths
 * The final result is a 2D array of shortest distances between all pairs of vertices.
 *
 * @param weightMatrix The input graph represented as an adjacency matrix.
 * @return A 2D array representing the shortest distances between all pairs of vertices.
 */
public static double[][] computeShortestPaths(double[][] weightMatrix) {
int totalVertices = weightMatrix.length;
double[][] edgeList = convertToEdgeArray(weightMatrix);
double[] adjustmentFactors = applyBellmanFord(edgeList, totalVertices);
double[][] adjustedGraph = reweightGraphEdges(weightMatrix, adjustmentFactors);
double[][] distanceMatrix = new double[totalVertices][totalVertices];
for (int startNode = 0; startNode < totalVertices; startNode++) {
distanceMatrix[startNode] = runDijkstra(adjustedGraph, startNode, adjustmentFactors);
}
return distanceMatrix;
}

/**
 * Converts the adjacency matrix representation of the graph to an edge list.
 *
 * @param weightMatrix The input graph as an adjacency matrix.
 * @return An array of edges, where each edge is represented as [from, to, weight].
 */
public static double[][] convertToEdgeArray(double[][] weightMatrix) {
int totalVertices = weightMatrix.length;
List<double[]> edgeCollection = new ArrayList<>();
for (int rowIndex = 0; rowIndex < totalVertices; rowIndex++) {
for (int colIndex = 0; colIndex < totalVertices; colIndex++) {
if (rowIndex != colIndex && !Double.isInfinite(weightMatrix[rowIndex][colIndex])) {
edgeCollection.add(new double[] {rowIndex, colIndex, weightMatrix[rowIndex][colIndex]});
}
}
}
return edgeCollection.toArray(new double[0][]);
}

/**
 * Implements the Bellman-Ford algorithm to compute the shortest paths from a new vertex
 * to all other vertices. This is used to calculate the weight function h(v) for reweighting.
 *
 * @param edgeData The edge list of the graph.
 * @param totalVertices The number of vertices in the original graph.
 * @return An array of modified weights for each vertex.
 */
private static double[] applyBellmanFord(double[][] edgeData, int totalVertices) {
double[] distanceValues = new double[totalVertices + 1];
Arrays.fill(distanceValues, INFINITY_VALUE);
distanceValues[totalVertices] = 0;
double[][] extendedEdges = Arrays.copyOf(edgeData, edgeData.length + totalVertices);
for (int vertexIndex = 0; vertexIndex < totalVertices; vertexIndex++) {
extendedEdges[edgeData.length + vertexIndex] = new double[] {totalVertices, vertexIndex, 0};
}
for (int passCount = 0; passCount < totalVertices; passCount++) {
for (double[] currentEdge : extendedEdges) {
int sourceNode = (int) currentEdge[0];
int targetNode = (int) currentEdge[1];
double edgeWeight = currentEdge[2];
if (distanceValues[sourceNode] != INFINITY_VALUE && distanceValues[sourceNode] + edgeWeight < distanceValues[targetNode]) {
distanceValues[targetNode] = distanceValues[sourceNode] + edgeWeight;
}
}
}
for (double[] currentEdge : extendedEdges) {
int sourceNode = (int) currentEdge[0];
int targetNode = (int) currentEdge[1];
double edgeWeight = currentEdge[2];
if (distanceValues[sourceNode] + edgeWeight < distanceValues[targetNode]) {
throw new IllegalArgumentException("Graph contains a negative weight cycle");
}
}
return Arrays.copyOf(distanceValues, totalVertices);
}

/**
 * Reweights the graph using the modified weights computed by Bellman-Ford.
 *
 * @param weightMatrix The original graph.
 * @param adjustmentFactors The modified weights from Bellman-Ford.
 * @return The reweighted graph.
 */
public static double[][] reweightGraphEdges(double[][] weightMatrix, double[] adjustmentFactors) {
int totalVertices = weightMatrix.length;
double[][] transformedMatrix = new double[totalVertices][totalVertices];
for (int rowIndex = 0; rowIndex < totalVertices; rowIndex++) {
for (int colIndex = 0; colIndex < totalVertices; colIndex++) {
if (weightMatrix[rowIndex][colIndex] != 0) {
transformedMatrix[rowIndex][colIndex] = weightMatrix[rowIndex][colIndex] + adjustmentFactors[rowIndex] - adjustmentFactors[colIndex];
}
}
}
return transformedMatrix;
}

/**
 * Implements Dijkstra's algorithm for finding shortest paths from a source vertex.
 *
 * @param adjustedGraph The reweighted graph to run Dijkstra's on.
 * @param startVertex The source vertex.
 * @param adjustmentFactors The modified weights from Bellman-Ford.
 * @return An array of shortest distances from the source to all other vertices.
 */
public static double[] runDijkstra(double[][] adjustedGraph, int startVertex, double[] adjustmentFactors) {
int totalVertices = adjustedGraph.length;
double[] distanceValues = new double[totalVertices];
boolean[] processedFlags = new boolean[totalVertices];
Arrays.fill(distanceValues, INFINITY_VALUE);
distanceValues[startVertex] = 0;
for (int iteration = 0; iteration < totalVertices - 1; iteration++) {
int currentVertex = findMinimumVertex(distanceValues, processedFlags);
processedFlags[currentVertex] = true;
for (int neighborIndex = 0; neighborIndex < totalVertices; neighborIndex++) {
if (!processedFlags[neighborIndex] &&
adjustedGraph[currentVertex][neighborIndex] != 0 &&
distanceValues[currentVertex] != INFINITY_VALUE &&
distanceValues[currentVertex] + adjustedGraph[currentVertex][neighborIndex] < distanceValues[neighborIndex]) {
distanceValues[neighborIndex] = distanceValues[currentVertex] + adjustedGraph[currentVertex][neighborIndex];
}
}
}
for (int vertexIndex = 0; vertexIndex < totalVertices; vertexIndex++) {
if (distanceValues[vertexIndex] != INFINITY_VALUE) {
distanceValues[vertexIndex] = distanceValues[vertexIndex] - adjustmentFactors[startVertex] + adjustmentFactors[vertexIndex];
}
}
return distanceValues;
}

/**
 * Finds the vertex with the minimum distance value from the set of vertices
 * not yet included in the shortest path tree.
 *
 * @param distanceValues Array of distances.
 * @param processedFlags Array of visited vertices.
 * @return The index of the vertex with minimum distance.
 */
public static int findMinimumVertex(double[] distanceValues, boolean[] processedFlags) {
double minimumValue = INFINITY_VALUE;
int minIndex = -1;
for (int vertexIndex = 0; vertexIndex < distanceValues.length; vertexIndex++) {
if (!processedFlags[vertexIndex] && distanceValues[vertexIndex] <= minimumValue) {
minimumValue = distanceValues[vertexIndex];
minIndex = vertexIndex;
}
}
return minIndex;
}
}

/**
 * The CircularQueue class represents a generic circular queue data structure that uses an array to
 * store elements. This queue allows efficient utilization of space by wrapping around the array,
 * thus avoiding the need to shift elements during enqueue and dequeue operations.
 *
 * <p>When the queue reaches its maximum capacity, further enqueues will raise an exception.
 * Similarly, attempts to dequeue or peek from an empty queue will also result in an exception.
 *
 * <p>Reference: <a href="https://en.wikipedia.org/wiki/Circular_buffer">Circular Buffer</a>
 *
 * <p>Usage Example:
 * <pre>
 *     CircularQueue<Integer> queue = new CircularQueue<>(3);
 *     queue.enQueue(1);
 *     queue.enQueue(2);
 *     queue.enQueue(3);
 *     queue.deQueue(); // Removes 1
 *     queue.enQueue(4); // Wraps around and places 4 at the position of removed 1
 * </pre>
 *
 * @param <T> the type of elements in this queue
 */
public class CircularQueue<T> {
    private T[] array;
    private int topOfQueue;
    private int beginningOfQueue;
    private final int size;
    private int currentSize;

    /**
     * Constructs a CircularQueue with a specified capacity.
     *
     * @param size the maximum number of elements this queue can hold
     * @throws IllegalArgumentException if the size is less than 1
     */
    @SuppressWarnings("unchecked")
    public CircularQueue(int size) {
        if (size < 1) {
            throw new IllegalArgumentException("Size must be greater than 0");
        }
        this.array = (T[]) new Object[size];
        this.topOfQueue = -1;
        this.beginningOfQueue = -1;
        this.size = size;
        this.currentSize = 0;
    }

    /**
     * Checks if the queue is empty.
     *
     * @return {@code true} if the queue is empty; {@code false} otherwise
     */
    public boolean isEmpty() {
        return currentSize == 0;
    }

    /**
     * Checks if the queue is full.
     *
     * @return {@code true} if the queue has reached its maximum capacity; {@code false} otherwise
     */
    public boolean isFull() {
        return currentSize == size;
    }

    /**
     * Adds a new element to the queue. If the queue is full, an exception is thrown.
     *
     * @param value the element to be added to the queue
     * @throws IllegalStateException if the queue is already full
     */
    public void enQueue(T value) {
        if (isFull()) {
            throw new IllegalStateException("Queue is full");
        }
        if (isEmpty()) {
            beginningOfQueue = 0;
        }
        topOfQueue = (topOfQueue + 1) % size;
        array[topOfQueue] = value;
        currentSize++;
    }

    /**
     * Removes and returns the element at the front of the queue.
     *
     * @return the element at the front of the queue
     * @throws IllegalStateException if the queue is empty
     */
    public T deQueue() {
        if (isEmpty()) {
            throw new IllegalStateException("Queue is empty");
        }
        T removedValue = array[beginningOfQueue];
        array[beginningOfQueue] = null; // Optional: Nullify to help garbage collection
        beginningOfQueue = (beginningOfQueue + 1) % size;
        currentSize--;
        if (isEmpty()) {
            beginningOfQueue = -1;
            topOfQueue = -1;
        }
        return removedValue;
    }

    /**
     * Returns the element at the front of the queue without removing it.
     *
     * @return the element at the front of the queue
     * @throws IllegalStateException if the queue is empty
     */
    public T peek() {
        if (isEmpty()) {
            throw new IllegalStateException("Queue is empty");
        }
        return array[beginningOfQueue];
    }

    /**
     * Deletes the entire queue by resetting all elements and pointers.
     */
    public void deleteQueue() {
        array = null;
        beginningOfQueue = -1;
        topOfQueue = -1;
        currentSize = 0;
    }

    /**
     * Returns the current number of elements in the queue.
     *
     * @return the number of elements currently in the queue
     */
    public int size() {
        return currentSize;
    }
}

