/**
 * Class to represent the Midpoint Circle Algorithm.
 * This algorithm calculates points on the circumference of a circle
 * using integer arithmetic for efficient computation.
 */
public final class MidpointCircle {

    private MidpointCircle() {
        // Private Constructor to prevent instantiation.
    }

    /**
     * Generates points on the circumference of a circle using the midpoint circle algorithm.
     *
     * @param centerX The x-coordinate of the circle's center.
     * @param centerY The y-coordinate of the circle's center.
     * @param radius  The radius of the circle.
     * @return A list of points on the circle, each represented as an int[] with 2 elements [x, y].
     */
    public static List<int[]> generateCirclePoints(int centerX, int centerY, int radius) {
        List<int[]> points = new ArrayList<>();

        // Special case for radius 0, only the center point should be added.
        if (radius == 0) {
            points.add(new int[] {centerX, centerY});
            return points;
        }

        // Start at (radius, 0)
        int x = radius;
        int y = 0;

        // Decision parameter
        int p = 1 - radius;

        // Add the initial points in all octants
        addSymmetricPoints(points, centerX, centerY, x, y);

        // Iterate while x > y
        while (x > y) {
            y++;

            if (p <= 0) {
                // Midpoint is inside or on the circle
                p = p + 2 * y + 1;
            } else {
                // Midpoint is outside the circle
                x--;
                p = p + 2 * y - 2 * x + 1;
            }

            // Add points for this (x, y)
            addSymmetricPoints(points, centerX, centerY, x, y);
        }

        return points;
    }

    /**
     * Adds the symmetric points in all octants of the circle based on the current x and y values.
     *
     * @param points  The list to which symmetric points will be added.
     * @param centerX The x-coordinate of the circle's center.
     * @param centerY The y-coordinate of the circle's center.
     * @param x       The current x-coordinate on the circumference.
     * @param y       The current y-coordinate on the circumference.
     */
    private static void addSymmetricPoints(Collection<int[]> points, int centerX, int centerY, int x, int y) {
        // Octant symmetry points
        points.add(new int[] {centerX + x, centerY + y});
        points.add(new int[] {centerX - x, centerY + y});
        points.add(new int[] {centerX + x, centerY - y});
        points.add(new int[] {centerX - x, centerY - y});
        points.add(new int[] {centerX + y, centerY + x});
        points.add(new int[] {centerX - y, centerY + x});
        points.add(new int[] {centerX + y, centerY - x});
        points.add(new int[] {centerX - y, centerY - x});
    }
}

/**
 * Given a text and wildcard pattern implement a wildcard pattern matching
 * algorithm that finds if wildcard is matched with text. The matching should
 * cover the entire text ?-> matches single characters *-> match the sequence of
 * characters
 *
 * For calculation of Time and Space Complexity. Let N be length of src and M be length of pat
 *
 * Memoization vs Tabulation : https://www.geeksforgeeks.org/tabulation-vs-memoization/
 * Question Link : https://practice.geeksforgeeks.org/problems/wildcard-pattern-matching/1
 */
public final class RegexMatching {
    private RegexMatching() {
    }

    /**
     * Method 1: Determines if the given source string matches the given pattern using a recursive approach.
     * This method directly applies recursion to check if the source string matches the pattern, considering
     * the wildcards '?' and '*'.
     *
     * Time Complexity: O(2^(N+M)), where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N + M) due to the recursion stack.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    public static boolean regexRecursion(String src, String pat) {
        if (src.length() == 0 && pat.length() == 0) {
            return true;
        }
        if (src.length() != 0 && pat.length() == 0) {
            return false;
        }
        if (src.length() == 0 && pat.length() != 0) {
            for (int i = 0; i < pat.length(); i++) {
                if (pat.charAt(i) != '*') {
                    return false;
                }
            }
            return true;
        }
        char chs = src.charAt(0);
        char chp = pat.charAt(0);

        String ros = src.substring(1);
        String rop = pat.substring(1);

        boolean ans;
        if (chs == chp || chp == '?') {
            ans = regexRecursion(ros, rop);
        } else if (chp == '*') {
            boolean blank = regexRecursion(src, rop);
            boolean multiple = regexRecursion(ros, pat);
            ans = blank || multiple;
        } else {
            ans = false;
        }
        return ans;
    }

    /**
     * Method 2: Determines if the given source string matches the given pattern using recursion.
     * This method utilizes a virtual index for both the source string and the pattern to manage the recursion.
     *
     * Time Complexity: O(2^(N+M)) where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N + M) due to the recursion stack.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @param svidx The current index in the source string.
     * @param pvidx The current index in the pattern.
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    static boolean regexRecursion(String src, String pat, int svidx, int pvidx) {
        if (src.length() == svidx && pat.length() == pvidx) {
            return true;
        }
        if (src.length() != svidx && pat.length() == pvidx) {
            return false;
        }
        if (src.length() == svidx && pat.length() != pvidx) {
            for (int i = pvidx; i < pat.length(); i++) {
                if (pat.charAt(i) != '*') {
                    return false;
                }
            }
            return true;
        }
        char chs = src.charAt(svidx);
        char chp = pat.charAt(pvidx);

        boolean ans;
        if (chs == chp || chp == '?') {
            ans = regexRecursion(src, pat, svidx + 1, pvidx + 1);
        } else if (chp == '*') {
            boolean blank = regexRecursion(src, pat, svidx, pvidx + 1);
            boolean multiple = regexRecursion(src, pat, svidx + 1, pvidx);
            ans = blank || multiple;
        } else {
            ans = false;
        }
        return ans;
    }

    /**
     * Method 3: Determines if the given source string matches the given pattern using top-down dynamic programming (memoization).
     * This method utilizes memoization to store intermediate results, reducing redundant computations and improving efficiency.
     *
     * Time Complexity: O(N * M), where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N * M) for the memoization table, plus additional space for the recursion stack.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @param svidx The current index in the source string.
     * @param pvidx The current index in the pattern.
     * @param strg A 2D array used for memoization to store the results of subproblems.
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    public static boolean regexRecursion(String src, String pat, int svidx, int pvidx, int[][] strg) {
        if (src.length() == svidx && pat.length() == pvidx) {
            return true;
        }
        if (src.length() != svidx && pat.length() == pvidx) {
            return false;
        }
        if (src.length() == svidx && pat.length() != pvidx) {
            for (int i = pvidx; i < pat.length(); i++) {
                if (pat.charAt(i) != '*') {
                    return false;
                }
            }
            return true;
        }
        if (strg[svidx][pvidx] != 0) {
            return strg[svidx][pvidx] != 1;
        }
        char chs = src.charAt(svidx);
        char chp = pat.charAt(pvidx);

        boolean ans;
        if (chs == chp || chp == '?') {
            ans = regexRecursion(src, pat, svidx + 1, pvidx + 1, strg);
        } else if (chp == '*') {
            boolean blank = regexRecursion(src, pat, svidx, pvidx + 1, strg);
            boolean multiple = regexRecursion(src, pat, svidx + 1, pvidx, strg);
            ans = blank || multiple;
        } else {
            ans = false;
        }
        strg[svidx][pvidx] = ans ? 2 : 1;
        return ans;
    }

    /**
     * Method 4: Determines if the given source string matches the given pattern using bottom-up dynamic programming (tabulation).
     * This method builds a solution iteratively by filling out a table, where each cell represents whether a substring
     * of the source string matches a substring of the pattern.
     *
     * Time Complexity: O(N * M), where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N * M) for the table used in the tabulation process.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    static boolean regexBU(String src, String pat) {
        boolean[][] strg = new boolean[src.length() + 1][pat.length() + 1];
        strg[src.length()][pat.length()] = true;
        for (int row = src.length(); row >= 0; row--) {
            for (int col = pat.length() - 1; col >= 0; col--) {
                if (row == src.length()) {
                    if (pat.charAt(col) == '*') {
                        strg[row][col] = strg[row][col + 1];
                    } else {
                        strg[row][col] = false;
                    }
                } else {
                    char chs = src.charAt(row);
                    char chp = pat.charAt(col);

                    boolean ans;
                    if (chs == chp || chp == '?') {
                        ans = strg[row + 1][col + 1];
                    } else if (chp == '*') {
                        boolean blank = strg[row][col + 1];
                        boolean multiple = strg[row + 1][col];
                        ans = blank || multiple;
                    } else {
                        ans = false;
                    }
                    strg[row][col] = ans;
                }
            }
        }
        return strg[0][0];
    }
}

package com.thealgorithms.datastructures.caches;

import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.BiConsumer;

/**
 * A thread-safe generic cache implementation using the First-In-First-Out eviction policy.
 * <p>
 * The cache holds a fixed number of entries, defined by its capacity. When the cache is full and a
 * new entry is added, the oldest entry in the cache is selected and evicted to make space.
 * <p>
 * Optionally, entries can have a time-to-live (TTL) in milliseconds. If a TTL is set, entries will
 * automatically expire and be removed upon access or insertion attempts.
 * <p>
 * Features:
 * <ul>
 *     <li>Removes oldest entry when capacity is exceeded</li>
 *     <li>Optional TTL (time-to-live in milliseconds) per entry or default TTL for all entries</li>
 *     <li>Thread-safe access using locking</li>
 *     <li>Hit and miss counters for cache statistics</li>
 *     <li>Eviction listener callback support</li>
 * </ul>
 *
 * @param <KeyType> the type of keys maintained by this cache
 * @param <ValueType> the type of mapped values
 * See <a href="https://en.wikipedia.org/wiki/Cache_replacement_policies#First_in_first_out_(FIFO)">FIFO</a>
 * @author Kevin Babu (<a href="https://www.github.com/KevinMwita7">GitHub</a>)
 */
public final class FIFOCache<KeyType, ValueType> {

private final int maxCapacity;
private final long globalTTL;
private final Map<KeyType, CachedEntry<ValueType>> storageMap;
private final Lock accessLock;

private long hitCount = 0;
private long missCount = 0;
private final BiConsumer<KeyType, ValueType> removalCallback;
private final EvictionHandler<KeyType, ValueType> evictionHandler;

/**
 * Internal structure to store value + expiry timestamp.
 *
 * @param <ValueType> the type of the value being cached
 */
private static class CachedEntry<ValueType> {
ValueType storedValue;
long expirationTime;

/**
 * Constructs a new {@code CachedEntry} with the specified value and time-to-live (TTL).
 * If TTL is 0, the entry is kept indefinitely, that is, unless it is the first value,
 * then it will be removed according to the FIFO principle
 *
 * @param valueData    the value to cache
 * @param ttlMillis the time-to-live in milliseconds
 */
CachedEntry(ValueType valueData, long ttlMillis) {
this.storedValue = valueData;
if (ttlMillis == 0) {
this.expirationTime = Long.MAX_VALUE;
} else {
this.expirationTime = System.currentTimeMillis() + ttlMillis;
}
}

/**
 * Checks if the cache entry has expired.
 *
 * @return {@code true} if the current time is past the expiration time; {@code false} otherwise
 */
boolean isExpired() {
return System.currentTimeMillis() > expirationTime;
}
}

/**
 * Constructs a new {@code FIFOCache} instance using the provided {@link Builder}.
 *
 * <p>This constructor initializes the cache with the specified capacity and default TTL,
 * sets up internal data structures (a {@code LinkedHashMap} for cache entries and configures eviction.
 *
 * @param configBuilder the {@code Builder} object containing configuration parameters
 */
private FIFOCache(Builder<KeyType, ValueType> configBuilder) {
this.maxCapacity = configBuilder.maxCapacity;
this.globalTTL = configBuilder.globalTTL;
this.storageMap = new LinkedHashMap<>();
this.accessLock = new ReentrantLock();
this.removalCallback = configBuilder.removalCallback;
this.evictionHandler = configBuilder.evictionHandler;
}

/**
 * Retrieves the value associated with the specified key from the cache.
 *
 * <p>If the key is not present or the corresponding entry has expired, this method
 * returns {@code null}. If an expired entry is found, it will be removed and the
 * eviction listener (if any) will be notified. Cache hit-and-miss statistics are
 * also updated accordingly.
 *
 * @param searchKey the key whose associated value is to be returned; must not be {@code null}
 * @return the cached value associated with the key, or {@code null} if not present or expired
 * @throws IllegalArgumentException if {@code searchKey} is {@code null}
 */
public ValueType get(KeyType searchKey) {
if (searchKey == null) {
throw new IllegalArgumentException("Key must not be null");
}
accessLock.lock();
try {
evictionHandler.onAccess(this);
CachedEntry<ValueType> targetEntry = storageMap.get(searchKey);
if (targetEntry == null || targetEntry.isExpired()) {
if (targetEntry != null) {
storageMap.remove(searchKey);
notifyRemoval(searchKey, targetEntry.storedValue);
}
missCount++;
return null;
}
hitCount++;
return targetEntry.storedValue;
} finally {
accessLock.unlock();
}
}

/**
 * Adds a key-value pair to the cache using the default time-to-live (TTL).
 *
 * <p>The key may overwrite an existing entry. The actual insertion is delegated
 * to the overloaded {@link #put(KeyType, ValueType, long)} method.
 *
 * @param insertKey   the key to cache the value under
 * @param insertValue the value to be cached
 */
public void put(KeyType insertKey, ValueType insertValue) {
put(insertKey, insertValue, globalTTL);
}

/**
 * Adds a key-value pair to the cache with a specified time-to-live (TTL).
 *
 * <p>If the key already exists, its value is removed, re-inserted at tail and its TTL is reset.
 * If the key does not exist and the cache is full, the oldest entry is evicted to make space.
 * Expired entries are also cleaned up prior to any eviction. The eviction listener
 * is notified when an entry gets evicted.
 *
 * @param insertKey        the key to associate with the cached value; must not be {@code null}
 * @param insertValue      the value to be cached; must not be {@code null}
 * @param timeToLiveMillis  the time-to-live for this entry in milliseconds; must be >= 0
 * @throws IllegalArgumentException if {@code insertKey} or {@code insertValue} is {@code null}, or if {@code timeToLiveMillis} is negative
 */
public void put(KeyType insertKey, ValueType insertValue, long timeToLiveMillis) {
if (insertKey == null || insertValue == null) {
throw new IllegalArgumentException("Key and value must not be null");
}
if (timeToLiveMillis < 0) {
throw new IllegalArgumentException("TTL must be >= 0");
}
accessLock.lock();
try {
CachedEntry<ValueType> existingEntry = storageMap.remove(insertKey);
if (existingEntry != null && !existingEntry.isExpired()) {
notifyRemoval(insertKey, existingEntry.storedValue);
}
removeExpiredEntries();
if (storageMap.size() >= maxCapacity) {
Iterator<Map.Entry<KeyType, CachedEntry<ValueType>>> iterator = storageMap.entrySet().iterator();
if (iterator.hasNext()) {
Map.Entry<KeyType, CachedEntry<ValueType>> oldestEntry = iterator.next();
iterator.remove();
notifyRemoval(oldestEntry.getKey(), oldestEntry.getValue().storedValue);
}
}
storageMap.put(insertKey, new CachedEntry<>(insertValue, timeToLiveMillis));
} finally {
accessLock.unlock();
}
}

/**
 * Removes all expired entries from the cache.
 *
 * <p>This method iterates through the list of cached keys and checks each associated
 * entry for expiration. Expired entries are removed the cache map. For each eviction,
 * the eviction listener is notified.
 */
private int removeExpiredEntries() {
int removedCount = 0;
Iterator<Map.Entry<KeyType, CachedEntry<ValueType>>> iterator = storageMap.entrySet().iterator();
while (iterator.hasNext()) {
Map.Entry<KeyType, CachedEntry<ValueType>> currentEntry = iterator.next();
if (currentEntry != null && currentEntry.getValue().isExpired()) {
iterator.remove();
notifyRemoval(currentEntry.getKey(), currentEntry.getValue().storedValue);
removedCount++;
}
}
return removedCount;
}

/**
 * Removes the specified key and its associated entry from the cache.
 *
 * @param targetKey the key to remove from the cache;
 * @return the value associated with the key;  or {@code null} if no such key exists
 */
public ValueType removeKey(KeyType targetKey) {
if (targetKey == null) {
throw new IllegalArgumentException("Key cannot be null");
}
CachedEntry<ValueType> removedEntry = storageMap.remove(targetKey);
if (removedEntry == null) {
return null;
}
notifyRemoval(targetKey, removedEntry.storedValue);
return removedEntry.storedValue;
}

/**
 * Notifies the eviction listener, if one is registered, that a key-value pair has been evicted.
 *
 * <p>If the {@code removalCallback} is not {@code null}, it is invoked with the provided key
 * and value. Any exceptions thrown by the listener are caught and logged to standard error,
 * preventing them from disrupting cache operations.
 *
 * @param evictedKey   the key that was evicted
 * @param evictedValue the value that was associated with the evicted key
 */
private void notifyRemoval(KeyType evictedKey, ValueType evictedValue) {
if (removalCallback != null) {
try {
removalCallback.accept(evictedKey, evictedValue);
} catch (Exception executionError) {
System.err.println("Eviction listener failed: " + executionError.getMessage());
}
}
}

/**
 * Returns the number of successful cache lookups (hits).
 *
 * @return the number of cache hits
 */
public long getHitCount() {
accessLock.lock();
try {
return hitCount;
} finally {
accessLock.unlock();
}
}

/**
 * Returns the number of failed cache lookups (misses), including expired entries.
 *
 * @return the number of cache misses
 */
public long getMissCount() {
accessLock.lock();
try {
return missCount;
} finally {
accessLock.unlock();
}
}

/**
 * Returns the current number of entries in the cache, excluding expired ones.
 *
 * @return the current cache size
 */
public int getCurrentSize() {
accessLock.lock();
try {
evictionHandler.onAccess(this);
int activeCount = 0;
for (CachedEntry<ValueType> entryData : storageMap.values()) {
if (!entryData.isExpired()) {
++activeCount;
}
}
return activeCount;
} finally {
accessLock.unlock();
}
}

/**
 * Removes all entries from the cache, regardless of their expiration status.
 *
 * <p>This method clears the internal cache map entirely, resets the hit-and-miss counters,
 * and notifies the eviction listener (if any) for each removed entry.
 * Note that expired entries are treated the same as active ones for the purpose of clearing.
 *
 * <p>This operation acquires the internal lock to ensure thread safety.
 */
public void clearAll() {
accessLock.lock();
try {
for (Map.Entry<KeyType, CachedEntry<ValueType>> entryItem : storageMap.entrySet()) {
notifyRemoval(entryItem.getKey(), entryItem.getValue().storedValue);
}
storageMap.clear();
hitCount = 0;
missCount = 0;
} finally {
accessLock.unlock();
}
}

/**
 * Returns a set of all keys currently stored in the cache that have not expired.
 *
 * <p>This method iterates through the cache and collects the keys of all non-expired entries.
 * Expired entries are ignored but not removed. If you want to ensure expired entries are cleaned up,
 * consider invoking {@link EvictionHandler#onAccess(FIFOCache)} or calling {@link #removeExpiredEntries()} manually.
 *
 * <p>This operation acquires the internal lock to ensure thread safety.
 *
 * @return a set containing all non-expired keys currently in the cache
 */
public Set<KeyType> getAllActiveKeys() {
accessLock.lock();
try {
Set<KeyType> activeKeys = new LinkedHashSet<>();
for (Map.Entry<KeyType, CachedEntry<ValueType>> entryItem : storageMap.entrySet()) {
if (!entryItem.getValue().isExpired()) {
activeKeys.add(entryItem.getKey());
}
}
return activeKeys;
} finally {
accessLock.unlock();
}
}

/**
 * Returns the current {@link EvictionHandler} used by this cache instance.

 * @return the eviction strategy currently assigned to this cache
 */
public EvictionHandler<KeyType, ValueType> getEvictionHandler() {
return evictionHandler;
}

/**
 * Returns a string representation of the cache, including metadata and current non-expired entries.
 *
 * <p>The returned string includes the cache's capacity, current size (excluding expired entries),
 * hit-and-miss counts, and a map of all non-expired key-value pairs. This method acquires a lock
 * to ensure thread-safe access.
 *
 * @return a string summarizing the state of the cache
 */
@Override
public String toString() {
accessLock.lock();
try {
Map<KeyType, ValueType> visibleEntries = new LinkedHashMap<>();
for (Map.Entry<KeyType, CachedEntry<ValueType>> entryItem : storageMap.entrySet()) {
if (!entryItem.getValue().isExpired()) {
visibleEntries.put(entryItem.getKey(), entryItem.getValue().storedValue);
}
}
return String.format("Cache(capacity=%d, size=%d, hits=%d, misses=%d, entries=%s)", maxCapacity, visibleEntries.size(), hitCount, missCount, visibleEntries);
} finally {
accessLock.unlock();
}
}

/**
 * A strategy interface for controlling when expired entries are evicted from the cache.
 *
 * <p>Implementations decide whether and when to trigger {@link FIFOCache#removeExpiredEntries()} based
 * on cache usage patterns. This allows for flexible eviction behaviour such as periodic cleanup,
 * or no automatic cleanup.
 *
 * @param <KeyType> the type of keys maintained by the cache
 * @param <ValueType> the type of cached values
 */
public interface EvictionHandler<KeyType, ValueType> {
/**
 * Called on each cache access (e.g., {@link FIFOCache#get(Object)}) to optionally trigger eviction.
 *
 * @param targetCache the cache instance on which this strategy is applied
 * @return the number of expired entries evicted during this access
 */
int onAccess(FIFOCache<KeyType, ValueType> targetCache);
}

/**
 * An eviction strategy that performs eviction of expired entries on each call.
 *
 * @param <KeyType> the type of keys
 * @param <ValueType> the type of values
 */
public static class ImmediateEvictionHandler<KeyType, ValueType> implements EvictionHandler<KeyType, ValueType> {
@Override
public int onAccess(FIFOCache<KeyType, ValueType> targetCache) {
return targetCache.removeExpiredEntries();
}
}

/**
 * An eviction strategy that triggers eviction on every fixed number of accesses.
 *
 * <p>This deterministic strategy ensures cleanup occurs at predictable intervals,
 * ideal for moderately active caches where memory usage is a concern.
 *
 * @param <KeyType> the type of keys
 * @param <ValueType> the type of values
 */
public static class PeriodicEvictionHandler<KeyType, ValueType> implements EvictionHandler<KeyType, ValueType> {
private final int accessInterval;
private final AtomicInteger accessCounter = new AtomicInteger();

/**
 * Constructs a periodic eviction strategy.
 *
 * @param intervalSteps the number of accesses between evictions; must be > 0
 * @throws IllegalArgumentException if {@code intervalSteps} is less than or equal to 0
 */
public PeriodicEvictionHandler(int intervalSteps) {
if (intervalSteps <= 0) {
throw new IllegalArgumentException("Interval must be > 0");
}
this.accessInterval = intervalSteps;
}

@Override
public int onAccess(FIFOCache<KeyType, ValueType> targetCache) {
if (accessCounter.incrementAndGet() % accessInterval == 0) {
return targetCache.removeExpiredEntries();
}
return 0;
}
}

/**
 * A builder for constructing a {@link FIFOCache} instance with customizable settings.
 *
 * <p>Allows configuring capacity, default TTL, eviction listener, and a pluggable eviction
 * strategy. Call {@link #build()} to create the configured cache instance.
 *
 * @param <KeyType> the type of keys maintained by the cache
 * @param <ValueType> the type of values stored in the cache
 */
public static class Builder<KeyType, ValueType> {
private final int maxCapacity;
private long globalTTL = 0;
private BiConsumer<KeyType, ValueType> removalCallback;
private EvictionHandler<KeyType, ValueType> evictionHandler = new FIFOCache.ImmediateEvictionHandler<>();

/**
 * Creates a new {@code Builder} with the specified cache capacity.
 *
 * @param capacityLimit the maximum number of entries the cache can hold; must be > 0
 * @throws IllegalArgumentException if {@code capacityLimit} is less than or equal to 0
 */
public Builder(int capacityLimit) {
if (capacityLimit <= 0) {
throw new IllegalArgumentException("Capacity must be > 0");
}
this.maxCapacity = capacityLimit;
}

/**
 * Sets the default time-to-live (TTL) in milliseconds for cache entries.
 *
 * @param ttlValue the TTL duration in milliseconds; must be >= 0
 * @return this builder instance for chaining
 * @throws IllegalArgumentException if {@code ttlValue} is negative
 */
public Builder<KeyType, ValueType> defaultTTL(long ttlValue) {
if (ttlValue < 0) {
throw new IllegalArgumentException("Default TTL must be >= 0");
}
this.globalTTL = ttlValue;
return this;
}

/**
 * Sets an eviction listener to be notified when entries are evicted from the cache.
 *
 * @param listenerCallback a {@link BiConsumer} that accepts evicted keys and values; must not be {@code null}
 * @return this builder instance for chaining
 * @throws IllegalArgumentException if {@code listenerCallback} is {@code null}
 */
public Builder<KeyType, ValueType> evictionListener(BiConsumer<KeyType, ValueType> listenerCallback) {
if (listenerCallback == null) {
throw new IllegalArgumentException("Listener must not be null");
}
this.removalCallback = listenerCallback;
return this;
}

/**
 * Builds and returns a new {@link FIFOCache} instance with the configured parameters.
 *
 * @return a fully configured {@code FIFOCache} instance
 */
public FIFOCache<KeyType, ValueType> build() {
return new FIFOCache<>(this);
}

/**
 * Sets the eviction strategy used to determine when to clean up expired entries.
 *
 * @param handlerStrategy an {@link EvictionHandler} implementation; must not be {@code null}
 * @return this builder instance
 * @throws IllegalArgumentException if {@code handlerStrategy} is {@code null}
 */
public Builder<KeyType, ValueType> evictionStrategy(EvictionHandler<KeyType, ValueType> handlerStrategy) {
if (handlerStrategy == null) {
throw new IllegalArgumentException("Eviction strategy must not be null");
}
this.evictionHandler = handlerStrategy;
return this;
}
}
}

package com.thealgorithms.datastructures.trees;

/**
 * This code recursively validates whether given Binary Search Tree (BST) is balanced or not.
 * Trees with only distinct values are supported.
 * Key points:
 * 1. According to the definition of a BST, each node in a tree must be in range [min, max],
 *    where 'min' and 'max' values represent the child nodes (left, right).
 * 2. The smallest possible node value is Integer.MIN_VALUE, the biggest - Integer.MAX_VALUE.
 */
public final class CheckBinaryTreeIsValidBST {
    private CheckBinaryTreeIsValidBST() {
    }
    public static boolean isBST(BinaryTree.Node root) {
        return isBSTUtil(root, Integer.MIN_VALUE, Integer.MAX_VALUE);
    }

    private static boolean isBSTUtil(BinaryTree.Node node, int min, int max) {
        // empty tree is a BST
        if (node == null) {
            return true;
        }

        if (node.data < min || node.data > max) {
            return false;
        }

        return (isBSTUtil(node.left, min, node.data - 1) && isBSTUtil(node.right, node.data + 1, max));
    }
}

public class StringSorter {
    public static void main(String[] args) {
        String[] words = {"banana", "Apple", "cherry", "date", "Elderberry"};

        // Sort ignoring case
        Arrays.sort(words, String.CASE_INSENSITIVE_ORDER);
        System.out.println("Case-insensitive: " + Arrays.toString(words));

        // Sort by length using a comparator
        Arrays.sort(words, Comparator.comparingInt(String::length));
        System.out.println("By length: " + Arrays.toString(words));
    }
}

public class Fibonacci {

    // Fibonacci dizisini iteratif olarak bulan metod
    public static int fibonacci(int sayi) {
        // Fibonacci sayilarini tutacak liste olustur
        List<Integer> liste = new ArrayList<>();
        // Ilk iki Fibonacci sayisini listeye ekle
        liste.add(0);
        liste.add(1);
        // Fibonacci dizisini iteratif olarak hesapla
        for (int i = 2; i < sayi + 1; i++) {
            // Onceki iki sayinin toplamini listeye ekle
            liste.add(liste.get(i - 2) + liste.get(i - 1));
        }
        // Istenen Fibonacci sayisini geri dondur
        return liste.get(sayi);
    }

    public static void main(String[] args) {

        // 10. Fibonacci sayisini hesapla
        int sonuc = fibonacci(10);
        // Sonucu ekrana yazdir
        System.out.println(sonuc);
    }
}

package overriding;

/*
 * Demonstrates overriding equals()/toString(): two Person
 * objects with identical field values compare equal via equals(),
 * even though they are different references.
 */
public class Kisi {

    private String isim;
    private int yasi;

    public Kisi(String isim, int yasi) {
        this.isim = isim;
        this.yasi = yasi;
    }

    // Value-based equality: same class, same name and age.
    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || getClass() != other.getClass()) {
            return false;
        }
        Kisi diger = (Kisi) other;
        return yasi == diger.yasi && isim.equals(diger.isim);
    }

    public String getAd() {
        return isim;
    }

    public int getYas() {
        return yasi;
    }

    @Override
    public String toString() {
        return "Kisi[Ad=" + isim + ", Yas=" + yasi + "]";
    }

    public static void main(String[] args) {
        Kisi kisiA = new Kisi("Ali", 25);
        Kisi kisiB = new Kisi("Ali", 25);

        // Reference comparison - expected to differ since they're distinct objects.
        if (kisiA == kisiB) {
            System.out.println("Iki kisi nesnesi esittir.");
        } else {
            System.out.println("Iki kisi nesnesi esit degildir.");
        }

        // Logical comparison via the overridden equals().
        if (kisiA.equals(kisiB)) {
            System.out.println("Iki kisi nesnesi esittir.");
        } else {
            System.out.println("Iki kisi nesnesi esit degildir.");
        }

        System.out.println(kisiA.toString());
    }
}

import java.util.Scanner;

public class SafeDivision {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            System.out.print("Enter numerator: ");
            int a = scanner.nextInt();
            System.out.print("Enter denominator: ");
            int b = scanner.nextInt();

            int result = a / b;
            System.out.println("Result: " + result);
        } catch (ArithmeticException e) {
            System.out.println("Error: division by zero is not allowed");
        } catch (Exception e) {
            System.out.println("Invalid input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }
}

package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Set;
import org.apache.commons.lang3.tuple.Pair;

/**
 * A class that handles unit conversions using affine transformations.
 *
 * <p>The {@code UnitsConverter} allows converting values between different units using
 * pre-defined affine conversion formulas. Each conversion is represented by an
 * {@link AffineConverter} that defines the scaling and offset for the conversion.
 *
 * <p>For each unit, both direct conversions (e.g., Celsius to Fahrenheit) and inverse
 * conversions (e.g., Fahrenheit to Celsius) are generated automatically. It also computes
 * transitive conversions (e.g., Celsius to Kelvin via Fahrenheit if both conversions exist).
 *
 * <p>Key features include:
 * <ul>
 *   <li>Automatic handling of inverse conversions (e.g., Fahrenheit to Celsius).</li>
 *   <li>Compositional conversions, meaning if conversions between A -> B and B -> C exist,
 *       it can automatically generate A -> C conversion.</li>
 *   <li>Supports multiple unit systems as long as conversions are provided in pairs.</li>
 * </ul>
 *
 * <h2>Example Usage</h2>
 * <pre>
 * Map&lt;Pair&lt;String, String&gt;, AffineConverter&gt; basicConversions = Map.ofEntries(
 *     entry(Pair.of("Celsius", "Fahrenheit"), new AffineConverter(9.0 / 5.0, 32.0)),
 *     entry(Pair.of("Kelvin", "Celsius"), new AffineConverter(1.0, -273.15))
 * );
 *
 * UnitsConverter converter = new UnitsConverter(basicConversions);
 * double result = converter.convert("Celsius", "Fahrenheit", 100.0);
 * // Output: 212.0 (Celsius to Fahrenheit conversion of 100°C)
 * </pre>
 *
 * <h2>Exception Handling</h2>
 * <ul>
 *   <li>If the input unit and output unit are the same, an {@link IllegalArgumentException} is thrown.</li>
 *   <li>If a conversion between the requested units does not exist, a {@link NoSuchElementException} is thrown.</li>
 * </ul>
 */
public final class UnitsConverter {
    private final Map<Pair<String, String>, AffineConverter> conversions;
    private final Set<String> units;

    private static void putIfNeeded(Map<Pair<String, String>, AffineConverter> conversions, final String inputUnit, final String outputUnit, final AffineConverter converter) {
        if (!inputUnit.equals(outputUnit)) {
            final var key = Pair.of(inputUnit, outputUnit);
            conversions.putIfAbsent(key, converter);
        }
    }

    private static Map<Pair<String, String>, AffineConverter> addInversions(final Map<Pair<String, String>, AffineConverter> knownConversions) {
        Map<Pair<String, String>, AffineConverter> res = new HashMap<Pair<String, String>, AffineConverter>();
        for (final var curConversion : knownConversions.entrySet()) {
            final var inputUnit = curConversion.getKey().getKey();
            final var outputUnit = curConversion.getKey().getValue();
            putIfNeeded(res, inputUnit, outputUnit, curConversion.getValue());
            putIfNeeded(res, outputUnit, inputUnit, curConversion.getValue().invert());
        }
        return res;
    }

    private static Map<Pair<String, String>, AffineConverter> addCompositions(final Map<Pair<String, String>, AffineConverter> knownConversions) {
        Map<Pair<String, String>, AffineConverter> res = new HashMap<Pair<String, String>, AffineConverter>();
        for (final var first : knownConversions.entrySet()) {
            final var firstKey = first.getKey();
            putIfNeeded(res, firstKey.getKey(), firstKey.getValue(), first.getValue());
            for (final var second : knownConversions.entrySet()) {
                final var secondKey = second.getKey();
                if (firstKey.getValue().equals(secondKey.getKey())) {
                    final var newConversion = second.getValue().compose(first.getValue());
                    putIfNeeded(res, firstKey.getKey(), secondKey.getValue(), newConversion);
                }
            }
        }
        return res;
    }

    private static Map<Pair<String, String>, AffineConverter> addAll(final Map<Pair<String, String>, AffineConverter> knownConversions) {
        final var res = addInversions(knownConversions);
        return addCompositions(res);
    }

    private static Map<Pair<String, String>, AffineConverter> computeAllConversions(final Map<Pair<String, String>, AffineConverter> basicConversions) {
        var tmp = basicConversions;
        var res = addAll(tmp);
        while (res.size() != tmp.size()) {
            tmp = res;
            res = addAll(tmp);
        }
        return res;
    }

    private static Set<String> extractUnits(final Map<Pair<String, String>, AffineConverter> conversions) {
        Set<String> res = new HashSet<>();
        for (final var conversion : conversions.entrySet()) {
            res.add(conversion.getKey().getKey());
        }
        return res;
    }

    /**
     * Constructor for {@code UnitsConverter}.
     *
     * <p>Accepts a map of basic conversions and automatically generates inverse and
     * transitive conversions.
     *
     * @param basicConversions the initial set of unit conversions to add.
     */
    public UnitsConverter(final Map<Pair<String, String>, AffineConverter> basicConversions) {
        conversions = computeAllConversions(basicConversions);
        units = extractUnits(conversions);
    }

    /**
     * Converts a value from one unit to another.
     *
     * @param inputUnit the unit of the input value.
     * @param outputUnit the unit to convert the value into.
     * @param value the value to convert.
     * @return the converted value in the target unit.
     * @throws IllegalArgumentException if inputUnit equals outputUnit.
     * @throws NoSuchElementException if no conversion exists between the units.
     */
    public double convert(final String inputUnit, final String outputUnit, final double value) {
        if (inputUnit.equals(outputUnit)) {
            throw new IllegalArgumentException("inputUnit must be different from outputUnit.");
        }
        final var conversionKey = Pair.of(inputUnit, outputUnit);
        return conversions.computeIfAbsent(conversionKey, k -> { throw new NoSuchElementException("No converter for: " + k); }).convert(value);
    }

    /**
     * Retrieves the set of all units supported by this converter.
     *
     * @return a set of available units.
     */
    public Set<String> availableUnits() {
        return units;
    }
}

