public final class DiffieHellman {

private final BigInteger generatorBase;
private final BigInteger privateSecret;
private final BigInteger sharedPrime;

// Constructor to initialize base, secret, and prime
public DiffieHellman(BigInteger generatorValue, BigInteger secretValue, BigInteger primeValue) {
if (generatorValue == null || secretValue == null || primeValue == null || generatorValue.signum() <= 0 || secretValue.signum() <= 0 || primeValue.signum() <= 0) {
throw new IllegalArgumentException("Generator, secret, and prime must be non-null and positive values.");
}
this.generatorBase = generatorValue;
this.privateSecret = secretValue;
this.sharedPrime = primeValue;
}

// Method to calculate public value (g^x mod p)
public BigInteger calculatePublicValue() {
return generatorBase.modPow(privateSecret, sharedPrime);
}

// Method to calculate the shared secret key (otherPublic^secret mod p)
public BigInteger calculateSharedSecret(BigInteger peerPublicValue) {
if (peerPublicValue == null || peerPublicValue.signum() <= 0) {
throw new IllegalArgumentException("Other public value must be non-null and positive.");
}
return peerPublicValue.modPow(privateSecret, sharedPrime);
}
}

