public class Faktoriyel {

	// Ozyineleme kullanarak faktoriyeli hesaplar
	public static int ozyinelemeliFaktoriyel(int deger) {
		// Taban durum: 0'in faktoriyeli 1 kabul edilir
		if (deger == 0) {
			return 1;
		}
		// Genel durum: deger ile bir onceki degerin faktoriyeli carpilir
		return deger * ozyinelemeliFaktoriyel(deger - 1);
	}

	// Dongu kullanarak faktoriyeli hesaplar
	public static int donguluFaktoriyel(int deger) {
		int carpim = 1;
		int i = 1;
		// i, degere ulasana kadar carpima katilir
		while (i <= deger) {
			carpim *= i;
			i++;
		}
		return carpim;
	}

	public static void main(String[] args) {

		Scanner tarayici = new Scanner(System.in);
		System.out.print("Faktoriyelini hesaplamak icin bir sayi girin: ");
		int girilenSayi = tarayici.nextInt();
		tarayici.close();

		System.out.println(girilenSayi + " sayisinin faktoriyeli (iterative): " + donguluFaktoriyel(girilenSayi));
		System.out.println(girilenSayi + " sayisinin faktoriyeli (rekursive): " + ozyinelemeliFaktoriyel(girilenSayi));
	}
}

/**
 * This class contains a method to check if the binary representation of a number is a palindrome.
 * <p>
 *     A binary palindrome is a number whose binary representation is the same when read from left to right and right to left.
 *     For example, the number 9 has a binary representation of 1001, which is a palindrome.
 *     The number 10 has a binary representation of 1010, which is not a palindrome.
 * </p>
 *
 * @author Hardvan
 */
public final class BinaryPalindromeCheck {
    private BinaryPalindromeCheck() {
    }

    /**
     * Checks if the binary representation of a number is a palindrome.
     *
     * @param x The number to check.
     * @return True if the binary representation is a palindrome, otherwise false.
     */
    public static boolean isBinaryPalindrome(int x) {
        int reversed = reverseBits(x);
        return x == reversed;
    }

    /**
     * Helper function to reverse all the bits of an integer.
     *
     * @param x The number to reverse the bits of.
     * @return The number with reversed bits.
     */
    private static int reverseBits(int x) {
        int result = 0;
        while (x > 0) {
            result <<= 1;
            result |= (x & 1);
            x >>= 1;
        }
        return result;
    }
}

package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.Map;

/**
 * Converts any Binary Number to a Hexadecimal Number
 *
 * @author Nishita Aggarwal
 */
public final class BinaryToHexadecimal {
private static final int BITS_PER_HEX_DIGIT = 4;
private static final int BINARY_BASE = 2;
private static final int DECIMAL_BASE = 10;
private static final int HEX_LETTER_START = 10;
private static final int HEX_LETTER_END = 15;

private BinaryToHexadecimal() {
}

/**
 * Converts a binary number to a hexadecimal number.
 *
 * @param binaryInput The binary number to convert.
 * @return The hexadecimal representation of the binary number.
 * @throws IllegalArgumentException If the binary number contains digits other than 0 and 1.
 */
public static String binToHex(int binaryInput) {
Map<Integer, String> hexMapping = buildHexMapping();
StringBuilder hexResult = new StringBuilder();
int remainingBinary = binaryInput;
while (remainingBinary != 0) {
int decimalGroup = 0;
for (int bitPos = 0; bitPos < BITS_PER_HEX_DIGIT; bitPos++) {
int currentBit = remainingBinary % DECIMAL_BASE;
if (currentBit > 1) {
throw new IllegalArgumentException("Incorrect binary digit: " + currentBit);
}
remainingBinary /= DECIMAL_BASE;
decimalGroup += (int) (currentBit * Math.pow(BINARY_BASE, bitPos));
}
hexResult.insert(0, hexMapping.get(decimalGroup));
}
return !hexResult.isEmpty() ? hexResult.toString() : "0";
}

/**
 * Initializes the hexadecimal map with decimal to hexadecimal mappings.
 *
 * @return The initialized map containing mappings from decimal numbers to hexadecimal digits.
 */
private static Map<Integer, String> buildHexMapping() {
Map<Integer, String> hexMap = new HashMap<>();
for (int digitValue = 0; digitValue < DECIMAL_BASE; digitValue++) {
hexMap.put(digitValue, String.valueOf(digitValue));
}
for (int letterValue = HEX_LETTER_START; letterValue <= HEX_LETTER_END; letterValue++) {
hexMap.put(letterValue, String.valueOf((char) ('A' + letterValue - HEX_LETTER_START)));
}
return hexMap;
}
}

