public class Singleton {
    private int num = 0;
    private Singleton () { // private restricts from creating multiple objects

    }

    private static Singleton instance; // This is a static variable that will hold the single instance of the Singleton class. Being static ensures that the variable is shared across all instances of the class, but since the constructor is private, only the Singleton class itself can assign a value to it.

    public static synchronized Singleton getInstance() {
        // check whether 1 object only is created or not
        if (instance == null) {
            instance = new Singleton();
        }
        return instance;
    }
}
/*
class Example {
    Singleton.instance = new Singleton();
}

SINCE INSTANCE IS PRIVATE, IT CAN'T BE ACCESSED OUTSIDE THE SINGLETON CLASS. SINCE SINGLETON CONSTRUCTOR IS PRIVATE
IT CANNOT CREATE A NEW OBJECT OUTSIDE THE SINGLETON CLASS.
*/

public class WrapperClass {
    public static void main(String[] args) {
//        int a = 10;
//        int b = 30;
//
//        Integer num = 45;

        A pair = new A(10, 30);
        swap(pair);

        System.out.println(pair.a + " " + pair.b);

        final int bonus = 2; // using final fixes the value of the variable
        // bonus = 3; can't be done

        // final A Kunal = new A("Kunal Kushwaha");
        // Kunal.name = "Ankan";
        // When final is used for non-primitive data-types, their instances can be changed but the
        // object itself cannot be changed.
        // Kunal = new com.ankan.com.ankan.packages.A("new object");


    }
    static void swap (A pair) {
        int temp = pair.a;
        pair.a = pair.b;
        pair.b = temp;
    } // Since the swap didn't work, we use a wrapper class.
    // final student Kunal = new Student ()
    // Kunal.name = "new-name"; can be done
    // But Kunal = other object cannot happen
}

class A { // wrapper class
    final int num = 10; // final variable needs to be initialised first. final used for primitive data-types; their
    // values
    // can't be changed. But when final is used for non-primitive data-types, their instances can be changed but the
    // object itself cannot be changed.
    Integer a, b;  // When final is used for non-primitive data-types, their instances can be changed but the object
    // itself cannot be changed. But when an object is used as fields inside another object, it can be changed, as it
    // changes the reference to the object A, not the Integer object itself.

    public A(Integer a, Integer b) {
        this.a = a;
        this.b = b;
    }

    @Override
    protected void finalize() throws Throwable {
        System.out.println("Object is destroyed");
    }
}

package syntax;

public class Islecler {

    public static void main(String[] args) {

        int p = 10;
        int q = 20;
        int r = 30;

        // Arithmetic operators
        int addResult = p + q;      // 30
        int subResult = q - p;      // 10
        int mulResult = p * q;      // 200
        int divResult = q / p;      // 2
        int modResult = q % p;      // 0

        // Relational operators
        boolean isEqual = p == q;             // false
        boolean isNotEqual = p != q;          // true
        boolean isGreater = q > p;            // true
        boolean isLess = p < q;               // true
        boolean isGreaterOrEqual = p >= r;    // false
        boolean isLessOrEqual = p <= q;       // true

        // Logical operators
        boolean andResult = (p < q) && (q < r);   // true
        boolean orResult = (p < q) || (q > r);    // true
        boolean notResult = !(p < q);             // false

        // Report every computed value.
        System.out.println("Toplam: " + addResult);
        System.out.println("Fark: " + subResult);
        System.out.println("Carpim: " + mulResult);
        System.out.println("Bolum: " + divResult);
        System.out.println("Kalan: " + modResult);
        System.out.println("esitMi: " + isEqual);
        System.out.println("esitDegilMi: " + isNotEqual);
        System.out.println("buyukMu: " + isGreater);
        System.out.println("kucukMu: " + isLess);
        System.out.println("buyukVeyaEsitMi: " + isGreaterOrEqual);
        System.out.println("kucukVeyaEsitMi: " + isLessOrEqual);
        System.out.println("veSonuc: " + andResult);
        System.out.println("veyaSonuc: " + orResult);
        System.out.println("degilSonuc: " + notResult);
    }
}

package forloop;

public class ContinueOrnegi {

    // Sayilari tek ve cift olarak ayirt eden ornek
    public static void tekCiftAyristir() {
        System.out.println("Tek ve Cift Sayilar Ornegi:");
        int n = 1;
        while (n <= 10) {
            if (n % 2 == 0) { // cift sayi kontrolu
                System.out.println("Cift sayi: " + n);
                n++;
                continue; // cift oldugunda alttaki satir atlanir
            }
            System.out.println("Tek sayi: " + n);
            n++;
        }
    }

    // 3 veya 5 ile tam bolunen sayilari atlayan ornek
    public static void ucBesKatlariniAtla() {
        System.out.println("\n3 ve 5'in Katlarini Atlayan Ornek:");
        for (int n = 1; n <= 15; n++) {
            if (n % 3 == 0 || n % 5 == 0) { // 3 ya da 5'in kati mi kontrol edilir
                System.out.println("Atlanan sayi: " + n);
                continue; // katlar icin devam eden kod calismaz
            }
            System.out.println("Gecerli sayi: " + n);
        }
    }

    // Ic ice donguler icerisinde continue kullanan ornek
    public static void icIceContinueOrnek() {
        System.out.println("\nIc Ice Dongulerde Continue Ornegi:");
        int satir = 1;
        while (satir <= 3) {
            for (int sutun = 1; sutun <= 3; sutun++) {
                if (satir == sutun) { // indeksler esitse atla
                    System.out.println("i: " + satir + ", j: " + sutun + " -> Continue uygulandi");
                    continue; // esitlik durumunda geri kalan kod calismaz
                }
                System.out.println("i: " + satir + ", j: " + sutun);
            }
            satir++;
        }
    }

    public static void main(String[] args) {
        // Ornekleri sirayla calistir
        tekCiftAyristir();
        ucBesKatlariniAtla();
        icIceContinueOrnek();
    }
}

