package com.thealgorithms.dynamicprogramming;

/**
 * DynamicProgramming solution for the Egg Dropping Puzzle
 */
public final class EggDropping {
    private EggDropping() {
    }

    // min trials with n eggs and m floors
    public static int minTrials(int n, int m) {
        int[][] eggFloor = new int[n + 1][m + 1];
        int result;
        int x;

        for (int i = 1; i <= n; i++) {
            eggFloor[i][0] = 0; // Zero trial for zero floor.
            eggFloor[i][1] = 1; // One trial for one floor
        }

        // j trials for only 1 egg
        for (int j = 1; j <= m; j++) {
            eggFloor[1][j] = j;
        }

        // Using bottom-up approach in DP
        for (int i = 2; i <= n; i++) {
            for (int j = 2; j <= m; j++) {
                eggFloor[i][j] = Integer.MAX_VALUE;
                for (x = 1; x <= j; x++) {
                    result = 1 + Math.max(eggFloor[i - 1][x - 1], eggFloor[i][j - x]);

                    // choose min of all values for particular x
                    if (result < eggFloor[i][j]) {
                        eggFloor[i][j] = result;
                    }
                }
            }
        }

        return eggFloor[n][m];
    }

    public static void main(String[] args) {
        int n = 2;
        int m = 4;
        // result outputs min no. of trials in worst case for n eggs and m floors
        int result = minTrials(n, m);
        System.out.println(result);
    }
}

package syntax;

public class Islecler {

	public static void main(String[] args) {

		int x = 10; // x degiskenine 10 degeri atandi
		int y = 20; // y degiskenine 20 degeri atandi
		int z = 30; // z degiskenine 30 degeri atandi

		// Aritmetik operatorler
		int toplam = x + y; // toplam = 30
		int fark = y - x; // fark = 10
		int carpim = x * y; // carpim = 200
		int bolum = y / x; // bolum = 2
		int kalan = y % x; // kalan = 0

		// Karsilastirma operatorleri
		boolean esitMi = x == y; // esitMi = false
		boolean esitDegilMi = x != y; // esitDegilMi = true
		boolean buyukMu = y > x; // buyukMu = true
		boolean kucukMu = x < y; // kucukMu = true
		boolean buyukVeyaEsitMi = x >= z; // buyukVeyaEsitMi = false
		boolean kucukVeyaEsitMi = x <= y; // kucukVeyaEsitMi = true

		// Mantiksal operatorler
		boolean veSonuc = x < y && y < z; // veSonuc = true
		boolean veyaSonuc = x < y || y > z; // veyaSonuc = true
		boolean degilSonuc = !(x < y); // degilSonuc = false

		// Sonuclari ekrana yazdir
		System.out.println("Toplam: " + toplam);
		System.out.println("Fark: " + fark);
		System.out.println("Carpim: " + carpim);
		System.out.println("Bolum: " + bolum);
		System.out.println("Kalan: " + kalan);
		System.out.println("esitMi: " + esitMi);
		System.out.println("esitDegilMi: " + esitDegilMi);
		System.out.println("buyukMu: " + buyukMu);
		System.out.println("kucukMu: " + kucukMu);
		System.out.println("buyukVeyaEsitMi: " + buyukVeyaEsitMi);
		System.out.println("kucukVeyaEsitMi: " + kucukVeyaEsitMi);
		System.out.println("veSonuc: " + veSonuc);
		System.out.println("veyaSonuc: " + veyaSonuc);
		System.out.println("degilSonuc: " + degilSonuc);

	}
}

/**
 * @author <a href="https://github.com/siddhant2002">Siddhant Swarup Mallick</a>

 * In mathematics, the Golomb sequence is a non-decreasing integer sequence where n-th term is equal
 * to number of times n appears in the sequence.

 * <a href="https://en.wikipedia.org/wiki/Golomb_sequence">Wikipedia</a>
 * Program description - To find the Golomb sequence upto n
 */
public final class CountFriendsPairing {
    private CountFriendsPairing() {
    }

    public static boolean countFriendsPairing(int n, int[] a) {
        int[] dp = new int[n + 1];
        // array of n+1 size is created
        dp[0] = 1;
        // since 1st index position value is fixed so it's marked as 1
        for (int i = 1; i < n; i++) {
            dp[i] = 1 + dp[i - dp[dp[i - 1]]];
            // formula for ith golomb sequence is dp(i) = 1 + dp(i – dp(dp(i - 1)))
        }
        for (int i = 1; i < n; i++) {
            if (a[i - 1] != dp[i]) {
                return false;
                // checks whether the calculated answer matches with the expected answer
            }
        }
        return true;
        // returns true if calculated answer matches with the expected answer
    }
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

/**
 * Gomory–Hu tree construction for undirected graphs via n−1 max-flow computations.
 *
 * <p>API: {@code buildTree(int[][])} returns {@code {parent, weight}} arrays for the tree.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Gomory%E2%80%93Hu_tree">Wikipedia: Gomory–Hu tree</a>
 */

public final class GomoryHuTree {
    private GomoryHuTree() {
    }

    public static int[][] buildTree(int[][] cap) {
        validateCapacityMatrix(cap);
        final int n = cap.length;
        if (n == 1) {
            return new int[][] {new int[] {-1}, new int[] {0}};
        }

        int[] parent = new int[n];
        int[] weight = new int[n];
        Arrays.fill(parent, 0);
        parent[0] = -1;
        weight[0] = 0;

        for (int s = 1; s < n; s++) {
            int t = parent[s];
            MaxFlowResult res = edmondsKarpWithMinCut(cap, s, t);
            int f = res.flow;
            weight[s] = f;

            for (int v = 0; v < n; v++) {
                if (v != s && parent[v] == t && res.reachable[v]) {
                    parent[v] = s;
                }
            }

            if (t != 0 && res.reachable[parent[t]]) {
                parent[s] = parent[t];
                parent[t] = s;
                weight[s] = weight[t];
                weight[t] = f;
            }
        }
        return new int[][] {parent, weight};
    }

    private static void validateCapacityMatrix(int[][] cap) {
        if (cap == null || cap.length == 0) {
            throw new IllegalArgumentException("Capacity matrix must not be null or empty");
        }
        final int n = cap.length;
        for (int i = 0; i < n; i++) {
            if (cap[i] == null || cap[i].length != n) {
                throw new IllegalArgumentException("Capacity matrix must be square");
            }
            for (int j = 0; j < n; j++) {
                if (cap[i][j] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative");
                }
            }
        }
    }

    private static final class MaxFlowResult {
        final int flow;
        final boolean[] reachable;
        MaxFlowResult(int flow, boolean[] reachable) {
            this.flow = flow;
            this.reachable = reachable;
        }
    }

    private static MaxFlowResult edmondsKarpWithMinCut(int[][] capacity, int source, int sink) {
        final int n = capacity.length;
        int[][] residual = new int[n][n];
        for (int i = 0; i < n; i++) {
            residual[i] = Arrays.copyOf(capacity[i], n);
        }

        int[] parent = new int[n];
        int maxFlow = 0;

        while (bfs(residual, source, sink, parent)) {
            int pathFlow = Integer.MAX_VALUE;
            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                pathFlow = Math.min(pathFlow, residual[u][v]);
            }
            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                residual[u][v] -= pathFlow;
                residual[v][u] += pathFlow;
            }
            maxFlow += pathFlow;
        }

        boolean[] reachable = new boolean[n];
        markReachable(residual, source, reachable);
        return new MaxFlowResult(maxFlow, reachable);
    }

    private static boolean bfs(int[][] residual, int source, int sink, int[] parent) {
        Arrays.fill(parent, -1);
        parent[source] = source;
        Queue<Integer> q = new ArrayDeque<>();
        q.add(source);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v = 0; v < residual.length; v++) {
                if (residual[u][v] > 0 && parent[v] == -1) {
                    parent[v] = u;
                    if (v == sink) {
                        return true;
                    }
                    q.add(v);
                }
            }
        }
        return false;
    }

    private static void markReachable(int[][] residual, int source, boolean[] vis) {
        Arrays.fill(vis, false);
        Queue<Integer> q = new ArrayDeque<>();
        vis[source] = true;
        q.add(source);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v = 0; v < residual.length; v++) {
                if (!vis[v] && residual[u][v] > 0) {
                    vis[v] = true;
                    q.add(v);
                }
            }
        }
    }
}

/**
 * This class maintains the median of a dynamically changing data stream using
 * two heaps: a max-heap and a min-heap. The max-heap stores the smaller half
 * of the numbers, and the min-heap stores the larger half.
 * This data structure ensures that retrieving the median is efficient.
 *
 * Time Complexity:
 * - Adding a number: O(log n) due to heap insertion.
 * - Finding the median: O(1).
 *
 * Space Complexity: O(n), where n is the total number of elements added.
 *
 * @author Hardvan
 */
public final class MedianFinder {
    MedianFinder() {
    }

    private PriorityQueue<Integer> minHeap = new PriorityQueue<>();
    private PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);

    /**
     * Adds a new number to the data stream. The number is placed in the appropriate
     * heap to maintain the balance between the two heaps.
     *
     * @param num the number to be added to the data stream
     */
    public void addNum(int num) {
        if (maxHeap.isEmpty() || num <= maxHeap.peek()) {
            maxHeap.offer(num);
        } else {
            minHeap.offer(num);
        }

        if (maxHeap.size() > minHeap.size() + 1) {
            minHeap.offer(maxHeap.poll());
        } else if (minHeap.size() > maxHeap.size()) {
            maxHeap.offer(minHeap.poll());
        }
    }

    /**
     * Finds the median of the numbers added so far. If the total number of elements
     * is even, the median is the average of the two middle elements. If odd, the
     * median is the middle element from the max-heap.
     *
     * @return the median of the numbers in the data stream
     */
    public double findMedian() {
        if (maxHeap.size() == minHeap.size()) {
            return (maxHeap.peek() + minHeap.peek()) / 2.0;
        }
        return maxHeap.peek();
    }
}

/*
 * Tiny demo showing basic array mechanics: build one, print it,
 * sum its contents, then mutate a single slot and print again.
 */
public class DiziOrnegi {

    public static void main(String[] args) {
        int[] veriler = {1, 2, 3, 4, 5};

        System.out.println("Dizi Elemanlari:");
        yazdir(veriler);
        System.out.println();

        int toplam = topla(veriler);
        System.out.println("Dizi Elemanlarinin Toplami: " + toplam);

        veriler[2] = 10;

        System.out.println("Guncellenmis Dizi Elemanlari:");
        yazdir(veriler);
    }

    private static void yazdir(int[] veriler) {
        for (int deger : veriler) {
            System.out.print(deger + " ");
        }
    }

    private static int topla(int[] veriler) {
        int sonuc = 0;
        for (int deger : veriler) {
            sonuc += deger;
        }
        return sonuc;
    }
}

