package datatypes;

public class LongVeriTuruOrnegi {

    public static void main(String[] args) {

        // long, short ve int turlerinden birer ornek deger
        long genisSayi = 2147483648L; // "L" son eki long sabiti belirtir
        short darSayi = 32000;
        int ortaSayi = 2147483647;

        System.out.println("Uzun Sayi: " + genisSayi);
        System.out.println("Kisa Sayi: " + darSayi);
        System.out.println("Tam Sayi: " + ortaSayi);

        // short + int toplami otomatik olarak int turune yukselir
        int toplamSonuc = darSayi + ortaSayi;
        System.out.println("Toplam: " + toplamSonuc);

        // long -> int -> short zincirinde acik donusumler (daraltma)
        long ikinciGenisSayi = 50000;
        int inteDonusen = (int) ikinciGenisSayi;
        short shortaDonusen = (short) inteDonusen;

        System.out.println("Uzun Sayi 2: " + ikinciGenisSayi);
        System.out.println("Tam Sayi 2: " + inteDonusen);
        System.out.println("Kisa Sayi 2: " + shortaDonusen);

        // Sinir degerleri
        System.out.println("Long veri turunun maksimum degeri: " + Long.MAX_VALUE);
        System.out.println("Long veri turunun minimum degeri: " + Long.MIN_VALUE);
        System.out.println("Short veri turunun maksimum degeri: " + Short.MAX_VALUE);
        System.out.println("Short veri turunun minimum degeri: " + Short.MIN_VALUE);
        System.out.println("Int veri turunun maksimum degeri: " + Integer.MAX_VALUE);
        System.out.println("Int veri turunun minimum degeri: " + Integer.MIN_VALUE);

        // long turu uzerinde aritmetik islemler
        long farkSonuc = genisSayi - ikinciGenisSayi;
        long carpimSonuc = genisSayi * ikinciGenisSayi;
        long bolumSonuc = genisSayi / ikinciGenisSayi;
        long kalanSonuc = genisSayi % ikinciGenisSayi;

        System.out.println("Long'tan Long'a Fark: " + farkSonuc);
        System.out.println("Long'tan Long'a Carpim: " + carpimSonuc);
        System.out.println("Long'tan Long'a Bolum: " + bolumSonuc);
        System.out.println("Long'tan Long'a Kalan: " + kalanSonuc);
    }
}

