package com.thealgorithms.ciphers;

/**
 * A Java implementation of Caesar Cipher. /It is a type of substitution cipher
 * in which each letter in the plaintext is replaced by a letter some fixed
 * number of positions down the alphabet. /
 *
 * @author FAHRI YARDIMCI
 * @author khalil2535
 */
public class Caesar {
private static char getNormalizedShift(final int shiftValue) {
return (char) (shiftValue % 26);
}

/**
 * Encrypt text by shifting every Latin char by add number shift for ASCII
 * Example : A + 1 -> B
 *
 * @return Encrypted message
 */
public String encode(String inputMessage, int shiftAmount) {
StringBuilder encodedResult = new StringBuilder();
final char adjustedShift = getNormalizedShift(shiftAmount);
for (int position = 0; position < inputMessage.length(); position++) {
char currentChar = inputMessage.charAt(position);
if (isCapitalLatinLetter(currentChar)) {
currentChar += adjustedShift;
encodedResult.append((char) (currentChar > 'Z' ? currentChar - 26 : currentChar));
} else if (isSmallLatinLetter(currentChar)) {
currentChar += adjustedShift;
encodedResult.append((char) (currentChar > 'z' ? currentChar - 26 : currentChar));
} else {
encodedResult.append(currentChar);
}
}
return encodedResult.toString();
}

/**
 * Decrypt message by shifting back every Latin char to previous the ASCII
 * Example : B - 1 -> A
 *
 * @return message
 */
public String decode(String encryptedData, int shiftAmount) {
StringBuilder decodedResult = new StringBuilder();
final char adjustedShift = getNormalizedShift(shiftAmount);
for (int position = 0; position < encryptedData.length(); position++) {
char currentChar = encryptedData.charAt(position);
if (isCapitalLatinLetter(currentChar)) {
currentChar -= adjustedShift;
decodedResult.append((char) (currentChar < 'A' ? currentChar + 26 : currentChar));
} else if (isSmallLatinLetter(currentChar)) {
currentChar -= adjustedShift;
decodedResult.append((char) (currentChar < 'a' ? currentChar + 26 : currentChar));
} else {
decodedResult.append(currentChar);
}
}
return decodedResult.toString();
}

/**
 * @return true if character is capital Latin letter or false for others
 */
private static boolean isCapitalLatinLetter(char symbol) {
return symbol >= 'A' && symbol <= 'Z';
}

/**
 * @return true if character is small Latin letter or false for others
 */
private static boolean isSmallLatinLetter(char symbol) {
return symbol >= 'a' && symbol <= 'z';
}

/**
 *  @return string array which contains all the possible decoded combination.
 */
public String[] bruteforce(String encryptedData) {
String[] allPossibleResults = new String[27];
for (int shiftIndex = 0; shiftIndex <= 26; shiftIndex++) {
allPossibleResults[shiftIndex] = decode(encryptedData, shiftIndex);
}
return allPossibleResults;
}
}

