/**
 * Class for linear convolution of two discrete signals
 *
 * @author Ioannis Karavitsis
 * @version 1.0
 */
public final class Convolution {
    private Convolution() {
    }

    /**
     * Discrete linear convolution function. Both input signals and the output
     * signal must start from 0. If you have a signal that has values before 0
     * then shift it to start from 0.
     *
     * @param a The first discrete signal
     * @param b The second discrete signal
     * @return The convolved signal
     */
    public static double[] convolution(double[] a, double[] b) {
        double[] convolved = new double[a.length + b.length - 1];

        /*
         * Discrete convolution formula:
         * C[i] = Σ A[k] * B[i - k]
         * where k ranges over valid indices so that both A[k] and B[i-k] are in bounds.
         */

        for (int i = 0; i < convolved.length; i++) {
            double sum = 0;
            int kStart = Math.max(0, i - b.length + 1);
            int kEnd = Math.min(i, a.length - 1);

            for (int k = kStart; k <= kEnd; k++) {
                sum += a[k] * b[i - k];
            }

            convolved[i] = sum;
        }

        return convolved;
    }
}

/**
 * A player with income subject to a tiered tax.
 */
public class PlayerIncome extends Player implements Tax {

    private double income;

    public PlayerIncome(double income) {
        this.income = income;
    }

    public PlayerIncome(double income, String name) {
        super(name);
        this.income = income;
    }

    public PlayerIncome() {
    }

    public double getIncome() {
        return income;
    }

    public void setIncome(double income) {
        this.income = income;
    }

    @Override
    public void displayDetails() {
        System.out.println("Name player: " + getName());
        System.out.println("Salary: " + (income - calculateTax()) + "$");
        System.out.println("Tax: " + calculateTax() + "$");
    }

    @Override
    public double calculateTax() {
        if (income <= 10000) {
            return income * 15 / 100;
        } else if (income <= 20000) {
            return income * 20 / 100;
        } else {
            return income * 30 / 100;
        }
    }
}

