package Dictionary;

import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Scanner;
import java.util.StringTokenizer;

/**
 * An English-Vietnamese dictionary backed by a text file.
 */
public class Dictionary {

    public static ArrayList<String> listwords = new ArrayList<>();

    public static void readDataFormFile() {
        File file = new File("D:\\FPT UNIVERSITY\\STUDY\\KY 2\\PRO\\BIN\\STRING WORK SHOP\\String_workshop\\src\\Dictionary\\en-vi.txt");
        try {
            if (file.exists()) {
                Scanner scanner = new Scanner(file);
                while (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    listwords.add(line.trim().replaceAll("\\s+", " "));
                }
            } else {
                try {
                    file.createNewFile();
                } catch (IOException ex) {
                    System.out.println("Can not create file");
                }
            }
        } catch (FileNotFoundException ex) {
            System.out.println("File data not found");
        }
    }

    public Dictionary() {
        readDataFormFile();
    }

    public String lookup(String word) {
        for (String entry : listwords) {
            StringTokenizer tokenizer = new StringTokenizer(entry, ":");
            String english = tokenizer.nextToken().toLowerCase().trim();
            String vietnamese = tokenizer.nextToken().toLowerCase().trim();
            if (word.equalsIgnoreCase(english)) {
                return vietnamese;
            }
        }
        return "not found";
    }
}

package com.thealgorithms.maths.Prime;
/*
 * Java program for Square free integer
 * This class has a function which checks
 * if an integer has repeated prime factors
 * and will return false if the number has repeated prime factors.
 * true otherwise
 * Wikipedia: https://en.wikipedia.org/wiki/Square-free_integer
 *
 * Author: Akshay Dubey (https://github.com/itsAkshayDubey)
 *
 * */

import java.util.HashSet;
import java.util.List;

public final class SquareFreeInteger {
    private SquareFreeInteger() {
    }
    /**
     * This method returns whether an integer is square free
     *
     * @param number Integer value which is to be checked
     * @return false when number has repeated prime factors
     *         true when number has non repeated prime factors
     * @throws IllegalArgumentException when number is negative or zero
     */
    public static boolean isSquareFreeInteger(int number) {

        if (number <= 0) {
            // throw exception when number is less than or is zero
            throw new IllegalArgumentException("Number must be greater than zero.");
        }

        // Store prime factors of number which is passed as argument
        // in a list
        List<Integer> primeFactorsList = PrimeFactorization.pfactors(number);

        // Create set from list of prime factors of integer number
        // if size of list and set is equal then the argument passed to this method is square free
        // if size of list and set is not equal then the argument passed to this method is not
        // square free
        return primeFactorsList.size() == new HashSet<>(primeFactorsList).size();
    }
}

package forloop;

import java.util.Scanner;

public class YildizDeseni {

    // Desen 1: normal piramit seklinde yildizlar
    public void desenPiramit(int yukseklik) {
        int satir = 1;
        while (satir <= yukseklik) {
            for (int bosluk = 1; bosluk <= yukseklik - satir; bosluk++) {
                System.out.print(" ");
            }
            for (int yildiz = 1; yildiz <= 2 * satir - 1; yildiz++) {
                System.out.print("*");
            }
            System.out.println();
            satir++;
        }
    }

    // Desen 2: ters cevrilmis piramit
    public void desenTersPiramit(int yukseklik) {
        for (int satir = yukseklik; satir > 0; satir--) {
            for (int bosluk = 1; bosluk <= yukseklik - satir; bosluk++) {
                System.out.print(" ");
            }
            for (int yildiz = 1; yildiz <= 2 * satir - 1; yildiz++) {
                System.out.print("*");
            }
            System.out.println();
        }
    }

    // Desen 3: sabit genislikte yildiz satirlari
    public void desenDikdortgen(int yukseklik) {
        int satir = 1;
        while (satir <= yukseklik) {
            int sutun = 1;
            while (sutun <= yukseklik) {
                System.out.print("* ");
                sutun++;
            }
            System.out.println();
            satir++;
        }
    }

    // Desen 4: yukari ve asagi birlesmis piramit (elmas benzeri)
    public void desenCiftYonlu(int yukseklik) {
        for (int satir = 1; satir <= yukseklik; satir++) {
            for (int bosluk = 1; bosluk <= yukseklik - satir; bosluk++) {
                System.out.print(" ");
            }
            for (int yildiz = 1; yildiz <= 2 * satir - 1; yildiz++) {
                System.out.print("*");
            }
            System.out.println();
        }
        int satir = yukseklik - 1;
        while (satir >= 1) {
            for (int bosluk = 1; bosluk <= yukseklik - satir; bosluk++) {
                System.out.print(" ");
            }
            for (int yildiz = 1; yildiz <= 2 * satir - 1; yildiz++) {
                System.out.print("*");
            }
            System.out.println();
            satir--;
        }
    }

    public static void main(String[] args) {

        Scanner girisOkuyucu = new Scanner(System.in);

        // Kullanicidan piramitin yukseklik degerini al
        System.out.print("Satir sayisini girin: ");
        int yukseklik = girisOkuyucu.nextInt();

        // Cizim islemleri icin nesne olustur
        YildizDeseni cizici = new YildizDeseni();

        System.out.println("Birinci Desen (Piramid):");
        cizici.desenPiramit(yukseklik);

        System.out.println("ikinci Desen (Ters Piramit):");
        cizici.desenTersPiramit(yukseklik);

        System.out.println("Ucuncu Desen (Duz Satir Yildizlari):");
        cizici.desenDikdortgen(yukseklik);

        System.out.println("Dorduncu Desen (Cift Yonlu Piramit):");
        cizici.desenCiftYonlu(yukseklik);

        girisOkuyucu.close();
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.Arrays;

/**
 * Class to solve the Bandwidth Allocation Problem.
 * The goal is to maximize the value gained by allocating bandwidth to users.
 * Example:
 * Bandwidth = 10
 * Users = [3, 5, 7]
 * Values = [10, 20, 30]
 * The maximum value achievable is 40 by allocating 3 units to user 0 and 7 units to user 2.
 *
 * @author Hardvan
 */
public final class BandwidthAllocation {
    private BandwidthAllocation() {
    }

    /**
     * Allocates bandwidth to maximize value.
     * Steps:
     * 1. Calculate the ratio of value/demand for each user.
     * 2. Sort the users in descending order of the ratio.
     * 3. Allocate bandwidth to users in order of the sorted list.
     * 4. If the bandwidth is not enough to allocate the full demand of a user, allocate a fraction of the demand.
     * 5. Return the maximum value achievable.
     *
     * @param bandwidth total available bandwidth to allocate
     * @param users     array of user demands
     * @param values    array of values associated with each user's demand
     * @return the maximum value achievable
     */
    public static int maxValue(int bandwidth, int[] users, int[] values) {
        int n = users.length;
        double[][] ratio = new double[n][2]; // {index, ratio}

        for (int i = 0; i < n; i++) {
            ratio[i][0] = i;
            ratio[i][1] = (double) values[i] / users[i];
        }

        Arrays.sort(ratio, (a, b) -> Double.compare(b[1], a[1]));

        int maxValue = 0;
        for (int i = 0; i < n; i++) {
            int index = (int) ratio[i][0];
            if (bandwidth >= users[index]) {
                maxValue += values[index];
                bandwidth -= users[index];
            } else {
                maxValue += (int) (ratio[i][1] * bandwidth);
                break;
            }
        }
        return maxValue;
    }
}

