// Interface defining a contract for objects that have a side descriptor
interface Side {
    String getSide();
}

// Concrete implementation for Head side
class Head implements Side {
    public String getSide() {
        return "Head ";
    }
}

// Concrete implementation for Tail side
class Tail implements Side {
    public String getSide() {
        return "Tail ";
    }
}

// Demonstration class showing method overloading and type casting resolution
class Coin {

    // Overloaded method accepting Head type (most specific)
    public static void overload(Head sideObject) { 
        System.out.print(sideObject.getSide()); 
    }

    // Overloaded method accepting Tail type (most specific)
    public static void overload(Tail sideObject) { 
        System.out.print(sideObject.getSide()); 
    }

    // Overloaded method accepting Side interface type (more general)
    public static void overload(Side sideObject) { 
        System.out.print("Side "); 
    }

    // Overloaded method accepting Object type (most general)
    public static void overload(Object sideObject) { 
        System.out.print("Object "); 
    }

    public static void main(String[] args) {
        // Reference type is Side (interface), actual object type is Head
        Side firstAttemptReference = new Head();  // Upcasting: Head → Side

        // Reference type is Tail (concrete class), actual object type is Tail
        Tail secondAttemptReference = new Tail();

        // Case 1: Compiler sees Side reference → chooses overload(Side side)
        // Even though actual object is Head, method selection happens at COMPILE TIME
        // based on reference type, not runtime object type
        overload(firstAttemptReference);  // Output: "Side "

        // Case 2: Explicit cast to Object → forces overload(Object side)
        // Casting overrides the reference type determination
        overload((Object)firstAttemptReference);  // Output: "Object "

        // Case 3: Reference type is Tail (no casting needed)
        // Compiler sees exact match with overload(Tail side)
        overload(secondAttemptReference);  // Output: "Tail "

        // Case 4: Explicit cast to Side interface
        // Even though secondAttemptReference is Tail, casting to Side makes compiler
        // choose overload(Side side) instead of overload(Tail side)
        overload((Side)secondAttemptReference);  // Output: "Side "

        // Educational Output Summary (optional demonstration):
        System.out.println(); // Newline for clean output separation
        System.out.println("--- Overloading Resolution Rules ---");
        System.out.println("1. Method overloading is determined at COMPILE TIME");
        System.out.println("2. The reference type (not object type) determines which overload is called");
        System.out.println("3. Explicit casting can override the default reference type");
        System.out.println("4. Most specific matching method is preferred when no cast is applied");
    }
}

/*
 * Bu ornekte, BufferedReader ve BufferedWriter siniflari kullanilarak metin dosyalari 
 * okunur ve yazilir. FileReader ve FileWriter siniflari, okuyucu ve yazicilari olusturmak 
 * icin kullanilirken, readLine() ve write() metodlari dosyalara veri yazma ve okuma icin 
 * kullanilir.
 */

public class MetinDosyasiOkuma {

	public static void main(String[] args) {

		// Dosya yollarini tanimla
		String girisDosyaYolu = "girdi.txt";
		String cikisDosyaYolu = "cikti.txt";

		// Giris dosyasindan oku
		try (BufferedReader okuyucu = new BufferedReader(new FileReader(girisDosyaYolu))) {
			String satir;
			while ((satir = okuyucu.readLine()) != null) {
				System.out.println(satir);
			}
		} catch (IOException e) {
			e.printStackTrace();
		}

		// Cikis dosyasina yaz
		try (BufferedWriter yazici = new BufferedWriter(new FileWriter(cikisDosyaYolu))) {
			yazici.write("Bu bir metin satiridir.");
			yazici.newLine();
			yazici.write("Bu da baska bir metin satiridir.");
		} catch (IOException e) {
			e.printStackTrace();
		}
	}
}

package functions; 
import java.util.Scanner;  // Kullaniciya giris almak icin Scanner sinifini ice aktar

public class BasamakSayisi {

    // 'basamakSayisiBul' metodu verilen sayinin kac basamaktan olustugunu bulur
    int basamakSayisiBul(int sayi) {
        int basamakSayisi = 0;  // Basamak sayisini tutacak degisken
        // Sayi 0'dan buyuk oldugu surece dongu devam eder
        while(sayi > 0) {
            // Sayi her dongude 10'a bolunerek bir basamak eksiltilir
            sayi = sayi / 10;
            // Her bolme isleminde bir basamak oldugu icin sayaci arttir
            basamakSayisi++;
        }
        // Basamak sayisini dondur
        return basamakSayisi;
    }

    public static void main(String[] args) {

        // Kullaniciya giris almak icin Scanner nesnesi olustur
        Scanner okuyucu = new Scanner(System.in);
        // Kullanicinin girdigi sayiyi al
        int sayi = okuyucu.nextInt();

        // BasamakSayisi sinifindan bir nesne olustur
        BasamakSayisi bulucu = new BasamakSayisi();

        // 'basamakSayisiBul' metodunu cagirararak sayinin basamak sayisini hesapla
        int sonuc = bulucu.basamakSayisiBul(sayi);

        // Sonucu ekrana yazdir
        System.out.println(sonuc);

        // Scanner nesnesini kapat
        okuyucu.close();
    }
}

/**
 * Demonstrates an abstract class with template method pattern.
 */
abstract class Vehicle {
    protected String model;

    public Vehicle(String model) {
        this.model = model;
    }

    // Template method
    public void startJourney() {
        checkFuel();
        start();
        System.out.println(model + " is on its way!");
    }

    protected void checkFuel() {
        System.out.println("Checking fuel level...");
    }

    protected abstract void start();
}

class Car extends Vehicle {
    public Car(String model) {
        super(model);
    }

    @Override
    protected void start() {
        System.out.println("Turning ignition key...");
    }
}

class ElectricScooter extends Vehicle {
    public ElectricScooter(String model) {
        super(model);
    }

    @Override
    protected void start() {
        System.out.println("Pressing power button...");
    }
}

public class VehicleDemo {
    public static void main(String[] args) {
        Vehicle[] vehicles = {new Car("Toyota"), new ElectricScooter("Xiaomi")};
        for (Vehicle vehicle : vehicles) {
            vehicle.startJourney();
        }
    }
}

public class VowelCounter {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String input = scanner.nextLine();

        int vowelCount = 0;
        for (char c : input.toLowerCase().toCharArray()) {
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                vowelCount++;
            }
        }

        System.out.println("Number of vowels: " + vowelCount);
        scanner.close();
    }
}

package tankgame;

