/*
 * Birden fazla arka plan gorevini thread kullanarak paralel olarak calistiran ve belirli
 * bir sure sonunda gorevleri sonlandiran genisletilmis Java programi.
 */

public class ArkaPlanGorevi implements Runnable {

	private String gorevAdi; // Gorevin ismi
	private volatile boolean calisiyor = true; // Thread'in calisma durumu

	// Constructor: Gorev ismini belirler
	public ArkaPlanGorevi(String gorevAdi) {
		this.gorevAdi = gorevAdi;
	}

	// Arka plan gorevini calistiracak metod
	public void run() {
		int sayac = 0;
		while (calisiyor && sayac < 10) {
			System.out.println(gorevAdi + " calisiyor: " + sayac); // Gorev mesajini yazdir
			try {
				Thread.sleep(400); // 0.4 saniye uyur
			} catch (InterruptedException e) {
				System.out.println(gorevAdi + " kesildi.");
				return; // Thread sonlandirilir
			}
			sayac++;
		}
		System.out.println(gorevAdi + " tamamlandi.");
	}

	// Thread'i durdurma metodu
	public void durdur() {
		calisiyor = false;
	}

	// Programin ana metodu
	public static void main(String[] args) {
		// Arka plan gorevleri olustur
		ArkaPlanGorevi gorev1 = new ArkaPlanGorevi("Gorev-1");
		ArkaPlanGorevi gorev2 = new ArkaPlanGorevi("Gorev-2");
		ArkaPlanGorevi gorev3 = new ArkaPlanGorevi("Gorev-3");

		// Thread'leri olustur ve adlandir
		Thread thread1 = new Thread(gorev1, "Thread-1");
		Thread thread2 = new Thread(gorev2, "Thread-2");
		Thread thread3 = new Thread(gorev3, "Thread-3");

		// Thread'leri baslat
		thread1.start();
		thread2.start();
		thread3.start();

		// Ana thread'de baska isler yap
		for (int i = 0; i < 5; i++) {
			System.out.println("Ana thread is yapiyor: " + i);
			try {
				Thread.sleep(500); // 0.5 saniye uyur
			} catch (InterruptedException e) {
				e.printStackTrace();
			}
		}

		// Belirli bir sure sonra tum thread'leri durdur
		try {
			Thread.sleep(5000); // 5 saniye bekle
		} catch (InterruptedException e) {
			e.printStackTrace();
		}

		System.out.println("Tum gorevler durduruluyor...");
		gorev1.durdur();
		gorev2.durdur();
		gorev3.durdur();

		// Tum thread'lerin tamamlanmasini bekle
		try {
			thread1.join();
			thread2.join();
			thread3.join();
		} catch (InterruptedException e) {
			e.printStackTrace();
		}

		System.out.println("Tum isler tamamlandi. Program sonlandi.");
	}
}

package com.thealgorithms.conversions;

/**
 * A utility class for converting numbers from any base to any other base.
 *
 * This class provides a method to convert a source number from a given base
 * to a destination number in another base. Valid bases range from 2 to 10.
 */
public final class AnytoAny {
    private AnytoAny() {
    }

    /**
     * Converts a number from a source base to a destination base.
     *
     * @param sourceNumber The number in the source base (as an integer).
     * @param sourceBase The base of the source number (between 2 and 10).
     * @param destBase The base to which the number should be converted (between 2 and 10).
     * @throws IllegalArgumentException if the bases are not between 2 and 10.
     * @return The converted number in the destination base (as an integer).
     */
    public static int convertBase(int sourceNumber, int sourceBase, int destBase) {
        if (sourceBase < 2 || sourceBase > 10 || destBase < 2 || destBase > 10) {
            throw new IllegalArgumentException("Bases must be between 2 and 10.");
        }

        int decimalValue = toDecimal(sourceNumber, sourceBase);
        return fromDecimal(decimalValue, destBase);
    }

    /**
     * Converts a number from a given base to its decimal representation (base 10).
     *
     * @param number The number in the original base.
     * @param base The base of the given number.
     * @return The decimal representation of the number.
     */
    private static int toDecimal(int number, int base) {
        int decimalValue = 0;
        int multiplier = 1;

        while (number != 0) {
            decimalValue += (number % 10) * multiplier;
            multiplier *= base;
            number /= 10;
        }
        return decimalValue;
    }

    /**
     * Converts a decimal (base 10) number to a specified base.
     *
     * @param decimal The decimal number to convert.
     * @param base The destination base for conversion.
     * @return The number in the specified base.
     */
    private static int fromDecimal(int decimal, int base) {
        int result = 0;
        int multiplier = 1;

        while (decimal != 0) {
            result += (decimal % base) * multiplier;
            multiplier *= 10;
            decimal /= base;
        }
        return result;
    }
}

package syntax;

import java.util.Scanner;

public class KarsilastirmaIslemleri {

    public static void main(String[] args) {

        // Fixed values used to illustrate every relational operator.
        int valueA = 10;
        int valueB = 20;

        System.out.println("sayi1, sayi2'ye esit mi? " + (valueA == valueB));       // false
        System.out.println("sayi1, sayi2'ye esit degil mi? " + (valueA != valueB)); // true
        System.out.println("sayi1, sayi2'den buyuk mu? " + (valueA > valueB));      // false
        System.out.println("sayi1, sayi2'den kucuk mu? " + (valueA < valueB));      // true
        System.out.println("sayi1, sayi2'den buyuk veya esit mi? " + (valueA >= valueB)); // false
        System.out.println("sayi1, sayi2'den kucuk veya esit mi? " + (valueA <= valueB)); // true

        // Now gather several inputs from the user and compare them.
        Scanner input = new Scanner(System.in);

        System.out.println("Lutfen yasinizi girin:");
        int age = input.nextInt();
        System.out.println("Yasiniz 18'den buyuk mu? " + (age > 18));

        System.out.println("Lutfen adinizi girin:");
        String name = input.next();
        System.out.println("Adiniz Ali mi? " + name.equals("Ali"));

        System.out.println("Lutfen 5 ile 15 arasinda bir sayi girin:");
        int rangedNumber = input.nextInt();
        System.out.println("Girilen sayi 5'ten buyuk mu? " + (rangedNumber > 5));
        System.out.println("Girilen sayi 15'ten kucuk mu? " + (rangedNumber < 15));

        System.out.println("Lutfen bir karakter girin:");
        char letter = input.next().charAt(0);
        System.out.println("Girilen karakter A mi? " + (letter == 'A'));

        input.close();
    }
}

