/**
 * Converts any Hexadecimal Number to Octal
 *
 * @author Tanmay Joshi
 */
public final class HexToOct {
private HexToOct() {
}

/**
 * Converts a Hexadecimal number to a Decimal number.
 *
 * @param hexInput The Hexadecimal number as a String.
 * @return The Decimal equivalent as an integer.
 */
public static int hexToDecimal(String hexInput) {
String validSymbols = "0123456789ABCDEF";
String normalizedInput = hexInput.toUpperCase();
int decimalResult = 0;
for (int position = 0; position < normalizedInput.length(); position++) {
char currentChar = normalizedInput.charAt(position);
int digitValue = validSymbols.indexOf(currentChar);
decimalResult = 16 * decimalResult + digitValue;
}
return decimalResult;
}

/**
 * Converts a Decimal number to an Octal number.
 *
 * @param decimalInput The Decimal number as an integer.
 * @return The Octal equivalent as an integer.
 */
public static int decimalToOctal(int decimalInput) {
int octalResult = 0;
int placeMultiplier = 1;
int remainingValue = decimalInput;
while (remainingValue > 0) {
int remainderDigit = remainingValue % 8;
octalResult += remainderDigit * placeMultiplier;
remainingValue /= 8;
placeMultiplier *= 10;
}
return octalResult;
}

/**
 * Converts a Hexadecimal number to an Octal number.
 *
 * @param hexString The Hexadecimal number as a String.
 * @return The Octal equivalent as an integer.
 */
public static int hexToOctal(String hexString) {
int decimalIntermediate = hexToDecimal(hexString);
return decimalToOctal(decimalIntermediate);
}
}
