package com.thealgorithms.devutils.nodes;

/**
 * Simple Node implementation that holds a reference to the next Node.
 *
 * @param <E> The type of the data held in the Node.
 *
 * @author <a href="https://github.com/aitorfi">aitorfi</a>
 */
public class SimpleNode<E> extends Node<E> {

    /**
     * Reference to the next Node.
     */
    private SimpleNode<E> nextNode;

    /**
     * Empty constructor.
     */
    public SimpleNode() {
        super();
    }

    /**
     * Initializes the Nodes' data.
     *
     * @param data Value to which data will be initialized.
     * @see Node#Node(Object)
     */
    public SimpleNode(E data) {
        super(data);
    }

    /**
     * Initializes the Nodes' data and next node reference.
     *
     * @param data Value to which data will be initialized.
     * @param nextNode Value to which the next node reference will be set.
     */
    public SimpleNode(E data, SimpleNode<E> nextNode) {
        super(data);
        this.nextNode = nextNode;
    }

    /**
     * @return True if there is a next node, otherwise false.
     */
    public boolean hasNext() {
        return (nextNode != null);
    }

    public SimpleNode<E> getNextNode() {
        return nextNode;
    }

    public void setNextNode(SimpleNode<E> nextNode) {
        this.nextNode = nextNode;
    }
}

package mysql;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.Scanner;

/**
 * Small interactive CRUD demo against a MySQL "users" table: insert,
 * update, delete, or list rows depending on a menu choice.
 */
public class MySQLDemo {

    private static final String JDBC_URL = "jdbc:mysql://localhost:3306/testdb";
    private static final String DB_USER = "root";
    private static final String DB_PASSWORD = "password";

    public static void main(String[] args) throws SQLException, ClassNotFoundException {

        Class.forName("com.mysql.jdbc.Driver");

        try (Connection db = DriverManager.getConnection(JDBC_URL, DB_USER, DB_PASSWORD);
             Statement generalStatement = db.createStatement();
             Scanner console = new Scanner(System.in)) {

            System.out.println("Yapmak istediginiz islemi secin: ");
            System.out.println("1 - Yeni kayit ekle");
            System.out.println("2 - Kayit guncelle");
            System.out.println("3 - Kayit sil");
            System.out.println("4 - Tum kayitlari listele");
            System.out.print("Seciminizi yapin: ");
            int menuChoice = console.nextInt();
            console.nextLine();

            switch (menuChoice) {
                case 1:
                    insertUser(db, console);
                    break;
                case 2:
                    updateUser(db, console);
                    break;
                case 3:
                    deleteUser(db, console);
                    break;
                case 4:
                    listUsers(generalStatement);
                    break;
                default:
                    System.out.println("Gecersiz secim.");
            }
        }
    }

    private static void insertUser(Connection db, Scanner console) throws SQLException {
        System.out.print("Adinizi girin: ");
        String name = console.nextLine();
        System.out.print("Email adresinizi girin: ");
        String email = console.nextLine();
        String sql = "iNSERT iNTO users (name, email) VALUES (?, ?)";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setString(1, name);
            stmt.setString(2, email);
            stmt.executeUpdate();
            System.out.println("Yeni kayit basariyla eklendi.");
        }
    }

    private static void updateUser(Connection db, Scanner console) throws SQLException {
        System.out.print("Guncellemek istediginiz kullanicinin iD'sini girin: ");
        int targetId = console.nextInt();
        console.nextLine();
        System.out.print("Yeni ad girin: ");
        String newName = console.nextLine();
        System.out.print("Yeni email adresi girin: ");
        String newEmail = console.nextLine();
        String sql = "UPDATE users SET name = ?, email = ? WHERE id = ?";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setString(1, newName);
            stmt.setString(2, newEmail);
            stmt.setInt(3, targetId);
            int affected = stmt.executeUpdate();
            System.out.println(affected > 0 ? "Kullanici guncellendi." : "Kullanici bulunamadi.");
        }
    }

    private static void deleteUser(Connection db, Scanner console) throws SQLException {
        System.out.print("Silmek istediginiz kullanicinin iD'sini girin: ");
        int targetId = console.nextInt();
        String sql = "DELETE FROM users WHERE id = ?";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setInt(1, targetId);
            int affected = stmt.executeUpdate();
            System.out.println(affected > 0 ? "Kullanici silindi." : "Kullanici bulunamadi.");
        }
    }

    private static void listUsers(Statement generalStatement) throws SQLException {
        String sql = "SELECT * FROM users";
        try (ResultSet rows = generalStatement.executeQuery(sql)) {
            while (rows.next()) {
                int id = rows.getInt("id");
                String name = rows.getString("name");
                String email = rows.getString("email");
                System.out.println("iD: " + id + ", Name: " + name + ", Email: " + email);
            }
        }
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.List;

/**
 * Implementation of Tarjan's Bridge-Finding Algorithm for undirected graphs.
 *
 * <p>A <b>bridge</b> (also called a cut-edge) is an edge in an undirected graph whose removal
 * increases the number of connected components. Bridges represent critical links
 * in a network — if any bridge is removed, part of the network becomes unreachable.</p>
 *
 * <p>The algorithm performs a single Depth-First Search (DFS) traversal, tracking two
 * values for each vertex:</p>
 * <ul>
 *   <li><b>discoveryTime</b> — the time step at which the vertex was first visited.</li>
 *   <li><b>lowLink</b> — the smallest discovery time reachable from the subtree rooted
 *       at that vertex (via back edges).</li>
 * </ul>
 *
 * <p>An edge (u, v) is a bridge if and only if {@code lowLink[v] > discoveryTime[u]},
 * meaning there is no back edge from the subtree of v that can reach u or any ancestor of u.</p>
 *
 * <p>Time Complexity: O(V + E), where V is the number of vertices and E is the number of edges.</p>
 * <p>Space Complexity: O(V + E) for the adjacency list, discovery/low arrays, and recursion stack.</p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Bridge_(graph_theory)">Wikipedia: Bridge (graph theory)</a>
 */
public final class TarjanBridges {

    private TarjanBridges() {
        throw new UnsupportedOperationException("Utility class");
    }

    /**
     * Finds all bridge edges in an undirected graph.
     *
     * <p>The graph is represented as an adjacency list where each vertex is identified by
     * an integer in the range {@code [0, vertexCount)}. For each undirected edge (u, v),
     * v must appear in {@code adjacencyList.get(u)} and u must appear in
     * {@code adjacencyList.get(v)}.</p>
     *
     * @param vertexCount   the total number of vertices in the graph (must be non-negative)
     * @param adjacencyList the adjacency list representation of the graph; must contain
     *                      exactly {@code vertexCount} entries (one per vertex)
     * @return a list of bridge edges, where each bridge is represented as an {@code int[]}
     *         of length 2 with {@code edge[0] < edge[1]}; returns an empty list if no bridges exist
     * @throws IllegalArgumentException if {@code vertexCount} is negative, or if
     *                                  {@code adjacencyList} is null or its size does not match
     *                                  {@code vertexCount}
     */
    public static List<int[]> findBridges(int vertexCount, List<List<Integer>> adjacencyList) {
        if (vertexCount < 0) {
            throw new IllegalArgumentException("vertexCount must be non-negative");
        }
        if (adjacencyList == null || adjacencyList.size() != vertexCount) {
            throw new IllegalArgumentException("adjacencyList size must equal vertexCount");
        }

        List<int[]> bridges = new ArrayList<>();

        if (vertexCount == 0) {
            return bridges;
        }

        BridgeFinder finder = new BridgeFinder(vertexCount, adjacencyList, bridges);

        // Run DFS from every unvisited vertex to handle disconnected graphs
        for (int i = 0; i < vertexCount; i++) {
            if (!finder.visited[i]) {
                finder.dfs(i, -1);
            }
        }

        return bridges;
    }

    private static class BridgeFinder {
        private final List<List<Integer>> adjacencyList;
        private final List<int[]> bridges;
        private final int[] discoveryTime;
        private final int[] lowLink;
        boolean[] visited;
        private int timer;

        BridgeFinder(int vertexCount, List<List<Integer>> adjacencyList, List<int[]> bridges) {
            this.adjacencyList = adjacencyList;
            this.bridges = bridges;
            this.discoveryTime = new int[vertexCount];
            this.lowLink = new int[vertexCount];
            this.visited = new boolean[vertexCount];
            this.timer = 0;
        }

        /**
         * Performs DFS from the given vertex, computing discovery times and low-link values,
         * and collects any bridge edges found.
         *
         * @param u      the current vertex being explored
         * @param parent the parent of u in the DFS tree (-1 if u is a root)
         */
        void dfs(int u, int parent) {
            visited[u] = true;
            discoveryTime[u] = timer;
            lowLink[u] = timer;
            timer++;

            for (int v : adjacencyList.get(u)) {
                if (!visited[v]) {
                    dfs(v, u);
                    lowLink[u] = Math.min(lowLink[u], lowLink[v]);

                    if (lowLink[v] > discoveryTime[u]) {
                        bridges.add(new int[] {Math.min(u, v), Math.max(u, v)});
                    }
                } else if (v != parent) {
                    lowLink[u] = Math.min(lowLink[u], discoveryTime[v]);
                }
            }
        }
    }
}

public class RasyonelSayi {

	private int pay;        // Rasyonel sayinin payini temsil eder
	private int payda;      // Rasyonel sayinin paydasini temsil eder

	public RasyonelSayi(int pay, int payda) {
		this.pay = pay;        // Pay ve payda degerlerini ayarlar
		this.payda = payda;
	}

	// Rasyonel sayiyi basitlestiren metod
	private void basitlestir() {
		int ebob = findEBOB(pay, payda);  // Pay ve payda icin en buyuk ortak boleni hesaplar
		pay /= ebob;        // Pay ve paydayi en buyuk ortak bolen ile bolerek basitlestirir
		payda /= ebob;
	}

	// En buyuk ortak boleni bulan metod
	private int findEBOB(int a, int b) {
		while (b != 0) {
			int temp = b;
			b = a % b;
			a = temp;
		}
		return a;   // En buyuk ortak boleni dondurur
	}

	// Iki rasyonel sayiyi toplayan metod
	public RasyonelSayi topla(RasyonelSayi digerSayi) {
		int yeniPay = (this.pay * digerSayi.payda) + (digerSayi.pay * this.payda);  // Iki rasyonel sayiyi toplar
		int yeniPayda = this.payda * digerSayi.payda;
		return new RasyonelSayi(yeniPay, yeniPayda);   // Yeni rasyonel sayiyi dondurur
	}

	// Iki rasyonel sayiyi carpan metod
	public RasyonelSayi carp(RasyonelSayi digerSayi) {
		int yeniPay = this.pay * digerSayi.pay;   // Iki rasyonel sayiyi carpar
		int yeniPayda = this.payda * digerSayi.payda;
		return new RasyonelSayi(yeniPay, yeniPayda);   // Yeni rasyonel sayiyi dondurur
	}

	// Rasyonel sayiyi metinsel olarak temsil eden metod
	public String toString() {
		return pay + "/" + payda;   // Rasyonel sayiyi metinsel olarak temsil eder
	}

	// Main metodunda rasyonel sayilari kullanma
	public static void main(String[] args) {

		// Kullaniciya sayi girmesi icin bir mesaj
		System.out.println("Iki rasyonel sayi girin:");
		RasyonelSayi sayi1 = new RasyonelSayi(8, 10);  // Ilk rasyonel sayiyi olusturur
		RasyonelSayi sayi2 = new RasyonelSayi(2, 3);  // Ikinci rasyonel sayiyi olusturur
		RasyonelSayi sayi3 = new RasyonelSayi(9, 3);

		// Rasyonel sayilarin toplami
		RasyonelSayi toplam = sayi1.topla(sayi2);  
		System.out.println("Rasyonel sayilarin toplami: " + toplam);

		// Rasyonel sayilarin carpimi
		RasyonelSayi carpim = sayi1.carp(sayi2);  
		System.out.println("Rasyonel sayilarin carpimi: " + carpim);

		// Pay ve payda degerlerinin kontrol edilmesi
		System.out.println("Sayi 1 - Pay: " + sayi1.pay + ", Payda: " + sayi1.payda);
		System.out.println("Sayi 2 - Pay: " + sayi2.pay + ", Payda: " + sayi2.payda);

		// Bir sayinin negatif olup olmadigini kontrol etme
		if (sayi1.pay < 0 || sayi1.payda < 0) {
			System.out.println("Sayi 1 negatif degerlere sahip.");
		}

		// Toplam ve carpim sayilarinin basitlestirilmis halleri
		RasyonelSayi basitToplam = new RasyonelSayi(toplam.pay, toplam.payda);
		RasyonelSayi basitCarpim = new RasyonelSayi(carpim.pay, carpim.payda);

		System.out.println("Basitlestirilmis Toplam: " + basitToplam);
		System.out.println("Basitlestirilmis Carpim: " + basitCarpim);

		// Ekstra islemler
		int pay1 = sayi3.pay;
		int payda1 = sayi3.payda;

		if (pay1 % payda1 == 0) {
			System.out.println("Sayi 3 bir tam sayidir.");
		} else {
			System.out.println("Sayi 3 bir kesirli sayidir.");
		}

		sayi1.basitlestir();
		sayi2.basitlestir();
		// Kullaniciya basitlestirilmis hali gosterme
		System.out.println("Sayi 1'in basitlestirilmis hali: " + sayi1);
		System.out.println("Sayi 2'nin basitlestirilmis hali: " + sayi2);
	}
}

public class RandomString {
    static String generate(int size) {
        StringBuffer sb = new StringBuffer(size);

        Random rand = new Random();

        for (int i = 0; i < size ; i++) {
            int randomChar = 97 + (int) (rand.nextFloat() * 26);
            sb.append((char)randomChar);
        }
        return sb.toString();
    }
}

public class Main {
    public static void main(String[] args) {
        int a = 5;
        int b = 0;
        try {
//           divide(a, b);
           // mimicking an expression
          String name = "Ankan";
          if (name.equals("Ankan")) {
              throw new myException("Name is Ankan");
          }
        } catch (myException e) {
            System.out.println(e.getMessage());
        } catch (Exception e) {
            System.out.println("normal exception");
        } finally { // finally will execute despite any errors
            System.out.println("This will always execute");
        }
    }

    static int divide(int a, int b) throws ArithmeticException {
