public class FibonacciSeries {
    public static void main(String[] args) {
        int n = 10;
        long first = 0;
        long second = 1;

        System.out.print("Fibonacci series: " + first + " " + second);
        for (int i = 2; i < n; i++) {
            long next = first + second;
            System.out.print(" " + next);
            first = second;
            second = next;
        }
        System.out.println();
    }
}

