package com.thealgorithms.devutils.nodes;

/**
 * Base class for any node implementation which contains a generic type
 * variable.
 *
 * All known subclasses: {@link TreeNode}, {@link SimpleNode}.
 *
 * @param <E> The type of the data held in the Node.
 *
 * @author <a href="https://github.com/aitorfi">aitorfi</a>
 */
public abstract class Node<E> {

    /**
     * Generic type data stored in the Node.
     */
    private E data;

    /**
     * Empty constructor.
     */
    public Node() {
    }

    /**
     * Initializes the Nodes' data.
     *
     * @param data Value to which data will be initialized.
     */
    public Node(E data) {
        this.data = data;
    }

    public E getData() {
        return data;
    }

    public void setData(E data) {
        this.data = data;
    }
}

/** "Girisi Yasak" trafik levhasini geometrik sekillerle ciziyor. */
public class GirisYasaktirIsareti extends JPanel {

    private static final long serialVersionUID = 1L;

    @Override
    public void paintComponent(Graphics tuval) {
        super.paintComponent(tuval);

        Point ortaNokta = new Point(getWidth() / 2, getHeight() / 2);

        int disCemberYaricapi = Math.min(getWidth() / 2, getHeight() / 2) - 5;
        int icCemberYaricapi = (int) (disCemberYaricapi * 0.9);
        int cubukUzunlugu = (int) (icCemberYaricapi * 1.4);
        int cubukKalinligi = (int) (icCemberYaricapi * 0.35);

        // Levhanin beyaz kenarligi
        tuval.setColor(Color.WHITE);
        tuval.fillOval(ortaNokta.x - disCemberYaricapi, ortaNokta.y - disCemberYaricapi,
                2 * disCemberYaricapi, 2 * disCemberYaricapi);

        // Kirmizi govde
        tuval.setColor(Color.RED);
        tuval.fillOval(ortaNokta.x - icCemberYaricapi, ortaNokta.y - icCemberYaricapi,
                icCemberYaricapi * 2, icCemberYaricapi * 2);

        // Ortadaki yatay beyaz cubuk
        tuval.setColor(Color.WHITE);
        tuval.fillRect(ortaNokta.x - cubukUzunlugu / 2, ortaNokta.y - cubukKalinligi / 2,
                cubukUzunlugu, cubukKalinligi);
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            GirisYasaktirIsareti levha = new GirisYasaktirIsareti();
            levha.setBackground(Color.GREEN.darker());

            JFrame pencere = new JFrame("Giris Yasaktir!");
            pencere.setSize(400, 300);
            pencere.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
            pencere.getContentPane().add(levha, BorderLayout.CENTER);
            pencere.setVisible(true);
        });
    }
}

package Workshop3.Guitar;

/**
 * A guitar, comparable by price then serial number.
 */
public class Guitar implements Comparable<Guitar> {

    private String serialNumber;
    private double price;
    private String builder;
    private String model;
    private String backWood;
    private String topWood;

    public Guitar() {
    }

    public Guitar(String serialNumber, double price, String builder, String model, String backWood, String topWood) {
        this.serialNumber = serialNumber;
        this.price = price;
        this.builder = builder;
        this.model = model;
        this.backWood = backWood;
        this.topWood = topWood;
    }

    public String getSerialNumber() {
        return serialNumber;
    }

    public void setSerialNumber(String serialNumber) {
        if (!serialNumber.isEmpty()) {
            this.serialNumber = serialNumber;
        }
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        this.price = price;
    }

    public String getBuilder() {
        return builder;
    }

    public void setBuilder(String builder) {
        this.builder = builder;
    }

    public String getModel() {
        return model;
    }

    public void setModel(String model) {
        this.model = model;
    }

    public String getBackWood() {
        return backWood;
    }

    public void setBackWood(String backWood) {
        this.backWood = backWood;
    }

    public String getTopWood() {
        return topWood;
    }

    public void setTopWood(String topWood) {
        this.topWood = topWood;
    }

    public void createSound() {
        System.out.println("serialNumber: " + getSerialNumber());
        System.out.println("Price: " + getPrice());
        System.out.println("Builder: " + getBuilder());
        System.out.println("Model: " + getModel());
        System.out.println("BackWood: " + getBackWood());
        System.out.println("TopWood: " + getTopWood());
    }

    @Override
    public String toString() {
        return "Guitar{serialNumber=" + serialNumber + ", price=" + price + ", builder=" + builder + ", model=" + model + ", backWood=" + backWood + ", topWood=" + topWood + '}';
    }

    @Override
    public int compareTo(Guitar other) {
        if (price > other.getPrice()) {
            return 1;
        } else if (price < other.getPrice()) {
            return -1;
        } else {
            return serialNumber.compareTo(other.getSerialNumber());
        }
    }
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.List;
import java.util.Stack;

/**
 * This class implements the Kosaraju Algorithm to find all the Strongly Connected Components (SCCs)
 * of a directed graph. Kosaraju's algorithm runs in linear time and leverages the concept that
 * the SCCs of a directed graph remain the same in its transpose (reverse) graph.
 *
 * <p>
 * A strongly connected component (SCC) of a directed graph is a subgraph where every vertex
 * is reachable from every other vertex in the subgraph. The Kosaraju algorithm is particularly
 * efficient for finding SCCs because it performs two Depth First Search (DFS) passes on the
 * graph and its transpose.
 * </p>
 *
 * <p><strong>Algorithm:</strong></p>
 * <ol>
 *     <li>Perform DFS on the original graph and push nodes to a stack in the order of their finishing time.</li>
 *     <li>Generate the transpose (reversed edges) of the original graph.</li>
 *     <li>Perform DFS on the transpose graph, using the stack from the first DFS. Each DFS run on the transpose graph gives a SCC.</li>
 * </ol>
 *
 * <p><strong>Example Graph:</strong></p>
 * <pre>
 * 0 <--- 2 -------> 3 -------- > 4 ---- > 7
 * |     ^                      | ^       ^
 * |    /                       |  \     /
 * |   /                        |   \   /
 * v  /                         v    \ /
 * 1                            5 --> 6
 * </pre>
 *
 * <p><strong>SCCs in the example:</strong></p>
 * <ul>
 *     <li>{0, 1, 2}</li>
 *     <li>{3}</li>
 *     <li>{4, 5, 6}</li>
 *     <li>{7}</li>
 * </ul>
 *
 * <p>The order of nodes in an SCC does not matter because every node in an SCC is reachable from every other node within the same SCC.</p>
 *
 * <p><strong>Graph Transpose Example:</strong></p>
 * <pre>
 * 0 ---> 2 <------- 3 <------- 4 <------ 7
 * ^     /                      ^ \       /
 * |    /                       |  \     /
 * |   /                        |   \   /
 * |  v                         |    v v
 * 1                            5 <--- 6
 * </pre>
 *
 * The SCCs of this transpose graph are the same as the original graph.
 */
public class KosarajuAlgorithm {

private final Stack<Integer> finishStack = new Stack<>();
private List<Integer> currentComponent = new ArrayList<>();
private final List<List<Integer>> allComponents = new ArrayList<>();

/**
 * Main function to perform Kosaraju's Algorithm.
 * Steps:
 * 1. Sort nodes by the lowest finishing time
 * 2. Create the transpose (reverse edges) of the original graph
 * 3. Find SCCs by performing DFS on the transpose graph
 * 4. Return the list of SCCs
 *
 * @param totalVertices the number of vertices in the graph
 * @param adjacencyList the adjacency list representing the directed graph
 * @return a list of SCCs where each SCC is a list of vertices
 */
public List<List<Integer>> findSCCs(int totalVertices, List<List<Integer>> adjacencyList) {
orderNodesByFinishTime(totalVertices, adjacencyList);
List<List<Integer>> reversedGraph = buildTransposeGraph(totalVertices, adjacencyList);
extractStronglyConnectedComponents(totalVertices, reversedGraph);
return allComponents;
}

/**
 * Performs DFS on the original graph to sort nodes by their finishing times.
 * @param totalVertices the number of vertices in the graph
 * @param adjacencyList the adjacency list representing the original graph
 */
private void orderNodesByFinishTime(int totalVertices, List<List<Integer>> adjacencyList) {
int[] visitedStatus = new int[totalVertices];
for (int nodeIndex = 0; nodeIndex < totalVertices; nodeIndex++) {
if (visitedStatus[nodeIndex] == 0) {
depthFirstSearch(nodeIndex, visitedStatus, adjacencyList);
}
}
}

/**
 * Creates the transpose (reverse) of the original graph.
 * @param totalVertices the number of vertices in the graph
 * @param adjacencyList the adjacency list representing the original graph
 * @return the adjacency list representing the transposed graph
 */
private List<List<Integer>> buildTransposeGraph(int totalVertices, List<List<Integer>> adjacencyList) {
List<List<Integer>> transposeGraph = new ArrayList<>(totalVertices);
for (int vertexIndex = 0; vertexIndex < totalVertices; vertexIndex++) {
transposeGraph.add(new ArrayList<>());
}
for (int sourceVertex = 0; sourceVertex < totalVertices; sourceVertex++) {
for (Integer targetVertex : adjacencyList.get(sourceVertex)) {
transposeGraph.get(targetVertex).add(sourceVertex);
}
}
return transposeGraph;
}

/**
 * Finds the strongly connected components (SCCs) by performing DFS on the transposed graph.
 * @param totalVertices the number of vertices in the graph
 * @param reversedGraph the adjacency list representing the transposed graph
 */
public void extractStronglyConnectedComponents(int totalVertices, List<List<Integer>> reversedGraph) {
int[] visitedStatus = new int[totalVertices];
while (!finishStack.isEmpty()) {
int currentNode = finishStack.pop();
if (visitedStatus[currentNode] == 0) {
collectComponent(currentNode, visitedStatus, reversedGraph);
allComponents.add(currentComponent);
currentComponent = new ArrayList<>();
}
}
}

/**
 * Performs DFS on the original graph and pushes nodes onto the stack in order of their finish time.
 * @param startNode the current node being visited
 * @param visitedStatus array to keep track of visited nodes
 * @param adjacencyList the adjacency list of the graph
 */
private void depthFirstSearch(int startNode, int[] visitedStatus, List<List<Integer>> adjacencyList) {
visitedStatus[startNode] = 1;
for (Integer neighborNode : adjacencyList.get(startNode)) {
if (visitedStatus[neighborNode] == 0) {
depthFirstSearch(neighborNode, visitedStatus, adjacencyList);
}
}
finishStack.push(startNode);
}

/**
 * Performs DFS on the transposed graph to find the strongly connected components.
 * @param startNode the current node being visited
 * @param visitedStatus array to keep track of visited nodes
 * @param reversedGraph the adjacency list of the transposed graph
 */
private void collectComponent(int startNode, int[] visitedStatus, List<List<Integer>> reversedGraph) {
visitedStatus[startNode] = 1;
for (Integer neighborNode : reversedGraph.get(startNode)) {
if (visitedStatus[neighborNode] == 0) {
collectComponent(neighborNode, visitedStatus, reversedGraph);
}
}
currentComponent.add(startNode);
}
}

