/**
 A Java-based utility for converting numeric values into their English word
 representations. Whether you need to convert a small number, a large number
 with millions and billions, or even a number with decimal places, this utility
 has you covered.
 *
 */
public final class NumberToWords {

private NumberToWords() {
}

private static final String[] BASIC_UNITS = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"};
private static final String[] DECADE_NAMES = {"", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};
private static final String[] MAGNITUDE_SUFFIX = {"", "Thousand", "Million", "Billion", "Trillion"};
private static final String ZERO_TEXT = "Zero";
private static final String DECIMAL_MARKER = " Point";
private static final String NEGATIVE_PREFIX = "Negative ";

public static String convert(BigDecimal numericValue) {
if (numericValue == null) {
return "Invalid Input";
}
boolean hasNegativeSign = numericValue.signum() < 0;
BigDecimal[] integerFractionParts = numericValue.abs().divideAndRemainder(BigDecimal.ONE);
BigDecimal integerComponent = integerFractionParts[0];
String fractionComponent = integerFractionParts[1].compareTo(BigDecimal.ZERO) > 0 ? integerFractionParts[1].toPlainString().substring(2) : "";
StringBuilder outputText = new StringBuilder();
if (hasNegativeSign) {
outputText.append(NEGATIVE_PREFIX);
}
outputText.append(convertIntegerPart(integerComponent));
if (!fractionComponent.isEmpty()) {
outputText.append(DECIMAL_MARKER);
for (char digitChar : fractionComponent.toCharArray()) {
int digitValue = Character.getNumericValue(digitChar);
outputText.append(" ").append(digitValue == 0 ? ZERO_TEXT : BASIC_UNITS[digitValue]);
}
}
return outputText.toString().trim();
}

private static String convertIntegerPart(BigDecimal integerValue) {
if (integerValue.compareTo(BigDecimal.ZERO) == 0) {
return ZERO_TEXT;
}
StringBuilder wordResult = new StringBuilder();
int magnitudeIndex = 0;
BigDecimal remainingValue = integerValue;
while (remainingValue.compareTo(BigDecimal.ZERO) > 0) {
BigDecimal[] divisionResult = remainingValue.divideAndRemainder(BigDecimal.valueOf(1000));
int threeDigitGroup = divisionResult[1].intValue();
if (threeDigitGroup > 0) {
String groupWords = convertThreeDigitGroup(threeDigitGroup);
if (magnitudeIndex > 0) {
wordResult.insert(0, MAGNITUDE_SUFFIX[magnitudeIndex] + " ");
}
wordResult.insert(0, groupWords + " ");
}
remainingValue = divisionResult[0];
magnitudeIndex++;
}
return wordResult.toString().trim();
}

private static String convertThreeDigitGroup(int groupValue) {
String resultSegment;
if (groupValue < 20) {
resultSegment = BASIC_UNITS[groupValue];
} else if (groupValue < 100) {
resultSegment = DECADE_NAMES[groupValue / 10] + (groupValue % 10 > 0 ? " " + BASIC_UNITS[groupValue % 10] : "");
} else {
resultSegment = BASIC_UNITS[groupValue / 100] + " Hundred" + (groupValue % 100 > 0 ? " " + convertThreeDigitGroup(groupValue % 100) : "");
}
return resultSegment;
}
}

/**
 * Disjoint Set Union (DSU) with Union by Size.
 * This data structure tracks a set of elements partitioned into disjoint (non-overlapping) subsets.
 * It supports two primary operations efficiently:
 *
 * <ul>
 *     <li>Find: Determine which subset a particular element belongs to.</li>
 *     <li>Union: Merge two subsets into a single subset using union by size.</li>
 * </ul>
 *
 * Union by size always attaches the smaller tree under the root of the larger tree.
 * This helps keep the tree shallow, improving the efficiency of find operations.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Disjoint-set_data_structure">Disjoint Set Union (Wikipedia)</a>
 */
public class DisjointSetUnionBySize<T> {
    /**
     * Node class for DSU by size.
     * Each node keeps track of its parent and the size of the set it represents.
     */
    public static class Node<T> {
        public T value;
        public Node<T> parent;
        public int size; // size of the set

        public Node(T value) {
            this.value = value;
            this.parent = this;
            this.size = 1; // initially, the set size is 1
        }
    }

    /**
     * Creates a new disjoint set containing the single specified element.
     * @param value the element to be placed in a new singleton set
     * @return a node representing the new set
     */
    public Node<T> makeSet(final T value) {
        return new Node<>(value);
    }

    /**
     * Finds and returns the representative (root) of the set containing the given node.
     * This method applies path compression to flatten the tree structure for future efficiency.
     * @param node the node whose set representative is to be found
     * @return the representative (root) node of the set
     */
    public Node<T> findSet(Node<T> node) {
        if (node != node.parent) {
            node.parent = findSet(node.parent); // path compression
        }
        return node.parent;
    }

    /**
     * Merges the sets containing the two given nodes using union by size.
     * The root of the smaller set is attached to the root of the larger set.
     * @param x a node in the first set
     * @param y a node in the second set
     */
    public void unionSets(Node<T> x, Node<T> y) {
        Node<T> rootX = findSet(x);
        Node<T> rootY = findSet(y);

        if (rootX == rootY) {
            return; // They are already in the same set
        }
        // Union by size: attach smaller tree under the larger one
        if (rootX.size < rootY.size) {
            rootX.parent = rootY;
            rootY.size += rootX.size; // update size
        } else {
            rootY.parent = rootX;
            rootX.size += rootY.size; // update size
        }
    }
}
// This implementation uses union by size instead of union by rank.
// The size field tracks the number of elements in each set.
// When two sets are merged, the smaller set is always attached to the larger set's root.
// This helps keep the tree shallow and improves the efficiency of find operations.

/*
Given the following grid with length m and width n:
\---\---\---\ (n)
\ 1 \ 3 \ 1 \
\---\---\---\
\ 1 \ 5 \ 1 \
\---\---\---\
\ 4 \ 2 \ 1 \
\---\---\---\
(m)
Find the path where its sum is the smallest.

The Time Complexity of your algorithm should be smaller than or equal to O(mn).
The Space Complexity of your algorithm should be smaller than or equal to O(n).
You can only move from the top left corner to the down right corner.
You can only move one step down or right.

EXAMPLE:
INPUT: grid = [[1,3,1],[1,5,1],[4,2,1]]
OUTPUT: 7
EXPLANATIONS: 1 + 3 + 1 + 1 + 1 = 7

For more information see https://www.geeksforgeeks.org/maximum-path-sum-matrix/
 */
public final class MinimumPathSum {

    private MinimumPathSum() {
    }

    public static int minimumPathSum(final int[][] grid) {
        int numRows = grid.length;
        int numCols = grid[0].length;

        if (numCols == 0) {
            return 0;
        }

        int[] dp = new int[numCols];

        // Initialize the first element of the dp array
        dp[0] = grid[0][0];

        // Calculate the minimum path sums for the first row
        for (int col = 1; col < numCols; col++) {
            dp[col] = dp[col - 1] + grid[0][col];
        }

        // Calculate the minimum path sums for the remaining rows
        for (int row = 1; row < numRows; row++) {
            // Update the minimum path sum for the first column
            dp[0] += grid[row][0];

            for (int col = 1; col < numCols; col++) {
                // Choose the minimum path sum from the left or above
                dp[col] = Math.min(dp[col - 1], dp[col]) + grid[row][col];
            }
        }

        // Return the minimum path sum for the last cell in the grid
        return dp[numCols - 1];
    }
}

/**
 * A simple two-number calculator driven by an operator character.
 */
public class Part2 {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Input number 1: ");
        double a = scanner.nextDouble();
        System.out.print("Input number 2: ");
        double b = scanner.nextDouble();
        scanner.nextLine();
        System.out.print("Enter the operator(+-*/): ");
        char op = scanner.nextLine().charAt(0);
        switch (op) {
            case '+':
                System.out.println("The result of: " + a + op + b + "=" + (a + b));
                break;
            case '-':
                System.out.println("The result of: " + a + op + b + "=" + (a - b));
                break;
            case '*':
                System.out.println("The result of: " + a + op + b + "=" + (a * b));
                break;
            case '/':
                System.out.println("The result of: " + a + op + b + "=" + (a / b));
                break;
            default:
                System.out.println("Please enter operator");
                break;
        }
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Given a text and wildcard pattern implement a wildcard pattern matching
 * algorithm that finds if wildcard is matched with text. The matching should
 * cover the entire text ?-> matches single characters *-> match the sequence of
 * characters
 *
 * For calculation of Time and Space Complexity. Let N be length of src and M be length of pat
 *
 * Memoization vs Tabulation : https://www.geeksforgeeks.org/tabulation-vs-memoization/
 * Question Link : https://practice.geeksforgeeks.org/problems/wildcard-pattern-matching/1
 */
public final class RegexMatching {
    private RegexMatching() {
    }

    /**
     * Method 1: Determines if the given source string matches the given pattern using a recursive approach.
     * This method directly applies recursion to check if the source string matches the pattern, considering
     * the wildcards '?' and '*'.
     *
     * Time Complexity: O(2^(N+M)), where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N + M) due to the recursion stack.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    public static boolean regexRecursion(String src, String pat) {
        if (src.length() == 0 && pat.length() == 0) {
            return true;
        }
        if (src.length() != 0 && pat.length() == 0) {
            return false;
        }
        if (src.length() == 0 && pat.length() != 0) {
            for (int i = 0; i < pat.length(); i++) {
                if (pat.charAt(i) != '*') {
                    return false;
                }
            }
            return true;
        }
        char chs = src.charAt(0);
        char chp = pat.charAt(0);

        String ros = src.substring(1);
        String rop = pat.substring(1);

        boolean ans;
        if (chs == chp || chp == '?') {
            ans = regexRecursion(ros, rop);
        } else if (chp == '*') {
            boolean blank = regexRecursion(src, rop);
            boolean multiple = regexRecursion(ros, pat);
            ans = blank || multiple;
        } else {
            ans = false;
        }
        return ans;
    }

    /**
     * Method 2: Determines if the given source string matches the given pattern using recursion.
     * This method utilizes a virtual index for both the source string and the pattern to manage the recursion.
     *
     * Time Complexity: O(2^(N+M)) where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N + M) due to the recursion stack.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @param svidx The current index in the source string.
     * @param pvidx The current index in the pattern.
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    static boolean regexRecursion(String src, String pat, int svidx, int pvidx) {
        if (src.length() == svidx && pat.length() == pvidx) {
            return true;
        }
        if (src.length() != svidx && pat.length() == pvidx) {
            return false;
        }
        if (src.length() == svidx && pat.length() != pvidx) {
            for (int i = pvidx; i < pat.length(); i++) {
                if (pat.charAt(i) != '*') {
                    return false;
                }
            }
            return true;
        }
        char chs = src.charAt(svidx);
        char chp = pat.charAt(pvidx);

        boolean ans;
        if (chs == chp || chp == '?') {
            ans = regexRecursion(src, pat, svidx + 1, pvidx + 1);
        } else if (chp == '*') {
            boolean blank = regexRecursion(src, pat, svidx, pvidx + 1);
            boolean multiple = regexRecursion(src, pat, svidx + 1, pvidx);
            ans = blank || multiple;
        } else {
            ans = false;
        }
        return ans;
    }

    /**
     * Method 3: Determines if the given source string matches the given pattern using top-down dynamic programming (memoization).
     * This method utilizes memoization to store intermediate results, reducing redundant computations and improving efficiency.
     *
     * Time Complexity: O(N * M), where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N * M) for the memoization table, plus additional space for the recursion stack.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @param svidx The current index in the source string.
     * @param pvidx The current index in the pattern.
     * @param strg A 2D array used for memoization to store the results of subproblems.
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    public static boolean regexRecursion(String src, String pat, int svidx, int pvidx, int[][] strg) {
        if (src.length() == svidx && pat.length() == pvidx) {
            return true;
        }
        if (src.length() != svidx && pat.length() == pvidx) {
            return false;
        }
        if (src.length() == svidx && pat.length() != pvidx) {
            for (int i = pvidx; i < pat.length(); i++) {
                if (pat.charAt(i) != '*') {
                    return false;
                }
            }
            return true;
        }
        if (strg[svidx][pvidx] != 0) {
            return strg[svidx][pvidx] != 1;
        }
        char chs = src.charAt(svidx);
        char chp = pat.charAt(pvidx);

        boolean ans;
        if (chs == chp || chp == '?') {
            ans = regexRecursion(src, pat, svidx + 1, pvidx + 1, strg);
        } else if (chp == '*') {
            boolean blank = regexRecursion(src, pat, svidx, pvidx + 1, strg);
            boolean multiple = regexRecursion(src, pat, svidx + 1, pvidx, strg);
            ans = blank || multiple;
        } else {
            ans = false;
        }
        strg[svidx][pvidx] = ans ? 2 : 1;
        return ans;
    }

    /**
     * Method 4: Determines if the given source string matches the given pattern using bottom-up dynamic programming (tabulation).
     * This method builds a solution iteratively by filling out a table, where each cell represents whether a substring
     * of the source string matches a substring of the pattern.
     *
     * Time Complexity: O(N * M), where N is the length of the source string and M is the length of the pattern.
     * Space Complexity: O(N * M) for the table used in the tabulation process.
     *
     * @param src The source string to be matched against the pattern.
     * @param pat The pattern containing wildcards ('*' matches a sequence of characters, '?' matches a single character).
     * @return {@code true} if the source string matches the pattern, {@code false} otherwise.
     */
    static boolean regexBU(String src, String pat) {
        boolean[][] strg = new boolean[src.length() + 1][pat.length() + 1];
        strg[src.length()][pat.length()] = true;
        for (int row = src.length(); row >= 0; row--) {
            for (int col = pat.length() - 1; col >= 0; col--) {
                if (row == src.length()) {
                    if (pat.charAt(col) == '*') {
                        strg[row][col] = strg[row][col + 1];
                    } else {
                        strg[row][col] = false;
                    }
                } else {
                    char chs = src.charAt(row);
                    char chp = pat.charAt(col);

                    boolean ans;
                    if (chs == chp || chp == '?') {
                        ans = strg[row + 1][col + 1];
                    } else if (chp == '*') {
                        boolean blank = strg[row][col + 1];
                        boolean multiple = strg[row + 1][col];
                        ans = blank || multiple;
                    } else {
                        ans = false;
                    }
                    strg[row][col] = ans;
                }
            }
        }
        return strg[0][0];
    }
}

/**
 * A generic BloomFilter implementation for probabilistic membership checking.
 * <p>
 * Bloom filters are space-efficient data structures that provide a fast way to
 * test whether an
 * element is a member of a set. They may produce false positives, indicating an
 * element is
 * in the set when it is not, but they will never produce false negatives.
 * </p>
 *
 * @param <ElementType> The type of elements to be stored in the Bloom filter.
 */
@SuppressWarnings("rawtypes")
public class BloomFilter<ElementType> {

private final int hashFunctionCount;
private final BitSet storageBits;
private final Hash<ElementType>[] hashFunctions;

/**
 * Constructs a BloomFilter with a specified number of hash functions and bit
 * array size.
 *
 * @param functionCount the number of hash functions to use
 * @param bitCapacity   the size of the bit array, which determines the
 *                              capacity of the filter
 * @throws IllegalArgumentException if functionCount or bitCapacity is
 *                                  less than 1
 */
@SuppressWarnings("unchecked")
public BloomFilter(int functionCount, int bitCapacity) {
if (functionCount < 1 || bitCapacity < 1) {
throw new IllegalArgumentException("Number of hash functions and bit array size must be greater than 0");
}
this.hashFunctionCount = functionCount;
this.storageBits = new BitSet(bitCapacity);
this.hashFunctions = new Hash[functionCount];
setupHashFunctions();
}

/**
 * Initializes the hash functions with unique indices to ensure different
 * hashing.
 */
private void setupHashFunctions() {
for (int functionIndex = 0; functionIndex < hashFunctionCount; functionIndex++) {
hashFunctions[functionIndex] = new Hash<>(functionIndex);
}
}

/**
 * Inserts an element into the Bloom filter.
 * <p>
 * This method hashes the element using all defined hash functions and sets the
 * corresponding
 * bits in the bit array.
 * </p>
 *
 * @param inputKey the element to insert into the Bloom filter
 */
public void insert(ElementType inputKey) {
for (Hash<ElementType> currentHash : hashFunctions) {
int bitPosition = Math.abs(currentHash.compute(inputKey) % storageBits.size());
storageBits.set(bitPosition);
}
}

/**
 * Checks if an element might be in the Bloom filter.
 * <p>
 * This method checks the bits at the positions computed by each hash function.
 * If any of these
 * bits are not set, the element is definitely not in the filter. If all bits
 * are set, the element
 * might be in the filter.
 * </p>
 *
 * @param targetKey the element to check for membership in the Bloom filter
 * @return {@code true} if the element might be in the Bloom filter,
 *         {@code false} if it is definitely not
 */
public boolean contains(ElementType targetKey) {
for (Hash<ElementType> currentHash : hashFunctions) {
int bitPosition = Math.abs(currentHash.compute(targetKey) % storageBits.size());
if (!storageBits.get(bitPosition)) {
return false;
}
}
return true;
}

/**
 * Inner class representing a hash function used by the Bloom filter.
 * <p>
 * Each instance of this class represents a different hash function based on its
 * index.
 * </p>
 *
 * @param <ElementType> The type of elements to be hashed.
 */
private static class Hash<ElementType> {

private final int functionId;

/**
 * Constructs a Hash function with a specified index.
 *
 * @param functionId the index of this hash function, used to create a unique hash
 */
Hash(int functionId) {
this.functionId = functionId;
}

/**
 * Computes the hash of the given key.
 * <p>
 * The hash value is calculated by multiplying the index of the hash function
 * with the ASCII sum of the string representation of the key.
 * </p>
 *
 * @param targetKey the element to hash
 * @return the computed hash value
 */
public int compute(ElementType targetKey) {
return functionId * computeContentHash(targetKey);
}

/**
 * Computes the ASCII value sum of the characters in a string.
 * <p>
 * This method iterates through each character of the string and accumulates
 * their ASCII values to produce a single integer value.
 * </p>
 *
 * @param textInput the string to compute
 * @return the sum of ASCII values of the characters in the string
 */
private int sumAsciiValues(String textInput) {
int totalSum = 0;
for (char currentChar : textInput.toCharArray()) {
totalSum += currentChar;
}
return totalSum;
}

/**
 * Computes a content-based hash for arrays; falls back to ASCII-sum of String value otherwise.
 */
private int computeContentHash(Object inputObject) {
if (inputObject instanceof int[]) {
return Arrays.hashCode((int[]) inputObject);
} else if (inputObject instanceof long[]) {
return Arrays.hashCode((long[]) inputObject);
} else if (inputObject instanceof byte[]) {
return Arrays.hashCode((byte[]) inputObject);
} else if (inputObject instanceof short[]) {
return Arrays.hashCode((short[]) inputObject);
} else if (inputObject instanceof char[]) {
return Arrays.hashCode((char[]) inputObject);
} else if (inputObject instanceof boolean[]) {
return Arrays.hashCode((boolean[]) inputObject);
} else if (inputObject instanceof float[]) {
return Arrays.hashCode((float[]) inputObject);
} else if (inputObject instanceof double[]) {
return Arrays.hashCode((double[]) inputObject);
} else if (inputObject instanceof Object[]) {
return Arrays.deepHashCode((Object[]) inputObject);
}
return sumAsciiValues(String.valueOf(inputObject));
}
}
}

package functions;

public class SayiOkuma {

    public static void main(String[] args) {

    	System.out.println(sayiOkunusu(1234));  // Sayinin okunusunu yazdir

        System.out.println(sayiOkunusu(7248));  

        System.out.println(sayiOkunusu(297));  

        System.out.println(sayiOkunusu(505));  

        System.out.println(sayiOkunusu(300)); 
    }

    // Sayinin okunusunu donduren ana fonksiyon
    public static String sayiOkunusu(int sayi) {
        // Eger sayi 0 ise "sifir" dondurulur
        if (sayi == 0) return "sifir";

        // Sonuc metnini tutacak degisken
        String sonuc = "";

        // Binler basamagini ayirma
        int bin = sayi / 1000;
        // Yuzler basamagini ayirma
        int yuz = (sayi / 100) % 10;
        // Onlar basamagini ayirma
        int on = (sayi / 10) % 10;
        // Birler basamagini ayirma
        int bir = sayi % 10;

        // Binler basamagi eklenir
        if (bin > 0) {
            sonuc += binOkunusu(bin) + " ";
        }

