package whileloop;

public class BasamakDegeri {

	public static void main(String[] args) {

		tumKombinasyonlariListele();

		System.out.println("Basamak Sayisi: " + basamakAdediniHesapla(345987));

		System.out.println("Rakamlar Toplami: " + digitToplamiHesapla(24653));

	}

	// Onlar ve birler basamagi olasi tum kombinasyonlarini ekrana basar
	public static void tumKombinasyonlariListele() {
		int onlarHanesi = 0;
		// Onlar hanesi 0'dan 4'e kadar donuyor
		while (onlarHanesi <= 4) {
			int birlerHanesi = 1;
			// Birler hanesi 1'den 9'a kadar donuyor
			while (birlerHanesi <= 9) {
				int birlesikSayi = onlarHanesi * 10 + birlerHanesi;
				System.out.println("Onlar basamagi: " + onlarHanesi + ", Birler basamagi: " + birlerHanesi + " --> " + birlesikSayi);
				birlerHanesi++;
			}
			onlarHanesi++;
		}
	}

	// Bir sayinin butun rakamlarinin toplamini dondurur
	public static int digitToplamiHesapla(int deger) {
		int toplam = 0;
		// Rakamlar tek tek ayristirilip toplama eklenir
		for (int kalan = deger; kalan > 0; kalan /= 10) {
			toplam += kalan % 10;
		}
		return toplam;
	}

	// Bir sayinin kac basamaktan olustugunu dondurur
	public static int basamakAdediniHesapla(int deger) {
		int adet = 0;
		// Sayi sifira dusene kadar her adimda bir basamak sayilir
		for (int kalan = deger; kalan > 0; kalan /= 10) {
			adet++;
		}
		return adet;
	}
}

/**
 * The Knight's Tour problem solver using backtracking with Warnsdorff's heuristic.
 * 
 * <p><b>Problem Statement:</b><br>
 * Given an N×N chessboard with a knight placed on the first block, the knight must
 * move according to standard chess rules and visit each square on the board exactly once.
 * This produces a "tour" of the knight across the entire board.</p>
 * 
 * <p><b>Example:</b>
 * <pre>
 * Input: N = 8 (standard 8×8 chessboard)
 * Output: A sequence of 64 numbers representing the order in which the knight visits each square.
 * The tour starts at position (2,2) - row 2, column 2 (0-indexed).
 * </pre>
 * 
 * <p><b>Algorithm Features:</b></p>
 * <ul>
 *   <li>Implements Warnsdorff's heuristic (choose the cell with the fewest onward moves)</li>
 *   <li>Uses backtracking to explore possible tours</li>
 *   <li>Includes orphan detection to prune dead ends early</li>
 *   <li>Adds buffer around the board to simplify boundary checking</li>
 * </ul>
 * 
 * @see <a href="https://en.wikipedia.org/wiki/Knight%27s_tour">Knight's Tour (Wikipedia)</a>
 * @see <a href="https://en.wikipedia.org/wiki/Warnsdorff%27s_rule">Warnsdorff's Rule</a>
 */
public final class KnightsTour {

    // Private constructor to prevent instantiation (utility class)
    private KnightsTour() {
        throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
    }

    // Board size: 12x12 grid with 2 extra rows/columns as a buffer around an 8x8 usable area
    // The buffer simplifies boundary checking - we don't need to check array bounds explicitly
    private static final int BOARD_DIMENSION = 12;

    // Buffer size (number of extra rows/columns around the usable board)
    private static final int BUFFER_SIZE = 2;

    // Usable board size = BOARD_DIMENSION - 2 * BUFFER_SIZE
    private static final int USABLE_BOARD_SIZE = BOARD_DIMENSION - 2 * BUFFER_SIZE;

    // All 8 possible moves for a knight in chess (x, y coordinate changes)
    // Format: {columnChange, rowChange}
    private static final int[][] LEGAL_MOVES = {
        {1, -2},  // Move right 1, up 2
        {2, -1},  // Move right 2, up 1
        {2, 1},   // Move right 2, down 1
        {1, 2},   // Move right 1, down 2
        {-1, 2},  // Move left 1, down 2
        {-2, 1},  // Move left 2, down 1
        {-2, -1}, // Move left 2, up 1
        {-1, -2}, // Move left 1, up 2
    };

    // Chess grid representing the board (0 = unvisited, -1 = boundary cell, positive = move number)
    private static int[][] chessBoard;

    // Total number of cells the knight needs to visit (board area)
    private static int totalCellsToVisit;

    /**
     * Resets the chess board to its initial state.
     * 
     * Initializes the grid with:
     * - Boundary cells (first 2 rows, last 2 rows, first 2 columns, last 2 columns) marked as -1
     * - Internal cells (the actual 8x8 board) marked as 0 (unvisited)
     * - Sets the total number of cells to visit
     */
    public static void initializeBoard() {
        chessBoard = new int[BOARD_DIMENSION][BOARD_DIMENSION];
        totalCellsToVisit = USABLE_BOARD_SIZE * USABLE_BOARD_SIZE;

        // Mark boundary cells as -1 (out of bounds / inaccessible)
        for (int rowIndex = 0; rowIndex < BOARD_DIMENSION; rowIndex++) {
            for (int colIndex = 0; colIndex < BOARD_DIMENSION; colIndex++) {
                if (rowIndex < BUFFER_SIZE || 
                    rowIndex > BOARD_DIMENSION - BUFFER_SIZE - 1 ||
                    colIndex < BUFFER_SIZE || 
                    colIndex > BOARD_DIMENSION - BUFFER_SIZE - 1) {
                    chessBoard[rowIndex][colIndex] = -1; // Boundary marker
                }
            }
        }
    }

    /**
     * Gets the current state of the chess board.
     *
     * @return 2D array representing the board (0 = unvisited, -1 = boundary, positive = move order)
     */
    public static int[][] getBoard() {
        return chessBoard;
    }

    /**
     * Prints the chess board with move numbers in a readable format.
     * Each cell shows the step number when the knight visited that square.
     */
    public static void printBoard() {
        System.out.println("Knight's Tour Solution:");
        System.out.println("Each number represents the move order (starting from 1):\n");

        for (int rowIndex = 0; rowIndex < BOARD_DIMENSION; rowIndex++) {
            for (int colIndex = 0; colIndex < BOARD_DIMENSION; colIndex++) {
                if (chessBoard[rowIndex][colIndex] == -1) {
                    System.out.print("  ** "); // Boundary cells
                } else {
                    System.out.printf("%4d ", chessBoard[rowIndex][colIndex]);
                }
            }
            System.out.println();
        }
    }

    /**
     * Solves the Knight's Tour problem using backtracking with Warnsdorff's heuristic.
     * 
     * @param startRow The starting row of the knight (0-indexed within the usable board)
     * @param startCol The starting column of the knight (0-indexed within the usable board)
     * @return true if a solution exists, false otherwise
     */
    public static boolean findKnightTour(int startRow, int startCol) {
        // Convert start position to buffer-adjusted coordinates
        int adjustedRow = startRow + BUFFER_SIZE;
        int adjustedCol = startCol + BUFFER_SIZE;

        // Place knight at starting position
        chessBoard[adjustedRow][adjustedCol] = 1; // First move

        // Find complete tour (move count starts at 2 because first move is already placed)
        boolean solutionFound = exploreKnightMoves(adjustedRow, adjustedCol, 2);

        if (!solutionFound) {
            System.out.println("No valid knight's tour found from starting position (" + 
                               startRow + ", " + startCol + ")");
        }

        return solutionFound;
    }

    /**
     * Recursive method to solve the Knight's Tour problem.
     * Uses Warnsdorff's heuristic to prioritize moves with fewer onward options.
     *
     * @param currentRow The current row of the knight
     * @param currentCol The current column of the knight
     * @param moveCount  The current move number (1-indexed)
     * @return True if a solution is found, False otherwise
     */
    private static boolean exploreKnightMoves(int currentRow, int currentCol, int moveCount) {
        // Base case: All cells have been visited
        if (moveCount > totalCellsToVisit) {
            return true;
        }

        // Get all valid neighbors from current position, sorted by Warnsdorff's rule
        List<int[]> availableMoves = getValidMoves(currentRow, currentCol);

        // Early pruning: If no moves available but not all cells visited, this path fails
        if (availableMoves.isEmpty() && moveCount <= totalCellsToVisit) {
            return false;
        }

        // Sort moves by number of onward moves (Warnsdorff's heuristic)
        // This significantly improves performance by trying promising moves first
        availableMoves.sort(Comparator.comparingInt(move -> move[2]));

        // Try each move in order of increasing onward options
        for (int[] nextMove : availableMoves) {
            int nextRow = nextMove[0];
            int nextCol = nextMove[1];

            // Place knight at the next position
            chessBoard[nextRow][nextCol] = moveCount;

            // Check for orphans (cells that would become unreachable)
            // This pruning technique prevents making moves that lead to dead ends
            if (!hasOrphanCells(moveCount, nextRow, nextCol) && 
                exploreKnightMoves(nextRow, nextCol, moveCount + 1)) {
                return true;
            }

            // Backtrack: Undo the move
            chessBoard[nextRow][nextCol] = 0;
        }

        return false;
    }

    /**
     * Returns a list of valid neighboring positions where the knight can move.
     * 
     * @param currentRow The current row of the knight
     * @param currentCol The current column of the knight
     * @return A list of arrays, each containing: {nextRow, nextCol, numberOfPossibleNextMoves}
     */
    private static List<int[]> getValidMoves(int currentRow, int currentCol) {
        List<int[]> validMoves = new ArrayList<>();

        for (int[] moveOffset : LEGAL_MOVES) {
            int nextRow = currentRow + moveOffset[1]; // row change is second element
            int nextCol = currentCol + moveOffset[0]; // column change is first element

            // Check if the move is within board bounds and the cell is unvisited
            if (nextRow >= 0 && nextRow < BOARD_DIMENSION && 
                nextCol >= 0 && nextCol < BOARD_DIMENSION && 
                chessBoard[nextRow][nextCol] == 0) {

                int onwardMoveCount = countOnwardMoves(nextRow, nextCol);
                validMoves.add(new int[]{nextRow, nextCol, onwardMoveCount});
            }
        }
        return validMoves;
    }

    /**
     * Counts the number of possible onward moves from a given position.
     * Used for Warnsdorff's heuristic.
     *
     * @param currentRow The row of the current position
     * @param currentCol The column of the current position
     * @return The number of valid neighboring moves
     */
    private static int countOnwardMoves(int currentRow, int currentCol) {
        int onwardMoveCount = 0;

        for (int[] moveOffset : LEGAL_MOVES) {
            int nextRow = currentRow + moveOffset[1];
            int nextCol = currentCol + moveOffset[0];

            if (nextRow >= 0 && nextRow < BOARD_DIMENSION && 
                nextCol >= 0 && nextCol < BOARD_DIMENSION && 
                chessBoard[nextRow][nextCol] == 0) {
                onwardMoveCount++;
            }
        }
        return onwardMoveCount;
    }

    /**
     * Detects if making a move will create an orphan cell (a position with no further valid moves).
     * This helps prune dead-end paths early.
     *
     * @param currentMoveNumber The current move number
     * @param currentRow The row of the current position after the move
     * @param currentCol The column of the current position after the move
     * @return True if an orphan would be created, False otherwise
     */
    private static boolean hasOrphanCells(int currentMoveNumber, int currentRow, int currentCol) {
        // Only check if we haven't yet filled the board (need at least 2 more moves)
        if (currentMoveNumber < totalCellsToVisit - 1) {
            List<int[]> futureMoves = getValidMoves(currentRow, currentCol);

            // Check if any future move leads to a dead end (zero onward moves)
            for (int[] nextMove : futureMoves) {
                if (countOnwardMoves(nextMove[0], nextMove[1]) == 0) {
                    return true; // Orphan detected - this path is doomed
                }
            }
        }
        return false;
    }

    /**
     * Static method to solve the knight's tour and return the result.
     * 
     * @param boardSize The size of the square board (N for N×N board)
     * @param startRow Starting row (0-indexed from 0 to boardSize-1)
     * @param startCol Starting column (0-indexed from 0 to boardSize-1)
     * @return The solved board as 2D array, or null if no solution exists
     */
    public static int[][] solveKnightsTour(int boardSize, int startRow, int startCol) {
        // Note: This implementation uses fixed BOARD_DIMENSION = 12
        // For different board sizes, the class would need to be modified
        if (boardSize != USABLE_BOARD_SIZE) {
            throw new IllegalArgumentException(
                "This implementation supports only " + USABLE_BOARD_SIZE + "x" + USABLE_BOARD_SIZE + 
                " boards. Requested: " + boardSize + "x" + boardSize
            );
        }

        initializeBoard();
        boolean solved = findKnightTour(startRow, startCol);

        if (solved) {
            // Return a copy of the usable board portion
            int[][] result = new int[USABLE_BOARD_SIZE][USABLE_BOARD_SIZE];
            for (int i = 0; i < USABLE_BOARD_SIZE; i++) {
                for (int j = 0; j < USABLE_BOARD_SIZE; j++) {
                    result[i][j] = chessBoard[i + BUFFER_SIZE][j + BUFFER_SIZE];
                }
            }
            return result;
        }

        return null;
    }
}

/*
COMPREHENSIVE DOCUMENTATION
===========================

KNIGHT'S TOUR PROBLEM
---------------------

Problem Definition:
==================
A knight's tour is a sequence of moves of a knight on a chessboard such that the knight
visits every square exactly once. A tour is called "closed" if the knight can return to
the starting square from the last square; otherwise, it's called "open" or "linear".

History:
========
The problem has been studied since the 9th century AD in Indian mathematics.
It's a special case of the Hamiltonian path problem in graph theory.

WHY USE WARNSDORFF'S HEURISTIC?
===============================

Warnsdorff's Rule (1823):
------------------------
Always move the knight to the square with the fewest onward moves (lowest degree).

Benefits:
---------
1. Dramatically reduces search space
2. Produces a solution quickly (often in O(N^2) time)
3. Works for most board sizes (5x5 and larger)

Without Warnsdorff's Rule:
-------------------------
- Exponential backtracking O(8^(N^2)) - impossible for N=8
- Would need to try 8^64 ≈ 6.2 × 10^57 possibilities

VISUALIZATION OF LEGAL KNIGHT MOVES
===================================

Knight's L-shaped movement:
        +-------+-------+-------+
        |   -2  |   -1  |   0   |   +1  |   +2  |
+-------+-------+-------+-------+-------+-------+
|  -2   |       |   ●   |       |   ●   |       |
+-------+-------+-------+-------+-------+-------+
|  -1   |   ●   |       |       |       |   ●   |
+-------+-------+-------+-------+-------+-------+
|   0   |       |       |   K   |       |       |
+-------+-------+-------+-------+-------+-------+
|  +1   |   ●   |       |       |       |   ●   |
+-------+-------+-------+-------+-------+-------+
|  +2   |       |   ●   |       |   ●   |       |
+-------+-------+-------+-------+-------+-------+

K = Knight's current position
● = Possible move destinations (8 total)

BOARD REPRESENTATION
===================

Buffer Implementation:
---------------------
Instead of checking boundaries at every move, we add 2 buffer rows/columns:

+-------------------------+
|  B  B  B  B  B  B  B  B |  (Boundary cells: -1)
|  B  B  B  B  B  B  B  B |
|  B  .  .  .  .  .  .  B |
|  B  .  .  .  .  .  .  B |  (Usable 8x8 board: 0 initially, then move numbers)
|  B  .  .  .  .  .  .  B |
|  B  .  .  .  .  .  .  B |
|  B  .  .  .  .  .  .  B |
|  B  .  .  .  .  .  .  B |
|  B  .  .  .  .  .  .  B |
|  B  .  .  .  .  .  .  B |
|  B  B  B  B  B  B  B  B |
|  B  B  B  B  B  B  B  B |
+-------------------------+

B = Boundary marker (-1)
. = Unvisited cell (0)

MOVE PRIORITIZATION WITH WARNSDORFF
===================================

Example: At position (4,4) on 8x8 board:

Calculate onward moves for each possible destination:
- Move to (3,2): has 5 onward moves
- Move to (5,2): has 3 onward moves
- Move to (6,3): has 2 onward moves ★ Choose this first
- Move to (6,5): has 4 onward moves
- Move to (5,6): has 3 onward moves
- Move to (3,6): has 5 onward moves
- Move to (2,5): has 4 onward moves
- Move to (2,3): has 4 onward moves

Sort by onward move count ascending: 2, 3, 3, 4, 4, 4, 5, 5

PERFORMANCE ANALYSIS
===================

| Board Size | Without Heuristic | With Warnsdorff | Solution Exists? |
|------------|-------------------|-----------------|------------------|
| 1x1 | 1 operation | 1 operation | Yes (trivial) |
| 2x2 | 8 operations | 8 operations | No |
| 3x3 | 8^9 ≈ 134M | ~10K | No |
| 5x5 | 8^25 ≈ 2^75 | ~100K | Yes |
| 8x8 | Impossible | 14 years? | Yes (many) |

With Warnsdorff's heuristic, the 8x8 knight's tour typically completes in milliseconds.

RECURSION DEPTH
===============

Maximum recursion depth = total cells = 64 for 8x8 board

Java stack limit ~ 1000-10000:
- 8x8: 64 depth ✓ Safe
- 50x50: 2500 depth → Max stack size error
- For larger boards, implement iterative version with explicit stack

ORPHAN DETECTION
================

What is an orphan?
-----------------
A cell that would become unreachable after making a move because:
1. It has no unvisited neighbor cells
2. But not all cells have been visited yet

Why detect orphans?
------------------
If a move creates an orphan, that path cannot lead to a complete tour.
Early detection improves performance significantly.

Example of orphan creation (simplified):
[2] [ ] [1]  → Starting from position 1, if we move to 2, the remaining
[ ] [K] [ ]     empty cell marked [ ] becomes isolated (an orphan)
[ ] [ ] [ ]

SOLUTION COUNT
==============

Number of possible knight's tours (closed) on chessboard:
- 1x1: 1
- 5x5: 1,728
- 6x6: 6,637,920
- 8x8: 26,534,728,821,064 (approximately 2.65 × 10^13)

Open tours (not returning to start) are even more numerous.

RELATED PROBLEMS
================

1. Hamiltonian Path Problem
2. King's Tour (different movement rules)
3. Rook's Tour (visited every square exactly once)
4. Queen's Tour
5. Magic Knight's Tour (tour with magic square properties)

PRACTICAL APPLICATIONS
======================

1. Computational Mathematics:
   - Graph theory research
   - Hamiltonicity testing

2. Maze Generation:
   - Creating interesting, well-connected paths

3. Robotics:
   - Path planning in grid-based environments
   - CNC machine tool path optimization

4. PCB Design:
   - Router path optimization
   - Via hole drilling sequences

5. Encryption:
   - Generating pseudorandom sequences
   - Creating lookup tables for ciphers

6. Game Development:
   - Puzzle generation
   - NPC movement patterns

SAMPLE USAGE
===========

public static void main(String[] args) {
    // Initialize the board
    KnightsTour.initializeBoard();

    // Start from position (1,1) on a standard 8x8 board (converted to buffer coordinates)
    // The usable board coordinates are from 0 to 7 (rows and columns)
    if (KnightsTour.findKnightTour(0, 0)) {
        KnightsTour.printBoard();
        System.out.println("Knight's tour completed successfully!");
    } else {
        System.out.println("No solution exists for this starting position.");
    }

    // Or use the convenience method:
    int[][] solvedBoard = KnightsTour.solveKnightsTour(8, 0, 0);
    if (solvedBoard != null) {
        System.out.println("Solution found!");
    }
}

FURTHER READING
===============

1. "Knight's Tours on 8x8 Board" by H. C. von Warnsdorff (1823)
2. "The Knight's Tour" by Lewis Carroll (Mathematical recreations)
3. "Graph Theory and Its Applications" by Jonathan L. Gross
4. "The Art of Computer Programming" by Donald Knuth (Section 7.2.2.2)
*/

