/**
 * The Autokey Cipher is an interesting and historically significant encryption method,
 * as it improves upon the classic Vigenère Cipher by using the plaintext itself to
 * extend the key. This makes it harder to break using frequency analysis, as it
 * doesn’t rely solely on a repeated key.
 * https://en.wikipedia.org/wiki/Autokey_cipher
 *
 * @author bennybebo
 */
public class Autokey {

    // Encrypts the plaintext using the Autokey cipher
    public String encrypt(String plaintext, String keyword) {
        plaintext = plaintext.toUpperCase().replaceAll("[^A-Z]", ""); // Sanitize input
        keyword = keyword.toUpperCase();

        StringBuilder extendedKey = new StringBuilder(keyword);
        extendedKey.append(plaintext); // Extend key with plaintext

        StringBuilder ciphertext = new StringBuilder();

        for (int i = 0; i < plaintext.length(); i++) {
            char plainChar = plaintext.charAt(i);
            char keyChar = extendedKey.charAt(i);

            int encryptedChar = (plainChar - 'A' + keyChar - 'A') % 26 + 'A';
            ciphertext.append((char) encryptedChar);
        }

        return ciphertext.toString();
    }

    // Decrypts the ciphertext using the Autokey cipher
    public String decrypt(String ciphertext, String keyword) {
        ciphertext = ciphertext.toUpperCase().replaceAll("[^A-Z]", ""); // Sanitize input
        keyword = keyword.toUpperCase();

        StringBuilder plaintext = new StringBuilder();
        StringBuilder extendedKey = new StringBuilder(keyword);

        for (int i = 0; i < ciphertext.length(); i++) {
            char cipherChar = ciphertext.charAt(i);
            char keyChar = extendedKey.charAt(i);

            int decryptedChar = (cipherChar - 'A' - (keyChar - 'A') + 26) % 26 + 'A';
            plaintext.append((char) decryptedChar);

            extendedKey.append((char) decryptedChar); // Extend key with each decrypted char
        }

        return plaintext.toString();
    }
}

public class HazineAvcisi {
    private static final int TAHTA_BOYUTU = 10;

    private int definenSatiri;
    private int definenSutunu;
    private final JButton[][] hucreler;
    private final JFrame pencere;

    private int gezginSatiri = 0;
    private int gezginSutunu = 0;
    private int sonOlculenMesafe;

    public HazineAvcisi() {
        Random rng = new Random();
        definenSatiri = rng.nextInt(TAHTA_BOYUTU);
        definenSutunu = rng.nextInt(TAHTA_BOYUTU);

        sonOlculenMesafe = mesafeHesapla(definenSatiri, definenSutunu, gezginSatiri, gezginSutunu);

        pencere = new JFrame("Hazine Avcisi");
        pencere.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        pencere.setSize(500, 500);
        pencere.setLayout(new GridLayout(TAHTA_BOYUTU, TAHTA_BOYUTU));

        hucreler = new JButton[TAHTA_BOYUTU][TAHTA_BOYUTU];
        for (int satir = 0; satir < TAHTA_BOYUTU; satir++) {
            for (int sutun = 0; sutun < TAHTA_BOYUTU; sutun++) {
                JButton hucre = new JButton();
                hucre.setBackground(Color.LIGHT_GRAY);
                hucre.setFont(new Font("Arial", Font.BOLD, 16));
                hucreler[satir][sutun] = hucre;
                pencere.add(hucre);
            }
        }

        hucreler[gezginSatiri][gezginSutunu].setBackground(Color.YELLOW);
        hucreler[gezginSatiri][gezginSutunu].setText("🚶");

        pencere.addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent olay) {
                gezginiTasi(olay.getKeyCode());
            }
        });

        pencere.setFocusable(true);
        pencere.setVisible(true);
    }

    private static int mesafeHesapla(int satirA, int sutunA, int satirB, int sutunB) {
        return Math.abs(satirA - satirB) + Math.abs(sutunA - sutunB);
    }

    // Yon tusuna gore gezgini hareket ettirir ve durumu gunceller
    private void gezginiTasi(int tusKodu) {
        int hedefSatir = gezginSatiri;
        int hedefSutun = gezginSutunu;

        if (tusKodu == KeyEvent.VK_UP && gezginSatiri > 0) {
            hedefSatir = gezginSatiri - 1;
        } else if (tusKodu == KeyEvent.VK_DOWN && gezginSatiri < TAHTA_BOYUTU - 1) {
            hedefSatir = gezginSatiri + 1;
        } else if (tusKodu == KeyEvent.VK_LEFT && gezginSutunu > 0) {
            hedefSutun = gezginSutunu - 1;
        } else if (tusKodu == KeyEvent.VK_RIGHT && gezginSutunu < TAHTA_BOYUTU - 1) {
            hedefSutun = gezginSutunu + 1;
        }

        if (hedefSatir == gezginSatiri && hedefSutun == gezginSutunu) {
            return;
        }

        int yeniMesafe = mesafeHesapla(definenSatiri, definenSutunu, hedefSatir, hedefSutun);

        hucreler[gezginSatiri][gezginSutunu].setBackground(Color.LIGHT_GRAY);
        hucreler[gezginSatiri][gezginSutunu].setText("");

        gezginSatiri = hedefSatir;
        gezginSutunu = hedefSutun;
        hucreler[gezginSatiri][gezginSutunu].setBackground(Color.YELLOW);
        hucreler[gezginSatiri][gezginSutunu].setText("🚶");

        if (gezginSatiri == definenSatiri && gezginSutunu == definenSutunu) {
            hucreler[gezginSatiri][gezginSutunu].setBackground(Color.GREEN);
            hucreler[gezginSatiri][gezginSutunu].setText("💎");
            JOptionPane.showMessageDialog(pencere, "Tebrikler! Hazineyi buldunuz!");
            turuSifirla();
            return;
        }

        if (yeniMesafe > sonOlculenMesafe) {
            JOptionPane.showMessageDialog(pencere, "Yanlis yondesiniz!");
        } else {
            JOptionPane.showMessageDialog(pencere, "Hazineye yaklasiyorsunuz!");
        }

        sonOlculenMesafe = yeniMesafe;
    }

    // Yeni bir tur icin tahtayi ve konumlari sifirlar
    private void turuSifirla() {
        Random rng = new Random();
        definenSatiri = rng.nextInt(TAHTA_BOYUTU);
        definenSutunu = rng.nextInt(TAHTA_BOYUTU);

        gezginSatiri = 0;
        gezginSutunu = 0;
        sonOlculenMesafe = mesafeHesapla(definenSatiri, definenSutunu, gezginSatiri, gezginSutunu);

        for (int satir = 0; satir < TAHTA_BOYUTU; satir++) {
            for (int sutun = 0; sutun < TAHTA_BOYUTU; sutun++) {
                hucreler[satir][sutun].setText("");
                hucreler[satir][sutun].setBackground(Color.LIGHT_GRAY);
            }
        }

        hucreler[gezginSatiri][gezginSutunu].setBackground(Color.YELLOW);
        hucreler[gezginSatiri][gezginSutunu].setText("🚶");
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(HazineAvcisi::new);
    }
}

/**
 * A triangle composed of three MyPoint vertices.
 */
class MyPoint {

    private int x;
    private int y;

    public MyPoint() {
    }

    public MyPoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int[] getXY() {
        return new int[]{x, y};
    }

    public void setXY(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public double distance(int x, int y) {
        return Math.sqrt(Math.pow(x - this.x, 2) + Math.pow(y - this.y, 2));
    }

    public double distance(MyPoint another) {
        return Math.sqrt(Math.pow(another.x - x, 2) + Math.pow(another.y - y, 2));
    }

    public double distance() {
        return Math.sqrt(Math.pow(-x, 2) + Math.pow(-y, 2));
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ')';
    }
}

public class MyTriangle {
    private MyPoint v1;
    private MyPoint v2;
    private MyPoint v3;

    public MyTriangle(int x1, int y1, int x2, int y2, int x3, int y3) {
        this.v1 = new MyPoint(x1, y1);
        this.v2 = new MyPoint(x2, y2);
        this.v3 = new MyPoint(x3, y3);
    }

    public MyTriangle(MyPoint v1, MyPoint v2, MyPoint v3) {
        this.v1 = v1;
        this.v2 = v2;
        this.v3 = v3;
    }

    public MyPoint getV1() {
        return v1;
    }

    public void setV1(MyPoint v1) {
        this.v1 = v1;
    }

    public MyPoint getV2() {
        return v2;
    }

    public void setV2(MyPoint v2) {
        this.v2 = v2;
    }

    public MyPoint getV3() {
        return v3;
    }

    public void setV3(MyPoint v3) {
        this.v3 = v3;
    }

    public double getPerimeter() {
        return v1.distance(v2) + v2.distance(v3) + v3.distance(v1);
    }

    public String getType() {
        double side12 = v1.distance(v2);
        double side23 = v2.distance(v3);
        double side31 = v3.distance(v1);
        if (side12 == side23 && side12 == side31) {
            return "Equilateral";
        } else if (side12 == side23 || side12 == side31 || side31 == side23) {
            return "Isosceles";
        } else {
            return "Scalene";
        }
    }

    @Override
    public String toString() {
        return "MyTriangle[v1=" + v1.toString() + ",v2=" + v2.toString() + ",v3=" + v3.toString() + ']';
    }
}

class TestMyTriangle {
    public static void main(String[] args) {
        MyTriangle myTriangle = new MyTriangle(new MyPoint(5, 5), new MyPoint(15, 15), new MyPoint(5, 25));
        System.out.println(myTriangle.getPerimeter());
        System.out.println(myTriangle.getType());
        System.out.println(myTriangle.getV1());
        System.out.println(myTriangle.getV2());
        System.out.println(myTriangle.getV3());
        System.out.println(myTriangle.toString());
    }
}

package sqlite; 
import java.sql.*;
import java.util.Random;
import java.util.Scanner;

/* 
 * Bu kod, bir SQLite veritabanini baslatir ve oyuncu, puan ve basarilarini saklamak icin bir tablo olusturur. 
 * Ardindan tabloya yeni rastgele bir kayit ekler, kullanicidan veri alir ve en yuksek puana sahip 10 oyuncuyu listeler.
 * 
 * */

public class GameResults {

    private static final String DB_URL = "jdbc:sqlite:game.db"; // Veritabani URL'si
    private static final String CREATE_TABLE_SQL = "CREATE TABLE IF NOT EXISTS scores (name TEXT, score INTEGER, achievement TEXT)"; // Tablo olusturma SQL sorgusu
    private static final String INSERT_SCORE_SQL = "INSERT INTO scores (name, score, achievement) VALUES (?, ?, ?)"; // Yeni puan ve basari ekleme SQL sorgusu
    private static final String SELECT_HIGH_SCORES_SQL = "SELECT * FROM scores ORDER BY score DESC LIMIT ?"; // Yuksek puanlari sorgulama SQL sorgusu
    private static Random random = new Random(); // Rastgele sayi uretici
    private static Scanner scanner = new Scanner(System.in); // Kullanici girdi alici

    public static void main(String[] args) {
        // Veritabanini baslat ve 'scores' tablosunu olustur
        try (Connection conn = DriverManager.getConnection(DB_URL); // Veritabanina baglan
        		Statement stmt = conn.createStatement()) { // SQL komutlari calistirmak icin statement olustur
            stmt.execute(CREATE_TABLE_SQL); // Tabloyu olustur
        } catch (SQLException e) {
            e.printStackTrace(); // Hata olursa yazdir
        }

        // Veritabanina rastgele oyuncu adi, puan ve basari ekle
        for (int i = 0; i < 5; i++) { // 5 oyuncu icin rastgele puanlar ve basarilar ekle
            try (Connection conn = DriverManager.getConnection(DB_URL); // Veritabanina baglan
            		PreparedStatement pstmt = conn.prepareStatement(INSERT_SCORE_SQL)) { // SQL komutunu hazirla
                String name = "player" + (i + 1); // Oyuncu adi ("player1", "player2", ...)
                int score = random.nextInt(100); // Rastgele bir puan (0-99 arasinda)
                String achievement = getRandomAchievement(); // Rastgele bir basari al
                pstmt.setString(1, name); // Oyuncunun adini ayarla
                pstmt.setInt(2, score); // Puani ayarla
                pstmt.setString(3, achievement); // Basariyi ayarla
                pstmt.executeUpdate(); // Veriyi ekle
                System.out.println("Yeni kayit eklendi: " + name + " - Puan: " + score + " - Basari: " + achievement); // Eklenen veriyi yazdir
            } catch (SQLException e) {
                e.printStackTrace(); // Hata olursa yazdir
            }
        }

        // Kullanici yeni oyuncu eklemek isterse
        System.out.print("Yeni oyuncu eklemek ister misiniz? (E/H): ");
        String choice = scanner.nextLine();
        if (choice.equalsIgnoreCase("E")) {
            System.out.print("Oyuncu ismi girin: ");
            String name = scanner.nextLine();
            System.out.print("Puan girin: ");
            int score = scanner.nextInt();
            scanner.nextLine(); // Bosluk karakterini temizle
            String achievement = getRandomAchievement(); // Rastgele basari ekle

            try (Connection conn = DriverManager.getConnection(DB_URL); // Veritabanina baglan
            		PreparedStatement pstmt = conn.prepareStatement(INSERT_SCORE_SQL)) { // SQL komutunu hazirla
                pstmt.setString(1, name); // Oyuncu adi
                pstmt.setInt(2, score); // Puan
                pstmt.setString(3, achievement); // Basari
                pstmt.executeUpdate(); // Veriyi ekle
                System.out.println("Yeni oyuncu eklendi: " + name + " - Puan: " + score + " - Basari: " + achievement);
            } catch (SQLException e) {
                e.printStackTrace(); // Hata olursa yazdir
            }
        }

        // Veritabanindan en yuksek puanli 10 kayidi al
        try (Connection conn = DriverManager.getConnection(DB_URL); // Veritabanina baglan
        		PreparedStatement pstmt = conn.prepareStatement(SELECT_HIGH_SCORES_SQL)) { // SQL komutunu hazirla
            pstmt.setInt(1, 10); // Sadece 10 kayit al
            ResultSet rs = pstmt.executeQuery(); // Sonuclari al
            System.out.println("\nEn yuksek 10 puan: ");
            while (rs.next()) { // Sonuclar uzerinde don
                String name = rs.getString("name"); // Oyuncunun adini al
                int score = rs.getInt("score"); // Puani al
                String achievement = rs.getString("achievement"); // Basariyi al
                System.out.println(name + ": " + score + " - Basari: " + achievement); // Puan ve basariyi ekrana yazdir
            }
        } catch (SQLException e) {
            e.printStackTrace(); // Hata olursa yazdir
        }
    }

    // Rastgele bir basari mesaji
    private static String getRandomAchievement() {
        String[] achievements = {
            "Yeni Baslayan",
            "Buyuk Zafer",
            "Efsane Oyuncu",
            "Hizli Dusunen",
            "Oyun Ustasi"
        };
        return achievements[random.nextInt(achievements.length)]; // Rastgele bir basari sec
    }
}

/** Basit bir 4x4 dugme duzenli GUI hesap makinesi. */
public class HesapMakinesi extends JFrame {

    private static final long serialVersionUID = 1L;

    private final JTextField ekran;
    private String aktifOperator = "";
    private double kayitliDeger = 0;
    private boolean yeniGirisBekleniyor = false;

    private static final String[] TUS_DIZILIMI = {
            "7", "8", "9", "/",
            "4", "5", "6", "x",
            "1", "2", "3", "-",
            "0", "AC", "=", "+"
    };

    public HesapMakinesi() {
        setTitle("Hesap Makinesi");
        setSize(300, 400);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        ekran = new JTextField();
        ekran.setEditable(false);
        ekran.setFont(new Font("Arial", Font.PLAIN, 24));
        ekran.setPreferredSize(new Dimension(0, 50));
        add(ekran, BorderLayout.NORTH);

        JPanel tusTakimi = new JPanel(new GridLayout(4, 4));
        TusDinleyicisi dinleyici = new TusDinleyicisi();
        for (String etiket : TUS_DIZILIMI) {
            JButton tus = new JButton(etiket);
            tus.addActionListener(dinleyici);
            tusTakimi.add(tus);
        }

        add(tusTakimi, BorderLayout.CENTER);
    }

    /** Rakam, operator, esittir ve temizle tuslarina tepki verir. */
    private class TusDinleyicisi implements ActionListener {

        @Override
        public void actionPerformed(ActionEvent e) {
            String basilan = e.getActionCommand();

            if (basilan.matches("[0-9]")) {
                rakamGirildi(basilan);
            } else if (basilan.equals("AC")) {
                ekran.setText("");
            } else if (basilan.matches("[+\\-x/]")) {
                operatorSecildi(basilan);
            } else if (basilan.equals("=")) {
                sonucuHesaplaVeGoster();
            }
        }

        private void rakamGirildi(String rakam) {
            if (yeniGirisBekleniyor) {
                ekran.setText("");
                yeniGirisBekleniyor = false;
            }
            ekran.setText(ekran.getText() + rakam);
        }

        private void operatorSecildi(String operator) {
            aktifOperator = operator;
            kayitliDeger = Double.parseDouble(ekran.getText());
            yeniGirisBekleniyor = true;
        }

        private void sonucuHesaplaVeGoster() {
            double girilenIkinciDeger = Double.parseDouble(ekran.getText());
            double sonuc = 0;

            switch (aktifOperator) {
                case "+":
                    sonuc = kayitliDeger + girilenIkinciDeger;
                    break;
                case "-":
                    sonuc = kayitliDeger - girilenIkinciDeger;
                    break;
                case "x":
                    sonuc = kayitliDeger * girilenIkinciDeger;
                    break;
                case "/":
                    sonuc = kayitliDeger / girilenIkinciDeger;
                    break;
                default:
                    break;
            }

            ekran.setText(String.valueOf(sonuc));
            yeniGirisBekleniyor = true;
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            HesapMakinesi uygulama = new HesapMakinesi();
            uygulama.setVisible(true);
        });
    }
}

package com.thealgorithms.conversions;

/**
 * A utility class for converting numbers from any base to any other base.
 *
 * This class provides a method to convert a source number from a given base
 * to a destination number in another base. Valid bases range from 2 to 10.
 */
public final class AnytoAny {
private AnytoAny() {
}

/**
 * Converts a number from a source base to a destination base.
 *
 * @param sourceValue The number in the source base (as an integer).
 * @param sourceBase The base of the source number (between 2 and 10).
 * @param targetBase The base to which the number should be converted (between 2 and 10).
 * @throws IllegalArgumentException if the bases are not between 2 and 10.
 * @return The converted number in the destination base (as an integer).
 */
public static int convertBase(int sourceValue, int sourceBase, int targetBase) {
if (sourceBase < 2 || sourceBase > 10 || targetBase < 2 || targetBase > 10) {
throw new IllegalArgumentException("Bases must be between 2 and 10.");
}
int decimalEquivalent = toDecimal(sourceValue, sourceBase);
return fromDecimal(decimalEquivalent, targetBase);
}

/**
 * Converts a number from a given base to its decimal representation (base 10).
 *
 * @param sourceNumber The number in the original base.
 * @param originalBase The base of the given number.
 * @return The decimal representation of the number.
 */
private static int toDecimal(int sourceNumber, int originalBase) {
int decimalResult = 0;
int positionMultiplier = 1;
int tempNumber = sourceNumber;
while (tempNumber != 0) {
decimalResult += (tempNumber % 10) * positionMultiplier;
positionMultiplier *= originalBase;
tempNumber /= 10;
}
return decimalResult;
}

/**
 * Converts a decimal (base 10) number to a specified base.
 *
 * @param decimalValue The decimal number to convert.
 * @param destinationBase The destination base for conversion.
 * @return The number in the specified base.
 */
private static int fromDecimal(int decimalValue, int destinationBase) {
int convertedResult = 0;
int positionMultiplier = 1;
int tempDecimal = decimalValue;
while (tempDecimal != 0) {
convertedResult += (tempDecimal % destinationBase) * positionMultiplier;
positionMultiplier *= 10;
tempDecimal /= destinationBase;
}
return convertedResult;
}
}

