/**
 * Java program that implements Tarjan's Algorithm to find Strongly Connected Components (SCCs) in a directed graph.
 *
 * <p>
 * Tarjan's algorithm is a linear time algorithm (O(V + E)) that identifies the SCCs of a directed graph.
 * An SCC is a maximal subgraph where every vertex is reachable from every other vertex within the subgraph.
 *
 * <h3>Algorithm Overview:</h3>
 * <ul>
 * <li>DFS Search: A depth-first search (DFS) is performed on the graph to generate a DFS tree.</li>
 * <li>Identification of SCCs: SCCs correspond to subtrees within this DFS tree.</li>
 * <li>Low-Link Values: For each node, a low-link value is maintained, which indicates the earliest visited
 * vertex (the one with the minimum insertion time) that can be reached from that subtree.</li>
 * <li>Stack Usage: Nodes are stored in a stack during DFS. When an SCC is identified, nodes are popped from
 * the stack until the head of the SCC is reached.</li>
 * </ul>
 *
 * <p>
 * Example of a directed graph:
 * <pre>
 *  0 --------> 1 -------> 3 --------> 4
 *  ^          /
 *  |         /
 *  |        /
 *  |       /
 *  |      /
 *  |     /
 *  |    /
 *  |   /
 *  |  /
 *  | /
 *  V
 *  2
 * </pre>
 *
 * <p>
 * For the above graph, the SCC list is as follows:
 * <ul>
 * <li>1, 2, 0</li>
 * <li>3</li>
 * <li>4</li>
 * </ul>
 * The order of nodes in an SCC does not matter as they form cycles.
 *
 * <h3>Comparison with Kosaraju's Algorithm:</h3>
 * <p>
 * Kosaraju's algorithm also identifies SCCs but does so using two DFS traversals.
 * In contrast, Tarjan's algorithm achieves this in a single DFS traversal, leading to improved performance
 * in terms of constant factors.
 * </p>
 */
public class TarjansAlgorithm {

private int currentTime;
private final List<List<Integer>> sccComponents = new ArrayList<>();

/**
 * Finds and returns the strongly connected components (SCCs) of the directed graph.
 *
 * @param totalVertices the number of vertices in the graph
 * @param adjacencyList the adjacency list representation of the graph
 * @return a list of lists, where each inner list represents a strongly connected component
 */
public List<List<Integer>> findSCCs(int totalVertices, List<List<Integer>> adjacencyList) {
int[] lowLinkValues = new int[totalVertices];
int[] discoveryTimes = new int[totalVertices];
for (int vertexIndex = 0; vertexIndex < totalVertices; vertexIndex++) {
discoveryTimes[vertexIndex] = -1;
lowLinkValues[vertexIndex] = -1;
}
boolean[] onStackFlag = new boolean[totalVertices];
Stack<Integer> dfsStack = new Stack<>();
for (int vertexIndex = 0; vertexIndex < totalVertices; vertexIndex++) {
if (discoveryTimes[vertexIndex] == -1) {
performDFS(vertexIndex, lowLinkValues, discoveryTimes, onStackFlag, dfsStack, adjacencyList);
}
}
return sccComponents;
}

private void performDFS(int currentNode, int[] lowLinkValues, int[] discoveryTimes, boolean[] onStackFlag, Stack<Integer> dfsStack, List<List<Integer>> adjacencyList) {
discoveryTimes[currentNode] = currentTime;
lowLinkValues[currentNode] = currentTime;
currentTime++;
onStackFlag[currentNode] = true;
dfsStack.push(currentNode);
for (Integer neighborNode : adjacencyList.get(currentNode)) {
if (discoveryTimes[neighborNode] == -1) {
performDFS(neighborNode, lowLinkValues, discoveryTimes, onStackFlag, dfsStack, adjacencyList);
lowLinkValues[currentNode] = Math.min(lowLinkValues[currentNode], lowLinkValues[neighborNode]);
} else if (onStackFlag[neighborNode]) {
lowLinkValues[currentNode] = Math.min(lowLinkValues[currentNode], discoveryTimes[neighborNode]);
}
}
if (lowLinkValues[currentNode] == discoveryTimes[currentNode]) {
int poppedNode;
List<Integer> currentComponent = new ArrayList<>();
do {
poppedNode = dfsStack.pop();
currentComponent.add(poppedNode);
onStackFlag[poppedNode] = false;
} while (poppedNode != currentNode);
sccComponents.add(currentComponent);
}
}
}
