public class LambdaFunctions {
    public static void main(String[] args) {
        // Lambda expressions provide a concise way to implement functional interfaces
        // They represent anonymous functions (one-line / inline functions)

        ArrayList<Integer> numberList = new ArrayList<>();
        for (int iterationCount = 1; iterationCount <= 5; iterationCount++) {
            numberList.add(iterationCount);
        }

        // Using Consumer functional interface with lambda (commented alternative)
        // numberList.forEach((eachItem) -> System.out.println(eachItem * 2));

        // Consumer takes one argument and returns no result
        Consumer<Integer> multiplyAndPrint = (eachItem) -> System.out.println("Value * 2 = " + eachItem * 2);
        numberList.forEach(multiplyAndPrint);

        // Defining different arithmetic operations using lambda expressions
        Operation additionOperation = (firstNumber, secondNumber) -> firstNumber + secondNumber;
        Operation multiplicationOperation = (firstNumber, secondNumber) -> firstNumber * secondNumber;
        Operation subtractionOperation = (firstNumber, secondNumber) -> firstNumber - secondNumber;

        LambdaFunctions lambdaCalculator = new LambdaFunctions();

        System.out.println("\n--- Arithmetic Operation Results ---");
        System.out.println("Addition (5 + 3): " + lambdaCalculator.performOperation(5, 3, additionOperation));
        System.out.println("Multiplication (5 * 3): " + lambdaCalculator.performOperation(5, 3, multiplicationOperation));
        System.out.println("Subtraction (5 - 3): " + lambdaCalculator.performOperation(5, 3, subtractionOperation));
    }

    private int performOperation(int operandOne, int operandTwo, Operation arithmeticOperation) {
        return arithmeticOperation.execute(operandOne, operandTwo);
    }
}

// Functional interface with a single abstract method
interface Operation {
    int execute(int firstOperand, int secondOperand);
}

package array;
import java.util.Arrays;

public class UcuncuEnBuyukBulucu {

	// Diziyi artan siraya gore sirala ve ucuncu en buyugu bul
	public static int ucuncuEnBuyuguBul(int[] dizi) {

		// Diziyi artan siraya gore sirala
		Arrays.sort(dizi);
		// Ucuncu en buyuk elemani dondur
		return dizi[dizi.length - 3];
	}

	// Diziyi teker teker kontrol ederek ucuncu en buyugu bul
	public static int ucuncuEnBuyuguBulVanilla(int[] dizi) {
		// En buyuk, ikinci en buyuk ve ucuncu en buyuk degerleri icin degiskenler olustur
		int birinciEnBuyuk = Integer.MIN_VALUE;
		int ikinciEnBuyuk = Integer.MIN_VALUE;
		int ucuncuEnBuyuk = Integer.MIN_VALUE;

		// Diziyi dolasarak en buyuk degerleri guncelle
		for (int eleman : dizi) {
			if (eleman > birinciEnBuyuk) {
				ucuncuEnBuyuk = ikinciEnBuyuk;
				ikinciEnBuyuk = birinciEnBuyuk;
				birinciEnBuyuk = eleman;
			} else if (eleman > ikinciEnBuyuk) {
				ucuncuEnBuyuk = ikinciEnBuyuk;
				ikinciEnBuyuk = eleman;
			} else if (eleman > ucuncuEnBuyuk) {
				ucuncuEnBuyuk = eleman;
			}
		}
		// Ucuncu en buyuk degeri dondur
		return ucuncuEnBuyuk;
	}

	public static void main(String[] args) {

		int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

		System.out.println(Arrays.toString(dizi));
		// Ucuncu en buyugu bul ve yazdir
		int ucuncuEnBuyuk = ucuncuEnBuyuguBul(dizi);
		System.out.println("3. buyuk sayi: " + ucuncuEnBuyuk);

		System.out.println(Arrays.toString(dizi));
		// Vanilla yontemiyle ucuncu en buyugu bul ve yazdir
		ucuncuEnBuyuk = ucuncuEnBuyuguBulVanilla(dizi);
		System.out.println("3. buyuk sayi: " + ucuncuEnBuyuk);
	}
}

package array;
import java.util.Scanner;

public class DogrusalArama {

    void dogrusalArama(int[] dizi, int aranan) {
        // Aranan deger icin bayrak tanimla
        boolean bulundu = false;

        // Dizideki her elemani kontrol et
        for (int i = 0; i < dizi.length; i++) {
            if (dizi[i] == aranan) {
                // Aranan deger bulunursa
                bulundu = true;
                System.out.println("Aranan oge bulundu: Indis " + i);
                break;
            }
        }

        // Aranan deger bulunamazsa
        if (bulundu == false) {
            System.out.println("Aranan oge bulunamadi");
        }
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);

        // Ornek bir dizi olustur
        int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        System.out.print("Aranacak degeri girin: ");
        int aranan = tarayici.nextInt();

        DogrusalArama arayici = new DogrusalArama();
        arayici.dogrusalArama(dizi, aranan);

        tarayici.close();
    }
}

import java.util.Scanner;

public class LeapYearChecker {
    public static boolean isLeapYear(int year) {
        // A year is leap if divisible by 4, except centuries
        // that are not divisible by 400
        return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a year: ");
        int year = scanner.nextInt();

        if (isLeapYear(year)) {
            System.out.println(year + " is a leap year");
        } else {
            System.out.println(year + " is not a leap year");
        }
        scanner.close();
    }
}

/**
 * Utility class for converting a hexadecimal string to its decimal representation.
 * <p>
 * A hexadecimal number uses the base-16 numeral system, with the following characters:
 * <ul>
 *   <li>Digits: 0-9</li>
 *   <li>Letters: A-F (case-insensitive)</li>
 * </ul>
 * Each character represents a power of 16. For example:
 * <pre>
 *   Hexadecimal "A1" = 10*16^1 + 1*16^0 = 161 (decimal)
 * </pre>
 *
 * <p>This class provides a method to perform the conversion without using built-in Java utilities.</p>
 */
public final class HexaDecimalToDecimal {
    private HexaDecimalToDecimal() {
    }

    /**
     * Converts a hexadecimal string to its decimal integer equivalent.
     * <p>The input string is case-insensitive, and must contain valid hexadecimal characters [0-9, A-F].</p>
     *
     * @param hex the hexadecimal string to convert
     * @return the decimal integer representation of the input hexadecimal string
     * @throws IllegalArgumentException if the input string contains invalid characters
     */
    public static int getHexaToDec(String hex) {
        String digits = "0123456789ABCDEF";
        hex = hex.toUpperCase();
        int val = 0;

        for (int i = 0; i < hex.length(); i++) {
            int d = digits.indexOf(hex.charAt(i));
            if (d == -1) {
                throw new IllegalArgumentException("Invalid hexadecimal character: " + hex.charAt(i));
            }
            val = 16 * val + d;
        }

        return val;
    }
}

