package com.thealgorithms.compression;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

/**
 * Huffman Coding Compression Algorithm Implementation.
 * <p>
 * Huffman Coding is a popular greedy algorithm used for lossless data compression.
 * It reduces the overall size of data by assigning variable-length, prefix-free
 * binary codes to input characters, ensuring that more frequent characters receive
 * the shortest possible codes.
 * </p>
 * <p>
 * <strong>Key Features:</strong>
 * <ul>
 * <li>Uses a PriorityQueue (min-heap) to efficiently construct the optimal prefix tree.</li>
 * <li>Fail-fast design throws exceptions for unsupported characters and malformed binary payloads.</li>
 * <li>Immutable internal dictionary state prevents external tampering with generated codes.</li>
 * <li>Robust handling of edge cases, including single-character strings and incomplete sequences.</li>
 * </ul>
 * </p>
 * @author Chahat Sandhu, <a href="https://github.com/singhc7">singhc7</a>
 * @see <a href="https://en.wikipedia.org/wiki/Huffman_coding">Huffman Coding (Wikipedia)</a>
 */
public class HuffmanCoding {

private TreeNode rootNode;
private final Map<Character, String> encodingTable;

private static class TreeNode implements Comparable<TreeNode> {
final char characterValue;
final int frequencyCount;
final TreeNode leftChild;
final TreeNode rightChild;

TreeNode(char characterValue, int frequencyCount) {
this.characterValue = characterValue;
this.frequencyCount = frequencyCount;
this.leftChild = null;
this.rightChild = null;
}

TreeNode(int frequencyCount, TreeNode leftChild, TreeNode rightChild) {
this.characterValue = '\0';
this.frequencyCount = frequencyCount;
this.leftChild = leftChild;
this.rightChild = rightChild;
}

boolean isLeafNode() {
return leftChild == null && rightChild == null;
}

@Override
public int compareTo(TreeNode otherNode) {
return Integer.compare(this.frequencyCount, otherNode.frequencyCount);
}
}

/**
 * Initializes the Huffman Tree and generates immutable prefix-free codes
 * based on the character frequencies in the provided text.
 *
 * @param sourceText The input string used to calculate frequencies and build the optimal tree.
 * If null or empty, an empty tree and dictionary are created.
 */
public HuffmanCoding(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
this.encodingTable = Collections.emptyMap();
return;
}
Map<Character, String> temporaryTable = new HashMap<>();
buildEncodingTree(sourceText);
generateCodes(rootNode, "", temporaryTable);
if (temporaryTable.size() == 1) {
temporaryTable.put(rootNode.characterValue, "0");
}
this.encodingTable = Collections.unmodifiableMap(temporaryTable);
}

/**
 * Computes character frequencies and constructs the Huffman Tree using a min-heap.
 * The optimal tree is built by repeatedly extracting the two lowest-frequency nodes
 * and merging them until a single root node remains.
 *
 * @param sourceText The input text to analyze.
 */
private void buildEncodingTree(String sourceText) {
Map<Character, Integer> frequencyMapping = new HashMap<>();
for (char currentChar : sourceText.toCharArray()) {
frequencyMapping.put(currentChar, frequencyMapping.getOrDefault(currentChar, 0) + 1);
}
PriorityQueue<TreeNode> minHeap = new PriorityQueue<>();
for (Map.Entry<Character, Integer> entry : frequencyMapping.entrySet()) {
minHeap.add(new TreeNode(entry.getKey(), entry.getValue()));
}
while (minHeap.size() > 1) {
TreeNode leftNode = minHeap.poll();
TreeNode rightNode = minHeap.poll();
minHeap.add(new TreeNode(leftNode.frequencyCount + rightNode.frequencyCount, leftNode, rightNode));
}
rootNode = minHeap.poll();
}

/**
 * Recursively traverses the Huffman Tree to generate prefix-free binary codes.
 * Left traversals append a '0' to the code, while right traversals append a '1'.
 *
 * @param currentNode The current node in the traversal.
 * @param currentCode The accumulated binary string for the current path.
 * @param codeMapping The temporary dictionary to populate with the final character-to-code mappings.
 */
private void generateCodes(TreeNode currentNode, String currentCode, Map<Character, String> codeMapping) {
if (currentNode == null) {
return;
}
if (currentNode.isLeafNode()) {
codeMapping.put(currentNode.characterValue, currentCode);
return;
}
generateCodes(currentNode.leftChild, currentCode + "0", codeMapping);
generateCodes(currentNode.rightChild, currentCode + "1", codeMapping);
}

/**
 * Encodes the given plaintext string into a binary string using the generated Huffman dictionary.
 *
 * @param sourceText The plaintext string to compress.
 * @return A string of '0's and '1's representing the compressed data.
 * Returns an empty string if the input is null or empty.
 * @throws IllegalStateException    If attempting to encode when the Huffman tree is empty.
 * @throws IllegalArgumentException If the input text contains a character not present
 * in the original text used to build the tree.
 */
public String encode(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
return "";
}
if (rootNode == null) {
throw new IllegalStateException("Huffman tree is empty.");
}
StringBuilder encodedOutput = new StringBuilder();
for (char currentChar : sourceText.toCharArray()) {
if (!encodingTable.containsKey(currentChar)) {
throw new IllegalArgumentException(String.format("Character '%c' (U+%04X) not found in Huffman dictionary.", currentChar, (int) currentChar));
}
encodedOutput.append(encodingTable.get(currentChar));
}
return encodedOutput.toString();
}

/**
 * Decodes the given binary string back into the original plaintext using the Huffman Tree.
 * Validates the integrity of the binary payload during traversal.
 *
 * @param encodedData The binary string of '0's and '1's to decompress.
 * @return The reconstructed plaintext string. Returns an empty string if the input is null or empty.
 * @throws IllegalStateException    If attempting to decode when the Huffman tree is empty.
 * @throws IllegalArgumentException If the binary string contains characters other than '0' or '1',
 * or if the sequence ends abruptly without reaching a leaf node.
 */
public String decode(String encodedData) {
if (encodedData == null || encodedData.isEmpty()) {
return "";
}
if (rootNode == null) {
throw new IllegalStateException("Huffman tree is empty.");
}
StringBuilder decodedOutput = new StringBuilder();
if (rootNode.isLeafNode()) {
for (char currentBit : encodedData.toCharArray()) {
if (currentBit != '0') {
throw new IllegalArgumentException("Invalid binary sequence for single-character tree.");
}
decodedOutput.append(rootNode.characterValue);
}
return decodedOutput.toString();
}
TreeNode traversalNode = rootNode;
for (char currentBit : encodedData.toCharArray()) {
if (currentBit != '0' && currentBit != '1') {
throw new IllegalArgumentException("Encoded text contains invalid characters: " + currentBit);
}
traversalNode = (currentBit == '0') ? traversalNode.leftChild : traversalNode.rightChild;
if (traversalNode.isLeafNode()) {
decodedOutput.append(traversalNode.characterValue);
traversalNode = rootNode;
}
}
if (traversalNode != rootNode) {
throw new IllegalArgumentException("Malformed encoded string: incomplete sequence ending.");
}
return decodedOutput.toString();
}

/**
 * Retrieves the generated Huffman dictionary mapping characters to their binary codes.
 *
 * @return An unmodifiable map containing the character-to-binary-code mappings to prevent
 * external mutation of the algorithm's state.
 */
public Map<Character, String> getHuffmanCodes() {
return encodingTable;
}
}

