}

/**
 * This class implements a solution to the 2-SAT (2-Satisfiability) problem
 * using Kosaraju's algorithm to find strongly connected components (SCCs)
 * in the implication graph.
 *
 * <p>
 * <strong>Brief Idea:</strong>
 * </p>
 *
 * <pre>
 * 1. From each clause (a ∨ b), we can derive implications:
 *      (¬a → b) and (¬b → a)
 *
 * 2. We construct an implication graph using these implications.
 *
 * 3. For each variable x, its negation ¬x is also represented as a node.
 *    If x and ¬x belong to the same SCC, the expression is unsatisfiable.
 *
 * 4. Otherwise, we assign truth values based on the SCC order:
 *    If SCC(x) > SCC(¬x), then x = true; otherwise, x = false.
 * </pre>
 *
 * <p>
 * <strong>Complexities:</strong>
 * </p>
 * <ul>
 * <li>Time Complexity: O(n + m)</li>
 * <li>Space Complexity: O(n + m)</li>
 * </ul>
 * where {@code n} is the number of variables and {@code m} is the number of
 * clauses.
 *
 * <p>
 * <strong>Usage Example:</strong>
 * </p>
 *
 * <pre>
 * TwoSat twoSat = new TwoSat(5); // Initialize with 5 variables: x1, x2, x3, x4, x5
 *
 * // Add clauses
 * twoSat.addClause(1, false, 2, false); // (x1 ∨ x2)
 * twoSat.addClause(3, true, 2, false); // (¬x3 ∨ x2)
 * twoSat.addClause(4, false, 5, true); // (x4 ∨ ¬x5)
 *
 * twoSat.solve(); // Solve the problem
 *
 * if (twoSat.isSolutionExists()) {
 *     boolean[] solution = twoSat.getSolutions();
 *     for (int i = 1; i <= 5; i++) {
 *         System.out.println("x" + i + " = " + solution[i]);
 *     }
 * }
 * </pre>
 * <p><strong>Reference</strong></p>
 * <a href="https://cp-algorithms.com/graph/2SAT.html">CP Algorithm</a> <br></br>
 * <a href="https://en.wikipedia.org/wiki/2-satisfiability">Wikipedia - 2 SAT</a>
 * @author Shoyeb Ansari
 *
 * @see Kosaraju
 */
class TwoSat {

    /** Number of variables in the boolean expression. */
    private final int numberOfVariables;

    /** Implication graph built from the boolean clauses. */
    private final ArrayList<Integer>[] graph;

    /** Transposed implication graph used in Kosaraju's algorithm. */
    private final ArrayList<Integer>[] graphTranspose;

    /** Stores one valid truth assignment for all variables (1-indexed). */
    private final boolean[] variableAssignments;

    /** Indicates whether a valid solution exists. */
    private boolean hasSolution = true;

    /** Tracks whether the {@code solve()} method has been called. */
    private boolean isSolved = false;

    /**
     * Initializes the TwoSat solver with the given number of variables.
     *
     * @param numberOfVariables the number of boolean variables
     * @throws IllegalArgumentException if the number of variables is negative
     */
    @SuppressWarnings({"unchecked", "rawtypes"})
    TwoSat(int numberOfVariables) {
        if (numberOfVariables < 0) {
            throw new IllegalArgumentException("Number of variables cannot be negative.");
        }
        this.numberOfVariables = numberOfVariables;
        int n = 2 * numberOfVariables + 1;

        graph = (ArrayList<Integer>[]) new ArrayList[n];
        graphTranspose = (ArrayList<Integer>[]) new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
            graphTranspose[i] = new ArrayList<>();
        }
        variableAssignments = new boolean[numberOfVariables + 1];
    }

    /**
     * Adds a clause of the form (a ∨ b) to the boolean expression.
     *
     * <p>
     * Example: To add (¬x₁ ∨ x₂), call:
     * </p>
     *
     * <pre>{@code
     * addClause(1, true, 2, false);
     * }</pre>
     *
     * @param a         the first variable (1 ≤ a ≤ numberOfVariables)
     * @param isNegateA {@code true} if variable {@code a} is negated
     * @param b         the second variable (1 ≤ b ≤ numberOfVariables)
     * @param isNegateB {@code true} if variable {@code b} is negated
     * @throws IllegalArgumentException if {@code a} or {@code b} are out of range
     */
    void addClause(int a, boolean isNegateA, int b, boolean isNegateB) {
        if (a <= 0 || a > numberOfVariables) {
            throw new IllegalArgumentException("Variable number must be between 1 and " + numberOfVariables);
        }
        if (b <= 0 || b > numberOfVariables) {
            throw new IllegalArgumentException("Variable number must be between 1 and " + numberOfVariables);
        }

        a = isNegateA ? negate(a) : a;
        b = isNegateB ? negate(b) : b;
        int notA = negate(a);
        int notB = negate(b);

        // Add implications: (¬a → b) and (¬b → a)
        graph[notA].add(b);
        graph[notB].add(a);

        // Build transpose graph
        graphTranspose[b].add(notA);
        graphTranspose[a].add(notB);
    }

    /**
     * Solves the 2-SAT problem using Kosaraju's algorithm to find SCCs
     * and determines whether a satisfying assignment exists.
     */
    void solve() {
        isSolved = true;
        int n = 2 * numberOfVariables + 1;

        boolean[] visited = new boolean[n];
        int[] component = new int[n];
        Stack<Integer> topologicalOrder = new Stack<>();

        // Step 1: Perform DFS to get topological order
        for (int i = 1; i < n; i++) {
            if (!visited[i]) {
                dfsForTopologicalOrder(i, visited, topologicalOrder);
            }
        }

        Arrays.fill(visited, false);
        int sccId = 0;

        // Step 2: Find SCCs on transposed graph
        while (!topologicalOrder.isEmpty()) {
            int node = topologicalOrder.pop();
            if (!visited[node]) {
                dfsForScc(node, visited, component, sccId);
                sccId++;
            }
        }

        // Step 3: Check for contradictions and assign values
        for (int i = 1; i <= numberOfVariables; i++) {
            int notI = negate(i);
            if (component[i] == component[notI]) {
                hasSolution = false;
                return;
            }
            // If SCC(i) > SCC(¬i), then variable i is true.
            variableAssignments[i] = component[i] > component[notI];
        }
    }

    /**
     * Returns whether the given boolean formula is satisfiable.
     *
     * @return {@code true} if a solution exists; {@code false} otherwise
     * @throws Error if called before {@link #solve()}
     */
    boolean isSolutionExists() {
        if (!isSolved) {
            throw new Error("Please call solve() before checking for a solution.");
        }
        return hasSolution;
    }

    /**
     * Returns one valid assignment of variables that satisfies the boolean formula.
     *
     * @return a boolean array where {@code result[i]} represents the truth value of
     *         variable {@code xᵢ}
     * @throws Error if called before {@link #solve()} or if no solution exists
     */
    boolean[] getSolutions() {
        if (!isSolved) {
            throw new Error("Please call solve() before fetching the solution.");
        }
        if (!hasSolution) {
            throw new Error("No satisfying assignment exists for the given expression.");
        }
        return variableAssignments.clone();
    }

    /** Performs DFS to compute topological order. */
    private void dfsForTopologicalOrder(int u, boolean[] visited, Stack<Integer> topologicalOrder) {
        visited[u] = true;
        for (int v : graph[u]) {
            if (!visited[v]) {
                dfsForTopologicalOrder(v, visited, topologicalOrder);
            }
        }
        topologicalOrder.push(u);
    }

    /** Performs DFS on the transposed graph to identify SCCs. */
    private void dfsForScc(int u, boolean[] visited, int[] component, int sccId) {
        visited[u] = true;
        component[u] = sccId;
        for (int v : graphTranspose[u]) {
            if (!visited[v]) {
                dfsForScc(v, visited, component, sccId);
            }
        }
    }

    /**
     * Returns the index representing the negation of the given variable.
     *
     * <p>
     * Mapping rule:
     * </p>
     *
     * <pre>
     * For a variable i:
     *     negate(i) = i + n
     * For a negated variable (i + n):
     *     negate(i + n) = i
     * where n = numberOfVariables
     * </pre>
     *
     * @param a the variable index
     * @return the index representing its negation
     */
    private int negate(int a) {
        return a <= numberOfVariables ? a + numberOfVariables : a - numberOfVariables;
    }
}

/**
 * Treap -> Tree + Heap
 * Also called as cartesian tree
 *
 * @see
 * <a href = "https://cp-algorithms.com/data_structures/treap.html" />
 */

public class Treap {

    public static class TreapNode {
        /**
         * TreapNode class defines the individual nodes in the Treap
         *
         * value -> holds the value of the node.
         * Binary Search Tree is built based on value.
         *
         * priority -> holds the priority of the node.
         * Heaps are maintained based on priority.
         * It is randomly assigned
         *
         * size -> holds the size of the subtree with current node as root
         *
         * left -> holds the left subtree
         * right -> holds the right subtree
         */
        public int value;
        private int priority;
        private int size;
        public TreapNode left;
        public TreapNode right;

        public TreapNode(int valueParam, int priorityParam) {
            value = valueParam;
            priority = priorityParam;
            size = 1;
            left = null;
            right = null;
        }

        /**
         * updateSize -> updates the subtree size of the current node
         */
        private void updateSize() {
            size = 1;
            if (left != null) {
                size += left.size;
            }
            if (right != null) {
                size += right.size;
            }
        }
    }

    /**
     * root -> holds the root node in the Treap
     * random -> to generate random priority for the nodes in the Treap
     */
    private TreapNode root;
    private Random random = new Random();

    /**
     * Constructors
     *
     * Treap() -> create an empty Treap
     * Treap(int[] nodeValues) -> add the elements given in the array to the Treap
     */
    public Treap() {
        root = null;
    }

    /**
     * merges two Treaps left and right into a single Treap
     *
     * @param left left Treap
     * @param right right Treap
     * @return root of merged Treap
     */
    private TreapNode merge(TreapNode left, TreapNode right) {
        if (left == null) {
            return right;
        }
        if (right == null) {
            return left;
        }

        if (left.priority > right.priority) {
            left.right = merge(left.right, right);
            left.updateSize();
            return left;
        } else {
            right.left = merge(left, right.left);
            right.updateSize();
            return right;
        }
    }

    /**
     * split the Treap into two Treaps where left Treap has nodes <= key and right Treap has nodes > key
     *
     * @param node root node to be split
     * @param key key to compare the nodes
     * @return TreapNode array of size 2.
     * TreapNode[0] contains the root of left Treap after split
     * TreapNode[1] contains the root of right Treap after split
     */
    private TreapNode[] split(TreapNode node, int key) {
        if (node == null) {
            return new TreapNode[] {null, null};
        }

        TreapNode[] result;

        if (node.value <= key) {
            result = split(node.right, key);
            node.right = result[0];
            node.updateSize();
            result[0] = node;
        } else {
            result = split(node.left, key);
            node.left = result[1];
            node.updateSize();
            result[1] = node;
        }

        return result;
    }

    /**
     * insert a node into the Treap
     *
     * @param value value to be inserted into the Treap
     * @return root of the Treap where the value is inserted
     */
    public TreapNode insert(int value) {
        if (root == null) {
            root = new TreapNode(value, random.nextInt());
            return root;
        }

        TreapNode[] splitted = split(root, value);

        TreapNode node = new TreapNode(value, random.nextInt());

        TreapNode tempMerged = merge(splitted[0], node);
        tempMerged.updateSize();

        TreapNode merged = merge(tempMerged, splitted[1]);
        merged.updateSize();

        root = merged;

        return root;
    }

    /**
     * delete a value from root if present
     *
     * @param value value to be deleted from the Treap
     * @return root of the Treap where delete has been performed
     */
    public TreapNode delete(int value) {
        root = deleteNode(root, value);
        return root;
    }

    private TreapNode deleteNode(TreapNode root, int value) {
        if (root == null) {
            return null;
        }

        if (value < root.value) {
            root.left = deleteNode(root.left, value);
        } else if (value > root.value) {
            root.right = deleteNode(root.right, value);
        } else {
            root = merge(root.left, root.right);
        }

        if (root != null) {
            root.updateSize();
        }
        return root;
    }

    /**
     * print inorder traversal of the Treap
     */
    public void inOrder() {
        System.out.print("{");
        printInorder(root);
        System.out.print("}");
    }

    private void printInorder(TreapNode root) {
        if (root == null) {
            return;
        }
        printInorder(root.left);
        System.out.print(root.value + ",");
        printInorder(root.right);
    }

    /**
     * print preOrder traversal of the Treap
     */
    public void preOrder() {
        System.out.print("{");
        printPreOrder(root);
        System.out.print("}");
    }

    private void printPreOrder(TreapNode root) {
        if (root == null) {
            return;
        }
        System.out.print(root.value + ",");
        printPreOrder(root.left);
        printPreOrder(root.right);
    }

    /**
     * print postOrder traversal of the Treap
     */
    public void postOrder() {
        System.out.print("{");
        printPostOrder(root);
        System.out.print("}");
    }

    private void printPostOrder(TreapNode root) {
        if (root == null) {
            return;
        }
        printPostOrder(root.left);
        printPostOrder(root.right);
        System.out.print(root.value + ",");
    }

    /**
     * Search a value in the Treap
     *
     * @param value value to be searched for
     * @return node containing the value
     * null if not found
     */
    public TreapNode search(int value) {
        return searchVal(root, value);
    }

    private TreapNode searchVal(TreapNode root, int value) {
        if (root == null) {
            return null;
        }

        if (root.value == value) {
            return root;
        } else if (root.value < value) {
            return searchVal(root.right, value);
        } else {
            return searchVal(root.left, value);
        }
    }

    /**
     * find the lowerBound of a value in the Treap
     *
     * @param value value for which lowerBound is to be found
     * @return node which is the lowerBound of the value passed
     */
    public TreapNode lowerBound(int value) {
        TreapNode lowerBoundNode = null;
        TreapNode current = root;

        while (current != null) {
            if (current.value >= value) {
                lowerBoundNode = current;
                current = current.left;
            } else {
                current = current.right;
            }
        }

        return lowerBoundNode;
    }

    /**
     * find the upperBound of a value in the Treap
     *
     * @param value value for which upperBound is to be found
     * @return node which is the upperBound of the value passed
     */
    public TreapNode upperBound(int value) {
        TreapNode upperBoundNode = null;
        TreapNode current = root;

        while (current != null) {
            if (current.value > value) {
                upperBoundNode = current;
                current = current.left;
            } else {
                current = current.right;
            }
        }

        return upperBoundNode;
    }

    /**
     * returns size of the Treap
     */
    public int size() {
        if (root == null) {
            return 0;
        }
        return root.size;
    }

    /**
     * returns if Treap is empty
     */
    public boolean isEmpty() {
        return root == null;
    }

    /**
     * returns root node of the Treap
     */
    public TreapNode getRoot() {
        return root;
    }

    /**
     * returns left node of the TreapNode
     */
    public TreapNode getLeft(TreapNode node) {
        return node.left;
    }

    /**
     * returns the right node of the TreapNode
     */
    public TreapNode getRight(TreapNode node) {
        return node.right;
    }

    /**
     * prints the value, priority, size of the subtree of the TreapNode, left TreapNode and right TreapNode of the node
     */
    public String toString(TreapNode node) {
        return "{value : " + node.value + ", priority : " + node.priority + ", subTreeSize = " + node.size + ", left = " + node.left + ", right = " + node.right + "}";
    }
}

