        System.out.print("4. sayi: ");
        sayi4 = scanner.nextInt();
        System.out.print("5. sayi: ");
        sayi5 = scanner.nextInt();

        scanner.close();

        // Siralama algoritmasi (basit karsilastirmalar)
        if (sayi1 > sayi2) { int gecici = sayi1; sayi1 = sayi2; sayi2 = gecici; }
