package com.thealgorithms.datastructures.caches;

import java.util.HashMap;
import java.util.Map;

/**
 * A Least Recently Used (LRU) Cache implementation.
 *
 * <p>An LRU cache is a fixed-size cache that maintains items in order of use. When the cache reaches
 * its capacity and a new item needs to be added, it removes the least recently used item first.
 * This implementation provides O(1) time complexity for both get and put operations.</p>
 *
 * <p>Features:</p>
 * <ul>
 *   <li>Fixed-size cache with configurable capacity</li>
 *   <li>Constant time O(1) operations for get and put</li>
 *   <li>Thread-unsafe - should be externally synchronized if used in concurrent environments</li>
 *   <li>Supports null values but not null keys</li>
 * </ul>
 *
 * <p>Implementation Details:</p>
 * <ul>
 *   <li>Uses a HashMap for O(1) key-value lookups</li>
 *   <li>Maintains a doubly-linked list for tracking access order</li>
 *   <li>The head of the list contains the least recently used item</li>
 *   <li>The tail of the list contains the most recently used item</li>
 * </ul>
 *
 * <p>Example usage:</p>
 * <pre>
 * LRUCache&lt;String, Integer&gt; cache = new LRUCache&lt;&gt;(3); // Create cache with capacity 3
 * cache.put("A", 1); // Cache: A=1
 * cache.put("B", 2); // Cache: A=1, B=2
 * cache.put("C", 3); // Cache: A=1, B=2, C=3
 * cache.get("A");    // Cache: B=2, C=3, A=1 (A moved to end)
 * cache.put("D", 4); // Cache: C=3, A=1, D=4 (B evicted)
 * </pre>
 *
 * @param <KeyType> the type of keys maintained by this cache
 * @param <ValueType> the type of mapped values
 */
public class LRUCache<KeyType, ValueType> {

private final Map<KeyType, CacheNode<KeyType, ValueType>> storageMap = new HashMap<>();
private CacheNode<KeyType, ValueType> leastNode;
private CacheNode<KeyType, ValueType> mostNode;
private int maxCapacity;
private static final int DEFAULT_CAPACITY = 100;

public LRUCache() {
setMaxCapacity(DEFAULT_CAPACITY);
}

public LRUCache(int capacityValue) {
setMaxCapacity(capacityValue);
}

/**
 * Returns the current capacity of the cache.
 *
 * @param newCapacity the new capacity of the cache
 */
private void setMaxCapacity(int newCapacity) {
validateCapacity(newCapacity);
for (int itemCount = storageMap.size(); itemCount > newCapacity; itemCount--) {
CacheNode<KeyType, ValueType> evictedNode = evictOldest();
storageMap.remove(evictedNode.getStoredKey());
}
this.maxCapacity = newCapacity;
}

/**
 * Evicts the least recently used item from the cache.
 *
 * @return the evicted entry
 */
private CacheNode<KeyType, ValueType> evictOldest() {
if (leastNode == null) {
throw new RuntimeException("cache cannot be empty!");
}
CacheNode<KeyType, ValueType> evictedItem = leastNode;
leastNode = evictedItem.getNextNode();
leastNode.setPreviousNode(null);
evictedItem.setNextNode(null);
return evictedItem;
}

/**
 * Checks if the capacity is valid.
 *
 * @param capacityValue the capacity to check
 */
private void validateCapacity(int capacityValue) {
if (capacityValue <= 0) {
throw new RuntimeException("capacity must greater than 0!");
}
}

/**
 * Returns the value to which the specified key is mapped, or null if this cache contains no
 * mapping for the key.
 *
 * @param searchKey the key whose associated value is to be returned
 * @return the value to which the specified key is mapped, or null if this cache contains no
 * mapping for the key
 */
public ValueType get(KeyType searchKey) {
if (!storageMap.containsKey(searchKey)) {
return null;
}
final CacheNode<KeyType, ValueType> targetNode = storageMap.get(searchKey);
moveNodeToEnd(targetNode);
return targetNode.getStoredValue();
}

/**
 * Moves the specified entry to the end of the list.
 *
 * @param targetNode the entry to move
 */
private void moveNodeToEnd(CacheNode<KeyType, ValueType> targetNode) {
if (mostNode == targetNode) {
return;
}
final CacheNode<KeyType, ValueType> previousItem = targetNode.getPreviousNode();
final CacheNode<KeyType, ValueType> nextItem = targetNode.getNextNode();
if (previousItem != null) {
previousItem.setNextNode(nextItem);
}
if (nextItem != null) {
nextItem.setPreviousNode(previousItem);
}
if (leastNode == targetNode) {
leastNode = nextItem;
}
mostNode.setNextNode(targetNode);
targetNode.setPreviousNode(mostNode);
targetNode.setNextNode(null);
mostNode = targetNode;
}

/**
 * Associates the specified value with the specified key in this cache.
 *
 * @param insertKey the key with which the specified value is to be associated
 * @param insertValue the value to be associated with the specified key
 */
public void put(KeyType insertKey, ValueType insertValue) {
if (storageMap.containsKey(insertKey)) {
final CacheNode<KeyType, ValueType> existingNode = storageMap.get(insertKey);
existingNode.setStoredValue(insertValue);
moveNodeToEnd(existingNode);
return;
}
CacheNode<KeyType, ValueType> newNode;
if (storageMap.size() == maxCapacity) {
newNode = evictOldest();
storageMap.remove(newNode.getStoredKey());
} else {
newNode = new CacheNode<>();
}
newNode.setStoredKey(insertKey);
newNode.setStoredValue(insertValue);
insertNewNode(newNode);
storageMap.put(insertKey, newNode);
}

/**
 * Adds a new entry to the end of the list.
 *
 * @param newNode the entry to add
 */
private void insertNewNode(CacheNode<KeyType, ValueType> newNode) {
if (storageMap.isEmpty()) {
leastNode = newNode;
mostNode = newNode;
return;
}
mostNode.setNextNode(newNode);
newNode.setPreviousNode(mostNode);
newNode.setNextNode(null);
mostNode = newNode;
}

static final class CacheNode<KeyType, ValueType> {

private CacheNode<KeyType, ValueType> previousNode;
private CacheNode<KeyType, ValueType> nextNode;
private KeyType storedKey;
private ValueType storedValue;

CacheNode() {
}

CacheNode(CacheNode<KeyType, ValueType> previousNode, CacheNode<KeyType, ValueType> nextNode, KeyType storedKey, ValueType storedValue) {
this.previousNode = previousNode;
this.nextNode = nextNode;
this.storedKey = storedKey;
this.storedValue = storedValue;
}

public CacheNode<KeyType, ValueType> getPreviousNode() {
return previousNode;
}

public void setPreviousNode(CacheNode<KeyType, ValueType> previousNode) {
this.previousNode = previousNode;
}

public CacheNode<KeyType, ValueType> getNextNode() {
return nextNode;
}

public void setNextNode(CacheNode<KeyType, ValueType> nextNode) {
this.nextNode = nextNode;
}

public KeyType getStoredKey() {
return storedKey;
}

public void setStoredKey(KeyType storedKey) {
this.storedKey = storedKey;
}

public ValueType getStoredValue() {
return storedValue;
}

public void setStoredValue(ValueType storedValue) {
this.storedValue = storedValue;
}
}
}

