/**
 * The RGB color model is an additive color model in which red, green, and blue
 * light are added together in various ways to reproduce a broad array of
 * colors. The name of the model comes from the initials of the three additive
 * primary colors, red, green, and blue. Meanwhile, the HSV representation
 * models how colors appear under light. In it, colors are represented using
 * three components: hue, saturation and (brightness-)value. This class provides
 * methods for converting colors from one representation to the other.
 * (description adapted from <a href="https://en.wikipedia.org/wiki/RGB_color_model">[1]</a> and
 * <a href="https://en.wikipedia.org/wiki/HSL_and_HSV">[2]</a>).
 */
public final class RgbHsvConversion {
private RgbHsvConversion() {
}

public static void main(String[] args) {
assert Arrays.equals(hsvToRgb(0, 0, 0), new int[] {0, 0, 0});
assert Arrays.equals(hsvToRgb(0, 0, 1), new int[] {255, 255, 255});
assert Arrays.equals(hsvToRgb(0, 1, 1), new int[] {255, 0, 0});
assert Arrays.equals(hsvToRgb(60, 1, 1), new int[] {255, 255, 0});
assert Arrays.equals(hsvToRgb(120, 1, 1), new int[] {0, 255, 0});
assert Arrays.equals(hsvToRgb(240, 1, 1), new int[] {0, 0, 255});
assert Arrays.equals(hsvToRgb(300, 1, 1), new int[] {255, 0, 255});
assert Arrays.equals(hsvToRgb(180, 0.5, 0.5), new int[] {64, 128, 128});
assert Arrays.equals(hsvToRgb(234, 0.14, 0.88), new int[] {193, 196, 224});
assert Arrays.equals(hsvToRgb(330, 0.75, 0.5), new int[] {128, 32, 80});
assert approximatelyEqualHsv(rgbToHsv(0, 0, 0), new double[] {0, 0, 0});
assert approximatelyEqualHsv(rgbToHsv(255, 255, 255), new double[] {0, 0, 1});
assert approximatelyEqualHsv(rgbToHsv(255, 0, 0), new double[] {0, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(255, 255, 0), new double[] {60, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(0, 255, 0), new double[] {120, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(0, 0, 255), new double[] {240, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(255, 0, 255), new double[] {300, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(64, 128, 128), new double[] {180, 0.5, 0.5});
assert approximatelyEqualHsv(rgbToHsv(193, 196, 224), new double[] {234, 0.14, 0.88});
assert approximatelyEqualHsv(rgbToHsv(128, 32, 80), new double[] {330, 0.75, 0.5});
}

/**
 * Conversion from the HSV-representation to the RGB-representation.
 *
 * @param hueValue Hue of the color.
 * @param saturationValue Saturation of the color.
 * @param brightnessValue Brightness-value of the color.
 * @return The tuple of RGB-components.
 */
public static int[] hsvToRgb(double hueValue, double saturationValue, double brightnessValue) {
if (hueValue < 0 || hueValue > 360) {
throw new IllegalArgumentException("hue should be between 0 and 360");
}
if (saturationValue < 0 || saturationValue > 1) {
throw new IllegalArgumentException("saturation should be between 0 and 1");
}
if (brightnessValue < 0 || brightnessValue > 1) {
throw new IllegalArgumentException("value should be between 0 and 1");
}
double chromaAmount = brightnessValue * saturationValue;
double hueSegment = hueValue / 60;
double secondaryComponent = chromaAmount * (1 - Math.abs(hueSegment % 2 - 1));
double brightnessOffset = brightnessValue - chromaAmount;
return getRgbFromSegment(hueSegment, chromaAmount, brightnessOffset, secondaryComponent);
}

/**
 * Conversion from the RGB-representation to the HSV-representation.
 *
 * @param redValue Red-component of the color.
 * @param greenValue Green-component of the color.
 * @param blueValue Blue-component of the color.
 * @return The tuple of HSV-components.
 */
public static double[] rgbToHsv(int redValue, int greenValue, int blueValue) {
if (redValue < 0 || redValue > 255) {
throw new IllegalArgumentException("red should be between 0 and 255");
}
if (greenValue < 0 || greenValue > 255) {
throw new IllegalArgumentException("green should be between 0 and 255");
}
if (blueValue < 0 || blueValue > 255) {
throw new IllegalArgumentException("blue should be between 0 and 255");
}
double normalizedRed = (double) redValue / 255;
double normalizedGreen = (double) greenValue / 255;
double normalizedBlue = (double) blueValue / 255;
double maxComponent = Math.max(Math.max(normalizedRed, normalizedGreen), normalizedBlue);
double minComponent = Math.min(Math.min(normalizedRed, normalizedGreen), normalizedBlue);
double chromaDifference = maxComponent - minComponent;
double saturationResult = maxComponent == 0 ? 0 : chromaDifference / maxComponent;
double hueResult;
if (chromaDifference == 0) {
hueResult = 0;
} else if (maxComponent == normalizedRed) {
hueResult = 60 * (0 + (normalizedGreen - normalizedBlue) / chromaDifference);
} else if (maxComponent == normalizedGreen) {
hueResult = 60 * (2 + (normalizedBlue - normalizedRed) / chromaDifference);
} else {
hueResult = 60 * (4 + (normalizedRed - normalizedGreen) / chromaDifference);
}
hueResult = (hueResult + 360) % 360;
return new double[] {hueResult, saturationResult, maxComponent};
}

private static boolean approximatelyEqualHsv(double[] hsvFirst, double[] hsvSecond) {
boolean hueMatch = Math.abs(hsvFirst[0] - hsvSecond[0]) < 0.2;
boolean saturationMatch = Math.abs(hsvFirst[1] - hsvSecond[1]) < 0.002;
boolean valueMatch = Math.abs(hsvFirst[2] - hsvSecond[2]) < 0.002;
return hueMatch && saturationMatch && valueMatch;
}

private static int[] getRgbFromSegment(double hueSegment, double chromaAmount, double brightnessOffset, double secondaryComponent) {
int redChannel, greenChannel, blueChannel;
if (hueSegment >= 0 && hueSegment <= 1) {
redChannel = convertToInt(chromaAmount + brightnessOffset);
greenChannel = convertToInt(secondaryComponent + brightnessOffset);
blueChannel = convertToInt(brightnessOffset);
} else if (hueSegment > 1 && hueSegment <= 2) {
redChannel = convertToInt(secondaryComponent + brightnessOffset);
greenChannel = convertToInt(chromaAmount + brightnessOffset);
blueChannel = convertToInt(brightnessOffset);
} else if (hueSegment > 2 && hueSegment <= 3) {
redChannel = convertToInt(brightnessOffset);
greenChannel = convertToInt(chromaAmount + brightnessOffset);
blueChannel = convertToInt(secondaryComponent + brightnessOffset);
} else if (hueSegment > 3 && hueSegment <= 4) {
redChannel = convertToInt(brightnessOffset);
greenChannel = convertToInt(secondaryComponent + brightnessOffset);
blueChannel = convertToInt(chromaAmount + brightnessOffset);
} else if (hueSegment > 4 && hueSegment <= 5) {
redChannel = convertToInt(secondaryComponent + brightnessOffset);
greenChannel = convertToInt(brightnessOffset);
blueChannel = convertToInt(chromaAmount + brightnessOffset);
} else {
redChannel = convertToInt(chromaAmount + brightnessOffset);
greenChannel = convertToInt(brightnessOffset);
blueChannel = convertToInt(secondaryComponent + brightnessOffset);
}
return new int[] {redChannel, greenChannel, blueChannel};
}

private static int convertToInt(double valueToConvert) {
return (int) Math.round(255 * valueToConvert);
}
}

package example;

import java.io.BufferedReader;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.ServerSocket;
import java.net.Socket;

// Her istemciyi ayri bir is parcasi olarak ele alan sinif
class ClientHandler extends Thread {
	DataInputStream input; // Istemciden veri almak icin
	DataOutputStream output; // Istemciye veri gondermek icin
	final Socket socket; // Bagli olan istemcinin soketi
	BufferedReader reader = new BufferedReader(new InputStreamReader(System.in)); // Kullanici girdisi icin

	// Yapilandirici: Istemci soketi alinir
	public ClientHandler(Socket socket) {
		this.socket = socket;
		try {
			input = new DataInputStream(socket.getInputStream());
			output = new DataOutputStream(socket.getOutputStream());
		} catch (IOException e) {
			e.printStackTrace();
			System.out.println("Istemci baglantisi olusturulurken hata meydana geldi: " + e.getMessage());
		}
	}

	// Istemci ile iletisimi yurutmek icin calistirilacak kod
	public void run() {
		try {
			String str = ""; // Istemciden gelen mesaj
			while (!str.equals("stop")) { // Istemciden "stop" mesajini alana kadar donguye devam et
				str = input.readUTF(); // Istemciden gelen mesaji al
				System.out.println("Istemciden alinan mesaj: " + str); // Gelen mesaji ekrana yazdir
				output.writeUTF(str); // Istemciden alinan mesaji geri gonder
				output.flush(); // Gonderilen mesajlari temizle
			}
		} catch (IOException e) {
			System.out.println("Istemci ile baglanti koptu: " + e.getMessage());
		} finally {
			try {
				// Soketi kapat
				this.socket.close();
				System.out.println("Istemci soketi kapatildi.");
			} catch (IOException e) {
				System.out.println("Soket kapatilirken hata meydana geldi: " + e.getMessage());
			}
		}
	}
}

public class Server {
	public static void main(String[] args) throws IOException {
		// Sunucu soketi olustur
		ServerSocket serverSocket = new ServerSocket(4444);
		System.out.println("Sunucu baslatildi ve baglanti bekleniyor...");

		while (true) {
			Socket socket = null; // Baglanacak istemci soketi
			try {
				// Yeni bir istemci baglandiginda kabul et
				socket = serverSocket.accept();
				System.out.println("Yeni bir istemci baglandi: " + socket);

				// Her istemci icin yeni bir thread baslat
				Thread thread = new ClientHandler(socket);
				thread.start();

			} catch (Exception e) {
				System.out.println("Baglanti sirasinda hata meydana geldi: " + e.getMessage());
				if (socket != null && !socket.isClosed()) {
					socket.close();
					System.out.println("Baglanti hatali soket kapatildi.");
				}
				serverSocket.close();
				e.printStackTrace();
				break; // Hata durumunda sunucuyu sonlandir
			}
		}
	}
}

package com.thealgorithms.conversions;

import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.Arrays;

/**
 * A utility class for converting between IPv6 and IPv4 addresses.
 *
 * - Converts IPv4 to IPv6-mapped IPv6 address.
 * - Extracts IPv4 address from IPv6-mapped IPv6.
 * - Handles exceptions for invalid inputs.
 *
 * @author Hardvan
 */
public final class IPv6Converter {
private IPv6Converter() {
}

/**
 * Converts an IPv4 address (e.g., "192.0.2.128") to an IPv6-mapped IPv6 address.
 * Example: IPv4 "192.0.2.128" -> IPv6 "::ffff:192.0.2.128"
 *
 * @param ipv4String The IPv4 address in string format.
 * @return The corresponding IPv6-mapped IPv6 address.
 * @throws UnknownHostException If the IPv4 address is invalid.
 * @throws IllegalArgumentException If the IPv6 address is not a mapped IPv4 address.
 */
public static String ipv4ToIpv6(String ipv4String) throws UnknownHostException {
if (ipv4String == null || ipv4String.isEmpty()) {
throw new UnknownHostException("IPv4 address is empty.");
}
InetAddress ipv4Address = InetAddress.getByName(ipv4String);
byte[] ipv4Bytes = ipv4Address.getAddress();
byte[] ipv6Bytes = new byte[16];
ipv6Bytes[10] = (byte) 0xff;
ipv6Bytes[11] = (byte) 0xff;
System.arraycopy(ipv4Bytes, 0, ipv6Bytes, 12, 4);
StringBuilder mappedIpv6 = new StringBuilder("::ffff:");
for (int segment = 12; segment < 16; segment++) {
mappedIpv6.append(ipv6Bytes[segment] & 0xFF);
if (segment < 15) {
mappedIpv6.append('.');
}
}
return mappedIpv6.toString();
}

/**
 * Extracts the IPv4 address from an IPv6-mapped IPv6 address.
 * Example: IPv6 "::ffff:192.0.2.128" -> IPv4 "192.0.2.128"
 *
 * @param ipv6String The IPv6 address in string format.
 * @return The extracted IPv4 address.
 * @throws UnknownHostException If the IPv6 address is invalid or not a mapped IPv4 address.
 */
public static String ipv6ToIpv4(String ipv6String) throws UnknownHostException {
InetAddress ipv6Address = InetAddress.getByName(ipv6String);
byte[] ipv6Bytes = ipv6Address.getAddress();
if (isMappedIpv4Address(ipv6Bytes)) {
byte[] ipv4Bytes = Arrays.copyOfRange(ipv6Bytes, 12, 16);
InetAddress ipv4Result = InetAddress.getByAddress(ipv4Bytes);
return ipv4Result.getHostAddress();
} else {
throw new IllegalArgumentException("Not a valid IPv6-mapped IPv4 address.");
}
}

/**
 * Helper function to check if the given byte array represents
 * an IPv6-mapped IPv4 address (prefix 0:0:0:0:0:ffff).
 *
 * @param ipv6Bytes Byte array representation of the IPv6 address.
 * @return True if the address is IPv6-mapped IPv4, otherwise false.
 */
private static boolean isMappedIpv4Address(byte[] ipv6Bytes) {
if (ipv6Bytes.length != 16) {
return false;
}
for (int offset = 0; offset < 10; offset++) {
if (ipv6Bytes[offset] != 0) {
return false;
}
}
return ipv6Bytes[10] == (byte) 0xff && ipv6Bytes[11] == (byte) 0xff;
}
}

public class Main {
    public static void main(String[] args) {
        // Example 1: Store 5 roll numbers using primitive array
        int[] rollNumbersArray = new int[5];

        // Example 2: Store 5 names using String array
        String[] studentNamesArray = new String[5];

        // Example 3: Store data for 5 students using separate arrays (not ideal OOP approach)
        int[] studentRollNumbers = new int[5];
        String[] studentNames = new String[5];
        float[] studentMarks = new float[5];

        // Preferred OOP approach: Array of Student objects
        Student[] studentsList = new Student[5];

        // Creating Student objects using parameterized constructor
        Student kunalStudent = new Student(15, "Kunal Kushwaha", 85.4f);
        Student rahulStudent = new Student(18, "Rahul Rana", 90.3f);

        // Alternative approach: Set properties individually (commented)
        // kunalStudent.rollNumber = 13;
        // kunalStudent.studentName = "Kunal Kushwaha";
        // kunalStudent.marksPercentage = 88.5f;

        // Call instance methods (commented)
        // kunalStudent.updateStudentName("Shoe lover");
        // kunalStudent.displayGreeting();

        // Display student details
        System.out.println("--- Kunal's Details ---");
        System.out.println("Roll Number: " + kunalStudent.rollNumber);
        System.out.println("Name: " + kunalStudent.studentName);
        System.out.println("Marks: " + kunalStudent.marksPercentage);

        // Copy constructor demonstration
        Student copiedStudent = new Student(kunalStudent);
        System.out.println("\n--- Copied Student (from Kunal) ---");
        System.out.println("Copied student name: " + copiedStudent.studentName);

        // Default constructor demonstration
        Student defaultStudent = new Student();
        System.out.println("\n--- Default Student ---");
        System.out.println("Default student name: " + defaultStudent.studentName);

        // Reference variable demonstration (both variables point to same object)
        Student studentReferenceOne = new Student();
        Student studentReferenceTwo = studentReferenceOne;

        // Modifying object through one reference affects the other
        studentReferenceOne.studentName = "Modified Name Example";

        System.out.println("\n--- Reference Variable Demonstration ---");
        System.out.println("studentReferenceTwo.name: " + studentReferenceTwo.studentName);
        System.out.println("studentReferenceTwo.rollNumber: " + studentReferenceTwo.rollNumber);

        // Creating student with custom roll number, name, and marks
        Student customStudent = new Student(23051814, "Ankan Chatterjee", 8.2f);
        System.out.println("\n--- Custom Student ---");
        System.out.println("Custom student name: " + customStudent.studentName);
    }
}

// Class representing a Student entity
// Encapsulates student-related data (roll number, name, marks) and behaviors
class Student {
    // Instance variables (fields)
    int rollNumber;           // Unique identifier for each student
    String studentName;       // Student's full name
    float marksPercentage;    // Student's marks (e.g., 85.4 means 85.4%)

    // Method to display greeting message
    void displayGreeting() {
        System.out.println("Hello! My name is " + this.studentName);
    }

    // Method to change/update student's name
    void updateStudentName(String newName) {
        this.studentName = newName;
    }

    // Copy constructor - creates a new Student object from an existing one
    Student(Student sourceStudent) {
        this.studentName = sourceStudent.studentName;
        this.rollNumber = sourceStudent.rollNumber;
        this.marksPercentage = sourceStudent.marksPercentage;
    }

    // Default constructor - initializes with default values by calling parameterized constructor
    Student() {
        // Calls the 3-parameter constructor with default values
        // Internally equivalent to: new Student(13, "default person", 100.0f);
        this(13, "Default Student Name", 100.0f);
    }

    // Parameterized constructor - initializes all instance variables
    // When creating object like: Student arpit = new Student(17, "Arpit", 89.7f);
    // The keyword 'this' refers to the object being created (arpit in this example)
    Student(int studentRollNumber, String studentFullName, float studentMarks) {
        this.rollNumber = studentRollNumber;
        this.studentName = studentFullName;
        this.marksPercentage = studentMarks;
    }
}

// Java'da lineer arama kullanarak bir dizide minimum elemani bulan program

public class EnKucukElemaniBul {

    public static void main(String[] args) {
        // Bir dizi tanimla ve degerlerini ata
        int[] dizi = {5, 2, 8, 1, 9, 4, 7};

        // Minimum elemani bulmak icin lineer arama yap
        int minEleman = dizi[0]; // Minimum elemani baslangicta ilk eleman olarak ata

        // Dizinin her elemanini kontrol et
        for (int i = 1; i < dizi.length; i++) {
            if (dizi[i] < minEleman) {
                minEleman = dizi[i]; // Yeni minimum elemani bulursak, onu ata
            }
        }

        // Minimum elemani ekrana yazdir
        System.out.println("Dizideki Minimum Eleman: " + minEleman);
    }
}

package MovableRectangle;

import MovableCircle.*;
import MovablePoint.*;

/**
 * A point with velocity that implements Movable.
 */
public class MovablePoint implements Movable {
    private int x;
    private int y;
    private int xSpeed;
    private int ySpeed;

    public MovablePoint() {
    }

    public MovablePoint(int x, int y, int xSpeed, int ySpeed) {
        this.x = x;
        this.y = y;
        this.xSpeed = xSpeed;
        this.ySpeed = ySpeed;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int getxSpeed() {
        return xSpeed;
    }

    public void setxSpeed(int xSpeed) {
        this.xSpeed = xSpeed;
    }

    public int getySpeed() {
        return ySpeed;
    }

    public void setySpeed(int ySpeed) {
        this.ySpeed = ySpeed;
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ") speed=" + xSpeed + "," + ySpeed + ')';
    }

    @Override
    public void moveUp() {
        y -= ySpeed;
    }

    @Override
    public void moveDown() {
        y += ySpeed;
    }

    @Override
    public void moveLeft() {
        x -= xSpeed;
    }

    @Override
    public void moveRight() {
        x += xSpeed;
    }
}

