package unchecked;

public class SifiraBolmeHatasi {

    public static void main(String[] args) {

        // Giris argumanlarini simule eden bir dizi tanimlandi
        String[] girisDizisi = {"10", "0"}; // Burada farkli degerlerle denenebilir

        try {
            // Diziden degerleri al ve tamsayi olarak ayristir
            int x = Integer.parseInt(girisDizisi[0]);
            int y = Integer.parseInt(girisDizisi[1]);

            // Iki sayiyi bol ve sonucu yazdir
            int z = x / y;
            System.out.println("Sonuc: " + z);

        } catch (NumberFormatException e) {
            // Eger girilen veri tamsayi degilse bu istisna firlatilir
            System.out.println("Gecersiz giris: Lutfen sadece tamsayi giriniz.");
            System.out.println("Istisna mesaji: " + e.getMessage());
            e.printStackTrace(); // Istisna izini yazdir

        } catch (ArithmeticException e) {
            // Eger bolme islemi sifira bolme icermisse bu istisna firlatilir
            System.out.println("Sifira bolme hatasi olustu!");
            System.out.println("Istisna mesaji: " + e.getMessage());
            e.printStackTrace(); // Istisna izini yazdir

        } catch (ArrayIndexOutOfBoundsException e) {
            // Eger dizi eksikse bu istisna firlatilir
            System.out.println("Eksik giris: Lutfen iki sayi giriniz.");
            System.out.println("Istisna mesaji: " + e.getMessage());
            e.printStackTrace(); // Istisna izini yazdir

        } finally {
            // Bu blok her zaman calisir
            System.out.println("Finally bloguna girildi!");
        }

        // Ek bir ornek: Istisna firlatmayan normal bir akisi test et
        try {
            basariliAkisTesti();
        } catch (Exception e) {
            System.out.println("Beklenmeyen bir hata: " + e.getMessage());
        }
    }

    /**
     * Basarili bir akis senaryosunu test eder.
     */
    public static void basariliAkisTesti() {
        System.out.println("Basarili akis testi calisiyor.");
        int a = 10;
        int b = 5;
        int sonuc = a / b;
        System.out.println("10 / 5 = " + sonuc);
        System.out.println("Her sey yolunda, istisna firlatilmadi!");
    }
}

/*
 * Walkthrough of basic SQLite operations from Java:
 *
 * - open a connection
 * - create a table
 * - insert, update, and delete rows
 * - list everything currently in the table
 */

public class SQLiteDemo {

    private static final String DB_URL = "jdbc:sqlite:test.db";

    public static void main(String[] args) {

        try (Connection db = DriverManager.getConnection(DB_URL);
             Statement stmt = db.createStatement()) {

            String createTable = "CREATE TABLE IF NOT EXISTS users (\n"
                    + " id INTEGER PRIMARY KEY,\n"
                    + " first_name TEXT NOT NULL,\n"
                    + " last_name TEXT NOT NULL,\n"
                    + " age INTEGER NOT NULL\n"
                    + ");";
            stmt.execute(createTable);
            System.out.println("Tablo basariyla olusturuldu");

            addPerson(db, "John", "Doe", 30);
            System.out.println("Kayit basariyla eklendi");

            addPerson(db, "Mike", "Tyson", 40);
            System.out.println("Kayit basariyla eklendi");

            listPeople(db);
            System.out.println("Tablo basariyla listelendi");

            editPerson(db, "John", "Smith", 35);
            System.out.println("Kayit basariyla guncellendi");

            listPeople(db);
            System.out.println("Tablo basariyla listelendi");

            removePerson(db, "John");
            System.out.println("Kayit basariyla silindi");

            listPeople(db);
            System.out.println("Tablo basariyla listelendi");

        } catch (SQLException e) {
            System.out.println(e.getMessage());
        }
    }

    public static void addPerson(Connection db, String firstName, String lastName, int age) throws SQLException {
        String sql = "INSERT INTO users(first_name, last_name, age) VALUES(?, ?, ?)";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setString(1, firstName);
            stmt.setString(2, lastName);
            stmt.setInt(3, age);
            stmt.executeUpdate();
        }
    }

    public static void editPerson(Connection db, String firstName, String lastName, int age) throws SQLException {
        String sql = "UPDATE users SET last_name = ?, age = ? WHERE first_name = ?";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setString(1, lastName);
            stmt.setInt(2, age);
            stmt.setString(3, firstName);
            stmt.executeUpdate();
        }
    }

    public static void listPeople(Connection db) throws SQLException {
        String sql = "SELECT id, first_name, last_name, age FROM users";
        try (Statement stmt = db.createStatement()) {
            ResultSet rows = stmt.executeQuery(sql);
            while (rows.next()) {
                System.out.println(rows.getInt("id") + "\t"
                        + rows.getString("first_name") + "\t"
                        + rows.getString("last_name") + "\t"
                        + rows.getInt("age"));
            }
        }
    }

    public static void removePerson(Connection db, String firstName) throws SQLException {
        String sql = "DELETE FROM users WHERE first_name = ?";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setString(1, firstName);
            stmt.executeUpdate();
        }
    }
}

/**
 * Implements various Boolean algebra gates (AND, OR, NOT, XOR, NAND, NOR)
 */
public final class BooleanAlgebraGates {

    private BooleanAlgebraGates() {
        // Prevent instantiation
    }

    /**
     * Represents a Boolean gate that takes multiple inputs and returns a result.
     */
    interface BooleanGate {
        /**
         * Evaluates the gate with the given inputs.
         *
         * @param inputs The input values for the gate.
         * @return The result of the evaluation.
         */
        boolean evaluate(List<Boolean> inputs);
    }

    /**
     * AND Gate implementation.
     * Returns true if all inputs are true; otherwise, false.
     */
    static class ANDGate implements BooleanGate {
        @Override
        public boolean evaluate(List<Boolean> inputs) {
            for (boolean input : inputs) {
                if (!input) {
                    return false;
                }
            }
            return true;
        }
    }

    /**
     * OR Gate implementation.
     * Returns true if at least one input is true; otherwise, false.
     */
    static class ORGate implements BooleanGate {
        @Override
        public boolean evaluate(List<Boolean> inputs) {
            for (boolean input : inputs) {
                if (input) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * NOT Gate implementation (Unary operation).
     * Negates a single input value.
     */
    static class NOTGate {
        /**
         * Evaluates the negation of the input.
         *
         * @param input The input value to be negated.
         * @return The negated value.
         */
        public boolean evaluate(boolean input) {
            return !input;
        }
    }

    /**
     * XOR Gate implementation.
     * Returns true if an odd number of inputs are true; otherwise, false.
     */
    static class XORGate implements BooleanGate {
        @Override
        public boolean evaluate(List<Boolean> inputs) {
            boolean result = false;
            for (boolean input : inputs) {
                result ^= input;
            }
            return result;
        }
    }

    /**
     * NAND Gate implementation.
     * Returns true if at least one input is false; otherwise, false.
     */
    static class NANDGate implements BooleanGate {
        @Override
        public boolean evaluate(List<Boolean> inputs) {
            return !new ANDGate().evaluate(inputs); // Equivalent to negation of AND
        }
    }

    /**
     * NOR Gate implementation.
     * Returns true if all inputs are false; otherwise, false.
     */
    static class NORGate implements BooleanGate {
        @Override
        public boolean evaluate(List<Boolean> inputs) {
            return !new ORGate().evaluate(inputs); // Equivalent to negation of OR
        }
    }
}

class Car {
