// java.awt.Robot kullanarak ekran goruntusu yakalayan yardimci sinif

/** Tum ekranin goruntusunu yakalayip PNG olarak diske kaydeder. */
public class EkranGoruntusuAlma {

    /** Ekran boyutunu tespit edip Robot ile anlik goruntu alarak dosyaya yazar. */
    public static void yakalaVeKaydet(String hedefDosyaAdi) throws AWTException, IOException {
        Dimension boyut = Toolkit.getDefaultToolkit().getScreenSize();
