        yakalaVeKaydet("ekran.png");
    }
}

/*
 * 
 * Bu ornekte, Calisan adinda bir sinif Serializable arayuzunu gerceklemektedir.
 * Bu sayede Calisan sinifindan olusturulan bir nesne ObjectOutputStream sinifi 
 * kullanilarak bir dosyaya serilestirilebilir. Daha sonra bu nesne, 
 * ObjectInputStream sinifi kullanilarak deserialization yoluyla dosyadan okunabilir.
 * Deserialization sonucu nesnenin orijinal durumu geri yuklenmektedir.
 * 
 */

public class Serilestirme {

	public static void main(String[] args) {

		// Yeni bir Calisan nesnesi olustur
		Calisan calisan = new Calisan("Ahmet Yilmaz", 54321, "Yazilim Muhendisi");

		// Nesneyi serilestir
		try {
			FileOutputStream dosyaCikisi = new FileOutputStream("calisan.ser");
			ObjectOutputStream cikisAkimi = new ObjectOutputStream(dosyaCikisi);
			cikisAkimi.writeObject(calisan);
			cikisAkimi.close();
			dosyaCikisi.close();
			System.out.println("Calisan nesnesi calisan.ser dosyasina serilestirildi.");
		} catch (IOException e) {
			e.printStackTrace();
		}

		// Nesneyi deserializasyon ile geri yukle
		Calisan geriYuklenenCalisan = null;
		try {
			FileInputStream dosyaGirisi = new FileInputStream("calisan.ser");
			ObjectInputStream girisAkimi = new ObjectInputStream(dosyaGirisi);
			geriYuklenenCalisan = (Calisan) girisAkimi.readObject();
			girisAkimi.close();
			dosyaGirisi.close();
		} catch (IOException e) {
			e.printStackTrace();
			return;
		} catch (ClassNotFoundException c) {
			System.out.println("Calisan sinifi bulunamadi.");
			c.printStackTrace();
			return;
		}

		// Geri yuklenen calisan bilgilerini yazdir
		System.out.println("Geri Yuklenen Calisan...");
		System.out.println("Isim: " + geriYuklenenCalisan.getIsim());
		System.out.println("ID: " + geriYuklenenCalisan.getID());
		System.out.println("Unvan: " + geriYuklenenCalisan.getUnvan());
	}
}

class Calisan implements Serializable {

	private static final long serialVersionUID = 1L;
	private String isim;
	private int ID;
	private String unvan;

	public Calisan(String isim, int ID, String unvan) {
		this.isim = isim;
		this.ID = ID;
		this.unvan = unvan;
	}

	public String getIsim() {
		return isim;
	}

	public int getID() {
		return ID;
	}

	public String getUnvan() {
		return unvan;
	}
}

public class SecondLargestElement {
    public static void main(String[] args) {
        int[] arr = {12, 35, 1, 10, 34, 1};

        int largest = Integer.MIN_VALUE;
        int secondLargest = Integer.MIN_VALUE;

        for (int value : arr) {
            if (value > largest) {
                secondLargest = largest;
                largest = value;
            } else if (value > secondLargest && value != largest) {
                secondLargest = value;
            }
        }

        System.out.println("Largest: " + largest);
        System.out.println("Second largest: " + secondLargest);
    }
}

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.BeforeEach;

/*
 * Notes on wiring up JUnit in Eclipse:
 *
 * Project Properties -> Java Build Path -> Libraries -> Add Library -> JUnit -> JUnit 3/4
 */

public class CalculatorTest {

    private Calculator math = new Calculator();

    @BeforeEach
    public void createFreshCalculator() {
        math = new Calculator();
    }

    @Test
    public void addsTwoNumbers() {
        assertEquals(5, math.add(2, 3));
        assertEquals(-1, math.add(-2, 1));
        assertEquals(0, math.add(-2, 2));
    }

    @Test
    public void subtractsTwoNumbers() {
        assertEquals(1, math.subtract(3, 2));
        assertEquals(-3, math.subtract(-2, 1));
        assertEquals(0, math.subtract(2, 2));
    }

    @Test
    public void multipliesTwoNumbers() {
        assertEquals(6, math.multiply(2, 3));
        assertEquals(-2, math.multiply(-2, 1));
        assertEquals(0, math.multiply(0, 2));
    }

    @Test
    public void dividesTwoNumbers() {
        assertEquals(2, math.divide(6, 3));
        assertEquals(-2, math.divide(-4, 2));

        Exception thrown = assertThrows(IllegalArgumentException.class, () -> {
            math.divide(1, 0);
        });

        assertEquals("Sifira bolme yapilamaz.", thrown.getMessage());
    }

    @Test
    public void computesModulus() {
        assertEquals(1, math.modulus(5, 2));
        assertEquals(0, math.modulus(4, 2));
        assertEquals(-1, math.modulus(-5, 2));
        assertEquals(0, math.modulus(0, 5));
    }

    @Test
    public void computesFactorial() {
        assertEquals(120, math.factorial(5));
        assertEquals(1, math.factorial(0));
        assertEquals(1, math.factorial(1));
        assertThrows(IllegalArgumentException.class, () -> math.factorial(-1));
    }

    @Test
    public void findsMaximum() {
        assertEquals(5, math.max(3, 5));
        assertEquals(-3, math.max(-3, -5));
        assertEquals(7, math.max(7, 7));
    }

    @Test
    public void findsMinimum() {
        assertEquals(3, math.min(3, 5));
        assertEquals(-5, math.min(-3, -5));
        assertEquals(7, math.min(7, 7));
    }

    @Test
    public void computesAverage() {
        assertEquals(3.0, math.average(2, 4), 0.001);
        assertEquals(5.5, math.average(5, 6), 0.001);
        assertEquals(-2.0, math.average(-4, -0), 0.001);
    }

    @Test
    public void raisesToPower() {
        assertEquals(8, math.power(2, 3), 0.001);
        assertEquals(1, math.power(5, 0), 0.001);
        assertEquals(-8, math.power(-2, 3), 0.001);
        assertEquals(0.25, math.power(2, -2), 0.001);
    }

    @Test
    public void computesSquareRoot() {
        assertEquals(3, math.squareRoot(9), 0.001);
        assertEquals(2, math.squareRoot(4), 0.001);

        Exception thrown = assertThrows(IllegalArgumentException.class, () -> {
            math.squareRoot(-4);
        });

        assertEquals("Negatif sayilarin karekoku hesaplanamaz.", thrown.getMessage());
    }
}

package com.ankan.inheritance;

interface Side {
    String getSide();
    }

class Head implements Side {
    public String getSide() {
        return "Head ";
    }
}
class Tail implements Side {
    public String getSide() {
        return "Tail ";
    }
}
class Coin {
    public static void overload(Head side) { System.out.print(side.getSide()); }
    public static void overload(Tail side) { System.out.print(side.getSide()); }
    public static void overload(Side side) { System.out.print("Side "); }
    public static void overload(Object side) { System.out.print("Object "); }
    public static void main(String []args) {
        Side firstAttempt = new Head();
        Tail secondAttempt = new Tail();
        overload(firstAttempt);
        overload((Object)firstAttempt);
        overload(secondAttempt);
        overload((Side)secondAttempt);
    }
}

public class ArrayListOrnegi {

	public static void main(String[] args) {

		// ArrayList tanimla ve isimler listesi olustur
		ArrayList<String> isimler = new ArrayList<>();

		// Listeye eleman ekle
		isimler.add("Alice");
		isimler.add("Bob");
		isimler.add("Charlie");
		isimler.add("Dave");
		isimler.add("Eve");

		// Orijinal listeyi ekrana yazdir
		System.out.println("Orijinal liste: " + isimler);

		// "Dave" yerine "Carol" ekle
		isimler.set(3, "Carol");
		System.out.println("Degistirilmis liste: " + isimler);

		// "Eve"yi listeden kaldir
		isimler.remove(4);
		System.out.println("Degistirilmis liste: " + isimler);

		// "Frank"i index 2'ye ekle
		isimler.add(2, "Frank");
		System.out.println("Degistirilmis liste: " + isimler);

		// "Bob"un index'ini bul
		int index = isimler.indexOf("Bob");
		System.out.println("Bob'un index'i: " + index);

		// Liste "Eve"yi iceriyor mu kontrol et
		boolean iceriyorMu = isimler.contains("Eve");
		System.out.println("Liste 'Eve'yi iceriyor mu: " + iceriyorMu);

		// Listenin boyutunu al
		int boyut = isimler.size();
		System.out.println("Listenin boyutu: " + boyut);
	}
}

package ifcondition;
import java.util.Scanner;

public class NotHesaplama {

	// Sayisal notu karsilik gelen harf notuna cevirip ekrana basar
	public static void notuGoster(int puan) {
		char harf;

		if (puan < 60) {
			harf = 'F';
		} else if (puan < 70) {
			harf = 'D';
		} else if (puan < 80) {
			harf = 'C';
		} else if (puan < 90) {
			harf = 'B';
		} else {
			harf = 'A';
		}

		System.out.println(harf);
	}

	public static void main(String[] args) {

		Scanner tarayici = new Scanner(System.in);

		System.out.print("Notunuzu girin: ");
		int ogrenciNotu = tarayici.nextInt();

		notuGoster(ogrenciNotu);

		tarayici.close();
	}
}

