public class ArrayStatistics {
    public static void main(String[] args) {
        int[] numbers = {12, 45, 7, 23, 56, 89, 34};

        int min = numbers[0];
        int max = numbers[0];
        int sum = 0;

        for (int number : numbers) {
            if (number < min) min = number;
            if (number > max) max = number;
            sum += number;
        }

        double average = (double) sum / numbers.length;

        System.out.println("Min: " + min);
        System.out.println("Max: " + max);
        System.out.println("Sum: " + sum);
        System.out.printf("Average: %.2f%n", average);
    }
}

/**
 * The Atbash cipher is a classic substitution cipher that substitutes each letter
 * with its opposite letter in the alphabet.
 *
 * For example:
 * - 'A' becomes 'Z', 'B' becomes 'Y', 'C' becomes 'X', and so on.
 * - Similarly, 'a' becomes 'z', 'b' becomes 'y', and so on.
 *
 * The cipher works identically for both uppercase and lowercase letters.
 * Non-alphabetical characters remain unchanged in the output.
 *
 * This cipher is symmetric, meaning that applying the cipher twice will return
 * the original text. Therefore, the same function is used for both encryption and decryption.
 *
 * <p>Usage Example:</p>
 * <pre>
 * AtbashCipher cipher = new AtbashCipher("Hello World!");
 * String encrypted = cipher.convert(); // Output: "Svool Dliow!"
 * </pre>
 *
 * @author <a href="https://github.com/Krounosity">Krounosity</a>
 * @see <a href="https://en.wikipedia.org/wiki/Atbash">Atbash Cipher (Wikipedia)</a>
 */
public class AtbashCipher {

private String inputString;

public AtbashCipher() {
}

/**
 * Constructor with a string parameter.
 *
 * @param rawText The string to be converted using the Atbash cipher
 */
public AtbashCipher(String rawText) {
this.inputString = rawText;
}

/**
 * Returns the current string set for conversion.
 *
 * @return The string to be converted
 */
public String getString() {
return inputString;
}

/**
 * Sets the string to be converted using the Atbash cipher.
 *
 * @param rawText The new string to convert
 */
public void setString(String rawText) {
this.inputString = rawText;
}

/**
 * Checks if a character is uppercase.
 *
 * @param symbol The character to check
 * @return {@code true} if the character is uppercase, {@code false} otherwise
 */
private boolean isCapital(char symbol) {
return symbol >= 'A' && symbol <= 'Z';
}

/**
 * Checks if a character is lowercase.
 *
 * @param symbol The character to check
 * @return {@code true} if the character is lowercase, {@code false} otherwise
 */
private boolean isSmall(char symbol) {
return symbol >= 'a' && symbol <= 'z';
}

/**
 * Converts the input string using the Atbash cipher.
 * Alphabetic characters are substituted with their opposite in the alphabet,
 * while non-alphabetic characters remain unchanged.
 *
 * @return The converted string after applying the Atbash cipher
 */
public String convert() {
StringBuilder convertedResult = new StringBuilder();
for (char currentSymbol : inputString.toCharArray()) {
if (isSmall(currentSymbol)) {
convertedResult.append((char) ('z' - (currentSymbol - 'a')));
} else if (isCapital(currentSymbol)) {
convertedResult.append((char) ('Z' - (currentSymbol - 'A')));
} else {
convertedResult.append(currentSymbol);
}
}
return convertedResult.toString();
}
}

package com.thealgorithms.maths;

import java.util.ArrayList;
import java.util.Collection;

/**
 * Class for circular convolution of two discrete signals using the convolution
 * theorem.
 *
 * @author Ioannis Karavitsis
 * @version 1.0
 */
public final class CircularConvolutionFFT {
    private CircularConvolutionFFT() {
    }

    /**
     * This method pads the signal with zeros until it reaches the new size.
     *
     * @param x The signal to be padded.
     * @param newSize The new size of the signal.
     */
    private static void padding(Collection<FFT.Complex> x, int newSize) {
        if (x.size() < newSize) {
            int diff = newSize - x.size();
            for (int i = 0; i < diff; i++) {
                x.add(new FFT.Complex());
            }
        }
    }

    /**
     * Discrete circular convolution function. It uses the convolution theorem
     * for discrete signals: convolved = IDFT(DFT(a)*DFT(b)). Then we use the
     * FFT algorithm for faster calculations of the two DFTs and the final IDFT.
     *
     * <p>
     * More info: https://en.wikipedia.org/wiki/Convolution_theorem
     *
     * @param a The first signal.
     * @param b The other signal.
     * @return The convolved signal.
     */
    public static ArrayList<FFT.Complex> fftCircularConvolution(ArrayList<FFT.Complex> a, ArrayList<FFT.Complex> b) {
        int convolvedSize = Math.max(a.size(), b.size()); // The two signals must have the same size equal to the bigger one
        padding(a, convolvedSize); // Zero padding the smaller signal
        padding(b, convolvedSize);

        /* Find the FFTs of both signal. Here we use the Bluestein algorithm because we want the FFT
         * to have the same length with the signal and not bigger */
        FFTBluestein.fftBluestein(a, false);
        FFTBluestein.fftBluestein(b, false);
        ArrayList<FFT.Complex> convolved = new ArrayList<>();

        for (int i = 0; i < a.size(); i++) {
            convolved.add(a.get(i).multiply(b.get(i))); // FFT(a)*FFT(b)
        }
        FFTBluestein.fftBluestein(convolved, true); // IFFT

        return convolved;
    }
}

