/**
 * An implementation of Edmonds's algorithm (also known as the Chu–Liu/Edmonds algorithm)
 * for finding a Minimum Spanning Arborescence (MSA).
 *
 * <p>An MSA is a directed graph equivalent of a Minimum Spanning Tree. It is a tree rooted
 * at a specific vertex 'r' that reaches all other vertices, such that the sum of the
 * weights of its edges is minimized.
 *
 * <p>The algorithm works recursively:
 * <ol>
 * <li>For each vertex other than the root, select the incoming edge with the minimum weight.</li>
 * <li>If the selected edges form a spanning arborescence, it is the MSA.</li>
 * <li>If cycles are formed, contract each cycle into a new "supernode".</li>
 * <li>Modify the weights of edges entering the new supernode.</li>
 * <li>Recursively call the algorithm on the contracted graph.</li>
 * <li>The final cost is the sum of the initial edge selections and the result of the recursive call.</li>
 * </ol>
 *
 * <p>Time Complexity: O(E * V) where E is the number of edges and V is the number of vertices.
 *
 * <p>References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Edmonds%27_algorithm">Wikipedia: Edmonds's algorithm</a></li>
 * </ul>
 */
public final class Edmonds {

    private Edmonds() {
    }

    /**
     * Represents a directed weighted edge in the graph.
     */
    public static class Edge {
        final int from;
        final int to;
        final long weight;

        /**
         * Constructs a directed edge.
         *
         * @param from source vertex
         * @param to destination vertex
         * @param weight edge weight
         */
        public Edge(int from, int to, long weight) {
            this.from = from;
            this.to = to;
            this.weight = weight;
        }
    }

    /**
     * Computes the total weight of the Minimum Spanning Arborescence of a directed,
     * weighted graph from a given root.
     *
     * @param numVertices the number of vertices, labeled {@code 0..numVertices-1}
     * @param edges list of directed edges in the graph
     * @param root the root vertex
     * @return the total weight of the MSA. Returns -1 if not all vertices are reachable
     *         from the root or if a valid arborescence cannot be formed.
     * @throws IllegalArgumentException if {@code numVertices <= 0} or {@code root} is out of range.
     */
    public static long findMinimumSpanningArborescence(int numVertices, List<Edge> edges, int root) {
        if (root < 0 || root >= numVertices) {
            throw new IllegalArgumentException("Invalid number of vertices or root");
        }
        if (numVertices == 1) {
            return 0;
        }

        return findMSARecursive(numVertices, edges, root);
    }

    /**
     * Recursive helper method for finding MSA.
     */
    private static long findMSARecursive(int n, List<Edge> edges, int root) {
        long[] minWeightEdge = new long[n];
        int[] predecessor = new int[n];
        Arrays.fill(minWeightEdge, Long.MAX_VALUE);
        Arrays.fill(predecessor, -1);

        for (Edge edge : edges) {
            if (edge.to != root && edge.weight < minWeightEdge[edge.to]) {
                minWeightEdge[edge.to] = edge.weight;
                predecessor[edge.to] = edge.from;
            }
        }
        // Check if all non-root nodes are reachable
        for (int i = 0; i < n; i++) {
            if (i != root && minWeightEdge[i] == Long.MAX_VALUE) {
                return -1; // No spanning arborescence exists
            }
        }
        int[] cycleId = new int[n];
        Arrays.fill(cycleId, -1);
        boolean[] visited = new boolean[n];
        int cycleCount = 0;

        for (int i = 0; i < n; i++) {
            if (visited[i]) {
                continue;
            }

            List<Integer> path = new ArrayList<>();
            int curr = i;

            // Follow predecessor chain
            while (curr != -1 && !visited[curr]) {
                visited[curr] = true;
                path.add(curr);
                curr = predecessor[curr];
            }

            // If we hit a visited node, check if it forms a cycle
            if (curr != -1) {
                boolean inCycle = false;
                for (int node : path) {
                    if (node == curr) {
                        inCycle = true;
                    }
                    if (inCycle) {
                        cycleId[node] = cycleCount;
                    }
                }
                if (inCycle) {
                    cycleCount++;
                }
            }
        }
        if (cycleCount == 0) {
            long totalWeight = 0;
            for (int i = 0; i < n; i++) {
                if (i != root) {
                    totalWeight += minWeightEdge[i];
                }
            }
            return totalWeight;
        }
        long cycleWeightSum = 0;
        for (int i = 0; i < n; i++) {
            if (cycleId[i] >= 0) {
                cycleWeightSum += minWeightEdge[i];
            }
        }

        // Map old nodes to new nodes (cycles become supernodes)
        int[] newNodeMap = new int[n];
        int[] cycleToNewNode = new int[cycleCount];
        int newN = 0;

        // Assign new node IDs to cycles first
        for (int i = 0; i < cycleCount; i++) {
            cycleToNewNode[i] = newN++;
        }

        // Assign new node IDs to non-cycle nodes
        for (int i = 0; i < n; i++) {
            if (cycleId[i] == -1) {
                newNodeMap[i] = newN++;
            } else {
                newNodeMap[i] = cycleToNewNode[cycleId[i]];
            }
        }

        int newRoot = newNodeMap[root];

        // Build contracted graph
        List<Edge> newEdges = new ArrayList<>();
        for (Edge edge : edges) {
            int uCycleId = cycleId[edge.from];
            int vCycleId = cycleId[edge.to];

            // Skip edges internal to a cycle
            if (uCycleId >= 0 && uCycleId == vCycleId) {
                continue;
            }

            int newU = newNodeMap[edge.from];
            int newV = newNodeMap[edge.to];

            long newWeight = edge.weight;
            // Adjust weight for edges entering a cycle
            if (vCycleId >= 0) {
                newWeight -= minWeightEdge[edge.to];
            }

            if (newU != newV) {
                newEdges.add(new Edge(newU, newV, newWeight));
            }
        }
        return cycleWeightSum + findMSARecursive(newN, newEdges, newRoot);
    }
}

/**
 * This class contains a method to check if the binary representation of a number is a palindrome.
 * <p>
 *     A binary palindrome is a number whose binary representation is the same when read from left to right and right to left.
 *     For example, the number 9 has a binary representation of 1001, which is a palindrome.
 *     The number 10 has a binary representation of 1010, which is not a palindrome.
 * </p>
 *
 * @author Hardvan
 * @see <a href="https://en.wikipedia.org/wiki/Binary_palindrome">Binary Palindrome (Wikipedia)</a>
 */
public final class BinaryPalindromeCheck {

    // Private constructor to prevent instantiation (utility class)
    private BinaryPalindromeCheck() {
        throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
    }

    /**
     * Checks if the binary representation of a number is a palindrome.
     * 
     * <p>A binary palindrome reads the same forwards and backwards when
     * written in base-2 (binary) format without leading zeros.</p>
     * 
     * <p><b>Examples:</b></p>
     * <ul>
     *   <li>9 (1001) → true</li>
     *   <li>5 (101) → true</li>
     *   <li>10 (1010) → false</li>
     *   <li>0 (0) → true (by convention)</li>
     *   <li>1 (1) → true</li>
     * </ul>
     *
     * @param number The number to check (can be any non-negative integer)
     * @return {@code true} if the binary representation is a palindrome, {@code false} otherwise
     */
    public static boolean isBinaryPalindrome(int number) {
        // Handle edge case: 0 is considered a palindrome (binary representation "0")
        if (number < 0) {
            return false; // Negative numbers have a '-' sign, not considered binary palindromes
        }

        // Special case: single bit numbers are always palindromes
        if (number == 0 || number == 1) {
            return true;
        }

        int reversedBits = reverseBitsPreservingLength(number);
        return number == reversedBits;
    }

    /**
     * Alternative implementation that checks binary palindrome without reversing all bits.
     * This method uses two-pointer technique on the binary representation.
     * More efficient as it stops early when a mismatch is found.
     *
     * @param number The number to check
     * @return {@code true} if the binary representation is a palindrome, {@code false} otherwise
     */
    public static boolean isBinaryPalindromeTwoPointer(int number) {
        if (number < 0) {
            return false;
        }

        if (number == 0 || number == 1) {
            return true;
        }

        // Find the most significant bit position
        int mostSignificantBit = Integer.highestOneBit(number);

        int leftBitMask = mostSignificantBit;
        int rightBitMask = 1;

        // Compare bits from both ends moving toward the center
        while (leftBitMask > rightBitMask) {
            int leftBit = (number & leftBitMask) == 0 ? 0 : 1;
            int rightBit = (number & rightBitMask) == 0 ? 0 : 1;

            if (leftBit != rightBit) {
                return false;
            }

            leftBitMask >>= 1;
            rightBitMask <<= 1;
        }

        return true;
    }

    /**
     * Helper function to reverse all the bits of an integer while preserving the original bit length.
     * 
     * <p><b>Example:</b>
     * <br>Input: 13 (binary: 1101)
     * <br>Output: 11 (binary: 1011)</p>
     *
     * @param number The number to reverse the bits of
     * @return The number with bits reversed (leading zeros are not preserved)
     */
    private static int reverseBitsPreservingLength(int number) {
        int reversedResult = 0;

        // Count the number of bits to preserve (excluding leading zeros)
        int tempNumber = number;
        int bitCount = 0;
        while (tempNumber > 0) {
            bitCount++;
            tempNumber >>= 1;
        }

        // Reverse the bits
        tempNumber = number;
        for (int bitIndex = 0; bitIndex < bitCount; bitIndex++) {
            reversedResult <<= 1;
            reversedResult |= (tempNumber & 1);
            tempNumber >>= 1;
        }

        return reversedResult;
    }

    /**
     * Returns the binary representation of a number as a string.
     * Useful for debugging and visualization.
     *
     * @param number The number to convert
     * @return Binary string without leading zeros
     */
    public static String getBinaryString(int number) {
        if (number < 0) {
            return Integer.toBinaryString(number); // Shows 32-bit representation for negatives
        }
        if (number == 0) {
            return "0";
        }
        return Integer.toBinaryString(number);
    }

    /**
     * Checks if a binary string is a palindrome (utility method).
     *
     * @param binaryString The binary string to check
     * @return {@code true} if the string is a palindrome, {@code false} otherwise
     */
    public static boolean isBinaryStringPalindrome(String binaryString) {
        if (binaryString == null || binaryString.isEmpty()) {
            return false;
        }

        int leftIndex = 0;
        int rightIndex = binaryString.length() - 1;

        while (leftIndex < rightIndex) {
            if (binaryString.charAt(leftIndex) != binaryString.charAt(rightIndex)) {
                return false;
            }
            leftIndex++;
            rightIndex--;
        }
        return true;
    }
}

