public class LazySegmentTree {

    /**
     * Lazy Segment Tree
     *
     * @see
     *	<a href="https://www.geeksforgeeks.org/lazy-propagation-in-segment-tree/">
     */
    static class Node {

        private final int start;
        private final int end; // start and end of the segment represented by this node
        private int value; // value is the sum of all elements in the range [start, end)
        private int lazy; // lazied value that should be added to children nodes
        Node left;
        Node right; // left and right children

        Node(int start, int end, int value) {
            this.start = start;
            this.end = end;
            this.value = value;
            this.lazy = 0;
            this.left = null;
            this.right = null;
        }

        /**
         * Update the value of this node with the given value diff.
         *
         * @param diff The value to add to every index of this node range.
         */
        public void applyUpdate(int diff) {
            this.lazy += diff;
            this.value += (this.end - this.start) * diff;
        }

        /**
         * Shift the lazy value of this node to its children.
         */
        public void shift() {
            if (lazy == 0) {
                return;
            }
            if (this.left == null && this.right == null) {
                return;
            }
            this.value += this.lazy;
            if (this.left != null) {
                this.left.applyUpdate(this.lazy);
            }
            if (this.right != null) {
                this.right.applyUpdate(this.lazy);
            }
            this.lazy = 0;
        }

        /**
         * Create a new node that is the sum of this node and the given node.
         *
         * @param left The left Node of merging
         * @param right The right Node of merging
         * @return The new Node.
         */
        static Node merge(Node left, Node right) {
            if (left == null) {
                return right;
            }
            if (right == null) {
                return left;
            }
            Node result = new Node(left.start, right.end, left.value + right.value);
            result.left = left;
            result.right = right;
            return result;
        }

        public int getValue() {
            return value;
        }

        public Node getLeft() {
            return left;
        }

        public Node getRight() {
            return right;
        }
    }

    private final Node root;

    /**
     * Create a new LazySegmentTree with the given array.
     *
     * @param array The array to create the LazySegmentTree from.
     */
    public LazySegmentTree(int[] array) {
        this.root = buildTree(array, 0, array.length);
    }

    /**
     * Build a new LazySegmentTree from the given array in O(n) time.
     *
     * @param array The array to build the LazySegmentTree from.
     * @param start The start index of the current node.
     * @param end The end index of the current node.
     * @return The root of the new LazySegmentTree.
     */
    private Node buildTree(int[] array, int start, int end) {
        if (end - start < 2) {
            return new Node(start, end, array[start]);
        }
        int mid = (start + end) >> 1;
        Node left = buildTree(array, start, mid);
        Node right = buildTree(array, mid, end);
        return Node.merge(left, right);
    }

    /**
     * Update the value of given range with the given value diff in O(log n) time.
     *
     * @param left The left index of the range to update.
     * @param right The right index of the range to update.
     * @param diff The value to add to every index of the range.
     * @param curr The current node.
     */
    private void updateRange(int left, int right, int diff, Node curr) {
        if (left <= curr.start && curr.end <= right) {
            curr.applyUpdate(diff);
            return;
        }
        if (left >= curr.end || right <= curr.start) {
            return;
        }
        curr.shift();
        updateRange(left, right, diff, curr.left);
        updateRange(left, right, diff, curr.right);
        Node merge = Node.merge(curr.left, curr.right);
        curr.value = merge.value;
    }

    /**
     * Get Node of given range in O(log n) time.
     *
     * @param left The left index of the range to update.
     * @param right The right index of the range to update.
     * @return The Node representing the sum of the given range.
     */
    private Node getRange(int left, int right, Node curr) {
        if (left <= curr.start && curr.end <= right) {
            return curr;
        }
        if (left >= curr.end || right <= curr.start) {
            return null;
        }
        curr.shift();
        return Node.merge(getRange(left, right, curr.left), getRange(left, right, curr.right));
    }

    public int getRange(int left, int right) {
        Node result = getRange(left, right, root);
        return result == null ? 0 : result.getValue();
    }

    public void updateRange(int left, int right, int diff) {
        updateRange(left, right, diff, root);
    }

    public Node getRoot() {
        return root;
    }
}

package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.Map;

/**
 * Converts text to Morse code and vice-versa.
 * Text to Morse code: Each letter is separated by a space and each word is separated by a pipe (|).
 * Example: "HELLO WORLD" -> ".... . .-.. .-.. --- | .-- --- .-. .-.. -.."
 *
 * Morse code to text: Each letter is separated by a space and each word is separated by a pipe (|).
 * Example: ".... . .-.. .-.. --- | .-- --- .-. .-.. -.." -> "HELLO WORLD"
 *
 * Applications: Used in radio communications and algorithmic challenges.
 *
 * @author Hardvan
 */
public final class MorseCodeConverter {
    private MorseCodeConverter() {
    }

    private static final Map<Character, String> MORSE_MAP = new HashMap<>();
    private static final Map<String, Character> REVERSE_MAP = new HashMap<>();

    static {
        MORSE_MAP.put('A', ".-");
        MORSE_MAP.put('B', "-...");
        MORSE_MAP.put('C', "-.-.");
        MORSE_MAP.put('D', "-..");
        MORSE_MAP.put('E', ".");
        MORSE_MAP.put('F', "..-.");
        MORSE_MAP.put('G', "--.");
        MORSE_MAP.put('H', "....");
        MORSE_MAP.put('I', "..");
        MORSE_MAP.put('J', ".---");
        MORSE_MAP.put('K', "-.-");
        MORSE_MAP.put('L', ".-..");
        MORSE_MAP.put('M', "--");
        MORSE_MAP.put('N', "-.");
        MORSE_MAP.put('O', "---");
        MORSE_MAP.put('P', ".--.");
        MORSE_MAP.put('Q', "--.-");
        MORSE_MAP.put('R', ".-.");
        MORSE_MAP.put('S', "...");
        MORSE_MAP.put('T', "-");
        MORSE_MAP.put('U', "..-");
        MORSE_MAP.put('V', "...-");
        MORSE_MAP.put('W', ".--");
        MORSE_MAP.put('X', "-..-");
        MORSE_MAP.put('Y', "-.--");
        MORSE_MAP.put('Z', "--..");

        // Build reverse map for decoding
        MORSE_MAP.forEach((k, v) -> REVERSE_MAP.put(v, k));
    }

    /**
     * Converts text to Morse code.
     * Each letter is separated by a space and each word is separated by a pipe (|).
     *
     * @param text The text to convert to Morse code.
     * @return The Morse code representation of the text.
     */
    public static String textToMorse(String text) {
        StringBuilder morse = new StringBuilder();
        String[] words = text.toUpperCase().split(" ");
        for (int i = 0; i < words.length; i++) {
            for (char c : words[i].toCharArray()) {
                morse.append(MORSE_MAP.getOrDefault(c, "")).append(" ");
            }
            if (i < words.length - 1) {
                morse.append("| ");
            }
        }
        return morse.toString().trim();
    }

    /**
     * Converts Morse code to text.
     * Each letter is separated by a space and each word is separated by a pipe (|).
     *
     * @param morse The Morse code to convert to text.
     * @return The text representation of the Morse code.
     */
    public static String morseToText(String morse) {
        StringBuilder text = new StringBuilder();
        String[] words = morse.split(" \\| ");
        for (int i = 0; i < words.length; i++) {
            for (String code : words[i].split(" ")) {
                text.append(REVERSE_MAP.getOrDefault(code, '?'));
            }
            if (i < words.length - 1) {
                text.append(" ");
            }
        }
        return text.toString();
    }
}

// Source
// http://www.java2s.com/example/java-utility-method/bitset/increment-bitset-bits-int-size-9fd84.html
// package com.java2s;
// License from project: Open Source License


public final class Utils {
private Utils() {
}

public static boolean increment(BitSet bitData, int maxSize) {
int position = maxSize - 1;
while (position >= 0 && bitData.get(position)) {
bitData.set(position--, false);
}
if (position < 0) {
return false;
}
bitData.set(position, true);
return true;
}
}

/**
 * This class implements a Leftist Heap, which is a type of priority queue
 * that follows similar operations to a binary min-heap but allows for
 * unbalanced structures based on the leftist property.
 *
 * <p>
 * A Leftist Heap maintains the leftist property, which ensures that the
 * left subtree is heavier than the right subtree based on the
 * null-path length (npl) values. This allows for efficient merging
 * of heaps and supports operations like insertion, extraction of
 * the minimum element, and in-order traversal.
 * </p>
 *
 * <p>
 * For more information on Leftist Heaps, visit:
 * <a href="https://iq.opengenus.org/leftist-heap/">OpenGenus</a>
 * </p>
 */
public class LeftistHeap {
    // Node class representing each element in the Leftist Heap
    private static final class Node {
        private final int element;
        private int npl;
        private Node left;
        private Node right;

        // Node constructor that initializes the element and sets child pointers to null
        private Node(int element) {
            this.element = element;
            left = null;
            right = null;
            npl = 0;
        }
    }

    private Node root;

    // Constructor initializing an empty Leftist Heap
    public LeftistHeap() {
        root = null;
    }

    /**
     * Checks if the heap is empty.
     *
     * @return true if the heap is empty; false otherwise
     */
    public boolean isEmpty() {
        return root == null;
    }

    /**
     * Resets the heap to its initial state, effectively clearing all elements.
     */
    public void clear() {
        root = null; // Set root to null to clear the heap
    }

    /**
     * Merges the contents of another Leftist Heap into this one.
     *
     * @param h1 the LeftistHeap to be merged into this heap
     */
    public void merge(LeftistHeap h1) {
        // Merge the current heap with the provided heap and set the provided heap's root to null
        root = merge(root, h1.root);
        h1.root = null;
    }

    /**
     * Merges two nodes, maintaining the leftist property.
     *
     * @param a the first node
     * @param b the second node
     * @return the merged node maintaining the leftist property
     */
    public Node merge(Node a, Node b) {
        if (a == null) {
            return b;
        }

        if (b == null) {
            return a;
        }

        // Ensure that the leftist property is maintained
        if (a.element > b.element) {
            Node temp = a;
            a = b;
            b = temp;
        }

        // Merge the right child of node a with node b
        a.right = merge(a.right, b);

        // If left child is null, make right child the left child
        if (a.left == null) {
            a.left = a.right;
            a.right = null;
        } else {
            if (a.left.npl < a.right.npl) {
                Node temp = a.left;
                a.left = a.right;
                a.right = temp;
            }
            a.npl = a.right.npl + 1;
        }
        return a;
    }

    /**
     * Inserts a new element into the Leftist Heap.
     *
     * @param a the element to be inserted
     */
    public void insert(int a) {
        root = merge(new Node(a), root);
    }

    /**
     * Extracts and removes the minimum element from the heap.
     *
     * @return the minimum element in the heap, or -1 if the heap is empty
     */
    public int extractMin() {
        if (isEmpty()) {
            return -1;
        }

        int min = root.element;
        root = merge(root.left, root.right);
        return min;
    }

    /**
     * Returns a list of the elements in the heap in in-order traversal.
     *
     * @return an ArrayList containing the elements in in-order
     */
    public ArrayList<Integer> inOrder() {
        ArrayList<Integer> lst = new ArrayList<>();
        inOrderAux(root, lst);
        return new ArrayList<>(lst);
    }

    /**
     * Auxiliary function for in-order traversal
     *
     * @param n the current node
     * @param lst the list to store the elements in in-order
     */
    private void inOrderAux(Node n, ArrayList<Integer> lst) {
        if (n == null) {
            return;
        }
        inOrderAux(n.left, lst);
        lst.add(n.element);
        inOrderAux(n.right, lst);
    }
}

/**
 * A stack implementation using linked nodes, supporting unlimited size without an ArrayList.
 *
 * <p>Each node in the stack contains data of generic type {@code Item}, along with references
 * to the next and previous nodes, supporting typical stack operations.
 *
 * <p>The stack follows a Last-In-First-Out (LIFO) order where elements added last are
 * removed first. Supported operations include push, pop, and peek.
 *
 * @param <Item> the type of elements held in this stack
 */
public class NodeStack<Item> {

    /**
     * Node class representing each element in the stack.
     */
    private class Node {
        Item data;
        Node previous;

        Node(Item data) {
            this.data = data;
            this.previous = null;
        }
    }

    private Node head; // Top node in the stack
    private int size; // Number of elements in the stack

    /**
     * Constructs an empty NodeStack.
     */
    public NodeStack() {
        head = null;
        size = 0;
    }

    /**
     * Pushes an item onto the stack.
     *
     * @param item the item to be pushed onto the stack
     */
    public void push(Item item) {
        Node newNode = new Node(item);
        newNode.previous = head;
        head = newNode;
        size++;
    }

    /**
     * Removes and returns the item at the top of the stack.
     *
     * @return the item at the top of the stack, or {@code null} if the stack is empty
     * @throws IllegalStateException if the stack is empty
     */
    public Item pop() {
        if (isEmpty()) {
            throw new IllegalStateException("Cannot pop from an empty stack.");
        }
        Item data = head.data;
        head = head.previous;
        size--;
        return data;
    }

    /**
     * Returns the item at the top of the stack without removing it.
     *
     * @return the item at the top of the stack, or {@code null} if the stack is empty
     * @throws IllegalStateException if the stack is empty
     */
    public Item peek() {
        if (isEmpty()) {
            throw new IllegalStateException("Cannot peek from an empty stack.");
        }
        return head.data;
    }

    /**
     * Checks whether the stack is empty.
     *
     * @return {@code true} if the stack has no elements, {@code false} otherwise
     */
    public boolean isEmpty() {
        return head == null;
    }

    /**
     * Returns the number of elements currently in the stack.
     *
     * @return the size of the stack
     */
    public int size() {
        return size;
    }
}

package datatypes;

public class IntVeriTuruOrnegi {

    public static void main(String[] args) {

        // short ve int turunde birer degisken
        short kucukDeger = 32000;
        int genisDeger = 2147483647;

        System.out.println("Kisa Sayi: " + kucukDeger);
        System.out.println("Tam Sayi: " + genisDeger);

        // short + int islemi otomatik olarak int'e genisler
        int toplamSonuc = kucukDeger + genisDeger;
        System.out.println("Toplam: " + toplamSonuc);

        // iki short'un toplami da int turunde degerlendirilir
        short ikinciKucukDeger = 30000;
        int ikinciToplam = ikinciKucukDeger + ikinciKucukDeger;
        System.out.println("Toplam 2: " + ikinciToplam);

        // int turu uzerinde temel aritmetik islemler
        int farkSonuc = genisDeger - kucukDeger;
        int carpimSonuc = genisDeger * kucukDeger;
        int bolumSonuc = genisDeger / kucukDeger;
        int kalanSonuc = genisDeger % kucukDeger;

        System.out.println("Fark: " + farkSonuc);
        System.out.println("Carpim: " + carpimSonuc);
        System.out.println("Bolum: " + bolumSonuc);
        System.out.println("Kalan: " + kalanSonuc);

        // short ve int turlerinin sinir degerleri
        System.out.println("Short veri turunun maksimum degeri: " + Short.MAX_VALUE);
        System.out.println("Short veri turunun minimum degeri: " + Short.MIN_VALUE);
        System.out.println("Int veri turunun maksimum degeri: " + Integer.MAX_VALUE);
        System.out.println("Int veri turunun minimum degeri: " + Integer.MIN_VALUE);
    }
}

package tankgame;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.util.ArrayList;
import java.util.Random;

public class TankSavarOyunu extends JPanel implements ActionListener {

    private static final long serialVersionUID = 1L;
    private static final int PANEL_WIDTH = 800;
    private static final int PANEL_HEIGHT = 600;

    // Tanklar ve top listeleri
    private ArrayList<Tank> tanklar;
    private ArrayList<Top> toplar;
    private Tanksavar tanksavar;  // Sadece 1 tane tanksavar

    // Oyun durumu
    private boolean sol = false, sag = false;
    private boolean atesEt = false;  // Ates etme durumu

    // Rastgele sayi ureteci
    private Random rastgele;

    // Skor
    private int score;

    public TankSavarOyunu() {
        setPreferredSize(new Dimension(PANEL_WIDTH, PANEL_HEIGHT));
        setBackground(Color.GRAY);
        tanklar = new ArrayList<>();
        toplar = new ArrayList<>();
        rastgele = new Random();
        score = 0;  // Skor baslangicta 0

        // Zamanlayici (Oyunun surekli guncellenmesi icin)
        Timer zamanlayici = new Timer(1000 / 60, this);  // 60 FPS
        zamanlayici.start();

        // Her saniye yeni tank uretecek zamanlayici
        Timer tankZamanlayici = new Timer(1000, new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                int x = rastgele.nextInt(PANEL_WIDTH - 50); // Tanklarin x pozisyonu
                int y = 0; // Tanklarin y pozisyonu en ustte olacak sekilde 0
                int tankType = rastgele.nextInt(2);  // Rastgele tank turu sec (0: T-90MS, 1: Leopard 2A4)
                if (tankType == 0) {
                    tanklar.add(new TankT90MS(x, y));  // T-90MS tanki
                } else {
                    tanklar.add(new TankLeopard2A4(x, y));  // Leopard 2A4 tanki
                }
            }
        });
        tankZamanlayici.start();

        // Oyun basinda yalnizca 1 tane tanksavar olusturulur
        int x = rastgele.nextInt(PANEL_WIDTH - 50); // Tanksavarin yerlestirilecegi x pozisyonu
        int y = PANEL_HEIGHT - 60;  // Tanksavari ekranin alt kismina yerlestir

        tanksavar = new TanksavarJawelin(x, y);  // Jawelin tanksavari

        // Klavye girdileri icin dinleyici
        addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                int key = e.getKeyCode();
                if (key == KeyEvent.VK_LEFT) {
                    sol = true;
                } else if (key == KeyEvent.VK_RIGHT) {
                    sag = true;
                } else if (key == KeyEvent.VK_SPACE && !atesEt) {
                    atesEt = true;  // Space tusuna basildiginda ates etme islemi baslar
                }
            }

            @Override
            public void keyReleased(KeyEvent e) {
                int key = e.getKeyCode();
                if (key == KeyEvent.VK_LEFT) {
                    sol = false;
                } else if (key == KeyEvent.VK_RIGHT) {
                    sag = false;
                } else if (key == KeyEvent.VK_SPACE) {
                    atesEt = false;  // Space tusu birakildiginda ates etme islemi biter
                }
            }
        });
        setFocusable(true);
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        // Tanksavarin hareketi
        if (sol) {
            tanksavar.x -= 5;  // Sol tusuna basildiginda sola hareket et
        }
        if (sag) {
            tanksavar.x += 5;  // Sag tusuna basildiginda saga hareket et
        }

        // Tanklarin hareketi
        for (Tank tank : tanklar) {
            tank.tankKonum.y += tank.hiz;  // Tanklari hizlarina gore asagiya hareket ettir
        }

        // Toplarin hareketi
        ArrayList<Top> toplarSilinecek = new ArrayList<>();
        for (Top top : toplar) {
            top.topKonum.y -= 10;  // Topu yukariya hareket ettir
            if (top.topKonum.y < 0) {
                toplarSilinecek.add(top);  // Top ekranin disina cikarsa sil
            }
        }
        toplar.removeAll(toplarSilinecek);

        // Ates etme islemi (space tusuna basildiginda top eklenir)
        if (atesEt) {
            // Tanksavara uygun topu ekle
            toplar.add(tanksavar.topAt());
            atesEt = false;  // Ates ettikten sonra ates etme durumu sifirlanir
        }

        // Carpisma kontrolu: Toplar tanklarla carpisiyor mu?
        ArrayList<Tank> tanklarSilinecek = new ArrayList<>();

        for (Top top : toplar) {
            for (Tank tank : tanklar) {
                if (top.topKonum.intersects(tank.tankKonum)) {  // Carpisma tespiti
                    tanklarSilinecek.add(tank);  // Carpisan tanki silmek icin isaretle
                    toplarSilinecek.add(top);  // Carpisan topu silmek icin isaretle
                    score++;  // Skoru bir arttir
                }
            }
        }

        if(score % 10 == 0) {
        	if(tanksavar instanceof TanksavarJawelin) {
        		tanksavar = new TanksavarTow2A(tanksavar.x, tanksavar.y);  // Tow2A tanksavari
        	} else if(tanksavar instanceof TanksavarTow2A){
        		tanksavar = new TanksavarJawelin(tanksavar.x, tanksavar.y);  // Jawelin tanksavari
        	}
        	score++;
        }

        // Carpisan tanklari ve toplari listeden sil
        tanklar.removeAll(tanklarSilinecek);
        toplar.removeAll(toplarSilinecek);

        // Paneli yeniden ciz
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);

        // Tanklari ciz
        for (Tank tank : tanklar) {
            g.setColor(tank.renk);
            g.fillRect(tank.tankKonum.x, tank.tankKonum.y, tank.tankKonum.width, tank.tankKonum.height);
        }

        // Tanksavari ciz
        g.setColor(tanksavar.renk);
        g.fillRect(tanksavar.x, tanksavar.y, tanksavar.genislik, tanksavar.yukseklik);

        // Toplari ciz
        for (Top top : toplar) {
            g.setColor(top.renk);  // Toplarin kendine ait rengini kullan
            g.fillRect(top.topKonum.x, top.topKonum.y, top.topKonum.width, top.topKonum.height);
        }

        // Skoru ekranda goster
        g.setColor(Color.WHITE);
        g.setFont(new Font("Arial", Font.BOLD, 20));
        g.drawString("Skor: " + score, 10, 20);
    }

    public static void main(String[] args) {
        JFrame frame = new JFrame("Tank Savar Oyunu");
        TankSavarOyunu oyun = new TankSavarOyunu();
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.add(oyun);
        frame.pack();
        frame.setVisible(true);
    }
}

