/**
 * A worker paid hourly at a fixed rate.
 */
public class Worker extends Person {

    private double hrs;
    final double RATE = 5.5;

    public Worker(String name, double hrs) {
        super(name);
        this.hrs = hrs;
    }

    public Worker(double hrs) {
        this.hrs = hrs;
    }

    public Worker() {
    }

    @Override
    public void display() {
        super.display();
        System.out.println("Hourse: " + hrs);
        System.out.println("RATE: " + RATE);
        System.out.println("Salary: " + getSalary());
    }

    @Override
    public double getSalary() {
        return hrs * RATE;
    }
}

package DTO;

import java.util.Scanner;

/**
 * A vase, which is an Item with a height and material.
 */
public class Vase extends Item {

    private int height;
    private String material;

    public Vase() {
    }

    public Vase(int value, String creator, int height, String material) {
        super(value, creator);
        this.height = height;
        this.material = material;
    }

    public int getHeight() {
        return height;
    }

    public void setHeight(int height) {
        this.height = height;
    }

    public String getMaterial() {
        return material;
    }

    public void setMaterial(String material) {
        this.material = material;
    }

    @Override
    public String toString() {
        return "Vase[" + super.toString() + ",height=" + height + ",material=" + material + ']';
    }

    public void inputVase() {
        super.input();
        Scanner scanner = new Scanner(System.in);
        System.out.print("Input a height: ");
        height = scanner.nextInt();
        scanner.nextLine();
        System.out.print("Input a material: ");
        material = scanner.nextLine();
    }

    public void outputVase() {
        super.output();
        System.out.println("Height: " + height);
        System.out.println("Material: " + material);
    }
}

package MyTriangle;

/**
 * A triangle composed of three MyPoint vertices.
 */
class MyPoint {

    private int x;
    private int y;

    public MyPoint() {
    }

    public MyPoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int[] getXY() {
        return new int[]{x, y};
    }

    public void setXY(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public double distance(int x, int y) {
        return Math.sqrt(Math.pow(x - this.x, 2) + Math.pow(y - this.y, 2));
    }

    public double distance(MyPoint another) {
        return Math.sqrt(Math.pow(another.x - x, 2) + Math.pow(another.y - y, 2));
    }

    public double distance() {
        return Math.sqrt(Math.pow(-x, 2) + Math.pow(-y, 2));
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ')';
    }
}

public class MyTriangle {
    private MyPoint v1;
    private MyPoint v2;
    private MyPoint v3;

    public MyTriangle(int x1, int y1, int x2, int y2, int x3, int y3) {
        this.v1 = new MyPoint(x1, y1);
        this.v2 = new MyPoint(x2, y2);
        this.v3 = new MyPoint(x3, y3);
    }

    public MyTriangle(MyPoint v1, MyPoint v2, MyPoint v3) {
        this.v1 = v1;
        this.v2 = v2;
        this.v3 = v3;
    }

    public MyPoint getV1() {
        return v1;
    }

    public void setV1(MyPoint v1) {
        this.v1 = v1;
    }

    public MyPoint getV2() {
        return v2;
    }

    public void setV2(MyPoint v2) {
        this.v2 = v2;
    }

    public MyPoint getV3() {
        return v3;
    }

    public void setV3(MyPoint v3) {
        this.v3 = v3;
    }

    public double getPerimeter() {
        return v1.distance(v2) + v2.distance(v3) + v3.distance(v1);
    }

    public String getType() {
        double side12 = v1.distance(v2);
        double side23 = v2.distance(v3);
        double side31 = v3.distance(v1);
        if (side12 == side23 && side12 == side31) {
            return "Equilateral";
        } else if (side12 == side23 || side12 == side31 || side31 == side23) {
            return "Isosceles";
        } else {
            return "Scalene";
        }
    }

    @Override
    public String toString() {
        return "MyTriangle[v1=" + v1.toString() + ",v2=" + v2.toString() + ",v3=" + v3.toString() + ']';
    }
}

class TestMyTriangle {
    public static void main(String[] args) {
        MyTriangle myTriangle = new MyTriangle(new MyPoint(5, 5), new MyPoint(15, 15), new MyPoint(5, 25));
        System.out.println(myTriangle.getPerimeter());
        System.out.println(myTriangle.getType());
        System.out.println(myTriangle.getV1());
        System.out.println(myTriangle.getV2());
        System.out.println(myTriangle.getV3());
        System.out.println(myTriangle.toString());
    }
}

