package com.thealgorithms.ciphers;

import java.math.BigInteger;

public final class DiffieHellman {

    private final BigInteger base;
    private final BigInteger secret;
    private final BigInteger prime;

    // Constructor to initialize base, secret, and prime
    public DiffieHellman(BigInteger base, BigInteger secret, BigInteger prime) {
        // Check for non-null and positive values
        if (base == null || secret == null || prime == null || base.signum() <= 0 || secret.signum() <= 0 || prime.signum() <= 0) {
            throw new IllegalArgumentException("Base, secret, and prime must be non-null and positive values.");
        }
        this.base = base;
        this.secret = secret;
        this.prime = prime;
    }

    // Method to calculate public value (g^x mod p)
    public BigInteger calculatePublicValue() {
        // Returns g^x mod p
        return base.modPow(secret, prime);
    }

    // Method to calculate the shared secret key (otherPublic^secret mod p)
    public BigInteger calculateSharedSecret(BigInteger otherPublicValue) {
        if (otherPublicValue == null || otherPublicValue.signum() <= 0) {
            throw new IllegalArgumentException("Other public value must be non-null and positive.");
        }
        // Returns b^x mod p or a^y mod p
        return otherPublicValue.modPow(secret, prime);
    }
}

/*
 * Models a rectangle with width and height, capable of computing
 * area, perimeter and diagonal (hypotenuse) length.
 */
public class Dikdortgen {

	private double boyutUzun;   // the rectangle's length
	private double boyutKisa;   // the rectangle's width

	public Dikdortgen(double boyutUzun, double boyutKisa) {
		this.boyutUzun = boyutUzun;
		this.boyutKisa = boyutKisa;
	}

	// Returns length * width.
	public double alanHesapla() {
		return boyutUzun * boyutKisa;
	}

	// Returns 2 * (length + width).
	public double cevreHesapla() {
		return 2 * (boyutUzun + boyutKisa);
	}

	// Replaces the current dimensions with new ones.
	public void alanGuncelle(double yeniBoyutUzun, double yeniBoyutKisa) {
		this.boyutUzun = yeniBoyutUzun;
		this.boyutKisa = yeniBoyutKisa;
	}

	@Override
	public String toString() {
		return "Uzunluk: " + boyutUzun + ", Genislik: " + boyutKisa + ", Alan: " + alanHesapla() + ", Cevre: " + cevreHesapla();
	}

	public static void main(String[] args) {

		Dikdortgen sekilBir = new Dikdortgen(10.0, 5.0);
		Dikdortgen sekilIki = new Dikdortgen(3.0, 7.0);
		Dikdortgen kareSekli = new Dikdortgen(4.0, 4.0); // a square is just a rectangle with equal sides

		System.out.println("Dikdortgen 1: " + sekilBir);
		System.out.println("Dikdortgen 2: " + sekilIki);
		System.out.println("Kare: " + kareSekli);

		sekilBir.alanGuncelle(12.0, 6.0);
		System.out.println("Guncellenmis Dikdortgen 1: " + sekilBir);

		double kosegenBir = sekilBir.hipotenusHesapla();
		double kosegenIki = sekilIki.hipotenusHesapla();
		double kosegenKare = kareSekli.hipotenusHesapla();

		System.out.println("Dikdortgen 1'in Hipotenusu: " + kosegenBir);
		System.out.println("Dikdortgen 2'nin Hipotenusu: " + kosegenIki);
		System.out.println("Karenin Hipotenusu: " + kosegenKare);

		if (sekilBir.alanHesapla() > sekilIki.alanHesapla()) {
			System.out.println("Dikdortgen 1'in alani, Dikdortgen 2'den buyuktur.");
		} else if (sekilBir.alanHesapla() < sekilIki.alanHesapla()) {
			System.out.println("Dikdortgen 2'nin alani, Dikdortgen 1'den buyuktur.");
		} else {
			System.out.println("Dikdortgen 1 ve Dikdortgen 2'nin alanlari esittir.");
		}
	}

	// Uses the Pythagorean theorem to compute the diagonal length.
	public double hipotenusHesapla() {
		return Math.sqrt(Math.pow(boyutUzun, 2) + Math.pow(boyutKisa, 2));
	}
}

package com.thealgorithms.datastructures.queues;

import java.util.NoSuchElementException;

/**
 * A [deque](https://en.wikipedia.org/wiki/Double-ended_queue) is short for a
 * double ended queue pronounced "deck" and sometimes referred to as a head-tail
 * linked list. A deque is a data structure based on a doubly linked list, but
 * only supports adding and removal of nodes from the beginning and the end of
 * the list.
 *
 * @author [Ian Cowan](https://github.com/iccowan)
 */
public class Deque<T> {

    /**
     * Node for the deque
     */
    private static class DequeNode<S> {
        S val;
        DequeNode<S> next = null;
        DequeNode<S> prev = null;

        DequeNode(S val) {
            this.val = val;
        }
    }

    private DequeNode<T> head = null;
    private DequeNode<T> tail = null;
    private int size = 0;

    /**
     * Adds the specified value to the head of the deque
     *
     * @param val Value to add to the deque
     */
    public void addFirst(T val) {
        DequeNode<T> newNode = new DequeNode<>(val);

        if (isEmpty()) {
            head = newNode;
            tail = newNode;
        } else {
            newNode.next = head;
            head.prev = newNode;
            head = newNode;
        }

        size++;
    }

    /**
     * Adds the specified value to the tail of the deque
     *
     * @param val Value to add to the deque
     */
    public void addLast(T val) {
        DequeNode<T> newNode = new DequeNode<>(val);
        if (tail == null) {
            head = newNode;
            tail = newNode;
        } else {
            newNode.prev = tail;
            tail.next = newNode;
            tail = newNode;
        }
        size++;
    }

    /**
     * Removes and returns the first (head) value in the deque
     *
     * @return the value of the head of the deque
     * @throws NoSuchElementException if the deque is empty
     */
    public T pollFirst() {
        if (head == null) {
            throw new NoSuchElementException("Deque is empty");
        }

        T oldHeadVal = head.val;
        if (head == tail) {
            head = null;
            tail = null;
        } else {
            head = head.next;
            head.prev = null;
        }
        size--;
        return oldHeadVal;
    }

    /**
     * Removes and returns the last (tail) value in the deque
     *
     * @return the value of the tail of the deque
     * @throws NoSuchElementException if the deque is empty
     */
    public T pollLast() {
        if (tail == null) {
            throw new NoSuchElementException("Deque is empty");
        }

        T oldTailVal = tail.val;
        if (head == tail) {
            head = null;
            tail = null;
        } else {
            tail = tail.prev;
            tail.next = null;
        }
        size--;
        return oldTailVal;
    }

    /**
     * Returns the first (head) value of the deque WITHOUT removing
     *
     * @return the value of the head of the deque, or null if empty
     */
    public T peekFirst() {
        return head != null ? head.val : null;
    }

    /**
     * Returns the last (tail) value of the deque WITHOUT removing
     *
     * @return the value of the tail of the deque, or null if empty
     */
    public T peekLast() {
        return tail != null ? tail.val : null;
    }

    /**
     * Returns the size of the deque
     *
     * @return the size of the deque
     */
    public int size() {
        return size;
    }

    /**
     * Returns whether or not the deque is empty
     *
     * @return whether or not the deque is empty
     */
    public boolean isEmpty() {
        return size == 0;
    }

    /**
     * Returns a stringified deque in a pretty form:
     *
     * <p>
     * Head -> 1 <-> 2 <-> 3 <- Tail
     *
     * @return the stringified deque
     */
    @Override
    public String toString() {
        StringBuilder dequeString = new StringBuilder("Head -> ");
        DequeNode<T> currNode = head;
        while (currNode != null) {
            dequeString.append(currNode.val);
            if (currNode.next != null) {
                dequeString.append(" <-> ");
            }
            currNode = currNode.next;
        }
        dequeString.append(" <- Tail");
        return dequeString.toString();
    }

    public static void main(String[] args) {
        Deque<Integer> myDeque = new Deque<>();
        for (int i = 0; i < 42; i++) {
            if (i / 42.0 < 0.5) {
                myDeque.addFirst(i);
            } else {
                myDeque.addLast(i);
            }
        }

        System.out.println(myDeque);
        System.out.println("Size: " + myDeque.size());
        System.out.println();

        myDeque.pollFirst();
        myDeque.pollFirst();
        myDeque.pollLast();
        System.out.println(myDeque);
        System.out.println("Size: " + myDeque.size());
        System.out.println();

        int dequeSize = myDeque.size();
        for (int i = 0; i < dequeSize; i++) {
            int removing = -1;
            if (i / 39.0 < 0.5) {
                removing = myDeque.pollFirst();
            } else {
                removing = myDeque.pollLast();
            }

            System.out.println("Removing: " + removing);
        }

        System.out.println(myDeque);
        System.out.println(myDeque.size());
    }
}

public class OgrenciNumarasi { // Ana sinif

    public static void main(String[] args) {

        // Kullanicidan ogrenci numarasini almak icin Scanner nesnesi olusturur.
        Scanner scanner = new Scanner(System.in);

        // Kullanicidan bir ogrenci numarasi girmesini ister.
        System.out.println("Ogrenci numarasini giriniz:");
        int numara = scanner.nextInt(); // Girilen ogrenci numarasini okur ve 'numara' degiskenine atar.

        // Ogrenci numarasinin ilk iki hanesi kayit yilini belirler. Bu iki hane 10000000'e bolunerek elde edilir.
        // 2000 yilina eklenerek ogrenci numarasindaki yil bilgisi cozulur.
        int kayityili = (numara / 10000000) + 2000;

        // Ogrencinin kayit yili ekrana yazdirilir.
        System.out.println("Kayit yili: " + kayityili);

        // Ogrenci numarasinin son uc hanesi, ogrencinin kayit sirasini gosterir.
        // Mod 1000 islemi ile bu uc hane alinir.
        int kayitsirasi = numara % 1000;

        // Kayit sirasi ekrana yazdirilir.
        System.out.println("Kayit sirasi: " + kayitsirasi);

        // Ogrenci numarasinin 5. hanesi ogrencinin bolumunu gosterir.
        // 100000'e bolunerek ilgili hane alinir ve mod 10 islemi ile bu hane elde edilir.
        int bolumu = (numara / 100000) % 10;

        // Bolum numarasina gore ogrencinin hangi bolumde oldugu belirlenir ve ekrana yazar.
        if(bolumu == 7) {
            // Eger bolum numarasi 7 ise Elektrik Elektronik bolumu yazdirilir.
            System.out.println("Bolum: Elektrik Elektronik");
        } else if (bolumu == 6) {
            // Eger bolum numarasi 6 ise Bilgisayar Muhendisligi bolumu yazdirilir.
            System.out.println("Bolum: Bilgisayar");
        } else if (bolumu == 5) {
            // Eger bolum numarasi 5 ise Makina Muhendisligi bolumu yazdirilir.
            System.out.println("Bolum: Makina");
        } else {
            // Eger bolum numarasi 5, 6 veya 7 degilse, bolum tanimlanmaz.
            System.out.println("Bilinmeyen bolum");
        }

        // Scanner nesnesini kapatir. Kaynak yonetimi acisindan onemli bir adimdir.
        scanner.close(); 
    }
}

/**
 * Exponential Moving Average (EMA) Filter for smoothing audio signals.
 *
 * <p>This filter applies an exponential moving average to a sequence of audio
 * signal values, making it useful for smoothing out rapid fluctuations.
 * The smoothing factor (alpha) controls the degree of smoothing.
 *
 * <p>Based on the definition from
 * <a href="https://en.wikipedia.org/wiki/Moving_average">Wikipedia link</a>.
 * 
 * <p><b>Application Example:</b>
 * <pre>
 * // Reduce noise in audio signal
 * double[] noisyAudio = {0.5, 0.8, 0.3, 0.9, 0.2};
 * EMAFilter smoother = new EMAFilter(0.3);
 * double[] smoothedAudio = smoother.apply(noisyAudio);
 * </pre>
 * 
 * @author The Algorithms Project
 * @version 1.0
 * @see <a href="https://en.wikipedia.org/wiki/Exponential_smoothing">Exponential Smoothing</a>
 */
public class EMAFilter {

    // Smoothing factor (alpha) - determines how much weight is given to new samples
    // Range: 0 < alpha <= 1
    // - Higher alpha = less smoothing (follows original signal closely)
    // - Lower alpha = more smoothing (stronger noise reduction)
    private final double smoothingFactor;

    // Current EMA value (state) - persists between apply() calls for continuous processing
    private double currentEmaValue;

    /**
     * Constructs an EMA filter with a specified smoothing factor.
     *
     * @param alphaValue Smoothing factor (0 < alphaValue <= 1)
     *                   Typical values: 0.1 (heavy smoothing), 0.5 (medium), 0.9 (light smoothing)
     * @throws IllegalArgumentException if alphaValue is outside the valid range (0, 1]
     */
    public EMAFilter(double alphaValue) {
        // Validate input parameter
        if (alphaValue <= 0 || alphaValue > 1) {
            throw new IllegalArgumentException(
                "Invalid smoothing factor: " + alphaValue + 
                ". Alpha must be between 0 and 1 (exclusive of 0, inclusive of 1)."
            );
        }
        this.smoothingFactor = alphaValue;
        this.currentEmaValue = 0.0; // Initialize EMA value (will be set on first sample)
    }

    /**
     * Applies the EMA filter to an entire audio signal array.
     * 
     * <p>The filter processes the signal one sample at a time using the recurrence relation:
     * <br>EMA(t) = α × signal(t) + (1-α) × EMA(t-1)
     * 
     * <p>The first sample is used as-is (EMA[0] = signal[0])
     *
     * @param audioSignal Raw audio signal array to be processed (must not be null)
     * @return Array of smoothed audio samples (same length as input)
     * @throws NullPointerException if audioSignal is null
     */
    public double[] apply(double[] audioSignal) {
        // Handle empty input gracefully
        if (audioSignal.length == 0) {
            return new double[0]; // Return empty array for empty input
        }

        // Create output array for smoothed results
        double[] smoothedSignal = new double[audioSignal.length];

        // Initialize EMA with the first sample (no smoothing applied to first value)
        currentEmaValue = audioSignal[0];
        smoothedSignal[0] = currentEmaValue;

        // Apply EMA recurrence formula for remaining samples
        for (int sampleIndex = 1; sampleIndex < audioSignal.length; sampleIndex++) {
            // EMA recurrence: new_value = α × current_sample + (1-α) × previous_EMA
            currentEmaValue = smoothingFactor * audioSignal[sampleIndex] + 
                              (1 - smoothingFactor) * currentEmaValue;
            smoothedSignal[sampleIndex] = currentEmaValue;
        }

        return smoothedSignal;
    }

    /**
     * Resets the internal EMA state to zero.
     * Use this method when starting to process a new, independent audio stream
     * to avoid carrying over previous signal influence.
     */
    public void resetState() {
        currentEmaValue = 0.0;
    }

    /**
     * Processes a single audio sample and returns the filtered result.
     * This method maintains state between calls, making it suitable for
     * real-time streaming audio processing.
     *
     * @param inputSample Raw audio sample value
     * @return Filtered (smoothed) sample value
     */
    public double processSample(double inputSample) {
        // If this is the first sample after reset, EMA = inputSample
        if (currentEmaValue == 0.0) {
            currentEmaValue = inputSample;
        } else {
            // Apply standard EMA recurrence
            currentEmaValue = smoothingFactor * inputSample + 
                              (1 - smoothingFactor) * currentEmaValue;
        }
        return currentEmaValue;
    }

    /**
     * Returns the current smoothing factor (alpha value).
     *
     * @return Current smoothing factor in range (0, 1]
     */
    public double getSmoothingFactor() {
        return smoothingFactor;
    }

    /**
     * Returns the current EMA value (internal state).
     * Useful for debugging or monitoring filter behavior.
     *
     * @return Current EMA value
     */
    public double getCurrentEmaValue() {
        return currentEmaValue;
    }
}

/*
COMPREHENSIVE TECHNICAL DOCUMENTATION
=====================================

EXPONENTIAL MOVING AVERAGE (EMA) FILTER
---------------------------------------

Mathematical Formula:
---------------------
EMA[t] = α × X[t] + (1-α) × EMA[t-1]

Where:
- EMA[t] = Filtered output at time t
- X[t]   = Raw input sample at time t
- α      = Smoothing factor (alpha) - determines filter responsiveness

How EMA Filter Works:
---------------------
1. Maintains a running average that weights recent samples more heavily
2. Older samples have exponentially decreasing influence
3. Unlike Simple Moving Average (SMA), EMA doesn't require storing a history window

Alpha Value Guidelines (Audio Applications):
--------------------------------------------
| Alpha Value | Smoothing Effect | Best For                           |
|-------------|------------------|------------------------------------|
| 0.05 - 0.1  | Heavy smoothing  | Strong noise reduction, slow changes|
| 0.2 - 0.3   | Moderate smoothing | General purpose, speech smoothing |
| 0.4 - 0.6   | Light smoothing  | Music, preserving transients       |
| 0.7 - 0.9   | Very light       | Quick response, minimal filtering  |
| 1.0         | No smoothing     | Passthrough (no effect)            |

Time Constant Relationship:
---------------------------
The relationship between alpha and time constant (τ):
α = 1 - e^(-T/τ), where T is the sampling period

For a given α, the effective window length (N) approximately:
N ≈ (2/α) - 1 samples

Example: α = 0.2 → effective window ≈ 9 samples

State Persistence Behavior:
---------------------------
- The filter maintains state (currentEmaValue) between apply() calls
- Process multiple chunks sequentially without losing history
- Use resetState() to start fresh when processing independent signals

Performance Characteristics:
----------------------------
- Time Complexity: O(n) per apply() call
- Space Complexity: O(n) for output array, O(1) for internal state
- Memory efficient: No need to store sample history

Common Audio Applications:
--------------------------
1. Envelope following (volume smoothing)
2. Noise gate smoothing
3. Parameter smoothing (avoiding sudden gain jumps)
4. Visualizing audio levels (VU meters)
5. Real-time audio effect parameter filtering

Physical Interpretation:
------------------------
EMA behaves like a first-order low-pass filter (RC circuit analog):
- α = 1 corresponds to no capacitor (pure resistor)
- α → 0 corresponds to infinite capacitor (heavy filtering)

Comparison with Other Filters:
-----------------------------
| Filter Type    | Advantages                    | Disadvantages                 |
|----------------|-------------------------------|-------------------------------|
| EMA (this)     | Simple, memory efficient      | Not symmetric (phase delay)   |
| SMA            | Simple, symmetric| Requires storage of N samples |
| Butterworth    | Very smooth, flat response    | Complex to implement          |
| Median Filter  | Excellent for impulse noise   | Higher computational cost     |
*/

import java.util.Scanner;

public class KesirliSayiToplama {

	public static void main(String[] args) {

		// Kullanicidan ondalikli iki deger okuyoruz
		Scanner girisOkuyucu = new Scanner(System.in);

		System.out.println("Birinci sayiyi giriniz: ");
		double ilkDeger = girisOkuyucu.nextDouble();

		System.out.println("ikinci sayiyi giriniz: ");
		double ikinciDeger = girisOkuyucu.nextDouble();

		girisOkuyucu.close();

		// Toplami ayri bir metotta hesaplatiyoruz
		double sonuc = topla(ilkDeger, ikinciDeger);

		System.out.println(ilkDeger + " ile " + ikinciDeger + " toplami: " + sonuc);
	}

	private static double topla(double a, double b) {
		return a + b;
	}
}

/**
 * This class provides a method to reverse the bits of a 32-bit integer.
 * Reversing the bits means that the least significant bit (LSB) becomes
 * the most significant bit (MSB) and vice versa.
 *
 * Example:
 * Input (binary): 00000010100101000001111010011100 (43261596)
 * Output (binary): 00111001011110000010100101000000 (964176192)
 *
 * Time Complexity: O(32) - A fixed number of 32 iterations
 * Space Complexity: O(1) - No extra space used
 *
 * Note:
 * - If the input is negative, Java handles it using two’s complement representation.
 * - This function works on 32-bit integers by default.
 *
 * @author Bama Charan Chhandogi
 */
public final class ReverseBits {
    private ReverseBits() {
    }

    /**
     * Reverses the bits of a 32-bit integer.
     *
     * @param n the integer whose bits are to be reversed
     * @return the integer obtained by reversing the bits of the input
     */
    public static int reverseBits(int n) {
        int result = 0;
        int bitCount = 32;
        for (int i = 0; i < bitCount; i++) {
            result <<= 1; // Left shift the result to make space for the next bit
            result |= (n & 1); // OR operation to set the least significant bit of result with the current bit of n
            n >>= 1; // Right shift n to move on to the next bit
        }
        return result;
    }
}

