package com.thealgorithms.conversions;

/**
 * A utility class to convert an octal (base-8) number into its binary (base-2) representation.
 *
 * <p>This class provides methods to:
 * <ul>
 *     <li>Convert an octal number to its binary equivalent</li>
 *     <li>Convert individual octal digits to binary</li>
 * </ul>
 *
 * <h2>Octal to Binary Conversion:</h2>
 * <p>An octal number is converted to binary by converting each octal digit to its 3-bit binary equivalent.
 * The result is a long representing the full binary equivalent of the octal number.</p>
 *
 * <h2>Example Usage</h2>
 * <pre>
 *   long binary = OctalToBinary.convertOctalToBinary(52); // Output: 101010 (52 in octal is 101010 in binary)
 * </pre>
 *
 * @author Bama Charan Chhandogi
 * @see <a href="https://en.wikipedia.org/wiki/Octal">Octal Number System</a>
 * @see <a href="https://en.wikipedia.org/wiki/Binary_number">Binary Number System</a>
 */
public final class OctalToBinary {
    private OctalToBinary() {
    }

    /**
     * Converts an octal number to its binary representation.
     *
     * <p>Each octal digit is individually converted to its 3-bit binary equivalent, and the binary
     * digits are concatenated to form the final binary number.</p>
     *
     * @param octalNumber the octal number to convert (non-negative integer)
     * @return the binary equivalent as a long
     */
    public static long convertOctalToBinary(int octalNumber) {
        long binaryNumber = 0;
        int digitPosition = 1;

        while (octalNumber != 0) {
            int octalDigit = octalNumber % 10;
            long binaryDigit = convertOctalDigitToBinary(octalDigit);

            binaryNumber += binaryDigit * digitPosition;

            octalNumber /= 10;
            digitPosition *= 1000;
        }

        return binaryNumber;
    }

    /**
     * Converts a single octal digit (0-7) to its binary equivalent.
     *
     * <p>For example:
     * <ul>
     *     <li>Octal digit 7 is converted to binary 111</li>
     *     <li>Octal digit 3 is converted to binary 011</li>
     * </ul>
     * </p>
     *
     * @param octalDigit a single octal digit (0-7)
     * @return the binary equivalent as a long
     */
    public static long convertOctalDigitToBinary(int octalDigit) {
        long binaryDigit = 0;
        int binaryMultiplier = 1;

        while (octalDigit != 0) {
            int octalDigitRemainder = octalDigit % 2;
            binaryDigit += octalDigitRemainder * binaryMultiplier;

            octalDigit /= 2;
            binaryMultiplier *= 10;
        }

        return binaryDigit;
    }
}

package DTO;

import java.util.Scanner;

/**
 * A painting, which is an Item with dimensions and style flags.
 */
public class Painting extends Item {
    private int height;
    private int width;
    private boolean isWatercolour;
    private boolean isFramed;

    public Painting() {
    }

    public Painting(int value, String creator, int height, int width, boolean isWatercolour, boolean isFramed) {
        super(value, creator);
        this.height = height;
        this.width = width;
        this.isWatercolour = isWatercolour;
        this.isFramed = isFramed;
    }

    public int getHeight() {
        return height;
    }

    public void setHeight(int height) {
        this.height = height;
    }

    public int getWidth() {
        return width;
    }

    public void setWidth(int width) {
        this.width = width;
    }

    public boolean isIsWatercolour() {
        return isWatercolour;
    }

    public void setIsWatercolour(boolean isWatercolour) {
        this.isWatercolour = isWatercolour;
    }

    public boolean isIsFramed() {
        return isFramed;
    }

    public void setIsFramed(boolean isFramed) {
        this.isFramed = isFramed;
    }

    @Override
    public String toString() {
        return "Painting[" + super.toString() + "height=" + height + ",width=" + width + ",isWatercolour=" + isWatercolour + ",isFramed=" + isFramed + ']';
    }

    public void inputPainting() {
        super.input();
        Scanner scanner = new Scanner(System.in);
        System.out.print("Input a height: ");
        height = scanner.nextInt();
        scanner.nextLine();
        System.out.print("Input a width: ");
        width = scanner.nextInt();
        scanner.nextLine();
        System.out.print("Is watercolour: ");
        isWatercolour = scanner.nextBoolean();
        scanner.nextLine();
        System.out.print("Is Framed: ");
        isFramed = scanner.nextBoolean();
        scanner.nextLine();
    }

    public void outputPainting() {
        super.output();
        System.out.println("Height: " + height);
        System.out.println("Width: " + width);
        System.out.println("Is Watercolour: " + isWatercolour);
        System.out.println("Is Framed: " + isFramed);
    }
}

public class Box {
    // Note: If declared as private, these variables would only be accessible within this class
    // Using default (package-private) access allows access from other classes in the same package
    double length;
    double height;
    double width;

    static void displayGreeting() {
        System.out.println("Greetings from the Box class! Hello there!");
    }

    // Default constructor - initializes Box with -1 values (represents invalid/empty state)
    Box() {
        this.height = -1;
        this.length = -1;
        this.width = -1;
    }

    // Constructor for creating a cube (all sides equal)
    // Calls the Object class constructor implicitly via super()
    Box(double sideLength) {
        this.length = sideLength;
        this.width = sideLength;
        this.height = sideLength;
    }

    // Parameterized constructor with all three dimensions
    Box(double boxLength, double boxHeight, double boxWidth) {
        this.length = boxLength;
        this.height = boxHeight;
        this.width = boxWidth;
    }

    // Copy constructor - creates a new Box from an existing Box object
    Box(Box existingBox) {
        this.length = existingBox.length;
        this.width = existingBox.width;
        this.height = existingBox.height;
    }

    public void displayInformation() {
        System.out.println("Box dimensions are currently accessible");
    }

    public void calculateAndDisplayVolume() {
        double volumeResult = length * width * height;
        System.out.println("Calculated volume: " + volumeResult);
        // Note: Original method only calculated volume without printing or returning
        // Enhanced version includes output for demonstration purposes
    }
}

