package Shape;

/**
 *
 * @author GIA KINH
 */
public class Square extends Rectangle{

    public Square() {
    }

    public Square(double side) {
        super(side, side);
    }

    public Square(double side, String color, boolean filled) {
        super(side, side, color, filled);
    }

    public double getSide(){
        return this.getLength();
    }

    public void setWidth(double side){
        super.setWidth(side);
        super.setLength(side);
    }

    public void setLength(double side){
        super.setWidth(side);
        super.setLength(side);
    }

    @Override
    public String toString(){
        return "Square["+super.toString()+"]";
    }
}

/**
 * A book with an array of Authors composed in.
 */
class Author {
    private String fullName;
    private String contactEmail;
    private char gender;

    public Author() {
    }

    public Author(String fullName, String contactEmail, char gender) {
        this.fullName = fullName;
        this.contactEmail = contactEmail;
        if (gender == 'm' || gender == 'f') {
            this.gender = gender;
        } else {
            System.out.println("Gender of 'm' or 'f'");
        }
    }

    public String getName() {
        return fullName;
    }

    public void setName(String fullName) {
        this.fullName = fullName;
    }

    public String getEmail() {
        return contactEmail;
    }

    public void setEmail(String contactEmail) {
        this.contactEmail = contactEmail;
    }

    public char getGender() {
        return gender;
    }

    public void setGender(char gender) {
        if (gender == 'm' || gender == 'f') {
            this.gender = gender;
        } else {
            System.out.println("Gender of 'm' or 'f'");
        }
    }

    @Override
    public String toString() {
        return "Author[name=" + fullName + ",email=" + contactEmail + ",gender=" + gender + ']';
    }
}

public class Book {
    private String title;
    private Author[] writers;
    private double price;
    private int qty;

    public Book() {
    }

    public Book(String title, Author[] writers, double price) {
        this.title = title;
        this.writers = writers;
        this.price = price;
    }

    public Book(String title, Author[] writers, double price, int qty) {
        this.title = title;
        this.writers = writers;
        this.price = price;
        this.qty = qty;
    }

    public String getName() {
        return title;
    }

    public void setName(String title) {
        this.title = title;
    }

    public Author[] getAuthors() {
        return writers;
    }

    public void setAuthors(Author[] writers) {
        this.writers = writers;
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        this.price = price;
    }

    public int getQty() {
        return qty;
    }

    public void setQty(int qty) {
        this.qty = qty;
    }

    public String getAuthorNames() {
        StringBuilder names = new StringBuilder();
        for (Author writer : writers) {
            names.append(writer.getName()).append(",");
        }
        names.deleteCharAt(names.length() - 1);
        return names.toString();
    }

    @Override
    public String toString() {
        StringBuilder joined = new StringBuilder();
        for (Author writer : writers) {
            joined.append(writer.toString()).append(",");
        }
        joined.deleteCharAt(joined.length() - 1);
        return "Book[name=" + title + ",author={" + joined + "},price=" + price + ",qty=" + qty + ']';
    }
}

