package com.thealgorithms.datastructures.caches;

import java.util.HashMap;
import java.util.Map;

/**
 * The {@code LFUCache} class implements a Least Frequently Used (LFU) cache.
 * An LFU cache evicts the least frequently used item when the cache reaches its capacity.
 * It maintains a mapping of keys to nodes, where each node contains the key, its associated value,
 * and a frequency count that tracks how many times the item has been accessed. A doubly linked list
 * is used to efficiently manage the ordering of items based on their usage frequency.
 *
 * <p>This implementation is designed to provide O(1) time complexity for both the {@code get} and
 * {@code put} operations, which is achieved through the use of a hashmap for quick access and a
 * doubly linked list for maintaining the order of item frequencies.</p>
 *
 * <p>
 * Reference: <a href="https://en.wikipedia.org/wiki/Least_frequently_used">LFU Cache - Wikipedia</a>
 * </p>
 *
 * @param <KeyType> The type of keys maintained by this cache.
 * @param <ValueType> The type of mapped values.
 *
 * @author Akshay Dubey (https://github.com/itsAkshayDubey)
 */
public class LFUCache<KeyType, ValueType> {

/**
 * The {@code CacheNode} class represents an element in the LFU cache.
 * Each node contains a key, a value, and a frequency count.
 * It also has pointers to the previous and next nodes in the doubly linked list.
 */
private class CacheNode {
private final KeyType nodeKey;
private ValueType nodeValue;
private int accessFrequency;
private CacheNode prevNode;
private CacheNode nextNode;

/**
 * Constructs a new {@code CacheNode} with the specified key, value, and frequency.
 *
 * @param inputKey The key associated with this node.
 * @param inputValue The value stored in this node.
 * @param initialFrequency The frequency of usage of this node.
 */
CacheNode(KeyType inputKey, ValueType inputValue, int initialFrequency) {
this.nodeKey = inputKey;
this.nodeValue = inputValue;
this.accessFrequency = initialFrequency;
}
}

private CacheNode headNode;
private CacheNode tailNode;
private final Map<KeyType, CacheNode> storageMap;
private final int maxCapacity;
private static final int DEFAULT_CAPACITY = 100;

/**
 * Constructs an LFU cache with the default capacity.
 */
public LFUCache() {
this(DEFAULT_CAPACITY);
}

/**
 * Constructs an LFU cache with the specified capacity.
 *
 * @param storageCapacity The maximum number of items that the cache can hold.
 * @throws IllegalArgumentException if the specified capacity is less than or equal to zero.
 */
public LFUCache(int storageCapacity) {
if (storageCapacity <= 0) {
throw new IllegalArgumentException("Capacity must be greater than zero.");
}
this.maxCapacity = storageCapacity;
this.storageMap = new HashMap<>();
}

/**
 * Retrieves the value associated with the given key from the cache.
 * If the key exists, the node's frequency is incremented, and the node is repositioned
 * in the linked list based on its updated frequency.
 *
 * @param searchKey The key whose associated value is to be returned.
 * @return The value associated with the key, or {@code null} if the key is not present in the cache.
 */
public ValueType get(KeyType searchKey) {
CacheNode targetNode = storageMap.get(searchKey);
if (targetNode == null) {
return null;
}
removeNodeFromList(targetNode);
targetNode.accessFrequency += 1;
insertNodeByFrequency(targetNode);
return targetNode.nodeValue;
}

/**
 * Inserts or updates a key-value pair in the cache.
 * If the key already exists, the value is updated and its frequency is incremented.
 * If the cache is full, the least frequently used item is removed before inserting the new item.
 *
 * @param insertKey The key associated with the value to be inserted or updated.
 * @param insertValue The value to be inserted or updated.
 */
public void put(KeyType insertKey, ValueType insertValue) {
if (storageMap.containsKey(insertKey)) {
CacheNode existingNode = storageMap.get(insertKey);
existingNode.nodeValue = insertValue;
existingNode.accessFrequency += 1;
removeNodeFromList(existingNode);
insertNodeByFrequency(existingNode);
} else {
if (storageMap.size() >= maxCapacity) {
storageMap.remove(this.headNode.nodeKey);
removeNodeFromList(headNode);
}
CacheNode newNode = new CacheNode(insertKey, insertValue, 1);
insertNodeByFrequency(newNode);
storageMap.put(insertKey, newNode);
}
}

/**
 * Adds a node to the linked list in the correct position based on its frequency.
 * The linked list is ordered by frequency, with the least frequently used node at the head.
 *
 * @param targetNode The node to be inserted into the list.
 */
private void insertNodeByFrequency(CacheNode targetNode) {
if (tailNode != null && headNode != null) {
CacheNode currentPointer = this.headNode;
while (true) {
if (currentPointer.accessFrequency > targetNode.accessFrequency) {
if (currentPointer == headNode) {
targetNode.nextNode = currentPointer;
currentPointer.prevNode = targetNode;
this.headNode = targetNode;
break;
} else {
targetNode.nextNode = currentPointer;
targetNode.prevNode = currentPointer.prevNode;
currentPointer.prevNode.nextNode = targetNode;
currentPointer.prevNode = targetNode;
break;
}
} else {
currentPointer = currentPointer.nextNode;
if (currentPointer == null) {
tailNode.nextNode = targetNode;
targetNode.prevNode = tailNode;
targetNode.nextNode = null;
tailNode = targetNode;
break;
}
}
}
} else {
tailNode = targetNode;
headNode = tailNode;
}
}

/**
 * Removes a node from the doubly linked list.
 * This method ensures that the pointers of neighboring nodes are properly updated.
 *
 * @param targetNode The node to be removed from the list.
 */
private void removeNodeFromList(CacheNode targetNode) {
if (targetNode.prevNode != null) {
targetNode.prevNode.nextNode = targetNode.nextNode;
} else {
this.headNode = targetNode.nextNode;
}
if (targetNode.nextNode != null) {
targetNode.nextNode.prevNode = targetNode.prevNode;
} else {
this.tailNode = targetNode.prevNode;
}
}
}

/**
 * Disjoint Set Union (DSU) with Union by Size.
 * This data structure tracks a set of elements partitioned into disjoint (non-overlapping) subsets.
 * It supports two primary operations efficiently:
 *
 * <ul>
 *     <li>Find: Determine which subset a particular element belongs to.</li>
 *     <li>Union: Merge two subsets into a single subset using union by size.</li>
 * </ul>
 *
 * Union by size always attaches the smaller tree under the root of the larger tree.
 * This helps keep the tree shallow, improving the efficiency of find operations.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Disjoint-set_data_structure">Disjoint Set Union (Wikipedia)</a>
 */
public class DisjointSetUnionBySize<ElementType> {
/**
 * Node class for DSU by size.
 * Each node keeps track of its parent and the size of the set it represents.
 */
public static class SetNode<ElementType> {
public ElementType storedValue;
public SetNode<ElementType> parentNode;
public int setSize;

public SetNode(ElementType elementValue) {
this.storedValue = elementValue;
this.parentNode = this;
this.setSize = 1;
}
}

/**
 * Creates a new disjoint set containing the single specified element.
 * @param elementValue the element to be placed in a new singleton set
 * @return a node representing the new set
 */
public SetNode<ElementType> createSet(final ElementType elementValue) {
return new SetNode<>(elementValue);
}

/**
 * Finds and returns the representative (root) of the set containing the given node.
 * This method applies path compression to flatten the tree structure for future efficiency.
 * @param targetNode the node whose set representative is to be found
 * @return the representative (root) node of the set
 */
public SetNode<ElementType> findRoot(SetNode<ElementType> targetNode) {
if (targetNode != targetNode.parentNode) {
targetNode.parentNode = findRoot(targetNode.parentNode);
}
return targetNode.parentNode;
}

/**
 * Merges the sets containing the two given nodes using union by size.
 * The root of the smaller set is attached to the root of the larger set.
 * @param firstNode a node in the first set
 * @param secondNode a node in the second set
 */
public void mergeSets(SetNode<ElementType> firstNode, SetNode<ElementType> secondNode) {
SetNode<ElementType> rootFirst = findRoot(firstNode);
SetNode<ElementType> rootSecond = findRoot(secondNode);
if (rootFirst == rootSecond) {
return;
}
if (rootFirst.setSize < rootSecond.setSize) {
rootFirst.parentNode = rootSecond;
rootSecond.setSize += rootFirst.setSize;
} else {
rootSecond.parentNode = rootFirst;
rootFirst.setSize += rootSecond.setSize;
}
}
}```

/**
 * N-Queens Problem: Place N queens on an N×N chessboard such that no two queens threaten each other.
 * 
 * <p><b>Problem Statement:</b><br>
 * Given an N×N chessboard, return all possible arrangements in which N queens can be placed
 * such that no two queens attack each other according to standard chess rules.
 * Queens attack horizontally, vertically, and diagonally.</p>
 * 
 * <p><b>Example (N = 4):</b>
 * <pre>
 * Solution 1:
 * . Q . .
 * . . . Q
 * Q . . .
 * . . Q .
 * 
 * Solution 2:
 * . . Q .
 * Q . . .
 * . . . Q
 * . Q . .
 * </pre>
 * </p>
 * 
 * <p><b>Algorithm Explanation:</b></p>
 * <ol>
 *   <li>Start with the first column and place queen on the first row</li>
 *   <li>Try placing queen in each row of the current column</li>
 *   <li>If placing queen in current cell doesn't attack any previously placed queens,
 *       recursively try to place queens in the next column</li>
 *   <li>If no valid row exists in current column, backtrack to previous column
 *       and try a different row position</li>
 *   <li>When all N queens are placed successfully, record the arrangement</li>
 *   <li>Continue searching for all possible arrangements</li>
 * </ol>
 * 
 * <p><b>Time Complexity:</b> O(N!) - The algorithm tries N! possible arrangements</p>
 * <p><b>Space Complexity:</b> O(N²) for storing board solutions plus O(N) recursion stack</p>
 * 
 * @see <a href="https://en.wikipedia.org/wiki/Eight_queens_puzzle">Eight Queens Puzzle (Wikipedia)</a>
 * @see <a href="https://en.wikipedia.org/wiki/Backtracking">Backtracking Algorithm</a>
 */
public final class NQueens {

    // Private constructor to prevent instantiation (utility class)
    private NQueens() {
        throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
    }

    // Queen representation constant
    private static final char QUEEN_SYMBOL = 'Q';
    private static final char EMPTY_SYMBOL = '.';

    /**
     * Returns all valid arrangements for placing N queens on an N×N board.
     *
     * @param boardSize The size of the board (N) and number of queens to place (must be >= 1)
     * @return List of arrangements, each arrangement is a list of strings representing the board
     * @throws IllegalArgumentException if boardSize is less than 1
     */
    public static List<List<String>> getAllNQueensSolutions(int boardSize) {
        if (boardSize < 1) {
            throw new IllegalArgumentException("Board size must be at least 1");
        }

        List<List<String>> validArrangements = new ArrayList<>();
        int[] columnPlacements = new int[boardSize]; // columns[i] = row where queen is placed in column i
        findQueenPlacements(boardSize, validArrangements, columnPlacements, 0);
        return validArrangements;
    }

    /**
     * Prints all valid N-Queens arrangements to the console.
     * 
     * <p>If no solutions exist, prints an appropriate message.
     * For N=1, there is 1 solution. For N=2 or N=3, there are no solutions.</p>
     *
     * @param boardSize The size of the board (N) and number of queens to place
     */
    public static void printAllNQueensArrangements(int boardSize) {
        List<List<String>> allSolutions = getAllNQueensSolutions(boardSize);

        if (allSolutions.isEmpty()) {
            System.out.printf("No valid arrangement exists to place %d queen(s) on a %dx%d board%n", 
                              boardSize, boardSize, boardSize);

            // Special cases explanation
            if (boardSize == 2) {
                System.out.println("Reason: Queens would always attack each other on a 2x2 board");
            } else if (boardSize == 3) {
                System.out.println("Reason: Queens would always attack each other on a 3x3 board");
            }
            return;
        }

        System.out.printf("Found %d distinct arrangement(s) for placing %d queen(s) on a %dx%d board:%n%n", 
                          allSolutions.size(), boardSize, boardSize, boardSize);

        for (int solutionIndex = 0; solutionIndex < allSolutions.size(); solutionIndex++) {
            System.out.printf("Solution #%d:%n", solutionIndex + 1);
            for (String boardRow : allSolutions.get(solutionIndex)) {
                System.out.println(boardRow);
            }
            System.out.println(); // Empty line between solutions
        }
    }

    /**
     * Recursive backtracking function that tries to place queens column by column.
     *
     * @param boardSize Size of the chess board (N)
     * @param validArrangements Collection to store all valid board arrangements
     * @param columnPlacements columns[i] = row index where queen is placed in column i
     * @param currentColumn The column index where queen is currently being placed (0..boardSize-1)
     */
    private static void findQueenPlacements(int boardSize, 
                                            List<List<String>> validArrangements,
                                            int[] columnPlacements, 
                                            int currentColumn) {
        // Base case: All queens have been placed successfully
        if (currentColumn == boardSize) {
            // Convert columnPlacements array to a visual board representation
            List<String> boardLayout = new ArrayList<>();
            for (int rowIndex = 0; rowIndex < boardSize; rowIndex++) {
                StringBuilder boardRow = new StringBuilder();
                for (int colIndex = 0; colIndex < boardSize; colIndex++) {
                    // Place 'Q' where the queen is positioned, otherwise '.'
                    if (colIndex == columnPlacements[rowIndex]) {
                        boardRow.append(QUEEN_SYMBOL);
                    } else {
                        boardRow.append(EMPTY_SYMBOL);
                    }
                }
                boardLayout.add(boardRow.toString());
            }
            validArrangements.add(boardLayout);
            return;
        }

        // Try placing queen in each row of the current column
        for (int candidateRow = 0; candidateRow < boardSize; candidateRow++) {
            columnPlacements[currentColumn] = candidateRow;

            // Check if queen can be placed safely at (candidateRow, currentColumn)
            if (isSafePlacement(columnPlacements, candidateRow, currentColumn)) {
                // Recursively try to place queens in the remaining columns
                findQueenPlacements(boardSize, validArrangements, columnPlacements, currentColumn + 1);
            }
            // If placement is unsafe or recursion fails, backtrack (implicitly by trying next row)
            // The columnPlacements[currentColumn] will be overwritten in the next loop iteration
        }
    }

    /**
     * Checks if placing a queen at (rowIndex, columnIndex) is safe given previously placed queens.
     * 
     * <p>A placement is safe if:</p>
     * <ul>
     *   <li>No other queen is in the same row (horizontal attack)</li>
     *   <li>No other queen is in the same diagonal (↖↗↘↙ attack)</li>
     *   <li>Vertical attacks are prevented by placing only one queen per column</li>
     * </ul>
     *
     * @param columnPlacements columns[i] = row index of queen in column i
     * @param targetRow The row where queen is intended to be placed in current column
     * @param targetColumn The column where queen is being placed
     * @return true if placement is safe, false otherwise
     */
    private static boolean isSafePlacement(int[] columnPlacements, int targetRow, int targetColumn) {
        // Check all previously placed columns (0 to targetColumn-1)
        for (int prevColumn = 0; prevColumn < targetColumn; prevColumn++) {
            int prevRow = columnPlacements[prevColumn];

            // Check if queens share the same row
            if (prevRow == targetRow) {
                return false; // Horizontal attack
            }

            // Check if queens share the same diagonal
            // Diagonal condition: absolute difference in rows equals difference in columns
            int rowDifference = Math.abs(prevRow - targetRow);
            int columnDifference = targetColumn - prevColumn;

            if (rowDifference == columnDifference) {
                return false; // Diagonal attack (both \ and / diagonals)
            }
        }
        return true; // No conflicts found
    }

    /**
     * Utility method to count the number of valid solutions without generating them.
     * Uses the same backtracking algorithm but only counts, doesn't store.
     * This is more memory efficient for large N where only the count is needed.
     *
     * @param boardSize The size of the board (N)
     * @return The number of distinct solutions
     */
    public static int countNQueensSolutions(int boardSize) {
        if (boardSize < 1) {
            return 0;
        }

        int[] columnPlacements = new int[boardSize];
        return countQueenPlacements(boardSize, columnPlacements, 0);
    }

    /**
     * Recursive helper function to count solutions without storing them.
     *
     * @param boardSize Size of the chess board
     * @param columnPlacements Current placements array
     * @param currentColumn Current column being processed
     * @return Number of solutions from this state
     */
    private static int countQueenPlacements(int boardSize, int[] columnPlacements, int currentColumn) {
        if (currentColumn == boardSize) {
            return 1; // Found one valid arrangement
        }

        int solutionCount = 0;
        for (int candidateRow = 0; candidateRow < boardSize; candidateRow++) {
            columnPlacements[currentColumn] = candidateRow;
            if (isSafePlacement(columnPlacements, candidateRow, currentColumn)) {
                solutionCount += countQueenPlacements(boardSize, columnPlacements, currentColumn + 1);
            }
        }
        return solutionCount;
    }

    /**
     * Validates if a given board arrangement is a correct N-Queens solution.
     * This can be used for testing and verification.
     *
     * @param board The board arrangement as a list of strings
     * @return true if the arrangement is valid, false otherwise
     */
    public static boolean isValidSolution(List<String> board) {
        int boardSize = board.size();

        // Extract queen positions
        int[] queenRows = new int[boardSize];
        for (int colIndex = 0; colIndex < boardSize; colIndex++) {
            String rowStr = board.get(colIndex);
            if (rowStr.length() != boardSize) {
                return false; // Invalid row length
            }

            int queenPos = rowStr.indexOf(QUEEN_SYMBOL);
            if (queenPos == -1) {
                return false; // No queen found in row
            }
            if (rowStr.lastIndexOf(QUEEN_SYMBOL) != queenPos) {
                return false; // Multiple queens in same row
            }

            queenRows[colIndex] = queenPos;
        }

        // Check for conflicts
        for (int i = 0; i < boardSize; i++) {
            for (int j = i + 1; j < boardSize; j++) {
                if (queenRows[i] == queenRows[j]) {
                    return false; // Same row (horizontal conflict)
                }
                if (Math.abs(queenRows[i] - queenRows[j]) == Math.abs(i - j)) {
                    return false; // Diagonal conflict
                }
            }
        }
        return true;
    }

    /**
     * Gets the solution count statistics for all board sizes up to a given maximum.
     * Useful for demonstration and educational purposes.
     *
     * @param maxSize Maximum board size to analyze (recommended ≤ 12 due to exponential complexity)
     */
    public static void printSolutionStatistics(int maxSize) {
        System.out.println("N-Queens Problem Statistics:");
        System.out.println("+-------+----------------+");
        System.out.println("| Size  | # Solutions    |");
        System.out.println("+-------+----------------+");

        for (int boardSize = 1; boardSize <= maxSize; boardSize++) {
            int solutionCount = countNQueensSolutions(boardSize);
            System.out.printf("| %3d   | %,13d |%n", boardSize, solutionCount);
        }
        System.out.println("+-------+----------------+");
    }
}

/*
COMPREHENSIVE DOCUMENTATION
===========================

N-QUEENS PROBLEM EXPLANATION
----------------------------

Chess Queen Movement:
====================
A queen in chess can move:
- Horizontally (left/right along the same row)
- Vertically (up/down along the same column)
- Diagonally (both / and \ directions)

Key Constraint: No two queens can share:
- The same row ✗
- The same column ✗
- The same diagonal ✗

Solution Visualization (N=4)
===========================

Valid Arrangement #1:
Column:  0   1   2   3
      ╔═══╤═══╤═══╤═══╗
Row 0 ║ . │ Q │ . │ . ║
      ╟───┼───┼───┼───╢
Row 1 ║ . │ . │ . │ Q ║
      ╟───┼───┼───┼───╢
Row 2 ║ Q │ . │ . │ . ║
      ╟───┼───┼───┼───╢
Row 3 ║ . │ . │ Q │ . ║
      ╚═══╧═══╧═══╧═══╝

Queens at: (0,1), (1,3), (2,0), (3,2)

BACKTRACKING TREE (N=4)
=======================

Col 0:        place Q at row 0
              /    |    \
Col 1:    row 2   row 3   (row 0,1 invalid)
           /       \
Col 2:  row 1     row 0
         /         \
Col 3:  row 3     row 2
        ✓         ✓
    Solution1  Solution2

DIAGONAL ATTACK DETECTION
========================

For two queens at (row1, col1) and (row2, col2):
They attack diagonally iff: |row1 - row2| = |col1 - col2|

Example:
Queen A: (1,2)
Queen B: (3,4)
|1-3| = 2, |2-4| = 2 → 2 == 2 → Diagonal attack! ✓

Queen A: (1,2)
Queen C: (4,1)
|1-4| = 3, |2-1| = 1 → 3 != 1 → No attack ✗

SOLUTION COUNTS FOR N=1 TO 15
==============================

| N | Number of Solutions | Distinct Solutions (excluding reflections/rotations) |
|---|--------------------|---------------------------------------------------|
| 1 | 1                  | 1                                                 |
| 2 | 0                  | 0                                                 |
| 3 | 0                  | 0                                                 |
| 4 | 2                  | 1                                                 |
| 5 | 10                 | 2                                                 |
| 6 | 4                  | 1                                                 |
| 7 | 40                 | 6                                                 |
| 8 | 92                 | 12                                                |
| 9 | 352                | 46                                                |
|10 | 724                | 92                                                |
|11 | 2,680              | 341                                               |
|12 | 14,200             | 1,787                                             |
|13 | 73,712             | 9,233                                             |
|14 | 365,596            | 45,752                                            |
|15 | 2,279,184          | 285,053                                           |

COMPLEXITY ANALYSIS
===================

The algorithm explores a search space of N! possibilities:
- At column 0: N choices
- At column 1: ≤ N-1 choices (some rows invalid)
- At column 2: ≤ N-2 choices
- ...
- At column N-1: 1 choice (if solution found)

Worst-case time complexity: O(N!) which is:
- N=8 (92 solutions): 8! = 40,320 placements checked
- N=12 (14,200 solutions): 12! = 479M placements checked
- N=15 (2.2M solutions): 15! ≈ 1.3 trillion placements (infeasible)

OPTIMIZATION TECHNIQUES
=======================

1. Symmetry Reduction:
   - Solutions that are rotations/reflections of each other can be considered equivalent
   - Reduces search space by factor of 8 (for square board)

2. Bitmask Optimization:
   - Use bitwise operations to track occupied rows and diagonals
   - Much faster than O(N) checks per placement

3. Minimum Remaining Values (MRV):
   - Try columns with fewest possible options first

4. Forward Checking:
   - After placing queen, mark invalid positions for future columns

ITERATIVE VERSION (using Stack)
===============================

Alternative non-recursive implementation using explicit stack to avoid recursion depth limits.

PRACTICAL APPLICATIONS
======================

1. Constraint Satisfaction Problems (CSP):
   - N-Queens is classic CSP benchmark
   - Tests backtracking algorithm performance

2. Parallel Computing:
   - Used to benchmark parallel algorithms
   - Solutions can be found independently

3. Scheduling Problems:
   - Resource allocation avoiding conflicts
   - Similar to placing non-conflicting tasks

4. Puzzle Games:
   - Eight queens puzzle in recreational mathematics
   - Brain teasers and logic puzzles

5. Graph Theory:
   - Special case of independent set problem
   - Queen's graph coloring

RELATED PROBLEMS
================

1. N-Queens II: Count solutions only (without storing boards)
2. N-Rooks: Simpler problem (rooks only attack horizontally/vertically)
3. N-Knights: Knights attack in L-shape
4. N-Bishops: Bishops only attack diagonally
5. N-Queens Completion: Fill pre-set queens
6. Minimum Dominating Set of Queens

EXTENSIONS
==========

1. 3D N-Queens:
   - Queens can move in 3 dimensions (x, y, z axes and all diagonals)

2. Toroidal N-Queens:
   - Board wraps around edges (pawn can exit left and appear right)

3. Super N-Queens:
   - Queens also move like knights

4. N-Queens with Custom Pieces:
   - Mix of different chess pieces

SAMPLE USAGE
===========

public static void main(String[] args) {
    // Get all solutions for 4-queens
    List<List<String>> solutions = NQueens.getAllNQueensSolutions(4);

    System.out.println("4-Queens Solutions:");
    for (int i = 0; i < solutions.size(); i++) {
        System.out.println("Solution " + (i+1) + ":");
        for (String row : solutions.get(i)) {
            System.out.println(row);
        }
        System.out.println();
    }

    // Print statistics for boards 1-8
    NQueens.printSolutionStatistics(8);

    // Count solutions for 8-queens
    int count = NQueens.countNQueensSolutions(8);
    System.out.println("8-Queens has " + count + " solutions");

    // Verify a solution
    boolean isValid = NQueens.isValidSolution(solutions.get(0));
    System.out.println("Is valid: " + isValid);
}

HISTORICAL NOTE
===============

The Eight Queens Puzzle was first proposed in 1848 by Max Bezzel.
Carl Friedrich Gauss (1777-1855) studied the problem and proposed 76 solutions.
In 1972, Edsger Dijkstra used this problem to demonstrate structured programming
and the power of backtracking in computer science.
*/

