package com.thealgorithms.greedyalgorithms;

import java.util.Arrays;

public final class MinimizingLateness {
    private MinimizingLateness() {
    }

    public static class Job {
        String jobName;
        int startTime = 0;
        int lateness = 0;
        int processingTime;
        int deadline;

        public Job(String jobName, int processingTime, int deadline) {
            this.jobName = jobName;
            this.processingTime = processingTime;
            this.deadline = deadline;
        }

        public static Job of(String jobName, int processingTime, int deadline) {
            return new Job(jobName, processingTime, deadline);
        }

        @Override
        public String toString() {
            return String.format("%s, startTime: %d, endTime: %d, lateness: %d", jobName, startTime, processingTime + startTime, lateness);
        }
    }

    static void calculateLateness(Job... jobs) {

        // sort the jobs based on their deadline
        Arrays.sort(jobs, (a, b) -> a.deadline - b.deadline);

        int startTime = 0;

        for (Job job : jobs) {
            job.startTime = startTime;
            startTime += job.processingTime;
            job.lateness = Math.max(0, startTime - job.deadline); // if the job finishes before deadline the lateness is 0
        }
    }
}

import java.util.Scanner;

public class AsalSayiKontrolu {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        // Kullanicidan bir sayi alinmasi
        System.out.print("Bir sayi girin: ");
        int sayi = scanner.nextInt();

        // Girilen sayi 1 veya daha kucukse, kullanicidan tekrar dogru bir sayi istenir
        while (sayi <= 1) {
            System.out.println("Lutfen 2'den buyuk bir pozitif sayi girin.");
            sayi = scanner.nextInt();
        }

        scanner.close(); // Scanner kaynaginin kapatilmasi

        boolean asal = true; // Asal olup olmadigini kontrol eden degisken

        // Asallik kontrolu icin dongu
        for (int i = 2; i <= sayi / 2; i++) {
            if (sayi % i == 0) { // Sayi, i'ye tam bolunuyorsa asal degildir
                asal = false;
                break; // Kontrolu sonlandir
            }
        }

        // Asallik durumunun yazdirilmasi
        if (asal) {
            System.out.println(sayi + " asal sayidir.");
        } else {
            System.out.println(sayi + " asal sayi degildir.");
        }
    }
}

public class WildCardExample<T extends Number> {
// Here to restrict to only Integer types, we must extend to Number
    private Object[] data;
    private static int DEFAULT_SIZE = 10;
    private int size = 0; // also working as index value

    public WildCardExample() {
        this.data = new Object[DEFAULT_SIZE];
    }

    public void getList(List<Number> list) {
        // do something

        // here you can only pass Number type
    }

    // WildCard

    public void getList1(List<? extends Number> list) {
        // here we can pass subclasses of Number -> int, float, double
    }

    public void add(T num) {
        if (isFull()) {
            resize();
        }
        data[size++] = num;
    }

    private void resize() {
        Object[] temp = new Object[data.length * 2];

        // copy the new items in the new array
        for (int i = 0; i < data.length; i++) {
            temp[i] = data[i];
        }
        data = temp;
    }

    private boolean isFull() {
        return size == data.length;
    }

    public T remove() {
        T removed = (T) (data[--size]);
        return removed;
    }

    public T get(int index) {
        return (T) data[index];
    }

    public int size() {
        return size;
    }

    public void set (int index, int value) {
        data[index] = value;
    }

    @Override
    public String toString() {
        return "CustomGenArrayList{" +
                "data=" + Arrays.toString(data) +
                ", size=" + size +
                '}';
    }

    public static void main(String[] args) {
//        ArrayList list = new ArrayList();
        WildCardExample list = new WildCardExample();
//        list.add(3);
//        list.add(5);
//        list.add(9);

//        for (int i = 0; i < 14; i++) {
//            list.add(2 * i);
//        }
//
//        System.out.println(list);

        ArrayList<String> list2 = new ArrayList<>();
//        list2.add("dfgg");
        // Generics help us in providing a parameterized type for stuff like <Integer> and all.

        WildCardExample<Integer> list3 = new WildCardExample<>();
        for (int i = 0; i < 14; i++) {
         list3.add(2 * i);
        }
        System.out.println(list3);
    }
}

