package com.thealgorithms.conversions;

/**
 * @author Varun Upadhyay (<a href="https://github.com/varunu28">...</a>)
 */
public final class AnyBaseToDecimal {
private static final int DIGIT_OFFSET = '0';
private static final int UPPERCASE_OFFSET = 'A' - 10;

private AnyBaseToDecimal() {
}

/**
 * Convert any radix to a decimal number.
 *
 * @param sourceString the string to be converted
 * @param sourceBase the radix (base) of the input string
 * @return the decimal equivalent of the input string
 * @throws NumberFormatException if the input string or radix is invalid
 */
public static int convertToDecimal(String sourceString, int sourceBase) {
int decimalResult = 0;
int positionalMultiplier = 1;
for (int index = sourceString.length() - 1; index >= 0; index--) {
int digitValue = getNumericValue(sourceString.charAt(index));
if (digitValue >= sourceBase) {
throw new NumberFormatException("For input string: " + sourceString);
}
decimalResult += digitValue * positionalMultiplier;
positionalMultiplier *= sourceBase;
}
return decimalResult;
}

/**
 * Convert a character to its integer value.
 *
 * @param inputSymbol the character to be converted
 * @return the integer value represented by the character
 * @throws NumberFormatException if the character is not an uppercase letter or a digit
 */
private static int getNumericValue(char inputSymbol) {
if (Character.isDigit(inputSymbol)) {
return inputSymbol - DIGIT_OFFSET;
} else if (Character.isUpperCase(inputSymbol)) {
return inputSymbol - UPPERCASE_OFFSET;
} else {
throw new NumberFormatException("invalid character:" + inputSymbol);
}
}
}

