package whileloop;
import java.util.Scanner;

/*
 * Girilen bir tam sayinin tersten okundugunda da ayni olup olmadigini,
 * yani palindrom olup olmadigini test eder.
 */

public class PalindromKontrol {

	// Sayiyi tersine cevirip orijinaliyle karsilastirarak palindrom kontrolu yapar
	public static boolean palindromMu(int deger) {

		int orijinalDeger = deger;
		int tersCevrilmisDeger = 0;

		for (int kalan = deger; kalan > 0; kalan /= 10) {
			int sonRakam = kalan % 10;
			tersCevrilmisDeger = (tersCevrilmisDeger * 10) + sonRakam;
		}

		return orijinalDeger == tersCevrilmisDeger;
	}

	public static void main(String[] args) {

		Scanner girisAraci = new Scanner(System.in);
		System.out.print("Bir sayi girin: ");
		int girilenSayi = girisAraci.nextInt();
		girisAraci.close();

		if (palindromMu(girilenSayi)) {
			System.out.println(girilenSayi + " bir palindromdur.");
		} else {
			System.out.println(girilenSayi + " bir palindrom degildir.");
		}
	}
}

/**
 * G-Counter (Grow-only Counter) is a state-based CRDT (Conflict-free Replicated Data Type)
 * designed for tracking counts in a distributed and concurrent environment.
 * Each process maintains its own counter, allowing only increments. The total count
 * is obtained by summing individual process counts.
 * This implementation supports incrementing, querying the total count,
 * comparing with other G-Counters, and merging with another G-Counter
 * to compute the element-wise maximum.
 * (https://en.wikipedia.org/wiki/Conflict-free_replicated_data_type)
 *
 * @author itakurah (https://github.com/itakurah)
 */

class GCounter {
private final Map<Integer, Integer> internalCounter;
private final int nodeIdentifier;
private final int totalNodes;

/**
 * Constructs a G-Counter for a cluster of totalNodes nodes.
 *
 * @param nodeId The identifier for the current node.
 * @param totalNodeCount The number of nodes in the cluster.
 */
GCounter(int nodeId, int totalNodeCount) {
this.nodeIdentifier = nodeId;
this.totalNodes = totalNodeCount;
this.internalCounter = new HashMap<>();
for (int nodeIndex = 0; nodeIndex < totalNodeCount; nodeIndex++) {
internalCounter.put(nodeIndex, 0);
}
}

/**
 * Increments the counter for the current node.
 */
public void increment() {
internalCounter.put(nodeIdentifier, internalCounter.get(nodeIdentifier) + 1);
}

/**
 * Gets the total value of the counter by summing up values from all nodes.
 *
 * @return The total value of the counter.
 */
public int getTotalValue() {
int accumulatedSum = 0;
for (int nodeValue : internalCounter.values()) {
accumulatedSum += nodeValue;
}
return accumulatedSum;
}

/**
 * Compares the state of this G-Counter with another G-Counter.
 *
 * @param otherCounter The other G-Counter to compare with.
 * @return True if the state of this G-Counter is less than or equal to the state of the other G-Counter.
 */
public boolean isLessOrEqual(GCounter otherCounter) {
for (int nodeIndex = 0; nodeIndex < totalNodes; nodeIndex++) {
if (this.internalCounter.get(nodeIndex) > otherCounter.internalCounter.get(nodeIndex)) {
return false;
}
}
return true;
}

/**
 * Merges the state of this G-Counter with another G-Counter.
 *
 * @param otherCounter The other G-Counter to merge with.
 */
public void mergeWith(GCounter otherCounter) {
for (int nodeIndex = 0; nodeIndex < totalNodes; nodeIndex++) {
int currentValue = this.internalCounter.get(nodeIndex);
int otherValue = otherCounter.internalCounter.get(nodeIndex);
this.internalCounter.put(nodeIndex, Math.max(currentValue, otherValue));
}
}
}

public class ChatClient {

    String serverAddress; // Sunucu adresi
    Scanner in; // Girdi akisi
    PrintWriter out; // Cikti akisi
    JFrame frame = new JFrame("Chatter"); // Chat penceresi
    JTextField textField = new JTextField(50); // Mesaj girmek icin alan
    JTextArea messageArea = new JTextArea(16, 50); // Mesajlari gosteren alan

    // Constructor: ChatClient nesnesi olusturur
    public ChatClient(String serverAddress) {
        this.serverAddress = serverAddress;

        textField.setEditable(false); // Mesaj girmek baslangicta kapali
        messageArea.setEditable(false); // Mesajlari gormek icin alani degistirilemez
        frame.getContentPane().add(textField, BorderLayout.SOUTH); // Mesaj girme alanini ekler
        frame.getContentPane().add(new JScrollPane(messageArea), BorderLayout.CENTER); // Mesajlari gosterme alanini ekler
        frame.pack();

        // Enter tusuna basildiginda mesaj gonderir, sonra textField'i temizler
        textField.addActionListener(new ActionListener() {
            public void actionPerformed(ActionEvent e) {
                out.println(textField.getText()); // Mesaji server'a gonder
                textField.setText(""); // Girdiyi temizle
            }
        });
    }

    // Kullaniciya ekran ismi secmesi icin dialog penceresi gosterir
    private String getName() {
        return JOptionPane.showInputDialog(frame, "Choose a screen name:", "Screen name selection",
                JOptionPane.PLAIN_MESSAGE);
    }

    // Chat client'ini baslatan ana metod
    private void run() throws IOException {
        try (var socket = new Socket(serverAddress, 59001)) { // Sunucuya baglanir
            in = new Scanner(socket.getInputStream()); // Sunucudan veri alir
            out = new PrintWriter(socket.getOutputStream(), true); // Sunucuya veri gonderir

            // Sunucudan gelen her satir icin islemleri yapar
            while (in.hasNextLine()) {
                var line = in.nextLine(); // Gelen satiri al
                if (line.startsWith("SUBMITNAME")) { // Ekran ismi istegini alir
                    out.println(getName()); // Kullaniciya ekran ismini sorar
                } else if (line.startsWith("NAMEACCEPTED")) { // Isim kabul edildiginde
                    this.frame.setTitle("Chatter - " + line.substring(13)); // Frame basligini gunceller
                    textField.setEditable(true); // Mesaj girmeye izin verir
                } else if (line.startsWith("MESSAGE")) { // Mesaj geldiyse
                    messageArea.append(line.substring(8) + "\n"); // Mesaji ekler
                }
            }
        } finally {
            frame.setVisible(false); // Frame'i gizler
            frame.dispose(); // Frame'i kapatir
        }
    }

    // Programi baslatan main metod
    public static void main(String[] args) throws Exception {

        var client = new ChatClient("localhost"); // Client'i olustur
        client.frame.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE); // Cikis yapildiginda programi kapat
        client.frame.setVisible(true); // Frame'i gorunur hale getir
        client.run(); // Chat client'ini calistir
    }
}

/**
 * A class that provides a solution to the abbreviation problem.
 *
 * Problem: Given two strings, `a` and `b`, determine if string `a` can be
 * transformed into string `b` by performing the following operations:
 * 1. Capitalize zero or more of `a`'s lowercase letters (i.e., convert them to uppercase).
 * 2. Delete any of the remaining lowercase letters from `a`.
 *
 * The task is to determine whether it is possible to make string `a` equal to string `b`.
 *
 * @author Hardvan
 */
public final class Abbreviation {
    private Abbreviation() {
    }

    /**
     * Determines if string `a` can be transformed into string `b` by capitalizing
     * some of its lowercase letters and deleting the rest.
     *
     * @param a The input string which may contain both uppercase and lowercase letters.
     * @param b The target string containing only uppercase letters.
     * @return {@code true} if string `a` can be transformed into string `b`,
     *         {@code false} otherwise.
     *
     * Time Complexity: O(n * m) where n = length of string `a` and m = length of string `b`.
     * Space Complexity: O(n * m) due to the dynamic programming table.
     */
    public static boolean abbr(String a, String b) {
        int n = a.length();
        int m = b.length();

        boolean[][] dp = new boolean[n + 1][m + 1];

        dp[0][0] = true;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= m; j++) {
                if (dp[i][j]) {
                    // Case 1: If the current characters match (or can be capitalized to match)
                    if (j < m && Character.toUpperCase(a.charAt(i)) == b.charAt(j)) {
                        dp[i + 1][j + 1] = true;
                    }
                    // Case 2: If the character in `a` is lowercase, we can skip it
                    if (Character.isLowerCase(a.charAt(i))) {
                        dp[i + 1][j] = true;
                    }
                }
            }
        }

        return dp[n][m];
    }
}

package com.thealgorithms.datastructures.crdt;

import java.util.HashMap;
import java.util.Map;

/**
 * PN-Counter (Positive-Negative Counter) is a state-based CRDT (Conflict-free Replicated Data Type)
 * designed for tracking counts with both increments and decrements in a distributed and concurrent environment.
 * It combines two G-Counters, one for increments (P) and one for decrements (N).
 * The total count is obtained by subtracting the value of the decrement counter from the increment counter.
 * This implementation supports incrementing, decrementing, querying the total count,
 * comparing with other PN-Counters, and merging with another PN-Counter
 * to compute the element-wise maximum for both increment and decrement counters.
 * (https://en.wikipedia.org/wiki/Conflict-free_replicated_data_type)
 *
 * @author itakurah (Niklas Hoefflin) (https://github.com/itakurah)
 */

class PNCounter {
    private final Map<Integer, Integer> pCounter;
    private final Map<Integer, Integer> nCounter;
    private final int myId;
    private final int n;

    /**
     * Constructs a PN-Counter for a cluster of n nodes.
     *
     * @param myId The identifier of the current node.
     * @param n    The number of nodes in the cluster.
     */
    PNCounter(int myId, int n) {
        this.myId = myId;
        this.n = n;
        this.pCounter = new HashMap<>();
        this.nCounter = new HashMap<>();

        for (int i = 0; i < n; i++) {
            pCounter.put(i, 0);
            nCounter.put(i, 0);
        }
    }

    /**
     * Increments the increment counter for the current node.
     */
    public void increment() {
        pCounter.put(myId, pCounter.get(myId) + 1);
    }

    /**
     * Increments the decrement counter for the current node.
     */
    public void decrement() {
        nCounter.put(myId, nCounter.get(myId) + 1);
    }

    /**
     * Gets the total value of the counter by subtracting the decrement counter from the increment counter.
     *
     * @return The total value of the counter.
     */
    public int value() {
        int sumP = pCounter.values().stream().mapToInt(Integer::intValue).sum();
        int sumN = nCounter.values().stream().mapToInt(Integer::intValue).sum();
        return sumP - sumN;
    }

    /**
     * Compares the state of this PN-Counter with another PN-Counter.
     *
     * @param other The other PN-Counter to compare with.
     * @return True if the state of this PN-Counter is less than or equal to the state of the other PN-Counter.
     */
    public boolean compare(PNCounter other) {
        if (this.n != other.n) {
            throw new IllegalArgumentException("Cannot compare PN-Counters with different number of nodes");
        }
        for (int i = 0; i < n; i++) {
            if (this.pCounter.get(i) > other.pCounter.get(i) && this.nCounter.get(i) > other.nCounter.get(i)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Merges the state of this PN-Counter with another PN-Counter.
     *
     * @param other The other PN-Counter to merge with.
     */
    public void merge(PNCounter other) {
        if (this.n != other.n) {
            throw new IllegalArgumentException("Cannot merge PN-Counters with different number of nodes");
        }
        for (int i = 0; i < n; i++) {
            this.pCounter.put(i, Math.max(this.pCounter.get(i), other.pCounter.get(i)));
            this.nCounter.put(i, Math.max(this.nCounter.get(i), other.nCounter.get(i)));
        }
    }
}

public class MutlakDeger {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);

		// Kullanicidan bir sayi girmesini iste
		System.out.print("Bir sayi girin: ");
		double sayi = scanner.nextDouble();

		double mutlakDeger;

		// Sayinin negatif olup olmadigini kontrol et
		if (sayi < 0) {
			// Eger sayi negatifse, isareti degistir
			mutlakDeger = -sayi;
		} else {
			// Sayi pozitifse, oldugu gibi sayiyi al
			mutlakDeger = sayi;
		}

		// Sonuc olarak sayinin mutlak degerini ekrana yazdir
		System.out.println("Girdiginiz sayinin mutlak degeri: " + mutlakDeger);

		// Scanner nesnesini kapat
		scanner.close();
	}
}

package com.thealgorithms.backtracking;

import java.util.ArrayList;
import java.util.List;

/**
 * Finds all possible simple paths from a given source vertex to a destination vertex
 * in a directed graph using backtracking.
 *
 * <p>This algorithm performs a Depth First Search (DFS) traversal while keeping track
 * of visited vertices to avoid cycles. Whenever the destination vertex is reached,
 * the current path is stored as one valid path.</p>
 *
 * <p><b>Key Characteristics:</b></p>
 * <ul>
 *   <li>Works on directed graphs</li>
 *   <li>Does not allow revisiting vertices in the same path</li>
 *   <li>Stores all possible paths from source to destination</li>
 * </ul>
 *
 * <p><b>Time Complexity:</b></p>
 * <ul>
 *   <li>Worst Case: O(V!) — when the graph is fully connected</li>
 * </ul>
 *
 * <p><b>Space Complexity:</b></p>
 * <ul>
 *   <li>O(V) for recursion stack and visited array</li>
 *   <li>Additional space for storing all valid paths</li>
 * </ul>
 *
 * <p>This implementation is intended for educational purposes.</p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Depth-first_search">Depth First Search</a>
 */

@SuppressWarnings({"rawtypes", "unchecked"})
public class AllPathsFromSourceToTarget {

    // No. of vertices in graph
    private final int v;

    // To store the paths from source to destination
    static List<List<Integer>> nm = new ArrayList<>();
    // adjacency list
    private ArrayList<Integer>[] adjList;

    // Constructor
    public AllPathsFromSourceToTarget(int vertices) {

        // initialise vertex count
        this.v = vertices;

        // initialise adjacency list
        initAdjList();
    }

    // utility method to initialise adjacency list
    private void initAdjList() {
        adjList = new ArrayList[v];

        for (int i = 0; i < v; i++) {
            adjList[i] = new ArrayList<>();
        }
    }

    // add edge from u to v
    public void addEdge(int u, int v) {
        // Add v to u's list.
        adjList[u].add(v);
    }

    public void storeAllPaths(int s, int d) {
        boolean[] isVisited = new boolean[v];
        ArrayList<Integer> pathList = new ArrayList<>();

        // add source to path[]
        pathList.add(s);
        // Call recursive utility
        storeAllPathsUtil(s, d, isVisited, pathList);
    }

    // A recursive function to print all paths from 'u' to 'd'.
    // isVisited[] keeps track of vertices in current path.
    // localPathList<> stores actual vertices in the current path
    private void storeAllPathsUtil(Integer u, Integer d, boolean[] isVisited, List<Integer> localPathList) {

        if (u.equals(d)) {
            nm.add(new ArrayList<>(localPathList));
            return;
        }

        // Mark the current node
        isVisited[u] = true;

        // Recursion for all the vertices adjacent to current vertex

        for (Integer i : adjList[u]) {
            if (!isVisited[i]) {
                // store current node in path[]
                localPathList.add(i);
                storeAllPathsUtil(i, d, isVisited, localPathList);

                // remove current node in path[]
                localPathList.remove(i);
            }
        }

        // Mark the current node
        isVisited[u] = false;
    }

    // Driver program
    public static List<List<Integer>> allPathsFromSourceToTarget(int vertices, int[][] a, int source, int destination) {
        // Create a sample graph
        AllPathsFromSourceToTarget g = new AllPathsFromSourceToTarget(vertices);
        for (int[] i : a) {
            g.addEdge(i[0], i[1]);
            // edges are added
        }
        g.storeAllPaths(source, destination);
        // method call to store all possible paths
        return nm;
        // returns all possible paths from source to destination
    }
}

// Class for a tree node
class TreeNode {

    // Members

    int key;
    TreeNode left;
    TreeNode right;

    // Constructor
    TreeNode(int key) {
        this.key = key;
        left = null;
        right = null;
    }
}

// A class to represent a queue item. The queue is used to do Level
// order traversal. Every Queue item contains node and horizontal
// distance of node from root
class QItem {

    TreeNode node;
    int hd;

    QItem(TreeNode n, int h) {
        node = n;
        hd = h;
    }
}

// Class for a Binary Tree
class Tree {

    TreeNode root;

    // Constructors
    Tree() {
        root = null;
    }

    Tree(TreeNode n) {
        root = n;
    }

    // This method prints nodes in top view of binary tree
    public void printTopView() {
        // base case
        if (root == null) {
            return;
        }

        // Creates an empty hashset
        HashSet<Integer> set = new HashSet<>();

        // Create a queue and add root to it
        Queue<QItem> queue = new LinkedList<QItem>();
        queue.add(new QItem(root, 0)); // Horizontal distance of root is 0

        // Standard BFS or level order traversal loop
        while (!queue.isEmpty()) {
            // Remove the front item and get its details
            QItem qi = queue.remove();
            int hd = qi.hd;
            TreeNode n = qi.node;

            // If this is the first node at its horizontal distance,
            // then this node is in top view
            if (!set.contains(hd)) {
                set.add(hd);
                System.out.print(n.key + " ");
            }

            // Enqueue left and right children of current node
            if (n.left != null) {
                queue.add(new QItem(n.left, hd - 1));
            }
            if (n.right != null) {
                queue.add(new QItem(n.right, hd + 1));
            }
        }
    }
}

// Driver class to test above methods
public final class PrintTopViewofTree {
    private PrintTopViewofTree() {
    }

    public static void main(String[] args) {
        /* Create following Binary Tree
       1
     /  \
    2    3
     \
      4
       \
        5
         \
          6*/
        TreeNode root = new TreeNode(1);
        root.left = new TreeNode(2);
        root.right = new TreeNode(3);
        root.left.right = new TreeNode(4);
        root.left.right.right = new TreeNode(5);
        root.left.right.right.right = new TreeNode(6);
        Tree t = new Tree(root);
        System.out.println("Following are nodes in top view of Binary Tree");
        t.printTopView();
    }
}

public class Main implements B {

    @Override
    public void performAction() {
        // Implementation for the method inherited from interface A
        // Since B extends A, this class must implement both interfaces' methods
        System.out.println("Performing main action - implementation of A's method");
    }

    @Override
    public void sendGreeting() {
        // Implementation for the method from interface B
        System.out.println("Sending greeting from Main class - implementation of B's method");
    }

    // Optional: Additional method to demonstrate usage
    public static void main(String[] args) {
        Main demoInstance = new Main();

        // Calling implemented methods
        demoInstance.performAction();
        demoInstance.sendGreeting();

        // Demonstrating polymorphism with interface references
        A interfaceARef = demoInstance;     // Upcasting to interface A
        B interfaceBRef = demoInstance;     // Upcasting to interface B

        System.out.println("\n--- Polymorphism Demonstration ---");
        interfaceARef.performAction();       // Calls Main's implementation
        interfaceBRef.sendGreeting();        // Calls Main's implementation
        interfaceBRef.performAction();       // Also works (B inherits from A)

        // Educational note:
        // A class implementing B must implement ALL methods from B AND from A
        // because B extends A (interface inheritance)
    }
}

/**
 * Given tree is traversed in an 'inorder' way: LEFT -> ROOT -> RIGHT.
 * Below are given the recursive and iterative implementations.
 *
 * Complexities:
 * Recursive: O(n) - time, O(n) - space, where 'n' is the number of nodes in a tree.
 *
 * Iterative: O(n) - time, O(h) - space, where 'n' is the number of nodes in a tree
 * and 'h' is the height of a binary tree.
 * In the worst case 'h' can be O(n) if tree is completely unbalanced, for instance:
 * 5
 *  \
 *   6
 *    \
 *     7
 *      \
 *       8
 *
 * @author Albina Gimaletdinova on 21/02/2023
 */
public final class InorderTraversal {
    private InorderTraversal() {
    }
    public static List<Integer> recursiveInorder(BinaryTree.Node root) {
        List<Integer> result = new ArrayList<>();
        recursiveInorder(root, result);
        return result;
    }

    public static List<Integer> iterativeInorder(BinaryTree.Node root) {
        List<Integer> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        Deque<BinaryTree.Node> stack = new ArrayDeque<>();
        while (!stack.isEmpty() || root != null) {
            while (root != null) {
                stack.push(root);
                root = root.left;
            }
            root = stack.pop();
            result.add(root.data);
            root = root.right;
        }
        return result;
    }

    private static void recursiveInorder(BinaryTree.Node root, List<Integer> result) {
        if (root == null) {
            return;
        }
        recursiveInorder(root.left, result);
        result.add(root.data);
        recursiveInorder(root.right, result);
    }
}

/**
 * Rectangle geometry helper.
 */
public class Rectangle {
    private float length;
    private float width;

    public Rectangle() {
        this(1.0f, 1.0f);
    }

    public Rectangle(float length, float width) {
        this.length = length;
        this.width = width;
    }

    public float getLength() {
        return length;
    }

    public void setLength(float length) {
        this.length = length;
    }

    public float getWidth() {
        return width;
    }

    public void setWidth(float width) {
        this.width = width;
    }

    public float getArea() {
        return length * width;
    }

    public float getPerimeter() {
        return 2 * (length + width);
    }

    @Override
    public String toString() {
        return "Rectangle[length=" + length + ", width=" + width + ']';
    }
}

class TestRectangle {
    public static void main(String[] args) {
        Rectangle r1 = new Rectangle(1.2f, 3.4f);
        System.out.println(r1);
        Rectangle r2 = new Rectangle();
        System.out.println(r2);

        r1.setLength(5.6f);
        r1.setWidth(7.8f);
        System.out.println(r1);
        System.out.println("length is: " + r1.getLength());
        System.out.println("width is: " + r1.getWidth());

        System.out.printf("area is: %.2f%n", r1.getArea());
        System.out.printf("perimeter is: %.2f%n", r1.getPerimeter());
    }
}

package com.ankan.inheritance;

public class Box {
    // Note: If declared as private, these variables would only be accessible within this class
    // Using default (package-private) access allows access from other classes in the same package
    double length;
    double height;
    double width;

    static void displayGreeting() {
        System.out.println("Greetings from the Box class! Hello there!");
    }

    // Default constructor - initializes Box with -1 values (represents invalid/empty state)
    Box() {
        this.height = -1;
        this.length = -1;
        this.width = -1;
    }

    // Constructor for creating a cube (all sides equal)
    // Calls the Object class constructor implicitly via super()
    Box(double sideLength) {
        this.length = sideLength;
        this.width = sideLength;
        this.height = sideLength;
    }

    // Parameterized constructor with all three dimensions
    Box(double boxLength, double boxHeight, double boxWidth) {
        this.length = boxLength;
        this.height = boxHeight;
        this.width = boxWidth;
    }

    // Copy constructor - creates a new Box from an existing Box object
    Box(Box existingBox) {
        this.length = existingBox.length;
        this.width = existingBox.width;
        this.height = existingBox.height;
    }

    public void displayInformation() {
        System.out.println("Box dimensions are currently accessible");
    }

    public void calculateAndDisplayVolume() {
        double volumeResult = length * width * height;
        System.out.println("Calculated volume: " + volumeResult);
        // Note: Original method only calculated volume without printing or returning
        // Enhanced version includes output for demonstration purposes
    }
}

package com.thealgorithms.datastructures.queues;

import java.util.NoSuchElementException;
import java.util.Stack;

/**
 * A queue implementation using two stacks. This class provides methods to
 * enqueue (add) elements to the end of the queue and dequeue (remove)
 * elements from the front, while utilizing two internal stacks to manage
 * the order of elements.
 *
 * @param <T> The type of elements held in this queue.
 */
@SuppressWarnings("unchecked")
public class QueueByTwoStacks<T> {

    private final Stack<T> enqueueStk;
    private final Stack<T> dequeueStk;

    /**
     * Constructor that initializes two empty stacks for the queue.
     * The `enqueueStk` is used to push elements when enqueuing, and
     * the `dequeueStk` is used to pop elements when dequeuing.
     */
    public QueueByTwoStacks() {
        enqueueStk = new Stack<>();
        dequeueStk = new Stack<>();
    }

    /**
     * Adds an element to the end of the queue. This method pushes the element
     * onto the `enqueueStk`.
     *
     * @param item The element to be added to the queue.
     */
    public void put(T item) {
        enqueueStk.push(item);
    }

    /**
     * Removes and returns the element at the front of the queue.
     * If `dequeueStk` is empty, it transfers all elements from
     * `enqueueStk` to `dequeueStk` to maintain the correct FIFO
     * (First-In-First-Out) order before popping.
     *
     * @return The element at the front of the queue.
     * @throws NoSuchElementException If the queue is empty.
     */
    public T get() {
        if (dequeueStk.isEmpty()) {
            while (!enqueueStk.isEmpty()) {
                dequeueStk.push(enqueueStk.pop());
            }
        }
        if (dequeueStk.isEmpty()) {
            throw new NoSuchElementException("Queue is empty");
        }
        return dequeueStk.pop();
    }

    /**
     * Returns the total number of elements currently in the queue.
     * This is the sum of the sizes of both stacks.
     *
     * @return The number of elements in the queue.
     */
    public int size() {
        return enqueueStk.size() + dequeueStk.size();
    }

    /**
     * Returns a string representation of the queue, showing the elements
     * in the correct order (from front to back).
     * The `dequeueStk` is first cloned, and then all elements from the
     * `enqueueStk` are added to the cloned stack in reverse order to
     * represent the queue accurately.
     *
     * @return A string representation of the queue.
     */
    @Override
    public String toString() {
        Stack<T> tempStack = (Stack<T>) dequeueStk.clone();
        while (!enqueueStk.isEmpty()) {
            tempStack.push(enqueueStk.pop());
        }
        return "Queue(" + tempStack + ")";
    }
}

