/**
 * AdjacencyMatrixGraph Implementation
 */
class AdjacencyMatrixGraph {

private int vertexCount;
private int edgeCount;
private int[][] connectionMatrix;
static final int EDGE_PRESENT = 1;
static final int EDGE_ABSENT = 0;

AdjacencyMatrixGraph(int totalVertices) {
this.vertexCount = totalVertices;
this.edgeCount = 0;
this.connectionMatrix = new int[totalVertices][totalVertices];
for (int rowIndex = 0; rowIndex < totalVertices; rowIndex++) {
for (int colIndex = 0; colIndex < totalVertices; colIndex++) {
this.connectionMatrix[rowIndex][colIndex] = EDGE_ABSENT;
}
}
}

private void setTotalVertices(int newVertexCount) {
this.vertexCount = newVertexCount;
}

public int getTotalVertices() {
return this.vertexCount;
}

private void setTotalEdges(int newEdgeCount) {
this.edgeCount = newEdgeCount;
}

public int getTotalEdges() {
return this.edgeCount;
}

private void setConnectionMatrix(int[][] newMatrix) {
this.connectionMatrix = newMatrix;
}

private int[][] getConnectionMatrix() {
return this.connectionMatrix;
}

private boolean hasConnection(int sourceNode, int targetNode) {
return (this.getConnectionMatrix()[sourceNode][targetNode] != EDGE_ABSENT);
}

public boolean isValidVertex(int targetVertex) {
return targetVertex >= 0 && targetVertex < this.getTotalVertices();
}

public boolean edgeExists(int sourceVertex, int targetVertex) {
if (this.isValidVertex(sourceVertex) && this.isValidVertex(targetVertex)) {
return this.hasConnection(sourceVertex, targetVertex);
}
return false;
}

public boolean addEdge(int sourceVertex, int targetVertex) {
if (this.isValidVertex(sourceVertex) && this.isValidVertex(targetVertex)) {
if (!this.hasConnection(sourceVertex, targetVertex)) {
this.getConnectionMatrix()[sourceVertex][targetVertex] = EDGE_PRESENT;
this.getConnectionMatrix()[targetVertex][sourceVertex] = EDGE_PRESENT;
this.setTotalEdges(this.getTotalEdges() + 1);
return true;
}
}
return false;
}

public boolean removeEdge(int sourceVertex, int targetVertex) {
if (this.isValidVertex(sourceVertex) && this.isValidVertex(targetVertex)) {
if (this.hasConnection(sourceVertex, targetVertex)) {
this.getConnectionMatrix()[sourceVertex][targetVertex] = EDGE_ABSENT;
this.getConnectionMatrix()[targetVertex][sourceVertex] = EDGE_ABSENT;
this.setTotalEdges(this.getTotalEdges() - 1);
return true;
}
}
return false;
}

public List<Integer> getDepthFirstOrder(int startVertex) {
if (startVertex >= vertexCount || startVertex < 0) {
return new ArrayList<>();
}
boolean[] visitedFlags = new boolean[vertexCount];
ArrayList<Integer> traversalOrder = new ArrayList<>();
performDFS(startVertex, visitedFlags, traversalOrder);
return traversalOrder;
}

private void performDFS(int currentVertex, boolean[] visitedFlags, List<Integer> traversalOrder) {
if (visitedFlags[currentVertex]) {
return;
}
visitedFlags[currentVertex] = true;
traversalOrder.add(currentVertex);
int[] neighborList = connectionMatrix[currentVertex];
for (int neighborIndex = 0; neighborIndex < neighborList.length; neighborIndex++) {
if (neighborList[neighborIndex] == EDGE_PRESENT) {
performDFS(neighborIndex, visitedFlags, traversalOrder);
}
}
}

public List<Integer> getBreadthFirstOrder(int startVertex) {
if (startVertex >= vertexCount || startVertex < 0) {
return new ArrayList<>();
}
boolean[] visitedFlags = new boolean[vertexCount];
ArrayList<Integer> traversalOrder = new ArrayList<>();
Queue<Integer> bfsQueue = new LinkedList<>();
bfsQueue.add(startVertex);
while (!bfsQueue.isEmpty()) {
int currentVertex = bfsQueue.poll();
if (visitedFlags[currentVertex]) {
continue;
}
traversalOrder.add(currentVertex);
visitedFlags[currentVertex] = true;
int[] neighborList = connectionMatrix[currentVertex];
for (int neighborIndex = 0; neighborIndex < neighborList.length; neighborIndex++) {
if (neighborList[neighborIndex] == EDGE_PRESENT) {
bfsQueue.add(neighborIndex);
}
}
}
return traversalOrder;
}

public String toString() {
StringBuilder outputBuilder = new StringBuilder("    ");
for (int nodeIndex = 0; nodeIndex < this.getTotalVertices(); nodeIndex++) {
outputBuilder.append(nodeIndex).append(" ");
}
outputBuilder.append(" \n");
for (int rowIndex = 0; rowIndex < this.getTotalVertices(); rowIndex++) {
outputBuilder.append(rowIndex).append(" : ");
for (int colIndex = 0; colIndex < this.getTotalVertices(); colIndex++) {
outputBuilder.append(this.connectionMatrix[rowIndex][colIndex]).append(" ");
}
outputBuilder.append("\n");
}
return outputBuilder.toString();
}
}

package com.thealgorithms.datastructures.graphs;

import java.util.LinkedList;
import java.util.Queue;

/**
 * This class implements the Ford-Fulkerson algorithm to compute the maximum flow
 * in a flow network.
 *
 * <p>The algorithm uses breadth-first search (BFS) to find augmenting paths from
 * the source vertex to the sink vertex, updating the flow in the network until
 * no more augmenting paths can be found.</p>
 */
public final class FordFulkerson {
    private static final int INF = Integer.MAX_VALUE;

    private FordFulkerson() {
    }

    /**
     * Computes the maximum flow in a flow network using the Ford-Fulkerson algorithm.
     *
     * @param vertexCount the number of vertices in the flow network
     * @param capacity    a 2D array representing the capacity of edges in the network
     * @param flow        a 2D array representing the current flow in the network
     * @param source      the source vertex in the flow network
     * @param sink        the sink vertex in the flow network
     * @return the total maximum flow from the source to the sink
     */
    public static int networkFlow(int vertexCount, int[][] capacity, int[][] flow, int source, int sink) {
        int totalFlow = 0;

        while (true) {
            int[] parent = new int[vertexCount];
            boolean[] visited = new boolean[vertexCount];
            Queue<Integer> queue = new LinkedList<>();

            queue.add(source);
            visited[source] = true;
            parent[source] = -1;

            while (!queue.isEmpty() && !visited[sink]) {
                int current = queue.poll();

                for (int next = 0; next < vertexCount; next++) {
                    if (!visited[next] && capacity[current][next] - flow[current][next] > 0) {
                        queue.add(next);
                        visited[next] = true;
                        parent[next] = current;
                    }
                }
            }

            if (!visited[sink]) {
                break; // No more augmenting paths
            }

            int pathFlow = INF;
            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                pathFlow = Math.min(pathFlow, capacity[u][v] - flow[u][v]);
            }

            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                flow[u][v] += pathFlow;
                flow[v][u] -= pathFlow;
            }

            totalFlow += pathFlow;
        }

        return totalFlow;
    }
}

