/**
 * This class implements a solution to the 2-SAT (2-Satisfiability) problem
 * using Kosaraju's algorithm to find strongly connected components (SCCs)
 * in the implication graph.
 *
 * <p>
 * <strong>Brief Idea:</strong>
 * </p>
 *
 * <pre>
 * 1. From each clause (a ∨ b), we can derive implications:
 *      (¬a → b) and (¬b → a)
 *
 * 2. We construct an implication graph using these implications.
 *
 * 3. For each variable x, its negation ¬x is also represented as a node.
 *    If x and ¬x belong to the same SCC, the expression is unsatisfiable.
 *
 * 4. Otherwise, we assign truth values based on the SCC order:
 *    If SCC(x) > SCC(¬x), then x = true; otherwise, x = false.
 * </pre>
 *
 * <p>
 * <strong>Complexities:</strong>
 * </p>
 * <ul>
 * <li>Time Complexity: O(n + m)</li>
 * <li>Space Complexity: O(n + m)</li>
 * </ul>
 * where {@code n} is the number of variables and {@code m} is the number of
 * clauses.
 *
 * <p>
 * <strong>Usage Example:</strong>
 * </p>
 *
 * <pre>
 * TwoSat twoSat = new TwoSat(5); // Initialize with 5 variables: x1, x2, x3, x4, x5
 *
 * // Add clauses
 * twoSat.addClause(1, false, 2, false); // (x1 ∨ x2)
 * twoSat.addClause(3, true, 2, false); // (¬x3 ∨ x2)
 * twoSat.addClause(4, false, 5, true); // (x4 ∨ ¬x5)
 *
 * twoSat.solve(); // Solve the problem
 *
 * if (twoSat.isSolutionExists()) {
 *     boolean[] solution = twoSat.getSolutions();
 *     for (int i = 1; i <= 5; i++) {
 *         System.out.println("x" + i + " = " + solution[i]);
 *     }
 * }
 * </pre>
 * <p><strong>Reference</strong></p>
 * <a href="https://cp-algorithms.com/graph/2SAT.html">CP Algorithm</a> <br></br>
 * <a href="https://en.wikipedia.org/wiki/2-satisfiability">Wikipedia - 2 SAT</a>
 * @author Shoyeb Ansari
 *
 * @see Kosaraju
 */
class TwoSatSolver {

/** Number of variables in the boolean expression. */
private final int variableCount;

/** Implication graph built from the boolean clauses. */
private final ArrayList<Integer>[] forwardGraph;

/** Transposed implication graph used in Kosaraju's algorithm. */
private final ArrayList<Integer>[] reverseGraph;

/** Stores one valid truth assignment for all variables (1-indexed). */
private final boolean[] truthAssignment;

/** Indicates whether a valid solution exists. */
private boolean hasValidSolution = true;

/** Tracks whether the {@code solve()} method has been called. */
private boolean isSolvedFlag = false;

/**
 * Initializes the TwoSat solver with the given number of variables.
 *
 * @param totalVariables the number of boolean variables
 * @throws IllegalArgumentException if the number of variables is negative
 */
@SuppressWarnings({"unchecked", "rawtypes"})
TwoSatSolver(int totalVariables) {
if (totalVariables < 0) {
throw new IllegalArgumentException("Number of variables cannot be negative.");
}
this.variableCount = totalVariables;
int totalNodes = 2 * totalVariables + 1;
forwardGraph = (ArrayList<Integer>[]) new ArrayList[totalNodes];
reverseGraph = (ArrayList<Integer>[]) new ArrayList[totalNodes];
for (int nodeIndex = 0; nodeIndex < totalNodes; nodeIndex++) {
forwardGraph[nodeIndex] = new ArrayList<>();
reverseGraph[nodeIndex] = new ArrayList<>();
}
truthAssignment = new boolean[totalVariables + 1];
}

/**
 * Adds a clause of the form (a ∨ b) to the boolean expression.
 *
 * <p>
 * Example: To add (¬x₁ ∨ x₂), call:
 * </p>
 *
 * <pre>{@code
 * addClause(1, true, 2, false);
 * }</pre>
 *
 * @param firstVar         the first variable (1 ≤ firstVar ≤ variableCount)
 * @param isNegatedFirst {@code true} if variable {@code firstVar} is negated
 * @param secondVar         the second variable (1 ≤ secondVar ≤ variableCount)
 * @param isNegatedSecond {@code true} if variable {@code secondVar} is negated
 * @throws IllegalArgumentException if {@code firstVar} or {@code secondVar} are out of range
 */
void addClause(int firstVar, boolean isNegatedFirst, int secondVar, boolean isNegatedSecond) {
if (firstVar <= 0 || firstVar > variableCount) {
throw new IllegalArgumentException("Variable number must be between 1 and " + variableCount);
}
if (secondVar <= 0 || secondVar > variableCount) {
throw new IllegalArgumentException("Variable number must be between 1 and " + variableCount);
}
int a = isNegatedFirst ? getNegatedIndex(firstVar) : firstVar;
int b = isNegatedSecond ? getNegatedIndex(secondVar) : secondVar;
int notA = getNegatedIndex(a);
int notB = getNegatedIndex(b);
forwardGraph[notA].add(b);
forwardGraph[notB].add(a);
reverseGraph[b].add(notA);
reverseGraph[a].add(notB);
}

/**
 * Solves the 2-SAT problem using Kosaraju's algorithm to find SCCs
 * and determines whether a satisfying assignment exists.
 */
void solve() {
isSolvedFlag = true;
int totalNodes = 2 * variableCount + 1;
boolean[] visitedNodes = new boolean[totalNodes];
int[] componentId = new int[totalNodes];
Stack<Integer> finishOrder = new Stack<>();
for (int startNode = 1; startNode < totalNodes; startNode++) {
if (!visitedNodes[startNode]) {
runDFSOrder(startNode, visitedNodes, finishOrder);
}
}
Arrays.fill(visitedNodes, false);
int sccCounter = 0;
while (!finishOrder.isEmpty()) {
int currentNode = finishOrder.pop();
if (!visitedNodes[currentNode]) {
runDFSLabels(currentNode, visitedNodes, componentId, sccCounter);
sccCounter++;
}
}
for (int varIndex = 1; varIndex <= variableCount; varIndex++) {
int negatedVar = getNegatedIndex(varIndex);
if (componentId[varIndex] == componentId[negatedVar]) {
hasValidSolution = false;
return;
}
truthAssignment[varIndex] = componentId[varIndex] > componentId[negatedVar];
}
}

/**
 * Returns whether the given boolean formula is satisfiable.
 *
 * @return {@code true} if a solution exists; {@code false} otherwise
 * @throws Error if called before {@link #solve()}
 */
boolean isSolutionExists() {
if (!isSolvedFlag) {
throw new Error("Please call solve() before checking for a solution.");
}
return hasValidSolution;
}

/**
 * Returns one valid assignment of variables that satisfies the boolean formula.
 *
 * @return a boolean array where {@code result[i]} represents the truth value of
 *         variable {@code xᵢ}
 * @throws Error if called before {@link #solve()} or if no solution exists
 */
boolean[] getSolutions() {
if (!isSolvedFlag) {
throw new Error("Please call solve() before fetching the solution.");
}
if (!hasValidSolution) {
throw new Error("No satisfying assignment exists for the given expression.");
}
return truthAssignment.clone();
}

/** Performs DFS to compute topological order. */
private void runDFSOrder(int startNode, boolean[] visitedNodes, Stack<Integer> finishOrder) {
visitedNodes[startNode] = true;
for (int neighborNode : forwardGraph[startNode]) {
if (!visitedNodes[neighborNode]) {
runDFSOrder(neighborNode, visitedNodes, finishOrder);
}
}
finishOrder.push(startNode);
}

/** Performs DFS on the transposed graph to identify SCCs. */
private void runDFSLabels(int startNode, boolean[] visitedNodes, int[] componentId, int sccCounter) {
visitedNodes[startNode] = true;
componentId[startNode] = sccCounter;
for (int neighborNode : reverseGraph[startNode]) {
if (!visitedNodes[neighborNode]) {
runDFSLabels(neighborNode, visitedNodes, componentId, sccCounter);
}
}
}

/**
 * Returns the index representing the negation of the given variable.
 *
 * <p>
 * Mapping rule:
 * </p>
 *
 * <pre>
 * For a variable i:
 *     negate(i) = i + variableCount
 * For a negated variable (i + variableCount):
 *     negate(i + variableCount) = i
 * where variableCount = numberOfVariables
 * </pre>
 *
 * @param nodeIndex the variable index
 * @return the index representing its negation
 */
private int getNegatedIndex(int nodeIndex) {
return nodeIndex <= variableCount ? nodeIndex + variableCount : nodeIndex - variableCount;
}
}
