/**
 * The RotateSinglyLinkedLists class provides a method to rotate a singly linked list
 * to the right by a specified number of positions.
 * <p>
 * In a right rotation by `k` steps, each node in the list moves `k` positions to the right.
 * Nodes that are rotated off the end of the list are placed back at the beginning.
 * </p>
 * <p>
 * Example:
 * Given linked list: 1 -> 2 -> 3 -> 4 -> 5 and k = 2, the output will be:
 * 4 -> 5 -> 1 -> 2 -> 3.
 * </p>
 * <p>
 * Edge Cases:
 * <ul>
 *   <li>If the list is empty, returns null.</li>
 *   <li>If `k` is 0 or a multiple of the list length, the list remains unchanged.</li>
 * </ul>
 * </p>
 * <p>
 * Complexity:
 * <ul>
 *   <li>Time Complexity: O(n), where n is the number of nodes in the linked list.</li>
 *   <li>Space Complexity: O(1), as we only use a constant amount of additional space.</li>
 * </ul>
 * </p>
 *
 * Author: Bama Charan Chhandogi (https://github.com/BamaCharanChhandogi)
 */
public class RotateSinglyLinkedLists {

    /**
     * Rotates a singly linked list to the right by `k` positions.
     *
     * @param head The head node of the singly linked list.
     * @param k The number of positions to rotate the list to the right.
     * @return The head of the rotated linked list.
     */
    public SinglyLinkedListNode rotateRight(SinglyLinkedListNode head, int k) {
        if (head == null || head.next == null || k == 0) {
            return head;
        }

        SinglyLinkedListNode curr = head;
        int len = 1;
        while (curr.next != null) {
            curr = curr.next;
            len++;
        }

        curr.next = head;
        k = k % len;
        k = len - k;
        while (k > 0) {
            curr = curr.next;
            k--;
        }

        head = curr.next;
        curr.next = null;
        return head;
    }
}

/**
 * Implements an algorithm to flatten a multilevel linked list.
 *
 * In this specific problem structure, each node has a `next` pointer (to the
 * next node at the same level) and a `child` pointer (which points to the head
 * of another sorted linked list). The goal is to merge all these lists into a
 * single, vertically sorted linked list using the `child` pointer.
 *
 * The approach is a recursive one that leverages a merge utility, similar to
 * the merge step in Merge Sort. It recursively flattens the list starting from
 * the rightmost node and merges each node's child list with the already
 * flattened list to its right.
 * @see <a href="https://www.geeksforgeeks.org/flattening-a-linked-list/">GeeksforGeeks: Flattening a Linked List</a>
 */
public final class FlattenMultilevelLinkedList {
    /**
     * Private constructor to prevent instantiation of this utility class.
     */
    private FlattenMultilevelLinkedList() {
    }
    /**
     * Node represents an element in the multilevel linked list. It contains the
     * integer data, a reference to the next node at the same level, and a
     * reference to the head of a child list.
     */
    static class Node {
        int data;
        Node next;
        Node child;

        Node(int data) {
            this.data = data;
            this.next = null;
            this.child = null;
        }
    }

    /**
     * Merges two sorted linked lists (connected via the `child` pointer).
     * This is a helper function for the main flatten algorithm.
     *
     * @param a The head of the first sorted list.
     * @param b The head of the second sorted list.
     * @return The head of the merged sorted list.
     */
    private static Node merge(Node a, Node b) {
        // If one of the lists is empty, return the other.
        if (a == null) {
            return b;
        }
        if (b == null) {
            return a;
        }

        Node result;

        // Choose the smaller value as the new head.
        if (a.data < b.data) {
            result = a;
            result.child = merge(a.child, b);
        } else {
            result = b;
            result.child = merge(a, b.child);
        }
        result.next = null; // Ensure the merged list has no `next` pointers.
        return result;
    }

    /**
     * Flattens a multilevel linked list into a single sorted list.
     * The flattened list is connected using the `child` pointers.
     *
     * @param head The head of the top-level list (connected via `next` pointers).
     * @return The head of the fully flattened and sorted list.
     */
    public static Node flatten(Node head) {
        // Base case: if the list is empty or has only one node, it's already flattened.
        if (head == null || head.next == null) {
            return head;
        }

        // Recursively flatten the list starting from the next node.
        head.next = flatten(head.next);

        // Now, merge the current list (head's child list) with the flattened rest of the list.
        head = merge(head, head.next);

        // Return the head of the fully merged list.
        return head;
    }
}

package capitalize;

import java.io.PrintWriter;
import java.net.Socket;
import java.util.Scanner;

/**
 * Reads lines from the console, sends each one to the uppercasing
 * server, and prints back whatever the server replies with.
 */
public class CapitalizeClient {

    private static final String HOST = "localhost";
    private static final int PORT = 59898;

    public static void main(String[] args) throws Exception {

        try (var connection = new Socket(HOST, PORT)) {

            System.out.println("Metin satirlarini girin, cikis yapmak icin Ctrl+D veya Ctrl+C kullanin");

            try (var keyboard = new Scanner(System.in)) {
                var fromServer = new Scanner(connection.getInputStream());
                var toServer = new PrintWriter(connection.getOutputStream(), true);

                while (keyboard.hasNextLine()) {
                    toServer.println(keyboard.nextLine());
                    System.out.println(fromServer.nextLine());
                }
            }
        }
    }
}

package forloop;

public class OnaKadarToplama {

    public static void main(String[] args) {

        // 1'den 10'a kadar sayilari yazdir
        System.out.print("1'den 10'a kadar olan sayilar: ");
        int n = 1;
        while (n <= 10) {
            System.out.print(n + " ");
            n++;
        }
        System.out.println();

        int birikenToplam = 0; // sabit araligin toplamini tutar

        // 1'den 10'a kadar olan sayilarin toplamini hesapla
        for (int i = 1; i <= 10; i++) {
            birikenToplam += i;
        }

        System.out.println("1'den 10'a kadar olan sayilarin toplami: " + birikenToplam);

        // Kullanicidan alinan bir sinir dahilinde toplama yap
        java.util.Scanner okuyucu = new java.util.Scanner(System.in);
        System.out.print("Toplamak istediginiz sayiyi girin: ");
        int sinir = okuyucu.nextInt();

        int ozelToplam = 0;
        int k = 1;
        while (k <= sinir) {
            ozelToplam += k;
            k++;
        }

        System.out.println("1'den " + sinir + "'a kadar olan sayilarin toplami: " + ozelToplam);

        okuyucu.close();
    }
}

/**
 * A utility class to convert between different units of time.
 *
 * <p>This class supports conversions between the following units:
 * <ul>
 *   <li>seconds</li>
 *   <li>minutes</li>
 *   <li>hours</li>
 *   <li>days</li>
 *   <li>weeks</li>
 *   <li>months (approximated as 30.44 days)</li>
 *   <li>years (approximated as 365.25 days)</li>
 * </ul>
 *
 * <p>The conversion is based on predefined constants in seconds.
 * Results are rounded to three decimal places for consistency.
 *
 * <p>This class is final and cannot be instantiated.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Unit_of_time">Wikipedia: Unit of time</a>
 */
public final class TimeConverter {

private TimeConverter() {
}

private enum TimeMeasurement {
SECONDS(1.0),
MINUTES(60.0),
HOURS(3600.0),
DAYS(86400.0),
WEEKS(604800.0),
MONTHS(2629800.0),
YEARS(31557600.0);

private final double baseSeconds;

TimeMeasurement(double baseSeconds) {
this.baseSeconds = baseSeconds;
}

public double toSeconds(double sourceValue) {
return sourceValue * baseSeconds;
}

public double fromSeconds(double secondsValue) {
return secondsValue / baseSeconds;
}
}

private static final Map<String, TimeMeasurement> UNIT_MAPPING = Map.ofEntries(
Map.entry("seconds", TimeMeasurement.SECONDS),
Map.entry("minutes", TimeMeasurement.MINUTES),
Map.entry("hours", TimeMeasurement.HOURS),
Map.entry("days", TimeMeasurement.DAYS),
Map.entry("weeks", TimeMeasurement.WEEKS),
Map.entry("months", TimeMeasurement.MONTHS),
Map.entry("years", TimeMeasurement.YEARS)
);

/**
 * Converts a time value from one unit to another.
 *
 * @param numericValue the numeric value of time to convert; must be non-negative
 * @param sourceUnit the unit of the input value (e.g., "minutes", "hours")
 * @param targetUnit the unit to convert into (e.g., "seconds", "days")
 * @return the converted value in the target unit, rounded to three decimals
 * @throws IllegalArgumentException if {@code numericValue} is negative
 * @throws IllegalArgumentException if either {@code sourceUnit} or {@code targetUnit} is not supported
 */
public static double convertTime(double numericValue, String sourceUnit, String targetUnit) {
if (numericValue < 0) {
throw new IllegalArgumentException("timeValue must be a non-negative number.");
}
TimeMeasurement sourceMeasurement = resolveUnit(sourceUnit);
TimeMeasurement targetMeasurement = resolveUnit(targetUnit);
double intermediateSeconds = sourceMeasurement.toSeconds(numericValue);
double convertedValue = targetMeasurement.fromSeconds(intermediateSeconds);
return Math.round(convertedValue * 1000.0) / 1000.0;
}

private static TimeMeasurement resolveUnit(String unitName) {
if (unitName == null) {
throw new IllegalArgumentException("Unit cannot be null.");
}
TimeMeasurement matchedUnit = UNIT_MAPPING.get(unitName.toLowerCase(Locale.ROOT));
if (matchedUnit == null) {
throw new IllegalArgumentException("Invalid unit '" + unitName + "'. Supported units are: " + UNIT_MAPPING.keySet());
}
return matchedUnit;
}
}

/**
 * The RGB color model is an additive color model in which red, green, and blue
 * light are added together in various ways to reproduce a broad array of
 * colors. The name of the model comes from the initials of the three additive
 * primary colors, red, green, and blue. Meanwhile, the HSV representation
 * models how colors appear under light. In it, colors are represented using
 * three components: hue, saturation and (brightness-)value. This class provides
 * methods for converting colors from one representation to the other.
 * (description adapted from <a href="https://en.wikipedia.org/wiki/RGB_color_model">[1]</a> and
 * <a href="https://en.wikipedia.org/wiki/HSL_and_HSV">[2]</a>).
 */
public final class RgbHsvConversion {
    private RgbHsvConversion() {
    }

    public static void main(String[] args) {
        // Expected RGB-values taken from https://www.rapidtables.com/convert/color/hsv-to-rgb.html

        // Test hsvToRgb-method
        assert Arrays.equals(hsvToRgb(0, 0, 0), new int[] {0, 0, 0});
        assert Arrays.equals(hsvToRgb(0, 0, 1), new int[] {255, 255, 255});
        assert Arrays.equals(hsvToRgb(0, 1, 1), new int[] {255, 0, 0});
        assert Arrays.equals(hsvToRgb(60, 1, 1), new int[] {255, 255, 0});
        assert Arrays.equals(hsvToRgb(120, 1, 1), new int[] {0, 255, 0});
        assert Arrays.equals(hsvToRgb(240, 1, 1), new int[] {0, 0, 255});
        assert Arrays.equals(hsvToRgb(300, 1, 1), new int[] {255, 0, 255});
        assert Arrays.equals(hsvToRgb(180, 0.5, 0.5), new int[] {64, 128, 128});
        assert Arrays.equals(hsvToRgb(234, 0.14, 0.88), new int[] {193, 196, 224});
        assert Arrays.equals(hsvToRgb(330, 0.75, 0.5), new int[] {128, 32, 80});

        // Test rgbToHsv-method
        // approximate-assertions needed because of small deviations due to converting between
        // int-values and double-values.
        assert approximatelyEqualHsv(rgbToHsv(0, 0, 0), new double[] {0, 0, 0});
        assert approximatelyEqualHsv(rgbToHsv(255, 255, 255), new double[] {0, 0, 1});
        assert approximatelyEqualHsv(rgbToHsv(255, 0, 0), new double[] {0, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(255, 255, 0), new double[] {60, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(0, 255, 0), new double[] {120, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(0, 0, 255), new double[] {240, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(255, 0, 255), new double[] {300, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(64, 128, 128), new double[] {180, 0.5, 0.5});
        assert approximatelyEqualHsv(rgbToHsv(193, 196, 224), new double[] {234, 0.14, 0.88});
        assert approximatelyEqualHsv(rgbToHsv(128, 32, 80), new double[] {330, 0.75, 0.5});
    }

    /**
     * Conversion from the HSV-representation to the RGB-representation.
     *
     * @param hue Hue of the color.
     * @param saturation Saturation of the color.
     * @param value Brightness-value of the color.
     * @return The tuple of RGB-components.
     */
    public static int[] hsvToRgb(double hue, double saturation, double value) {
        if (hue < 0 || hue > 360) {
            throw new IllegalArgumentException("hue should be between 0 and 360");
        }

        if (saturation < 0 || saturation > 1) {
            throw new IllegalArgumentException("saturation should be between 0 and 1");
        }

        if (value < 0 || value > 1) {
            throw new IllegalArgumentException("value should be between 0 and 1");
        }

        double chroma = value * saturation;
        double hueSection = hue / 60;
        double secondLargestComponent = chroma * (1 - Math.abs(hueSection % 2 - 1));
        double matchValue = value - chroma;

        return getRgbBySection(hueSection, chroma, matchValue, secondLargestComponent);
    }

    /**
     * Conversion from the RGB-representation to the HSV-representation.
     *
     * @param red Red-component of the color.
     * @param green Green-component of the color.
     * @param blue Blue-component of the color.
     * @return The tuple of HSV-components.
     */
    public static double[] rgbToHsv(int red, int green, int blue) {
        if (red < 0 || red > 255) {
            throw new IllegalArgumentException("red should be between 0 and 255");
        }

        if (green < 0 || green > 255) {
            throw new IllegalArgumentException("green should be between 0 and 255");
        }

        if (blue < 0 || blue > 255) {
            throw new IllegalArgumentException("blue should be between 0 and 255");
        }

        double dRed = (double) red / 255;
        double dGreen = (double) green / 255;
        double dBlue = (double) blue / 255;
        double value = Math.max(Math.max(dRed, dGreen), dBlue);
        double chroma = value - Math.min(Math.min(dRed, dGreen), dBlue);
        double saturation = value == 0 ? 0 : chroma / value;
        double hue;

        if (chroma == 0) {
            hue = 0;
        } else if (value == dRed) {
            hue = 60 * (0 + (dGreen - dBlue) / chroma);
        } else if (value == dGreen) {
            hue = 60 * (2 + (dBlue - dRed) / chroma);
        } else {
            hue = 60 * (4 + (dRed - dGreen) / chroma);
        }

        hue = (hue + 360) % 360;

        return new double[] {hue, saturation, value};
    }

    private static boolean approximatelyEqualHsv(double[] hsv1, double[] hsv2) {
        boolean bHue = Math.abs(hsv1[0] - hsv2[0]) < 0.2;
        boolean bSaturation = Math.abs(hsv1[1] - hsv2[1]) < 0.002;
        boolean bValue = Math.abs(hsv1[2] - hsv2[2]) < 0.002;

        return bHue && bSaturation && bValue;
    }

    private static int[] getRgbBySection(double hueSection, double chroma, double matchValue, double secondLargestComponent) {
        int red;
        int green;
        int blue;

        if (hueSection >= 0 && hueSection <= 1) {
            red = convertToInt(chroma + matchValue);
            green = convertToInt(secondLargestComponent + matchValue);
            blue = convertToInt(matchValue);
        } else if (hueSection > 1 && hueSection <= 2) {
            red = convertToInt(secondLargestComponent + matchValue);
            green = convertToInt(chroma + matchValue);
            blue = convertToInt(matchValue);
        } else if (hueSection > 2 && hueSection <= 3) {
            red = convertToInt(matchValue);
            green = convertToInt(chroma + matchValue);
            blue = convertToInt(secondLargestComponent + matchValue);
        } else if (hueSection > 3 && hueSection <= 4) {
            red = convertToInt(matchValue);
            green = convertToInt(secondLargestComponent + matchValue);
            blue = convertToInt(chroma + matchValue);
        } else if (hueSection > 4 && hueSection <= 5) {
            red = convertToInt(secondLargestComponent + matchValue);
            green = convertToInt(matchValue);
            blue = convertToInt(chroma + matchValue);
        } else {
            red = convertToInt(chroma + matchValue);
            green = convertToInt(matchValue);
            blue = convertToInt(secondLargestComponent + matchValue);
        }

        return new int[] {red, green, blue};
    }

    private static int convertToInt(double input) {
        return (int) Math.round(255 * input);
    }
}

package forloop;

public class BreakOrnegi {

    // For dongusu icerisinde break ifadesinin nasil calistigini gosterir
    public static void forOrnegiGoster() {
        System.out.println("For dongusu ornegi:");
        int sayac = 1;
        for (; sayac <= 10; sayac++) {
            if (sayac == 5) { // sayac 5'e ulastiginda dongu durur
                System.out.println("Dongu 5 degerinde kirildi!");
                break;
            }
            System.out.println("Dongu adimi: " + sayac);
        }
    }

    // While dongusu icinde break kullanilan ornek
    public static void whileOrnegiGoster() {
        System.out.println("\nWhile dongusu ornegi:");
        int sayac = 1;
        while (true) {
            if (sayac > 10) {
                break;
            }
            if (sayac == 7) { // sayac 7 oldugunda dongu sonlanir
                System.out.println("Dongu 7 degerinde kirildi!");
                break;
            }
            System.out.println("Dongu adimi: " + sayac);
            sayac++;
        }
    }

    // Ic ice yerlestirilmis donguler icerisinde break kullanimi
    public static void icIceOrnegiGoster() {
        System.out.println("\nIc ice donguler ornegi:");
        for (int disSayac = 1; disSayac <= 4; disSayac++) {
            int icSayac = 1;
            while (icSayac <= 4) {
                if (icSayac == 2) { // ic dongu belli bir noktada durdurulur
                    System.out.println("Ic dongu j = 2 de kirildi (i = " + disSayac + ")");
                    break;
                }
                System.out.println("i: " + disSayac + ", j: " + icSayac);
                icSayac++;
            }
        }
    }

    public static void main(String[] args) {
        // Sirasiyla ornekleri calistir
        forOrnegiGoster();
        whileOrnegiGoster();
        icIceOrnegiGoster();
    }
}

package com.thealgorithms.datastructures.queues;

import java.util.ArrayList;
import java.util.List;

/**
 * This class implements a GenericArrayListQueue, a queue data structure that
 * holds elements of any type specified at runtime, allowing flexibility in the type
 * of elements it stores.
 *
 * <p>The GenericArrayListQueue operates on a First-In-First-Out (FIFO) basis, where
 * elements added first are the first to be removed. New elements are added to the back
 * (or rear) of the queue, while removal of elements occurs from the front.
 *
 * @param <T> The type of elements held in this queue.
 */
public class GenericArrayListQueue<T> {

    /**
     * A list that stores the queue's elements in insertion order.
     */
    private final List<T> elementList = new ArrayList<>();

    /**
     * Checks if the queue is empty.
     *
     * @return {@code true} if the queue has no elements; {@code false} otherwise.
     */
    public boolean isEmpty() {
        return elementList.isEmpty();
    }

    /**
     * Retrieves, but does not remove, the element at the front of the queue.
     *
     * @return The element at the front of the queue, or {@code null} if the queue is empty.
     */
    public T peek() {
        return isEmpty() ? null : elementList.getFirst();
    }

    /**
     * Inserts an element at the back of the queue.
     *
     * @param element The element to be added to the queue.
     * @return {@code true} if the element was successfully added.
     */
    public boolean add(T element) {
        return elementList.add(element);
    }

    /**
     * Retrieves and removes the element at the front of the queue.
     *
     * @return The element removed from the front of the queue, or {@code null} if the queue is empty.
     */
    public T poll() {
        return isEmpty() ? null : elementList.removeFirst();
    }
}

package com.thealgorithms.conversions;

public final class BinaryToOctal {
    private static final int BITS_PER_OCTAL_DIGIT = 3;
    private static final int BINARY_BASE = 2;
    private static final int DECIMAL_BASE = 10;

    private BinaryToOctal() {
    }

    /**
     * This method converts a binary number to an octal number.
     *
     * @param binary The binary number
     * @return The octal number
     * @throws IllegalArgumentException if the input is not a valid binary number
     */
    public static String convertBinaryToOctal(int binary) {
        if (binary == 0) {
            return "0";
        }

        if (!String.valueOf(binary).matches("[01]+")) {
            throw new IllegalArgumentException("Input is not a valid binary number.");
        }

        StringBuilder octal = new StringBuilder();
        int currentBit;
        int bitValueMultiplier = 1;

        while (binary != 0) {
            int octalDigit = 0;
            for (int i = 0; i < BITS_PER_OCTAL_DIGIT && binary != 0; i++) {
                currentBit = binary % DECIMAL_BASE;
                binary /= DECIMAL_BASE;
                octalDigit += currentBit * bitValueMultiplier;
                bitValueMultiplier *= BINARY_BASE;
            }
            octal.insert(0, octalDigit);
            bitValueMultiplier = 1; // Reset multiplier for the next group
        }

        return octal.toString();
    }
}

package Invoice;

/**
 * An invoice composed with a Customer, applying a discount.
 */
class Customer {

    private int customerId;
    private String fullName;
    private int discountPercent;

    public Customer(int customerId, String fullName, int discountPercent) {
        this.customerId = customerId;
        this.fullName = fullName;
        this.discountPercent = discountPercent;
    }

    public int getID() {
        return customerId;
    }

    public void setID(int customerId) {
        this.customerId = customerId;
    }

    public String getName() {
        return fullName;
    }

    public void setName(String fullName) {
        this.fullName = fullName;
    }

    public int getDiscount() {
        return discountPercent;
    }

    public void setDiscount(int discountPercent) {
        this.discountPercent = discountPercent;
    }

    @Override
    public String toString() {
        return fullName + "(" + customerId + ")" + "(" + discountPercent + "%)";
    }
}

public class Invoice {

    private int invoiceId;
    private Customer buyer;
    private double amount;

    public Invoice(int invoiceId, Customer buyer, double amount) {
        this.invoiceId = invoiceId;
        this.buyer = buyer;
        this.amount = amount;
    }

    public int getID() {
        return invoiceId;
    }

    public void setID(int invoiceId) {
        this.invoiceId = invoiceId;
    }

    public Customer getCustomer() {
        return buyer;
    }

    public void setCustomer(Customer buyer) {
        this.buyer = buyer;
    }

    public double getAmount() {
        return amount;
    }

    public void setAmount(double amount) {
        this.amount = amount;
    }

    public int getCustomerID() {
        return buyer.getID();
    }

    public String getCustomerName() {
        return buyer.getName();
    }

    public int getCustomerDiscount() {
        return buyer.getDiscount();
    }

    public double getAmountAfterDiscount() {
        return amount - (amount * buyer.getDiscount() / 100);
    }

    @Override
    public String toString() {
        return "Invoice[id=" + invoiceId + ",customer=" + buyer + ",amount=" + amount + "]";
    }
}

class TestInvoice {

    public static void main(String[] args) {
        Customer c1 = new Customer(88, "Tan Ah Teck", 10);
