/**
 * This class implements a PriorityQueue.
 *
 * <p>
 * A priority queue adds elements into positions based on their priority. So the
 * most important elements are placed at the front/on the top. In this example I
 * give numbers that are bigger, a higher priority. Queues in theory have no
 * fixed size but when using an array implementation it does.
 * <p>
 * Additional contributions made by: PuneetTri(https://github.com/PuneetTri)
 */
class PriorityQueue {

    /**
     * The max size of the queue
     */
    private int maxSize;
    /**
     * The array for the queue
     */
    private int[] queueArray;
    /**
     * How many items are in the queue
     */
    private int nItems;

    /**
     * Default Constructor
     */

    PriorityQueue() {
        /* If capacity is not defined, default size of 11 would be used
         *  capacity=max+1 because we can't access 0th element of PQ, and to
         *  accommodate (max)th elements we need capacity to be max+1.
         *  Parent is at position k, child at position (k*2,k*2+1), if we
         *  use position 0 in our queue, its child would be at:
         *  (0*2, 0*2+1) -> (0,0). This is why we start at position 1
         */
        int size = 11; // Default value of 11
        maxSize = size + 1;
        queueArray = new int[maxSize];
        nItems = 0;
    }

    /**
     * Parameterized Constructor
     *
     * @param size Size of the queue
     */

    PriorityQueue(int size) {
        maxSize = size + 1;
        queueArray = new int[maxSize];
        nItems = 0;
    }

    /**
     * Helper function for the max-heap implementation of PQ
     * Function would help demote parent node to their correct
     * position
     *
     * @param pos Position of newly added element at bottom
     */
    private void swim(int pos) {
        // Check if parent is smaller than child node
        while (pos > 1 && (queueArray[pos / 2] < queueArray[pos])) {
            // In such case swap value of child with parent
            int temp = queueArray[pos];
            queueArray[pos] = queueArray[pos / 2];
            queueArray[pos / 2] = temp;
            pos = pos / 2; // Jump to position of parent node
        }
        // Promotion of child node will go on until it becomes smaller than the parent
    }

    /**
     * Helper function for the max-heap implementation of PQ
     * Function would help demote parent node to their correct
     * position
     *
     * @param pos Position of element at top
     */
    private void sink(int pos) {
        // Check if node's position is that of parent node
        while (2 * pos <= nItems) {
            int current = 2 * pos; // Jump to the positon of child node
            // Compare both the children for the greater one
            if (current < nItems && queueArray[current] < queueArray[current + 1]) {
                current++;
            }
            // If the parent node is greater, sink operation is complete. Break the loop
            if (queueArray[pos] >= queueArray[current]) {
                break;
            }

            // If not exchange the value of parent with child
            int temp = queueArray[pos];
            queueArray[pos] = queueArray[current];
            queueArray[current] = temp;
            pos = current; // Exchange parent position to child position in the array
        }
    }

    /**
     * Inserts an element in it's appropriate place
     *
     * @param value Value to be inserted
     */
    public void insert(int value) {
        // Print overflow message if the capacity is full
        if (isFull()) {
            throw new RuntimeException("Queue is full");
        } else {
            queueArray[++nItems] = value;
            swim(nItems); // Swim up the element to its correct position
        }
    }

    /**
     * Dequeue the element with the max priority from PQ
     *
     * @return The element removed
     */
    public int remove() {
        if (isEmpty()) {
            throw new RuntimeException("Queue is Empty");
        } else {
            int max = queueArray[1]; // By definition of our max-heap, value at queueArray[1] pos is
                                     // the greatest

            // Swap max and last element
            int temp = queueArray[1];
            queueArray[1] = queueArray[nItems];
            queueArray[nItems] = temp;
            queueArray[nItems--] = 0; // Nullify the last element from the priority queue
            sink(1); // Sink the element in order

            return max;
        }
    }

    /**
     * Checks what's at the front of the queue
     *
     * @return element at the front of the queue
     */
    public int peek() {
        return queueArray[1];
    }

    /**
     * Returns true if the queue is empty
     *
     * @return true if the queue is empty
     */
    public boolean isEmpty() {
        return (nItems == 0);
    }

    /**
     * Returns true if the queue is full
     *
     * @return true if the queue is full
     */
    public boolean isFull() {
        return (nItems == maxSize - 1);
    }

    /**
     * Returns the number of elements in the queue
     *
     * @return number of elements in the queue
     */
    public int getSize() {
        return nItems;
    }
}

package com.thealgorithms.backtracking;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import java.util.TreeSet;

/**
 * Finds all combinations of a given array using backtracking algorithm.
 * 
 * <p>This class provides functionality to generate all possible combinations
 * of a specified length from an array of elements. The combinations are
 * returned as {@link TreeSet} objects, which automatically maintain order
 * and eliminate duplicates.</p>
 * 
 * <p><b>Key Features:</b></p>
 * <ul>
 *   <li>Preserves element order by automatically sorting the input array</li>
 *   <li>Uses TreeSet to ensure each combination is stored in sorted order</li>
 *   <li>Implements efficient backtracking to avoid duplicate combinations</li>
 *   <li>Handles generic types for maximum flexibility</li>
 * </ul>
 * 
 * <p><b>Example Usage:</b></p>
 * <pre>
 * // Generate combinations of length 2 from an array of strings
 * String[] fruits = {"apple", "banana", "orange", "grape"};
 * List&lt;TreeSet&lt;String&gt;&gt; combinations = Combination.findCombinations(fruits, 2);
 * 
 * // Result: [{apple, banana}, {apple, grape}, {apple, orange}, 
 * //          {banana, grape}, {banana, orange}, {grape, orange}]
 * 
 * // Generate combinations of length 3 from numbers
 * Integer[] numbers = {1, 5, 3, 7, 9};
 * List&lt;TreeSet&lt;Integer&gt;&gt; combos = Combination.findCombinations(numbers, 3);
 * </pre>
 * 
 * <p><b>Time Complexity:</b> O(C(n,k) × k) - where C(n,k) is the binomial coefficient,
 * and k is the combination length. A significant improvement over naive O(n^k) approach.</p>
 * 
 * <p><b>Space Complexity:</b> O(C(n,k) × k) for storing all combinations plus O(k) recursion depth.</p>
 * 
 * @author Alan Piao (<a href="https://github.com/cpiao3">git-Alan Piao</a>)
 * @param <T> The type of elements in the array (must be Comparable for TreeSet ordering)
 * @see <a href="https://en.wikipedia.org/wiki/Combination">Combination (Wikipedia)</a>
 * @see <a href="https://en.wikipedia.org/wiki/Backtracking">Backtracking Algorithm</a>
 */
public final class Combination {

    // Private constructor to prevent instantiation (utility class)
    private Combination() {
        throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
    }

    /**
     * Finds all combinations of specified length from the given array using backtracking.
     * 
     * <p>The algorithm works by:
     * <ol>
     *   <li>Sorting the input array to ensure consistent ordering</li>
     *   <li>Using backtracking to explore all possible combinations</li>
     *   <li>Storing each valid combination as a TreeSet (automatically sorted)</li>
     * </ol>
     * </p>
     * 
     * @param inputArray The source array from which combinations are generated (must not be null)
     * @param combinationLength The desired length of each combination (0 ≤ k ≤ inputArray.length)
     * @param <T> The type of elements in the array (must implement Comparable)
     * @return A list of TreeSets, each representing a unique combination of length k.
     *         Returns an empty list if k == 0 or if no combinations are possible.
     * @throws IllegalArgumentException if combinationLength is negative or greater than array length
     * @throws NullPointerException if inputArray is null
     * 
     * @example
     * combination(new Integer[]{1,2,3}, 2) → [{1,2}, {1,3}, {2,3}]
     * combination(new String[]{"A","B","C"}, 1) → [{A}, {B}, {C}]
     * combination(new Integer[]{1,2,3,4}, 4) → [{1,2,3,4}]
     */
    public static <T> List<TreeSet<T>> findCombinations(T[] inputArray, int combinationLength) {
        // Validate input
        if (inputArray == null) {
            throw new NullPointerException("Input array cannot be null");
        }

        if (combinationLength < 0) {
            throw new IllegalArgumentException(
                "Combination length cannot be negative: " + combinationLength
            );
        }

        if (combinationLength > inputArray.length) {
            throw new IllegalArgumentException(
                "Combination length (" + combinationLength + ") cannot exceed array length (" + 
                inputArray.length + ")"
            );
        }

        // Base case: combinations of length 0
        if (combinationLength == 0) {
            return Collections.emptyList();
        }

        // Sort array to maintain consistent ordering
        T[] sortedArray = inputArray.clone();
        Arrays.sort(sortedArray);

        // Generate all combinations using backtracking
        List<TreeSet<T>> allCombinations = new LinkedList<>();
        generateCombinations(sortedArray, combinationLength, 0, new TreeSet<T>(), allCombinations);

        return allCombinations;
    }

    /**
     * Recursive backtracking method to generate all combinations.
     * 
     * <p>This method implements the core backtracking logic:
     * <ul>
     *   <li>Prunes branches where not enough elements remain to complete the combination</li>
     *   <li>When only one more element is needed, adds all remaining valid elements</li>
     *   <li>Otherwise, recursively explores each possible next element</li>
     * </ul>
     * </p>
     *
     * @param sortedArray The pre-sorted source array (ascending order)
     * @param targetLength The desired length of each combination (k)
     * @param currentIndex The current position in the array to start searching from
     * @param currentSet The current combination being built (as a TreeSet for automatic ordering)
     * @param allCombinations List to store all valid combinations found
     * @param <T> The type of elements in the array
     */
    private static <T> void generateCombinations(T[] sortedArray, 
                                                  int targetLength, 
                                                  int currentIndex, 
                                                  TreeSet<T> currentSet, 
                                                  List<TreeSet<T>> allCombinations) {

        // Pruning optimization: Not enough remaining elements to complete the combination
        // We need (targetLength - currentSet.size()) more elements
        // If we don't have enough elements left, abandon this branch
        if (currentIndex + targetLength - currentSet.size() > sortedArray.length) {
            return;
        }

        // Base case: Only one more element is needed to complete the combination
        if (currentSet.size() == targetLength - 1) {
            // Add each remaining element as the final element
            for (int elementIndex = currentIndex; elementIndex < sortedArray.length; elementIndex++) {
                currentSet.add(sortedArray[elementIndex]);
                // Store a copy of the complete combination
                allCombinations.add(new TreeSet<>(currentSet));
                // Backtrack: remove the added element
                currentSet.remove(sortedArray[elementIndex]);
            }
            return;
        }

        // Recursive case: Build combination by adding elements one by one
        for (int elementIndex = currentIndex; elementIndex < sortedArray.length; elementIndex++) {
            // Choose: Add current element to the combination
            currentSet.add(sortedArray[elementIndex]);

            // Explore: Generate combinations with remaining elements
            generateCombinations(sortedArray, targetLength, elementIndex + 1, currentSet, allCombinations);

            // Unchoose: Backtrack - remove current element to try other possibilities
            currentSet.remove(sortedArray[elementIndex]);
        }
    }

    /**
     * Utility method to count the total number of possible combinations without generating them.
     * Uses the binomial coefficient formula: C(n,k) = n! / (k! × (n-k)!)
     *
     * @param totalElements The total number of elements (n)
     * @param combinationSize The size of each combination (k)
     * @return The number of possible combinations (C(n,k))
     * @throws IllegalArgumentException if k > n or any parameter is negative
     */
    public static long getCombinationCount(int totalElements, int combinationSize) {
        if (combinationSize < 0 || totalElements < 0 || combinationSize > totalElements) {
            throw new IllegalArgumentException("Invalid parameters for combination count");
        }

        // Use symmetry: C(n,k) = C(n, n-k) to minimize computations
        int smallerK = Math.min(combinationSize, totalElements - combinationSize);

        long count = 1;
        for (int i = 1; i <= smallerK; i++) {
            count = count * (totalElements - smallerK + i) / i;
        }
        return count;
    }

    /**
     * Prints all combinations in a human-readable format.
     * Useful for debugging and demonstration.
     *
     * @param combinations The list of combinations to print
     * @param <T> The type of elements in the combinations
     */
    public static <T> void printAllCombinations(List<TreeSet<T>> combinations) {
        if (combinations == null || combinations.isEmpty()) {
            System.out.println("No combinations found.");
            return;
        }

        System.out.println("Total combinations: " + combinations.size());
        int combinationIndex = 1;
        for (TreeSet<T> combination : combinations) {
            System.out.printf("Combination %3d: %s%n", combinationIndex++, combination.toString());
        }
    }
}

/*
COMPREHENSIVE DOCUMENTATION
===========================

ALGORITHM EXPLANATION
---------------------

Why Use TreeSet?
===============
- Automatically maintains elements in sorted order
- Provides O(log n) add/remove operations
- Ensures no duplicate elements within a combination
- Natural ordering based on Comparable implementation

Backtracking Visualization (n=5, k=3):
=====================================

Sorted Array: [A, B, C, D, E]

Recursion Tree:
                                    start(0)
                                      |
                +------------------+--+--+-------------------+
                |                  |        |                   |
             add A(1)            add B(1)  add C(1)            add D(1)
                |                  |        |                   |
          index=1               index=2   index=3              index=4
                |                  |        |                   |
        +-------+-------+          etc...   etc...             (need 2 more)
        |       |       |          
     add B(2) add C(2) add D(2)
        |       |       |
    index=2  index=3  index=4
        |       |       |
      add C   add D   add E
        |       |       |
    [A,B,C]✓ [A,C,D]✓ [A,D,E]✓

LEGEND:
- (n) = current set size
- ✓ = valid combination found

IMPORTANT DIFFERENCES FROM OTHER COMBINATION ALGORITHMS
=======================================================

| Feature | This Implementation | ArrayCombination | Standard Backtracking |
|---------|---------------------|------------------|----------------------|
| Output Type | TreeSet<T> | List<Integer> | List<List<T>> |
| Ordering | Automatic sorting | Input order | Depends on input |
| Duplicate Handling | Prevents duplicates | Allows duplicates | Varies |
| Memory Usage | Higher (TreeSet overhead) | Lower | Medium |
| Performance | Slower (TreeSet ops) | Fastest | Fast |

PERFORMANCE OPTIMIZATIONS
=========================

1. Pruning Optimization:
   if (index + n - currSet.size() > arr.length) return;
   - Prevents exploring branches that can't produce valid combinations
   - Significantly reduces recursion depth for large n,k

2. Base Case Optimization:
   When only one element is needed (currSet.size() == n - 1):
   - Adds all remaining elements at once instead of recursing further
   - Reduces function call overhead

3. Sorting Optimization:
   - Sorts array once at the beginning
   - Ensures combinations are generated in lexicographic order
   - Makes pruning more effective

COMPLEXITY ANALYSIS
===================

Time Complexity Breakdown:
------------------------
| Operation | Per Combination | Total |
|-----------|----------------|-------|
| TreeSet add | O(log k) | O(C(n,k) × log k) |
| TreeSet remove | O(log k) | O(C(n,k) × log k) |
| TreeSet copy | O(k) | O(C(n,k) × k) |
| Recursion overhead | O(1) | O(C(n,k)) |

Space Complexity Breakdown:
-------------------------
1. Input array clone: O(n)
2. Recursion stack: O(k)
3. Current TreeSet: O(k)
4. Result storage: O(C(n,k) × k)

MEMORY USAGE EXAMPLE
===================
n=15, k=5:
- C(15,5) = 3,003 combinations
- Each TreeSet: ~5 elements × 8 bytes + overhead (~72 bytes)
- Total memory: ~216 KB for results + recursion overhead
Total: ~500 KB (very manageable)

PRACTICAL APPLICATIONS
======================

1. Market Basket Analysis
   - Generate all item combinations of size k
   - Find frequently purchased product sets

2. Feature Selection in Machine Learning
   - Test all feature combinations of size k
   - Find optimal feature subset

3. Combinatorial Optimization
   - Generate candidate solutions
   - Evaluate each combination for optimality

4. Game AI
   - Generate all possible moves in state space
   - Evaluate and choose best combination

5. Testing and QA
   - Generate test case combinations
   - Parameter combination testing

6. Cryptography
   - Generate all possible key combinations of length k
   - Brute-force attacks on weak systems

7. DNA Sequence Analysis
   - Generate all possible gene combinations
   - Find significant biological patterns

WHEN TO USE THIS ALGORITHM
==========================

✅ Use When:
- All combinations of specific size are needed
- Input array is relatively small (n ≤ 30)
- Ordered results are important
- Duplicate prevention is required

❌ Avoid When:
- Only need count of combinations (use formula instead)
- Working with very large arrays (n > 30)
- Real-time performance is critical
- Memory is severely limited

ALTERNATIVE APPROACHES
======================

1. Iterative Approach (Binary Method):
   for (int i = 0; i < (1 << n); i++)
     if (Integer.bitCount(i) == k)
       generate combination

   Pros: Simple, no recursion
   Cons: Inefficient for large n, requires bit operations

2. Dynamic Programming:
   Use DP table to build combinations iteratively

   Pros: No recursion depth issues
   Cons: More complex implementation, more memory

3. Library Functions:
   Apache Commons CombinatoricsUtils
   Google Guava Collections2

   Pros: Well-tested, optimized
   Cons: External dependency

RELATED PROBLEMS
================

1. Subsets (all sizes) - power set generation
2. Permutations (ordered selections)
3. Combinations with repetition
4. Combinations of multiple sets (Cartesian product)
5. Partition problems
6. Subset sum problem
7. Knapsack problem (0/1)
*/

