package com.thealgorithms.conversions;

import java.math.BigDecimal;

/**
 A Java-based utility for converting numeric values into their English word
 representations. Whether you need to convert a small number, a large number
 with millions and billions, or even a number with decimal places, this utility
 has you covered.
 *
 */
public final class NumberToWords {

    private NumberToWords() {
    }

    private static final String[] UNITS = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"};

    private static final String[] TENS = {"", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};

    private static final String[] POWERS = {"", "Thousand", "Million", "Billion", "Trillion"};

    private static final String ZERO = "Zero";
    private static final String POINT = " Point";
    private static final String NEGATIVE = "Negative ";

    public static String convert(BigDecimal number) {
        if (number == null) {
            return "Invalid Input";
        }

        // Check for negative sign
        boolean isNegative = number.signum() < 0;

        // Split the number into whole and fractional parts
        BigDecimal[] parts = number.abs().divideAndRemainder(BigDecimal.ONE);
        BigDecimal wholePart = parts[0]; // Keep whole part as BigDecimal
        String fractionalPartStr = parts[1].compareTo(BigDecimal.ZERO) > 0 ? parts[1].toPlainString().substring(2) : ""; // Get fractional part only if it exists

        // Convert whole part to words
        StringBuilder result = new StringBuilder();
        if (isNegative) {
            result.append(NEGATIVE);
        }
        result.append(convertWholeNumberToWords(wholePart));

        // Convert fractional part to words
        if (!fractionalPartStr.isEmpty()) {
            result.append(POINT);
            for (char digit : fractionalPartStr.toCharArray()) {
                int digitValue = Character.getNumericValue(digit);
                result.append(" ").append(digitValue == 0 ? ZERO : UNITS[digitValue]);
            }
        }

        return result.toString().trim();
    }

    private static String convertWholeNumberToWords(BigDecimal number) {
        if (number.compareTo(BigDecimal.ZERO) == 0) {
            return ZERO;
        }

        StringBuilder words = new StringBuilder();
        int power = 0;

        while (number.compareTo(BigDecimal.ZERO) > 0) {
            // Get the last three digits
            BigDecimal[] divisionResult = number.divideAndRemainder(BigDecimal.valueOf(1000));
            int chunk = divisionResult[1].intValue();

            if (chunk > 0) {
                String chunkWords = convertChunk(chunk);
                if (power > 0) {
                    words.insert(0, POWERS[power] + " ");
                }
                words.insert(0, chunkWords + " ");
            }

            number = divisionResult[0]; // Continue with the remaining part
            power++;
        }

        return words.toString().trim();
    }

    private static String convertChunk(int number) {
        String chunkWords;

        if (number < 20) {
            chunkWords = UNITS[number];
        } else if (number < 100) {
            chunkWords = TENS[number / 10] + (number % 10 > 0 ? " " + UNITS[number % 10] : "");
        } else {
            chunkWords = UNITS[number / 100] + " Hundred" + (number % 100 > 0 ? " " + convertChunk(number % 100) : "");
        }

        return chunkWords;
    }
}

package string;

import java.util.Random;

/*
 * Uzunlugu 8 ile 12 karakter arasinda degisen rastgele bir sifre uretir.
 * Uretilen sifre en az bir buyuk harf, bir rakam ve bir sembol icerir.
 */

public class SifreUreteci {

    private static final String BUYUK_HARFLER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String RAKAMLAR = "0123456789";
    private static final String SEMBOLLER = "!@#$%^&*()_+-=[]{}|;':\"<>,.?/\\";

    public static String yeniSifreOlustur() {
        Random rng = new Random();

        int hedefUzunluk = 8 + rng.nextInt(5);

        StringBuilder tampon = new StringBuilder();
        tampon.append(BUYUK_HARFLER.charAt(rng.nextInt(BUYUK_HARFLER.length())));
        tampon.append(RAKAMLAR.charAt(rng.nextInt(RAKAMLAR.length())));
        tampon.append(SEMBOLLER.charAt(rng.nextInt(SEMBOLLER.length())));

        String genelHavuz = BUYUK_HARFLER + RAKAMLAR + SEMBOLLER + BUYUK_HARFLER.toLowerCase();
        for (int kalan = hedefUzunluk - 3; kalan > 0; kalan--) {
            tampon.append(genelHavuz.charAt(rng.nextInt(genelHavuz.length())));
        }

        return harfleriKaristir(tampon.toString());
    }

    public static String harfleriKaristir(String girdi) {
        char[] harfler = girdi.toCharArray();
        Random rng = new Random();

        for (int son = harfler.length - 1; son > 0; son--) {
            int hedefIndeks = rng.nextInt(son);
            char gecici = harfler[hedefIndeks];
            harfler[hedefIndeks] = harfler[son];
            harfler[son] = gecici;
        }

        return new String(harfler);
    }

    public static void main(String[] args) {
        System.out.println(yeniSifreOlustur());
    }
}

public class LFSR implements BaseLFSR {

private final BitSet internalRegister;
private final int registerLength;
private final int clockBitPosition;
private final int[] tapBitPositions;

public LFSR(int lengthValue, int clockPosition, int[] tapPositions) {
this.registerLength = lengthValue;
this.clockBitPosition = clockPosition;
this.tapBitPositions = tapPositions;
internalRegister = new BitSet(lengthValue);
}

@Override
public void initialize(BitSet keyData, BitSet frameData) {
internalRegister.clear();
loadBits(keyData, SESSION_KEY_LENGTH);
loadBits(frameData, FRAME_COUNTER_LENGTH);
}

private void loadBits(BitSet sourceData, int dataLength) {
for (int position = dataLength - 1; position >= 0; --position) {
boolean newBitValue = sourceData.get(position) ^ computeXorTap();
shiftAndInsert(newBitValue);
}
}

@Override
public boolean clock() {
return shiftAndInsert(computeXorTap());
}

public boolean getClockBit() {
return internalRegister.get(clockBitPosition);
}

public boolean get(int bitPosition) {
return internalRegister.get(bitPosition);
}

public boolean getLastBit() {
return internalRegister.get(registerLength - 1);
}

private boolean computeXorTap() {
boolean xorResult = false;
for (int tapPosition : tapBitPositions) {
xorResult ^= internalRegister.get(tapPosition);
}
return xorResult;
}

private boolean shiftAndInsert(boolean inputBit) {
boolean droppedBit = shiftRight();
internalRegister.set(0, inputBit);
return droppedBit;
}

private boolean shiftRight() {
boolean discarded = get(registerLength - 1);
for (int index = registerLength - 1; index > 0; --index) {
internalRegister.set(index, get(index - 1));
}
internalRegister.set(0, false);
return discarded;
}

@Override
public String toString() {
return internalRegister.toString();
}
}

public class MySQLDemo {

    public static void main(String[] args) throws SQLException, ClassNotFoundException {

        // MySQL surucusunu kaydet
        Class.forName("com.mysql.jdbc.Driver");

        // Veritabanina baglanti olustur
        String url = "jdbc:mysql://localhost:3306/testdb";
        String username = "root";
        String password = "password";

        try (Connection connection = DriverManager.getConnection(url, username, password);
             Statement statement = connection.createStatement();
             Scanner scanner = new Scanner(System.in)) {

            // Kullanicidan islem tipi al
            System.out.println("Yapmak istediginiz islemi secin: ");
            System.out.println("1 - Yeni kayit ekle");
            System.out.println("2 - Kayit guncelle");
            System.out.println("3 - Kayit sil");
            System.out.println("4 - Tum kayitlari listele");
            System.out.print("Seciminizi yapin: ");
            int choice = scanner.nextInt();
            scanner.nextLine();  // Bu satir, 'nextInt' sonrasi gelen '\n' karakterini temizler

            switch (choice) {
                case 1:
                    // Yeni bir kayit ekle
                    System.out.print("Adinizi girin: ");
                    String name = scanner.nextLine();
                    System.out.print("Email adresinizi girin: ");
                    String email = scanner.nextLine();
                    String insertSql = "iNSERT iNTO users (name, email) VALUES (?, ?)";
                    try (PreparedStatement pstmt = connection.prepareStatement(insertSql)) {
                        pstmt.setString(1, name);
                        pstmt.setString(2, email);
                        pstmt.executeUpdate();
                        System.out.println("Yeni kayit basariyla eklendi.");
                    }
                    break;

                case 2:
                    // Var olan bir kaydi guncelle
                    System.out.print("Guncellemek istediginiz kullanicinin iD'sini girin: ");
                    int idToUpdate = scanner.nextInt();
                    scanner.nextLine(); // 'nextInt' sonrasi gelen '\n' karakterini temizler
                    System.out.print("Yeni ad girin: ");
                    String newName = scanner.nextLine();
                    System.out.print("Yeni email adresi girin: ");
                    String newEmail = scanner.nextLine();
                    String updateSql = "UPDATE users SET name = ?, email = ? WHERE id = ?";
                    try (PreparedStatement pstmt = connection.prepareStatement(updateSql)) {
                        pstmt.setString(1, newName);
                        pstmt.setString(2, newEmail);
                        pstmt.setInt(3, idToUpdate);
                        int rowsUpdated = pstmt.executeUpdate();
                        if (rowsUpdated > 0) {
                            System.out.println("Kullanici guncellendi.");
                        } else {
                            System.out.println("Kullanici bulunamadi.");
                        }
                    }
                    break;

                case 3:
                    // Bir kaydi sil
                    System.out.print("Silmek istediginiz kullanicinin iD'sini girin: ");
                    int idToDelete = scanner.nextInt();
                    String deleteSql = "DELETE FROM users WHERE id = ?";
                    try (PreparedStatement pstmt = connection.prepareStatement(deleteSql)) {
                        pstmt.setInt(1, idToDelete);
                        int rowsDeleted = pstmt.executeUpdate();
                        if (rowsDeleted > 0) {
                            System.out.println("Kullanici silindi.");
                        } else {
                            System.out.println("Kullanici bulunamadi.");
                        }
                    }
                    break;

                case 4:
                    // Tum kayitlari listele
                    String selectSql = "SELECT * FROM users";
                    try (ResultSet resultSet = statement.executeQuery(selectSql)) {
                        while (resultSet.next()) {
                            int id = resultSet.getInt("id");
                            String userName = resultSet.getString("name");
                            String userEmail = resultSet.getString("email");
                            System.out.println("iD: " + id + ", Name: " + userName + ", Email: " + userEmail);
                        }
                    }
                    break;

                default:
                    System.out.println("Gecersiz secim.");
            }
        }
    }
}

package com.thealgorithms.compression;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * An implementation of the Lempel-Ziv 78 (LZ78) compression algorithm.
 * <p>
 * LZ78 is a dictionary-based lossless data compression algorithm. It processes
 * input data sequentially, building a dictionary of phrases encountered so far.
 * It outputs pairs (dictionary_index, next_character), representing
 * the longest match found in the dictionary plus the character that follows it.
 * </p>
 * <p>
 * This implementation builds the dictionary dynamically during compression.
 * The dictionary index 0 represents the empty string (no prefix).
 * </p>
 * <p>
 * Time Complexity: O(n) on average for compression and decompression, assuming
 * efficient dictionary lookups (using a HashMap), where n is the
 * length of the input string.
 * </p>
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/LZ77_and_LZ78#LZ78">Wikipedia: LZ78</a></li>
 * </ul>
 * </p>
 */
public final class LZ78 {

    /**
     * Special character used to mark end of stream when needed.
     */
    private static final char END_OF_STREAM = '\u0000';

    /**
     * Private constructor to prevent instantiation of this utility class.
     */
    private LZ78() {
    }

    /**
     * Represents a token in the LZ78 compressed output.
     * Stores the index of the matching prefix in the dictionary and the next character.
     * Index 0 represents the empty string (no prefix).
     */
    public record Token(int index, char nextChar) {
    }

    /**
     * A node in the dictionary trie structure.
     * Each node represents a phrase and can have child nodes for extended phrases.
     */
    private static final class TrieNode {
        Map<Character, TrieNode> children = new HashMap<>();
        int index = -1; // -1 means not assigned yet
    }

    /**
     * Compresses the input text using the LZ78 algorithm.
     *
     * @param text The input string to compress. Must not be null.
     * @return A list of {@link Token} objects representing the compressed data.
     */
    public static List<Token> compress(String text) {
        if (text == null || text.isEmpty()) {
            return new ArrayList<>();
        }

        List<Token> compressedOutput = new ArrayList<>();
        TrieNode root = new TrieNode();
        int nextDictionaryIndex = 1;

        TrieNode currentNode = root;
        int lastMatchedIndex = 0;

        for (int i = 0; i < text.length(); i++) {
            char currentChar = text.charAt(i);

            if (currentNode.children.containsKey(currentChar)) {
                currentNode = currentNode.children.get(currentChar);
                lastMatchedIndex = currentNode.index;
            } else {
                // Output: (index of longest matching prefix, current character)
                compressedOutput.add(new Token(lastMatchedIndex, currentChar));

                TrieNode newNode = new TrieNode();
                newNode.index = nextDictionaryIndex++;
                currentNode.children.put(currentChar, newNode);

                currentNode = root;
                lastMatchedIndex = 0;
            }
        }

        // Handle remaining phrase at end of input
        if (currentNode != root) {
            compressedOutput.add(new Token(lastMatchedIndex, END_OF_STREAM));
        }

        return compressedOutput;
    }

    /**
     * Decompresses a list of LZ78 tokens back into the original string.
     *
     * @param compressedData The list of {@link Token} objects. Must not be null.
     * @return The original, uncompressed string.
     */
    public static String decompress(List<Token> compressedData) {
        if (compressedData == null || compressedData.isEmpty()) {
            return "";
        }

        StringBuilder decompressedText = new StringBuilder();
        Map<Integer, String> dictionary = new HashMap<>();
        int nextDictionaryIndex = 1;

        for (Token token : compressedData) {
            String prefix = (token.index == 0) ? "" : dictionary.get(token.index);

            if (token.nextChar == END_OF_STREAM) {
                decompressedText.append(prefix);
            } else {
                String currentPhrase = prefix + token.nextChar;
                decompressedText.append(currentPhrase);
                dictionary.put(nextDictionaryIndex++, currentPhrase);
            }
        }

        return decompressedText.toString();
    }
}

package com.thealgorithms.datastructures.crdt;

import java.util.HashSet;
import java.util.Set;

/**
 * GSet (Grow-only Set) is a state-based CRDT (Conflict-free Replicated Data Type)
 * that allows only the addition of elements and ensures that once an element is added,
 * it cannot be removed. The merge operation of two G-Sets is their union.
 * This implementation supports adding elements, looking up elements, comparing with other G-Sets,
 * and merging with another G-Set to create a new G-Set containing all unique elements from both sets.
 * (https://en.wikipedia.org/wiki/Conflict-free_replicated_data_type)
 *
 * @author itakurah (Niklas Hoefflin) (https://github.com/itakurah)
 */

public class GSet<ElementType> {
private final Set<ElementType> storedElements;

/**
 * Constructs an empty G-Set.
 */
public GSet() {
this.storedElements = new HashSet<>();
}

/**
 * Adds an element to the G-Set.
 *
 * @param elementToAdd the element to be added
 */
public void addElement(ElementType elementToAdd) {
storedElements.add(elementToAdd);
}

/**
 * Checks if the given element is present in the G-Set.
 *
 * @param searchElement the element to be checked
 * @return true if the element is present, false otherwise
 */
public boolean contains(ElementType searchElement) {
return storedElements.contains(searchElement);
}

/**
 * Compares the G-Set with another G-Set to check if it is a subset.
 *
 * @param otherSet the other G-Set to compare with
 * @return true if the current G-Set is a subset of the other, false otherwise
 */
public boolean isSubsetOf(GSet<ElementType> otherSet) {
return otherSet.storedElements.containsAll(storedElements);
}

/**
 * Merges the current G-Set with another G-Set, creating a new G-Set
 * containing all unique elements from both sets.
 *
 * @param otherSet the G-Set to merge with
 */
public void mergeWith(GSet<ElementType> otherSet) {
storedElements.addAll(otherSet.storedElements);
}
}

public final class MinimizingLateness {
    private MinimizingLateness() {
    }

    public static class Job {
        String jobName;
        int startTime = 0;
        int lateness = 0;
        int processingTime;
        int deadline;

        public Job(String jobName, int processingTime, int deadline) {
            this.jobName = jobName;
            this.processingTime = processingTime;
            this.deadline = deadline;
        }

        public static Job of(String jobName, int processingTime, int deadline) {
            return new Job(jobName, processingTime, deadline);
        }

        @Override
        public String toString() {
            return String.format("%s, startTime: %d, endTime: %d, lateness: %d", jobName, startTime, processingTime + startTime, lateness);
        }
    }

    static void calculateLateness(Job... jobs) {

        // sort the jobs based on their deadline
        Arrays.sort(jobs, (a, b) -> a.deadline - b.deadline);

        int startTime = 0;

        for (Job job : jobs) {
            job.startTime = startTime;
            startTime += job.processingTime;
            job.lateness = Math.max(0, startTime - job.deadline); // if the job finishes before deadline the lateness is 0
        }
    }
}

package com.thealgorithms.compression;

/**
 * An implementation of the Run-Length Encoding (RLE) algorithm.
 *
 * <p>Run-Length Encoding is a simple form of lossless data compression in which
 * runs of data (sequences in which the same data value occurs in many
 * consecutive data elements) are stored as a single data value and count,
 * rather than as the original run.
 *
 * <p>This implementation provides methods for both compressing and decompressing
 * a string. For example:
 * <ul>
 * <li>Compressing "AAAABBBCCDAA" results in "4A3B2C1D2A".</li>
 * <li>Decompressing "4A3B2C1D2A" results in "AAAABBBCCDAA".</li>
 * </ul>
 *
 * <p>Time Complexity: O(n) for both compression and decompression, where n is the
 * length of the input string.
 *
 * <p>References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Run-length_encoding">Wikipedia: Run-length encoding</a></li>
 * </ul>
 */
public final class RunLengthEncoding {

/**
 * Private constructor to prevent instantiation of this utility class.
 */
private RunLengthEncoding() {
}

/**
 * Compresses a string using the Run-Length Encoding algorithm.
 *
 * @param sourceText The string to be compressed. Must not be null.
 * @return The compressed string. Returns an empty string if the input is empty.
 */
public static String compress(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
return "";
}
StringBuilder encodedResult = new StringBuilder();
int repeatCount = 1;
for (int position = 0; position < sourceText.length(); position++) {
if (position == sourceText.length() - 1 || sourceText.charAt(position) != sourceText.charAt(position + 1)) {
encodedResult.append(repeatCount);
encodedResult.append(sourceText.charAt(position));
repeatCount = 1;
} else {
repeatCount++;
}
}
return encodedResult.toString();
}

/**
 * Decompresses a string that was compressed using the Run-Length Encoding algorithm.
 *
 * @param encodedData The compressed string. Must not be null.
 * @return The original, uncompressed string.
 */
public static String decompress(String encodedData) {
if (encodedData == null || encodedData.isEmpty()) {
return "";
}
StringBuilder decodedResult = new StringBuilder();
int numberBuffer = 0;
for (char currentSymbol : encodedData.toCharArray()) {
if (Character.isDigit(currentSymbol)) {
numberBuffer = numberBuffer * 10 + (currentSymbol - '0');
} else {
decodedResult.append(String.valueOf(currentSymbol).repeat(Math.max(0, numberBuffer)));
numberBuffer = 0;
}
}
return decodedResult.toString();
}
}

