public class SansOyunu {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);
        Random rng = new Random();

        System.out.println("0 ile 100 arasinda bir sayi giriniz:");
        int guess = input.nextInt();
        input.close();

        // Reject the guess early if it falls outside the valid range.
        boolean inRange = guess >= 0 && guess <= 100;
        if (!inRange) {
            System.out.println("Lutfen 0 ile 100 arasinda bir sayi giriniz.");
            return;
        }

        // Draw the outcome roll and apply a 35% win chance threshold.
        int roll = rng.nextInt(100);
        boolean isWin = roll < 35;

        System.out.println(isWin ? "Kazandiniz!" : "Kaybettiniz!");
    }
}

