}

package functions; 
import java.util.Scanner;  // Kullanicidan girdi almak icin Scanner sinifini ice aktar

public class Faktoriyel {

    // 'faktoriyelAl' metodu, verilen sayinin faktoriyelini hesaplar
    int faktoriyelAl(int sayi) {
        int sonuc = 1;  // Faktoriyel sonucunu tutacak degisken, baslangicta 1 olmali
        // Sayi 0'dan buyuk oldugu surece dongu devam eder
        while(sayi > 0) {
            // Sonuc degiskenini her adimda sayi ile carp
            sonuc *= sayi;
            // Sayi her seferinde 1 azaltilir
            sayi--;
        }
        // Faktoriyel hesaplandiktan sonra sonuc dondurulur
        return sonuc;
    }

    public static void main(String[] args) {

        // Kullanicidan girdi almak icin Scanner nesnesi olustur
        Scanner okuyucu = new Scanner(System.in);

        // Kullanicidan bir sayi girmesini iste
        System.out.println("Lutfen bir sayi giriniz");
        int sayi = okuyucu.nextInt();  // Kullanicinin girdigi sayiyi al

        // Faktoriyel sinifindan bir nesne olustur
        Faktoriyel bulucu = new Faktoriyel();

        // 'faktoriyelAl' metodunu cagirarak sayinin faktoriyelini hesapla
        int sonuc = bulucu.faktoriyelAl(sayi);

        // Hesaplanan faktoriyel sonucunu ekrana yazdir
        System.out.println("Sonuc = " + sonuc);

        // Scanner nesnesini kapat
        okuyucu.close();
    }
}

package com.thealgorithms.maths;

/**
 * Class for linear convolution of two discrete signals
 *
 * @author Ioannis Karavitsis
 * @version 1.0
 */
public final class Convolution {
    private Convolution() {
    }

    /**
     * Discrete linear convolution function. Both input signals and the output
     * signal must start from 0. If you have a signal that has values before 0
     * then shift it to start from 0.
     *
     * @param a The first discrete signal
     * @param b The second discrete signal
     * @return The convolved signal
     */
    public static double[] convolution(double[] a, double[] b) {
        double[] convolved = new double[a.length + b.length - 1];

        /*
         * Discrete convolution formula:
         * C[i] = Σ A[k] * B[i - k]
         * where k ranges over valid indices so that both A[k] and B[i-k] are in bounds.
         */

        for (int i = 0; i < convolved.length; i++) {
            double sum = 0;
            int kStart = Math.max(0, i - b.length + 1);
            int kEnd = Math.min(i, a.length - 1);

            for (int k = kStart; k <= kEnd; k++) {
                sum += a[k] * b[i - k];
            }

            convolved[i] = sum;
        }

        return convolved;
    }
}

package eamples;
import java.util.Random; // Rastgele sayilar uretmek icin Random sinifini ice aktarir.
import java.util.Scanner; // Kullanicidan giris almak icin Scanner sinifini ice aktarir.

public class RastgeleSayiTahmin { // Ana sinif

    public static void main(String[] args) { // Programin calismaya basladigi ana fonksiyon

        // Random sinifindan bir nesne olusturur, bu nesne ile rastgele sayilar uretilir.
        Random rastgele = new Random();

        // 1 ile 100 arasinda rastgele bir sayi uretir. 'nextInt(100)' ifadesi 0-99 arasinda bir sayi uretir,
        // bu yuzden sonuca 1 eklenir ve 1-100 araliginda bir sayi elde edilir.
        int sayi = rastgele.nextInt(100) + 1; 

        // Kullanicidan giris almak icin Scanner nesnesi olusturur.
        Scanner scanner = new Scanner(System.in);

        // Kullanicinin dogru tahmini yapana kadar donecek sonsuz bir dongu baslatilir.
        while(true) {

            // Kullanicinin girdigi sayiyi okur ve 'girilen' degiskenine atar.
            int girilen = scanner.nextInt();

            // Rastgele uretilen sayi ve kullanicinin girdigi sayiyi ekrana yazdirir.
            System.out.println("Rastgele = " + sayi + " Girilen = " + girilen);

            // Eger kullanicinin girdigi sayi, rastgele uretilen sayiya esitse, donguden cikilir.
            if(sayi == girilen) {
                // Tahmin dogru, dongu sonlanir.
                break;
            } 
            // Eger girilen sayi, rastgele sayidan kucukse, kullaniciya daha buyuk bir sayi girmesi gerektigini soyler.
            else if(girilen < sayi) {
                System.out.println("Daha buyuk bir sayi giriniz (yukari).");
            } 
            // Eger girilen sayi, rastgele sayidan buyukse, kullaniciya daha kucuk bir sayi girmesi gerektigini soyler.
            else {
                System.out.println("Daha kucuk bir sayi giriniz (asagi).");
            }
        }
        // Program burada sonlanir, scanner nesnesini kapatmayi unutmamak gerekir.
        scanner.close(); 
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * This class implements Kadane's Algorithm to find the maximum subarray sum
 * within a given array of integers. The algorithm efficiently computes the maximum
 * sum of a contiguous subarray in linear time.
 *
 * Author: <a href="https://github.com/siddhant2002">Siddhant Swarup Mallick</a>
 */
public final class KadaneAlgorithm {
    private KadaneAlgorithm() {
    }

    /**
     * Computes the maximum subarray sum using Kadane's Algorithm and checks
     * if it matches a predicted answer.
     *
     * @param a              The input array of integers for which the maximum
     *                       subarray sum is to be calculated.
     * @param predictedAnswer The expected maximum subarray sum to be verified
     *                       against the computed sum.
     * @return true if the computed maximum subarray sum equals the predicted
     *         answer, false otherwise.
     *
     * <p>Example:</p>
     * <pre>
     * Input: {89, 56, 98, 123, 26, 75, 12, 40, 39, 68, 91}
     * Output: true if the maximum subarray sum is equal to the
     *         predicted answer.
     * </pre>
     *
     * <p>Algorithmic Complexity:</p>
     * <ul>
     * <li>Time Complexity: O(n) - the algorithm iterates through the array once.</li>
     * <li>Auxiliary Space Complexity: O(1) - only a constant amount of additional space is used.</li>
     * </ul>
     */
    public static boolean maxSum(int[] a, int predictedAnswer) {
        int sum = a[0];
        int runningSum = 0;

        for (int k : a) {
            runningSum += k;
            sum = Math.max(sum, runningSum);
            if (runningSum < 0) {
                runningSum = 0;
            }
        }

        return sum == predictedAnswer;
    }
}

