/**
 * Employee record with salary operations.
 */
public class Employee {
    private int employeeId;
    private String firstName;
    private String lastName;
    private int monthlySalary;

    public Employee() {
    }

    public Employee(int employeeId, String firstName, String lastName, int monthlySalary) {
        this.employeeId = employeeId;
        this.firstName = firstName;
        this.lastName = lastName;
        this.monthlySalary = monthlySalary;
    }

    public int getID() {
        return employeeId;
    }

    public void setID(int employeeId) {
        this.employeeId = employeeId;
    }

    public String getFirstName() {
        return firstName;
    }

    public void setFirstName(String firstName) {
        this.firstName = firstName;
    }

    public String getLastName() {
        return lastName;
    }

    public void setLastName(String lastName) {
        this.lastName = lastName;
    }

    public int getSalary() {
        return monthlySalary;
    }

    public void setSalary(int monthlySalary) {
        this.monthlySalary = monthlySalary;
    }

    public String getName() {
        return firstName + " " + lastName;
    }

    public int getAnnualSalary() {
        return monthlySalary * 12;
    }

    public int raiseSalary(int percent) {
        int raise = (monthlySalary * percent) / 100;
        monthlySalary += raise;
        return monthlySalary;
    }

    @Override
    public String toString() {
        return "Employee[id=" + employeeId + ",name=" + firstName + " " + lastName + ",salary=" + monthlySalary + ']';
    }
}

