public class ArmstrongNumber {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int number = scanner.nextInt();

        int original = number;
        int digits = String.valueOf(number).length();
        int sum = 0;

        while (number > 0) {
            int digit = number % 10;
            sum += Math.pow(digit, digits);
            number /= 10;
        }

        if (sum == original) {
            System.out.println(original + " is an Armstrong number");
        } else {
            System.out.println(original + " is not an Armstrong number");
        }
        scanner.close();
    }
}

/**
 * Class that provides methods to calculate the length of the shortest
 * supersequence of two given strings. The shortest supersequence is the smallest string
 * that contains both given strings as subsequences.
 */
final class ShortestCommonSupersequenceLength {
    private ShortestCommonSupersequenceLength() {
    }

    /**
     * Finds the length of the shortest supersequence of two given strings.
     * The shortest supersequence is defined as the smallest string that contains both
     * given strings as subsequences.
     *
     * @param x The first input string.
     * @param y The second input string.
     * @return The length of the shortest supersequence of the two strings.
     */
    static int shortestSuperSequence(String x, String y) {
        int m = x.length();
        int n = y.length();

        // find lcs
        int l = lcs(x, y, m, n);

        // Result is sum of input string
        // lengths - length of lcs
        return m + n - l;
    }

    /**
     * Calculates the length of the longest common subsequence (LCS) between two strings.
     * The LCS is the longest sequence that can be derived from both strings by deleting some
     * (or none) of the characters without changing the order of the remaining characters.
     *
     * @param x The first input string.
     * @param y The second input string.
     * @param m The length of the first input string.
     * @param n The length of the second input string.
     * @return The length of the longest common subsequence of the two strings.
     */
    static int lcs(String x, String y, int m, int n) {
        int[][] lN = new int[m + 1][n + 1];
        int i;
        int j;

        // Following steps build lN[m + 1][n + 1]
        // in bottom up fashion. Note that
        // lN[i][j] contains length of lNCS
        // of x[0..i - 1]and y[0..j - 1]
        for (i = 0; i <= m; i++) {
            for (j = 0; j <= n; j++) {
                if (i == 0 || j == 0) {
                    lN[i][j] = 0;
                } else if (x.charAt(i - 1) == y.charAt(j - 1)) {
                    lN[i][j] = lN[i - 1][j - 1] + 1;
                } else {
                    lN[i][j] = Math.max(lN[i - 1][j], lN[i][j - 1]);
                }
            }
        }

        // lN[m][n] contains length of LCS
        // for x[0..n - 1] and y[0..m - 1]
        return lN[m][n];
    }
}

package com.thealgorithms.geometry;
/**
 * This Class implements the Haversine formula to calculate the distance between two points on a sphere (like Earth) from their latitudes and longitudes.
 *
 * The Haversine formula is used in navigation and mapping to find the great-circle distance,
 * which is the shortest distance between two points along the surface of a sphere. It is often
 * used to calculate the "as the crow flies" distance between two geographical locations.
 *
 * The formula is reliable for all distances, including small ones, and avoids issues with
 * numerical instability that can affect other methods.
 *
 * @see "https://en.wikipedia.org/wiki/Haversine_formula" - Wikipedia
 */
public final class Haversine {

    // Average radius of Earth in kilometers
    private static final double EARTH_RADIUS_KM = 6371.0;

    /**
     * Private constructor to prevent instantiation of this utility class.
     */
    private Haversine() {
    }

    /**
     * Calculates the great-circle distance between two points on the earth
     * (specified in decimal degrees).
     *
     * @param lat1 Latitude of the first point in decimal degrees.
     * @param lon1 Longitude of the first point in decimal degrees.
     * @param lat2 Latitude of the second point in decimal degrees.
     * @param lon2 Longitude of the second point in decimal degrees.
     * @return The distance between the two points in kilometers.
     */
    public static double haversine(double lat1, double lon1, double lat2, double lon2) {
        // Convert latitude and longitude from degrees to radians
        double dLat = Math.toRadians(lat2 - lat1);
        double dLon = Math.toRadians(lon2 - lon1);

        double lat1Rad = Math.toRadians(lat1);
        double lat2Rad = Math.toRadians(lat2);

        // Apply the Haversine formula
        double a = Math.pow(Math.sin(dLat / 2), 2) + Math.pow(Math.sin(dLon / 2), 2) * Math.cos(lat1Rad) * Math.cos(lat2Rad);
        double c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

        return EARTH_RADIUS_KM * c;
    }
}

package com.thealgorithms.datastructures.stacks;

import java.util.Stack;

/**
 * Provides methods to reverse a stack using recursion.
 *
 * <p>This class includes methods to reverse the order of elements in a stack
 * without using additional data structures. Elements are inserted at the bottom
 * of the stack to achieve the reverse order.
 *
 * <p>Example usage:
 * <pre>
 *     Stack<Integer> stack = new Stack<>();
 *     stack.push(1);
 *     stack.push(2);
 *     stack.push(3);
 *     ReverseStack.reverseStack(stack);
 * </pre>
 * After calling {@code reverseStack(stack)}, the stack's order is reversed.
 *
 * <p>This class is final and has a private constructor to prevent instantiation.
 *
 * @author Ishika Agarwal, 2021
 */
public final class ReverseStack {
    private ReverseStack() {
    }

    /**
     * Reverses the order of elements in the given stack using recursion.
     * Steps:
     * 1. Check if the stack is empty. If so, return.
     * 2. Pop the top element from the stack.
     * 3. Recursively reverse the remaining stack.
     * 4. Insert the originally popped element at the bottom of the reversed stack.
     *
     * @param stack the stack to reverse; should not be null
     */
    public static void reverseStack(Stack<Integer> stack) {
        if (stack == null) {
            throw new IllegalArgumentException("Stack cannot be null");
        }
        if (stack.isEmpty()) {
            return;
        }

        int element = stack.pop();
        reverseStack(stack);
        insertAtBottom(stack, element);
    }

    /**
     * Inserts the specified element at the bottom of the stack.
     *
     * <p>This method is a helper for {@link #reverseStack(Stack)}.
     *
     * Steps:
     * 1. If the stack is empty, push the element and return.
     * 2. Remove the top element from the stack.
     * 3. Recursively insert the new element at the bottom of the stack.
     * 4. Push the removed element back onto the stack.
     *
     * @param stack the stack in which to insert the element; should not be null
     * @param element the element to insert at the bottom of the stack
     */
    private static void insertAtBottom(Stack<Integer> stack, int element) {
        if (stack.isEmpty()) {
            stack.push(element);
            return;
        }

        int topElement = stack.pop();
        insertAtBottom(stack, element);
        stack.push(topElement);
    }
}

public class LFSR implements BaseLFSR {

    private final BitSet register;
    private final int length;
    private final int clockBitIndex;
    private final int[] tappingBitsIndices;

    public LFSR(int length, int clockBitIndex, int[] tappingBitsIndices) {
        this.length = length;
        this.clockBitIndex = clockBitIndex;
        this.tappingBitsIndices = tappingBitsIndices;
        register = new BitSet(length);
    }

    @Override
    public void initialize(BitSet sessionKey, BitSet frameCounter) {
        register.clear();
        clock(sessionKey, SESSION_KEY_LENGTH);
        clock(frameCounter, FRAME_COUNTER_LENGTH);
    }

    private void clock(BitSet key, int keyLength) {
        // We start from reverse because LFSR 0 index is the left most bit
        // while key 0 index is right most bit, so we reverse it
        for (int i = keyLength - 1; i >= 0; --i) {
            var newBit = key.get(i) ^ xorTappingBits();
            pushBit(newBit);
        }
    }

    @Override
    public boolean clock() {
        return pushBit(xorTappingBits());
    }

    public boolean getClockBit() {
        return register.get(clockBitIndex);
    }

    public boolean get(int bitIndex) {
        return register.get(bitIndex);
    }

    public boolean getLastBit() {
        return register.get(length - 1);
    }

    private boolean xorTappingBits() {
        boolean result = false;
        for (int i : tappingBitsIndices) {
            result ^= register.get(i);
        }
        return result;
    }

    private boolean pushBit(boolean bit) {
        boolean discardedBit = rightShift();
        register.set(0, bit);
        return discardedBit;
    }

    private boolean rightShift() {
        boolean discardedBit = get(length - 1);
        for (int i = length - 1; i > 0; --i) {
            register.set(i, get(i - 1));
        }
        register.set(0, false);
        return discardedBit;
    }

    @Override
    public String toString() {
        return register.toString();
    }
}

package array;

public class SecmeliSiralama {

    public static void main(String[] args) {
        int[] degerler = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        siralamayiUygula(degerler);

        System.out.println("Siralanmis Dizi:");
        StringBuilder cikti = new StringBuilder();
        for (int deger : degerler) {
            cikti.append(deger).append(' ');
        }
        System.out.print(cikti);
    }

    // Selection sort - her turda kalan en kucuk elemani one tasir
    public static void siralamayiUygula(int[] degerler) {
        int uzunluk = degerler.length;

        for (int sinir = 0; sinir < uzunluk - 1; sinir++) {
            int enKucukKonum = sinir;

            for (int arayan = sinir + 1; arayan < uzunluk; arayan++) {
                if (degerler[arayan] < degerler[enKucukKonum]) {
                    enKucukKonum = arayan;
                }
            }

            if (enKucukKonum != sinir) {
                int gecici = degerler[sinir];
                degerler[sinir] = degerler[enKucukKonum];
                degerler[enKucukKonum] = gecici;
            }
        }
    }
}

public class Main {
    public static void main(String[] args) throws CloneNotSupportedException {
        Human ankan = new Human(21, "Ankan");
//        Human twin = new Human(ankan); //creating a copy of ankan. Instead we can use object cloning.

        Human twin = (Human)ankan.clone();
        System.out.println(twin.age + " " + twin.name);
        System.out.println(Arrays.toString(twin.arr));

        twin.arr[0] = 100; // for primitives, it does not create a copy of an array. It just points to the original
        // array. Even for String which is a primitive, it just points to the original name. This is shallow copying.

        System.out.println(Arrays.toString(twin.arr));
        System.out.println(Arrays.toString(ankan.arr)); // very important
    }
}

