/*
 * Java program for Binomial Coefficients
 * Binomial Coefficients: A binomial coefficient C(n,k) gives number ways
 * in which k objects can be chosen from n objects.
 * Wikipedia: https://en.wikipedia.org/wiki/Binomial_coefficient
 *
 * Author: Akshay Dubey (https://github.com/itsAkshayDubey)
 *
 * */

public final class BinomialCoefficient {
    private BinomialCoefficient() {
    }

    /**
     * This method returns the number of ways in which k objects can be chosen from n objects
     *
     * @param totalObjects    Total number of objects
     * @param numberOfObjects Number of objects to be chosen from total_objects
     * @return number of ways in which no_of_objects objects can be chosen from total_objects
     *     objects
     */

    public static int binomialCoefficient(int totalObjects, int numberOfObjects) {
        // Base Case
        if (numberOfObjects > totalObjects) {
            return 0;
        }

        // Base Case
        if (numberOfObjects == 0 || numberOfObjects == totalObjects) {
            return 1;
        }

        // Recursive Call
        return (binomialCoefficient(totalObjects - 1, numberOfObjects - 1) + binomialCoefficient(totalObjects - 1, numberOfObjects));
    }
}

package player;

/**
 * A player with income subject to a tiered tax.
 */
public class PlayerIncome extends Player implements Tax {

    private double income;

    public PlayerIncome(double income) {
        this.income = income;
    }

    public PlayerIncome(double income, String name) {
        super(name);
        this.income = income;
    }

    public PlayerIncome() {
    }

    public double getIncome() {
        return income;
    }

    public void setIncome(double income) {
        this.income = income;
    }

    @Override
    public void displayDetails() {
        System.out.println("Name player: " + getName());
        System.out.println("Salary: " + (income - calculateTax()) + "$");
        System.out.println("Tax: " + calculateTax() + "$");
    }

    @Override
    public double calculateTax() {
        if (income <= 10000) {
            return income * 15 / 100;
        } else if (income <= 20000) {
            return income * 20 / 100;
        } else {
            return income * 30 / 100;
        }
    }
}

/**
 * Utility class to find the number of unique subsequences that can be
 * produced from a given string.
 *
 * <p> This class contains static methods to compute the unique subsequence count
 * using dynamic programming and recursion. It ensures that duplicate characters
 * are not counted multiple times in the subsequences.</p>
 *
 * <p> Author: https://github.com/Tuhinm2002 </p>
 */
public final class UniqueSubsequencesCount {

    /**
     * Private constructor to prevent instantiation of this utility class.
     * This class should only be used in a static context.
     *
     * @throws UnsupportedOperationException if attempted to instantiate.
     */
    private UniqueSubsequencesCount() {
        throw new UnsupportedOperationException("Utility class");
    }

    /**
     * Finds the number of unique subsequences that can be generated from
     * the given string.
     *
     * <p> This method initializes a dynamic programming (DP) array and invokes
     * the recursive helper function to compute the subsequence count.</p>
     *
     * @param str the input string from which subsequences are generated
     * @return the total count of unique subsequences
     */
    public static int countSubseq(String str) {

        // DP array initialized to store intermediate results
        int[] dp = new int[str.length() + 1];
        Arrays.fill(dp, -1);

        // Calls the recursive function to compute the result
        return countSubsequences(str, 0, dp);
    }

    /**
     * Recursive helper function to count the number of unique subsequences
     * starting from the given index.
     *
     * <p> Uses a HashSet to avoid counting duplicate characters within
     * a single subsequence.</p>
     *
     * @param st the input string
     * @param idx the current index from which to calculate subsequences
     * @param dp dynamic programming array used to memoize results
     * @return the total number of unique subsequences starting from the
     *         current index
     */
    public static int countSubsequences(String st, int idx, int[] dp) {

        // Base case: when index exceeds the string length
        if (idx >= st.length()) {
            return 0;
        }

        // If result is already calculated, return the memoized value
        if (dp[idx] != -1) {
            return dp[idx];
        }

        // Set to store characters to avoid duplicates
        Set<Character> set = new HashSet<>();

        int res = 0;

        // Iterate over the string starting from current index
        for (int j = idx; j < st.length(); j++) {

            // If character is already in the set, skip it
            if (set.contains(st.charAt(j))) {
                continue;
            }

            // Add character to set and recursively calculate subsequences
            set.add(st.charAt(j));

            // 1 for the current subsequence + recursive call for the rest of the string
            res = 1 + countSubsequences(st, j + 1, dp) + res;
        }

        // Memoize the result
        dp[idx] = res;
        return dp[idx];
    }
}

/**
 * A utility class for converting between IPv6 and IPv4 addresses.
 *
 * - Converts IPv4 to IPv6-mapped IPv6 address.
 * - Extracts IPv4 address from IPv6-mapped IPv6.
 * - Handles exceptions for invalid inputs.
 *
 * @author Hardvan
 */
public final class IPv6Converter {
private IPv6Converter() {
}

/**
 * Converts an IPv4 address (e.g., "192.0.2.128") to an IPv6-mapped IPv6 address.
 * Example: IPv4 "192.0.2.128" -> IPv6 "::ffff:192.0.2.128"
 *
 * @param ipv4String The IPv4 address in string format.
 * @return The corresponding IPv6-mapped IPv6 address.
 * @throws UnknownHostException If the IPv4 address is invalid.
 * @throws IllegalArgumentException If the IPv6 address is not a mapped IPv4 address.
 */
public static String ipv4ToIpv6(String ipv4String) throws UnknownHostException {
if (ipv4String == null || ipv4String.isEmpty()) {
throw new UnknownHostException("IPv4 address is empty.");
}
InetAddress ipv4Address = InetAddress.getByName(ipv4String);
byte[] ipv4Bytes = ipv4Address.getAddress();
byte[] ipv6Bytes = new byte[16];
ipv6Bytes[10] = (byte) 0xff;
ipv6Bytes[11] = (byte) 0xff;
System.arraycopy(ipv4Bytes, 0, ipv6Bytes, 12, 4);
StringBuilder mappedIpv6 = new StringBuilder("::ffff:");
for (int segment = 12; segment < 16; segment++) {
mappedIpv6.append(ipv6Bytes[segment] & 0xFF);
if (segment < 15) {
mappedIpv6.append('.');
}
}
return mappedIpv6.toString();
}

/**
 * Extracts the IPv4 address from an IPv6-mapped IPv6 address.
 * Example: IPv6 "::ffff:192.0.2.128" -> IPv4 "192.0.2.128"
 *
 * @param ipv6String The IPv6 address in string format.
 * @return The extracted IPv4 address.
 * @throws UnknownHostException If the IPv6 address is invalid or not a mapped IPv4 address.
 */
public static String ipv6ToIpv4(String ipv6String) throws UnknownHostException {
InetAddress ipv6Address = InetAddress.getByName(ipv6String);
byte[] ipv6Bytes = ipv6Address.getAddress();
if (isMappedIpv4Address(ipv6Bytes)) {
byte[] ipv4Bytes = Arrays.copyOfRange(ipv6Bytes, 12, 16);
InetAddress ipv4Result = InetAddress.getByAddress(ipv4Bytes);
return ipv4Result.getHostAddress();
} else {
throw new IllegalArgumentException("Not a valid IPv6-mapped IPv4 address.");
}
}

/**
 * Helper function to check if the given byte array represents
 * an IPv6-mapped IPv4 address (prefix 0:0:0:0:0:ffff).
 *
 * @param ipv6Bytes Byte array representation of the IPv6 address.
 * @return True if the address is IPv6-mapped IPv4, otherwise false.
 */
private static boolean isMappedIpv4Address(byte[] ipv6Bytes) {
if (ipv6Bytes.length != 16) {
return false;
}
for (int offset = 0; offset < 10; offset++) {
if (ipv6Bytes[offset] != 0) {
return false;
}
}
return ipv6Bytes[10] == (byte) 0xff && ipv6Bytes[11] == (byte) 0xff;
}
}

package chat;

import java.awt.BorderLayout;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.IOException;
import java.io.PrintWriter;
import java.net.Socket;
import java.util.Scanner;

import javax.swing.JFrame;
import javax.swing.JOptionPane;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.WindowConstants;

/**
 * Swing chat window that speaks the tiny line-based protocol expected
 * by ChatServer: SUBMITNAME / NAMEACCEPTED / MESSAGE.
 */
public class ChatClient {

    private static final int SERVER_PORT = 59001;

    private final String host;
    private Scanner serverIn;
    private PrintWriter serverOut;

    private final JFrame window = new JFrame("Chatter");
    private final JTextField composeField = new JTextField(50);
    private final JTextArea history = new JTextArea(16, 50);

    public ChatClient(String host) {
        this.host = host;

        composeField.setEditable(false);
        history.setEditable(false);
        window.getContentPane().add(composeField, BorderLayout.SOUTH);
        window.getContentPane().add(new JScrollPane(history), BorderLayout.CENTER);
        window.pack();

        composeField.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent event) {
                serverOut.println(composeField.getText());
                composeField.setText("");
            }
        });
    }

    private String promptForScreenName() {
        return JOptionPane.showInputDialog(window, "Choose a screen name:", "Screen name selection",
                JOptionPane.PLAIN_MESSAGE);
    }

    private void connectAndListen() throws IOException {
        try (var socket = new Socket(host, SERVER_PORT)) {
            serverIn = new Scanner(socket.getInputStream());
            serverOut = new PrintWriter(socket.getOutputStream(), true);

            while (serverIn.hasNextLine()) {
                String line = serverIn.nextLine();
                if (line.startsWith("SUBMITNAME")) {
                    serverOut.println(promptForScreenName());
                } else if (line.startsWith("NAMEACCEPTED")) {
                    window.setTitle("Chatter - " + line.substring(13));
                    composeField.setEditable(true);
                } else if (line.startsWith("MESSAGE")) {
                    history.append(line.substring(8) + "\n");
                }
            }
        } finally {
            window.setVisible(false);
            window.dispose();
        }
    }

    public static void main(String[] args) throws Exception {
        var client = new ChatClient("localhost");
        client.window.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
        client.window.setVisible(true);
        client.connectAndListen();
    }
}

package com.thealgorithms.datastructures.stacks;

import java.util.NoSuchElementException;

/**
 * A stack implementation using a singly linked list.
 *
 * <p>This class provides methods to push, pop, and peek elements in a Last-In-First-Out (LIFO) manner.
 * It keeps track of the number of elements in the stack and allows checking if the stack is empty.
 *
 * <p>This implementation does not allow null elements to be pushed onto the stack.
 */
final class StackOfLinkedList {
    private StackOfLinkedList() {
    }
}

// A node class for the linked list
class Node {
    public int data;
    public Node next;

    Node(int data) {
        this.data = data;
        this.next = null;
    }
}

/**
 * A class that implements a stack using a linked list.
 *
 * <p>This stack supports basic operations:
 * <ul>
 * <li>push: Adds an element to the top of the stack</li>
 * <li>pop: Removes and returns the top element of the stack</li>
 * <li>peek: Returns the top element without removing it</li>
 * <li>isEmpty: Checks if the stack is empty</li>
 * <li>getSize: Returns the current size of the stack</li>
 * </ul>
 */
class LinkedListStack {

    private Node head; // Top of the stack
    private int size; // Number of elements in the stack

    /**
     * Initializes an empty stack.
     */
    LinkedListStack() {
        head = null;
        size = 0;
    }

    /**
     * Adds an element to the top of the stack.
     *
     * @param x the element to be added
     * @return <tt>true</tt> if the element is added successfully
     */
    public boolean push(int x) {
        Node newNode = new Node(x);
        newNode.next = head;
        head = newNode;
        size++;
        return true;
    }

    /**
     * Removes and returns the top element of the stack.
     *
     * @return the element at the top of the stack
     * @throws NoSuchElementException if the stack is empty
     */
    public int pop() {
        if (size == 0) {
            throw new NoSuchElementException("Empty stack. Nothing to pop");
        }
        Node destroy = head;
        head = head.next;
        int retValue = destroy.data;
        destroy = null; // Help garbage collection
        size--;
        return retValue;
    }

    /**
     * Returns the top element of the stack without removing it.
     *
     * @return the element at the top of the stack
     * @throws NoSuchElementException if the stack is empty
     */
    public int peek() {
        if (size == 0) {
            throw new NoSuchElementException("Empty stack. Nothing to peek");
        }
        return head.data;
    }

    @Override
    public String toString() {
        Node cur = head;
        StringBuilder builder = new StringBuilder();
        while (cur != null) {
            builder.append(cur.data).append("->");
            cur = cur.next;
        }
        return builder.replace(builder.length() - 2, builder.length(), "").toString(); // Remove the last "->"
    }

    /**
     * Checks if the stack is empty.
     *
     * @return <tt>true</tt> if the stack is empty, <tt>false</tt> otherwise
     */
    public boolean isEmpty() {
        return size == 0;
    }

    /**
     * Returns the current size of the stack.
     *
     * @return the number of elements in the stack
     */
    public int getSize() {
        return size;
    }

    /**
     * Removes all elements from the stack.
     */
    public void makeEmpty() {
        head = null;
        size = 0;
    }
}

package checked;

public class SinifBulunamadiHatasi {

	public static void main(String[] args) {
		try {
			// Load a class that definitely exists in the JDK
			String targetClass = "java.util.Scanner";
			Class<?> loaded = Class.forName(targetClass);
			System.out.println(targetClass + " sinifi basariyla yuklendi.");

			// Load another class known to be present in this project
			targetClass = "checked.DosyaOkumaHatasi";
			loaded = Class.forName(targetClass);
			System.out.println(targetClass + " sinifi basariyla yuklendi.");

			// This one does not exist, so Class.forName should throw
			String missingClass = "com.ornek.Sinif";
			Class<?> notFound = Class.forName(missingClass);
			System.out.println(missingClass + " sinifi basariyla yuklendi.");

		} catch (ClassNotFoundException notFoundEx) {
			System.out.println("Sinif bulunamadi: " + notFoundEx.getMessage());
			notFoundEx.printStackTrace();
		} finally {
			System.out.println("Islem tamamlandi.");
		}
	}
}

public class SayiOkuma {

    public static void main(String[] args) {

        System.out.println(sayiOkunusu(1234));  // Sayinin okunusunu yazdir

        System.out.println(sayiOkunusu(7248));  

        System.out.println(sayiOkunusu(297));  

        System.out.println(sayiOkunusu(505));  

        System.out.println(sayiOkunusu(300));  
    }

    // Sayinin okunusunu donduren fonksiyon
    public static String sayiOkunusu(int sayi) {
        // Eger sayi 0 ise "sifir" dondurulur
        if (sayi == 0) return "sifir";

        // Birler, onlar, yuzler ve binler basamagi icin diziler
        String[] birler = {"", "bir", "iki", "uc", "dort", "bes", "alti", "yedi", "sekiz", "dokuz"};
        String[] onlar = {"", "on", "yirmi", "otuz", "kirk", "elli", "altmis", "yetmis", "seksen", "doksan"};
        String[] yuzler = {"", "yuz"};  // Yuzler icin sadece "yuz" kelimesi var
        String[] binler = {"", "bin"};  // Binler icin sadece "bin" kelimesi var

        // Sonuc metnini tutacak degisken
        String sonuc = "";

        // Binler basamagini ayirma
        int bin = sayi / 1000;
        // Yuzler basamagini ayirma
        int yuz = (sayi / 100) % 10;
        // Onlar basamagini ayirma
        int on = (sayi / 10) % 10;
        // Birler basamagini ayirma
        int bir = sayi % 10;

        // Binler basamagi varsa eklenir
        if (bin > 0) {
            // Binler basamagi 1'den buyukse, sayinin okunusu da eklenir
            if (bin > 1) sonuc += birler[bin] + " ";
            sonuc += binler[1] + " ";  // "bin" kelimesi eklenir
        }

        // Yuzler basamagi varsa eklenir
        if (yuz > 0) {
            // Yuzler basamagi 1'den buyukse, sayinin okunusu da eklenir
            if (yuz > 1) sonuc += birler[yuz] + " ";
            sonuc += yuzler[1] + " ";  // "yuz" kelimesi eklenir
        }

        // Onlar basamagi varsa eklenir
        if (on > 0) {
            sonuc += onlar[on] + " ";  // Onlar basamaginin okunusu eklenir
        }

        // Birler basamagi varsa eklenir
        if (bir > 0) {
            sonuc += birler[bir];  // Birler basamaginin okunusu eklenir
        }

        return sonuc;
    }
}

