package com.thealgorithms.datastructures.hashmap.hashing;

import java.util.LinkedList;

/**
 * A generic implementation of a hash map using an array of linked lists for collision resolution.
 * This class provides a way to store key-value pairs efficiently, allowing for average-case
 * constant time complexity for insertion, deletion, and retrieval operations.
 *
 * <p>
 * The hash map uses separate chaining for collision resolution. Each bucket in the hash map is a
 * linked list that stores nodes containing key-value pairs. When a collision occurs (i.e., when
 * two keys hash to the same index), the new key-value pair is simply added to the corresponding
 * linked list.
 * </p>
 *
 * <p>
 * The hash map automatically resizes itself when the load factor exceeds 0.75. The load factor is
 * defined as the ratio of the number of entries to the number of buckets. When resizing occurs,
 * all existing entries are rehashed and inserted into the new buckets.
 * </p>
 *
 * @param <K> the type of keys maintained by this hash map
 * @param <V> the type of mapped values
 */
@SuppressWarnings({"rawtypes", "unchecked"})
public class GenericHashMapUsingArray<K, V> {

    private int size; // Total number of key-value pairs
    private LinkedList<Node>[] buckets; // Array of linked lists (buckets) for storing entries

    /**
     * Constructs a new empty hash map with an initial capacity of 16.
     */
    public GenericHashMapUsingArray() {
        initBuckets(16);
        size = 0;
    }

    /**
     * Initializes the buckets for the hash map with the specified number of buckets.
     *
     * @param n the number of buckets to initialize
     */
    private void initBuckets(int n) {
        buckets = new LinkedList[n];
        for (int i = 0; i < buckets.length; i++) {
            buckets[i] = new LinkedList<>();
        }
    }

    /**
     * Associates the specified value with the specified key in this map.
     * If the map previously contained a mapping for the key, the old value is replaced.
     *
     * @param key the key with which the specified value is to be associated
     * @param value the value to be associated with the specified key
     */
    public void put(K key, V value) {
        int bucketIndex = hashFunction(key);
        LinkedList<Node> nodes = buckets[bucketIndex];
        // Update existing key's value if present
        for (Node node : nodes) {
            if (node.key.equals(key)) {
                node.value = value;
                return;
            }
        }

        // Insert new key-value pair
        nodes.add(new Node(key, value));
        size++;

        // Check if rehashing is needed
        // Load factor threshold for resizing
        float loadFactorThreshold = 0.75f;
        if ((float) size / buckets.length > loadFactorThreshold) {
            reHash();
        }
    }

    /**
     * Returns the index of the bucket in which the key would be stored.
     *
     * @param key the key whose bucket index is to be computed
     * @return the bucket index
     */
    private int hashFunction(K key) {
        return Math.floorMod(key.hashCode(), buckets.length);
    }

    /**
     * Rehashes the map by doubling the number of buckets and re-inserting all entries.
     */
    private void reHash() {
        LinkedList<Node>[] oldBuckets = buckets;
        initBuckets(oldBuckets.length * 2);
        this.size = 0;

        for (LinkedList<Node> nodes : oldBuckets) {
            for (Node node : nodes) {
                put(node.key, node.value);
            }
        }
    }

    /**
     * Removes the mapping for the specified key from this map if present.
     *
     * @param key the key whose mapping is to be removed from the map
     */
    public void remove(K key) {
        int bucketIndex = hashFunction(key);
        LinkedList<Node> nodes = buckets[bucketIndex];

        Node target = null;
        for (Node node : nodes) {
            if (node.key.equals(key)) {
                target = node;
                break;
            }
        }

        if (target != null) {
            nodes.remove(target);
            size--;
        }
    }

    /**
     * Returns the number of key-value pairs in this map.
     *
     * @return the number of key-value pairs
     */
    public int size() {
        return this.size;
    }

    /**
     * Returns the value to which the specified key is mapped, or null if this map contains no mapping for the key.
     *
     * @param key the key whose associated value is to be returned
     * @return the value associated with the specified key, or null if no mapping exists
     */
    public V get(K key) {
        int bucketIndex = hashFunction(key);
        LinkedList<Node> nodes = buckets[bucketIndex];
        for (Node node : nodes) {
            if (node.key.equals(key)) {
                return node.value;
            }
        }
        return null;
    }

    @Override
    public String toString() {
        StringBuilder builder = new StringBuilder();
        builder.append("{");
        for (LinkedList<Node> nodes : buckets) {
            for (Node node : nodes) {
                builder.append(node.key);
                builder.append(" : ");
                builder.append(node.value);
                builder.append(", ");
            }
        }
        // Remove trailing comma and space
        if (builder.length() > 1) {
            builder.setLength(builder.length() - 2);
        }
        builder.append("}");
        return builder.toString();
    }

    /**
     * Returns true if this map contains a mapping for the specified key.
     *
     * @param key the key whose presence in this map is to be tested
     * @return true if this map contains a mapping for the specified key
     */
    public boolean containsKey(K key) {
        return get(key) != null;
    }

    /**
     * A private class representing a key-value pair (node) in the hash map.
     */
    public class Node {
        K key;
        V value;

        /**
         * Constructs a new Node with the specified key and value.
         *
         * @param key the key of the key-value pair
         * @param value the value of the key-value pair
         */
        public Node(K key, V value) {
            this.key = key;
            this.value = value;
        }
    }
}

/**
 * BinaryAddition class to perform binary addition of two binary strings.
 */
public class BinaryAddition {
    /**
     * Computes the sum of two binary characters and a carry.
     * @param a First binary character ('0' or '1').
     * @param b Second binary character ('0' or '1').
     * @param carry The carry from the previous operation ('0' or '1').
     * @return The sum as a binary character ('0' or '1').
     */
    public char sum(char a, char b, char carry) {
        int count = 0;
        if (a == '1') {
            count++;
        }
        if (b == '1') {
            count++;
        }
        if (carry == '1') {
            count++;
        }
        return count % 2 == 0 ? '0' : '1';
    }
    /**
     * Computes the carry for the next higher bit from two binary characters and a carry.
     * @param a First binary character ('0' or '1').
     * @param b Second binary character ('0' or '1').
     * @param carry The carry from the previous operation ('0' or '1').
     * @return The carry for the next bit ('0' or '1').
     */
    public char carry(char a, char b, char carry) {
        int count = 0;
        if (a == '1') {
            count++;
        }
        if (b == '1') {
            count++;
        }
        if (carry == '1') {
            count++;
        }
        return count >= 2 ? '1' : '0';
    }
    /**
     * Adds two binary strings and returns their sum as a binary string.
     * @param a First binary string.
     * @param b Second binary string.
     * @return Binary string representing the sum of the two binary inputs.
     */
    public String addBinary(String a, String b) {
        // Padding the shorter string with leading zeros
        int maxLength = Math.max(a.length(), b.length());
        a = String.join("", Collections.nCopies(maxLength - a.length(), "0")) + a;
        b = String.join("", Collections.nCopies(maxLength - b.length(), "0")) + b;
        StringBuilder result = new StringBuilder();
        char carry = '0';
        // Iterating over the binary strings from the least significant to the most significant bit
        for (int i = maxLength - 1; i >= 0; i--) {
            char sum = sum(a.charAt(i), b.charAt(i), carry);
            carry = carry(a.charAt(i), b.charAt(i), carry);
            result.append(sum);
        }
        // If there's a remaining carry, append it
        if (carry == '1') {
            result.append('1');
        }
        // Reverse the result as we constructed it from the least significant bit
        return result.reverse().toString();
    }
}

package unchecked;

public class BosReferansHatasi {

    public static void main(String[] args) {

        // Null degeri atanmis bir nesne olustur
        String str = null;

        try {
            // Null olan nesne uzerinde bir metod cagirilmaya calisilir
            int uzunluk = str.length(); // Burada NullPointerException olusur
            System.out.println("String uzunlugu: " + uzunluk);
        } catch (NullPointerException e) {
            // NullPointerException yakalanir ve kullaniciya mesaj verilir
            System.out.println("Hata: Null deger uzerinde islem yapilamaz!");
            System.out.println("Hata mesaji: " + e.getMessage());
            e.printStackTrace(); // Istisnanin izini yazdir
        } finally {
            // Kaynak temizleme veya islemin tamamlandigini bildirmek icin kullanilir
            System.out.println("Islem tamamlandi.");
        }

        // Alternatif bir ornek: Null degeri olmayan bir nesne
        String str2 = "Merhaba";
        System.out.println("String uzunlugu: " + str2.length()); // Bu islem basariyla calisir
    }
}

public class Singleton {
    private int internalNumber = 0;  // Example instance variable (not related to singleton pattern)

    // Private constructor prevents instantiation from outside the Singleton class
    // This is the key to the Singleton pattern - only Singleton can create its own instance
    private Singleton() {
        System.out.println("Singleton instance created (constructor called)");
        // Private constructor restricts creating multiple objects
        // No external class can use 'new Singleton()'
    }

    // Static variable that holds the single instance of the Singleton class
    // Being static ensures the variable belongs to the class itself, not to any instance
    // Since the constructor is private, only the Singleton class can assign a value to this variable
    private static Singleton uniqueInstance = null;

    // Static method that provides global access point to the single instance
    // Synchronized keyword makes it thread-safe (prevents multiple threads from creating multiple instances)
    public static synchronized Singleton getInstance() {
        // Check whether an instance has already been created or not
        // Lazy initialization: create instance only when first requested
        if (uniqueInstance == null) {
            uniqueInstance = new Singleton();  // Create the single instance
        }
        return uniqueInstance;  // Return the existing instance
    }

    // Optional: Method to display the instance's internal state
    public void displayInstanceInfo() {
        System.out.println("Singleton instance hashcode: " + this.hashCode());
        System.out.println("Internal number value: " + internalNumber);
    }

    // Optional: Method to modify internal state (demonstrates that single instance state is shared)
    public void setInternalNumber(int newValue) {
        this.internalNumber = newValue;
        System.out.println("Internal number updated to: " + internalNumber);
    }
}

/*
Important Notes about Singleton Pattern:
=========================================

1. Private Constructor:
   - Cannot be called from outside the Singleton class
   - Prevents external code from creating multiple instances
   - Example: Singleton obj = new Singleton(); // COMPILATION ERROR

2. Private Static Instance:
   - Holds the single instance of the class
   - Static means it belongs to the class level, not object level
   - Private means only Singleton class can access it directly

3. Public Static getInstance() Method:
   - Global access point to get the singleton instance
   - Static so can be called without an object: Singleton.getInstance()
   - Synchronized for thread safety in multi-threaded environments

4. Lazy Initialization:
   - Instance is created only when first requested, not at class loading time
   - Saves resources if the instance is never used

5. Thread Safety:
   - The 'synchronized' keyword ensures only one thread can execute getInstance() at a time
   - Prevents race conditions that could create multiple instances

What WON'T Work (External Access Attempts):
===========================================

class Example {
    void attemptToCreateSingleton() {
        // Cannot access private constructor:
        // Singleton invalidInstance = new Singleton();  // COMPILATION ERROR

        // Cannot access private static field:
        // Singleton.uniqueInstance = new Singleton();   // COMPILATION ERROR

        // Only valid way to get instance:
        Singleton validInstance = Singleton.getInstance();  // ✅ WORKS
    }
}

Since 'instance' is private, it cannot be accessed outside the Singleton class.
Since Singleton constructor is private, it cannot create a new object outside the Singleton class.
*/

/**
 * This class provides a method to find the majority element(s) in an array of integers.
 * A majority element is defined as an element that appears at least ⌊n/2⌋ times,
 * where n is the length of the array. If multiple elements qualify as majority elements,
 * they are all returned in a list.
 */
public final class MajorityElement {
private MajorityElement() {
}

/**
 * Returns a list of majority element(s) from the given array of integers.
 *
 * @param inputNumbers an array of integers
 * @return a list containing the majority element(s); returns an empty list if none exist or input is null/empty
 */
public static List<Integer> findMajority(int[] inputNumbers) {
if (inputNumbers == null || inputNumbers.length == 0) {
return Collections.emptyList();
}
Map<Integer, Integer> frequencyMapping = new HashMap<>();
for (final var currentNumber : inputNumbers) {
frequencyMapping.merge(currentNumber, 1, Integer::sum);
}
List<Integer> resultElements = new ArrayList<>();
for (final var frequencyEntry : frequencyMapping.entrySet()) {
if (frequencyEntry.getValue() >= inputNumbers.length / 2) {
resultElements.add(frequencyEntry.getKey());
}
}
return resultElements;
}
}

