 * @author GIA KINH
 */

class MyPoint {
    private int x;
    private int y;

    public MyPoint() {
    }

    public MyPoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int[] getXY() {
        return new int[]{this.x, this.y};
    }

    public void setXY(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public double distance(int x, int y) {
        return (double) Math.sqrt(Math.pow((x - this.x), 2) + Math.pow((y - this.y), 2));
    }

    public double distance(MyPoint another) {
        return (double) Math.sqrt(Math.pow((another.x - this.x), 2) + Math.pow((another.y - this.y), 2));
    }

    public double distance() {
        return (double) Math.sqrt(Math.pow((0 - this.x), 2) + Math.pow((0 - this.y), 2));
    }

    @Override
    public String toString() {
        return "(" +x + "," + y + ')';
    }
}

public class MyLine {
    private MyPoint begin;
    private MyPoint end;

    public MyLine(int x1, int y1,int x2,int y2) {
        this.begin = new MyPoint(x1, y1);
        this.end = new MyPoint(x2,y2);
    }

    public MyLine(MyPoint begin, MyPoint end) {
        this.begin = begin;
        this.end = end;
    }

    public MyPoint getBegin() {
        return begin;
    }

    public void setBegin(MyPoint begin) {
        this.begin = begin;
    }

    public MyPoint getEnd() {
        return end;
    }

    public void setEnd(MyPoint end) {
        this.end = end;
    }

    public void setBeginX(int x){
        this.begin.setX(x);
    }

    public int getBeginX(){
        return this.begin.getX();
    }

    public void setBeginY(int y){
        this.begin.setY(y);
    }

    public int getBeginY(){
        return this.begin.getY();
    }

    public void setEndX(int x){
        this.end.setX(x);
    }

    public int getEndX(){
        return this.end.getX();
    }

    public void setEndY(int y){
        this.end.setY(y);
    }

    public int getEndY(){
        return this.end.getY();
    }

    public void setBeginXY(int x, int y){
        this.begin.setXY(x, y);
    }

    public int[] getBeginXY(){
        return this.begin.getXY();
    }

    public void setEndXY(int x, int y){
        this.end.setXY(x, y);
    }

    public int[] getEndXY(){
        return this.end.getXY();
    }

    public double getLength(){
        return this.begin.distance(this.end);
    }

    public double getGradient(){
        return Math.atan2(this.end.getY()-this.begin.getY(), this.end.getX()-this.begin.getX());
    }

    @Override
    public String toString() {
        return "MyLine[" + "begin=" + begin + ",end=" + end + ']';
    }
}


class TestMyLine{
    public static void main(String[] args) {
           MyLine myLine = new MyLine(new MyPoint(0, 1), new MyPoint(3, 4));
           System.out.println(myLine.getLength());
           System.out.println(myLine.getGradient());
           System.out.println(myLine.toString());
           System.out.println(Arrays.toString(myLine.getBeginXY()));
           System.out.println(Arrays.toString(myLine.getEndXY()));
    }
}

public class CapitalizeServer {

	public static void main(String[] args) throws Exception {
		// 59898 portunda dinlemeye baslar
		try (var listener = new ServerSocket(59898)) {
			System.out.println("Buyuk harfe cevirme sunucusu calisiyor...");

			// Thread havuzu olusturulur, en fazla 20 thread calistirilabilir
			var pool = Executors.newFixedThreadPool(20);

			// Sonsuz dongu ile her baglantiyi kabul eder ve isler
			while (true) {
				pool.execute(new Capitalizer(listener.accept())); // Yeni bir baglanti alinir ve yeni thread ile islenir
			}
		}
	}

	// Capitalizer sinifi, her bir istemciyi islemek icin calisan bir thread'i temsil eder
	private static class Capitalizer implements Runnable {
		private Socket socket;

		// Constructor: Istemci soketini alir
		Capitalizer(Socket socket) {
			this.socket = socket;
		}

		@Override
		public void run() {
			System.out.println("Baglantili: " + socket);
			try (var in = new Scanner(socket.getInputStream())) { // Istemciden veri almak icin scanner
				var out = new PrintWriter(socket.getOutputStream(), true); // Istemciye veri gondermek icin printwriter

				// Istemciden gelen her satir alinir ve buyuk harfe cevrilir
				while (in.hasNextLine()) {
					out.println(in.nextLine().toUpperCase()); // Veriyi buyuk harfe cevirip gonderir
				}
			} catch (Exception e) {
				System.out.println("Hata: " + socket);
			} finally {
				// Soket kapatilir
				try {
					socket.close();
				} catch (IOException e) {
					System.out.println("Hata: " + socket);
				}
				System.out.println("Kapatildi: " + socket);
			}
		}
	}
}

package com.thealgorithms.datastructures.hashmap.hashing;

import java.util.ArrayList;
import java.util.LinkedList;

/**
 * A generic implementation of a hash map using an array list of linked lists for collision resolution.
 * This class allows storage of key-value pairs with average-case constant time complexity for insertion,
 * deletion, and retrieval operations.
 *
 * <p>
 * The hash map uses separate chaining to handle collisions. Each bucket in the hash map is represented
 * by a linked list that holds nodes containing key-value pairs. When multiple keys hash to the same index,
 * they are stored in the same linked list.
 * </p>
 *
 * <p>
 * The hash map automatically resizes itself when the load factor exceeds 0.5. The load factor is defined
 * as the ratio of the number of entries to the number of buckets. When resizing occurs, all existing entries
 * are rehashed and inserted into the new buckets.
 * </p>
 *
 * @param <K> the type of keys maintained by this hash map
 * @param <V> the type of mapped values
 */
public class GenericHashMapUsingArrayList<K, V> {

    private ArrayList<LinkedList<Node>> buckets; // Array list of buckets (linked lists)
    private int size; // Number of key-value pairs in the hash map

    /**
     * Constructs a new empty hash map with an initial capacity of 10 buckets.
     */
    public GenericHashMapUsingArrayList() {
        buckets = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            buckets.add(new LinkedList<>());
        }
        size = 0;
    }

    /**
     * Associates the specified value with the specified key in this map.
     * If the map previously contained a mapping for the key, the old value is replaced.
     *
     * @param key the key with which the specified value is to be associated
     * @param value the value to be associated with the specified key
     */
    public void put(K key, V value) {
        int hash = Math.abs(key.hashCode() % buckets.size());
        LinkedList<Node> nodes = buckets.get(hash);

        for (Node node : nodes) {
            if (node.key.equals(key)) {
                node.val = value;
                return;
            }
        }

        nodes.add(new Node(key, value));
        size++;

        // Load factor threshold for resizing
        float loadFactorThreshold = 0.5f;
        if ((float) size / buckets.size() > loadFactorThreshold) {
            reHash();
        }
    }

    /**
     * Resizes the hash map by doubling the number of buckets and rehashing existing entries.
     */
    private void reHash() {
        ArrayList<LinkedList<Node>> oldBuckets = buckets;
        buckets = new ArrayList<>();
        size = 0;
        for (int i = 0; i < oldBuckets.size() * 2; i++) {
            buckets.add(new LinkedList<>());
        }
        for (LinkedList<Node> nodes : oldBuckets) {
            for (Node node : nodes) {
                put(node.key, node.val);
            }
        }
    }

    /**
     * Returns the value to which the specified key is mapped, or null if this map contains no mapping for the key.
     *
     * @param key the key whose associated value is to be returned
     * @return the value associated with the specified key, or null if no mapping exists
     */
    public V get(K key) {
        int hash = Math.abs(key.hashCode() % buckets.size());
        LinkedList<Node> nodes = buckets.get(hash);
        for (Node node : nodes) {
            if (node.key.equals(key)) {
                return node.val;
            }
        }
        return null;
    }

    /**
     * Removes the mapping for the specified key from this map if present.
     *
     * @param key the key whose mapping is to be removed from the map
     */
    public void remove(K key) {
        int hash = Math.abs(key.hashCode() % buckets.size());
        LinkedList<Node> nodes = buckets.get(hash);

        Node target = null;
        for (Node node : nodes) {
            if (node.key.equals(key)) {
                target = node;
                break;
            }
        }
        if (target != null) {
            nodes.remove(target);
            size--;
        }
    }

    /**
     * Returns true if this map contains a mapping for the specified key.
     *
     * @param key the key whose presence in this map is to be tested
     * @return true if this map contains a mapping for the specified key
     */
    public boolean containsKey(K key) {
        return get(key) != null;
    }

    /**
     * Returns the number of key-value pairs in this map.
     *
     * @return the number of key-value pairs
     */
    public int size() {
        return this.size;
    }

    /**
     * Returns a string representation of the map, containing all key-value pairs.
     *
     * @return a string representation of the map
     */
    @Override
    public String toString() {
        StringBuilder builder = new StringBuilder();
        builder.append("{");
        for (LinkedList<Node> nodes : buckets) {
            for (Node node : nodes) {
                builder.append(node.key);
                builder.append(" : ");
                builder.append(node.val);
                builder.append(", ");
            }
        }
        // Remove trailing comma and space if there are any elements
        if (builder.length() > 1) {
            builder.setLength(builder.length() - 2);
        }
        builder.append("}");
        return builder.toString();
    }

    /**
     * A private inner class representing a key-value pair (node) in the hash map.
     */
    private class Node {
        K key;
        V val;

        /**
         * Constructs a new Node with the specified key and value.
         *
         * @param key the key of the key-value pair
         * @param val the value of the key-value pair
         */
        Node(K key, V val) {
            this.key = key;
            this.val = val;
        }
    }
}

