/**
 * This class implements Johnson's algorithm for finding all-pairs shortest paths in a weighted,
 * directed graph that may contain negative edge weights.
 *
 * Johnson's algorithm works by using the Bellman-Ford algorithm to compute a transformation of the
 * input graph that removes all negative weights, allowing Dijkstra's algorithm to be used for
 * efficient shortest path computations.
 *
 * Time Complexity: O(V^2 * log(V) + V*E)
 * Space Complexity: O(V^2)
 *
 * Where V is the number of vertices and E is the number of edges in the graph.
 *
 * For more information, please visit {@link https://en.wikipedia.org/wiki/Johnson%27s_algorithm}
 */
public final class JohnsonsAlgorithm {

private static final double INFINITY_VALUE = Double.POSITIVE_INFINITY;

private JohnsonsAlgorithm() {
}

/**
 * Executes Johnson's algorithm on the given graph.
 * Steps:
 * 1. Add a new vertex to the graph and run Bellman-Ford to compute modified weights
 * 2. Reweight the graph using the modified weights
 * 3. Run Dijkstra's algorithm for each vertex to compute the shortest paths
 * The final result is a 2D array of shortest distances between all pairs of vertices.
 *
 * @param weightMatrix The input graph represented as an adjacency matrix.
 * @return A 2D array representing the shortest distances between all pairs of vertices.
 */
public static double[][] computeShortestPaths(double[][] weightMatrix) {
int totalVertices = weightMatrix.length;
double[][] edgeList = convertToEdgeArray(weightMatrix);
double[] adjustmentFactors = applyBellmanFord(edgeList, totalVertices);
double[][] adjustedGraph = reweightGraphEdges(weightMatrix, adjustmentFactors);
double[][] distanceMatrix = new double[totalVertices][totalVertices];
for (int startNode = 0; startNode < totalVertices; startNode++) {
distanceMatrix[startNode] = runDijkstra(adjustedGraph, startNode, adjustmentFactors);
}
return distanceMatrix;
}

/**
 * Converts the adjacency matrix representation of the graph to an edge list.
 *
 * @param weightMatrix The input graph as an adjacency matrix.
 * @return An array of edges, where each edge is represented as [from, to, weight].
 */
public static double[][] convertToEdgeArray(double[][] weightMatrix) {
int totalVertices = weightMatrix.length;
List<double[]> edgeCollection = new ArrayList<>();
for (int rowIndex = 0; rowIndex < totalVertices; rowIndex++) {
for (int colIndex = 0; colIndex < totalVertices; colIndex++) {
if (rowIndex != colIndex && !Double.isInfinite(weightMatrix[rowIndex][colIndex])) {
edgeCollection.add(new double[] {rowIndex, colIndex, weightMatrix[rowIndex][colIndex]});
}
}
}
return edgeCollection.toArray(new double[0][]);
}

/**
 * Implements the Bellman-Ford algorithm to compute the shortest paths from a new vertex
 * to all other vertices. This is used to calculate the weight function h(v) for reweighting.
 *
 * @param edgeData The edge list of the graph.
 * @param totalVertices The number of vertices in the original graph.
 * @return An array of modified weights for each vertex.
 */
private static double[] applyBellmanFord(double[][] edgeData, int totalVertices) {
double[] distanceValues = new double[totalVertices + 1];
Arrays.fill(distanceValues, INFINITY_VALUE);
distanceValues[totalVertices] = 0;
double[][] extendedEdges = Arrays.copyOf(edgeData, edgeData.length + totalVertices);
for (int vertexIndex = 0; vertexIndex < totalVertices; vertexIndex++) {
extendedEdges[edgeData.length + vertexIndex] = new double[] {totalVertices, vertexIndex, 0};
}
for (int passCount = 0; passCount < totalVertices; passCount++) {
for (double[] currentEdge : extendedEdges) {
int sourceNode = (int) currentEdge[0];
int targetNode = (int) currentEdge[1];
double edgeWeight = currentEdge[2];
if (distanceValues[sourceNode] != INFINITY_VALUE && distanceValues[sourceNode] + edgeWeight < distanceValues[targetNode]) {
distanceValues[targetNode] = distanceValues[sourceNode] + edgeWeight;
}
}
}
for (double[] currentEdge : extendedEdges) {
int sourceNode = (int) currentEdge[0];
int targetNode = (int) currentEdge[1];
double edgeWeight = currentEdge[2];
if (distanceValues[sourceNode] + edgeWeight < distanceValues[targetNode]) {
throw new IllegalArgumentException("Graph contains a negative weight cycle");
}
}
return Arrays.copyOf(distanceValues, totalVertices);
}

/**
 * Reweights the graph using the modified weights computed by Bellman-Ford.
 *
 * @param weightMatrix The original graph.
 * @param adjustmentFactors The modified weights from Bellman-Ford.
 * @return The reweighted graph.
 */
public static double[][] reweightGraphEdges(double[][] weightMatrix, double[] adjustmentFactors) {
int totalVertices = weightMatrix.length;
double[][] transformedMatrix = new double[totalVertices][totalVertices];
for (int rowIndex = 0; rowIndex < totalVertices; rowIndex++) {
for (int colIndex = 0; colIndex < totalVertices; colIndex++) {
if (weightMatrix[rowIndex][colIndex] != 0) {
transformedMatrix[rowIndex][colIndex] = weightMatrix[rowIndex][colIndex] + adjustmentFactors[rowIndex] - adjustmentFactors[colIndex];
}
}
}
return transformedMatrix;
}

/**
 * Implements Dijkstra's algorithm for finding shortest paths from a source vertex.
 *
 * @param adjustedGraph The reweighted graph to run Dijkstra's on.
 * @param startVertex The source vertex.
 * @param adjustmentFactors The modified weights from Bellman-Ford.
 * @return An array of shortest distances from the source to all other vertices.
 */
public static double[] runDijkstra(double[][] adjustedGraph, int startVertex, double[] adjustmentFactors) {
int totalVertices = adjustedGraph.length;
double[] distanceValues = new double[totalVertices];
boolean[] processedFlags = new boolean[totalVertices];
Arrays.fill(distanceValues, INFINITY_VALUE);
distanceValues[startVertex] = 0;
for (int iteration = 0; iteration < totalVertices - 1; iteration++) {
int currentVertex = findMinimumVertex(distanceValues, processedFlags);
processedFlags[currentVertex] = true;
for (int neighborIndex = 0; neighborIndex < totalVertices; neighborIndex++) {
if (!processedFlags[neighborIndex] &&
adjustedGraph[currentVertex][neighborIndex] != 0 &&
distanceValues[currentVertex] != INFINITY_VALUE &&
distanceValues[currentVertex] + adjustedGraph[currentVertex][neighborIndex] < distanceValues[neighborIndex]) {
distanceValues[neighborIndex] = distanceValues[currentVertex] + adjustedGraph[currentVertex][neighborIndex];
}
}
}
for (int vertexIndex = 0; vertexIndex < totalVertices; vertexIndex++) {
if (distanceValues[vertexIndex] != INFINITY_VALUE) {
distanceValues[vertexIndex] = distanceValues[vertexIndex] - adjustmentFactors[startVertex] + adjustmentFactors[vertexIndex];
}
}
return distanceValues;
}

/**
 * Finds the vertex with the minimum distance value from the set of vertices
 * not yet included in the shortest path tree.
 *
 * @param distanceValues Array of distances.
 * @param processedFlags Array of visited vertices.
 * @return The index of the vertex with minimum distance.
 */
public static int findMinimumVertex(double[] distanceValues, boolean[] processedFlags) {
double minimumValue = INFINITY_VALUE;
int minIndex = -1;
for (int vertexIndex = 0; vertexIndex < distanceValues.length; vertexIndex++) {
if (!processedFlags[vertexIndex] && distanceValues[vertexIndex] <= minimumValue) {
minimumValue = distanceValues[vertexIndex];
minIndex = vertexIndex;
}
}
return minIndex;
}
}

package com.thealgorithms.datastructures.heaps;

import java.util.ArrayList;
import java.util.List;

/**
 * A Min Heap implementation where each node's key is lower than or equal to its children's keys.
 * This data structure provides O(log n) time complexity for insertion and deletion operations,
 * and O(1) for retrieving the minimum element.
 *
 * Properties:
 * 1. Complete Binary Tree
 * 2. Parent node's key ≤ Children nodes' keys
 * 3. Root contains the minimum element
 *
 * Example usage:
 * ```java
 * List<HeapElement> elements = Arrays.asList(
 *     new HeapElement(5, "Five"),
 *     new HeapElement(2, "Two")
 * );
 * MinHeap heap = new MinHeap(elements);
 * heap.insertElement(new HeapElement(1, "One"));
 * HeapElement min = heap.getElement(); // Returns and removes the minimum element
 * ```
 *
 * @author Nicolas Renard
 */
public class MinHeap implements Heap {

    private final List<HeapElement> minHeap;

    /**
     * Constructs a new MinHeap from a list of elements.
     * Null elements in the input list are ignored with a warning message.
     *
     * @param listElements List of HeapElement objects to initialize the heap
     * @throws IllegalArgumentException if the input list is null
     */
    public MinHeap(List<HeapElement> listElements) {
        if (listElements == null) {
            throw new IllegalArgumentException("Input list cannot be null");
        }

        minHeap = new ArrayList<>();

        // Safe initialization: directly add elements first
        for (HeapElement heapElement : listElements) {
            if (heapElement != null) {
                minHeap.add(heapElement);
            } else {
                System.out.println("Null element. Not added to heap");
            }
        }

        // Heapify the array bottom-up
        for (int i = minHeap.size() / 2; i >= 0; i--) {
            heapifyDown(i + 1);
        }

        if (minHeap.isEmpty()) {
            System.out.println("No element has been added, empty heap.");
        }
    }

    /**
     * Retrieves the element at the specified index without removing it.
     * Note: The index is 1-based for consistency with heap operations.
     *
     * @param elementIndex 1-based index of the element to retrieve
     * @return HeapElement at the specified index
     * @throws IndexOutOfBoundsException if the index is invalid
     */
    public HeapElement getElement(int elementIndex) {
        if ((elementIndex <= 0) || (elementIndex > minHeap.size())) {
            throw new IndexOutOfBoundsException("Index " + elementIndex + " is out of heap range [1, " + minHeap.size() + "]");
        }
        return minHeap.get(elementIndex - 1);
    }

    /**
     * Retrieves the key value of an element at the specified index.
     *
     * @param elementIndex 1-based index of the element
     * @return double value representing the key
     * @throws IndexOutOfBoundsException if the index is invalid
     */
    private double getElementKey(int elementIndex) {
        if ((elementIndex <= 0) || (elementIndex > minHeap.size())) {
            throw new IndexOutOfBoundsException("Index " + elementIndex + " is out of heap range [1, " + minHeap.size() + "]");
        }
        return minHeap.get(elementIndex - 1).getKey();
    }

    /**
     * Swaps two elements in the heap.
     *
     * @param index1 1-based index of first element
     * @param index2 1-based index of second element
     */
    private void swap(int index1, int index2) {
        HeapElement temporaryElement = minHeap.get(index1 - 1);
        minHeap.set(index1 - 1, minHeap.get(index2 - 1));
        minHeap.set(index2 - 1, temporaryElement);
    }

    /**
     * Maintains heap properties by moving an element down the heap.
     * Used specifically during initialization.
     *
     * @param elementIndex 1-based index of the element to heapify
     */
    private void heapifyDown(int elementIndex) {
        int smallest = elementIndex - 1; // Convert to 0-based index
        int leftChild = 2 * elementIndex - 1;
        int rightChild = 2 * elementIndex;

        // Check if left child is smaller than root
        if (leftChild < minHeap.size() && minHeap.get(leftChild).getKey() < minHeap.get(smallest).getKey()) {
            smallest = leftChild;
        }

        // Check if right child is smaller than smallest so far
        if (rightChild < minHeap.size() && minHeap.get(rightChild).getKey() < minHeap.get(smallest).getKey()) {
            smallest = rightChild;
        }

        // If smallest is not root
        if (smallest != elementIndex - 1) {
            HeapElement swap = minHeap.get(elementIndex - 1);
            minHeap.set(elementIndex - 1, minHeap.get(smallest));
            minHeap.set(smallest, swap);

            // Recursively heapify the affected sub-tree
            heapifyDown(smallest + 1); // Convert back to 1-based index
        }
    }

    /**
     * Moves an element up the heap until heap properties are satisfied.
     * This operation is called after insertion to maintain heap properties.
     *
     * @param elementIndex 1-based index of the element to move up
     */
    private void toggleUp(int elementIndex) {
        if (elementIndex <= 1) {
            return;
        }

        double key = minHeap.get(elementIndex - 1).getKey();
        int parentIndex = (int) Math.floor(elementIndex / 2.0);

        while (elementIndex > 1 && getElementKey(parentIndex) > key) {
            swap(elementIndex, parentIndex);
            elementIndex = parentIndex;
            parentIndex = (int) Math.floor(elementIndex / 2.0);
        }
    }

    /**
     * Moves an element down the heap until heap properties are satisfied.
     * This operation is called after deletion to maintain heap properties.
     *
     * @param elementIndex 1-based index of the element to move down
     */
    private void toggleDown(int elementIndex) {
        double key = minHeap.get(elementIndex - 1).getKey();
        int size = minHeap.size();

        while (true) {
            int smallest = elementIndex;
            int leftChild = 2 * elementIndex;
            int rightChild = 2 * elementIndex + 1;

            if (leftChild <= size && getElementKey(leftChild) < key) {
                smallest = leftChild;
            }

            if (rightChild <= size && getElementKey(rightChild) < getElementKey(smallest)) {
                smallest = rightChild;
            }

            if (smallest == elementIndex) {
                break;
            }

            swap(elementIndex, smallest);
            elementIndex = smallest;
        }
    }

    /**
     * Extracts and returns the minimum element from the heap.
     *
     * @return HeapElement with the lowest key
     * @throws EmptyHeapException if the heap is empty
     */
    private HeapElement extractMin() throws EmptyHeapException {
        if (minHeap.isEmpty()) {
            throw new EmptyHeapException("Cannot extract from empty heap");
        }
        HeapElement result = minHeap.getFirst();
        deleteElement(1);
        return result;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public void insertElement(HeapElement element) {
        if (element == null) {
            throw new IllegalArgumentException("Cannot insert null element");
        }
        minHeap.add(element);
        toggleUp(minHeap.size());
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public void deleteElement(int elementIndex) throws EmptyHeapException {
        if (minHeap.isEmpty()) {
            throw new EmptyHeapException("Cannot delete from empty heap");
        }
        if ((elementIndex > minHeap.size()) || (elementIndex <= 0)) {
            throw new IndexOutOfBoundsException("Index " + elementIndex + " is out of heap range [1, " + minHeap.size() + "]");
        }

        // Replace with last element and remove last position
        minHeap.set(elementIndex - 1, minHeap.getLast());
        minHeap.removeLast();

        // No need to toggle if we just removed the last element
        if (!minHeap.isEmpty() && elementIndex <= minHeap.size()) {
            // Determine whether to toggle up or down
            if (elementIndex > 1 && getElementKey(elementIndex) < getElementKey((int) Math.floor(elementIndex / 2.0))) {
                toggleUp(elementIndex);
            } else {
                toggleDown(elementIndex);
            }
        }
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public HeapElement getElement() throws EmptyHeapException {
        return extractMin();
    }

    /**
     * Returns the current size of the heap.
     *
     * @return number of elements in the heap
     */
    public int size() {
        return minHeap.size();
    }

    /**
     * Checks if the heap is empty.
     *
     * @return true if the heap contains no elements
     */
    public boolean isEmpty() {
        return minHeap.isEmpty();
    }
}

public class Calculator { 

    // Iki sayiyi toplama islemi yapan method
    public int add(int a, int b) {
        return a + b;
    }

    // Iki sayiyi cikarma islemi yapan method
    public int subtract(int a, int b) {
        return a - b;
    }

    // Iki sayiyi carpma islemi yapan method
    public int multiply(int a, int b) {
        return a * b;
    }

    // Iki sayiyi bolme islemi yapan method
    public int divide(int a, int b) throws IllegalArgumentException {
        if (b == 0) {
            // Sifira bolme yapilamaz, hata firlatilir
            throw new IllegalArgumentException("Sifira bolme yapilamaz.");
        }
        return a / b;
    }

    // Iki sayiyi mod alma islemi yapan method
    public int modulus(int a, int b) throws IllegalArgumentException {
        if (b == 0) {
            // Sifira bolme yapilamaz, hata firlatilir
            throw new IllegalArgumentException("Sifira mod alma yapilamaz.");
        }
        return a % b;
    }

    // Bir sayinin faktoryelini hesaplayan method
    public long factorial(int n) throws IllegalArgumentException {
        if (n < 0) {
            // Negatif sayi ile faktoriyel hesaplanamaz, hata firlatilir
            throw new IllegalArgumentException("Negatif sayilarin faktoriyeli hesaplanamaz.");
        }
        long result = 1;
        for (int i = 1; i <= n; i++) {
            result *= i;
        }
        return result;
    }

    // Iki sayinin us alarak hesaplamasini yapan method
    public double power(double base, double exponent) {
        return Math.pow(base, exponent);
    }

    // Bir sayinin karekokunu hesaplayan method
    public double squareRoot(double a) throws IllegalArgumentException {
        if (a < 0) {
            // Negatif sayinin karekoku hesaplanamaz, hata firlatilir
            throw new IllegalArgumentException("Negatif sayilarin karekoku hesaplanamaz.");
        }
        return Math.sqrt(a);
    }

    // Iki sayinin maksimum degerini bulan method
    public int max(int a, int b) {
        return (a > b) ? a : b;
    }

    // Iki sayinin minimum degerini bulan method
    public int min(int a, int b) {
        return (a < b) ? a : b;
    }

    // Iki sayinin ortalamasini hesaplayan method
    public double average(int a, int b) {
        return (a + b) / 2.0;
    }
}

/**
 * Given 2 binary trees.
 * This code checks whether they are the same (structurally identical and have the same values) or
 * not. <p> Example:
 * 1. Binary trees:
 *      1                 1
 *     / \               / \
 *    2   3             2   3
 *   /\   /\           /\   /\
 *  4  5 6  7         4  5 6  7
 * These trees are the same, so the code returns 'true'.
 * <p>
 * 2. Binary trees:
 *      1   1
 *     /     \
 *    2       2
 * These trees are NOT the same (the structure differs), so the code returns 'false'.
 * <p>
 * This solution implements the breadth-first search (BFS) algorithm.
 * For each tree we create a queue and iterate the trees using these queues.
 * On each step we check the nodes for equality, and if the nodes are not the same, return false.
 * Otherwise, add children nodes to the queues and continue traversing the trees.
 * <p>
 * Complexities:
 * O(N) - time, where N is the number of nodes in a binary tree,
 * O(N) - space, where N is the number of nodes in a binary tree.
 *
 * @author Albina Gimaletdinova on 13/01/2023
 */
public final class SameTreesCheck {
    private SameTreesCheck() {
    }
    public static boolean check(BinaryTree.Node p, BinaryTree.Node q) {
        if (p == null && q == null) {
            return true;
        }
        if (p == null || q == null) {
            return false;
        }

        Deque<BinaryTree.Node> q1 = new ArrayDeque<>();
        Deque<BinaryTree.Node> q2 = new ArrayDeque<>();
        q1.add(p);
        q2.add(q);
        while (!q1.isEmpty() && !q2.isEmpty()) {
            BinaryTree.Node first = q1.poll();
            BinaryTree.Node second = q2.poll();
            // check that some node can be null
            // if the check is true: both nodes are null or both nodes are not null
            if (!equalNodes(first, second)) {
                return false;
            }

            if (first != null) {
                if (!equalNodes(first.left, second.left)) {
                    return false;
                }
                if (first.left != null) {
                    q1.add(first.left);
                    q2.add(second.left);
                }

                if (!equalNodes(first.right, second.right)) {
                    return false;
                }
                if (first.right != null) {
                    q1.add(first.right);
                    q2.add(second.right);
                }
            }
        }
        return true;
    }

    private static boolean equalNodes(BinaryTree.Node p, BinaryTree.Node q) {
        if (p == null && q == null) {
            return true;
        }
        if (p == null || q == null) {
            return false;
        }
        return p.data == q.data;
    }
}

