/**
 * The Welsh-Powell algorithm is a graph coloring algorithm that aims to color a graph
 * using the minimum number of colors such that no two adjacent vertices share the same color.
 *
 * <p>
 * The algorithm works by:
 * <ol>
 * <li>Sorting the vertices in descending order based on their degrees (number of edges connected).</li>
 * <li>Iterating through each vertex and assigning it the smallest available color that has not been used by its adjacent vertices.</li>
 * <li>Coloring adjacent vertices with the same color is avoided.</li>
 * </ol>
 * </p>
 *
 * <p>
 * For more information, see <a href="https://en.wikipedia.org/wiki/Graph_coloring">Graph Coloring</a>.
 * </p>
 */
@SuppressWarnings({"rawtypes", "unchecked"})
public final class WelshPowell {
private static final int NOT_ASSIGNED = -1;

private WelshPowell() {
}

/**
 * Represents a graph using an adjacency list.
 */
static final class UndirectedGraph {
private final HashSet<Integer>[] neighborSets;

/**
 * Initializes a graph with a specified number of vertices.
 *
 * @param totalVertices the number of vertices in the graph
 * @throws IllegalArgumentException if the number of vertices is negative
 */
private UndirectedGraph(int totalVertices) {
if (totalVertices < 0) {
throw new IllegalArgumentException("Number of vertices cannot be negative");
}
neighborSets = new HashSet[totalVertices];
Arrays.setAll(neighborSets, vertexIndex -> new HashSet<>());
}

/**
 * Adds an edge between two vertices in the graph.
 *
 * @param firstNode one end of the edge
 * @param secondNode the other end of the edge
 * @throws IllegalArgumentException if the vertices are out of bounds or if a self-loop is attempted
 */
private void connectVertices(int firstNode, int secondNode) {
validateVertexIndex(firstNode);
validateVertexIndex(secondNode);
if (firstNode == secondNode) {
throw new IllegalArgumentException("Self-loops are not allowed");
}
neighborSets[firstNode].add(secondNode);
neighborSets[secondNode].add(firstNode);
}

/**
 * Validates that the vertex index is within the bounds of the graph.
 *
 * @param vertexId the index of the vertex to validate
 * @throws IllegalArgumentException if the vertex is out of bounds
 */
private void validateVertexIndex(int vertexId) {
if (vertexId < 0 || vertexId >= getVertexCount()) {
throw new IllegalArgumentException("Vertex " + vertexId + " is out of bounds");
}
}

/**
 * Returns the adjacency list for a specific vertex.
 *
 * @param targetVertex the index of the vertex
 * @return the set of adjacent vertices
 */
HashSet<Integer> getNeighbors(int targetVertex) {
return neighborSets[targetVertex];
}

/**
 * Returns the number of vertices in the graph.
 *
 * @return the number of vertices
 */
int getVertexCount() {
return neighborSets.length;
}
}

/**
 * Creates a graph with the specified number of vertices and edges.
 *
 * @param totalVertices the total number of vertices
 * @param edgePairs a 2D array representing edges where each inner array contains two vertex indices
 * @return an UndirectedGraph object representing the created graph
 * @throws IllegalArgumentException if the edge array is invalid or vertices are out of bounds
 */
public static UndirectedGraph buildGraph(int totalVertices, int[][] edgePairs) {
UndirectedGraph targetGraph = new UndirectedGraph(totalVertices);
for (int[] edgePair : edgePairs) {
if (edgePair.length != 2) {
throw new IllegalArgumentException("Edge array must have exactly two elements");
}
targetGraph.connectVertices(edgePair[0], edgePair[1]);
}
return targetGraph;
}

/**
 * Finds the coloring of the given graph using the Welsh-Powell algorithm.
 *
 * @param inputGraph the input graph to color
 * @return an array of integers where each index represents a vertex and the value represents the color assigned
 */
public static int[] colorGraph(UndirectedGraph inputGraph) {
int[] assignedColors = initializeColors(inputGraph.getVertexCount());
Integer[] sortedNodes = sortByDegree(inputGraph);
for (int currentNode : sortedNodes) {
if (isUnassigned(assignedColors[currentNode])) {
boolean[] occupiedColors = getOccupiedColors(inputGraph, currentNode, assignedColors);
final int availableColor = findFirstFreeColor(occupiedColors);
assignedColors[currentNode] = availableColor;
for (int otherNode : sortedNodes) {
if (isUnassigned(assignedColors[otherNode]) && !hasAdjacentColored(inputGraph, otherNode, assignedColors)) {
assignedColors[otherNode] = availableColor;
}
}
}
}
return assignedColors;
}

private static boolean isUnassigned(int colorValue) {
return colorValue == NOT_ASSIGNED;
}

private static boolean hasAdjacentColored(UndirectedGraph inputGraph, int targetVertex, int[] assignedColors) {
return inputGraph.getNeighbors(targetVertex).stream().anyMatch(neighborId -> !isUnassigned(assignedColors[neighborId]));
}

private static int[] initializeColors(int vertexCount) {
int[] colorArray = new int[vertexCount];
Arrays.fill(colorArray, NOT_ASSIGNED);
return colorArray;
}

private static Integer[] sortByDegree(final UndirectedGraph inputGraph) {
return IntStream.range(0, inputGraph.getVertexCount())
.boxed()
.sorted(Comparator.comparingInt(vertexId -> -inputGraph.getNeighbors(vertexId).size()))
.toArray(Integer[] ::new);
}

private static boolean[] getOccupiedColors(final UndirectedGraph inputGraph, final int targetVertex, final int[] assignedColors) {
boolean[] usedColors = new boolean[inputGraph.getVertexCount()];
inputGraph.getNeighbors(targetVertex).stream()
.map(neighborId -> assignedColors[neighborId])
.filter(colorValue -> !isUnassigned(colorValue))
.forEach(colorValue -> usedColors[colorValue] = true);
return usedColors;
}

private static int findFirstFreeColor(boolean[] occupiedColors) {
return IntStream.range(0, occupiedColors.length)
.filter(colorIndex -> !occupiedColors[colorIndex])
.findFirst()
.getAsInt();
}
}
