public class IdealKiloHesaplayici {

	public static void main(String[] args) {

		Scanner okuyucu = new Scanner(System.in);

		System.out.print("Boyunuzu metre cinsinden giriniz: ");
		double boyMetre = okuyucu.nextDouble();
		okuyucu.close();

		// 1.5 metre esik degeri kabul edilerek ideal kilo hesaplaniyor
		double esikBoy = 1.5;
		double katsayi = 90;
		double tabanKilo = 50;

		double sonucKilo = (boyMetre > esikBoy)
				? tabanKilo + (boyMetre - esikBoy) * katsayi
				: tabanKilo;

		System.out.println("Ideal kilonuz: " + sonucKilo + " kilogram");
	}
}

