/**
 * Class for converting an octal number to a decimal number. Octal numbers are based on 8, using digits from 0 to 7.
 *
 */
public final class OctalToDecimal {
    private static final int OCTAL_BASE = 8;

    private OctalToDecimal() {
    }

    /**
     * Converts a given octal number (as a string) to its decimal representation.
     * If the input is not a valid octal number (i.e., contains characters other than 0-7),
     * the method throws an IllegalArgumentException.
     *
     * @param inputOctal The octal number as a string
     * @return The decimal equivalent of the octal number
     * @throws IllegalArgumentException if the input is not a valid octal number
     */
    public static int convertOctalToDecimal(String inputOctal) {
        if (inputOctal == null || inputOctal.isEmpty()) {
            throw new IllegalArgumentException("Input cannot be null or empty");
        }

        int decimalValue = 0;

        for (int i = 0; i < inputOctal.length(); i++) {
            char currentChar = inputOctal.charAt(i);

            if (currentChar < '0' || currentChar > '7') {
                throw new IllegalArgumentException("Incorrect input: Expecting an octal number (digits 0-7)");
            }

            int currentDigit = currentChar - '0';
            decimalValue = decimalValue * OCTAL_BASE + currentDigit;
        }

        return decimalValue;
    }
}

public class UcuncuEnBuyukBulucu {

    // Yaklasim 1: onceden siralayip sondan ucuncu elemani okur
    public static int siralayarakBul(int[] degerler) {
        Arrays.sort(degerler);
        return degerler[degerler.length - 3];
    }

    // Yaklasim 2: tek geciste en buyuk uc degeri takip ederek bulur
    public static int tekGecisleBul(int[] degerler) {
        long birinci = Long.MIN_VALUE;
        long ikinci = Long.MIN_VALUE;
        long ucuncu = Long.MIN_VALUE;

        for (int mevcut : degerler) {
            if (mevcut > birinci) {
                ucuncu = ikinci;
                ikinci = birinci;
                birinci = mevcut;
            } else if (mevcut > ikinci) {
                ucuncu = ikinci;
                ikinci = mevcut;
            } else if (mevcut > ucuncu) {
                ucuncu = mevcut;
            }
        }

        return (int) ucuncu;
    }

    public static void main(String[] args) {
        int[] veriler = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        System.out.println(Arrays.toString(veriler));
        int sonuc1 = siralayarakBul(veriler);
        System.out.println("3. buyuk sayi: " + sonuc1);

        System.out.println(Arrays.toString(veriler));
        int sonuc2 = tekGecisleBul(veriler);
        System.out.println("3. buyuk sayi: " + sonuc2);
    }
}

package com.thealgorithms.datastructures.trees;

import com.thealgorithms.datastructures.trees.BinaryTree.Node;

/**
 * Check if a binary tree is symmetric or not.
 * A binary tree is a symmetric tree if the left and right subtree of root are mirror image.
 * Below is a symmetric tree
 *                               1
 *                   /                         \
 *                2                           2
 *         /                \             /             \
 *      3                    4         4                3
 *
 * Below is not symmetric because values is different in last level
 *                               1
 *                   /                         \
 *                 2                           2
 *         /                \             /             \
 *      3                    5         4                3
 * <p>
 * Approach:
 * Recursively check for left and right subtree of root
 * 1. left subtrees root's values should be equal right subtree's root value
 * 2. recursively check with left subtrees' left child VS right subtree's right child AND
 * left subtree's right child VS right subtree left child
 * Complexity
 * 1. Time: O(n)
 * 2. Space: O(lg(n)) for height of tree
 *
 * @author kumanoit on 10/10/22 IST 12:52 AM
 */
public final class CheckTreeIsSymmetric {
    private CheckTreeIsSymmetric() {
    }

    public static boolean isSymmetric(Node root) {
        if (root == null) {
            return true;
        }
        return isSymmetric(root.left, root.right);
    }

    private static boolean isSymmetric(Node leftSubtreeRoot, Node rightSubtreeRoot) {
        if (leftSubtreeRoot == null && rightSubtreeRoot == null) {
            return true;
        }

        if (isInvalidSubtree(leftSubtreeRoot, rightSubtreeRoot)) {
            return false;
        }

        return isSymmetric(leftSubtreeRoot.right, rightSubtreeRoot.left) && isSymmetric(leftSubtreeRoot.left, rightSubtreeRoot.right);
    }

    private static boolean isInvalidSubtree(Node leftSubtreeRoot, Node rightSubtreeRoot) {
        return leftSubtreeRoot == null || rightSubtreeRoot == null || leftSubtreeRoot.data != rightSubtreeRoot.data;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Terminal uzerinde ASCII karakterlerle sekilen, birbirinden bagimsiz
 * hareket eden birden fazla "top" gosteren basit bir animasyon dongusu.
 */
public class KonsoldaTopAnimasyonu {

    private static final int TERMINAL_GENISLIK = 50;
    private static final int TERMINAL_YUKSEKLIK = 20;
    private static final int TOP_ADEDI = 5;
    private static final int KARE_GECIKMESI_MS = 100;

    /** Konumu ve hareket vektoru olan tek bir noktasal cismi temsil eder. */
    private static class HareketliNokta {
        int yatayKonum;
        int dikeyKonum;
        int yatayYon;
        int dikeyYon;

        HareketliNokta(int yatayKonum, int dikeyKonum, int yatayYon, int dikeyYon) {
            this.yatayKonum = yatayKonum;
            this.dikeyKonum = dikeyKonum;
            this.yatayYon = yatayYon;
            this.dikeyYon = dikeyYon;
        }

        void birAdimIlerle() {
            yatayKonum += yatayYon;
            dikeyKonum += dikeyYon;

            if (yatayKonum <= 0 || yatayKonum >= TERMINAL_GENISLIK - 1) {
                yatayYon *= -1;
            }
            if (dikeyKonum <= 0 || dikeyKonum >= TERMINAL_YUKSEKLIK - 1) {
                dikeyYon *= -1;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        List<HareketliNokta> noktalar = rastgeleNoktalarUret();

        while (true) {
            noktalar.forEach(HareketliNokta::birAdimIlerle);
            terminaleCiz(noktalar);
            Thread.sleep(KARE_GECIKMESI_MS);
        }
    }

    private static List<HareketliNokta> rastgeleNoktalarUret() {
        Random rng = new Random();
        List<HareketliNokta> liste = new ArrayList<>();
        for (int i = 0; i < TOP_ADEDI; i++) {
            liste.add(new HareketliNokta(
                    rng.nextInt(TERMINAL_GENISLIK),
                    rng.nextInt(TERMINAL_YUKSEKLIK),
                    rng.nextBoolean() ? 1 : -1,
                    rng.nextBoolean() ? 1 : -1
            ));
        }
        return liste;
    }

    private static void terminaleCiz(List<HareketliNokta> noktalar) {
        System.out.print("\033[H\033[2J");
        StringBuilder kare = new StringBuilder();
        for (int satir = 0; satir < TERMINAL_YUKSEKLIK; satir++) {
            for (int sutun = 0; sutun < TERMINAL_GENISLIK; sutun++) {
                kare.append(hucreSembolu(noktalar, sutun, satir));
            }
            kare.append('\n');
        }
        System.out.print(kare);
    }

    private static char hucreSembolu(List<HareketliNokta> noktalar, int sutun, int satir) {
        for (HareketliNokta n : noktalar) {
            if (n.yatayKonum == sutun && n.dikeyKonum == satir) {
                return 'O';
            }
        }
        return ' ';
    }
}

// Gerekli Java kutuphaneleri iceri aktar



// Basit bir cizim paneli olusturan sinif
public class BasitCizimPaneli extends JPanel {
    private static final long serialVersionUID = -3630443364990545965L;

    // Kullanici tarafindan cizilen egri listesi
    private List<List<Point>> egriler = new ArrayList<>();

    // Constructor - panelin olay dinleyicilerini ayarlar
    public BasitCizimPaneli() {
        // Fare hareketlerini dinler (surukleme islemi)
        addMouseMotionListener(new MouseMotionAdapter() {
            @Override
            public void mouseDragged(MouseEvent e) {
                // Mevcut egrinin sonuna yeni noktayi ekler
                egriler.get(egriler.size() - 1).add(new Point(e.getX(), e.getY()));
                // Paneli yeniden cizer
                repaint(0, 0, getWidth(), getHeight());
            }
        });

        // Fare tiklamalarini dinler
        addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                // Yeni bir egri olusturur ve ilk noktayi ekler
                var yeniEgri = new ArrayList<Point>();
                yeniEgri.add(new Point(e.getX(), e.getY()));
                egriler.add(yeniEgri);
            }
        });
    }

    // Panelin icerigini cizer
    @Override
    public void paintComponent(Graphics g) {
        super.paintComponent(g);
        // Her bir egriyi ciz
        for (var egri : egriler) {
            var onceki = egri.get(0); // Ilk noktayi al
            for (var nokta : egri) {
                // Iki nokta arasinda bir cizgi ciz
                g.drawLine(onceki.x, onceki.y, nokta.x, nokta.y);
                onceki = nokta; // Onceki noktayi guncelle
            }
        }
    }

    // Programin giris noktasi
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            // Uygulama icin bir pencere olustur
            var frame = new JFrame("Basit Cizim Programi");
            // Cizim panelini pencereye ekle
            frame.getContentPane().add(new BasitCizimPaneli(), BorderLayout.CENTER);
            // Kapatma islemini ayarla
            frame.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
            // Pencere boyutunu ayarla
            frame.setSize(400, 300);
            // Pencereyi gorunur yap
            frame.setVisible(true);
        });
    }
}

package com.thealgorithms.ciphers;

/**
 * The AffineCipher class implements the Affine cipher, a type of monoalphabetic substitution cipher.
 * It encrypts and decrypts messages using a linear transformation defined by the formula:
 *
 *     E(x) = (a * x + b) mod m
 *     D(y) = a^-1 * (y - b) mod m
 *
 * where:
 * - E(x) is the encrypted character,
 * - D(y) is the decrypted character,
 * - a is the multiplicative key (must be coprime to m),
 * - b is the additive key,
 * - x is the index of the plaintext character,
 * - y is the index of the ciphertext character,
 * - m is the size of the alphabet (26 for the English alphabet).
 *
 * The class provides methods for encrypting and decrypting messages, as well as a main method to demonstrate its usage.
 */
final class AffineCipher {
private AffineCipher() {
}

static int multiplierKey = 17;
static int additiveKey = 20;

/**
 * Encrypts a message using the Affine cipher.
 *
 * @param inputMessage the plaintext message as a character array
 * @return the encrypted ciphertext
 */
static String encryptMessage(char[] inputMessage) {
StringBuilder encryptedResult = new StringBuilder();
for (int charIndex = 0; charIndex < inputMessage.length; charIndex++) {
if (inputMessage[charIndex] != ' ') {
encryptedResult.append((char) ((((multiplierKey * (inputMessage[charIndex] - 'A')) + additiveKey) % 26) + 'A'));
} else {
encryptedResult.append(inputMessage[charIndex]);
}
}
return encryptedResult.toString();
}

/**
 * Decrypts a ciphertext using the Affine cipher.
 *
 * @param encryptedText the ciphertext to decrypt
 * @return the decrypted plaintext message
 */
static String decryptCipher(String encryptedText) {
StringBuilder decryptedResult = new StringBuilder();
int inverseMultiplier = 0;
int foundFlag;
for (int testValue = 0; testValue < 26; testValue++) {
foundFlag = (multiplierKey * testValue) % 26;
if (foundFlag == 1) {
inverseMultiplier = testValue;
break;
}
}
for (int charIndex = 0; charIndex < encryptedText.length(); charIndex++) {
if (encryptedText.charAt(charIndex) != ' ') {
decryptedResult.append((char) (((inverseMultiplier * ((encryptedText.charAt(charIndex) - 'A') - additiveKey + 26)) % 26) + 'A'));
} else {
decryptedResult.append(encryptedText.charAt(charIndex));
}
}
return decryptedResult.toString();
}
}

/**
 * A player's tournament performance and resulting grade bonus.
 */
public class TournamentIncome extends Player implements GradeBonus {

    private int totalMatches;
    private int battle;
    private double[] points;
    private double income;

    public TournamentIncome(int totalMatches, int battle, double[] points, double income) {
        this.income = income;
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(int totalMatches, int battle, double[] points, double income, String name) {
        super(name);
        this.income = income;
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(int totalMatches, int battle, double[] points) {
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(double income, String name) {
        super(name);
        this.income = income;
    }

    public TournamentIncome() {
    }

    public int getTotalMatches() {
        return totalMatches;
    }

    public void setTotalMatches(int totalMatches) {
        this.totalMatches = totalMatches;
    }

    public int getBattle() {
        return battle;
    }

    public void setBattle(int battle) {
        this.battle = battle;
    }

    public double[] getPoints() {
        return points;
    }

    public void setPoints(double[] points) {
        this.points = points;
    }

    public double getIncome() {
        return income;
    }

    public void setIncome(double income) {
        this.income = income;
    }

    @Override
    public void displayDetails() {
        System.out.println("Name player: " + getName());
        System.out.println("Grade bonus: " + calculateGradeBonus() + "%");
        System.out.println("Income: " + income + "$");
    }

    @Override
    public double calculateGradeBonus() {
        double totalPoint = 0;
        double money = 1000000;
        if (points == null) {
            System.out.println("Please enter points");
            return 0;
        }
        for (double point : points) {
            totalPoint += point;
        }
        if (totalPoint < totalMatches * 100 * 0.3) {
            return GRADE_D_BONUS_PERCENT * money / 100;
        } else if (totalPoint < totalMatches * 100 * 0.4) {
            return GRADE_C_BONUS_PERCENT * money / 100;
        } else if (totalPoint < totalMatches * 100 * 0.5) {
            return GRADE_B_BONUS_PERCENT * money / 100;
        } else {
            return GRADE_A_BONUS_PERCENT * money / 100;
        }
    }
}

package com.thealgorithms.datastructures.heaps;

/**
 * Class representing an element in a heap.
 *
 * <p>
 * A heap element contains two attributes: a key used for ordering in the heap
 * (which can be of type int or double, either as primitive types or as wrapper objects)
 * and an additional immutable object that can store any supplementary information the user desires.
 * Note that using mutable objects may compromise the integrity of this information.
 * </p>
 *
 * <p>
 * The key attribute is used to determine the order of elements in the heap,
 * while the additionalInfo attribute can carry user-defined data associated with the key.
 * </p>
 *
 * <p>
 * This class provides multiple constructors to accommodate various key types and includes
 * methods to retrieve the key and additional information.
 * </p>
 *
 * @author Nicolas Renard
 */
public class HeapElement {

    private final double key;
    private final Object additionalInfo;

    // Constructors
    /**
     * Creates a HeapElement with the specified key and additional information.
     *
     * @param key  the key of the element (primitive type double)
     * @param info any immutable object containing additional information, may be null
     */
    public HeapElement(double key, Object info) {
        this.key = key;
        this.additionalInfo = info;
    }

    /**
     * Creates a HeapElement with the specified key and additional information.
     *
     * @param key  the key of the element (primitive type int)
     * @param info any immutable object containing additional information, may be null
     */
    public HeapElement(int key, Object info) {
        this.key = key;
        this.additionalInfo = info;
    }

    /**
     * Creates a HeapElement with the specified key and additional information.
     *
     * @param key  the key of the element (object type Integer)
     * @param info any immutable object containing additional information, may be null
     */
    public HeapElement(Integer key, Object info) {
        this.key = key;
        this.additionalInfo = info;
    }

    /**
     * Creates a HeapElement with the specified key and additional information.
     *
     * @param key  the key of the element (object type Double)
     * @param info any immutable object containing additional information, may be null
     */
    public HeapElement(Double key, Object info) {
        this.key = key;
        this.additionalInfo = info;
    }

    /**
     * Creates a HeapElement with the specified key.
     *
     * @param key the key of the element (primitive type double)
     */
    public HeapElement(double key) {
        this.key = key;
        this.additionalInfo = null;
    }

    /**
     * Creates a HeapElement with the specified key.
     *
     * @param key the key of the element (primitive type int)
     */
    public HeapElement(int key) {
        this.key = key;
        this.additionalInfo = null;
    }

    /**
     * Creates a HeapElement with the specified key.
     *
     * @param key the key of the element (object type Integer)
     */
    public HeapElement(Integer key) {
        this.key = key;
        this.additionalInfo = null;
    }

    /**
     * Creates a HeapElement with the specified key.
     *
     * @param key the key of the element (object type Double)
     */
    public HeapElement(Double key) {
        this.key = key;
        this.additionalInfo = null;
    }

    // Getters
    /**
     * Returns the object containing the additional information provided by the user.
     *
     * @return the additional information
     */
    public Object getInfo() {
        return additionalInfo;
    }

    /**
     * Returns the key value of the element.
     *
     * @return the key of the element
     */
    public double getKey() {
        return key;
    }

    // Overridden object methods
    /**
     * Returns a string representation of the heap element.
     *
     * @return a string describing the key and additional information
     */
    @Override
    public String toString() {
        return "Key: " + key + " - " + (additionalInfo != null ? additionalInfo.toString() : "No additional info");
    }

    /**
     * @param o : an object to compare with the current element
     * @return true if the keys on both elements are identical and the
     * additional info objects are identical.
     */
    @Override
    public boolean equals(Object o) {
        if (o instanceof HeapElement otherHeapElement) {
            return this.key == otherHeapElement.key && (this.additionalInfo != null ? this.additionalInfo.equals(otherHeapElement.additionalInfo) : otherHeapElement.additionalInfo == null);
        }
        return false;
    }

    /**
     * Returns a hash code value for the heap element.
     *
     * @return a hash code value for this heap element
     */
    @Override
    public int hashCode() {
        int result = 31 * (int) key;
        result += (additionalInfo != null) ? additionalInfo.hashCode() : 0;
        return result;
    }

    public String getValue() {
        return additionalInfo.toString();
    }
}

/**
 * An implementation of Dial's Algorithm for the single-source shortest path problem.
 * This algorithm is an optimization of Dijkstra's algorithm and is particularly
 * efficient for graphs with small, non-negative integer edge weights.
 *
 * It uses a bucket queue (implemented here as a List of HashSets) to store vertices,
 * where each bucket corresponds to a specific distance from the source. This is more
 * efficient than a standard priority queue when the range of edge weights is small.
 *
 * Time Complexity: O(E + W * V), where E is the number of edges, V is the number
 * of vertices, and W is the maximum weight of any edge.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Dijkstra%27s_algorithm#Dial's_algorithm">Wikipedia - Dial's Algorithm</a>
 */
public final class DialsAlgorithm {
/**
 * Private constructor to prevent instantiation of this utility class.
 */
private DialsAlgorithm() {
}
/**
 * Represents an edge in the graph, connecting to a destination vertex with a given weight.
 */
public static class WeightedEdge {
private final int targetVertex;
private final int edgeWeight;

public WeightedEdge(int targetVertex, int edgeWeight) {
this.targetVertex = targetVertex;
this.edgeWeight = edgeWeight;
}

public int getTargetVertex() {
return targetVertex;
}

public int getEdgeWeight() {
return edgeWeight;
}
}
/**
 * Finds the shortest paths from a source vertex to all other vertices in a weighted graph.
 *
 * @param adjacencyList The graph represented as an adjacency list.
 * @param startVertex The source vertex to start from (0-indexed).
 * @param maxWeightValue The maximum weight of any single edge in the graph.
 * @return An array of integers where the value at each index `i` is the
 * shortest distance from the source to vertex `i`. Unreachable vertices
 * will have a value of Integer.MAX_VALUE.
 * @throws IllegalArgumentException if the source vertex is out of bounds.
 */
public static int[] findShortestPaths(List<List<WeightedEdge>> adjacencyList, int startVertex, int maxWeightValue) {
int totalVertices = adjacencyList.size();
if (startVertex < 0 || startVertex >= totalVertices) {
throw new IllegalArgumentException("Source vertex is out of bounds.");
}
int[] shortestDistances = new int[totalVertices];
Arrays.fill(shortestDistances, Integer.MAX_VALUE);
shortestDistances[startVertex] = 0;
int maxPossiblePath = maxWeightValue * (totalVertices > 0 ? totalVertices - 1 : 0);
List<Set<Integer>> distanceBuckets = new ArrayList<>(maxPossiblePath + 1);
for (int bucketIndex = 0; bucketIndex <= maxPossiblePath; bucketIndex++) {
distanceBuckets.add(new HashSet<>());
}
distanceBuckets.get(0).add(startVertex);
for (int currentDistance = 0; currentDistance <= maxPossiblePath; currentDistance++) {
while (!distanceBuckets.get(currentDistance).isEmpty()) {
int currentVertex = distanceBuckets.get(currentDistance).iterator().next();
distanceBuckets.get(currentDistance).remove(currentVertex);
if (currentDistance > shortestDistances[currentVertex]) {
continue;
}
for (WeightedEdge neighborEdge : adjacencyList.get(currentVertex)) {
int neighborVertex = neighborEdge.getTargetVertex();
int edgeCost = neighborEdge.getEdgeWeight();
if (shortestDistances[currentVertex] != Integer.MAX_VALUE &&
shortestDistances[currentVertex] + edgeCost < shortestDistances[neighborVertex]) {
if (shortestDistances[neighborVertex] != Integer.MAX_VALUE) {
distanceBuckets.get(shortestDistances[neighborVertex]).remove(neighborVertex);
}
shortestDistances[neighborVertex] = shortestDistances[currentVertex] + edgeCost;
distanceBuckets.get(shortestDistances[neighborVertex]).add(neighborVertex);
}
}
}
}
}
return shortestDistances;
}
}

package com.thealgorithms.datastructures.lists;

/**
 * This class is a circular singly linked list implementation. In a circular linked list,
 * the last node points back to the first node, creating a circular chain.
 *
 * <p>This implementation includes basic operations such as appending elements
 * to the end, removing elements from a specified position, and converting
 * the list to a string representation.
 *
 * @param <E> the type of elements held in this list
 */
@SuppressWarnings("rawtypes")
public class CircleLinkedList<E> {

    /**
     * A static nested class representing a node in the circular linked list.
     *
     * @param <E> the type of element stored in the node
     */
    static final class Node<E> {

        Node<E> next;
        E value;

        private Node(E value, Node<E> next) {
            this.value = value;
            this.next = next;
        }
    }

    private int size;
    Node<E> head = null;
    private Node<E> tail;

    /**
     * Initializes a new circular linked list. A dummy head node is used for simplicity,
     * pointing initially to itself to ensure the list is never empty.
     */
    public CircleLinkedList() {
        head = new Node<>(null, head);
        tail = head;
        size = 0;
    }

    /**
     * Returns the current size of the list.
     *
     * @return the number of elements in the list
     */
    public int getSize() {
        return size;
    }

    /**
     * Appends a new element to the end of the list. Throws a NullPointerException if
     * a null value is provided.
     *
     * @param value the value to append to the list
     * @throws NullPointerException if the value is null
     */
    public void append(E value) {
        if (value == null) {
            throw new NullPointerException("Cannot add null element to the list");
        }
        if (tail == null) {
            tail = new Node<>(value, head);
            head.next = tail;
        } else {
            tail.next = new Node<>(value, head);
            tail = tail.next;
        }
        size++;
    }

    /**
     * Returns a string representation of the list in the format "[ element1, element2, ... ]".
     * An empty list is represented as "[]".
     *
     * @return the string representation of the list
     */
    public String toString() {
        if (size == 0) {
            return "[]";
        }
        StringBuilder sb = new StringBuilder("[ ");
        Node<E> current = head.next;
        while (current != head) {
            sb.append(current.value);
            if (current.next != head) {
                sb.append(", ");
            }
            current = current.next;
        }
        sb.append(" ]");
        return sb.toString();
    }

    /**
     * Removes and returns the element at the specified position in the list.
     * Throws an IndexOutOfBoundsException if the position is invalid.
     *
     * @param pos the position of the element to remove
     * @return the value of the removed element
     * @throws IndexOutOfBoundsException if the position is out of range
     */
    public E remove(int pos) {
        if (pos >= size || pos < 0) {
            throw new IndexOutOfBoundsException("Position out of bounds");
        }

        Node<E> before = head;
        for (int i = 1; i <= pos; i++) {
            before = before.next;
        }
        Node<E> destroy = before.next;
        E saved = destroy.value;
        before.next = destroy.next;

        if (destroy == tail) {
            tail = before;
        }
        destroy = null;
        size--;
        return saved;
    }
}

package com.ankan.generics;

import java.util.ArrayList;
import java.util.Arrays;

public class CustomArrayList {

    private int[] internalDataArray;
    private static int DEFAULT_CAPACITY = 10;
    private int currentSize = 0; // also works as the next available index position

    public CustomArrayList() {
        this.internalDataArray = new int[DEFAULT_CAPACITY];
    }

    public void add(int elementToAdd) {
        if (isArrayFull()) {
            resizeArray();
        }
        internalDataArray[currentSize++] = elementToAdd;
    }

    private void resizeArray() {
        int[] expandedArray = new int[internalDataArray.length * 2];

        // Copy all existing elements into the new larger array
        for (int indexPosition = 0; indexPosition < internalDataArray.length; indexPosition++) {
            expandedArray[indexPosition] = internalDataArray[indexPosition];
        }
        internalDataArray = expandedArray;
    }

    private boolean isArrayFull() {
        return currentSize == internalDataArray.length;
    }

    public int removeLastElement() {
        int removedElementValue = internalDataArray[--currentSize];
        return removedElementValue;
    }

    public int getElementAtIndex(int targetIndex) {
        return internalDataArray[targetIndex];
    }

    public int getCurrentSize() {
        return currentSize;
    }

    public void updateValueAtIndex(int targetIndex, int newValue) {
        internalDataArray[targetIndex] = newValue;
    }

    @Override
    public String toString() {
        return "CustomArrayList { " +
                "data = " + Arrays.toString(internalDataArray) +
                ", currentSize = " + currentSize +
                '}';
    }

    public static void main(String[] args) {
        // Standard Java ArrayList example (commented)
        // ArrayList list = new ArrayList();

        // Using our custom ArrayList implementation
        CustomArrayList customList = new CustomArrayList();
//        customList.add(3);
//        customList.add(5);
//        customList.add(9);

        // Populate the list with even numbers
        for (int iterationCount = 0; iterationCount < 14; iterationCount++) {
            customList.add(2 * iterationCount);
        }

        System.out.println("Custom ArrayList contents: " + customList);

        // Demonstration of Java's generic ArrayList with String type
        ArrayList<String> stringArrayList = new ArrayList<>();
        stringArrayList.add("sample text");

        // Educational note about Generics
        // Generics enable parameterized type checking at compile time
        // Example: ArrayList<Integer>, ArrayList<String> etc.
    }
}

/**
 *
 *
 * <h1>Binary Search Tree (Recursive)</h1>
 *
 * An implementation of BST recursively. In recursive implementation the checks
 * are down the tree First root is checked if not found then its children are
 * checked Binary Search Tree is a binary tree which satisfies three properties:
 * left child is less than root node, right child is grater than root node, both
 * left and right children must themselves be a BST.
 *
 * <p>
 * I have made public functions as methods and to actually implement recursive
 * approach I have used private methods
 *
 * @author [Lakhan Nad](<a href="https://github.com/Lakhan-Nad">git-Lakhan Nad</a>)
 */
public class BSTRecursive {

    /**
     * only data member is root of BST
     */
    private Node root;

    /**
     * Constructor use to initialize node as null
     */
    BSTRecursive() {
        root = null;
    }

    public Node getRoot() {
        return root;
    }

    /**
     * Recursive method to delete a data if present in BST.
     *
     * @param node the current node to search for data
     * @param data the value to be deleted
     * @return Node the updated value of root parameter after delete operation
     */
    private Node delete(Node node, int data) {
        if (node == null) {
            System.out.println("No such data present in BST.");
        } else if (node.data > data) {
            node.left = delete(node.left, data);
        } else if (node.data < data) {
            node.right = delete(node.right, data);
        } else {
            if (node.right == null && node.left == null) { // If it is leaf node
                node = null;
            } else if (node.left == null) { // If only right node is present
                Node temp = node.right;
                node.right = null;
                node = temp;
            } else if (node.right == null) { // Only left node is present
                Node temp = node.left;
                node.left = null;
                node = temp;
            } else { // both children are present
                Node temp = node.right;
                // Find leftmost child of right subtree
                while (temp.left != null) {
                    temp = temp.left;
                }
                node.data = temp.data;
                node.right = delete(node.right, temp.data);
            }
        }
        return node;
    }

    /**
     * Recursive insertion of value in BST.
     *
     * @param node to check if the data can be inserted in current node or its
     * subtree
     * @param data the value to be inserted
     * @return the modified value of the root parameter after insertion
     */
    private Node insert(Node node, int data) {
        if (node == null) {
            node = new Node(data);
        } else if (node.data > data) {
            node.left = insert(node.left, data);
        } else if (node.data < data) {
            node.right = insert(node.right, data);
        }
        return node;
    }

    /**
     * Search recursively if the given value is present in BST or not.
     *
     * @param node the current node to check
     * @param data the value to be checked
     * @return boolean if data is present or not
     */
    private boolean search(Node node, int data) {
        if (node == null) {
            return false;
        } else if (node.data == data) {
            return true;
        } else if (node.data > data) {
            return search(node.left, data);
        } else {
            return search(node.right, data);
        }
    }

    /**
     * add in BST. if the value is not already present it is inserted or else no
     * change takes place.
     *
     * @param data the value to be inserted
     */
    public void add(int data) {
        this.root = insert(this.root, data);
    }

    /**
     * If data is present in BST delete it else do nothing.
     *
     * @param data the value to be removed
     */
    public void remove(int data) {
        this.root = delete(this.root, data);
    }

    /**
     * To check if given value is present in tree or not.
     *
     * @param data the data to be found for
     */
    public boolean find(int data) {
        if (search(this.root, data)) {
            System.out.println(data + " is present in given BST.");
            return true;
        }
        System.out.println(data + " not found.");
        return false;
    }
}

public class Main {
    public static void main(String[] args) {
        B obj = new B();
        System.out.println(obj.isOdd(6));
    }
}

