		// Listenin boyutunu al
		int boyut = isimler.size();
		System.out.println("Listenin boyutu: " + boyut);
	}
}

/**
 * The {@code KnapsackZeroOne} provides Recursive solution for the 0/1 Knapsack
 * problem. Solves by exploring all combinations of items using recursion. No
 * memoization or dynamic programming optimizations are applied.
 *
 * Time Complexity: O(2^n) — explores all subsets.
 * Space Complexity: O(n) — due to recursive call stack.
 *
 * Problem Reference: https://en.wikipedia.org/wiki/Knapsack_problem
 */
public final class KnapsackZeroOne {

    private KnapsackZeroOne() {
        // Prevent instantiation
    }

    /**
     * Solves the 0/1 Knapsack problem using recursion.
     *
     * @param values   the array containing values of the items
     * @param weights  the array containing weights of the items
     * @param capacity the total capacity of the knapsack
     * @param n        the number of items
     * @return the maximum total value achievable within the given weight limit
     * @throws IllegalArgumentException if input arrays are null, empty, or
     *     lengths mismatch
     */
    public static int compute(final int[] values, final int[] weights, final int capacity, final int n) {
        if (values == null || weights == null) {
            throw new IllegalArgumentException("Input arrays cannot be null.");
        }
        if (values.length != weights.length) {
            throw new IllegalArgumentException("Value and weight arrays must be of the same length.");
        }
        if (capacity < 0 || n < 0) {
            throw new IllegalArgumentException("Invalid input: arrays must be non-empty and capacity/n "
                + "non-negative.");
        }
        if (n == 0 || capacity == 0 || values.length == 0) {
            return 0;
        }

        if (weights[n - 1] <= capacity) {
            final int include = values[n - 1] + compute(values, weights, capacity - weights[n - 1], n - 1);
            final int exclude = compute(values, weights, capacity, n - 1);
            return Math.max(include, exclude);
        } else {
            return compute(values, weights, capacity, n - 1);
        }
    }
}

/**
 * Smith–Waterman algorithm for local sequence alignment.
 * Finds the highest scoring local alignment between substrings of two sequences.
 *
 * Time Complexity: O(n * m)
 * Space Complexity: O(n * m)
 */
public final class SmithWaterman {

    private SmithWaterman() {
        // Utility Class
    }

    /**
     * Computes the Smith–Waterman local alignment score between two strings.
     *
     * @param s1 first string
     * @param s2 second string
     * @param matchScore score for a match
     * @param mismatchPenalty penalty for mismatch (negative)
     * @param gapPenalty penalty for insertion/deletion (negative)
     * @return the maximum local alignment score
     */
    public static int align(String s1, String s2, int matchScore, int mismatchPenalty, int gapPenalty) {
        if (s1 == null || s2 == null) {
            throw new IllegalArgumentException("Input strings must not be null.");
        }

        int n = s1.length();
        int m = s2.length();
        int maxScore = 0;

        int[][] dp = new int[n + 1][m + 1];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                int matchOrMismatch = (s1.charAt(i - 1) == s2.charAt(j - 1)) ? matchScore : mismatchPenalty;

                dp[i][j] = Math.max(0,
                    Math.max(Math.max(dp[i - 1][j - 1] + matchOrMismatch, // match/mismatch
                                 dp[i - 1][j] + gapPenalty // deletion
                                 ),
                        dp[i][j - 1] + gapPenalty // insertion
                        ));

                if (dp[i][j] > maxScore) {
                    maxScore = dp[i][j];
                }
            }
        }

        return maxScore;
    }
}

public class AtamaIslemleri {

    public static void main(String[] args) {
        // Atama islemleri
        int x = 5; // x degiskenine 5 atandi
        int y = 10; // y degiskenine 10 atandi
        int z = 15; // z degiskenine 15 atandi

        // Toplama ve atama
        x = x + y; // x, x ve y'nin toplamina esit olur
        System.out.println("Toplama ve Atama: x = " + x + " y = " + y); // x simdi 15

        // Cikarma ve atama
        x -= y; // x, x ve y'nin farkina esit olur
        System.out.println("Cikarma ve Atama: x = " + x + " y = " + y); // x simdi 5

        // Carpma ve atama
        x *= 2; // x, x'in 2 ile carpimina esit olur
        System.out.println("Carpma ve Atama: x = " + x + " y = " + y); // x simdi 10

        // Bolme ve atama
        x /= 4; // x, x'in 4'e bolumune esit olur
        System.out.println("Bolme ve Atama: x = " + x + " y = " + y); // x simdi 2

        // Modul (Kalan) ve atama
        x %= 3; // x, x'in 3'e bolumunden kalanina esit olur
        System.out.println("Mod ve Atama: x = " + x + " y = " + y); // x simdi 2 % 3 = 2

        // x'in z ile toplanmasi
        x += z; // x, x ve z'nin toplamina esit olur
        System.out.println("Toplama ve Atama (x + z): x = " + x + " z = " + z); // x simdi 17

        // x'in z ile carpimi
        x *= z; // x, x ve z'nin carpimina esit olur
        System.out.println("Carpma ve Atama (x * z): x = " + x + " z = " + z); // x simdi 255

        // z'nin x'e bolunmesi
        x = z / x; // z'nin x'e bolumune esit olur
        System.out.println("Bolme ve Atama (z / x): x = " + x + " z = " + z); // x simdi 0

        // y'nin x'e bolumunden kalan
        x = y % (x + 1); // y'nin x'e bolumunden kalan
        System.out.println("Mod ve Atama (y % (x + 1)): x = " + x + " y = " + y); // x simdi 0

        // y'nin x'e eklenmesi
        x = 10; // x'i 10'a ayarla
        y += x; // y, y ve x'in toplamina esit olur
        System.out.println("Toplama ve Atama (y + x): x = " + x + " y = " + y); // y simdi 20

        // y'nin x'e bolunmesi
        y /= x; // y, y'nin x'e bolumune esit olur
        System.out.println("Bolme ve Atama (y / x): x = " + x + " y = " + y); // y simdi 2

        // x'in negatif degeri
        x = -x; // x'in negatif degeri
        System.out.println("Negatif deger: x = " + x); // x simdi -10
    }
}

