public class GirisYasaktirIsareti extends JPanel {

	private static final long serialVersionUID = 1L;

    // paintComponent metodu ekrani cizmek icin kullanilir
    @Override
    public void paintComponent(Graphics g) {
        super.paintComponent(g);

        // Merkez noktasini hesapla
        var merkez = new Point(getWidth() / 2, getHeight() / 2);

        // Yaricapi hesapla (panelin en ve boyunun yarisi)
        var yaricap = Math.min(getWidth() / 2, getHeight() / 2) - 5;

        // ic yaricapi hesapla
        var icYaricap = (int)(yaricap * 0.9);

        // Barin genisligini hesapla
        var barGenislik = (int)(icYaricap * 1.4);

        // Barin yuksekligini hesapla
        var barYukseklik = (int)(icYaricap * 0.35);

        // Beyaz rengini ayarla ve daire ciz
        g.setColor(Color.WHITE);
        g.fillOval(merkez.x - yaricap, merkez.y - yaricap, 2 * yaricap, 2 * yaricap);

        // Kirmizi rengini ayarla ve ic daireyi ciz
        g.setColor(Color.RED);
        g.fillOval(merkez.x - icYaricap, merkez.y - icYaricap, icYaricap * 2, icYaricap * 2);

        // Beyaz rengini tekrar ayarla ve dikdortgen (bar) ciz
        g.setColor(Color.WHITE);
        g.fillRect(merkez.x - barGenislik / 2, merkez.y - barYukseklik / 2, barGenislik, barYukseklik);
    }

    public static void main(String[] args) {
        // Swing uygulamasini baslat
        SwingUtilities.invokeLater(() -> {
            var panel = new GirisYasaktirIsareti();

            // Panelin arka plan rengini ayarla
            panel.setBackground(Color.GREEN.darker());

            // Yeni bir pencere olustur
            var pencere = new JFrame("Giris Yasaktir!");
            pencere.setSize(400, 300);
            pencere.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);

            // Paneli pencereye ekle
            pencere.getContentPane().add(panel, BorderLayout.CENTER);

            // Pencereyi gorunur hale getir
            pencere.setVisible(true);
        });
    }
}

package com.thealgorithms.datastructures.disjointsetunion;

/**
 * Disjoint Set Union (DSU) with Union by Size.
 * This data structure tracks a set of elements partitioned into disjoint (non-overlapping) subsets.
 * It supports two primary operations efficiently:
 *
 * <ul>
 *     <li>Find: Determine which subset a particular element belongs to.</li>
 *     <li>Union: Merge two subsets into a single subset using union by size.</li>
 * </ul>
 *
 * Union by size always attaches the smaller tree under the root of the larger tree.
 * This helps keep the tree shallow, improving the efficiency of find operations.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Disjoint-set_data_structure">Disjoint Set Union (Wikipedia)</a>
 */
public class DisjointSetUnionBySize<T> {
    /**
     * Node class for DSU by size.
     * Each node keeps track of its parent and the size of the set it represents.
     */
    public static class Node<T> {
        public T value;
        public Node<T> parent;
        public int size; // size of the set

        public Node(T value) {
            this.value = value;
            this.parent = this;
            this.size = 1; // initially, the set size is 1
        }
    }

    /**
     * Creates a new disjoint set containing the single specified element.
     * @param value the element to be placed in a new singleton set
     * @return a node representing the new set
     */
    public Node<T> makeSet(final T value) {
        return new Node<>(value);
    }

    /**
     * Finds and returns the representative (root) of the set containing the given node.
     * This method applies path compression to flatten the tree structure for future efficiency.
     * @param node the node whose set representative is to be found
     * @return the representative (root) node of the set
     */
    public Node<T> findSet(Node<T> node) {
        if (node != node.parent) {
            node.parent = findSet(node.parent); // path compression
        }
        return node.parent;
    }

    /**
     * Merges the sets containing the two given nodes using union by size.
     * The root of the smaller set is attached to the root of the larger set.
     * @param x a node in the first set
     * @param y a node in the second set
     */
    public void unionSets(Node<T> x, Node<T> y) {
        Node<T> rootX = findSet(x);
        Node<T> rootY = findSet(y);

        if (rootX == rootY) {
            return; // They are already in the same set
        }
        // Union by size: attach smaller tree under the larger one
        if (rootX.size < rootY.size) {
            rootX.parent = rootY;
            rootY.size += rootX.size; // update size
        } else {
            rootY.parent = rootX;
            rootX.size += rootY.size; // update size
        }
    }
}
// This implementation uses union by size instead of union by rank.
// The size field tracks the number of elements in each set.
// When two sets are merged, the smaller set is always attached to the larger set's root.
// This helps keep the tree shallow and improves the efficiency of find operations.

package com.thealgorithms.compression;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

/**
 * Implementation of the Burrows-Wheeler Transform (BWT) and its inverse.
 * <p>
 * BWT is a reversible data transformation algorithm that rearranges a string into runs of
 * similar characters. While not a compression algorithm itself, it significantly improves
 * the compressibility of data for subsequent algorithms like Move-to-Front encoding and
 * Run-Length Encoding.
 * </p>
 *
 * <p>The transform works by:
 * <ol>
 *   <li>Generating all rotations of the input string</li>
 *   <li>Sorting these rotations lexicographically</li>
 *   <li>Taking the last column of the sorted matrix as output</li>
 *   <li>Recording the index of the original string in the sorted matrix</li>
 * </ol>
 * </p>
 *
 * <p><b>Important:</b> The input string should end with a unique end-of-string marker
 * (typically '$') that:
 * <ul>
 *   <li>Does not appear anywhere else in the text</li>
 *   <li>Is lexicographically smaller than all other characters</li>
 *   <li>Ensures unique rotations and enables correct inverse transformation</li>
 * </ul>
 * Without this marker, the inverse transform may not correctly reconstruct the original string.
 * </p>
 *
 * <p><b>Time Complexity:</b>
 * <ul>
 *   <li>Forward transform: O(n² log n) where n is the string length</li>
 *   <li>Inverse transform: O(n) using the LF-mapping technique</li>
 * </ul>
 * </p>
 *
 * <p><b>Example:</b></p>
 * <pre>
 * Input:  "banana$"
 * Output: BWTResult("annb$aa", 4)
 *         - "annb$aa" is the transformed string (groups similar characters)
 *         - 4 is the index of the original string in the sorted rotations
 * </pre>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Burrows%E2%80%93Wheeler_transform">Burrows–Wheeler transform (Wikipedia)</a>
 */
public final class BurrowsWheelerTransform {

private BurrowsWheelerTransform() {
}

/**
 * A container for the result of the forward BWT.
 * <p>
 * Contains the transformed string and the index of the original string
 * in the sorted rotations matrix, both of which are required for the
 * inverse transformation.
 * </p>
 */
public static class TransformResult {
public final String encodedData;
public final int originalPosition;

public TransformResult(String encodedData, int originalPosition) {
this.encodedData = encodedData;
this.originalPosition = originalPosition;
}

@Override
public boolean equals(Object otherObject) {
if (this == otherObject) return true;
if (otherObject == null || getClass() != otherObject.getClass()) return false;
TransformResult that = (TransformResult) otherObject;
return originalPosition == that.originalPosition && encodedData.equals(that.encodedData);
}

@Override
public int hashCode() {
return 31 * encodedData.hashCode() + originalPosition;
}

@Override
public String toString() {
return "TransformResult[encodedData=" + encodedData + ", originalPosition=" + originalPosition + "]";
}
}

/**
 * Performs the forward Burrows-Wheeler Transform on the input string.
 * <p>
 * The algorithm generates all cyclic rotations of the input, sorts them
 * lexicographically, and returns the last column of this sorted matrix
 * along with the position of the original string.
 * </p>
 *
 * <p><b>Note:</b> It is strongly recommended that the input string ends with
 * a unique end-of-string marker (e.g., '$') that is lexicographically smaller
 * than any other character in the string. This ensures correct inversion.</p>
 *
 * @param sourceText the input string to transform; must not be {@code null}
 * @return a {@link TransformResult} object containing the transformed string (L-column)
 *         and the index of the original string in the sorted rotations matrix;
 *         returns {@code TransformResult("", -1)} for empty input
 * @throws NullPointerException if {@code sourceText} is {@code null}
 */
public static TransformResult encode(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
return new TransformResult("", -1);
}
int textLength = sourceText.length();
String[] rotationArray = new String[textLength];
for (int offset = 0; offset < textLength; offset++) {
rotationArray[offset] = sourceText.substring(offset) + sourceText.substring(0, offset);
}
Arrays.sort(rotationArray);
int originalIndex = Arrays.binarySearch(rotationArray, sourceText);
StringBuilder lastColumnBuilder = new StringBuilder(textLength);
for (int index = 0; index < textLength; index++) {
lastColumnBuilder.append(rotationArray[index].charAt(textLength - 1));
}
return new TransformResult(lastColumnBuilder.toString(), originalIndex);
}

/**
 * Performs the inverse Burrows-Wheeler Transform using the LF-mapping technique.
 * <p>
 * The LF-mapping (Last-First mapping) is an efficient method to reconstruct
 * the original string from the BWT output without explicitly reconstructing
 * the entire sorted rotations matrix.
 * </p>
 *
 * <p>The algorithm works by:
 * <ol>
 *   <li>Creating the first column by sorting the BWT string</li>
 *   <li>Building a mapping from first column indices to last column indices</li>
 *   <li>Following this mapping starting from the original index to reconstruct the string</li>
 * </ol>
 * </p>
 *
 * @param encodedData the transformed string (L-column) from the forward transform; must not be {@code null}
 * @param originalPosition the index of the original string row from the forward transform;
 *                      use -1 for empty strings
 * @return the original, untransformed string; returns empty string if input is empty or {@code originalPosition} is -1
 * @throws NullPointerException if {@code encodedData} is {@code null}
 * @throws IllegalArgumentException if {@code originalPosition} is out of valid range (except -1)
 */
public static String decode(String encodedData, int originalPosition) {
if (encodedData == null || encodedData.isEmpty() || originalPosition == -1) {
return "";
}
int dataLength = encodedData.length();
if (originalPosition < 0 || originalPosition >= dataLength) {
throw new IllegalArgumentException("Original index must be between 0 and " + (dataLength - 1) + ", got: " + originalPosition);
}
char[] lastColumnChars = encodedData.toCharArray();
char[] firstColumnChars = encodedData.toCharArray();
Arrays.sort(firstColumnChars);
int[] nextMapping = new int[dataLength];
Map<Character, Integer> charCounter = new HashMap<>();
Map<Character, Integer> firstOccurrenceMap = new HashMap<>();
for (int index = 0; index < dataLength; index++) {
if (!firstOccurrenceMap.containsKey(firstColumnChars[index])) {
firstOccurrenceMap.put(firstColumnChars[index], index);
}
}
for (int index = 0; index < dataLength; index++) {
char currentChar = lastColumnChars[index];
int currentCount = charCounter.getOrDefault(currentChar, 0);
int firstOccurrenceIndex = firstOccurrenceMap.get(currentChar);
nextMapping[firstOccurrenceIndex + currentCount] = index;
charCounter.put(currentChar, currentCount + 1);
}
StringBuilder restoredText = new StringBuilder(dataLength);
int currentRow = originalPosition;
for (int step = 0; step < dataLength; step++) {
restoredText.append(firstColumnChars[currentRow]);
currentRow = nextMapping[currentRow];
}
return restoredText.toString();
}
}

package tankgame;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/*
 * Main game surface: spawns descending tanks, lets the player
 * slide a turret left/right and fire shells upward, and keeps
 * a running score of destroyed vehicles. Rebuilt with a
 * different internal layout from the original tutorial version
 * but the exact same rules.
 */
public class TankSavarOyunu extends JPanel implements ActionListener {

    private static final long serialVersionUID = 1L;
    private static final int GENISLIK = 800;
    private static final int YUKSEKLIK = 600;
    private static final int TUR_SURESI_MS = 1000 / 60;
    private static final int SPAWN_ARALIGI_MS = 1000;
    private static final int YATAY_ADIM = 5;
    private static final int MERMI_HIZI = 10;
    private static final int TERFI_ESIGI = 10;

    private final List<Tank> dusmanlar = new ArrayList<>();
    private final List<Top> mermiler = new ArrayList<>();
    private Tanksavar oyuncu;

    private boolean solaGit, sagaGit, tetikCekildi;

    private final Random zar = new Random();
    private int puan;

    public TankSavarOyunu() {
        setPreferredSize(new Dimension(GENISLIK, YUKSEKLIK));
        setBackground(Color.GRAY);

        oyuncu = yeniOyuncuOlustur();

        new Timer(TUR_SURESI_MS, this).start();
        new Timer(SPAWN_ARALIGI_MS, e -> dusmanEkle()).start();

        baglaKlavye();
        setFocusable(true);
    }

    private Tanksavar yeniOyuncuOlustur() {
        int baslangicX = zar.nextInt(GENISLIK - 50);
        int baslangicY = YUKSEKLIK - 60;
        return new TanksavarJawelin(baslangicX, baslangicY);
    }

    private void dusmanEkle() {
        int x = zar.nextInt(GENISLIK - 50);
        int y = 0;
        Tank yeni = (zar.nextInt(2) == 0) ? new TankT90MS(x, y) : new TankLeopard2A4(x, y);
        dusmanlar.add(yeni);
    }

    private void baglaKlavye() {
        addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                switch (e.getKeyCode()) {
                    case KeyEvent.VK_LEFT -> solaGit = true;
                    case KeyEvent.VK_RIGHT -> sagaGit = true;
                    case KeyEvent.VK_SPACE -> {
                        if (!tetikCekildi) {
                            tetikCekildi = true;
                        }
                    }
                    default -> { }
                }
            }

            @Override
            public void keyReleased(KeyEvent e) {
                switch (e.getKeyCode()) {
                    case KeyEvent.VK_LEFT -> solaGit = false;
                    case KeyEvent.VK_RIGHT -> sagaGit = false;
                    case KeyEvent.VK_SPACE -> tetikCekildi = false;
                    default -> { }
                }
            }
        });
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        hareketEttir();
        mermileriTasi();
        atesEtGerekirse();
        carpismalariIsle();
        repaint();
    }

    private void hareketEttir() {
        if (solaGit) {
            oyuncu.x -= YATAY_ADIM;
        }
        if (sagaGit) {
            oyuncu.x += YATAY_ADIM;
        }
        for (Tank t : dusmanlar) {
            t.bounds.y += t.hiz;
        }
    }

    private void mermileriTasi() {
        List<Top> disariCikanlar = new ArrayList<>();
        for (Top mermi : mermiler) {
            mermi.konum.y -= MERMI_HIZI;
            if (mermi.konum.y < 0) {
                disariCikanlar.add(mermi);
            }
        }
        mermiler.removeAll(disariCikanlar);
    }

    private void atesEtGerekirse() {
        if (tetikCekildi) {
            mermiler.add(oyuncu.topAt());
            tetikCekildi = false;
        }
    }

    private void carpismalariIsle() {
        List<Tank> yokEdilecekTanklar = new ArrayList<>();
        List<Top> tuketilecekMermiler = new ArrayList<>();

        for (Top mermi : mermiler) {
            for (Tank hedef : dusmanlar) {
                if (mermi.konum.intersects(hedef.bounds)) {
                    yokEdilecekTanklar.add(hedef);
                    tuketilecekMermiler.add(mermi);
                    puan++;
                }
            }
        }

        if (puan % TERFI_ESIGI == 0) {
            oyuncu = terfiEttir(oyuncu);
            puan++;
        }

        dusmanlar.removeAll(yokEdilecekTanklar);
        mermiler.removeAll(tuketilecekMermiler);
    }

    private Tanksavar terfiEttir(Tanksavar mevcut) {
        if (mevcut instanceof TanksavarJawelin) {
            return new TanksavarTow2A(mevcut.x, mevcut.y);
        } else if (mevcut instanceof TanksavarTow2A) {
            return new TanksavarJawelin(mevcut.x, mevcut.y);
        }
        return mevcut;
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);

        for (Tank t : dusmanlar) {
            g.setColor(t.renk);
            g.fillRect(t.bounds.x, t.bounds.y, t.bounds.width, t.bounds.height);
        }

        g.setColor(oyuncu.renk);
        g.fillRect(oyuncu.x, oyuncu.y, oyuncu.genislik, oyuncu.yukseklik);

        for (Top mermi : mermiler) {
            g.setColor(mermi.renk);
            g.fillRect(mermi.konum.x, mermi.konum.y, mermi.konum.width, mermi.konum.height);
        }

        g.setColor(Color.WHITE);
        g.setFont(new Font("Arial", Font.BOLD, 20));
        g.drawString("Skor: " + puan, 10, 20);
    }

    public static void main(String[] args) {
        JFrame pencere = new JFrame("Tank Savar Oyunu");
        TankSavarOyunu panel = new TankSavarOyunu();
        pencere.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        pencere.add(panel);
        pencere.pack();
        pencere.setVisible(true);
    }
}

public class SinifBulunamadiHatasi {

	public static void main(String[] args) {
		try {
			// Load a class that definitely exists in the JDK
			String targetClass = "java.util.Scanner";
			Class<?> loaded = Class.forName(targetClass);
			System.out.println(targetClass + " sinifi basariyla yuklendi.");

			// Load another class known to be present in this project
			targetClass = "checked.DosyaOkumaHatasi";
			loaded = Class.forName(targetClass);
			System.out.println(targetClass + " sinifi basariyla yuklendi.");

			// This one does not exist, so Class.forName should throw
			String missingClass = "com.ornek.Sinif";
			Class<?> notFound = Class.forName(missingClass);
			System.out.println(missingClass + " sinifi basariyla yuklendi.");

		} catch (ClassNotFoundException notFoundEx) {
			System.out.println("Sinif bulunamadi: " + notFoundEx.getMessage());
			notFoundEx.printStackTrace();
		} finally {
			System.out.println("Islem tamamlandi.");
		}
	}
}

/**
 * A generic HashMap implementation that uses separate chaining with linked lists
 * to handle collisions. The class supports basic operations such as insert, delete,
 * and search, as well as displaying the contents of the hash map.
 *
 * @param <KeyType> the type of keys maintained by this map
 * @param <ValueType> the type of mapped values
 */
@SuppressWarnings("rawtypes")
public class HashMap<KeyType, ValueType> {
private final int bucketCount;
private final ChainBucket<KeyType, ValueType>[] storageBuckets;

/**
 * Constructs a HashMap with the specified hash size.
 *
 * @param hashSize the number of buckets in the hash map
 */
@SuppressWarnings("unchecked")
public HashMap(int hashSize) {
this.bucketCount = hashSize;
this.storageBuckets = new ChainBucket[hashSize];
for (int bucketIndex = 0; bucketIndex < hashSize; bucketIndex++) {
storageBuckets[bucketIndex] = new ChainBucket<>();
}
}

/**
 * Computes the hash code for the specified key.
 * Null keys are hashed to bucket 0.
 *
 * @param targetKey the key for which the hash code is to be computed
 * @return the hash code corresponding to the key
 */
private int computePosition(KeyType targetKey) {
if (targetKey == null) {
return 0;
}
int rawHash = targetKey.hashCode() % bucketCount;
return rawHash < 0 ? rawHash + bucketCount : rawHash;
}

/**
 * Inserts the specified key-value pair into the hash map.
 * If the key already exists, the value is updated.
 *
 * @param insertKey   the key to be inserted
 * @param insertValue the value to be associated with the key
 */
public void insert(KeyType insertKey, ValueType insertValue) {
int targetSlot = computePosition(insertKey);
storageBuckets[targetSlot].insert(insertKey, insertValue);
}

/**
 * Deletes the key-value pair associated with the specified key from the hash map.
 *
 * @param targetKey the key whose key-value pair is to be deleted
 */
public void delete(KeyType targetKey) {
int targetSlot = computePosition(targetKey);
storageBuckets[targetSlot].delete(targetKey);
}

/**
 * Searches for the value associated with the specified key in the hash map.
 *
 * @param searchKey the key whose associated value is to be returned
 * @return the value associated with the specified key, or null if the key does not exist
 */
public ValueType search(KeyType searchKey) {
int targetSlot = computePosition(searchKey);
KeyValueNode<KeyType, ValueType> matchedNode = storageBuckets[targetSlot].findKey(searchKey);
return matchedNode != null ? matchedNode.getValue() : null;
}

/**
 * Displays the contents of the hash map, showing each bucket and its key-value pairs.
 */
public void display() {
for (int slotIndex = 0; slotIndex < bucketCount; slotIndex++) {
System.out.printf("Bucket %d: %s%n", slotIndex, storageBuckets[slotIndex].toString());
}
}

/**
 * Clears the contents of the hash map by reinitializing each bucket.
 */
public void clear() {
for (int slotIndex = 0; slotIndex < bucketCount; slotIndex++) {
storageBuckets[slotIndex] = new ChainBucket<>();
}
}

/**
 * Gets the number of key-value pairs in the hash map.
 *
 * @return the number of key-value pairs in the hash map
 */
public int getSize() {
int totalCount = 0;
for (int slotIndex = 0; slotIndex < bucketCount; slotIndex++) {
totalCount += storageBuckets[slotIndex].isEmpty() ? 0 : 1;
}
return totalCount;
}

/**
 * A nested static class that represents a linked list used for separate chaining in the hash map.
 *
 * @param <KeyType> the type of keys maintained by this linked list
 * @param <ValueType> the type of mapped values
 */
public static class ChainBucket<KeyType, ValueType> {
private KeyValueNode<KeyType, ValueType> firstNode;

/**
 * Inserts the specified key-value pair into the linked list.
 * If the linked list is empty, the pair becomes the head.
 * Otherwise, the pair is added to the end of the list.
 *
 * @param insertKey   the key to be inserted
 * @param insertValue the value to be associated with the key
 */
public void insert(KeyType insertKey, ValueType insertValue) {
KeyValueNode<KeyType, ValueType> existingEntry = findKey(insertKey);
if (existingEntry != null) {
existingEntry.setValue(insertValue);
} else {
if (isEmpty()) {
firstNode = new KeyValueNode<>(insertKey, insertValue);
} else {
KeyValueNode<KeyType, ValueType> lastNode = findTail(firstNode);
lastNode.setNext(new KeyValueNode<>(insertKey, insertValue));
}
}
}

private KeyValueNode<KeyType, ValueType> findTail(KeyValueNode<KeyType, ValueType> startNode) {
while (startNode.getNext() != null) {
startNode = startNode.getNext();
}
return startNode;
}

/**
 * Finds the node associated with the specified key in the linked list.
 *
 * @param searchKey the key to search for
 * @return the node associated with the specified key, or null if not found
 */
public KeyValueNode<KeyType, ValueType> findKey(KeyType searchKey) {
KeyValueNode<KeyType, ValueType> currentNode = firstNode;
while (currentNode != null) {
if ((searchKey == null && currentNode.getKey() == null) ||
(currentNode.getKey() != null && currentNode.getKey().equals(searchKey))) {
return currentNode;
}
currentNode = currentNode.getNext();
}
return null;
}

/**
 * Deletes the node associated with the specified key from the linked list.
 * Handles the case where the key could be null.
 *
 * @param targetKey the key whose associated node is to be deleted
 */
public void delete(KeyType targetKey) {
if (isEmpty()) {
return;
}
if ((targetKey == null && firstNode.getKey() == null) ||
(firstNode.getKey() != null && firstNode.getKey().equals(targetKey))) {
firstNode = firstNode.getNext();
return;
}
KeyValueNode<KeyType, ValueType> currentPos = firstNode;
while (currentPos.getNext() != null) {
if ((targetKey == null && currentPos.getNext().getKey() == null) ||
(currentPos.getNext().getKey() != null && currentPos.getNext().getKey().equals(targetKey))) {
currentPos.setNext(currentPos.getNext().getNext());
return;
}
currentPos = currentPos.getNext();
}
}

/**
 * Displays the contents of the linked list as a string.
 *
 * @return a string representation of the linked list
 */
public String toString() {
KeyValueNode<KeyType, ValueType> currentNode = firstNode;
StringBuilder output = new StringBuilder();
while (currentNode != null) {
output.append(currentNode.getKey()).append("=").append(currentNode.getValue());
currentNode = currentNode.getNext();
if (currentNode != null) {
output.append(" -> ");
}
}
return output.toString().isEmpty() ? "null" : output.toString();
}

/**
 * Checks if the linked list is empty.
 *
 * @return true if the linked list is empty, false otherwise
 */
public boolean isEmpty() {
return firstNode == null;
}
}

/**
 * A nested static class representing a node in the linked list.
 *
 * @param <KeyType> the type of key maintained by this node
 * @param <ValueType> the type of value maintained by this node
 */
public static class KeyValueNode<KeyType, ValueType> {
private final KeyType nodeKey;
private ValueType nodeValue;
private KeyValueNode<KeyType, ValueType> nextNode;

/**
 * Constructs a Node with the specified key and value.
 *
 * @param inputKey   the key associated with this node
 * @param inputValue the value associated with this node
 */
public KeyValueNode(KeyType inputKey, ValueType inputValue) {
this.nodeKey = inputKey;
this.nodeValue = inputValue;
}

/**
 * Gets the key associated with this node.
 *
 * @return the key associated with this node
 */
public KeyType getKey() {
return nodeKey;
}

/**
 * Gets the value associated with this node.
 *
 * @return the value associated with this node
 */
public ValueType getValue() {
return nodeValue;
}

public void setValue(ValueType newValue) {
this.nodeValue = newValue;
}

/**
 * Gets the next node in the linked list.
 *
 * @return the next node in the linked list
 */
public KeyValueNode<KeyType, ValueType> getNext() {
return nextNode;
}

/**
 * Sets the next node in the linked list.
 *
 * @param nextElement the next node to be linked
 */
public void setNext(KeyValueNode<KeyType, ValueType> nextElement) {
this.nextNode = nextElement;
}
}
}

package forloop;
import java.util.Scanner;

public class AralikToplama {

    // Iki sinir arasindaki (kucukten buyuge) tum sayilarin toplamini dondurur
    public static void toplaAralik(int alt, int ust) {
        int birikim = 0; // toplami tutan degisken
        int sayac = alt;
        while (sayac <= ust) { // alt sinirdan ust sinira kadar ilerler
            birikim += sayac; // her adimda sayac degeri toplama katilir
            sayac++;
        }
        // Sonucu ekrana bas
        System.out.println(alt + " ile " + ust + " arasindaki sayilarin toplami: " + birikim);
    }

    public static void main(String[] args) {
        Scanner giris = new Scanner(System.in);

        // Kullanicidan ilk siniri al
        System.out.print("Baslangic degerini girin (a): ");
        int deger1 = giris.nextInt();

        // Kullanicidan ikinci siniri al
        System.out.print("Bitis degerini girin (b): ");
        int deger2 = giris.nextInt();

        // Kucuk olan deger once, buyuk olan sonra gelecek sekilde metodu cagir
        if (deger1 < deger2) {
            toplaAralik(deger1, deger2);
        } else {
            toplaAralik(deger2, deger1);
        }

        giris.close();
    }
}

package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.Map;

/**
 * A utility class to convert Roman numerals into integers.
 *
 * <p>Roman numerals are based on seven symbols given below:
 * <ul>
 *   <li>I = 1</li>
 *   <li>V = 5</li>
 *   <li>X = 10</li>
 *   <li>L = 50</li>
 *   <li>C = 100</li>
 *   <li>D = 500</li>
 *   <li>M = 1000</li>
 * </ul>
 *
 * <p>If a smaller numeral appears before a larger numeral, it is subtracted.
 * Otherwise, it is added. For example:
 * <pre>
 *   MCMXCIV = 1000 + (1000 - 100) + (100 - 10) + (5 - 1) = 1994
 * </pre>
 */
public final class RomanToInteger {

private static final Map<Character, Integer> SYMBOL_VALUES = new HashMap<>() {
{
put('I', 1);
put('V', 5);
put('X', 10);
put('L', 50);
put('C', 100);
put('D', 500);
put('M', 1000);
}
};

private RomanToInteger() {
}

/**
 * Converts a single Roman numeral character to its integer value.
 *
 * @param romanSymbol the Roman numeral character
 * @return the corresponding integer value
 * @throws IllegalArgumentException if the symbol is not a valid Roman numeral
 */
private static int getSymbolValue(final char romanSymbol) {
return SYMBOL_VALUES.computeIfAbsent(romanSymbol, symbol -> { throw new IllegalArgumentException("Unknown Roman symbol: " + symbol); });
}

/**
 * Converts a Roman numeral string to its integer equivalent.
 * Steps:
 * <ol>
 *     <li>Iterate over the string from right to left.</li>
 *     <li>For each character, convert it to an integer value.</li>
 *     <li>If the current value is greater than or equal to the max previous value, add it.</li>
 *     <li>Otherwise, subtract it from the sum.</li>
 *     <li>Update the max previous value.</li>
 *     <li>Return the sum.</li>
 * </ol>
 *
 * @param romanInput the Roman numeral string
 * @return the integer value of the Roman numeral
 * @throws IllegalArgumentException if the input contains invalid Roman characters
 * @throws NullPointerException if the input is {@code null}
 */
public static int romanToInt(String romanInput) {
if (romanInput == null) {
throw new NullPointerException("Input cannot be null");
}
String normalizedInput = romanInput.toUpperCase();
int totalSum = 0;
int maxPreviousValue = 0;
for (int position = normalizedInput.length() - 1; position >= 0; position--) {
int currentValue = getSymbolValue(normalizedInput.charAt(position));
if (currentValue >= maxPreviousValue) {
totalSum += currentValue;
maxPreviousValue = currentValue;
} else {
totalSum -= currentValue;
}
}
return totalSum;
}
}

/**
 * This class provides solutions to the Traveling Salesman Problem (TSP) using both brute-force and dynamic programming approaches.
 * For more information, see <a href="https://en.wikipedia.org/wiki/Travelling_salesman_problem">Wikipedia</a>.
 * @author  <a href="https://github.com/DenizAltunkapan">Deniz Altunkapan</a>
 */

public final class TravelingSalesman {

    // Private constructor to prevent instantiation
    private TravelingSalesman() {
    }

    /**
     * Solves the Traveling Salesman Problem (TSP) using brute-force approach.
     * This method generates all possible permutations of cities, calculates the total distance for each route, and returns the shortest distance found.
     *
     * @param distanceMatrix A square matrix where element [i][j] represents the distance from city i to city j.
     * @return The shortest possible route distance visiting all cities exactly once and returning to the starting city.
     */
    public static int bruteForce(int[][] distanceMatrix) {
        if (distanceMatrix.length <= 1) {
            return 0;
        }

        List<Integer> cities = new ArrayList<>();
        for (int i = 1; i < distanceMatrix.length; i++) {
            cities.add(i);
        }

        List<List<Integer>> permutations = generatePermutations(cities);
        int minDistance = Integer.MAX_VALUE;

        for (List<Integer> permutation : permutations) {
            List<Integer> route = new ArrayList<>();
            route.add(0);
            route.addAll(permutation);
            int currentDistance = calculateDistance(distanceMatrix, route);
            if (currentDistance < minDistance) {
                minDistance = currentDistance;
            }
        }

        return minDistance;
    }

    /**
     * Computes the total distance of a given route.
     *
     * @param distanceMatrix A square matrix where element [i][j] represents the
     *                       distance from city i to city j.
     * @param route          A list representing the order in which the cities are visited.
     * @return The total distance of the route, or Integer.MAX_VALUE if the route is invalid.
     */
    public static int calculateDistance(int[][] distanceMatrix, List<Integer> route) {
        int distance = 0;
        for (int i = 0; i < route.size() - 1; i++) {
            int d = distanceMatrix[route.get(i)][route.get(i + 1)];
            if (d == Integer.MAX_VALUE) {
                return Integer.MAX_VALUE;
            }
            distance += d;
        }
        int returnDist = distanceMatrix[route.get(route.size() - 1)][route.get(0)];
        return (returnDist == Integer.MAX_VALUE) ? Integer.MAX_VALUE : distance + returnDist;
    }

    /**
     * Generates all permutations of a given list of cities.
     *
     * @param cities A list of cities to permute.
     * @return A list of all possible permutations.
     */
    private static List<List<Integer>> generatePermutations(List<Integer> cities) {
        List<List<Integer>> permutations = new ArrayList<>();
        permute(cities, 0, permutations);
        return permutations;
    }

    /**
     * Recursively generates permutations using backtracking.
     *
     * @param arr     The list of cities.
     * @param k       The current index in the permutation process.
     * @param output  The list to store generated permutations.
     */
    private static void permute(List<Integer> arr, int k, List<List<Integer>> output) {
        if (k == arr.size()) {
            output.add(new ArrayList<>(arr));
            return;
        }
        for (int i = k; i < arr.size(); i++) {
            Collections.swap(arr, i, k);
            permute(arr, k + 1, output);
            Collections.swap(arr, i, k);
        }
    }

    /**
     * Solves the Traveling Salesman Problem (TSP) using dynamic programming with the Held-Karp algorithm.
     *
     * @param distanceMatrix A square matrix where element [i][j] represents the distance from city i to city j.
     * @return The shortest possible route distance visiting all cities exactly once and returning to the starting city.
     * @throws IllegalArgumentException if the input matrix is not square.
     */
    public static int dynamicProgramming(int[][] distanceMatrix) {
        if (distanceMatrix.length == 0) {
            return 0;
        }
        int n = distanceMatrix.length;

        for (int[] row : distanceMatrix) {
            if (row.length != n) {
                throw new IllegalArgumentException("Matrix must be square");
            }
        }

        int[][] dp = new int[n][1 << n];
        for (int[] row : dp) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        dp[0][1] = 0;

        for (int mask = 1; mask < (1 << n); mask++) {
            for (int u = 0; u < n; u++) {
                if ((mask & (1 << u)) == 0 || dp[u][mask] == Integer.MAX_VALUE) {
                    continue;
                }
                for (int v = 0; v < n; v++) {
                    if ((mask & (1 << v)) != 0 || distanceMatrix[u][v] == Integer.MAX_VALUE) {
                        continue;
                    }
                    int newMask = mask | (1 << v);
                    dp[v][newMask] = Math.min(dp[v][newMask], dp[u][mask] + distanceMatrix[u][v]);
                }
            }
        }

        int minDistance = Integer.MAX_VALUE;
        int fullMask = (1 << n) - 1;
        for (int i = 1; i < n; i++) {
            if (dp[i][fullMask] != Integer.MAX_VALUE && distanceMatrix[i][0] != Integer.MAX_VALUE) {
                minDistance = Math.min(minDistance, dp[i][fullMask] + distanceMatrix[i][0]);
            }
        }

        return minDistance == Integer.MAX_VALUE ? 0 : minDistance;
    }
}

/**
 * An implementation of the Stoer-Wagner algorithm to find the global minimum cut of an undirected, weighted graph.
 * A minimum cut is a partition of the graph's vertices into two disjoint sets with the minimum possible edge weight
 * sum connecting the two sets.
 *
 * Wikipedia: https://en.wikipedia.org/wiki/Stoer%E2%80%93Wagner_algorithm
 * Time Complexity: O(V^3) where V is the number of vertices.
 */
public class StoerWagner {

    /**
     * Finds the minimum cut in the given undirected, weighted graph.
     *
     * @param graph An adjacency matrix representing the graph. graph[i][j] is the weight of the edge between i and j.
     * @return The weight of the minimum cut.
     */
    public int findMinCut(int[][] graph) {
        int n = graph.length;
        if (n < 2) {
            return 0;
        }

        int[][] currentGraph = new int[n][n];
        for (int i = 0; i < n; i++) {
            System.arraycopy(graph[i], 0, currentGraph[i], 0, n);
        }

        int minCut = Integer.MAX_VALUE;
        boolean[] merged = new boolean[n];

        for (int phase = 0; phase < n - 1; phase++) {
            boolean[] inSetA = new boolean[n];
            int[] weights = new int[n];
            int prev = -1;
            int last = -1;

            for (int i = 0; i < n - phase; i++) {
                int maxWeight = -1;
                int currentVertex = -1;

                for (int j = 0; j < n; j++) {
                    if (!merged[j] && !inSetA[j] && weights[j] > maxWeight) {
                        maxWeight = weights[j];
                        currentVertex = j;
                    }
                }

                if (currentVertex == -1) {
                    // This can happen if the graph is disconnected.
                    return 0;
                }

                prev = last;
                last = currentVertex;
                inSetA[last] = true;

                for (int j = 0; j < n; j++) {
                    if (!merged[j] && !inSetA[j]) {
                        weights[j] += currentGraph[last][j];
                    }
                }
            }

            minCut = Math.min(minCut, weights[last]);

            // Merge 'last' vertex into 'prev' vertex
            for (int i = 0; i < n; i++) {
                currentGraph[prev][i] += currentGraph[last][i];
                currentGraph[i][prev] = currentGraph[prev][i];
            }
            merged[last] = true;
        }

        return minCut;
    }
}

