package com.thealgorithms.dynamicprogramming;

import com.thealgorithms.datastructures.graphs.UndirectedAdjacencyListGraph;

/**
 * This class implements the algorithm for calculating the maximum weighted matching in a tree.
 * The tree is represented as an undirected graph with weighted edges.
 *
 * Problem Description:
 *  Given an undirected tree G = (V, E) with edge weights γ: E → N and a root r ∈ V,
 *  the goal is to find a maximum weight matching M ⊆ E such that no two edges in M
 *  share a common vertex. The sum of the weights of the edges in M, ∑ e∈M γ(e), should be maximized.
 *  For more Information: <a href="https://en.wikipedia.org/wiki/Matching_(graph_theory)">Matching (graph theory)</a>
 *
 * @author  <a href="https://github.com/DenizAltunkapan">Deniz Altunkapan</a>
 */
public class TreeMatching {

    private UndirectedAdjacencyListGraph graph;
    private int[][] dp;

    /**
     * Constructor that initializes the graph and the DP table.
     *
     * @param graph The graph that represents the tree and is used for the matching algorithm.
     */
    public TreeMatching(UndirectedAdjacencyListGraph graph) {
        this.graph = graph;
        this.dp = new int[graph.size()][2];
    }

    /**
     * Calculates the maximum weighted matching for the tree, starting from the given root node.
     *
     * @param root The index of the root node of the tree.
     * @param parent The index of the parent node (used for recursion).
     * @return The maximum weighted matching for the tree, starting from the root node.
     *
     */
    public int getMaxMatching(int root, int parent) {
        if (root < 0 || root >= graph.size()) {
            throw new IllegalArgumentException("Invalid root: " + root);
        }
        maxMatching(root, parent);
        return Math.max(dp[root][0], dp[root][1]);
    }

    /**
     * Recursively computes the maximum weighted matching for a node, assuming that the node
     * can either be included or excluded from the matching.
     *
     * @param node The index of the current node for which the matching is calculated.
     * @param parent The index of the parent node (to avoid revisiting the parent node during recursion).
     */
    private void maxMatching(int node, int parent) {
        dp[node][0] = 0;
        dp[node][1] = 0;

        int sumWithoutEdge = 0;
        for (int adjNode : graph.getNeighbors(node)) {
            if (adjNode == parent) {
                continue;
            }
            maxMatching(adjNode, node);
            sumWithoutEdge += Math.max(dp[adjNode][0], dp[adjNode][1]);
        }

        dp[node][0] = sumWithoutEdge;

        for (int adjNode : graph.getNeighbors(node)) {
            if (adjNode == parent) {
                continue;
            }
            int weight = graph.getEdgeWeight(node, adjNode);
            dp[node][1] = Math.max(dp[node][1], sumWithoutEdge - Math.max(dp[adjNode][0], dp[adjNode][1]) + dp[adjNode][0] + weight);
        }
    }
}

package syntax;

public class MantiksalIslemler {

    public static void main(String[] args) {

        boolean truthy = true;
        boolean falsy = false;

        // Logical AND: both sides must hold.
        boolean andOutcome = truthy && falsy;
        System.out.println("VE Mantiksal Operatori (&&): " + andOutcome); // false

        // Logical OR: at least one side must hold.
        boolean orOutcome = truthy || falsy;
        System.out.println("VEYA Mantiksal Operatori (||): " + orOutcome); // true

        // Logical NOT: flips the boolean value.
        boolean notOutcome = !truthy;
        System.out.println("DEGiL Mantiksal Operatori (!): " + notOutcome); // false

        // A compound expression mixing all three operators.
        boolean combinedOutcome = (truthy && falsy) || (truthy || !falsy);
        System.out.println("Karmasik Mantiksal ifade: " + combinedOutcome); // true
    }
}

/**
 * Ana menuye sahip minimal bir metin editoru: dosya ac/kaydet/yazdir
 * ve kes/kopyala/yapistir islemlerini destekler.
 */
public class MetinEditoru extends JFrame implements ActionListener {

    private static final long serialVersionUID = 1L;

    JTextArea duzenlemeAlani;
    JFrame editorPenceresi;

    public MetinEditoru() {
        editorPenceresi = new JFrame("Metin Editoru");
        temayiUygula();

        duzenlemeAlani = new JTextArea();
        JMenuBar menuCubugu = new JMenuBar();

        menuCubugu.add(dosyaMenusunuOlustur());
        menuCubugu.add(duzenlemeMenusunuOlustur());
        menuCubugu.add(cikisOgesiniOlustur());

        editorPenceresi.setJMenuBar(menuCubugu);
        editorPenceresi.add(new JScrollPane(duzenlemeAlani));
        editorPenceresi.setSize(500, 500);
        editorPenceresi.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        editorPenceresi.setVisible(true);
    }

    private void temayiUygula() {
        try {
            UIManager.setLookAndFeel("javax.swing.plaf.metal.MetalLookAndFeel");
            MetalLookAndFeel.setCurrentTheme(new OceanTheme());
        } catch (Exception hata) {
            System.out.println(hata.getMessage());
        }
    }

    private JMenu dosyaMenusunuOlustur() {
        JMenu menu = new JMenu("Dosya");
        String[] etiketler = {"Yeni", "Ac", "Kaydet", "Yazdir"};
        for (String etiket : etiketler) {
            JMenuItem oge = new JMenuItem(etiket);
            oge.addActionListener(this);
            menu.add(oge);
        }
        return menu;
    }

    private JMenu duzenlemeMenusunuOlustur() {
        JMenu menu = new JMenu("Duzenle");
        String[] etiketler = {"Kes", "Kopyala", "Yapistir"};
        for (String etiket : etiketler) {
            JMenuItem oge = new JMenuItem(etiket);
            oge.addActionListener(this);
            menu.add(oge);
        }
        return menu;
    }

    private JMenuItem cikisOgesiniOlustur() {
        JMenuItem cikis = new JMenuItem("Cikis");
        cikis.addActionListener(this);
        return cikis;
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        String komut = e.getActionCommand();

        switch (komut) {
            case "Kes":
                duzenlemeAlani.cut();
                break;
            case "Kopyala":
                duzenlemeAlani.copy();
                break;
            case "Yapistir":
                duzenlemeAlani.paste();
                break;
            case "Kaydet":
                dosyayaKaydet();
                break;
            case "Yazdir":
                dosyayiYazdir();
                break;
            case "Ac":
                dosyaAc();
                break;
            case "Yeni":
                duzenlemeAlani.setText("");
                break;
            case "Cikis":
                editorPenceresi.dispose();
                break;
            default:
                break;
        }
    }

    private void dosyayaKaydet() {
        JFileChooser secici = new JFileChooser(System.getProperty("user.dir"));
        int secim = secici.showSaveDialog(null);

        if (secim == JFileChooser.APPROVE_OPTION) {
            File hedef = new File(secici.getSelectedFile().getAbsolutePath());
            try (BufferedWriter yazici = new BufferedWriter(new FileWriter(hedef, false))) {
                yazici.write(duzenlemeAlani.getText());
            } catch (Exception hata) {
                JOptionPane.showMessageDialog(editorPenceresi, "Dosya kaydedilemedi: " + hata.getMessage());
            }
        }
    }

    private void dosyayiYazdir() {
        try {
            duzenlemeAlani.print();
        } catch (Exception hata) {
            JOptionPane.showMessageDialog(editorPenceresi, "Yazdirma hatasi: " + hata.getMessage());
        }
    }

    private void dosyaAc() {
        JFileChooser secici = new JFileChooser(System.getProperty("user.dir"));
        int secim = secici.showOpenDialog(null);

        if (secim == JFileChooser.APPROVE_OPTION) {
            File kaynak = new File(secici.getSelectedFile().getAbsolutePath());
            try (BufferedReader okuyucu = new BufferedReader(new FileReader(kaynak))) {
                duzenlemeAlani.read(okuyucu, null);
            } catch (Exception hata) {
                JOptionPane.showMessageDialog(editorPenceresi, "Dosya acilamadi: " + hata.getMessage());
            }
        }
    }

    public static void main(String[] args) {
        new MetinEditoru();
    }
}

package PhoneNumber;

/**
 * A local phone number: area code plus number.
 */
public class PhoneNumber {
    protected int area;
    protected String number;

    public PhoneNumber(int area, String number) {
        this.area = area;
        this.number = number;
    }

    public PhoneNumber() {
    }

    public void display() {
        if (area != 0) {
            System.out.print(area + "-");
        }
        if (!number.isEmpty()) {
            System.out.print(number);
        }
        System.out.println();
    }

    public int getArea() {
        return area;
    }

    public void setArea(int area) {
        this.area = area;
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    @Override
    public String toString() {
        return "PhoneNumber{area=" + area + ", number=" + number + '}';
    }
}

package com.thealgorithms.ciphers;

/**
 * The Autokey Cipher is an interesting and historically significant encryption method,
 * as it improves upon the classic Vigenère Cipher by using the plaintext itself to
 * extend the key. This makes it harder to break using frequency analysis, as it
 * doesn’t rely solely on a repeated key.
 * https://en.wikipedia.org/wiki/Autokey_cipher
 *
 * @author bennybebo
 */
public class Autokey {

// Encrypts the plaintext using the Autokey cipher
public String encrypt(String inputText, String secretKey) {
String cleanInput = inputText.toUpperCase().replaceAll("[^A-Z]", "");
String cleanKey = secretKey.toUpperCase();
StringBuilder combinedKey = new StringBuilder(cleanKey);
combinedKey.append(cleanInput);
StringBuilder encryptedResult = new StringBuilder();
for (int position = 0; position < cleanInput.length(); position++) {
char inputChar = cleanInput.charAt(position);
char keyChar = combinedKey.charAt(position);
int encryptedValue = (inputChar - 'A' + keyChar - 'A') % 26 + 'A';
encryptedResult.append((char) encryptedValue);
}
return encryptedResult.toString();
}

// Decrypts the ciphertext using the Autokey cipher
public String decrypt(String encodedText, String secretKey) {
String cleanEncoded = encodedText.toUpperCase().replaceAll("[^A-Z]", "");
String cleanKey = secretKey.toUpperCase();
StringBuilder decryptedResult = new StringBuilder();
StringBuilder dynamicKey = new StringBuilder(cleanKey);
for (int position = 0; position < cleanEncoded.length(); position++) {
char encodedChar = cleanEncoded.charAt(position);
char keyChar = dynamicKey.charAt(position);
int decryptedValue = (encodedChar - 'A' - (keyChar - 'A') + 26) % 26 + 'A';
decryptedResult.append((char) decryptedValue);
dynamicKey.append((char) decryptedValue);
}
return decryptedResult.toString();
}
}

public class EnBuyukOrtakBolen {

	// Iki sayinin en buyuk ortak bolenini hesaplayan metod
	public static int ebob(int a, int b) { 
		// b sifir ise a geri don
		if (b == 0) 
			return a; 
		// Aksi halde, ebob(b, a % b) olarak tekrar cagirilir
		return ebob(b, a % b);  
	}

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		System.out.print("Ebobu bulmak icin bir sayi girin: ");
		int sayi1 = sc.nextInt();
		System.out.print("Ebob bulmak icin bir sayi daha girin: ");
		int sayi2 = sc.nextInt();
		sc.close();

		// En buyuk ortak boleni hesaplamak icin ebob metodu cagrilir
		int sonuc = ebob(sayi1, sayi2);
		// Sonuc ekrana yazdirilir
		System.out.print("En buyuk ortak bolen: " + sonuc);
	}
}

public class HataFirlatma {

    public static void main(String[] args) {

        try {
            divide(10, 0);
        } catch (ArithmeticException ex) {
            System.out.println("Hata: Sifira bolme islemi yapilamaz!");
            System.out.println("Hata mesaji: " + ex.getMessage());
        }

        try {
            divide(20, 5);  // ordinary division
            divide(15, -3); // division with a negative divisor
        } catch (ArithmeticException ex) {
            System.out.println("Hata olustu: " + ex.getMessage());
        }

        System.out.println("Toplama islemi: " + add(10, 5));
    }

    /**
     * Divides x by y, throwing if y is zero.
     * @param x dividend
     * @param y divisor
     * @throws ArithmeticException when y is zero
     */
    public static void divide(int x, int y) throws ArithmeticException {
        if (y == 0) {
            throw new ArithmeticException("Sifira bolme hatasi!");
        }
        int result = x / y;
        System.out.println("Bolme Islemi: " + result);
    }

    /**
     * Adds two integers.
     * @param a first operand
     * @param b second operand
     * @return sum of a and b
     */
    public static int add(int a, int b) {
        return a + b;
    }
}

