package com.thealgorithms.datastructures.trees;

import java.util.ArrayList;
import java.util.List;

/**
 * Threaded binary tree implementation that supports insertion and
 * in-order traversal without recursion or stack by using threads.
 *
 * <p>In this implementation, a node's null left/right pointers are used
 * to point to the in-order predecessor/successor respectively. Two flags
 * indicate whether left/right pointers are real children or threads.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Threaded_binary_tree">Wikipedia:
 * Threaded binary tree</a>
 */
public final class ThreadedBinaryTree {

    private Node root;

    private static final class Node {
        int value;
        Node left;
        Node right;
        boolean leftIsThread;
        boolean rightIsThread;

        Node(int value) {
            this.value = value;
            this.left = null;
            this.right = null;
            this.leftIsThread = false;
            this.rightIsThread = false;
        }
    }

    public ThreadedBinaryTree() {
        this.root = null;
    }

    /**
     * Inserts a value into the threaded binary tree. Duplicate values are inserted
     * to the right subtree (consistent deterministic rule).
     *
     * @param value the integer value to insert
     */
    public void insert(int value) {
        Node newNode = new Node(value);
        if (root == null) {
            root = newNode;
            return;
        }

        Node current = root;
        Node parent = null;

        while (true) {
            parent = current;
            if (value < current.value) {
                if (!current.leftIsThread && current.left != null) {
                    current = current.left;
                } else {
                    break;
                }
            } else { // value >= current.value
                if (!current.rightIsThread && current.right != null) {
                    current = current.right;
                } else {
                    break;
                }
            }
        }

        if (value < parent.value) {
            // attach newNode as left child
            newNode.left = parent.left;
            newNode.leftIsThread = parent.leftIsThread;
            newNode.right = parent;
            newNode.rightIsThread = true;

            parent.left = newNode;
            parent.leftIsThread = false;
        } else {
            // attach newNode as right child
            newNode.right = parent.right;
            newNode.rightIsThread = parent.rightIsThread;
            newNode.left = parent;
            newNode.leftIsThread = true;

            parent.right = newNode;
            parent.rightIsThread = false;
        }
    }

    /**
     * Returns the in-order traversal of the tree as a list of integers.
     * Traversal is done without recursion or an explicit stack by following threads.
     *
     * @return list containing the in-order sequence of node values
     */
    public List<Integer> inorderTraversal() {
        List<Integer> result = new ArrayList<>();
        Node current = root;
        if (current == null) {
            return result;
        }

        // Move to the leftmost node
        while (current.left != null && !current.leftIsThread) {
            current = current.left;
        }

        while (current != null) {
            result.add(current.value);

            // If right pointer is a thread, follow it
            if (current.rightIsThread) {
                current = current.right;
            } else {
                // Move to leftmost node in right subtree
                current = current.right;
                while (current != null && !current.leftIsThread && current.left != null) {
                    current = current.left;
                }
            }
        }

        return result;
    }

    /**
     * Helper: checks whether the tree is empty.
     *
     * @return true if tree has no nodes
     */
    public boolean isEmpty() {
        return root == null;
    }
}

/**
 * A Java implementation of the Vigenère Cipher.
 *
 * The Vigenère Cipher is a polyalphabetic substitution cipher that uses a
 * keyword to shift letters in the plaintext by different amounts, depending
 * on the corresponding character in the keyword. It wraps around the alphabet,
 * ensuring the shifts are within 'A'-'Z' or 'a'-'z'.
 *
 * Non-alphabetic characters (like spaces, punctuation) are kept unchanged.
 *
 * Encryption Example:
 * - Plaintext: "Hello World!"
 * - Key: "suchsecret"
 * - Encrypted Text: "Zynsg Yfvev!"
 *
 * Decryption Example:
 * - Ciphertext: "Zynsg Yfvev!"
 * - Key: "suchsecret"
 * - Decrypted Text: "Hello World!"
 *
 * Wikipedia Reference:
 * <a href="https://en.wikipedia.org/wiki/Vigen%C3%A8re_cipher">Vigenère Cipher - Wikipedia</a>
 *
 * @author straiffix
 * @author beingmartinbmc
 */
public class Vigenere {

/**
 * Encrypts a given message using the Vigenère Cipher with the specified key.
 * Steps:
 * 1. Iterate over each character in the message.
 * 2. If the character is a letter, shift it by the corresponding character in the key.
 * 3. Preserve the case of the letter.
 * 4. Preserve non-alphabetic characters.
 * 5. Move to the next character in the key (cyclic).
 * 6. Return the encrypted message.
 *
 * @param sourceMessage The plaintext message to encrypt.
 * @param secretKey The keyword used for encryption.
 * @throws IllegalArgumentException if the key is empty.
 * @return The encrypted message.
 */
public String encrypt(final String sourceMessage, final String secretKey) {
if (secretKey.isEmpty()) {
throw new IllegalArgumentException("Key cannot be empty.");
}
StringBuilder encryptedOutput = new StringBuilder();
int keyPosition = 0;
for (int charIndex = 0; charIndex < sourceMessage.length(); charIndex++) {
char currentChar = sourceMessage.charAt(charIndex);
if (Character.isLetter(currentChar)) {
if (Character.isUpperCase(currentChar)) {
encryptedOutput.append((char) ((currentChar + secretKey.toUpperCase().charAt(keyPosition) - 2 * 'A') % 26 + 'A'));
} else {
encryptedOutput.append((char) ((currentChar + secretKey.toLowerCase().charAt(keyPosition) - 2 * 'a') % 26 + 'a'));
}
keyPosition = ++keyPosition % secretKey.length();
} else {
encryptedOutput.append(currentChar);
}
}
return encryptedOutput.toString();
}

/**
 * Decrypts a given message encrypted with the Vigenère Cipher using the specified key.
 * Steps:
 * 1. Iterate over each character in the message.
 * 2. If the character is a letter, shift it back by the corresponding character in the key.
 * 3. Preserve the case of the letter.
 * 4. Preserve non-alphabetic characters.
 * 5. Move to the next character in the key (cyclic).
 * 6. Return the decrypted message.
 *
 * @param encryptedData The encrypted message to decrypt.
 * @param secretKey The keyword used for decryption.
 * @throws IllegalArgumentException if the key is empty.
 * @return The decrypted plaintext message.
 */
public String decrypt(final String encryptedData, final String secretKey) {
if (secretKey.isEmpty()) {
throw new IllegalArgumentException("Key cannot be empty.");
}
StringBuilder decryptedOutput = new StringBuilder();
int keyPosition = 0;
for (int charIndex = 0; charIndex < encryptedData.length(); charIndex++) {
char currentChar = encryptedData.charAt(charIndex);
if (Character.isLetter(currentChar)) {
if (Character.isUpperCase(currentChar)) {
decryptedOutput.append((char) ('Z' - (25 - (currentChar - secretKey.toUpperCase().charAt(keyPosition))) % 26));
} else {
decryptedOutput.append((char) ('z' - (25 - (currentChar - secretKey.toLowerCase().charAt(keyPosition))) % 26));
}
keyPosition = ++keyPosition % secretKey.length();
} else {
decryptedOutput.append(currentChar);
}
}
return decryptedOutput.toString();
}
}

package com.thealgorithms.ciphers;

import java.util.HashMap;
import java.util.Map;

/**
 * The simple substitution cipher is a cipher that has been in use for many
 * hundreds of years (an excellent history is given in Simon Singhs 'the Code
 * Book'). It basically consists of substituting every plaintext character for a
 * different ciphertext character. It differs from the Caesar cipher in that the
 * cipher alphabet is not simply the alphabet shifted, it is completely jumbled.
 */
public class SimpleSubCipher {

    /**
     * Encrypt text by replacing each element with its opposite character.
     *
     * @param message
     * @param cipherSmall
     * @return Encrypted message
     */
    public String encode(String message, String cipherSmall) {
        StringBuilder encoded = new StringBuilder();

        // This map is used to encode
        Map<Character, Character> cipherMap = new HashMap<>();

        char beginSmallLetter = 'a';
        char beginCapitalLetter = 'A';

        cipherSmall = cipherSmall.toLowerCase();
        String cipherCapital = cipherSmall.toUpperCase();

        // To handle Small and Capital letters
        for (int i = 0; i < cipherSmall.length(); i++) {
            cipherMap.put(beginSmallLetter++, cipherSmall.charAt(i));
            cipherMap.put(beginCapitalLetter++, cipherCapital.charAt(i));
        }

        for (int i = 0; i < message.length(); i++) {
            if (Character.isAlphabetic(message.charAt(i))) {
                encoded.append(cipherMap.get(message.charAt(i)));
            } else {
                encoded.append(message.charAt(i));
            }
        }

        return encoded.toString();
    }

    /**
     * Decrypt message by replacing each element with its opposite character in
     * cipher.
     *
     * @param encryptedMessage
     * @param cipherSmall
     * @return message
     */
    public String decode(String encryptedMessage, String cipherSmall) {
        StringBuilder decoded = new StringBuilder();

        Map<Character, Character> cipherMap = new HashMap<>();

        char beginSmallLetter = 'a';
        char beginCapitalLetter = 'A';

        cipherSmall = cipherSmall.toLowerCase();
        String cipherCapital = cipherSmall.toUpperCase();

        for (int i = 0; i < cipherSmall.length(); i++) {
            cipherMap.put(cipherSmall.charAt(i), beginSmallLetter++);
            cipherMap.put(cipherCapital.charAt(i), beginCapitalLetter++);
        }

        for (int i = 0; i < encryptedMessage.length(); i++) {
            if (Character.isAlphabetic(encryptedMessage.charAt(i))) {
                decoded.append(cipherMap.get(encryptedMessage.charAt(i)));
            } else {
                decoded.append(encryptedMessage.charAt(i));
            }
        }

        return decoded.toString();
    }
}

/**
 * A circle implementing GeometricObject.
 */
public class Circle implements GeometricObject {

    protected double radius;

    public Circle(double radius) {
        this.radius = radius;
    }

    public Circle() {
    }

    public double getRadius() {
        return radius;
    }

    public void setRadius(double radius) {
        this.radius = radius;
    }

    @Override
    public String toString() {
        return "Circle[radius=" + radius + ']';
    }

    @Override
    public double getArea() {
        return Math.PI * radius * radius;
    }

    @Override
