/**
 * ClearLeftmostSetBit class contains a method to clear the leftmost set bit of a number.
 * The leftmost set bit is the leftmost bit that is set to 1 in the binary representation of a number.
 *
 * Example:
 * 26 (11010) -> 10 (01010)
 * 1 (1) -> 0 (0)
 * 7 (111) -> 3 (011)
 * 6 (0110) -> 2 (0010)
 *
 * @author Hardvan
 */
public final class ClearLeftmostSetBit {
    private ClearLeftmostSetBit() {
    }

    /**
     * Clears the leftmost set bit (1) of a given number.
     * Step 1: Find the position of the leftmost set bit
     * Step 2: Create a mask with all bits set except for the leftmost set bit
     * Step 3: Clear the leftmost set bit using AND with the mask
     *
     * @param num The input number.
     * @return The number after clearing the leftmost set bit.
     */
    public static int clearLeftmostSetBit(int num) {
        int pos = 0;
        int temp = num;
        while (temp > 0) {
            temp >>= 1;
            pos++;
        }

        int mask = ~(1 << (pos - 1));
        return num & mask;
    }
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

/**
 * A class representing the adjacency list of a directed graph. The adjacency list
 * maintains a mapping of vertices to their adjacent vertices.
 *
 * @param <VertexType> the type of vertices, extending Comparable to ensure that vertices
 * can be compared
 */
class AdjacencyList<VertexType extends Comparable<VertexType>> {

Map<VertexType, ArrayList<VertexType>> adjacencyMap;

/**
 * Constructor to initialize the adjacency list.
 */
AdjacencyList() {
adjacencyMap = new LinkedHashMap<>();
}

/**
 * Adds a directed edge from one vertex to another in the adjacency list.
 * If the vertex does not exist, it will be added to the list.
 *
 * @param startVertex the starting vertex of the directed edge
 * @param endVertex   the destination vertex of the directed edge
 */
void addDirectedEdge(VertexType startVertex, VertexType endVertex) {
if (!adjacencyMap.containsKey(startVertex)) {
adjacencyMap.put(startVertex, new ArrayList<>());
}
adjacencyMap.get(startVertex).add(endVertex);
if (!adjacencyMap.containsKey(endVertex)) {
adjacencyMap.put(endVertex, new ArrayList<>());
}
}

/**
 * Retrieves the list of adjacent vertices for a given vertex.
 *
 * @param sourceVertex the vertex whose adjacent vertices are to be fetched
 * @return an ArrayList of adjacent vertices for sourceVertex
 */
ArrayList<VertexType> getNeighbors(VertexType sourceVertex) {
return adjacencyMap.get(sourceVertex);
}

/**
 * Retrieves the set of all vertices present in the graph.
 *
 * @return a set containing all vertices in the graph
 */
Set<VertexType> getAllVertices() {
return adjacencyMap.keySet();
}
}

/**
 * A class that performs topological sorting on a directed graph using Kahn's algorithm.
 *
 * @param <VertexType> the type of vertices, extending Comparable to ensure that vertices
 * can be compared
 */
class TopologicalSort<VertexType extends Comparable<VertexType>> {

AdjacencyList<VertexType> inputGraph;
Map<VertexType, Integer> inDegreeMap;

/**
 * Constructor to initialize the topological sorting class with a given graph.
 *
 * @param inputGraph the directed graph represented as an adjacency list
 */
TopologicalSort(AdjacencyList<VertexType> inputGraph) {
this.inputGraph = inputGraph;
}

/**
 * Calculates the in-degree of all vertices in the graph. The in-degree is
 * the number of edges directed into a vertex.
 */
void computeInDegrees() {
inDegreeMap = new HashMap<>();
for (VertexType currentVertex : inputGraph.getAllVertices()) {
inDegreeMap.putIfAbsent(currentVertex, 0);
for (VertexType neighborVertex : inputGraph.getNeighbors(currentVertex)) {
inDegreeMap.put(neighborVertex, inDegreeMap.getOrDefault(neighborVertex, 0) + 1);
}
}
}

/**
 * Returns an ArrayList containing the vertices of the graph arranged in
 * topological order. Topological sorting ensures that for any directed edge
 * (u, v), vertex u appears before vertex v in the ordering.
 *
 * @return an ArrayList of vertices in topological order
 * @throws IllegalStateException if the graph contains a cycle
 */
ArrayList<VertexType> getTopologicalOrder() {
computeInDegrees();
Queue<VertexType> processingQueue = new LinkedList<>();
for (var degreeEntry : inDegreeMap.entrySet()) {
if (degreeEntry.getValue() == 0) {
processingQueue.add(degreeEntry.getKey());
}
}
ArrayList<VertexType> sortedOrder = new ArrayList<>();
int processedCount = 0;
while (!processingQueue.isEmpty()) {
VertexType currentVertex = processingQueue.poll();
sortedOrder.add(currentVertex);
processedCount++;
for (VertexType neighborVertex : inputGraph.getNeighbors(currentVertex)) {
inDegreeMap.put(neighborVertex, inDegreeMap.get(neighborVertex) - 1);
if (inDegreeMap.get(neighborVertex) == 0) {
processingQueue.add(neighborVertex);
}
}
}
if (processedCount != inputGraph.getAllVertices().size()) {
throw new IllegalStateException("Graph contains a cycle, topological sort not possible");
}
return sortedOrder;
}
}

/**
 * A driver class that sorts a given graph in topological order using Kahn's algorithm.
 */
public final class KahnsAlgorithm {
private KahnsAlgorithm() {
}

public static void main(String[] args) {
AdjacencyList<String> sampleGraph = new AdjacencyList<>();
sampleGraph.addDirectedEdge("a", "b");
sampleGraph.addDirectedEdge("c", "a");
sampleGraph.addDirectedEdge("a", "d");
sampleGraph.addDirectedEdge("b", "d");
sampleGraph.addDirectedEdge("c", "u");
sampleGraph.addDirectedEdge("u", "b");
TopologicalSort<String> sorter = new TopologicalSort<>(sampleGraph);
for (String vertexName : sorter.getTopologicalOrder()) {
System.out.print(vertexName + " ");
}
}
}

import javax.swing.*;
import java.io.*;
import java.awt.event.*;
import javax.swing.plaf.metal.*;

/**
 * Ana menuye sahip minimal bir metin editoru: dosya ac/kaydet/yazdir
 * ve kes/kopyala/yapistir islemlerini destekler.
 */
public class MetinEditoru extends JFrame implements ActionListener {

    private static final long serialVersionUID = 1L;

    JTextArea duzenlemeAlani;
    JFrame editorPenceresi;

    public MetinEditoru() {
        editorPenceresi = new JFrame("Metin Editoru");
        temayiUygula();

        duzenlemeAlani = new JTextArea();
        JMenuBar menuCubugu = new JMenuBar();

        menuCubugu.add(dosyaMenusunuOlustur());
        menuCubugu.add(duzenlemeMenusunuOlustur());
        menuCubugu.add(cikisOgesiniOlustur());

        editorPenceresi.setJMenuBar(menuCubugu);
        editorPenceresi.add(new JScrollPane(duzenlemeAlani));
        editorPenceresi.setSize(500, 500);
        editorPenceresi.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        editorPenceresi.setVisible(true);
    }

    private void temayiUygula() {
        try {
            UIManager.setLookAndFeel("javax.swing.plaf.metal.MetalLookAndFeel");
            MetalLookAndFeel.setCurrentTheme(new OceanTheme());
        } catch (Exception hata) {
            System.out.println(hata.getMessage());
        }
    }

    private JMenu dosyaMenusunuOlustur() {
        JMenu menu = new JMenu("Dosya");
        String[] etiketler = {"Yeni", "Ac", "Kaydet", "Yazdir"};
        for (String etiket : etiketler) {
            JMenuItem oge = new JMenuItem(etiket);
            oge.addActionListener(this);
            menu.add(oge);
        }
        return menu;
    }

    private JMenu duzenlemeMenusunuOlustur() {
        JMenu menu = new JMenu("Duzenle");
        String[] etiketler = {"Kes", "Kopyala", "Yapistir"};
        for (String etiket : etiketler) {
            JMenuItem oge = new JMenuItem(etiket);
            oge.addActionListener(this);
            menu.add(oge);
        }
        return menu;
    }

    private JMenuItem cikisOgesiniOlustur() {
        JMenuItem cikis = new JMenuItem("Cikis");
        cikis.addActionListener(this);
        return cikis;
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        String komut = e.getActionCommand();

        switch (komut) {
            case "Kes":
                duzenlemeAlani.cut();
                break;
            case "Kopyala":
                duzenlemeAlani.copy();
                break;
            case "Yapistir":
                duzenlemeAlani.paste();
                break;
            case "Kaydet":
                dosyayaKaydet();
                break;
            case "Yazdir":
                dosyayiYazdir();
                break;
            case "Ac":
                dosyaAc();
                break;
            case "Yeni":
                duzenlemeAlani.setText("");
                break;
            case "Cikis":
                editorPenceresi.dispose();
                break;
            default:
                break;
        }
    }

    private void dosyayaKaydet() {
        JFileChooser secici = new JFileChooser(System.getProperty("user.dir"));
        int secim = secici.showSaveDialog(null);

        if (secim == JFileChooser.APPROVE_OPTION) {
            File hedef = new File(secici.getSelectedFile().getAbsolutePath());
            try (BufferedWriter yazici = new BufferedWriter(new FileWriter(hedef, false))) {
                yazici.write(duzenlemeAlani.getText());
            } catch (Exception hata) {
                JOptionPane.showMessageDialog(editorPenceresi, "Dosya kaydedilemedi: " + hata.getMessage());
            }
        }
    }

    private void dosyayiYazdir() {
        try {
            duzenlemeAlani.print();
        } catch (Exception hata) {
            JOptionPane.showMessageDialog(editorPenceresi, "Yazdirma hatasi: " + hata.getMessage());
        }
    }

    private void dosyaAc() {
        JFileChooser secici = new JFileChooser(System.getProperty("user.dir"));
        int secim = secici.showOpenDialog(null);

        if (secim == JFileChooser.APPROVE_OPTION) {
            File kaynak = new File(secici.getSelectedFile().getAbsolutePath());
            try (BufferedReader okuyucu = new BufferedReader(new FileReader(kaynak))) {
                duzenlemeAlani.read(okuyucu, null);
            } catch (Exception hata) {
                JOptionPane.showMessageDialog(editorPenceresi, "Dosya acilamadi: " + hata.getMessage());
            }
        }
    }

    public static void main(String[] args) {
        new MetinEditoru();
    }
}

