/**
 * Demonstrates subclassing Thread directly (as opposed to Runnable),
 * with a tick counter and a cooperative stop flag.
 */
public class ThreadOrnegi extends Thread {

    private final String label;
    private final int intervalMillis;
    private volatile boolean running = true;

    public ThreadOrnegi(String label, int intervalMillis) {
        this.label = label;
        this.intervalMillis = intervalMillis;
    }

    @Override
    public void run() {
        int tick = 0;
        while (running) {
            System.out.println(Thread.currentThread().getName() + ": " + label + " [" + tick + "]");
            try {
                Thread.sleep(intervalMillis);
            } catch (InterruptedException interrupted) {
                System.out.println(Thread.currentThread().getName() + " kesildi.");
                return;
            }
            tick++;
        }
        System.out.println(Thread.currentThread().getName() + " durduruldu.");
    }

    public void requestStop() {
        running = false;
    }

    public static void main(String[] args) {
        ThreadOrnegi workerA = new ThreadOrnegi("ali", 1000);
        Thread t1 = new Thread(workerA, "Thread-1");

        ThreadOrnegi workerB = new ThreadOrnegi("veli", 2000);
        Thread t2 = new Thread(workerB, "Thread-2");

        ThreadOrnegi workerC = new ThreadOrnegi("ayse", 3000);
        Thread t3 = new Thread(workerC, "Thread-3");

        t1.start();
        t2.start();
        t3.start();

        // Keep the main thread busy while the workers run in parallel
        for (int step = 0; step < 5; step++) {
            System.out.println("Ana thread is yapiyor: " + step);
            pause(500);
        }

        pause(10000);

        System.out.println("Tum thread'ler durduruluyor...");
        workerA.requestStop();
        workerB.requestStop();
        workerC.requestStop();

        for (Thread t : new Thread[] { t1, t2, t3 }) {
            try {
                t.join();
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }

        System.out.println("Program tamamlandi.");
    }

    private static void pause(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}

package com.thealgorithms.backtracking;

/**
 * Problem Statement:
 * Find the number of ways that a given integer, N, can be expressed as the sum of the Xth powers
 * of unique, natural numbers.
 * For example, if N=100 and X=3, we have to find all combinations of unique cubes adding up to 100.
 * The only solution is 1^3 + 2^3 + 3^3 + 4^3. Therefore, the output will be 1.
 *
 * N is represented by the parameter 'targetSum' in the code.
 * X is represented by the parameter 'power' in the code.
 */
public class PowerSum {

    /**
     * Calculates the number of ways to express the target sum as a sum of Xth powers of unique natural numbers.
     *
     * @param targetSum The target sum to achieve (N in the problem statement)
     * @param power The power to raise natural numbers to (X in the problem statement)
     * @return The number of ways to express the target sum
     */
    public int powSum(int targetSum, int power) {
        // Special case: when both targetSum and power are zero
        if (targetSum == 0 && power == 0) {
            return 1; // by convention, one way to sum to zero: use nothing
        }
        return sumRecursive(targetSum, power, 1, 0);
    }

    /**
     * Recursively calculates the number of ways to express the remaining sum as a sum of Xth powers.
     *
     * @param remainingSum The remaining sum to achieve
     * @param power The power to raise natural numbers to (X in the problem statement)
     * @param currentNumber The current natural number being considered
     * @param currentSum The current sum of powered numbers
     * @return The number of valid combinations
     */
    private int sumRecursive(int remainingSum, int power, int currentNumber, int currentSum) {
        int newSum = currentSum + (int) Math.pow(currentNumber, power);

        if (newSum == remainingSum) {
            return 1;
        }
        if (newSum > remainingSum) {
            return 0;
        }

        return sumRecursive(remainingSum, power, currentNumber + 1, newSum) + sumRecursive(remainingSum, power, currentNumber + 1, currentSum);
    }
}

/**
 * A class that counts the number of different connected components in a graph
 *
 * @author Lukas Keul, Florian Mercks
 */
class Graph<E extends Comparable<E>> {

    class Node {

        E name;

        Node(E name) {
            this.name = name;
        }
    }

    class Edge {

        Node startNode;
        Node endNode;

        Edge(Node startNode, Node endNode) {
            this.startNode = startNode;
            this.endNode = endNode;
        }
    }

    ArrayList<Edge> edgeList;
    ArrayList<Node> nodeList;

    Graph() {
        edgeList = new ArrayList<Edge>();
        nodeList = new ArrayList<Node>();
    }

    /**
     * Adds a new Edge to the graph. If the nodes aren't yet in nodeList, they
     * will be added to it.
     *
     * @param startNode the starting Node from the edge
     * @param endNode the ending Node from the edge
     */
    public void addEdge(E startNode, E endNode) {
        Node start = null;
        Node end = null;
        for (Node node : nodeList) {
            if (startNode.compareTo(node.name) == 0) {
                start = node;
            } else if (endNode.compareTo(node.name) == 0) {
                end = node;
            }
        }
        if (start == null) {
            start = new Node(startNode);
            nodeList.add(start);
        }
        if (end == null) {
            end = new Node(endNode);
            nodeList.add(end);
        }

        edgeList.add(new Edge(start, end));
    }

    /**
     * Main method used for counting the connected components. Iterates through
     * the array of nodes to do a depth first search to get all nodes of the
     * graph from the actual node. These nodes are added to the array
     * markedNodes and will be ignored if they are chosen in the nodeList.
     *
     * @return returns the amount of unconnected graphs
     */
    public int countGraphs() {
        int count = 0;
        Set<Node> markedNodes = new HashSet<Node>();

        for (Node n : nodeList) {
            if (markedNodes.add(n)) {
                markedNodes.addAll(depthFirstSearch(n, new ArrayList<Node>()));
                count++;
            }
        }

        return count;
    }

    /**
     * Implementation of depth first search.
     *
     * @param n the actual visiting node
     * @param visited A list of already visited nodes in the depth first search
     * @return returns a set of visited nodes
     */
    public ArrayList<Node> depthFirstSearch(Node n, ArrayList<Node> visited) {
        visited.add(n);
        for (Edge e : edgeList) {
            if (e.startNode.equals(n) && !visited.contains(e.endNode)) {
                depthFirstSearch(e.endNode, visited);
            }
        }
        return visited;
    }
}

public final class ConnectedComponent {
    private ConnectedComponent() {
    }

    public static void main(String[] args) {
        Graph<Character> graphChars = new Graph<>();

        // Graph 1
        graphChars.addEdge('a', 'b');
        graphChars.addEdge('a', 'e');
        graphChars.addEdge('b', 'e');
        graphChars.addEdge('b', 'c');
        graphChars.addEdge('c', 'd');
        graphChars.addEdge('d', 'a');

        graphChars.addEdge('x', 'y');
        graphChars.addEdge('x', 'z');

        graphChars.addEdge('w', 'w');

        Graph<Integer> graphInts = new Graph<>();

        // Graph 2
        graphInts.addEdge(1, 2);
        graphInts.addEdge(2, 3);
        graphInts.addEdge(2, 4);
        graphInts.addEdge(3, 5);

        graphInts.addEdge(7, 8);
        graphInts.addEdge(8, 10);
        graphInts.addEdge(10, 8);

        System.out.println("Amount of different char-graphs: " + graphChars.countGraphs());
        System.out.println("Amount of different int-graphs: " + graphInts.countGraphs());
    }
}

