public final class BinaryToOctal {
private static final int BITS_PER_GROUP = 3;
private static final int BINARY_RADIX = 2;
private static final int DECIMAL_RADIX = 10;

private BinaryToOctal() {
}

/**
 * This method converts a binary number to an octal number.
 *
 * @param binaryInput The binary number
 * @return The octal number
 * @throws IllegalArgumentException if the input is not a valid binary number
 */
public static String convertBinaryToOctal(int binaryInput) {
if (binaryInput == 0) {
return "0";
}
if (!String.valueOf(binaryInput).matches("[01]+")) {
throw new IllegalArgumentException("Input is not a valid binary number.");
}
StringBuilder octalResult = new StringBuilder();
int remainingValue = binaryInput;
int powerMultiplier = 1;
while (remainingValue != 0) {
int octalDigit = 0;
for (int bitPos = 0; bitPos < BITS_PER_GROUP && remainingValue != 0; bitPos++) {
int currentBit = remainingValue % DECIMAL_RADIX;
remainingValue /= DECIMAL_RADIX;
octalDigit += currentBit * powerMultiplier;
powerMultiplier *= BINARY_RADIX;
}
octalResult.insert(0, octalDigit);
powerMultiplier = 1;
}
return octalResult.toString();
}
}

public class KabarcikSiralama {

    public static void main(String[] args) {

        int[] veriler = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        kabarcikYontemiUygula(veriler);

        System.out.println("Siralanmis Dizi:");
        StringBuilder cikti = new StringBuilder();
        for (int deger : veriler) {
            cikti.append(deger).append(' ');
        }
        System.out.print(cikti);
    }

    // Bubble sort - komsu elemanlari kiyaslayip gerekince yer degistirir
    static void kabarcikYontemiUygula(int[] veriler) {
        int boyut = veriler.length;
        boolean degisiklikOldu;

        int tur = 0;
        do {
            degisiklikOldu = false;
            for (int k = 0; k < boyut - 1 - tur; k++) {
                if (veriler[k] > veriler[k + 1]) {
                    int gecici = veriler[k];
                    veriler[k] = veriler[k + 1];
                    veriler[k + 1] = gecici;
                    degisiklikOldu = true;
                }
            }
            tur++;
        } while (degisiklikOldu && tur < boyut - 1);
    }
}

public class IdealKiloHesaplayici {

	public static void main(String[] args) {

		Scanner scanner = new Scanner(System.in);

		// Kullanicidan boyunu metre cinsinden girmesini iste
		System.out.print("Boyunuzu metre cinsinden giriniz: ");
		double boy = scanner.nextDouble();
		scanner.close();

		// Kullanicinin boyuna gore ideal kilosunu hesapla
		double idealKilo = 0;
		if (boy > 1.5) {
			idealKilo = (boy - 1.5) * 90 + 50;
		} else {
			idealKilo = 50;
		}

		// Ideal kiloyu yazdir
		System.out.println("Ideal kilonuz: " + idealKilo + " kilogram");
	}
}

