package com.thealgorithms.datastructures.disjointsetunion;

/**
 * Disjoint Set Union (DSU) with Union by Size.
 * This data structure tracks a set of elements partitioned into disjoint (non-overlapping) subsets.
 * It supports two primary operations efficiently:
 *
 * <ul>
 *     <li>Find: Determine which subset a particular element belongs to.</li>
 *     <li>Union: Merge two subsets into a single subset using union by size.</li>
 * </ul>
 *
 * Union by size always attaches the smaller tree under the root of the larger tree.
 * This helps keep the tree shallow, improving the efficiency of find operations.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Disjoint-set_data_structure">Disjoint Set Union (Wikipedia)</a>
 */
public class DisjointSetUnionBySize<ElementType> {
/**
 * Node class for DSU by size.
 * Each node keeps track of its parent and the size of the set it represents.
 */
public static class SetNode<ElementType> {
public ElementType storedValue;
public SetNode<ElementType> parentNode;
public int setSize;

public SetNode(ElementType elementValue) {
this.storedValue = elementValue;
this.parentNode = this;
this.setSize = 1;
}
}

/**
 * Creates a new disjoint set containing the single specified element.
 * @param elementValue the element to be placed in a new singleton set
 * @return a node representing the new set
 */
public SetNode<ElementType> createSet(final ElementType elementValue) {
return new SetNode<>(elementValue);
}

/**
 * Finds and returns the representative (root) of the set containing the given node.
 * This method applies path compression to flatten the tree structure for future efficiency.
 * @param targetNode the node whose set representative is to be found
 * @return the representative (root) node of the set
 */
public SetNode<ElementType> findRoot(SetNode<ElementType> targetNode) {
if (targetNode != targetNode.parentNode) {
targetNode.parentNode = findRoot(targetNode.parentNode);
}
return targetNode.parentNode;
}

/**
 * Merges the sets containing the two given nodes using union by size.
 * The root of the smaller set is attached to the root of the larger set.
 * @param firstNode a node in the first set
 * @param secondNode a node in the second set
 */
public void mergeSets(SetNode<ElementType> firstNode, SetNode<ElementType> secondNode) {
SetNode<ElementType> rootFirst = findRoot(firstNode);
SetNode<ElementType> rootSecond = findRoot(secondNode);
if (rootFirst == rootSecond) {
return;
}
if (rootFirst.setSize < rootSecond.setSize) {
rootFirst.parentNode = rootSecond;
rootSecond.setSize += rootFirst.setSize;
} else {
rootSecond.parentNode = rootFirst;
rootFirst.setSize += rootSecond.setSize;
}
}
}```

/**
 * The FractionalKnapsack class provides a method to solve the fractional knapsack problem
 * using a greedy algorithm approach. It allows for selecting fractions of items to maximize
 * the total value in a knapsack with a given weight capacity.
 *
 * The problem consists of a set of items, each with a weight and a value, and a knapsack
 * that can carry a maximum weight. The goal is to maximize the value of items in the knapsack,
 * allowing for the inclusion of fractions of items.
 *
 * Problem Link: https://en.wikipedia.org/wiki/Continuous_knapsack_problem
 */
public final class FractionalKnapsack {
    private FractionalKnapsack() {
    }

    /**
     * Computes the maximum value that can be accommodated in a knapsack of a given capacity.
     *
     * @param weight an array of integers representing the weights of the items
     * @param value an array of integers representing the values of the items
     * @param capacity an integer representing the maximum weight capacity of the knapsack
     * @return the maximum value that can be obtained by including the items in the knapsack
     */
    public static int fractionalKnapsack(int[] weight, int[] value, int capacity) {
        double[][] ratio = new double[weight.length][2];

        for (int i = 0; i < weight.length; i++) {
            ratio[i][0] = i;
            ratio[i][1] = value[i] / (double) weight[i];
        }

        Arrays.sort(ratio, Comparator.comparingDouble(o -> o[1]));

        int finalValue = 0;
        double current = capacity;

        for (int i = ratio.length - 1; i >= 0; i--) {
            int index = (int) ratio[i][0];
            if (current >= weight[index]) {
                finalValue += value[index];
                current -= weight[index];
            } else {
                finalValue += (int) (ratio[i][1] * current);
                break;
            }
        }
        return finalValue;
    }
}

