/*
 * Girilen bir tam sayinin tersten okundugunda da ayni olup olmadigini,
 * yani palindrom olup olmadigini test eder.
 */

public class PalindromKontrol {

	// Sayiyi tersine cevirip orijinaliyle karsilastirarak palindrom kontrolu yapar
	public static boolean palindromMu(int deger) {

		int orijinalDeger = deger;
		int tersCevrilmisDeger = 0;

		for (int kalan = deger; kalan > 0; kalan /= 10) {
			int sonRakam = kalan % 10;
			tersCevrilmisDeger = (tersCevrilmisDeger * 10) + sonRakam;
		}

		return orijinalDeger == tersCevrilmisDeger;
	}

	public static void main(String[] args) {

		Scanner girisAraci = new Scanner(System.in);
		System.out.print("Bir sayi girin: ");
		int girilenSayi = girisAraci.nextInt();
		girisAraci.close();

		if (palindromMu(girilenSayi)) {
			System.out.println(girilenSayi + " bir palindromdur.");
		} else {
			System.out.println(girilenSayi + " bir palindrom degildir.");
		}
	}
}

package array;
import java.util.Arrays;
import java.util.Scanner;

public class IkiliArama {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        System.out.println(Arrays.toString(dizi));

        // Sirali bir dizi olustur
        Arrays.sort(dizi);

        System.out.println(Arrays.toString(dizi));

        System.out.print("Aranacak degeri girin: ");
        int aranan = scanner.nextInt();

        int sonuc = ikiliArama(dizi, aranan);

        if (sonuc == -1) {
            // Deger bulunamazsa mesaj goster
            System.out.println("Deger bulunamadi.");
        } else {
            // Deger bulunursa indisi yazdir
            System.out.println("Deger bulundu! Indis: " + sonuc);
        }

        scanner.close();
    }

    public static int ikiliArama(int[] dizi, int aranan) {
        int sol = 0;
        int sag = dizi.length - 1;

        // Sol ve sag indeksler arasinda arama yap
        while (sol <= sag) {
            // Ortadaki elemani hesapla
            int orta = sol + (sag - sol) / 2;

            // Ortadaki eleman aranan degere esitse indisi dondur
            if (dizi[orta] == aranan) {
                return orta;
            }

            // Aranan deger ortadaki elemandan buyukse sag tarafina git
            if (dizi[orta] < aranan) {
                sol = orta + 1;
            } else {
                // Aranan deger ortadaki elemandan kucukse sol tarafina git
                sag = orta - 1;
            }
        }

        // Deger bulunamazsa -1 dondur
        return -1;
    }
}

package com.thealgorithms.datastructures.lists;

import java.util.Comparator;
import java.util.PriorityQueue;

/**
 * The MergeKSortedLinkedList class provides a method to merge multiple sorted linked lists
 * into a single sorted linked list.
 * This implementation uses a min-heap (priority queue) to efficiently
 * find the smallest node across all lists, thus optimizing the merge process.
 *
 * <p>Example usage:
 * <pre>
 * Node list1 = new Node(1, new Node(4, new Node(5)));
 * Node list2 = new Node(1, new Node(3, new Node(4)));
 * Node list3 = new Node(2, new Node(6));
 * Node[] lists = { list1, list2, list3 };
 *
 * MergeKSortedLinkedList merger = new MergeKSortedLinkedList();
 * Node mergedHead = merger.mergeKList(lists, lists.length);
 * </pre>
 * </p>
 *
 * <p>This class is designed to handle nodes of integer linked lists and can be expanded for additional data types if needed.</p>
 *
 * @author Arun Pandey (https://github.com/pandeyarun709)
 */
public class MergeKSortedLinkedList {

    /**
     * Merges K sorted linked lists into a single sorted linked list.
     *
     * <p>This method uses a priority queue (min-heap) to repeatedly extract the smallest node from the heads of all the lists,
     * then inserts the next node from that list into the heap. The process continues until all nodes have been processed,
     * resulting in a fully merged and sorted linked list.</p>
     *
     * @param a Array of linked list heads to be merged.
     * @param n Number of linked lists.
     * @return Head of the merged sorted linked list.
     */
    Node mergeKList(Node[] a, int n) {
        if (a == null || n == 0) {
            return null;
        }

        // Min Heap to store nodes based on their values for efficient retrieval of the smallest element.
        PriorityQueue<Node> minHeap = new PriorityQueue<>(Comparator.comparingInt(x -> x.data));

        // Initialize the min-heap with the head of each non-null linked list
        for (Node node : a) {
            if (node != null) {
                minHeap.add(node);
            }
        }

        // Start merging process
        Node head = minHeap.poll(); // Smallest head is the initial head of the merged list
        if (head != null && head.next != null) {
            minHeap.add(head.next);
        }

        Node curr = head;
        while (!minHeap.isEmpty()) {
            Node temp = minHeap.poll();
            curr.next = temp;
            curr = temp;

            // Add the next node in the current list to the heap if it exists
            if (temp.next != null) {
                minHeap.add(temp.next);
            }
        }

        return head;
    }

    /**
     * Represents a node in the linked list.
     */
    static class Node {
        int data;
        Node next;

        Node(int data) {
            this.data = data;
            this.next = null;
        }

        Node(int data, Node next) {
            this.data = data;
            this.next = next;
        }
    }
}

// BankaHesabi sinifi
public class BankaHesabi {

	private int hesapNumarasi; // Hesap numarasi
	private double bakiye; // Hesap bakiyesi
	private String hesapTuru; // Hesap turu (orn. "Vadesiz", "Vadeli")

	// BankaHesabi sinifinin yapici metodu
	public BankaHesabi(int hesapNumarasi, double bakiye, String hesapTuru) {
		this.hesapNumarasi = hesapNumarasi;
		this.bakiye = bakiye;
		this.hesapTuru = hesapTuru;
	}

	// Hesap numarasini donduren metod
	public int getHesapNumarasi() {
		return hesapNumarasi;
	}

	// Hesap bakiyesini donduren metod
	public double getBakiye() {
		return bakiye;
	}

	// Hesap turunu donduren metod
	public String getHesapTuru() {
		return hesapTuru;
	}

	// Para yatirma islemi
	public void paraYatir(double miktar) {
		if (miktar > 0) {
			bakiye += miktar;
			System.out.println(miktar + " TL yatirildi. Yeni bakiye: " + bakiye);
		} else {
			System.out.println("Yatirilan miktar gecersiz.");
		}
	}

	// Para cekme islemi
	public void paraCek(double miktar) {
		if (miktar <= bakiye && miktar > 0) {
			bakiye -= miktar;
			System.out.println(miktar + " TL cekildi. Kalan bakiye: " + bakiye);
		} else if (miktar > bakiye) {
			System.out.println("Yetersiz bakiye.");
		} else {
			System.out.println("cekilen miktar gecersiz.");
		}
	}

	// Faiz ekleme islemi (Vadeli hesap icin)
	public void faizEkle(double oran) {
		if (hesapTuru.equals("Vadeli") && oran > 0) {
			double faiz = bakiye * oran / 100;
			bakiye += faiz;
			System.out.println("Faiz ekleniyor: " + faiz + " TL. Yeni bakiye: " + bakiye);
		} else if (!hesapTuru.equals("Vadeli")) {
			System.out.println("Faiz yalnizca vadeli hesaplarda uygulanabilir.");
		} else {
			System.out.println("Gecersiz faiz orani.");
		}
	}

	// Baska bir hesaba transfer islemi
	public void transfer(BankaHesabi hedefHesap, double miktar) {
		if (miktar <= bakiye && miktar > 0) {
			bakiye -= miktar;
			hedefHesap.paraYatir(miktar);
			System.out.println(miktar + " TL transfer edildi. Yeni bakiye: " + bakiye);
		} else {
			System.out.println("Yetersiz bakiye veya gecersiz miktar.");
		}
	}
}

/**
 * Finds all combinations of a given array using backtracking algorithm * @author Alan Piao (<a href="https://github.com/cpiao3">git-Alan Piao</a>)
 */
public final class Combination {
    private Combination() {
    }

    /**
     * Find all combinations of given array using backtracking
     * @param arr the array.
     * @param n length of combination
     * @param <T> the type of elements in the array.
     * @return a list of all combinations of length n. If n == 0, return null.
     */
    public static <T> List<TreeSet<T>> combination(T[] arr, int n) {
        if (n < 0) {
            throw new IllegalArgumentException("The combination length cannot be negative.");
        }

        if (n == 0) {
            return Collections.emptyList();
        }
        T[] array = arr.clone();
        Arrays.sort(array);

        List<TreeSet<T>> result = new LinkedList<>();
        backtracking(array, n, 0, new TreeSet<T>(), result);
        return result;
    }

    /**
     * Backtrack all possible combinations of a given array
     * @param arr the array.
     * @param n length of the combination
     * @param index the starting index.
     * @param currSet set that tracks current combination
     * @param result the list contains all combination.
     * @param <T> the type of elements in the array.
     */
    private static <T> void backtracking(T[] arr, int n, int index, TreeSet<T> currSet, List<TreeSet<T>> result) {
        if (index + n - currSet.size() > arr.length) {
            return;
        }
        if (currSet.size() == n - 1) {
            for (int i = index; i < arr.length; i++) {
                currSet.add(arr[i]);
                result.add(new TreeSet<>(currSet));
                currSet.remove(arr[i]);
            }
            return;
        }
        for (int i = index; i < arr.length; i++) {
            currSet.add(arr[i]);
            backtracking(arr, n, i + 1, currSet, result);
            currSet.remove(arr[i]);
        }
    }
}

/**
 * Class to solve the Bandwidth Allocation Problem.
 * The goal is to maximize the value gained by allocating bandwidth to users.
 * Example:
 * Bandwidth = 10
 * Users = [3, 5, 7]
 * Values = [10, 20, 30]
 * The maximum value achievable is 40 by allocating 3 units to user 0 and 7 units to user 2.
 *
 * @author Hardvan
 */
public final class BandwidthAllocation {
    private BandwidthAllocation() {
    }

    /**
     * Allocates bandwidth to maximize value.
     * Steps:
     * 1. Calculate the ratio of value/demand for each user.
     * 2. Sort the users in descending order of the ratio.
     * 3. Allocate bandwidth to users in order of the sorted list.
     * 4. If the bandwidth is not enough to allocate the full demand of a user, allocate a fraction of the demand.
     * 5. Return the maximum value achievable.
     *
     * @param bandwidth total available bandwidth to allocate
     * @param users     array of user demands
     * @param values    array of values associated with each user's demand
     * @return the maximum value achievable
     */
    public static int maxValue(int bandwidth, int[] users, int[] values) {
        int n = users.length;
        double[][] ratio = new double[n][2]; // {index, ratio}

        for (int i = 0; i < n; i++) {
            ratio[i][0] = i;
            ratio[i][1] = (double) values[i] / users[i];
        }

        Arrays.sort(ratio, (a, b) -> Double.compare(b[1], a[1]));

        int maxValue = 0;
        for (int i = 0; i < n; i++) {
            int index = (int) ratio[i][0];
            if (bandwidth >= users[index]) {
                maxValue += values[index];
                bandwidth -= users[index];
            } else {
                maxValue += (int) (ratio[i][1] * bandwidth);
                break;
            }
        }
        return maxValue;
    }
}

package array;

import java.util.Scanner;

public class KartNumarasiDogrulayici {

    // Tek bir sayinin basamaklarini toplar (orn: 47 -> 4+7 = 11)
    private static int basamakToplamiHesapla(int deger) {
        int birikim = 0;
        int kalan = deger;
        while (kalan != 0) {
            birikim = birikim + (kalan % 10);
            kalan /= 10;
        }
        return birikim;
    }

    // Hata ayiklama amacli dizi gosterimi
    private static void diziyiGoster(int[] veriler) {
        StringBuilder sb = new StringBuilder("Dizi: ");
        for (int deger : veriler) {
            sb.append(deger).append(' ');
        }
        System.out.println(sb.toString().trim());
    }

    // Karakter dizisindeki her rakami int dizisine cevirir
    private static int[] karakterleriSayiyaCevir(String numara) {
        int uzunluk = numara.length();
        int[] rakamlar = new int[uzunluk];

        for (int pozisyon = 0; pozisyon < uzunluk; pozisyon++) {
            char karakter = numara.charAt(pozisyon);
            rakamlar[pozisyon] = karakter - '0';
        }

        diziyiGoster(rakamlar);
        return rakamlar;
    }

    // Luhn algoritmasi geregi sagdan itibaren her ikinci haneyi ikiye katlar
    private static int[] ikinciHaneleriKatla(int[] rakamlar) {
        int pozisyon = rakamlar.length - 2;
        while (pozisyon >= 0) {
            rakamlar[pozisyon] = rakamlar[pozisyon] * 2;
            pozisyon -= 2;
        }

        diziyiGoster(rakamlar);
        return rakamlar;
    }

    // Dizideki tum degerlerin toplamini verir
    private static int hepsiniTopla(int[] rakamlar) {
        int genelToplam = 0;
        for (int deger : rakamlar) {
            genelToplam += deger;
        }
        System.out.println("Dizi elemanlar toplami: " + genelToplam);
        return genelToplam;
    }

    // Luhn kontrolune gore kart numarasinin gecerliligini belirler
    private static boolean luhnKontroluGecerliMi(String numara) {
        int[] rakamlar = karakterleriSayiyaCevir(numara);
        rakamlar = ikinciHaneleriKatla(rakamlar);

        for (int i = 0; i < rakamlar.length; i++) {
            rakamlar[i] = basamakToplamiHesapla(rakamlar[i]);
        }

        int nihaiToplam = hepsiniTopla(rakamlar);
        return (nihaiToplam % 10) == 0;
    }

    // Ornek kart numaralari uzerinde toplu test calistirir
    private static void ornekleriTestEt() {
        String[] ornekKartlar = {
            "4532015112830366", "6011514433546201", "378282246310005",
            "1234567890123456", "1111222333334444"
        };

        for (String kart : ornekKartlar) {
            String durum = luhnKontroluGecerliMi(kart) ? "Gecerli" : "Gecersiz";
            System.out.println(kart + " -> " + durum);
            System.out.println();
        }
    }

    // Kullanicidan kart numarasi ister, format dogrulamasi yapar ve sonucu bildirir
    private static void kullanicidanKartAl() {
        Scanner tarayici = new Scanner(System.in);
        System.out.println("\nKart numaranizi giriniz:");
        String girilenNumara = tarayici.next();

        while (!girilenNumara.matches("\\d{13,19}")) {
            System.out.println("Lutfen gecerli bir kart numarasi giriniz (13-19 hane):");
            girilenNumara = tarayici.next();
        }
        tarayici.close();

        if (luhnKontroluGecerliMi(girilenNumara)) {
            System.out.println("Kart numarasi dogru.");
        } else {
            System.out.println("Kart numarasi yanlis.");
        }
    }

    public static void main(String[] args) {
        ornekleriTestEt();
        kullanicidanKartAl();
    }
}

