public class OffRamp {
    public static void main(String[] args) {
        int[] output = {0, 0, 0, 0, 0, 0};
        int counter = 0;

        for (int idx = 0; idx < 4; idx++) {
            output[0] = idx;
        }
        for (int idx = 0; idx < 4; idx++) {
            output[1] = idx;
        }

        counter = 0;
        while(counter++ < 3) output[2] = counter;
        counter = 0;
        while(++counter < 3) output[3] = counter;

        counter = 0;
        do {
            output[4] = counter;
        } while (counter++ < 7);
        counter = 0;
        do {
            output[5] = counter;
        } while (++counter < 7);

        for(int val: output) {System.out.print(val + " ");}
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Smith–Waterman algorithm for local sequence alignment.
 * Finds the highest scoring local alignment between substrings of two sequences.
 *
 * Time Complexity: O(n * m)
 * Space Complexity: O(n * m)
 */
public final class SmithWaterman {

    private SmithWaterman() {
        // Utility Class
    }

    /**
     * Computes the Smith–Waterman local alignment score between two strings.
     *
     * @param s1 first string
     * @param s2 second string
     * @param matchScore score for a match
     * @param mismatchPenalty penalty for mismatch (negative)
     * @param gapPenalty penalty for insertion/deletion (negative)
     * @return the maximum local alignment score
     */
    public static int align(String s1, String s2, int matchScore, int mismatchPenalty, int gapPenalty) {
        if (s1 == null || s2 == null) {
            throw new IllegalArgumentException("Input strings must not be null.");
        }

        int n = s1.length();
        int m = s2.length();
        int maxScore = 0;

        int[][] dp = new int[n + 1][m + 1];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                int matchOrMismatch = (s1.charAt(i - 1) == s2.charAt(j - 1)) ? matchScore : mismatchPenalty;

                dp[i][j] = Math.max(0,
                    Math.max(Math.max(dp[i - 1][j - 1] + matchOrMismatch, // match/mismatch
                                 dp[i - 1][j] + gapPenalty // deletion
                                 ),
                        dp[i][j - 1] + gapPenalty // insertion
                        ));

                if (dp[i][j] > maxScore) {
                    maxScore = dp[i][j];
                }
            }
        }

        return maxScore;
    }
}

package com.thealgorithms.maths;

/*
 * Java program for Binomial Coefficients
 * Binomial Coefficients: A binomial coefficient C(n,k) gives number ways
 * in which k objects can be chosen from n objects.
 * Wikipedia: https://en.wikipedia.org/wiki/Binomial_coefficient
 *
 * Author: Akshay Dubey (https://github.com/itsAkshayDubey)
 *
 * */

public final class BinomialCoefficient {
    private BinomialCoefficient() {
    }

    /**
     * This method returns the number of ways in which k objects can be chosen from n objects
     *
     * @param totalObjects    Total number of objects
     * @param numberOfObjects Number of objects to be chosen from total_objects
     * @return number of ways in which no_of_objects objects can be chosen from total_objects
     *     objects
     */

    public static int binomialCoefficient(int totalObjects, int numberOfObjects) {
        // Base Case
        if (numberOfObjects > totalObjects) {
            return 0;
        }

        // Base Case
        if (numberOfObjects == 0 || numberOfObjects == totalObjects) {
            return 1;
        }

        // Recursive Call
        return (binomialCoefficient(totalObjects - 1, numberOfObjects - 1) + binomialCoefficient(totalObjects - 1, numberOfObjects));
    }
}

