public class BinarySearchDemo {
    /**
     * Performs binary search on a sorted array.
     * @param arr sorted array to search
     * @param target value to find
     * @return index of target, or -1 if not found
     */
    public static int binarySearch(int[] arr, int target) {
        int left = 0;
        int right = arr.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] == target) {
                return mid;
            } else if (arr[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] data = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
        System.out.println("Index of 23: " + binarySearch(data, 23));
        System.out.println("Index of 40: " + binarySearch(data, 40));
    }
}

/**
 * This class provides a method to compute the remainder
 * of a number when divided by a power of two (2^n)
 * without using division or modulo operations.
 *
 * @author Hardvan
 */
public final class ModuloPowerOfTwo {
private ModuloPowerOfTwo() {
}

/**
 * Computes the remainder of a given integer when divided by 2^n.
 *
 * @param inputValue the input number
 * @param exponentValue the exponent (power of two)
 * @return the remainder of inputValue divided by 2^exponentValue
 */
public static int moduloPowerOfTwo(int inputValue, int exponentValue) {
if (exponentValue <= 0) {
throw new IllegalArgumentException("The exponent must be positive");
}
return inputValue & ((1 << exponentValue) - 1);
}
}

package com.thealgorithms.dynamicprogramming;

/**
 * Provides functionality to solve the Palindrome Partitioning II problem, which involves finding
 * the minimum number of partitions needed to divide a given string into palindromic substrings.
 *
 * <p>
 * The problem is solved using dynamic programming. The approach involves checking all possible
 * substrings and determining whether they are palindromes. The minimum number of cuts required
 * for palindrome partitioning is computed in a bottom-up manner.
 * </p>
 *
 * <p>
 * Example:
 * <ul>
 *     <li>Input: "nitik" => Output: 2 (Partitioning: "n | iti | k")</li>
 *     <li>Input: "ababbbabbababa" => Output: 3 (Partitioning: "aba | b | bbabb | ababa")</li>
 * </ul>
 * </p>
 *
 * @see <a href="https://leetcode.com/problems/palindrome-partitioning-ii/">Palindrome Partitioning II</a>
 * @see <a href="https://www.geeksforgeeks.org/palindrome-partitioning-dp-17/">Palindrome Partitioning (GeeksforGeeks)</a>
 */
public final class PalindromicPartitioning {
    private PalindromicPartitioning() {
    }

    public static int minimalPartitions(String word) {
        int len = word.length();
        /* We Make two arrays to create a bottom-up solution.
           minCuts[i] = Minimum number of cuts needed for palindrome partitioning of substring
           word[0..i] isPalindrome[i][j] = true if substring str[i..j] is palindrome Base Condition:
           C[i] is 0 if P[0][i]= true
         */
        int[] minCuts = new int[len];
        boolean[][] isPalindrome = new boolean[len][len];

        int i;
        int j;
        int subLen; // different looping variables

        // Every substring of length 1 is a palindrome
        for (i = 0; i < len; i++) {
            isPalindrome[i][i] = true;
        }

        /* subLen is substring length. Build the solution in bottom up manner by considering all
         * substrings of length starting from 2 to n. */
        for (subLen = 2; subLen <= len; subLen++) {
            // For substring of length subLen, set different possible starting indexes
            for (i = 0; i < len - subLen + 1; i++) {
                j = i + subLen - 1; // Ending index
                // If subLen is 2, then we just need to
                // compare two characters. Else need to
                // check two corner characters and value
                // of P[i+1][j-1]
                if (subLen == 2) {
                    isPalindrome[i][j] = (word.charAt(i) == word.charAt(j));
                } else {
                    isPalindrome[i][j] = (word.charAt(i) == word.charAt(j)) && isPalindrome[i + 1][j - 1];
                }
            }
        }

        // We find the minimum for each index
        for (i = 0; i < len; i++) {
            if (isPalindrome[0][i]) {
                minCuts[i] = 0;
            } else {
                minCuts[i] = Integer.MAX_VALUE;
                for (j = 0; j < i; j++) {
                    if (isPalindrome[j + 1][i] && 1 + minCuts[j] < minCuts[i]) {
                        minCuts[i] = 1 + minCuts[j];
                    }
                }
            }
        }

        // Return the min cut value for complete
        // string. i.e., str[0..n-1]
        return minCuts[len - 1];
    }
}

public class BasamakDegeri {

	public static void main(String[] args) {

		tumKombinasyonlariListele();

		System.out.println("Basamak Sayisi: " + basamakAdediniHesapla(345987));

		System.out.println("Rakamlar Toplami: " + digitToplamiHesapla(24653));

	}

	// Onlar ve birler basamagi olasi tum kombinasyonlarini ekrana basar
	public static void tumKombinasyonlariListele() {
		int onlarHanesi = 0;
		// Onlar hanesi 0'dan 4'e kadar donuyor
		while (onlarHanesi <= 4) {
			int birlerHanesi = 1;
			// Birler hanesi 1'den 9'a kadar donuyor
			while (birlerHanesi <= 9) {
				int birlesikSayi = onlarHanesi * 10 + birlerHanesi;
				System.out.println("Onlar basamagi: " + onlarHanesi + ", Birler basamagi: " + birlerHanesi + " --> " + birlesikSayi);
				birlerHanesi++;
			}
			onlarHanesi++;
		}
	}

	// Bir sayinin butun rakamlarinin toplamini dondurur
	public static int digitToplamiHesapla(int deger) {
		int toplam = 0;
		// Rakamlar tek tek ayristirilip toplama eklenir
		for (int kalan = deger; kalan > 0; kalan /= 10) {
			toplam += kalan % 10;
		}
		return toplam;
	}

	// Bir sayinin kac basamaktan olustugunu dondurur
	public static int basamakAdediniHesapla(int deger) {
		int adet = 0;
		// Sayi sifira dusene kadar her adimda bir basamak sayilir
		for (int kalan = deger; kalan > 0; kalan /= 10) {
			adet++;
		}
		return adet;
	}
}

/**
 * A utility class for performing single-bit operations on integers.
 * These operations include flipping, setting, clearing, and getting
 * individual bits at specified positions.
 *
 * Bit positions are zero-indexed (i.e., the least significant bit is at position 0).
 * These methods leverage bitwise operations for optimal performance.
 *
 * Examples:
 * - `flipBit(3, 1)` flips the bit at index 1 in binary `11` (result: `1`).
 * - `setBit(4, 0)` sets the bit at index 0 in `100` (result: `101` or 5).
 * - `clearBit(7, 1)` clears the bit at index 1 in `111` (result: `101` or 5).
 * - `getBit(6, 0)` checks if the least significant bit is set (result: `0`).
 *
 * Time Complexity: O(1) for all operations.
 *
 * Author: lukasb1b (https://github.com/lukasb1b)
 */
public final class SingleBitOperations {
private SingleBitOperations() {
}

/**
 * Flips (toggles) the bit at the specified position.
 *
 * @param inputNumber the input number
 * @param bitPosition the position of the bit to flip (0-indexed)
 * @return the new number after flipping the specified bit
 */
public static int flipBit(final int inputNumber, final int bitPosition) {
return inputNumber ^ (1 << bitPosition);
}

/**
 * Sets the bit at the specified position to 1.
 *
 * @param inputNumber the input number
 * @param bitPosition the position of the bit to set (0-indexed)
 * @return the new number after setting the specified bit to 1
 */
public static int setBit(final int inputNumber, final int bitPosition) {
return inputNumber | (1 << bitPosition);
}

/**
 * Clears the bit at the specified position (sets it to 0).
 *
 * @param inputNumber the input number
 * @param bitPosition the position of the bit to clear (0-indexed)
 * @return the new number after clearing the specified bit
 */
public static int clearBit(final int inputNumber, final int bitPosition) {
return inputNumber & ~(1 << bitPosition);
}

/**
 * Gets the bit value (0 or 1) at the specified position.
 *
 * @param inputNumber the input number
 * @param bitPosition the position of the bit to retrieve (0-indexed)
 * @return 1 if the bit is set, 0 otherwise
 */
public static int getBit(final int inputNumber, final int bitPosition) {
return (inputNumber >> bitPosition) & 1;
}
}

