package com.thealgorithms.datastructures.buffers;

import java.util.concurrent.atomic.AtomicInteger;

/**
 * The {@code CircularBuffer} class implements a generic circular (or ring) buffer.
 * A circular buffer is a fixed-size data structure that operates in a FIFO (First In, First Out) manner.
 * The buffer allows you to overwrite old data when the buffer is full and efficiently use limited memory.
 * When the buffer is full, adding a new item will overwrite the oldest data.
 *
 * @param <DataType> The type of elements stored in the circular buffer.
 */
@SuppressWarnings("unchecked")
public class CircularBuffer<DataType> {
private final DataType[] storageArray;
private final CircularPointer writePosition;
private final CircularPointer readPosition;
private final AtomicInteger currentSize = new AtomicInteger(0);

/**
 * Constructor to initialize the circular buffer with a specified size.
 *
 * @param bufferCapacity The size of the circular buffer.
 * @throws IllegalArgumentException if the bufferCapacity is zero or negative.
 */
public CircularBuffer(int bufferCapacity) {
if (bufferCapacity <= 0) {
throw new IllegalArgumentException("Buffer size must be positive");
}
this.storageArray = (DataType[]) new Object[bufferCapacity];
this.writePosition = new CircularPointer(0, bufferCapacity);
this.readPosition = new CircularPointer(0, bufferCapacity);
}

/**
 * Checks if the circular buffer is empty.
 * This method is based on the current size of the buffer.
 *
 * @return {@code true} if the buffer is empty, {@code false} otherwise.
 */
public boolean isEmpty() {
return currentSize.get() == 0;
}

/**
 * Checks if the circular buffer is full.
 * The buffer is considered full when its size equals its capacity.
 *
 * @return {@code true} if the buffer is full, {@code false} otherwise.
 */
public boolean isFull() {
return currentSize.get() == storageArray.length;
}

/**
 * Retrieves and removes the item at the front of the buffer (FIFO).
 * This operation will move the {@code readPosition} forward.
 *
 * @return The item at the front of the buffer, or {@code null} if the buffer is empty.
 */
public DataType get() {
if (isEmpty()) {
return null;
}
DataType retrievedItem = storageArray[readPosition.getAndIncrement()];
currentSize.decrementAndGet();
return retrievedItem;
}

/**
 * Adds an item to the end of the buffer (FIFO).
 * If the buffer is full, this operation will overwrite the oldest data.
 *
 * @param inputItem The item to be added.
 * @throws IllegalArgumentException if the inputItem is null.
 * @return {@code true} if the item was successfully added, {@code false} if the buffer was full and the item overwrote existing data.
 */
public boolean put(DataType inputItem) {
if (inputItem == null) {
throw new IllegalArgumentException("Null items are not allowed");
}
boolean wasPreviouslyEmpty = isEmpty();
if (isFull()) {
readPosition.getAndIncrement();
} else {
currentSize.incrementAndGet();
}
storageArray[writePosition.getAndIncrement()] = inputItem;
return wasPreviouslyEmpty;
}

/**
 * The {@code CircularPointer} class is a helper class used to track the current index (pointer)
 * in the circular buffer.
 * The max value represents the capacity of the buffer.
 * The `CircularPointer` class ensures that the pointer automatically wraps around to 0
 * when it reaches the maximum index.
 * This is achieved in the `getAndIncrement` method, where the pointer
 * is incremented and then taken modulo the maximum value (`max`).
 * This operation ensures that the pointer always stays within the bounds of the buffer.
 */
private static class CircularPointer {
private int currentIndex;
private final int upperLimit;

/**
 * Constructor to initialize the circular pointer.
 *
 * @param startIndex The initial position of the pointer.
 * @param maxBoundary The maximum size (capacity) of the circular buffer.
 */
CircularPointer(int startIndex, int maxBoundary) {
this.currentIndex = startIndex;
this.upperLimit = maxBoundary;
}

/**
 * Increments the pointer by 1 and wraps it around to 0 if it reaches the maximum value.
 * This ensures the pointer always stays within the buffer's bounds.
 *
 * @return The current pointer value before incrementing.
 */
public int getAndIncrement() {
int previousValue = currentIndex;
currentIndex = (currentIndex + 1) % upperLimit;
return previousValue;
}
}
}

package ifcondition;

public class SayiOkuma {

	// Basamak degerlerine karsilik gelen Turkce kelimeler, index sifirdan basladigi icin ilk eleman kullanilmaz
	private static final String[] BIRLER_KELIME = {
			"", "bir", "iki", "uc", "dort", "bes", "alti", "yedi", "sekiz", "dokuz"
	};

	private static final String[] ONLAR_KELIME = {
			"", "on", "yirmi", "otuz", "kirk", "elli", "altmis", "yetmis", "seksen", "doksan"
	};

	private static final String[] YUZLER_KELIME = {
			"", "yuz", "iki yuz", "uc yuz", "dort yuz", "bes yuz", "alti yuz", "yedi yuz", "sekiz yuz", "dokuz yuz"
	};

	private static final String[] BINLER_KELIME = {
			"", "bin", "iki bin", "uc bin", "dort bin", "bes bin", "alti bin", "yedi bin", "sekiz bin", "dokuz bin"
	};

	public static void main(String[] args) {

		System.out.println(sayiyiYaziyaCevir(1234));

		System.out.println(sayiyiYaziyaCevir(7248));

		System.out.println(sayiyiYaziyaCevir(297));

		System.out.println(sayiyiYaziyaCevir(505));

		System.out.println(sayiyiYaziyaCevir(300));
	}

	// 0-9999 arasindaki bir sayiyi Turkce okunusuna cevirir
	public static String sayiyiYaziyaCevir(int deger) {
		if (deger == 0) {
			return "sifir";
		}

		int binBasamagi = deger / 1000;
		int yuzBasamagi = (deger / 100) % 10;
		int onBasamagi = (deger / 10) % 10;
		int birBasamagi = deger % 10;

		StringBuilder metin = new StringBuilder();

		metin.append(BINLER_KELIME[binBasamagi]);
		if (binBasamagi > 0) {
			metin.append(" ");
		}

		metin.append(YUZLER_KELIME[yuzBasamagi]);
		if (yuzBasamagi > 0) {
			metin.append(" ");
		}

		metin.append(ONLAR_KELIME[onBasamagi]);
		if (onBasamagi > 0) {
			metin.append(" ");
		}

		metin.append(BIRLER_KELIME[birBasamagi]);

		return metin.toString();
	}
}

/**
 * This code recursively validates whether given Binary Search Tree (BST) is balanced or not.
 * Trees with only distinct values are supported.
 * Key points:
 * 1. According to the definition of a BST, each node in a tree must be in range [min, max],
 *    where 'min' and 'max' values represent the child nodes (left, right).
 * 2. The smallest possible node value is Integer.MIN_VALUE, the biggest - Integer.MAX_VALUE.
 */
public final class CheckBinaryTreeIsValidBST {
    private CheckBinaryTreeIsValidBST() {
    }
    public static boolean isBST(BinaryTree.Node root) {
        return isBSTUtil(root, Integer.MIN_VALUE, Integer.MAX_VALUE);
    }

    private static boolean isBSTUtil(BinaryTree.Node node, int min, int max) {
        // empty tree is a BST
        if (node == null) {
            return true;
        }

        if (node.data < min || node.data > max) {
            return false;
        }

        return (isBSTUtil(node.left, min, node.data - 1) && isBSTUtil(node.right, node.data + 1, max));
    }
}

package switchcase;
import java.util.Scanner;

public class MevsimAdlari {

	public static void main(String[] args) {

		Scanner girisAraci = new Scanner(System.in);

		System.out.print("Bir ay girin (1-12): ");
		int secilenAy = girisAraci.nextInt();

		String mevsimAdi = ayaGoreMevsimBul(secilenAy);

		System.out.println("Girdiginiz ayin mevsimi: " + mevsimAdi);

		girisAraci.close();
	}

	// Verilen ay numarasina karsilik gelen mevsim adini switch yapisi ile bulur
	private static String ayaGoreMevsimBul(int ay) {
		String mevsim;
		switch (ay) {
			case 12:
			case 1:
			case 2:
				mevsim = "Kis";
				break;
			case 3:
			case 4:
			case 5:
				mevsim = "ilkbahar";
				break;
			case 6:
			case 7:
			case 8:
				mevsim = "Yaz";
				break;
			case 9:
			case 10:
			case 11:
				mevsim = "Sonbahar";
				break;
			default:
				mevsim = "Gecersiz ay";
		}
		return mevsim;
	}
}

public class TodoListApp {
    private static final List<String> tasks = new ArrayList<>();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        boolean running = true;

        while (running) {
            System.out.println("\n1. Add task\n2. Show tasks\n3. Remove task\n4. Exit");
            System.out.print("Choose: ");
            int choice = scanner.nextInt();
            scanner.nextLine();

            switch (choice) {
                case 1:
                    System.out.print("Task description: ");
                    tasks.add(scanner.nextLine());
                    System.out.println("Task added.");
                    break;
                case 2:
                    if (tasks.isEmpty()) {
                        System.out.println("No tasks yet.");
                    } else {
                        for (int i = 0; i < tasks.size(); i++) {
                            System.out.println((i + 1) + ". " + tasks.get(i));
                        }
                    }
                    break;
                case 3:
                    System.out.print("Task number to remove: ");
                    int index = scanner.nextInt() - 1;
                    if (index >= 0 && index < tasks.size()) {
                        System.out.println("Removed: " + tasks.remove(index));
                    } else {
                        System.out.println("Invalid task number.");
                    }
                    break;
                case 4:
                    running = false;
                    break;
                default:
                    System.out.println("Unknown option.");
            }
        }
        scanner.close();
    }
}

public class PalindromKontrol {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        // Kullanicidan bir kelime veya cumle girmesini iste
        System.out.print("Bir kelime veya cumle girin: ");
        String metin = scanner.nextLine();

        scanner.close(); // Scanner'i kapat

        // Metni temizleme: Harf olmayan karakterleri kaldir ve kucuk harfe donustur
        metin = metin.replaceAll("[^a-zA-Z]", "").toLowerCase();

        // Metni ters cevirme islemini bir dongu ile yap
        String tersMetin = "";
        for (int i = metin.length() - 1; i >= 0; i--) {
            tersMetin += metin.charAt(i); // Metindeki karakterleri sondan basa dogru ekle
        }

        // Palindrom kontrolu
        if (metin.equals(tersMetin)) {
            // Eger metin ile tersMetin ayniysa palindromdur
            System.out.println("Girdi bir palindromdur.");
        } else {
            // Eger metin ile tersMetin farkliysa palindrom degildir
            System.out.println("Girdi bir palindrom degildir.");
        }
    }
}

public class DosyaOkumaYazma {

    public static void main(String[] args) {
        String sourceName = "girdi.txt";
        String targetName = "cikti.txt";

        try {
            byte[] contents = readAllBytes(sourceName);
            writeAllBytes(targetName, contents);

            System.out.println("Dosya basariyla '" + targetName + "' dosyasina kopyalandi!");

        } catch (IOException ioEx) {
            System.out.println("Dosya isleminde bir hata olustu: " + ioEx.getMessage());
        } catch (Exception unexpected) {
            System.out.println("Beklenmeyen bir hata olustu: " + unexpected.getMessage());
        }
    }

    /**
     * Reads the full contents of a file into a byte array.
     * @param fileName file to read
     * @return raw bytes read from the file
     * @throws IOException if the file is missing or unreadable
     */
    public static byte[] readAllBytes(String fileName) throws IOException {
        File source = new File(fileName);

        if (!source.exists()) {
            throw new IOException("Giris dosyasi bulunamadi: " + fileName);
        }

        FileInputStream in = new FileInputStream(source);
        byte[] buffer = new byte[(int) source.length()];

        int bytesRead = in.read(buffer);
        System.out.println("Okunan byte sayisi: " + bytesRead);

        in.close();
        return buffer;
    }

    /**
     * Writes a byte array out to a file, overwriting it if present.
     * @param fileName file to write
     * @param data bytes to write
     * @throws IOException if the file can't be created or written
     */
    public static void writeAllBytes(String fileName, byte[] data) throws IOException {
        File destination = new File(fileName);

        if (destination.exists()) {
            System.out.println("Uyari: Cikis dosyasi zaten mevcut, uzerine yaziliyor.");
        }

        FileOutputStream out = new FileOutputStream(destination);
        out.write(data);
        System.out.println("Cikis dosyasina yazma islemi tamamlandi.");

        out.close();
    }
}

/**
 * A generic implementation of a hash map using an array list of linked lists for collision resolution.
 * This class allows storage of key-value pairs with average-case constant time complexity for insertion,
 * deletion, and retrieval operations.
 *
 * <p>
 * The hash map uses separate chaining to handle collisions. Each bucket in the hash map is represented
 * by a linked list that holds nodes containing key-value pairs. When multiple keys hash to the same index,
 * they are stored in the same linked list.
 * </p>
 *
 * <p>
 * The hash map automatically resizes itself when the load factor exceeds 0.5. The load factor is defined
 * as the ratio of the number of entries to the number of buckets. When resizing occurs, all existing entries
 * are rehashed and inserted into the new buckets.
 * </p>
 *
 * @param <K> the type of keys maintained by this hash map
 * @param <V> the type of mapped values
 */
public class GenericHashMapUsingArrayList<K, V> {

    private ArrayList<LinkedList<Node>> buckets; // Array list of buckets (linked lists)
    private int size; // Number of key-value pairs in the hash map

    /**
     * Constructs a new empty hash map with an initial capacity of 10 buckets.
     */
    public GenericHashMapUsingArrayList() {
        buckets = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            buckets.add(new LinkedList<>());
        }
        size = 0;
    }

    /**
     * Associates the specified value with the specified key in this map.
     * If the map previously contained a mapping for the key, the old value is replaced.
     *
     * @param key the key with which the specified value is to be associated
     * @param value the value to be associated with the specified key
     */
    public void put(K key, V value) {
        int hash = Math.abs(key.hashCode() % buckets.size());
        LinkedList<Node> nodes = buckets.get(hash);

        for (Node node : nodes) {
            if (node.key.equals(key)) {
                node.val = value;
                return;
            }
        }

        nodes.add(new Node(key, value));
        size++;

        // Load factor threshold for resizing
        float loadFactorThreshold = 0.5f;
        if ((float) size / buckets.size() > loadFactorThreshold) {
            reHash();
        }
    }

    /**
     * Resizes the hash map by doubling the number of buckets and rehashing existing entries.
     */
    private void reHash() {
        ArrayList<LinkedList<Node>> oldBuckets = buckets;
        buckets = new ArrayList<>();
        size = 0;
        for (int i = 0; i < oldBuckets.size() * 2; i++) {
            buckets.add(new LinkedList<>());
        }
        for (LinkedList<Node> nodes : oldBuckets) {
            for (Node node : nodes) {
                put(node.key, node.val);
            }
        }
    }

    /**
     * Returns the value to which the specified key is mapped, or null if this map contains no mapping for the key.
     *
     * @param key the key whose associated value is to be returned
     * @return the value associated with the specified key, or null if no mapping exists
     */
    public V get(K key) {
        int hash = Math.abs(key.hashCode() % buckets.size());
        LinkedList<Node> nodes = buckets.get(hash);
        for (Node node : nodes) {
            if (node.key.equals(key)) {
                return node.val;
            }
        }
        return null;
    }

    /**
     * Removes the mapping for the specified key from this map if present.
     *
     * @param key the key whose mapping is to be removed from the map
     */
    public void remove(K key) {
        int hash = Math.abs(key.hashCode() % buckets.size());
        LinkedList<Node> nodes = buckets.get(hash);

        Node target = null;
        for (Node node : nodes) {
            if (node.key.equals(key)) {
                target = node;
                break;
            }
        }
        if (target != null) {
            nodes.remove(target);
            size--;
        }
    }

    /**
     * Returns true if this map contains a mapping for the specified key.
     *
     * @param key the key whose presence in this map is to be tested
     * @return true if this map contains a mapping for the specified key
     */
    public boolean containsKey(K key) {
        return get(key) != null;
    }

    /**
     * Returns the number of key-value pairs in this map.
     *
     * @return the number of key-value pairs
     */
    public int size() {
        return this.size;
    }

    /**
     * Returns a string representation of the map, containing all key-value pairs.
     *
     * @return a string representation of the map
     */
    @Override
    public String toString() {
        StringBuilder builder = new StringBuilder();
        builder.append("{");
        for (LinkedList<Node> nodes : buckets) {
            for (Node node : nodes) {
                builder.append(node.key);
                builder.append(" : ");
                builder.append(node.val);
                builder.append(", ");
            }
        }
        // Remove trailing comma and space if there are any elements
        if (builder.length() > 1) {
            builder.setLength(builder.length() - 2);
        }
        builder.append("}");
        return builder.toString();
    }

    /**
     * A private inner class representing a key-value pair (node) in the hash map.
     */
    private class Node {
        K key;
        V val;

        /**
         * Constructs a new Node with the specified key and value.
         *
         * @param key the key of the key-value pair
         * @param val the value of the key-value pair
         */
        Node(K key, V val) {
            this.key = key;
            this.val = val;
        }
    }
}

/**
 * This class provides a method to detect if two integers
 * differ by exactly one bit flip.
 *
 * Example:
 * 1 (0001) and 2 (0010) differ by exactly one bit flip.
 * 7 (0111) and 3 (0011) differ by exactly one bit flip.
 *
 * @author Hardvan
 */
public final class OneBitDifference {
    private OneBitDifference() {
    }

    /**
     * Checks if two integers differ by exactly one bit.
     *
     * @param x the first integer
     * @param y the second integer
     * @return true if x and y differ by exactly one bit, false otherwise
     */
    public static boolean differByOneBit(int x, int y) {
        if (x == y) {
            return false;
        }

        int xor = x ^ y;
        return (xor & (xor - 1)) == 0;
    }
}

