/*
 * Base type for every geometric figure used in this small demo.
 * Concrete figures must supply their own area/perimeter formulas,
 * while the drawing behaviour has a generic default that can be
 * swapped out by subclasses if they need something fancier.
 */
abstract class Sekil {

    private String etiket;

    protected Sekil(String etiket) {
        this.etiket = etiket;
    }

    public String getIsim() {
        return etiket;
    }

    public void setIsim(String etiket) {
        this.etiket = etiket;
    }

    // Every figure must know how to compute its own surface.
    public abstract double alanHesapla();

    // Every figure must know how to compute its own outline length.
    public abstract double cevreHesapla();

    // Default rendering routine; subclasses may replace it.
    public void ciz() {
        System.out.println(etiket + " ciziliyor.");
    }

    public static void main(String[] args) {
        Sekil[] figurler = new Sekil[3];
        figurler[0] = new Kare(5);
        figurler[1] = new Dikdortgen(4, 6);
        figurler[2] = new Cember(7);

        for (Sekil f : figurler) {
            System.out.println(f.getIsim() + " alani: " + f.alanHesapla());
            System.out.println(f.getIsim() + " cevresi: " + f.cevreHesapla());
            f.ciz();
        }
    }
}

package overriding;

// Kisi sinifi
public class Kisi {

    private String ad;
    private int yas;

    // Kisi yapilandirici metodu
    public Kisi(String ad, int yas) {
        this.ad = ad;
        this.yas = yas;
    }

    // Equals metodu ozellestirilmistir
    @Override
    public boolean equals(Object obj) {
        // Ayni referansa sahipse, esittir
        if (this == obj) return true;

        // Null kontrolu yapilir ve nesne turu karsilastirilir
        if (obj == null || getClass() != obj.getClass()) return false;

        // Kisi nesnelerinin alanlari karsilastirilir
        Kisi kisi = (Kisi) obj;
        return yas == kisi.yas && ad.equals(kisi.ad);
    }

    // Ad alani icin getter metodu
    public String getAd() {
        return ad;
    }

    // Yas alani icin getter metodu
    public int getYas() {
        return yas;
    }

    // toString metodu
    @Override
    public String toString() {
        return "Kisi[Ad=" + ad + ", Yas=" + yas + "]";
    }

    public static void main(String[] args) {
        // Iki farkli Kisi nesnesi olusturulur
        Kisi kisi1 = new Kisi("Ali", 25);
        Kisi kisi2 = new Kisi("Ali", 25);

        // == operatoru ile esitlik kontrolu yapilir
        if (kisi1 == kisi2) {
            System.out.println("Iki kisi nesnesi esittir.");
        } else {
            System.out.println("Iki kisi nesnesi esit degildir.");
        }

        // equals metodu kullanilarak esitlik kontrolu yapilir
        if (kisi1.equals(kisi2)) {
            System.out.println("Iki kisi nesnesi esittir.");
        } else {
            System.out.println("Iki kisi nesnesi esit degildir.");
        }

        // Kisi nesnesinin bilgileri yazdirilir
        System.out.println(kisi1.toString());
    }
}

/**
 * This class provides a method to compute the Two's Complement of a given binary number.
 *
 * <p>In two's complement representation, a binary number's negative value is obtained
 * by taking the one's complement (inverting all bits) and then adding 1 to the result.
 * This method handles both small and large binary strings and ensures the output is
 * correct for all binary inputs, including edge cases like all zeroes and all ones.
 *
 * <p>For more information on Two's Complement:
 * @see <a href="https://en.wikipedia.org/wiki/Two%27s_complement">Wikipedia - Two's Complement</a>
 *
 * <p>Algorithm originally suggested by Jon von Neumann.
 *
 * @author Abhinay Verma (https://github.com/Monk-AbhinayVerma)
 */
public final class TwosComplement {
    private TwosComplement() {
    }

    /**
     * Computes the Two's Complement of the given binary string.
     * Steps:
     * 1. Compute the One's Complement (invert all bits).
     * 2. Add 1 to the One's Complement to get the Two's Complement.
     * 3. Iterate from the rightmost bit to the left, adding 1 and carrying over as needed.
     * 4. If a carry is still present after the leftmost bit, prepend '1' to handle overflow.
     *
     * @param binary The binary number as a string (only '0' and '1' characters allowed).
     * @return The two's complement of the input binary string as a new binary string.
     * @throws IllegalArgumentException If the input contains non-binary characters.
     */
    public static String twosComplement(String binary) {
        if (!binary.matches("[01]+")) {
            throw new IllegalArgumentException("Input must contain only '0' and '1'.");
        }

        StringBuilder onesComplement = new StringBuilder();
        for (char bit : binary.toCharArray()) {
            onesComplement.append(bit == '0' ? '1' : '0');
        }

        StringBuilder twosComplement = new StringBuilder(onesComplement);
        boolean carry = true;

        for (int i = onesComplement.length() - 1; i >= 0 && carry; i--) {
            if (onesComplement.charAt(i) == '1') {
                twosComplement.setCharAt(i, '0');
            } else {
                twosComplement.setCharAt(i, '1');
                carry = false;
            }
        }

        if (carry) {
            twosComplement.insert(0, '1');
        }

        return twosComplement.toString();
    }
}

