package com.thealgorithms.datastructures.graphs;

import java.util.Arrays;

/**
 * Java program to find a Hamiltonian Cycle in a graph.
 * A Hamiltonian Cycle is a cycle that visits every vertex exactly once
 * and returns to the starting vertex.
 *
 * <p>For more details, see the
 * <a href="https://en.wikipedia.org/wiki/Hamiltonian_path">Wikipedia article</a>.
 *
 * @author  <a href="https://github.com/itsAkshayDubey">Akshay Dubey</a>
 */
public class HamiltonianCycle {

private int totalVertices;
private int visitedCount;
private int[] cyclePath;
private int[][] adjacencyMatrix;

/**
 * Finds a Hamiltonian Cycle for the given graph.
 *
 * @param weightMatrix Adjacency matrix representing the graph G(V, E), where V is
 *              the set of vertices and E is the set of edges.
 * @return An array representing the Hamiltonian cycle if found, otherwise an
 *         array filled with -1 indicating no Hamiltonian cycle exists.
 */
public int[] findHamiltonianCycle(int[][] weightMatrix) {
if (weightMatrix.length == 1) {
return new int[] {0, 0};
}
this.totalVertices = weightMatrix.length;
this.cyclePath = new int[this.totalVertices + 1];
Arrays.fill(this.cyclePath, -1);
this.adjacencyMatrix = weightMatrix;
this.cyclePath[0] = 0;
this.visitedCount = 1;
if (!explorePath(0)) {
Arrays.fill(this.cyclePath, -1);
} else {
this.cyclePath[this.cyclePath.length - 1] = this.cyclePath[0];
}
return cyclePath;
}

/**
 * Recursively searches for a Hamiltonian cycle from the given vertex.
 *
 * @param currentVertex The current vertex from which to explore paths.
 * @return {@code true} if a Hamiltonian cycle is found, otherwise {@code false}.
 */
public boolean explorePath(int currentVertex) {
boolean connectsToStart = this.adjacencyMatrix[currentVertex][0] == 1 && this.visitedCount == this.totalVertices;
if (connectsToStart) {
return true;
}
if (this.visitedCount == this.totalVertices) {
return false;
}
for (int neighborVertex = 0; neighborVertex < this.totalVertices; neighborVertex++) {
if (this.adjacencyMatrix[currentVertex][neighborVertex] == 1) {
this.cyclePath[this.visitedCount++] = neighborVertex;
this.adjacencyMatrix[currentVertex][neighborVertex] = 0;
this.adjacencyMatrix[neighborVertex][currentVertex] = 0;
if (!isAlreadyUsed(neighborVertex)) {
return explorePath(neighborVertex);
}
this.adjacencyMatrix[currentVertex][neighborVertex] = 1;
this.adjacencyMatrix[neighborVertex][currentVertex] = 1;
this.cyclePath[--this.visitedCount] = -1;
}
}
return false;
}

/**
 * Checks if a vertex is already part of the current Hamiltonian path.
 *
 * @param targetVertex The vertex to check.
 * @return {@code true} if the vertex is already in the path, otherwise {@code false}.
 */
public boolean isAlreadyUsed(int targetVertex) {
for (int position = 0; position < visitedCount - 1; position++) {
if (cyclePath[position] == targetVertex) {
return true;
}
}
return false;
}
}
