/**
 * An implementation of the Lempel-Ziv 77 (LZ77) compression algorithm.
 * <p>
 * LZ77 is a lossless data compression algorithm that works by finding repeated
 * occurrences of data in a sliding window. It replaces subsequent occurrences
 * with references (offset, length) to the first occurrence within the window.
 * </p>
 * <p>
 * This implementation uses a simple sliding window and lookahead buffer approach.
 * Output format is a sequence of tuples (offset, length, next_character).
 * </p>
 * <p>
 * Time Complexity: O(n*W) in this naive implementation, where n is the input length
 * and W is the window size, due to the search for the longest match. More advanced
 * data structures (like suffix trees) can improve this.
 * </p>
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/LZ77_and_LZ78#LZ77">Wikipedia: LZ77</a></li>
 * </ul>
 * </p>
 */
public final class LZ77 {

private static final int DEFAULT_WINDOW_SIZE = 4096;
private static final int DEFAULT_LOOKAHEAD_BUFFER_SIZE = 16;
private static final char END_MARKER = '\u0000';

private LZ77() {
}

/**
 * Represents a token in the LZ77 compressed output.
 * Stores the offset back into the window, the length of the match,
 * and the next character after the match (or END_MARKER if at end).
 */
public record CompressionToken(int distanceOffset, int matchLength, char nextCharacter) {
}

/**
 * Compresses the input text using the LZ77 algorithm.
 *
 * @param sourceText The input string to compress. Must not be null.
 * @param windowSize The size of the sliding window (search buffer). Must be positive.
 * @param lookaheadSize The size of the lookahead buffer. Must be positive.
 * @return A list of {@link CompressionToken} objects representing the compressed data.
 * @throws IllegalArgumentException if windowSize or lookaheadSize are not positive.
 */
public static List<CompressionToken> compress(String sourceText, int windowSize, int lookaheadSize) {
if (sourceText == null) {
return new ArrayList<>();
}
if (windowSize <= 0 || lookaheadSize <= 0) {
throw new IllegalArgumentException("Window size and lookahead buffer size must be positive.");
}
List<CompressionToken> encodedTokens = new ArrayList<>();
int currentPos = 0;
while (currentPos < sourceText.length()) {
int bestOffset = 0;
int bestLen = 0;
int searchStart = Math.max(0, currentPos - windowSize);
int lookaheadEnd = Math.min(currentPos + lookaheadSize, sourceText.length());
for (int searchPos = searchStart; searchPos < currentPos; searchPos++) {
int currentLen = 0;
while (currentPos + currentLen < lookaheadEnd) {
int sourceIdx = searchPos + currentLen;
if (sourceIdx >= currentPos) {
int relativeOffset = currentPos - searchPos;
sourceIdx = searchPos + (currentLen % relativeOffset);
}
if (sourceText.charAt(sourceIdx) == sourceText.charAt(currentPos + currentLen)) {
currentLen++;
} else {
break;
}
}
if (currentLen > bestLen) {
bestLen = currentLen;
bestOffset = currentPos - searchPos;
}
}
char nextChar;
if (currentPos + bestLen < sourceText.length()) {
nextChar = sourceText.charAt(currentPos + bestLen);
} else {
nextChar = END_MARKER;
}
encodedTokens.add(new CompressionToken(bestOffset, bestLen, nextChar));
if (nextChar == END_MARKER) {
currentPos += bestLen;
} else {
currentPos += bestLen + 1;
}
}
return encodedTokens;
}

/**
 * Compresses the input text using the LZ77 algorithm with default buffer sizes.
 *
 * @param sourceText The input string to compress. Must not be null.
 * @return A list of {@link CompressionToken} objects representing the compressed data.
 */
public static List<CompressionToken> compress(String sourceText) {
return compress(sourceText, DEFAULT_WINDOW_SIZE, DEFAULT_LOOKAHEAD_BUFFER_SIZE);
}

/**
 * Decompresses a list of LZ77 tokens back into the original string.
 *
 * @param encodedData The list of {@link CompressionToken} objects. Must not be null.
 * @return The original, uncompressed string.
 */
public static String decompress(List<CompressionToken> encodedData) {
if (encodedData == null) {
return "";
}
StringBuilder decodedText = new StringBuilder();
for (CompressionToken currentToken : encodedData) {
if (currentToken.matchLength() > 0) {
int startIndex = decodedText.length() - currentToken.distanceOffset();
for (int copyPos = 0; copyPos < currentToken.matchLength(); copyPos++) {
decodedText.append(decodedText.charAt(startIndex + copyPos));
}
}
if (currentToken.nextCharacter() != END_MARKER) {
decodedText.append(currentToken.nextCharacter());
}
}
return decodedText.toString();
}
}

public class RastgeleKarakterYazdirma {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Random random = new Random();

        // Kullanicidan bir kelime girmesini iste
        System.out.println("Bir kelime giriniz:");
        String kelime = scanner.nextLine();

        // Eger kelime bossa hata mesaji yazdir ve programi sonlandir
        if (kelime.isEmpty()) {
            System.out.println("Kelime bos olamaz.");
            scanner.close();
            return;
        }

        // Kullanicidan kac karakter secilecegini sor
        System.out.println("Kac rastgele karakter secmek istersiniz?");
        int karakterSayisi = scanner.nextInt();

        scanner.close();

        // Eger kullanicidan girilen sayi gecersizse hata mesaji yazdir
        if (karakterSayisi <= 0 || karakterSayisi > kelime.length()) {
            System.out.println("Gecersiz karakter sayisi. 1 ile " + kelime.length() + " arasinda bir sayi giriniz.");
            return;
        }

        // Rastgele karakterleri sec ve ekrana yazdir
        System.out.println("Secilen rastgele karakterler:");
        boolean[] secilenindeksler = new boolean[kelime.length()];
        for (int i = 0; i < karakterSayisi; i++) {
            int indeks;
            // Ayni karakterin tekrar secilmemesi icin dongu
            do {
                indeks = random.nextInt(kelime.length());
            } while (secilenindeksler[indeks]);

            secilenindeksler[indeks] = true;
            System.out.println("indeks " + indeks + ": " + kelime.charAt(indeks));
        }

        // Kullaniciya istatistik goster
        System.out.println("\nKelimenin uzunlugu: " + kelime.length());
        System.out.println("Secilen karakter sayisi: " + karakterSayisi);
    }
}

/**
 * This class implements a hash table using linear probing to resolve collisions.
 * Linear probing is a collision resolution method where each slot in the hash table is checked in a sequential manner
 * until an empty slot is found.
 *
 * <p>
 * The class allows for storing key-value pairs, where both the key and value are generic types.
 * The key must be of a type that implements the Comparable interface to ensure that the keys can be compared for sorting.
 * </p>
 *
 * <p>
 * This implementation supports basic operations such as:
 * <ul>
 *     <li><b>put(Key key, Value value)</b>: Adds a key-value pair to the hash table. If the key already exists, its value is updated.</li>
 *     <li><b>get(Key key)</b>: Retrieves the value associated with the given key.</li>
 *     <li><b>delete(Key key)</b>: Removes the key and its associated value from the hash table.</li>
 *     <li><b>contains(Key key)</b>: Checks if the hash table contains a given key.</li>
 *     <li><b>size()</b>: Returns the number of key-value pairs in the hash table.</li>
 *     <li><b>keys()</b>: Returns an iterable collection of keys stored in the hash table.</li>
 * </ul>
 * </p>
 *
 * <p>
 * The internal size of the hash table is automatically resized when the load factor exceeds 0.5 or falls below 0.125,
 * ensuring efficient space utilization.
 * </p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Linear_probing">Linear Probing Hash Table</a>
 *
 * @param <Key> the type of keys maintained by this map
 * @param <Value> the type of mapped values
 */
@SuppressWarnings("rawtypes")
public class LinearProbingHashMap<Key extends Comparable<Key>, Value> extends Map<Key, Value> {
    private int hsize; // size of the hash table
    private Key[] keys; // array to store keys
    private Value[] values; // array to store values
    private int size; // number of elements in the hash table

    // Default constructor initializes the table with a default size of 16
    public LinearProbingHashMap() {
        this(16);
    }

    @SuppressWarnings("unchecked")
    // Constructor to initialize the hash table with a specified size
    public LinearProbingHashMap(int size) {
        this.hsize = size;
        keys = (Key[]) new Comparable[size];
        values = (Value[]) new Object[size];
    }

    @Override
    public boolean put(Key key, Value value) {
        if (key == null) {
            return false;
        }

        if (size > hsize / 2) {
            resize(2 * hsize);
        }

        int keyIndex = hash(key, hsize);
        for (; keys[keyIndex] != null; keyIndex = increment(keyIndex)) {
            if (key.equals(keys[keyIndex])) {
                values[keyIndex] = value;
                return true;
            }
        }

        keys[keyIndex] = key;
        values[keyIndex] = value;
        size++;
        return true;
    }

    @Override
    public Value get(Key key) {
        if (key == null) {
            return null;
        }

        for (int i = hash(key, hsize); keys[i] != null; i = increment(i)) {
            if (key.equals(keys[i])) {
                return values[i];
            }
        }

        return null;
    }

    @Override
    public boolean delete(Key key) {
        if (key == null || !contains(key)) {
            return false;
        }

        int i = hash(key, hsize);
        while (!key.equals(keys[i])) {
            i = increment(i);
        }

        keys[i] = null;
        values[i] = null;

        i = increment(i);
        while (keys[i] != null) {
            // Save the key and value for rehashing
            Key keyToRehash = keys[i];
            Value valToRehash = values[i];
            keys[i] = null;
            values[i] = null;
            size--;
            put(keyToRehash, valToRehash);
            i = increment(i);
        }

        size--;
        if (size > 0 && size <= hsize / 8) {
            resize(hsize / 2);
        }

        return true;
    }

    @Override
    public boolean contains(Key key) {
        return get(key) != null;
    }

    @Override
    int size() {
        return size;
    }

    @Override
    Iterable<Key> keys() {
        ArrayList<Key> listOfKeys = new ArrayList<>(size);
        for (int i = 0; i < hsize; i++) {
            if (keys[i] != null) {
                listOfKeys.add(keys[i]);
            }
        }

        listOfKeys.sort(Comparable::compareTo);
        return listOfKeys;
    }

    private int increment(int i) {
        return (i + 1) % hsize;
    }

    private void resize(int newSize) {
        LinearProbingHashMap<Key, Value> tmp = new LinearProbingHashMap<>(newSize);
        for (int i = 0; i < hsize; i++) {
            if (keys[i] != null) {
                tmp.put(keys[i], values[i]);
            }
        }

        this.keys = tmp.keys;
        this.values = tmp.values;
        this.hsize = newSize;
    }
}

