public class KlasorIslemleri {

	// Klasorleri listele
	public static File[] klasorleriListele(String yol) {
		return new File(yol).listFiles(File::isDirectory);
	}

	// Klasordeki dosyalari listele
	public static File[] klasordekiDosyalariListele(final File klasor) {
		return klasor.listFiles(File::isFile);
	}

	// Klasordeki tum dosyalari rekursif olarak listele
	public static List<File> tumDosyalariListele(String yol) {
		List<File> tumDosyalar = new ArrayList<>();
		File[] liste = new File(yol).listFiles();

		if (liste != null) { // Erisim hatasi durumunda liste null olabilir
			for (File dosya : liste) {
				if (dosya.isDirectory()) {
					tumDosyalar.addAll(tumDosyalariListele(dosya.getAbsolutePath()));
				} else {
					tumDosyalar.add(dosya.getAbsoluteFile());
				}
			}
		}
		return tumDosyalar;
	}

	// Belirli bir dosyayi sil
	public static boolean dosyaSil(String dosyaYolu) {
		File dosya = new File(dosyaYolu);
		return dosya.delete();
	}

	// Yeni bir klasor olustur
	public static boolean klasorOlustur(String yol) {
		File yeniKlasor = new File(yol);
		return yeniKlasor.mkdir();
	}

	// Bir klasoru ve icindekileri sil
	public static boolean klasoruSil(File klasor) {
		if (klasor.isDirectory()) {
			File[] icerik = klasor.listFiles();
			if (icerik != null) {
				for (File dosya : icerik) {
					klasoruSil(dosya); // Icindeki dosyalari/klasorleri sil
				}
			}
		}
		return klasor.delete(); // Bos klasoru sil
	}

	// Dosya bilgilerini yazdir
	public static void dosyaBilgileri(File dosya) {
		System.out.println("Dosya adi: " + dosya.getName());
		System.out.println("Tam yol: " + dosya.getAbsolutePath());
		System.out.println("Boyut (byte): " + dosya.length());
		System.out.println("Yazilabilir: " + dosya.canWrite());
		System.out.println("Okunabilir: " + dosya.canRead());
		System.out.println("Son degistirilme: " + dosya.lastModified());
	}

	public static void main(String[] args) {
		// Proje klasorunun yolunu al
		String projeKlasoru = System.getProperty("user.dir");
		System.out.println("Proje klasoru: " + projeKlasoru);

		// Proje klasoru altindaki klasorleri listele
		File[] klasorler = klasorleriListele(projeKlasoru);
		if (klasorler != null) {
			System.out.println("Klasor sayisi: " + klasorler.length);
			for (File klasor : klasorler) {
				System.out.println(klasor.toString());
			}
		} else {
			System.out.println("Klasor bulunamadi veya erisim hatasi.");
		}

		// Proje klasoru altindaki dosyalari listele
		if (klasorler != null && klasorler.length > 0) {
			File[] dosyalar = klasordekiDosyalariListele(klasorler[0]);
			if (dosyalar != null) {
				System.out.println("Dosya sayisi: " + dosyalar.length);
				for (File dosya : dosyalar) {
					System.out.println(dosya.toString());
				}
			} else {
				System.out.println("Dosya bulunamadi veya erisim hatasi.");
			}
		}

		// Proje klasoru altindaki tum dosyalari rekursif olarak listele
		List<File> dosyaListesi = tumDosyalariListele(projeKlasoru);
		System.out.println("Proje klasorundeki tum dosyalar:");
		for (File dosya : dosyaListesi) {
			System.out.println(dosya.toString());
		}

		// Yeni bir klasor olusturma
		String yeniKlasorYolu = projeKlasoru + File.separator + "YeniKlasor";
		if (klasorOlustur(yeniKlasorYolu)) {
			System.out.println("Yeni klasor olusturuldu: " + yeniKlasorYolu);
		} else {
			System.out.println("Klasor olusturulamadi veya zaten mevcut.");
		}

		// Yeni klasorun icine bir dosya olustur
		String yeniDosyaYolu = yeniKlasorYolu + File.separator + "TestDosyasi.txt";
		try {
			File yeniDosya = new File(yeniDosyaYolu);
			if (yeniDosya.createNewFile()) {
				System.out.println("Yeni dosya olusturuldu: " + yeniDosyaYolu);
			}
		} catch (IOException e) {
			System.out.println("Dosya olusturma hatasi: " + e.getMessage());
		}

		// YeniKlasor'u ve icindeki dosyayi sil
		File yeniKlasor = new File(yeniKlasorYolu);
		if (klasoruSil(yeniKlasor)) {
			System.out.println("YeniKlasor ve icindekiler silindi.");
		} else {
			System.out.println("YeniKlasor silinemedi veya mevcut degil.");
		}
	}
}

package com.thealgorithms.datastructures.lists;

import java.util.ArrayList;
import java.util.List;

/**
 * The SortedLinkedList class represents a singly linked list that maintains its elements in sorted order.
 * Elements are ordered based on their natural ordering, with smaller elements at the head and larger elements toward the tail.
 * The class provides methods for inserting, deleting, and searching elements, as well as checking if the list is empty.
 * <p>
 * This implementation utilizes a singly linked list to maintain a dynamically sorted list.
 * </p>
 * <p>
 * Further information can be found here:
 * https://runestone.academy/ns/books/published/cppds/LinearLinked/ImplementinganOrderedList.html
 * </p>
 *
 * <b>Usage Example:</b>
 * <pre>
 *     SortedLinkedList list = new SortedLinkedList();
 *     list.insert(10);
 *     list.insert(5);
 *     list.insert(20);
 *     System.out.println(list); // Outputs: [5, 10, 20]
 * </pre>
 */
public class SortedLinkedList {
    private Node head;
    private Node tail;

    /**
     * Initializes an empty sorted linked list.
     */
    public SortedLinkedList() {
        this.head = null;
        this.tail = null;
    }

    /**
     * Inserts a new integer into the list, maintaining sorted order.
     *
     * @param value the integer to insert
     */
    public void insert(int value) {
        Node newNode = new Node(value);
        if (head == null) {
            this.head = newNode;
            this.tail = newNode;
        } else if (value < head.value) {
            newNode.next = this.head;
            this.head = newNode;
        } else if (value > tail.value) {
            this.tail.next = newNode;
            this.tail = newNode;
        } else {
            Node temp = head;
            while (temp.next != null && temp.next.value < value) {
                temp = temp.next;
            }
            newNode.next = temp.next;
            temp.next = newNode;
            if (newNode.next == null) {
                this.tail = newNode;
            }
        }
    }

    /**
     * Deletes the first occurrence of a specified integer in the list.
     *
     * @param value the integer to delete
     * @return {@code true} if the element was found and deleted; {@code false} otherwise
     */
    public boolean delete(int value) {
        if (this.head == null) {
            return false;
        } else if (this.head.value == value) {
            if (this.head.next == null) {
                this.head = null;
                this.tail = null;
            } else {
                this.head = this.head.next;
            }
            return true;
        } else {
            Node temp = this.head;
            while (temp.next != null) {
                if (temp.next.value == value) {
                    if (temp.next == this.tail) {
                        this.tail = temp;
                    }
                    temp.next = temp.next.next;
                    return true;
                }
                temp = temp.next;
            }
            return false;
        }
    }

    /**
     * Searches for a specified integer in the list.
     *
     * @param value the integer to search for
     * @return {@code true} if the value is present in the list; {@code false} otherwise
     */
    public boolean search(int value) {
        Node temp = this.head;
        while (temp != null) {
            if (temp.value == value) {
                return true;
            }
            temp = temp.next;
        }
        return false;
    }

    /**
     * Checks if the list is empty.
     *
     * @return {@code true} if the list is empty; {@code false} otherwise
     */
    public boolean isEmpty() {
        return head == null;
    }

    /**
     * Returns a string representation of the sorted linked list in the format [element1, element2, ...].
     *
     * @return a string representation of the sorted linked list
     */
    @Override
    public String toString() {
        if (this.head != null) {
            List<String> elements = new ArrayList<>();
            Node temp = this.head;
            while (temp != null) {
                elements.add(String.valueOf(temp.value));
                temp = temp.next;
            }
            return "[" + String.join(", ", elements) + "]";
        } else {
            return "[]";
        }
    }

    /**
     * Node represents an element in the sorted linked list.
     */
    public final class Node {
        public final int value;
        public Node next;

        public Node(int value) {
            this.value = value;
            this.next = null;
        }
    }
}

package com.thealgorithms.maths;

public record ADTFraction(int numerator, int denominator) {
    /**
     * Initializes a newly created {@code ADTFraction} object so that it represents
     * a fraction with the {@code numerator} and {@code denominator} provided as arguments.
     *
     * @param numerator   The fraction numerator
     * @param denominator The fraction denominator
     */
    public ADTFraction {
        if (denominator == 0) {
            throw new IllegalArgumentException("Denominator cannot be 0");
        }
    }

    /**
     * Add two fractions.
     *
     * @param fraction the {@code ADTFraction} to add
     * @return A new {@code ADTFraction} containing the result of the operation
     */
    public ADTFraction plus(ADTFraction fraction) {
        var numerator = this.denominator * fraction.numerator + this.numerator * fraction.denominator;
        var denominator = this.denominator * fraction.denominator;
        return new ADTFraction(numerator, denominator);
    }

    /**
     * Multiply fraction by a number.
     *
     * @param number the number to multiply
     * @return A new {@code ADTFraction} containing the result of the operation
     */
    public ADTFraction times(int number) {
        return times(new ADTFraction(number, 1));
    }

    /**
     * Multiply two fractions.
     *
     * @param fraction the {@code ADTFraction} to multiply
     * @return A new {@code ADTFraction} containing the result of the operation
     */
    public ADTFraction times(ADTFraction fraction) {
        var numerator = this.numerator * fraction.numerator;
        var denominator = this.denominator * fraction.denominator;
        return new ADTFraction(numerator, denominator);
    }

    /**
     * Generates the reciprocal of the fraction.
     *
     * @return A new {@code ADTFraction} with the {@code numerator} and {@code denominator} switched
     */
    public ADTFraction reciprocal() {
        return new ADTFraction(this.denominator, this.numerator);
    }

    /**
     * Calculates the result of the fraction.
     *
     * @return The numerical result of the division between {@code numerator} and {@code
     *     denominator}
     */
    public float value() {
        return (float) this.numerator / this.denominator;
    }

    /**
     * Returns a string representation of this {@code ADTFraction} in the format
     * {@code numerator}/{@code denominator}.
     *
     * @return A string representation of this {@code ADTFraction}
     */
    @Override
    public String toString() {
        return String.format("%d/%d", this.numerator, this.denominator);
    }
}

package com.thealgorithms.datastructures.trees; // Java program to print top view of Binary tree

import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;

// Class for a tree node
class TreeNode {

    // Members

    int key;
    TreeNode left;
    TreeNode right;

    // Constructor
    TreeNode(int key) {
        this.key = key;
        left = null;
        right = null;
    }
}

// A class to represent a queue item. The queue is used to do Level
// order traversal. Every Queue item contains node and horizontal
// distance of node from root
class QItem {

    TreeNode node;
    int hd;

    QItem(TreeNode n, int h) {
        node = n;
        hd = h;
    }
}

// Class for a Binary Tree
class Tree {

    TreeNode root;

    // Constructors
    Tree() {
        root = null;
    }

    Tree(TreeNode n) {
        root = n;
    }

    // This method prints nodes in top view of binary tree
    public void printTopView() {
        // base case
        if (root == null) {
            return;
        }

        // Creates an empty hashset
        HashSet<Integer> set = new HashSet<>();

        // Create a queue and add root to it
        Queue<QItem> queue = new LinkedList<QItem>();
        queue.add(new QItem(root, 0)); // Horizontal distance of root is 0

        // Standard BFS or level order traversal loop
        while (!queue.isEmpty()) {
            // Remove the front item and get its details
            QItem qi = queue.remove();
            int hd = qi.hd;
            TreeNode n = qi.node;

            // If this is the first node at its horizontal distance,
            // then this node is in top view
            if (!set.contains(hd)) {
                set.add(hd);
                System.out.print(n.key + " ");
            }

            // Enqueue left and right children of current node
            if (n.left != null) {
                queue.add(new QItem(n.left, hd - 1));
            }
            if (n.right != null) {
                queue.add(new QItem(n.right, hd + 1));
            }
        }
    }
}

// Driver class to test above methods
public final class PrintTopViewofTree {
    private PrintTopViewofTree() {
    }

    public static void main(String[] args) {
        /* Create following Binary Tree
       1
     /  \
    2    3
     \
      4
       \
        5
         \
          6*/
        TreeNode root = new TreeNode(1);
        root.left = new TreeNode(2);
        root.right = new TreeNode(3);
        root.left.right = new TreeNode(4);
        root.left.right.right = new TreeNode(5);
        root.left.right.right.right = new TreeNode(6);
        Tree t = new Tree(root);
        System.out.println("Following are nodes in top view of Binary Tree");
        t.printTopView();
    }
}

