package random;

import java.util.Random;
import java.util.Scanner;

public class SayiTahminOyunu {

    public static void main(String[] args) {

        // Draw the secret number from the inclusive range 1..10.
        Random rng = new Random();
        int secret = rng.nextInt(10) + 1;

        Scanner input = new Scanner(System.in);
        System.out.println("Tahmininizi girin (1-10):");
        int guess = input.nextInt();
        input.close();

        boolean isCorrect = guess == secret;

        if (isCorrect) {
            System.out.println("Tebrikler! Dogru sayiyi tahmin ettiniz!");
        } else {
            System.out.println("Uzgunum, dogru sayi " + secret + " idi.");
        }
    }
}

interface Shape {
    double area();
    double perimeter();
}

class Circle implements Shape {
    private final double radius;

    public Circle(double radius) {
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }

    @Override
    public double perimeter() {
        return 2 * Math.PI * radius;
    }
}

class Rectangle implements Shape {
    private final double width;
    private final double height;

    public Rectangle(double width, double height) {
        this.width = width;
        this.height = height;
    }

    @Override
    public double area() {
        return width * height;
    }

    @Override
    public double perimeter() {
        return 2 * (width + height);
    }
}

public class ShapeDemo {
    public static void main(String[] args) {
        Shape[] shapes = {new Circle(5), new Rectangle(4, 6)};
        for (Shape shape : shapes) {
            System.out.printf("Area: %.2f, Perimeter: %.2f%n",
                    shape.area(), shape.perimeter());
        }
    }
}

/**
 * A rectangle composed of top-left and bottom-right MyPoint corners.
 */
class MyPoint {

    private int x;
    private int y;

    public MyPoint() {
    }

    public MyPoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int[] getXY() {
        return new int[]{x, y};
    }

    public void setXY(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public double distance(int x, int y) {
        return Math.sqrt(Math.pow(x - this.x, 2) + Math.pow(y - this.y, 2));
    }

    public double distance(MyPoint another) {
        return Math.sqrt(Math.pow(another.x - x, 2) + Math.pow(another.y - y, 2));
    }

    public double distance() {
        return Math.sqrt(Math.pow(-x, 2) + Math.pow(-y, 2));
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ')';
    }
}

public class MyRectangle {
    private MyPoint topLeft;
    private MyPoint bottomRight;

    public MyRectangle() {
    }

    public MyRectangle(MyPoint topLeft, MyPoint bottomRight) {
        this.topLeft = topLeft;
        this.bottomRight = bottomRight;
    }

    public MyRectangle(int x1, int y1, int x2, int y2) {
        this.topLeft = new MyPoint(x1, y1);
        this.bottomRight = new MyPoint(x2, y2);
    }

    public MyPoint getTopLeft() {
        return topLeft;
    }

    public void setTopLeft(MyPoint topLeft) {
        this.topLeft = topLeft;
    }

    public MyPoint getBottomRight() {
        return bottomRight;
    }

    public void setBottomRight(MyPoint bottomRight) {
        this.bottomRight = bottomRight;
    }

    public void setTopLeftX(int x) {
        topLeft.setX(x);
    }

    public int getTopLeftX() {
        return topLeft.getX();
    }

    public void setTopLeftY(int y) {
        topLeft.setY(y);
    }

    public int getTopLeftY() {
        return topLeft.getY();
    }

    public void setTopLeftXY(int x, int y) {
        topLeft.setXY(x, y);
    }

    public int[] getTopLeftXY() {
        return new int[]{topLeft.getX(), topLeft.getY()};
    }

    public void setBottomRightX(int x) {
        bottomRight.setX(x);
    }

    public int getBottomRightX() {
