/**
 * A rectangle whose two corners are MovablePoints, implementing Movable.
 */
public class MovableRectangle implements Movable {

    private MovablePoint topLeft;
    private MovablePoint bottomRight;

    public MovableRectangle() {
    }

    public MovableRectangle(MovablePoint topLeft, MovablePoint bottomRight) {
        this.topLeft = topLeft;
        this.bottomRight = bottomRight;
    }

    public MovablePoint getTopLeft() {
        return topLeft;
    }

    public void setTopLeft(MovablePoint topLeft) {
        this.topLeft = topLeft;
    }

    public MovablePoint getBottomRight() {
        return bottomRight;
    }

    public void setBottomRight(MovablePoint bottomRight) {
        this.bottomRight = bottomRight;
    }

    @Override
    public String toString() {
        return "MovableRectangle[topLeft=" + topLeft + ",bottomRight=" + bottomRight + ']';
    }

    @Override
    public void moveUp() {
        topLeft.setY(topLeft.getY() - topLeft.getySpeed());
        bottomRight.setY(bottomRight.getY() - bottomRight.getySpeed());
    }

    @Override
    public void moveDown() {
        topLeft.setY(topLeft.getY() + topLeft.getySpeed());
        bottomRight.setY(bottomRight.getY() + bottomRight.getySpeed());
    }

    @Override
    public void moveLeft() {
        topLeft.setX(topLeft.getX() - topLeft.getxSpeed());
        bottomRight.setX(bottomRight.getX() - bottomRight.getxSpeed());
    }

    @Override
    public void moveRight() {
        topLeft.setX(topLeft.getX() + topLeft.getxSpeed());
        bottomRight.setX(bottomRight.getX() + bottomRight.getxSpeed());
    }
}

public class NotHesaplama {

	// 'harfNotunaCevir' metodu, girilen sayisal notu harf notuna cevirir
	public static void harfNotunaCevir(int not) {
		// Not 90 veya daha yuksekse 'A' harf notu verilir
		if (not >= 90) {
			System.out.println("A");
		} 
		// Not 80 veya daha yuksekse 'B' harf notu verilir
		else if (not >= 80) {
			System.out.println("B");
		} 
		// Not 70 veya daha yuksekse 'C' harf notu verilir
		else if (not >= 70) {
			System.out.println("C");
		} 
		// Not 60 veya daha yuksekse 'D' harf notu verilir
		else if (not >= 60) {
			System.out.println("D");
		} 
		// Diger durumlar icin 'F' harf notu verilir
		else {
			System.out.println("F");
		}
	}

	public static void main(String[] args) {

		Scanner scanner = new Scanner(System.in);

		// Kullaniciya notunu girmesini iste
		System.out.print("Notunuzu girin: ");
		int not = scanner.nextInt();

		// 'harfNotunaCevir' metodu ile sayisal not harf notuna cevir
		harfNotunaCevir(not);

		// Scanner nesnesi kapat
		scanner.close();
	}
}

public class Student implements Comparable<Student>{
    int rollno;
    float marks;

    public Student(int rollno, float marks) {
        this.rollno = rollno;
        this.marks = marks;
    }

    @Override
    public String toString() {
        return marks + "";
    }

    /**
     * Compares this object with the specified object for order.  Returns a
     * negative integer, zero, or a positive integer as this object is less
     * than, equal to, or greater than the specified object.
     *
     * <p>The implementor must ensure {@link Integer#signum
     * signum}{@code (x.compareTo(y)) == -signum(y.compareTo(x))} for
     * all {@code x} and {@code y}.  (This implies that {@code
     * x.compareTo(y)} must throw an exception if and only if {@code
     * y.compareTo(x)} throws an exception.)
     *
     * <p>The implementor must also ensure that the relation is transitive:
     * {@code (x.compareTo(y) > 0 && y.compareTo(z) > 0)} implies
     * {@code x.compareTo(z) > 0}.
     *
     * <p>Finally, the implementor must ensure that {@code
     * x.compareTo(y)==0} implies that {@code signum(x.compareTo(z))
     * == signum(y.compareTo(z))}, for all {@code z}.
     *
     * @param o the object to be compared.
     * @return a negative integer, zero, or a positive integer as this object
     * is less than, equal to, or greater than the specified object.
     * @throws NullPointerException if the specified object is null
     * @throws ClassCastException   if the specified object's type prevents it
     *                              from being compared to this object.
     * @apiNote It is strongly recommended, but <i>not</i> strictly required that
     * {@code (x.compareTo(y)==0) == (x.equals(y))}.  Generally speaking, any
     * class that implements the {@code Comparable} interface and violates
     * this condition should clearly indicate this fact.  The recommended
     * language is "Note: this class has a natural ordering that is
     * inconsistent with equals."
     */
    @Override
    public int compareTo(Student o) {
        System.out.println("in compareTo method");
        int diff = (int)(this.marks - o.marks);
        // if diff == 0; means both are equal
        // if diff < 1; means o is bigger else o is smal
        return diff;
    }
}

package com.ankan.interfaces.extendDemo2;

public interface A {

    // Static methods in interfaces must have a body (cannot be abstract)
    // They belong to the interface itself, not to implementing classes
    static void displayStaticGreeting() {
        System.out.println("Static method in interface A - belongs to interface, not instances");
    }

    // Default methods provide a default implementation that implementing classes
    // can optionally override. They allow adding new methods to interfaces without
    // breaking existing implementations (backward compatibility)
    default void performDefaultAction() {
        System.out.println("Default implementation from interface A");
    }

    // Regular abstract method (implicitly public and abstract)
    void abstractMethod();
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Implementation of the Bron–Kerbosch algorithm with pivoting for enumerating all maximal cliques
 * in an undirected graph.
 *
 * <p>The input graph is represented as an adjacency list where {@code adjacency.get(u)} returns the
 * set of vertices adjacent to {@code u}. The algorithm runs in time proportional to the number of
 * maximal cliques produced and is widely used for clique enumeration problems.</p>
 *
 * @author <a href="https://en.wikipedia.org/wiki/Bron%E2%80%93Kerbosch_algorithm">Wikipedia: Bron–Kerbosch algorithm</a>
 */
public final class BronKerbosch {

    private BronKerbosch() {
    }

    /**
     * Finds all maximal cliques of the provided graph.
     *
     * @param adjacency adjacency list where {@code adjacency.size()} equals the number of vertices
     * @return a list containing every maximal clique, each represented as a {@link Set} of vertices
     * @throws IllegalArgumentException if the adjacency list is {@code null}, contains {@code null}
     *         entries, or references invalid vertices
     */
    public static List<Set<Integer>> findMaximalCliques(List<Set<Integer>> adjacency) {
        if (adjacency == null) {
            throw new IllegalArgumentException("Adjacency list must not be null");
        }

        int n = adjacency.size();
        List<Set<Integer>> graph = new ArrayList<>(n);
        for (int u = 0; u < n; u++) {
            Set<Integer> neighbors = adjacency.get(u);
            if (neighbors == null) {
                throw new IllegalArgumentException("Adjacency list must not contain null sets");
            }
            Set<Integer> copy = new HashSet<>();
            for (int v : neighbors) {
                if (v < 0 || v >= n) {
                    throw new IllegalArgumentException("Neighbor index out of bounds: " + v);
                }
                if (v != u) {
                    copy.add(v);
                }
            }
            graph.add(copy);
        }

        Set<Integer> r = new HashSet<>();
        Set<Integer> p = new HashSet<>();
        Set<Integer> x = new HashSet<>();
        for (int v = 0; v < n; v++) {
            p.add(v);
        }

        List<Set<Integer>> cliques = new ArrayList<>();
        bronKerboschPivot(r, p, x, graph, cliques);
        return cliques;
    }

    private static void bronKerboschPivot(Set<Integer> r, Set<Integer> p, Set<Integer> x, List<Set<Integer>> graph, List<Set<Integer>> cliques) {
        if (p.isEmpty() && x.isEmpty()) {
            cliques.add(new HashSet<>(r));
            return;
        }

        int pivot = choosePivot(p, x, graph);
        Set<Integer> candidates = new HashSet<>(p);
        if (pivot != -1) {
            candidates.removeAll(graph.get(pivot));
        }

        for (Integer v : candidates) {
            r.add(v);
            Set<Integer> newP = intersection(p, graph.get(v));
            Set<Integer> newX = intersection(x, graph.get(v));
            bronKerboschPivot(r, newP, newX, graph, cliques);
            r.remove(v);
            p.remove(v);
            x.add(v);
        }
    }

    private static int choosePivot(Set<Integer> p, Set<Integer> x, List<Set<Integer>> graph) {
        int pivot = -1;
        int maxDegree = -1;
        Set<Integer> union = new HashSet<>(p);
        union.addAll(x);
        for (Integer v : union) {
            int degree = graph.get(v).size();
            if (degree > maxDegree) {
                maxDegree = degree;
                pivot = v;
            }
        }
        return pivot;
    }

    private static Set<Integer> intersection(Set<Integer> base, Set<Integer> neighbors) {
        Set<Integer> result = new HashSet<>();
        for (Integer v : base) {
            if (neighbors.contains(v)) {
                result.add(v);
            }
        }
        return result;
    }
}

/**
 * Last-Write-Wins Element Set (LWWElementSet) is a state-based CRDT (Conflict-free Replicated Data
 * Type) designed for managing sets in a distributed and concurrent environment. It supports the
 * addition and removal of elements, using timestamps to determine the order of operations. The set
 * is split into two subsets: the add set for elements to be added and the remove set for elements
 * to be removed. The LWWElementSet ensures that the most recent operation (based on the timestamp)
 * wins in the case of concurrent operations.
 *
 * @param <ElementType> The type of the elements in the LWWElementSet.
 * @author <a href="https://github.com/itakurah">itakurah (GitHub)</a>, <a
 * href="https://www.linkedin.com/in/niklashoefflin/">Niklas Hoefflin (LinkedIn)</a>
 * @see <a href="https://en.wikipedia.org/wiki/Conflict-free_replicated_data_type">Conflict free
 * replicated data type (Wikipedia)</a>
 * @see <a href="https://inria.hal.science/inria-00555588v1/document">A comprehensive study of
 * Convergent and Commutative Replicated Data Types</a>
 */
class LWWElementSet<ElementType> {
final Map<ElementType, TimedElement<ElementType>> addedElements;
final Map<ElementType, TimedElement<ElementType>> removedElements;

/**
 * Constructs an empty LWWElementSet. This constructor initializes the addSet and removeSet as
 * empty HashMaps. The addSet stores elements that are added, and the removeSet stores elements
 * that are removed.
 */
LWWElementSet() {
this.addedElements = new HashMap<>();
this.removedElements = new HashMap<>();
}

/**
 * Adds an element to the addSet with the current timestamp. This method stores the element in the
 * addSet, ensuring that the element is added to the set with an associated timestamp that
 * represents the time of the addition.
 *
 * @param elementKey The key of the element to be added.
 */
public void add(ElementType elementKey) {
addedElements.put(elementKey, new TimedElement<>(elementKey, Instant.now()));
}

/**
 * Removes an element by adding it to the removeSet with the current timestamp. This method adds
 * the element to the removeSet, marking it as removed with the current timestamp.
 *
 * @param elementKey The key of the element to be removed.
 */
public void remove(ElementType elementKey) {
removedElements.put(elementKey, new TimedElement<>(elementKey, Instant.now()));
}

/**
 * Checks if an element is in the LWWElementSet. An element is considered present if it exists in
 * the addSet and either does not exist in the removeSet, or its add timestamp is later than any
 * corresponding remove timestamp.
 *
 * @param searchKey The key of the element to be checked.
 * @return {@code true} if the element is present in the set (i.e., its add timestamp is later
 * than its remove timestamp, or it is not in the remove set), {@code false} otherwise (i.e.,
 * the element has been removed or its remove timestamp is later than its add timestamp).
 */
public boolean contains(ElementType searchKey) {
TimedElement<ElementType> addEntry = addedElements.get(searchKey);
TimedElement<ElementType> removeEntry = removedElements.get(searchKey);
return addEntry != null && (removeEntry == null || addEntry.getTimestamp().isAfter(removeEntry.getTimestamp()));
}

/**
 * Merges another LWWElementSet into this set. This method takes the union of both the add-sets
 * and remove-sets from the two sets, resolving conflicts by keeping the element with the latest
 * timestamp. If an element appears in both the add-set and remove-set of both sets, the one with
 * the later timestamp will be retained.
 *
 * @param otherSet The LWWElementSet to merge with the current set.
 */
public void mergeWith(LWWElementSet<ElementType> otherSet) {
for (Map.Entry<ElementType, TimedElement<ElementType>> entryItem : otherSet.addedElements.entrySet()) {
addedElements.merge(entryItem.getKey(), entryItem.getValue(), this::resolveTimestampConflict);
}
for (Map.Entry<ElementType, TimedElement<ElementType>> entryItem : otherSet.removedElements.entrySet()) {
removedElements.merge(entryItem.getKey(), entryItem.getValue(), this::resolveTimestampConflict);
}
}

/**
 * Resolves conflicts between two elements by selecting the one with the later timestamp. This
 * method is used when merging two LWWElementSets to ensure that the most recent operation (based
 * on timestamps) is kept.
 *
 * @param firstElement The first element.
 * @param secondElement The second element.
 * @return The element with the later timestamp.
 */
private TimedElement<ElementType> resolveTimestampConflict(TimedElement<ElementType> firstElement, TimedElement<ElementType> secondElement) {
return firstElement.getTimestamp().isAfter(secondElement.getTimestamp()) ? firstElement : secondElement;
}
}

/**
 * Represents an element in the LWWElementSet, consisting of a key and a timestamp. This class is
 * used to store the elements in both the add and remove sets with their respective timestamps.
 *
 * @param <ElementType> The type of the key associated with the element.
 */
class TimedElement<ElementType> {
private final ElementType elementKey;
private final Instant operationTimestamp;

/**
 * Constructs a new Element with the specified key and timestamp.
 *
 * @param elementKey       The key of the element.
 * @param operationTimestamp The timestamp associated with the element.
 */
TimedElement(ElementType elementKey, Instant operationTimestamp) {
this.elementKey = elementKey;
this.operationTimestamp = operationTimestamp;
}

public ElementType getElementKey() {
return elementKey;
}

public Instant getTimestamp() {
return operationTimestamp;
}
}

package Shape;

/**
 * A rectangle shape.
 */
public class Rectangle extends Shape {
    protected double width;
    protected double length;

    public Rectangle() {
    }

    public Rectangle(double width, double length) {
        this.width = width;
        this.length = length;
    }

    public Rectangle(double width, double length, String color, boolean filled) {
        super(color, filled);
        this.width = width;
        this.length = length;
    }

    public double getWidth() {
        return width;
    }

    public void setWidth(double width) {
        this.width = width;
    }

    public double getLength() {
        return length;
    }

    public void setLength(double length) {
        this.length = length;
    }

    public double getArea() {
        return length * width;
    }

    public double getPerimeter() {
        return (length + width) * 2;
    }

    @Override
    public String toString() {
        return "Rectangle[" + super.toString() + ",width=" + width + ", length=" + length + ']';
    }
}

public class AsalSayi {

    // Verilen degerin asal olup olmadigini dondurur
    boolean asalDegerMi(int deger) {
        // 2'den baslayip degerden bir kucuge kadar bolunebilirlik test edilir
        int bolen = 2;
        while (bolen < deger) {
            if (deger % bolen == 0) {
                return false; // tam bolunen bulundu, asal olamaz
            }
            bolen++;
        }
        return true; // hicbir bolen bulunamadi, asaldir
    }

    // Verilen degerden sonraki ilk asal sayiyi bulur
    int birSonrakiAsal(int deger) {
        int aday = deger;
        do {
            aday++;
        } while (!asalDegerMi(aday));
        return aday;
    }

    // Verilen degerden onceki ilk asal sayiyi bulur
    int birOncekiAsal(int deger) {
        int aday = deger;
        do {
            aday--;
        } while (!asalDegerMi(aday));
        return aday;
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);

        System.out.println("Lutfen bir sayi giriniz");
        int girilenDeger = tarayici.nextInt();

        AsalSayi kontrolor = new AsalSayi();

        // Asalligini kontrol edip sonucu bas
        if (kontrolor.asalDegerMi(girilenDeger)) {
            System.out.println(girilenDeger + " sayisi asaldir.");
        } else {
            System.out.println(girilenDeger + " sayisi asal degildir.");
        }

        System.out.println("Sonraki asal sayi: " + kontrolor.birSonrakiAsal(girilenDeger));
        System.out.println("Onceki asal sayi: " + kontrolor.birOncekiAsal(girilenDeger));

        tarayici.close();
    }
}

/*
 * Notes on wiring up JUnit in Eclipse:
 *
 * Project Properties -> Java Build Path -> Libraries -> Add Library -> JUnit -> JUnit 3/4
 */

public class CalculatorTest {

    private Calculator math = new Calculator();

    @BeforeEach
    public void createFreshCalculator() {
        math = new Calculator();
    }

    @Test
    public void addsTwoNumbers() {
        assertEquals(5, math.add(2, 3));
        assertEquals(-1, math.add(-2, 1));
        assertEquals(0, math.add(-2, 2));
    }

    @Test
    public void subtractsTwoNumbers() {
        assertEquals(1, math.subtract(3, 2));
        assertEquals(-3, math.subtract(-2, 1));
        assertEquals(0, math.subtract(2, 2));
    }

    @Test
    public void multipliesTwoNumbers() {
        assertEquals(6, math.multiply(2, 3));
        assertEquals(-2, math.multiply(-2, 1));
        assertEquals(0, math.multiply(0, 2));
    }

    @Test
    public void dividesTwoNumbers() {
        assertEquals(2, math.divide(6, 3));
        assertEquals(-2, math.divide(-4, 2));

        Exception thrown = assertThrows(IllegalArgumentException.class, () -> {
            math.divide(1, 0);
        });

        assertEquals("Sifira bolme yapilamaz.", thrown.getMessage());
    }

    @Test
    public void computesModulus() {
        assertEquals(1, math.modulus(5, 2));
        assertEquals(0, math.modulus(4, 2));
        assertEquals(-1, math.modulus(-5, 2));
        assertEquals(0, math.modulus(0, 5));
    }

    @Test
    public void computesFactorial() {
        assertEquals(120, math.factorial(5));
        assertEquals(1, math.factorial(0));
        assertEquals(1, math.factorial(1));
        assertThrows(IllegalArgumentException.class, () -> math.factorial(-1));
    }

    @Test
    public void findsMaximum() {
        assertEquals(5, math.max(3, 5));
        assertEquals(-3, math.max(-3, -5));
        assertEquals(7, math.max(7, 7));
    }

    @Test
    public void findsMinimum() {
        assertEquals(3, math.min(3, 5));
        assertEquals(-5, math.min(-3, -5));
        assertEquals(7, math.min(7, 7));
    }

    @Test
    public void computesAverage() {
        assertEquals(3.0, math.average(2, 4), 0.001);
        assertEquals(5.5, math.average(5, 6), 0.001);
        assertEquals(-2.0, math.average(-4, -0), 0.001);
    }

    @Test
    public void raisesToPower() {
        assertEquals(8, math.power(2, 3), 0.001);
        assertEquals(1, math.power(5, 0), 0.001);
        assertEquals(-8, math.power(-2, 3), 0.001);
        assertEquals(0.25, math.power(2, -2), 0.001);
    }

    @Test
    public void computesSquareRoot() {
        assertEquals(3, math.squareRoot(9), 0.001);
        assertEquals(2, math.squareRoot(4), 0.001);

        Exception thrown = assertThrows(IllegalArgumentException.class, () -> {
            math.squareRoot(-4);
        });

        assertEquals("Negatif sayilarin karekoku hesaplanamaz.", thrown.getMessage());
    }
}

package workshop6;

import java.util.ArrayList;
import java.util.Scanner;

/**
 * Prints a numbered menu and reads the chosen index.
 */
public class Menu {
    public static int getChoice(ArrayList<String> options) {
        int i = 1;
        for (String option : options) {
            System.out.println(i + "-" + option);
            i++;
        }
        System.out.print("Choose 1.." + options.size() + ": ");
        Scanner scanner = new Scanner(System.in);
        return Integer.parseInt(scanner.nextLine());
    }

    public static int getChoice(Object[] options) {
        int i = 1;
        for (Object option : options) {
            System.out.println(i + "-" + option.toString());
            i++;
        }
        System.out.print("Choose 1.." + options.length + ": ");
        Scanner scanner = new Scanner(System.in);
        return Integer.parseInt(scanner.nextLine());
    }
}

import java.net.*;
import java.io.*;

public class ChatSunucu {

    public static void main(String[] args) throws IOException {
        try (// Bir sunucu soketi olustur
		ServerSocket sunucuSoketi = new ServerSocket(8000)) {
			System.out.println("Sunucu baslatildi");

			// Bir baglanti istegi bekle
			Socket soket = sunucuSoketi.accept();

			System.out.println("Istemci baglandi");

			// Veri alisverisi icin girdi ve cikti akislari olustur
			DataInputStream istemcidenGelenVeri = new DataInputStream(soket.getInputStream());
			DataOutputStream istemciyeGidenVeri = new DataOutputStream(soket.getOutputStream());

			while (true) {
			    // Istemciden bir mesaj oku
			    String mesaj = istemcidenGelenVeri.readUTF();

			    // Mesaji geri gonder
			    istemciyeGidenVeri.writeUTF(mesaj);
			}
		}
    }
}

