/**
 * A circle shape.
 */
public class Circle extends Shape {
    private double radius = 1.0;

    public Circle() {
    }

    public Circle(double radius) {
        this.radius = radius;
    }

    public Circle(double radius, String color, boolean filled) {
        super(color, filled);
        this.radius = radius;
    }

    public double getArea() {
        return Math.PI * radius * radius;
    }

    public double getPerimeter() {
        return 2 * Math.PI * radius;
    }

    @Override
    public String toString() {
        return "Circle[" + super.toString() + ",radius=" + radius + ']';
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }
}

package com.thealgorithms.graph;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.Stack;

/**
 * Implementation of Hierholzer's algorithm to find an Eulerian Circuit in an undirected graph.
 * <p>
 * An Eulerian circuit is a trail in a graph that visits every edge exactly once,
 * starting and ending at the same vertex. This algorithm finds such a circuit if one exists.
 * </p>
 * <p>
 * This implementation is designed for an <strong>undirected graph</strong>. For a valid Eulerian
 * circuit to exist, the graph must satisfy two conditions:
 * <ol>
 * <li>All vertices with a non-zero degree must be part of a single connected component.</li>
 * <li>Every vertex must have an even degree (an even number of edges connected to it).</li>
 * </ol>
 * </p>
 * <p>
 * The algorithm runs in O(E + V) time, where E is the number of edges and V is the number of vertices.
 * The graph is represented by a Map where keys are vertices and values are a LinkedList of adjacent vertices.
 * </p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Eulerian_path#Hierholzer's_algorithm">Wikipedia: Hierholzer's algorithm</a>
 */
public final class HierholzerAlgorithm {

    private final Map<Integer, LinkedList<Integer>> graph;

    public HierholzerAlgorithm(Map<Integer, LinkedList<Integer>> graph) {
        this.graph = (graph == null) ? new HashMap<>() : graph;
    }

    public boolean hasEulerianCircuit() {
        if (graph.isEmpty()) {
            return true;
        }

        for (List<Integer> neighbors : graph.values()) {
            if (neighbors.size() % 2 != 0) {
                return false;
            }
        }

        return isCoherentlyConnected();
    }

    public List<Integer> findEulerianCircuit() {
        if (!hasEulerianCircuit()) {
            return Collections.emptyList();
        }

        Map<Integer, LinkedList<Integer>> tempGraph = new HashMap<>();
        for (Map.Entry<Integer, LinkedList<Integer>> entry : graph.entrySet()) {
            tempGraph.put(entry.getKey(), new LinkedList<>(entry.getValue()));
        }

        Stack<Integer> currentPath = new Stack<>();
        LinkedList<Integer> circuit = new LinkedList<>();

        int startVertex = -1;
        for (Map.Entry<Integer, LinkedList<Integer>> entry : tempGraph.entrySet()) {
            if (!entry.getValue().isEmpty()) {
                startVertex = entry.getKey();
                break;
            }
        }

        if (startVertex == -1) {
            if (graph.isEmpty()) {
                return Collections.emptyList();
            }
            return Collections.singletonList(graph.keySet().iterator().next());
        }

        currentPath.push(startVertex);

        while (!currentPath.isEmpty()) {
            int currentVertex = currentPath.peek();

            if (tempGraph.containsKey(currentVertex) && !tempGraph.get(currentVertex).isEmpty()) {
                int nextVertex = tempGraph.get(currentVertex).pollFirst();
                tempGraph.get(nextVertex).remove(Integer.valueOf(currentVertex));
                currentPath.push(nextVertex);
            } else {
                circuit.addFirst(currentVertex);
                currentPath.pop();
            }
        }

        return circuit;
    }

    private boolean isCoherentlyConnected() {
        if (graph.isEmpty()) {
            return true;
        }

        Set<Integer> visited = new HashSet<>();
        int startNode = -1;

        for (Map.Entry<Integer, LinkedList<Integer>> entry : graph.entrySet()) {
            if (!entry.getValue().isEmpty()) {
                startNode = entry.getKey();
                break;
            }
        }

        if (startNode == -1) {
            return true;
        }

        dfs(startNode, visited);

        for (Map.Entry<Integer, LinkedList<Integer>> entry : graph.entrySet()) {
            if (!entry.getValue().isEmpty() && !visited.contains(entry.getKey())) {
                return false;
            }
        }
        return true;
    }

    private void dfs(int u, Set<Integer> visited) {
        visited.add(u);
        if (graph.containsKey(u)) {
            for (int v : graph.get(u)) {
                if (!visited.contains(v)) {
                    dfs(v, visited);
                }
            }
        }
    }
}

package com.thealgorithms.bitmanipulation;

/**
 * This class provides a method to reverse the bits of a 32-bit integer.
 * Reversing the bits means that the least significant bit (LSB) becomes
 * the most significant bit (MSB) and vice versa.
 *
 * Example:
 * Input (binary): 00000010100101000001111010011100 (43261596)
 * Output (binary): 00111001011110000010100101000000 (964176192)
 *
 * Time Complexity: O(32) - A fixed number of 32 iterations
 * Space Complexity: O(1) - No extra space used
 *
 * Note:
 * - If the input is negative, Java handles it using two’s complement representation.
 * - This function works on 32-bit integers by default.
 *
 * @author Bama Charan Chhandogi
 */
public final class ReverseBits {
private ReverseBits() {
}

/**
 * Reverses the bits of a 32-bit integer.
 *
 * @param inputNumber the integer whose bits are to be reversed
 * @return the integer obtained by reversing the bits of the input
 */
public static int reverseBits(int inputNumber) {
int reversedResult = 0;
int totalBits = 32;
for (int bitIndex = 0; bitIndex < totalBits; bitIndex++) {
reversedResult <<= 1;
reversedResult |= (inputNumber & 1);
inputNumber >>= 1;
}
return reversedResult;
}
}

/**
 * Class generates all subsequences for a given list of elements using backtracking
 */
public final class SubsequenceFinder {
    private SubsequenceFinder() {
    }

    /**
     * Find all subsequences of given list using backtracking
     *
     * @param sequence a list of items on the basis of which we need to generate all subsequences
     * @param <T> the type of elements in the array
     * @return a list of all subsequences
     */
    public static <T> List<List<T>> generateAll(List<T> sequence) {
        List<List<T>> allSubSequences = new ArrayList<>();
        if (sequence.isEmpty()) {
            allSubSequences.add(new ArrayList<>());
            return allSubSequences;
        }
        List<T> currentSubsequence = new ArrayList<>();
        backtrack(sequence, currentSubsequence, 0, allSubSequences);
        return allSubSequences;
    }

    /**
     * Iterate through each branch of states
     * We know that each state has exactly two branching
     * It terminates when it reaches the end of the given sequence
     *
     * @param sequence all elements
     * @param currentSubsequence current subsequence
     * @param index current index
     * @param allSubSequences contains all sequences
     * @param <T> the type of elements which we generate
     */
    private static <T> void backtrack(List<T> sequence, List<T> currentSubsequence, final int index, List<List<T>> allSubSequences) {
        assert index <= sequence.size();
        if (index == sequence.size()) {
            allSubSequences.add(new ArrayList<>(currentSubsequence));
            return;
        }

        backtrack(sequence, currentSubsequence, index + 1, allSubSequences);
        currentSubsequence.add(sequence.get(index));
        backtrack(sequence, currentSubsequence, index + 1, allSubSequences);
        currentSubsequence.removeLast();
    }
}

/**
 * Implementation of a B-Tree, a self-balancing tree data structure that maintains sorted data
 * and allows searches, sequential access, insertions, and deletions in logarithmic time.
 *
 * B-Trees are generalizations of binary search trees in that a node can have more than two children.
 * They're widely used in databases and file systems.
 *
 * For more information: https://en.wikipedia.org/wiki/B-tree
 */

public class BTree {
    static class BTreeNode {
        int[] keys;
        int t; // Minimum degree (defines range for number of keys)
        BTreeNode[] children;
        int n; // Current number of keys
        boolean leaf;

        BTreeNode(int t, boolean leaf) {
            this.t = t;
            this.leaf = leaf;
            this.keys = new int[2 * t - 1];
            this.children = new BTreeNode[2 * t];
            this.n = 0;
        }

        void traverse(ArrayList<Integer> result) {
            for (int i = 0; i < n; i++) {
                if (!leaf) {
                    children[i].traverse(result);
                }
                result.add(keys[i]);
            }
            if (!leaf) {
                children[n].traverse(result);
            }
        }

        BTreeNode search(int key) {
            int i = 0;
            while (i < n && key > keys[i]) {
                i++;
            }
            if (i < n && keys[i] == key) {
                return this;
            }
            if (leaf) {
                return null;
            }
            return children[i].search(key);
        }

        void insertNonFull(int key) {
            int i = n - 1;
            if (leaf) {
                while (i >= 0 && keys[i] > key) {
                    keys[i + 1] = keys[i];
                    i--;
                }
                keys[i + 1] = key;
                n++;
            } else {
                while (i >= 0 && keys[i] > key) {
                    i--;
                }
                if (children[i + 1].n == 2 * t - 1) {
                    splitChild(i + 1, children[i + 1]);
                    if (keys[i + 1] < key) {
                        i++;
                    }
                }
                children[i + 1].insertNonFull(key);
            }
        }

        void splitChild(int i, BTreeNode y) {
            BTreeNode z = new BTreeNode(y.t, y.leaf);
            z.n = t - 1;

            System.arraycopy(y.keys, t, z.keys, 0, t - 1);
            if (!y.leaf) {
                System.arraycopy(y.children, t, z.children, 0, t);
            }
            y.n = t - 1;

            for (int j = n; j >= i + 1; j--) {
                children[j + 1] = children[j];
            }
            children[i + 1] = z;

            for (int j = n - 1; j >= i; j--) {
                keys[j + 1] = keys[j];
            }
            keys[i] = y.keys[t - 1];
            n++;
        }

        void remove(int key) {
            int idx = findKey(key);

            if (idx < n && keys[idx] == key) {
                if (leaf) {
                    removeFromLeaf(idx);
                } else {
                    removeFromNonLeaf(idx);
                }
            } else {
                if (leaf) {
                    return; // Key not found
                }

                boolean flag = idx == n;
                if (children[idx].n < t) {
                    fill(idx);
                }

                if (flag && idx > n) {
                    children[idx - 1].remove(key);
                } else {
                    children[idx].remove(key);
                }
            }
        }

        private int findKey(int key) {
            int idx = 0;
            while (idx < n && keys[idx] < key) {
                ++idx;
            }
            return idx;
        }

        private void removeFromLeaf(int idx) {
            for (int i = idx + 1; i < n; ++i) {
                keys[i - 1] = keys[i];
            }
            n--;
        }

        private void removeFromNonLeaf(int idx) {
            int key = keys[idx];
            if (children[idx].n >= t) {
                int pred = getPredecessor(idx);
                keys[idx] = pred;
                children[idx].remove(pred);
            } else if (children[idx + 1].n >= t) {
                int succ = getSuccessor(idx);
                keys[idx] = succ;
                children[idx + 1].remove(succ);
            } else {
                merge(idx);
                children[idx].remove(key);
            }
        }

        private int getPredecessor(int idx) {
            BTreeNode cur = children[idx];
            while (!cur.leaf) {
                cur = cur.children[cur.n];
            }
            return cur.keys[cur.n - 1];
        }

        private int getSuccessor(int idx) {
            BTreeNode cur = children[idx + 1];
            while (!cur.leaf) {
                cur = cur.children[0];
            }
            return cur.keys[0];
        }

        private void fill(int idx) {
            if (idx != 0 && children[idx - 1].n >= t) {
                borrowFromPrev(idx);
            } else if (idx != n && children[idx + 1].n >= t) {
                borrowFromNext(idx);
            } else {
                if (idx != n) {
                    merge(idx);
                } else {
                    merge(idx - 1);
                }
            }
        }

        private void borrowFromPrev(int idx) {
            BTreeNode child = children[idx];
            BTreeNode sibling = children[idx - 1];

            for (int i = child.n - 1; i >= 0; --i) {
                child.keys[i + 1] = child.keys[i];
            }

            if (!child.leaf) {
                for (int i = child.n; i >= 0; --i) {
                    child.children[i + 1] = child.children[i];
                }
            }

            child.keys[0] = keys[idx - 1];

            if (!child.leaf) {
                child.children[0] = sibling.children[sibling.n];
            }

            keys[idx - 1] = sibling.keys[sibling.n - 1];

            child.n += 1;
            sibling.n -= 1;
        }

        private void borrowFromNext(int idx) {
            BTreeNode child = children[idx];
            BTreeNode sibling = children[idx + 1];

            child.keys[child.n] = keys[idx];

            if (!child.leaf) {
                child.children[child.n + 1] = sibling.children[0];
            }

            keys[idx] = sibling.keys[0];

            for (int i = 1; i < sibling.n; ++i) {
                sibling.keys[i - 1] = sibling.keys[i];
            }

            if (!sibling.leaf) {
                for (int i = 1; i <= sibling.n; ++i) {
                    sibling.children[i - 1] = sibling.children[i];
                }
            }

            child.n += 1;
            sibling.n -= 1;
        }

        private void merge(int idx) {
            BTreeNode child = children[idx];
            BTreeNode sibling = children[idx + 1];

            child.keys[t - 1] = keys[idx];

            for (int i = 0; i < sibling.n; ++i) {
                child.keys[i + t] = sibling.keys[i];
            }

            if (!child.leaf) {
                for (int i = 0; i <= sibling.n; ++i) {
                    child.children[i + t] = sibling.children[i];
                }
            }

            for (int i = idx + 1; i < n; ++i) {
                keys[i - 1] = keys[i];
            }

            for (int i = idx + 2; i <= n; ++i) {
                children[i - 1] = children[i];
            }

            child.n += sibling.n + 1;
            n--;
        }
    }

    private BTreeNode root;
    private final int t;

    public BTree(int t) {
        this.root = null;
        this.t = t;
    }

    public void traverse(ArrayList<Integer> result) {
        if (root != null) {
            root.traverse(result);
        }
    }

    public boolean search(int key) {
        return root != null && root.search(key) != null;
    }

    public void insert(int key) {
        if (search(key)) {
            return;
        }
        if (root == null) {
            root = new BTreeNode(t, true);
            root.keys[0] = key;
            root.n = 1;
        } else {
            if (root.n == 2 * t - 1) {
                BTreeNode s = new BTreeNode(t, false);
                s.children[0] = root;
                s.splitChild(0, root);
                int i = 0;
                if (s.keys[0] < key) {
                    i++;
                }
                s.children[i].insertNonFull(key);
                root = s;
            } else {
                root.insertNonFull(key);
            }
        }
    }

    public void delete(int key) {
        if (root == null) {
            return;
        }
        root.remove(key);
        if (root.n == 0) {
            root = root.leaf ? null : root.children[0];
        }
    }
}

package syntax;

public class UcluIslec {

    public static void main(String[] args) {

        int sayi = 10;

        // Basit bir uclu operator ornegi
        String sonuc = (sayi > 5) ? "Buyuk" : "Kucuk"; // sayi 5'ten buyukse "Buyuk", degilse "Kucuk" yazdir
        System.out.println("Sayi 5ten Buyuk mu? " + sonuc); // Sayi Buyuk mu? Buyuk

        sonuc = (sayi > 15) ? "Buyuk" : "Kucuk"; // sayi 5'ten buyukse "Buyuk", degilse "Kucuk" yazdir
        System.out.println("Sayi 15ten Buyuk mu? " + sonuc); // Sayi Buyuk mu? Buyuk

        // Ic ice girmis uclu operatorlerin kullanimi
        String derece = (sayi > 25) ? "Sicak" : (sayi > 15) ? "Ilik" : "Soguk"; 
        // sayi 25'ten buyukse "Sicak", 15'ten buyukse "Ilik", degilse "Soguk" yazdir
        System.out.println("Hava Durumu: 10 derece " + derece); // Hava Durumu: Ilik

        sayi = 20;
        derece = (sayi > 25) ? "Sicak" : (sayi > 15) ? "Ilik" : "Soguk"; 
        // sayi 25'ten buyukse "Sicak", 15'ten buyukse "Ilik", degilse "Soguk" yazdir
        System.out.println("Hava Durumu: 20 derece " + derece); // Hava Durumu: Ilik

        sayi = 30;
        derece = (sayi > 25) ? "Sicak" : (sayi > 15) ? "Ilik" : "Soguk"; 
        // sayi 25'ten buyukse "Sicak", 15'ten buyukse "Ilik", degilse "Soguk" yazdir
        System.out.println("Hava Durumu: 30 derece " + derece); // Hava Durumu: Ilik
    }
}

package com.ankan.interfaces;

public class Main {
    public static void main(String[] args) {
        // Demonstrating polymorphism with interface references

        // Engine reference pointing to a Car object
        // Available methods: Only those declared in Engine interface
        Engine engineReference = new Car();

        // These methods are NOT accessible through Engine reference:
        // engineReference.carModelNumber;     // Field not in Engine interface
        // engineReference.increaseSpeed();    // Would be accessible if method exists in Engine
        // engineReference.startEngine();      // Should be accessible (depends on Engine interface)
        // engineReference.stopEngine();       // Should be accessible

        // Media interface reference pointing to a Car object
        // Available methods: Only those declared in Media interface
        Media mediaReference = new Car();
        // mediaReference.stopPlayback();      // Accessible through Media interface

        // Demonstrating NiceCar functionality (has both engine and media capabilities)
        System.out.println("--- NiceCar Demonstration ---");
        NiceCar upgradedCar = new NiceCar();

        upgradedCar.startEngine();        // Starts the car's engine
        upgradedCar.startPlayback();      // Starts music/media playback
        upgradedCar.upgradeEngine();      // Upgrades to a better engine (PowerEngine)
        upgradedCar.startEngine();        // Starts the newly upgraded engine

        // Educational note:
        // The reference type determines what methods can be called at compile time
        // The actual object type determines which implementation runs at runtime
        // This is why 'car' reference can't access Media methods even if the object
        // is a Car that implements both Engine and Media interfaces
    }
}

package com.thealgorithms.maths;

import java.util.stream.IntStream;

/**
 * In number theory, the aliquot sum s(n) of a positive integer n is the sum of
 * all proper divisors of n, that is, all divisors of n other than n itself. For
 * example, the proper divisors of 15 (that is, the positive divisors of 15 that
 * are not equal to 15) are 1, 3 and 5, so the aliquot sum of 15 is 9 i.e. (1 +
 * 3 + 5). Wikipedia: https://en.wikipedia.org/wiki/Aliquot_sum
 */
public final class AliquotSum {
    private AliquotSum() {
    }

    /**
     * Finds the aliquot sum of an integer number.
     *
     * @param number a positive integer
     * @return aliquot sum of given {@code number}
     */
    public static int getAliquotValue(int number) {
        var sumWrapper = new Object() { int value = 0; };

        IntStream.iterate(1, i -> ++i).limit(number / 2).filter(i -> number % i == 0).forEach(i -> sumWrapper.value += i);

        return sumWrapper.value;
    }

    /**
     * Function to calculate the aliquot sum of an integer number
     *
     * @param n a positive integer
     * @return aliquot sum of given {@code number}
     */
    public static int getAliquotSum(int n) {
        if (n <= 0) {
            return -1;
        }
        int sum = 1;
        double root = Math.sqrt(n);
        /*
         * We can get the factors after the root by dividing number by its factors
         * before the root.
         * Ex- Factors of 100 are 1, 2, 4, 5, 10, 20, 25, 50 and 100.
         * Root of 100 is 10. So factors before 10 are 1, 2, 4 and 5.
         * Now by dividing 100 by each factor before 10 we get:
         * 100/1 = 100, 100/2 = 50, 100/4 = 25 and 100/5 = 20
         * So we get 100, 50, 25 and 20 which are factors of 100 after 10
         */
        for (int i = 2; i <= root; i++) {
            if (n % i == 0) {
                sum += i + n / i;
            }
        }
        // if n is a perfect square then its root was added twice in above loop, so subtracting root
        // from sum
        if (root == (int) root) {
            sum -= (int) root;
        }
        return sum;
    }
}

/**
 * A cylinder that extends Circle by adding a height.
 */
public class Cylinder extends Circle {

    private double height = 1.0;

    public Cylinder() {
    }

    public Cylinder(double radius) {
        super(radius);
    }

    public Cylinder(double radius, String color) {
        super(radius, color);
    }

    public Cylinder(double radius, double height) {
        super(radius);
        this.height = height;
    }

    public Cylinder(double radius, double height, String color) {
        super(radius, color);
        this.height = height;
    }

    public double getHeight() {
        return height;
    }

    public void setHeight(double height) {
        this.height = height;
    }

    public double getVolume() {
        return getArea() * height;
    }

    @Override
    public String toString() {
        return "Cylinder: subclass of " + super.toString() + " height=" + height;
    }
}

