package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;

public class UndirectedAdjacencyListGraph {
private ArrayList<HashMap<Integer, Integer>> neighborMap = new ArrayList<>();

/**
 * Adds a new node to the graph by adding an empty HashMap for its neighbors.
 * @return the index of the newly added node in the adjacency list
 */
public int insertNode() {
neighborMap.add(new HashMap<>());
return neighborMap.size() - 1;
}

/**
 * Adds an undirected edge between the origin node (@startNode) and the destination node (@endNode) with the specified weight.
 * If the edge already exists, no changes are made.
 * @param startNode the index of the origin node
 * @param endNode the index of the destination node
 * @param edgeWeight the weight of the edge between @startNode and @endNode
 * @return true if the edge was successfully added, false if the edge already exists or if any node index is invalid
 */
public boolean addEdge(int startNode, int endNode, int edgeWeight) {
int totalNodes = neighborMap.size();
if (startNode >= totalNodes || endNode >= totalNodes || startNode < 0 || endNode < 0) {
return false;
}
if (neighborMap.get(startNode).containsKey(endNode)) {
return false;
}
neighborMap.get(startNode).put(endNode, edgeWeight);
neighborMap.get(endNode).put(startNode, edgeWeight);
return true;
}

/**
 * Returns the set of all adjacent nodes (neighbors) for the given node.
 * @param targetNode the index of the node whose neighbors are to be retrieved
 * @return a HashSet containing the indices of all neighboring nodes
 */
public HashSet<Integer> getAdjacentNodes(int targetNode) {
return new HashSet<>(neighborMap.get(targetNode).keySet());
}

/**
 * Returns the weight of the edge between the origin node (@startNode) and the destination node (@endNode).
 * If no edge exists, returns null.
 * @param startNode the index of the origin node
 * @param endNode the index of the destination node
 * @return the weight of the edge between @startNode and @endNode, or null if no edge exists
 */
public Integer getEdgeWeight(int startNode, int endNode) {
return neighborMap.get(startNode).getOrDefault(endNode, null);
}

/**
 * Returns the number of nodes currently in the graph.
 * @return the number of nodes in the graph
 */
public int getVertexCount() {
return neighborMap.size();
}
}
