/**
 * Implementation of the Burrows-Wheeler Transform (BWT) and its inverse.
 * <p>
 * BWT is a reversible data transformation algorithm that rearranges a string into runs of
 * similar characters. While not a compression algorithm itself, it significantly improves
 * the compressibility of data for subsequent algorithms like Move-to-Front encoding and
 * Run-Length Encoding.
 * </p>
 *
 * <p>The transform works by:
 * <ol>
 *   <li>Generating all rotations of the input string</li>
 *   <li>Sorting these rotations lexicographically</li>
 *   <li>Taking the last column of the sorted matrix as output</li>
 *   <li>Recording the index of the original string in the sorted matrix</li>
 * </ol>
 * </p>
 *
 * <p><b>Important:</b> The input string should end with a unique end-of-string marker
 * (typically '$') that:
 * <ul>
 *   <li>Does not appear anywhere else in the text</li>
 *   <li>Is lexicographically smaller than all other characters</li>
 *   <li>Ensures unique rotations and enables correct inverse transformation</li>
 * </ul>
 * Without this marker, the inverse transform may not correctly reconstruct the original string.
 * </p>
 *
 * <p><b>Time Complexity:</b>
 * <ul>
 *   <li>Forward transform: O(n² log n) where n is the string length</li>
 *   <li>Inverse transform: O(n) using the LF-mapping technique</li>
 * </ul>
 * </p>
 *
 * <p><b>Example:</b></p>
 * <pre>
 * Input:  "banana$"
 * Output: BWTResult("annb$aa", 4)
 *         - "annb$aa" is the transformed string (groups similar characters)
 *         - 4 is the index of the original string in the sorted rotations
 * </pre>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Burrows%E2%80%93Wheeler_transform">Burrows–Wheeler transform (Wikipedia)</a>
 */
public final class BurrowsWheelerTransform {

private BurrowsWheelerTransform() {
}

/**
 * A container for the result of the forward BWT.
 * <p>
 * Contains the transformed string and the index of the original string
 * in the sorted rotations matrix, both of which are required for the
 * inverse transformation.
 * </p>
 */
public static class TransformResult {
public final String encodedData;
public final int originalPosition;

public TransformResult(String encodedData, int originalPosition) {
this.encodedData = encodedData;
this.originalPosition = originalPosition;
}

@Override
public boolean equals(Object otherObject) {
if (this == otherObject) return true;
if (otherObject == null || getClass() != otherObject.getClass()) return false;
TransformResult that = (TransformResult) otherObject;
return originalPosition == that.originalPosition && encodedData.equals(that.encodedData);
}

@Override
public int hashCode() {
return 31 * encodedData.hashCode() + originalPosition;
}

@Override
public String toString() {
return "TransformResult[encodedData=" + encodedData + ", originalPosition=" + originalPosition + "]";
}
}

/**
 * Performs the forward Burrows-Wheeler Transform on the input string.
 * <p>
 * The algorithm generates all cyclic rotations of the input, sorts them
 * lexicographically, and returns the last column of this sorted matrix
 * along with the position of the original string.
 * </p>
 *
 * <p><b>Note:</b> It is strongly recommended that the input string ends with
 * a unique end-of-string marker (e.g., '$') that is lexicographically smaller
 * than any other character in the string. This ensures correct inversion.</p>
 *
 * @param sourceText the input string to transform; must not be {@code null}
 * @return a {@link TransformResult} object containing the transformed string (L-column)
 *         and the index of the original string in the sorted rotations matrix;
 *         returns {@code TransformResult("", -1)} for empty input
 * @throws NullPointerException if {@code sourceText} is {@code null}
 */
public static TransformResult encode(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
return new TransformResult("", -1);
}
int textLength = sourceText.length();
String[] rotationArray = new String[textLength];
for (int offset = 0; offset < textLength; offset++) {
rotationArray[offset] = sourceText.substring(offset) + sourceText.substring(0, offset);
}
Arrays.sort(rotationArray);
int originalIndex = Arrays.binarySearch(rotationArray, sourceText);
StringBuilder lastColumnBuilder = new StringBuilder(textLength);
for (int index = 0; index < textLength; index++) {
lastColumnBuilder.append(rotationArray[index].charAt(textLength - 1));
}
return new TransformResult(lastColumnBuilder.toString(), originalIndex);
}

/**
 * Performs the inverse Burrows-Wheeler Transform using the LF-mapping technique.
 * <p>
 * The LF-mapping (Last-First mapping) is an efficient method to reconstruct
 * the original string from the BWT output without explicitly reconstructing
 * the entire sorted rotations matrix.
 * </p>
 *
 * <p>The algorithm works by:
 * <ol>
 *   <li>Creating the first column by sorting the BWT string</li>
 *   <li>Building a mapping from first column indices to last column indices</li>
 *   <li>Following this mapping starting from the original index to reconstruct the string</li>
 * </ol>
 * </p>
 *
 * @param encodedData the transformed string (L-column) from the forward transform; must not be {@code null}
 * @param originalPosition the index of the original string row from the forward transform;
 *                      use -1 for empty strings
 * @return the original, untransformed string; returns empty string if input is empty or {@code originalPosition} is -1
 * @throws NullPointerException if {@code encodedData} is {@code null}
 * @throws IllegalArgumentException if {@code originalPosition} is out of valid range (except -1)
 */
public static String decode(String encodedData, int originalPosition) {
if (encodedData == null || encodedData.isEmpty() || originalPosition == -1) {
return "";
}
int dataLength = encodedData.length();
if (originalPosition < 0 || originalPosition >= dataLength) {
throw new IllegalArgumentException("Original index must be between 0 and " + (dataLength - 1) + ", got: " + originalPosition);
}
char[] lastColumnChars = encodedData.toCharArray();
char[] firstColumnChars = encodedData.toCharArray();
Arrays.sort(firstColumnChars);
int[] nextMapping = new int[dataLength];
Map<Character, Integer> charCounter = new HashMap<>();
Map<Character, Integer> firstOccurrenceMap = new HashMap<>();
for (int index = 0; index < dataLength; index++) {
if (!firstOccurrenceMap.containsKey(firstColumnChars[index])) {
firstOccurrenceMap.put(firstColumnChars[index], index);
}
}
for (int index = 0; index < dataLength; index++) {
char currentChar = lastColumnChars[index];
int currentCount = charCounter.getOrDefault(currentChar, 0);
int firstOccurrenceIndex = firstOccurrenceMap.get(currentChar);
nextMapping[firstOccurrenceIndex + currentCount] = index;
charCounter.put(currentChar, currentCount + 1);
}
StringBuilder restoredText = new StringBuilder(dataLength);
int currentRow = originalPosition;
for (int step = 0; step < dataLength; step++) {
restoredText.append(firstColumnChars[currentRow]);
currentRow = nextMapping[currentRow];
}
return restoredText.toString();
}
}

package Exchange_money;

import java.util.ArrayList;
import java.util.StringTokenizer;

/**
 * Looks up a known "code1;code2;rate" entry and converts an amount.
 */
public class Exchange {

    public static ArrayList<String> listRates = new ArrayList<>();

    public static void createRete() {
        listRates.add("USD;VND;17000");
        listRates.add("EUR;USD;1.2");
        listRates.add("USD;IDN;15789");
        listRates.add("USD;EUR;0.83");
        listRates.add("CAD;IDN;16869");
    }

    public double convert(String code1, String code2, double amount) {
        createRete();
        for (String entry : listRates) {
            StringTokenizer tokenizer = new StringTokenizer(entry, ";");
            String fromCode = tokenizer.nextToken();
            String toCode = tokenizer.nextToken();
            double knownRate = Double.parseDouble(tokenizer.nextToken());
            if (code1.equalsIgnoreCase(fromCode) && code2.equalsIgnoreCase(toCode)) {
                return knownRate * amount;
            }
        }
        System.out.println("Can not found code!!!!");
        return amount;
    }
}

package functions;
import java.util.Scanner;  // kullanicidan giris almak icin gerekli

public class OgrenciNumarasi {

    // Ogrenci numarasindan kayit yilini cikarir
    int kayitYiliniBul(int numara) {
        // numaranin ust basamaklari yil bilgisini verir, 2000 eklenir
        return (numara / 10000000) + 2000;
    }

    // Ogrenci numarasindan siradaki kayit numarasini cikarir
    int kayitSirasiniBul(int numara) {
        // son 3 hane siralamayi belirtir
        return numara % 1000;
    }

    // Ogrenci numarasindan bolum bilgisini cozer
    String bolumAdiniBul(int numara) {
        int bolumKodu = (numara / 1000) % 10;

        String sonucAdi;
        if (bolumKodu == 7) {
            sonucAdi = "Elektrik Elektronik";
        } else if (bolumKodu == 6) {
            sonucAdi = "Bilgisayar";
        } else if (bolumKodu == 5) {
            sonucAdi = "Makina";
        } else {
            sonucAdi = "Bilinmiyor";
        }
        return sonucAdi;
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);

        System.out.println("Lutfen okul numaranizi giriniz");
        int okunanNumara = tarayici.nextInt();

        // Sabit test degeri ile ustune yazilir
        okunanNumara = 230707123;

        OgrenciNumarasi cozumleyici = new OgrenciNumarasi();

        System.out.println("Kayit yili: " + cozumleyici.kayitYiliniBul(okunanNumara));
        System.out.println("Kayit sirasi: " + cozumleyici.kayitSirasiniBul(okunanNumara));
        System.out.println("Bolum: " + cozumleyici.bolumAdiniBul(okunanNumara));

        tarayici.close();
    }
}

/**
 * Centroid Decomposition is a divide-and-conquer technique for trees.
 * It recursively partitions a tree by finding centroids - nodes whose removal
 * creates balanced subtrees (each with at most N/2 nodes).
 *
 * <p>
 * Time Complexity: O(N log N) for construction
 * Space Complexity: O(N)
 *
 * <p>
 * Applications:
 * - Distance queries on trees
 * - Path counting problems
 * - Nearest neighbor searches
 *
 * @see <a href="https://en.wikipedia.org/wiki/Centroid_decomposition">Centroid Decomposition</a>
 * @see <a href="https://codeforces.com/blog/entry/81661">Centroid Decomposition Tutorial</a>
 * @author lens161
 */
public final class CentroidDecomposition {

    private CentroidDecomposition() {
    }

    /**
     * Represents the centroid tree structure.
     */
    public static final class CentroidTree {
        private final int n;
        private final List<List<Integer>> adj;
        private final int[] parent;
        private final int[] subtreeSize;
        private final boolean[] removed;
        private int root;

        /**
         * Constructs a centroid tree from an adjacency list.
         *
         * @param adj adjacency list representation of the tree (0-indexed)
         * @throws IllegalArgumentException if tree is empty or null
         */
        public CentroidTree(List<List<Integer>> adj) {
            if (adj == null || adj.isEmpty()) {
                throw new IllegalArgumentException("Tree cannot be empty or null");
            }

            this.n = adj.size();
            this.adj = adj;
            this.parent = new int[n];
            this.subtreeSize = new int[n];
            this.removed = new boolean[n];
            Arrays.fill(parent, -1);

            // Build centroid tree starting from node 0
            this.root = decompose(0, -1);
        }

        /**
         * Recursively builds the centroid tree.
         *
         * @param u current node
         * @param p parent in centroid tree
         * @return centroid of current component
         */
        private int decompose(int u, int p) {
            int size = getSubtreeSize(u, -1);
            int centroid = findCentroid(u, -1, size);

            removed[centroid] = true;
            parent[centroid] = p;

            // Recursively decompose each subtree
            for (int v : adj.get(centroid)) {
                if (!removed[v]) {
                    decompose(v, centroid);
                }
            }

            return centroid;
        }

        /**
         * Calculates subtree size from node u.
         *
         * @param u current node
         * @param p parent node (-1 for root)
         * @return size of subtree rooted at u
         */
        private int getSubtreeSize(int u, int p) {
            subtreeSize[u] = 1;
            for (int v : adj.get(u)) {
                if (v != p && !removed[v]) {
                    subtreeSize[u] += getSubtreeSize(v, u);
                }
            }
            return subtreeSize[u];
        }

        /**
         * Finds the centroid of a subtree.
         * A centroid is a node whose removal creates components with size &lt;= totalSize/2.
         *
         * @param u current node
         * @param p parent node
         * @param totalSize total size of current component
         * @return centroid node
         */
        private int findCentroid(int u, int p, int totalSize) {
            for (int v : adj.get(u)) {
                if (v != p && !removed[v] && subtreeSize[v] > totalSize / 2) {
                    return findCentroid(v, u, totalSize);
                }
            }
            return u;
        }

        /**
         * Gets the parent of a node in the centroid tree.
         *
         * @param node the node
         * @return parent node in centroid tree, or -1 if root
         */
        public int getParent(int node) {
            if (node < 0 || node >= n) {
                throw new IllegalArgumentException("Invalid node: " + node);
            }
            return parent[node];
        }

        /**
         * Gets the root of the centroid tree.
         *
         * @return root node
         */
        public int getRoot() {
            return root;
        }

        /**
         * Gets the number of nodes in the tree.
         *
         * @return number of nodes
         */
        public int size() {
            return n;
        }

        /**
         * Returns the centroid tree structure as a string.
         * Format: node -&gt; parent (or ROOT for root node)
         *
         * @return string representation
         */
        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder("Centroid Tree:\n");
            for (int i = 0; i < n; i++) {
                sb.append("Node ").append(i).append(" -> ");
                if (parent[i] == -1) {
                    sb.append("ROOT");
                } else {
                    sb.append("Parent ").append(parent[i]);
                }
                sb.append("\n");
            }
            return sb.toString();
        }
    }

    /**
     * Creates a centroid tree from an edge list.
     *
     * @param n number of nodes (0-indexed: 0 to n-1)
     * @param edges list of edges where each edge is [u, v]
     * @return CentroidTree object
     * @throws IllegalArgumentException if n &lt;= 0 or edges is invalid
     */
    public static CentroidTree buildFromEdges(int n, int[][] edges) {
        if (n <= 0) {
            throw new IllegalArgumentException("Number of nodes must be positive");
        }
        if (edges == null) {
            throw new IllegalArgumentException("Edges cannot be null");
        }
        if (edges.length != n - 1) {
            throw new IllegalArgumentException("Tree must have exactly n-1 edges");
        }

        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            if (edge.length != 2) {
                throw new IllegalArgumentException("Each edge must have exactly 2 nodes");
            }
            int u = edge[0];
            int v = edge[1];

            if (u < 0 || u >= n || v < 0 || v >= n) {
                throw new IllegalArgumentException("Invalid node in edge: [" + u + ", " + v + "]");
            }

            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        return new CentroidTree(adj);
    }
}

package com.thealgorithms.datastructures.graphs;

/**
 * The {@code FloydWarshall} class provides an implementation of the Floyd-Warshall algorithm
 * to compute the shortest paths between all pairs of vertices in a weighted graph.
 * It handles both positive and negative edge weights but does not support negative cycles.
 * The algorithm is based on dynamic programming and runs in O(V^3) time complexity,
 * where V is the number of vertices in the graph.
 *
 * <p>
 * The distance matrix is updated iteratively to find the shortest distance between any two vertices
 * by considering each vertex as an intermediate step.
 * </p>
 *
 * Reference: <a href="https://en.wikipedia.org/wiki/Floyd%E2%80%93Warshall_algorithm">Floyd-Warshall Algorithm</a>
 */
public class FloydWarshall {

    private int[][] distanceMatrix;
    private int numberofvertices;
    public static final int INFINITY = 999;

    /**
     * Constructs a Floyd-Warshall instance for a graph with the given number of vertices.
     * Initializes the distance matrix for the graph.
     *
     * @param numberofvertices The number of vertices in the graph.
     */
    public FloydWarshall(int numberofvertices) {
        distanceMatrix = new int[numberofvertices + 1][numberofvertices + 1];
        // The matrix is initialized with 0's by default
        this.numberofvertices = numberofvertices;
    }

    /**
     * Executes the Floyd-Warshall algorithm to compute the shortest path between all pairs of vertices.
     * It uses an adjacency matrix to calculate the distance matrix by considering each vertex as an intermediate point.
     *
     * @param adjacencyMatrix The weighted adjacency matrix representing the graph.
     *                        A value of 0 means no direct edge between the vertices, except for diagonal elements which are 0 (distance to self).
     */
    public void floydwarshall(int[][] adjacencyMatrix) {
        // Initialize the distance matrix with the adjacency matrix.
        for (int source = 1; source <= numberofvertices; source++) {
            System.arraycopy(adjacencyMatrix[source], 1, distanceMatrix[source], 1, numberofvertices);
        }
        for (int intermediate = 1; intermediate <= numberofvertices; intermediate++) {
            for (int source = 1; source <= numberofvertices; source++) {
                for (int destination = 1; destination <= numberofvertices; destination++) {
                    // Update distance if a shorter path through the intermediate vertex exists.
                    if (distanceMatrix[source][intermediate] + distanceMatrix[intermediate][destination] < distanceMatrix[source][destination]) {
                        distanceMatrix[source][destination] = distanceMatrix[source][intermediate] + distanceMatrix[intermediate][destination];
                    }
                }
            }
        }

        printDistanceMatrix();
    }

    /**
     * Prints the distance matrix representing the shortest paths between all pairs of vertices.
     * The rows and columns correspond to the source and destination vertices.
     */
    private void printDistanceMatrix() {
        // Print header for vertices
        for (int source = 1; source <= numberofvertices; source++) {
            System.out.print("\t" + source);
        }
        System.out.println();

        // Print the distance matrix
        for (int source = 1; source <= numberofvertices; source++) {
            System.out.print(source + "\t");
            for (int destination = 1; destination <= numberofvertices; destination++) {
                System.out.print(distanceMatrix[source][destination] + "\t");
            }
            System.out.println();
        }
    }

    public Object[] getDistanceMatrix() {
        return distanceMatrix;
    }
}

public final class LCA {
    private LCA() {
    }

    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        // The adjacency list representation of a tree:
        ArrayList<ArrayList<Integer>> adj = new ArrayList<>();

        // v is the number of vertices and e is the number of edges
        int v = SCANNER.nextInt();
        int e = v - 1;

        for (int i = 0; i < v; i++) {
            adj.add(new ArrayList<Integer>());
        }

        // Storing the given tree as an adjacency list
        int to;
        int from;
        for (int i = 0; i < e; i++) {
            to = SCANNER.nextInt();
            from = SCANNER.nextInt();

            adj.get(to).add(from);
            adj.get(from).add(to);
        }

        // parent[v1] gives parent of a vertex v1
        int[] parent = new int[v];

        // depth[v1] gives depth of vertex v1 with respect to the root
        int[] depth = new int[v];

        // Assuming the tree to be rooted at 0, hence calculating parent and depth of every vertex
        dfs(adj, 0, -1, parent, depth);

        // Inputting the two vertices whose LCA is to be calculated
        int v1 = SCANNER.nextInt();
        int v2 = SCANNER.nextInt();

        // Outputting the LCA
        System.out.println(getLCA(v1, v2, depth, parent));
    }

    /**
     * Depth first search to calculate parent and depth of every vertex
     *
     * @param adj The adjacency list representation of the tree
     * @param s The source vertex
     * @param p Parent of source
     * @param parent An array to store parents of all vertices
     * @param depth An array to store depth of all vertices
     */
    private static void dfs(ArrayList<ArrayList<Integer>> adj, int s, int p, int[] parent, int[] depth) {
        for (int adjacent : adj.get(s)) {
            if (adjacent != p) {
                parent[adjacent] = s;
                depth[adjacent] = 1 + depth[s];
                dfs(adj, adjacent, s, parent, depth);
            }
        }
    }

    /**
     * Method to calculate Lowest Common Ancestor
     *
     * @param v1 The first vertex
     * @param v2 The second vertex
     * @param depth An array with depths of all vertices
     * @param parent An array with parents of all vertices
     * @return Returns a vertex that is LCA of v1 and v2
     */
    private static int getLCA(int v1, int v2, int[] depth, int[] parent) {
        if (depth[v1] < depth[v2]) {
            int temp = v1;
            v1 = v2;
            v2 = temp;
        }
        while (depth[v1] != depth[v2]) {
            v1 = parent[v1];
        }
        if (v1 == v2) {
            return v1;
        }
        while (v1 != v2) {
            v1 = parent[v1];
            v2 = parent[v2];
        }
        return v1;
    }
}
