// Dikdortgen sinifi, Sekil sinifini genisletir
package polymorphism;

public class Dikdortgen extends Sekil {
	private double genislik;
	private double yukseklik;

	// Yapilandirici
	public Dikdortgen(double genislik, double yukseklik) {
		super("Dikdortgen");
		this.genislik = genislik;
		this.yukseklik = yukseklik;
	}

	// Genislik ve yukseklik icin getter ve setter metodlari
	public double getGenislik() {
		return genislik;
	}

	public void setGenislik(double genislik) {
		this.genislik = genislik;
	}

	public double getYukseklik() {
		return yukseklik;
	}

	public void setYukseklik(double yukseklik) {
		this.yukseklik = yukseklik;
	}

	// alanHesapla metodu override edilir
	@Override
	public double alanHesapla() {
		return genislik * yukseklik;
	}

	// cevreHesapla metodu override edilir
	@Override
	public double cevreHesapla() {
		return 2 * (genislik + yukseklik);
	}

	// ciz metodu override edilir
	@Override
	public void ciz() {
		System.out.println("Dikdortgen ciziliyor: Genislik " + genislik + ", Yukseklik " + yukseklik);
	}
}

package com.thealgorithms.ciphers;

/**
 * A Java implementation of the Vigenère Cipher.
 *
 * The Vigenère Cipher is a polyalphabetic substitution cipher that uses a
 * keyword to shift letters in the plaintext by different amounts, depending
 * on the corresponding character in the keyword. It wraps around the alphabet,
 * ensuring the shifts are within 'A'-'Z' or 'a'-'z'.
 *
 * Non-alphabetic characters (like spaces, punctuation) are kept unchanged.
 *
 * Encryption Example:
 * - Plaintext: "Hello World!"
 * - Key: "suchsecret"
 * - Encrypted Text: "Zynsg Yfvev!"
 *
 * Decryption Example:
 * - Ciphertext: "Zynsg Yfvev!"
 * - Key: "suchsecret"
 * - Decrypted Text: "Hello World!"
 *
 * Wikipedia Reference:
 * <a href="https://en.wikipedia.org/wiki/Vigen%C3%A8re_cipher">Vigenère Cipher - Wikipedia</a>
 *
 * @author straiffix
 * @author beingmartinbmc
 */
public class Vigenere {

/**
 * Encrypts a given message using the Vigenère Cipher with the specified key.
 * Steps:
 * 1. Iterate over each character in the message.
 * 2. If the character is a letter, shift it by the corresponding character in the key.
 * 3. Preserve the case of the letter.
 * 4. Preserve non-alphabetic characters.
 * 5. Move to the next character in the key (cyclic).
 * 6. Return the encrypted message.
 *
 * @param sourceMessage The plaintext message to encrypt.
 * @param secretKey The keyword used for encryption.
 * @throws IllegalArgumentException if the key is empty.
 * @return The encrypted message.
 */
public String encrypt(final String sourceMessage, final String secretKey) {
if (secretKey.isEmpty()) {
throw new IllegalArgumentException("Key cannot be empty.");
}
StringBuilder encryptedOutput = new StringBuilder();
int keyPosition = 0;
for (int charIndex = 0; charIndex < sourceMessage.length(); charIndex++) {
char currentChar = sourceMessage.charAt(charIndex);
if (Character.isLetter(currentChar)) {
if (Character.isUpperCase(currentChar)) {
encryptedOutput.append((char) ((currentChar + secretKey.toUpperCase().charAt(keyPosition) - 2 * 'A') % 26 + 'A'));
} else {
encryptedOutput.append((char) ((currentChar + secretKey.toLowerCase().charAt(keyPosition) - 2 * 'a') % 26 + 'a'));
}
keyPosition = ++keyPosition % secretKey.length();
} else {
encryptedOutput.append(currentChar);
}
}
return encryptedOutput.toString();
}

/**
 * Decrypts a given message encrypted with the Vigenère Cipher using the specified key.
 * Steps:
 * 1. Iterate over each character in the message.
 * 2. If the character is a letter, shift it back by the corresponding character in the key.
 * 3. Preserve the case of the letter.
 * 4. Preserve non-alphabetic characters.
 * 5. Move to the next character in the key (cyclic).
 * 6. Return the decrypted message.
 *
 * @param encryptedData The encrypted message to decrypt.
 * @param secretKey The keyword used for decryption.
 * @throws IllegalArgumentException if the key is empty.
 * @return The decrypted plaintext message.
 */
public String decrypt(final String encryptedData, final String secretKey) {
if (secretKey.isEmpty()) {
throw new IllegalArgumentException("Key cannot be empty.");
}
StringBuilder decryptedOutput = new StringBuilder();
int keyPosition = 0;
for (int charIndex = 0; charIndex < encryptedData.length(); charIndex++) {
char currentChar = encryptedData.charAt(charIndex);
if (Character.isLetter(currentChar)) {
if (Character.isUpperCase(currentChar)) {
decryptedOutput.append((char) ('Z' - (25 - (currentChar - secretKey.toUpperCase().charAt(keyPosition))) % 26));
} else {
decryptedOutput.append((char) ('z' - (25 - (currentChar - secretKey.toLowerCase().charAt(keyPosition))) % 26));
}
keyPosition = ++keyPosition % secretKey.length();
} else {
decryptedOutput.append(currentChar);
}
}
return decryptedOutput.toString();
}
}

package MyComplex;

/**
 * A mutable complex number with basic arithmetic operations.
 */
public class MyComplex {
    private double re;
    private double im;

    public MyComplex() {
    }

    public MyComplex(double re, double im) {
        this.re = re;
        this.im = im;
    }

    public double getReal() {
        return re;
    }

    public void setReal(double re) {
        this.re = re;
    }

    public double getImag() {
        return im;
    }

    public void setImag(double im) {
        this.im = im;
    }

    @Override
    public String toString() {
        return "(" + re + "+" + im + "i)";
    }

    public boolean isReal() {
        return re == 0;
    }

    public boolean isImaginary() {
        return im == 0;
    }

    public boolean equals(double re, double im) {
        return this.re == re && this.im == im;
    }

    public boolean equals(MyComplex other) {
        return this.re == other.re && this.im == other.im;
    }

    public double Magnitude() {
        return Math.sqrt(re * re + im * im);
    }

    public double argument() {
        return Math.atan2(im, re);
    }

    public MyComplex addInto(MyComplex right) {
        re += right.re;
        im += right.im;
        return this;
    }

    public MyComplex add(MyComplex right) {
        re += right.re;
        im += right.im;
        return this;
    }

    public MyComplex addNew(MyComplex right) {
        return new MyComplex(re + right.re, im + right.im);
    }

    public MyComplex subtract(MyComplex right) {
        re -= right.re;
        im -= right.im;
        return this;
    }

    public MyComplex subtractNew(MyComplex right) {
        return new MyComplex(re - right.re, im - right.im);
    }

    public MyComplex multiply(MyComplex right) {
        // Note: mirrors the original's order of updates, where the
        // imaginary part is computed from the already-updated real part.
        re = re * right.re - im * right.im;
        im = re * right.im + im * right.re;
        return this;
    }

    public MyComplex divide(MyComplex right) {
        double denom = Math.pow(right.re, 2) + Math.pow(right.im, 2);
        re = (re * right.re + im * right.im) / denom;
        im -= (im * right.re - re * right.im) / denom;
        return this;
    }

    public MyComplex conjugate() {
        im *= -1;
        return this;
    }
}

class TestMyComplex {
    public static void main(String[] args) {
    }
}

