package workshop6;

import java.util.Scanner;
import java.util.regex.Pattern;

/**
 *
 * @author giaki
 */
public class Inputter {

    public static Scanner scanner = new Scanner(System.in);

    public static int inputInt(String msg, int min, int max) {
        if (min > max) {
            int z = min;
            min = max;
            max = z;
        }
        int data;
        do {
            System.out.print(msg);
            data = Integer.parseInt(scanner.nextLine());
        } while (data < min || data > max);
        return data;
    }

    public static String inputStr(String msg) {
        System.out.print(msg);
        String data = scanner.nextLine().trim();
        return data;
    }

    public static String inputNonBlankStr(String msg) {
        String data = null;
        do {
            System.out.print(msg);
            data = scanner.nextLine().trim();
        } while (data.length() == 0 || data == null);
        return data;
    }

    public static String inputPattern(String msg, String pattern) {
        String data = null;
        do {
            System.out.print(msg);
            data = scanner.nextLine().trim();
        } while (!data.matches(pattern));
        return data;
    }
}

/*
 * Represents a customer's bank account.
 * Wraps the account number, balance and account category behind
 * private fields, exposing only controlled operations.
 */
public class BankaHesabi {

	private int accountId;
	private double currentBalance;
	private String accountCategory; // e.g. "Vadesiz" (checking) or "Vadeli" (term deposit)

	public BankaHesabi(int accountId, double currentBalance, String accountCategory) {
		this.accountId = accountId;
		this.currentBalance = currentBalance;
		this.accountCategory = accountCategory;
	}

	public int getHesapNumarasi() {
		return accountId;
	}

	public double getBakiye() {
		return currentBalance;
	}

	public String getHesapTuru() {
		return accountCategory;
	}

	/**
	 * Deposits funds into the account, rejecting non-positive amounts.
	 */
	public void paraYatir(double amount) {
		boolean isValid = amount > 0;
		if (isValid) {
			currentBalance = currentBalance + amount;
			System.out.println(amount + " TL yatirildi. Yeni bakiye: " + currentBalance);
		} else {
			System.out.println("Yatirilan miktar gecersiz.");
		}
	}

	/**
	 * Withdraws funds, checking both validity and sufficient balance.
	 */
	public void paraCek(double amount) {
		if (amount > 0 && amount <= currentBalance) {
			currentBalance = currentBalance - amount;
			System.out.println(amount + " TL cekildi. Kalan bakiye: " + currentBalance);
		} else if (amount > currentBalance) {
			System.out.println("Yetersiz bakiye.");
		} else {
			System.out.println("cekilen miktar gecersiz.");
		}
	}

	/**
	 * Applies interest only when the account is a term ("Vadeli") account.
	 */
	public void faizEkle(double rate) {
		boolean isTermAccount = accountCategory.equals("Vadeli");
		if (isTermAccount && rate > 0) {
			double interestAmount = currentBalance * rate / 100;
			currentBalance += interestAmount;
			System.out.println("Faiz ekleniyor: " + interestAmount + " TL. Yeni bakiye: " + currentBalance);
		} else if (!isTermAccount) {
			System.out.println("Faiz yalnizca vadeli hesaplarda uygulanabilir.");
		} else {
			System.out.println("Gecersiz faiz orani.");
		}
	}

	/**
	 * Moves money from this account into another BankaHesabi instance.
	 */
	public void transfer(BankaHesabi receivingAccount, double amount) {
		if (amount > 0 && amount <= currentBalance) {
			currentBalance -= amount;
			receivingAccount.paraYatir(amount);
			System.out.println(amount + " TL transfer edildi. Yeni bakiye: " + currentBalance);
		} else {
			System.out.println("Yetersiz bakiye veya gecersiz miktar.");
		}
	}
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

/**
 * Push–Relabel (Relabel-to-Front variant simplified to array scanning) for maximum flow.
 *
 * <p>Input graph is a capacity matrix where {@code capacity[u][v]} is the capacity of the edge
 * {@code u -> v}. Capacities must be non-negative. Vertices are indexed in {@code [0, n)}.
 *
 * <p>Time complexity: O(V^3) in the worst case for the array-based variant; typically fast in
 * practice. This implementation uses a residual network over an adjacency-matrix representation.
 *
 * <p>The API mirrors {@link EdmondsKarp#maxFlow(int[][], int, int)} and {@link Dinic#maxFlow(int[][], int, int)}.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Push%E2%80%93relabel_maximum_flow_algorithm">Wikipedia: Push–Relabel maximum flow algorithm</a>
 */
public final class PushRelabel {

    private PushRelabel() {
    }

    /**
     * Computes the maximum flow from {@code source} to {@code sink} using Push–Relabel.
     *
     * @param capacity square capacity matrix (n x n); entries must be >= 0
     * @param source source vertex index in [0, n)
     * @param sink sink vertex index in [0, n)
     * @return the maximum flow value
     * @throws IllegalArgumentException if inputs are invalid
     */
    public static int maxFlow(int[][] capacity, int source, int sink) {
        validate(capacity, source, sink);
        final int n = capacity.length;
        if (source == sink) {
            return 0;
        }

        int[][] residual = new int[n][n];
        for (int i = 0; i < n; i++) {
            residual[i] = Arrays.copyOf(capacity[i], n);
        }

        int[] height = new int[n];
        int[] excess = new int[n];
        int[] nextNeighbor = new int[n];

        // Preflow initialization
        height[source] = n;
        for (int v = 0; v < n; v++) {
            int cap = residual[source][v];
            if (cap > 0) {
                residual[source][v] -= cap;
                residual[v][source] += cap;
                excess[v] += cap;
                excess[source] -= cap;
            }
        }

        // Active queue contains vertices (except source/sink) with positive excess
        Queue<Integer> active = new ArrayDeque<>();
        for (int v = 0; v < n; v++) {
            if (v != source && v != sink && excess[v] > 0) {
                active.add(v);
            }
        }

        State state = new State(residual, height, excess, nextNeighbor, source, sink, active);

        while (!active.isEmpty()) {
            int u = active.poll();
            discharge(u, state);
            if (excess[u] > 0) {
                // still active after discharge; push to back
                active.add(u);
            }
        }

        // Total flow equals excess at sink
        return excess[sink];
    }

    private static void discharge(int u, State s) {
        final int n = s.residual.length;
        while (s.excess[u] > 0) {
            if (s.nextNeighbor[u] >= n) {
                relabel(u, s.residual, s.height);
                s.nextNeighbor[u] = 0;
                continue;
            }
            int v = s.nextNeighbor[u];
            if (s.residual[u][v] > 0 && s.height[u] == s.height[v] + 1) {
                int delta = Math.min(s.excess[u], s.residual[u][v]);
                s.residual[u][v] -= delta;
                s.residual[v][u] += delta;
                s.excess[u] -= delta;
                int prevExcessV = s.excess[v];
                s.excess[v] += delta;
                if (v != s.source && v != s.sink && prevExcessV == 0) {
                    s.active.add(v);
                }
            } else {
                s.nextNeighbor[u]++;
            }
        }
    }

    private static final class State {
        final int[][] residual;
        final int[] height;
        final int[] excess;
        final int[] nextNeighbor;
        final int source;
        final int sink;
        final Queue<Integer> active;

        State(int[][] residual, int[] height, int[] excess, int[] nextNeighbor, int source, int sink, Queue<Integer> active) {
            this.residual = residual;
            this.height = height;
            this.excess = excess;
            this.nextNeighbor = nextNeighbor;
            this.source = source;
            this.sink = sink;
            this.active = active;
        }
    }

    private static void relabel(int u, int[][] residual, int[] height) {
        final int n = residual.length;
        int minHeight = Integer.MAX_VALUE;
        for (int v = 0; v < n; v++) {
            if (residual[u][v] > 0) {
                minHeight = Math.min(minHeight, height[v]);
            }
        }
        if (minHeight < Integer.MAX_VALUE) {
            height[u] = minHeight + 1;
        }
    }

    private static void validate(int[][] capacity, int source, int sink) {
        if (capacity == null || capacity.length == 0) {
            throw new IllegalArgumentException("Capacity matrix must not be null or empty");
        }
        int n = capacity.length;
        for (int i = 0; i < n; i++) {
            if (capacity[i] == null || capacity[i].length != n) {
                throw new IllegalArgumentException("Capacity matrix must be square");
            }
            for (int j = 0; j < n; j++) {
                if (capacity[i][j] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative");
                }
            }
        }
        if (source < 0 || sink < 0 || source >= n || sink >= n) {
            throw new IllegalArgumentException("Source and sink must be valid vertex indices");
        }
    }
}

/**
 * A circle whose center is a MovablePoint, implementing Movable.
 */
public class MovableCircle implements Movable {
    private int radius;
    private MovablePoint center;

    public MovableCircle() {
    }

    public MovableCircle(int radius, MovablePoint center) {
        this.radius = radius;
        this.center = center;
    }

    public MovableCircle(int x, int y, int xSpeed, int ySpeed, int radius) {
        this.radius = radius;
        this.center = new MovablePoint(x, y, xSpeed, ySpeed);
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }

    public MovablePoint getCenter() {
        return center;
    }

    public void setCenter(MovablePoint center) {
        this.center = center;
    }

    @Override
    public String toString() {
        return center + ",radius=" + radius;
    }

    @Override
    public void moveUp() {
        center.setY(center.getY() - center.getySpeed());
    }

    @Override
    public void moveDown() {
        center.setY(center.getY() + center.getySpeed());
    }

    @Override
    public void moveLeft() {
        center.setX(center.getX() - center.getxSpeed());
    }

    @Override
    public void moveRight() {
        center.setX(center.getX() + center.getxSpeed());
    }
}

package com.thealgorithms.dynamicprogramming;

public final class SubsetSum {
    private SubsetSum() {
    }

    /**
     * Test if a set of integers contains a subset that sums to a given integer.
     *
     * @param arr the array containing integers.
     * @param sum the target sum of the subset.
     * @return {@code true} if a subset exists that sums to the given value,
     *         otherwise {@code false}.
     */
    public static boolean subsetSum(int[] arr, int sum) {
        int n = arr.length;

        // Initialize a single array to store the possible sums
        boolean[] isSum = new boolean[sum + 1];

        // Mark isSum[0] = true since a sum of 0 is always possible with 0 elements
        isSum[0] = true;

        // Iterate through each Element in the array
        for (int i = 0; i < n; i++) {
            // Traverse the isSum array backwards to prevent overwriting values
            for (int j = sum; j >= arr[i]; j--) {
                isSum[j] = isSum[j] || isSum[j - arr[i]];
            }
        }
        return isSum[sum];
    }
}

/**
 * Utility class to compute the ceiling of a given number.
 */
public final class Ceil {

    private Ceil() {
    }

    /**
     * Returns the smallest double value that is greater than or equal to the input.
     * Equivalent to mathematical ⌈x⌉ (ceiling function).
     *
     * @param number the number to ceil
     * @return the smallest double greater than or equal to {@code number}
     */
    public static double ceil(double number) {
        if (Double.isNaN(number) || Double.isInfinite(number) || number == 0.0 || number < Integer.MIN_VALUE || number > Integer.MAX_VALUE) {
            return number;
        }

        if (number < 0.0 && number > -1.0) {
            return -0.0;
        }

        long intPart = (long) number;
        if (number > 0 && number != intPart) {
            return intPart + 1.0;
        } else {
            return intPart;
        }
    }
}

/*
 * Bu kod, minimum 8 karakter ve maksimum 12 karakter iceren bir rastgele sifre olusturur. 
 * Sifre en az bir buyuk harf, bir rakam ve bir ozel karakter icermektedir:
 */

public class SifreUreteci {

    public static String sifreUret() {

        String buyukHarfler = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"; // Buyuk harfler
        String rakamlar = "0123456789"; // Rakamlar
        String ozelKarakterler = "!@#$%^&*()_+-=[]{}|;':\"<>,.?/\\"; // Ozel karakterler

        Random rastgele = new Random();

        int uzunluk = 8 + rastgele.nextInt(5); // 8 ile 12 arasinda rastgele bir uzunluk belirlenir
        String sifre = "";

        // Her bir karakter grubundan rastgele bir karakter secilir ve sifreye eklenir
        sifre += buyukHarfler.charAt(rastgele.nextInt(buyukHarfler.length()));
        sifre += rakamlar.charAt(rastgele.nextInt(rakamlar.length()));
        sifre += ozelKarakterler.charAt(rastgele.nextInt(ozelKarakterler.length()));

        // Geriye kalan karakterler rastgele secilir
        for (int i = 0; i < uzunluk - 3; i++) {
            String karakterler = buyukHarfler + rakamlar + ozelKarakterler + buyukHarfler.toLowerCase();
            sifre += karakterler.charAt(rastgele.nextInt(karakterler.length()));
        }

        return stringKaristir(sifre); // Sifreyi karistir ve dondur
    }

    public static String stringKaristir(String sifre) {

        char[] dizi = sifre.toCharArray();
        Random rastgele = new Random();
        for (int i = dizi.length - 1; i > 0; i--) {
            int index = rastgele.nextInt(i); // Rastgele bir index sec
            char temp = dizi[index];
            dizi[index] = dizi[i];
            dizi[i] = temp;
        }
        return new String(dizi);
    }

    public static void main(String[] args) {
        System.out.println(sifreUret()); // Rastgele sifreyi yazdir
    }
}

