 */
public class Exchange {

    public static ArrayList<String> listRates = new ArrayList<String>();

    public static void createRete() {
        listRates.add("USD;VND;17000");
        listRates.add("EUR;USD;1.2");
        listRates.add("USD;IDN;15789");
        listRates.add("USD;EUR;0.83");
        listRates.add("CAD;IDN;16869");
    }

    public double convert(String code1, String code2, double amount) {
        createRete();
        for (String rateString : listRates) {
            StringTokenizer tokenizer = new StringTokenizer(rateString, ";");
            String tokenizer_code1 = tokenizer.nextToken();
            String tokenizer_code2 = tokenizer.nextToken();
            Double tokenizer_amount = Double.parseDouble(tokenizer.nextToken());
            if (code1.toLowerCase().equals(tokenizer_code1.toLowerCase()) && code2.toLowerCase().equals(tokenizer_code2.toLowerCase())) {
                return tokenizer_amount * amount;
            }
        }
        System.out.println("Can not found code!!!!");
        return amount;
    }
}

package Container;

/**
 * A bouncing ball, moved and reflected by a Container.
 */
class Ball {

    private float posX;
    private float posY;
    private int radius;
    private float speedX;
    private float speedY;

    public Ball(float posX, float posY, int radius, float speedX, float speedY) {
        this.posX = posX;
        this.posY = posY;
        this.radius = radius;
        this.speedX = speedX;
        this.speedY = speedY;
    }

    public Ball(float posX, float posY, int radius, int speed, int direction) {
        this.posX = posX;
        this.posY = posY;
        this.radius = radius;
        this.speedX = speed * (float) Math.cos(Math.toRadians(direction));
        this.speedY = -speed * (float) Math.sin(Math.toRadians(direction));
    }

    public float getX() {
        return posX;
    }

    public void setX(float posX) {
        this.posX = posX;
    }

    public float getY() {
        return posY;
    }

    public void setY(float posY) {
        this.posY = posY;
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }

    public float getXDelta() {
        return speedX;
    }

    public void setXDelta(float speedX) {
        this.speedX = speedX;
    }

    public float getYDelta() {
        return speedY;
    }

    public void setYDelta(float speedY) {
        this.speedY = speedY;
    }

    public int getSpeed() {
        return (int) Math.sqrt(speedX * speedX + speedY * speedY);
    }

    public int getDirection() {
        return (int) Math.toDegrees(Math.atan2(-speedY, speedX));
    }

    public void setXY(int posX, int posY) {
        this.posX = posX;
        this.posY = posY;
    }

    public void move() {
        posX += speedX;
        posY += speedY;
    }

    public void reflectHorizontal() {
        speedX = -speedX;
    }

    public void reflectVertical() {
        speedY = -speedY;
    }

    @Override
    public String toString() {
        return "Ball[(" + posX + "," + posY + "),speed=(" + speedX + "," + speedY + ")]";
    }
}

public class Container {

    private int left;
    private int top;
    private int right;
    private int bottom;

    public Container(int left, int top, int width, int height) {
        this.left = left;
        this.top = top;
        this.right = left + width - 1;
        this.bottom = top + height - 1;
    }

    public int getX1() {
        return left;
    }

    public void setX1(int left) {
        this.left = left;
    }

    public int getY1() {
        return top;
    }

    public void setY1(int top) {
        this.top = top;
    }

    public int getX2() {
        return right;
    }

    public void setX2(int right) {
        this.right = right;
    }

    public int getY2() {
        return bottom;
    }

    public void setY2(int bottom) {
        this.bottom = bottom;
    }

    public int getX() {
        return left;
    }

    public int getY(int y2) {
        return top;
    }

    public int getWidth() {
        return right - left + 1;
    }

    public int getHeight() {
        return bottom - top + 1;
    }

    public boolean collides(Ball ball) {
        boolean hit = ball.getX() - ball.getRadius() <= left || ball.getX() - ball.getRadius() >= right;
        if (hit) {
            ball.reflectHorizontal();
        }
        return hit;
    }

    public boolean collidesWith(Ball ball) {
        boolean hit = ball.getX() - ball.getRadius() <= left || ball.getX() - ball.getRadius() >= right;
        if (hit) {
            ball.reflectHorizontal();
        }
        return hit;
    }

    @Override
    public String toString() {
        return "Container[(" + left + "," + top + "),(" + right + "," + bottom + ")]";
    }
}

class TestContainer {
    public static void main(String[] args) {
        Ball ball = new Ball(50, 50, 5, 10, 30);
        Container box = new Container(0, 0, 100, 100);
        System.out.println(box.getHeight());
        System.out.println(box.getWidth());
        for (int step = 0; step < 10; ++step) {
            ball.move();
            box.collidesWith(ball);
            System.out.println(ball);
        }
    }
}

