/**
 * The Needleman–Wunsch algorithm performs global sequence alignment between two strings.
 * It computes the optimal alignment score using dynamic programming,
 * given a scoring scheme for matches, mismatches, and gaps.
 *
 * Time Complexity: O(n * m)
 * Space Complexity: O(n * m)
 */
public final class NeedlemanWunsch {

    private NeedlemanWunsch() {
        // Utility Class
    }

    /**
     * Computes the Needleman–Wunsch global alignment score between two strings.
     *
     * @param s1 the first string
     * @param s2 the second string
     * @param matchScore score for a character match
     * @param mismatchPenalty penalty for a mismatch (should be negative)
     * @param gapPenalty penalty for inserting a gap (should be negative)
     * @return the optimal alignment score
     */
    public static int align(String s1, String s2, int matchScore, int mismatchPenalty, int gapPenalty) {
        if (s1 == null || s2 == null) {
            throw new IllegalArgumentException("Input strings must not be null.");
        }

        int n = s1.length();
        int m = s2.length();

        int[][] dp = new int[n + 1][m + 1];

        // Initialize gap penalties for first row and column
        for (int i = 0; i <= n; i++) {
            dp[i][0] = i * gapPenalty;
        }
        for (int j = 0; j <= m; j++) {
            dp[0][j] = j * gapPenalty;
        }

        // Fill the DP matrix
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                int matchOrMismatch = (s1.charAt(i - 1) == s2.charAt(j - 1)) ? matchScore : mismatchPenalty;

                dp[i][j] = Math.max(Math.max(dp[i - 1][j - 1] + matchOrMismatch, // match/mismatch
                                        dp[i - 1][j] + gapPenalty // deletion (gap in s2)
                                        ),
                    dp[i][j - 1] + gapPenalty // insertion (gap in s1)
                );
            }
        }

        return dp[n][m];
    }
}

package com.thealgorithms.conversions;

/**
 * A utility class to convert integers into Roman numerals.
 *
 * <p>Roman numerals follow these rules:
 * <ul>
 *   <li>I = 1</li>
 *   <li>IV = 4</li>
 *   <li>V = 5</li>
 *   <li>IX = 9</li>
 *   <li>X = 10</li>
 *   <li>XL = 40</li>
 *   <li>L = 50</li>
 *   <li>XC = 90</li>
 *   <li>C = 100</li>
 *   <li>D = 500</li>
 *   <li>M = 1000</li>
 * </ul>
 *
 * <p>Conversion is based on repeatedly subtracting the largest possible Roman numeral value
 * from the input number until it reaches zero. For example, 1994 is converted as:
 * <pre>
 *   1994 -> MCMXCIV (1000 + 900 + 90 + 4)
 * </pre>
 */
public final class IntegerToRoman {

    // Array of Roman numeral values in descending order
    private static final int[] ALL_ROMAN_NUMBERS_IN_ARABIC = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};

    // Corresponding Roman numeral symbols
    private static final String[] ALL_ROMAN_NUMBERS = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};

    private IntegerToRoman() {
    }

    /**
     * Converts an integer to its Roman numeral representation.
     * Steps:
     * <ol>
     *     <li>Iterate over the Roman numeral values in descending order</li>
     *     <li>Calculate how many times a numeral fits</li>
     *     <li>Append the corresponding symbol</li>
     *     <li>Subtract the value from the number</li>
     *     <li>Repeat until the number is zero</li>
     *     <li>Return the Roman numeral representation</li>
     * </ol>
     *
     * @param num the integer value to convert (must be greater than 0)
     * @return the Roman numeral representation of the input integer
     *         or an empty string if the input is non-positive
     */
    public static String integerToRoman(int num) {
        if (num <= 0) {
            return "";
        }

        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < ALL_ROMAN_NUMBERS_IN_ARABIC.length; i++) {
            int times = num / ALL_ROMAN_NUMBERS_IN_ARABIC[i];
            builder.append(ALL_ROMAN_NUMBERS[i].repeat(Math.max(0, times)));
            num -= times * ALL_ROMAN_NUMBERS_IN_ARABIC[i];
        }

        return builder.toString();
    }
}

