}

public class Faktoriyel {

    // Verilen sayinin faktoriyelini hesaplayip dondurur
    int faktoriyelHesapla(int deger) {
        int carpim = 1; // notr eleman ile baslatilir
        for (; deger > 0; deger--) {
            carpim *= deger; // her adimda mevcut degerle carpilir
        }
        return carpim;
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);

        System.out.println("Lutfen bir sayi giriniz");
        int girilenDeger = tarayici.nextInt();

        Faktoriyel hesaplayici = new Faktoriyel();

        int sonuc = hesaplayici.faktoriyelHesapla(girilenDeger);
        System.out.println("Sonuc = " + sonuc);

        tarayici.close();
    }
}

package com.thealgorithms.audiofilters;

/**
 * Exponential Moving Average (EMA) Filter for smoothing audio signals.
 *
 * <p>This filter applies an exponential moving average to a sequence of audio
 * signal values, making it useful for smoothing out rapid fluctuations.
 * The smoothing factor (alpha) controls the degree of smoothing.
 *
 * <p>Based on the definition from
 * <a href="https://en.wikipedia.org/wiki/Moving_average">Wikipedia link</a>.
 * 
 * <p><b>Application Example:</b>
 * <pre>
 * // Reduce noise in audio signal
 * double[] noisyAudio = {0.5, 0.8, 0.3, 0.9, 0.2};
 * EMAFilter smoother = new EMAFilter(0.3);
 * double[] smoothedAudio = smoother.apply(noisyAudio);
 * </pre>
 * 
 * @author The Algorithms Project
 * @version 1.0
 * @see <a href="https://en.wikipedia.org/wiki/Exponential_smoothing">Exponential Smoothing</a>
 */
public class EMAFilter {

    // Smoothing factor (alpha) - determines how much weight is given to new samples
    // Range: 0 < alpha <= 1
    // - Higher alpha = less smoothing (follows original signal closely)
    // - Lower alpha = more smoothing (stronger noise reduction)
    private final double smoothingFactor;

    // Current EMA value (state) - persists between apply() calls for continuous processing
    private double currentEmaValue;

    /**
     * Constructs an EMA filter with a specified smoothing factor.
     *
     * @param alphaValue Smoothing factor (0 < alphaValue <= 1)
     *                   Typical values: 0.1 (heavy smoothing), 0.5 (medium), 0.9 (light smoothing)
     * @throws IllegalArgumentException if alphaValue is outside the valid range (0, 1]
     */
    public EMAFilter(double alphaValue) {
        // Validate input parameter
        if (alphaValue <= 0 || alphaValue > 1) {
            throw new IllegalArgumentException(
                "Invalid smoothing factor: " + alphaValue + 
                ". Alpha must be between 0 and 1 (exclusive of 0, inclusive of 1)."
            );
        }
        this.smoothingFactor = alphaValue;
        this.currentEmaValue = 0.0; // Initialize EMA value (will be set on first sample)
    }

    /**
     * Applies the EMA filter to an entire audio signal array.
     * 
     * <p>The filter processes the signal one sample at a time using the recurrence relation:
     * <br>EMA(t) = α × signal(t) + (1-α) × EMA(t-1)
     * 
     * <p>The first sample is used as-is (EMA[0] = signal[0])
     *
     * @param audioSignal Raw audio signal array to be processed (must not be null)
     * @return Array of smoothed audio samples (same length as input)
     * @throws NullPointerException if audioSignal is null
     */
    public double[] apply(double[] audioSignal) {
        // Handle empty input gracefully
        if (audioSignal.length == 0) {
            return new double[0]; // Return empty array for empty input
        }

        // Create output array for smoothed results
        double[] smoothedSignal = new double[audioSignal.length];

        // Initialize EMA with the first sample (no smoothing applied to first value)
        currentEmaValue = audioSignal[0];
        smoothedSignal[0] = currentEmaValue;

        // Apply EMA recurrence formula for remaining samples
        for (int sampleIndex = 1; sampleIndex < audioSignal.length; sampleIndex++) {
            // EMA recurrence: new_value = α × current_sample + (1-α) × previous_EMA
            currentEmaValue = smoothingFactor * audioSignal[sampleIndex] + 
                              (1 - smoothingFactor) * currentEmaValue;
            smoothedSignal[sampleIndex] = currentEmaValue;
        }

        return smoothedSignal;
    }

    /**
     * Resets the internal EMA state to zero.
     * Use this method when starting to process a new, independent audio stream
     * to avoid carrying over previous signal influence.
     */
    public void resetState() {
        currentEmaValue = 0.0;
    }

    /**
     * Processes a single audio sample and returns the filtered result.
     * This method maintains state between calls, making it suitable for
     * real-time streaming audio processing.
     *
     * @param inputSample Raw audio sample value
     * @return Filtered (smoothed) sample value
     */
    public double processSample(double inputSample) {
        // If this is the first sample after reset, EMA = inputSample
        if (currentEmaValue == 0.0) {
            currentEmaValue = inputSample;
        } else {
            // Apply standard EMA recurrence
            currentEmaValue = smoothingFactor * inputSample + 
                              (1 - smoothingFactor) * currentEmaValue;
        }
        return currentEmaValue;
    }

    /**
     * Returns the current smoothing factor (alpha value).
     *
     * @return Current smoothing factor in range (0, 1]
     */
    public double getSmoothingFactor() {
        return smoothingFactor;
    }

    /**
     * Returns the current EMA value (internal state).
     * Useful for debugging or monitoring filter behavior.
     *
     * @return Current EMA value
     */
    public double getCurrentEmaValue() {
        return currentEmaValue;
    }
}

/*
COMPREHENSIVE TECHNICAL DOCUMENTATION
=====================================

EXPONENTIAL MOVING AVERAGE (EMA) FILTER
---------------------------------------

Mathematical Formula:
---------------------
EMA[t] = α × X[t] + (1-α) × EMA[t-1]

Where:
- EMA[t] = Filtered output at time t
- X[t]   = Raw input sample at time t
- α      = Smoothing factor (alpha) - determines filter responsiveness

How EMA Filter Works:
---------------------
1. Maintains a running average that weights recent samples more heavily
2. Older samples have exponentially decreasing influence
3. Unlike Simple Moving Average (SMA), EMA doesn't require storing a history window

Alpha Value Guidelines (Audio Applications):
--------------------------------------------
| Alpha Value | Smoothing Effect | Best For                           |
|-------------|------------------|------------------------------------|
| 0.05 - 0.1  | Heavy smoothing  | Strong noise reduction, slow changes|
| 0.2 - 0.3   | Moderate smoothing | General purpose, speech smoothing |
| 0.4 - 0.6   | Light smoothing  | Music, preserving transients       |
| 0.7 - 0.9   | Very light       | Quick response, minimal filtering  |
| 1.0         | No smoothing     | Passthrough (no effect)            |

Time Constant Relationship:
---------------------------
The relationship between alpha and time constant (τ):
α = 1 - e^(-T/τ), where T is the sampling period

For a given α, the effective window length (N) approximately:
N ≈ (2/α) - 1 samples

Example: α = 0.2 → effective window ≈ 9 samples

State Persistence Behavior:
---------------------------
- The filter maintains state (currentEmaValue) between apply() calls
- Process multiple chunks sequentially without losing history
- Use resetState() to start fresh when processing independent signals

Performance Characteristics:
----------------------------
- Time Complexity: O(n) per apply() call
- Space Complexity: O(n) for output array, O(1) for internal state
- Memory efficient: No need to store sample history

Common Audio Applications:
--------------------------
1. Envelope following (volume smoothing)
2. Noise gate smoothing
3. Parameter smoothing (avoiding sudden gain jumps)
4. Visualizing audio levels (VU meters)
5. Real-time audio effect parameter filtering

Physical Interpretation:
------------------------
EMA behaves like a first-order low-pass filter (RC circuit analog):
- α = 1 corresponds to no capacitor (pure resistor)
- α → 0 corresponds to infinite capacitor (heavy filtering)

Comparison with Other Filters:
-----------------------------
| Filter Type    | Advantages                    | Disadvantages                 |
|----------------|-------------------------------|-------------------------------|
| EMA (this)     | Simple, memory efficient      | Not symmetric (phase delay)   |
| SMA            | Simple, symmetric| Requires storage of N samples |
| Butterworth    | Very smooth, flat response    | Complex to implement          |
| Median Filter  | Excellent for impulse noise   | Higher computational cost     |
*/

package eamples;

import java.util.Scanner;

public class OgrenciNumarasi {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Ogrenci numarasini giriniz:");
        int studentId = input.nextInt();

        // The leading two digits encode the enrollment year (offset from 2000).
        int enrollmentYear = studentId / 10000000 + 2000;
        System.out.println("Kayit yili: " + enrollmentYear);

        // The trailing three digits encode the student's registration order.
        int registrationOrder = studentId % 1000;
        System.out.println("Kayit sirasi: " + registrationOrder);

        // The fifth digit encodes the department code.
        int departmentCode = studentId / 100000 % 10;

        String departmentName;
        switch (departmentCode) {
            case 7:
                departmentName = "Elektrik Elektronik";
                break;
            case 6:
                departmentName = "Bilgisayar";
                break;
            case 5:
                departmentName = "Makina";
                break;
            default:
                departmentName = null;
        }

        if (departmentName != null) {
            System.out.println("Bolum: " + departmentName);
        } else {
            System.out.println("Bilinmeyen bolum");
        }

        input.close();
    }
}

package com.thealgorithms.bitmanipulation;

/**
 * A utility class for performing single-bit operations on integers.
 * These operations include flipping, setting, clearing, and getting
 * individual bits at specified positions.
 *
 * Bit positions are zero-indexed (i.e., the least significant bit is at position 0).
 * These methods leverage bitwise operations for optimal performance.
 *
 * Examples:
 * - `flipBit(3, 1)` flips the bit at index 1 in binary `11` (result: `1`).
 * - `setBit(4, 0)` sets the bit at index 0 in `100` (result: `101` or 5).
 * - `clearBit(7, 1)` clears the bit at index 1 in `111` (result: `101` or 5).
 * - `getBit(6, 0)` checks if the least significant bit is set (result: `0`).
 *
 * Time Complexity: O(1) for all operations.
 *
 * Author: lukasb1b (https://github.com/lukasb1b)
 */
public final class SingleBitOperations {
private SingleBitOperations() {
}

/**
 * Flips (toggles) the bit at the specified position.
 *
 * @param inputNumber the input number
 * @param bitPosition the position of the bit to flip (0-indexed)
 * @return the new number after flipping the specified bit
 */
public static int flipBit(final int inputNumber, final int bitPosition) {
return inputNumber ^ (1 << bitPosition);
}

/**
 * Sets the bit at the specified position to 1.
 *
 * @param inputNumber the input number
 * @param bitPosition the position of the bit to set (0-indexed)
 * @return the new number after setting the specified bit to 1
 */
public static int setBit(final int inputNumber, final int bitPosition) {
return inputNumber | (1 << bitPosition);
}

/**
 * Clears the bit at the specified position (sets it to 0).
 *
 * @param inputNumber the input number
 * @param bitPosition the position of the bit to clear (0-indexed)
 * @return the new number after clearing the specified bit
 */
public static int clearBit(final int inputNumber, final int bitPosition) {
return inputNumber & ~(1 << bitPosition);
}

/**
 * Gets the bit value (0 or 1) at the specified position.
 *
 * @param inputNumber the input number
 * @param bitPosition the position of the bit to retrieve (0-indexed)
 * @return 1 if the bit is set, 0 otherwise
 */
public static int getBit(final int inputNumber, final int bitPosition) {
return (inputNumber >> bitPosition) & 1;
}
}

