package com.thealgorithms.datastructures.hashmap.hashing;

/**
 * Immutable HashMap implementation using separate chaining.
 *
 * <p>This HashMap does not allow modification of existing instances.
 * Any update operation returns a new ImmutableHashMap.
 *
 * @param <KeyType> key type
 * @param <ValueType> value type
 */
public final class ImmutableHashMap<KeyType, ValueType> {

private static final int INITIAL_BUCKETS = 16;

private final HashNode<KeyType, ValueType>[] bucketArray;
private final int totalEntries;

/**
 * Private constructor to enforce immutability.
 */
private ImmutableHashMap(HashNode<KeyType, ValueType>[] bucketArray, int totalEntries) {
this.bucketArray = bucketArray;
this.totalEntries = totalEntries;
}

/**
 * Creates an empty ImmutableHashMap.
 *
 * @param <KeyType> key type
 * @param <ValueType> value type
 * @return empty ImmutableHashMap
 */
@SuppressWarnings({"unchecked", "rawtypes"})
public static <KeyType, ValueType> ImmutableHashMap<KeyType, ValueType> emptyMap() {
HashNode<KeyType, ValueType>[] emptyBuckets = (HashNode<KeyType, ValueType>[]) new HashNode[INITIAL_BUCKETS];
return new ImmutableHashMap<>(emptyBuckets, 0);
}

/**
 * Returns a new ImmutableHashMap with the given key-value pair added.
 *
 * @param insertKey key to add
 * @param insertValue value to associate
 * @return new ImmutableHashMap instance
 */
public ImmutableHashMap<KeyType, ValueType> put(KeyType insertKey, ValueType insertValue) {
HashNode<KeyType, ValueType>[] expandedBuckets = bucketArray.clone();
int bucketPosition = computeHash(insertKey);
expandedBuckets[bucketPosition] = new HashNode<>(insertKey, insertValue, expandedBuckets[bucketPosition]);
return new ImmutableHashMap<>(expandedBuckets, totalEntries + 1);
}

/**
 * Retrieves the value associated with the given key.
 *
 * @param searchKey key to search
 * @return value if found, otherwise null
 */
public ValueType get(KeyType searchKey) {
int bucketPosition = computeHash(searchKey);
HashNode<KeyType, ValueType> currentNode = bucketArray[bucketPosition];
while (currentNode != null) {
if ((searchKey == null && currentNode.keyValue == null) || (searchKey != null && searchKey.equals(currentNode.keyValue))) {
return currentNode.storedValue;
}
currentNode = currentNode.nextNode;
}
return null;
}

/**
 * Checks whether the given key exists in the map.
 *
 * @param searchKey key to check
 * @return true if key exists, false otherwise
 */
public boolean containsKey(KeyType searchKey) {
return get(searchKey) != null;
}

/**
 * Returns the number of key-value pairs.
 *
 * @return size of the map
 */
public int getSize() {
return totalEntries;
}

/**
 * Computes hash index for a given key.
 */
private int computeHash(KeyType targetKey) {
return targetKey == null ? 0 : (targetKey.hashCode() & Integer.MAX_VALUE) % bucketArray.length;
}

/**
 * Node class for separate chaining.
 */
private static final class HashNode<KeyType, ValueType> {

private final KeyType keyValue;
private final ValueType storedValue;
private final HashNode<KeyType, ValueType> nextNode;

private HashNode(KeyType keyValue, ValueType storedValue, HashNode<KeyType, ValueType> nextNode) {
this.keyValue = keyValue;
this.storedValue = storedValue;
this.nextNode = nextNode;
}
}
}
