package overloading;

/*
 * Demonstrates method overloading: several "topla/cikar/carp/bol"
 * variants that accept different parameter types/counts.
 */
public class HesapMakinesi {

    int sonIslemSonucu = 0; // holds the result of the last add operation

    // Adds two integers, remembering the result.
    public int topla(int x, int y) {
        sonIslemSonucu = x + y;
        return sonIslemSonucu;
    }

    // Adds two doubles without touching memory.
    public double topla(double x, double y) {
        return x + y;
    }

    // Adds three integers together.
    public int topla(int x, int y, int z) {
        return x + y + z;
    }

    // Sums every element of an integer array.
    public int topla(int[] degerler) {
        int birikimSonucu = 0;
        for (int tekDeger : degerler) {
            birikimSonucu = birikimSonucu + tekDeger;
        }
        return birikimSonucu;
    }

    public int cikar(int x, int y) {
        return x - y;
    }

    public double cikar(double x, double y) {
        return x - y;
    }

    public int carp(int x, int y) {
        return x * y;
    }

    public double carp(double x, double y) {
        return x * y;
    }

    public int bol(int x, int y) {
        if (y == 0) {
            throw new ArithmeticException("Bolme islemi icin bolen sifir olamaz!");
        }
        return x / y;
    }

    public double bol(double x, double y) {
        if (y == 0.0) {
            throw new ArithmeticException("Bolme islemi icin bolen sifir olamaz!");
        }
        return x / y;
    }

    public static void main(String[] args) {
        HesapMakinesi makine = new HesapMakinesi();

        int toplamIkiTam = makine.topla(5, 3);
        double toplamIkiOndalik = makine.topla(3.5, 2.7);
        int toplamUcTam = makine.topla(4, 6, 8);

        int[] diziDegerleri = {1, 2, 3, 4, 5};
        int diziToplami = makine.topla(diziDegerleri);

        int cikarmaTam = makine.cikar(10, 4);
        double cikarmaOndalik = makine.cikar(7.8, 2.4);

        int carpmaTam = makine.carp(3, 5);
        double carpmaOndalik = makine.carp(2.5, 4.0);

        int bolmeTam = makine.bol(20, 4);
        double bolmeOndalik = makine.bol(9.0, 3.0);

        System.out.println("Sonuc 1: " + toplamIkiTam);
        System.out.println("Sonuc 2: " + toplamIkiOndalik);
        System.out.println("Sonuc 3: " + toplamUcTam);
        System.out.println("Sonuc 4 (Dizi toplama): " + diziToplami);
        System.out.println("Sonuc 5 (cikarma): " + cikarmaTam);
        System.out.println("Sonuc 6 (Double cikarma): " + cikarmaOndalik);
        System.out.println("Sonuc 7 (carpma): " + carpmaTam);
        System.out.println("Sonuc 8 (Double carpma): " + carpmaOndalik);
        System.out.println("Sonuc 9 (Bolme): " + bolmeTam);
        System.out.println("Sonuc 10 (Double bolme): " + bolmeOndalik);
    }
}

public class ioStream {
    public static void main(String[] args) {
        // Demonstrating InputStreamReader to read byte input from console as characters
        try (InputStreamReader consoleCharacterReader = new InputStreamReader(System.in)) {
            System.out.print("Please enter some text or numbers: ");
            int characterCode = consoleCharacterReader.read(); // reads first character as integer (ASCII/Unicode value)

            while(consoleCharacterReader.ready()) {
                System.out.print((char) characterCode); // convert integer back to character
                characterCode = consoleCharacterReader.read(); // move to next character in stream
            }
            consoleCharacterReader.close(); // explicitly close the stream (though try-with-resources does this automatically)
            System.out.println(); // add newline after output
        } catch (IOException readError) {
            System.out.println("An I/O error occurred: " + readError.getMessage());
        }
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * A Dynamic Programming solution for the Rod cutting problem.
 * Returns the best obtainable price for a rod of length n and price[] as prices of different pieces.
 */
public final class RodCutting {
    private RodCutting() {
    }

    /**
     * This method calculates the maximum obtainable value for cutting a rod of length n
     * into different pieces, given the prices for each possible piece length.
     *
     * @param price An array representing the prices of different pieces, where price[i-1]
     *              represents the price of a piece of length i.
     * @param n     The length of the rod to be cut.
     * @throws IllegalArgumentException if the price array is null or empty, or if n is less than 0.
     * @return The maximum obtainable value.
     */
    public static int cutRod(int[] price, int n) {
        if (price == null || price.length == 0) {
            throw new IllegalArgumentException("Price array cannot be null or empty.");
        }
        if (n < 0) {
            throw new IllegalArgumentException("Rod length cannot be negative.");
        }

        // Create an array to store the maximum obtainable values for each rod length.
        int[] val = new int[n + 1];
        val[0] = 0;

        // Calculate the maximum value for each rod length from 1 to n.
        for (int i = 1; i <= n; i++) {
            int maxVal = Integer.MIN_VALUE;
            // Try all possible ways to cut the rod and find the maximum value.
            for (int j = 1; j <= i; j++) {
                maxVal = Math.max(maxVal, price[j - 1] + val[i - j]);
            }
            // Store the maximum value for the current rod length.
            val[i] = maxVal;
        }

        // The final element of 'val' contains the maximum obtainable value for a rod of length 'n'.
        return val[n];
    }
}

package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.Map;

/**
 * A utility class to convert Roman numerals into integers.
 *
 * <p>Roman numerals are based on seven symbols given below:
 * <ul>
 *   <li>I = 1</li>
 *   <li>V = 5</li>
 *   <li>X = 10</li>
 *   <li>L = 50</li>
 *   <li>C = 100</li>
 *   <li>D = 500</li>
 *   <li>M = 1000</li>
 * </ul>
 *
 * <p>If a smaller numeral appears before a larger numeral, it is subtracted.
 * Otherwise, it is added. For example:
 * <pre>
 *   MCMXCIV = 1000 + (1000 - 100) + (100 - 10) + (5 - 1) = 1994
 * </pre>
 */
public final class RomanToInteger {

    private static final Map<Character, Integer> ROMAN_TO_INT = new HashMap<>() {
        {
            put('I', 1);
            put('V', 5);
            put('X', 10);
            put('L', 50);
            put('C', 100);
            put('D', 500);
            put('M', 1000);
        }
    };

    private RomanToInteger() {
    }

    /**
     * Converts a single Roman numeral character to its integer value.
     *
     * @param symbol the Roman numeral character
     * @return the corresponding integer value
     * @throws IllegalArgumentException if the symbol is not a valid Roman numeral
     */
    private static int romanSymbolToInt(final char symbol) {
        return ROMAN_TO_INT.computeIfAbsent(symbol, c -> { throw new IllegalArgumentException("Unknown Roman symbol: " + c); });
    }

    /**
     * Converts a Roman numeral string to its integer equivalent.
     * Steps:
     * <ol>
     *     <li>Iterate over the string from right to left.</li>
     *     <li>For each character, convert it to an integer value.</li>
     *     <li>If the current value is greater than or equal to the max previous value, add it.</li>
     *     <li>Otherwise, subtract it from the sum.</li>
     *     <li>Update the max previous value.</li>
     *     <li>Return the sum.</li>
     * </ol>
     *
     * @param roman the Roman numeral string
     * @return the integer value of the Roman numeral
     * @throws IllegalArgumentException if the input contains invalid Roman characters
     * @throws NullPointerException if the input is {@code null}
     */
    public static int romanToInt(String roman) {
        if (roman == null) {
            throw new NullPointerException("Input cannot be null");
        }

        roman = roman.toUpperCase();
        int sum = 0;
        int maxPrevValue = 0;
        for (int i = roman.length() - 1; i >= 0; i--) {
            int currentValue = romanSymbolToInt(roman.charAt(i));
            if (currentValue >= maxPrevValue) {
                sum += currentValue;
                maxPrevValue = currentValue;
            } else {
                sum -= currentValue;
            }
        }

        return sum;
    }
}

package com.thealgorithms.datastructures.heaps;

import java.util.ArrayList;
import java.util.HashMap;

/**
 * A generic implementation of a max heap data structure.
 *
 * @param <T> the type of elements in this heap, must extend Comparable.
 */
public class GenericHeap<T extends Comparable<T>> {

    private final ArrayList<T> data = new ArrayList<>();
    private final HashMap<T, Integer> map = new HashMap<>();

    /**
     * Adds an item to the heap, maintaining the heap property.
     *
     * @param item the item to be added
     */
    public void add(T item) {
        if (item == null) {
            throw new IllegalArgumentException("Cannot insert null into the heap.");
        }

        this.data.add(item);
        map.put(item, this.data.size() - 1);
        upHeapify(this.data.size() - 1);
    }

    /**
     * Restores the heap property by moving the item at the given index upwards.
     *
     * @param ci the index of the current item
     */
    private void upHeapify(int ci) {
        int pi = (ci - 1) / 2;
        if (ci > 0 && isLarger(this.data.get(ci), this.data.get(pi)) > 0) {
            swap(pi, ci);
            upHeapify(pi);
        }
    }

    /**
     * Returns the number of elements in the heap.
     *
     * @return the size of the heap
     */
    public int size() {
        return this.data.size();
    }

    /**
     * Checks if the heap is empty.
     *
     * @return true if the heap is empty, false otherwise
     */
    public boolean isEmpty() {
        return this.size() == 0;
    }

    /**
     * Removes and returns the maximum item from the heap.
     *
     * @return the maximum item
     */
    public T remove() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        this.swap(0, this.size() - 1);
        T rv = this.data.remove(this.size() - 1);
        map.remove(rv);
        downHeapify(0);
        return rv;
    }

    /**
     * Restores the heap property by moving the item at the given index downwards.
     *
     * @param pi the index of the current item
     */
    private void downHeapify(int pi) {
        int lci = 2 * pi + 1;
        int rci = 2 * pi + 2;
        int mini = pi;
        if (lci < this.size() && isLarger(this.data.get(lci), this.data.get(mini)) > 0) {
            mini = lci;
        }
        if (rci < this.size() && isLarger(this.data.get(rci), this.data.get(mini)) > 0) {
            mini = rci;
        }
        if (mini != pi) {
            this.swap(pi, mini);
            downHeapify(mini);
        }
    }

    /**
     * Retrieves the maximum item from the heap without removing it.
     *
     * @return the maximum item
     */
    public T get() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return this.data.getFirst();
    }

    /**
     * Compares two items to determine their order.
     *
     * @param t the first item
     * @param o the second item
     * @return a positive integer if t is greater than o, negative if t is less, and zero if they are equal
     */
    private int isLarger(T t, T o) {
        return t.compareTo(o);
    }

    /**
     * Swaps two items in the heap and updates their indices in the map.
     *
     * @param i index of the first item
     * @param j index of the second item
     */
    private void swap(int i, int j) {
        T ith = this.data.get(i);
        T jth = this.data.get(j);
        this.data.set(i, jth);
        this.data.set(j, ith);
        map.put(ith, j);
        map.put(jth, i);
    }

    /**
     * Updates the priority of the specified item by restoring the heap property.
     *
     * @param item the item whose priority is to be updated
     */
    public void updatePriority(T item) {
        if (!map.containsKey(item)) {
            throw new IllegalArgumentException("Item not found in the heap");
        }
        int index = map.get(item);
        upHeapify(index);
    }
}

package polymorphism;

/*
 * Base type for every geometric figure used in this small demo.
 * Concrete figures must supply their own area/perimeter formulas,
 * while the drawing behaviour has a generic default that can be
 * swapped out by subclasses if they need something fancier.
 */
abstract class Sekil {

    private String etiket;

    protected Sekil(String etiket) {
        this.etiket = etiket;
    }

    public String getIsim() {
        return etiket;
    }

    public void setIsim(String etiket) {
        this.etiket = etiket;
    }

    // Every figure must know how to compute its own surface.
    public abstract double alanHesapla();

    // Every figure must know how to compute its own outline length.
    public abstract double cevreHesapla();

    // Default rendering routine; subclasses may replace it.
    public void ciz() {
        System.out.println(etiket + " ciziliyor.");
    }

    public static void main(String[] args) {
        Sekil[] figurler = new Sekil[3];
        figurler[0] = new Kare(5);
        figurler[1] = new Dikdortgen(4, 6);
        figurler[2] = new Cember(7);

        for (Sekil f : figurler) {
            System.out.println(f.getIsim() + " alani: " + f.alanHesapla());
            System.out.println(f.getIsim() + " cevresi: " + f.cevreHesapla());
            f.ciz();
        }
    }
}

