/**
 *
 * @author GIA KINH
 */
public class Rectangle extends Shape{
    private double width;
    private double length;

    public Rectangle() {
    }

    public Rectangle(double width, double length) {
        this.width = width;
        this.length = length;
    }

    public Rectangle(double width, double length, String color, boolean filled) {
        super(color, filled);
        this.width = width;
        this.length = length;
    }

    public double getWidth() {
        return width;
    }

    public void setWidth(double width) {
        this.width = width;
    }

    public double getLength() {
        return length;
    }

    public void setLength(double length) {
        this.length = length;
    }

    public double getArea(){
        return this.length*this.width;
    }

    public double getPerimeter(){
        return (this.length+this.width)*2;
    }

    @Override
    public String toString() {
        return "Rectangle["+ super.toString() + ",width=" + width + ", length=" + length + ']';
    }


}

/**
 * A line segment that extends Point to reuse the "begin" coordinate,
 * while composing a second Point for the "end" coordinate.
 */
public class LineSub extends Point {

    private Point endPoint;

    public LineSub(Point begin, Point end) {
        super(begin.getX(), begin.getY());
        this.endPoint = end;
    }

    public LineSub(int beginX, int beginY, int endX, int endY) {
        super(beginX, beginY);
        this.endPoint = new Point(endX, endY);
    }

    @Override
    public String toString() {
        return "LineSub[begin=" + super.toString() + ",end=" + endPoint + ']';
    }

    public Point getBegin() {
        return new Point(getX(), getY());
    }

    public Point getEnd() {
        return endPoint;
    }

    public void setBegin(int beginX, int beginY) {
        setXY(beginX, beginY);
    }

    public void setEnd(int endX, int endY) {
        endPoint.setXY(endX, endY);
    }

    public int getBeginX() {
        return getX();
    }

    public int getBeginY() {
        return getY();
    }

    public int getEndX() {
        return endPoint.getX();
    }

    public int getEndY() {
        return endPoint.getY();
    }

    public void setBeginX(int beginX) {
        setX(beginX);
    }

    public void setBeginY(int beginY) {
        setY(beginY);
    }

    public void setBeginXY(int beginX, int beginY) {
        setXY(beginX, beginY);
    }

    public void setEndX(int endX) {
        endPoint.setX(endX);
    }

    public void setEndY(int endY) {
        endPoint.setY(endY);
    }

    public void setEndXY(int endX, int endY) {
        endPoint.setXY(endX, endY);
    }

    public int getLength() {
        int dx = endPoint.getX() - getX();
        int dy = endPoint.getY() - getY();
        double distance = Math.sqrt(dx * dx + dy * dy);
        return (int) distance;
    }

    public double getGradient() {
        int dx = endPoint.getX() - getX();
        int dy = endPoint.getY() - getY();
        return Math.atan2(dy, dx);
    }
}

class TestLineSub {
    public static void main(String[] args) {
        LineSub lineSub = new LineSub(8, 9, 6, 7);
        System.out.println(lineSub.getBegin());
        System.out.println(lineSub.getEnd());
        System.out.println(lineSub.getLength());
        System.out.println(lineSub.getGradient());
    }
}

package com.thealgorithms.datastructures.queues;

import java.util.Iterator;
import java.util.NoSuchElementException;

public class LinkedQueue<T> implements Iterable<T> {

    /**
     * Node class representing each element in the queue.
     */
    private static class Node<T> {
        T data;
        Node<T> next;

        Node(T data) {
            this.data = data;
            this.next = null;
        }
    }

    private Node<T> front; // Front of the queue
    private Node<T> rear; // Rear of the queue
    private int size; // Size of the queue

    /**
     * Initializes an empty LinkedQueue.
     */
    public LinkedQueue() {
        front = null;
        rear = null;
        size = 0;
    }

    /**
     * Checks if the queue is empty.
     *
     * @return true if the queue is empty, otherwise false.
     */
    public boolean isEmpty() {
        return size == 0;
    }

    /**
     * Adds an element to the rear of the queue.
     *
     * @param data the element to insert.
     * @throws IllegalArgumentException if data is null.
     */
    public void enqueue(T data) {
        if (data == null) {
            throw new IllegalArgumentException("Cannot enqueue null data");
        }

        Node<T> newNode = new Node<>(data);

        if (isEmpty()) {
            front = newNode;
        } else {
            rear.next = newNode;
        }
        rear = newNode;
        size++;
    }

    /**
     * Removes and returns the element at the front of the queue.
     *
     * @return the element at the front of the queue.
     * @throws NoSuchElementException if the queue is empty.
     */
    public T dequeue() {
        if (isEmpty()) {
            throw new NoSuchElementException("Queue is empty");
        }

        T retValue = front.data;
        front = front.next;
        size--;

        if (isEmpty()) {
            rear = null;
        }

        return retValue;
    }

    /**
     * Returns the element at the front of the queue without removing it.
     *
     * @return the element at the front of the queue.
     * @throws NoSuchElementException if the queue is empty.
     */
    public T peekFront() {
        if (isEmpty()) {
            throw new NoSuchElementException("Queue is empty");
        }
        return front.data;
    }

    /**
     * Returns the element at the rear of the queue without removing it.
     *
     * @return the element at the rear of the queue.
     * @throws NoSuchElementException if the queue is empty.
     */
    public T peekRear() {
        if (isEmpty()) {
            throw new NoSuchElementException("Queue is empty");
        }
        return rear.data;
    }

    /**
     * Returns the element at the specified position (1-based index).
     *
     * @param pos the position to peek at (1-based index).
     * @return the element at the specified position.
     * @throws IndexOutOfBoundsException if the position is out of range.
     */
    public T peek(int pos) {
        if (pos < 1 || pos > size) {
            throw new IndexOutOfBoundsException("Position " + pos + " out of range!");
        }

        Node<T> node = front;
        for (int i = 1; i < pos; i++) {
            node = node.next;
        }
        return node.data;
    }

    /**
     * Returns an iterator over the elements in the queue.
     *
     * @return an iterator over the elements in the queue.
     */
    @Override
    public Iterator<T> iterator() {
        return new Iterator<>() {
            private Node<T> current = front;

            @Override
            public boolean hasNext() {
                return current != null;
            }

            @Override
            public T next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }

                T data = current.data;
                current = current.next;
                return data;
            }
        };
    }

    /**
     * Returns the size of the queue.
     *
     * @return the size of the queue.
     */
    public int size() {
        return size;
    }

    /**
     * Clears all elements from the queue.
     */
    public void clear() {
        front = null;
        rear = null;
        size = 0;
    }

    /**
     * Returns a string representation of the queue.
     *
     * @return a string representation of the queue.
     */
    @Override
    public String toString() {
        if (isEmpty()) {
            return "[]";
        }

        StringBuilder sb = new StringBuilder("[");
        Node<T> current = front;
        while (current != null) {
            sb.append(current.data);
            if (current.next != null) {
                sb.append(", ");
            }
            current = current.next;
        }
        sb.append(']');
        return sb.toString();
    }
}

public class Student implements Comparable<Student>{
    int rollNumber;
    float studentMarks;

    public Student(int rollNumber, float studentMarks) {
        this.rollNumber = rollNumber;
        this.studentMarks = studentMarks;
    }

    @Override
    public String toString() {
        return String.valueOf(studentMarks); // Convert marks to string representation
    }

    /**
     * Compares this student object with the specified student object for natural ordering.
     * Returns a negative integer, zero, or a positive integer as this student's marks
     * are less than, equal to, or greater than the specified student's marks.
     *
     * <p>The implementor must ensure {@link Integer#signum
     * signum}{@code (x.compareTo(y)) == -signum(y.compareTo(x))} for
     * all {@code x} and {@code y}.  (This implies that {@code
     * x.compareTo(y)} must throw an exception if and only if {@code
     * y.compareTo(x)} throws an exception.)
     *
     * <p>The implementor must also ensure that the relation is transitive:
     * {@code (x.compareTo(y) > 0 && y.compareTo(z) > 0)} implies
     * {@code x.compareTo(z) > 0}.
     *
     * <p>Finally, the implementor must ensure that {@code
     * x.compareTo(y)==0} implies that {@code signum(x.compareTo(z))
     * == signum(y.compareTo(z))}, for all {@code z}.
     *
     * @param otherStudent the student object to be compared with this student
     * @return a negative integer if this student has lesser marks,
     *         zero if marks are equal,
     *         a positive integer if this student has greater marks
     * @throws NullPointerException if the specified student object is null
     * @throws ClassCastException   if the specified object's type prevents it
     *                              from being compared to this student object
     * @apiNote It is strongly recommended, but <i>not</i> strictly required that
     * {@code (x.compareTo(y)==0) == (x.equals(y))}.  Generally speaking, any
     * class that implements the {@code Comparable} interface and violates
     * this condition should clearly indicate this fact.  The recommended
     * language is "Note: this class has a natural ordering that is
     * inconsistent with equals."
     */
    @Override
    public int compareTo(Student otherStudent) {
        System.out.println("compareTo() invoked for natural ordering comparison");
        int marksDifference = (int)(this.studentMarks - otherStudent.studentMarks);
        // If marksDifference == 0 → both students have equal marks
        // If marksDifference < 0 → this student has lower marks than otherStudent
        // If marksDifference > 0 → this student has higher marks than otherStudent
        return marksDifference;
    }
}

/**
 * Converts an IPv4 address to its binary equivalent and vice-versa.
 * IP to Binary: Converts an IPv4 address to its binary equivalent.
 * Example: 127.3.4.5 -> 01111111.00000011.00000100.00000101
 *
 * Binary to IP: Converts a binary equivalent to an IPv4 address.
 * Example: 01111111.00000011.00000100.00000101 -> 127.3.4.5
 *
 * @author Hardvan
 */
public final class IPConverter {
    private IPConverter() {
    }

    /**
     * Converts an IPv4 address to its binary equivalent.
     * @param ip The IPv4 address to convert.
     * @return The binary equivalent of the IPv4 address.
     */
    public static String ipToBinary(String ip) {
        StringBuilder binary = new StringBuilder();
        for (String octet : ip.split("\\.")) {
            binary.append(octetToBinary(Integer.parseInt(octet))).append(".");
        }
        return binary.substring(0, binary.length() - 1);
    }

    /**
     * Converts a single octet to its 8-bit binary representation.
     * @param octet The octet to convert (0-255).
     * @return The 8-bit binary representation as a String.
     */
    private static String octetToBinary(int octet) {
        char[] binary = {'0', '0', '0', '0', '0', '0', '0', '0'};
        for (int i = 7; i >= 0; i--) {
            if ((octet & 1) == 1) {
                binary[i] = '1';
            }
            octet >>>= 1;
        }
        return new String(binary);
    }

    /**
     * Converts a binary equivalent to an IPv4 address.
     * @param binary The binary equivalent to convert.
     * @return The IPv4 address of the binary equivalent.
     */
    public static String binaryToIP(String binary) {
        StringBuilder ip = new StringBuilder();
        for (String octet : binary.split("\\.")) {
            ip.append(Integer.parseInt(octet, 2)).append(".");
        }
        return ip.substring(0, ip.length() - 1);
    }
}

public class CustomGenArrayList<T> {
    // Custom generic ArrayList implementation - allows any reference type <T>
    private Object[] internalDataStore;
    private static int INITIAL_DEFAULT_CAPACITY = 10;
    private int currentElementCount = 0; // also serves as the next available index position

    public CustomGenArrayList() {
        this.internalDataStore = new Object[INITIAL_DEFAULT_CAPACITY];
    }

    public void addElement(T elementToInsert) {
        if (isStorageFull()) {
            expandStorageCapacity();
        }
        internalDataStore[currentElementCount++] = elementToInsert;
    }

    private void expandStorageCapacity() {
        Object[] largerStorageArray = new Object[internalDataStore.length * 2];

        // Copy all existing elements into the newly created larger array
        for (int indexPosition = 0; indexPosition < internalDataStore.length; indexPosition++) {
            largerStorageArray[indexPosition] = internalDataStore[indexPosition];
        }
        internalDataStore = largerStorageArray;
    }

    private boolean isStorageFull() {
        return currentElementCount == internalDataStore.length;
    }

    public T removeLastElement() {
        T removedElementValue = (T) internalDataStore[--currentElementCount];
        return removedElementValue;
    }

    public T getElementAtIndex(int targetIndex) {
        return (T) internalDataStore[targetIndex];
    }

    public int getCurrentElementCount() {
        return currentElementCount;
    }

    public void updateValueAtIndex(int targetIndex, T updatedValue) {
        internalDataStore[targetIndex] = updatedValue;
    }

    @Override
    public String toString() {
        return "CustomGenArrayList{" +
                "internalDataStore=" + Arrays.toString(internalDataStore) +
                ", currentElementCount=" + currentElementCount +
                '}';
    }

    public static void main(String[] args) {
        // Standard Java ArrayList example (commented)
        // ArrayList list = new ArrayList();

        // Raw type usage (not recommended - shown for demonstration)
        CustomGenArrayList rawTypeList = new CustomGenArrayList();
//        rawTypeList.add(3);
//        rawTypeList.add(5);
//        rawTypeList.add(9);

//        // Integer example with for loop (commented)
//        for (int iterationValue = 0; iterationValue < 14; iterationValue++) {
//            rawTypeList.add(2 * iterationValue);
//        }
//        System.out.println(rawTypeList);

        // Standard generic ArrayList with String type
        ArrayList<String> stringTypeArrayList = new ArrayList<>();
//        stringTypeArrayList.add("sample text");
        // Note: Generics provide compile-time type safety - e.g., ArrayList<Integer>, ArrayList<Double>

        // Demonstrating CustomGenArrayList with Double type parameter
        CustomGenArrayList<Double> doubleTypeArrayList = new CustomGenArrayList<>();
        for (double incrementalValue = 0; incrementalValue < 14; incrementalValue++) {
            doubleTypeArrayList.addElement(2.5 * incrementalValue);
        }

        System.out.println("Complete Double ArrayList: " + doubleTypeArrayList);
        System.out.println("Element at index 5: " + doubleTypeArrayList.getElementAtIndex(5));
        System.out.println("Removed last element: " + doubleTypeArrayList.removeLastElement());
        System.out.println("ArrayList after removal: " + doubleTypeArrayList);
    }
}

