/**
 * A generic implementation of a hash map using an array of linked lists for collision resolution.
 * This class provides a way to store key-value pairs efficiently, allowing for average-case
 * constant time complexity for insertion, deletion, and retrieval operations.
 *
 * <p>
 * The hash map uses separate chaining for collision resolution. Each bucket in the hash map is a
 * linked list that stores nodes containing key-value pairs. When a collision occurs (i.e., when
 * two keys hash to the same index), the new key-value pair is simply added to the corresponding
 * linked list.
 * </p>
 *
 * <p>
 * The hash map automatically resizes itself when the load factor exceeds 0.75. The load factor is
 * defined as the ratio of the number of entries to the number of buckets. When resizing occurs,
 * all existing entries are rehashed and inserted into the new buckets.
 * </p>
 *
 * @param <KeyType> the type of keys maintained by this hash map
 * @param <ValueType> the type of mapped values
 */
@SuppressWarnings({"rawtypes", "unchecked"})
public class GenericHashMapUsingArray<KeyType, ValueType> {

private int entryCount;
private LinkedList<EntryNode>[] bucketArray;

/**
 * Constructs a new empty hash map with an initial capacity of 16.
 */
public GenericHashMapUsingArray() {
initializeBuckets(16);
entryCount = 0;
}

/**
 * Initializes the buckets for the hash map with the specified number of buckets.
 *
 * @param bucketCapacity the number of buckets to initialize
 */
private void initializeBuckets(int bucketCapacity) {
bucketArray = new LinkedList[bucketCapacity];
for (int bucketIndex = 0; bucketIndex < bucketArray.length; bucketIndex++) {
bucketArray[bucketIndex] = new LinkedList<>();
}
}

/**
 * Associates the specified value with the specified key in this map.
 * If the map previously contained a mapping for the key, the old value is replaced.
 *
 * @param insertKey the key with which the specified value is to be associated
 * @param insertValue the value to be associated with the specified key
 */
public void put(KeyType insertKey, ValueType insertValue) {
int bucketPosition = computeHash(insertKey);
LinkedList<EntryNode> targetBucket = bucketArray[bucketPosition];
for (EntryNode existingEntry : targetBucket) {
if (existingEntry.keyValue.equals(insertKey)) {
existingEntry.storedValue = insertValue;
return;
}
}
targetBucket.add(new EntryNode(insertKey, insertValue));
entryCount++;
float loadThreshold = 0.75f;
if ((float) entryCount / bucketArray.length > loadThreshold) {
expandAndRehash();
}
}

/**
 * Returns the index of the bucket in which the key would be stored.
 *
 * @param targetKey the key whose bucket index is to be computed
 * @return the bucket index
 */
private int computeHash(KeyType targetKey) {
return Math.floorMod(targetKey.hashCode(), bucketArray.length);
}

/**
 * Rehashes the map by doubling the number of buckets and re-inserting all entries.
 */
private void expandAndRehash() {
LinkedList<EntryNode>[] oldBuckets = bucketArray;
initializeBuckets(oldBuckets.length * 2);
this.entryCount = 0;
for (LinkedList<EntryNode> currentBucket : oldBuckets) {
for (EntryNode nodeEntry : currentBucket) {
put(nodeEntry.keyValue, nodeEntry.storedValue);
}
}
}

/**
 * Removes the mapping for the specified key from this map if present.
 *
 * @param targetKey the key whose mapping is to be removed from the map
 */
public void remove(KeyType targetKey) {
int bucketPosition = computeHash(targetKey);
LinkedList<EntryNode> targetBucket = bucketArray[bucketPosition];
EntryNode entryToRemove = null;
for (EntryNode currentEntry : targetBucket) {
if (currentEntry.keyValue.equals(targetKey)) {
entryToRemove = currentEntry;
break;
}
}
if (entryToRemove != null) {
targetBucket.remove(entryToRemove);
entryCount--;
}
}

/**
 * Returns the number of key-value pairs in this map.
 *
 * @return the number of key-value pairs
 */
public int getSize() {
return this.entryCount;
}

/**
 * Returns the value to which the specified key is mapped, or null if this map contains no mapping for the key.
 *
 * @param searchKey the key whose associated value is to be returned
 * @return the value associated with the specified key, or null if no mapping exists
 */
public ValueType get(KeyType searchKey) {
int bucketPosition = computeHash(searchKey);
LinkedList<EntryNode> targetBucket = bucketArray[bucketPosition];
for (EntryNode currentEntry : targetBucket) {
if (currentEntry.keyValue.equals(searchKey)) {
return currentEntry.storedValue;
}
}
return null;
}

@Override
public String toString() {
StringBuilder resultBuilder = new StringBuilder();
resultBuilder.append("{");
for (LinkedList<EntryNode> currentBucket : bucketArray) {
for (EntryNode nodeEntry : currentBucket) {
resultBuilder.append(nodeEntry.keyValue);
resultBuilder.append(" : ");
resultBuilder.append(nodeEntry.storedValue);
resultBuilder.append(", ");
}
}
if (resultBuilder.length() > 1) {
resultBuilder.setLength(resultBuilder.length() - 2);
}
resultBuilder.append("}");
return resultBuilder.toString();
}

/**
 * Returns true if this map contains a mapping for the specified key.
 *
 * @param searchKey the key whose presence in this map is to be tested
 * @return true if this map contains a mapping for the specified key
 */
public boolean containsKey(KeyType searchKey) {
return get(searchKey) != null;
}

/**
 * A private class representing a key-value pair (node) in the hash map.
 */
public class EntryNode {
KeyType keyValue;
ValueType storedValue;

/**
 * Constructs a new Node with the specified key and value.
 *
 * @param inputKey the key of the key-value pair
 * @param inputValue the value of the key-value pair
 */
public EntryNode(KeyType inputKey, ValueType inputValue) {
this.keyValue = inputKey;
this.storedValue = inputValue;
}
}
}
