/**
 *
 * @author GIA KINH
 */

class MyPoint {

    private int x;
    private int y;

    public MyPoint() {
    }

    public MyPoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int[] getXY() {
        return new int[]{this.x, this.y};
    }

    public void setXY(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public double distance(int x, int y) {
        return (double) Math.sqrt(Math.pow((x - this.x), 2) + Math.pow((y - this.y), 2));
    }

    public double distance(MyPoint another) {
        return (double) Math.sqrt(Math.pow((another.x - this.x), 2) + Math.pow((another.y - this.y), 2));
    }

    public double distance() {
        return (double) Math.sqrt(Math.pow((0 - this.x), 2) + Math.pow((0 - this.y), 2));
    }

    @Override
    public String toString() {
        return "(" +x + "," + y + ')';
    }
}

public class MyTriangle {
    private MyPoint v1;
    private MyPoint v2;
    private MyPoint v3;

    public MyTriangle(int x1, int y1, int x2, int y2, int x3, int y3){
        this.v1 = new MyPoint(x1,y1);
        this.v2 = new MyPoint(x2,y2);
        this.v3 = new MyPoint(x3,y3);
    }

    public MyTriangle(MyPoint v1, MyPoint v2, MyPoint v3) {
        this.v1 = v1;
        this.v2 = v2;
        this.v3 = v3;
    }

    public MyPoint getV1() {
        return v1;
    }

    public void setV1(MyPoint v1) {
        this.v1 = v1;
    }

    public MyPoint getV2() {
        return v2;
    }

    public void setV2(MyPoint v2) {
        this.v2 = v2;
    }

    public MyPoint getV3() {
        return v3;
    }

    public void setV3(MyPoint v3) {
        this.v3 = v3;
    }

    public double getPerimeter(){
        return this.v1.distance(this.v2) + this.v2.distance(this.v3) + this.v3.distance(this.v1);
    }

    public String getType(){
        if(this.v1.distance(this.v2) == this.v2.distance(this.v3) && this.v1.distance(this.v2) ==  this.v3.distance(this.v1)){
            return "Equilateral";
        }else if(this.v1.distance(this.v2) == this.v2.distance(this.v3) || 
                this.v1.distance(this.v2) ==  this.v3.distance(this.v1) ||
                this.v3.distance(this.v1) == this.v2.distance(this.v3)
                ){
            return "Isosceles";
        }else{
            return "Scalene";
        }
    }

    @Override
    public String toString() {
        return "MyTriangle[" + "v1=" + v1.toString() + ",v2=" + v2.toString() + ",v3=" + v3.toString() + ']';
    }
}

class TestMyTriangle {
    public static void main(String[] args) {
        MyTriangle myTriangle = new MyTriangle(new MyPoint(5, 5), new MyPoint(15, 15), new MyPoint(5,25));
        System.out.println(myTriangle.getPerimeter());
        System.out.println(myTriangle.getType());
        System.out.println(myTriangle.getV1());
        System.out.println(myTriangle.getV2());
        System.out.println(myTriangle.getV3());
        System.out.println(myTriangle.toString());
    }
}

/**
 * @author Varun Upadhyay (https://github.com/varunu28)
 */
public final class Fibonacci {
    private Fibonacci() {
    }

    static final Map<Integer, Integer> CACHE = new HashMap<>();

    /**
     * This method finds the nth fibonacci number using memoization technique
     *
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * @throws IllegalArgumentException if n is negative
     */
    public static int fibMemo(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        if (CACHE.containsKey(n)) {
            return CACHE.get(n);
        }

        int f;

        if (n <= 1) {
            f = n;
        } else {
            f = fibMemo(n - 1) + fibMemo(n - 2);
            CACHE.put(n, f);
        }
        return f;
    }

    /**
     * This method finds the nth fibonacci number using bottom up
     *
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * @throws IllegalArgumentException if n is negative
     */
    public static int fibBotUp(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        Map<Integer, Integer> fib = new HashMap<>();

        for (int i = 0; i <= n; i++) {
            int f;
            if (i <= 1) {
                f = i;
            } else {
                f = fib.get(i - 1) + fib.get(i - 2);
            }
            fib.put(i, f);
        }

        return fib.get(n);
    }

    /**
     * This method finds the nth fibonacci number using bottom up
     *
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * <p>
     * This is optimized version of Fibonacci Program. Without using Hashmap and
     * recursion. It saves both memory and time. Space Complexity will be O(1)
     * Time Complexity will be O(n)
     * <p>
     * Whereas , the above functions will take O(n) Space.
     * @throws IllegalArgumentException if n is negative
     * @author Shoaib Rayeen (https://github.com/shoaibrayeen)
     */
    public static int fibOptimized(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        if (n == 0) {
            return 0;
        }
        int prev = 0;
        int res = 1;
        int next;
        for (int i = 2; i <= n; i++) {
            next = prev + res;
            prev = res;
            res = next;
        }
        return res;
    }

    /**
     * We have only defined the nth Fibonacci number in terms of the two before it. Now, we will
     * look at Binet's formula to calculate the nth Fibonacci number in constant time. The Fibonacci
     * terms maintain a ratio called golden ratio denoted by Φ, the Greek character pronounced
     * ‘phi'. First, let's look at how the golden ratio is calculated: Φ = ( 1 + √5 )/2
     * = 1.6180339887... Now, let's look at Binet's formula: Sn = Φⁿ–(– Φ⁻ⁿ)/√5 We first calculate
     * the squareRootof5 and phi and store them in variables. Later, we apply Binet's formula to get
     * the required term. Time Complexity will be O(1)
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * @throws IllegalArgumentException if n is negative
     */
    public static int fibBinet(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        double squareRootOf5 = Math.sqrt(5);
        double phi = (1 + squareRootOf5) / 2;
        return (int) ((Math.pow(phi, n) - Math.pow(-phi, -n)) / squareRootOf5);
    }
}

public class Banka {

	public static void main(String[] args) {

		// Banka hesaplari olusturuluyor
		BankaHesabi hesap1 = new BankaHesabi(123456, 2000.0, "Vadeli");
		BankaHesabi hesap2 = new BankaHesabi(789012, 1500.0, "Vadesiz");

		// Hesap bilgileri yazdiriliyor
		System.out.println("Hesap 1 numarasi: " + hesap1.getHesapNumarasi());
		System.out.println("Hesap 1 bakiye: " + hesap1.getBakiye());
		System.out.println("Hesap 1 turu: " + hesap1.getHesapTuru());

		System.out.println("\nHesap 2 numarasi: " + hesap2.getHesapNumarasi());
		System.out.println("Hesap 2 bakiye: " + hesap2.getBakiye());
		System.out.println("Hesap 2 turu: " + hesap2.getHesapTuru());

		System.out.println();
		// Para yatirma
		hesap1.paraYatir(500.0); // Hesap 1'e 500 TL yatirildi

		// Para cekme
		hesap2.paraCek(200.0); // Hesap 2'den 200 TL cekildi

		// Faiz ekleme
		hesap1.faizEkle(5.0); // Hesap 1'e %5 faiz eklendi

		// Transfer islemi
		hesap1.transfer(hesap2, 300.0); // Hesap 1'den Hesap 2'ye 300 TL transfer edildi

		// Yeni bakiyeleri yazdirma
		System.out.println("\nHesap 1 yeni bakiye: " + hesap1.getBakiye());
		System.out.println("Hesap 2 yeni bakiye: " + hesap2.getBakiye());
	}
}

public class Loto {

    // Loto cekilisi yapan metod
    public static Integer[] lotoYap(int toplamSayi, int cekilecekSayi) {
        // Sayilari tutacak bir ArrayList olustur
        ArrayList<Integer> sayilar = new ArrayList<Integer>();

        // 1'den toplamSayi'ya kadar sayilari listeye ekle
        for (int i = 0; i < toplamSayi; i++) {
            sayilar.add(i + 1);
        }

        // Sayilari karistir
        Collections.shuffle(sayilar);

        // Cekilecek sayi kadar elemani yeni bir Integer dizisine kopyala
        Integer[] cekilenSayilar = new Integer[cekilecekSayi];
        for (int i = 0; i < cekilecekSayi; i++) {
            cekilenSayilar[i] = sayilar.get(i);
        }

        return cekilenSayilar;
    }

    public static void main(String[] args) {
        // 49 sayidan 6 tane cekilis sonucu al
        Integer[] sonuc = lotoYap(49, 6);

        // Sonuclari ekrana yazdir
        for (Integer item : sonuc) {
            System.out.print(item + " ");
        }
    }
}

