package MyLine;

import java.util.Arrays;

/**
 *
 * @author GIA KINH
 */

class MyPoint {
    private int x;
    private int y;

    public MyPoint() {
    }

    public MyPoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int[] getXY() {
        return new int[]{this.x, this.y};
    }

    public void setXY(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public double distance(int x, int y) {
        return (double) Math.sqrt(Math.pow((x - this.x), 2) + Math.pow((y - this.y), 2));
    }

    public double distance(MyPoint another) {
        return (double) Math.sqrt(Math.pow((another.x - this.x), 2) + Math.pow((another.y - this.y), 2));
    }

    public double distance() {
        return (double) Math.sqrt(Math.pow((0 - this.x), 2) + Math.pow((0 - this.y), 2));
    }

    @Override
    public String toString() {
        return "(" +x + "," + y + ')';
    }
}

public class MyLine {
    private MyPoint begin;
    private MyPoint end;

    public MyLine(int x1, int y1,int x2,int y2) {
        this.begin = new MyPoint(x1, y1);
        this.end = new MyPoint(x2,y2);
    }

    public MyLine(MyPoint begin, MyPoint end) {
        this.begin = begin;
        this.end = end;
    }

    public MyPoint getBegin() {
        return begin;
    }

    public void setBegin(MyPoint begin) {
        this.begin = begin;
    }

    public MyPoint getEnd() {
        return end;
    }

    public void setEnd(MyPoint end) {
        this.end = end;
    }

    public void setBeginX(int x){
        this.begin.setX(x);
    }

    public int getBeginX(){
        return this.begin.getX();
    }

    public void setBeginY(int y){
        this.begin.setY(y);
    }

    public int getBeginY(){
        return this.begin.getY();
    }

    public void setEndX(int x){
        this.end.setX(x);
    }

    public int getEndX(){
        return this.end.getX();
    }

    public void setEndY(int y){
        this.end.setY(y);
    }

    public int getEndY(){
        return this.end.getY();
    }

    public void setBeginXY(int x, int y){
        this.begin.setXY(x, y);
    }

    public int[] getBeginXY(){
        return this.begin.getXY();
    }

    public void setEndXY(int x, int y){
        this.end.setXY(x, y);
    }

    public int[] getEndXY(){
        return this.end.getXY();
    }

    public double getLength(){
        return this.begin.distance(this.end);
    }

    public double getGradient(){
        return Math.atan2(this.end.getY()-this.begin.getY(), this.end.getX()-this.begin.getX());
    }

    @Override
    public String toString() {
        return "MyLine[" + "begin=" + begin + ",end=" + end + ']';
    }
}


class TestMyLine{
    public static void main(String[] args) {
           MyLine myLine = new MyLine(new MyPoint(0, 1), new MyPoint(3, 4));
           System.out.println(myLine.getLength());
           System.out.println(myLine.getGradient());
           System.out.println(myLine.toString());
           System.out.println(Arrays.toString(myLine.getBeginXY()));
           System.out.println(Arrays.toString(myLine.getEndXY()));
    }
}

/**
 * @see <a href="https://en.wikipedia.org/wiki/Combination">Combination</a>
 */
public final class Combinations {
    private Combinations() {
    }

    /**
     * Calculate of factorial
     *
     * @param n the number
     * @return factorial of given number
     */
    public static long factorial(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("number is negative");
        }
        return n == 0 || n == 1 ? 1 : n * factorial(n - 1);
    }

    /**
     * Calculate combinations
     *
     * @param n first number
     * @param k second number
     * @return combinations of given {@code n} and {@code k}
     */
    public static long combinations(int n, int k) {
        return factorial(n) / (factorial(k) * factorial(n - k));
    }

    /**
     * The above method can exceed limit of long (overflow) when factorial(n) is
     * larger than limits of long variable. Thus even if nCk is within range of
     * long variable above reason can lead to incorrect result. This is an
     * optimized version of computing combinations. Observations: nC(k + 1) = (n
     * - k) * nCk / (k + 1) We know the value of nCk when k = 1 which is nCk = n
     * Using this base value and above formula we can compute the next term
     * nC(k+1)
     *
     * @param n
     * @param k
     * @return nCk
     */
    public static long combinationsOptimized(int n, int k) {
        if (n < 0 || k < 0) {
            throw new IllegalArgumentException("n or k can't be negative");
        }
        if (n < k) {
            throw new IllegalArgumentException("n can't be smaller than k");
        }
        // nC0 is always 1
        long solution = 1;
        for (int i = 0; i < k; i++) {
            solution = (n - i) * solution / (i + 1);
        }
        return solution;
    }
}

public class WordFrequencyCounter {
    public static void main(String[] args) {
        String text = "the quick brown fox jumps over the lazy dog the end";

        Map<String, Integer> frequencies = new HashMap<>();
        for (String word : text.split("\\s+")) {
            frequencies.put(word, frequencies.getOrDefault(word, 0) + 1);
        }

        for (Map.Entry<String, Integer> entry : frequencies.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }
}

// Postane sinifi

public class Postane {

	private String ad;
	private String telefonNumarasi;

	public Postane(String ad, String telefonNumarasi) {
		this.ad = ad;
		this.telefonNumarasi = telefonNumarasi;
	}

	public String getAd() {
		return ad;
	}

	public String getTelefonNumarasi() {
		return telefonNumarasi;
	}

	public void postaneyiTanit() {
		System.out.println("Postane Adi: " + ad + ", Telefon Numarasi: " + telefonNumarasi);
	}

	public static void main(String[] args) {

		// Sabit degerler ile Kisi, Adres ve Postane nesneleri olusturuluyor
		// Kisi bilgileri
		String isim = "Ahmet";
		int yas = 30;

		// Adres bilgileri
		String sokakAdresi = "Mevlana Caddesi No:5";
		String sehir = "Konya";
		String postakodu = "42030";
		String ulke = "Turkiye";

		// Adres nesnesi olusturuluyor
		Adres adres = new Adres(sokakAdresi, sehir, postakodu, ulke);

		// Kisi nesnesi olusturuluyor
		Kisi kisi = new Kisi(isim, yas, adres);

		// Kisi bilgileri yazdiriliyor
		kisi.kisiyiTanit();

		// Postane bilgileri
		String postaneAdi = "Konya Postanesi";
		String telefonNumarasi = "0332 123 45 67";

		// Postane nesnesi olusturuluyor
		Postane postane = new Postane(postaneAdi, telefonNumarasi);

		// Postane bilgileri yazdiriliyor
		postane.postaneyiTanit();

		// Adres bilgileri yazdiriliyor
		adres.adresiYazdir();

		// Kisi'nin yasini kontrol etme
		System.out.println("Kisinin yasini kontrol edelim. 18 yasindan buyuk mu?");
		if (kisi.getYas() > 18) {
			System.out.println(kisi.getIsim() + " 18 yasindan buyuk.");
		} else {
			System.out.println(kisi.getIsim() + " 18 yasindan kucuk.");
		}
	}
}

