/**
 *
 * @author GIA KINH
 */
public class Painting extends Item{
    private int height;
    private int width;
    private boolean isWatercolour;
    private boolean isFramed;

    public Painting() {
    }

    public Painting(int value, String creator, int height, int width, boolean isWatercolour, boolean isFramed) {
        super(value, creator);
        this.height = height;
        this.width = width;
        this.isWatercolour = isWatercolour;
        this.isFramed = isFramed;
    }

    public int getHeight() {
        return height;
    }

    public void setHeight(int height) {
        this.height = height;
    }

    public int getWidth() {
        return width;
    }

    public void setWidth(int width) {
        this.width = width;
    }

    public boolean isIsWatercolour() {
        return isWatercolour;
    }

    public void setIsWatercolour(boolean isWatercolour) {
        this.isWatercolour = isWatercolour;
    }

    public boolean isIsFramed() {
        return isFramed;
    }

    public void setIsFramed(boolean isFramed) {
        this.isFramed = isFramed;
    }

    @Override
    public String toString() {
        return "Painting[" + super.toString() + "height=" + height + ",width=" + width + ",isWatercolour=" + isWatercolour + ",isFramed=" + isFramed + ']';
    }



    public void inputPainting(){
        super.input();
        Scanner scanner = new Scanner(System.in);
        System.out.print("Input a height: ");
        this.height = scanner.nextInt();
        scanner.nextLine();
        System.out.print("Input a width: ");
        this.width = scanner.nextInt();
        scanner.nextLine();
        System.out.print("Is watercolour: ");
        this.isWatercolour = scanner.nextBoolean();
        scanner.nextLine();
        System.out.print("Is Framed: ");
        this.isFramed = scanner.nextBoolean();
        scanner.nextLine();
    }

    public void outputPainting(){
        super.output();
        System.out.println("Height: " + height);
        System.out.println("Width: " + width);
        System.out.println("Is Watercolour: " + isWatercolour);
        System.out.println("Is Framed: " + isFramed);
    }
}

public final class PrimeCheck {
    private PrimeCheck() {
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a number: ");
        int n = scanner.nextInt();
        if (isPrime(n)) {
            System.out.println("algo1 verify that " + n + " is a prime number");
        } else {
            System.out.println("algo1 verify that " + n + " is not a prime number");
        }

        if (fermatPrimeChecking(n, 20)) {
            System.out.println("algo2 verify that " + n + " is a prime number");
        } else {
            System.out.println("algo2 verify that " + n + " is not a prime number");
        }
        scanner.close();
    }

    /**
     * *
     * Checks if a number is prime or not
     *
     * @param n the number
     * @return {@code true} if {@code n} is prime
     */
    public static boolean isPrime(int n) {
        if (n == 2) {
            return true;
        }
        if (n < 2 || n % 2 == 0) {
            return false;
        }
        for (int i = 3, limit = (int) Math.sqrt(n); i <= limit; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }

    /**
     * *
     * Checks if a number is prime or not
     *
     * @param n the number
     * @return {@code true} if {@code n} is prime
     */
    public static boolean fermatPrimeChecking(int n, int iteration) {
        long a;
        int up = n - 2;
        int down = 2;
        for (int i = 0; i < iteration; i++) {
            a = (long) Math.floor(Math.random() * (up - down + 1) + down);
            if (modPow(a, n - 1, n) != 1) {
                return false;
            }
        }
        return true;
    }

    /**
     * *
     * @param a basis
     * @param b exponent
     * @param c modulo
     * @return (a^b) mod c
     */
    private static long modPow(long a, long b, long c) {
        long res = 1;
        for (int i = 0; i < b; i++) {
            res *= a;
            res %= c;
        }
        return res % c;
    }
}

/**
 * Small utility belt for inspecting and manipulating directories/files
 * on the local filesystem: listing, recursive discovery, creation and
 * deletion helpers.
 */
public class KlasorIslemleri {

    /** Verilen yoldaki alt klasorleri (sadece klasorleri) dondurur. */
    public static File[] altKlasorler(String kokYol) {
        return new File(kokYol).listFiles(File::isDirectory);
    }

    /** Verilen klasordeki dosyalari (sadece dosyalari) dondurur. */
    public static File[] icindekiDosyalar(final File klasor) {
        return klasor.listFiles(File::isFile);
    }

    /** Kok yoldan baslayarak tum agaci gezip her dosyayi biriktirir (BFS benzeri). */
    public static Queue<File> agaciTaraVeTopla(String kokYol) {
        Queue<File> sonuclar = new LinkedList<>();
        Queue<File> bekleyenKlasorler = new LinkedList<>();
        bekleyenKlasorler.add(new File(kokYol));

        while (!bekleyenKlasorler.isEmpty()) {
            File guncelKlasor = bekleyenKlasorler.poll();
            File[] icerik = guncelKlasor.listFiles();
            if (icerik == null) {
                continue; // erisim yok veya klasor degil
            }
            for (File eleman : icerik) {
                if (eleman.isDirectory()) {
                    bekleyenKlasorler.add(eleman);
                } else {
                    sonuclar.add(eleman.getAbsoluteFile());
                }
            }
        }
        return sonuclar;
    }

    /** Tek bir dosyayi diskten kaldirir. */
    public static boolean dosyaKaldir(String tamYol) {
        return new File(tamYol).delete();
    }

    /** Yeni, bos bir klasor uretir. */
    public static boolean klasorUret(String hedefYol) {
        return new File(hedefYol).mkdir();
    }

    /** Klasoru icindeki her seyle birlikte (derinlemesine) temizler. */
    public static boolean agaciTemizle(File hedef) {
        if (hedef.isDirectory()) {
            File[] altElemanlar = hedef.listFiles();
            if (altElemanlar != null) {
                for (File altEleman : altElemanlar) {
                    agaciTemizle(altEleman);
                }
            }
        }
        return hedef.delete();
    }

    /** Bir dosyaya ait temel meta bilgileri konsola basar. */
    public static void metaBilgileriGoster(File hedef) {
        StringBuilder rapor = new StringBuilder();
        rapor.append("Dosya adi: ").append(hedef.getName()).append('\n');
        rapor.append("Tam yol: ").append(hedef.getAbsolutePath()).append('\n');
        rapor.append("Boyut (byte): ").append(hedef.length()).append('\n');
        rapor.append("Yazilabilir: ").append(hedef.canWrite()).append('\n');
        rapor.append("Okunabilir: ").append(hedef.canRead()).append('\n');
        rapor.append("Son degistirilme: ").append(hedef.lastModified());
        System.out.println(rapor);
    }

    public static void main(String[] args) {
        String calismaDizini = System.getProperty("user.dir");
        System.out.println("Proje klasoru: " + calismaDizini);

        File[] klasorler = altKlasorler(calismaDizini);
        if (klasorler == null) {
            System.out.println("Klasor bulunamadi veya erisim hatasi.");
        } else {
            System.out.println("Klasor sayisi: " + klasorler.length);
            for (File k : klasorler) {
                System.out.println(k.toString());
            }
        }

        if (klasorler != null && klasorler.length > 0) {
            File[] dosyalar = icindekiDosyalar(klasorler[0]);
            if (dosyalar == null) {
                System.out.println("Dosya bulunamadi veya erisim hatasi.");
            } else {
                System.out.println("Dosya sayisi: " + dosyalar.length);
                for (File d : dosyalar) {
                    System.out.println(d.toString());
                }
            }
        }

        System.out.println("Proje klasorundeki tum dosyalar:");
        for (File d : agaciTaraVeTopla(calismaDizini)) {
            System.out.println(d.toString());
        }

        String testKlasoru = calismaDizini + File.separator + "YeniKlasor";
        if (klasorUret(testKlasoru)) {
            System.out.println("Yeni klasor olusturuldu: " + testKlasoru);
        } else {
            System.out.println("Klasor olusturulamadi veya zaten mevcut.");
        }

        String testDosyaYolu = testKlasoru + File.separator + "TestDosyasi.txt";
        try {
            File yeni = new File(testDosyaYolu);
            if (yeni.createNewFile()) {
                System.out.println("Yeni dosya olusturuldu: " + testDosyaYolu);
            }
        } catch (IOException hata) {
            System.out.println("Dosya olusturma hatasi: " + hata.getMessage());
        }

        File kaldirilacakKlasor = new File(testKlasoru);
        if (agaciTemizle(kaldirilacakKlasor)) {
            System.out.println("YeniKlasor ve icindekiler silindi.");
        } else {
            System.out.println("YeniKlasor silinemedi veya mevcut degil.");
        }
    }
}

public class YildizDeseni {

    // Desen 1: normal piramit seklinde yildizlar
    public void desenPiramit(int yukseklik) {
        int satir = 1;
        while (satir <= yukseklik) {
            for (int bosluk = 1; bosluk <= yukseklik - satir; bosluk++) {
                System.out.print(" ");
            }
            for (int yildiz = 1; yildiz <= 2 * satir - 1; yildiz++) {
                System.out.print("*");
            }
            System.out.println();
            satir++;
        }
    }

    // Desen 2: ters cevrilmis piramit
    public void desenTersPiramit(int yukseklik) {
        for (int satir = yukseklik; satir > 0; satir--) {
            for (int bosluk = 1; bosluk <= yukseklik - satir; bosluk++) {
                System.out.print(" ");
            }
            for (int yildiz = 1; yildiz <= 2 * satir - 1; yildiz++) {
                System.out.print("*");
            }
            System.out.println();
        }
    }

    // Desen 3: sabit genislikte yildiz satirlari
    public void desenDikdortgen(int yukseklik) {
        int satir = 1;
        while (satir <= yukseklik) {
            int sutun = 1;
            while (sutun <= yukseklik) {
                System.out.print("* ");
                sutun++;
            }
            System.out.println();
            satir++;
        }
    }

    // Desen 4: yukari ve asagi birlesmis piramit (elmas benzeri)
    public void desenCiftYonlu(int yukseklik) {
        for (int satir = 1; satir <= yukseklik; satir++) {
            for (int bosluk = 1; bosluk <= yukseklik - satir; bosluk++) {
                System.out.print(" ");
            }
            for (int yildiz = 1; yildiz <= 2 * satir - 1; yildiz++) {
                System.out.print("*");
            }
            System.out.println();
        }
        int satir = yukseklik - 1;
        while (satir >= 1) {
            for (int bosluk = 1; bosluk <= yukseklik - satir; bosluk++) {
                System.out.print(" ");
            }
            for (int yildiz = 1; yildiz <= 2 * satir - 1; yildiz++) {
                System.out.print("*");
            }
            System.out.println();
            satir--;
        }
    }

    public static void main(String[] args) {

        Scanner girisOkuyucu = new Scanner(System.in);

        // Kullanicidan piramitin yukseklik degerini al
        System.out.print("Satir sayisini girin: ");
        int yukseklik = girisOkuyucu.nextInt();

        // Cizim islemleri icin nesne olustur
        YildizDeseni cizici = new YildizDeseni();

        System.out.println("Birinci Desen (Piramid):");
        cizici.desenPiramit(yukseklik);

        System.out.println("ikinci Desen (Ters Piramit):");
        cizici.desenTersPiramit(yukseklik);

        System.out.println("Ucuncu Desen (Duz Satir Yildizlari):");
        cizici.desenDikdortgen(yukseklik);

        System.out.println("Dorduncu Desen (Cift Yonlu Piramit):");
        cizici.desenCiftYonlu(yukseklik);

        girisOkuyucu.close();
    }
}

