/**
 * The Autokey Cipher is an interesting and historically significant encryption method,
 * as it improves upon the classic Vigenère Cipher by using the plaintext itself to
 * extend the key. This makes it harder to break using frequency analysis, as it
 * doesn’t rely solely on a repeated key.
 * https://en.wikipedia.org/wiki/Autokey_cipher
 *
 * @author bennybebo
 */
public class Autokey {

// Encrypts the plaintext using the Autokey cipher
public String encrypt(String inputText, String secretKey) {
String cleanInput = inputText.toUpperCase().replaceAll("[^A-Z]", "");
String cleanKey = secretKey.toUpperCase();
StringBuilder combinedKey = new StringBuilder(cleanKey);
combinedKey.append(cleanInput);
StringBuilder encryptedResult = new StringBuilder();
for (int position = 0; position < cleanInput.length(); position++) {
char inputChar = cleanInput.charAt(position);
char keyChar = combinedKey.charAt(position);
int encryptedValue = (inputChar - 'A' + keyChar - 'A') % 26 + 'A';
encryptedResult.append((char) encryptedValue);
}
return encryptedResult.toString();
}

// Decrypts the ciphertext using the Autokey cipher
public String decrypt(String encodedText, String secretKey) {
String cleanEncoded = encodedText.toUpperCase().replaceAll("[^A-Z]", "");
String cleanKey = secretKey.toUpperCase();
StringBuilder decryptedResult = new StringBuilder();
StringBuilder dynamicKey = new StringBuilder(cleanKey);
for (int position = 0; position < cleanEncoded.length(); position++) {
char encodedChar = cleanEncoded.charAt(position);
char keyChar = dynamicKey.charAt(position);
int decryptedValue = (encodedChar - 'A' - (keyChar - 'A') + 26) % 26 + 'A';
decryptedResult.append((char) decryptedValue);
dynamicKey.append((char) decryptedValue);
}
return decryptedResult.toString();
}
}

public class UsAlma {

	// 'usAl' metodu, verilen tabanin belirtilen usse gore ussunu hesaplar
	int usAl(int taban, int us) {
		int sonuc = 1;  // Sonuc degiskeni 1 ile baslar cunku herhangi bir sayinin 0. kuvveti 1'dir

		// Dongu, us sayisi kadar doner ve her adimda sonucu taban ile carpar
		for(int i = 0; i < us; i++) {
			sonuc *= taban;  
		}

		// Hesaplanan sonuc dondurulur
		return sonuc;
	}

	public static void main(String[] args) {

		// Kullanicidan giris almak icin Scanner nesnesi olustur
		Scanner okuyucu = new Scanner(System.in);

		// Kullanicidan taban sayisini girmesini iste
		System.out.println("Lutfen tabani giriniz:");
		int taban = okuyucu.nextInt();  // Kullanicinin girdigi taban sayisi alinir

		// Kullanicidan us sayisini girmesini iste
		System.out.println("Lutfen ussu giriniz:");
		int us = okuyucu.nextInt();  // Kullanicinin girdigi us sayisi alinir

		// UsAlma sinifindan bir nesne olustur
		UsAlma bulucu = new UsAlma();

		// 'usAl' metodunu cagir
		int sonuc = bulucu.usAl(taban, us);

		// Hesaplanan sonuc ekrana yazdirilir
		System.out.println("Sonuc = " + sonuc);

		// Scanner nesnesini kapat
		okuyucu.close();
	}
}

package com.thealgorithms.datastructures.queues;

import java.util.Deque;
import java.util.LinkedList;

/**
 * The {@code SlidingWindowMaximum} class provides a method to efficiently compute
 * the maximum element within every sliding window of size {@code k} in a given array.
 *
 * <p>The algorithm uses a deque to maintain the indices of useful elements within
 * the current sliding window. The time complexity of this approach is O(n) since
 * each element is processed at most twice.
 *
 * @author Hardvan
 */
public final class SlidingWindowMaximum {
    private SlidingWindowMaximum() {
    }

    /**
     * Returns an array of the maximum values for each sliding window of size {@code k}.
     * <p>If {@code nums} has fewer elements than {@code k}, the result will be an empty array.
     * <p>Example:
     * <pre>
     * Input: nums = [1, 3, -1, -3, 5, 3, 6, 7], k = 3
     * Output: [3, 3, 5, 5, 6, 7]
     * </pre>
     *
     * @param nums the input array of integers
     * @param k the size of the sliding window
     * @return an array containing the maximum element for each sliding window
     */
    public static int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        if (n < k || k == 0) {
            return new int[0];
        }

        int[] result = new int[n - k + 1];
        Deque<Integer> deque = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            // Remove elements from the front of the deque if they are out of the current window
            if (!deque.isEmpty() && deque.peekFirst() < i - k + 1) {
                deque.pollFirst();
            }

            // Remove elements from the back if they are smaller than the current element
            while (!deque.isEmpty() && nums[deque.peekLast()] < nums[i]) {
                deque.pollLast();
            }

            // Add the current element's index to the deque
            deque.offerLast(i);

            // Store the maximum element for the current window (starting from the k-1th element)
            if (i >= k - 1) {
                result[i - k + 1] = nums[deque.peekFirst()];
            }
        }

        return result;
    }
}

