package twodimensional;

import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;

public class TicTacToeGUI {

    private static final int BOARD_SIZE = 3;
    private static final String BLANK = " ";

    private final JFrame window;              // top-level application window
    private final JButton[][] cells;          // grid of clickable cells
    private char turnMarker;                  // symbol of whichever player is up next

    public TicTacToeGUI() {
        window = new JFrame("Tic-Tac-Toe");
        cells = new JButton[BOARD_SIZE][BOARD_SIZE];
        turnMarker = 'X';
        buildInterface();
    }

    private void buildInterface() {
        window.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        window.setSize(400, 400);
        window.setLayout(new GridLayout(BOARD_SIZE, BOARD_SIZE));

        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                JButton cellButton = new JButton(BLANK);
                cellButton.setFont(new Font("Arial", Font.PLAIN, 60));
                cells[row][col] = cellButton;
                window.add(cellButton);

                final int fixedRow = row;
                final int fixedCol = col;
                cellButton.addActionListener(new ActionListener() {
                    @Override
                    public void actionPerformed(ActionEvent event) {
                        handleCellClick(fixedRow, fixedCol);
                    }
                });
            }
        }

        window.setVisible(true);
    }

    private void handleCellClick(int row, int col) {
        if (!cells[row][col].getText().equals(BLANK)) {
            return; // cell already taken, ignore the click
        }

        cells[row][col].setText(String.valueOf(turnMarker));

        if (hasWinner()) {
            JOptionPane.showMessageDialog(window, "Tebrikler, " + turnMarker + " kazandi!");
            resetBoard();
        } else if (isDraw()) {
            JOptionPane.showMessageDialog(window, "Oyun berabere bitti!");
            resetBoard();
        } else {
            turnMarker = (turnMarker == 'X') ? 'O' : 'X';
        }
    }

    private boolean hasWinner() {
        String marker = String.valueOf(turnMarker);

        for (int i = 0; i < BOARD_SIZE; i++) {
            if (cells[i][0].getText().equals(marker) &&
                cells[i][1].getText().equals(marker) &&
                cells[i][2].getText().equals(marker)) {
                return true;
            }
            if (cells[0][i].getText().equals(marker) &&
                cells[1][i].getText().equals(marker) &&
                cells[2][i].getText().equals(marker)) {
                return true;
            }
        }

        if (cells[0][0].getText().equals(marker) &&
            cells[1][1].getText().equals(marker) &&
            cells[2][2].getText().equals(marker)) {
            return true;
        }

        return cells[0][2].getText().equals(marker) &&
               cells[1][1].getText().equals(marker) &&
               cells[2][0].getText().equals(marker);
    }

    private boolean isDraw() {
        for (JButton[] rowOfButtons : cells) {
            for (JButton button : rowOfButtons) {
                if (button.getText().equals(BLANK)) {
                    return false;
                }
            }
        }
        return true;
    }

    private void resetBoard() {
        for (JButton[] rowOfButtons : cells) {
            for (JButton button : rowOfButtons) {
                button.setText(BLANK);
            }
        }
        turnMarker = 'X';
    }

    public static void main(String[] args) {
        new TicTacToeGUI();
    }
}

/**
 * The simple substitution cipher is a cipher that has been in use for many
 * hundreds of years (an excellent history is given in Simon Singhs 'the Code
 * Book'). It basically consists of substituting every plaintext character for a
 * different ciphertext character. It differs from the Caesar cipher in that the
 * cipher alphabet is not simply the alphabet shifted, it is completely jumbled.
 */
public class SimpleSubCipher {

    /**
     * Encrypt text by replacing each element with its opposite character.
     *
     * @param message
     * @param cipherSmall
     * @return Encrypted message
     */
    public String encode(String message, String cipherSmall) {
        StringBuilder encoded = new StringBuilder();

        // This map is used to encode
        Map<Character, Character> cipherMap = new HashMap<>();

        char beginSmallLetter = 'a';
        char beginCapitalLetter = 'A';

        cipherSmall = cipherSmall.toLowerCase();
        String cipherCapital = cipherSmall.toUpperCase();

        // To handle Small and Capital letters
        for (int i = 0; i < cipherSmall.length(); i++) {
            cipherMap.put(beginSmallLetter++, cipherSmall.charAt(i));
            cipherMap.put(beginCapitalLetter++, cipherCapital.charAt(i));
        }

        for (int i = 0; i < message.length(); i++) {
            if (Character.isAlphabetic(message.charAt(i))) {
                encoded.append(cipherMap.get(message.charAt(i)));
            } else {
                encoded.append(message.charAt(i));
            }
        }

        return encoded.toString();
    }

    /**
     * Decrypt message by replacing each element with its opposite character in
     * cipher.
     *
     * @param encryptedMessage
     * @param cipherSmall
     * @return message
     */
    public String decode(String encryptedMessage, String cipherSmall) {
        StringBuilder decoded = new StringBuilder();

        Map<Character, Character> cipherMap = new HashMap<>();

        char beginSmallLetter = 'a';
        char beginCapitalLetter = 'A';

        cipherSmall = cipherSmall.toLowerCase();
        String cipherCapital = cipherSmall.toUpperCase();

        for (int i = 0; i < cipherSmall.length(); i++) {
            cipherMap.put(cipherSmall.charAt(i), beginSmallLetter++);
            cipherMap.put(cipherCapital.charAt(i), beginCapitalLetter++);
        }

        for (int i = 0; i < encryptedMessage.length(); i++) {
            if (Character.isAlphabetic(encryptedMessage.charAt(i))) {
                decoded.append(cipherMap.get(encryptedMessage.charAt(i)));
            } else {
                decoded.append(encryptedMessage.charAt(i));
            }
        }

        return decoded.toString();
    }
}

/**
 * Converts text to the NATO phonetic alphabet.
 * Examples:
 * "ABC" -> "Alpha Bravo Charlie"
 * "Hello" -> "Hotel Echo Lima Lima Oscar"
 * "123" -> "One Two Three"
 * "A1B2C3" -> "Alpha One Bravo Two Charlie Three"
 *
 * @author Hardvan
 */
public final class PhoneticAlphabetConverter {
    private PhoneticAlphabetConverter() {
    }

    private static final Map<Character, String> PHONETIC_MAP = new HashMap<>();

    static {
        PHONETIC_MAP.put('A', "Alpha");
        PHONETIC_MAP.put('B', "Bravo");
        PHONETIC_MAP.put('C', "Charlie");
        PHONETIC_MAP.put('D', "Delta");
        PHONETIC_MAP.put('E', "Echo");
        PHONETIC_MAP.put('F', "Foxtrot");
        PHONETIC_MAP.put('G', "Golf");
        PHONETIC_MAP.put('H', "Hotel");
        PHONETIC_MAP.put('I', "India");
        PHONETIC_MAP.put('J', "Juliett");
        PHONETIC_MAP.put('K', "Kilo");
        PHONETIC_MAP.put('L', "Lima");
        PHONETIC_MAP.put('M', "Mike");
        PHONETIC_MAP.put('N', "November");
        PHONETIC_MAP.put('O', "Oscar");
        PHONETIC_MAP.put('P', "Papa");
        PHONETIC_MAP.put('Q', "Quebec");
        PHONETIC_MAP.put('R', "Romeo");
        PHONETIC_MAP.put('S', "Sierra");
        PHONETIC_MAP.put('T', "Tango");
        PHONETIC_MAP.put('U', "Uniform");
        PHONETIC_MAP.put('V', "Victor");
        PHONETIC_MAP.put('W', "Whiskey");
        PHONETIC_MAP.put('X', "X-ray");
        PHONETIC_MAP.put('Y', "Yankee");
        PHONETIC_MAP.put('Z', "Zulu");
        PHONETIC_MAP.put('0', "Zero");
        PHONETIC_MAP.put('1', "One");
        PHONETIC_MAP.put('2', "Two");
        PHONETIC_MAP.put('3', "Three");
        PHONETIC_MAP.put('4', "Four");
        PHONETIC_MAP.put('5', "Five");
        PHONETIC_MAP.put('6', "Six");
        PHONETIC_MAP.put('7', "Seven");
        PHONETIC_MAP.put('8', "Eight");
        PHONETIC_MAP.put('9', "Nine");
    }

    /**
     * Converts text to the NATO phonetic alphabet.
     * Steps:
     * 1. Convert the text to uppercase.
     * 2. Iterate over each character in the text.
     * 3. Get the phonetic equivalent of the character from the map.
     * 4. Append the phonetic equivalent to the result.
     * 5. Append a space to separate the phonetic equivalents.
     * 6. Return the result.
     *
     * @param text the text to convert
     * @return the NATO phonetic alphabet
     */
    public static String textToPhonetic(String text) {
        StringBuilder phonetic = new StringBuilder();
        for (char c : text.toUpperCase().toCharArray()) {
            if (Character.isWhitespace(c)) {
                continue;
            }
            phonetic.append(PHONETIC_MAP.getOrDefault(c, String.valueOf(c))).append(" ");
        }
        return phonetic.toString().trim();
    }
}

/**
 * The {@code Intersection} class provides a method to compute the intersection of two integer arrays.
 * <p>
 * This intersection includes duplicate values — meaning elements are included in the result
 * as many times as they appear in both arrays (i.e., multiset intersection).
 * </p>
 *
 * <p>
 * The algorithm uses a {@link java.util.HashMap} to count occurrences of elements in the first array,
 * then iterates through the second array to collect common elements based on these counts.
 * </p>
 *
 * <p>
 * Example usage:
 * <pre>{@code
 * int[] array1 = {1, 2, 2, 1};
 * int[] array2 = {2, 2};
 * List<Integer> result = Intersection.intersection(array1, array2); // result: [2, 2]
 * }</pre>
 * </p>
 *
 * <p>
 * Note: The order of elements in the returned list depends on the order in the second input array.
 * </p>
 */
public final class Intersection {

    private Intersection() {
        // Utility class; prevent instantiation
    }

    /**
     * Computes the intersection of two integer arrays, preserving element frequency.
     * For example, given [1,2,2,3] and [2,2,4], the result will be [2,2].
     *
     * Steps:
     * 1. Count the occurrences of each element in the first array using a map.
     * 2. Iterate over the second array and collect common elements.
     *
     * @param arr1 the first array of integers
     * @param arr2 the second array of integers
     * @return a list containing the intersection of the two arrays (with duplicates),
     *         or an empty list if either array is null or empty
     */
    public static List<Integer> intersection(int[] arr1, int[] arr2) {
        if (arr1 == null || arr2 == null || arr1.length == 0 || arr2.length == 0) {
            return Collections.emptyList();
        }

        Map<Integer, Integer> countMap = new HashMap<>();
        for (int num : arr1) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        List<Integer> result = new ArrayList<>();
        for (int num : arr2) {
            if (countMap.getOrDefault(num, 0) > 0) {
                result.add(num);
                countMap.computeIfPresent(num, (k, v) -> v - 1);
            }
        }

        return result;
    }
}

/**
 * The A5KeyStreamGenerator class is responsible for generating key streams
 * for the A5/1 encryption algorithm using a combination of Linear Feedback Shift Registers (LFSRs).
 *
 * <p>
 * This class extends the CompositeLFSR and initializes a set of LFSRs with
 * a session key and a frame counter to produce a pseudo-random key stream.
 * </p>
 *
 * <p>
 * Note: Proper exception handling for invalid usage is to be implemented.
 * </p>
 */
public class A5KeyStreamGenerator extends CompositeLFSR {

private BitSet storedFrameCounter;
private BitSet currentFrameCounter;
private BitSet sessionKeyData;
private static final int INITIAL_CLOCK_CYCLES = 100;
private static final int GENERATED_STREAM_LENGTH = 228;

/**
 * Initializes the A5KeyStreamGenerator with the specified session key and frame counter.
 *
 * <p>
 * This method sets up the internal state of the LFSRs using the provided
 * session key and frame counter. It creates three LFSRs with specific
 * configurations and initializes them.
 * </p>
 *
 * @param keyData a BitSet representing the session key used for key stream generation.
 * @param frameData a BitSet representing the frame counter that influences the key stream.
 */
@Override
public void initialize(BitSet keyData, BitSet frameData) {
this.sessionKeyData = keyData;
this.currentFrameCounter = (BitSet) frameData.clone();
this.storedFrameCounter = (BitSet) frameData.clone();
registers.clear();
LFSR firstRegister = new LFSR(19, 8, new int[] {13, 16, 17, 18});
LFSR secondRegister = new LFSR(22, 10, new int[] {20, 21});
LFSR thirdRegister = new LFSR(23, 10, new int[] {7, 20, 21, 22});
registers.add(firstRegister);
registers.add(secondRegister);
registers.add(thirdRegister);
registers.forEach(register -> register.initialize(keyData, frameData));
}

/**
 * Re-initializes the key stream generator with the original session key
 * and frame counter. This method restores the generator to its initial
 * state.
 */
public void reInitialize() {
this.initialize(sessionKeyData, storedFrameCounter);
}

/**
 * Generates the next key stream of bits.
 *
 * <p>
 * This method performs an initial set of clocking cycles and then retrieves
 * a key stream of the specified length. After generation, it re-initializes
 * the internal registers.
 * </p>
 *
 * @return a BitSet containing the generated key stream bits.
 */
public BitSet getNextKeyStream() {
for (int cycleIndex = 1; cycleIndex <= INITIAL_CLOCK_CYCLES; ++cycleIndex) {
this.clock();
}
BitSet generatedStream = new BitSet(GENERATED_STREAM_LENGTH);
for (int bitPosition = 1; bitPosition <= GENERATED_STREAM_LENGTH; ++bitPosition) {
boolean currentBit = this.clock();
generatedStream.set(bitPosition - 1, currentBit);
}
resetInternalRegisters();
return generatedStream;
}

/**
 * Re-initializes the registers for the LFSRs.
 *
 * <p>
 * This method increments the frame counter and re-initializes each LFSR
 * with the current session key and frame counter.
 * </p>
 */
private void resetInternalRegisters() {
incrementFrameCount();
registers.forEach(register -> register.initialize(sessionKeyData, currentFrameCounter));
}

/**
 * Increments the current frame counter.
 *
 * <p>
 * This method uses a utility function to increment the frame counter,
 * which influences the key stream generation process.
 * </p>
 */
private void incrementFrameCount() {
Utils.increment(currentFrameCounter, FRAME_COUNTER_LENGTH);
}

/**
 * Retrieves the current frame counter.
 *
 * @return a BitSet representing the current state of the frame counter.
 */
public BitSet getFrameCounter() {
return currentFrameCounter;
}
}

