        // System.out.println("Is 0 odd? " + oddNumberChecker.checkIfNumberIsOdd(0));   // false

        // Demonstrating access through nested interface type
        A.NumberParityChecker interfaceBasedReference = oddNumberChecker;
        System.out.println("Is 9 odd? (via interface reference) " + interfaceBasedReference.checkIfNumberIsOdd(9));

