package com.thealgorithms.ciphers;

import java.util.HashMap;
import java.util.Map;

/**
 * The Baconian Cipher is a substitution cipher where each letter is represented
 * by a group of five binary digits (A's and B's). It can also be used to hide
 * messages within other texts, making it a simple form of steganography.
 * https://en.wikipedia.org/wiki/Bacon%27s_cipher
 *
 * @author Bennybebo
 */
public class BaconianCipher {

private static final Map<Character, String> ENCODE_MAP = new HashMap<>();
private static final Map<String, Character> DECODE_MAP = new HashMap<>();

static {
String[] binaryCodes = {"AAAAA", "AAAAB", "AAABA", "AAABB", "AABAA", "AABAB", "AABBA", "AABBB", "ABAAA", "ABAAB", "ABABA", "ABABB", "ABBAA", "ABBAB", "ABBBA", "ABBBB", "BAAAA", "BAAAB", "BAABA", "BAABB", "BABAA", "BABAB", "BABBA", "BABBB", "BBAAA", "BBAAB"};
char currentLetter = 'A';
for (String codeValue : binaryCodes) {
ENCODE_MAP.put(currentLetter, codeValue);
DECODE_MAP.put(codeValue, currentLetter);
currentLetter++;
}
ENCODE_MAP.put('I', ENCODE_MAP.get('J'));
DECODE_MAP.put(ENCODE_MAP.get('I'), 'I');
}

/**
 * Encrypts the given plaintext using the Baconian cipher.
 *
 * @param inputText The plaintext message to encrypt.
 * @return The ciphertext as a binary (A/B) sequence.
 */
public String encrypt(String inputText) {
StringBuilder encodedResult = new StringBuilder();
String cleanText = inputText.toUpperCase().replaceAll("[^A-Z]", "");
for (char letterChar : cleanText.toCharArray()) {
encodedResult.append(ENCODE_MAP.get(letterChar));
}
return encodedResult.toString();
}

/**
 * Decrypts the given ciphertext encoded in binary (A/B) format using the Baconian cipher.
 *
 * @param encodedText The ciphertext to decrypt.
 * @return The decrypted plaintext message.
 */
public String decrypt(String encodedText) {
StringBuilder decodedResult = new StringBuilder();
for (int position = 0; position < encodedText.length(); position += 5) {
String codeSegment = encodedText.substring(position, position + 5);
if (DECODE_MAP.containsKey(codeSegment)) {
decodedResult.append(DECODE_MAP.get(codeSegment));
} else {
throw new IllegalArgumentException("Invalid Baconian code: " + codeSegment);
}
}
return decodedResult.toString();
}
}

