package com.thealgorithms.conversions;

/**
 * Class for converting an Octal number to its Hexadecimal equivalent.
 *
 * @author Tanmay Joshi
 */
public final class OctalToHexadecimal {
private static final int OCTAL_RADIX = 8;
private static final int HEX_RADIX = 16;
private static final String HEX_SYMBOLS = "0123456789ABCDEF";

private OctalToHexadecimal() {
}

/**
 * Converts an Octal number (as a string) to its Decimal equivalent.
 *
 * @param octalString The Octal number as a string
 * @return The Decimal equivalent of the Octal number
 * @throws IllegalArgumentException if the input contains invalid octal digits
 */
public static int octalToDecimal(String octalString) {
if (octalString == null || octalString.isEmpty()) {
throw new IllegalArgumentException("Input cannot be null or empty");
}
int decimalValue = 0;
for (int position = 0; position < octalString.length(); position++) {
char currentChar = octalString.charAt(position);
if (currentChar < '0' || currentChar > '7') {
throw new IllegalArgumentException("Incorrect octal digit: " + currentChar);
}
int digitValue = currentChar - '0';
decimalValue = decimalValue * OCTAL_RADIX + digitValue;
}
return decimalValue;
}

/**
 * Converts a Decimal number to its Hexadecimal equivalent.
 *
 * @param decimalInput The Decimal number
 * @return The Hexadecimal equivalent of the Decimal number
 */
public static String decimalToHexadecimal(int decimalInput) {
if (decimalInput == 0) {
return "0";
}
StringBuilder hexResult = new StringBuilder();
int remainingValue = decimalInput;
while (remainingValue > 0) {
int remainderDigit = remainingValue % HEX_RADIX;
hexResult.insert(0, HEX_SYMBOLS.charAt(remainderDigit));
remainingValue /= HEX_RADIX;
}
return hexResult.toString();
}
}

package Cylinder;

/**
 * A cylinder that both extends Circle (its own top face) and composes
 * a Circle as its base, to contrast composition vs inheritance.
 */
public class Cylinder extends Circle {

    private Circle base;
    private double height = 1.0;

    public Cylinder() {
        this.base = new Circle();
    }

    public Cylinder(double radius) {
        super(radius);
        this.base = new Circle();
    }

    public Cylinder(double radius, String color) {
        super(radius, color);
        this.base = new Circle();
    }

    public Cylinder(double radius, double height) {
        super(radius);
        this.base = new Circle();
        this.height = height;
    }

    public Cylinder(double radius, double height, String color) {
        super(radius, color);
        this.height = height;
        this.base = new Circle();
    }

    public Cylinder(double radius1, String color1, double radius2, String color2) {
        super(radius1, color1);
        this.base = new Circle(radius2, color2);
    }

    public Cylinder(double height, double radius1, String color1, double radius2, String color2) {
        super(radius1, color1);
        this.height = height;
        this.base = new Circle(radius2, color2);
    }

    public Cylinder(double radius1, String color1, double radius2, String color2, double height) {
        super(radius1, color1);
        this.height = height;
        this.base = new Circle(radius2, color2);
    }

    public double getHeight() {
        return height;
    }

    public void setHeight(double height) {
        this.height = height;
    }

    public double getVolume() {
        return getArea() * height;
    }

    public Circle getBase() {
        return base;
    }

    public void setBase(Circle base) {
        this.base = base;
    }

    @Override
    public String toString() {
        return "Cylinder[" + "circle=" + super.toString() + "" + "base=" + base + ", height=" + height + '}';
    }
}

