public class LongVeriTuruOrnegi {

    public static void main(String[] args) {

        // long, short ve int turlerinden birer ornek deger
        long genisSayi = 2147483648L; // "L" son eki long sabiti belirtir
        short darSayi = 32000;
        int ortaSayi = 2147483647;

        System.out.println("Uzun Sayi: " + genisSayi);
        System.out.println("Kisa Sayi: " + darSayi);
        System.out.println("Tam Sayi: " + ortaSayi);

        // short + int toplami otomatik olarak int turune yukselir
        int toplamSonuc = darSayi + ortaSayi;
        System.out.println("Toplam: " + toplamSonuc);

        // long -> int -> short zincirinde acik donusumler (daraltma)
        long ikinciGenisSayi = 50000;
        int inteDonusen = (int) ikinciGenisSayi;
        short shortaDonusen = (short) inteDonusen;

        System.out.println("Uzun Sayi 2: " + ikinciGenisSayi);
        System.out.println("Tam Sayi 2: " + inteDonusen);
        System.out.println("Kisa Sayi 2: " + shortaDonusen);

        // Sinir degerleri
        System.out.println("Long veri turunun maksimum degeri: " + Long.MAX_VALUE);
        System.out.println("Long veri turunun minimum degeri: " + Long.MIN_VALUE);
        System.out.println("Short veri turunun maksimum degeri: " + Short.MAX_VALUE);
        System.out.println("Short veri turunun minimum degeri: " + Short.MIN_VALUE);
        System.out.println("Int veri turunun maksimum degeri: " + Integer.MAX_VALUE);
        System.out.println("Int veri turunun minimum degeri: " + Integer.MIN_VALUE);

        // long turu uzerinde aritmetik islemler
        long farkSonuc = genisSayi - ikinciGenisSayi;
        long carpimSonuc = genisSayi * ikinciGenisSayi;
        long bolumSonuc = genisSayi / ikinciGenisSayi;
        long kalanSonuc = genisSayi % ikinciGenisSayi;

        System.out.println("Long'tan Long'a Fark: " + farkSonuc);
        System.out.println("Long'tan Long'a Carpim: " + carpimSonuc);
        System.out.println("Long'tan Long'a Bolum: " + bolumSonuc);
        System.out.println("Long'tan Long'a Kalan: " + kalanSonuc);
    }
}

/**
 * Class to represent a fraction as a sum of unique unit fractions.
 * Example:
 * 2/3 = 1/2 + 1/6
 * 3/10 = 1/4 + 1/20
 *
 * @author Hardvan
 */
public final class EgyptianFraction {
    private EgyptianFraction() {
    }

    /**
     * Calculates the Egyptian Fraction representation of a given fraction.
     *
     * @param numerator   the numerator of the fraction
     * @param denominator the denominator of the fraction
     * @return List of unit fractions represented as strings "1/x"
     */
    public static List<String> getEgyptianFraction(int numerator, int denominator) {
        List<String> result = new ArrayList<>();
        while (numerator != 0) {
            int x = (int) Math.ceil((double) denominator / numerator);
            result.add("1/" + x);
            numerator = numerator * x - denominator;
            denominator = denominator * x;
        }
        return result;
    }
}

import java.util.Scanner;

/*
 * Modulo operatoru (%) kullanilarak sayinin 2'ye tam olarak bolunup bolunmedigi kontrol edilir. 
 * Eger bolunuyorsa, sayi cifttir. Bolunmuyorsa, sayi tektir. 
 */

public class TekMiCiftMi {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        // Kullanicidan bir sayi girmesini iste
        System.out.println("Bir sayi giriniz: ");
        int sayi = scan.nextInt();
        scan.close();

        // Sayinin tek mi cift mi oldugunu kontrol et
        if (sayi % 2 == 0) {
            System.out.println(sayi + " cift bir sayidir.");
        } else {
            System.out.println(sayi + " tek bir sayidir.");
        }
    }
}

/**
 * RSA is an asymmetric cryptographic algorithm used for secure data encryption and decryption.
 * It relies on a pair of keys: a public key (used for encryption) and a private key
 * (used for decryption). The algorithm is based on the difficulty of factoring large prime numbers.
 *
 * This implementation includes key generation, encryption, and decryption methods that can handle both
 * text-based messages and BigInteger inputs. For more details on RSA:
 * <a href="https://en.wikipedia.org/wiki/RSA_(cryptosystem)">RSA Cryptosystem - Wikipedia</a>.
 *
 * Example Usage:
 * <pre>
 * RSA rsa = new RSA(1024);
 * String encryptedMessage = rsa.encrypt("Hello RSA!");
 * String decryptedMessage = rsa.decrypt(encryptedMessage);
 * System.out.println(decryptedMessage);  // Output: Hello RSA!
 * </pre>
 *
 * Note: The key size directly affects the security and performance of the RSA algorithm.
 * Larger keys are more secure but slower to compute.
 *
 * @author Nguyen Duy Tiep
 * @version 23-Oct-17
 */
public class RSA {

    private BigInteger modulus;
    private BigInteger privateKey;
    private BigInteger publicKey;

    /**
     * Constructor that generates RSA keys with the specified number of bits.
     *
     * @param bits The bit length of the keys to be generated. Common sizes include 512, 1024, 2048, etc.
     */
    public RSA(int bits) {
        generateKeys(bits);
    }

    /**
     * Encrypts a text message using the RSA public key.
     *
     * @param message The plaintext message to be encrypted.
     * @throws IllegalArgumentException If the message is empty.
     * @return The encrypted message represented as a String.
     */
    public synchronized String encrypt(String message) {
        if (message.isEmpty()) {
            throw new IllegalArgumentException("Message is empty");
        }
        return (new BigInteger(message.getBytes())).modPow(publicKey, modulus).toString();
    }

    /**
     * Encrypts a BigInteger message using the RSA public key.
     *
     * @param message The plaintext message as a BigInteger.
     * @return The encrypted message as a BigInteger.
     */
    public synchronized BigInteger encrypt(BigInteger message) {
        return message.modPow(publicKey, modulus);
    }

    /**
     * Decrypts an encrypted message (as String) using the RSA private key.
     *
     * @param encryptedMessage The encrypted message to be decrypted, represented as a String.
     * @throws IllegalArgumentException If the message is empty.
     * @return The decrypted plaintext message as a String.
     */
    public synchronized String decrypt(String encryptedMessage) {
        if (encryptedMessage.isEmpty()) {
            throw new IllegalArgumentException("Message is empty");
        }
        return new String((new BigInteger(encryptedMessage)).modPow(privateKey, modulus).toByteArray());
    }

    /**
     * Decrypts an encrypted BigInteger message using the RSA private key.
     *
     * @param encryptedMessage The encrypted message as a BigInteger.
     * @return The decrypted plaintext message as a BigInteger.
     */
    public synchronized BigInteger decrypt(BigInteger encryptedMessage) {
        return encryptedMessage.modPow(privateKey, modulus);
    }

    /**
     * Generates a new RSA key pair (public and private keys) with the specified bit length.
     * Steps:
     * 1. Generate two large prime numbers p and q.
     * 2. Compute the modulus n = p * q.
     * 3. Compute Euler's totient function: φ(n) = (p-1) * (q-1).
     * 4. Choose a public key e (starting from 3) that is coprime with φ(n).
     * 5. Compute the private key d as the modular inverse of e mod φ(n).
     * The public key is (e, n) and the private key is (d, n).
     *
     * @param bits The bit length of the keys to be generated.
     */
    public final synchronized void generateKeys(int bits) {
        SecureRandom random = new SecureRandom();
        BigInteger p = new BigInteger(bits / 2, 100, random);
        BigInteger q = new BigInteger(bits / 2, 100, random);
        modulus = p.multiply(q);

        BigInteger phi = (p.subtract(BigInteger.ONE)).multiply(q.subtract(BigInteger.ONE));

        publicKey = BigInteger.valueOf(3L);
        while (phi.gcd(publicKey).intValue() > 1) {
            publicKey = publicKey.add(BigInteger.TWO);
        }

        privateKey = publicKey.modInverse(phi);
    }
}

// Adds two integer matrices of the same shape element by element.
package twodimensional;

public class MatrisToplami {

    public static void main(String[] args) {
        int[][] matrixA = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };

        int[][] matrixB = {
            {9, 8, 7},
            {6, 5, 4},
            {3, 2, 1}
        };

        int rowCount = matrixA.length;
        int colCount = matrixA[0].length;
        int[][] sumMatrix = new int[rowCount][colCount];

        for (int r = 0; r < rowCount; r++) {
            for (int c = 0; c < colCount; c++) {
                sumMatrix[r][c] = matrixA[r][c] + matrixB[r][c];
            }
        }

        System.out.println("Matris Toplami:");
        for (int r = 0; r < rowCount; r++) {
            StringBuilder line = new StringBuilder();
            for (int c = 0; c < colCount; c++) {
                line.append(sumMatrix[r][c]).append(' ');
            }
            System.out.println(line.toString().trim());
        }
    }
}

