package com.ankan.inheritance;

public class BoxWeight extends Box {
    double boxWeight; // Weight of the box (could represent mass or shipping weight)

    // Default constructor - initializes weight to -1 (sentinel value)
    public BoxWeight() {
        this.boxWeight = -1.0;
    }

//    // Example of why static methods cannot be overridden (commented)
//    // @Override annotation is not allowed on static methods
//    static void displayGreeting() {
//        System.out.println("Greetings from BoxWeight class!");
//    }

    // Copy constructor - creates a BoxWeight from an existing BoxWeight object
    BoxWeight(BoxWeight existingBoxWeight) {
        super(existingBoxWeight); // Calls the Box(Box old) copy constructor
        // Explanation: super(existingBoxWeight) refers to the parent class constructor
        // Box(Box old) which copies length, height, and width from the source object

        this.boxWeight = existingBoxWeight.boxWeight;

        // Important OOP note: It's the reference variable type, not the actual object type,
        // that determines which members can be accessed at compile time.
        // System.out.println(super.boxWeight); // This would not work - parent class doesn't have weight
    }

    // Constructor that only sets the weight
    public BoxWeight(double weightValue) {
        this.boxWeight = weightValue;
        // Note: Parent class fields (length, height, width) remain uninitialized (default 0.0)
    }

    // Constructor for cube-shaped boxes (all dimensions equal) with specified weight
    public BoxWeight(double sideLength, double weightValue) {
        super(sideLength); // Calls Box(double side) cube constructor
        this.boxWeight = weightValue;
    }

    // Fully parameterized constructor - sets all dimensions and weight
    public BoxWeight(double boxLength, double boxHeight, double boxWidth, double weightValue) {
        super(boxLength, boxHeight, boxWidth); // Calls Box(double l, double h, double w) constructor
        this.boxWeight = weightValue;

        // Demonstrating field access - 'this.w' accesses the width field from current class
        // 'super.w' accesses the width field from parent class (same value in this case)
        System.out.println("Width accessed via 'this': " + this.width);
        System.out.println("Width accessed via 'super': " + super.width);
    }

    // Constructor that combines a regular Box object with additional weight
    public BoxWeight(Box existingBox, double weightValue) {
        super(existingBox); // Copies dimensions from the existing Box object
        this.boxWeight = weightValue;
    }

    // Additional method to display box weight information (educational enhancement)
    public void displayWeightInfo() {
        System.out.println("Box weight: " + boxWeight + " units");
    }
}

package collections;

import java.util.ArrayList;

public class ArrayListOrnegi {

    public static void main(String[] args) {

        ArrayList<String> katilimcilar = new ArrayList<>();

        katilimcilar.add("Alice");
        katilimcilar.add("Bob");
        katilimcilar.add("Charlie");
        katilimcilar.add("Dave");
        katilimcilar.add("Eve");

        System.out.println("Orijinal liste: " + katilimcilar);

        // Index 3'teki degeri degistir
        katilimcilar.set(3, "Carol");
        System.out.println("Degistirilmis liste: " + katilimcilar);

        // Son elemani listeden cikar
        katilimcilar.remove(4);
        System.out.println("Degistirilmis liste: " + katilimcilar);

        // Belirli bir konuma yeni eleman ekle
        katilimcilar.add(2, "Frank");
        System.out.println("Degistirilmis liste: " + katilimcilar);

        int bobunKonumu = katilimcilar.indexOf("Bob");
        System.out.println("Bob'un index'i: " + bobunKonumu);

        boolean eveVarMi = katilimcilar.contains("Eve");
        System.out.println("Liste 'Eve'yi iceriyor mu: " + eveVarMi);

        int toplamEleman = katilimcilar.size();
        System.out.println("Listenin boyutu: " + toplamEleman);
    }
}

/*
 * Byte veri turu, -128 ile 127 arasinda bir tam sayiyi depolayabilen veri turudur. 
 * Kodda, byte veri turunun en kucuk ve en buyuk degerleri yazdirilir ve byte degiskenleriyle 
 * aritmetik islemler yapilir.
 */

public class ByteVeriTuruOrnegi {

    public static void main(String[] args) {

        // byte veri turunu kullanarak bir degisken tanimla
        byte minDeger = Byte.MIN_VALUE; // Byte turunun en kucuk degeri
        byte maxDeger = Byte.MAX_VALUE; // Byte turunun en buyuk degeri

        // Degerleri yazdir
        System.out.println("Byte veri turunun en kucuk degeri: " + minDeger);
        System.out.println("Byte veri turunun en buyuk degeri: " + maxDeger);

        // Bir byte degiskeni kullanarak aritmetik islem yap
        byte sayi1 = 80;
        byte sayi2 = 50;
        byte toplam = (byte) (sayi1 + sayi2); // Toplam sonucunu bir byte'a donusturmek gerekebilir
        System.out.println("Toplam: " + toplam);

        // Cikarma islemi
        byte fark = (byte) (sayi1 - sayi2); // Fark sonucunu bir byte'a donustur
        System.out.println("Fark: " + fark);

        // Carpma islemi
        byte carpim = (byte) (sayi1 * sayi2); // Carpim sonucunu bir byte'a donustur
        System.out.println("Carpim: " + carpim);

        // Bolme islemi
        byte bolum = (byte) (sayi1 / sayi2); // Bolum sonucunu bir byte'a donustur
        System.out.println("Bolum: " + bolum);

        // Modulus islemi (kalan)
        byte kalan = (byte) (sayi1 % sayi2); // Modulus sonucunu bir byte'a donustur
        System.out.println("Kalan: " + kalan);

        // Byte degerinin sinirlarini kontrol etme
        byte sinirKontrol = 127;
        System.out.println("Sinir Kontrol: " + sinirKontrol);
        if (sinirKontrol == Byte.MAX_VALUE) {
            System.out.println("Sinirda bir deger var.");
        } else {
            System.out.println("Sinirda degil.");
        }

        // Byte degiskeni ile bitwise islemler
        byte a = 5; // 00000101
        byte b = 3; // 00000011
        byte sonuc = (byte) (a & b); // AND islemi
        System.out.println("AND islemi sonucu: " + sonuc);

        sonuc = (byte) (a | b); // OR islemi
        System.out.println("OR islemi sonucu: " + sonuc);

        sonuc = (byte) (a ^ b); // XOR islemi
        System.out.println("XOR islemi sonucu: " + sonuc);

        sonuc = (byte) (~a); // NOT islemi
        System.out.println("NOT islemi sonucu: " + sonuc);
    }
}

package mysql; 

import java.sql.*;
import java.util.Scanner;

public class MySQLDemo {

    public static void main(String[] args) throws SQLException, ClassNotFoundException {

        // MySQL surucusunu kaydet
        Class.forName("com.mysql.jdbc.Driver");

        // Veritabanina baglanti olustur
        String url = "jdbc:mysql://localhost:3306/testdb";
        String username = "root";
        String password = "password";

        try (Connection connection = DriverManager.getConnection(url, username, password);
             Statement statement = connection.createStatement();
             Scanner scanner = new Scanner(System.in)) {

            // Kullanicidan islem tipi al
            System.out.println("Yapmak istediginiz islemi secin: ");
            System.out.println("1 - Yeni kayit ekle");
            System.out.println("2 - Kayit guncelle");
            System.out.println("3 - Kayit sil");
            System.out.println("4 - Tum kayitlari listele");
            System.out.print("Seciminizi yapin: ");
            int choice = scanner.nextInt();
            scanner.nextLine();  // Bu satir, 'nextInt' sonrasi gelen '\n' karakterini temizler

            switch (choice) {
                case 1:
                    // Yeni bir kayit ekle
                    System.out.print("Adinizi girin: ");
                    String name = scanner.nextLine();
                    System.out.print("Email adresinizi girin: ");
                    String email = scanner.nextLine();
                    String insertSql = "iNSERT iNTO users (name, email) VALUES (?, ?)";
                    try (PreparedStatement pstmt = connection.prepareStatement(insertSql)) {
                        pstmt.setString(1, name);
                        pstmt.setString(2, email);
                        pstmt.executeUpdate();
                        System.out.println("Yeni kayit basariyla eklendi.");
                    }
                    break;

                case 2:
                    // Var olan bir kaydi guncelle
                    System.out.print("Guncellemek istediginiz kullanicinin iD'sini girin: ");
                    int idToUpdate = scanner.nextInt();
                    scanner.nextLine(); // 'nextInt' sonrasi gelen '\n' karakterini temizler
                    System.out.print("Yeni ad girin: ");
                    String newName = scanner.nextLine();
                    System.out.print("Yeni email adresi girin: ");
                    String newEmail = scanner.nextLine();
                    String updateSql = "UPDATE users SET name = ?, email = ? WHERE id = ?";
                    try (PreparedStatement pstmt = connection.prepareStatement(updateSql)) {
                        pstmt.setString(1, newName);
                        pstmt.setString(2, newEmail);
                        pstmt.setInt(3, idToUpdate);
                        int rowsUpdated = pstmt.executeUpdate();
                        if (rowsUpdated > 0) {
                            System.out.println("Kullanici guncellendi.");
                        } else {
                            System.out.println("Kullanici bulunamadi.");
                        }
                    }
                    break;

                case 3:
                    // Bir kaydi sil
                    System.out.print("Silmek istediginiz kullanicinin iD'sini girin: ");
                    int idToDelete = scanner.nextInt();
                    String deleteSql = "DELETE FROM users WHERE id = ?";
                    try (PreparedStatement pstmt = connection.prepareStatement(deleteSql)) {
                        pstmt.setInt(1, idToDelete);
                        int rowsDeleted = pstmt.executeUpdate();
                        if (rowsDeleted > 0) {
                            System.out.println("Kullanici silindi.");
                        } else {
                            System.out.println("Kullanici bulunamadi.");
                        }
                    }
                    break;

                case 4:
                    // Tum kayitlari listele
                    String selectSql = "SELECT * FROM users";
                    try (ResultSet resultSet = statement.executeQuery(selectSql)) {
                        while (resultSet.next()) {
                            int id = resultSet.getInt("id");
                            String userName = resultSet.getString("name");
                            String userEmail = resultSet.getString("email");
                            System.out.println("iD: " + id + ", Name: " + userName + ", Email: " + userEmail);
                        }
                    }
                    break;

                default:
                    System.out.println("Gecersiz secim.");
            }
        }
    }
}

package com.thealgorithms.datastructures.hashmap.hashing;

/**
 * Immutable HashMap implementation using separate chaining.
 *
 * <p>This HashMap does not allow modification of existing instances.
 * Any update operation returns a new ImmutableHashMap.
 *
 * @param <K> key type
 * @param <V> value type
 */
public final class ImmutableHashMap<K, V> {

    private static final int DEFAULT_CAPACITY = 16;

    private final Node<K, V>[] table;
    private final int size;

    /**
     * Private constructor to enforce immutability.
     */
    private ImmutableHashMap(Node<K, V>[] table, int size) {
        this.table = table;
        this.size = size;
    }

    /**
     * Creates an empty ImmutableHashMap.
     *
     * @param <K> key type
     * @param <V> value type
     * @return empty ImmutableHashMap
     */
    @SuppressWarnings({"unchecked", "rawtypes"})
    public static <K, V> ImmutableHashMap<K, V> empty() {
        Node<K, V>[] table = (Node<K, V>[]) new Node[DEFAULT_CAPACITY];
        return new ImmutableHashMap<>(table, 0);
    }

    /**
     * Returns a new ImmutableHashMap with the given key-value pair added.
     *
     * @param key key to add
     * @param value value to associate
     * @return new ImmutableHashMap instance
     */
    public ImmutableHashMap<K, V> put(K key, V value) {
        Node<K, V>[] newTable = table.clone();
        int index = hash(key);

        newTable[index] = new Node<>(key, value, newTable[index]);
        return new ImmutableHashMap<>(newTable, size + 1);
    }

    /**
     * Retrieves the value associated with the given key.
     *
     * @param key key to search
     * @return value if found, otherwise null
     */
    public V get(K key) {
        int index = hash(key);
        Node<K, V> current = table[index];

        while (current != null) {
            if ((key == null && current.key == null) || (key != null && key.equals(current.key))) {
                return current.value;
            }
            current = current.next;
        }
        return null;
    }

    /**
     * Checks whether the given key exists in the map.
     *
     * @param key key to check
     * @return true if key exists, false otherwise
     */
    public boolean containsKey(K key) {
        return get(key) != null;
    }

    /**
     * Returns the number of key-value pairs.
     *
     * @return size of the map
     */
    public int size() {
        return size;
    }

    /**
     * Computes hash index for a given key.
     */
    private int hash(K key) {
        return key == null ? 0 : (key.hashCode() & Integer.MAX_VALUE) % table.length;
    }

    /**
     * Node class for separate chaining.
     */
    private static final class Node<K, V> {

        private final K key;
        private final V value;
        private final Node<K, V> next;

        private Node(K key, V value, Node<K, V> next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }
}

/**
 * Tabulation (Bottom-Up) Solution for 0-1 Knapsack Problem.
 * This method uses dynamic programming to build up a solution iteratively,
 * filling a 2-D array where each entry dp[i][w] represents the maximum value
 * achievable with the first i items and a knapsack capacity of w.
 *
 * The tabulation approach is efficient because it avoids redundant calculations
 * by solving all subproblems in advance and storing their results, ensuring
 * each subproblem is solved only once. This is a key technique in dynamic programming,
 * making it possible to solve problems that would otherwise be infeasible due to
 * exponential time complexity in naive recursive solutions.
 *
 * Time Complexity: O(n * W), where n is the number of items and W is the knapsack capacity.
 * Space Complexity: O(n * W) for the DP table.
 *
 * For more information, see:
 * https://en.wikipedia.org/wiki/Knapsack_problem#Dynamic_programming
 */
public final class KnapsackZeroOneTabulation {

    private KnapsackZeroOneTabulation() {
        // Prevent instantiation
    }

    /**
     * Solves the 0-1 Knapsack problem using the bottom-up tabulation technique.
     * @param values the values of the items
     * @param weights the weights of the items
     * @param capacity the total capacity of the knapsack
     * @param itemCount the number of items
     * @return the maximum value that can be put in the knapsack
     * @throws IllegalArgumentException if input arrays are null, of different lengths,or if capacity or itemCount is invalid
     */
    public static int compute(final int[] values, final int[] weights, final int capacity, final int itemCount) {
        if (values == null || weights == null) {
            throw new IllegalArgumentException("Values and weights arrays must not be null.");
        }
        if (values.length != weights.length) {
            throw new IllegalArgumentException("Values and weights arrays must be non-null and of same length.");
        }
        if (capacity < 0) {
            throw new IllegalArgumentException("Capacity must not be negative.");
        }
        if (itemCount < 0 || itemCount > values.length) {
            throw new IllegalArgumentException("Item count must be between 0 and the length of the values array.");
        }

        final int[][] dp = new int[itemCount + 1][capacity + 1];

        for (int i = 1; i <= itemCount; i++) {
            final int currentValue = values[i - 1];
            final int currentWeight = weights[i - 1];

            for (int w = 1; w <= capacity; w++) {
                if (currentWeight <= w) {
                    final int includeItem = currentValue + dp[i - 1][w - currentWeight];
                    final int excludeItem = dp[i - 1][w];
                    dp[i][w] = Math.max(includeItem, excludeItem);
                } else {
                    dp[i][w] = dp[i - 1][w];
                }
            }
        }

        return dp[itemCount][capacity];
    }
}

public class Main {
    public static void main(String[] args) throws CloneNotSupportedException {
        Human originalPerson = new Human(21, "OriginalName");
//        Human twin = new Human(originalPerson); //creating a copy of originalPerson. Instead we can use object cloning.

        Human clonedPerson = (Human)originalPerson.clone();
        System.out.println(clonedPerson.ageValue + " " + clonedPerson.fullName);
        System.out.println(Arrays.toString(clonedPerson.dataArray));

        clonedPerson.dataArray[0] = 100; // for primitive arrays, shallow copy does not create a new array copy.
        // It just points to the original array reference. Even for String (which is immutable), it just points to the original reference.
        // This demonstrates shallow copying behavior.

        System.out.println(Arrays.toString(clonedPerson.dataArray));
        System.out.println(Arrays.toString(originalPerson.dataArray)); // demonstrates that original array is also modified
        // in shallow copy — very important concept
    }
}

/**
 * The {@code Tribonacci} class provides a method to compute the n-th number in the Tribonacci sequence.
 * N-th Tribonacci Number - https://leetcode.com/problems/n-th-tribonacci-number/description/
 */
public final class Tribonacci {
    private Tribonacci() {
    }

    /**
     * Computes the n-th Tribonacci number.
     *
     * @param n the index of the Tribonacci number to compute
     * @return the n-th Tribonacci number
     */
    public static int compute(int n) {
        if (n == 0) {
            return 0;
        }
        if (n == 1 || n == 2) {
            return 1;
        }

        int first = 0;
        int second = 1;
        int third = 1;

        for (int i = 3; i <= n; i++) {
            int next = first + second + third;
            first = second;
            second = third;
            third = next;
        }

        return third;
    }
}

package com.thealgorithms.geometry;

import java.awt.geom.Point2D;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.NavigableSet;
import java.util.Objects;
import java.util.PriorityQueue;
import java.util.Set;
import java.util.SortedSet;
import java.util.TreeSet;

/**
 * Implementation of the Bentley–Ottmann algorithm for finding all intersection
 * points among a set of line segments in O((n + k) log n) time.
 *
 * <p>Uses a sweep-line approach with an event queue and status structure to
 * efficiently detect intersections in 2D plane geometry.</p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Bentley%E2%80%93Ottmann_algorithm">
 *      Bentley–Ottmann algorithm</a>
 */
public final class BentleyOttmann {

    private BentleyOttmann() {
    }

    private static final double EPS = 1e-9;
    private static double currentSweepX;

    /**
     * Represents a line segment with two endpoints.
     */
    public static class Segment {
        final Point2D.Double p1;
        final Point2D.Double p2;
        final int id; // Unique identifier for each segment

        Segment(Point2D.Double p1, Point2D.Double p2) {
            this.p1 = p1;
            this.p2 = p2;
            this.id = segmentCounter++;
        }

        private static int segmentCounter = 0;

        /**
         * Computes the y-coordinate of this segment at a given x value.
         */
        double getY(double x) {
            if (Math.abs(p2.x - p1.x) < EPS) {
                // Vertical segment: return midpoint y
                return (p1.y + p2.y) / 2.0;
            }
            double t = (x - p1.x) / (p2.x - p1.x);
            return p1.y + t * (p2.y - p1.y);
        }

        Point2D.Double leftPoint() {
            return p1.x < p2.x ? p1 : p1.x > p2.x ? p2 : p1.y < p2.y ? p1 : p2;
        }

        Point2D.Double rightPoint() {
            return p1.x > p2.x ? p1 : p1.x < p2.x ? p2 : p1.y > p2.y ? p1 : p2;
        }

        @Override
        public String toString() {
            return String.format("S%d[(%.2f, %.2f), (%.2f, %.2f)]", id, p1.x, p1.y, p2.x, p2.y);
        }
    }

    /**
     * Event types for the sweep line algorithm.
     */
    private enum EventType { START, END, INTERSECTION }

    /**
     * Represents an event in the event queue.
     */
    private static class Event implements Comparable<Event> {
        final Point2D.Double point;
        final EventType type;
        final Set<Segment> segments; // Segments involved in this event

        Event(Point2D.Double point, EventType type) {
            this.point = point;
            this.type = type;
            this.segments = new HashSet<>();
        }

        void addSegment(Segment s) {
            segments.add(s);
        }

        @Override
        public int compareTo(Event other) {
            // Sort by x-coordinate, then by y-coordinate
            int cmp = Double.compare(this.point.x, other.point.x);
            if (cmp == 0) {
                cmp = Double.compare(this.point.y, other.point.y);
            }
            if (cmp == 0) {
                // Process END events before START events at same point
                cmp = this.type.compareTo(other.type);
            }
            return cmp;
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Event e)) {
                return false;
            }
            return pointsEqual(this.point, e.point);
        }

        @Override
        public int hashCode() {
            return Objects.hash(Math.round(point.x * 1e6), Math.round(point.y * 1e6));
        }
    }

    /**
     * Comparator for segments in the status structure (sweep line).
     * Orders segments by their y-coordinate at the current sweep line position.
     */
    private static final class StatusComparator implements Comparator<Segment> {
        @Override
        public int compare(Segment s1, Segment s2) {
            if (s1.id == s2.id) {
                return 0;
            }

            double y1 = s1.getY(currentSweepX);
            double y2 = s2.getY(currentSweepX);

            int cmp = Double.compare(y1, y2);
            if (Math.abs(y1 - y2) < EPS) {
                // If y-coordinates are equal, use segment id for consistency
                return Integer.compare(s1.id, s2.id);
            }
            return cmp;
        }
    }

    /**
     * Finds all intersection points among a set of line segments.
     *
     * <p>An intersection point is reported when two or more segments cross or touch.
     * For overlapping segments, only actual crossing/touching points are reported,
     * not all points along the overlap.</p>
     *
     * @param segments list of line segments represented as pairs of points
     * @return a set of intersection points where segments meet or cross
     * @throws IllegalArgumentException if the list is null or contains null points
     */
    public static Set<Point2D.Double> findIntersections(List<Segment> segments) {
        if (segments == null) {
            throw new IllegalArgumentException("Segment list must not be null");
        }

        Segment.segmentCounter = 0; // Reset counter
        Set<Point2D.Double> intersections = new HashSet<>();
        PriorityQueue<Event> eventQueue = new PriorityQueue<>();
        TreeSet<Segment> status = new TreeSet<>(new StatusComparator());
        Map<Point2D.Double, Event> eventMap = new HashMap<>();

        // Initialize event queue with segment start and end points
        for (Segment s : segments) {
            Point2D.Double left = s.leftPoint();
            Point2D.Double right = s.rightPoint();

            Event startEvent = getOrCreateEvent(eventMap, left, EventType.START);
            startEvent.addSegment(s);

            Event endEvent = getOrCreateEvent(eventMap, right, EventType.END);
            endEvent.addSegment(s);
        }

        // Add all unique events to the queue
        for (Event e : eventMap.values()) {
            if (!e.segments.isEmpty()) {
                eventQueue.add(e);
            }
        }

        // Process events
        while (!eventQueue.isEmpty()) {
            Event event = eventQueue.poll();
            currentSweepX = event.point.x;

            handleEvent(event, status, eventQueue, eventMap, intersections);
        }

        return intersections;
    }

    private static Event getOrCreateEvent(Map<Point2D.Double, Event> eventMap, Point2D.Double point, EventType type) {
        // Find existing event at this point
        for (Map.Entry<Point2D.Double, Event> entry : eventMap.entrySet()) {
            if (pointsEqual(entry.getKey(), point)) {
                return entry.getValue();
            }
        }
        // Create new event
        Event event = new Event(point, type);
        eventMap.put(point, event);
        return event;
    }

    private static void handleEvent(Event event, TreeSet<Segment> status, PriorityQueue<Event> eventQueue, Map<Point2D.Double, Event> eventMap, Set<Point2D.Double> intersections) {
        Point2D.Double p = event.point;
        Set<Segment> segmentsAtPoint = new HashSet<>(event.segments);

        // Check segments in status structure (much smaller than allSegments)
        for (Segment s : status) {
            if (pointsEqual(s.p1, p) || pointsEqual(s.p2, p) || (onSegment(s, p) && !pointsEqual(s.p1, p) && !pointsEqual(s.p2, p))) {
                segmentsAtPoint.add(s);
            }
        }

        // If 2 or more segments meet at this point, it's an intersection
        if (segmentsAtPoint.size() >= 2) {
            intersections.add(p);
        }

        // Categorize segments
        Set<Segment> upperSegs = new HashSet<>(); // Segments starting at p
        Set<Segment> lowerSegs = new HashSet<>(); // Segments ending at p
        Set<Segment> containingSegs = new HashSet<>(); // Segments containing p in interior

        for (Segment s : segmentsAtPoint) {
            if (pointsEqual(s.leftPoint(), p)) {
                upperSegs.add(s);
            } else if (pointsEqual(s.rightPoint(), p)) {
                lowerSegs.add(s);
            } else {
                containingSegs.add(s);
            }
        }

        // Remove ending segments and segments containing p from status
        status.removeAll(lowerSegs);
        status.removeAll(containingSegs);

        // Update sweep line position slightly past the event
        currentSweepX = p.x + EPS;

        // Add starting segments and re-add containing segments
        status.addAll(upperSegs);
        status.addAll(containingSegs);

        if (upperSegs.isEmpty() && containingSegs.isEmpty()) {
            // Find neighbors and check for new intersections
            Segment sl = getNeighbor(status, lowerSegs, true);
            Segment sr = getNeighbor(status, lowerSegs, false);
            if (sl != null && sr != null) {
                findNewEvent(sl, sr, p, eventQueue, eventMap);
            }
        } else {
            Set<Segment> unionSegs = new HashSet<>(upperSegs);
            unionSegs.addAll(containingSegs);

            Segment leftmost = getLeftmost(unionSegs, status);
            Segment rightmost = getRightmost(unionSegs, status);

            if (leftmost != null) {
                Segment sl = status.lower(leftmost);
                if (sl != null) {
                    findNewEvent(sl, leftmost, p, eventQueue, eventMap);
                }
            }

            if (rightmost != null) {
                Segment sr = status.higher(rightmost);
                if (sr != null) {
                    findNewEvent(rightmost, sr, p, eventQueue, eventMap);
                }
            }
        }
    }

    private static Segment getNeighbor(NavigableSet<Segment> status, Set<Segment> removed, boolean lower) {
        if (removed.isEmpty()) {
            return null;
        }
        Segment ref = removed.iterator().next();
        return lower ? status.lower(ref) : status.higher(ref);
    }

    private static Segment getLeftmost(Set<Segment> segments, SortedSet<Segment> status) {
        Segment leftmost = null;
        for (Segment s : segments) {
            if (leftmost == null || Objects.requireNonNull(status.comparator()).compare(s, leftmost) < 0) {
                leftmost = s;
            }
        }
        return leftmost;
    }

    private static Segment getRightmost(Set<Segment> segments, SortedSet<Segment> status) {
        Segment rightmost = null;
        for (Segment s : segments) {
            if (status.comparator() != null && (rightmost == null || status.comparator().compare(s, rightmost) > 0)) {
                rightmost = s;
            }
        }
        return rightmost;
    }

    private static void findNewEvent(Segment s1, Segment s2, Point2D.Double currentPoint, PriorityQueue<Event> eventQueue, Map<Point2D.Double, Event> eventMap) {
        Point2D.Double intersection = getIntersection(s1, s2);

        if (intersection != null && intersection.x > currentPoint.x - EPS && !pointsEqual(intersection, currentPoint)) {

            // Check if event already exists
            boolean exists = false;
            for (Map.Entry<Point2D.Double, Event> entry : eventMap.entrySet()) {
                if (pointsEqual(entry.getKey(), intersection)) {
                    exists = true;
                    Event existingEvent = entry.getValue();
                    existingEvent.addSegment(s1);
                    existingEvent.addSegment(s2);
                    break;
                }
            }

            if (!exists) {
                Event newEvent = new Event(intersection, EventType.INTERSECTION);
                newEvent.addSegment(s1);
                newEvent.addSegment(s2);
                eventMap.put(intersection, newEvent);
                eventQueue.add(newEvent);
            }
        }
    }

    private static Point2D.Double getIntersection(Segment s1, Segment s2) {
        double x1 = s1.p1.x;
        double y1 = s1.p1.y;
        double x2 = s1.p2.x;
        double y2 = s1.p2.y;
        double x3 = s2.p1.x;
        double y3 = s2.p1.y;
        double x4 = s2.p2.x;
        double y4 = s2.p2.y;

        double denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);

        if (Math.abs(denom) < EPS) {
            // Parallel or collinear
            if (areCollinear(s1, s2)) {
                // For collinear segments, check if they overlap
                // Return any overlapping point
                List<Point2D.Double> overlapPoints = new ArrayList<>();

                if (onSegment(s1, s2.p1)) {
                    overlapPoints.add(s2.p1);
                }
                if (onSegment(s1, s2.p2)) {
                    overlapPoints.add(s2.p2);
                }
                if (onSegment(s2, s1.p1)) {
                    overlapPoints.add(s1.p1);
                }
                if (onSegment(s2, s1.p2)) {
                    overlapPoints.add(s1.p2);
                }

                // Remove duplicates and return the first point
                if (!overlapPoints.isEmpty()) {
                    // Find the point that's not an endpoint of both segments
                    for (Point2D.Double pt : overlapPoints) {
                        boolean isS1Endpoint = pointsEqual(pt, s1.p1) || pointsEqual(pt, s1.p2);
                        boolean isS2Endpoint = pointsEqual(pt, s2.p1) || pointsEqual(pt, s2.p2);

                        // If it's an endpoint of both, it's a touching point
                        if (isS1Endpoint && isS2Endpoint) {
                            return pt;
                        }
                    }
                    // Return the first overlap point
                    return overlapPoints.getFirst();
                }
            }
            return null;
        }

        double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom;
        double u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom;

        if (t >= -EPS && t <= 1 + EPS && u >= -EPS && u <= 1 + EPS) {
            double px = x1 + t * (x2 - x1);
            double py = y1 + t * (y2 - y1);
            return new Point2D.Double(px, py);
        }

        return null;
    }

    private static boolean areCollinear(Segment s1, Segment s2) {
        double cross1 = crossProduct(s1.p1, s1.p2, s2.p1);
        double cross2 = crossProduct(s1.p1, s1.p2, s2.p2);
        return Math.abs(cross1) < EPS && Math.abs(cross2) < EPS;
    }

    private static double crossProduct(Point2D.Double a, Point2D.Double b, Point2D.Double c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    private static boolean onSegment(Segment s, Point2D.Double p) {
        return p.x >= Math.min(s.p1.x, s.p2.x) - EPS && p.x <= Math.max(s.p1.x, s.p2.x) + EPS && p.y >= Math.min(s.p1.y, s.p2.y) - EPS && p.y <= Math.max(s.p1.y, s.p2.y) + EPS && Math.abs(crossProduct(s.p1, s.p2, p)) < EPS;
    }

    private static boolean pointsEqual(Point2D.Double p1, Point2D.Double p2) {
        return Math.abs(p1.x - p2.x) < EPS && Math.abs(p1.y - p2.y) < EPS;
    }
}

package com.ankan.enumExamples;

public class Basic {

    enum Week implements A {
        // These are enum constants. Each constant is a public, static, and final instance of type Week.
        // Since it's final, we cannot extend or create child enums.
        MONDAY, TUESDAY, WEDNESDAY, THURSDAY, FRIDAY, SATURDAY, SUNDAY;

        // Constructor is called once per enum constant when the enum type is first accessed
        Week() {
            System.out.println("Constructor invoked for " + this);
        }
        // Constructor cannot be public or protected — only private or package-private.
        // This prevents external instantiation.
        // Internally: public static final Week MONDAY = new Week();

        @Override
        public void sayHello() {
            System.out.println("Greetings! How are you doing?");
        }
    }

    public static void main(String[] args) {
