/**
 * This class converts Decimal numbers to Octal Numbers
 */
public final class DecimalToOctal {
private static final int OCTAL_RADIX = 8;
private static final int STARTING_OCTAL = 0;
private static final int STARTING_MULTIPLIER = 1;

private DecimalToOctal() {
}

/**
 * Converts a decimal number to its octal equivalent.
 *
 * @param decimalInput The decimal number to convert.
 * @return The octal equivalent as an integer.
 * @throws IllegalArgumentException if the decimalInput is negative.
 */
public static int convertToOctal(int decimalInput) {
if (decimalInput < 0) {
throw new IllegalArgumentException("Decimal number cannot be negative.");
}
int octalResult = STARTING_OCTAL;
int placeMultiplier = STARTING_MULTIPLIER;
int remainingValue = decimalInput;
while (remainingValue != 0) {
int remainderDigit = remainingValue % OCTAL_RADIX;
octalResult += remainderDigit * placeMultiplier;
remainingValue /= OCTAL_RADIX;
placeMultiplier *= 10;
}
return octalResult;
}
}
