package com.thealgorithms.conversions;

/**
 * @author Varun Upadhyay (<a href="https://github.com/varunu28">...</a>)
 */
public final class AnyBaseToDecimal {
    private static final int CHAR_OFFSET_FOR_DIGIT = '0';
    private static final int CHAR_OFFSET_FOR_UPPERCASE = 'A' - 10;

    private AnyBaseToDecimal() {
    }

    /**
     * Convert any radix to a decimal number.
     *
     * @param input the string to be converted
     * @param radix the radix (base) of the input string
     * @return the decimal equivalent of the input string
     * @throws NumberFormatException if the input string or radix is invalid
     */
    public static int convertToDecimal(String input, int radix) {
        int result = 0;
        int power = 1;

        for (int i = input.length() - 1; i >= 0; i--) {
            int digit = valOfChar(input.charAt(i));
            if (digit >= radix) {
                throw new NumberFormatException("For input string: " + input);
            }
            result += digit * power;
            power *= radix;
        }
        return result;
    }

    /**
     * Convert a character to its integer value.
     *
     * @param character the character to be converted
     * @return the integer value represented by the character
     * @throws NumberFormatException if the character is not an uppercase letter or a digit
     */
    private static int valOfChar(char character) {
        if (Character.isDigit(character)) {
            return character - CHAR_OFFSET_FOR_DIGIT;
        } else if (Character.isUpperCase(character)) {
            return character - CHAR_OFFSET_FOR_UPPERCASE;
        } else {
            throw new NumberFormatException("invalid character:" + character);
        }
    }
}

package com.ankan.interfaces.extendDemo2;

public class Main implements A, B, C {
    // Note: A class can implement multiple interfaces in Java
    // However, if two interfaces provide conflicting default methods,
    // the implementing class MUST override the conflicting method

    // Implementation of abstract method from interface B
    @Override
    public void sendGreetingMessage() {
        System.out.println("Sending greeting from Main class - implementation of B's method");
    }

    // Implementation of abstract method from interface C
    @Override
    public void arrangeMeeting() {
        System.out.println("Arranging meeting from Main class - implementation of C's method");
    }

    // Implementation of abstract method from interface A
    @Override
    public void abstractMethod() {
        System.out.println("Implementing A's abstract method in Main class");
    }

    // Optional: Override A's default method (commented - using default implementation)
    // @Override
    // public void performDefaultAction() {
    //     System.out.println("Overriding A's default method");
    // }

    // Note: A's static method greeting() is NOT inherited - must be called via interface name

    public static void main(String[] args) {
        Main mainInstance = new Main();

        // Demonstrating all implemented methods
        System.out.println("--- Method Calls Demonstration ---");
        mainInstance.sendGreetingMessage();
        mainInstance.arrangeMeeting();
        mainInstance.abstractMethod();
        mainInstance.performDefaultAction();  // Calls A's default method (not overridden)

        // Static methods belong to the interface, not to instances
        // They are called using the interface name, not via object reference
        A.displayStaticGreeting();  // Correct way to call static interface method

        // B.displayStaticGreeting(); // ERROR: B does not have this static method
        // mainInstance.displayStaticGreeting(); // ERROR: Cannot call static method via instance

        System.out.println("\n--- Multiple Inheritance Demonstration ---");
        System.out.println("Main class implements A, B, and C simultaneously");
        System.out.println("This demonstrates Java's support for multiple inheritance of type");
    }
}

public class UcluIslec {

    public static void main(String[] args) {

        int deger = 10;

        // Tek seviyeli kosul (ternary) operatoru ornegi
        String karsilastirma = (deger > 5) ? "Buyuk" : "Kucuk"; // 5'i gecerse Buyuk, gecmezse Kucuk
        System.out.println("Sayi 5ten Buyuk mu? " + karsilastirma);

        karsilastirma = (deger > 15) ? "Buyuk" : "Kucuk"; // 15'i gecerse Buyuk, gecmezse Kucuk
        System.out.println("Sayi 15ten Buyuk mu? " + karsilastirma);

        // Birden fazla kosulun zincirlenerek kullanilmasi
        String durum = (deger > 25) ? "Sicak" : (deger > 15) ? "Ilik" : "Soguk";
        // 25 ustu Sicak, 15 ustu Ilik, digerleri Soguk olarak degerlendirilir
        System.out.println("Hava Durumu: 10 derece " + durum);

        deger = 20;
        durum = (deger > 25) ? "Sicak" : (deger > 15) ? "Ilik" : "Soguk";
        System.out.println("Hava Durumu: 20 derece " + durum);

        deger = 30;
        durum = (deger > 25) ? "Sicak" : (deger > 15) ? "Ilik" : "Soguk";
        System.out.println("Hava Durumu: 30 derece " + durum);
    }
}

/**
 * Small arithmetic utility bundling the basic operations exercised by
 * CalculatorTest: the four basic operators plus modulus, factorial,
 * power, square root, min/max and average.
 */
public class Calculator {

    // Sums two integers
    public int add(int x, int y) {
        return x + y;
    }

    // Subtracts the second integer from the first
    public int subtract(int x, int y) {
        return x - y;
    }

    // Multiplies two integers
    public int multiply(int x, int y) {
        return x * y;
    }

    // Divides x by y, rejecting a zero divisor
    public int divide(int x, int y) throws IllegalArgumentException {
        if (y == 0) {
            throw new IllegalArgumentException("Sifira bolme yapilamaz.");
        }
        return x / y;
    }

    // Remainder of x divided by y, rejecting a zero divisor
    public int modulus(int x, int y) throws IllegalArgumentException {
        if (y == 0) {
            throw new IllegalArgumentException("Sifira mod alma yapilamaz.");
        }
        return x % y;
    }

    // Product of every integer from 1 to n; rejects negative input
    public long factorial(int n) throws IllegalArgumentException {
        if (n < 0) {
            throw new IllegalArgumentException("Negatif sayilarin faktoriyeli hesaplanamaz.");
        }
        long product = 1;
        for (int factor = 1; factor <= n; factor++) {
            product *= factor;
        }
        return product;
    }

    // base raised to exponent
    public double power(double base, double exponent) {
        return Math.pow(base, exponent);
    }

    // Square root of a non-negative value
    public double squareRoot(double value) throws IllegalArgumentException {
        if (value < 0) {
            throw new IllegalArgumentException("Negatif sayilarin karekoku hesaplanamaz.");
        }
        return Math.sqrt(value);
    }

    // Larger of the two integers
    public int max(int x, int y) {
        return (x > y) ? x : y;
    }

    // Smaller of the two integers
    public int min(int x, int y) {
        return (x < y) ? x : y;
    }

    // Arithmetic mean of two integers, as a double
    public double average(int x, int y) {
        return (x + y) / 2.0;
    }
}

