package functions; 
import java.util.Scanner;  // Kullanicidan giris almak icin Scanner sinifini ice aktar

public class UsAlma {

	// 'usAl' metodu, verilen tabanin belirtilen usse gore ussunu hesaplar
	int usAl(int taban, int us) {
		int sonuc = 1;  // Sonuc degiskeni 1 ile baslar cunku herhangi bir sayinin 0. kuvveti 1'dir

		// Dongu, us sayisi kadar doner ve her adimda sonucu taban ile carpar
		for(int i = 0; i < us; i++) {
			sonuc *= taban;  
		}

		// Hesaplanan sonuc dondurulur
		return sonuc;
	}

	public static void main(String[] args) {

		// Kullanicidan giris almak icin Scanner nesnesi olustur
		Scanner okuyucu = new Scanner(System.in);

		// Kullanicidan taban sayisini girmesini iste
		System.out.println("Lutfen tabani giriniz:");
		int taban = okuyucu.nextInt();  // Kullanicinin girdigi taban sayisi alinir

		// Kullanicidan us sayisini girmesini iste
		System.out.println("Lutfen ussu giriniz:");
		int us = okuyucu.nextInt();  // Kullanicinin girdigi us sayisi alinir

		// UsAlma sinifindan bir nesne olustur
		UsAlma bulucu = new UsAlma();

		// 'usAl' metodunu cagir
		int sonuc = bulucu.usAl(taban, us);

		// Hesaplanan sonuc ekrana yazdirilir
		System.out.println("Sonuc = " + sonuc);

		// Scanner nesnesini kapat
		okuyucu.close();
	}
}

/**
 * Columnar Transposition Cipher Encryption and Decryption.
 *
 * @author <a href="https://github.com/freitzzz">freitzzz</a>
 */
public final class ColumnarTranspositionCipher {
private ColumnarTranspositionCipher() {
}

private static String encryptionKey;
private static Object[][] cipherTable;
private static String characterSet;
public static final String DEFAULT_CHARACTER_SET = "abcdefghijklmnopqrstuvwxyzABCDEFG"
+ "HIJKLMNOPQRSTUVWXYZ0123456789,.;:-@";
private static final String PLACEHOLDER_STRING = "≈";
private static final char PLACEHOLDER_CHAR = '≈';

/**
 * Encrypts a certain String with the Columnar Transposition Cipher Rule
 *
 * @param sourceWord Word being encrypted
 * @param keyValue String with keyword being used
 * @return a String with the word encrypted by the Columnar Transposition
 * Cipher Rule
 */
public static String encrypt(final String sourceWord, final String keyValue) {
encryptionKey = keyValue;
buildCharacterSet();
cipherTable = buildCipherTable(sourceWord);
Object[][] sortedTable = sortCipherTable(cipherTable);
StringBuilder encryptedResult = new StringBuilder();
for (int columnPos = 0; columnPos < sortedTable[0].length; columnPos++) {
for (int rowPos = 1; rowPos < sortedTable.length; rowPos++) {
encryptedResult.append(sortedTable[rowPos][columnPos]);
}
}
return encryptedResult.toString();
}

/**
 * Encrypts a certain String with the Columnar Transposition Cipher Rule
 *
 * @param sourceWord Word being encrypted
 * @param keyValue String with keyword being used
 * @param customCharacterSet String with the abecedarium being used. null for
 * default one
 * @return a String with the word encrypted by the Columnar Transposition
 * Cipher Rule
 */
public static String encrypt(String sourceWord, String keyValue, String customCharacterSet) {
encryptionKey = keyValue;
ColumnarTranspositionCipher.characterSet = Objects.requireNonNullElse(customCharacterSet, DEFAULT_CHARACTER_SET);
cipherTable = buildCipherTable(sourceWord);
Object[][] sortedTable = sortCipherTable(cipherTable);
StringBuilder encryptedResult = new StringBuilder();
for (int columnPos = 0; columnPos < sortedTable[0].length; columnPos++) {
for (int rowPos = 1; rowPos < sortedTable.length; rowPos++) {
encryptedResult.append(sortedTable[rowPos][columnPos]);
}
}
return encryptedResult.toString();
}

/**
 * Decrypts a certain encrypted String with the Columnar Transposition
 * Cipher Rule
 *
 * @return a String decrypted with the word encrypted by the Columnar
 * Transposition Cipher Rule
 */
public static String decrypt() {
StringBuilder decryptedResult = new StringBuilder();
for (int rowPos = 1; rowPos < cipherTable.length; rowPos++) {
for (Object cellValue : cipherTable[rowPos]) {
decryptedResult.append(cellValue);
}
}
return decryptedResult.toString().replaceAll(PLACEHOLDER_STRING, "");
}

/**
 * Builds a table with the word to be encrypted in rows by the Columnar
 * Transposition Cipher Rule
 *
 * @return An Object[][] with the word to be encrypted filled in rows and
 * columns
 */
private static Object[][] buildCipherTable(String sourceWord) {
Object[][] gridTable = new Object[getRowCount(sourceWord) + 1][encryptionKey.length()];
char[] wordChars = sourceWord.toCharArray();
gridTable[0] = getColumnOrderValues();
int charPosition = 0;
for (int rowPos = 1; rowPos < gridTable.length; rowPos++) {
for (int colPos = 0; colPos < gridTable[rowPos].length; colPos++) {
if (charPosition < wordChars.length) {
gridTable[rowPos][colPos] = wordChars[charPosition];
charPosition++;
} else {
gridTable[rowPos][colPos] = PLACEHOLDER_CHAR;
}
}
}
return gridTable;
}

/**
 * Determines the number of rows the table should have regarding the
 * Columnar Transposition Cipher Rule
 *
 * @return an int with the number of rows that the table should have in
 * order to respect the Columnar Transposition Cipher Rule.
 */
private static int getRowCount(String sourceWord) {
if (sourceWord.length() % encryptionKey.length() != 0) {
return (sourceWord.length() / encryptionKey.length()) + 1;
} else {
return sourceWord.length() / encryptionKey.length();
}
}

/**
 * @return charValues
 */
private static Object[] getColumnOrderValues() {
Object[] orderValues = new Object[encryptionKey.length()];
for (int index = 0; index < orderValues.length; index++) {
int valuePosition = characterSet.indexOf(encryptionKey.charAt(index));
orderValues[index] = valuePosition > -1 ? valuePosition : null;
}
return orderValues;
}

/**
 * @return tableSorted
 */
private static Object[][] sortCipherTable(Object[][] originalTable) {
Object[][] sortedGrid = new Object[originalTable.length][originalTable[0].length];
for (int rowPos = 0; rowPos < sortedGrid.length; rowPos++) {
System.arraycopy(originalTable[rowPos], 0, sortedGrid[rowPos], 0, sortedGrid[rowPos].length);
}
for (int colPos = 0; colPos < sortedGrid[0].length; colPos++) {
for (int nextCol = colPos + 1; nextCol < sortedGrid[0].length; nextCol++) {
if ((int) sortedGrid[0][colPos] > (int) originalTable[0][nextCol]) {
Object[] targetColumn = extractColumn(sortedGrid, sortedGrid.length, nextCol);
swapColumns(sortedGrid, nextCol, colPos, targetColumn);
}
}
}
return sortedGrid;
}

/**
 * @return columnArray
 */
private static Object[] extractColumn(Object[][] gridTable, int rowCount, int columnIndex) {
Object[] columnData = new Object[rowCount];
for (int rowPos = 0; rowPos < rowCount; rowPos++) {
columnData[rowPos] = gridTable[rowPos][columnIndex];
}
return columnData;
}

private static void swapColumns(Object[][] gridTable, int sourceCol, int targetCol, Object[] sourceColumnData) {
for (int rowPos = 0; rowPos < gridTable.length; rowPos++) {
gridTable[rowPos][targetCol] = gridTable[rowPos][sourceCol];
gridTable[rowPos][sourceCol] = sourceColumnData[rowPos];
}
}

/**
 * Creates an abecedarium with all available ascii values.
 */
private static void buildCharacterSet() {
StringBuilder tempSet = new StringBuilder();
for (int asciiValue = 0; asciiValue < 256; asciiValue++) {
tempSet.append((char) asciiValue);
}
characterSet = tempSet.toString();
}
}

/**
 * In numerical analysis, Chebyshev iteration is an iterative method for solving
 * systems of linear equations Ax = b. It is designed for systems where the
 * matrix A is symmetric positive-definite (SPD).
 *
 * <p>
 * This method is a "polynomial acceleration" method, meaning it finds the
 * optimal polynomial to apply to the residual to accelerate convergence.
 *
 * <p>
 * It requires knowledge of the bounds of the eigenvalues of the matrix A:
 * m(A) (smallest eigenvalue) and M(A) (largest eigenvalue).
 *
 * <p>
 * Wikipedia: https://en.wikipedia.org/wiki/Chebyshev_iteration
 *
 * @author Mitrajit Ghorui(KeyKyrios)
 */
public final class ChebyshevIteration {

    private ChebyshevIteration() {
    }

    /**
     * Solves the linear system Ax = b using the Chebyshev iteration method.
     *
     * <p>
     * NOTE: The matrix A *must* be symmetric positive-definite (SPD) for this
     * algorithm to converge.
     *
     * @param a The matrix A (must be square, SPD).
     * @param b The vector b.
     * @param x0 The initial guess vector.
     * @param minEigenvalue The smallest eigenvalue of A (m(A)).
     * @param maxEigenvalue The largest eigenvalue of A (M(A)).
     * @param maxIterations The maximum number of iterations to perform.
     * @param tolerance The desired tolerance for the residual norm.
     * @return The solution vector x.
     * @throws IllegalArgumentException if matrix/vector dimensions are
     * incompatible,
     * if maxIterations <= 0, or if eigenvalues are invalid (e.g., minEigenvalue
     * <= 0, maxEigenvalue <= minEigenvalue).
     */
    public static double[] solve(double[][] a, double[] b, double[] x0, double minEigenvalue, double maxEigenvalue, int maxIterations, double tolerance) {
        validateInputs(a, b, x0, minEigenvalue, maxEigenvalue, maxIterations, tolerance);

        int n = b.length;
        double[] x = x0.clone();
        double[] r = vectorSubtract(b, matrixVectorMultiply(a, x));
        double[] p = new double[n];

        double d = (maxEigenvalue + minEigenvalue) / 2.0;
        double c = (maxEigenvalue - minEigenvalue) / 2.0;

        double alpha = 0.0;
        double alphaPrev = 0.0;

        for (int k = 0; k < maxIterations; k++) {
            double residualNorm = vectorNorm(r);
            if (residualNorm < tolerance) {
                return x; // Solution converged
            }

            if (k == 0) {
                alpha = 1.0 / d;
                System.arraycopy(r, 0, p, 0, n); // p = r
            } else {
                double beta = c * alphaPrev / 2.0 * (c * alphaPrev / 2.0);
                alpha = 1.0 / (d - beta / alphaPrev);
                double[] pUpdate = scalarMultiply(beta / alphaPrev, p);
                p = vectorAdd(r, pUpdate); // p = r + (beta / alphaPrev) * p
            }

            double[] xUpdate = scalarMultiply(alpha, p);
            x = vectorAdd(x, xUpdate); // x = x + alpha * p

            // Recompute residual for accuracy
            r = vectorSubtract(b, matrixVectorMultiply(a, x));
            alphaPrev = alpha;
        }

        return x; // Return best guess after maxIterations
    }

    /**
     * Validates the inputs for the Chebyshev solver.
     */
    private static void validateInputs(double[][] a, double[] b, double[] x0, double minEigenvalue, double maxEigenvalue, int maxIterations, double tolerance) {
        int n = a.length;
        if (n == 0) {
            throw new IllegalArgumentException("Matrix A cannot be empty.");
        }
        if (n != a[0].length) {
            throw new IllegalArgumentException("Matrix A must be square.");
        }
        if (n != b.length) {
            throw new IllegalArgumentException("Matrix A and vector b dimensions do not match.");
        }
        if (n != x0.length) {
            throw new IllegalArgumentException("Matrix A and vector x0 dimensions do not match.");
        }
        if (minEigenvalue <= 0) {
            throw new IllegalArgumentException("Smallest eigenvalue must be positive (matrix must be positive-definite).");
        }
        if (maxEigenvalue <= minEigenvalue) {
            throw new IllegalArgumentException("Max eigenvalue must be strictly greater than min eigenvalue.");
        }
        if (maxIterations <= 0) {
            throw new IllegalArgumentException("Max iterations must be positive.");
        }
        if (tolerance <= 0) {
            throw new IllegalArgumentException("Tolerance must be positive.");
        }
    }

    // --- Vector/Matrix Helper Methods ---
    /**
     * Computes the product of a matrix A and a vector v (Av).
     */
    private static double[] matrixVectorMultiply(double[][] a, double[] v) {
        int n = a.length;
        double[] result = new double[n];
        for (int i = 0; i < n; i++) {
            double sum = 0;
            for (int j = 0; j < n; j++) {
                sum += a[i][j] * v[j];
            }
            result[i] = sum;
        }
        return result;
    }

    /**
     * Computes the subtraction of two vectors (v1 - v2).
     */
    private static double[] vectorSubtract(double[] v1, double[] v2) {
        int n = v1.length;
        double[] result = new double[n];
        for (int i = 0; i < n; i++) {
            result[i] = v1[i] - v2[i];
        }
        return result;
    }

    /**
     * Computes the addition of two vectors (v1 + v2).
     */
    private static double[] vectorAdd(double[] v1, double[] v2) {
        int n = v1.length;
        double[] result = new double[n];
        for (int i = 0; i < n; i++) {
            result[i] = v1[i] + v2[i];
        }
        return result;
    }

    /**
     * Computes the product of a scalar and a vector (s * v).
     */
    private static double[] scalarMultiply(double scalar, double[] v) {
        int n = v.length;
        double[] result = new double[n];
        for (int i = 0; i < n; i++) {
            result[i] = scalar * v[i];
        }
        return result;
    }

    /**
     * Computes the L2 norm (Euclidean norm) of a vector.
     */
    private static double vectorNorm(double[] v) {
        double sumOfSquares = 0;
        for (double val : v) {
            sumOfSquares += val * val;
        }
        return Math.sqrt(sumOfSquares);
    }
}

