/*
 * Bootstraps a small SQLite leaderboard: creates the "scores" table if it
 * is missing, seeds it with a handful of randomly generated entries,
 * optionally lets the user add their own score, then prints the top ten.
 */

public class GameResults {

    private static final String DB_URL = "jdbc:sqlite:game.db";
    private static final String CREATE_TABLE =
            "CREATE TABLE IF NOT EXISTS scores (name TEXT, score INTEGER, achievement TEXT)";
    private static final String INSERT_ENTRY =
            "INSERT INTO scores (name, score, achievement) VALUES (?, ?, ?)";
    private static final String TOP_SCORES =
            "SELECT * FROM scores ORDER BY score DESC LIMIT ?";

    private static final Random rng = new Random();
    private static final Scanner console = new Scanner(System.in);

    public static void main(String[] args) {
        ensureTableExists();
        seedRandomEntries(5);
        maybeAddPlayerEntry();
        printTopScores(10);
    }

    private static void ensureTableExists() {
        try (Connection db = DriverManager.getConnection(DB_URL);
             Statement stmt = db.createStatement()) {
            stmt.execute(CREATE_TABLE);
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    private static void seedRandomEntries(int count) {
        for (int i = 0; i < count; i++) {
            String name = "player" + (i + 1);
            int score = rng.nextInt(100);
            String achievement = randomAchievement();
            saveEntry(name, score, achievement);
            System.out.println("Yeni kayit eklendi: " + name + " - Puan: " + score + " - Basari: " + achievement);
        }
    }

    private static void maybeAddPlayerEntry() {
        System.out.print("Yeni oyuncu eklemek ister misiniz? (E/H): ");
        String answer = console.nextLine();
        if (!answer.equalsIgnoreCase("E")) {
            return;
        }
        System.out.print("Oyuncu ismi girin: ");
        String name = console.nextLine();
        System.out.print("Puan girin: ");
        int score = console.nextInt();
        console.nextLine();
        String achievement = randomAchievement();
        saveEntry(name, score, achievement);
        System.out.println("Yeni oyuncu eklendi: " + name + " - Puan: " + score + " - Basari: " + achievement);
    }

    private static void saveEntry(String name, int score, String achievement) {
        try (Connection db = DriverManager.getConnection(DB_URL);
             PreparedStatement stmt = db.prepareStatement(INSERT_ENTRY)) {
            stmt.setString(1, name);
            stmt.setInt(2, score);
            stmt.setString(3, achievement);
            stmt.executeUpdate();
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    private static void printTopScores(int limit) {
        try (Connection db = DriverManager.getConnection(DB_URL);
             PreparedStatement stmt = db.prepareStatement(TOP_SCORES)) {
            stmt.setInt(1, limit);
            ResultSet rows = stmt.executeQuery();
            System.out.println("\nEn yuksek 10 puan: ");
            while (rows.next()) {
                String name = rows.getString("name");
                int score = rows.getInt("score");
                String achievement = rows.getString("achievement");
                System.out.println(name + ": " + score + " - Basari: " + achievement);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    private static String randomAchievement() {
        String[] pool = {
                "Yeni Baslayan",
                "Buyuk Zafer",
                "Efsane Oyuncu",
                "Hizli Dusunen",
                "Oyun Ustasi"
        };
        return pool[rng.nextInt(pool.length)];
    }
}

