/**
 * Boruvka's algorithm to find Minimum Spanning Tree
 * (https://en.wikipedia.org/wiki/Bor%C5%AFvka%27s_algorithm)
 *
 * @author itakurah (https://github.com/itakurah)
 */

final class BoruvkaAlgorithm {
private BoruvkaAlgorithm() {
}

/**
 * Represents an edge in the graph
 */
static class GraphEdge {
final int sourceVertex;
final int targetVertex;
final int edgeWeight;

GraphEdge(final int fromVertex, final int toVertex, final int weightValue) {
this.sourceVertex = fromVertex;
this.targetVertex = toVertex;
this.edgeWeight = weightValue;
}
}

/**
 * Represents the graph
 */
static class WeightedGraph {
final int nodeCount;
final List<GraphEdge> edgeList;

/**
 * Constructor for the graph
 *
 * @param nodeCount number of vertices
 * @param edgeList  list of edges
 */
WeightedGraph(final int nodeCount, final List<GraphEdge> edgeList) {
if (nodeCount < 0) {
throw new IllegalArgumentException("Number of vertices must be positive");
}
if (edgeList == null || edgeList.isEmpty()) {
throw new IllegalArgumentException("Edges list must not be null or empty");
}
for (final var currentEdge : edgeList) {
validateVertex(currentEdge.sourceVertex, nodeCount);
validateVertex(currentEdge.targetVertex, nodeCount);
}
this.nodeCount = nodeCount;
this.edgeList = edgeList;
}
}

/**
 * Represents a subset for Union-Find operations
 */
private static class SubsetData {
int parentNode;
int treeLevel;

SubsetData(final int parentNode, final int treeLevel) {
this.parentNode = parentNode;
this.treeLevel = treeLevel;
}
}

/**
 * Represents the state of Union-Find components and the result list
 */
private static class AlgorithmState {
List<GraphEdge> mstEdges;
SubsetData[] componentData;
final WeightedGraph inputGraph;

AlgorithmState(final WeightedGraph inputGraph) {
this.mstEdges = new ArrayList<>();
this.componentData = initializeComponents(inputGraph);
this.inputGraph = inputGraph;
}

/**
 * Adds the cheapest edges to the result list and performs Union operation on the subsets.
 *
 * @param cheapestEdgeArray Array containing the cheapest edge for each subset.
 */
void mergeComponents(final GraphEdge[] cheapestEdgeArray) {
for (int subsetIndex = 0; subsetIndex < inputGraph.nodeCount; ++subsetIndex) {
if (cheapestEdgeArray[subsetIndex] != null) {
final int rootFirst = findRoot(componentData, cheapestEdgeArray[subsetIndex].sourceVertex);
final int rootSecond = findRoot(componentData, cheapestEdgeArray[subsetIndex].targetVertex);
if (rootFirst != rootSecond) {
mstEdges.add(cheapestEdgeArray[subsetIndex]);
unionComponents(componentData, rootFirst, rootSecond);
}
}
}
}

/**
 * Checks if there are more edges to add to the result list
 *
 * @return true if there are more edges to add, false otherwise
 */
boolean hasRemainingEdges() {
return mstEdges.size() < inputGraph.nodeCount - 1;
}

/**
 * Computes the cheapest edges for each subset in the Union-Find structure.
 *
 * @return an array containing the cheapest edge for each subset.
 */
private GraphEdge[] findCheapestEdges() {
GraphEdge[] cheapestEdgeForComponent = new GraphEdge[inputGraph.nodeCount];
for (final var currentEdge : inputGraph.edgeList) {
final int rootFirst = findRoot(componentData, currentEdge.sourceVertex);
final int rootSecond = findRoot(componentData, currentEdge.targetVertex);
if (rootFirst != rootSecond) {
if (cheapestEdgeForComponent[rootFirst] == null || currentEdge.edgeWeight < cheapestEdgeForComponent[rootFirst].edgeWeight) {
cheapestEdgeForComponent[rootFirst] = currentEdge;
}
if (cheapestEdgeForComponent[rootSecond] == null || currentEdge.edgeWeight < cheapestEdgeForComponent[rootSecond].edgeWeight) {
cheapestEdgeForComponent[rootSecond] = currentEdge;
}
}
}
return cheapestEdgeForComponent;
}

/**
 * Initializes subsets for Union-Find
 *
 * @param targetGraph the graph
 * @return the initialized subsets
 */
private static SubsetData[] initializeComponents(final WeightedGraph targetGraph) {
SubsetData[] componentList = new SubsetData[targetGraph.nodeCount];
for (int vertexIndex = 0; vertexIndex < targetGraph.nodeCount; ++vertexIndex) {
componentList[vertexIndex] = new SubsetData(vertexIndex, 0);
}
return componentList;
}
}

/**
 * Finds the parent of the subset using path compression
 *
 * @param componentData array of subsets
 * @param elementIndex          index of the subset
 * @return the parent of the subset
 */
static int findRoot(final SubsetData[] componentData, final int elementIndex) {
if (componentData[elementIndex].parentNode != elementIndex) {
componentData[elementIndex].parentNode = findRoot(componentData, componentData[elementIndex].parentNode);
}
return componentData[elementIndex].parentNode;
}

/**
 * Performs the Union operation for Union-Find
 *
 * @param componentData array of subsets
 * @param firstSet          index of the first subset
 * @param secondSet          index of the second subset
 */
static void unionComponents(SubsetData[] componentData, final int firstSet, final int secondSet) {
final int rootFirst = findRoot(componentData, firstSet);
final int rootSecond = findRoot(componentData, secondSet);
if (componentData[rootFirst].treeLevel < componentData[rootSecond].treeLevel) {
componentData[rootFirst].parentNode = rootSecond;
} else if (componentData[rootFirst].treeLevel > componentData[rootSecond].treeLevel) {
componentData[rootSecond].parentNode = rootFirst;
} else {
componentData[rootSecond].parentNode = rootFirst;
componentData[rootFirst].treeLevel++;
}
}

/**
 * Boruvka's algorithm to find the Minimum Spanning Tree
 *
 * @param targetGraph the graph
 * @return list of edges in the Minimum Spanning Tree
 */
static List<GraphEdge> findMinimumSpanningTree(final WeightedGraph targetGraph) {
var algorithmState = new AlgorithmState(targetGraph);
while (algorithmState.hasRemainingEdges()) {
final var cheapestEdges = algorithmState.findCheapestEdges();
algorithmState.mergeComponents(cheapestEdges);
}
return algorithmState.mstEdges;
}

/**
 * Checks if the edge vertices are in a valid range
 *
 * @param vertexValue     the vertex to check
 * @param upperBound the upper bound for the vertex range
 */
private static void validateVertex(final int vertexValue, final int upperBound) {
if (vertexValue < 0 || vertexValue >= upperBound) {
throw new IllegalArgumentException("Edge vertex out of range");
}
}
}
