public class RezerveKelimeler {

    public static void main(String[] args) {

        // Using a reserved keyword as an identifier fails to compile:
        //     int new = 5;         // "new" is reserved and cannot name a variable
        //     String switch = "x"; // "switch" is reserved and cannot name a variable

        // The full list of words that Java reserves and forbids as identifiers:
        // abstract, assert, boolean, break, byte, case, catch, char, class, const, continue, default,
        // do, double, else, enum, extends, final, finally, float, for, goto, if, implements, import,
        // instanceof, int, interface, long, native, new, package, private, protected, public, return,
        // short, static, strictfp, super, switch, synchronized, this, throw, throws, transient, try,
        // void, volatile, while, true, false, null

        // Pick alternative names instead of the reserved words above.
        int freshValue = 10;
        String colorName = "Mavi";
    }
}

/**
 * A student record comparable by mark (descending).
 */
public class Student implements Comparable<Student> {
    String code;
    String name;
    int mark;

    public Student() {
        code = "";
        name = "";
        mark = 0;
    }

    public Student(String code, String name, int mark) {
        this.code = code.toUpperCase();
        this.name = name.toUpperCase();
        this.mark = (mark >= 0 && mark <= 10) ? mark : 0;
    }

    public String getCode() {
        return code;
    }

    public void setCode(String code) {
        this.code = code;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        if (name.length() > 0) {
            this.name = name.trim().toUpperCase();
        }
    }

    public int getMark() {
        return mark;
    }

    public void setMark(int mark) {
        this.mark = (mark >= 0 && mark <= 10) ? mark : 0;
    }

    @Override
    public String toString() {
        return code + ", " + name + ", " + mark;
    }

    @Override
    public int compareTo(Student other) {
        return -(mark - other.getMark());
    }
}

/**
 * Demonstrates implementing Runnable instead of extending Thread.
 * Each worker prints a label repeatedly on its own delay until told to stop.
 */
public class RunnableOrnegi implements Runnable {

    private final String label;          // text printed on every tick
    private final int intervalMillis;     // pause between ticks
    private volatile boolean active = true; // flips to false to request shutdown

    public RunnableOrnegi(String label, int intervalMillis) {
        this.label = label;
        this.intervalMillis = intervalMillis;
    }

    // Loop body executed on whichever Thread wraps this Runnable
    @Override
    public void run() {
        while (active) {
            System.out.println(Thread.currentThread().getName() + ": " + label);
            try {
                Thread.sleep(intervalMillis);
            } catch (InterruptedException interrupted) {
                System.out.println(Thread.currentThread().getName() + " kesildi.");
                return;
            }
        }
        System.out.println(Thread.currentThread().getName() + " durduruldu.");
    }

    // Signals the loop to end after the current sleep finishes
    public void requestStop() {
        active = false;
    }

    public static void main(String[] args) {
        RunnableOrnegi first = new RunnableOrnegi("ali", 1000);
        Thread workerOne = new Thread(first, "Thread-1");

        RunnableOrnegi second = new RunnableOrnegi("veli", 2000);
        Thread workerTwo = new Thread(second, "Thread-2");

        RunnableOrnegi third = new RunnableOrnegi("ayse", 3000);
        Thread workerThree = new Thread(third, "Thread-3");

        workerOne.start();
        workerTwo.start();
        workerThree.start();

        // Let the workers run for a while before shutting them down
        sleepQuietly(10000);

        System.out.println("Thread'ler durduruluyor...");
        first.requestStop();
        second.requestStop();
        third.requestStop();

        joinQuietly(workerOne);
        joinQuietly(workerTwo);
        joinQuietly(workerThree);

        System.out.println("Program sonlandi.");
    }

    private static void sleepQuietly(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    private static void joinQuietly(Thread thread) {
        try {
            thread.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}

