package com.thealgorithms.datastructures.graphs;

import java.util.LinkedList;
import java.util.Queue;

/**
 * This class implements the Ford-Fulkerson algorithm to compute the maximum flow
 * in a flow network.
 *
 * <p>The algorithm uses breadth-first search (BFS) to find augmenting paths from
 * the source vertex to the sink vertex, updating the flow in the network until
 * no more augmenting paths can be found.</p>
 */
public final class FordFulkerson {
private static final int MAX_VALUE = Integer.MAX_VALUE;

private FordFulkerson() {
}

/**
 * Computes the maximum flow in a flow network using the Ford-Fulkerson algorithm.
 *
 * @param vertexCount the number of vertices in the flow network
 * @param capacityMatrix a 2D array representing the capacity of edges in the network
 * @param flowMatrix a 2D array representing the current flow in the network
 * @param sourceNode the source vertex in the flow network
 * @param sinkNode the sink vertex in the flow network
 * @return the total maximum flow from the source to the sink
 */
public static int computeMaxFlow(int vertexCount, int[][] capacityMatrix, int[][] flowMatrix, int sourceNode, int sinkNode) {
int totalFlowValue = 0;
while (true) {
int[] parentArray = new int[vertexCount];
boolean[] visitedNodes = new boolean[vertexCount];
Queue<Integer> bfsQueue = new LinkedList<>();
bfsQueue.add(sourceNode);
visitedNodes[sourceNode] = true;
parentArray[sourceNode] = -1;
while (!bfsQueue.isEmpty() && !visitedNodes[sinkNode]) {
int currentVertex = bfsQueue.poll();
for (int nextVertex = 0; nextVertex < vertexCount; nextVertex++) {
if (!visitedNodes[nextVertex] && capacityMatrix[currentVertex][nextVertex] - flowMatrix[currentVertex][nextVertex] > 0) {
bfsQueue.add(nextVertex);
visitedNodes[nextVertex] = true;
parentArray[nextVertex] = currentVertex;
}
}
}
if (!visitedNodes[sinkNode]) {
break;
}
int pathMinimum = MAX_VALUE;
for (int targetVertex = sinkNode; targetVertex != sourceNode; targetVertex = parentArray[targetVertex]) {
int prevVertex = parentArray[targetVertex];
pathMinimum = Math.min(pathMinimum, capacityMatrix[prevVertex][targetVertex] - flowMatrix[prevVertex][targetVertex]);
}
for (int targetVertex = sinkNode; targetVertex != sourceNode; targetVertex = parentArray[targetVertex]) {
int prevVertex = parentArray[targetVertex];
flowMatrix[prevVertex][targetVertex] += pathMinimum;
flowMatrix[targetVertex][prevVertex] -= pathMinimum;
}
totalFlowValue += pathMinimum;
}
return totalFlowValue;
}
}
