/**
 * Implementation of the Burrows-Wheeler Transform (BWT) and its inverse.
 * <p>
 * BWT is a reversible data transformation algorithm that rearranges a string into runs of
 * similar characters. While not a compression algorithm itself, it significantly improves
 * the compressibility of data for subsequent algorithms like Move-to-Front encoding and
 * Run-Length Encoding.
 * </p>
 *
 * <p>The transform works by:
 * <ol>
 *   <li>Generating all rotations of the input string</li>
 *   <li>Sorting these rotations lexicographically</li>
 *   <li>Taking the last column of the sorted matrix as output</li>
 *   <li>Recording the index of the original string in the sorted matrix</li>
 * </ol>
 * </p>
 *
 * <p><b>Important:</b> The input string should end with a unique end-of-string marker
 * (typically '$') that:
 * <ul>
 *   <li>Does not appear anywhere else in the text</li>
 *   <li>Is lexicographically smaller than all other characters</li>
 *   <li>Ensures unique rotations and enables correct inverse transformation</li>
 * </ul>
 * Without this marker, the inverse transform may not correctly reconstruct the original string.
 * </p>
 *
 * <p><b>Time Complexity:</b>
 * <ul>
 *   <li>Forward transform: O(n² log n) where n is the string length</li>
 *   <li>Inverse transform: O(n) using the LF-mapping technique</li>
 * </ul>
 * </p>
 *
 * <p><b>Example:</b></p>
 * <pre>
 * Input:  "banana$"
 * Output: BWTResult("annb$aa", 4)
 *         - "annb$aa" is the transformed string (groups similar characters)
 *         - 4 is the index of the original string in the sorted rotations
 * </pre>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Burrows%E2%80%93Wheeler_transform">Burrows–Wheeler transform (Wikipedia)</a>
 */
public final class BurrowsWheelerTransform {

    private BurrowsWheelerTransform() {
    }

    /**
     * A container for the result of the forward BWT.
     * <p>
     * Contains the transformed string and the index of the original string
     * in the sorted rotations matrix, both of which are required for the
     * inverse transformation.
     * </p>
     */
    public static class BWTResult {
        /** The transformed string (last column of the sorted rotation matrix) */
        public final String transformed;

        /** The index of the original string in the sorted rotations matrix */
        public final int originalIndex;

        /**
         * Constructs a BWTResult with the transformed string and original index.
         *
         * @param transformed the transformed string (L-column)
         * @param originalIndex the index of the original string in sorted rotations
         */
        public BWTResult(String transformed, int originalIndex) {
            this.transformed = transformed;
            this.originalIndex = originalIndex;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) {
                return true;
            }
            if (obj == null || getClass() != obj.getClass()) {
                return false;
            }
            BWTResult bwtResult = (BWTResult) obj;
            return originalIndex == bwtResult.originalIndex && transformed.equals(bwtResult.transformed);
        }

        @Override
        public int hashCode() {
            return 31 * transformed.hashCode() + originalIndex;
        }

        @Override
        public String toString() {
            return "BWTResult[transformed=" + transformed + ", originalIndex=" + originalIndex + "]";
        }
    }

    /**
     * Performs the forward Burrows-Wheeler Transform on the input string.
     * <p>
     * The algorithm generates all cyclic rotations of the input, sorts them
     * lexicographically, and returns the last column of this sorted matrix
     * along with the position of the original string.
     * </p>
     *
     * <p><b>Note:</b> It is strongly recommended that the input string ends with
     * a unique end-of-string marker (e.g., '$') that is lexicographically smaller
     * than any other character in the string. This ensures correct inversion.</p>
     *
     * @param text the input string to transform; must not be {@code null}
     * @return a {@link BWTResult} object containing the transformed string (L-column)
     *         and the index of the original string in the sorted rotations matrix;
     *         returns {@code BWTResult("", -1)} for empty input
     * @throws NullPointerException if {@code text} is {@code null}
     */
    public static BWTResult transform(String text) {
        if (text == null || text.isEmpty()) {
            return new BWTResult("", -1);
        }

        int n = text.length();

        // Generate all rotations of the input string
        String[] rotations = new String[n];
        for (int i = 0; i < n; i++) {
            rotations[i] = text.substring(i) + text.substring(0, i);
        }

        // Sort rotations lexicographically
        Arrays.sort(rotations);
        int originalIndex = Arrays.binarySearch(rotations, text);
        StringBuilder lastColumn = new StringBuilder(n);
        for (int i = 0; i < n; i++) {
            lastColumn.append(rotations[i].charAt(n - 1));
        }

        return new BWTResult(lastColumn.toString(), originalIndex);
    }

    /**
     * Performs the inverse Burrows-Wheeler Transform using the LF-mapping technique.
     * <p>
     * The LF-mapping (Last-First mapping) is an efficient method to reconstruct
     * the original string from the BWT output without explicitly reconstructing
     * the entire sorted rotations matrix.
     * </p>
     *
     * <p>The algorithm works by:
     * <ol>
     *   <li>Creating the first column by sorting the BWT string</li>
     *   <li>Building a mapping from first column indices to last column indices</li>
     *   <li>Following this mapping starting from the original index to reconstruct the string</li>
     * </ol>
     * </p>
     *
     * @param bwtString the transformed string (L-column) from the forward transform; must not be {@code null}
     * @param originalIndex the index of the original string row from the forward transform;
     *                      use -1 for empty strings
     * @return the original, untransformed string; returns empty string if input is empty or {@code originalIndex} is -1
     * @throws NullPointerException if {@code bwtString} is {@code null}
     * @throws IllegalArgumentException if {@code originalIndex} is out of valid range (except -1)
     */
    public static String inverseTransform(String bwtString, int originalIndex) {
        if (bwtString == null || bwtString.isEmpty() || originalIndex == -1) {
            return "";
        }

        int n = bwtString.length();
        if (originalIndex < 0 || originalIndex >= n) {
            throw new IllegalArgumentException("Original index must be between 0 and " + (n - 1) + ", got: " + originalIndex);
        }

        char[] lastColumn = bwtString.toCharArray();
        char[] firstColumn = bwtString.toCharArray();
        Arrays.sort(firstColumn);

        // Create the "next" array for LF-mapping.
        // next[i] stores the row index in the last column that corresponds to firstColumn[i]
        int[] next = new int[n];

        // Track the count of each character seen so far in the last column
        Map<Character, Integer> countMap = new HashMap<>();

        // Store the first occurrence index of each character in the first column
        Map<Character, Integer> firstOccurrence = new HashMap<>();

        for (int i = 0; i < n; i++) {
            if (!firstOccurrence.containsKey(firstColumn[i])) {
                firstOccurrence.put(firstColumn[i], i);
            }
        }

        // Build the LF-mapping
        for (int i = 0; i < n; i++) {
            char c = lastColumn[i];
            int count = countMap.getOrDefault(c, 0);
            int firstIndex = firstOccurrence.get(c);
            next[firstIndex + count] = i;
            countMap.put(c, count + 1);
        }

        // Reconstruct the original string by following the LF-mapping
        StringBuilder originalString = new StringBuilder(n);
        int currentRow = originalIndex;
        for (int i = 0; i < n; i++) {
            originalString.append(firstColumn[currentRow]);
            currentRow = next[currentRow];
        }

        return originalString.toString();
    }
}

public class AralikToplama {

    // Verilen araliktaki (a'dan b'ye kadar) sayilarin toplamini hesaplayan metot
    public static void aralikTopla(int a, int b) {
        int toplam = 0; // Toplam degiskeni baslatilir
        for (int i = a; i <= b; i++) { // a'dan b'ye kadar olan sayilar donguyle eklenir
            toplam += i; // Her sayi toplam degiskenine eklenir
        }
        // Toplam sonucu ekrana yazdirilir
        System.out.println(a + " ile " + b + " arasindaki sayilarin toplami: " + toplam);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Kullanicidan baslangic degeri (a) alinir
        System.out.print("Baslangic degerini girin (a): ");
        int a = scanner.nextInt();

        // Kullanicidan bitis degeri (b) alinir
        System.out.print("Bitis degerini girin (b): ");
        int b = scanner.nextInt();

        // aralikTopla metodu cagrilarak verilen araliktaki sayilarin toplami hesaplanir
        if(a < b) {
        	aralikTopla(a, b);
        }
        else {
        	aralikTopla(b, a);
        }

        // Scanner kapatilir
        scanner.close();
    }
}

/**
 * A Least Recently Used (LRU) Cache implementation.
 *
 * <p>An LRU cache is a fixed-size cache that maintains items in order of use. When the cache reaches
 * its capacity and a new item needs to be added, it removes the least recently used item first.
 * This implementation provides O(1) time complexity for both get and put operations.</p>
 *
 * <p>Features:</p>
 * <ul>
 *   <li>Fixed-size cache with configurable capacity</li>
 *   <li>Constant time O(1) operations for get and put</li>
 *   <li>Thread-unsafe - should be externally synchronized if used in concurrent environments</li>
 *   <li>Supports null values but not null keys</li>
 * </ul>
 *
 * <p>Implementation Details:</p>
 * <ul>
 *   <li>Uses a HashMap for O(1) key-value lookups</li>
 *   <li>Maintains a doubly-linked list for tracking access order</li>
 *   <li>The head of the list contains the least recently used item</li>
 *   <li>The tail of the list contains the most recently used item</li>
 * </ul>
 *
 * <p>Example usage:</p>
 * <pre>
 * LRUCache<String, Integer> cache = new LRUCache<>(3); // Create cache with capacity 3
 * cache.put("A", 1); // Cache: A=1
 * cache.put("B", 2); // Cache: A=1, B=2
 * cache.put("C", 3); // Cache: A=1, B=2, C=3
 * cache.get("A");    // Cache: B=2, C=3, A=1 (A moved to end)
 * cache.put("D", 4); // Cache: C=3, A=1, D=4 (B evicted)
 * </pre>
 *
 * @param <K> the type of keys maintained by this cache
 * @param <V> the type of mapped values
 */
public class LRUCache<K, V> {

    private final Map<K, Entry<K, V>> data = new HashMap<>();
    private Entry<K, V> head;
    private Entry<K, V> tail;
    private int cap;
    private static final int DEFAULT_CAP = 100;

    public LRUCache() {
        setCapacity(DEFAULT_CAP);
    }

    public LRUCache(int cap) {
        setCapacity(cap);
    }

    /**
     * Returns the current capacity of the cache.
     *
     * @param newCapacity the new capacity of the cache
     */
    private void setCapacity(int newCapacity) {
        checkCapacity(newCapacity);
        for (int i = data.size(); i > newCapacity; i--) {
            Entry<K, V> evicted = evict();
            data.remove(evicted.getKey());
        }
        this.cap = newCapacity;
    }

    /**
     * Evicts the least recently used item from the cache.
     *
     * @return the evicted entry
     */
    private Entry<K, V> evict() {
        if (head == null) {
            throw new RuntimeException("cache cannot be empty!");
        }
        Entry<K, V> evicted = head;
        head = evicted.getNextEntry();
        head.setPreEntry(null);
        evicted.setNextEntry(null);
        return evicted;
    }

    /**
     * Checks if the capacity is valid.
     *
     * @param capacity the capacity to check
     */
    private void checkCapacity(int capacity) {
        if (capacity <= 0) {
            throw new RuntimeException("capacity must greater than 0!");
        }
    }

    /**
     * Returns the value to which the specified key is mapped, or null if this cache contains no
     * mapping for the key.
     *
     * @param key the key whose associated value is to be returned
     * @return the value to which the specified key is mapped, or null if this cache contains no
     * mapping for the key
     */
    public V get(K key) {
        if (!data.containsKey(key)) {
            return null;
        }
        final Entry<K, V> entry = data.get(key);
        moveNodeToLast(entry);
        return entry.getValue();
    }

    /**
     * Moves the specified entry to the end of the list.
     *
     * @param entry the entry to move
     */
    private void moveNodeToLast(Entry<K, V> entry) {
        if (tail == entry) {
            return;
        }
        final Entry<K, V> preEntry = entry.getPreEntry();
        final Entry<K, V> nextEntry = entry.getNextEntry();
        if (preEntry != null) {
            preEntry.setNextEntry(nextEntry);
        }
        if (nextEntry != null) {
            nextEntry.setPreEntry(preEntry);
        }
        if (head == entry) {
            head = nextEntry;
        }
        tail.setNextEntry(entry);
        entry.setPreEntry(tail);
        entry.setNextEntry(null);
        tail = entry;
    }

    /**
     * Associates the specified value with the specified key in this cache.
     *
     * @param key the key with which the specified value is to be associated
     * @param value the value to be associated with the specified key
     */
    public void put(K key, V value) {
        if (data.containsKey(key)) {
            final Entry<K, V> existingEntry = data.get(key);
            existingEntry.setValue(value);
            moveNodeToLast(existingEntry);
            return;
        }
        Entry<K, V> newEntry;
        if (data.size() == cap) {
            newEntry = evict();
            data.remove(newEntry.getKey());
        } else {
            newEntry = new Entry<>();
        }

        newEntry.setKey(key);
        newEntry.setValue(value);
        addNewEntry(newEntry);
        data.put(key, newEntry);
    }

    /**
     * Adds a new entry to the end of the list.
     *
     * @param newEntry the entry to add
     */
    private void addNewEntry(Entry<K, V> newEntry) {
        if (data.isEmpty()) {
            head = newEntry;
            tail = newEntry;
            return;
        }
        tail.setNextEntry(newEntry);
        newEntry.setPreEntry(tail);
        newEntry.setNextEntry(null);
        tail = newEntry;
    }

    static final class Entry<I, J> {

        private Entry<I, J> preEntry;
        private Entry<I, J> nextEntry;
        private I key;
        private J value;

        Entry() {
        }

        Entry(Entry<I, J> preEntry, Entry<I, J> nextEntry, I key, J value) {
            this.preEntry = preEntry;
            this.nextEntry = nextEntry;
            this.key = key;
            this.value = value;
        }

        public Entry<I, J> getPreEntry() {
            return preEntry;
        }

        public void setPreEntry(Entry<I, J> preEntry) {
            this.preEntry = preEntry;
        }

        public Entry<I, J> getNextEntry() {
            return nextEntry;
        }

        public void setNextEntry(Entry<I, J> nextEntry) {
            this.nextEntry = nextEntry;
        }

        public I getKey() {
            return key;
        }

        public void setKey(I key) {
            this.key = key;
        }

        public J getValue() {
            return value;
        }

        public void setValue(J value) {
            this.value = value;
        }
    }
}

/**
 * The ADFGVX cipher is a fractionating transposition cipher that was used by
 * the German Army during World War I. It combines a **Polybius square substitution**
 * with a **columnar transposition** to enhance encryption strength.
 * <p>
 * The name "ADFGVX" refers to the six letters (A, D, F, G, V, X) used as row and
 * column labels in the Polybius square. This cipher was designed to secure
 * communication and create complex, hard-to-break ciphertexts.
 * <p>
 * Learn more: <a href="https://en.wikipedia.org/wiki/ADFGVX_cipher">ADFGVX Cipher - Wikipedia</a>.
 * <p>
 * Example usage:
 * <pre>
 * ADFGVXCipher cipher = new ADFGVXCipher();
 * String encrypted = cipher.encrypt("attack at 1200am", "PRIVACY");
 * String decrypted = cipher.decrypt(encrypted, "PRIVACY");
 * </pre>
 *
 * @author bennybebo
 */
public class ADFGVXCipher {

private static final char[] POLYBIUS_CHARS = {'A', 'D', 'F', 'G', 'V', 'X'};
private static final char[][] POLYBIUS_GRID = {
{'N', 'A', '1', 'C', '3', 'H'},
{'8', 'T', 'B', '2', 'O', 'M'},
{'E', '5', 'W', 'R', 'P', 'D'},
{'4', 'F', '6', 'G', '7', 'I'},
{'9', 'J', '0', 'K', 'L', 'Q'},
{'S', 'U', 'V', 'X', 'Y', 'Z'}
};

private static final Map<String, Character> SUBSTITUTION_MAP = new HashMap<>();
private static final Map<Character, String> REVERSE_SUBSTITUTION_MAP = new HashMap<>();

static {
for (int rowIndex = 0; rowIndex < POLYBIUS_GRID.length; rowIndex++) {
for (int colIndex = 0; colIndex < POLYBIUS_GRID[rowIndex].length; colIndex++) {
String codeKey = "" + POLYBIUS_CHARS[rowIndex] + POLYBIUS_CHARS[colIndex];
SUBSTITUTION_MAP.put(codeKey, POLYBIUS_GRID[rowIndex][colIndex]);
REVERSE_SUBSTITUTION_MAP.put(POLYBIUS_GRID[rowIndex][colIndex], codeKey);
}
}
}

public String encrypt(String inputText, String cipherKey) {
String cleanInput = inputText.toUpperCase().replaceAll("[^A-Z0-9]", "");
StringBuilder fractionatedData = new StringBuilder();
for (char currentChar : cleanInput.toCharArray()) {
fractionatedData.append(REVERSE_SUBSTITUTION_MAP.get(currentChar));
}
return applyColumnTransposition(fractionatedData.toString(), cipherKey);
}

public String decrypt(String encodedText, String cipherKey) {
String reversedFractionated = reverseColumnTransposition(encodedText, cipherKey);
StringBuilder resultText = new StringBuilder();
for (int index = 0; index < reversedFractionated.length(); index += 2) {
String charPair = reversedFractionated.substring(index, index + 2);
resultText.append(SUBSTITUTION_MAP.get(charPair));
}
return resultText.toString();
}

private String applyColumnTransposition(String sourceData, String cipherKey) {
int totalRows = (int) Math.ceil((double) sourceData.length() / cipherKey.length());
char[][] gridTable = new char[totalRows][cipherKey.length()];
for (char[] gridRow : gridTable) {
Arrays.fill(gridRow, '_');
}
for (int position = 0; position < sourceData.length(); position++) {
gridTable[position / cipherKey.length()][position % cipherKey.length()] = sourceData.charAt(position);
}
StringBuilder encryptedResult = new StringBuilder();
char[] sortedKeyChars = cipherKey.toCharArray();
Arrays.sort(sortedKeyChars);
for (char currentKeyChar : sortedKeyChars) {
int targetColumn = cipherKey.indexOf(currentKeyChar);
for (char[] gridRow : gridTable) {
if (gridRow[targetColumn] != '_') {
encryptedResult.append(gridRow[targetColumn]);
}
}
}
return encryptedResult.toString();
}

private String reverseColumnTransposition(String encryptedData, String cipherKey) {
int totalRows = (int) Math.ceil((double) encryptedData.length() / cipherKey.length());
char[][] gridTable = new char[totalRows][cipherKey.length()];
char[] sortedKeyChars = cipherKey.toCharArray();
Arrays.sort(sortedKeyChars);
int dataPos = 0;
for (char currentKeyChar : sortedKeyChars) {
int targetColumn = cipherKey.indexOf(currentKeyChar);
for (int rowPos = 0; rowPos < totalRows; rowPos++) {
if (dataPos < encryptedData.length()) {
gridTable[rowPos][targetColumn] = encryptedData.charAt(dataPos++);
} else {
gridTable[rowPos][targetColumn] = '_';
}
}
}
StringBuilder fractionatedResult = new StringBuilder();
for (char[] gridRow : gridTable) {
for (char cellChar : gridRow) {
if (cellChar != '_') {
fractionatedResult.append(cellChar);
}
}
}
return fractionatedResult.toString();
}
}

