package MyTime;

import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * A clock time holder formatted as HH:mm:ss.
 */
public class MyTime {
    private int hour;
    private int minute;
    private int second;

    public MyTime(int hour, int minute, int second) {
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    public int getHour() {
        return hour;
    }

    public void setHour(int hour) {
        this.hour = hour;
    }

    public int getMinute() {
        return minute;
    }

    public void setMinute(int minute) {
        this.minute = minute;
    }

    public int getSecond() {
        return second;
    }

    public void setSecond(int second) {
        this.second = second;
    }

    public void setTime(int hour, int minute, int second) {
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    @Override
    public String toString() {
        String raw = hour + ":" + minute + ":" + second;
        Date parsed = null;
        try {
            parsed = new SimpleDateFormat("HH:mm:ss").parse(raw);
        } catch (ParseException ex) {
            Logger.getLogger(MyTime.class.getName()).log(Level.SEVERE, null, ex);
        }
        return new SimpleDateFormat("HH:mm:ss").format(parsed);
    }

    public MyTime nextHour() {
        hour++;
        return this;
    }

    public MyTime nextMinute() {
        minute++;
        return this;
    }

    public MyTime nextSecond() {
        second++;
        return this;
    }

    public MyTime previousHour() {
        hour--;
        return this;
    }

    public MyTime previousMinute() {
        minute--;
        return this;
    }

    public MyTime previousSecond() {
        second--;
        return this;
    }
}

class TestMyTime {
    public static void main(String[] args) {
        MyTime myTime = new MyTime(23, 59, 59);
        System.out.println(myTime);
        myTime.nextHour();
        System.out.println(myTime);
        myTime.nextSecond();
        System.out.println(myTime);
    }
}

