/**
 * Recursive Solution for 0-1 knapsack with memoization
 * This method is basically an extension to the recursive approach so that we
 * can overcome the problem of calculating redundant cases and thus increased
 * complexity. We can solve this problem by simply creating a 2-D array that can
 * store a particular state (n, w) if we get it the first time.
 */
public class KnapsackMemoization {

    int knapSack(int capacity, int[] weights, int[] profits, int numOfItems) {

        // Declare the table dynamically
        int[][] dpTable = new int[numOfItems + 1][capacity + 1];

        // Loop to initially fill the table with -1
        for (int[] table : dpTable) {
            Arrays.fill(table, -1);
        }

        return solveKnapsackRecursive(capacity, weights, profits, numOfItems, dpTable);
    }

    // Returns the value of maximum profit using recursive approach
    int solveKnapsackRecursive(int capacity, int[] weights, int[] profits, int numOfItems, int[][] dpTable) {
        // Base condition
        if (numOfItems == 0 || capacity == 0) {
            return 0;
        }

        if (dpTable[numOfItems][capacity] != -1) {
            return dpTable[numOfItems][capacity];
        }

        if (weights[numOfItems - 1] > capacity) {
            // Store the value of function call stack in table
            dpTable[numOfItems][capacity] = solveKnapsackRecursive(capacity, weights, profits, numOfItems - 1, dpTable);
        } else {
            // case 1. include the item, if it is less than the capacity
            final int includeCurrentItem = profits[numOfItems - 1] + solveKnapsackRecursive(capacity - weights[numOfItems - 1], weights, profits, numOfItems - 1, dpTable);

            // case 2. exclude the item if it is more than the capacity
            final int excludeCurrentItem = solveKnapsackRecursive(capacity, weights, profits, numOfItems - 1, dpTable);

            // Store the value of function call stack in table and return
            dpTable[numOfItems][capacity] = Math.max(includeCurrentItem, excludeCurrentItem);
        }
        return dpTable[numOfItems][capacity];
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 *
 * Author: Janmesh Singh
 * Github: https://github.com/janmeshjs

 * Problem Statement: To determine if the pattern matches the text.
 * The pattern can include two special wildcard characters:
 *       ' ? ': Matches any single character.
 *       ' * ': Matches zero or more of any character sequence.
 *
 * Use DP to return True if the pattern matches the entire text and False otherwise
 *
 */
public final class WildcardMatching {
    private WildcardMatching() {
    }

    public static boolean isMatch(String text, String pattern) {
        int m = text.length();
        int n = pattern.length();

        // Create a DP table to store intermediate results
        boolean[][] dp = new boolean[m + 1][n + 1];

        // Base case: an empty pattern matches an empty text
        dp[0][0] = true;

        // Handle patterns starting with '*'
        for (int j = 1; j <= n; j++) {
            if (pattern.charAt(j - 1) == '*') {
                dp[0][j] = dp[0][j - 1];
            }
        }

        // Fill the DP table
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                char textChar = text.charAt(i - 1);
                char patternChar = pattern.charAt(j - 1);

                if (patternChar == textChar || patternChar == '?') {
                    dp[i][j] = dp[i - 1][j - 1];
                } else if (patternChar == '*') {
                    // '*' can match zero or more characters
                    dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
                } else {
                    dp[i][j] = false;
                }
            }
        }
        // The result is in the bottom-right cell of the DP table
        return dp[m][n];
    }
}

public class IkiliArama {

    // Klasik ikili (binary) arama - sinirlari daraltarak calisir
    public static int ara(int[] siraliDizi, int hedef) {
        int altSinir = 0;
        int ustSinir = siraliDizi.length - 1;

        while (altSinir <= ustSinir) {
            int ortaIndeks = (altSinir + ustSinir) >>> 1;
            int ortaDeger = siraliDizi[ortaIndeks];

            if (ortaDeger == hedef) {
                return ortaIndeks;
            } else if (ortaDeger < hedef) {
                altSinir = ortaIndeks + 1;
            } else {
                ustSinir = ortaIndeks - 1;
            }
        }

        return -1;
    }

    public static void main(String[] args) {
        try (Scanner girisOkuyucu = new Scanner(System.in)) {

            int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

            System.out.println(Arrays.toString(dizi));

            Arrays.sort(dizi);

            System.out.println(Arrays.toString(dizi));

            System.out.print("Aranacak degeri girin: ");
            int hedefDeger = girisOkuyucu.nextInt();

            int bulunanIndeks = ara(dizi, hedefDeger);

            if (bulunanIndeks == -1) {
                System.out.println("Deger bulunamadi.");
            } else {
                System.out.println("Deger bulundu! Indis: " + bulunanIndeks);
            }
        }
    }
}

package com.thealgorithms.datastructures.graphs;

import java.util.Arrays;
import java.util.Set;
import java.util.TreeSet;
import org.apache.commons.lang3.tuple.Pair;

/**
 * Dijkstra's algorithm for finding the shortest path from a single source vertex to all other vertices in a graph.
 */
public class DijkstraOptimizedAlgorithm {

    private final int vertexCount;

    /**
     * Constructs a Dijkstra object with the given number of vertices.
     *
     * @param vertexCount The number of vertices in the graph.
     */
    public DijkstraOptimizedAlgorithm(int vertexCount) {
        this.vertexCount = vertexCount;
    }

    /**
     * Executes Dijkstra's algorithm on the provided graph to find the shortest paths from the source vertex to all other vertices.
     *
     * The graph is represented as an adjacency matrix where {@code graph[i][j]} represents the weight of the edge from vertex {@code i}
     * to vertex {@code j}. A value of 0 indicates no edge exists between the vertices.
     *
     * @param graph The graph represented as an adjacency matrix.
     * @param source The source vertex.
     * @return An array where the value at each index {@code i} represents the shortest distance from the source vertex to vertex {@code i}.
     * @throws IllegalArgumentException if the source vertex is out of range.
     */
    public int[] run(int[][] graph, int source) {
        if (source < 0 || source >= vertexCount) {
            throw new IllegalArgumentException("Incorrect source");
        }

        int[] distances = new int[vertexCount];
        boolean[] processed = new boolean[vertexCount];
        Set<Pair<Integer, Integer>> unprocessed = new TreeSet<>();

        Arrays.fill(distances, Integer.MAX_VALUE);
        Arrays.fill(processed, false);
        distances[source] = 0;
        unprocessed.add(Pair.of(0, source));

        while (!unprocessed.isEmpty()) {
            Pair<Integer, Integer> distanceAndU = unprocessed.iterator().next();
            unprocessed.remove(distanceAndU);
            int u = distanceAndU.getRight();
            processed[u] = true;

            for (int v = 0; v < vertexCount; v++) {
                if (!processed[v] && graph[u][v] != 0 && distances[u] != Integer.MAX_VALUE && distances[u] + graph[u][v] < distances[v]) {
                    unprocessed.remove(Pair.of(distances[v], v));
                    distances[v] = distances[u] + graph[u][v];
                    unprocessed.add(Pair.of(distances[v], v));
                }
            }
        }

        return distances;
    }
}

package com.thealgorithms.ciphers;

import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.HexFormat;

/**
 * A simple implementation of the XOR cipher that allows both encryption and decryption
 * using a given key. This cipher works by applying the XOR bitwise operation between
 * the bytes of the input text and the corresponding bytes of the key (repeating the key
 * if necessary).
 *
 * Usage:
 * - Encryption: Converts plaintext into a hexadecimal-encoded ciphertext.
 * - Decryption: Converts the hexadecimal ciphertext back into plaintext.
 *
 * Characteristics:
 * - Symmetric: The same key is used for both encryption and decryption.
 * - Simple but vulnerable: XOR encryption is insecure for real-world cryptography,
 *   especially when the same key is reused.
 *
 * Example:
 * Plaintext: "Hello!"
 * Key: "key"
 * Encrypted: "27090c03120b"
 * Decrypted: "Hello!"
 *
 * Reference: <a href="https://en.wikipedia.org/wiki/XOR_cipher">XOR Cipher - Wikipedia</a>
 *
 * @author <a href="https://github.com/lcsjunior">lcsjunior</a>
 */
public final class XORCipher {

// Default character encoding for string conversion
private static final Charset DEFAULT_CHARSET = StandardCharsets.UTF_8;

private XORCipher() {
}

/**
 * Applies the XOR operation between the input bytes and the key bytes.
 * If the key is shorter than the input, it wraps around (cyclically).
 *
 * @param sourceBytes The input byte array (plaintext or ciphertext).
 * @param keyBytes The key byte array used for XOR operation.
 * @return A new byte array containing the XOR result.
 */
public static byte[] xorBytes(final byte[] sourceBytes, final byte[] keyBytes) {
byte[] outputData = new byte[sourceBytes.length];
for (int bytePosition = 0; bytePosition < sourceBytes.length; ++bytePosition) {
outputData[bytePosition] = (byte) (sourceBytes[bytePosition] ^ keyBytes[bytePosition % keyBytes.length]);
}
return outputData;
}

/**
 * Encrypts the given plaintext using the XOR cipher with the specified key.
 * The result is a hexadecimal-encoded string representing the ciphertext.
 *
 * @param sourceText The input plaintext to encrypt.
 * @param secretKey The encryption key.
 * @throws IllegalArgumentException if the key is empty.
 * @return A hexadecimal string representing the encrypted text.
 */
public static String encrypt(final String sourceText, final String secretKey) {
if (secretKey.isEmpty()) {
throw new IllegalArgumentException("Key must not be empty");
}
byte[] sourceData = sourceText.getBytes(DEFAULT_CHARSET);
byte[] keyData = secretKey.getBytes(DEFAULT_CHARSET);
byte[] xorResultData = xorBytes(sourceData, keyData);
return HexFormat.of().formatHex(xorResultData);
}

/**
 * Decrypts the given ciphertext (in hexadecimal format) using the XOR cipher
 * with the specified key. The result is the original plaintext.
 *
 * @param encodedText The hexadecimal string representing the encrypted text.
 * @param secretKey The decryption key (must be the same as the encryption key).
 * @throws IllegalArgumentException if the key is empty.
 * @return The decrypted plaintext.
 */
public static String decrypt(final String encodedText, final String secretKey) {
if (secretKey.isEmpty()) {
throw new IllegalArgumentException("Key must not be empty");
}
byte[] encodedData = HexFormat.of().parseHex(encodedText);
byte[] keyData = secretKey.getBytes(DEFAULT_CHARSET);
byte[] xorResultData = xorBytes(encodedData, keyData);
return new String(xorResultData, DEFAULT_CHARSET);
}
}

/**
 * A guitar, comparable by price then serial number.
 */
public class Guitar implements Comparable<Guitar> {

    private String serialNumber;
    private double price;
    private String builder;
    private String model;
    private String backWood;
    private String topWood;

    public Guitar() {
    }

    public Guitar(String serialNumber, double price, String builder, String model, String backWood, String topWood) {
        this.serialNumber = serialNumber;
        this.price = price;
        this.builder = builder;
        this.model = model;
        this.backWood = backWood;
        this.topWood = topWood;
    }

    public String getSerialNumber() {
        return serialNumber;
    }

    public void setSerialNumber(String serialNumber) {
        if (!serialNumber.isEmpty()) {
            this.serialNumber = serialNumber;
        }
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        this.price = price;
    }

    public String getBuilder() {
        return builder;
    }

    public void setBuilder(String builder) {
        this.builder = builder;
    }

    public String getModel() {
        return model;
    }

    public void setModel(String model) {
        this.model = model;
    }

    public String getBackWood() {
        return backWood;
    }

    public void setBackWood(String backWood) {
        this.backWood = backWood;
    }

    public String getTopWood() {
        return topWood;
    }

    public void setTopWood(String topWood) {
        this.topWood = topWood;
    }

    public void createSound() {
        System.out.println("serialNumber: " + getSerialNumber());
        System.out.println("Price: " + getPrice());
        System.out.println("Builder: " + getBuilder());
        System.out.println("Model: " + getModel());
        System.out.println("BackWood: " + getBackWood());
        System.out.println("TopWood: " + getTopWood());
    }

    @Override
    public String toString() {
        return "Guitar{serialNumber=" + serialNumber + ", price=" + price + ", builder=" + builder + ", model=" + model + ", backWood=" + backWood + ", topWood=" + topWood + '}';
    }

    @Override
    public int compareTo(Guitar other) {
        if (price > other.getPrice()) {
            return 1;
        } else if (price < other.getPrice()) {
            return -1;
        } else {
            return serialNumber.compareTo(other.getSerialNumber());
        }
    }
}

