public class RakamlarToplami {

    // Sayinin tum rakamlarinin toplamini hesaplar
    int rakamToplamiHesapla(int deger) {
        int toplam = 0;

        while (deger > 0) {
            int sonRakam = deger % 10; // en sagdaki rakami ayikla
            toplam += sonRakam;
            deger /= 10; // bir hane kisalt
        }

        return toplam;
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);

        System.out.println("Lutfen bir sayi giriniz:");
        int girilenDeger = tarayici.nextInt();

        RakamlarToplami hesaplayici = new RakamlarToplami();

        int sonuc = hesaplayici.rakamToplamiHesapla(girilenDeger);
        System.out.println("Rakamlar Toplami = " + sonuc);

        tarayici.close();
    }
}

