package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;

/**
 * AStar class implements the A* pathfinding algorithm to find the shortest path in a graph.
 * The graph is represented using an adjacency list, and the algorithm uses a heuristic to estimate
 * the cost to reach the destination node.
 * Time Complexity = O(E), where E is equal to the number of edges
 */
public final class AStar {
private AStar() {
}

/**
 * Represents a graph using an adjacency list.
 */
static class GraphData {
private ArrayList<ArrayList<EdgeItem>> adjacencyList;

GraphData(int vertexCount) {
this.adjacencyList = new ArrayList<>();
for (int nodeIndex = 0; nodeIndex < vertexCount; nodeIndex++) {
this.adjacencyList.add(new ArrayList<>());
}
}

private ArrayList<EdgeItem> getNeighbors(int sourceNode) {
return this.adjacencyList.get(sourceNode);
}

private void insertEdge(EdgeItem edgeData) {
this.adjacencyList.get(edgeData.getStartNode()).add(new EdgeItem(edgeData.getStartNode(), edgeData.getEndNode(), edgeData.getWeightValue()));
this.adjacencyList.get(edgeData.getEndNode()).add(new EdgeItem(edgeData.getEndNode(), edgeData.getStartNode(), edgeData.getWeightValue()));
}
}

/**
 * Represents an edge in the graph with a start node, end node, and weight.
 */
private static class EdgeItem {
private int startNode;
private int endNode;
private int weightValue;

EdgeItem(int fromNode, int toNode, int edgeWeight) {
this.startNode = fromNode;
this.endNode = toNode;
this.weightValue = edgeWeight;
}

public int getStartNode() {
return startNode;
}

public int getEndNode() {
return endNode;
}

public int getWeightValue() {
return weightValue;
}
}

/**
 * Contains information about the path and its total distance.
 */
static class SearchResult {
private int totalDistance;
private ArrayList<Integer> nodePath;
private int heuristicEstimate;

SearchResult(int distanceValue, ArrayList<Integer> pathSequence, int estimateValue) {
this.totalDistance = distanceValue;
this.nodePath = pathSequence;
this.heuristicEstimate = estimateValue;
}

public int getTotalDistance() {
return totalDistance;
}

public ArrayList<Integer> getNodePath() {
return nodePath;
}

public int getHeuristicEstimate() {
return heuristicEstimate;
}
}

static void buildGraph(GraphData graphData, List<Integer> edgeData) {
for (int dataIndex = 0; dataIndex < edgeData.size(); dataIndex += 4) {
graphData.insertEdge(new EdgeItem(edgeData.get(dataIndex), edgeData.get(dataIndex + 1), edgeData.get(dataIndex + 2)));
}
}

/**
 * Implements the A* pathfinding algorithm to find the shortest path from a start node to a destination node.
 *
 * @param startNode     the starting node
 * @param targetNode       the destination node
 * @param graphData    the graph representation of the problem
 * @param heuristicData the heuristic estimates for each node
 * @return a SearchResult object containing the shortest path and its distance
 */
public static SearchResult findShortestPath(int startNode, int targetNode, GraphData graphData, int[] heuristicData) {
PriorityQueue<SearchResult> openSet = new PriorityQueue<>(Comparator.comparingInt(candidate -> (candidate.getTotalDistance() + candidate.getHeuristicEstimate())));
openSet.add(new SearchResult(0, new ArrayList<>(List.of(startNode)), heuristicData[startNode]));
boolean pathFound = false;
SearchResult currentEntry = new SearchResult(-1, null, -1);
while (!openSet.isEmpty() && !pathFound) {
currentEntry = openSet.poll();
int currentNode = currentEntry.getNodePath().get(currentEntry.getNodePath().size() - 1);
if (currentNode == targetNode) {
pathFound = true;
} else {
for (EdgeItem adjacentEdge : graphData.getNeighbors(currentNode)) {
if (!currentEntry.getNodePath().contains(adjacentEdge.getEndNode())) {
ArrayList<Integer> extendedPath = new ArrayList<>(currentEntry.getNodePath());
extendedPath.add(adjacentEdge.getEndNode());
openSet.add(new SearchResult(currentEntry.getTotalDistance() + adjacentEdge.getWeightValue(), extendedPath, heuristicData[adjacentEdge.getEndNode()]));
}
}
}
}
return (pathFound) ? currentEntry : new SearchResult(-1, null, -1);
}
}
