package array;

/*
 * Tiny demo showing basic array mechanics: build one, print it,
 * sum its contents, then mutate a single slot and print again.
 */
public class DiziOrnegi {

    public static void main(String[] args) {
        int[] veriler = {1, 2, 3, 4, 5};

        System.out.println("Dizi Elemanlari:");
        yazdir(veriler);
        System.out.println();

        int toplam = topla(veriler);
        System.out.println("Dizi Elemanlarinin Toplami: " + toplam);

        veriler[2] = 10;

        System.out.println("Guncellenmis Dizi Elemanlari:");
        yazdir(veriler);
    }

    private static void yazdir(int[] veriler) {
        for (int deger : veriler) {
            System.out.print(deger + " ");
        }
    }

    private static int topla(int[] veriler) {
        int sonuc = 0;
        for (int deger : veriler) {
            sonuc += deger;
        }
        return sonuc;
    }
}

