import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;

// Hesap Makinesi GUI uygulamasi
public class HesapMakinesi extends JFrame {

	private static final long serialVersionUID = 1L;
	private JTextField metinKutusu; // Sayi ve sonuclarin gosterilecegi metin kutusu
    private String operator; // Secilen matematiksel operator (+, -, x, /)
    private double birinciSayi; // Ilk operand
    private boolean operatorTiklandi; // Operator secildiginde durumu tutar

    // Yapici metot: Arayuz olusturulur
    public HesapMakinesi() {
        setTitle("Hesap Makinesi"); // Pencere basligi
        setSize(300, 400); // Pencere boyutu
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE); // Cikis islemi
        setLayout(new BorderLayout()); // Cerceve duzeni

        operator = "";
        birinciSayi = 0;
        operatorTiklandi = false;

        // Metin kutusunu olustur ve ust bolgeye ekle
        metinKutusu = new JTextField();
        metinKutusu.setEditable(false); // Kullanici dogrudan metin kutusuna yazamaz
        metinKutusu.setFont(new Font("Arial", Font.PLAIN, 24)); // Daha buyuk bir yazi tipi
        metinKutusu.setPreferredSize(new Dimension(0, 50)); // Metin kutusunun yuksekligini arttir
        add(metinKutusu, BorderLayout.NORTH);

        // Buton panelini olustur
        JPanel butonPaneli = new JPanel();
        butonPaneli.setLayout(new GridLayout(4, 4)); // 4x4 duzen

        // Butonlarin metinlerini tanimla
        String[] butonlar = {
                "7", "8", "9", "/",
                "4", "5", "6", "x",
                "1", "2", "3", "-",
                "0", "AC", "=", "+"
        };

        // Her buton icin dongu ile islem yap
        for (String buton : butonlar) {
            JButton btn = new JButton(buton); // Butonu olustur
            btn.addActionListener(new ButonTiklamaDinleyicisi()); // Tiklama olayini dinle
            butonPaneli.add(btn); // Butonu panele ekle
        }

        add(butonPaneli, BorderLayout.CENTER); // Buton panelini orta bolgeye ekle
    }

    // Butonlara tiklandiginda yapilacak islemler
    private class ButonTiklamaDinleyicisi implements ActionListener {

        public void actionPerformed(ActionEvent e) {

            String komut = e.getActionCommand(); // Tiklanan butonun metni alinir

            if (komut.matches("[0-9]")) { // Eger bir sayi ise
                if (operatorTiklandi) { // Eger daha once operator tiklandiysa
                    metinKutusu.setText(""); // Metin kutusunu temizle
                    operatorTiklandi = false;
                }
                metinKutusu.setText(metinKutusu.getText() + komut); // Sayiyi ekle
            } else if (komut.equals("AC")) { // Eger "AC" (Temizle) tiklandiysa
                metinKutusu.setText(""); // Metin kutusunu temizle
            } else if (komut.matches("[+\\-x/]")) { // Eger bir operator tiklandiysa
                operator = komut; // Operatoru kaydet
                birinciSayi = Double.parseDouble(metinKutusu.getText()); // Ilk sayiyi kaydet
                operatorTiklandi = true; // Operator tiklandigini isaretle
            } else if (komut.equals("=")) { // Eger "=" tiklandiysa
                double ikinciSayi = Double.parseDouble(metinKutusu.getText()); // Ikinci sayiyi al
                double sonuc = 0; // Sonuc degiskeni

                // Operatore gore islem yap
                switch (operator) {
                    case "+":
                        sonuc = birinciSayi + ikinciSayi;
                        break;
                    case "-":
                        sonuc = birinciSayi - ikinciSayi;
                        break;
                    case "x":
                        sonuc = birinciSayi * ikinciSayi;
                        break;
                    case "/":
                        sonuc = birinciSayi / ikinciSayi;
                        break;
                }

                metinKutusu.setText(String.valueOf(sonuc)); // Sonucu goster
                operatorTiklandi = true; // Yeni islem icin hazirla
            }
        }
    }

    // Ana metot: Uygulamayi baslatir
    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            public void run() {
                HesapMakinesi hesapMakinesi = new HesapMakinesi(); // Hesap makinesi olustur
                hesapMakinesi.setVisible(true); // Gorunur yap
            }
        });
    }
}

package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.Map;

/**
 * Converts text to the NATO phonetic alphabet.
 * Examples:
 * "ABC" -> "Alpha Bravo Charlie"
 * "Hello" -> "Hotel Echo Lima Lima Oscar"
 * "123" -> "One Two Three"
 * "A1B2C3" -> "Alpha One Bravo Two Charlie Three"
 *
 * @author Hardvan
 */
public final class PhoneticAlphabetConverter {
    private PhoneticAlphabetConverter() {
    }

    private static final Map<Character, String> PHONETIC_MAP = new HashMap<>();

    static {
        PHONETIC_MAP.put('A', "Alpha");
        PHONETIC_MAP.put('B', "Bravo");
        PHONETIC_MAP.put('C', "Charlie");
        PHONETIC_MAP.put('D', "Delta");
        PHONETIC_MAP.put('E', "Echo");
        PHONETIC_MAP.put('F', "Foxtrot");
        PHONETIC_MAP.put('G', "Golf");
        PHONETIC_MAP.put('H', "Hotel");
        PHONETIC_MAP.put('I', "India");
        PHONETIC_MAP.put('J', "Juliett");
        PHONETIC_MAP.put('K', "Kilo");
        PHONETIC_MAP.put('L', "Lima");
        PHONETIC_MAP.put('M', "Mike");
        PHONETIC_MAP.put('N', "November");
        PHONETIC_MAP.put('O', "Oscar");
        PHONETIC_MAP.put('P', "Papa");
        PHONETIC_MAP.put('Q', "Quebec");
        PHONETIC_MAP.put('R', "Romeo");
        PHONETIC_MAP.put('S', "Sierra");
        PHONETIC_MAP.put('T', "Tango");
        PHONETIC_MAP.put('U', "Uniform");
        PHONETIC_MAP.put('V', "Victor");
        PHONETIC_MAP.put('W', "Whiskey");
        PHONETIC_MAP.put('X', "X-ray");
        PHONETIC_MAP.put('Y', "Yankee");
        PHONETIC_MAP.put('Z', "Zulu");
        PHONETIC_MAP.put('0', "Zero");
        PHONETIC_MAP.put('1', "One");
        PHONETIC_MAP.put('2', "Two");
        PHONETIC_MAP.put('3', "Three");
        PHONETIC_MAP.put('4', "Four");
        PHONETIC_MAP.put('5', "Five");
        PHONETIC_MAP.put('6', "Six");
        PHONETIC_MAP.put('7', "Seven");
        PHONETIC_MAP.put('8', "Eight");
        PHONETIC_MAP.put('9', "Nine");
    }

    /**
     * Converts text to the NATO phonetic alphabet.
     * Steps:
     * 1. Convert the text to uppercase.
     * 2. Iterate over each character in the text.
     * 3. Get the phonetic equivalent of the character from the map.
     * 4. Append the phonetic equivalent to the result.
     * 5. Append a space to separate the phonetic equivalents.
     * 6. Return the result.
     *
     * @param text the text to convert
     * @return the NATO phonetic alphabet
     */
    public static String textToPhonetic(String text) {
        StringBuilder phonetic = new StringBuilder();
        for (char c : text.toUpperCase().toCharArray()) {
            if (Character.isWhitespace(c)) {
                continue;
            }
            phonetic.append(PHONETIC_MAP.getOrDefault(c, String.valueOf(c))).append(" ");
        }
        return phonetic.toString().trim();
    }
}

package objects;

import java.util.ArrayList;
import java.util.List;

public class Ogrenci {

    private String ad;
    private int numara;
    private List<String> dersler;
    private List<Double> notlar;

    // Constructor: ogrenci adi, numarasi ve dersler listesi
    public Ogrenci(String ad, int numara) {
        this.ad = ad;
        this.numara = numara;
        this.dersler = new ArrayList<>();
        this.notlar = new ArrayList<>();
    }

    // Selam verme metodu
    public void selamVer() {
        System.out.println("Merhaba, ben " + this.ad + ". Numaram: " + this.numara);
    }

    // ogrenciye ders ekleme metodu
    public void dersEkle(String dersAdi, double notu) {
        dersler.add(dersAdi);
        notlar.add(notu);
        System.out.println(dersAdi + " dersi ve " + notu + " notu eklendi.");
    }

    // ogrencinin basari durumunu kontrol etme
    public void basariDurumu() {
        double ortalama = 0;
        for (double not : notlar) {
            ortalama += not;
        }
        ortalama /= notlar.size();

        System.out.println(ad + " adli ogrencinin not ortalamasi: " + ortalama);

        if (ortalama >= 60) {
            System.out.println(ad + " basarili.");
        } else {
            System.out.println(ad + " basarisiz.");
        }
    }

    // ogrencinin derslerinin ve notlarinin listesini yazdirma
    public void dersleriYazdir() {
        System.out.println(ad + " adli ogrencinin dersleri ve notlari:");
        for (int i = 0; i < dersler.size(); i++) {
            System.out.println(dersler.get(i) + " - Not: " + notlar.get(i));
        }
    }

    // toString metodunu ozellestirme
    @Override
    public String toString() {
        return "Ogrenci [ad=" + ad + ", numara=" + numara + ", dersler=" + dersler + ", notlar=" + notlar + "]";
    }

    // Ana metod (main method) icinde kullanimi
    public static void main(String[] args) {

        // Ogrenci nesneleri olusturuluyor
        Ogrenci ogrenci1 = new Ogrenci("Ali", 20122273);
        Ogrenci ogrenci2 = new Ogrenci("Ayse", 20132272);

        // Ders ve not ekleme
        ogrenci1.dersEkle("Matematik", 75.0);
        ogrenci1.dersEkle("Fizik", 82.0);
        ogrenci1.dersEkle("Kimya", 90.0);

        ogrenci2.dersEkle("Matematik", 65.0);
        ogrenci2.dersEkle("Fizik", 58.0);
        ogrenci2.dersEkle("Kimya", 72.0);

        // ogrencilerin selam vermesi
        ogrenci1.selamVer();
        ogrenci2.selamVer();

        // ogrencilerin derslerini ve basari durumlarini yazdirma
        ogrenci1.dersleriYazdir();
        ogrenci2.dersleriYazdir();

        // ogrencilerin basari durumlarini kontrol etme
        ogrenci1.basariDurumu();
        ogrenci2.basariDurumu();

        // ogrencilerin genel bilgilerini yazdirma
        System.out.println(ogrenci1);
        System.out.println(ogrenci2);
    }
}

