public class CarpimTablosu {

    public static void main(String[] args) {

        // Baslik yazdirilir
        System.out.println("Carpim Tablosu:");

        // Dis dongu: Satirlari temsil eder
        for (int i = 1; i <= 10; i++) {

            // Ic dongu: Sutunlari temsil eder
            for (int j = 1; j <= 10; j++) {

                // Carpim sonucu yazdirilir, tab ile hizalama yapilir
                System.out.print(i + "x" + j + "=" + (i * j) + "\t");
            }

            // Her satir tamamlandiginda yeni satira gecilir
            System.out.println();
        }
    }
}

// Demonstration of static variable initialization using static blocks
// Static blocks execute once when the class is first loaded into memory
public class StaticBlock {

    // Static variables (class variables)
    static int initialValue = 4;      // Static variable with explicit initialization
    static int calculatedValue;       // Static variable initialized in static block

    // Static initialization block
    // This block runs ONLY ONCE - when the class is first loaded into memory
    // It executes before any constructor and before the main method
    static {
        System.out.println("Static block executed - class is being loaded into memory");
        calculatedValue = initialValue * 5;  // CalculatedValue becomes 20 (4 × 5)
    }

    // Optional: Constructor to demonstrate that static block runs BEFORE constructors
    public StaticBlock() {
        System.out.println("Constructor called - new object being created");
    }

    // Optional: Instance block (non-static) - runs each time an object is created
    {
        System.out.println("Instance initialization block - runs before constructor");
    }

    public static void main(String[] args) {
        System.out.println("\n--- First Object Creation ---");
        StaticBlock firstObject = new StaticBlock();
        System.out.println("Values: initialValue = " + initialValue + 
                           ", calculatedValue = " + calculatedValue);

        System.out.println("\n--- Modifying Static Variable ---");
        calculatedValue += 3;  // Modifying static variable affects ALL objects
        System.out.println("After adding 3 to calculatedValue: " + calculatedValue);

        System.out.println("\n--- Second Object Creation ---");
        StaticBlock secondObject = new StaticBlock();
        System.out.println("Static variables retain their modified values: " + 
                           initialValue + " and " + calculatedValue);

        System.out.println("\n--- Key Observation ---");
        System.out.println("Static block ran ONLY ONCE (at the beginning)");
        System.out.println("Instance blocks and constructors run EACH TIME an object is created");
        System.out.println("Static variables are SHARED across all instances of the class");
    }
}

/*
Detailed Explanation of Static Blocks:
=======================================

What is a Static Block?
-----------------------
A static block is a block of code inside a Java class that is declared with the 'static' keyword.
It is used to initialize static variables or perform one-time setup operations.

When Does a Static Block Execute?
--------------------------------
- Executes ONCE when the class is first loaded into memory by the ClassLoader
- Before any object creation (constructors)
- Before the main method (if main is in the same class)
- In the order they appear in the source code (if multiple static blocks)

Order of Execution When Creating Objects:
-----------------------------------------
1. Static blocks (only once, at class loading)
2. Instance initialization blocks (each time an object is created)
3. Constructors (each time an object is created)

Use Cases for Static Blocks:
----------------------------
1. Initializing complex static variables that require multiple statements
2. Loading native libraries (System.loadLibrary())
3. Setting up database connections or configuration
4. Registering drivers (e.g., JDBC drivers)
5. Any one-time setup required before the class can be used

Important Characteristics:
--------------------------
- Cannot access non-static (instance) members directly
- Can throw checked exceptions (must be handled)
- A class can have multiple static blocks
- Static blocks are executed in the order they appear

Comparison of Initialization Methods:
======================================

| Method | When Executed | Use Case |
|--------|---------------|----------|
| Static variable initialization | Class loading | Simple constant values |
| Static block | Class loading | Complex initialization, multiple statements |
| Instance block | Each object creation | Common constructor code |
| Constructor | Each object creation | Object-specific initialization |

Example of Multiple Static Blocks:
----------------------------------
static {
    System.out.println("First static block");
}

static {
    System.out.println("Second static block");
}
// Output order: First static block, then Second static block
*/

public class Loto {

    // Havuzdaki sayilari karistirip istenen adette cekilis yapar
    public static Integer[] cekilisYap(int havuzBuyuklugu, int kacTaneCekilecek) {
        List<Integer> havuz = new ArrayList<>();

        for (int deger = 1; deger <= havuzBuyuklugu; deger++) {
            havuz.add(deger);
        }

        Collections.shuffle(havuz);

        Integer[] secilenler = new Integer[kacTaneCekilecek];
        for (int i = 0; i < kacTaneCekilecek; i++) {
            secilenler[i] = havuz.get(i);
        }

        return secilenler;
    }

    public static void main(String[] args) {
        Integer[] cekilenNumaralar = cekilisYap(49, 6);

        StringBuilder cikti = new StringBuilder();
        for (Integer numara : cekilenNumaralar) {
            cikti.append(numara).append(' ');
        }
        System.out.print(cikti);
    }
}

