/**
 * CursorLinkedList is an array-based implementation of a singly linked list.
 * Each node in the array simulates a linked list node, storing an element and
 * the index of the next node. This structure allows for efficient list operations
 * without relying on traditional pointers.
 *
 * @param <T> the type of elements in this list
 */
@SuppressWarnings({"rawtypes", "unchecked"})
public class CursorLinkedList<T> {

    /**
     * Node represents an individual element in the list, containing the element
     * itself and a pointer (index) to the next node.
     */
    private static class Node<T> {
        T element;
        int next;

        Node(T element, int next) {
            this.element = element;
            this.next = next;
        }
    }

    private final int os;
    private int head;
    private final Node<T>[] cursorSpace;
    private int count;
    private static final int CURSOR_SPACE_SIZE = 100;

    {
        // Initialize cursor space array and free list pointers
        cursorSpace = new Node[CURSOR_SPACE_SIZE];
        for (int i = 0; i < CURSOR_SPACE_SIZE; i++) {
            cursorSpace[i] = new Node<>(null, i + 1);
        }
        cursorSpace[CURSOR_SPACE_SIZE - 1].next = 0;
    }

    /**
     * Constructs an empty CursorLinkedList with the default capacity.
     */
    public CursorLinkedList() {
        os = 0;
        count = 0;
        head = -1;
    }

    /**
     * Prints all elements in the list in their current order.
     */
    public void printList() {
        if (head != -1) {
            int start = head;
            while (start != -1) {
                T element = cursorSpace[start].element;
                System.out.println(element.toString());
                start = cursorSpace[start].next;
            }
        }
    }

    /**
     * Finds the logical index of a specified element in the list.
     *
     * @param element the element to search for in the list
     * @return the logical index of the element, or -1 if not found
     * @throws NullPointerException if element is null
     */
    public int indexOf(T element) {
        if (element == null) {
            throw new NullPointerException("Element cannot be null");
        }
        try {
            Objects.requireNonNull(element);
            Node<T> iterator = cursorSpace[head];
            for (int i = 0; i < count; i++) {
                if (iterator.element.equals(element)) {
                    return i;
                }
                iterator = cursorSpace[iterator.next];
            }
        } catch (Exception e) {
            return -1;
        }
        return -1;
    }

    /**
     * Retrieves an element at a specified logical index in the list.
     *
     * @param position the logical index of the element
     * @return the element at the specified position, or null if index is out of bounds
     */
    public T get(int position) {
        if (position >= 0 && position < count) {
            int start = head;
            int counter = 0;
            while (start != -1) {
                T element = cursorSpace[start].element;
                if (counter == position) {
                    return element;
                }
                start = cursorSpace[start].next;
                counter++;
            }
        }
        return null;
    }

    /**
     * Removes the element at a specified logical index from the list.
     *
     * @param index the logical index of the element to remove
     */
    public void removeByIndex(int index) {
        if (index >= 0 && index < count) {
            T element = get(index);
            remove(element);
        }
    }

    /**
     * Removes a specified element from the list.
     *
     * @param element the element to be removed
     * @throws NullPointerException if element is null
     */
    public void remove(T element) {
        Objects.requireNonNull(element);
        T tempElement = cursorSpace[head].element;
        int tempNext = cursorSpace[head].next;
        if (tempElement.equals(element)) {
            free(head);
            head = tempNext;
        } else {
            int prevIndex = head;
            int currentIndex = cursorSpace[prevIndex].next;
            while (currentIndex != -1) {
                T currentElement = cursorSpace[currentIndex].element;
                if (currentElement.equals(element)) {
                    cursorSpace[prevIndex].next = cursorSpace[currentIndex].next;
                    free(currentIndex);
                    break;
                }
                prevIndex = currentIndex;
                currentIndex = cursorSpace[prevIndex].next;
            }
        }
        count--;
    }

    /**
     * Allocates a new node index for storing an element.
     *
     * @return the index of the newly allocated node
     * @throws OutOfMemoryError if no space is available in cursor space
     */
    private int alloc() {
        int availableNodeIndex = cursorSpace[os].next;
        if (availableNodeIndex == 0) {
            throw new OutOfMemoryError();
        }
        cursorSpace[os].next = cursorSpace[availableNodeIndex].next;
        cursorSpace[availableNodeIndex].next = -1;
        return availableNodeIndex;
    }

    /**
     * Releases a node back to the free list.
     *
     * @param index the index of the node to release
     */
    private void free(int index) {
        Node<T> osNode = cursorSpace[os];
        int osNext = osNode.next;
        cursorSpace[os].next = index;
        cursorSpace[index].element = null;
        cursorSpace[index].next = osNext;
    }

    /**
     * Appends an element to the end of the list.
     *
     * @param element the element to append
     * @throws NullPointerException if element is null
     */
    public void append(T element) {
        Objects.requireNonNull(element);
        int availableIndex = alloc();
        cursorSpace[availableIndex].element = element;
        if (head == -1) {
            head = availableIndex;
        } else {
            int iterator = head;
            while (cursorSpace[iterator].next != -1) {
                iterator = cursorSpace[iterator].next;
            }
            cursorSpace[iterator].next = availableIndex;
        }
        cursorSpace[availableIndex].next = -1;
        count++;
    }
}

package com.thealgorithms.bitmanipulation;

/**
 * This class provides a method to detect if two integers
 * differ by exactly one bit flip.
 *
 * Example:
 * 1 (0001) and 2 (0010) differ by exactly one bit flip.
 * 7 (0111) and 3 (0011) differ by exactly one bit flip.
 *
 * @author Hardvan
 */
public final class OneBitDifference {
private OneBitDifference() {
}

/**
 * Checks if two integers differ by exactly one bit.
 *
 * @param firstNumber the first integer
 * @param secondNumber the second integer
 * @return true if firstNumber and secondNumber differ by exactly one bit, false otherwise
 */
public static boolean differByOneBit(int firstNumber, int secondNumber) {
if (firstNumber == secondNumber) {
return false;
}
int xorResult = firstNumber ^ secondNumber;
return (xorResult & (xorResult - 1)) == 0;
}
}

package com.thealgorithms.conversions;

import java.util.Arrays;

/**
 * The RGB color model is an additive color model in which red, green, and blue
 * light are added together in various ways to reproduce a broad array of
 * colors. The name of the model comes from the initials of the three additive
 * primary colors, red, green, and blue. Meanwhile, the HSV representation
 * models how colors appear under light. In it, colors are represented using
 * three components: hue, saturation and (brightness-)value. This class provides
 * methods for converting colors from one representation to the other.
 * (description adapted from <a href="https://en.wikipedia.org/wiki/RGB_color_model">[1]</a> and
 * <a href="https://en.wikipedia.org/wiki/HSL_and_HSV">[2]</a>).
 */
public final class RgbHsvConversion {
    private RgbHsvConversion() {
    }

    public static void main(String[] args) {
        // Expected RGB-values taken from https://www.rapidtables.com/convert/color/hsv-to-rgb.html

        // Test hsvToRgb-method
        assert Arrays.equals(hsvToRgb(0, 0, 0), new int[] {0, 0, 0});
        assert Arrays.equals(hsvToRgb(0, 0, 1), new int[] {255, 255, 255});
        assert Arrays.equals(hsvToRgb(0, 1, 1), new int[] {255, 0, 0});
        assert Arrays.equals(hsvToRgb(60, 1, 1), new int[] {255, 255, 0});
        assert Arrays.equals(hsvToRgb(120, 1, 1), new int[] {0, 255, 0});
        assert Arrays.equals(hsvToRgb(240, 1, 1), new int[] {0, 0, 255});
        assert Arrays.equals(hsvToRgb(300, 1, 1), new int[] {255, 0, 255});
        assert Arrays.equals(hsvToRgb(180, 0.5, 0.5), new int[] {64, 128, 128});
        assert Arrays.equals(hsvToRgb(234, 0.14, 0.88), new int[] {193, 196, 224});
        assert Arrays.equals(hsvToRgb(330, 0.75, 0.5), new int[] {128, 32, 80});

        // Test rgbToHsv-method
        // approximate-assertions needed because of small deviations due to converting between
        // int-values and double-values.
        assert approximatelyEqualHsv(rgbToHsv(0, 0, 0), new double[] {0, 0, 0});
        assert approximatelyEqualHsv(rgbToHsv(255, 255, 255), new double[] {0, 0, 1});
        assert approximatelyEqualHsv(rgbToHsv(255, 0, 0), new double[] {0, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(255, 255, 0), new double[] {60, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(0, 255, 0), new double[] {120, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(0, 0, 255), new double[] {240, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(255, 0, 255), new double[] {300, 1, 1});
        assert approximatelyEqualHsv(rgbToHsv(64, 128, 128), new double[] {180, 0.5, 0.5});
        assert approximatelyEqualHsv(rgbToHsv(193, 196, 224), new double[] {234, 0.14, 0.88});
        assert approximatelyEqualHsv(rgbToHsv(128, 32, 80), new double[] {330, 0.75, 0.5});
    }

    /**
     * Conversion from the HSV-representation to the RGB-representation.
     *
     * @param hue Hue of the color.
     * @param saturation Saturation of the color.
     * @param value Brightness-value of the color.
     * @return The tuple of RGB-components.
     */
    public static int[] hsvToRgb(double hue, double saturation, double value) {
        if (hue < 0 || hue > 360) {
            throw new IllegalArgumentException("hue should be between 0 and 360");
        }

        if (saturation < 0 || saturation > 1) {
            throw new IllegalArgumentException("saturation should be between 0 and 1");
        }

        if (value < 0 || value > 1) {
            throw new IllegalArgumentException("value should be between 0 and 1");
        }

        double chroma = value * saturation;
        double hueSection = hue / 60;
        double secondLargestComponent = chroma * (1 - Math.abs(hueSection % 2 - 1));
        double matchValue = value - chroma;

        return getRgbBySection(hueSection, chroma, matchValue, secondLargestComponent);
    }

    /**
     * Conversion from the RGB-representation to the HSV-representation.
     *
     * @param red Red-component of the color.
     * @param green Green-component of the color.
     * @param blue Blue-component of the color.
     * @return The tuple of HSV-components.
     */
    public static double[] rgbToHsv(int red, int green, int blue) {
        if (red < 0 || red > 255) {
            throw new IllegalArgumentException("red should be between 0 and 255");
        }

        if (green < 0 || green > 255) {
            throw new IllegalArgumentException("green should be between 0 and 255");
        }

        if (blue < 0 || blue > 255) {
            throw new IllegalArgumentException("blue should be between 0 and 255");
        }

        double dRed = (double) red / 255;
        double dGreen = (double) green / 255;
        double dBlue = (double) blue / 255;
        double value = Math.max(Math.max(dRed, dGreen), dBlue);
        double chroma = value - Math.min(Math.min(dRed, dGreen), dBlue);
        double saturation = value == 0 ? 0 : chroma / value;
        double hue;

        if (chroma == 0) {
            hue = 0;
        } else if (value == dRed) {
            hue = 60 * (0 + (dGreen - dBlue) / chroma);
        } else if (value == dGreen) {
            hue = 60 * (2 + (dBlue - dRed) / chroma);
        } else {
            hue = 60 * (4 + (dRed - dGreen) / chroma);
        }

        hue = (hue + 360) % 360;

        return new double[] {hue, saturation, value};
    }

    private static boolean approximatelyEqualHsv(double[] hsv1, double[] hsv2) {
        boolean bHue = Math.abs(hsv1[0] - hsv2[0]) < 0.2;
        boolean bSaturation = Math.abs(hsv1[1] - hsv2[1]) < 0.002;
        boolean bValue = Math.abs(hsv1[2] - hsv2[2]) < 0.002;

        return bHue && bSaturation && bValue;
    }

    private static int[] getRgbBySection(double hueSection, double chroma, double matchValue, double secondLargestComponent) {
        int red;
        int green;
        int blue;

        if (hueSection >= 0 && hueSection <= 1) {
            red = convertToInt(chroma + matchValue);
            green = convertToInt(secondLargestComponent + matchValue);
            blue = convertToInt(matchValue);
        } else if (hueSection > 1 && hueSection <= 2) {
            red = convertToInt(secondLargestComponent + matchValue);
            green = convertToInt(chroma + matchValue);
            blue = convertToInt(matchValue);
        } else if (hueSection > 2 && hueSection <= 3) {
            red = convertToInt(matchValue);
            green = convertToInt(chroma + matchValue);
            blue = convertToInt(secondLargestComponent + matchValue);
        } else if (hueSection > 3 && hueSection <= 4) {
            red = convertToInt(matchValue);
            green = convertToInt(secondLargestComponent + matchValue);
            blue = convertToInt(chroma + matchValue);
        } else if (hueSection > 4 && hueSection <= 5) {
            red = convertToInt(secondLargestComponent + matchValue);
            green = convertToInt(matchValue);
            blue = convertToInt(chroma + matchValue);
        } else {
            red = convertToInt(chroma + matchValue);
            green = convertToInt(matchValue);
            blue = convertToInt(secondLargestComponent + matchValue);
        }

        return new int[] {red, green, blue};
    }

    private static int convertToInt(double input) {
        return (int) Math.round(255 * input);
    }
}

package array;

import java.util.Arrays;

public class UcuncuEnBuyukBulucu {

    // Yaklasim 1: onceden siralayip sondan ucuncu elemani okur
    public static int siralayarakBul(int[] degerler) {
        Arrays.sort(degerler);
        return degerler[degerler.length - 3];
    }

    // Yaklasim 2: tek geciste en buyuk uc degeri takip ederek bulur
    public static int tekGecisleBul(int[] degerler) {
        long birinci = Long.MIN_VALUE;
        long ikinci = Long.MIN_VALUE;
        long ucuncu = Long.MIN_VALUE;

        for (int mevcut : degerler) {
            if (mevcut > birinci) {
                ucuncu = ikinci;
                ikinci = birinci;
                birinci = mevcut;
            } else if (mevcut > ikinci) {
                ucuncu = ikinci;
                ikinci = mevcut;
            } else if (mevcut > ucuncu) {
                ucuncu = mevcut;
            }
        }

        return (int) ucuncu;
    }

    public static void main(String[] args) {
        int[] veriler = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        System.out.println(Arrays.toString(veriler));
        int sonuc1 = siralayarakBul(veriler);
        System.out.println("3. buyuk sayi: " + sonuc1);

        System.out.println(Arrays.toString(veriler));
        int sonuc2 = tekGecisleBul(veriler);
        System.out.println("3. buyuk sayi: " + sonuc2);
    }
}

public class Main {
    public static void main(String[] args) {
        // Singleton pattern demonstration:
        // Only ONE instance of Singleton class can ever be created

        Singleton firstInstance = Singleton.getInstance();
        Singleton secondInstance = Singleton.getInstance();
        Singleton thirdInstance = Singleton.getInstance();

        // All three reference variables point to the exact same object in memory
        // This ensures only one instance exists throughout the application

        System.out.println("--- Singleton Pattern Demonstration ---");
        System.out.println("First instance hashcode: " + firstInstance.hashCode());
        System.out.println("Second instance hashcode: " + secondInstance.hashCode());
        System.out.println("Third instance hashcode: " + thirdInstance.hashCode());
        System.out.println("All three references point to the SAME object: " + 
                           (firstInstance == secondInstance && secondInstance == thirdInstance));

        // Accessing a class from another package (com.ankan.access.A)
        A externalClassObject = new A(10, "Sample Name");

        // Demonstrating getter method usage (public access)
        int retrievedValue = externalClassObject.getNumValue();
        System.out.println("\nRetrieved value using getter: " + retrievedValue);

        // Direct field access would cause compilation error if field is protected/private
        // int directAccess = externalClassObject.numValue; // ERROR: Cannot access protected field from different package
    }
}

package com.ankan.generics;

import java.util.ArrayList;
import java.util.function.Consumer;

public class LambdaFunctions {
    public static void main(String[] args) {
        // Lambda expressions provide a concise way to implement functional interfaces
        // They represent anonymous functions (one-line / inline functions)

        ArrayList<Integer> numberList = new ArrayList<>();
        for (int iterationCount = 1; iterationCount <= 5; iterationCount++) {
            numberList.add(iterationCount);
        }

        // Using Consumer functional interface with lambda (commented alternative)
        // numberList.forEach((eachItem) -> System.out.println(eachItem * 2));

        // Consumer takes one argument and returns no result
        Consumer<Integer> multiplyAndPrint = (eachItem) -> System.out.println("Value * 2 = " + eachItem * 2);
        numberList.forEach(multiplyAndPrint);

        // Defining different arithmetic operations using lambda expressions
        Operation additionOperation = (firstNumber, secondNumber) -> firstNumber + secondNumber;
        Operation multiplicationOperation = (firstNumber, secondNumber) -> firstNumber * secondNumber;
        Operation subtractionOperation = (firstNumber, secondNumber) -> firstNumber - secondNumber;

        LambdaFunctions lambdaCalculator = new LambdaFunctions();

        System.out.println("\n--- Arithmetic Operation Results ---");
        System.out.println("Addition (5 + 3): " + lambdaCalculator.performOperation(5, 3, additionOperation));
        System.out.println("Multiplication (5 * 3): " + lambdaCalculator.performOperation(5, 3, multiplicationOperation));
        System.out.println("Subtraction (5 - 3): " + lambdaCalculator.performOperation(5, 3, subtractionOperation));
    }

    private int performOperation(int operandOne, int operandTwo, Operation arithmeticOperation) {
        return arithmeticOperation.execute(operandOne, operandTwo);
    }
}

// Functional interface with a single abstract method
interface Operation {
    int execute(int firstOperand, int secondOperand);
}

package com.thealgorithms.datastructures.hashmap.hashing;

/**
 * A generic HashMap implementation that uses separate chaining with linked lists
 * to handle collisions. The class supports basic operations such as insert, delete,
 * and search, as well as displaying the contents of the hash map.
 *
 * @param <K> the type of keys maintained by this map
 * @param <V> the type of mapped values
 */
@SuppressWarnings("rawtypes")
public class HashMap<K, V> {
    private final int hashSize;
    private final LinkedList<K, V>[] buckets;

    /**
     * Constructs a HashMap with the specified hash size.
     *
     * @param hashSize the number of buckets in the hash map
     */
    @SuppressWarnings("unchecked")
    public HashMap(int hashSize) {
        this.hashSize = hashSize;
        // Safe to suppress warning because we are creating an array of generic type
        this.buckets = new LinkedList[hashSize];
        for (int i = 0; i < hashSize; i++) {
            buckets[i] = new LinkedList<>();
        }
    }

    /**
     * Computes the hash code for the specified key.
     * Null keys are hashed to bucket 0.
     *
     * @param key the key for which the hash code is to be computed
     * @return the hash code corresponding to the key
     */
    private int computeHash(K key) {
        if (key == null) {
            return 0; // Use a special bucket (e.g., bucket 0) for null keys
        }
        int hash = key.hashCode() % hashSize;
        return hash < 0 ? hash + hashSize : hash;
    }

    /**
     * Inserts the specified key-value pair into the hash map.
     * If the key already exists, the value is updated.
     *
     * @param key   the key to be inserted
     * @param value the value to be associated with the key
     */
    public void insert(K key, V value) {
        int hash = computeHash(key);
        buckets[hash].insert(key, value);
    }

    /**
     * Deletes the key-value pair associated with the specified key from the hash map.
     *
     * @param key the key whose key-value pair is to be deleted
     */
    public void delete(K key) {
        int hash = computeHash(key);
        buckets[hash].delete(key);
    }

    /**
     * Searches for the value associated with the specified key in the hash map.
     *
     * @param key the key whose associated value is to be returned
     * @return the value associated with the specified key, or null if the key does not exist
     */
    public V search(K key) {
        int hash = computeHash(key);
        Node<K, V> node = buckets[hash].findKey(key);
        return node != null ? node.getValue() : null;
    }

    /**
     * Displays the contents of the hash map, showing each bucket and its key-value pairs.
     */
    public void display() {
        for (int i = 0; i < hashSize; i++) {
            System.out.printf("Bucket %d: %s%n", i, buckets[i].display());
        }
    }

    /**
     * Clears the contents of the hash map by reinitializing each bucket.
     */
    public void clear() {
        for (int i = 0; i < hashSize; i++) {
            buckets[i] = new LinkedList<>();
        }
    }

    /**
     * Gets the number of key-value pairs in the hash map.
     *
     * @return the number of key-value pairs in the hash map
     */
    public int size() {
        int size = 0;
        for (int i = 0; i < hashSize; i++) {
            size += buckets[i].isEmpty() ? 0 : 1;
        }
        return size;
    }

    /**
     * A nested static class that represents a linked list used for separate chaining in the hash map.
     *
     * @param <K> the type of keys maintained by this linked list
     * @param <V> the type of mapped values
     */
    public static class LinkedList<K, V> {
        private Node<K, V> head;

        /**
         * Inserts the specified key-value pair into the linked list.
         * If the linked list is empty, the pair becomes the head.
         * Otherwise, the pair is added to the end of the list.
         *
         * @param key   the key to be inserted
         * @param value the value to be associated with the key
         */
        public void insert(K key, V value) {
            Node<K, V> existingNode = findKey(key);
            if (existingNode != null) {
                existingNode.setValue(value); // Update the value, even if it's null
            } else {
                if (isEmpty()) {
                    head = new Node<>(key, value);
                } else {
                    Node<K, V> temp = findEnd(head);
                    temp.setNext(new Node<>(key, value));
                }
            }
        }

        /**
         * Finds the last node in the linked list.
         *
         * @param node the starting node
         * @return the last node in the linked list
         */
        private Node<K, V> findEnd(Node<K, V> node) {
            while (node.getNext() != null) {
                node = node.getNext();
            }
            return node;
        }

        /**
         * Finds the node associated with the specified key in the linked list.
         *
         * @param key the key to search for
         * @return the node associated with the specified key, or null if not found
         */
        public Node<K, V> findKey(K key) {
            Node<K, V> temp = head;
            while (temp != null) {
                if ((key == null && temp.getKey() == null) || (temp.getKey() != null && temp.getKey().equals(key))) {
                    return temp;
                }
                temp = temp.getNext();
            }
            return null;
        }

        /**
         * Deletes the node associated with the specified key from the linked list.
         * Handles the case where the key could be null.
         *
         * @param key the key whose associated node is to be deleted
         */
        public void delete(K key) {
            if (isEmpty()) {
                return;
            }

            // Handle the case where the head node has the key to delete
            if ((key == null && head.getKey() == null) || (head.getKey() != null && head.getKey().equals(key))) {
                head = head.getNext();
                return;
            }

            // Traverse the list to find and delete the node
            Node<K, V> current = head;
            while (current.getNext() != null) {
                if ((key == null && current.getNext().getKey() == null) || (current.getNext().getKey() != null && current.getNext().getKey().equals(key))) {
                    current.setNext(current.getNext().getNext());
                    return;
                }
                current = current.getNext();
            }
        }

        /**
         * Displays the contents of the linked list as a string.
         *
         * @return a string representation of the linked list
         */
        public String display() {
            return display(head);
        }

        /**
         * Constructs a string representation of the linked list non-recursively.
         *
         * @param node the starting node
         * @return a string representation of the linked list starting from the given node
         */
        private String display(Node<K, V> node) {
            StringBuilder sb = new StringBuilder();
            while (node != null) {
                sb.append(node.getKey()).append("=").append(node.getValue());
                node = node.getNext();
                if (node != null) {
                    sb.append(" -> ");
                }
            }
            return sb.toString().isEmpty() ? "null" : sb.toString();
        }

        /**
         * Checks if the linked list is empty.
         *
         * @return true if the linked list is empty, false otherwise
         */
        public boolean isEmpty() {
            return head == null;
        }
    }

    /**
     * A nested static class representing a node in the linked list.
     *
     * @param <K> the type of key maintained by this node
     * @param <V> the type of value maintained by this node
     */
    public static class Node<K, V> {
        private final K key;
        private V value;
        private Node<K, V> next;

        /**
         * Constructs a Node with the specified key and value.
         *
         * @param key   the key associated with this node
         * @param value the value associated with this node
         */
        public Node(K key, V value) {
            this.key = key;
            this.value = value;
        }

        /**
         * Gets the key associated with this node.
         *
         * @return the key associated with this node
         */
        public K getKey() {
            return key;
        }

        /**
         * Gets the value associated with this node.
         *
         * @return the value associated with this node
         */
        public V getValue() {
            return value;
        }

        public void setValue(V value) { // This method allows updating the value
            this.value = value;
        }

        /**
         * Gets the next node in the linked list.
         *
         * @return the next node in the linked list
         */
        public Node<K, V> getNext() {
            return next;
        }

        /**
         * Sets the next node in the linked list.
         *
         * @param next the next node to be linked
         */
        public void setNext(Node<K, V> next) {
            this.next = next;
        }
    }
}

package Person;

import java.util.Scanner;

/**
 * Reads workers/officers until choice 0, then prints only workers.
 */
public class TestMain {
    public static void main(String[] args) {
        Person[] people = new Person[10];
        int count = 0;
        int choice;
        do {
            System.out.println("Worker (1); Officer(2): ");
            Scanner in = new Scanner(System.in);
            choice = in.nextInt();
            if (choice == 1) {
                System.out.print("Enter worker name: ");
                String name = in.next();
                System.out.print("Enter worker working hours: ");
                int hrs = in.nextInt();
                people[count] = new Worker(name, hrs);
                count++;
            } else if (choice == 2) {
                System.out.print("Enter Officer name: ");
                String name = in.next();
                System.out.print("Enter officer salary: ");
                double salary = in.nextDouble();
                people[count] = new Officer(name, salary);
                count++;
            }
        } while (choice != 0);
        for (int i = 0; i < count; i++) {
            if (people[i] instanceof Worker) {
                people[i].display();
            }
        }
    }
}

/**
 * Implementation of Hierholzer's Algorithm for finding an Eulerian Path or Circuit
 * in a directed graph.
 *
 * <p>
 * An <b>Eulerian Circuit</b> is a path that starts and ends at the same vertex
 * and visits every edge exactly once.
 * </p>
 *
 * <p>
 * An <b>Eulerian Path</b> visits every edge exactly once but may start and end
 * at different vertices.
 * </p>
 *
 * <p>
 * <b>Algorithm Summary:</b><br>
 * 1. Compute indegree and outdegree for all vertices.<br>
 * 2. Check if the graph satisfies Eulerian path or circuit conditions.<br>
 * 3. Verify that all vertices with non-zero degree are weakly connected (undirected connectivity).<br>
 * 4. Use Hierholzer’s algorithm to build the path by exploring unused edges iteratively.
 * </p>
 *
 * <p>
 * <b>Time Complexity:</b> O(E + V).<br>
 * <b>Space Complexity:</b> O(V + E).
 * </p>
 *
 * @author <a href="https://en.wikipedia.org/wiki/Eulerian_path#Hierholzer's_algorithm">Wikipedia: Hierholzer algorithm</a>
 */
public class HierholzerEulerianPath {

    /**
     * Simple directed graph represented by adjacency lists.
     */
    public static class Graph {
        private final List<List<Integer>> adjacencyList;

        /**
         * Constructs a graph with a given number of vertices.
         *
         * @param numNodes number of vertices
         */
        public Graph(int numNodes) {
            adjacencyList = new ArrayList<>();
            for (int i = 0; i < numNodes; i++) {
                adjacencyList.add(new ArrayList<>());
            }
        }

        /**
         * Adds a directed edge from vertex {@code from} to vertex {@code to}.
         *
         * @param from source vertex
         * @param to   destination vertex
         */
        public void addEdge(int from, int to) {
            adjacencyList.get(from).add(to);
        }

        /**
         * Returns a list of outgoing edges from the given vertex.
         *
         * @param node vertex index
         * @return list of destination vertices
         */
        public List<Integer> getEdges(int node) {
            return adjacencyList.get(node);
        }

        /**
         * Returns the number of vertices in the graph.
         *
         * @return number of vertices
         */
        public int getNumNodes() {
            return adjacencyList.size();
        }
    }

    private final Graph graph;

    /**
     * Creates a Hierholzer solver for the given graph.
     *
     * @param graph directed graph
     */
    public HierholzerEulerianPath(Graph graph) {
        this.graph = graph;
    }

    /**
     * Finds an Eulerian Path or Circuit using Hierholzer’s Algorithm.
     *
     * @return list of vertices representing the Eulerian Path/Circuit,
     *         or an empty list if none exists
     */
    public List<Integer> findEulerianPath() {
        int n = graph.getNumNodes();

        // empty graph -> no path
        if (n == 0) {
            return new ArrayList<>();
        }

        int[] inDegree = new int[n];
        int[] outDegree = new int[n];
        int edgeCount = computeDegrees(inDegree, outDegree);

        // no edges -> single vertex response requested by tests: [0]
        if (edgeCount == 0) {
            return Collections.singletonList(0);
        }

        int startNode = determineStartNode(inDegree, outDegree);
        if (startNode == -1) {
            return new ArrayList<>();
        }

        if (!allNonZeroDegreeVerticesWeaklyConnected(startNode, n, outDegree, inDegree)) {
            return new ArrayList<>();
        }

        List<Integer> path = buildHierholzerPath(startNode, n);
        if (path.size() != edgeCount + 1) {
            return new ArrayList<>();
        }

        return rotateEulerianCircuitIfNeeded(path, outDegree, inDegree);
    }

    private int computeDegrees(int[] inDegree, int[] outDegree) {
        int edgeCount = 0;
        for (int u = 0; u < graph.getNumNodes(); u++) {
            for (int v : graph.getEdges(u)) {
                outDegree[u]++;
                inDegree[v]++;
                edgeCount++;
            }
        }
        return edgeCount;
    }

    private int determineStartNode(int[] inDegree, int[] outDegree) {
        int n = graph.getNumNodes();
        int startNode = -1;
        int startCount = 0;
        int endCount = 0;

        for (int i = 0; i < n; i++) {
            int diff = outDegree[i] - inDegree[i];
            if (diff == 1) {
                startNode = i;
                startCount++;
            } else if (diff == -1) {
                endCount++;
            } else if (Math.abs(diff) > 1) {
                return -1;
            }
        }

        if (!((startCount == 1 && endCount == 1) || (startCount == 0 && endCount == 0))) {
            return -1;
        }

        if (startNode == -1) {
            for (int i = 0; i < n; i++) {
                if (outDegree[i] > 0) {
                    startNode = i;
                    break;
                }
            }
        }
        return startNode;
    }

    private List<Integer> buildHierholzerPath(int startNode, int n) {
        List<Deque<Integer>> tempAdj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            tempAdj.add(new ArrayDeque<>(graph.getEdges(i)));
        }

        Deque<Integer> stack = new ArrayDeque<>();
        List<Integer> path = new ArrayList<>();
        stack.push(startNode);

        while (!stack.isEmpty()) {
            int u = stack.peek();
            if (!tempAdj.get(u).isEmpty()) {
                stack.push(tempAdj.get(u).pollFirst());
            } else {
                path.add(stack.pop());
            }
        }

        Collections.reverse(path);
        return path;
    }

    private List<Integer> rotateEulerianCircuitIfNeeded(List<Integer> path, int[] outDegree, int[] inDegree) {
        int startCount = 0;
        int endCount = 0;
        for (int i = 0; i < outDegree.length; i++) {
            int diff = outDegree[i] - inDegree[i];
            if (diff == 1) {
                startCount++;
            } else if (diff == -1) {
                endCount++;
            }
        }

        if (startCount == 0 && endCount == 0 && !path.isEmpty()) {
            int preferredStart = -1;
            for (int i = 0; i < outDegree.length; i++) {
                if (outDegree[i] > 0) {
                    preferredStart = i;
                    break;
                }
            }

            if (preferredStart != -1 && path.get(0) != preferredStart) {
                int idx = 0;
                for (Integer node : path) { // replaced indexed loop
                    if (node == preferredStart) {
                        break;
                    }
                    idx++;
                }

                if (idx > 0) {
                    List<Integer> rotated = new ArrayList<>();
                    int currentIndex = 0;
                    for (Integer node : path) { // replaced indexed loop
                        if (currentIndex >= idx) {
                            rotated.add(node);
                        }
                        currentIndex++;
                    }
                    currentIndex = 0;
                    for (Integer node : path) { // replaced indexed loop
                        if (currentIndex < idx) {
                            rotated.add(node);
                        }
                        currentIndex++;
                    }
                    path = rotated;
                }
            }
        }
        return path;
    }

    /**
     * Checks weak connectivity (undirected) among vertices that have non-zero degree.
     *
     * @param startNode node to start DFS from (must be a vertex with non-zero degree)
     * @param n number of vertices
     * @param outDegree out-degree array
     * @param inDegree in-degree array
     * @return true if all vertices having non-zero degree belong to a single weak component
     */
    private boolean allNonZeroDegreeVerticesWeaklyConnected(int startNode, int n, int[] outDegree, int[] inDegree) {
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(startNode);
        visited[startNode] = true;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int v : graph.getEdges(u)) {
                if (!visited[v]) {
                    visited[v] = true;
                    stack.push(v);
                }
            }
            for (int x = 0; x < n; x++) {
                if (!visited[x]) {
                    for (int y : graph.getEdges(x)) {
                        if (y == u) {
                            visited[x] = true;
                            stack.push(x);
                            break;
                        }
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (outDegree[i] + inDegree[i] > 0 && !visited[i]) {
                return false;
            }
        }
        return true;
    }
}

public class Grids {
    public static void main(String[] args) {
        int [] [] ia2;
        int [] ia1 = {1, 2, 3};
        Object o = ia1;
        ia2 = new int[3][3];
        ia2 [0] = (int[]) o;
//        ia2 [0][0] = (int[]) o;
        ia2 [0][0] = ((int[]) o)[0];
    }
}

/*
* Here ia2[0] is the 1st row of 1D array in a 2D array which is assigned to the entire array of Object type o which
* is casted into (int[]) o. But in the case ia2[0][0] which defines the first element of the 2D array of int type, it
*  can't be assigned an entire 1D array. So, it gives a compilation error. To access and copy the first element of
* the 1D array we need to again cast to ((int[]) o)[0].
* */

