import java.util.Scanner;

public class ArtanSiraDortSayi {

	public static void main(String[] args) {

		Scanner okuyucu = new Scanner(System.in);

		System.out.print("Birinci sayiyi girin: ");
		int a = okuyucu.nextInt();

		System.out.print("ikinci sayiyi girin: ");
		int b = okuyucu.nextInt();

		System.out.print("ucuncu sayiyi girin: ");
		int c = okuyucu.nextInt();

		System.out.print("Dorduncu sayiyi girin: ");
		int d = okuyucu.nextInt();

		okuyucu.close();

		// Dort degeri diziye koyup dongu ile siraliyoruz (secmeli siralama mantigi)
		int[] degerler = { a, b, c, d };

		for (int i = 0; i < degerler.length; i++) {
			int enKucukIndex = i;
			for (int j = i + 1; j < degerler.length; j++) {
				if (degerler[j] < degerler[enKucukIndex]) {
					enKucukIndex = j;
				}
			}
			if (enKucukIndex != i) {
				int gecici = degerler[i];
				degerler[i] = degerler[enKucukIndex];
				degerler[enKucukIndex] = gecici;
			}
		}

		System.out.println("Artan sirayla: " + degerler[0] + ", " + degerler[1] + ", " + degerler[2] + ", " + degerler[3]);
	}
}

/**
 * The Baconian Cipher is a substitution cipher where each letter is represented
 * by a group of five binary digits (A's and B's). It can also be used to hide
 * messages within other texts, making it a simple form of steganography.
 * https://en.wikipedia.org/wiki/Bacon%27s_cipher
 *
 * @author Bennybebo
 */
public class BaconianCipher {

private static final Map<Character, String> ENCODE_MAP = new HashMap<>();
private static final Map<String, Character> DECODE_MAP = new HashMap<>();

static {
String[] binaryCodes = {"AAAAA", "AAAAB", "AAABA", "AAABB", "AABAA", "AABAB", "AABBA", "AABBB", "ABAAA", "ABAAB", "ABABA", "ABABB", "ABBAA", "ABBAB", "ABBBA", "ABBBB", "BAAAA", "BAAAB", "BAABA", "BAABB", "BABAA", "BABAB", "BABBA", "BABBB", "BBAAA", "BBAAB"};
char currentLetter = 'A';
for (String codeValue : binaryCodes) {
ENCODE_MAP.put(currentLetter, codeValue);
DECODE_MAP.put(codeValue, currentLetter);
currentLetter++;
}
ENCODE_MAP.put('I', ENCODE_MAP.get('J'));
DECODE_MAP.put(ENCODE_MAP.get('I'), 'I');
}

/**
 * Encrypts the given plaintext using the Baconian cipher.
 *
 * @param inputText The plaintext message to encrypt.
 * @return The ciphertext as a binary (A/B) sequence.
 */
public String encrypt(String inputText) {
StringBuilder encodedResult = new StringBuilder();
String cleanText = inputText.toUpperCase().replaceAll("[^A-Z]", "");
for (char letterChar : cleanText.toCharArray()) {
encodedResult.append(ENCODE_MAP.get(letterChar));
}
return encodedResult.toString();
}

/**
 * Decrypts the given ciphertext encoded in binary (A/B) format using the Baconian cipher.
 *
 * @param encodedText The ciphertext to decrypt.
 * @return The decrypted plaintext message.
 */
public String decrypt(String encodedText) {
StringBuilder decodedResult = new StringBuilder();
for (int position = 0; position < encodedText.length(); position += 5) {
String codeSegment = encodedText.substring(position, position + 5);
if (DECODE_MAP.containsKey(codeSegment)) {
decodedResult.append(DECODE_MAP.get(codeSegment));
} else {
throw new IllegalArgumentException("Invalid Baconian code: " + codeSegment);
}
}
return decodedResult.toString();
}
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;

class AdjacencyListGraph<ElementType extends Comparable<ElementType>> {

ArrayList<GraphVertex> vertexList;

AdjacencyListGraph() {
vertexList = new ArrayList<>();
}

private class GraphVertex {
ElementType nodeValue;
ArrayList<GraphVertex> neighborList;

GraphVertex(ElementType nodeValue) {
neighborList = new ArrayList<>();
this.nodeValue = nodeValue;
}

public boolean addNeighbor(GraphVertex targetVertex) {
for (GraphVertex existingNeighbor : neighborList) {
if (existingNeighbor.nodeValue.compareTo(targetVertex.nodeValue) == 0) {
return false;
}
}
return neighborList.add(targetVertex);
}

public boolean removeNeighbor(ElementType neighborValue) {
for (int index = 0; index < neighborList.size(); index++) {
if (neighborList.get(index).nodeValue.compareTo(neighborValue) == 0) {
neighborList.remove(index);
return true;
}
}
return false;
}
}

/**
 * this method removes an edge from the graph between two specified
 * vertices
 *
 * @param startValue the data of the vertex the edge is from
 * @param endValue the data of the vertex the edge is going to
 * @return returns false if the edge doesn't exist, returns true if the edge
 * exists and is removed
 */
public boolean removeEdge(ElementType startValue, ElementType endValue) {
GraphVertex startVertex = null;
for (GraphVertex currentVertex : vertexList) {
if (startValue.compareTo(currentVertex.nodeValue) == 0) {
startVertex = currentVertex;
break;
}
}
if (startVertex == null) {
return false;
}
return startVertex.removeNeighbor(endValue);
}

/**
 * this method adds an edge to the graph between two specified vertices
 *
 * @param startValue the data of the vertex the edge is from
 * @param endValue the data of the vertex the edge is going to
 * @return returns true if the edge did not exist, return false if it
 * already did
 */
public boolean addEdge(ElementType startValue, ElementType endValue) {
GraphVertex startVertex = null;
GraphVertex endVertex = null;
for (GraphVertex currentVertex : vertexList) {
if (startValue.compareTo(currentVertex.nodeValue) == 0) {
startVertex = currentVertex;
} else if (endValue.compareTo(currentVertex.nodeValue) == 0) {
endVertex = currentVertex;
}
if (startVertex != null && endVertex != null) {
break;
}
}
if (startVertex == null) {
startVertex = new GraphVertex(startValue);
vertexList.add(startVertex);
}
if (endVertex == null) {
endVertex = new GraphVertex(endValue);
vertexList.add(endVertex);
}
return startVertex.addNeighbor(endVertex);
}

/**
 * this gives a list of vertices in the graph and their adjacencies
 *
 * @return returns a string describing this graph
 */
@Override
public String toString() {
StringBuilder outputBuilder = new StringBuilder();
for (GraphVertex currentVertex : vertexList) {
outputBuilder.append("Vertex: ");
outputBuilder.append(currentVertex.nodeValue);
outputBuilder.append("\n");
outputBuilder.append("Adjacent vertices: ");
for (GraphVertex neighborVertex : currentVertex.neighborList) {
outputBuilder.append(neighborVertex.nodeValue);
outputBuilder.append(" ");
}
outputBuilder.append("\n");
}
return outputBuilder.toString();
}
}

public final class Graphs {
private Graphs() {
}

public static void main(String[] args) {
AdjacencyListGraph<Integer> sampleGraph = new AdjacencyListGraph<>();
assert sampleGraph.addEdge(1, 2);
assert sampleGraph.addEdge(1, 5);
assert sampleGraph.addEdge(2, 5);
assert !sampleGraph.addEdge(1, 2);
assert sampleGraph.addEdge(2, 3);
assert sampleGraph.addEdge(3, 4);
assert sampleGraph.addEdge(4, 1);
assert !sampleGraph.addEdge(2, 3);
System.out.println(sampleGraph);
}
}

