package com.thealgorithms.conversions;

/**
 * Class for converting an Octal number to its Hexadecimal equivalent.
 *
 * @author Tanmay Joshi
 */
public final class OctalToHexadecimal {
    private static final int OCTAL_BASE = 8;
    private static final int HEX_BASE = 16;
    private static final String HEX_DIGITS = "0123456789ABCDEF";

    private OctalToHexadecimal() {
    }

    /**
     * Converts an Octal number (as a string) to its Decimal equivalent.
     *
     * @param octalNumber The Octal number as a string
     * @return The Decimal equivalent of the Octal number
     * @throws IllegalArgumentException if the input contains invalid octal digits
     */
    public static int octalToDecimal(String octalNumber) {
        if (octalNumber == null || octalNumber.isEmpty()) {
            throw new IllegalArgumentException("Input cannot be null or empty");
        }

        int decimalValue = 0;
        for (int i = 0; i < octalNumber.length(); i++) {
            char currentChar = octalNumber.charAt(i);
            if (currentChar < '0' || currentChar > '7') {
                throw new IllegalArgumentException("Incorrect octal digit: " + currentChar);
            }
            int currentDigit = currentChar - '0';
            decimalValue = decimalValue * OCTAL_BASE + currentDigit;
        }

        return decimalValue;
    }

    /**
     * Converts a Decimal number to its Hexadecimal equivalent.
     *
     * @param decimalNumber The Decimal number
     * @return The Hexadecimal equivalent of the Decimal number
     */
    public static String decimalToHexadecimal(int decimalNumber) {
        if (decimalNumber == 0) {
            return "0";
        }

        StringBuilder hexValue = new StringBuilder();
        while (decimalNumber > 0) {
            int digit = decimalNumber % HEX_BASE;
            hexValue.insert(0, HEX_DIGITS.charAt(digit));
            decimalNumber /= HEX_BASE;
        }

        return hexValue.toString();
    }
}

/*
 * Bu Java kodu, verilen bir sayinin palindrom olup olmadigini kontrol eder:
 * 
 * */

public class PalindromKontrol {

	// Sayinin palindrom olup olmadigini kontrol eden fonksiyon
	public static boolean palindromMu(int sayi) {

		int orijinalSayi = sayi;  // Orijinal sayiyi sakla
		int tersSayi = 0;  // Ters sayiyi ilklendir
		while (sayi > 0) {
			int rakam = sayi % 10;  // Sayinin son rakamini al
			tersSayi = (tersSayi * 10) + rakam;  // Ters sayiyi olustur
			sayi /= 10;  // Sayiyi bir basamak kucult
		}
		// Orijinal sayi ile ters sayiyi karsilastir
		return orijinalSayi == tersSayi;
	}

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		System.out.print("Bir sayi girin: ");
		int sayi = sc.nextInt();
		sc.close();

		// Sayinin palindrom olup olmadigini kontrol et
		if (palindromMu(sayi)) {
			System.out.println(sayi + " bir palindromdur.");
		} else {
			System.out.println(sayi + " bir palindrom degildir.");
		}
	}
}

/**
 * Class for converting an octal number to a decimal number. Octal numbers are based on 8, using digits from 0 to 7.
 *
 */
public final class OctalToDecimal {
private static final int BASE_VALUE = 8;

private OctalToDecimal() {
}

/**
 * Converts a given octal number (as a string) to its decimal representation.
 * If the input is not a valid octal number (i.e., contains characters other than 0-7),
 * the method throws an IllegalArgumentException.
 *
 * @param octalInput The octal number as a string
 * @return The decimal equivalent of the octal number
 * @throws IllegalArgumentException if the input is not a valid octal number
 */
public static int convertOctalToDecimal(String octalInput) {
if (octalInput == null || octalInput.isEmpty()) {
throw new IllegalArgumentException("Input cannot be null or empty");
}
int decimalResult = 0;
for (int position = 0; position < octalInput.length(); position++) {
char currentSymbol = octalInput.charAt(position);
if (currentSymbol < '0' || currentSymbol > '7') {
throw new IllegalArgumentException("Incorrect input: Expecting an octal number (digits 0-7)");
}
int digitValue = currentSymbol - '0';
decimalResult = decimalResult * BASE_VALUE + digitValue;
}
return decimalResult;
}
}

/**
 * A local phone number: area code plus number.
 */
public class PhoneNumber {
    protected int area;
    protected String number;

    public PhoneNumber(int area, String number) {
        this.area = area;
        this.number = number;
    }

    public PhoneNumber() {
    }

    public void display() {
        if (area != 0) {
            System.out.print(area + "-");
        }
        if (!number.isEmpty()) {
            System.out.print(number);
        }
        System.out.println();
    }

    public int getArea() {
        return area;
    }

    public void setArea(int area) {
        this.area = area;
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    @Override
    public String toString() {
        return "PhoneNumber{area=" + area + ", number=" + number + '}';
    }
}

/*
 * Ornek: birden fazla arka plan islemini ayri thread'lerde paralel
 * yurutup, ana thread bir sure kendi isini yaptiktan sonra hepsini
 * kontrollu bicimde durduran ve tamamlanmalarini bekleyen program.
 */

public class ArkaPlanGorevi implements Runnable {

    private final String etiket;
    private volatile boolean aktif = true;

    public ArkaPlanGorevi(String etiket) {
        this.etiket = etiket;
    }

    /** Gorev durdurulana ya da 10 tur tamamlanana kadar ilerleme mesaji basar. */
    @Override
    public void run() {
        int turSayaci = 0;
        while (aktif && turSayaci < 10) {
            System.out.println(etiket + " calisiyor: " + turSayaci);
            try {
                Thread.sleep(400);
            } catch (InterruptedException kesinti) {
                System.out.println(etiket + " kesildi.");
                return;
            }
            turSayaci++;
        }
        System.out.println(etiket + " tamamlandi.");
    }

    /** Calisan gorevi bir sonraki kontrol noktasinda sonlandirmak icin bayragi indirir. */
    public void durdur() {
        aktif = false;
    }

    public static void main(String[] args) throws InterruptedException {
        ArkaPlanGorevi ilkGorev = new ArkaPlanGorevi("Gorev-1");
        ArkaPlanGorevi ikinciGorev = new ArkaPlanGorevi("Gorev-2");
        ArkaPlanGorevi ucuncuGorev = new ArkaPlanGorevi("Gorev-3");

        Thread ilkIsParcacigi = new Thread(ilkGorev, "Thread-1");
        Thread ikinciIsParcacigi = new Thread(ikinciGorev, "Thread-2");
        Thread ucuncuIsParcacigi = new Thread(ucuncuGorev, "Thread-3");

        ilkIsParcacigi.start();
        ikinciIsParcacigi.start();
        ucuncuIsParcacigi.start();

        anaThreadMesguletmesi();

        beklemeSuresiTanimla(5000);

        System.out.println("Tum gorevler durduruluyor...");
        ilkGorev.durdur();
        ikinciGorev.durdur();
        ucuncuGorev.durdur();

        ilkIsParcacigi.join();
        ikinciIsParcacigi.join();
        ucuncuIsParcacigi.join();

        System.out.println("Tum isler tamamlandi. Program sonlandi.");
    }

    private static void anaThreadMesguletmesi() {
        for (int i = 0; i < 5; i++) {
            System.out.println("Ana thread is yapiyor: " + i);
            beklemeSuresiTanimla(500);
        }
    }

    private static void beklemeSuresiTanimla(long milisaniye) {
        try {
            Thread.sleep(milisaniye);
        } catch (InterruptedException kesinti) {
            kesinti.printStackTrace();
        }
    }
}

package chat; 
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.IOException;
import java.io.PrintWriter;
import java.net.Socket;
import java.util.Scanner;

import java.awt.BorderLayout;
import javax.swing.JFrame;
import javax.swing.JOptionPane;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.WindowConstants;

public class ChatClient {

    String serverAddress; // Sunucu adresi
    Scanner in; // Girdi akisi
    PrintWriter out; // Cikti akisi
    JFrame frame = new JFrame("Chatter"); // Chat penceresi
    JTextField textField = new JTextField(50); // Mesaj girmek icin alan
    JTextArea messageArea = new JTextArea(16, 50); // Mesajlari gosteren alan

    // Constructor: ChatClient nesnesi olusturur
    public ChatClient(String serverAddress) {
        this.serverAddress = serverAddress;

        textField.setEditable(false); // Mesaj girmek baslangicta kapali
        messageArea.setEditable(false); // Mesajlari gormek icin alani degistirilemez
        frame.getContentPane().add(textField, BorderLayout.SOUTH); // Mesaj girme alanini ekler
        frame.getContentPane().add(new JScrollPane(messageArea), BorderLayout.CENTER); // Mesajlari gosterme alanini ekler
        frame.pack();

        // Enter tusuna basildiginda mesaj gonderir, sonra textField'i temizler
        textField.addActionListener(new ActionListener() {
            public void actionPerformed(ActionEvent e) {
                out.println(textField.getText()); // Mesaji server'a gonder
                textField.setText(""); // Girdiyi temizle
            }
        });
    }

    // Kullaniciya ekran ismi secmesi icin dialog penceresi gosterir
    private String getName() {
        return JOptionPane.showInputDialog(frame, "Choose a screen name:", "Screen name selection",
                JOptionPane.PLAIN_MESSAGE);
    }

    // Chat client'ini baslatan ana metod
    private void run() throws IOException {
        try (var socket = new Socket(serverAddress, 59001)) { // Sunucuya baglanir
            in = new Scanner(socket.getInputStream()); // Sunucudan veri alir
            out = new PrintWriter(socket.getOutputStream(), true); // Sunucuya veri gonderir

            // Sunucudan gelen her satir icin islemleri yapar
            while (in.hasNextLine()) {
                var line = in.nextLine(); // Gelen satiri al
                if (line.startsWith("SUBMITNAME")) { // Ekran ismi istegini alir
                    out.println(getName()); // Kullaniciya ekran ismini sorar
                } else if (line.startsWith("NAMEACCEPTED")) { // Isim kabul edildiginde
                    this.frame.setTitle("Chatter - " + line.substring(13)); // Frame basligini gunceller
                    textField.setEditable(true); // Mesaj girmeye izin verir
                } else if (line.startsWith("MESSAGE")) { // Mesaj geldiyse
                    messageArea.append(line.substring(8) + "\n"); // Mesaji ekler
                }
            }
        } finally {
            frame.setVisible(false); // Frame'i gizler
            frame.dispose(); // Frame'i kapatir
        }
    }

    // Programi baslatan main metod
    public static void main(String[] args) throws Exception {

        var client = new ChatClient("localhost"); // Client'i olustur
        client.frame.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE); // Cikis yapildiginda programi kapat
        client.frame.setVisible(true); // Frame'i gorunur hale getir
        client.run(); // Chat client'ini calistir
    }
}

package com.ankan.staticExample;

// Static import demonstration - importing a static method directly
// Allows calling the method without class name prefix
import static com.ankan.packages.b.Greeting.displayPersonalGreeting;

// Car class - represents a vehicle with basic properties
class Car {
    String brandName;      // Car manufacturer (e.g., Toyota, BMW)
    String exteriorColor;  // Car's color
    int currentSpeed;      // Speed in km/h

    // Constructor - initializes a new Car object
    public Car(String brand, String color, int speed) {
        this.brandName = brand;
        this.exteriorColor = color;
        this.currentSpeed = speed;
    }

    // Instance method - makes the car drive
    void startDriving() {
        System.out.println(brandName + " is currently driving at " + currentSpeed + " km/hr");
    }

    // Instance method - stops the car
    void applyBrakeToStop() {
        System.out.println(brandName + " has come to a complete stop");
    }
}

public class Main {
    public static void main(String[] args) {
        // Creating Human objects (from Human class in same package)
        Human firstPerson = new Human(22, "First Person", 100000, false);
        Human secondPerson = new Human(21, "Second Person", 200000, false);
        Human thirdPerson = new Human(25, "Third Person", 50000, true);

        // Accessing static variable - using class name (recommended practice)
        // System.out.println(firstPerson.totalPopulationCount); // Works but NOT recommended
        System.out.println("Total human population: " + Human.totalPopulationCount);

        // Calling static method from another package using static import
        // Original: Greeting.displayPersonalGreeting("Ankan");
        displayPersonalGreeting("Sample Name");  // Static import allows direct call

        // Creating Car objects
        Car firstCar = new Car("Toyota", "blue", 85);
        Car secondCar = new Car("Bentley", "silver-white", 120);

        // Demonstrating Car behavior
        System.out.println("\n--- Car Demonstration ---");
        firstCar.startDriving();
        secondCar.startDriving();
        firstCar.applyBrakeToStop();
        secondCar.applyBrakeToStop();
    }

    // Static method - belongs to the class itself, not to any instance
    // Can be called without creating an object of Main
    static void displayStaticMessage() {
        // To call non-static method from static context, we need an instance
        Main mainInstance = new Main();
        mainInstance.displayNonStaticGreeting();
        System.out.println("Static method executing properly!");
    }

    // Non-static (instance) method - belongs to objects of Main
    // Can access both static and non-static members
    void displayNonStaticGreeting() {
        displayStaticMessage();  // Static methods can be called from non-static context
        System.out.println("Non-static greeting message - Hello from instance method!");
    }
}

/*
Important Static vs Non-Static Concepts:
========================================

1. Static Variables (Class Variables):
   - Shared across ALL instances of a class
   - Accessed using ClassName.variableName (recommended)
   - Memory allocated only once at class loading time

2. Instance Variables:
   - Each object has its own copy
   - Accessed using objectReference.variableName

3. Static Methods:
   - Can be called without creating an object
   - Cannot directly access instance variables/methods
   - Can only call other static methods directly
   - To access instance members, need an object reference

4. Instance Methods:
   - Require an object to be called
   - Can access both instance AND static members directly
   - Have access to 'this' keyword

5. Static Import:
   - Allows importing static members (methods/variables) directly
   - Use: import static package.Class.staticMember;
   - After import, can call without class name prefix

Why can't a static method call a non-static method directly?
-----------------------------------------------------------
- Static methods exist at class level (no 'this' reference)
- Non-static methods require an object instance ('this' is available)
- Without an object, the non-static method doesn't know which instance to use
- Solution: Create an object instance first, then call the non-static method
*/

public class Main {
    public static void main(String[] args) {
        List<Integer> arrayListCollection = new ArrayList<>();
        List<Integer> linkedListCollection = new LinkedList<>();

        linkedListCollection.add(34);
        linkedListCollection.add(78);
        linkedListCollection.add(55);
        linkedListCollection.add(89);

        System.out.println(linkedListCollection);

        List<Integer> vectorCollection = new Vector<>();
        vectorCollection.add(45);
        vectorCollection.add(5);
        vectorCollection.add(15);
        vectorCollection.add(56);
        vectorCollection.add(12);

        System.out.println(vectorCollection);

    }
}

/**
 * A utility class to convert between different temperature units.
 *
 * <p>This class supports conversions between the following units:
 * <ul>
 *   <li>Celsius</li>
 *   <li>Fahrenheit</li>
 *   <li>Kelvin</li>
 * </ul>
 *
 * <p>This class is final and cannot be instantiated.
 *
 * @author krishna-medapati (https://github.com/krishna-medapati)
 * @see <a href="https://en.wikipedia.org/wiki/Conversion_of_scales_of_temperature">Wikipedia: Temperature Conversion</a>
 */
public final class TemperatureConverter {

    private TemperatureConverter() {
    }

    public static double celsiusToFahrenheit(double celsius) {
        return celsius * 9.0 / 5.0 + 32.0;
    }

    public static double celsiusToKelvin(double celsius) {
        return celsius + 273.15;
    }

    public static double fahrenheitToCelsius(double fahrenheit) {
        return (fahrenheit - 32.0) * 5.0 / 9.0;
    }

    public static double fahrenheitToKelvin(double fahrenheit) {
        return (fahrenheit - 32.0) * 5.0 / 9.0 + 273.15;
    }

    public static double kelvinToCelsius(double kelvin) {
        return kelvin - 273.15;
    }

    public static double kelvinToFahrenheit(double kelvin) {
        return (kelvin - 273.15) * 9.0 / 5.0 + 32.0;
    }
}

/**
 * Algorithm explanation
 * https://www.educative.io/edpresso/longest-palindromic-subsequence-algorithm
 */
public final class LongestPalindromicSubsequence {
    private LongestPalindromicSubsequence() {
    }

    public static void main(String[] args) {
        String a = "BBABCBCAB";
        String b = "BABCBAB";

        String aLPS = lps(a);
        String bLPS = lps(b);

        System.out.println(a + " => " + aLPS);
        System.out.println(b + " => " + bLPS);
    }

    public static String lps(String original) throws IllegalArgumentException {
        StringBuilder reverse = new StringBuilder(original);
        reverse = reverse.reverse();
        return recursiveLPS(original, reverse.toString());
    }

    private static String recursiveLPS(String original, String reverse) {
        String bestResult = "";

        // no more chars, then return empty
        if (original.length() == 0 || reverse.length() == 0) {
            bestResult = "";
        } else {
            // if the last chars match, then remove it from both strings and recur
            if (original.charAt(original.length() - 1) == reverse.charAt(reverse.length() - 1)) {
                String bestSubResult = recursiveLPS(original.substring(0, original.length() - 1), reverse.substring(0, reverse.length() - 1));

                bestResult = reverse.charAt(reverse.length() - 1) + bestSubResult;
            } else {
                // otherwise (1) ignore the last character of reverse, and recur on original and
                // updated reverse again (2) ignore the last character of original and recur on the
                // updated original and reverse again then select the best result from these two
                // subproblems.

                String bestSubResult1 = recursiveLPS(original, reverse.substring(0, reverse.length() - 1));
                String bestSubResult2 = recursiveLPS(original.substring(0, original.length() - 1), reverse);
                if (bestSubResult1.length() > bestSubResult2.length()) {
                    bestResult = bestSubResult1;
                } else {
                    bestResult = bestSubResult2;
                }
            }
        }

        return bestResult;
    }
}

