package unchecked;

public class HataFirlatma {

    public static void main(String[] args) {

        try {
            divide(10, 0);
        } catch (ArithmeticException ex) {
            System.out.println("Hata: Sifira bolme islemi yapilamaz!");
            System.out.println("Hata mesaji: " + ex.getMessage());
        }

        try {
            divide(20, 5);  // ordinary division
            divide(15, -3); // division with a negative divisor
        } catch (ArithmeticException ex) {
            System.out.println("Hata olustu: " + ex.getMessage());
        }

        System.out.println("Toplama islemi: " + add(10, 5));
    }

    /**
     * Divides x by y, throwing if y is zero.
     * @param x dividend
     * @param y divisor
     * @throws ArithmeticException when y is zero
     */
    public static void divide(int x, int y) throws ArithmeticException {
        if (y == 0) {
            throw new ArithmeticException("Sifira bolme hatasi!");
        }
        int result = x / y;
        System.out.println("Bolme Islemi: " + result);
    }

    /**
     * Adds two integers.
     * @param a first operand
     * @param b second operand
     * @return sum of a and b
     */
    public static int add(int a, int b) {
        return a + b;
    }
}

