private static final int[][][] ALL_S_BOXES = {S1_BOX, S2_BOX, S3_BOX, S4_BOX, S5_BOX, S6_BOX, S7_BOX, S8_BOX};

static final int[] PERMUTATION_TABLE = {16, 7, 20, 21, 29, 12, 28, 17, 1, 15, 23, 26, 5, 18, 31, 10, 2, 8, 24, 14, 32, 27, 3, 9, 19, 13, 30, 6, 22, 11, 4, 25};

static final int[] IP_INVERSE_TABLE = {40, 8, 48, 16, 56, 24, 64, 32, 39, 7, 47, 15, 55, 23, 63, 31, 38, 6, 46, 14, 54, 22, 62, 30, 37, 5, 45, 13, 53, 21, 61, 29, 36, 4, 44, 12, 52, 20, 60, 28, 35, 3, 43, 11, 51, 19, 59, 27, 34, 2, 42, 10, 50, 18, 58, 26, 33, 1, 41, 9, 49, 17, 57, 25};

private String[] generateSubKeys(String originalKeyData) {
StringBuilder permutedKey = new StringBuilder();
for (int position = 0; position < 56; position++) {
permutedKey.append(originalKeyData.charAt(PC1_TABLE[position] - 1));
}
String[] subKeyArray = new String[16];
String currentKey = permutedKey.toString();
String leftHalf = currentKey.substring(0, 28);
String rightHalf = currentKey.substring(28);
for (int round = 0; round < 16; round++) {
leftHalf = leftHalf.substring(KEY_SHIFT_AMOUNTS[round]) + leftHalf.substring(0, KEY_SHIFT_AMOUNTS[round]);
rightHalf = rightHalf.substring(KEY_SHIFT_AMOUNTS[round]) + rightHalf.substring(0, KEY_SHIFT_AMOUNTS[round]);
subKeyArray[round] = leftHalf + rightHalf;
}
for (int round = 0; round < 16; round++) {
StringBuilder compressedKey = new StringBuilder();
String roundKey = subKeyArray[round];
for (int index = 0; index < 48; index++) {
compressedKey.append(roundKey.charAt(PC2_TABLE[index] - 1));
}
subKeyArray[round] = compressedKey.toString();
}
return subKeyArray;
}

private String xorBits(String firstValue, String secondValue) {
StringBuilder xorResult = new StringBuilder();
for (int position = 0; position < firstValue.length(); position++) {
int bitA = firstValue.charAt(position) - 48;
int bitB = secondValue.charAt(position) - 48;
xorResult.append((bitA ^ bitB));
}
return xorResult.toString();
}

private String padLeft(String sourceText, int targetLength) {
return "0".repeat(targetLength - sourceText.length()) + sourceText;
}

private String padRight(String sourceText, int targetLength) {
return sourceText + "\0".repeat(targetLength - sourceText.length());
}

private String applyFeistel(String blockData, String roundKey) {
StringBuilder expandedBlock = new StringBuilder();
for (int position = 0; position < 48; position++) {
expandedBlock.append(blockData.charAt(EXPANSION_TABLE[position] - 1));
}
String mixedData = xorBits(expandedBlock.toString(), roundKey);
StringBuilder substitutedData = new StringBuilder();
for (int segment = 0; segment < 48; segment += 6) {
String sixBitSegment = mixedData.substring(segment, segment + 6);
int rowValue = (sixBitSegment.charAt(0) - 48) * 2 + (sixBitSegment.charAt(5) - 48);
int colValue = (sixBitSegment.charAt(1) - 48) * 8 + (sixBitSegment.charAt(2) - 48) * 4 + (sixBitSegment.charAt(3) - 48) * 2 + (sixBitSegment.charAt(4) - 48);
String substitutedSegment = padLeft(Integer.toBinaryString(ALL_S_BOXES[segment / 6][rowValue][colValue]), 4);
substitutedData.append(substitutedSegment);
}
StringBuilder permutedData = new StringBuilder();
for (int position = 0; position < 32; position++) {
permutedData.append(substitutedData.charAt(PERMUTATION_TABLE[position] - 1));
}
return permutedData.toString();
}

private String processBlock(String inputBlock, String[] keySchedule) {
StringBuilder permutedBlock = new StringBuilder();
for (int position = 0; position < 64; position++) {
permutedBlock.append(inputBlock.charAt(IP_TABLE[position] - 1));
}
String leftPart = permutedBlock.substring(0, 32);
String rightPart = permutedBlock.substring(32);
for (int round = 0; round < 16; round++) {
String nextLeft = rightPart;
String nextRight = xorBits(leftPart, applyFeistel(rightPart, keySchedule[round]));
leftPart = nextLeft;
rightPart = nextRight;
}
String combinedBlock = rightPart + leftPart;
permutedBlock.setLength(0);
for (int position = 0; position < 64; position++) {
permutedBlock.append(combinedBlock.charAt(IP_INVERSE_TABLE[position] - 1));
}
return permutedBlock.toString();
}

private String decodeBlock(String inputBlock, String[] keySchedule) {
String[] reversedKeys = new String[keySchedule.length];
for (int index = 0; index < keySchedule.length; index++) {
reversedKeys[index] = keySchedule[keySchedule.length - index - 1];
}
return processBlock(inputBlock, reversedKeys);
}

/**
 * @param message Message to be encrypted
 * @return The encrypted message, as a binary string
 */
public String encrypt(String sourceMessage) {
StringBuilder encryptedOutput = new StringBuilder();
int messageLength = sourceMessage.length();
if (messageLength % 8 != 0) {
int targetLength = (messageLength / 8 + 1) * 8;
sourceMessage = padRight(sourceMessage, targetLength);
messageLength = targetLength;
}
for (int blockStart = 0; blockStart < messageLength; blockStart += 8) {
String textSegment = sourceMessage.substring(blockStart, blockStart + 8);
StringBuilder binarySegment = new StringBuilder();
byte[] byteData = textSegment.getBytes();
for (int bytePos = 0; bytePos < 8; bytePos++) {
binarySegment.append(padLeft(Integer.toBinaryString(byteData[bytePos] & 0xFF), 8));
}
encryptedOutput.append(processBlock(binarySegment.toString(), roundSubKeys));
}
return encryptedOutput.toString();
}

/**
 * @param message The encrypted string. Expects it to be a multiple of 64 bits, in binary format
 * @return The decrypted String, in plain English
 */
public String decrypt(String encryptedData) {
StringBuilder decryptedOutput = new StringBuilder();
int dataLength = encryptedData.length();
if (dataLength % 64 != 0) {
throw new IllegalArgumentException("Encrypted message should be a multiple of 64 characters in length");
}
for (int blockStart = 0; blockStart < dataLength; blockStart += 64) {
String blockSegment = encryptedData.substring(blockStart, blockStart + 64);
String decodedSegment = decodeBlock(blockSegment, roundSubKeys);
byte[] byteBuffer = new byte[8];
for (int bytePos = 0; bytePos < 64; bytePos += 8) {
byteBuffer[bytePos / 8] = (byte) Integer.parseInt(decodedSegment.substring(bytePos, bytePos + 8), 2);
}
decryptedOutput.append(new String(byteBuffer));
}
return decryptedOutput.toString().replace("\0", "");
}
}

/**
 * Find the number of subsets present in the given array with a sum equal to target.
 * Based on Solution discussed on
 * <a href="https://stackoverflow.com/questions/22891076/count-number-of-subsets-with-sum-equal-to-k">StackOverflow</a>
 * @author <a href="https://github.com/samratpodder">Samrat Podder</a>
 */
public final class SubsetCount {
    private SubsetCount() {
    }

    /**
     * Dynamic Programming Implementation.
     * Method to find out the number of subsets present in the given array with a sum equal to
     * target. Time Complexity is O(n*target) and Space Complexity is O(n*target)
     * @param arr is the input array on which subsets are  to searched
     * @param target is the sum of each element of the subset taken together
     *
     */
    public static int getCount(int[] arr, int target) {
        /*
         * Base Cases - If target becomes zero, we have reached the required sum for the subset
         * If we reach the end of the array arr then, either if target==arr[end], then we add one to
         * the final count Otherwise we add 0 to the final count
         */
        int n = arr.length;
        int[][] dp = new int[n][target + 1];
        for (int i = 0; i < n; i++) {
            dp[i][0] = 1;
        }
        if (arr[0] <= target) {
            dp[0][arr[0]] = 1;
        }
        for (int t = 1; t <= target; t++) {
            for (int idx = 1; idx < n; idx++) {
                int notpick = dp[idx - 1][t];
                int pick = 0;
                if (arr[idx] <= t) {
                    pick += dp[idx - 1][target - t];
                }
                dp[idx][target] = pick + notpick;
            }
        }
        return dp[n - 1][target];
    }

    /**
     * This Method is a Space Optimized version of the getCount(int[], int) method and solves the
     * same problem This approach is a bit better in terms of Space Used Time Complexity is
     * O(n*target) and Space Complexity is O(target)
     * @param arr is the input array on which subsets are  to searched
     * @param target is the sum of each element of the subset taken together
     */
    public static int getCountSO(int[] arr, int target) {
        int n = arr.length;
        int[] prev = new int[target + 1];
        prev[0] = 1;
        if (arr[0] <= target) {
            prev[arr[0]] = 1;
        }
        for (int ind = 1; ind < n; ind++) {
            int[] cur = new int[target + 1];
            cur[0] = 1;
            for (int t = 1; t <= target; t++) {
                int notTaken = prev[t];
                int taken = 0;
                if (arr[ind] <= t) {
                    taken = prev[t - arr[ind]];
                }
                cur[t] = notTaken + taken;
            }
            prev = cur;
        }
        return prev[target];
    }
}

package forloop;

public class ContinueOrnegi {

    // Tek ve cift sayilari ayiran ornek
    public static void tekVeCiftSayilar() {
        System.out.println("Tek ve Cift Sayilar Ornegi:");
        for (int i = 1; i <= 10; i++) {
            if (i % 2 == 0) { // Cift sayilar kontrol edilir
                System.out.println("Cift sayi: " + i);
                continue; // Cift sayilar icin kalan kod atlanir
            }
            System.out.println("Tek sayi: " + i);
        }
    }

    // 3 ve 5'in katlarini atlayan ornek
    public static void ucVeBesKatlari() {
        System.out.println("\n3 ve 5'in Katlarini Atlayan Ornek:");
        for (int i = 1; i <= 15; i++) {
            if (i % 3 == 0 || i % 5 == 0) { // 3 veya 5'in kati kontrol edilir
                System.out.println("Atlanan sayi: " + i);
                continue; // 3 veya 5'in katlari icin kalan kod atlanir
            }
            System.out.println("Gecerli sayi: " + i);
        }
    }

    // Ic ice dongulerde continue kullanimi
    public static void icIceDonguler() {
        System.out.println("\nIc Ice Dongulerde Continue Ornegi:");
        for (int i = 1; i <= 3; i++) {
            for (int j = 1; j <= 3; j++) {
                if (i == j) { // i ve j esit oldugunda atlanir
                    System.out.println("i: " + i + ", j: " + j + " -> Continue uygulandi");
                    continue; // Bu sart saglandiginda ic dongu bir sonraki iterasyona gecer
                }
                System.out.println("i: " + i + ", j: " + j);
            }
        }
    }

    public static void main(String[] args) {
        // Tek ve cift sayilarin ayristirildigi ornek
        tekVeCiftSayilar();

        // 3 ve 5'in katlarini atlayan ornek
        ucVeBesKatlari();

        // Ic ice dongulerde continue kullanimi
        icIceDonguler();
    }
}

public class TankSavarOyunu extends JPanel implements ActionListener {

    private static final long serialVersionUID = 1L;
    private static final int PANEL_WIDTH = 800;
    private static final int PANEL_HEIGHT = 600;

    // Tanklar ve top listeleri
    private ArrayList<Tank> tanklar;
    private ArrayList<Top> toplar;
    private Tanksavar tanksavar;  // Sadece 1 tane tanksavar

    // Oyun durumu
    private boolean sol = false, sag = false;
    private boolean atesEt = false;  // Ates etme durumu

    // Rastgele sayi ureteci
    private Random rastgele;

    // Skor
    private int score;

    public TankSavarOyunu() {
        setPreferredSize(new Dimension(PANEL_WIDTH, PANEL_HEIGHT));
        setBackground(Color.GRAY);
        tanklar = new ArrayList<>();
        toplar = new ArrayList<>();
        rastgele = new Random();
        score = 0;  // Skor baslangicta 0

        // Zamanlayici (Oyunun surekli guncellenmesi icin)
        Timer zamanlayici = new Timer(1000 / 60, this);  // 60 FPS
        zamanlayici.start();

        // Her saniye yeni tank uretecek zamanlayici
        Timer tankZamanlayici = new Timer(1000, new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                int x = rastgele.nextInt(PANEL_WIDTH - 50); // Tanklarin x pozisyonu
                int y = 0; // Tanklarin y pozisyonu en ustte olacak sekilde 0
                int tankType = rastgele.nextInt(2);  // Rastgele tank turu sec (0: T-90MS, 1: Leopard 2A4)
                if (tankType == 0) {
                    tanklar.add(new TankT90MS(x, y));  // T-90MS tanki
                } else {
                    tanklar.add(new TankLeopard2A4(x, y));  // Leopard 2A4 tanki
                }
            }
        });
        tankZamanlayici.start();

        // Oyun basinda yalnizca 1 tane tanksavar olusturulur
        int x = rastgele.nextInt(PANEL_WIDTH - 50); // Tanksavarin yerlestirilecegi x pozisyonu
        int y = PANEL_HEIGHT - 60;  // Tanksavari ekranin alt kismina yerlestir

        tanksavar = new TanksavarJawelin(x, y);  // Jawelin tanksavari

        // Klavye girdileri icin dinleyici
        addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                int key = e.getKeyCode();
                if (key == KeyEvent.VK_LEFT) {
                    sol = true;
                } else if (key == KeyEvent.VK_RIGHT) {
                    sag = true;
                } else if (key == KeyEvent.VK_SPACE && !atesEt) {
                    atesEt = true;  // Space tusuna basildiginda ates etme islemi baslar
                }
            }

            @Override
            public void keyReleased(KeyEvent e) {
                int key = e.getKeyCode();
                if (key == KeyEvent.VK_LEFT) {
                    sol = false;
                } else if (key == KeyEvent.VK_RIGHT) {
                    sag = false;
                } else if (key == KeyEvent.VK_SPACE) {
                    atesEt = false;  // Space tusu birakildiginda ates etme islemi biter
                }
            }
        });
        setFocusable(true);
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        // Tanksavarin hareketi
        if (sol) {
            tanksavar.x -= 5;  // Sol tusuna basildiginda sola hareket et
        }
        if (sag) {
            tanksavar.x += 5;  // Sag tusuna basildiginda saga hareket et
        }

        // Tanklarin hareketi
        for (Tank tank : tanklar) {
            tank.tankKonum.y += tank.hiz;  // Tanklari hizlarina gore asagiya hareket ettir
        }

        // Toplarin hareketi
        ArrayList<Top> toplarSilinecek = new ArrayList<>();
        for (Top top : toplar) {
            top.topKonum.y -= 10;  // Topu yukariya hareket ettir
            if (top.topKonum.y < 0) {
                toplarSilinecek.add(top);  // Top ekranin disina cikarsa sil
            }
        }
        toplar.removeAll(toplarSilinecek);

        // Ates etme islemi (space tusuna basildiginda top eklenir)
        if (atesEt) {
            // Tanksavara uygun topu ekle
            toplar.add(tanksavar.topAt());
            atesEt = false;  // Ates ettikten sonra ates etme durumu sifirlanir
        }

        // Carpisma kontrolu: Toplar tanklarla carpisiyor mu?
        ArrayList<Tank> tanklarSilinecek = new ArrayList<>();

        for (Top top : toplar) {
            for (Tank tank : tanklar) {
                if (top.topKonum.intersects(tank.tankKonum)) {  // Carpisma tespiti
                    tanklarSilinecek.add(tank);  // Carpisan tanki silmek icin isaretle
                    toplarSilinecek.add(top);  // Carpisan topu silmek icin isaretle
                    score++;  // Skoru bir arttir
                }
            }
        }

        if(score % 10 == 0) {
        	if(tanksavar instanceof TanksavarJawelin) {
        		tanksavar = new TanksavarTow2A(tanksavar.x, tanksavar.y);  // Tow2A tanksavari
        	} else if(tanksavar instanceof TanksavarTow2A){
        		tanksavar = new TanksavarJawelin(tanksavar.x, tanksavar.y);  // Jawelin tanksavari
        	}
        	score++;
        }

        // Carpisan tanklari ve toplari listeden sil
        tanklar.removeAll(tanklarSilinecek);
        toplar.removeAll(toplarSilinecek);

        // Paneli yeniden ciz
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);

        // Tanklari ciz
        for (Tank tank : tanklar) {
            g.setColor(tank.renk);
            g.fillRect(tank.tankKonum.x, tank.tankKonum.y, tank.tankKonum.width, tank.tankKonum.height);
        }

        // Tanksavari ciz
        g.setColor(tanksavar.renk);
        g.fillRect(tanksavar.x, tanksavar.y, tanksavar.genislik, tanksavar.yukseklik);

        // Toplari ciz
        for (Top top : toplar) {
            g.setColor(top.renk);  // Toplarin kendine ait rengini kullan
            g.fillRect(top.topKonum.x, top.topKonum.y, top.topKonum.width, top.topKonum.height);
        }

        // Skoru ekranda goster
        g.setColor(Color.WHITE);
        g.setFont(new Font("Arial", Font.BOLD, 20));
        g.drawString("Skor: " + score, 10, 20);
    }

    public static void main(String[] args) {
        JFrame frame = new JFrame("Tank Savar Oyunu");
        TankSavarOyunu oyun = new TankSavarOyunu();
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.add(oyun);
        frame.pack();
        frame.setVisible(true);
    }
}

/**
 * Given a string containing just the characters '(' and ')', find the length of
 * the longest valid (well-formed) parentheses substring.
 *
 * @author Libin Yang (https://github.com/yanglbme)
 * @since 2018/10/5
 */
public final class LongestValidParentheses {
    private LongestValidParentheses() {
    }

    public static int getLongestValidParentheses(String s) {
        if (s == null || s.length() < 2) {
            return 0;
        }
        char[] chars = s.toCharArray();
        int n = chars.length;
        int[] res = new int[n];
        res[0] = 0;
        res[1] = chars[1] == ')' && chars[0] == '(' ? 2 : 0;

        int max = res[1];

        for (int i = 2; i < n; ++i) {
            if (chars[i] == ')') {
                if (chars[i - 1] == '(') {
                    res[i] = res[i - 2] + 2;
                } else {
                    int index = i - res[i - 1] - 1;
                    if (index >= 0 && chars[index] == '(') {
                        // ()(())
                        res[i] = res[i - 1] + 2 + (index - 1 >= 0 ? res[index - 1] : 0);
                    }
                }
            }
            max = Math.max(max, res[i]);
        }

        return max;
    }
}

package datatypes;

public class LongVeriTuruOrnegi {

    public static void main(String[] args) {

        // long, short ve int veri turlerini kullanarak degiskenler tanimla
        long uzunSayi = 2147483648L; // long veri turu "L" ile belirtilir
        short kisaSayi = 32000;
        int tamSayi = 2147483647;

        // Degerleri yazdir
        System.out.println("Uzun Sayi: " + uzunSayi);
        System.out.println("Kisa Sayi: " + kisaSayi);
        System.out.println("Tam Sayi: " + tamSayi);

        // short ve int veri turlerini topla
        // Sonuc otomatik olarak int turune donusecektir
        int toplam = kisaSayi + tamSayi;
        System.out.println("Toplam: " + toplam);

        // long turunden int turune ve int turunden short turune acik donusum yapilabilir (casting)
        long uzunSayi2 = 50000;
        int tamSayi2 = (int) uzunSayi2; // long'dan int'e donusum (casting)
        short kisaSayi2 = (short) tamSayi2; // int'ten short'a donusum (casting)

        System.out.println("Uzun Sayi 2: " + uzunSayi2);
        System.out.println("Tam Sayi 2: " + tamSayi2);
        System.out.println("Kisa Sayi 2: " + kisaSayi2);

        // Maksimum ve minimum degerler
        System.out.println("Long veri turunun maksimum degeri: " + Long.MAX_VALUE);
        System.out.println("Long veri turunun minimum degeri: " + Long.MIN_VALUE);
        System.out.println("Short veri turunun maksimum degeri: " + Short.MAX_VALUE);
        System.out.println("Short veri turunun minimum degeri: " + Short.MIN_VALUE);
        System.out.println("Int veri turunun maksimum degeri: " + Integer.MAX_VALUE);
        System.out.println("Int veri turunun minimum degeri: " + Integer.MIN_VALUE);

        // Long veri turu ile aritmetik islemler
        long fark = uzunSayi - uzunSayi2;
        long carpim = uzunSayi * uzunSayi2;
        long bolum = uzunSayi / uzunSayi2; // Tam sayi bolmesi
        long kalan = uzunSayi % uzunSayi2; // Modulus islemi

        // Aritmetik islemler sonuclarini yazdir
        System.out.println("Long'tan Long'a Fark: " + fark);
        System.out.println("Long'tan Long'a Carpim: " + carpim);
        System.out.println("Long'tan Long'a Bolum: " + bolum);
        System.out.println("Long'tan Long'a Kalan: " + kalan);
    }
}

import java.util.Scanner;

public class GradeCalculator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter your score (0-100): ");
        int score = scanner.nextInt();

        char grade;
        if (score >= 90) {
            grade = 'A';
        } else if (score >= 80) {
            grade = 'B';
        } else if (score >= 70) {
            grade = 'C';
        } else if (score >= 60) {
            grade = 'D';
        } else {
            grade = 'F';
        }

        System.out.println("Your grade: " + grade);
        scanner.close();
    }
}

/**
 * Base64 is a group of binary-to-text encoding schemes that represent binary data
 * in an ASCII string format by translating it into a radix-64 representation.
 * Each base64 digit represents exactly 6 bits of data.
 *
 * Base64 encoding is commonly used when there is a need to encode binary data
 * that needs to be stored and transferred over media that are designed to deal
 * with textual data.
 *
 * Wikipedia Reference: https://en.wikipedia.org/wiki/Base64
 * Author: Nithin U.
 * Github: https://github.com/NithinU2802
 */

public final class Base64 {

    // Base64 character set
    private static final String BASE64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    private static final char PADDING_CHAR = '=';

    private Base64() {
    }

    /**
     * Encodes the given byte array to a Base64 encoded string.
     *
     * @param input the byte array to encode
     * @return the Base64 encoded string
     * @throws IllegalArgumentException if input is null
     */
    public static String encode(byte[] input) {
        if (input == null) {
            throw new IllegalArgumentException("Input cannot be null");
        }

        if (input.length == 0) {
            return "";
        }

        StringBuilder result = new StringBuilder();
        int padding = 0;

        // Process input in groups of 3 bytes
        for (int i = 0; i < input.length; i += 3) {
            // Get up to 3 bytes
            int byte1 = input[i] & 0xFF;
            int byte2 = (i + 1 < input.length) ? (input[i + 1] & 0xFF) : 0;
            int byte3 = (i + 2 < input.length) ? (input[i + 2] & 0xFF) : 0;

            // Calculate padding needed
            if (i + 1 >= input.length) {
                padding = 2;
            } else if (i + 2 >= input.length) {
                padding = 1;
            }

            // Combine 3 bytes into a 24-bit number
            int combined = (byte1 << 16) | (byte2 << 8) | byte3;

            // Extract four 6-bit groups
            result.append(BASE64_CHARS.charAt((combined >> 18) & 0x3F));
            result.append(BASE64_CHARS.charAt((combined >> 12) & 0x3F));
            result.append(BASE64_CHARS.charAt((combined >> 6) & 0x3F));
            result.append(BASE64_CHARS.charAt(combined & 0x3F));
        }

        // Replace padding characters
        if (padding > 0) {
            result.setLength(result.length() - padding);
            for (int i = 0; i < padding; i++) {
                result.append(PADDING_CHAR);
            }
        }

        return result.toString();
    }

    /**
     * Encodes the given string to a Base64 encoded string using UTF-8 encoding.
     *
     * @param input the string to encode
     * @return the Base64 encoded string
     * @throws IllegalArgumentException if input is null
     */
    public static String encode(String input) {
        if (input == null) {
            throw new IllegalArgumentException("Input cannot be null");
        }

        return encode(input.getBytes(StandardCharsets.UTF_8));
    }

    /**
     * Decodes the given Base64 encoded string to a byte array.
     *
     * @param input the Base64 encoded string to decode
     * @return the decoded byte array
     * @throws IllegalArgumentException if input is null or contains invalid Base64 characters
     */
    public static byte[] decode(String input) {
        if (input == null) {
            throw new IllegalArgumentException("Input cannot be null");
        }

        if (input.isEmpty()) {
            return new byte[0];
        }

        // Strict RFC 4648 compliance: length must be a multiple of 4
        if (input.length() % 4 != 0) {
            throw new IllegalArgumentException("Invalid Base64 input length; must be multiple of 4");
        }

        // Validate padding: '=' can only appear at the end (last 1 or 2 chars)
        int firstPadding = input.indexOf('=');
        if (firstPadding != -1 && firstPadding < input.length() - 2) {
            throw new IllegalArgumentException("Padding '=' can only appear at the end (last 1 or 2 characters)");
        }

        List<Byte> result = new ArrayList<>();

        // Process input in groups of 4 characters
        for (int i = 0; i < input.length(); i += 4) {
            // Get up to 4 characters
            int char1 = getBase64Value(input.charAt(i));
            int char2 = getBase64Value(input.charAt(i + 1));
            int char3 = input.charAt(i + 2) == '=' ? 0 : getBase64Value(input.charAt(i + 2));
            int char4 = input.charAt(i + 3) == '=' ? 0 : getBase64Value(input.charAt(i + 3));

            // Combine four 6-bit groups into a 24-bit number
            int combined = (char1 << 18) | (char2 << 12) | (char3 << 6) | char4;

            // Extract three 8-bit bytes
            result.add((byte) ((combined >> 16) & 0xFF));
            if (input.charAt(i + 2) != '=') {
                result.add((byte) ((combined >> 8) & 0xFF));
            }
            if (input.charAt(i + 3) != '=') {
                result.add((byte) (combined & 0xFF));
            }
        }

        // Convert List<Byte> to byte[]
        byte[] resultArray = new byte[result.size()];
        for (int i = 0; i < result.size(); i++) {
            resultArray[i] = result.get(i);
        }

        return resultArray;
    }

    /**
     * Decodes the given Base64 encoded string to a string using UTF-8 encoding.
     *
     * @param input the Base64 encoded string to decode
     * @return the decoded string
     * @throws IllegalArgumentException if input is null or contains invalid Base64 characters
     */
    public static String decodeToString(String input) {
        if (input == null) {
            throw new IllegalArgumentException("Input cannot be null");
        }

        byte[] decodedBytes = decode(input);
        return new String(decodedBytes, StandardCharsets.UTF_8);
    }

    /**
     * Gets the numeric value of a Base64 character.
     *
     * @param c the Base64 character
     * @return the numeric value (0-63)
     * @throws IllegalArgumentException if character is not a valid Base64 character
     */
    private static int getBase64Value(char c) {
        if (c >= 'A' && c <= 'Z') {
            return c - 'A';
        } else if (c >= 'a' && c <= 'z') {
            return c - 'a' + 26;
        } else if (c >= '0' && c <= '9') {
            return c - '0' + 52;
        } else if (c == '+') {
            return 62;
        } else if (c == '/') {
            return 63;
        } else {
            throw new IllegalArgumentException("Invalid Base64 character: " + c);
        }
    }
}

package objects;

public class Telefon {

	String numara;  // Telefon numarasini tutan alan

	// Telefon sinifinin yapici metodu, telefon numarasini alir
	public Telefon(String numara) {
		this.numara = numara;  // Telefon numarasini baslatir
	}

	// Arama islemi yapan metod
	public void aramaYap(Telefon telefon) {
		// Verilen telefon numarasina arama yapma islemi
		System.out.println(this.numara + " numarali telefon " + telefon.numara + " numarasina arama yapiyor.");
	}

	// Mesaj gonderme islemi yapan metod
	public void mesajGonder(Telefon telefon, String mesaj) {
		// Verilen telefona mesaj gonderme islemi
		System.out.println(this.numara + " numarali telefon, " + telefon.numara + " numarasina mesaj gonderdi: " + mesaj);
	}

	// Kamera acma islemi yapan metod
	public void kameraAc() {
		// Kamerayi acma islemi
		System.out.println(this.numara + " numarali telefon kamerasini acti.");
	}

	// Telefonun sarj durumunu kontrol eden metod
	public void sarjDurumunuKontrolEt() {
		// Telefonun sarj durumunu simule etme
		System.out.println(this.numara + " numarali telefonun sarj durumu %85.");
	}

	// Arama gecmisi tutan metod
	public void aramaGecmisiGoster() {
		// Arama gecmisi simule etme
		System.out.println(this.numara + " numarali telefonun arama gecmisi gosteriliyor.");
	}

	// Ana metod (main method) icinde kullanimi
	public static void main(String[] args) {
		// iki telefon nesnesi olusturuluyor
		Telefon telefon1 = new Telefon("5551234567");  // Telefon 1
		Telefon telefon2 = new Telefon("5051234567");  // Telefon 2

		// Telefon 1, Telefon 2'ye arama yapar
		telefon1.aramaYap(telefon2);

		// Telefon 2, Telefon 1'e mesaj gonderir
		telefon2.mesajGonder(telefon1, "Merhaba!");

		// Telefon 1 kamerasini acar
		telefon1.kameraAc();

		// Telefon 1 sarj durumunu kontrol eder
		telefon1.sarjDurumunuKontrolEt();

		// Telefon 2'nin arama gecmisi goruntulenir
		telefon2.aramaGecmisiGoster();
	}
}

