public class DosyaOkumaYazma {

    public static void main(String[] args) {
        // Okuma yapilacak dosyanin adi
        String girisDosyaAdi = "girdi.txt";
        // Yazma yapilacak dosyanin adi
        String cikisDosyaAdi = "cikti.txt";

        try {
            // Okuma islemini gerceklestir
            byte[] veri = dosyaOku(girisDosyaAdi);

            // Yazma islemini gerceklestir
            dosyaYaz(cikisDosyaAdi, veri);

            System.out.println("Dosya basariyla '" + cikisDosyaAdi + "' dosyasina kopyalandi!");

        } catch (IOException e) {
            // Hata olusursa konsola hata mesajini yaz
            System.out.println("Dosya isleminde bir hata olustu: " + e.getMessage());
        } catch (Exception e) {
            // Beklenmeyen bir hata olusursa yakala
            System.out.println("Beklenmeyen bir hata olustu: " + e.getMessage());
        }
    }

    /**
     * Bir dosyadan veriyi byte dizisi olarak okur.
     * @param dosyaAdi Okuma yapilacak dosyanin adi
     * @return Dosyadan okunan veri
     * @throws IOException Dosya bulunamazsa veya okuma hatasi olusursa
     */
    public static byte[] dosyaOku(String dosyaAdi) throws IOException {
        File girisDosyasi = new File(dosyaAdi);

        if (!girisDosyasi.exists()) {
            throw new IOException("Giris dosyasi bulunamadi: " + dosyaAdi);
        }

        FileInputStream girisAkimi = new FileInputStream(girisDosyasi);
        byte[] veri = new byte[(int) girisDosyasi.length()];

        int okunanByteSayisi = girisAkimi.read(veri);
        System.out.println("Okunan byte sayisi: " + okunanByteSayisi);

        girisAkimi.close();
        return veri;
    }

    /**
     * Bir byte dizisini dosyaya yazar.
     * @param dosyaAdi Yazma yapilacak dosyanin adi
     * @param veri Yazilacak veri
     * @throws IOException Dosya olusturulamazsa veya yazma hatasi olusursa
     */
    public static void dosyaYaz(String dosyaAdi, byte[] veri) throws IOException {
        File cikisDosyasi = new File(dosyaAdi);

        // Dosyanin mevcut olup olmadigini kontrol et
        if (cikisDosyasi.exists()) {
            System.out.println("Uyari: Cikis dosyasi zaten mevcut, uzerine yaziliyor.");
        }

        FileOutputStream cikisAkimi = new FileOutputStream(cikisDosyasi);
        cikisAkimi.write(veri);
        System.out.println("Cikis dosyasina yazma islemi tamamlandi.");

        cikisAkimi.close();
    }
}

package functions;

public class SayiOkuma {

    public static void main(String[] args) {

        System.out.println(sayiyiYaziyaCevir(1234)); // ornek degerlerin yazili karsiligini goster

        System.out.println(sayiyiYaziyaCevir(7248));

        System.out.println(sayiyiYaziyaCevir(297));

        System.out.println(sayiyiYaziyaCevir(505));

        System.out.println(sayiyiYaziyaCevir(300));
    }

    // Verilen dort haneye kadar olan sayiyi Turkce yaziya cevirir
    public static String sayiyiYaziyaCevir(int deger) {
        if (deger == 0) {
            return "sifir";
        }

        StringBuilder metin = new StringBuilder();

        int binler = deger / 1000;
        int yuzler = (deger / 100) % 10;
        int onlar = (deger / 10) % 10;
        int birler = deger % 10;

        if (binler > 0) {
            metin.append(binHanesiYaz(binler)).append(" ");
        }
        if (yuzler > 0) {
            metin.append(yuzHanesiYaz(yuzler)).append(" ");
        }
        if (onlar > 0) {
            metin.append(onlarHanesiYaz(onlar)).append(" ");
        }
        if (birler > 0) {
            metin.append(birlerHanesiYaz(birler));
        }

        return metin.toString().trim();
    }

    // Binler hanesinin karsiligini switch yapisiyla belirler
    public static String binHanesiYaz(int binler) {
        switch (binler) {
            case 1: return "bin";
            case 2: return "iki bin";
            case 3: return "uc bin";
            case 4: return "dort bin";
            case 5: return "bes bin";
            case 6: return "alti bin";
            case 7: return "yedi bin";
            case 8: return "sekiz bin";
            case 9: return "dokuz bin";
            default: return "";
        }
    }

    // Yuzler hanesinin karsiligini switch yapisiyla belirler
    public static String yuzHanesiYaz(int yuzler) {
        switch (yuzler) {
            case 1: return "yuz";
            case 2: return "iki yuz";
            case 3: return "uc yuz";
            case 4: return "dort yuz";
            case 5: return "bes yuz";
            case 6: return "alti yuz";
            case 7: return "yedi yuz";
            case 8: return "sekiz yuz";
            case 9: return "dokuz yuz";
            default: return "";
        }
    }

    // Onlar hanesinin karsiligini switch yapisiyla belirler
    public static String onlarHanesiYaz(int onlar) {
        switch (onlar) {
            case 1: return "on";
            case 2: return "yirmi";
            case 3: return "otuz";
            case 4: return "kirk";
            case 5: return "elli";
            case 6: return "altmis";
            case 7: return "yetmis";
            case 8: return "seksen";
            case 9: return "doksan";
            default: return "";
        }
    }

    // Birler hanesinin karsiligini switch yapisiyla belirler
    public static String birlerHanesiYaz(int birler) {
        switch (birler) {
            case 1: return "bir";
            case 2: return "iki";
            case 3: return "uc";
            case 4: return "dort";
            case 5: return "bes";
            case 6: return "alti";
            case 7: return "yedi";
            case 8: return "sekiz";
            case 9: return "dokuz";
            default: return "";
        }
    }
}

import java.util.HashMap;
import java.util.Map;

public class RomanToInteger {
    /**
     * Converts a Roman numeral string to an integer.
     */
    public static int convert(String roman) {
        Map<Character, Integer> values = new HashMap<>();
        values.put('I', 1);
        values.put('V', 5);
        values.put('X', 10);
        values.put('L', 50);
        values.put('C', 100);
        values.put('D', 500);
        values.put('M', 1000);

        int total = 0;
        for (int i = 0; i < roman.length(); i++) {
            int current = values.get(roman.charAt(i));
            // If a smaller value precedes a larger one, subtract it
            if (i + 1 < roman.length() && current < values.get(roman.charAt(i + 1))) {
                total -= current;
            } else {
                total += current;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        System.out.println("XIV = " + convert("XIV"));
        System.out.println("MCMXCIV = " + convert("MCMXCIV"));
    }
}

/**
 * Given a sorted array. Create a balanced binary search tree from it.
 *
 * Steps: 1. Find the middle element of array. This will act as root 2. Use the
 * left half recursively to create left subtree 3. Use the right half
 * recursively to create right subtree
 */
public final class BSTFromSortedArray {
    private BSTFromSortedArray() {
    }
    public static Node createBST(int[] array) {
        if (array == null || array.length == 0) {
            return null;
        }
        return createBST(array, 0, array.length - 1);
    }

    private static Node createBST(int[] array, int startIdx, int endIdx) {
        // No element left.
        if (startIdx > endIdx) {
            return null;
        }
        int mid = startIdx + (endIdx - startIdx) / 2;

        // middle element will be the root
        Node root = new Node(array[mid]);
        root.left = createBST(array, startIdx, mid - 1);
        root.right = createBST(array, mid + 1, endIdx);
        return root;
    }
}

public final class DiffieHellman {

    private final BigInteger base;
    private final BigInteger secret;
    private final BigInteger prime;

    // Constructor to initialize base, secret, and prime
    public DiffieHellman(BigInteger base, BigInteger secret, BigInteger prime) {
        // Check for non-null and positive values
        if (base == null || secret == null || prime == null || base.signum() <= 0 || secret.signum() <= 0 || prime.signum() <= 0) {
            throw new IllegalArgumentException("Base, secret, and prime must be non-null and positive values.");
        }
        this.base = base;
        this.secret = secret;
        this.prime = prime;
    }

    // Method to calculate public value (g^x mod p)
    public BigInteger calculatePublicValue() {
        // Returns g^x mod p
        return base.modPow(secret, prime);
    }

    // Method to calculate the shared secret key (otherPublic^secret mod p)
    public BigInteger calculateSharedSecret(BigInteger otherPublicValue) {
        if (otherPublicValue == null || otherPublicValue.signum() <= 0) {
            throw new IllegalArgumentException("Other public value must be non-null and positive.");
        }
        // Returns b^x mod p or a^y mod p
        return otherPublicValue.modPow(secret, prime);
    }
}

public class Human implements Cloneable {
    int age;
    String name;
    int[] arr;

    public Human(int age, String name) {
        this.age = age;
        this.name = name;
        this.arr = new int[]{3, 4, 5, 6, 7};
    }

//    public Human(Human other) {
