public class BasamakSayisi {

    // 'basamakSayisiBul' metodu verilen sayinin kac basamaktan olustugunu bulur
    int basamakSayisiBul(int sayi) {
        int basamakSayisi = 0;  // Basamak sayisini tutacak degisken
        // Sayi 0'dan buyuk oldugu surece dongu devam eder
        while(sayi > 0) {
            // Sayi her dongude 10'a bolunerek bir basamak eksiltilir
            sayi = sayi / 10;
            // Her bolme isleminde bir basamak oldugu icin sayaci arttir
            basamakSayisi++;
        }
        // Basamak sayisini dondur
        return basamakSayisi;
    }

    public static void main(String[] args) {

        // Kullaniciya giris almak icin Scanner nesnesi olustur
        Scanner okuyucu = new Scanner(System.in);
        // Kullanicinin girdigi sayiyi al
        int sayi = okuyucu.nextInt();

        // BasamakSayisi sinifindan bir nesne olustur
        BasamakSayisi bulucu = new BasamakSayisi();

        // 'basamakSayisiBul' metodunu cagirararak sayinin basamak sayisini hesapla
        int sonuc = bulucu.basamakSayisiBul(sayi);

        // Sonucu ekrana yazdir
        System.out.println(sonuc);

        // Scanner nesnesini kapat
        okuyucu.close();
    }
}

/**
 * An implementation of the Shannon-Fano algorithm for generating prefix codes.
 *
 * <p>Shannon-Fano coding is an entropy encoding technique for lossless data
 * compression. It assigns variable-length codes to symbols based on their
 * frequencies of occurrence. It is a precursor to Huffman coding and works by
 * recursively partitioning a sorted list of symbols into two sub-lists with
 * nearly equal total frequencies.
 *
 * <p>The algorithm works as follows:
 * <ol>
 * <li>Count the frequency of each symbol in the input data.</li>
 * <li>Sort the symbols in descending order of their frequencies.</li>
 * <li>Recursively divide the list of symbols into two parts with sums of
 * frequencies as close as possible to each other.</li>
 * <li>Assign a '0' bit to the codes in the first part and a '1' bit to the codes
 * in the second part.</li>
 * <li>Repeat the process for each part until a part contains only one symbol.</li>
 * </ol>
 *
 * <p>Time Complexity: O(n^2) in this implementation due to the partitioning logic,
 * or O(n log n) if a more optimized partitioning strategy is used.
 * Sorting takes O(n log n), where n is the number of unique symbols.
 *
 * <p>References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Shannon–Fano_coding">Wikipedia: Shannon–Fano coding</a></li>
 * </ul>
 */
public final class ShannonFano {

/**
 * Private constructor to prevent instantiation of this utility class.
 */
private ShannonFano() {
}

/**
 * A private inner class to represent a symbol and its frequency.
 * Implements Comparable to allow sorting based on frequency.
 */
private static class FrequencyNode implements Comparable<FrequencyNode> {
final char symbolChar;
final int occurrenceCount;
String binaryCode = "";

FrequencyNode(char symbolChar, int occurrenceCount) {
this.symbolChar = symbolChar;
this.occurrenceCount = occurrenceCount;
}

@Override
public int compareTo(FrequencyNode otherNode) {
return Integer.compare(otherNode.occurrenceCount, this.occurrenceCount);
}
}

/**
 * Generates Shannon-Fano codes for the symbols in a given text.
 *
 * @param sourceText The input string for which to generate codes. Must not be null.
 * @return A map where keys are characters and values are their corresponding Shannon-Fano codes.
 */
public static Map<Character, String> generateCodes(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
return Collections.emptyMap();
}
Map<Character, Integer> freqMapping = new HashMap<>();
for (char currentChar : sourceText.toCharArray()) {
freqMapping.put(currentChar, freqMapping.getOrDefault(currentChar, 0) + 1);
}
List<FrequencyNode> symbolList = new ArrayList<>();
for (Map.Entry<Character, Integer> entry : freqMapping.entrySet()) {
symbolList.add(new FrequencyNode(entry.getKey(), entry.getValue()));
}
Collections.sort(symbolList);
if (symbolList.size() == 1) {
symbolList.getFirst().binaryCode = "0";
} else {
buildCodeTree(symbolList, 0, symbolList.size() - 1, "");
}
return symbolList.stream().collect(Collectors.toMap(node -> node.symbolChar, node -> node.binaryCode));
}

/**
 * Recursively builds the Shannon-Fano code tree by partitioning the list of symbols.
 * Uses index-based approach to avoid sublist creation issues.
 *
 * @param symbolList The sorted list of symbols to be processed.
 * @param startIndex The start index of the current partition.
 * @param endIndex The end index of the current partition (inclusive).
 * @param codePrefix The current prefix code being built for the symbols in this partition.
 */
private static void buildCodeTree(List<FrequencyNode> symbolList, int startIndex, int endIndex, String codePrefix) {
if (startIndex == endIndex) {
symbolList.get(startIndex).binaryCode = codePrefix;
return;
}
int splitPosition = findSplitIndex(symbolList, startIndex, endIndex);
buildCodeTree(symbolList, startIndex, splitPosition, codePrefix + "0");
buildCodeTree(symbolList, splitPosition + 1, endIndex, codePrefix + "1");
}

/**
 * Finds the index that splits the range into two parts with the most balanced frequency sums.
 * This method tries every possible split point and returns the index that minimizes the
 * absolute difference between the two partition sums.
 *
 * @param symbolList The sorted list of symbols.
 * @param startIndex The start index of the range.
 * @param endIndex The end index of the range (inclusive).
 * @return The index of the last element in the first partition.
 */
private static int findSplitIndex(List<FrequencyNode> symbolList, int startIndex, int endIndex) {
long totalFrequency = 0;
for (int position = startIndex; position <= endIndex; position++) {
totalFrequency += symbolList.get(position).occurrenceCount;
}
long accumulatedLeft = 0;
long minimalDifference = Long.MAX_VALUE;
int splitPoint = startIndex;
for (int position = startIndex; position < endIndex; position++) {
accumulatedLeft += symbolList.get(position).occurrenceCount;
long rightPartSum = totalFrequency - accumulatedLeft;
long currentDifference = Math.abs(accumulatedLeft - rightPartSum);
if (currentDifference < minimalDifference) {
minimalDifference = currentDifference;
splitPoint = position;
}
}
return splitPoint;
}
}

/**
 * Base class for people: a name and address.
 */
public class Person {
    private String name;
    private String address;

    public Person() {
    }

    public Person(String name, String address) {
        this.name = name;
        this.address = address;
    }

