    }
}

package com.ankan.stringBuffer;

import java.lang.reflect.Array;
import java.text.DecimalFormat;
import java.util.Arrays;
import java.util.Random;
import java.util.random.*;

import static com.ankan.stringBuffer.RandomString.generateRandomString;

public class LargeStringExample {
    public static void main(String[] args) {

        // ========== STRINGBUFFER CONSTRUCTOR DEMONSTRATION ==========

        // Constructor 1: Default constructor (initial capacity = 16 characters)
        StringBuffer defaultBuffer = new StringBuffer();
        System.out.println("Default buffer capacity: " + defaultBuffer.capacity());  // Output: 16

        // Constructor 2: Constructor with initial string value
        StringBuffer initialStringBuffer = new StringBuffer("Ankan Chatterjee");
        System.out.println("Buffer with initial string: " + initialStringBuffer);

        // Constructor 3: Constructor with custom initial capacity
        StringBuffer customCapacityBuffer = new StringBuffer(30);
        System.out.println("Custom capacity buffer capacity: " + customCapacityBuffer.capacity());  // Output: 30

        // ========== STRINGBUFFER MUTATION OPERATIONS ==========

        StringBuffer mutableBuffer = new StringBuffer();
        mutableBuffer.append("WeMakeDevs");
        mutableBuffer.append(" is nice");

        // Insert operation (commented)
        // mutableBuffer.insert(2, " Ankan ");

        // Replace operation - end index is exclusive (doesn't include index 5)
        mutableBuffer.replace(1, 5, " Chatterjee ");

        // Delete operation - end index is exclusive
        mutableBuffer.delete(1, 5);

        // Convert StringBuffer to immutable String
        String finalStringResult = mutableBuffer.toString();
        System.out.println("Final string after operations: " + finalStringResult);

        /* ========== STRINGBUFFER EDUCATIONAL NOTES ==========

        What is StringBuffer class?
        ---------------------------
        - Mutable sequence of characters (unlike String which is immutable)
        - Can be modified without creating new objects each time

        Advantages over String:
        ------------------------
        1. MUTABLE - Can change content without creating new objects
        2. MORE EFFICIENT - Better performance for frequent modifications
        3. THREAD-SAFE - Methods are synchronized (safe for multi-threading)

        StringBuffer vs StringBuilder:
        -------------------------------
        | Feature        | StringBuffer | StringBuilder |
        |---------------|--------------|---------------|
        | Thread Safety | ✅ Yes       | ❌ No        |
        | Performance   | Slower       | Faster        |
        | Use Case      | Multi-threaded | Single-threaded |

        Note: StringBuilder is NOT thread-safe but is faster than StringBuffer
        */

        // ========== RANDOM STRING GENERATION ==========

        int desiredLength = 20;
        String randomGeneratedString = generateRandomString(desiredLength);
        System.out.println("\nRandomly generated string: " + randomGeneratedString);

        // ========== REMOVING WHITESPACES ==========

        String sentenceWithSpaces = "Hi   my  name is    Ankan";
        System.out.println("\nOriginal sentence: " + sentenceWithSpaces);
        System.out.println("After removing all whitespaces: " + sentenceWithSpaces.replaceAll("\\s", ""));
        // The regex "\\s" matches any whitespace character (space, tab, newline)

        // ========== STRING SPLITTING ==========

        String commaSeparatedNames = "Ankan, Apoorv, Rahul, Snehal";
        String[] nameArray = commaSeparatedNames.split(", ");
        System.out.println("\nSplit names array: " + Arrays.toString(nameArray));

        // Accessing individual elements
        System.out.println("First name: " + nameArray[0]);
        System.out.println("Second name: " + nameArray[1]);

        // ========== NUMBER FORMATTING (ROUNDING OFF) ==========

        DecimalFormat decimalFormatter = new DecimalFormat("0.0000");
        double numberToFormat = 7.29;
        String formattedNumber = decimalFormatter.format(numberToFormat);
        System.out.println("\nOriginal number: " + numberToFormat);
        System.out.println("Formatted (4 decimal places): " + formattedNumber);

        // Additional DecimalFormat examples (commented)
        // DecimalFormat twoDecimals = new DecimalFormat("0.00");
        // System.out.println(twoDecimals.format(7.29));  // Output: 7.29
        // System.out.println(twoDecimals.format(7.293)); // Output: 7.29
    }
}

/*
COMPREHENSIVE SUMMARY - StringBuffer Class
==========================================

Key Characteristics:
--------------------
1. MUTABLE: Can be changed after creation
2. THREAD-SAFE: All public methods are synchronized
3. RESIZABLE: Automatically grows when capacity is exceeded
4. EFFICIENT: Better than String for multiple concatenations

Common Methods:
---------------
| Method | Description | Example |
|--------|-------------|---------|
| append() | Adds text to the end | sb.append("text") |
| insert() | Inserts text at position | sb.insert(2, "text") |
| replace() | Replaces characters | sb.replace(1, 5, "new") |
| delete() | Removes characters | sb.delete(1, 5) |
| reverse() | Reverses the sequence | sb.reverse() |
| capacity() | Returns current capacity | sb.capacity() |
| toString() | Converts to String | sb.toString() |

Capacity Management:
--------------------
- Default capacity: 16 characters
- When capacity is exceeded: (old_capacity * 2) + 2
- Can set custom capacity in constructor

When to Use StringBuffer?
-------------------------
✅ Use StringBuffer when:
   - Multiple string modifications are needed
   - Working in a multi-threaded environment
   - Performance is important but thread-safety is required

❌ Use StringBuilder when:
   - Working in single-threaded environment
   - Maximum performance is needed
   - Thread-safety is not required

Use String (immutable) when:
   - String content does not change
   - Small number of concatenations
   - Simple string operations
*/

