        this.discountRate = discountRate;
    }

    public Customer(int customerId, String fullName, char gender) {
        this.customerId = customerId;
        this.fullName = fullName;
        if (gender == 'm' || gender == 'f') {
            this.gender = gender;
        } else {
            System.out.println("Gender of 'm' or 'f'");
        }
    }

    public int getID() {
        return customerId;
    }

    public void setID(int customerId) {
        this.customerId = customerId;
    }

    public String getName() {
        return fullName;
    }

    public void setName(String fullName) {
        this.fullName = fullName;
    }

    public char getGender() {
        return gender;
    }

    public void setGender(char gender) {
        if (gender == 'm' || gender == 'f') {
            this.gender = gender;
        } else {
            System.out.println("Gender of 'm' or 'f'");
        }
    }

    public double getDiscount() {
        return discountRate;
    }

    public void setDiscount(double discountRate) {
        this.discountRate = discountRate;
    }

    @Override
    public String toString() {
        return fullName + "(" + customerId + ")";
    }
}

public class Account {
    private int accountId;
    private Customer owner;
    private double balance;

    public Account(int accountId, Customer owner, double balance) {
        this.accountId = accountId;
        this.owner = owner;
        this.balance = balance;
    }

    public Account(int accountId, Customer owner) {
        this.accountId = accountId;
        this.owner = owner;
    }

    public int getId() {
        return accountId;
    }

    public void setId(int accountId) {
        this.accountId = accountId;
    }

    public Customer getCustomer() {
        return owner;
    }

    public void setCustomer(Customer owner) {
        this.owner = owner;
    }

    public double getBalance() {
        return balance;
    }

    public void setBalance(double balance) {
        this.balance = balance;
    }

    public String getCustomerName() {
        return owner.getName();
    }

    public Account deposit(double amount) {
        balance += amount;
        return this;
    }

    public Account withdraw(double amount) {
        if (amount > balance) {
            System.out.println("amount withdraw exceeds the current balance!");
        } else {
            balance -= amount;
        }
        return this;
    }

    @Override
    public String toString() {
        return owner.getName() + "(" + accountId + ")" + " balance=" + String.format("$%.2f", balance);
    }
}

