package syntax;

public class IsimlendirmeKurallari {

    public static void main(String[] args) {

        // A rundown of legal Java identifiers across the primitive types.
        long phoneNumber;   // valid: simple long variable
        char gender;        // valid: meaningful single-word name
        boolean isMarried;  // valid: meaningful boolean name
        double salaryCalc;  // valid: multi-word, descriptive name
        String fullName;    // valid: identifiers may combine several words
        int age;            // valid: minimal but clear variable name

        // Constants are conventionally written in all caps.
        final double PI_VALUE = 3.14159;

        // Java forbids special characters and whitespace inside identifiers:
        // int 2age;               // invalid: cannot start with a digit
        // String @fullName;       // invalid: cannot start with a special character
        // double salary calc;     // invalid: no spaces allowed
        // boolean is married;     // invalid: no spaces allowed

        // Identifiers should always be descriptive rather than arbitrary.
        String cityName = "Istanbul";
        int studentCount = 100;

        // Identifiers must not start with an uppercase letter by convention:
        // String FullName; // discouraged: should not start with a capital letter

        // camelCase is the standard convention for variable and method names.
        String studentFullName = "Ali Veli";
        double totalSalary = 5000.0;

        // Even so, constant fields are still written in uppercase snake case.
        final int MAX_COUNT = 100;
    }
}

public class AgeCalculator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter birth year: ");
        int year = scanner.nextInt();
        System.out.print("Enter birth month: ");
        int month = scanner.nextInt();
        System.out.print("Enter birth day: ");
        int day = scanner.nextInt();

        LocalDate birthDate = LocalDate.of(year, month, day);
        Period age = Period.between(birthDate, LocalDate.now());

        System.out.printf("You are %d years, %d months and %d days old%n",
                age.getYears(), age.getMonths(), age.getDays());
        scanner.close();
    }
}

package switchcase; 
import java.util.Scanner;

public class MevsimAdlari {

	public static void main(String[] args) {

		Scanner scanner = new Scanner(System.in);

		// Kullanicidan bir ay numarasi girmesini iste
		System.out.print("Bir ay girin (1-12): ");
		int ay = scanner.nextInt();

		String mevsim;

		// Ay numarasina gore mevsimi belirle
		switch (ay) {
		case 3:
		case 4:
		case 5:
			mevsim = "ilkbahar";  // 3, 4 ve 5. aylar ilkbahar mevsimidir
			break;
		case 6:
		case 7:
		case 8:
			mevsim = "Yaz";  // 6, 7 ve 8. aylar yaz mevsimidir
			break;
		case 9:
		case 10:
		case 11:
			mevsim = "Sonbahar";  // 9, 10 ve 11. aylar sonbahar mevsimidir
			break;
		case 12:
		case 1:
		case 2:
			mevsim = "Kis";  // 12, 1 ve 2. aylar kis mevsimidir
			break;
		default:
			mevsim = "Gecersiz ay";  // Gecersiz bir ay numarasi girilirse
			break;
		}

		// Hesaplanan mevsimi ekrana yazdir
		System.out.println("Girdiginiz ayin mevsimi: " + mevsim);

		// Scanner nesnesini kapat
		scanner.close();
	}
}

package MyRectangle;

/**
 * A rectangle composed of top-left and bottom-right MyPoint corners.
 */
class MyPoint {

    private int x;
    private int y;

    public MyPoint() {
    }

    public MyPoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int[] getXY() {
        return new int[]{x, y};
    }

    public void setXY(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public double distance(int x, int y) {
        return Math.sqrt(Math.pow(x - this.x, 2) + Math.pow(y - this.y, 2));
    }

    public double distance(MyPoint another) {
        return Math.sqrt(Math.pow(another.x - x, 2) + Math.pow(another.y - y, 2));
    }

    public double distance() {
        return Math.sqrt(Math.pow(-x, 2) + Math.pow(-y, 2));
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ')';
    }
}

public class MyRectangle {
    private MyPoint topLeft;
    private MyPoint bottomRight;

    public MyRectangle() {
    }

    public MyRectangle(MyPoint topLeft, MyPoint bottomRight) {
        this.topLeft = topLeft;
        this.bottomRight = bottomRight;
    }

    public MyRectangle(int x1, int y1, int x2, int y2) {
        this.topLeft = new MyPoint(x1, y1);
        this.bottomRight = new MyPoint(x2, y2);
    }

    public MyPoint getTopLeft() {
        return topLeft;
    }

    public void setTopLeft(MyPoint topLeft) {
        this.topLeft = topLeft;
    }

    public MyPoint getBottomRight() {
        return bottomRight;
    }

    public void setBottomRight(MyPoint bottomRight) {
        this.bottomRight = bottomRight;
    }

    public void setTopLeftX(int x) {
        topLeft.setX(x);
    }

    public int getTopLeftX() {
        return topLeft.getX();
    }

    public void setTopLeftY(int y) {
        topLeft.setY(y);
    }

    public int getTopLeftY() {
        return topLeft.getY();
    }

    public void setTopLeftXY(int x, int y) {
        topLeft.setXY(x, y);
    }

    public int[] getTopLeftXY() {
        return new int[]{topLeft.getX(), topLeft.getY()};
    }

    public void setBottomRightX(int x) {
        bottomRight.setX(x);
    }

    public int getBottomRightX() {
        return bottomRight.getX();
    }

    public void setBottomRightY(int y) {
        bottomRight.setY(y);
    }

    public int getBottomRightY() {
        return bottomRight.getY();
    }

    public void setBottomRightXY(int x, int y) {
        bottomRight.setXY(x, y);
    }

    public int[] getBottomRightXY() {
        return new int[]{bottomRight.getX(), bottomRight.getY()};
    }

    public MyPoint getBottomLeft() {
        return new MyPoint(topLeft.getX(), bottomRight.getY());
    }

    public MyPoint getTopRight() {
        return new MyPoint(bottomRight.getX(), topLeft.getY());
    }

    public double getDiagonal() {
        return topLeft.distance(bottomRight);
    }

    public String getFullPoint() {
        return "MyRectangle[" + "topLeft=" + topLeft + ",bottomLeft" + getBottomLeft() + ",bottomRight=" + bottomRight + ",topRight" + getTopRight() + ']';
    }

    public int getArea() {
        return (int) (topLeft.distance(getTopRight()) * bottomRight.distance(getTopRight()));
    }

    public int getPerimeter() {
        return (int) ((topLeft.distance(getTopRight()) + bottomRight.distance(getTopRight())) * 2);
    }

    @Override
    public String toString() {
        return "MyRectangle[topLeft=" + topLeft + ",bottomRight=" + bottomRight + ']';
    }
}

class TestMyRectangle {
    public static void main(String[] args) {
        MyRectangle myRectangle = new MyRectangle(new MyPoint(4, 8), new MyPoint(14, 2));
        System.out.println(myRectangle.getArea());
        System.out.println(myRectangle.getPerimeter());
        System.out.println(myRectangle);
        System.out.println(myRectangle.getFullPoint());
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.HashMap;
import java.util.Map;

/**
 * @author Varun Upadhyay (https://github.com/varunu28)
 */
public final class Fibonacci {
    private Fibonacci() {
    }

    static final Map<Integer, Integer> CACHE = new HashMap<>();

    /**
     * This method finds the nth fibonacci number using memoization technique
     *
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * @throws IllegalArgumentException if n is negative
     */
    public static int fibMemo(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        if (CACHE.containsKey(n)) {
            return CACHE.get(n);
        }

        int f;

        if (n <= 1) {
            f = n;
        } else {
            f = fibMemo(n - 1) + fibMemo(n - 2);
            CACHE.put(n, f);
        }
        return f;
    }

    /**
     * This method finds the nth fibonacci number using bottom up
     *
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * @throws IllegalArgumentException if n is negative
     */
    public static int fibBotUp(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        Map<Integer, Integer> fib = new HashMap<>();

        for (int i = 0; i <= n; i++) {
            int f;
            if (i <= 1) {
                f = i;
            } else {
                f = fib.get(i - 1) + fib.get(i - 2);
            }
            fib.put(i, f);
        }

        return fib.get(n);
    }

    /**
     * This method finds the nth fibonacci number using bottom up
     *
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * <p>
     * This is optimized version of Fibonacci Program. Without using Hashmap and
     * recursion. It saves both memory and time. Space Complexity will be O(1)
     * Time Complexity will be O(n)
     * <p>
     * Whereas , the above functions will take O(n) Space.
     * @throws IllegalArgumentException if n is negative
     * @author Shoaib Rayeen (https://github.com/shoaibrayeen)
     */
    public static int fibOptimized(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        if (n == 0) {
            return 0;
        }
        int prev = 0;
        int res = 1;
        int next;
        for (int i = 2; i <= n; i++) {
            next = prev + res;
            prev = res;
            res = next;
        }
        return res;
    }

    /**
     * We have only defined the nth Fibonacci number in terms of the two before it. Now, we will
     * look at Binet's formula to calculate the nth Fibonacci number in constant time. The Fibonacci
     * terms maintain a ratio called golden ratio denoted by Φ, the Greek character pronounced
     * ‘phi'. First, let's look at how the golden ratio is calculated: Φ = ( 1 + √5 )/2
     * = 1.6180339887... Now, let's look at Binet's formula: Sn = Φⁿ–(– Φ⁻ⁿ)/√5 We first calculate
     * the squareRootof5 and phi and store them in variables. Later, we apply Binet's formula to get
     * the required term. Time Complexity will be O(1)
     * @param n The input n for which we have to determine the fibonacci number
     * Outputs the nth fibonacci number
     * @throws IllegalArgumentException if n is negative
     */
    public static int fibBinet(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input n must be non-negative");
        }
        double squareRootOf5 = Math.sqrt(5);
        double phi = (1 + squareRootOf5) / 2;
        return (int) ((Math.pow(phi, n) - Math.pow(-phi, -n)) / squareRootOf5);
    }
}

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;

public class DosyaOkumaYazma {

    public static void main(String[] args) {
        // Okuma yapilacak dosyanin adi
        String girisDosyaAdi = "girdi.txt";
        // Yazma yapilacak dosyanin adi
        String cikisDosyaAdi = "cikti.txt";

        try {
            // Okuma islemini gerceklestir
            byte[] veri = dosyaOku(girisDosyaAdi);

            // Yazma islemini gerceklestir
            dosyaYaz(cikisDosyaAdi, veri);

            System.out.println("Dosya basariyla '" + cikisDosyaAdi + "' dosyasina kopyalandi!");

        } catch (IOException e) {
            // Hata olusursa konsola hata mesajini yaz
            System.out.println("Dosya isleminde bir hata olustu: " + e.getMessage());
        } catch (Exception e) {
            // Beklenmeyen bir hata olusursa yakala
            System.out.println("Beklenmeyen bir hata olustu: " + e.getMessage());
        }
    }

    /**
     * Bir dosyadan veriyi byte dizisi olarak okur.
     * @param dosyaAdi Okuma yapilacak dosyanin adi
     * @return Dosyadan okunan veri
     * @throws IOException Dosya bulunamazsa veya okuma hatasi olusursa
     */
    public static byte[] dosyaOku(String dosyaAdi) throws IOException {
        File girisDosyasi = new File(dosyaAdi);

        if (!girisDosyasi.exists()) {
            throw new IOException("Giris dosyasi bulunamadi: " + dosyaAdi);
        }

        FileInputStream girisAkimi = new FileInputStream(girisDosyasi);
        byte[] veri = new byte[(int) girisDosyasi.length()];

        int okunanByteSayisi = girisAkimi.read(veri);
        System.out.println("Okunan byte sayisi: " + okunanByteSayisi);

        girisAkimi.close();
        return veri;
    }

    /**
     * Bir byte dizisini dosyaya yazar.
     * @param dosyaAdi Yazma yapilacak dosyanin adi
     * @param veri Yazilacak veri
     * @throws IOException Dosya olusturulamazsa veya yazma hatasi olusursa
     */
    public static void dosyaYaz(String dosyaAdi, byte[] veri) throws IOException {
        File cikisDosyasi = new File(dosyaAdi);

        // Dosyanin mevcut olup olmadigini kontrol et
        if (cikisDosyasi.exists()) {
            System.out.println("Uyari: Cikis dosyasi zaten mevcut, uzerine yaziliyor.");
        }

        FileOutputStream cikisAkimi = new FileOutputStream(cikisDosyasi);
        cikisAkimi.write(veri);
        System.out.println("Cikis dosyasina yazma islemi tamamlandi.");

        cikisAkimi.close();
    }
}

// Computes the product of two square integer matrices.
package twodimensional;

public class MatrisCarpimi {

    public static void main(String[] args) {
        // Left-hand operand matrix
        int[][] left = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };

        // Right-hand operand matrix
        int[][] right = {
            {9, 8, 7},
            {6, 5, 4},
            {3, 2, 1}
        };

        int leftRows = left.length;        // number of rows in the left matrix
        int leftCols = left[0].length;      // number of columns in the left matrix
        int rightCols = right[0].length;    // number of columns in the right matrix

        int[][] product = new int[leftRows][rightCols];

        // Standard triple-nested-loop matrix multiplication
        for (int row = 0; row < leftRows; row++) {
            for (int col = 0; col < rightCols; col++) {
                int accumulator = 0;
                for (int k = 0; k < leftCols; k++) {
                    accumulator += left[row][k] * right[k][col];
                }
                product[row][col] = accumulator;
            }
        }

        System.out.println("Matris Carpim Sonucu:");
        printMatrix(product);
    }

    // Helper that prints a matrix row by row, space separated.
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            StringBuilder sb = new StringBuilder();
            for (int value : row) {
                sb.append(value).append(' ');
            }
            System.out.println(sb.toString().trim());
        }
    }
}

package com.thealgorithms.graph;

/**
 * An implementation of the Stoer-Wagner algorithm to find the global minimum cut of an undirected, weighted graph.
 * A minimum cut is a partition of the graph's vertices into two disjoint sets with the minimum possible edge weight
 * sum connecting the two sets.
 *
 * Wikipedia: https://en.wikipedia.org/wiki/Stoer%E2%80%93Wagner_algorithm
 * Time Complexity: O(V^3) where V is the number of vertices.
 */
public class StoerWagner {

    /**
     * Finds the minimum cut in the given undirected, weighted graph.
     *
     * @param graph An adjacency matrix representing the graph. graph[i][j] is the weight of the edge between i and j.
     * @return The weight of the minimum cut.
     */
    public int findMinCut(int[][] graph) {
        int n = graph.length;
        if (n < 2) {
            return 0;
        }

        int[][] currentGraph = new int[n][n];
        for (int i = 0; i < n; i++) {
            System.arraycopy(graph[i], 0, currentGraph[i], 0, n);
        }

        int minCut = Integer.MAX_VALUE;
        boolean[] merged = new boolean[n];

        for (int phase = 0; phase < n - 1; phase++) {
            boolean[] inSetA = new boolean[n];
            int[] weights = new int[n];
            int prev = -1;
            int last = -1;

            for (int i = 0; i < n - phase; i++) {
                int maxWeight = -1;
                int currentVertex = -1;

                for (int j = 0; j < n; j++) {
                    if (!merged[j] && !inSetA[j] && weights[j] > maxWeight) {
                        maxWeight = weights[j];
                        currentVertex = j;
                    }
                }

                if (currentVertex == -1) {
                    // This can happen if the graph is disconnected.
                    return 0;
                }

                prev = last;
                last = currentVertex;
                inSetA[last] = true;

                for (int j = 0; j < n; j++) {
                    if (!merged[j] && !inSetA[j]) {
                        weights[j] += currentGraph[last][j];
                    }
                }
            }

            minCut = Math.min(minCut, weights[last]);

            // Merge 'last' vertex into 'prev' vertex
            for (int i = 0; i < n; i++) {
                currentGraph[prev][i] += currentGraph[last][i];
                currentGraph[i][prev] = currentGraph[prev][i];
            }
            merged[last] = true;
        }

        return minCut;
    }
}

