public final class MainCuckooHashing {
private MainCuckooHashing() {
}

public static void main(String[] args) {
int userChoice;
int inputKey;
CuckooHashMap hashTable = new CuckooHashMap(7);
Scanner inputScanner = new Scanner(System.in);
while (true) {
System.out.println("_________________________");
System.out.println("Enter your Choice :");
System.out.println("1. Add Key");
System.out.println("2. Delete Key");
System.out.println("3. Print Table");
System.out.println("4. Exit");
System.out.println("5. Search and print key index");
System.out.println("6. Check load factor");
System.out.println("7. Rehash Current Table");
userChoice = inputScanner.nextInt();
switch (userChoice) {
case 1:
System.out.println("Enter the Key: ");
inputKey = inputScanner.nextInt();
hashTable.insertKey(inputKey);
break;
case 2:
System.out.println("Enter the Key delete:  ");
inputKey = inputScanner.nextInt();
hashTable.deleteKey(inputKey);
break;
case 3:
System.out.println("Print table:\n");
hashTable.displayTable();
break;
case 4:
inputScanner.close();
return;
case 5:
System.out.println("Enter the Key to find and print:  ");
inputKey = inputScanner.nextInt();
System.out.println("Key: " + inputKey + " is at index: " + hashTable.locateKey(inputKey) + "\n");
break;
case 6:
System.out.printf("Load factor is: %.2f%n", hashTable.verifyLoadRatio());
break;
case 7:
hashTable.increaseAndRehash();
break;
default:
throw new IllegalArgumentException("Unexpected value: " + userChoice);
}
}
}
}

package MyCircle;

import java.util.Arrays;

/**
 * A circle composed of a center MyPoint and a radius.
 */
class MyPoint {

    private int x;
    private int y;

    public MyPoint() {
    }

    public MyPoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int[] getXY() {
        return new int[]{x, y};
    }

    public void setXY(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public double distance(int x, int y) {
        return Math.sqrt(Math.pow(x - this.x, 2) + Math.pow(y - this.y, 2));
    }

    public double distance(MyPoint another) {
        return Math.sqrt(Math.pow(another.x - x, 2) + Math.pow(another.y - y, 2));
    }

    public double distance() {
        return Math.sqrt(Math.pow(-x, 2) + Math.pow(-y, 2));
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ')';
    }
}

public class MyCircle {
    private MyPoint center;
    private int radius;

    public MyCircle() {
    }

    public MyCircle(MyPoint center, int radius) {
        this.center = center;
        this.radius = radius;
    }

    public MyCircle(int x, int y, int radius) {
        this.center = new MyPoint(x, y);
        this.radius = radius;
    }

    public MyPoint getCenter() {
        return center;
    }

    public void setCenter(MyPoint center) {
        this.center = center;
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }

    public int getCenterX() {
        return center.getX();
    }

    public int getCenterY() {
        return center.getY();
    }

    public void setCenterX(int x) {
        center.setX(x);
    }

    public void setCenterY(int y) {
        // mirrors the original's bug: this sets X instead of Y
        center.setX(y);
    }

    public int[] getCenterXY() {
        return center.getXY();
    }

    public void setCenterXY(int x, int y) {
        center.setXY(x, y);
    }

    public double getArea() {
        return Math.pow(radius, 2) * Math.PI;
    }

    public double getCircumference() {
        return radius * 2 * Math.PI;
    }

    public double distance(MyCircle another) {
        return center.distance(another.center);
    }

    @Override
    public String toString() {
        return "MyCircle[radius=" + radius + ",center=" + center.toString() + ']';
    }
}

class TestMyCircle {
    public static void main(String[] args) {
        MyCircle myCircle = new MyCircle(new MyPoint(5, 8), 6);
        System.out.println(myCircle.distance(new MyCircle(new MyPoint(30, 46), 2)));
        System.out.println(myCircle.getArea());
        System.out.println(myCircle.getCircumference());
        System.out.println(myCircle.toString());
        System.out.println(Arrays.toString(myCircle.getCenterXY()));
    }
}

