package com.thealgorithms.dynamicprogramming;

/*
 * A dynamic programming solution for the "Climbing Stairs" problem.
 * Returns the no. of distinct ways to climb to the top
 * of a staircase when you can climb either 1 or 2 steps at a time.
 *
 * For example, if there are 5 steps, the possible ways to climb the
 * staircase are:
 * 1. 1-1-1-1-1
 * 2. 1-1-1-2
 * 3. 1-2-1-1
 * 4. 2-1-1-1
 * 5. 2-2-1
 * 6. 1-1-2-1
 * 7. 1-2-2
 * 8. 2-1-2
 * Ans: 8 ways
 */
public final class ClimbingStairs {

    private ClimbingStairs() {
    }

    /**
     * Calculates the no. of distinct ways to climb a staircase with n steps.
     *
     * @param n the no. of steps in the staircase (non-negative integer)
     * @return the no. of distinct ways to climb to the top
     *         - Returns 0 if n is 0 (no steps to climb).
     *         - Returns 1 if n is 1 (only one way to climb).
     *         - For n > 1, it returns the total no. of ways to climb.
     */
    public static int numberOfWays(int n) {

        // Base case: if there are no steps or only one step, return n.
        if (n == 1 || n == 0) {
            return n;
        }

        int prev = 1; // Ways to reach the step before the current one (step 1)
        int curr = 1; // Ways to reach the current step (step 2)
        int next; // Total ways to reach the next step

        for (int i = 2; i <= n; i++) { // step 2 to n
            next = curr + prev;

            // Move the pointers to the next step
            prev = curr;
            curr = next;
        }

        return curr; // Ways to reach the nth step
    }
}

/**
 * This class provides a method to compute the Two's Complement of a given binary number.
 *
 * <p>In two's complement representation, a binary number's negative value is obtained
 * by taking the one's complement (inverting all bits) and then adding 1 to the result.
 * This method handles both small and large binary strings and ensures the output is
 * correct for all binary inputs, including edge cases like all zeroes and all ones.
 *
 * <p>For more information on Two's Complement:
 * @see <a href="https://en.wikipedia.org/wiki/Two%27s_complement">Wikipedia - Two's Complement</a>
 *
 * <p>Algorithm originally suggested by Jon von Neumann.
 *
 * @author Abhinay Verma (https://github.com/Monk-AbhinayVerma)
 */
public final class TwosComplement {
private TwosComplement() {
}

/**
 * Computes the Two's Complement of the given binary string.
 * Steps:
 * 1. Compute the One's Complement (invert all bits).
 * 2. Add 1 to the One's Complement to get the Two's Complement.
 * 3. Iterate from the rightmost bit to the left, adding 1 and carrying over as needed.
 * 4. If a carry is still present after the leftmost bit, prepend '1' to handle overflow.
 *
 * @param binaryInput The binary number as a string (only '0' and '1' characters allowed).
 * @return The two's complement of the input binary string as a new binary string.
 * @throws IllegalArgumentException If the input contains non-binary characters.
 */
public static String twosComplement(String binaryInput) {
if (!binaryInput.matches("[01]+")) {
throw new IllegalArgumentException("Input must contain only '0' and '1'.");
}
StringBuilder invertedBits = new StringBuilder();
for (char currentBit : binaryInput.toCharArray()) {
invertedBits.append(currentBit == '0' ? '1' : '0');
}
StringBuilder twosComplementResult = new StringBuilder(invertedBits);
boolean hasCarry = true;
for (int position = invertedBits.length() - 1; position >= 0 && hasCarry; position--) {
if (invertedBits.charAt(position) == '1') {
twosComplementResult.setCharAt(position, '0');
} else {
twosComplementResult.setCharAt(position, '1');
hasCarry = false;
}
}
if (hasCarry) {
twosComplementResult.insert(0, '1');
}
return twosComplementResult.toString();
}
}

package forloop;
import java.util.Scanner;

public class AralikToplama {

    // Verilen araliktaki (a'dan b'ye kadar) sayilarin toplamini hesaplayan metot
    public static void aralikTopla(int a, int b) {
        int toplam = 0; // Toplam degiskeni baslatilir
        for (int i = a; i <= b; i++) { // a'dan b'ye kadar olan sayilar donguyle eklenir
            toplam += i; // Her sayi toplam degiskenine eklenir
        }
        // Toplam sonucu ekrana yazdirilir
        System.out.println(a + " ile " + b + " arasindaki sayilarin toplami: " + toplam);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Kullanicidan baslangic degeri (a) alinir
        System.out.print("Baslangic degerini girin (a): ");
        int a = scanner.nextInt();

        // Kullanicidan bitis degeri (b) alinir
        System.out.print("Bitis degerini girin (b): ");
        int b = scanner.nextInt();

        // aralikTopla metodu cagrilarak verilen araliktaki sayilarin toplami hesaplanir
        if(a < b) {
        	aralikTopla(a, b);
        }
        else {
        	aralikTopla(b, a);
        }

        // Scanner kapatilir
        scanner.close();
    }
}

public class LargeStringExample {
    public static void main(String[] args) {

        // constructor 1
        StringBuffer sb = new StringBuffer();
        System.out.println(sb.capacity());

        //constructor 2
        StringBuffer sb2 = new StringBuffer("Ankan Chatterjee");

        //constructor 3
        StringBuffer sb3 = new StringBuffer(30);
        System.out.println(sb3.capacity());

        sb.append("WeMakeDevs");
        sb.append(" is nice");
//        sb.insert(2, " Ankan ");
        sb.replace(1, 5, " Chatterjee "); // end integer is not inclusive
        sb.delete(1, 5); // end integer is not inclusive

        String str = sb.toString();
        System.out.println(str);

        /* What is StringBuffer class?
            Mutable sequence of characters
            Advantages over String
            --> Mutable
            --> More Efficient because we don't have to make objects again and again
            --> Thread safe
            ** String Builder is not thread-safe but it is faster
         */
        int n = 20;
        String name = generate(n);
        System.out.println(name);

        // removing whitespaces

        String sentence = "Hi   my  name is    Ankan";
        System.out.println(sentence);
        System.out.println(sentence.replaceAll("\\s", ""));

        // split

        String arr = "Ankan, Apoorv, Rahul, Snehal";
        String[] names = arr.split(", ");
        System.out.println(Arrays.toString(names));

        // rounding off
        DecimalFormat df = new DecimalFormat("0.0000");
        System.out.println(df.format(7.29));
    }
}

