package com.thealgorithms.conversions;

import java.util.Arrays;

/**
 * The RGB color model is an additive color model in which red, green, and blue
 * light are added together in various ways to reproduce a broad array of
 * colors. The name of the model comes from the initials of the three additive
 * primary colors, red, green, and blue. Meanwhile, the HSV representation
 * models how colors appear under light. In it, colors are represented using
 * three components: hue, saturation and (brightness-)value. This class provides
 * methods for converting colors from one representation to the other.
 * (description adapted from <a href="https://en.wikipedia.org/wiki/RGB_color_model">[1]</a> and
 * <a href="https://en.wikipedia.org/wiki/HSL_and_HSV">[2]</a>).
 */
public final class RgbHsvConversion {
private RgbHsvConversion() {
}

public static void main(String[] args) {
assert Arrays.equals(hsvToRgb(0, 0, 0), new int[] {0, 0, 0});
assert Arrays.equals(hsvToRgb(0, 0, 1), new int[] {255, 255, 255});
assert Arrays.equals(hsvToRgb(0, 1, 1), new int[] {255, 0, 0});
assert Arrays.equals(hsvToRgb(60, 1, 1), new int[] {255, 255, 0});
assert Arrays.equals(hsvToRgb(120, 1, 1), new int[] {0, 255, 0});
assert Arrays.equals(hsvToRgb(240, 1, 1), new int[] {0, 0, 255});
assert Arrays.equals(hsvToRgb(300, 1, 1), new int[] {255, 0, 255});
assert Arrays.equals(hsvToRgb(180, 0.5, 0.5), new int[] {64, 128, 128});
assert Arrays.equals(hsvToRgb(234, 0.14, 0.88), new int[] {193, 196, 224});
assert Arrays.equals(hsvToRgb(330, 0.75, 0.5), new int[] {128, 32, 80});
assert approximatelyEqualHsv(rgbToHsv(0, 0, 0), new double[] {0, 0, 0});
assert approximatelyEqualHsv(rgbToHsv(255, 255, 255), new double[] {0, 0, 1});
assert approximatelyEqualHsv(rgbToHsv(255, 0, 0), new double[] {0, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(255, 255, 0), new double[] {60, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(0, 255, 0), new double[] {120, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(0, 0, 255), new double[] {240, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(255, 0, 255), new double[] {300, 1, 1});
assert approximatelyEqualHsv(rgbToHsv(64, 128, 128), new double[] {180, 0.5, 0.5});
assert approximatelyEqualHsv(rgbToHsv(193, 196, 224), new double[] {234, 0.14, 0.88});
assert approximatelyEqualHsv(rgbToHsv(128, 32, 80), new double[] {330, 0.75, 0.5});
}

/**
 * Conversion from the HSV-representation to the RGB-representation.
 *
 * @param hueValue Hue of the color.
 * @param saturationValue Saturation of the color.
 * @param brightnessValue Brightness-value of the color.
 * @return The tuple of RGB-components.
 */
public static int[] hsvToRgb(double hueValue, double saturationValue, double brightnessValue) {
if (hueValue < 0 || hueValue > 360) {
throw new IllegalArgumentException("hue should be between 0 and 360");
}
if (saturationValue < 0 || saturationValue > 1) {
throw new IllegalArgumentException("saturation should be between 0 and 1");
}
if (brightnessValue < 0 || brightnessValue > 1) {
throw new IllegalArgumentException("value should be between 0 and 1");
}
double chromaAmount = brightnessValue * saturationValue;
double hueSegment = hueValue / 60;
double secondaryComponent = chromaAmount * (1 - Math.abs(hueSegment % 2 - 1));
double brightnessOffset = brightnessValue - chromaAmount;
return getRgbFromSegment(hueSegment, chromaAmount, brightnessOffset, secondaryComponent);
}

/**
 * Conversion from the RGB-representation to the HSV-representation.
 *
 * @param redValue Red-component of the color.
 * @param greenValue Green-component of the color.
 * @param blueValue Blue-component of the color.
 * @return The tuple of HSV-components.
 */
public static double[] rgbToHsv(int redValue, int greenValue, int blueValue) {
if (redValue < 0 || redValue > 255) {
throw new IllegalArgumentException("red should be between 0 and 255");
}
if (greenValue < 0 || greenValue > 255) {
throw new IllegalArgumentException("green should be between 0 and 255");
}
if (blueValue < 0 || blueValue > 255) {
throw new IllegalArgumentException("blue should be between 0 and 255");
}
double normalizedRed = (double) redValue / 255;
double normalizedGreen = (double) greenValue / 255;
double normalizedBlue = (double) blueValue / 255;
double maxComponent = Math.max(Math.max(normalizedRed, normalizedGreen), normalizedBlue);
double minComponent = Math.min(Math.min(normalizedRed, normalizedGreen), normalizedBlue);
double chromaDifference = maxComponent - minComponent;
double saturationResult = maxComponent == 0 ? 0 : chromaDifference / maxComponent;
double hueResult;
if (chromaDifference == 0) {
hueResult = 0;
} else if (maxComponent == normalizedRed) {
hueResult = 60 * (0 + (normalizedGreen - normalizedBlue) / chromaDifference);
} else if (maxComponent == normalizedGreen) {
hueResult = 60 * (2 + (normalizedBlue - normalizedRed) / chromaDifference);
} else {
hueResult = 60 * (4 + (normalizedRed - normalizedGreen) / chromaDifference);
}
hueResult = (hueResult + 360) % 360;
return new double[] {hueResult, saturationResult, maxComponent};
}

private static boolean approximatelyEqualHsv(double[] hsvFirst, double[] hsvSecond) {
boolean hueMatch = Math.abs(hsvFirst[0] - hsvSecond[0]) < 0.2;
boolean saturationMatch = Math.abs(hsvFirst[1] - hsvSecond[1]) < 0.002;
boolean valueMatch = Math.abs(hsvFirst[2] - hsvSecond[2]) < 0.002;
return hueMatch && saturationMatch && valueMatch;
}

private static int[] getRgbFromSegment(double hueSegment, double chromaAmount, double brightnessOffset, double secondaryComponent) {
int redChannel, greenChannel, blueChannel;
if (hueSegment >= 0 && hueSegment <= 1) {
redChannel = convertToInt(chromaAmount + brightnessOffset);
greenChannel = convertToInt(secondaryComponent + brightnessOffset);
blueChannel = convertToInt(brightnessOffset);
} else if (hueSegment > 1 && hueSegment <= 2) {
redChannel = convertToInt(secondaryComponent + brightnessOffset);
greenChannel = convertToInt(chromaAmount + brightnessOffset);
blueChannel = convertToInt(brightnessOffset);
} else if (hueSegment > 2 && hueSegment <= 3) {
redChannel = convertToInt(brightnessOffset);
greenChannel = convertToInt(chromaAmount + brightnessOffset);
blueChannel = convertToInt(secondaryComponent + brightnessOffset);
} else if (hueSegment > 3 && hueSegment <= 4) {
redChannel = convertToInt(brightnessOffset);
greenChannel = convertToInt(secondaryComponent + brightnessOffset);
blueChannel = convertToInt(chromaAmount + brightnessOffset);
} else if (hueSegment > 4 && hueSegment <= 5) {
redChannel = convertToInt(secondaryComponent + brightnessOffset);
greenChannel = convertToInt(brightnessOffset);
blueChannel = convertToInt(chromaAmount + brightnessOffset);
} else {
redChannel = convertToInt(chromaAmount + brightnessOffset);
greenChannel = convertToInt(brightnessOffset);
blueChannel = convertToInt(secondaryComponent + brightnessOffset);
}
return new int[] {redChannel, greenChannel, blueChannel};
}

private static int convertToInt(double valueToConvert) {
return (int) Math.round(255 * valueToConvert);
}
}

import java.util.Arrays;

public class BinarySearchDemo {
    /**
     * Performs binary search on a sorted array.
     * @param arr sorted array to search
     * @param target value to find
     * @return index of target, or -1 if not found
     */
    public static int binarySearch(int[] arr, int target) {
        int left = 0;
        int right = arr.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] == target) {
                return mid;
            } else if (arr[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] data = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
        System.out.println("Index of 23: " + binarySearch(data, 23));
        System.out.println("Index of 40: " + binarySearch(data, 40));
    }
}

/**
 * Java program that implements Tarjan's Algorithm to find Strongly Connected Components (SCCs) in a directed graph.
 *
 * <p>
 * Tarjan's algorithm is a linear time algorithm (O(V + E)) that identifies the SCCs of a directed graph.
 * An SCC is a maximal subgraph where every vertex is reachable from every other vertex within the subgraph.
 *
 * <h3>Algorithm Overview:</h3>
 * <ul>
 * <li>DFS Search: A depth-first search (DFS) is performed on the graph to generate a DFS tree.</li>
 * <li>Identification of SCCs: SCCs correspond to subtrees within this DFS tree.</li>
 * <li>Low-Link Values: For each node, a low-link value is maintained, which indicates the earliest visited
 * vertex (the one with the minimum insertion time) that can be reached from that subtree.</li>
 * <li>Stack Usage: Nodes are stored in a stack during DFS. When an SCC is identified, nodes are popped from
 * the stack until the head of the SCC is reached.</li>
 * </ul>
 *
 * <p>
 * Example of a directed graph:
 * <pre>
 *  0 --------> 1 -------> 3 --------> 4
 *  ^          /
 *  |         /
 *  |        /
 *  |       /
 *  |      /
 *  |     /
 *  |    /
 *  |   /
 *  |  /
 *  | /
 *  V
 *  2
 * </pre>
 *
 * <p>
 * For the above graph, the SCC list is as follows:
 * <ul>
 * <li>1, 2, 0</li>
 * <li>3</li>
 * <li>4</li>
 * </ul>
 * The order of nodes in an SCC does not matter as they form cycles.
 *
 * <h3>Comparison with Kosaraju's Algorithm:</h3>
 * <p>
 * Kosaraju's algorithm also identifies SCCs but does so using two DFS traversals.
 * In contrast, Tarjan's algorithm achieves this in a single DFS traversal, leading to improved performance
 * in terms of constant factors.
 * </p>
 */
public class TarjansAlgorithm {

    // Timer for tracking low time and insertion time
    private int time;

    // List to store all strongly connected components
    private final List<List<Integer>> sccList = new ArrayList<>();

    /**
     * Finds and returns the strongly connected components (SCCs) of the directed graph.
     *
     * @param v the number of vertices in the graph
     * @param graph the adjacency list representation of the graph
     * @return a list of lists, where each inner list represents a strongly connected component
     */
    public List<List<Integer>> stronglyConnectedComponents(int v, List<List<Integer>> graph) {
        // Initialize arrays for insertion time and low-link values
        int[] lowTime = new int[v];
        int[] insertionTime = new int[v];
        for (int i = 0; i < v; i++) {
            insertionTime[i] = -1;
            lowTime[i] = -1;
        }

        // Track if vertices are in the stack
        boolean[] isInStack = new boolean[v];

        // Stack to hold nodes during DFS
        Stack<Integer> st = new Stack<>();

        for (int i = 0; i < v; i++) {
            if (insertionTime[i] == -1) {
                stronglyConnCompsUtil(i, lowTime, insertionTime, isInStack, st, graph);
            }
        }

        return sccList;
    }

    /**
     * A utility function to perform DFS and find SCCs.
     *
     * @param u the current vertex being visited
     * @param lowTime array to keep track of the low-link values
     * @param insertionTime array to keep track of the insertion times
     * @param isInStack boolean array indicating if a vertex is in the stack
     * @param st the stack used for DFS
     * @param graph the adjacency list representation of the graph
     */
    private void stronglyConnCompsUtil(int u, int[] lowTime, int[] insertionTime, boolean[] isInStack, Stack<Integer> st, List<List<Integer>> graph) {
        // Set insertion time and low-link value
        insertionTime[u] = time;
        lowTime[u] = time;
        time++;

        // Push current node onto the stack
        isInStack[u] = true;
        st.push(u);

        // Explore adjacent vertices
        for (Integer vertex : graph.get(u)) {
            if (insertionTime[vertex] == -1) {
                stronglyConnCompsUtil(vertex, lowTime, insertionTime, isInStack, st, graph);
                // Update low-link value
                lowTime[u] = Math.min(lowTime[u], lowTime[vertex]);
            } else if (isInStack[vertex]) {
                // Vertex is in the stack; update low-link value
                lowTime[u] = Math.min(lowTime[u], insertionTime[vertex]);
            }
        }

        // Check if the current vertex is the root of an SCC
        if (lowTime[u] == insertionTime[u]) {
            int w = -1;
            List<Integer> scc = new ArrayList<>();

            // Pop vertices from the stack until the root is found
            while (w != u) {
                w = st.pop();
                scc.add(w);
                isInStack[w] = false;
            }
            sccList.add(scc);
        }
    }
}

package com.thealgorithms.ciphers;

/**
 * This class is build to demonstrate the application of the DES-algorithm
 * (https://en.wikipedia.org/wiki/Data_Encryption_Standard) on a plain English message. The supplied
 * key must be in form of a 64 bit binary String.
 */
public class DES {

private String secretKey;
private final String[] roundSubKeys;

private void validateKey(String keyData) {
int keyLength = keyData.length();
if (keyLength != 64) {
throw new IllegalArgumentException("DES key must be supplied as a 64 character binary string");
}
}

DES(String keyData) {
validateKey(keyData);
this.secretKey = keyData;
roundSubKeys = generateSubKeys(keyData);
}

public String getKey() {
return this.secretKey;
}

public void setKey(String keyData) {
validateKey(keyData);
this.secretKey = keyData;
}

private static final int[] PC1_TABLE = {57, 49, 41, 33, 25, 17, 9, 1, 58, 50, 42, 34, 26, 18, 10, 2, 59, 51, 43, 35, 27, 19, 11, 3, 60, 52, 44, 36, 63, 55, 47, 39, 31, 23, 15, 7, 62, 54, 46, 38, 30, 22, 14, 6, 61, 53, 45, 37, 29, 21, 13, 5, 28, 20, 12, 4};

private static final int[] KEY_SHIFT_AMOUNTS = {1, 1, 2, 2, 2, 2, 2, 2, 1, 2, 2, 2, 2, 2, 2, 1};

private static final int[] PC2_TABLE = {14, 17, 11, 24, 1, 5, 3, 28, 15, 6, 21, 10, 23, 19, 12, 4, 26, 8, 16, 7, 27, 20, 13, 2, 41, 52, 31, 37, 47, 55, 30, 40, 51, 45, 33, 48, 44, 49, 39, 56, 34, 53, 46, 42, 50, 36, 29, 32};

private static final int[] IP_TABLE = {58, 50, 42, 34, 26, 18, 10, 2, 60, 52, 44, 36, 28, 20, 12, 4, 62, 54, 46, 38, 30, 22, 14, 6, 64, 56, 48, 40, 32, 24, 16, 8, 57, 49, 41, 33, 25, 17, 9, 1, 59, 51, 43, 35, 27, 19, 11, 3, 61, 53, 45, 37, 29, 21, 13, 5, 63, 55, 47, 39, 31, 23, 15, 7};

private static final int[] EXPANSION_TABLE = {32, 1, 2, 3, 4, 5, 4, 5, 6, 7, 8, 9, 8, 9, 10, 11, 12, 13, 12, 13, 14, 15, 16, 17, 16, 17, 18, 19, 20, 21, 20, 21, 22, 23, 24, 25, 24, 25, 26, 27, 28, 29, 28, 29, 30, 31, 32, 1};

private static final int[][] S1_BOX = {{14, 4, 13, 1, 2, 15, 11, 8, 3, 10, 6, 12, 5, 9, 0, 7}, {0, 15, 7, 4, 14, 2, 13, 1, 10, 6, 12, 11, 9, 5, 3, 8}, {4, 1, 14, 8, 13, 6, 2, 11, 15, 12, 9, 7, 3, 10, 5, 0}, {15, 12, 8, 2, 4, 9, 1, 7, 5, 11, 3, 14, 10, 0, 6, 13}};

private static final int[][] S2_BOX = {{15, 1, 8, 14, 6, 11, 3, 4, 9, 7, 2, 13, 12, 0, 5, 10}, {3, 13, 4, 7, 15, 2, 8, 14, 12, 0, 1, 10, 6, 9, 11, 5}, {0, 14, 7, 11, 10, 4, 13, 1, 5, 8, 12, 6, 9, 3, 2, 15}, {13, 8, 10, 1, 3, 15, 4, 2, 11, 6, 7, 12, 0, 5, 14, 9}};

private static final int[][] S3_BOX = {{10, 0, 9, 14, 6, 3, 15, 5, 1, 13, 12, 7, 11, 4, 2, 8}, {13, 7, 0, 9, 3, 4, 6, 10, 2, 8, 5, 14, 12, 11, 15, 1}, {13, 6, 4, 9, 8, 15, 3, 0, 11, 1, 2, 12, 5, 10, 14, 7}, {1, 10, 13, 0, 6, 9, 8, 7, 4, 15, 14, 3, 11, 5, 2, 12}};

private static final int[][] S4_BOX = {{7, 13, 14, 3, 0, 6, 9, 10, 1, 2, 8, 5, 11, 12, 4, 15}, {13, 8, 11, 5, 6, 15, 0, 3, 4, 7, 2, 12, 1, 10, 14, 9}, {10, 6, 9, 0, 12, 11, 7, 13, 15, 1, 3, 14, 5, 2, 8, 4}, {3, 15, 0, 6, 10, 1, 13, 8, 9, 4, 5, 11, 12, 7, 2, 14}};

private static final int[][] S5_BOX = {{2, 12, 4, 1, 7, 10, 11, 6, 8, 5, 3, 15, 13, 0, 14, 9}, {14, 11, 2, 12, 4, 7, 13, 1, 5, 0, 15, 10, 3, 9, 8, 6}, {4, 2, 1, 11, 10, 13, 7, 8, 15, 9, 12, 5, 6, 3, 0, 14}, {11, 8, 12, 7, 1, 14, 2, 13, 6, 15, 0, 9, 10, 4, 5, 3}};

private static final int[][] S6_BOX = {{12, 1, 10, 15, 9, 2, 6, 8, 0, 13, 3, 4, 14, 7, 5, 11}, {10, 15, 4, 2, 7, 12, 9, 5, 6, 1, 13, 14, 0, 11, 3, 8}, {9, 14, 15, 5, 2, 8, 12, 3, 7, 0, 4, 10, 1, 13, 11, 6}, {4, 3, 2, 12, 9, 5, 15, 10, 11, 14, 1, 7, 6, 0, 8, 13}};

private static final int[][] S7_BOX = {{4, 11, 2, 14, 15, 0, 8, 13, 3, 12, 9, 7, 5, 10, 6, 1}, {13, 0, 11, 7, 4, 9, 1, 10, 14, 3, 5, 12, 2, 15, 8, 6}, {1, 4, 11, 13, 12, 3, 7, 14, 10, 15, 6, 8, 0, 5, 9, 2}, {6, 11, 13, 8, 1, 4, 10, 7, 9, 5, 0, 15, 14, 2, 3, 12}};

private static final int[][] S8_BOX = {{13, 2, 8, 4, 6, 15, 11, 1, 10, 9, 3, 14, 5, 0, 12, 7}, {1, 15, 13, 8, 10, 3, 7, 4, 12, 5, 6, 11, 0, 14, 9, 2}, {7, 11, 4, 1, 9, 12, 14, 2, 0, 6, 10, 13, 15, 3, 5, 8}, {2, 1, 14, 7, 4, 10, 8, 13, 15, 12, 9, 0, 3, 5, 6, 11}};

private static final int[][][] ALL_S_BOXES = {S1_BOX, S2_BOX, S3_BOX, S4_BOX, S5_BOX, S6_BOX, S7_BOX, S8_BOX};

static final int[] PERMUTATION_TABLE = {16, 7, 20, 21, 29, 12, 28, 17, 1, 15, 23, 26, 5, 18, 31, 10, 2, 8, 24, 14, 32, 27, 3, 9, 19, 13, 30, 6, 22, 11, 4, 25};

static final int[] IP_INVERSE_TABLE = {40, 8, 48, 16, 56, 24, 64, 32, 39, 7, 47, 15, 55, 23, 63, 31, 38, 6, 46, 14, 54, 22, 62, 30, 37, 5, 45, 13, 53, 21, 61, 29, 36, 4, 44, 12, 52, 20, 60, 28, 35, 3, 43, 11, 51, 19, 59, 27, 34, 2, 42, 10, 50, 18, 58, 26, 33, 1, 41, 9, 49, 17, 57, 25};

private String[] generateSubKeys(String originalKeyData) {
StringBuilder permutedKey = new StringBuilder();
for (int position = 0; position < 56; position++) {
permutedKey.append(originalKeyData.charAt(PC1_TABLE[position] - 1));
}
String[] subKeyArray = new String[16];
String currentKey = permutedKey.toString();
String leftHalf = currentKey.substring(0, 28);
String rightHalf = currentKey.substring(28);
for (int round = 0; round < 16; round++) {
leftHalf = leftHalf.substring(KEY_SHIFT_AMOUNTS[round]) + leftHalf.substring(0, KEY_SHIFT_AMOUNTS[round]);
rightHalf = rightHalf.substring(KEY_SHIFT_AMOUNTS[round]) + rightHalf.substring(0, KEY_SHIFT_AMOUNTS[round]);
subKeyArray[round] = leftHalf + rightHalf;
}
for (int round = 0; round < 16; round++) {
StringBuilder compressedKey = new StringBuilder();
String roundKey = subKeyArray[round];
for (int index = 0; index < 48; index++) {
compressedKey.append(roundKey.charAt(PC2_TABLE[index] - 1));
}
subKeyArray[round] = compressedKey.toString();
}
return subKeyArray;
}

private String xorBits(String firstValue, String secondValue) {
StringBuilder xorResult = new StringBuilder();
for (int position = 0; position < firstValue.length(); position++) {
int bitA = firstValue.charAt(position) - 48;
int bitB = secondValue.charAt(position) - 48;
xorResult.append((bitA ^ bitB));
}
return xorResult.toString();
}

private String padLeft(String sourceText, int targetLength) {
return "0".repeat(targetLength - sourceText.length()) + sourceText;
}

private String padRight(String sourceText, int targetLength) {
return sourceText + "\0".repeat(targetLength - sourceText.length());
}

private String applyFeistel(String blockData, String roundKey) {
StringBuilder expandedBlock = new StringBuilder();
for (int position = 0; position < 48; position++) {
expandedBlock.append(blockData.charAt(EXPANSION_TABLE[position] - 1));
}
String mixedData = xorBits(expandedBlock.toString(), roundKey);
StringBuilder substitutedData = new StringBuilder();
for (int segment = 0; segment < 48; segment += 6) {
String sixBitSegment = mixedData.substring(segment, segment + 6);
int rowValue = (sixBitSegment.charAt(0) - 48) * 2 + (sixBitSegment.charAt(5) - 48);
int colValue = (sixBitSegment.charAt(1) - 48) * 8 + (sixBitSegment.charAt(2) - 48) * 4 + (sixBitSegment.charAt(3) - 48) * 2 + (sixBitSegment.charAt(4) - 48);
String substitutedSegment = padLeft(Integer.toBinaryString(ALL_S_BOXES[segment / 6][rowValue][colValue]), 4);
substitutedData.append(substitutedSegment);
}
StringBuilder permutedData = new StringBuilder();
for (int position = 0; position < 32; position++) {
permutedData.append(substitutedData.charAt(PERMUTATION_TABLE[position] - 1));
}
return permutedData.toString();
}

private String processBlock(String inputBlock, String[] keySchedule) {
StringBuilder permutedBlock = new StringBuilder();
for (int position = 0; position < 64; position++) {
permutedBlock.append(inputBlock.charAt(IP_TABLE[position] - 1));
}
String leftPart = permutedBlock.substring(0, 32);
String rightPart = permutedBlock.substring(32);
for (int round = 0; round < 16; round++) {
String nextLeft = rightPart;
String nextRight = xorBits(leftPart, applyFeistel(rightPart, keySchedule[round]));
leftPart = nextLeft;
rightPart = nextRight;
}
String combinedBlock = rightPart + leftPart;
permutedBlock.setLength(0);
for (int position = 0; position < 64; position++) {
permutedBlock.append(combinedBlock.charAt(IP_INVERSE_TABLE[position] - 1));
}
return permutedBlock.toString();
}

private String decodeBlock(String inputBlock, String[] keySchedule) {
String[] reversedKeys = new String[keySchedule.length];
for (int index = 0; index < keySchedule.length; index++) {
reversedKeys[index] = keySchedule[keySchedule.length - index - 1];
}
return processBlock(inputBlock, reversedKeys);
}

/**
 * @param message Message to be encrypted
 * @return The encrypted message, as a binary string
 */
public String encrypt(String sourceMessage) {
StringBuilder encryptedOutput = new StringBuilder();
int messageLength = sourceMessage.length();
if (messageLength % 8 != 0) {
int targetLength = (messageLength / 8 + 1) * 8;
sourceMessage = padRight(sourceMessage, targetLength);
messageLength = targetLength;
}
for (int blockStart = 0; blockStart < messageLength; blockStart += 8) {
String textSegment = sourceMessage.substring(blockStart, blockStart + 8);
StringBuilder binarySegment = new StringBuilder();
byte[] byteData = textSegment.getBytes();
for (int bytePos = 0; bytePos < 8; bytePos++) {
binarySegment.append(padLeft(Integer.toBinaryString(byteData[bytePos] & 0xFF), 8));
}
encryptedOutput.append(processBlock(binarySegment.toString(), roundSubKeys));
}
return encryptedOutput.toString();
}

/**
 * @param message The encrypted string. Expects it to be a multiple of 64 bits, in binary format
 * @return The decrypted String, in plain English
 */
public String decrypt(String encryptedData) {
StringBuilder decryptedOutput = new StringBuilder();
int dataLength = encryptedData.length();
if (dataLength % 64 != 0) {
throw new IllegalArgumentException("Encrypted message should be a multiple of 64 characters in length");
}
for (int blockStart = 0; blockStart < dataLength; blockStart += 64) {
String blockSegment = encryptedData.substring(blockStart, blockStart + 64);
String decodedSegment = decodeBlock(blockSegment, roundSubKeys);
byte[] byteBuffer = new byte[8];
for (int bytePos = 0; bytePos < 64; bytePos += 8) {
byteBuffer[bytePos / 8] = (byte) Integer.parseInt(decodedSegment.substring(bytePos, bytePos + 8), 2);
}
decryptedOutput.append(new String(byteBuffer));
}
return decryptedOutput.toString().replace("\0", "");
}
}

// Digital Root: Bir sayinin basamaklarini tekrarli olarak toplar ve tek bir basamak kalana kadar devam eder.
package whileloop;

import java.util.Scanner;

public class DijitalKok {

    public static void main(String[] args) {

        // Kullanicidan bir sayi girdisi al
        Scanner tarayici = new Scanner(System.in);
        System.out.print("Bir sayi giriniz: ");
        int sayi = tarayici.nextInt();

        // Dijital kok hesaplama
        int dijitalKok = sayi;

        // Tek basamak kalana kadar dongu
        while (dijitalKok >= 10) {
            int gecici = dijitalKok; // Gecici degisken
            int toplam = 0; // Basamak toplami

            // Basamaklari toplama islemi
            while (gecici > 0) {
                toplam += gecici % 10; // Son basamagi toplama ekle
                gecici /= 10; // Son basamagi cikar
            }

            dijitalKok = toplam; // Yeni dijital kok degerini guncelle
        }

        // Sonuc yazdir
        System.out.println("Dijital kok: " + dijitalKok);

        tarayici.close(); // Kaynaklari serbest birak
    }
}

package syntax;

public class AtamaIslemleri {

    public static void main(String[] args) {
        // Atama islemleri
        int x = 5; // x degiskenine 5 atandi
        int y = 10; // y degiskenine 10 atandi
        int z = 15; // z degiskenine 15 atandi

        // Toplama ve atama
        x = x + y; // x, x ve y'nin toplamina esit olur
        System.out.println("Toplama ve Atama: x = " + x + " y = " + y); // x simdi 15

        // Cikarma ve atama
        x -= y; // x, x ve y'nin farkina esit olur
        System.out.println("Cikarma ve Atama: x = " + x + " y = " + y); // x simdi 5

        // Carpma ve atama
        x *= 2; // x, x'in 2 ile carpimina esit olur
        System.out.println("Carpma ve Atama: x = " + x + " y = " + y); // x simdi 10

        // Bolme ve atama
        x /= 4; // x, x'in 4'e bolumune esit olur
        System.out.println("Bolme ve Atama: x = " + x + " y = " + y); // x simdi 2

        // Modul (Kalan) ve atama
        x %= 3; // x, x'in 3'e bolumunden kalanina esit olur
        System.out.println("Mod ve Atama: x = " + x + " y = " + y); // x simdi 2 % 3 = 2

        // x'in z ile toplanmasi
        x += z; // x, x ve z'nin toplamina esit olur
        System.out.println("Toplama ve Atama (x + z): x = " + x + " z = " + z); // x simdi 17

        // x'in z ile carpimi
        x *= z; // x, x ve z'nin carpimina esit olur
        System.out.println("Carpma ve Atama (x * z): x = " + x + " z = " + z); // x simdi 255

        // z'nin x'e bolunmesi
        x = z / x; // z'nin x'e bolumune esit olur
        System.out.println("Bolme ve Atama (z / x): x = " + x + " z = " + z); // x simdi 0

        // y'nin x'e bolumunden kalan
        x = y % (x + 1); // y'nin x'e bolumunden kalan
        System.out.println("Mod ve Atama (y % (x + 1)): x = " + x + " y = " + y); // x simdi 0

        // y'nin x'e eklenmesi
        x = 10; // x'i 10'a ayarla
        y += x; // y, y ve x'in toplamina esit olur
        System.out.println("Toplama ve Atama (y + x): x = " + x + " y = " + y); // y simdi 20

        // y'nin x'e bolunmesi
        y /= x; // y, y'nin x'e bolumune esit olur
        System.out.println("Bolme ve Atama (y / x): x = " + x + " y = " + y); // y simdi 2

        // x'in negatif degeri
        x = -x; // x'in negatif degeri
        System.out.println("Negatif deger: x = " + x); // x simdi -10
    }
}

