package com.thealgorithms.conversions;

/**
 * A utility class to perform affine transformations of the form:
 * transformedValue = slopeValue * originalValue + interceptValue.
 *
 * This class supports inversion and composition of affine transformations.
 * It is immutable, meaning each instance represents a fixed transformation.
 */
public final class AffineConverter {
private final double slopeValue;
private final double interceptValue;

/**
 * Constructs an AffineConverter with the given slope and intercept.
 *
 * @param inputSlope The slope of the affine transformation.
 * @param inputIntercept The intercept (constant term) of the affine transformation.
 * @throws IllegalArgumentException if either parameter is NaN.
 */
public AffineConverter(final double inputSlope, final double inputIntercept) {
if (Double.isNaN(inputSlope) || Double.isNaN(inputIntercept)) {
throw new IllegalArgumentException("Slope and intercept must be valid numbers.");
}
slopeValue = inputSlope;
interceptValue = inputIntercept;
}

/**
 * Converts the given input value using the affine transformation:
 * result = slopeValue * inputValue + interceptValue.
 *
 * @param inputValue The input value to convert.
 * @return The transformed value.
 */
public double convert(final double inputValue) {
return slopeValue * inputValue + interceptValue;
}

/**
 * Returns a new AffineConverter representing the inverse of the current transformation.
 * The inverse of transformedValue = slopeValue * originalValue + interceptValue
 * is originalValue = (transformedValue - interceptValue) / slopeValue.
 *
 * @return A new AffineConverter representing the inverse transformation.
 * @throws AssertionError if the slope is zero, as the inverse would be undefined.
 */
public AffineConverter invert() {
assert slopeValue != 0.0 : "Slope cannot be zero for inversion.";
return new AffineConverter(1.0 / slopeValue, -interceptValue / slopeValue);
}

/**
 * Composes this affine transformation with another, returning a new AffineConverter.
 * If this transformation is f(x) and the other is g(x), the result is f(g(x)).
 *
 * @param otherTransform Another AffineConverter to compose with.
 * @return A new AffineConverter representing the composition of the two transformations.
 */
public AffineConverter compose(final AffineConverter otherTransform) {
double combinedSlope = slopeValue * otherTransform.slopeValue;
double combinedIntercept = slopeValue * otherTransform.interceptValue + interceptValue;
return new AffineConverter(combinedSlope, combinedIntercept);
}
}

package objects;

public class DijitalSaat {

	private int saat = 0;         // Saat degerini tutar
	private int dakika = 0;       // Dakika degerini tutar
	private int saniye = 0;       // Saniye degerini tutar

	// Saniye degerini donduren metod
	public int getSaniye() {
		return this.saniye;
	}

	// Saniye degerini ayarlayan metod (0-59 arasinda olmali)
	public void setSaniye(int saniye) {
		if(saniye >= 0 && saniye < 60) {
			this.saniye = saniye;
		}
	}

	// Saati, dakikayi ve saniyeyi gosteren metod
	public void goster() {
		System.out.println(saat + ":" + dakika + ":" + saniye);
	}

	// Saati arttiran metod (0-23 arasinda doner)
	private void saatiArttir() {
		saat++;
		if(saat > 23) {
			saat = 0;   // Saat 23'ten sonra 0'a doner
		}
	}

	// Dakikayi arttiran metod (0-59 arasinda doner)
	private void dakikayiArttir() {
		dakika++;
		if(dakika > 59) {
			dakika = 0;  // Dakika 59'dan sonra 0'a doner
			saatiArttir();  // Her dakika arttiginda saati de arttirir
		}
	}

	// Saniyeyi arttiran metod (0-59 arasinda doner)
	public void saniyeyiArttir() {
		saniye++;
		if(saniye > 59) {
			saniye = 0;   // Saniye 59'dan sonra 0'a doner
			dakikayiArttir();  // Her saniye arttiginda dakikayi arttirir
		}
	}

	// Saatin guncellenmesini saglayan metod
	public void saatiGuncelle(int saat, int dakika, int saniye) {
		this.saat = saat;
		this.dakika = dakika;
		this.saniye = saniye;
	}

	// Ana metod (main method) icinde kullanimi
	public static void main(String[] args) {
		// Dijital saat nesnesi olusturuluyor
		DijitalSaat saat = new DijitalSaat();

		// Baslangic saati, dakika ve saniye ayarlari
		saat.saatiGuncelle(10, 58, 50);
		System.out.println("Baslangic saati:");
		saat.goster();  // ilk gosterim

		// 70 saniye boyunca saniye arttirma islemi
		for(int i = 0; i < 70; i++) {
			saat.saniyeyiArttir();  // Saniyeyi arttir
			System.out.print("Saniye " + (i + 1) + ": ");
			saat.goster();  // Guncellenmis saati goster
		}

		// 120 saniye ekleyerek saati bir saat ileri alalim
		System.out.println("\nSaati bir saat ileri aliyoruz...");
		for(int i = 0; i < 120; i++) {
			saat.saniyeyiArttir();  // Yine saniyeleri arttir
		}
		System.out.print("Yeni saat: ");
		saat.goster();  // Guncellenmis saati goster
	}
}

package functions; 
import java.util.Scanner;  // Kullanicidan giris almak icin Scanner sinifini ice aktar

public class OgrenciNumarasi {

    // 'kayitYili' metodu, ogrenci numarasinin ilk iki hanesine bakarak kayit yilini hesaplar
    int kayitYili(int sayi) {
        // Ogrenci numarasinin ilk iki hanesini (numaranin basindaki iki rakami) alir ve 2000 ekler
        return (sayi / 10000000) + 2000;
    }

    // 'kayitSirasi' metodu, ogrenci numarasinin son uc hanesine bakarak kayit sirasi'ni dondurur
    int kayitSirasi(int sayi) {
        // Numaranin son uc rakamini almak icin 1000'e gore mod islemi yapilir
        return sayi % 1000;
    }

    // 'bolumu' metodu, ogrenci numarasindaki belirli bir haneye bakarak ogrencinin bolumunu bulur
    String bolumu(int sayi) {
        // Numaranin bolum bilgisini tutan kisimi al (numaranin sondan dorduncu hanesi)
        int bolum = (sayi / 1000) % 10;

        // Bolum numarasina gore hangi bolumde okudugunu kontrol et
        if(bolum == 7) {
            return "Elektrik Elektronik";
        } else if(bolum == 6) {
            return "Bilgisayar";
        } else if(bolum == 5) {
            return "Makina";
        } else {
            return "Bilinmiyor";  // Belirtilen numaraya uymayan bir deger icin bilinmiyor sonucu doner
        }
    }

    public static void main(String[] args) {

        // Kullanicidan giris almak icin Scanner nesnesi olustur
        Scanner okuyucu = new Scanner(System.in);

        // Kullanicidan okul numarasini girmesini iste
        System.out.println("Lutfen okul numaranizi giriniz");
        int numara = okuyucu.nextInt();  // Kullanicinin girdigi okul numarasi alinir

        numara = 230707123;

        // OgrenciNumarasi sinifindan bir nesne olustur
        OgrenciNumarasi bulucu = new OgrenciNumarasi();

        // Ogrencinin kayit yili ekrana yazdirilir
        System.out.println("Kayit yili: " + bulucu.kayitYili(numara));

        // Ogrencinin kayit sirasi ekrana yazdirilir
        System.out.println("Kayit sirasi: " + bulucu.kayitSirasi(numara));

        // Ogrencinin bolumu ekrana yazdirilir
        System.out.println("Bolum: " + bulucu.bolumu(numara));

        // Scanner nesnesini kapatiyoruz
        okuyucu.close();
    }
}

/**
 * A bouncing ball, moved and reflected by a Container.
 */
class Ball {

    private float posX;
    private float posY;
    private int radius;
    private float speedX;
    private float speedY;

    public Ball(float posX, float posY, int radius, float speedX, float speedY) {
        this.posX = posX;
        this.posY = posY;
        this.radius = radius;
        this.speedX = speedX;
        this.speedY = speedY;
    }

    public Ball(float posX, float posY, int radius, int speed, int direction) {
        this.posX = posX;
        this.posY = posY;
        this.radius = radius;
        this.speedX = speed * (float) Math.cos(Math.toRadians(direction));
        this.speedY = -speed * (float) Math.sin(Math.toRadians(direction));
    }

    public float getX() {
        return posX;
    }

    public void setX(float posX) {
        this.posX = posX;
    }

    public float getY() {
        return posY;
    }

    public void setY(float posY) {
        this.posY = posY;
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }

    public float getXDelta() {
        return speedX;
    }

    public void setXDelta(float speedX) {
        this.speedX = speedX;
    }

    public float getYDelta() {
        return speedY;
    }

    public void setYDelta(float speedY) {
        this.speedY = speedY;
    }

    public int getSpeed() {
        return (int) Math.sqrt(speedX * speedX + speedY * speedY);
    }

    public int getDirection() {
        return (int) Math.toDegrees(Math.atan2(-speedY, speedX));
    }

    public void setXY(int posX, int posY) {
        this.posX = posX;
        this.posY = posY;
    }

    public void move() {
        posX += speedX;
        posY += speedY;
    }

    public void reflectHorizontal() {
        speedX = -speedX;
    }

    public void reflectVertical() {
        speedY = -speedY;
    }

    @Override
    public String toString() {
        return "Ball[(" + posX + "," + posY + "),speed=(" + speedX + "," + speedY + ")]";
    }
}

public class Container {

    private int left;
    private int top;
    private int right;
    private int bottom;

    public Container(int left, int top, int width, int height) {
        this.left = left;
        this.top = top;
        this.right = left + width - 1;
        this.bottom = top + height - 1;
    }

    public int getX1() {
        return left;
    }

    public void setX1(int left) {
        this.left = left;
    }

    public int getY1() {
        return top;
    }

    public void setY1(int top) {
        this.top = top;
    }

    public int getX2() {
        return right;
    }

    public void setX2(int right) {
        this.right = right;
    }

    public int getY2() {
        return bottom;
    }

    public void setY2(int bottom) {
        this.bottom = bottom;
    }

    public int getX() {
        return left;
    }

    public int getY(int y2) {
        return top;
    }

    public int getWidth() {
        return right - left + 1;
    }

    public int getHeight() {
        return bottom - top + 1;
    }

    public boolean collides(Ball ball) {
        boolean hit = ball.getX() - ball.getRadius() <= left || ball.getX() - ball.getRadius() >= right;
        if (hit) {
            ball.reflectHorizontal();
        }
        return hit;
    }

    public boolean collidesWith(Ball ball) {
        boolean hit = ball.getX() - ball.getRadius() <= left || ball.getX() - ball.getRadius() >= right;
        if (hit) {
            ball.reflectHorizontal();
        }
        return hit;
    }

    @Override
    public String toString() {
        return "Container[(" + left + "," + top + "),(" + right + "," + bottom + ")]";
    }
}

class TestContainer {
    public static void main(String[] args) {
        Ball ball = new Ball(50, 50, 5, 10, 30);
        Container box = new Container(0, 0, 100, 100);
        System.out.println(box.getHeight());
        System.out.println(box.getWidth());
        for (int step = 0; step < 10; ++step) {
            ball.move();
            box.collidesWith(ball);
            System.out.println(ball);
        }
    }
}

