package com.thealgorithms.ciphers;

import java.util.Objects;

/**
 * Columnar Transposition Cipher Encryption and Decryption.
 *
 * @author <a href="https://github.com/freitzzz">freitzzz</a>
 */
public final class ColumnarTranspositionCipher {
private ColumnarTranspositionCipher() {
}

private static String encryptionKey;
private static Object[][] cipherTable;
private static String characterSet;
public static final String DEFAULT_CHARACTER_SET = "abcdefghijklmnopqrstuvwxyzABCDEFG"
+ "HIJKLMNOPQRSTUVWXYZ0123456789,.;:-@";
private static final String PLACEHOLDER_STRING = "≈";
private static final char PLACEHOLDER_CHAR = '≈';

/**
 * Encrypts a certain String with the Columnar Transposition Cipher Rule
 *
 * @param sourceWord Word being encrypted
 * @param keyValue String with keyword being used
 * @return a String with the word encrypted by the Columnar Transposition
 * Cipher Rule
 */
public static String encrypt(final String sourceWord, final String keyValue) {
encryptionKey = keyValue;
buildCharacterSet();
cipherTable = buildCipherTable(sourceWord);
Object[][] sortedTable = sortCipherTable(cipherTable);
StringBuilder encryptedResult = new StringBuilder();
for (int columnPos = 0; columnPos < sortedTable[0].length; columnPos++) {
for (int rowPos = 1; rowPos < sortedTable.length; rowPos++) {
encryptedResult.append(sortedTable[rowPos][columnPos]);
}
}
return encryptedResult.toString();
}

/**
 * Encrypts a certain String with the Columnar Transposition Cipher Rule
 *
 * @param sourceWord Word being encrypted
 * @param keyValue String with keyword being used
 * @param customCharacterSet String with the abecedarium being used. null for
 * default one
 * @return a String with the word encrypted by the Columnar Transposition
 * Cipher Rule
 */
public static String encrypt(String sourceWord, String keyValue, String customCharacterSet) {
encryptionKey = keyValue;
ColumnarTranspositionCipher.characterSet = Objects.requireNonNullElse(customCharacterSet, DEFAULT_CHARACTER_SET);
cipherTable = buildCipherTable(sourceWord);
Object[][] sortedTable = sortCipherTable(cipherTable);
StringBuilder encryptedResult = new StringBuilder();
for (int columnPos = 0; columnPos < sortedTable[0].length; columnPos++) {
for (int rowPos = 1; rowPos < sortedTable.length; rowPos++) {
encryptedResult.append(sortedTable[rowPos][columnPos]);
}
}
return encryptedResult.toString();
}

/**
 * Decrypts a certain encrypted String with the Columnar Transposition
 * Cipher Rule
 *
 * @return a String decrypted with the word encrypted by the Columnar
 * Transposition Cipher Rule
 */
public static String decrypt() {
StringBuilder decryptedResult = new StringBuilder();
for (int rowPos = 1; rowPos < cipherTable.length; rowPos++) {
for (Object cellValue : cipherTable[rowPos]) {
decryptedResult.append(cellValue);
}
}
return decryptedResult.toString().replaceAll(PLACEHOLDER_STRING, "");
}

/**
 * Builds a table with the word to be encrypted in rows by the Columnar
 * Transposition Cipher Rule
 *
 * @return An Object[][] with the word to be encrypted filled in rows and
 * columns
 */
private static Object[][] buildCipherTable(String sourceWord) {
Object[][] gridTable = new Object[getRowCount(sourceWord) + 1][encryptionKey.length()];
char[] wordChars = sourceWord.toCharArray();
gridTable[0] = getColumnOrderValues();
int charPosition = 0;
for (int rowPos = 1; rowPos < gridTable.length; rowPos++) {
for (int colPos = 0; colPos < gridTable[rowPos].length; colPos++) {
if (charPosition < wordChars.length) {
gridTable[rowPos][colPos] = wordChars[charPosition];
charPosition++;
} else {
gridTable[rowPos][colPos] = PLACEHOLDER_CHAR;
}
}
}
return gridTable;
}

/**
 * Determines the number of rows the table should have regarding the
 * Columnar Transposition Cipher Rule
 *
 * @return an int with the number of rows that the table should have in
 * order to respect the Columnar Transposition Cipher Rule.
 */
private static int getRowCount(String sourceWord) {
if (sourceWord.length() % encryptionKey.length() != 0) {
return (sourceWord.length() / encryptionKey.length()) + 1;
} else {
return sourceWord.length() / encryptionKey.length();
}
}

/**
 * @return charValues
 */
private static Object[] getColumnOrderValues() {
Object[] orderValues = new Object[encryptionKey.length()];
for (int index = 0; index < orderValues.length; index++) {
int valuePosition = characterSet.indexOf(encryptionKey.charAt(index));
orderValues[index] = valuePosition > -1 ? valuePosition : null;
}
return orderValues;
}

/**
 * @return tableSorted
 */
private static Object[][] sortCipherTable(Object[][] originalTable) {
Object[][] sortedGrid = new Object[originalTable.length][originalTable[0].length];
for (int rowPos = 0; rowPos < sortedGrid.length; rowPos++) {
System.arraycopy(originalTable[rowPos], 0, sortedGrid[rowPos], 0, sortedGrid[rowPos].length);
}
for (int colPos = 0; colPos < sortedGrid[0].length; colPos++) {
for (int nextCol = colPos + 1; nextCol < sortedGrid[0].length; nextCol++) {
if ((int) sortedGrid[0][colPos] > (int) originalTable[0][nextCol]) {
Object[] targetColumn = extractColumn(sortedGrid, sortedGrid.length, nextCol);
swapColumns(sortedGrid, nextCol, colPos, targetColumn);
}
}
}
return sortedGrid;
}

/**
 * @return columnArray
 */
private static Object[] extractColumn(Object[][] gridTable, int rowCount, int columnIndex) {
Object[] columnData = new Object[rowCount];
for (int rowPos = 0; rowPos < rowCount; rowPos++) {
columnData[rowPos] = gridTable[rowPos][columnIndex];
}
return columnData;
}

private static void swapColumns(Object[][] gridTable, int sourceCol, int targetCol, Object[] sourceColumnData) {
for (int rowPos = 0; rowPos < gridTable.length; rowPos++) {
gridTable[rowPos][targetCol] = gridTable[rowPos][sourceCol];
gridTable[rowPos][sourceCol] = sourceColumnData[rowPos];
}
}

/**
 * Creates an abecedarium with all available ascii values.
 */
private static void buildCharacterSet() {
StringBuilder tempSet = new StringBuilder();
for (int asciiValue = 0; asciiValue < 256; asciiValue++) {
tempSet.append((char) asciiValue);
}
characterSet = tempSet.toString();
}
}

package com.ankan.cloning;

public class Human implements Cloneable {
    int ageValue;
    String fullName;
    int[] dataArray;

    public Human(int ageValue, String fullName) {
        this.ageValue = ageValue;
        this.fullName = fullName;
        this.dataArray = new int[]{3, 4, 5, 6, 7};
    }

//    public Human(Human otherInstance) {
//        this.ageValue = otherInstance.ageValue;
//        this.fullName = otherInstance.fullName;
//    }

//    public Object clone() throws  CloneNotSupportedException {
//        // this is shallow copy as twin points to the original array in object ankan.
//        return super.clone();
//    }

    public Object clone() throws  CloneNotSupportedException {
        // this is deep copy implementation
        Human clonedInstance = (Human)super.clone(); // this performs shallow copy initially

        // create a deep copy of the array to avoid shared reference
        clonedInstance.dataArray = new int[clonedInstance.dataArray.length];
        for (int idx = 0; idx < clonedInstance.dataArray.length; idx++) {
            clonedInstance.dataArray[idx] = this.dataArray[idx];
        }
        return clonedInstance;
    }

}

package com.thealgorithms.datastructures.trees;

import com.thealgorithms.datastructures.trees.BinaryTree.Node;

/**
 *
 *
 * <h1>Binary Search Tree (Recursive)</h1>
 *
 * An implementation of BST recursively. In recursive implementation the checks
 * are down the tree First root is checked if not found then its children are
 * checked Binary Search Tree is a binary tree which satisfies three properties:
 * left child is less than root node, right child is grater than root node, both
 * left and right children must themselves be a BST.
 *
 * <p>
 * I have made public functions as methods and to actually implement recursive
 * approach I have used private methods
 *
 * @author [Lakhan Nad](<a href="https://github.com/Lakhan-Nad">git-Lakhan Nad</a>)
 */
public class BSTRecursive {

    /**
     * only data member is root of BST
     */
    private Node root;

    /**
     * Constructor use to initialize node as null
     */
    BSTRecursive() {
        root = null;
    }

    public Node getRoot() {
        return root;
    }

    /**
     * Recursive method to delete a data if present in BST.
     *
     * @param node the current node to search for data
     * @param data the value to be deleted
     * @return Node the updated value of root parameter after delete operation
     */
    private Node delete(Node node, int data) {
        if (node == null) {
            System.out.println("No such data present in BST.");
        } else if (node.data > data) {
            node.left = delete(node.left, data);
        } else if (node.data < data) {
            node.right = delete(node.right, data);
        } else {
            if (node.right == null && node.left == null) { // If it is leaf node
                node = null;
            } else if (node.left == null) { // If only right node is present
                Node temp = node.right;
                node.right = null;
                node = temp;
            } else if (node.right == null) { // Only left node is present
                Node temp = node.left;
                node.left = null;
                node = temp;
            } else { // both children are present
                Node temp = node.right;
                // Find leftmost child of right subtree
                while (temp.left != null) {
                    temp = temp.left;
                }
                node.data = temp.data;
                node.right = delete(node.right, temp.data);
            }
        }
        return node;
    }

    /**
     * Recursive insertion of value in BST.
     *
     * @param node to check if the data can be inserted in current node or its
     * subtree
     * @param data the value to be inserted
     * @return the modified value of the root parameter after insertion
     */
    private Node insert(Node node, int data) {
        if (node == null) {
            node = new Node(data);
        } else if (node.data > data) {
            node.left = insert(node.left, data);
        } else if (node.data < data) {
            node.right = insert(node.right, data);
        }
        return node;
    }

    /**
     * Search recursively if the given value is present in BST or not.
     *
     * @param node the current node to check
     * @param data the value to be checked
     * @return boolean if data is present or not
     */
    private boolean search(Node node, int data) {
        if (node == null) {
            return false;
        } else if (node.data == data) {
            return true;
        } else if (node.data > data) {
            return search(node.left, data);
        } else {
            return search(node.right, data);
        }
    }

    /**
     * add in BST. if the value is not already present it is inserted or else no
     * change takes place.
     *
     * @param data the value to be inserted
     */
    public void add(int data) {
        this.root = insert(this.root, data);
    }

    /**
     * If data is present in BST delete it else do nothing.
     *
     * @param data the value to be removed
     */
    public void remove(int data) {
        this.root = delete(this.root, data);
    }

    /**
     * To check if given value is present in tree or not.
     *
     * @param data the data to be found for
     */
    public boolean find(int data) {
        if (search(this.root, data)) {
            System.out.println(data + " is present in given BST.");
            return true;
        }
        System.out.println(data + " not found.");
        return false;
    }
}

