import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.List;

public class TurkceKarakterDegistirici {

    // Dosyalarin ve klasorlerin rekursif olarak kontrol edilmesi icin metod
    public static void dosyalariTarama(File klasor) {
        // Klasordeki tum dosyalari ve alt klasorleri al
        File[] dosyalar = klasor.listFiles();

        if (dosyalar != null) {
            // Her bir dosya veya klasor uzerinde islem yap
            for (File dosya : dosyalar) {
                // Eger bu bir klasorse, rekursif olarak icine gir
                if (dosya.isDirectory()) {
                    dosyalariTarama(dosya);  // Rekursif cagri
                } else if (dosya.isFile() && dosya.getName().endsWith(".java") && !dosya.getName().startsWith("Turkce")) {
                    try {
                        // Dosyanin icerigini satir satir oku
                        List<String> satirlar = Files.readAllLines(dosya.toPath(), StandardCharsets.UTF_8);
                        boolean degisiklikYapildi = false;

                        // Her satiri kontrol et
                        for (int i = 0; i < satirlar.size(); i++) {
                            String orijinalSatir = satirlar.get(i);
                            // Turkce karakterleri degistirmek icin satiri duzenle
                            String degistirilmisSatir = orijinalSatir
                                .replace("ü", "u")
                                .replace("Ü", "U")
                                .replace("ğ", "g")
                                .replace("Ğ", "G")
                                .replace("ı", "i")
                                .replace("İ", "I")
                                .replace("ş", "s")
                                .replace("Ş", "S")
                                .replace("ç", "c")
                                .replace("Ç", "C")
                                .replace("ö", "o")
                                .replace("Ö", "O");

                            // Eger satirda bir degisiklik yapildiysa
                            if (!orijinalSatir.equals(degistirilmisSatir)) {
                                satirlar.set(i, degistirilmisSatir);  // Satiri degistirdik
                                // Degisiklik yapilan satiri ekrana yazdir
                                System.out.println("Dosya: " + dosya.getAbsolutePath() + " - Satir " + (i + 1) + " degistirildi.");
                                degisiklikYapildi = true;
                            }
                        }

                        // Eger herhangi bir degisiklik yapilmissa, dosyayi guncelle
                        if (degisiklikYapildi) {
                            Files.write(dosya.toPath(), satirlar, StandardCharsets.UTF_8);
                        }
                    } catch (IOException e) {
                        // Hata durumunda ekrana hata mesaji yazdir
                        System.out.println("Hata: " + e.getMessage());
                    }
                }
            }
        }
    }

    public static void main(String[] args) {
        // Bulundugunuz dizinin bir ust dizini
        File klasor = new File(System.getProperty("user.dir")).getParentFile();
        // ust dizindeki dosyalari ve klasorleri taramak icin metodu cagir
        dosyalariTarama(klasor);
    }
}

public class YildizDeseni {

    // Birinci desenin cizimi (Piramid)
    public void cizdir1(int satirSayisi) {
        for (int i = 1; i <= satirSayisi; i++) {
            for (int j = 1; j <= satirSayisi - i; j++) {
                System.out.print(" "); // Bosluklari ekrana yazdir
            }
            for (int k = 1; k <= 2 * i - 1; k++) {
                System.out.print("*"); // Yildizlari ekrana yazdir
            }
            System.out.println(); // Yeni satira gecer
        }
    }

    // ikinci desenin cizimi (Ters Piramit)
    public void cizdir2(int satirSayisi) {
        for (int i = satirSayisi; i > 0; i--) {
            for (int j = 1; j <= satirSayisi - i; j++) {
                System.out.print(" "); // Bosluklari ekrana yazdir
            }
            for (int k = 1; k <= 2 * i - 1; k++) {
                System.out.print("*"); // Yildizlari ekrana yazdir
            }
            System.out.println(); // Yeni satira gecer
        }
    }

    // ucuncu desenin cizimi (Duz Satir Yildizlari)
    public void cizdir3(int satirSayisi) {
        for (int i = 1; i <= satirSayisi; i++) {
            for (int j = 1; j <= satirSayisi; j++) {
                System.out.print("* "); // Yildizlari ekrana yazdir
            }
            System.out.println(); // Yeni satira gecer
        }
    }

    // Dorduncu desenin cizimi (cift Yonlu Piramit)
    public void cizdir4(int satirSayisi) {
        for (int i = 1; i <= satirSayisi; i++) {
            for (int j = 1; j <= satirSayisi - i; j++) {
                System.out.print(" "); // Bosluklari ekrana yazdir
            }
            for (int k = 1; k <= 2 * i - 1; k++) {
                System.out.print("*"); // Yildizlari ekrana yazdir
            }
            System.out.println(); // Yeni satira gecer
        }
        for (int i = satirSayisi - 1; i >= 1; i--) {
            for (int j = 1; j <= satirSayisi - i; j++) {
                System.out.print(" "); // Bosluklari ekrana yazdir
            }
            for (int k = 1; k <= 2 * i - 1; k++) {
                System.out.print("*"); // Yildizlari ekrana yazdir
            }
            System.out.println(); // Yeni satira gecer
        }
    }

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        // Kullanicidan satir sayisini alma
        System.out.print("Satir sayisini girin: ");
        int satirSayisi = scanner.nextInt();

        // YildizDeseni nesnesi olusturuluyor
        YildizDeseni desen = new YildizDeseni();

        // Birinci desen (Piramid) cizdiriliyor
        System.out.println("Birinci Desen (Piramid):");
        desen.cizdir1(satirSayisi);

        // ikinci desen (Ters Piramit) cizdiriliyor
        System.out.println("ikinci Desen (Ters Piramit):");
        desen.cizdir2(satirSayisi);

        // ucuncu desen (Duz Satir Yildizlari) cizdiriliyor
        System.out.println("Ucuncu Desen (Duz Satir Yildizlari):");
        desen.cizdir3(satirSayisi);

        // Dorduncu desen (Cift Yonlu Piramit) cizdiriliyor
        System.out.println("Dorduncu Desen (Cift Yonlu Piramit):");
        desen.cizdir4(satirSayisi);

        // Scanner nesnesi kapatiliyor
        scanner.close();
    }
}

