 */
public class Number_String {

    public static void menu(){
        System.out.println("1. search words \"me\", \"why\", \"well\"");
        System.out.println("2. \"you\" word appear in @str how many times?");
        System.out.println("3. Replace the first character of each word by its UPPER CASE");
        System.out.println("4. Replace the first character of each word by its LOWER CASE, and the last character of each word by its UPPER CASE");
        System.out.println("5. Extract @str string to an array of words, then display those words by increasing order.");
        System.out.println("6. Give a character named c, remove from @str the first character which is equals to c. ");
        System.out.println("7. Count how many words in @str, display “empty string” if @str is an empty string.");
        System.out.println("8. Print all letters of @str only.");
        System.out.println("9. Reserve @str.");
        System.out.println("10. Replace all letter ‘a’ by ‘A’ and ‘b’ by ‘B’.");
        System.out.println("11. How many upper letters in @str?");
        System.out.println("12. Show menu");
        System.out.println("0. exit");
    }

    public static boolean checkMeWhyWell(String string){
        if (string.toLowerCase().contains("me") && string.toLowerCase().contains("why") && string.toLowerCase().contains("well")) {
            return true;
        }
        return false;
    }

    public static int countWordYou(String string){
        StringTokenizer tokenizer = new StringTokenizer(string, " ");
        int count=0;
        while(tokenizer.hasMoreTokens()){
            if (tokenizer.nextToken().toLowerCase().equals("you")) {
                count++;
            }
        }
        return count;
    }

    public static String upperFisrtCharWord(String string){
        StringTokenizer tokenizer = new StringTokenizer(string, " ");
        String newString = "";
        while(tokenizer.hasMoreTokens()){
            String str = tokenizer.nextToken();
            newString+= str.substring(0, 1).toUpperCase() + str.substring(1).toLowerCase() + " ";
        }
        return newString.trim();
    }

    public static String upperLastCharWord(String string){
        StringTokenizer tokenizer = new StringTokenizer(string, " ");
        String newString = "";
        while(tokenizer.hasMoreTokens()){
            String str = tokenizer.nextToken();
            newString+= str.substring(0, str.length()-1).toLowerCase()+ str.substring(str.length()-1).toUpperCase() + " ";
        }
        return newString.trim();
    }

    public static void sortWord(String string){
        String[] listStrings = string.trim().replaceAll("\\s+", " ").split(" ");
        ArrayList<String> list = new ArrayList<String>(Arrays.asList(listStrings));
        Collections.sort(list);
        System.out.println("After string sort word: " + list.toString());
    }

    public static String removeCharString(String string, char c){
        StringBuilder stringBuilder = new StringBuilder(string);
        if (string.indexOf(c)!=-1) {
            stringBuilder.deleteCharAt(string.indexOf(c));
            return stringBuilder.toString();
        }
        System.out.println("Can not found character");
        return string;
    }


    public static int countWords(String string){
        if(!string.isEmpty()){
            String[] listStrings = string.trim().split("\\s+"); 
            return listStrings.length;
        }else{
            System.out.println("Empty String");
            return 0;
        }
    }

    public static void showAllLetters(String string){
        char[] listChars = string.replaceAll("[^a-zA-Z]", "").toCharArray();
        ArrayList<Character> list = new ArrayList<>();
        for(char c: listChars){
            if (!list.contains(c)) {
                list.add(c);
            }
        }
        System.out.println("All letters: " + Arrays.toString(list.toArray()));
    }


    public static String reserveString(String string){
        StringBuilder stringBuilder = new StringBuilder(string);
        return stringBuilder.reverse().toString();
    }

    public static String replaceLetterAandB(String string){
        return string.replaceAll("a", "A").replaceAll("b", "B");
    }

    public static int countUpperLetter(String string){
       String[] liStrings = string.trim().replaceAll("[^A-Z]", " ").replaceAll("\\s+", " ").split(" ");
       return  liStrings.length;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String string = scanner.nextLine();
        menu();
        do {
            System.out.print("Select option: ");
            int choose = scanner.nextInt();
            switch(choose){
                case 1:
                    System.out.println("String have contains \"me\", \"why\", \"well\"? " +checkMeWhyWell(string));
                    break;
                case 2:
                    System.out.println("Have "+ countWordYou(string) +" word \"you\" in string");
                    break;
                case 3:
                    string = upperFisrtCharWord(string);
                    System.out.println("After String: " + string);
                    break;
                case 4:
                    string = upperLastCharWord(string);
                    System.out.println("After String: " + string);
                    break;
                case 5:
                    sortWord(string);
                    break;
                case 6:
                    System.out.print("Enter char: ");
                    char c = scanner.next().charAt(0);
                    string = removeCharString(string, c);
                    System.out.println("After string remove char: "+ string);
                    break;
                case 7:
                    int count = countWords(string);
                    if (count > 0) {
                        System.out.println("Words in string: " + count);
                    }
                    break;
                case 8:
                    showAllLetters(string);
                    break;
                case 9:
                    System.out.println("Reserve string: " + reserveString(string));
                    break;
                case 10:
                    string = replaceLetterAandB(string);
                    System.out.println("After string: "+string);
                    break;
                case 11:
                    System.out.println("Have upper letter: "+countUpperLetter(string));
                    break;
                case 12:
                    menu();
                    break;
                case 0:
                    break;
                default:
                    System.out.println("Please enter [0->12]");
                    break;
            }
            if (choose==0) {
                break;
            }
        } while (true);
    }
}

package com.thealgorithms.conversions;

/**
 * This class converts a Binary number to a Decimal number
 */
final class BinaryToDecimal {
    private static final int BINARY_BASE = 2;

    private BinaryToDecimal() {
    }

    /**
     * Converts a binary number to its decimal equivalent.
     *
     * @param binaryNumber The binary number to convert.
     * @return The decimal equivalent of the binary number.
     * @throws IllegalArgumentException If the binary number contains digits other than 0 and 1.
     */
    public static long binaryToDecimal(long binaryNumber) {
        long decimalValue = 0;
        long power = 0;

        while (binaryNumber != 0) {
            long digit = binaryNumber % 10;
            if (digit > 1) {
                throw new IllegalArgumentException("Incorrect binary digit: " + digit);
            }
            decimalValue += (long) (digit * Math.pow(BINARY_BASE, power++));
            binaryNumber /= 10;
        }
        return decimalValue;
    }

    /**
     * Converts a binary String to its decimal equivalent using bitwise operators.
     *
     * @param binary The binary number to convert.
     * @return The decimal equivalent of the binary number.
     * @throws IllegalArgumentException If the binary number contains digits other than 0 and 1.
     */
    public static long binaryStringToDecimal(String binary) {
        boolean isNegative = binary.charAt(0) == '-';
        if (isNegative) {
            binary = binary.substring(1);
        }

        long decimalValue = 0;

        for (char bit : binary.toCharArray()) {
            if (bit != '0' && bit != '1') {
                throw new IllegalArgumentException("Incorrect binary digit: " + bit);
            }
            // shift left by 1 (multiply by 2) and add bit value
            decimalValue = (decimalValue << 1) | (bit - '0');
        }

        return isNegative ? -decimalValue : decimalValue;
    }
}

package com.thealgorithms.ciphers.a5;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * The CompositeLFSR class represents a composite implementation of
 * Linear Feedback Shift Registers (LFSRs) for cryptographic purposes.
 *
 * <p>
 * This abstract class manages a collection of LFSR instances and
 * provides a mechanism for irregular clocking based on the
 * majority bit among the registers. It implements the BaseLFSR
 * interface, requiring subclasses to define specific LFSR behaviors.
 * </p>
 */
public abstract class CompositeLFSR implements BaseLFSR {

    protected final List<LFSR> registers = new ArrayList<>();

    /**
     * Performs a clocking operation on the composite LFSR.
     *
     * <p>
     * This method determines the majority bit across all registers and
     * clocks each register based on its clock bit. If a register's
     * clock bit matches the majority bit, it is clocked (shifted).
     * The method also computes and returns the XOR of the last bits
     * of all registers.
     * </p>
     *
     * @return the XOR value of the last bits of all registers.
     */
    @Override
    public boolean clock() {
        boolean majorityBit = getMajorityBit();
        boolean result = false;
        for (var register : registers) {
            result ^= register.getLastBit();
            if (register.getClockBit() == majorityBit) {
                register.clock();
            }
        }
        return result;
    }

    /**
     * Calculates the majority bit among all registers.
     *
     * <p>
     * This private method counts the number of true and false clock bits
     * across all LFSR registers. It returns true if the count of true
     * bits is greater than or equal to the count of false bits; otherwise,
     * it returns false.
     * </p>
     *
     * @return true if the majority clock bits are true; false otherwise.
     */
    private boolean getMajorityBit() {
        Map<Boolean, Integer> bitCount = new TreeMap<>();
        bitCount.put(Boolean.FALSE, 0);
        bitCount.put(Boolean.TRUE, 0);

        registers.forEach(lfsr -> bitCount.put(lfsr.getClockBit(), bitCount.get(lfsr.getClockBit()) + 1));
        return bitCount.get(Boolean.FALSE) <= bitCount.get(Boolean.TRUE);
    }
}

public class SubClass extends A {
    boolean hasSingleProperty;  // Renamed from 'single' for clarity

    public SubClass(int rollNumber, String studentName) {
        super(rollNumber, studentName);
    }

    public static void main(String[] args) {
        // Creating SubClass instance - can access protected field 'numValue' from parent A
        // because SubClass extends A (inheritance grants access to protected members)
        SubClass subclassInstance = new SubClass(45, "Sample Name");
        int inheritedValue = subclassInstance.numValue;  // ✅ Accessible (SubClass IS-A A)

        System.out.println("Accessing protected field from SubClass: " + inheritedValue);

        // Creating parent class A instance directly
        // Parent reference cannot access protected fields from another package
        // even though the parent class declares them
        A parentClassInstance = new A(45, "Another Name");
        // int parentFieldValue = parentClassInstance.numValue;  // ❌ COMPILATION ERROR
        // Reason: Even though numValue is protected in A, the reference type is A,
        // and we're accessing from a different package (com.ankan.singleton)
        // Protected members are accessible only through inheritance OR same package

        // Correct way to access from parent reference in different package:
        int correctlyAccessedValue = parentClassInstance.getNumValue();  // ✅ Using public getter
        System.out.println("Accessing via getter from parent reference: " + correctlyAccessedValue);
    }
}

// Grandchild class demonstrating multi-level inheritance
// SubSubclass inherits from SubClass, which inherits from A
// Protected members remain accessible throughout the inheritance chain
class SubSubclass extends SubClass {

    public SubSubclass(int rollNumber, String studentName) {
        super(rollNumber, studentName);
    }

    public static void main(String[] args) {
        // Grandchild can also access protected field from great-grandparent A
        SubSubclass grandchildInstance = new SubSubclass(45, "Grandchild Name");
        int inheritedFromTop = grandchildInstance.numValue;  // ✅ Accessible (transitive inheritance)

        System.out.println("Accessing protected field from SubSubclass: " + inheritedFromTop);
        System.out.println("Protected members are accessible throughout the inheritance hierarchy");
    }
}

// Sibling class - also extends A, but NOT related to SubClass
// Both SubClass and SubClass2 are children of A, but they don't know about each other
class SubClass2 extends A {
    boolean hasSingleProperty;  // Renamed for consistency

    public SubClass2(int rollNumber, String studentName) {
        super(rollNumber, studentName);
    }

    public static void main(String[] args) {
        // SubClass2 can access its OWN inherited protected field
        SubClass2 siblingInstance = new SubClass2(45, "Sibling Name");
        int ownInheritedValue = siblingInstance.numValue;  // ✅ Accessible (own inheritance)

        // However, SubClass2 CANNOT access protected field from SubClass instance
        // because they are different classes (siblings) with no inheritance relationship
        SubClass differentBranchInstance = new SubClass(45, "Different Branch");
        // int differentBranchValue = differentBranchInstance.numValue;  // ❌ COMPILATION ERROR
        // Reason: SubClass2 does NOT extend SubClass, so no inheritance relationship
        // Even though both extend A, protected members are NOT accessible across sibling classes

        System.out.println("Accessing own protected field from SubClass2: " + ownInheritedValue);
        System.out.println("\n--- Inheritance Hierarchy Visualization ---");
        System.out.println("                    A (parent)                    ");
        System.out.println("                   /    \\                        ");
        System.out.println("                  /      \\                       ");
        System.out.println("           SubClass    SubClass2                  ");
        System.out.println("               |                                  ");
        System.out.println("               |                                  ");
        System.out.println("          SubSubclass                             ");
        System.out.println("\nProtected access rule: Accessible within inheritance chain");
        System.out.println("Sibling classes CANNOT access each other's protected fields");
    }
}

public interface A {

    // Static methods in interfaces must have a body (cannot be abstract)
    // They belong to the interface itself, not to implementing classes
    static void displayStaticGreeting() {
        System.out.println("Static method in interface A - belongs to interface, not instances");
    }

    // Default methods provide a default implementation that implementing classes
    // can optionally override. They allow adding new methods to interfaces without
    // breaking existing implementations (backward compatibility)
    default void performDefaultAction() {
        System.out.println("Default implementation from interface A");
    }

    // Regular abstract method (implicitly public and abstract)
    void abstractMethod();
}

/**
 * Utility class to find the single non-duplicate element from an array
 * where all other elements appear twice.
 * <p>
 * The algorithm runs in O(n) time complexity and O(1) space complexity
 * using bitwise XOR.
 * </p>
 *
 * @author <a href="http://github.com/tuhinm2002">Tuhin M</a>
 */
public final class SingleElement {

    /**
     * Private constructor to prevent instantiation of this utility class.
     * Throws an UnsupportedOperationException if attempted.
     */
    private SingleElement() {
        throw new UnsupportedOperationException("Utility Class");
    }

    /**
     * Finds the single non-duplicate element in an array where every other
     * element appears exactly twice. Uses bitwise XOR to achieve O(n) time
     * complexity and O(1) space complexity.
     *
     * @param arr the input array containing integers where every element
     *            except one appears exactly twice
     * @return the single non-duplicate element
     */
    public static int findSingleElement(int[] arr) {
        int ele = 0;
        for (int i = 0; i < arr.length; i++) {
            ele ^= arr[i];
        }
        return ele;
    }
}

package recursive; 
import java.util.Scanner;

public class EnBuyukOrtakBolen {

	// Iki sayinin en buyuk ortak bolenini hesaplayan metod
	public static int ebob(int a, int b) { 
		// b sifir ise a geri don
		if (b == 0) 
			return a; 
		// Aksi halde, ebob(b, a % b) olarak tekrar cagirilir
		return ebob(b, a % b);  
	}

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		System.out.print("Ebobu bulmak icin bir sayi girin: ");
		int sayi1 = sc.nextInt();
		System.out.print("Ebob bulmak icin bir sayi daha girin: ");
		int sayi2 = sc.nextInt();
		sc.close();

		// En buyuk ortak boleni hesaplamak icin ebob metodu cagrilir
		int sonuc = ebob(sayi1, sayi2);
		// Sonuc ekrana yazdirilir
		System.out.print("En buyuk ortak bolen: " + sonuc);
	}
}

