package functions; 
import java.util.Scanner;  // Kullanicidan girdi almak icin Scanner sinifini projeye aktar.

public class AsalSayi {

    // 'asalMi' metodu bir sayinin asal olup olmadigini kontrol eder.
    boolean asalMi(int sayi) {
        // 2'den baslayarak sayinin kendisinden bir kucuk sayiya kadar tam bolunebilir olup olmadigini kontrol et.
        for(int i = 2; i < sayi; i++) {
            // Eger sayi herhangi bir 'i' degerine tam bolunuyorsa, asal degildir.
            if(sayi % i == 0) {
                return false;  // Sayi asal degil, false doner
            }
        }
        // Eger dongu sonunda hic bolunen olmadiysa, sayi asaldir.
        return true;
    }

    // 'sonrakiAsalSayi' metodu, kullanicinin girdigi sayidan sonraki ilk asal sayiyi bulur.
    int sonrakiAsalSayi(int sayi) {
        // Sayiyi bir arttir, ve asal olup olmadigini kontrol et.
        while(!asalMi(++sayi)) {
            // Asal degilse, bir arttirip tekrar kontrol et.
        }
        return sayi;  // Sonraki asal sayi bulunur ve doner.
    }

    // 'oncekiAsalSayi' metodu, kullanicinin girdigi sayidan onceki ilk asal sayiyi bulur.
    int oncekiAsalSayi(int sayi) {
        // Sayiyi bir azalt, ve asal olup olmadigini kontrol et.
        while(!asalMi(--sayi)) {
            // Asal degilse, bir azaltip tekrar kontrol et.
        }
        return sayi;  // Onceki asal sayi bulunur ve doner.
    }

    public static void main(String[] args) {

        // Kullanicidan girdi almak icin Scanner sinifindan nesne olustur
        Scanner okuyucu = new Scanner(System.in);

        // Kullanicidan bir sayi girmesini iste
        System.out.println("Lutfen bir sayi giriniz");
        int sayi = okuyucu.nextInt();  // Kullanicinin girdigi sayi alinir

        // AsalSayi sinifindan bir nesne olustur
        AsalSayi bulucu = new AsalSayi();

        // Girilen sayinin asal olup olmadigini kontrol et ve sonucu yazdir
        if (bulucu.asalMi(sayi)) {
            System.out.println(sayi + " sayisi asaldir.");
        } else {
            System.out.println(sayi + " sayisi asal degildir.");
        }

        // Girilen sayidan sonraki ilk asal sayiyi bul ve yazdir
        System.out.println("Sonraki asal sayi: " + bulucu.sonrakiAsalSayi(sayi));

        // Girilen sayidan onceki ilk asal sayiyi bul ve yazdir
        System.out.println("Onceki asal sayi: " + bulucu.oncekiAsalSayi(sayi));

        // Scanner nesnesini kapat, kaynaklari isletim sistemine geri ver.
        okuyucu.close();
    }
}

package com.ankan.generics;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class WildCardExample<T extends Number> {
    // Class restricted to Number and its subclasses (Integer, Double, Float, etc.)
    // The wildcard concept allows flexibility when passing parameterized types

    private Object[] internalDataStore;
    private static int INITIAL_DEFAULT_CAPACITY = 10;
    private int currentElementCount = 0; // also works as next available index position

    public WildCardExample() {
        this.internalDataStore = new Object[INITIAL_DEFAULT_CAPACITY];
    }

    // This method accepts ONLY List of Number type (no subclasses allowed)
    public void processNumberList(List<Number> numberList) {
        // Can only accept List<Number>, not List<Integer> or List<Double>
        System.out.println("Processing list of Number type: " + numberList);
    }

    // Wildcard example - accepts List of Number OR any of its subclasses
    // This is more flexible than the method above
    public void processExtendedNumberList(List<? extends Number> genericNumberList) {
        // Can accept: List<Number>, List<Integer>, List<Double>, List<Float>, etc.
        System.out.println("Processing list with wildcard: " + genericNumberList);
    }

    // Upper bounded wildcard demonstration
    public void demonstrateWildcardUsage() {
        List<Integer> integerList = Arrays.asList(1, 2, 3);
        List<Double> doubleList = Arrays.asList(1.5, 2.5, 3.5);
        List<Number> numberList = Arrays.asList(10, 20, 30);

        // processNumberList(integerList); // This would cause compilation error
        processNumberList(numberList); // Only this works for processNumberList

        processExtendedNumberList(integerList); // Works with Integer
        processExtendedNumberList(doubleList);  // Works with Double
        processExtendedNumberList(numberList);  // Works with Number
    }

    public void addElement(T elementToInsert) {
        if (isStorageFull()) {
            expandStorageCapacity();
        }
        internalDataStore[currentElementCount++] = elementToInsert;
    }

    private void expandStorageCapacity() {
        Object[] largerStorageArray = new Object[internalDataStore.length * 2];

        // Copy all existing elements into the new larger array
        for (int indexPosition = 0; indexPosition < internalDataStore.length; indexPosition++) {
            largerStorageArray[indexPosition] = internalDataStore[indexPosition];
        }
        internalDataStore = largerStorageArray;
    }

    private boolean isStorageFull() {
        return currentElementCount == internalDataStore.length;
    }

    public T removeLastElement() {
        T removedElementValue = (T) (internalDataStore[--currentElementCount]);
        return removedElementValue;
    }

    public T getElementAtIndex(int targetIndex) {
        return (T) internalDataStore[targetIndex];
    }

    public int getCurrentElementCount() {
        return currentElementCount;
    }

    public void updateValueAtIndex(int targetIndex, int newValue) {
        internalDataStore[targetIndex] = newValue;
    }

    @Override
    public String toString() {
        return "WildCardExample{" +
                "internalDataStore=" + Arrays.toString(internalDataStore) +
                ", currentElementCount=" + currentElementCount +
                '}';
    }

    public static void main(String[] args) {
        // Standard ArrayList example (commented)
        // ArrayList<String> stringList = new ArrayList<>();

        // Raw type usage (not recommended - for demonstration only)
        WildCardExample rawTypeExample = new WildCardExample();
//        rawTypeExample.addElement(3);
//        rawTypeExample.addElement(5);
//        rawTypeExample.addElement(9);

//        // Integer example with for loop (commented)
//        for (int iterationValue = 0; iterationValue < 14; iterationValue++) {
//            rawTypeExample.addElement(2 * iterationValue);
//        }
//        System.out.println(rawTypeExample);

        // Generic ArrayList with String type (commented)
        ArrayList<String> stringArrayList = new ArrayList<>();
//        stringArrayList.add("sample text");

        // Note: Generics provide compile-time type safety
        // Wildcards allow flexible method parameter definitions

        // Demonstrating WildCardExample with Integer type parameter
        WildCardExample<Integer> integerTypeExample = new WildCardExample<>();
        for (int iterationCount = 0; iterationCount < 14; iterationCount++) {
            integerTypeExample.addElement(2 * iterationCount);
        }

        System.out.println("Complete Integer ArrayList: " + integerTypeExample);

        // Demonstrate wildcard methods
        integerTypeExample.demonstrateWildcardUsage();
    }
}

public class CustomArrayList {

    private int[] internalDataArray;
    private static int DEFAULT_CAPACITY = 10;
    private int currentSize = 0; // also works as the next available index position

    public CustomArrayList() {
        this.internalDataArray = new int[DEFAULT_CAPACITY];
    }

    public void add(int elementToAdd) {
        if (isArrayFull()) {
            resizeArray();
        }
        internalDataArray[currentSize++] = elementToAdd;
    }

    private void resizeArray() {
        int[] expandedArray = new int[internalDataArray.length * 2];

        // Copy all existing elements into the new larger array
        for (int indexPosition = 0; indexPosition < internalDataArray.length; indexPosition++) {
            expandedArray[indexPosition] = internalDataArray[indexPosition];
        }
        internalDataArray = expandedArray;
    }

    private boolean isArrayFull() {
        return currentSize == internalDataArray.length;
    }

    public int removeLastElement() {
        int removedElementValue = internalDataArray[--currentSize];
        return removedElementValue;
    }

    public int getElementAtIndex(int targetIndex) {
        return internalDataArray[targetIndex];
    }

    public int getCurrentSize() {
        return currentSize;
    }

    public void updateValueAtIndex(int targetIndex, int newValue) {
        internalDataArray[targetIndex] = newValue;
    }

    @Override
    public String toString() {
        return "CustomArrayList { " +
                "data = " + Arrays.toString(internalDataArray) +
                ", currentSize = " + currentSize +
                '}';
    }

    public static void main(String[] args) {
        // Standard Java ArrayList example (commented)
        // ArrayList list = new ArrayList();

        // Using our custom ArrayList implementation
        CustomArrayList customList = new CustomArrayList();
//        customList.add(3);
//        customList.add(5);
//        customList.add(9);

        // Populate the list with even numbers
        for (int iterationCount = 0; iterationCount < 14; iterationCount++) {
            customList.add(2 * iterationCount);
        }

        System.out.println("Custom ArrayList contents: " + customList);

        // Demonstration of Java's generic ArrayList with String type
        ArrayList<String> stringArrayList = new ArrayList<>();
        stringArrayList.add("sample text");

        // Educational note about Generics
        // Generics enable parameterized type checking at compile time
        // Example: ArrayList<Integer>, ArrayList<String> etc.
    }
}

public class LinearSearch {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter array size: ");
        int n = scanner.nextInt();
        int[] arr = new int[n];
        System.out.println("Enter " + n + " elements:");
        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
        }
        System.out.print("Enter element to search: ");
        int key = scanner.nextInt();

        int foundIndex = -1;
        for (int i = 0; i < n; i++) {
            if (arr[i] == key) {
                foundIndex = i;
                break;
            }
        }

        if (foundIndex >= 0) {
            System.out.println("Element found at index " + foundIndex);
        } else {
            System.out.println("Element not found");
        }
        scanner.close();
    }
}

import java.util.ArrayList;
import java.util.List;

/**
 * A simple student management example demonstrating
 * classes, lists and basic CRUD operations.
 */
class Student {
    private final int id;
    private String name;
    private double grade;

    public Student(int id, String name, double grade) {
        this.id = id;
        this.name = name;
        this.grade = grade;
    }

    public int getId() { return id; }
    public String getName() { return name; }
    public double getGrade() { return grade; }

    @Override
    public String toString() {
        return String.format("Student{id=%d, name='%s', grade=%.1f}", id, name, grade);
    }
}

public class StudentManager {
    private final List<Student> students = new ArrayList<>();

    public void addStudent(Student student) {
        students.add(student);
    }

    public Student findById(int id) {
        for (Student student : students) {
            if (student.getId() == id) {
                return student;
            }
        }
        return null;
    }

    public double averageGrade() {
        if (students.isEmpty()) {
            return 0;
        }
        double sum = 0;
        for (Student student : students) {
            sum += student.getGrade();
        }
        return sum / students.size();
    }

    public static void main(String[] args) {
        StudentManager manager = new StudentManager();
        manager.addStudent(new Student(1, "Alice", 4.5));
        manager.addStudent(new Student(2, "Bob", 3.8));
        manager.addStudent(new Student(3, "Charlie", 4.9));

        System.out.println("Found: " + manager.findById(2));
        System.out.printf("Average grade: %.2f%n", manager.averageGrade());
    }
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;

class AdjacencyListGraph<E extends Comparable<E>> {

    ArrayList<Vertex> vertices;

    AdjacencyListGraph() {
        vertices = new ArrayList<>();
    }

    private class Vertex {

        E data;
        ArrayList<Vertex> adjacentVertices;

        Vertex(E data) {
            adjacentVertices = new ArrayList<>();
            this.data = data;
        }

        public boolean addAdjacentVertex(Vertex to) {
            for (Vertex v : adjacentVertices) {
                if (v.data.compareTo(to.data) == 0) {
                    return false; // the edge already exists
                }
            }
            return adjacentVertices.add(to); // this will return true;
        }

        public boolean removeAdjacentVertex(E to) {
            // use indexes here so it is possible to
            // remove easily without implementing
            // equals method that ArrayList.remove(Object o) uses
            for (int i = 0; i < adjacentVertices.size(); i++) {
                if (adjacentVertices.get(i).data.compareTo(to) == 0) {
                    adjacentVertices.remove(i);
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * this method removes an edge from the graph between two specified
     * vertices
     *
     * @param from the data of the vertex the edge is from
     * @param to the data of the vertex the edge is going to
     * @return returns false if the edge doesn't exist, returns true if the edge
     * exists and is removed
     */
    public boolean removeEdge(E from, E to) {
        Vertex fromV = null;
        for (Vertex v : vertices) {
            if (from.compareTo(v.data) == 0) {
                fromV = v;
                break;
            }
        }
        if (fromV == null) {
            return false;
        }
        return fromV.removeAdjacentVertex(to);
    }

    /**
     * this method adds an edge to the graph between two specified vertices
     *
     * @param from the data of the vertex the edge is from
     * @param to the data of the vertex the edge is going to
     * @return returns true if the edge did not exist, return false if it
     * already did
     */
    public boolean addEdge(E from, E to) {
        Vertex fromV = null;
        Vertex toV = null;
        for (Vertex v : vertices) {
            if (from.compareTo(v.data) == 0) { // see if from vertex already exists
                fromV = v;
            } else if (to.compareTo(v.data) == 0) { // see if to vertex already exists
                toV = v;
            }
            if (fromV != null && toV != null) {
                break; // both nodes exist so stop searching
            }
        }
        if (fromV == null) {
            fromV = new Vertex(from);
            vertices.add(fromV);
        }
        if (toV == null) {
            toV = new Vertex(to);
            vertices.add(toV);
        }
        return fromV.addAdjacentVertex(toV);
    }

    /**
     * this gives a list of vertices in the graph and their adjacencies
     *
     * @return returns a string describing this graph
     */
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Vertex v : vertices) {
            sb.append("Vertex: ");
            sb.append(v.data);
            sb.append("\n");
            sb.append("Adjacent vertices: ");
            for (Vertex v2 : v.adjacentVertices) {
                sb.append(v2.data);
                sb.append(" ");
            }
            sb.append("\n");
        }
        return sb.toString();
    }
}

public final class Graphs {
    private Graphs() {
    }

    public static void main(String[] args) {
        AdjacencyListGraph<Integer> graph = new AdjacencyListGraph<>();
        assert graph.addEdge(1, 2);
        assert graph.addEdge(1, 5);
        assert graph.addEdge(2, 5);
        assert !graph.addEdge(1, 2);
        assert graph.addEdge(2, 3);
        assert graph.addEdge(3, 4);
        assert graph.addEdge(4, 1);
        assert !graph.addEdge(2, 3);
        System.out.println(graph);
    }
}

public class ContinueOrnegi {

    // Sayilari tek ve cift olarak ayirt eden ornek
    public static void tekCiftAyristir() {
        System.out.println("Tek ve Cift Sayilar Ornegi:");
        int n = 1;
        while (n <= 10) {
            if (n % 2 == 0) { // cift sayi kontrolu
                System.out.println("Cift sayi: " + n);
                n++;
                continue; // cift oldugunda alttaki satir atlanir
            }
            System.out.println("Tek sayi: " + n);
            n++;
        }
    }

    // 3 veya 5 ile tam bolunen sayilari atlayan ornek
    public static void ucBesKatlariniAtla() {
        System.out.println("\n3 ve 5'in Katlarini Atlayan Ornek:");
        for (int n = 1; n <= 15; n++) {
            if (n % 3 == 0 || n % 5 == 0) { // 3 ya da 5'in kati mi kontrol edilir
                System.out.println("Atlanan sayi: " + n);
                continue; // katlar icin devam eden kod calismaz
            }
            System.out.println("Gecerli sayi: " + n);
        }
    }

    // Ic ice donguler icerisinde continue kullanan ornek
    public static void icIceContinueOrnek() {
        System.out.println("\nIc Ice Dongulerde Continue Ornegi:");
        int satir = 1;
        while (satir <= 3) {
            for (int sutun = 1; sutun <= 3; sutun++) {
                if (satir == sutun) { // indeksler esitse atla
                    System.out.println("i: " + satir + ", j: " + sutun + " -> Continue uygulandi");
                    continue; // esitlik durumunda geri kalan kod calismaz
                }
                System.out.println("i: " + satir + ", j: " + sutun);
            }
            satir++;
        }
    }

    public static void main(String[] args) {
        // Ornekleri sirayla calistir
        tekCiftAyristir();
        ucBesKatlariniAtla();
        icIceContinueOrnek();
    }
}

