import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.Scanner;

/*
 * A minimal trivia-quiz game. Questions and their answers are loaded from
 * a text file ("sorular.txt"), where each line holds one question and its
 * answer separated by a colon (:). The player gets up to three guesses per
 * question, and a final tally of right/wrong answers is printed at the end.
 */

public class BilgiYarismasi {

    private static final int MAX_ATTEMPTS = 3;

    public static void main(String[] args) {

        int questionCount = 0;
        int correctCount = 0;

        try (BufferedReader fileReader = new BufferedReader(new FileReader("sorular.txt"))) {
            String line;
            Scanner console = new Scanner(System.in);

            while ((line = fileReader.readLine()) != null) {
                questionCount++;

                String[] fields = line.split(":");
                String question = fields[0];
                String answer = fields[1];

                System.out.println(question);
                boolean guessedRight = false;

                for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
                    System.out.print("Tahmininizi girin: ");
                    String guess = console.nextLine();

                    if (guess.equalsIgnoreCase(answer)) {
                        System.out.println("Dogru!");
                        correctCount++;
                        guessedRight = true;
                        break;
                    }

                    if (attempt == MAX_ATTEMPTS - 1) {
                        System.out.println("Dogru cevap: " + answer);
                    } else {
                        System.out.println("Yanlis. Tekrar deneyin.");
                    }
                }
                // guessedRight isn't needed further; loop already reported results
            }
            console.close();
        } catch (IOException fileError) {
            System.out.println("Dosyadan okuma sirasinda hata: " + fileError.getMessage());
        }

        System.out.println("Dogru cevaplar: " + correctCount);
        System.out.println("Yanlis cevaplar: " + (questionCount - correctCount));
    }
}

/**
 * A class that counts the number of different connected components in a graph
 *
 * @author Lukas Keul, Florian Mercks
 */
class Graph<NodeType extends Comparable<NodeType>> {

class GraphNode {
NodeType nodeName;

GraphNode(NodeType nodeName) {
this.nodeName = nodeName;
}
}

class ConnectionEdge {
GraphNode startNode;
GraphNode endNode;

ConnectionEdge(GraphNode startNode, GraphNode endNode) {
this.startNode = startNode;
this.endNode = endNode;
}
}

ArrayList<ConnectionEdge> edgeList;
ArrayList<GraphNode> nodeList;

Graph() {
edgeList = new ArrayList<ConnectionEdge>();
nodeList = new ArrayList<GraphNode>();
}

/**
 * Adds a new Edge to the graph. If the nodes aren't yet in nodeList, they
 * will be added to it.
 *
 * @param startNode the starting Node from the edge
 * @param endNode the ending Node from the edge
 */
public void insertEdge(NodeType startNode, NodeType endNode) {
GraphNode startVertex = null;
GraphNode endVertex = null;
for (GraphNode existingNode : nodeList) {
if (startNode.compareTo(existingNode.nodeName) == 0) {
startVertex = existingNode;
} else if (endNode.compareTo(existingNode.nodeName) == 0) {
endVertex = existingNode;
}
}
if (startVertex == null) {
startVertex = new GraphNode(startNode);
nodeList.add(startVertex);
}
if (endVertex == null) {
endVertex = new GraphNode(endNode);
nodeList.add(endVertex);
}
edgeList.add(new ConnectionEdge(startVertex, endVertex));
}

/**
 * Main method used for counting the connected components. Iterates through
 * the array of nodes to do a depth first search to get all nodes of the
 * graph from the actual node. These nodes are added to the array
 * markedNodes and will be ignored if they are chosen in the nodeList.
 *
 * @return returns the amount of unconnected graphs
 */
public int countComponents() {
int componentCount = 0;
Set<GraphNode> visitedNodes = new HashSet<GraphNode>();
for (GraphNode currentNode : nodeList) {
if (visitedNodes.add(currentNode)) {
visitedNodes.addAll(performDFS(currentNode, new ArrayList<GraphNode>()));
componentCount++;
}
}
return componentCount;
}

/**
 * Implementation of depth first search.
 *
 * @param startNode the actual visiting node
 * @param visitedNodes A list of already visited nodes in the depth first search
 * @return returns a set of visited nodes
 */
public ArrayList<GraphNode> performDFS(GraphNode startNode, ArrayList<GraphNode> visitedNodes) {
visitedNodes.add(startNode);
for (ConnectionEdge currentEdge : edgeList) {
if (currentEdge.startNode.equals(startNode) && !visitedNodes.contains(currentEdge.endNode)) {
performDFS(currentEdge.endNode, visitedNodes);
}
}
return visitedNodes;
}
}

public final class ConnectedComponent {
private ConnectedComponent() {
}

public static void main(String[] args) {
Graph<Character> charGraph = new Graph<>();
charGraph.insertEdge('a', 'b');
charGraph.insertEdge('a', 'e');
charGraph.insertEdge('b', 'e');
charGraph.insertEdge('b', 'c');
charGraph.insertEdge('c', 'd');
charGraph.insertEdge('d', 'a');
charGraph.insertEdge('x', 'y');
charGraph.insertEdge('x', 'z');
charGraph.insertEdge('w', 'w');
Graph<Integer> intGraph = new Graph<>();
intGraph.insertEdge(1, 2);
intGraph.insertEdge(2, 3);
intGraph.insertEdge(2, 4);
intGraph.insertEdge(3, 5);
intGraph.insertEdge(7, 8);
intGraph.insertEdge(8, 10);
intGraph.insertEdge(10, 8);
System.out.println("Amount of different char-graphs: " + charGraph.countComponents());
System.out.println("Amount of different int-graphs: " + intGraph.countComponents());
}
}

/*
 * Ornek: birden fazla arka plan islemini ayri thread'lerde paralel
 * yurutup, ana thread bir sure kendi isini yaptiktan sonra hepsini
 * kontrollu bicimde durduran ve tamamlanmalarini bekleyen program.
 */

public class ArkaPlanGorevi implements Runnable {

    private final String etiket;
    private volatile boolean aktif = true;

    public ArkaPlanGorevi(String etiket) {
        this.etiket = etiket;
    }

    /** Gorev durdurulana ya da 10 tur tamamlanana kadar ilerleme mesaji basar. */
    @Override
    public void run() {
        int turSayaci = 0;
        while (aktif && turSayaci < 10) {
            System.out.println(etiket + " calisiyor: " + turSayaci);
            try {
                Thread.sleep(400);
            } catch (InterruptedException kesinti) {
                System.out.println(etiket + " kesildi.");
                return;
            }
            turSayaci++;
        }
        System.out.println(etiket + " tamamlandi.");
    }

    /** Calisan gorevi bir sonraki kontrol noktasinda sonlandirmak icin bayragi indirir. */
    public void durdur() {
        aktif = false;
    }

    public static void main(String[] args) throws InterruptedException {
        ArkaPlanGorevi ilkGorev = new ArkaPlanGorevi("Gorev-1");
        ArkaPlanGorevi ikinciGorev = new ArkaPlanGorevi("Gorev-2");
        ArkaPlanGorevi ucuncuGorev = new ArkaPlanGorevi("Gorev-3");

        Thread ilkIsParcacigi = new Thread(ilkGorev, "Thread-1");
        Thread ikinciIsParcacigi = new Thread(ikinciGorev, "Thread-2");
        Thread ucuncuIsParcacigi = new Thread(ucuncuGorev, "Thread-3");

        ilkIsParcacigi.start();
        ikinciIsParcacigi.start();
        ucuncuIsParcacigi.start();

        anaThreadMesguletmesi();

        beklemeSuresiTanimla(5000);

        System.out.println("Tum gorevler durduruluyor...");
        ilkGorev.durdur();
        ikinciGorev.durdur();
        ucuncuGorev.durdur();

        ilkIsParcacigi.join();
        ikinciIsParcacigi.join();
        ucuncuIsParcacigi.join();

        System.out.println("Tum isler tamamlandi. Program sonlandi.");
    }

    private static void anaThreadMesguletmesi() {
        for (int i = 0; i < 5; i++) {
            System.out.println("Ana thread is yapiyor: " + i);
            beklemeSuresiTanimla(500);
        }
    }

    private static void beklemeSuresiTanimla(long milisaniye) {
        try {
            Thread.sleep(milisaniye);
        } catch (InterruptedException kesinti) {
            kesinti.printStackTrace();
        }
    }
}

public class OnaKadarToplama {

    public static void main(String[] args) {

    	// 1'den 10'a kadar olan sayilari ekrana yazdirma
        System.out.print("1'den 10'a kadar olan sayilar: ");
        for (int i = 1; i <= 10; i++) {
            System.out.print(i + " "); // Sayilari ekrana yazdir
        }
        System.out.println(); // Yeni satir

        int toplam = 0; // Toplam degiskeni baslangicta 0 olarak tanimlanir

        // 1'den 10'a kadar sayilarin toplami icin dongu
        for (int i = 1; i <= 10; i++) {
            toplam += i; // Her bir sayi toplama eklenir
        }

        // Toplam sonucu ekrana yazdirilir
        System.out.println("1'den 10'a kadar olan sayilarin toplami: " + toplam);

        // Kullanici girisi ile belirli bir sayi kadar toplama islemi yapma
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        System.out.print("Toplamak istediginiz sayiyi girin: ");
        int n = scanner.nextInt(); // Kullanici girisi alinir

        int kullaniciToplam = 0; // Kullanici toplami baslangicta 0 olarak atanir
        for (int i = 1; i <= n; i++) {
            kullaniciToplam += i; // Her bir sayi kullanici toplamina eklenir
        }

        // Kullanici toplami ekrana yazdirilir
        System.out.println("1'den " + n + "'a kadar olan sayilarin toplami: " + kullaniciToplam);

        scanner.close(); // Scanner kapatilir
    }
}

