package encapsulation;

public class Banka {

	public static void main(String[] args) {

		// Iki farkli turde banka hesabi acilir
		BankaHesabi vadeliHesap = new BankaHesabi(123456, 2000.0, "Vadeli");
		BankaHesabi vadesizHesap = new BankaHesabi(789012, 1500.0, "Vadesiz");

		hesapBilgisiYazdir("Hesap 1", vadeliHesap);

		System.out.println();

		hesapBilgisiYazdir("Hesap 2", vadesizHesap);

		System.out.println();

		// Ilk hesaba para yatiriliyor
		vadeliHesap.paraYatir(500.0);

		// Ikinci hesaptan para cekiliyor
		vadesizHesap.paraCek(200.0);

		// Vadeli hesaba faiz uygulaniyor
		vadeliHesap.faizEkle(5.0);

		// Ilk hesaptan ikinci hesaba transfer yapiliyor
		vadeliHesap.transfer(vadesizHesap, 300.0);

		System.out.println();
		System.out.println("Hesap 1 yeni bakiye: " + vadeliHesap.getBakiye());
		System.out.println("Hesap 2 yeni bakiye: " + vadesizHesap.getBakiye());
	}

	// Bir hesabin numara, bakiye ve tur bilgisini etiketleyerek ekrana basar
	private static void hesapBilgisiYazdir(String etiket, BankaHesabi hesap) {
		System.out.println(etiket + " numarasi: " + hesap.getHesapNumarasi());
		System.out.println(etiket + " bakiye: " + hesap.getBakiye());
		System.out.println(etiket + " turu: " + hesap.getHesapTuru());
	}
}

package Shape;

/**
 * Abstract base shape: a color and whether it is filled.
 */
public abstract class Shape {

    protected String color = "red";
    protected boolean filled = true;

    public Shape() {
    }

    public Shape(String color, boolean filled) {
        this.color = color;
        this.filled = filled;
    }

    public String getColor() {
        return color;
    }

    public void setColor(String color) {
        this.color = color;
    }

    public boolean isFilled() {
        return filled;
    }

    public void setFilled(boolean filled) {
        this.filled = filled;
    }

    public abstract double getArea();

    public abstract double getPerimeter();

    @Override
    public String toString() {
        return "Shape[color=" + color + ",filled=" + filled + ']';
    }
}

package com.thealgorithms.backtracking;

import java.util.ArrayList;
import java.util.List;

/**
 * Finds all possible simple paths from a given source vertex to a destination vertex
 * in a directed graph using backtracking.
 *
 * <p>This algorithm performs a Depth First Search (DFS) traversal while keeping track
 * of visited vertices to avoid cycles. Whenever the destination vertex is reached,
 * the current path is stored as one valid path.</p>
 *
 * <p><b>Key Characteristics:</b></p>
 * <ul>
 *   <li>Works on directed graphs</li>
 *   <li>Does not allow revisiting vertices in the same path</li>
 *   <li>Stores all possible paths from source to destination</li>
 *   <li>Uses backtracking to explore all possible routes</li>
 * </ul>
 *
 * <p><b>Time Complexity:</b></p>
 * <ul>
 *   <li>Worst Case: O(V!) — when the graph is fully connected (complete graph)</li>
 *   <li>Average Case: O(E) for sparse graphs</li>
 * </ul>
 *
 * <p><b>Space Complexity:</b></p>
 * <ul>
 *   <li>O(V) for recursion stack and visited array</li>
 *   <li>O(V × number_of_paths) for storing all valid paths</li>
 * </ul>
 *
 * <p><b>Example Usage:</b></p>
 * <pre>
 * // Graph with 4 vertices: 0 → 1 → 2 → 3
 * int[][] edges = {{0, 1}, {1, 2}, {2, 3}};
 * List&lt;List&lt;Integer&gt;&gt; paths = AllPathsFromSourceToTarget.allPathsFromSourceToTarget(4, edges, 0, 3);
 * // Result: [[0, 1, 2, 3]]
 * </pre>
 *
 * <p>This implementation is intended for educational purposes to demonstrate
 * backtracking and DFS traversal in graph theory.</p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Depth-first_search">Depth First Search</a>
 * @see <a href="https://en.wikipedia.org/wiki/Backtracking">Backtracking Algorithm</a>
 */

@SuppressWarnings({"rawtypes", "unchecked"})
public final class AllPathsFromSourceToTarget {

    // Number of vertices in the graph
    private final int vertexCount;

    // Static storage for all discovered paths from source to destination
    // Made static for simplicity in this implementation
    private static List<List<Integer>> allDiscoveredPaths = new ArrayList<>();

    // Adjacency list representation of the graph
    private ArrayList<Integer>[] adjacencyList;

    /**
     * Constructs a graph with the specified number of vertices.
     *
     * @param numberOfVertices The total number of vertices in the graph (must be ≥ 1)
     */
    public AllPathsFromSourceToTarget(int numberOfVertices) {
        // Validate input
        if (numberOfVertices < 1) {
            throw new IllegalArgumentException("Vertex count must be at least 1");
        }

        // Initialize vertex count
        this.vertexCount = numberOfVertices;

        // Initialize adjacency list data structure
        initializeAdjacencyList();
    }

    /**
     * Initializes the adjacency list for all vertices.
     * Creates an empty ArrayList for each vertex.
     */
    private void initializeAdjacencyList() {
        adjacencyList = new ArrayList[vertexCount];

        for (int vertexIndex = 0; vertexIndex < vertexCount; vertexIndex++) {
            adjacencyList[vertexIndex] = new ArrayList<>();
        }
    }

    /**
     * Adds a directed edge from source vertex to destination vertex.
     *
     * @param sourceVertex The starting vertex of the edge
     * @param destinationVertex The ending vertex of the edge
     * @throws IndexOutOfBoundsException if either vertex is invalid
     */
    public void addDirectedEdge(int sourceVertex, int destinationVertex) {
        // Validate vertex indices
        if (sourceVertex < 0 || sourceVertex >= vertexCount || 
            destinationVertex < 0 || destinationVertex >= vertexCount) {
            throw new IndexOutOfBoundsException("Invalid vertex index");
        }

        // Add destination to source's adjacency list
        adjacencyList[sourceVertex].add(destinationVertex);
    }

    /**
     * Finds all simple paths from source to destination and stores them.
     * Resets the path storage before starting the search.
     *
     * @param sourceVertex The starting vertex (path origin)
     * @param destinationVertex The target vertex (path destination)
     */
    public void findAllPaths(int sourceVertex, int destinationVertex) {
        // Reset path storage for each new search
        allDiscoveredPaths.clear();

        // Track visited vertices to avoid cycles
        boolean[] visitedVertices = new boolean[vertexCount];

        // Initialize path with the source vertex
        ArrayList<Integer> currentPath = new ArrayList<>();
        currentPath.add(sourceVertex);

        // Start recursive exploration
        findAllPathsRecursive(sourceVertex, destinationVertex, visitedVertices, currentPath);
    }

    /**
     * Recursive utility method to explore all paths using DFS and backtracking.
     *
     * @param currentVertex Current vertex being explored
     * @param destinationVertex Target vertex we're trying to reach
     * @param visitedVertices Tracks visited vertices in the current path
     * @param currentPath List of vertices in the current path
     */
    private void findAllPathsRecursive(Integer currentVertex, Integer destinationVertex, 
                                        boolean[] visitedVertices, List<Integer> currentPath) {

        // Base case: Reached the destination
        if (currentVertex.equals(destinationVertex)) {
            // Store a copy of the current path
            allDiscoveredPaths.add(new ArrayList<>(currentPath));
            return;
        }

        // Mark current vertex as visited
        visitedVertices[currentVertex] = true;

        // Explore all adjacent vertices
        for (Integer neighborVertex : adjacencyList[currentVertex]) {
            if (!visitedVertices[neighborVertex]) {
                // Add neighbor to current path
                currentPath.add(neighborVertex);

                // Recursive exploration
                findAllPathsRecursive(neighborVertex, destinationVertex, visitedVertices, currentPath);

                // Backtrack: remove neighbor from path
                currentPath.remove(neighborVertex);
            }
        }

        // Unmark current vertex (backtrack) for other path explorations
        visitedVertices[currentVertex] = false;
    }

    /**
     * Static convenience method to find all paths from source to destination.
     * Creates a graph, adds edges, and returns all discovered paths.
     *
     * @param vertexCount Number of vertices in the graph
     * @param edges Array of directed edges where each edge is [source, destination]
     * @param sourceVertex Starting vertex for path search
     * @param destinationVertex Target vertex for path search
     * @return List of all paths from source to destination
     * 
     * <p><b>Example:</b>
     * <pre>
     * int[][] edges = {{0, 1}, {0, 2}, {1, 3}, {2, 3}};
     * List&lt;List&lt;Integer&gt;&gt; paths = allPathsFromSourceToTarget(4, edges, 0, 3);
     * // Possible paths: [0, 1, 3] and [0, 2, 3]
     * </pre>
     */
    public static List<List<Integer>> findAllPathsFromSourceToTarget(int vertexCount, int[][] edges, 
                                                                      int sourceVertex, int destinationVertex) {
        // Validate input parameters
        if (edges == null) {
            throw new IllegalArgumentException("Edges array cannot be null");
        }

        // Create graph instance
        AllPathsFromSourceToTarget graphInstance = new AllPathsFromSourceToTarget(vertexCount);

        // Add all edges to the graph
        for (int[] edge : edges) {
            if (edge.length != 2) {
                throw new IllegalArgumentException("Each edge must have exactly 2 vertices: [source, destination]");
            }
            graphInstance.addDirectedEdge(edge[0], edge[1]);
        }

        // Find all paths
        graphInstance.findAllPaths(sourceVertex, destinationVertex);

        // Return the discovered paths
        return allDiscoveredPaths;
    }

    /**
     * Returns the number of paths found in the most recent search.
     *
     * @return The count of discovered paths
     */
    public static int getPathCount() {
        return allDiscoveredPaths.size();
    }

    /**
     * Prints all discovered paths in a readable format.
     * Useful for debugging and demonstration purposes.
     */
    public static void printAllPaths() {
        if (allDiscoveredPaths.isEmpty()) {
            System.out.println("No paths found.");
            return;
        }

        System.out.println("Found " + allDiscoveredPaths.size() + " path(s):");
        for (int pathIndex = 0; pathIndex < allDiscoveredPaths.size(); pathIndex++) {
            System.out.println("Path " + (pathIndex + 1) + ": " + allDiscoveredPaths.get(pathIndex));
        }
    }
}

/*
COMPREHENSIVE DOCUMENTATION
===========================

ALGORITHM EXPLANATION
---------------------

What is Backtracking?
- Backtracking is an algorithmic technique for solving problems recursively
- Builds candidates for solutions incrementally
- Abandons a candidate ("backtracks") as soon as it determines it cannot lead to a valid solution
- Used extensively in path finding, constraint satisfaction, and combinatorial problems

How the Algorithm Works:
-----------------------
1. Start at the source vertex
2. Mark the current vertex as visited
3. If current vertex is the destination, record the current path
4. Otherwise, recursively explore all unvisited neighbors
5. After exploring a neighbor, backtrack by removing it from the path
6. Unmark the current vertex to allow other paths to use it

Visual Example:
--------------
Consider a graph: 0 → 1 → 3
                  ↘ 2 ↗

Finding paths from 0 to 3:
- Path 1: 0 → 1 → 3
- Path 2: 0 → 2 → 3

Backtracking Process for Path 1:
1. Start: path = [0], visited = {0}
2. Explore 1: path = [0,1], visited = {0,1}
3. Explore 3: path = [0,1,3] → FOUND PATH
4. Backtrack: remove 3, then remove 1
5. Explore 2: path = [0,2], visited = {0,2}
6. Explore 3: path = [0,2,3] → FOUND PATH

GRAPH TERMINOLOGY
=================

| Term | Definition |
|------|------------|
| Vertex (Node) | A point in the graph (represented by integers) |
| Edge | Connection between two vertices |
| Directed Graph | Edges have a direction (u → v is different from v → u) |
| Path | Sequence of vertices where consecutive vertices are connected |
| Simple Path | Path with no repeated vertices |
| Source | Starting vertex for path search |
| Destination | Target vertex for path search |
| Adjacency List | Data structure storing neighbors for each vertex |

APPLICATIONS
============

Real-world uses of path finding:
1. GPS Navigation Systems - Finding all possible routes between locations
2. Network Routing - Discovering alternative paths in computer networks
3. Social Networks - Finding connection chains between users
4. Game Development - Pathfinding for AI characters
5. Circuit Design - Tracing all possible signal paths
6. Compiler Design - Finding execution paths in control flow graphs

COMPLEXITY ANALYSIS
===================

| Operation | Time Complexity | Space Complexity |
|-----------|----------------|------------------|
| Building graph | O(V + E) | O(V + E) |
| Single path (DFS) | O(V + E) | O(V) |
| All paths worst-case | O(V!) | O(V × number_of_paths) |
| Adding edge | O(1) | O(1) |

LIMITATIONS
===========
1. Exponential time complexity for dense graphs
2. Not suitable for very large graphs (V > 20 may be problematic)
3. No path optimization (finds all paths, not just shortest)
4. Memory intensive when storing many paths

IMPROVEMENTS POSSIBLE
=====================
1. Use pruning techniques to reduce exploration
2. Implement iterative approach to avoid recursion depth limits
3. Add early termination if only specific paths are needed
4. Use memoization for overlapping subproblems
5. Implement parallel processing for large graphs
*/

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.List;
import java.util.Map;
import java.util.LinkedHashMap;

/**
 * Walks a directory tree and strips Turkish-specific accented letters
 * out of every ".java" source file it finds (except files starting
 * with "Turkce"), replacing them with their plain ASCII equivalents.
 */
public class TurkceKarakterDegistirici {

    private static final Map<String, String> DEGISIM_TABLOSU = new LinkedHashMap<>();
    static {
        DEGISIM_TABLOSU.put("ü", "u");
        DEGISIM_TABLOSU.put("Ü", "U");
        DEGISIM_TABLOSU.put("ğ", "g");
        DEGISIM_TABLOSU.put("Ğ", "G");
        DEGISIM_TABLOSU.put("ı", "i");
        DEGISIM_TABLOSU.put("İ", "I");
        DEGISIM_TABLOSU.put("ş", "s");
        DEGISIM_TABLOSU.put("Ş", "S");
        DEGISIM_TABLOSU.put("ç", "c");
        DEGISIM_TABLOSU.put("Ç", "C");
        DEGISIM_TABLOSU.put("ö", "o");
        DEGISIM_TABLOSU.put("Ö", "O");
    }

    /** Belirtilen klasoru ve tum alt klasorlerini gezerek uygun dosyalari isler. */
    public static void agaciGez(File baslangicNoktasi) {
        File[] icerik = baslangicNoktasi.listFiles();
        if (icerik == null) {
            return;
        }

        for (File oge : icerik) {
            if (oge.isDirectory()) {
                agaciGez(oge);
            } else if (isleneceklerdenMi(oge)) {
                dosyayiTemizle(oge);
            }
        }
    }

    private static boolean isleneceklerdenMi(File oge) {
        return oge.isFile()
                && oge.getName().endsWith(".java")
                && !oge.getName().startsWith("Turkce");
    }

    /** Bir Java dosyasindaki Turkce karakterleri ayiklayip degisiklikleri diske yansitir. */
    private static void dosyayiTemizle(File hedefDosya) {
        try {
            List<String> satirlar = Files.readAllLines(hedefDosya.toPath(), StandardCharsets.UTF_8);
            boolean herhangiBirSatirDegisti = false;

            for (int satirIndex = 0; satirIndex < satirlar.size(); satirIndex++) {
                String eski = satirlar.get(satirIndex);
                String yeni = karakterleriCevir(eski);

                if (!eski.equals(yeni)) {
                    satirlar.set(satirIndex, yeni);
                    System.out.println("Dosya: " + hedefDosya.getAbsolutePath()
                            + " - Satir " + (satirIndex + 1) + " degistirildi.");
                    herhangiBirSatirDegisti = true;
                }
            }

            if (herhangiBirSatirDegisti) {
                Files.write(hedefDosya.toPath(), satirlar, StandardCharsets.UTF_8);
            }
        } catch (IOException hata) {
            System.out.println("Hata: " + hata.getMessage());
        }
    }

    private static String karakterleriCevir(String satir) {
        String sonuc = satir;
        for (Map.Entry<String, String> kural : DEGISIM_TABLOSU.entrySet()) {
            sonuc = sonuc.replace(kural.getKey(), kural.getValue());
        }
        return sonuc;
    }

    public static void main(String[] args) {
        File ustDizin = new File(System.getProperty("user.dir")).getParentFile();
        agaciGez(ustDizin);
    }
}

/**
 * A generic BloomFilter implementation for probabilistic membership checking.
 * <p>
 * Bloom filters are space-efficient data structures that provide a fast way to
 * test whether an
 * element is a member of a set. They may produce false positives, indicating an
 * element is
 * in the set when it is not, but they will never produce false negatives.
 * </p>
 *
 * @param <T> The type of elements to be stored in the Bloom filter.
 */
@SuppressWarnings("rawtypes")
public class BloomFilter<T> {

    private final int numberOfHashFunctions;
    private final BitSet bitArray;
    private final Hash<T>[] hashFunctions;

    /**
     * Constructs a BloomFilter with a specified number of hash functions and bit
     * array size.
     *
     * @param numberOfHashFunctions the number of hash functions to use
     * @param bitArraySize          the size of the bit array, which determines the
     *                              capacity of the filter
     * @throws IllegalArgumentException if numberOfHashFunctions or bitArraySize is
     *                                  less than 1
     */
    @SuppressWarnings("unchecked")
    public BloomFilter(int numberOfHashFunctions, int bitArraySize) {
        if (numberOfHashFunctions < 1 || bitArraySize < 1) {
            throw new IllegalArgumentException("Number of hash functions and bit array size must be greater than 0");
        }
        this.numberOfHashFunctions = numberOfHashFunctions;
        this.bitArray = new BitSet(bitArraySize);
        this.hashFunctions = new Hash[numberOfHashFunctions];
        initializeHashFunctions();
    }

    /**
     * Initializes the hash functions with unique indices to ensure different
     * hashing.
     */
    private void initializeHashFunctions() {
        for (int i = 0; i < numberOfHashFunctions; i++) {
            hashFunctions[i] = new Hash<>(i);
        }
    }

    /**
     * Inserts an element into the Bloom filter.
     * <p>
     * This method hashes the element using all defined hash functions and sets the
     * corresponding
     * bits in the bit array.
     * </p>
     *
     * @param key the element to insert into the Bloom filter
     */
    public void insert(T key) {
        for (Hash<T> hash : hashFunctions) {
            int position = Math.abs(hash.compute(key) % bitArray.size());
            bitArray.set(position);
        }
    }

    /**
     * Checks if an element might be in the Bloom filter.
     * <p>
     * This method checks the bits at the positions computed by each hash function.
     * If any of these
     * bits are not set, the element is definitely not in the filter. If all bits
     * are set, the element
     * might be in the filter.
     * </p>
     *
     * @param key the element to check for membership in the Bloom filter
     * @return {@code true} if the element might be in the Bloom filter,
     *         {@code false} if it is definitely not
     */
    public boolean contains(T key) {
        for (Hash<T> hash : hashFunctions) {
            int position = Math.abs(hash.compute(key) % bitArray.size());
            if (!bitArray.get(position)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Inner class representing a hash function used by the Bloom filter.
     * <p>
     * Each instance of this class represents a different hash function based on its
     * index.
     * </p>
     *
     * @param <T> The type of elements to be hashed.
     */
    private static class Hash<T> {

        private final int index;

        /**
         * Constructs a Hash function with a specified index.
         *
         * @param index the index of this hash function, used to create a unique hash
         */
        Hash(int index) {
            this.index = index;
        }

        /**
         * Computes the hash of the given key.
         * <p>
         * The hash value is calculated by multiplying the index of the hash function
         * with the ASCII sum of the string representation of the key.
         * </p>
         *
         * @param key the element to hash
         * @return the computed hash value
         */
        public int compute(T key) {
            return index * contentHash(key);
        }

        /**
         * Computes the ASCII value sum of the characters in a string.
         * <p>
         * This method iterates through each character of the string and accumulates
         * their ASCII values to produce a single integer value.
         * </p>
         *
         * @param word the string to compute
         * @return the sum of ASCII values of the characters in the string
         */
        private int asciiString(String word) {
            int sum = 0;
            for (char c : word.toCharArray()) {
                sum += c;
            }
            return sum;
        }

        /**
         * Computes a content-based hash for arrays; falls back to ASCII-sum of String value otherwise.
         */
        private int contentHash(Object key) {
            if (key instanceof int[]) {
                return Arrays.hashCode((int[]) key);
            } else if (key instanceof long[]) {
                return Arrays.hashCode((long[]) key);
            } else if (key instanceof byte[]) {
                return Arrays.hashCode((byte[]) key);
            } else if (key instanceof short[]) {
                return Arrays.hashCode((short[]) key);
            } else if (key instanceof char[]) {
                return Arrays.hashCode((char[]) key);
            } else if (key instanceof boolean[]) {
                return Arrays.hashCode((boolean[]) key);
            } else if (key instanceof float[]) {
                return Arrays.hashCode((float[]) key);
            } else if (key instanceof double[]) {
                return Arrays.hashCode((double[]) key);
            } else if (key instanceof Object[]) {
                return Arrays.deepHashCode((Object[]) key);
            }
            return asciiString(String.valueOf(key));
        }
    }
}

/**
 * A statue, which is an Item with a weight and color.
 */
public class Statue extends Item {
    private int weight;
    private String color;

    public Statue() {
    }

    public Statue(int value, String creator, int weight, String color) {
        super(value, creator);
        this.weight = weight;
        this.color = color;
    }

    public int getWeight() {
        return weight;
    }

    public void setWeight(int weight) {
        this.weight = weight;
    }

    public String getColor() {
        return color;
    }

    public void setColor(String color) {
        this.color = color;
    }

    @Override
    public String toString() {
        return "Statue[" + super.toString() + ",weight=" + weight + ",color=" + color + ']';
    }

    public void inputStatue() {
        super.input();
        Scanner scanner = new Scanner(System.in);
        System.out.print("Input a weight: ");
        weight = scanner.nextInt();
        scanner.nextLine();
        System.out.print("Input a color: ");
        color = scanner.nextLine();
    }

    public void outputStatue() {
        super.output();
        System.out.println("Weight: " + weight);
        System.out.println("Color: " + color);
    }
}

public class VotingEligibility {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
