/**
 * Generates all subsequences for a given list of elements using backtracking.
 * 
 * <p><b>Problem Statement:</b><br>
 * Given a list of elements, generate all possible subsequences (including the empty subsequence).
 * A subsequence is any sequence that can be derived by deleting some (or none) of the elements
 * without changing the order of the remaining elements.</p>
 * 
 * <p><b>Key Concepts:</b></p>
 * <ul>
 *   <li>A subsequence is NOT the same as a substring (which requires contiguous elements)</li>
 *   <li>Elements maintain their original relative order in subsequences</li>
 *   <li>For a sequence of n elements, there are exactly 2ⁿ subsequences</li>
 *   <li>Includes both empty subsequence and the full original sequence</li>
 * </ul>
 * 
 * <p><b>Algorithm Explanation:</b></p>
 * <ol>
 *   <li>At each position, we have two choices: include the current element or skip it</li>
 *   <li>Recursively process the next position after making each choice</li>
 *   <li>When we reach the end of the sequence, add the current subsequence to results</li>
 *   <li>Uses backtracking to explore both possibilities</li>
 * </ol>
 * 
 * <p><b>Time Complexity:</b> O(2ⁿ × n) where n is the length of the sequence.
 * There are 2ⁿ subsequences and creating each takes O(n) to copy.</p>
 * 
 * <p><b>Space Complexity:</b> O(2ⁿ × n) for storing all subsequences plus O(n) for recursion stack</p>
 * 
 * <p><b>Example:</b>
 * <pre>
 * Input: sequence = [1, 2, 3]
 * Output: [[], [3], [2], [2,3], [1], [1,3], [1,2], [1,2,3]]
 * </pre>
 * </p>
 * 
 * @param <T> The type of elements in the sequence
 * @see <a href="https://en.wikipedia.org/wiki/Subsequence">Subsequence (Wikipedia)</a>
 * @see <a href="https://en.wikipedia.org/wiki/Backtracking">Backtracking Algorithm</a>
 */
public final class SubsequenceFinder {

    // Private constructor to prevent instantiation (utility class)
    private SubsequenceFinder() {
        throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
    }

    /**
     * Finds all subsequences of a given list using backtracking.
     * 
     * <p>This method returns a list containing all possible subsequences of the input sequence,
     * including the empty subsequence and the full original sequence.</p>
     *
     * @param originalSequence The input list for which to generate all subsequences (must not be null)
     * @param <T> The type of elements in the sequence
     * @return A list of all subsequences as lists of type T
     * @throws NullPointerException if originalSequence is null
     * 
     * @example
     * List&lt;Integer&gt; numbers = Arrays.asList(1, 2, 3);
     * List&lt;List&lt;Integer&gt;&gt; result = SubsequenceFinder.generateAllSubsequences(numbers);
     * // Result: [[], [3], [2], [2,3], [1], [1,3], [1,2], [1,2,3]] (order may vary)
     */
    public static <T> List<List<T>> generateAllSubsequences(List<T> originalSequence) {
        // Validate input
        if (originalSequence == null) {
            throw new NullPointerException("Input sequence cannot be null");
        }

        List<List<T>> allSubsequences = new ArrayList<>();

        // Edge case: Empty input → only the empty subsequence
        if (originalSequence.isEmpty()) {
            allSubsequences.add(new ArrayList<>());
            return allSubsequences;
        }

        List<T> currentSubsequence = new ArrayList<>();
        generateSubsequencesRecursive(originalSequence, currentSubsequence, 0, allSubsequences);
        return allSubsequences;
    }

    /**
     * Generates all subsequences and returns them as arrays (if needed for primitive types).
     * This convenience method works with arrays instead of lists.
     *
     * @param originalArray The input array to generate subsequences from
     * @param <T> The type of elements in the array
     * @return A list of all subsequences as arrays
     */
    public static <T> List<T[]> generateAllSubsequencesAsArrays(T[] originalArray) {
        List<List<T>> subsequenceLists = generateAllSubsequences(List.of(originalArray));
        List<T[]> subsequenceArrays = new ArrayList<>(subsequenceLists.size());

        for (List<T> subsequenceList : subsequenceLists) {
            @SuppressWarnings("unchecked")
            T[] subsequenceArray = (T[]) new Object[subsequenceList.size()];
            subsequenceArrays.add(subsequenceList.toArray(subsequenceArray));
        }
        return subsequenceArrays;
    }

    /**
     * Recursive backtracking algorithm to generate all subsequences.
     * 
     * <p>At each index, the algorithm branches into two paths:
     * <ul>
     *   <li>Skip the current element and recurse to the next index</li>
     *   <li>Include the current element and recurse to the next index</li>
     * </ul>
     * </p>
     * 
     * <p><b>Visualization for [1, 2, 3]:</b>
     * <pre>
     *                                   start (index=0, current=[])
     *                                  /                \
     *                    skip index0                     include index0
     *              (index=1, current=[])               (index=1, current=[1])
     *                /            \                     /           \
     *         skip 1           include 1          skip 1         include 1
     *    (idx=2, [])       (idx=2, [2])       (idx=2, [1])    (idx=2, [1,2])
     *      /    \            /    \             /    \          /     \
     *   skip2  include2   ...    ...          ...    ...      skip2  include2
     *    []      [3]                          
     * </pre>
     * </p>
     *
     * @param originalSequence The original input sequence
     * @param currentSubsequence The subsequence being built in the current recursion branch
     * @param currentIndex The current position in the sequence being considered
     * @param allSubsequences Collection to store all completed subsequences
     * @param <T> The type of elements
     */
    private static <T> void generateSubsequencesRecursive(List<T> originalSequence, 
                                                           List<T> currentSubsequence, 
                                                           final int currentIndex, 
                                                           List<List<T>> allSubsequences) {
        // Safe assertion to ensure we don't go out of bounds
        assert currentIndex <= originalSequence.size();

        // Base case: Reached the end of the sequence
        if (currentIndex == originalSequence.size()) {
            // Add a copy of the current subsequence to results
            allSubsequences.add(new ArrayList<>(currentSubsequence));
            return;
        }

        // BRANCH 1: Skip the current element
        generateSubsequencesRecursive(originalSequence, currentSubsequence, currentIndex + 1, allSubsequences);

        // BRANCH 2: Include the current element
        currentSubsequence.add(originalSequence.get(currentIndex));
        generateSubsequencesRecursive(originalSequence, currentSubsequence, currentIndex + 1, allSubsequences);

        // Backtrack: Remove the last element to restore state for upper recursion levels
        // Using removeLast() for efficiency (available in Java 21+)
        // For compatibility, can use remove(currentSubsequence.size() - 1)
        currentSubsequence.removeLast();
    }

    /**
     * Returns the total number of possible subsequences for a sequence of given length.
     * This is simply 2ⁿ where n is the length.
     *
     * @param sequenceLength The length of the original sequence
     * @return The total number of subsequences (2^sequenceLength)
     * @throws IllegalArgumentException if sequenceLength is negative
     */
    public static long getSubsequenceCount(int sequenceLength) {
        if (sequenceLength < 0) {
            throw new IllegalArgumentException("Sequence length cannot be negative: " + sequenceLength);
        }

        // 2ⁿ subsequences (including empty)
        return 1L << sequenceLength; // Bit shift for power of 2 calculation
    }

    /**
     * Generates subsequences of a fixed length k (combinations).
     * This is a specialized version that only returns subsequences with exactly k elements.
     *
     * @param originalSequence The input sequence
     * @param targetLength The desired length of subsequences (0 ≤ k ≤ n)
     * @param <T> The type of elements
     * @return List of subsequences of exactly length k
     * @throws IllegalArgumentException if k is out of valid range
     */
    public static <T> List<List<T>> generateSubsequencesOfLength(List<T> originalSequence, int targetLength) {
        if (originalSequence == null) {
            throw new NullPointerException("Input sequence cannot be null");
        }

        int n = originalSequence.size();
        if (targetLength < 0 || targetLength > n) {
            throw new IllegalArgumentException(
                String.format("Target length must be between 0 and %d (inclusive). Got: %d", n, targetLength)
            );
        }

        List<List<T>> subsequencesOfLength = new ArrayList<>();
        List<T> currentSubsequence = new ArrayList<>();
        generateSubsequencesOfLengthRecursive(originalSequence, currentSubsequence, 0, targetLength, subsequencesOfLength);
        return subsequencesOfLength;
    }

    /**
     * Recursive helper for generating subsequences of fixed length k.
     *
     * @param sequence Original sequence
     * @param current Current subsequence
     * @param index Current index
     * @param k Desired length
     * @param result Collection to store results
     * @param <T> Element type
     */
    private static <T> void generateSubsequencesOfLengthRecursive(List<T> sequence, 
                                                                   List<T> current, 
                                                                   int index, 
                                                                   int k, 
                                                                   List<List<T>> result) {
        // Base case: Reached desired length
        if (current.size() == k) {
            result.add(new ArrayList<>(current));
            return;
        }

        // Base case: Not enough remaining elements to reach k
        if (index >= sequence.size()) {
            return;
        }

        // Remaining elements needed
        int remainingNeeded = k - current.size();
        int remainingAvailable = sequence.size() - index;

        // Pruning: Not enough elements left
        if (remainingNeeded > remainingAvailable) {
            return;
        }

        // Branch 1: Skip current element
        generateSubsequencesOfLengthRecursive(sequence, current, index + 1, k, result);

        // Branch 2: Include current element
        current.add(sequence.get(index));
        generateSubsequencesOfLengthRecursive(sequence, current, index + 1, k, result);
        current.remove(current.size() - 1);
    }

    /**
     * Prints all subsequences in a formatted, readable way.
     *
     * @param subsequences The list of subsequences to print
     * @param <T> The type of elements
     */
    public static <T> void printAllSubsequences(List<List<T>> subsequences) {
        if (subsequences == null || subsequences.isEmpty()) {
            System.out.println("No subsequences found.");
            return;
        }

        System.out.printf("Total subsequences: %,d%n", subsequences.size());
        System.out.println("All subsequences:");

        int subsequenceIndex = 1;
        for (List<T> subsequence : subsequences) {
            System.out.printf("%6d: %s%n", subsequenceIndex++, subsequence);
        }
    }

    /**
     * Checks if one sequence is a subsequence of another sequence.
     *
     * @param potentialSubsequence The candidate subsequence to check
     * @param originalSequence The sequence to check against
     * @param <T> The type of elements
     * @return true if potentialSubsequence is a subsequence of originalSequence, false otherwise
     */
    public static <T> boolean isSubsequence(List<T> potentialSubsequence, List<T> originalSequence) {
        if (potentialSubsequence == null || originalSequence == null) {
            return false;
        }

        int subseqIndex = 0;
        int originalIndex = 0;

        while (subseqIndex < potentialSubsequence.size() && originalIndex < originalSequence.size()) {
            if (potentialSubsequence.get(subseqIndex).equals(originalSequence.get(originalIndex))) {
                subseqIndex++;
            }
            originalIndex++;
        }

        return subseqIndex == potentialSubsequence.size();
    }
}

/*
COMPREHENSIVE DOCUMENTATION
===========================

SUBSEQUENCE VS SUBSTRING VS SUBSET
==================================

| Term | Definition | Example (ABC) | Count |
|------|------------|---------------|-------|
| Subsequence | Any sequence from original by deleting elements (order preserved) | "A", "B", "C", "AB", "AC", "BC", "ABC", "" | 2ⁿ |
| Substring | Contiguous sequence from original | "A", "B", "C", "AB", "BC", "ABC", "" | n×(n+1)/2 + 1 |
| Subset | Unordered selection (order doesn't matter) | {}, {A}, {B}, {C}, {A,B}, {A,C}, {B,C}, {A,B,C} | 2ⁿ |
| Permutation | Ordered arrangement (all elements used) | ABC, ACB, BAC, BCA, CAB, CBA | n! |

BITMASK REPRESENTATION
======================

For a sequence of n elements, each subsequence can be represented by a binary mask:
- 0 at position i → element i is excluded
- 1 at position i → element i is included

Example for [A, B, C]:
- mask 000 (0)  → []
- mask 001 (1)  → [C]
- mask 010 (2)  → [B]
- mask 011 (3)  → [B, C]
- mask 100 (4)  → [A]
- mask 101 (5)  → [A, C]
- mask 110 (6)  → [A, B]
- mask 111 (7)  → [A, B, C]

ITERATIVE APPROACH (BITMASK)
===========================

Alternative implementation without recursion:

public static <T> List<List<T>> generateAllIterative(List<T> sequence) {
    List<List<T>> result = new ArrayList<>();
    int n = sequence.size();
    int total = 1 << n; // 2^n

    for (int mask = 0; mask < total; mask++) {
        List<T> subsequence = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) {
                subsequence.add(sequence.get(i));
            }
        }
        result.add(subsequence);
    }
    return result;
}

RECURSION DEPTH ANALYSIS
=======================

For n = 3:
Depth 0: index=0, current=[]
├─ Skip A: index=1, current=[]
│  ├─ Skip B: index=2, current=[]
│  │  ├─ Skip C: index=3 → add []
│  │  └─ Include C: index=3 → add [C]
│  └─ Include B: index=2, current=[B]
│     ├─ Skip C: index=3 → add [B]
│     └─ Include C: index=3 → add [B,C]
└─ Include A: index=1, current=[A]
   ├─ Skip B: index=2, current=[A]
   │  ├─ Skip C: index=3 → add [A]
   │  └─ Include C: index=3 → add [A,C]
   └─ Include B: index=2, current=[A,B]
      ├─ Skip C: index=3 → add [A,B]
      └─ Include C: index=3 → add [A,B,C]

SUBSEQUENCE COUNT BY LENGTH
==========================

For a sequence of length n:

| n | Total (2ⁿ) | Breakdown by length (k) |
|---|-----------|--------------------------|
| 1 | 2         | k=0:1, k=1:1 |
| 2 | 4         | k=0:1, k=1:2, k=2:1 |
| 3 | 8         | k=0:1, k=1:3, k=2:3, k=3:1 |
| 4 | 16        | k=0:1, k=1:4, k=2:6, k=3:4, k=4:1 |
| 5 | 32        | k=0:1, k=1:5, k=2:10, k=3:10, k=4:5, k=5:1 |

Formula: C(n,k) = n!/(k!×(n-k)!) subsequences of length k

COMPLEXITY COMPARISON
====================

| Aspect | Recursive Backtracking | Iterative (Bitmask) | Iterative (DP) |
|--------|----------------------|---------------------|----------------|
| Time | O(2ⁿ×n) | O(2ⁿ×n) | O(2ⁿ×n) |
| Space (stack) | O(n) | O(1) | O(1) |
| Space (results) | O(2ⁿ×n) | O(2ⁿ×n) | O(2ⁿ×n) |
| Readability | High | Medium | Medium |
| Memory overhead | Low-medium | Low | Low |

ADVANCED APPLICATIONS
=====================

1. String Processing:
   - Finding all substrings (contiguous variant)
   - Pattern matching in sequences

2. Biological Sequence Analysis:
   - DNA/protein subsequence matching
   - Gene sequence alignment

3. Data Compression:
   - Longest common subsequence (LCS) algorithm
   - Diff utilities (git diff, file comparison)

4. Natural Language Processing:
   - Sentence subsequences for paraphrasing
   - Phrase extraction

5. Machine Learning:
   - Feature subset selection
   - Sequence generation for RNNs

6. Algorithm Design:
   - Dynamic programming preprocessing
   - Power set generation for combinatorial problems

RELATED PROBLEMS
================

1. Longest Common Subsequence (LCS) - Find longest subsequence present in two sequences
2. Shortest Common Supersequence (SCS) - Shortest sequence containing both as subsequences
3. Increasing Subsequence - Find longest increasing subsequence
4. Distinct Subsequences - Count distinct subsequences in a string
5. Subsequence with Constraints - Subsequences with sum constraints, etc.

OPTIMIZATION TECHNIQUES
======================

1. Memoization:
   - Cache results for repeated subproblems
   - Useful when same sequence is processed multiple times

2. Iterative Generation with Pruning:
   - Use bitmask to avoid recursion overhead
   - Early termination when partial subsequence already invalid

3. Parallel Generation:
   - Split mask space among multiple threads
   - Each thread processes a contiguous range of masks

4. Lazy Generation:
   - Use Iterator pattern to generate subsequences on-demand
   - Saves memory when not all subsequences needed

SAMPLE USAGE
===========

public static void main(String[] args) {
    // Character subsequences
    List<Character> chars = List.of('A', 'B', 'C');
    List<List<Character>> allChars = SubsequenceFinder.generateAllSubsequences(chars);
    SubsequenceFinder.printAllSubsequences(allChars);

    // Integer subsequences
    List<Integer> numbers = List.of(1, 2, 3, 4);
    List<List<Integer>> allNumbers = SubsequenceFinder.generateAllSubsequences(numbers);
    System.out.println("\nTotal: " + SubsequenceFinder.getSubsequenceCount(4));

    // Subsequences of specific length
    List<List<Integer>> length2 = SubsequenceFinder.generateSubsequencesOfLength(numbers, 2);
    System.out.println("\nSubsequences of length 2: " + length2);

    // Check subsequence relationship
    List<Integer> subList = List.of(1, 3);
    boolean isSub = SubsequenceFinder.isSubsequence(subList, numbers);
    System.out.println("Is [1,3] a subsequence of [1,2,3,4]? " + isSub);

    // Using array version
    String[] words = {"hello", "world", "java"};
    List<String[]> arraySubseqs = SubsequenceFinder.generateAllSubsequencesAsArrays(words);
    System.out.println("\nArray subsequences count: " + arraySubseqs.size());
}

MEMORY USAGE EXAMPLE
===================

For n=20: Total subsequences = 2²⁰ = 1,048,576
Each stored as ArrayList<Integer> with average size ~10 elements
Memory per Integer: ~28 bytes (object overhead) + 8 bytes (index)
Each ArrayList: ~40 bytes overhead
Total: ~ 1M × (10×28 + 40) ≈ 320 MB

For n=20, iterating with generator pattern would be more memory-efficient.

KNOWLEDGE BASE SUMMARY
======================

Time:    O(2ⁿ × n)
Space:   O(2ⁿ × n) for full storage, O(n) for streaming
Stable:  Yes (order preserved within subsequences)
Type:    Generic (works with any type T)
Optimal: Yes for generating all subsequences
Use when: n ≤ 20 for full generation, or use iterative approach for larger n
*/ 
