package com.thealgorithms.ciphers;

import java.math.BigInteger;
import java.security.SecureRandom;

/**
 * RSA is an asymmetric cryptographic algorithm used for secure data encryption and decryption.
 * It relies on a pair of keys: a public key (used for encryption) and a private key
 * (used for decryption). The algorithm is based on the difficulty of factoring large prime numbers.
 *
 * This implementation includes key generation, encryption, and decryption methods that can handle both
 * text-based messages and BigInteger inputs. For more details on RSA:
 * <a href="https://en.wikipedia.org/wiki/RSA_(cryptosystem)">RSA Cryptosystem - Wikipedia</a>.
 *
 * Example Usage:
 * <pre>
 * RSA rsa = new RSA(1024);
 * String encryptedMessage = rsa.encrypt("Hello RSA!");
 * String decryptedMessage = rsa.decrypt(encryptedMessage);
 * System.out.println(decryptedMessage);  // Output: Hello RSA!
 * </pre>
 *
 * Note: The key size directly affects the security and performance of the RSA algorithm.
 * Larger keys are more secure but slower to compute.
 *
 * @author Nguyen Duy Tiep
 * @version 23-Oct-17
 */
public class RSA {

private BigInteger modulusValue;
private BigInteger privateKeyValue;
private BigInteger publicKeyValue;

/**
 * Constructor that generates RSA keys with the specified number of bits.
 *
 * @param keySize The bit length of the keys to be generated. Common sizes include 512, 1024, 2048, etc.
 */
public RSA(int keySize) {
generateKeyPair(keySize);
}

/**
 * Encrypts a text message using the RSA public key.
 *
 * @param inputMessage The plaintext message to be encrypted.
 * @throws IllegalArgumentException If the message is empty.
 * @return The encrypted message represented as a String.
 */
public synchronized String encrypt(String inputMessage) {
if (inputMessage.isEmpty()) {
throw new IllegalArgumentException("Message is empty");
}
return (new BigInteger(inputMessage.getBytes())).modPow(publicKeyValue, modulusValue).toString();
}

/**
 * Encrypts a BigInteger message using the RSA public key.
 *
 * @param inputMessage The plaintext message as a BigInteger.
 * @return The encrypted message as a BigInteger.
 */
public synchronized BigInteger encrypt(BigInteger inputMessage) {
return inputMessage.modPow(publicKeyValue, modulusValue);
}

/**
 * Decrypts an encrypted message (as String) using the RSA private key.
 *
 * @param encryptedData The encrypted message to be decrypted, represented as a String.
 * @throws IllegalArgumentException If the message is empty.
 * @return The decrypted plaintext message as a String.
 */
public synchronized String decrypt(String encryptedData) {
if (encryptedData.isEmpty()) {
throw new IllegalArgumentException("Message is empty");
}
return new String((new BigInteger(encryptedData)).modPow(privateKeyValue, modulusValue).toByteArray());
}

/**
 * Decrypts an encrypted BigInteger message using the RSA private key.
 *
 * @param encryptedData The encrypted message as a BigInteger.
 * @return The decrypted plaintext message as a BigInteger.
 */
public synchronized BigInteger decrypt(BigInteger encryptedData) {
return encryptedData.modPow(privateKeyValue, modulusValue);
}

/**
 * Generates a new RSA key pair (public and private keys) with the specified bit length.
 * Steps:
 * 1. Generate two large prime numbers p and q.
 * 2. Compute the modulus n = p * q.
 * 3. Compute Euler's totient function: φ(n) = (p-1) * (q-1).
 * 4. Choose a public key e (starting from 3) that is coprime with φ(n).
 * 5. Compute the private key d as the modular inverse of e mod φ(n).
 * The public key is (e, n) and the private key is (d, n).
 *
 * @param keySize The bit length of the keys to be generated.
 */
public final synchronized void generateKeyPair(int keySize) {
SecureRandom randomGenerator = new SecureRandom();
BigInteger primeP = new BigInteger(keySize / 2, 100, randomGenerator);
BigInteger primeQ = new BigInteger(keySize / 2, 100, randomGenerator);
modulusValue = primeP.multiply(primeQ);
BigInteger phiValue = (primeP.subtract(BigInteger.ONE)).multiply(primeQ.subtract(BigInteger.ONE));
publicKeyValue = BigInteger.valueOf(3L);
while (phiValue.gcd(publicKeyValue).intValue() > 1) {
publicKeyValue = publicKeyValue.add(BigInteger.TWO);
}
privateKeyValue = publicKeyValue.modInverse(phiValue);
}
}

