/**
 * This class provides a method to detect if two integers
 * differ by exactly one bit flip.
 *
 * Example:
 * 1 (0001) and 2 (0010) differ by exactly one bit flip.
 * 7 (0111) and 3 (0011) differ by exactly one bit flip.
 *
 * @author Hardvan
 */
public final class OneBitDifference {
private OneBitDifference() {
}

/**
 * Checks if two integers differ by exactly one bit.
 *
 * @param firstNumber the first integer
 * @param secondNumber the second integer
 * @return true if firstNumber and secondNumber differ by exactly one bit, false otherwise
 */
public static boolean differByOneBit(int firstNumber, int secondNumber) {
if (firstNumber == secondNumber) {
return false;
}
int xorResult = firstNumber ^ secondNumber;
return (xorResult & (xorResult - 1)) == 0;
}
}

/**
 * The simple substitution cipher is a cipher that has been in use for many
 * hundreds of years (an excellent history is given in Simon Singhs 'the Code
 * Book'). It basically consists of substituting every plaintext character for a
 * different ciphertext character. It differs from the Caesar cipher in that the
 * cipher alphabet is not simply the alphabet shifted, it is completely jumbled.
 */
public class SimpleSubCipher {

/**
 * Encrypt text by replacing each element with its opposite character.
 *
 * @param inputMessage
 * @param substitutionKey
 * @return Encrypted message
 */
public String encode(String inputMessage, String substitutionKey) {
StringBuilder encryptedResult = new StringBuilder();
Map<Character, Character> substitutionMap = new HashMap<>();
char smallLetterStart = 'a';
char capitalLetterStart = 'A';
substitutionKey = substitutionKey.toLowerCase();
String capitalKey = substitutionKey.toUpperCase();
for (int index = 0; index < substitutionKey.length(); index++) {
substitutionMap.put(smallLetterStart++, substitutionKey.charAt(index));
substitutionMap.put(capitalLetterStart++, capitalKey.charAt(index));
}
for (int position = 0; position < inputMessage.length(); position++) {
if (Character.isAlphabetic(inputMessage.charAt(position))) {
encryptedResult.append(substitutionMap.get(inputMessage.charAt(position)));
} else {
encryptedResult.append(inputMessage.charAt(position));
}
}
return encryptedResult.toString();
}

/**
 * Decrypt message by replacing each element with its opposite character in
 * cipher.
 *
 * @param encryptedData
 * @param substitutionKey
 * @return message
 */
public String decode(String encryptedData, String substitutionKey) {
StringBuilder decryptedResult = new StringBuilder();
Map<Character, Character> reverseMap = new HashMap<>();
char smallLetterStart = 'a';
char capitalLetterStart = 'A';
substitutionKey = substitutionKey.toLowerCase();
String capitalKey = substitutionKey.toUpperCase();
for (int index = 0; index < substitutionKey.length(); index++) {
reverseMap.put(substitutionKey.charAt(index), smallLetterStart++);
reverseMap.put(capitalKey.charAt(index), capitalLetterStart++);
}
for (int position = 0; position < encryptedData.length(); position++) {
if (Character.isAlphabetic(encryptedData.charAt(position))) {
decryptedResult.append(reverseMap.get(encryptedData.charAt(position)));
} else {
decryptedResult.append(encryptedData.charAt(position));
}
}
return decryptedResult.toString();
}
}

package recursive; 
import java.util.Scanner;

public class Faktoriyel {

	// Rekursif olarak faktoriyel hesaplayan metod
	public static int recursiveFaktoriyel(int sayi) {
		int sonuc = 0; // Baslangic degeri
		// Eger sayi 0 ise, faktoriyel 1 olarak kabul edilir
		if (sayi == sonuc) {
			return sonuc + 1;
		}
		// Aksi takdirde, ozyinelemeli olarak sayi * (sayi-1)'in faktoriyeli hesaplanir
		return sayi * recursiveFaktoriyel(sayi - 1);
	}

	// Dongu ile faktoriyel hesaplayan metod
	public static int iterativeFaktoriyel(int sayi) {
		int sonuc = 1; // Sonuc 1 olarak alinir

		// 1'den sayiya kadar olan sayilari carpip faktoriyel hesaplanir
		for (int i = 1; i <= sayi; i++) {
			sonuc *= i;
		}
		return sonuc;
	}

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		System.out.print("Faktoriyelini hesaplamak icin bir sayi girin: ");
		int sayi = sc.nextInt();
		sc.close();

		// Sonucu ekrana yazdir
		System.out.println(sayi + " sayisinin faktoriyeli (iterative): " + iterativeFaktoriyel(sayi));
		System.out.println(sayi + " sayisinin faktoriyeli (rekursive): " + recursiveFaktoriyel(sayi));
	}
}

/**
 * A 3D point that extends Point2D by adding a Z coordinate.
 */
public class Point3D extends Point2D {
    private float z;

    public Point3D() {
    }

    public Point3D(float x, float y, float z) {
        super(x, y);
        this.z = z;
    }

    public float getZ() {
        return z;
    }

    public void setZ(float z) {
        this.z = z;
    }

    public void setXYZ(float x, float y, float z) {
        setXY(x, y);
        this.z = z;
    }

    public float[] getXYZ() {
        return new float[]{getX(), getY(), z};
    }

    @Override
    public String toString() {
        // mirrors the original's typo: closes with '}' instead of ')'
        return "(" + getX() + "," + getY() + "," + z + '}';
    }
}

/**
 *
 * Author: Janmesh Singh
 * Github: https://github.com/janmeshjs

 * Problem Statement: To determine if the pattern matches the text.
 * The pattern can include two special wildcard characters:
 *       ' ? ': Matches any single character.
 *       ' * ': Matches zero or more of any character sequence.
 *
 * Use DP to return True if the pattern matches the entire text and False otherwise
 *
 */
public final class WildcardMatching {
    private WildcardMatching() {
    }

    public static boolean isMatch(String text, String pattern) {
        int m = text.length();
        int n = pattern.length();

        // Create a DP table to store intermediate results
        boolean[][] dp = new boolean[m + 1][n + 1];

        // Base case: an empty pattern matches an empty text
        dp[0][0] = true;

        // Handle patterns starting with '*'
        for (int j = 1; j <= n; j++) {
            if (pattern.charAt(j - 1) == '*') {
                dp[0][j] = dp[0][j - 1];
            }
        }

        // Fill the DP table
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                char textChar = text.charAt(i - 1);
                char patternChar = pattern.charAt(j - 1);

                if (patternChar == textChar || patternChar == '?') {
                    dp[i][j] = dp[i - 1][j - 1];
                } else if (patternChar == '*') {
                    // '*' can match zero or more characters
                    dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
                } else {
                    dp[i][j] = false;
                }
            }
        }
        // The result is in the bottom-right cell of the DP table
        return dp[m][n];
    }
}

package com.thealgorithms.backtracking;

/**
 * This class contains methods to solve a maze using recursive backtracking.
 * The maze is represented as a 2D array where walls, paths, and visited/dead
 * ends are marked with different integers.
 *
 * The goal is to find a path from a starting position to the target position
 * (map[6][5]) while navigating through the maze.
 */
public final class MazeRecursion {

    private MazeRecursion() {
    }

    /**
     * This method solves the maze using the "down -> right -> up -> left"
     * movement strategy.
     *
     * @param map The 2D array representing the maze (walls, paths, etc.)
     * @return The solved maze with paths marked, or null if no solution exists.
     */
    public static int[][] solveMazeUsingFirstStrategy(int[][] map) {
        if (setWay(map, 1, 1)) {
            return map;
        }
        return null;
    }

    /**
     * This method solves the maze using the "up -> right -> down -> left"
     * movement strategy.
     *
     * @param map The 2D array representing the maze (walls, paths, etc.)
     * @return The solved maze with paths marked, or null if no solution exists.
     */
    public static int[][] solveMazeUsingSecondStrategy(int[][] map) {
        if (setWay2(map, 1, 1)) {
            return map;
        }
        return null;
    }

    /**
     * Attempts to find a path through the maze using a "down -> right -> up -> left"
     * movement strategy. The path is marked with '2' for valid paths and '3' for dead ends.
     *
     * @param map The 2D array representing the maze (walls, paths, etc.)
     * @param i   The current x-coordinate of the ball (row index)
     * @param j   The current y-coordinate of the ball (column index)
     * @return True if a path is found to (6,5), otherwise false
     */
    private static boolean setWay(int[][] map, int i, int j) {
        if (map[6][5] == 2) {
            return true;
        }

        // If the current position is unvisited (0), explore it
        if (map[i][j] == 0) {
            // Mark the current position as '2'
            map[i][j] = 2;

            // Move down
            if (setWay(map, i + 1, j)) {
                return true;
            }
            // Move right
            else if (setWay(map, i, j + 1)) {
                return true;
            }
            // Move up
            else if (setWay(map, i - 1, j)) {
                return true;
            }
            // Move left
            else if (setWay(map, i, j - 1)) {
                return true;
            }

            map[i][j] = 3; // Mark as dead end (3) if no direction worked
            return false;
        }
        return false;
    }

    /**
     * Attempts to find a path through the maze using an alternative movement
     * strategy "up -> right -> down -> left".
     *
     * @param map The 2D array representing the maze (walls, paths, etc.)
     * @param i   The current x-coordinate of the ball (row index)
     * @param j   The current y-coordinate of the ball (column index)
     * @return True if a path is found to (6,5), otherwise false
     */
    private static boolean setWay2(int[][] map, int i, int j) {
        if (map[6][5] == 2) {
            return true;
        }

        if (map[i][j] == 0) {
            map[i][j] = 2;

            // Move up
            if (setWay2(map, i - 1, j)) {
                return true;
            }
            // Move right
            else if (setWay2(map, i, j + 1)) {
                return true;
            }
            // Move down
            else if (setWay2(map, i + 1, j)) {
                return true;
            }
            // Move left
            else if (setWay2(map, i, j - 1)) {
                return true;
            }

            map[i][j] = 3; // Mark as dead end (3) if no direction worked
            return false;
        }
        return false;
    }
}

/**
 * This class provides methods to convert between XS-3 (Excess-3) and binary.
 *
 * Excess-3, also called XS-3, is a binary-coded decimal (BCD) code in which each decimal digit is represented by its corresponding 4-bit binary value plus 3.
 *
 * For more information, refer to the
 * <a href="https://en.wikipedia.org/wiki/Excess-3">Excess-3</a> Wikipedia page.
 *
 * <b>Example usage:</b>
 * <pre>
 * int binary = Xs3Conversion.xs3ToBinary(0x4567);
 * System.out.println("XS-3 0x4567 to binary: " + binary); // Output: 1234
 *
 * int xs3 = Xs3Conversion.binaryToXs3(1234);
 * System.out.println("Binary 1234 to XS-3: " + Integer.toHexString(xs3)); // Output: 0x4567
 * </pre>
 */
public final class Xs3Conversion {
    private Xs3Conversion() {
    }
    /**
     * Converts an XS-3 (Excess-3) number to binary.
     *
     * @param xs3 The XS-3 number.
     * @return The corresponding binary number.
     */
    public static int xs3ToBinary(int xs3) {
        int binary = 0;
        int multiplier = 1;
        while (xs3 > 0) {
            int digit = (xs3 & 0xF) - 3; // Extract the last 4 bits (one XS-3 digit) and subtract 3
            binary += digit * multiplier;
            multiplier *= 10;
            xs3 >>= 4; // Shift right by 4 bits to process the next XS-3 digit
        }
        return binary;
    }

    /**
     * Converts a binary number to XS-3 (Excess-3).
     *
     * @param binary The binary number.
     * @return The corresponding XS-3 number.
     */
    public static int binaryToXs3(int binary) {
        int xs3 = 0;
        int shift = 0;
        while (binary > 0) {
            int digit = (binary % 10) + 3; // Extract the last decimal digit and add 3
            xs3 |= (digit << (shift * 4)); // Shift the digit to the correct XS-3 position
            binary /= 10; // Remove the last decimal digit
            shift++;
        }
        return xs3;
    }
}

package com.thealgorithms.conversions;

/**
 * Converts an IPv4 address to its binary equivalent and vice-versa.
 * IP to Binary: Converts an IPv4 address to its binary equivalent.
 * Example: 127.3.4.5 -> 01111111.00000011.00000100.00000101
 *
 * Binary to IP: Converts a binary equivalent to an IPv4 address.
 * Example: 01111111.00000011.00000100.00000101 -> 127.3.4.5
 *
 * @author Hardvan
 */
public final class IPConverter {
    private IPConverter() {
    }

    /**
     * Converts an IPv4 address to its binary equivalent.
     * @param ip The IPv4 address to convert.
     * @return The binary equivalent of the IPv4 address.
     */
    public static String ipToBinary(String ip) {
        StringBuilder binary = new StringBuilder();
        for (String octet : ip.split("\\.")) {
            binary.append(octetToBinary(Integer.parseInt(octet))).append(".");
        }
        return binary.substring(0, binary.length() - 1);
    }

    /**
     * Converts a single octet to its 8-bit binary representation.
     * @param octet The octet to convert (0-255).
     * @return The 8-bit binary representation as a String.
     */
    private static String octetToBinary(int octet) {
        char[] binary = {'0', '0', '0', '0', '0', '0', '0', '0'};
        for (int i = 7; i >= 0; i--) {
            if ((octet & 1) == 1) {
                binary[i] = '1';
            }
            octet >>>= 1;
        }
        return new String(binary);
    }

    /**
     * Converts a binary equivalent to an IPv4 address.
     * @param binary The binary equivalent to convert.
     * @return The IPv4 address of the binary equivalent.
     */
    public static String binaryToIP(String binary) {
        StringBuilder ip = new StringBuilder();
        for (String octet : binary.split("\\.")) {
            ip.append(Integer.parseInt(octet, 2)).append(".");
        }
        return ip.substring(0, ip.length() - 1);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class TodoListApp {
    private static final List<String> tasks = new ArrayList<>();

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        boolean running = true;

        while (running) {
            System.out.println("\n1. Add task\n2. Show tasks\n3. Remove task\n4. Exit");
            System.out.print("Choose: ");
            int choice = scanner.nextInt();
            scanner.nextLine();

            switch (choice) {
                case 1:
                    System.out.print("Task description: ");
                    tasks.add(scanner.nextLine());
                    System.out.println("Task added.");
                    break;
                case 2:
                    if (tasks.isEmpty()) {
                        System.out.println("No tasks yet.");
                    } else {
                        for (int i = 0; i < tasks.size(); i++) {
                            System.out.println((i + 1) + ". " + tasks.get(i));
                        }
                    }
                    break;
                case 3:
                    System.out.print("Task number to remove: ");
                    int index = scanner.nextInt() - 1;
                    if (index >= 0 && index < tasks.size()) {
                        System.out.println("Removed: " + tasks.remove(index));
                    } else {
                        System.out.println("Invalid task number.");
                    }
                    break;
                case 4:
                    running = false;
                    break;
                default:
                    System.out.println("Unknown option.");
            }
        }
        scanner.close();
    }
}

package forloop;

public class BreakOrnegi {

    // For dongusunde break kullanimi
    public static void forDongusuOrnegi() {
        System.out.println("For dongusu ornegi:");
        for (int i = 1; i <= 10; i++) {
            if (i == 5) { // Deger 5 oldugunda dongu kirilir
                System.out.println("Dongu 5 degerinde kirildi!");
                break;
            }
            System.out.println("Dongu adimi: " + i);
        }
    }

    // While dongusunde break kullanimi
    public static void whileDongusuOrnegi() {
        System.out.println("\nWhile dongusu ornegi:");
        int i = 1;
        while (i <= 10) {
            if (i == 7) { // Deger 7 oldugunda dongu kirilir
                System.out.println("Dongu 7 degerinde kirildi!");
                break;
            }
            System.out.println("Dongu adimi: " + i);
            i++;
        }
    }

    // Ic ice dongulerde break kullanimi
    public static void icIceDongulerOrnegi() {
        System.out.println("\nIc ice donguler ornegi:");
        for (int i = 1; i <= 4; i++) {
            for (int j = 1; j <= 4; j++) {
                if (j == 2) { // Ic dongu belirli bir sartta kirilir
                    System.out.println("Ic dongu j = 2 de kirildi (i = " + i + ")");
                    break;
                }
                System.out.println("i: " + i + ", j: " + j);
            }
        }
    }

    public static void main(String[] args) {
        // For dongusu ornegi
        forDongusuOrnegi();

        // While dongusu ornegi
        whileDongusuOrnegi();

        // Ic ice donguler ornegi
        icIceDongulerOrnegi();
    }
}

