/*
 * Girilen tam sayinin ciftlik durumu, 2'ye bolumunden kalan uzerinden
 * belirlenir. Kalan sifirsa sayi cift, degilse tektir.
 */

public class TekMiCiftMi {

    public static void main(String[] args) {

        Scanner girdi = new Scanner(System.in);

        System.out.println("Bir sayi giriniz: ");
        int deger = girdi.nextInt();
        girdi.close();

        String durum = (deger % 2 == 0) ? "cift" : "tek";

        System.out.println(deger + " " + durum + " bir sayidir.");
    }
}

public class ArtanSiraIkiSayi {

	public static void main(String[] args) {

		Scanner scanner = new Scanner(System.in);

		System.out.println("ilk sayiyi girin: ");
		int sayi1 = scanner.nextInt();

		System.out.println("ikinci sayiyi girin: ");
		int sayi2 = scanner.nextInt();

		scanner.close();

		// iki sayiyi artan sirada yazdirma
		if (sayi1 < sayi2) {
			System.out.println("Artan sirayla: " + sayi1 + ", " + sayi2);
		} else {
			System.out.println("Artan sirayla: " + sayi2 + ", " + sayi1);
		}
	}
}

/**
 * A generic implementation of a max heap data structure.
 *
 * @param <ElementType> the type of elements in this heap, must extend Comparable.
 */
public class GenericHeap<ElementType extends Comparable<ElementType>> {

private final ArrayList<ElementType> heapArray = new ArrayList<>();
private final HashMap<ElementType, Integer> positionMap = new HashMap<>();

/**
 * Adds an item to the heap, maintaining the heap property.
 *
 * @param newItem the item to be added
 */
public void insert(ElementType newItem) {
if (newItem == null) {
throw new IllegalArgumentException("Cannot insert null into the heap.");
}
this.heapArray.add(newItem);
positionMap.put(newItem, this.heapArray.size() - 1);
siftUp(this.heapArray.size() - 1);
}

/**
 * Restores the heap property by moving the item at the given index upwards.
 *
 * @param childIndex the index of the current item
 */
private void siftUp(int childIndex) {
int parentIndex = (childIndex - 1) / 2;
if (childIndex > 0 && compareValues(this.heapArray.get(childIndex), this.heapArray.get(parentIndex)) > 0) {
swapPositions(parentIndex, childIndex);
siftUp(parentIndex);
}
}

/**
 * Returns the number of elements in the heap.
 *
 * @return the size of the heap
 */
public int getSize() {
return this.heapArray.size();
}

/**
 * Checks if the heap is empty.
 *
 * @return true if the heap is empty, false otherwise
 */
public boolean isEmpty() {
return this.getSize() == 0;
}

/**
 * Removes and returns the maximum item from the heap.
 *
 * @return the maximum item
 */
public ElementType extractMax() {
if (isEmpty()) {
throw new IllegalStateException("Heap is empty");
}
this.swapPositions(0, this.getSize() - 1);
ElementType removedValue = this.heapArray.remove(this.getSize() - 1);
positionMap.remove(removedValue);
siftDown(0);
return removedValue;
}

/**
 * Restores the heap property by moving the item at the given index downwards.
 *
 * @param parentIndex the index of the current item
 */
private void siftDown(int parentIndex) {
int leftChild = 2 * parentIndex + 1;
int rightChild = 2 * parentIndex + 2;
int largestIndex = parentIndex;
if (leftChild < this.getSize() && compareValues(this.heapArray.get(leftChild), this.heapArray.get(largestIndex)) > 0) {
largestIndex = leftChild;
}
if (rightChild < this.getSize() && compareValues(this.heapArray.get(rightChild), this.heapArray.get(largestIndex)) > 0) {
largestIndex = rightChild;
}
if (largestIndex != parentIndex) {
this.swapPositions(parentIndex, largestIndex);
siftDown(largestIndex);
}
}

/**
 * Retrieves the maximum item from the heap without removing it.
 *
 * @return the maximum item
 */
public ElementType peekMax() {
if (isEmpty()) {
throw new IllegalStateException("Heap is empty");
}
return this.heapArray.getFirst();
}

/**
 * Compares two items to determine their order.
 *
 * @param firstItem the first item
 * @param secondItem the second item
 * @return a positive integer if firstItem is greater than secondItem, negative if firstItem is less, and zero if they are equal
 */
private int compareValues(ElementType firstItem, ElementType secondItem) {
return firstItem.compareTo(secondItem);
}

/**
 * Swaps two items in the heap and updates their indices in the map.
 *
 * @param firstIndex index of the first item
 * @param secondIndex index of the second item
 */
private void swapPositions(int firstIndex, int secondIndex) {
ElementType firstElement = this.heapArray.get(firstIndex);
ElementType secondElement = this.heapArray.get(secondIndex);
this.heapArray.set(firstIndex, secondElement);
this.heapArray.set(secondIndex, firstElement);
positionMap.put(firstElement, secondIndex);
positionMap.put(secondElement, firstIndex);
}

/**
 * Updates the priority of the specified item by restoring the heap property.
 *
 * @param targetItem the item whose priority is to be updated
 */
public void adjustPriority(ElementType targetItem) {
if (!positionMap.containsKey(targetItem)) {
throw new IllegalArgumentException("Item not found in the heap");
}
int currentIndex = positionMap.get(targetItem);
siftUp(currentIndex);
}
}

/**
 * Finds all possible simple paths from a given source vertex to a destination vertex
 * in a directed graph using backtracking.
 *
 * <p>This algorithm performs a Depth First Search (DFS) traversal while keeping track
 * of visited vertices to avoid cycles. Whenever the destination vertex is reached,
 * the current path is stored as one valid path.</p>
 *
 * <p><b>Key Characteristics:</b></p>
 * <ul>
 *   <li>Works on directed graphs</li>
 *   <li>Does not allow revisiting vertices in the same path</li>
 *   <li>Stores all possible paths from source to destination</li>
 * </ul>
 *
 * <p><b>Time Complexity:</b></p>
 * <ul>
 *   <li>Worst Case: O(V!) — when the graph is fully connected</li>
 * </ul>
 *
 * <p><b>Space Complexity:</b></p>
 * <ul>
 *   <li>O(V) for recursion stack and visited array</li>
 *   <li>Additional space for storing all valid paths</li>
 * </ul>
 *
 * <p>This implementation is intended for educational purposes.</p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Depth-first_search">Depth First Search</a>
 */

@SuppressWarnings({"rawtypes", "unchecked"})
public class AllPathsFromSourceToTarget {

    // No. of vertices in graph
    private final int v;

    // To store the paths from source to destination
    static List<List<Integer>> nm = new ArrayList<>();
    // adjacency list
    private ArrayList<Integer>[] adjList;

    // Constructor
    public AllPathsFromSourceToTarget(int vertices) {

        // initialise vertex count
        this.v = vertices;

        // initialise adjacency list
        initAdjList();
    }

    // utility method to initialise adjacency list
    private void initAdjList() {
        adjList = new ArrayList[v];

        for (int i = 0; i < v; i++) {
            adjList[i] = new ArrayList<>();
        }
    }

    // add edge from u to v
    public void addEdge(int u, int v) {
        // Add v to u's list.
        adjList[u].add(v);
    }

    public void storeAllPaths(int s, int d) {
        boolean[] isVisited = new boolean[v];
        ArrayList<Integer> pathList = new ArrayList<>();

        // add source to path[]
        pathList.add(s);
        // Call recursive utility
        storeAllPathsUtil(s, d, isVisited, pathList);
    }

    // A recursive function to print all paths from 'u' to 'd'.
    // isVisited[] keeps track of vertices in current path.
    // localPathList<> stores actual vertices in the current path
    private void storeAllPathsUtil(Integer u, Integer d, boolean[] isVisited, List<Integer> localPathList) {

        if (u.equals(d)) {
            nm.add(new ArrayList<>(localPathList));
            return;
        }

        // Mark the current node
        isVisited[u] = true;

        // Recursion for all the vertices adjacent to current vertex

        for (Integer i : adjList[u]) {
            if (!isVisited[i]) {
                // store current node in path[]
                localPathList.add(i);
                storeAllPathsUtil(i, d, isVisited, localPathList);

                // remove current node in path[]
                localPathList.remove(i);
            }
        }

        // Mark the current node
        isVisited[u] = false;
    }

    // Driver program
    public static List<List<Integer>> allPathsFromSourceToTarget(int vertices, int[][] a, int source, int destination) {
        // Create a sample graph
        AllPathsFromSourceToTarget g = new AllPathsFromSourceToTarget(vertices);
        for (int[] i : a) {
            g.addEdge(i[0], i[1]);
            // edges are added
        }
        g.storeAllPaths(source, destination);
        // method call to store all possible paths
        return nm;
        // returns all possible paths from source to destination
    }
}

import java.util.Scanner;

public class AsalSayiKontrolu {

    public static void main(String[] args) {

        Scanner okuyucu = new Scanner(System.in);

        // Kullanicidan gecerli bir sayi gelene kadar sormaya devam ediyoruz
        System.out.print("Bir sayi girin: ");
        int deger = okuyucu.nextInt();

        while (deger <= 1) {
            System.out.println("Lutfen 2'den buyuk bir pozitif sayi girin.");
            deger = okuyucu.nextInt();
        }

        okuyucu.close();

        // Asalligi kontrol etmek icin bolen arayan bir yardimci metot cagiriyoruz
        boolean sonuc = asalMi(deger);

        if (sonuc) {
            System.out.println(deger + " asal sayidir.");
        } else {
            System.out.println(deger + " asal sayi degildir.");
        }
    }

    // Verilen sayinin asal olup olmadigini dondurur
    private static boolean asalMi(int sayi) {
        int bolen = 2;
        while (bolen <= sayi / 2) {
            if (sayi % bolen == 0) {
                return false;
            }
            bolen++;
        }
        return true;
    }
}

package WordCount;

import java.util.Hashtable;
import java.util.Scanner;
import java.util.StringTokenizer;

/**
 * Counts occurrences of each lowercase word in a line of input.
 */
public class WordCount {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String line = scanner.nextLine().trim();
        StringTokenizer tokenizer = new StringTokenizer(line, " ");
        Hashtable<String, Integer> counts = new Hashtable<>(100, 0.2f);
        while (tokenizer.hasMoreTokens()) {
            String word = tokenizer.nextToken().toLowerCase();
            int newCount = counts.containsKey(word) ? counts.get(word) + 1 : 1;
            counts.put(word, newCount);
        }
        counts.forEach((key, value) -> System.out.println(key + " " + value));
    }
}

