/**
 * N-Order Infinite Impulse Response (IIR) Filter for audio signal processing.
 * 
 * <p>IIR filters are recursive filters that can achieve a given frequency response
 * with a lower order than FIR filters. They are commonly used in audio applications
 * due to their computational efficiency and ability to model analog filters.
 * 
 * <p><b>Important:</b> Input samples should be normalized to the range [-1, 1]
 * for optimal performance and to avoid numerical instability.
 * 
 * <p>Based on the difference equation from
 * <a href="https://en.wikipedia.org/wiki/Infinite_impulse_response">Wikipedia: Infinite Impulse Response</a>
 * 
 * <p><b>Example Usage:</b>
 * <pre>
 * // Create a 2nd order low-pass filter
 * IIRFilter lowPass = new IIRFilter(2);
 * double[] feedforward = {0.5, 1.0, 0.5};      // b coefficients
 * double[] feedback = {1.0, -1.5, 0.7};        // a coefficients
 * lowPass.setCoeffs(feedback, feedforward);
 * 
 * // Process audio samples
 * double[] audioSignal = {0.5, 0.8, 0.3, 0.7};
 * double[] filteredSignal = new double[audioSignal.length];
 * for (int i = 0; i < audioSignal.length; i++) {
 *     filteredSignal[i] = lowPass.process(audioSignal[i]);
 * }
 * </pre>
 * 
 * @author The Algorithms Project
 * @version 1.0
 */
public class IIRFilter {

    // Filter order (number of past samples affecting current output)
    private final int filterOrder;

    // Denominator coefficients (feedback) - a[0] to a[order]
    private final double[] denominatorCoefficients;

    // Numerator coefficients (feedforward) - b[0] to b[order]
    private final double[] numeratorCoefficients;

    // History buffer for previous input samples (x[n-1], x[n-2], ..., x[n-order])
    private final double[] inputHistory;

    // History buffer for previous output samples (y[n-1], y[n-2], ..., y[n-order])
    private final double[] outputHistory;

    /**
     * Constructs an IIR Filter of the specified order.
     * 
     * <p>The filter is initialized with identity coefficients:
     * <br>a[0] = 1.0 (all other a[i] = 0.0)
     * <br>b[0] = 1.0 (all other b[i] = 0.0)
     * <br>This configuration acts as a passthrough (no filtering).
     *
     * @param order the filter's order (must be ≥ 1)
     * @throws IllegalArgumentException if order is less than 1
     */
    public IIRFilter(int order) throws IllegalArgumentException {
        if (order < 1) {
            throw new IllegalArgumentException(
                "Invalid filter order: " + order + ". Order must be greater than or equal to 1."
            );
        }

        this.filterOrder = order;

        // Allocate arrays of size order+1 (index 0 to order)
        denominatorCoefficients = new double[order + 1];
        numeratorCoefficients = new double[order + 1];

        // Initialize with identity (passthrough) configuration
        denominatorCoefficients[0] = 1.0;  // Normalization factor
        numeratorCoefficients[0] = 1.0;    // Direct path

        // Allocate history buffers (stores last 'order' samples)
        inputHistory = new double[order];
        outputHistory = new double[order];
    }

    /**
     * Sets the filter coefficients for the IIR filter.
     * 
     * <p>The general difference equation is:
     * <br>a[0]·y[n] = Σ(b[k]·x[n-k]) - Σ(a[k]·y[n-k]) for k = 1 to order
     * <br>where:
     * <br>- x[n] is the current input
     * <br>- y[n] is the current output
     * <br>- b[k] are feedforward (numerator) coefficients
     * <br>- a[k] are feedback (denominator) coefficients
     *
     * @param feedbackCoefficients Denominator coefficients (a[1] to a[order]).
     *                            Must have length = order.
     * @param feedforwardCoefficients Numerator coefficients (b[1] to b[order]).
     *                                Must have length = order.
     * @throws IllegalArgumentException if coefficient arrays have incorrect size
     *                                  or if a[0] would be set to zero
     */
    public void setCoefficients(double[] feedbackCoefficients, double[] feedforwardCoefficients) 
            throws IllegalArgumentException {

        // Validate feedback coefficient array size
        if (feedbackCoefficients.length != filterOrder) {
            throw new IllegalArgumentException(
                "Feedback coefficients length mismatch: expected " + filterOrder + 
                ", got " + feedbackCoefficients.length
            );
        }

        // Validate that a[0] is non-zero (prevents division by zero)
        if (feedbackCoefficients[0] == 0.0) {
            throw new IllegalArgumentException(
                "a[0] (first feedback coefficient) must be non-zero to avoid division by zero"
            );
        }

        // Validate feedforward coefficient array size
        if (feedforwardCoefficients.length != filterOrder) {
            throw new IllegalArgumentException(
                "Feedforward coefficients length mismatch: expected " + filterOrder + 
                ", got " + feedforwardCoefficients.length
            );
        }

        // Copy coefficients to internal arrays
        for (int coefficientIndex = 0; coefficientIndex < filterOrder; coefficientIndex++) {
            denominatorCoefficients[coefficientIndex] = feedbackCoefficients[coefficientIndex];
            numeratorCoefficients[coefficientIndex] = feedforwardCoefficients[coefficientIndex];
        }
    }

    /**
     * Processes a single audio sample through the IIR filter.
     * 
     * <p>This method implements the difference equation:
     * <br>y[n] = (b[0]·x[n] + Σ(b[k]·x[n-k]) - Σ(a[k]·y[n-k])) / a[0]
     * 
     * <p>The filter maintains internal state (history buffers) between calls,
     * allowing for continuous processing of streaming audio.
     *
     * @param currentSample The current input sample to process (normalized to [-1, 1])
     * @return The filtered output sample
     */
    public double processSample(double currentSample) {
        double outputValue = 0.0;

        // Compute the output using the difference equation
        // Σ(b[k]·x[n-k] - a[k]·y[n-k]) for k = 1 to order
        for (int delayIndex = 1; delayIndex <= filterOrder; delayIndex++) {
            outputValue += (numeratorCoefficients[delayIndex] * inputHistory[delayIndex - 1] 
                         - denominatorCoefficients[delayIndex] * outputHistory[delayIndex - 1]);
        }

        // Add the feedforward contribution from the current sample and normalize by a[0]
        outputValue = (outputValue + numeratorCoefficients[0] * currentSample) / denominatorCoefficients[0];

        // Update history buffers (shift right by one position)
        // Most recent samples move to history[0], older samples shift to higher indices
        for (int delayIndex = filterOrder - 1; delayIndex > 0; delayIndex--) {
            inputHistory[delayIndex] = inputHistory[delayIndex - 1];
            outputHistory[delayIndex] = outputHistory[delayIndex - 1];
        }

        // Store current samples in history buffers (will become x[n-1] and y[n-1] for next iteration)
        inputHistory[0] = currentSample;
        outputHistory[0] = outputValue;

        return outputValue;
    }

    /**
     * Resets the filter's internal state (history buffers) to zero.
     * 
     * <p>This method should be called when starting to process a new,
     * independent audio signal to avoid transient artifacts from previous
     * processing.
     */
    public void resetState() {
        for (int historyIndex = 0; historyIndex < filterOrder; historyIndex++) {
            inputHistory[historyIndex] = 0.0;
            outputHistory[historyIndex] = 0.0;
        }
    }

    /**
     * Returns the order of the IIR filter.
     *
     * @return The filter order (number of past samples affecting current output)
     */
    public int getFilterOrder() {
        return filterOrder;
    }

    /**
     * Checks whether the filter is stable based on its denominator coefficients.
     * 
     * <p>A necessary condition for stability is that all poles (roots of the
     * denominator polynomial) lie inside the unit circle in the z-plane.
     * 
     * <p><b>Note:</b> This is a simplified stability check. For complete
     * stability analysis, compute the roots of the denominator polynomial.
     *
     * @return true if the filter appears stable (all denominator coefficients positive),
     *         false otherwise (may still be stable - use with caution)
     */
    public boolean isStable() {
        // Simplified stability heuristic - for production use, implement actual pole analysis
        for (int coefficientIndex = 1; coefficientIndex <= filterOrder; coefficientIndex++) {
            if (Math.abs(denominatorCoefficients[coefficientIndex]) >= 1.0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.HashSet;
import java.util.Set;

public class DuplicateFinder {
    /**
     * Prints all duplicate elements of the array using a HashSet.
     */
    public static void main(String[] args) {
        int[] values = {4, 2, 7, 4, 9, 2, 5, 7, 1};

        Set<Integer> seen = new HashSet<>();
        Set<Integer> duplicates = new HashSet<>();

        for (int value : values) {
            if (!seen.add(value)) {
                duplicates.add(value);
            }
        }

        System.out.println("Duplicates: " + duplicates);
    }
}

package com.thealgorithms.lineclipping;

import com.thealgorithms.lineclipping.utils.Line;
import com.thealgorithms.lineclipping.utils.Point;

/**
 * @author shikarisohan
 * @since 10/4/24
 * Cohen-Sutherland Line Clipping Algorithm
 *
 * This algorithm is used to clip a line segment to a rectangular window.
 * It assigns a region code to each endpoint of the line segment, and
 * then efficiently determines whether the line segment is fully inside,
 * fully outside, or partially inside the window.
 *
 * Reference:
 * https://en.wikipedia.org/wiki/Cohen%E2%80%93Sutherland_algorithm
 *
 * Clipping window boundaries are defined as (xMin, yMin) and (xMax, yMax).
 * The algorithm computes the clipped line segment if it's partially or
 * fully inside the clipping window.
 */
public class CohenSutherland {

    // Region codes for the 9 regions
    private static final int INSIDE = 0; // 0000
    private static final int LEFT = 1; // 0001
    private static final int RIGHT = 2; // 0010
    private static final int BOTTOM = 4; // 0100
    private static final int TOP = 8; // 1000

    // Define the clipping window
    double xMin;
    double yMin;
    double xMax;
    double yMax;

    public CohenSutherland(double xMin, double yMin, double xMax, double yMax) {
        this.xMin = xMin;
        this.yMin = yMin;
        this.xMax = xMax;
        this.yMax = yMax;
    }

    // Compute the region code for a point (x, y)
    private int computeCode(double x, double y) {
        int code = INSIDE;

        if (x < xMin) // to the left of rectangle
        {
            code |= LEFT;
        } else if (x > xMax) // to the right of rectangle
        {
            code |= RIGHT;
        }
        if (y < yMin) // below the rectangle
        {
            code |= BOTTOM;
        } else if (y > yMax) // above the rectangle
        {
            code |= TOP;
        }

        return code;
    }

    // Cohen-Sutherland algorithm to return the clipped line
    public Line cohenSutherlandClip(Line line) {
        double x1 = line.start.x;
        double y1 = line.start.y;
        double x2 = line.end.x;
        double y2 = line.end.y;

        int code1 = computeCode(x1, y1);
        int code2 = computeCode(x2, y2);
        boolean accept = false;

        while (true) {
            if ((code1 == 0) && (code2 == 0)) {
                // Both points are inside the rectangle
                accept = true;
                break;
            } else if ((code1 & code2) != 0) {
                // Both points are outside the rectangle in the same region
                break;
            } else {
                // Some segment of the line is inside the rectangle
                double x = 0;
                double y = 0;

                // Pick an endpoint that is outside the rectangle
                int codeOut = (code1 != 0) ? code1 : code2;

                // Find the intersection point using the line equation
                if ((codeOut & TOP) != 0) {
                    // Point is above the rectangle
                    x = x1 + (x2 - x1) * (yMax - y1) / (y2 - y1);
                    y = yMax;
                } else if ((codeOut & BOTTOM) != 0) {
                    // Point is below the rectangle
                    x = x1 + (x2 - x1) * (yMin - y1) / (y2 - y1);
                    y = yMin;
                } else if ((codeOut & RIGHT) != 0) {
                    // Point is to the right of the rectangle
                    y = y1 + (y2 - y1) * (xMax - x1) / (x2 - x1);
                    x = xMax;
                } else if ((codeOut & LEFT) != 0) {
                    // Point is to the left of the rectangle
                    y = y1 + (y2 - y1) * (xMin - x1) / (x2 - x1);
                    x = xMin;
                }

                // Replace the point outside the rectangle with the intersection point
                if (codeOut == code1) {
                    x1 = x;
                    y1 = y;
                    code1 = computeCode(x1, y1);
                } else {
                    x2 = x;
                    y2 = y;
                    code2 = computeCode(x2, y2);
                }
            }
        }

        if (accept) {
            return new Line(new Point(x1, y1), new Point(x2, y2));
        } else {

            return null; // The line is fully rejected
        }
    }
}

package com.thealgorithms.datastructures.hashmap.hashing;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * This class provides a method to find the majority element(s) in an array of integers.
 * A majority element is defined as an element that appears at least ⌊n/2⌋ times,
 * where n is the length of the array. If multiple elements qualify as majority elements,
 * they are all returned in a list.
 */
public final class MajorityElement {
    private MajorityElement() {
    }

    /**
     * Returns a list of majority element(s) from the given array of integers.
     *
     * @param nums an array of integers
     * @return a list containing the majority element(s); returns an empty list if none exist or input is null/empty
     */
    public static List<Integer> majority(int[] nums) {
        if (nums == null || nums.length == 0) {
            return Collections.emptyList();
        }

        Map<Integer, Integer> numToCount = new HashMap<>();
        for (final var num : nums) {
            numToCount.merge(num, 1, Integer::sum);
        }

        List<Integer> majorityElements = new ArrayList<>();
        for (final var entry : numToCount.entrySet()) {
            if (entry.getValue() >= nums.length / 2) {
                majorityElements.add(entry.getKey());
            }
        }
        return majorityElements;
    }
}

package Person;

/**
 * A worker paid hourly at a fixed rate.
