package com.thealgorithms.maths;

/**
 * Class for correlation of two discrete variables
 */

public final class Correlation {
    private Correlation() {
    }

    public static final double DELTA = 1e-9;

    /**
     * Discrete correlation function.
     * Correlation between two discrete variables is calculated
     * according to the formula: Cor(x, y)=Cov(x, y)/sqrt(Var(x)*Var(y)).
     * Correlation with a constant variable is taken to be zero.
     *
     * @param x The first discrete variable
     * @param y The second discrete variable
     * @param n The number of values for each variable
     * @return The result of the correlation of variables x,y.
     */
    public static double correlation(double[] x, double[] y, int n) {
        double exy = 0; // E(XY)
        double ex = 0; // E(X)
        double exx = 0; // E(X^2)
        double ey = 0; // E(Y)
        double eyy = 0; // E(Y^2)
        for (int i = 0; i < n; i++) {
            exy += x[i] * y[i];
            ex += x[i];
            exx += x[i] * x[i];
            ey += y[i];
            eyy += y[i] * y[i];
        }
        exy /= n;
        ex /= n;
        exx /= n;
        ey /= n;
        eyy /= n;
        double cov = exy - ex * ey; // Cov(X, Y) = E(XY)-E(X)E(Y)
        double varx = Math.sqrt(exx - ex * ex); // Var(X) = sqrt(E(X^2)-E(X)^2)
        double vary = Math.sqrt(eyy - ey * ey); // Var(Y) = sqrt(E(Y^2)-E(Y)^2)
        if (varx * vary < DELTA) { // Var(X) = 0 means X = const, the same about Y
            return 0;
        } else {
            return cov / Math.sqrt(varx * vary);
        }
    }
}

public class OgrenciNumarasi {

    // 'kayitYili' metodu, ogrenci numarasinin ilk iki hanesine bakarak kayit yilini hesaplar
    int kayitYili(int sayi) {
        // Ogrenci numarasinin ilk iki hanesini (numaranin basindaki iki rakami) alir ve 2000 ekler
        return (sayi / 10000000) + 2000;
    }

    // 'kayitSirasi' metodu, ogrenci numarasinin son uc hanesine bakarak kayit sirasi'ni dondurur
    int kayitSirasi(int sayi) {
        // Numaranin son uc rakamini almak icin 1000'e gore mod islemi yapilir
        return sayi % 1000;
    }

    // 'bolumu' metodu, ogrenci numarasindaki belirli bir haneye bakarak ogrencinin bolumunu bulur
    String bolumu(int sayi) {
        // Numaranin bolum bilgisini tutan kisimi al (numaranin sondan dorduncu hanesi)
        int bolum = (sayi / 1000) % 10;

        // Bolum numarasina gore hangi bolumde okudugunu kontrol et
        if(bolum == 7) {
            return "Elektrik Elektronik";
        } else if(bolum == 6) {
            return "Bilgisayar";
        } else if(bolum == 5) {
            return "Makina";
        } else {
            return "Bilinmiyor";  // Belirtilen numaraya uymayan bir deger icin bilinmiyor sonucu doner
        }
    }

    public static void main(String[] args) {

        // Kullanicidan giris almak icin Scanner nesnesi olustur
        Scanner okuyucu = new Scanner(System.in);

        // Kullanicidan okul numarasini girmesini iste
        System.out.println("Lutfen okul numaranizi giriniz");
        int numara = okuyucu.nextInt();  // Kullanicinin girdigi okul numarasi alinir

        numara = 230707123;

        // OgrenciNumarasi sinifindan bir nesne olustur
        OgrenciNumarasi bulucu = new OgrenciNumarasi();

        // Ogrencinin kayit yili ekrana yazdirilir
        System.out.println("Kayit yili: " + bulucu.kayitYili(numara));

        // Ogrencinin kayit sirasi ekrana yazdirilir
        System.out.println("Kayit sirasi: " + bulucu.kayitSirasi(numara));

        // Ogrencinin bolumu ekrana yazdirilir
        System.out.println("Bolum: " + bulucu.bolumu(numara));

        // Scanner nesnesini kapatiyoruz
        okuyucu.close();
    }
}

package com.thealgorithms.backtracking;

/**
 * Power Sum Problem: Find the number of ways that a given integer, N, can be expressed
 * as the sum of the Xth powers of unique, natural numbers.
 * 
 * <p><b>Problem Statement:</b><br>
 * Given two integers N (target sum) and X (power), find the number of ways to represent N
 * as the sum of Xth powers of unique natural numbers (positive integers).</p>
 * 
 * <p><b>Key Rules:</b></p>
 * <ul>
 *   <li>Only natural numbers (1, 2, 3, ...) are allowed</li>
 *   <li>Each number can be used at most once (unique numbers)</li>
 *   <li>The numbers are raised to the power X before summation</li>
 *   <li>Order does not matter (combinations, not permutations)</li>
 * </ul>
 * 
 * <p><b>Example:</b><br>
 * N = 100, X = 3 (cubes): 1³ + 2³ + 3³ + 4³ = 1 + 8 + 27 + 64 = 100<br>
 * Only one valid combination exists → output = 1</p>
 * 
 * <p><b>Example:</b><br>
 * N = 10, X = 2 (squares):<br>
 * Possible combinations: 1² + 3² = 1 + 9 = 10<br>
 * Also: 1² + 2² + 3²? = 1 + 4 + 9 = 14 (too high)<br>
 * So there is 1 valid combination → output = 1</p>
 * 
 * <p><b>Time Complexity:</b> O(2^N^(1/X)) - Exponential due to exploring all subsets</p>
 * <p><b>Space Complexity:</b> O(N^(1/X)) for recursion stack</p>
 * 
 * @see <a href="https://en.wikipedia.org/wiki/Backtracking">Backtracking Algorithm</a>
 */
public final class PowerSum {

    /**
     * Calculates the number of ways to express the target sum as a sum of Xth powers
     * of unique natural numbers.
     * 
     * <p>This method provides the main entry point for solving the Power Sum problem.
     * It initializes the recursion by starting with natural number 1 and current sum 0.</p>
     *
     * @param targetSum The target sum to achieve (N in the problem statement)
     * @param exponent The power to raise natural numbers to (X in the problem statement)
     * @return The number of distinct ways to express targetSum as sum of Xth powers
     * 
     * @example
     * PowerSum solver = new PowerSum();
     * int ways = solver.countPowerSumRepresentations(100, 3);  // returns 1
     * int ways = solver.countPowerSumRepresentations(10, 2);   // returns 1
     * int ways = solver.countPowerSumRepresentations(5, 2);    // returns 0
     */
    public int countPowerSumRepresentations(int targetSum, int exponent) {
        // Validate input parameters
        if (targetSum < 0) {
            throw new IllegalArgumentException("Target sum cannot be negative: " + targetSum);
        }
        if (exponent < 0) {
            throw new IllegalArgumentException("Exponent cannot be negative: " + exponent);
        }

        // Special case: when target sum is 0
        if (targetSum == 0) {
            // By convention: one way to represent 0 - use no numbers
            return 1;
        }

        // Special case: when exponent is 0
        // X^0 = 1 for any X>0, so we need to find numbers that sum to targetSum
        // But numbers must be unique, so this becomes counting subsets of {1,1,1,...}
        // For practical purposes, when exponent=0, each number contributes 1
        // So the problem reduces to: can targetSum be represented as sum of unique values? 
        // Actually, it's a different combinatorial problem - we'll handle it generally
        if (exponent == 0) {
            // When exponent is 0, 1^0 = 1, 2^0 = 1, 3^0 = 1, etc.
            // So we're looking for combinations of unique numbers that count to targetSum
            // Each number contributes exactly 1 to the sum
            // Therefore, we need to find how many ways to pick k distinct numbers where k = targetSum
            // Since numbers are unique and each contributes 1, we need exactly targetSum numbers
            // There is exactly 1 way if targetSum >= 1? Actually, numbers start at 1, so we need
            // to pick the first targetSum numbers: {1, 2, 3, ..., targetSum}
            // But any targetSum distinct numbers would work? The sum of powers (1's) would equal targetSum
            // So we need exactly targetSum numbers, but they must be the smallest targetSum numbers
            // because larger numbers would have the same power (1) but are less efficient
            // For exponent=0, there is exactly 1 combination: {1, 2, 3, ..., targetSum}
            // This only works if targetSum can be represented this way
            return (targetSum >= 1) ? 1 : 0;
        }

        // Start the recursive backtracking process
        return findPowerSumWays(targetSum, exponent, 1, 0);
    }

    /**
     * Calculates the number of ways to express the target sum as a sum of Xth powers.
     * This is an alias method for better readability.
     *
     * @param targetSum The target sum to achieve (N)
     * @param exponent The power to raise natural numbers to (X)
     * @return The number of ways to express targetSum
     */
    public int sumOfPowerWays(int targetSum, int exponent) {
        return countPowerSumRepresentations(targetSum, exponent);
    }

    /**
     * Returns the maximum possible natural number whose Xth power ≤ targetSum.
     * This helps in limiting the search space.
     *
     * @param targetSum The target sum (N)
     * @param exponent The power (X)
     * @return The maximum natural number whose exponent-th power ≤ targetSum
     */
    private int getMaxNaturalNumber(int targetSum, int exponent) {
        int maxNumber = 1;
        while (Math.pow(maxNumber + 1, exponent) <= targetSum) {
            maxNumber++;
        }
        return maxNumber;
    }

    /**
     * Gets all possible power values up to the maximum natural number.
     * This is an optimization to avoid repeated Math.pow calculations.
     *
     * @param maxNumber The maximum natural number to consider
     * @param exponent The exponent (X)
     * @return Array where index i contains i^exponent (0-indexed)
     */
    private int[] precomputePowerValues(int maxNumber, int exponent) {
        int[] powerValues = new int[maxNumber + 1];
        for (int number = 1; number <= maxNumber; number++) {
            powerValues[number] = (int) Math.pow(number, exponent);
        }
        return powerValues;
    }

    /**
     * Recursively calculates the number of ways to express the remaining sum as a sum
     * of Xth powers of unique natural numbers using backtracking.
     * 
     * <p>At each step, the algorithm decides whether to include the current natural number
     * raised to the given exponent or skip it, similar to the 0/1 knapsack approach.</p>
     *
     * @param targetSum The original target sum (N)
     * @param exponent The power to raise numbers to (X)
     * @param currentNumber The current natural number being considered (starts at 1)
     * @param accumulatedSum The sum of selected numbers raised to the exponent so far
     * @return The number of valid combinations from this state
     */
    private int findPowerSumWays(int targetSum, int exponent, int currentNumber, int accumulatedSum) {
        // Compute the value of currentNumber raised to the given exponent
        int powerValue = (int) Math.pow(currentNumber, exponent);

        // Calculate the sum if we include the current number
        int sumIfIncluded = accumulatedSum + powerValue;

        // Base case: Exact match found
        if (sumIfIncluded == targetSum) {
            return 1; // Valid combination
        }

        // Pruning: If including current number exceeds target, no need to continue
        if (sumIfIncluded > targetSum) {
            return 0; // Invalid branch
        }

        // Recursive case: Two choices - include current number or skip it
        // Note: We always move to next number (currentNumber + 1) to maintain uniqueness
        int waysWithCurrent = findPowerSumWays(targetSum, exponent, currentNumber + 1, sumIfIncluded);
        int waysWithoutCurrent = findPowerSumWays(targetSum, exponent, currentNumber + 1, accumulatedSum);

        // Return the total number of ways from this branch
        return waysWithCurrent + waysWithoutCurrent;
    }

    /**
     * Optimized version using memoization (Dynamic Programming) to avoid recomputation.
     * This significantly improves performance for overlapping subproblems.
     *
     * @param targetSum The target sum to achieve (N)
     * @param exponent The power to raise numbers to (X)
     * @return The number of ways to express targetSum
     */
    public int countPowerSumWaysMemoized(int targetSum, int exponent) {
        if (targetSum < 0) return 0;
        if (targetSum == 0) return 1;

        int maxNumber = getMaxNaturalNumber(targetSum, exponent);
        int[] powerValues = precomputePowerValues(maxNumber, exponent);

        // DP table: dp[i][j] = ways to achieve sum j using numbers from i to maxNumber
        Integer[][] memo = new Integer[maxNumber + 2][targetSum + 1];
        return findPowerSumWaysMemoized(targetSum, powerValues, 1, 0, memo);
    }

    /**
     * Recursive helper with memoization for Power Sum problem.
     *
     * @param targetSum The original target sum
     * @param powerValues Precomputed power values array (index -> number^exponent)
     * @param currentIndex Current natural number index
     * @param accumulatedSum Current accumulated sum
     * @param memo Memoization cache
     * @return Number of ways from this state
     */
    private int findPowerSumWaysMemoized(int targetSum, int[] powerValues, int currentIndex, 
                                          int accumulatedSum, Integer[][] memo) {
        // Base case: Exact match
        if (accumulatedSum == targetSum) {
            return 1;
        }

        // Pruning: Exceeded target or no more numbers to try
        if (accumulatedSum > targetSum || currentIndex >= powerValues.length) {
            return 0;
        }

        // Check memoization cache
        if (memo[currentIndex][accumulatedSum] != null) {
            return memo[currentIndex][accumulatedSum];
        }

        int powerValue = powerValues[currentIndex];

        // Option 1: Include current number (only if adding doesn't exceed target)
        int waysWith = 0;
        if (accumulatedSum + powerValue <= targetSum) {
            waysWith = findPowerSumWaysMemoized(targetSum, powerValues, currentIndex + 1, 
                                                accumulatedSum + powerValue, memo);
        }

        // Option 2: Skip current number
        int waysWithout = findPowerSumWaysMemoized(targetSum, powerValues, currentIndex + 1, 
                                                   accumulatedSum, memo);

        // Store result in cache
        memo[currentIndex][accumulatedSum] = waysWith + waysWithout;
        return memo[currentIndex][accumulatedSum];
    }

    /**
     * Utility method to print all valid combinations (for debugging/visualization).
     * This method builds and prints each combination as it's found.
     *
     * @param targetSum The target sum (N)
     * @param exponent The exponent (X)
     */
    public void printAllPowerSumCombinations(int targetSum, int exponent) {
        System.out.printf("All combinations for N=%d, X=%d:%n", targetSum, exponent);
        printCombinationsRecursive(targetSum, exponent, 1, 0, new java.util.ArrayList<>());
    }

    /**
     * Recursive helper to print all valid combinations.
     *
     * @param targetSum Target sum
     * @param exponent Exponent (X)
     * @param currentNumber Current natural number
     * @param accumulatedSum Accumulated sum so far
     * @param currentCombination List to store current combination
     */
    private void printCombinationsRecursive(int targetSum, int exponent, int currentNumber, 
                                             int accumulatedSum, java.util.List<Integer> currentCombination) {
        int powerValue = (int) Math.pow(currentNumber, exponent);
        int newSum = accumulatedSum + powerValue;

        if (newSum == targetSum) {
            // Found a valid combination
            currentCombination.add(currentNumber);
            System.out.println(currentCombination);
            currentCombination.remove(currentCombination.size() - 1);
            return;
        }

        if (newSum > targetSum) {
            return;
        }

        // Include current number
        currentCombination.add(currentNumber);
        printCombinationsRecursive(targetSum, exponent, currentNumber + 1, newSum, currentCombination);
        currentCombination.remove(currentCombination.size() - 1);

        // Skip current number
        printCombinationsRecursive(targetSum, exponent, currentNumber + 1, accumulatedSum, currentCombination);
    }
}

/*
COMPREHENSIVE DOCUMENTATION
===========================

POWER SUM PROBLEM - MATHEMATICAL FOUNDATION
===========================================

Problem Definition:
-------------------
Given N and X, count the number of ways to write N as:
N = a₁^X + a₂^X + ... + a_k^X
where a₁, a₂, ..., a_k are distinct natural numbers (positive integers)

Mathematical Notation:
---------------------
N = Σᵢ a_i^X, where a_i ∈ ℕ⁺, a_i are distinct

Example 1 (N=100, X=3):
100 = 1³ + 2³ + 3³ + 4³
1 + 8 + 27 + 64 = 100 → 1 way

Example 2 (N=50, X=2):
50 = 1² + 7² = 1 + 49 = 50
50 = 5² + 5²? Not allowed (numbers must be distinct)
50 = 1² + 2² + 3² + 4² + 5²? 1+4+9+16+25=55 (too high)
Hence 1 way

PROBLEM SPACE ANALYSIS
=====================

Upper Bound on Numbers:
----------------------
Since we're working with positive integers raised to X, and they sum to N,
the maximum number we need to consider is the largest integer m such that:
m^X ≤ N

For N=100, X=2: m ≤ 10 (since 10²=100, 11²=121>100)
For N=100, X=3: m ≤ 4 (since 4³=64, 5³=125>100)

This gives us a natural bound on the search space: O(N^(1/X))

RECURSION TREE VISUALIZATION
===========================

For N=10, X=2:

                                    root (sum=0, num=1)
                                    /                  \
                            include 1²                skip 1²
                            (sum=1, num=2)           (sum=0, num=2)
                           /           \             /           \
                    include 2²        skip 2²   include 2²     skip 2²
                   (sum=5, num=3)    (sum=1, num=3) invalid
                   /        \        /        \   (sum=4, num=3)
            include 3²    skip 3²  etc.      etc.
            (sum=14, invalid)

            ... (continues)

Leaf nodes: sum=10 found! Return 1
           sum>10 → return 0
           sum<10 but num exhausted → return 0

Total valid combinations = 1

OPTIMIZATIONS
============

1. Early Pruning:
   - If current sum > target, terminate branch
   - pre compute power values to avoid repeated Math.pow calls

2. Memoization (DP):
   - State: (currentIndex, accumulatedSum)
   - Many overlapping subproblems, especially as branches converge

3. Iterative DP:
   - Can be solved as a variation of subset sum problem
   - dp[sum] += dp[sum - power(number)] using 1D array

ITERATIVE DP SOLUTION EXAMPLE
===========================

public int countPowerSumWaysIterative(int targetSum, int exponent) {
    int[] dp = new int[targetSum + 1];
    dp[0] = 1;

    int maxNum = getMaxNaturalNumber(targetSum, exponent);

    for (int num = 1; num <= maxNum; num++) {
        int power = (int) Math.pow(num, exponent);
        for (int sum = targetSum; sum >= power; sum--) {
            dp[sum] += dp[sum - power];
        }
    }

    return dp[targetSum];
}

COMPLEXITY COMPARISON
====================

| Approach | Time Complexity | Space Complexity | Best For |
|----------|----------------|------------------|----------|
| Recursive Backtracking | O(2^(N^(1/X))) | O(N^(1/X)) | Small N, demonstration |
| Memoization | O(N^{(1/X)} × N) | O(N^{(1/X)} × N) | Medium N |
| Iterative DP | O(N × N^{(1/X)}) | O(N) | Larger N, optimal |

EXAMPLES WITH OUTPUTS
====================

| N | X | Maximum Number | Power Values | Valid Combinations | Count |
|---|----|----------------|---------------|--------------------|-------|
| 1 | 1 | 1 | 1 | {1} | 1 |
| 4 | 2 | 2 | 1,4 | {2} | 1 |
| 10| 2 | 3 | 1,4,9 | {1,3} | 1 |
| 50| 2 | 7 | 1,4,9,16,25,36,49 | {1,7}, {5,5? no}, {1,2,3,4,5?55} | 1 |
| 100| 3 | 4 | 1,8,27,64 | {1,2,3,4} | 1 |
| 30| 2 | 5 | 1,4,9,16,25 | {1,2,3,4} (1+4+9+16=30), {5} (25+?), {1,5?26}, {2,5?29} | 1 |
| 1000| 2 | 31 | squares up to 961 | Several combinations | More than 1 |

VALIDATION CHECKS
================

1. Distinctness: By always moving to next number (currentNumber+1), we ensure uniqueness
2. Order independence: Only consider increasing sequences, so each combination counted once
3. Pruning: When sum exceeds target or no more numbers possible, backtrack

SPECIAL CASES
============

| Case | Input | Expected Output | Explanation |
|------|-------|-----------------|-------------|
| Negative N | N=-5, X=2 | Throw exception | Target sum can't be negative |
| Negative X | N=100, X=-2 | Throw exception | Negative exponents produce fractions |
| N=0 | N=0, X=anything | 1 | Empty sum |
| Large X | N=100, X=100 | 0 | 1^100=1, 2^100>100, can't reach 100 |
| X=0 | N=5, X=0 | 1 | Numbers 1,2,3,... each contribute 1, need sum=5 → exactly 5 numbers only |
| N=1, X=1000 | 1 | 1 | 1^1000=1 works |

PRACTICAL APPLICATIONS
======================

1. Number Theory:
   - Represent numbers as sums of powers
   - Partition theorems

2. Computer Science:
   - Combinatorial optimization
   - Constraint satisfaction problems

3. Financial Mathematics:
   - Representing amounts using different denominations
   - Coin change problem variant

4. Physics:
   - Energy level combinations
   - Quantum state representations

5. Cryptography:
   - Key space exploration
   - Subset sum problems in cryptanalysis

RELATED PROBLEMS
===============

1. Subset Sum Problem
2. Coin Change (with limited coins)
3. Integer Partition (with power constraint)
4. Exact Sum Problem
5. Binary Representation (X=0,1,2,...)

EDGE CASES HANDLED
=================

1. Large exponents - maxNumber becomes 1 quickly
2. Large N but small X - exponential growth in possibilities
3. Exact powers (N = m^X) - at least one combination
4. Sum of consecutive powers

SAMPLE USAGE
===========

public static void main(String[] args) {
    PowerSum solver = new PowerSum();

    // Basic usage
    int ways1 = solver.countPowerSumRepresentations(100, 3);
    System.out.println("Ways to represent 100 as sum of cubes: " + ways1);

    // Using memoized version for better performance
    int ways2 = solver.countPowerSumWaysMemoized(1000, 2);
    System.out.println("Ways to represent 1000 as sum of squares: " + ways2);

    // Print all combinations for N=100, X=2
    solver.printAllPowerSumCombinations(100, 2);

    // Compute max natural number to consider
    int maxNum = (int) Math.pow(100, 1.0/3); // about 4
    System.out.println("Maximum number to consider for 100^3: " + maxNum);
}

MEMORY CONSIDERATIONS
====================

For N=10,000, X=2:
- maxNumber = 100 (since 100²=10,000)
- DP array size: 10,001 integers
- Memoization table: 101 × 10,001 = ~1M entries
- Each entry: Integer object (~16 bytes) → ~16 MB

For N=100,000, X=2:
- maxNumber = 316
- Memoization table: 317 × 100,001 ≈ 31.7M entries
- Memory: ~500 MB feasible with -Xmx

KNOWLEDGE BASE SUMMARY
======================

Time:    O(2^(N^{1/X})) naive, O(N × N^{1/X}) with DP
Space:   O(N) iterative DP, O(N × N^{1/X}) memoization
Type:    Backtracking with pruning, Dynamic Programming alternative
Optimal: Yes, with memoization exhaustively explores state space
Use when: N ≤ 10,000 and X ≥ 2 for practical performance
*/

/**
 * A utility class for performing single-bit operations on integers.
 * These operations include flipping, setting, clearing, and getting
 * individual bits at specified positions.
 *
 * Bit positions are zero-indexed (i.e., the least significant bit is at position 0).
 * These methods leverage bitwise operations for optimal performance.
 *
 * Examples:
 * - `flipBit(3, 1)` flips the bit at index 1 in binary `11` (result: `1`).
 * - `setBit(4, 0)` sets the bit at index 0 in `100` (result: `101` or 5).
 * - `clearBit(7, 1)` clears the bit at index 1 in `111` (result: `101` or 5).
 * - `getBit(6, 0)` checks if the least significant bit is set (result: `0`).
 *
 * Time Complexity: O(1) for all operations.
 *
 * Author: lukasb1b (https://github.com/lukasb1b)
 */
public final class SingleBitOperations {
    private SingleBitOperations() {
    }

    /**
     * Flips (toggles) the bit at the specified position.
     *
     * @param num the input number
     * @param bit the position of the bit to flip (0-indexed)
     * @return the new number after flipping the specified bit
     */
    public static int flipBit(final int num, final int bit) {
        return num ^ (1 << bit);
    }

    /**
     * Sets the bit at the specified position to 1.
     *
     * @param num the input number
     * @param bit the position of the bit to set (0-indexed)
     * @return the new number after setting the specified bit to 1
     */
    public static int setBit(final int num, final int bit) {
        return num | (1 << bit);
    }

    /**
     * Clears the bit at the specified position (sets it to 0).
     *
     * @param num the input number
     * @param bit the position of the bit to clear (0-indexed)
     * @return the new number after clearing the specified bit
     */
    public static int clearBit(final int num, final int bit) {
        return num & ~(1 << bit);
    }

    /**
     * Gets the bit value (0 or 1) at the specified position.
     *
     * @param num the input number
     * @param bit the position of the bit to retrieve (0-indexed)
     * @return 1 if the bit is set, 0 otherwise
     */
    public static int getBit(final int num, final int bit) {
        return (num >> bit) & 1;
    }
}

/**
 * Utility class for converting hexadecimal numbers to binary representation.
 * <p>
 * A hexadecimal number consists of digits from {@code [0-9]} and {@code [A-F]} (case-insensitive),
 * while binary representation uses only {@code [0, 1]}.
 * <p>
 * This class provides methods to:
 * <ul>
 *   <li>Convert a hexadecimal string to its binary string equivalent.</li>
 *   <li>Ensure the binary output is padded to 8 bits (1 byte).</li>
 * </ul>
 * <p>
 * Example:
 * <ul>
 *   <li>{@code "A1"} → {@code "10100001"}</li>
 *   <li>{@code "1"} → {@code "00000001"}</li>
 * </ul>
 *
 * <p>This class assumes that the input hexadecimal string is valid.</p>
 */
public class HexaDecimalToBinary {

    /**
     * Converts a hexadecimal string to its binary string equivalent.
     * The binary output is padded to a minimum of 8 bits (1 byte).
     * Steps:
     * <ol>
     *     <li>Convert the hexadecimal string to an integer.</li>
     *     <li>Convert the integer to a binary string.</li>
     *     <li>Pad the binary string to ensure it is at least 8 bits long.</li>
     *     <li>Return the padded binary string.</li>
     * </ol>
     *
     * @param numHex the hexadecimal string (e.g., "A1", "7F")
     * @throws NumberFormatException if the input string is not a valid hexadecimal number
     * @return the binary string representation, padded to 8 bits (e.g., "10100001")
     */
    public String convert(String numHex) {
        int conHex = Integer.parseInt(numHex, 16);
        String binary = Integer.toBinaryString(conHex);
        return completeDigits(binary);
    }

    /**
     * Pads the binary string to ensure it is at least 8 bits long.
     * If the binary string is shorter than 8 bits, it adds leading zeros.
     *
     * @param binNum the binary string to pad
     * @return the padded binary string with a minimum length of 8
     */
    public String completeDigits(String binNum) {
        final int byteSize = 8;
        StringBuilder binNumBuilder = new StringBuilder(binNum);
        while (binNumBuilder.length() < byteSize) {
            binNumBuilder.insert(0, "0");
        }
        binNum = binNumBuilder.toString();
        return binNum;
    }
}

/**
 * A utility class to convert between Cartesian and Polar coordinate systems.
 *
 * <p>This class provides methods to perform the following conversions:
 * <ul>
 *   <li>Cartesian to Polar coordinates</li>
 *   <li>Polar to Cartesian coordinates</li>
 * </ul>
 *
 * <p>The class is final and cannot be instantiated.
 */
public final class CoordinateConverter {

    private CoordinateConverter() {
        // Prevent instantiation
    }

    /**
     * Converts Cartesian coordinates to Polar coordinates.
     *
     * @param x the x-coordinate in the Cartesian system; must be a finite number
     * @param y the y-coordinate in the Cartesian system; must be a finite number
     * @return an array where the first element is the radius (r) and the second element is the angle (theta) in degrees
     * @throws IllegalArgumentException if x or y is not a finite number
     */
    public static double[] cartesianToPolar(double x, double y) {
        if (!Double.isFinite(x) || !Double.isFinite(y)) {
            throw new IllegalArgumentException("x and y must be finite numbers.");
        }
        double r = Math.sqrt(x * x + y * y);
        double theta = Math.toDegrees(Math.atan2(y, x));
        return new double[] {r, theta};
    }

    /**
     * Converts Polar coordinates to Cartesian coordinates.
     *
     * @param r the radius in the Polar system; must be non-negative
     * @param thetaDegrees the angle (theta) in degrees in the Polar system; must be a finite number
     * @return an array where the first element is the x-coordinate and the second element is the y-coordinate in the Cartesian system
     * @throws IllegalArgumentException if r is negative or thetaDegrees is not a finite number
     */
    public static double[] polarToCartesian(double r, double thetaDegrees) {
        if (r < 0) {
            throw new IllegalArgumentException("Radius (r) must be non-negative.");
        }
        if (!Double.isFinite(thetaDegrees)) {
            throw new IllegalArgumentException("Theta (angle) must be a finite number.");
        }
        double theta = Math.toRadians(thetaDegrees);
        double x = r * Math.cos(theta);
        double y = r * Math.sin(theta);
        return new double[] {x, y};
    }
}

public class KarekokBulma {

    // Bu metod, verilen bir sayinin karekokunu iterative olarak hesaplar
    public static double karekokBul(double sayi) {
        double dusuk = 0.0; // Aramanin alt siniri
        double yuksek = sayi; // Aramanin ust siniri
        double tolerans = 0.00001; // Kabul edilebilir hata payi
        while (yuksek - dusuk > tolerans) {
            double orta = (dusuk + yuksek) / 2; // Ortadaki deger
            double ortaKare = orta * orta; // Ortadaki degerin karesi
            if (ortaKare > sayi) {
                yuksek = orta; // Aralik yukari dogru daraltilir
            } else {
                dusuk = orta; // Aralik asagi dogru daraltilir
            }
        }
        return (dusuk + yuksek) / 2; // Sonuc olarak ortalama deger dondurulur
    }

    public static void main(String[] args) {
        // Ornek sayilarin karekoklerini hesaplama
        double sayi = 10.0;
        double karekok = karekokBul(sayi);
        System.out.println(sayi + " sayisinin karekoku: " + karekok);

        sayi = 16.0;
        karekok = karekokBul(sayi);
        System.out.println(sayi + " sayisinin karekoku: " + karekok);

        sayi = 100.0;
        karekok = karekokBul(sayi);
        System.out.println(sayi + " sayisinin karekoku: " + karekok);
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Stack;

/**
 * Finds the strongly connected components in a directed graph.
 *
 * @param adjList The adjacency list representation of the graph.
 * @param n The number of nodes in the graph.
 * @return The number of strongly connected components.
 */
public class StronglyConnectedComponentOptimized {

    public void btrack(HashMap<Integer, List<Integer>> adjList, int[] visited, Stack<Integer> dfsCallsNodes, int currentNode) {
        visited[currentNode] = 1;
        List<Integer> neighbors = adjList.get(currentNode);
        // Check for null before iterating
        if (neighbors != null) {
            for (int neighbor : neighbors) {
                if (visited[neighbor] == -1) {
                    btrack(adjList, visited, dfsCallsNodes, neighbor);
                }
            }
        }
        dfsCallsNodes.add(currentNode);
    }

    public void btrack2(HashMap<Integer, List<Integer>> adjRevList, int[] visited, int currentNode, List<Integer> newScc) {
        visited[currentNode] = 1;
        newScc.add(currentNode);
        List<Integer> neighbors = adjRevList.get(currentNode);
        // Check for null before iterating
        if (neighbors != null) {
            for (int neighbor : neighbors) {
                if (visited[neighbor] == -1) {
                    btrack2(adjRevList, visited, neighbor, newScc);
                }
            }
        }
    }

    public int getOutput(HashMap<Integer, List<Integer>> adjList, int n) {
        int[] visited = new int[n];
        Arrays.fill(visited, -1);
        Stack<Integer> dfsCallsNodes = new Stack<>();

        for (int i = 0; i < n; i++) {
            if (visited[i] == -1) {
                btrack(adjList, visited, dfsCallsNodes, i);
            }
        }

        HashMap<Integer, List<Integer>> adjRevList = new HashMap<>();
        for (int i = 0; i < n; i++) {
            adjRevList.put(i, new ArrayList<>());
        }

        for (int i = 0; i < n; i++) {
            List<Integer> neighbors = adjList.get(i);
            // Check for null before iterating
            if (neighbors != null) {
                for (int neighbor : neighbors) {
                    adjRevList.get(neighbor).add(i);
                }
            }
        }

        Arrays.fill(visited, -1);
        int stronglyConnectedComponents = 0;

        while (!dfsCallsNodes.isEmpty()) {
            int node = dfsCallsNodes.pop();
            if (visited[node] == -1) {
                List<Integer> newScc = new ArrayList<>();
                btrack2(adjRevList, visited, node, newScc);
                stronglyConnectedComponents++;
            }
        }

        return stronglyConnectedComponents;
    }
}

package com.thealgorithms.datastructures.trees;

public class FenwickTree {

    private int n;
    private int[] fenTree;

    /* Constructor which takes the size of the array as a parameter */
    public FenwickTree(int n) {
        this.n = n;
        this.fenTree = new int[n + 1];
    }

    /* A function which will add the element val at index i*/
    public void update(int i, int val) {
        // As index starts from 0, increment the index by 1
        i += 1;
        while (i <= n) {
            fenTree[i] += val;
            i += i & (-i);
        }
    }

    /* A function which will return the cumulative sum from index 1 to index i*/
    public int query(int i) {
        // As index starts from 0, increment the index by 1
        i += 1;
        int cumSum = 0;
        while (i > 0) {
            cumSum += fenTree[i];
            i -= i & (-i);
        }
        return cumSum;
    }
}

