        return "(" + this.getX() + "," + this.getY() + "," + z + '}';
    }
}

package com.ankan.stringBuffer;

import java.util.Random;

public class RandomString {

    /**
     * Generates a random lowercase string of the specified length.
     * 
     * @param desiredLength The length of the random string to generate
     * @return A randomly generated string containing only lowercase English letters (a-z)
     * 
     * Example: generateRandomString(5) might return "abcde", "xyzab", "random", etc.
     */
    static String generateRandomString(int desiredLength) {
        // Create a StringBuffer with the exact capacity needed (no resizing required)
        StringBuffer stringBuilder = new StringBuffer(desiredLength);

        // Random number generator for selecting characters
        Random randomGenerator = new Random();

        // Generate each character in the string
        for (int indexPosition = 0; indexPosition < desiredLength; indexPosition++) {
            // Generate random integer between 97 and 122 (ASCII values for 'a' to 'z')
            // Formula: 97 + (random value between 0 and 25)
            // - 97 is ASCII code for 'a'
            // - rand.nextFloat() * 26 gives a value between 0.0 and 26.0
            // - Casting to int truncates to a whole number between 0 and 25
            int asciiCode = 97 + (int) (randomGenerator.nextFloat() * 26);

            // Convert ASCII code to character and append to buffer
            stringBuilder.append((char) asciiCode);
        }

        // Convert the mutable StringBuffer to an immutable String
        return stringBuilder.toString();
    }

    /**
     * Alternative method using Random.nextInt() for better readability.
     * This is a more modern approach than using nextFloat().
     */
    static String generateRandomStringAlternative(int desiredLength) {
        StringBuffer stringBuilder = new StringBuffer(desiredLength);
        Random randomGenerator = new Random();

        for (int indexPosition = 0; indexPosition < desiredLength; indexPosition++) {
            // nextInt(26) generates a random integer from 0 to 25
            // Adding 97 gives the ASCII value for 'a' through 'z'
            char randomLowercaseLetter = (char) (97 + randomGenerator.nextInt(26));
            stringBuilder.append(randomLowercaseLetter);
        }

        return stringBuilder.toString();
    }

    /**
     * Generates a random string with custom character set (uppercase, lowercase, digits, etc.)
     * 
     * @param desiredLength The length of the random string
     * @param includeUppercase Whether to include uppercase letters (A-Z)
     * @param includeDigits Whether to include digits (0-9)
     * @return Randomly generated string based on specified rules
     */
    static String generateCustomRandomString(int desiredLength, boolean includeUppercase, boolean includeDigits) {
        String characters = "abcdefghijklmnopqrstuvwxyz";

        if (includeUppercase) {
            characters += "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        }
        if (includeDigits) {
            characters += "0123456789";
        }

        StringBuffer stringBuilder = new StringBuffer(desiredLength);
        Random randomGenerator = new Random();

        for (int indexPosition = 0; indexPosition < desiredLength; indexPosition++) {
            int randomIndex = randomGenerator.nextInt(characters.length());
            stringBuilder.append(characters.charAt(randomIndex));
        }

        return stringBuilder.toString();
    }
}

/*
TECHNICAL EXPLANATION - Random String Generation
================================================

How the Original Algorithm Works:
---------------------------------
1. Start with ASCII value 97 (which corresponds to character 'a')
2. Generate random float between 0.0 and 1.0
3. Multiply by 26 to get range [0.0, 26.0)
4. Cast to int to get integer between 0 and 25
5. Add to 97 to get ASCII value between 97 and 122 ('a' to 'z')
6. Cast to char and append to buffer

ASCII Reference for Lowercase Letters:
---------------------------------------
a = 97    g = 103   m = 109   s = 115   y = 121
b = 98    h = 104   n = 110   t = 116   z = 122
c = 99    i = 105   o = 111   u = 117
d = 100   j = 106   p = 112   v = 118
e = 101   k = 107   q = 113   w = 119
f = 102   l = 108   r = 114   x = 120

Why StringBuffer/Builder is Appropriate Here:
----------------------------------------------
- Multiple string concatenations (in loop) would create many intermediate String objects
- StringBuffer/Builder allows efficient in-place modification
- Pre-allocating capacity (size) prevents dynamic resizing

StringBuffer vs StringBuilder for This Use Case:
------------------------------------------------
- This method is NOT shared across threads (called from single thread)
- StringBuilder would be faster because it's not synchronized
- StringBuffer was used for thread-safety (though not needed here)

Performance Comparison (for 1000 iterations, length 10):
--------------------------------------------------------
| Approach | Objects Created | Approximate Time |
|----------|----------------|------------------|
| String Concatenation (+) | 1000+ | Slower |
| StringBuffer | 1 | Medium |
| StringBuilder | 1 | Fastest |

When to Use Each:
-----------------
✅ Use String (immutable): Single concatenation or compile-time known strings
✅ Use StringBuilder: Single-threaded, frequent modifications
✅ Use StringBuffer: Multi-threaded, frequent modifications
*/

public class DiziyiRastgeleDoldur {

    public static void main(String[] args) {
        // Dizi boyutu belirle
        int diziBoyutu = 20;

        // Rastgele sayilar olusturmak icin Random sinifini kullan
        Random random = new Random();

        // Rastgele degerlerle bir dizi olustur
        int[] rastgeleDizi = new int[diziBoyutu];

        // Diziyi doldur ve ekrana yazdir
        System.out.print("Rastgele Dizi Elemanlari: ");
        for (int i = 0; i < diziBoyutu; i++) {
            // Rastgele bir sayi olustur ve dizinin ilgili elemanina ata
            rastgeleDizi[i] = random.nextInt(20); // 0 ile 100 arasinda rastgele bir sayi
            System.out.print(rastgeleDizi[i] + " ");
        }

        // Dizinin toplamini ekrana yazdir
        int toplam = dizininToplaminiBul(rastgeleDizi);
        System.out.println("\nDizinin Toplami: " + toplam);

        // Dizinin ortalamasini ekrana yazdir
        double ortalama = dizininOrtalamasi(rastgeleDizi);
        System.out.println("Dizinin Ortalamasi: " + ortalama);

        // Dizinin ortancasini ekrana yazdir
        double ortanca = dizininOrtancasiniBul(rastgeleDizi);
        System.out.println("Dizinin Ortancasi: " + ortanca);

        // Dizinin modunu ekrana yazdir
        int mod = dizininModunuBul(rastgeleDizi);
        System.out.println("Dizinin Modu: " + mod);
    }

    // Dizinin toplamini bulan fonksiyon
    public static int dizininToplaminiBul(int[] dizi) {
        int toplam = 0;
        for (int i = 0; i < dizi.length; i++) {
            toplam += dizi[i];
        }
        return toplam;
    }

    // Dizinin ortalamasini bulan fonksiyon
    public static double dizininOrtalamasi(int[] dizi) {
        int toplam = dizininToplaminiBul(dizi);
        return (double) toplam / dizi.length;
    }

    // Dizinin ortancasini bulan fonksiyon
    public static double dizininOrtancasiniBul(int[] dizi) {
        // Diziyi kucukten buyuge sirala
        Arrays.sort(dizi);

        System.out.println("Sirali Dizi Elemanlari: " + Arrays.toString(dizi));

        // Eger dizi cift sayida elemandan olusuyorsa, ortanca iki ortadaki sayinin ortalamasidir
        if (dizi.length % 2 == 0) {
            return (dizi[dizi.length / 2 - 1] + dizi[dizi.length / 2]) / 2.0;
        } else {
            return dizi[dizi.length / 2];
        }
    }

    // Dizinin modunu bulan fonksiyon
    public static int dizininModunuBul(int[] dizi) {
        // Diziyi kucukten buyuge sirala
        Arrays.sort(dizi);

        // Modu bulmak icin degiskenler
        int mod = dizi[0];
        int maksimumFrekans = 1;
        int mevcutFrekans = 1;

        // Sirali dizide tek dongu ile elemanlari kontrol et
        for (int i = 1; i < dizi.length; i++) {
            if (dizi[i] == dizi[i - 1]) {
                mevcutFrekans++;  // Ayni elemanla karsilasildiginda frekansi artir
            } else {
                mevcutFrekans = 1;  // Yeni bir elemanla karsilasildiginda frekansi sifirla
            }

            // Eger mevcut frekans, en yuksek frekanstan buyukse, modu guncelle
            if (mevcutFrekans > maksimumFrekans) {
                maksimumFrekans = mevcutFrekans;
                mod = dizi[i];
            }
        }

        return mod;
    }
}

