		if (ay >= 3 && ay <= 5) {
			mevsim = "ilkbahar";  // Mart, Nisan, Mayis aylari ilkbahar
		} else if (ay >= 6 && ay <= 8) {
			mevsim = "Yaz";  // Haziran, Temmuz, Agustos aylari yaz
		} else if (ay >= 9 && ay <= 11) {
