package com.ankan.singleton;

import com.ankan.access.A;

public class SubClass extends A {
    boolean hasSingleProperty;  // Renamed from 'single' for clarity

    public SubClass(int rollNumber, String studentName) {
        super(rollNumber, studentName);
    }

    public static void main(String[] args) {
        // Creating SubClass instance - can access protected field 'numValue' from parent A
        // because SubClass extends A (inheritance grants access to protected members)
        SubClass subclassInstance = new SubClass(45, "Sample Name");
        int inheritedValue = subclassInstance.numValue;  // ✅ Accessible (SubClass IS-A A)

        System.out.println("Accessing protected field from SubClass: " + inheritedValue);

        // Creating parent class A instance directly
        // Parent reference cannot access protected fields from another package
        // even though the parent class declares them
        A parentClassInstance = new A(45, "Another Name");
        // int parentFieldValue = parentClassInstance.numValue;  // ❌ COMPILATION ERROR
        // Reason: Even though numValue is protected in A, the reference type is A,
        // and we're accessing from a different package (com.ankan.singleton)
        // Protected members are accessible only through inheritance OR same package

        // Correct way to access from parent reference in different package:
        int correctlyAccessedValue = parentClassInstance.getNumValue();  // ✅ Using public getter
        System.out.println("Accessing via getter from parent reference: " + correctlyAccessedValue);
    }
}

// Grandchild class demonstrating multi-level inheritance
// SubSubclass inherits from SubClass, which inherits from A
// Protected members remain accessible throughout the inheritance chain
class SubSubclass extends SubClass {

    public SubSubclass(int rollNumber, String studentName) {
        super(rollNumber, studentName);
    }

    public static void main(String[] args) {
        // Grandchild can also access protected field from great-grandparent A
        SubSubclass grandchildInstance = new SubSubclass(45, "Grandchild Name");
        int inheritedFromTop = grandchildInstance.numValue;  // ✅ Accessible (transitive inheritance)

        System.out.println("Accessing protected field from SubSubclass: " + inheritedFromTop);
        System.out.println("Protected members are accessible throughout the inheritance hierarchy");
    }
}

// Sibling class - also extends A, but NOT related to SubClass
// Both SubClass and SubClass2 are children of A, but they don't know about each other
class SubClass2 extends A {
    boolean hasSingleProperty;  // Renamed for consistency

    public SubClass2(int rollNumber, String studentName) {
        super(rollNumber, studentName);
    }

    public static void main(String[] args) {
        // SubClass2 can access its OWN inherited protected field
        SubClass2 siblingInstance = new SubClass2(45, "Sibling Name");
        int ownInheritedValue = siblingInstance.numValue;  // ✅ Accessible (own inheritance)

        // However, SubClass2 CANNOT access protected field from SubClass instance
        // because they are different classes (siblings) with no inheritance relationship
        SubClass differentBranchInstance = new SubClass(45, "Different Branch");
        // int differentBranchValue = differentBranchInstance.numValue;  // ❌ COMPILATION ERROR
        // Reason: SubClass2 does NOT extend SubClass, so no inheritance relationship
        // Even though both extend A, protected members are NOT accessible across sibling classes

        System.out.println("Accessing own protected field from SubClass2: " + ownInheritedValue);
        System.out.println("\n--- Inheritance Hierarchy Visualization ---");
        System.out.println("                    A (parent)                    ");
        System.out.println("                   /    \\                        ");
        System.out.println("                  /      \\                       ");
        System.out.println("           SubClass    SubClass2                  ");
        System.out.println("               |                                  ");
        System.out.println("               |                                  ");
        System.out.println("          SubSubclass                             ");
        System.out.println("\nProtected access rule: Accessible within inheritance chain");
        System.out.println("Sibling classes CANNOT access each other's protected fields");
    }
}

/**
 * Push–Relabel (Relabel-to-Front variant simplified to array scanning) for maximum flow.
 *
 * <p>Input graph is a capacity matrix where {@code capacity[u][v]} is the capacity of the edge
 * {@code u -> v}. Capacities must be non-negative. Vertices are indexed in {@code [0, n)}.
 *
 * <p>Time complexity: O(V^3) in the worst case for the array-based variant; typically fast in
 * practice. This implementation uses a residual network over an adjacency-matrix representation.
 *
 * <p>The API mirrors {@link EdmondsKarp#maxFlow(int[][], int, int)} and {@link Dinic#maxFlow(int[][], int, int)}.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Push%E2%80%93relabel_maximum_flow_algorithm">Wikipedia: Push–Relabel maximum flow algorithm</a>
 */
public final class PushRelabel {

    private PushRelabel() {
    }

    /**
     * Computes the maximum flow from {@code source} to {@code sink} using Push–Relabel.
     *
     * @param capacity square capacity matrix (n x n); entries must be >= 0
     * @param source source vertex index in [0, n)
     * @param sink sink vertex index in [0, n)
     * @return the maximum flow value
     * @throws IllegalArgumentException if inputs are invalid
     */
    public static int maxFlow(int[][] capacity, int source, int sink) {
        validate(capacity, source, sink);
        final int n = capacity.length;
        if (source == sink) {
            return 0;
        }

        int[][] residual = new int[n][n];
        for (int i = 0; i < n; i++) {
            residual[i] = Arrays.copyOf(capacity[i], n);
        }

        int[] height = new int[n];
        int[] excess = new int[n];
        int[] nextNeighbor = new int[n];

        // Preflow initialization
        height[source] = n;
        for (int v = 0; v < n; v++) {
            int cap = residual[source][v];
            if (cap > 0) {
                residual[source][v] -= cap;
                residual[v][source] += cap;
                excess[v] += cap;
                excess[source] -= cap;
            }
        }

        // Active queue contains vertices (except source/sink) with positive excess
        Queue<Integer> active = new ArrayDeque<>();
        for (int v = 0; v < n; v++) {
            if (v != source && v != sink && excess[v] > 0) {
                active.add(v);
            }
        }

        State state = new State(residual, height, excess, nextNeighbor, source, sink, active);

        while (!active.isEmpty()) {
            int u = active.poll();
            discharge(u, state);
            if (excess[u] > 0) {
                // still active after discharge; push to back
                active.add(u);
            }
        }

        // Total flow equals excess at sink
        return excess[sink];
    }

    private static void discharge(int u, State s) {
        final int n = s.residual.length;
        while (s.excess[u] > 0) {
            if (s.nextNeighbor[u] >= n) {
                relabel(u, s.residual, s.height);
                s.nextNeighbor[u] = 0;
                continue;
            }
            int v = s.nextNeighbor[u];
            if (s.residual[u][v] > 0 && s.height[u] == s.height[v] + 1) {
                int delta = Math.min(s.excess[u], s.residual[u][v]);
                s.residual[u][v] -= delta;
                s.residual[v][u] += delta;
                s.excess[u] -= delta;
                int prevExcessV = s.excess[v];
                s.excess[v] += delta;
                if (v != s.source && v != s.sink && prevExcessV == 0) {
                    s.active.add(v);
                }
            } else {
                s.nextNeighbor[u]++;
            }
        }
    }

    private static final class State {
        final int[][] residual;
        final int[] height;
        final int[] excess;
        final int[] nextNeighbor;
        final int source;
        final int sink;
        final Queue<Integer> active;

        State(int[][] residual, int[] height, int[] excess, int[] nextNeighbor, int source, int sink, Queue<Integer> active) {
            this.residual = residual;
            this.height = height;
            this.excess = excess;
            this.nextNeighbor = nextNeighbor;
            this.source = source;
            this.sink = sink;
            this.active = active;
        }
    }

    private static void relabel(int u, int[][] residual, int[] height) {
        final int n = residual.length;
        int minHeight = Integer.MAX_VALUE;
        for (int v = 0; v < n; v++) {
            if (residual[u][v] > 0) {
                minHeight = Math.min(minHeight, height[v]);
            }
        }
        if (minHeight < Integer.MAX_VALUE) {
            height[u] = minHeight + 1;
        }
    }

    private static void validate(int[][] capacity, int source, int sink) {
        if (capacity == null || capacity.length == 0) {
            throw new IllegalArgumentException("Capacity matrix must not be null or empty");
        }
        int n = capacity.length;
        for (int i = 0; i < n; i++) {
            if (capacity[i] == null || capacity[i].length != n) {
                throw new IllegalArgumentException("Capacity matrix must be square");
            }
            for (int j = 0; j < n; j++) {
                if (capacity[i][j] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative");
                }
            }
        }
        if (source < 0 || sink < 0 || source >= n || sink >= n) {
            throw new IllegalArgumentException("Source and sink must be valid vertex indices");
        }
    }
}

/**
 * A utility class for counting the number of inversions in an array.
 * <p>
 * An inversion is a pair (i, j) such that i < j and arr[i] > arr[j].
 * This class implements a divide-and-conquer approach, similar to merge sort,
 * to count the number of inversions efficiently.
 * <p>
 * Time Complexity: O(n log n)
 * Space Complexity: O(n) (due to temporary arrays during merge step)
 *
 * <p>Applications:
 * - Used in algorithms related to sorting and permutation analysis.
 * - Helps in determining how far an array is from being sorted.
 * - Applicable in bioinformatics and signal processing.
 *
 * <p>This class cannot be instantiated, as it is intended to provide
 * only static utility methods.
 *
 * @author Hardvan
 */
public final class CountingInversions {
    private CountingInversions() {
    }

    /**
     * Counts the number of inversions in the given array.
     *
     * @param arr The input array of integers.
     * @return The total number of inversions in the array.
     */
    public static int countInversions(int[] arr) {
        return mergeSortAndCount(arr, 0, arr.length - 1);
    }

    /**
     * Recursively divides the array into two halves, sorts them, and counts
     * the number of inversions. Uses a modified merge sort approach.
     *
     * @param arr  The input array.
     * @param left The starting index of the current segment.
     * @param right The ending index of the current segment.
     * @return The number of inversions within the segment [left, right].
     */
    private static int mergeSortAndCount(int[] arr, int left, int right) {
        if (left >= right) {
            return 0;
        }

        int mid = left + (right - left) / 2;
        int inversions = 0;

        inversions += mergeSortAndCount(arr, left, mid);
        inversions += mergeSortAndCount(arr, mid + 1, right);
        inversions += mergeAndCount(arr, left, mid, right);
        return inversions;
    }

    /**
     * Merges two sorted subarrays and counts the cross-inversions between them.
     * A cross-inversion occurs when an element from the right subarray is
     * smaller than an element from the left subarray.
     *
     * @param arr The input array.
     * @param left The starting index of the first subarray.
     * @param mid The ending index of the first subarray and midpoint of the segment.
     * @param right The ending index of the second subarray.
     * @return The number of cross-inversions between the two subarrays.
     */
    private static int mergeAndCount(int[] arr, int left, int mid, int right) {
        int[] leftArr = new int[mid - left + 1];
        int[] rightArr = new int[right - mid];

        System.arraycopy(arr, left, leftArr, 0, mid - left + 1);
        System.arraycopy(arr, mid + 1, rightArr, 0, right - mid);

        int i = 0;
        int j = 0;
        int k = left;
        int inversions = 0;

        while (i < leftArr.length && j < rightArr.length) {
            if (leftArr[i] <= rightArr[j]) {
                arr[k++] = leftArr[i++];
            } else {
                arr[k++] = rightArr[j++];
                inversions += mid + 1 - left - i;
            }
        }

        while (i < leftArr.length) {
            arr[k++] = leftArr[i++];
        }
        while (j < rightArr.length) {
            arr[k++] = rightArr[j++];
        }

        return inversions;
    }
}

