/* 
 * Bu kod, bir SQLite veritabanini baslatir ve oyuncu, puan ve basarilarini saklamak icin bir tablo olusturur. 
 * Ardindan tabloya yeni rastgele bir kayit ekler, kullanicidan veri alir ve en yuksek puana sahip 10 oyuncuyu listeler.
 * 
 * */

public class GameResults {

    private static final String DB_URL = "jdbc:sqlite:game.db"; // Veritabani URL'si
    private static final String CREATE_TABLE_SQL = "CREATE TABLE IF NOT EXISTS scores (name TEXT, score INTEGER, achievement TEXT)"; // Tablo olusturma SQL sorgusu
    private static final String INSERT_SCORE_SQL = "INSERT INTO scores (name, score, achievement) VALUES (?, ?, ?)"; // Yeni puan ve basari ekleme SQL sorgusu
    private static final String SELECT_HIGH_SCORES_SQL = "SELECT * FROM scores ORDER BY score DESC LIMIT ?"; // Yuksek puanlari sorgulama SQL sorgusu
    private static Random random = new Random(); // Rastgele sayi uretici
    private static Scanner scanner = new Scanner(System.in); // Kullanici girdi alici

    public static void main(String[] args) {
        // Veritabanini baslat ve 'scores' tablosunu olustur
        try (Connection conn = DriverManager.getConnection(DB_URL); // Veritabanina baglan
        		Statement stmt = conn.createStatement()) { // SQL komutlari calistirmak icin statement olustur
            stmt.execute(CREATE_TABLE_SQL); // Tabloyu olustur
        } catch (SQLException e) {
            e.printStackTrace(); // Hata olursa yazdir
        }

        // Veritabanina rastgele oyuncu adi, puan ve basari ekle
        for (int i = 0; i < 5; i++) { // 5 oyuncu icin rastgele puanlar ve basarilar ekle
            try (Connection conn = DriverManager.getConnection(DB_URL); // Veritabanina baglan
            		PreparedStatement pstmt = conn.prepareStatement(INSERT_SCORE_SQL)) { // SQL komutunu hazirla
                String name = "player" + (i + 1); // Oyuncu adi ("player1", "player2", ...)
                int score = random.nextInt(100); // Rastgele bir puan (0-99 arasinda)
                String achievement = getRandomAchievement(); // Rastgele bir basari al
                pstmt.setString(1, name); // Oyuncunun adini ayarla
                pstmt.setInt(2, score); // Puani ayarla
                pstmt.setString(3, achievement); // Basariyi ayarla
                pstmt.executeUpdate(); // Veriyi ekle
                System.out.println("Yeni kayit eklendi: " + name + " - Puan: " + score + " - Basari: " + achievement); // Eklenen veriyi yazdir
            } catch (SQLException e) {
                e.printStackTrace(); // Hata olursa yazdir
            }
        }

        // Kullanici yeni oyuncu eklemek isterse
        System.out.print("Yeni oyuncu eklemek ister misiniz? (E/H): ");
        String choice = scanner.nextLine();
        if (choice.equalsIgnoreCase("E")) {
            System.out.print("Oyuncu ismi girin: ");
            String name = scanner.nextLine();
            System.out.print("Puan girin: ");
            int score = scanner.nextInt();
            scanner.nextLine(); // Bosluk karakterini temizle
            String achievement = getRandomAchievement(); // Rastgele basari ekle

            try (Connection conn = DriverManager.getConnection(DB_URL); // Veritabanina baglan
            		PreparedStatement pstmt = conn.prepareStatement(INSERT_SCORE_SQL)) { // SQL komutunu hazirla
                pstmt.setString(1, name); // Oyuncu adi
                pstmt.setInt(2, score); // Puan
                pstmt.setString(3, achievement); // Basari
                pstmt.executeUpdate(); // Veriyi ekle
                System.out.println("Yeni oyuncu eklendi: " + name + " - Puan: " + score + " - Basari: " + achievement);
            } catch (SQLException e) {
                e.printStackTrace(); // Hata olursa yazdir
            }
        }

        // Veritabanindan en yuksek puanli 10 kayidi al
        try (Connection conn = DriverManager.getConnection(DB_URL); // Veritabanina baglan
        		PreparedStatement pstmt = conn.prepareStatement(SELECT_HIGH_SCORES_SQL)) { // SQL komutunu hazirla
            pstmt.setInt(1, 10); // Sadece 10 kayit al
            ResultSet rs = pstmt.executeQuery(); // Sonuclari al
            System.out.println("\nEn yuksek 10 puan: ");
            while (rs.next()) { // Sonuclar uzerinde don
                String name = rs.getString("name"); // Oyuncunun adini al
                int score = rs.getInt("score"); // Puani al
                String achievement = rs.getString("achievement"); // Basariyi al
                System.out.println(name + ": " + score + " - Basari: " + achievement); // Puan ve basariyi ekrana yazdir
            }
        } catch (SQLException e) {
            e.printStackTrace(); // Hata olursa yazdir
        }
    }

    // Rastgele bir basari mesaji
    private static String getRandomAchievement() {
        String[] achievements = {
            "Yeni Baslayan",
            "Buyuk Zafer",
            "Efsane Oyuncu",
            "Hizli Dusunen",
            "Oyun Ustasi"
        };
        return achievements[random.nextInt(achievements.length)]; // Rastgele bir basari sec
    }
}

public class KuvvetTablosu {

    public static void main(String[] args) {

        // Basliklari hizali sekilde yazdir
        System.out.printf("%8s %8s %8s %8s %8s %8s%n", "Sayi", "^1", "^2", "^3", "^4", "^5");
        // Ayirici cizgi
        System.out.println("-------------------------------------------------------");

        // 1'den 10'a kadar her sayi icin kuvvet degerlerini hesapla
        int taban = 1;
        while (taban <= 10) {
            System.out.printf("%9d", taban);
            // Kuvvetleri 1'den 5'e kadar hesaplayan ic dongu
            for (int us = 1; us <= 5; us++) {
                System.out.printf("%9d", (int) Math.pow(taban, us));
            }
            // Bir sonraki sayiya gecmeden once satir atla
            System.out.println();
            taban++;
        }
    }
}

/**
 * An implementation of the Lempel-Ziv-Welch (LZW) algorithm.
 *
 * <p>
 * LZW is a universal lossless data compression algorithm created by Abraham
 * Lempel, Jacob Ziv, and Terry Welch. It works by building a dictionary of
 * strings encountered during compression and replacing occurrences of those
 * strings with a shorter code.
 * </p>
 *
 * <p>
 * This implementation handles standard ASCII characters and provides methods for
 * both compression and decompression.
 * <ul>
 * <li>Compressing "TOBEORNOTTOBEORTOBEORNOT" results in a list of integer
 * codes.</li>
 * <li>Decompressing that list of codes results back in the original
 * string.</li>
 * </ul>
 * </p>
 *
 * <p>
 * Time Complexity: O(n) for both compression and decompression, where n is the
 * length of the input string.
 * </p>
 *
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Lempel%E2%80%93Ziv%E2%80%93Welch">Wikipedia:
 * Lempel–Ziv–Welch</a></li>
 * </ul>
 * </p>
 */
public final class LZW {

/**
 * Private constructor to prevent instantiation of this utility class.
 */
private LZW() {
}

/**
 * Compresses a string using the LZW algorithm.
 *
 * @param sourceData The string to be compressed. Can be null.
 * @return A list of integers representing the compressed data. Returns an empty
 * list if the input is null or empty.
 */
public static List<Integer> compress(String sourceData) {
if (sourceData == null || sourceData.isEmpty()) {
return new ArrayList<>();
}
int nextCodeValue = 256;
Map<String, Integer> codeDictionary = new HashMap<>();
for (int asciiValue = 0; asciiValue < nextCodeValue; asciiValue++) {
codeDictionary.put("" + (char) asciiValue, asciiValue);
}
String currentSequence = "";
List<Integer> encodedResult = new ArrayList<>();
for (char currentChar : sourceData.toCharArray()) {
String extendedSequence = currentSequence + currentChar;
if (codeDictionary.containsKey(extendedSequence)) {
currentSequence = extendedSequence;
} else {
encodedResult.add(codeDictionary.get(currentSequence));
codeDictionary.put(extendedSequence, nextCodeValue++);
currentSequence = "" + currentChar;
}
}
encodedResult.add(codeDictionary.get(currentSequence));
return encodedResult;
}

/**
 * Decompresses a list of integers back into a string using the LZW algorithm.
 *
 * @param encodedData A list of integers representing the compressed data. Can be
 *                   null.
 * @return The original, uncompressed string. Returns an empty string if the
 * input is null or empty.
 */
public static String decompress(List<Integer> encodedData) {
if (encodedData == null || encodedData.isEmpty()) {
return "";
}
int nextCodeValue = 256;
Map<Integer, String> reverseDictionary = new HashMap<>();
for (int asciiValue = 0; asciiValue < nextCodeValue; asciiValue++) {
reverseDictionary.put(asciiValue, "" + (char) asciiValue);
}
List<Integer> remainingCodes = new ArrayList<>(encodedData);
String currentSequence = reverseDictionary.get(remainingCodes.removeFirst());
StringBuilder decodedResult = new StringBuilder(currentSequence);
for (int currentCode : remainingCodes) {
String decodedEntry;
if (reverseDictionary.containsKey(currentCode)) {
decodedEntry = reverseDictionary.get(currentCode);
} else if (currentCode == nextCodeValue) {
decodedEntry = currentSequence + currentSequence.charAt(0);
} else {
throw new IllegalArgumentException("Invalid compressed code encountered: " + currentCode);
}
decodedResult.append(decodedEntry);
reverseDictionary.put(nextCodeValue++, currentSequence + decodedEntry.charAt(0));
currentSequence = decodedEntry;
}
return decodedResult.toString();
}
}

