public class SumOfDigits {
    public static void main(String[] args) {
        int number = 48293;
        int original = number;
        int sum = 0;

        while (number > 0) {
            sum += number % 10;
            number /= 10;
        }

        System.out.println("Sum of digits of " + original + " is " + sum);
    }
}

