public class Exchange extends ArrayList<String>{
    public Exchange() {
        this.add("USD;VND;17000");
        this.add("EUR;USD;1.2");
        this.add("USD;IDN;15789");
        this.add("USD;EUR;0.83");
        this.add("CAD;IDN;16869");
    }

    public double convert(Rate rate) {
        for (String rateString : this) {
            StringTokenizer tokenizer = new StringTokenizer(rateString, ";");
            String tokenizer_code1 = tokenizer.nextToken();
            String tokenizer_code2 = tokenizer.nextToken();
            Double tokenizer_amount = Double.parseDouble(tokenizer.nextToken());
            if (rate.getCODE1().toLowerCase().equals(tokenizer_code1.toLowerCase()) && rate.getCODE2().toLowerCase().equals(tokenizer_code2.toLowerCase())) {
                return tokenizer_amount * rate.getRate();
            }
        }
        System.out.println("Can not found code!!!!");
        return rate.getRate();
    }
}

public class PowerCalculator {
    /**
     * Computes base^exponent using fast (binary) exponentiation.
     * Works in O(log n) time.
     */
    public static long power(long base, int exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result *= base;
            }
            base *= base;
            exponent >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println("2^10 = " + power(2, 10));
        System.out.println("3^7 = " + power(3, 7));
        System.out.println("5^0 = " + power(5, 0));
    }
}

/**
 * Given a set of points and a number k.
 * The goal is to minimize the maximum distance between any point and its nearest center.
 * Each point is assigned to the nearest center.
 * The distance between two points is the Euclidean distance.
 * The problem is NP-hard.
 *
 * @author Hardvan
 */
public final class KCenters {
    private KCenters() {
    }

    /**
     * Finds the maximum distance to the nearest center given k centers.
     * Steps:
     * 1. Initialize an array {@code selected} of size n and an array {@code maxDist} of size n.
     * 2. Set the first node as selected and update the maxDist array.
     * 3. For each center, find the farthest node from the selected centers.
     * 4. Update the maxDist array.
     * 5. Return the maximum distance to the nearest center.
     *
     * @param distances matrix representing distances between nodes
     * @param k         the number of centers
     * @return the maximum distance to the nearest center
     */
    public static int findKCenters(int[][] distances, int k) {
        int n = distances.length;
        boolean[] selected = new boolean[n];
        int[] maxDist = new int[n];

        Arrays.fill(maxDist, Integer.MAX_VALUE);

        selected[0] = true;
        for (int i = 1; i < n; i++) {
            maxDist[i] = Math.min(maxDist[i], distances[0][i]);
        }

        for (int centers = 1; centers < k; centers++) {
            int farthest = -1;
            for (int i = 0; i < n; i++) {
                if (!selected[i] && (farthest == -1 || maxDist[i] > maxDist[farthest])) {
                    farthest = i;
                }
            }
            selected[farthest] = true;
            for (int i = 0; i < n; i++) {
                maxDist[i] = Math.min(maxDist[i], distances[farthest][i]);
            }
        }

        int result = 0;
        for (int dist : maxDist) {
            result = Math.max(result, dist);
        }
        return result;
    }
}

/**
 * Given a binary tree.
 * This code returns the zigzag level order traversal of its nodes' values.
 * Binary tree:
 *                               7
 *                   /                         \
 *                6                           3
 *         /                \             /             \
 *      2                    4         10                19
 * Zigzag traversal:
 * [[7], [3, 6], [2, 4, 10, 19]]
 * <p>
 * This solution implements the breadth-first search (BFS) algorithm using a queue.
 * 1. The algorithm starts with a root node. This node is added to a queue.
 * 2. While the queue is not empty:
 *  - each time we enter the while-loop we get queue size. Queue size refers to the number of nodes
 * at the current level.
 *  - we traverse all the level nodes in 2 ways: from left to right OR from right to left
 *    (this state is stored on `prevLevelFromLeftToRight` variable)
 *  - if the current node has children we add them to a queue
 *  - add level with nodes to a result.
 * <p>
 * Complexities:
 * O(N) - time, where N is the number of nodes in a binary tree
 * O(N) - space, where N is the number of nodes in a binary tree
 *
 * @author Albina Gimaletdinova on 11/01/2023
 */
public final class ZigzagTraversal {
    private ZigzagTraversal() {
    }
    public static List<List<Integer>> traverse(BinaryTree.Node root) {
        if (root == null) {
            return List.of();
        }

        List<List<Integer>> result = new ArrayList<>();

        // create a queue
        Deque<BinaryTree.Node> q = new ArrayDeque<>();
        q.offer(root);
        // start with writing nodes from left to right
        boolean prevLevelFromLeftToRight = false;

        while (!q.isEmpty()) {
            int nodesOnLevel = q.size();
            List<Integer> level = new LinkedList<>();
            // traverse all the level nodes
            for (int i = 0; i < nodesOnLevel; i++) {
                BinaryTree.Node node = q.poll();
                if (prevLevelFromLeftToRight) {
                    level.add(0, node.data);
                } else {
                    level.add(node.data);
                }
                if (node.left != null) {
                    q.offer(node.left);
                }
                if (node.right != null) {
                    q.offer(node.right);
                }
            }
            // the next level node traversal will be from the other side
            prevLevelFromLeftToRight = !prevLevelFromLeftToRight;
            result.add(level);
        }
        return result;
    }
}

import java.util.Random;
import java.util.Scanner;

public class NumberGuessingGame {
    public static void main(String[] args) {
        Random random = new Random();
        Scanner scanner = new Scanner(System.in);
        int secret = random.nextInt(100) + 1;
        int attempts = 0;

        System.out.println("Guess a number between 1 and 100!");

        while (true) {
            System.out.print("Your guess: ");
            int guess = scanner.nextInt();
            attempts++;

            if (guess < secret) {
                System.out.println("Too low!");
            } else if (guess > secret) {
                System.out.println("Too high!");
            } else {
                System.out.println("Correct! Attempts: " + attempts);
                break;
            }
        }
        scanner.close();
    }
}

package com.thealgorithms.datastructures.crdt;

import java.util.HashSet;
import java.util.Set;
import java.util.UUID;

/**
 * ORSet (Observed-Removed Set) is a state-based CRDT (Conflict-free Replicated Data Type)
 * that supports both addition and removal of elements. This particular implementation follows
 * the Add-Wins strategy, meaning that in case of conflicting add and remove operations,
 * the add operation takes precedence. The merge operation of two OR-Sets ensures that
 * elements added at any replica are eventually observed at all replicas. Removed elements,
 * once observed, are never reintroduced.
 * This OR-Set implementation provides methods for adding elements, removing elements,
 * checking for element existence, retrieving the set of elements, comparing with other OR-Sets,
 * and merging with another OR-Set to create a new OR-Set containing all unique elements
 * from both sets.
 *
 * @author itakurah (Niklas Hoefflin) (https://github.com/itakurah)
 * @see <a href="https://en.wikipedia.org/wiki/Conflict-free_replicated_data_type">Conflict-free_replicated_data_type</a>
 * @see <a href="https://github.com/itakurah">itakurah (Niklas Hoefflin)</a>
 */

public class ORSet<ElementType> {

private final Set<VersionedPair<ElementType>> activeElements;
private final Set<VersionedPair<ElementType>> removedMarkers;

/**
 * Constructs an empty OR-Set.
 */
public ORSet() {
this.activeElements = new HashSet<>();
this.removedMarkers = new HashSet<>();
}

/**
 * Checks if the set contains the specified element.
 *
 * @param targetElement the element to check for
 * @return true if the set contains the element, false otherwise
 */
public boolean contains(ElementType targetElement) {
return activeElements.stream().anyMatch(pair -> pair.getElementValue().equals(targetElement));
}

/**
 * Retrieves the elements in the set.
 *
 * @return a set containing the elements
 */
public Set<ElementType> getCurrentElements() {
Set<ElementType> resultSet = new HashSet<>();
activeElements.forEach(pair -> resultSet.add(pair.getElementValue()));
return resultSet;
}

/**
 * Adds the specified element to the set.
 *
 * @param elementToAdd the element to add
 */
public void add(ElementType elementToAdd) {
String uniqueToken = generateUniqueToken();
applyAddOperation(elementToAdd, uniqueToken);
}

/**
 * Removes the specified element from the set.
 *
 * @param elementToRemove the element to remove
 */
public void remove(ElementType elementToRemove) {
Set<VersionedPair<ElementType>> pairsToRemove = findPairsForElement(elementToRemove);
applyRemoveOperation(pairsToRemove);
}

/**
 * Collect all pairs with the specified element.
 *
 * @param targetElement the element to collect pairs for
 * @return a set of pairs with the specified element to be removed
 */
private Set<VersionedPair<ElementType>> findPairsForElement(ElementType targetElement) {
Set<VersionedPair<ElementType>> matchingPairs = new HashSet<>();
for (VersionedPair<ElementType> currentPair : activeElements) {
if (currentPair.getElementValue().equals(targetElement)) {
matchingPairs.add(currentPair);
}
}
return matchingPairs;
}

/**
 * Generates a unique tag for the element.
 *
 * @return the unique tag
 */
private String generateUniqueToken() {
return UUID.randomUUID().toString();
}

/**
 * Adds the element with the specified unique tag to the set.
 *
 * @param elementValue the element to add
 * @param uniqueToken       the unique tag associated with the element
 */
private void applyAddOperation(ElementType elementValue, String uniqueToken) {
VersionedPair<ElementType> newPair = new VersionedPair<>(elementValue, uniqueToken);
activeElements.add(newPair);
activeElements.removeAll(removedMarkers);
}

/**
 * Removes the specified pairs from the set.
 *
 * @param pairsToRemove the pairs to remove
 */
private void applyRemoveOperation(Set<VersionedPair<ElementType>> pairsToRemove) {
activeElements.removeAll(pairsToRemove);
removedMarkers.addAll(pairsToRemove);
}

/**
 * Compares this Add-Wins OR-Set with another OR-Set to check if elements and tombstones are a subset.
 *
 * @param otherSet the other OR-Set to compare
 * @return true if the sets are subset, false otherwise
 */
public boolean isSubsetOf(ORSet<ElementType> otherSet) {
Set<VersionedPair<ElementType>> combinedSelf = new HashSet<>(activeElements);
combinedSelf.addAll(removedMarkers);
Set<VersionedPair<ElementType>> combinedOther = new HashSet<>(otherSet.activeElements);
combinedOther.addAll(otherSet.removedMarkers);
return combinedOther.containsAll(combinedSelf) && otherSet.removedMarkers.containsAll(removedMarkers);
}

/**
 * Merges this Add-Wins OR-Set with another OR-Set.
 *
 * @param otherSet the other OR-Set to merge
 */
public void mergeWith(ORSet<ElementType> otherSet) {
activeElements.removeAll(otherSet.removedMarkers);
otherSet.activeElements.removeAll(removedMarkers);
activeElements.addAll(otherSet.activeElements);
removedMarkers.addAll(otherSet.removedMarkers);
}

/**
 * Represents a pair containing an element and a unique tag.
 *
 * @param <ElementType> the type of the element in the pair
 */
public static class VersionedPair<ElementType> {
private final ElementType elementValue;
private final String uniqueIdentifier;

/**
 * Constructs a pair with the specified element and unique tag.
 *
 * @param elementValue   the element in the pair
 * @param uniqueIdentifier the unique tag associated with the element
 */
public VersionedPair(ElementType elementValue, String uniqueIdentifier) {
this.elementValue = elementValue;
this.uniqueIdentifier = uniqueIdentifier;
}

/**
 * Gets the element from the pair.
 *
 * @return the element
 */
public ElementType getElementValue() {
return elementValue;
}
}
}

package functions;
import java.util.Scanner;  // kullanicidan girdi okumak icin

public class Faktoriyel {

    // Verilen sayinin faktoriyelini hesaplayip dondurur
    int faktoriyelHesapla(int deger) {
        int carpim = 1; // notr eleman ile baslatilir
        for (; deger > 0; deger--) {
            carpim *= deger; // her adimda mevcut degerle carpilir
        }
        return carpim;
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);

        System.out.println("Lutfen bir sayi giriniz");
        int girilenDeger = tarayici.nextInt();

        Faktoriyel hesaplayici = new Faktoriyel();

        int sonuc = hesaplayici.faktoriyelHesapla(girilenDeger);
        System.out.println("Sonuc = " + sonuc);

        tarayici.close();
    }
}

package com.thealgorithms.maths.Prime;

/*
 * Java program for mobius function
 * For any positive integer n, define μ(n) as the sum of the primitive nth roots of unity.
 * It has values in {−1, 0, 1} depending on the factorization of n into prime factors:
 *   μ(n) = +1 if n is a square-free positive integer with an even number of prime factors.
 *   μ(n) = −1 if n is a square-free positive integer with an odd number of prime factors.
 *   μ(n) = 0 if n has a squared prime factor.
 * Wikipedia: https://en.wikipedia.org/wiki/M%C3%B6bius_function
 *
 * Author: Akshay Dubey (https://github.com/itsAkshayDubey)
 *
 * */
public final class MobiusFunction {
    private MobiusFunction() {
    }

    /**
     * This method returns μ(n) of given number n
     *
     * @param number Integer value which μ(n) is to be calculated
     * @return  1 when number is less than or equals 1
     *            or number has even number of prime factors
     *          0 when number has repeated prime factor
     *         -1 when number has odd number of prime factors
     */
    public static int mobius(int number) {
        if (number <= 0) {
            // throw exception when number is less than or is zero
            throw new IllegalArgumentException("Number must be greater than zero.");
        }

        if (number == 1) {
            // return 1 if number passed is less or is 1
            return 1;
        }

        int primeFactorCount = 0;

        for (int i = 1; i <= number; i++) {
            // find prime factors of number
            if (number % i == 0 && PrimeCheck.isPrime(i)) {
                // check if number is divisible by square of prime factor
                if (number % (i * i) == 0) {
                    // if number is divisible by square of prime factor
                    return 0;
                }
                /*increment primeFactorCount by 1
                                if number is not divisible by square of found prime factor*/
                primeFactorCount++;
            }
        }

        return (primeFactorCount % 2 == 0) ? 1 : -1;
    }
}

package com.thealgorithms.datastructures.crdt;

import java.util.HashMap;
import java.util.Map;

/**
 * G-Counter (Grow-only Counter) is a state-based CRDT (Conflict-free Replicated Data Type)
 * designed for tracking counts in a distributed and concurrent environment.
 * Each process maintains its own counter, allowing only increments. The total count
 * is obtained by summing individual process counts.
 * This implementation supports incrementing, querying the total count,
 * comparing with other G-Counters, and merging with another G-Counter
 * to compute the element-wise maximum.
 * (https://en.wikipedia.org/wiki/Conflict-free_replicated_data_type)
 *
 * @author itakurah (https://github.com/itakurah)
 */

class GCounter {
private final Map<Integer, Integer> internalCounter;
private final int nodeIdentifier;
private final int totalNodes;

/**
 * Constructs a G-Counter for a cluster of totalNodes nodes.
 *
 * @param nodeId The identifier for the current node.
 * @param totalNodeCount The number of nodes in the cluster.
 */
GCounter(int nodeId, int totalNodeCount) {
this.nodeIdentifier = nodeId;
this.totalNodes = totalNodeCount;
this.internalCounter = new HashMap<>();
for (int nodeIndex = 0; nodeIndex < totalNodeCount; nodeIndex++) {
internalCounter.put(nodeIndex, 0);
}
}

/**
 * Increments the counter for the current node.
 */
public void increment() {
internalCounter.put(nodeIdentifier, internalCounter.get(nodeIdentifier) + 1);
}

/**
 * Gets the total value of the counter by summing up values from all nodes.
 *
 * @return The total value of the counter.
 */
public int getTotalValue() {
int accumulatedSum = 0;
for (int nodeValue : internalCounter.values()) {
accumulatedSum += nodeValue;
}
return accumulatedSum;
}

/**
 * Compares the state of this G-Counter with another G-Counter.
 *
 * @param otherCounter The other G-Counter to compare with.
 * @return True if the state of this G-Counter is less than or equal to the state of the other G-Counter.
 */
public boolean isLessOrEqual(GCounter otherCounter) {
for (int nodeIndex = 0; nodeIndex < totalNodes; nodeIndex++) {
if (this.internalCounter.get(nodeIndex) > otherCounter.internalCounter.get(nodeIndex)) {
return false;
}
}
return true;
}

/**
 * Merges the state of this G-Counter with another G-Counter.
 *
 * @param otherCounter The other G-Counter to merge with.
 */
public void mergeWith(GCounter otherCounter) {
for (int nodeIndex = 0; nodeIndex < totalNodes; nodeIndex++) {
int currentValue = this.internalCounter.get(nodeIndex);
int otherValue = otherCounter.internalCounter.get(nodeIndex);
this.internalCounter.put(nodeIndex, Math.max(currentValue, otherValue));
}
}
}

