}

package objects;

/*
 * Models a 24-hour digital clock that can tick forward second by
 * second, cascading into minutes and hours as needed.
 */
public class DijitalSaat {

	private int saatDegeri = 0;
	private int dakikaDegeri = 0;
	private int saniyeDegeri = 0;

	public int getSaniye() {
		return this.saniyeDegeri;
	}

	// Only accepts values within the valid 0-59 range.
	public void setSaniye(int saniyeDegeri) {
		if (saniyeDegeri >= 0 && saniyeDegeri < 60) {
			this.saniyeDegeri = saniyeDegeri;
		}
	}

	// Prints the current time as saat:dakika:saniye.
	public void goster() {
		System.out.println(saatDegeri + ":" + dakikaDegeri + ":" + saniyeDegeri);
	}

	// Rolls the hour over back to 0 after 23.
	private void saatiArttir() {
		saatDegeri = saatDegeri + 1;
		if (saatDegeri > 23) {
			saatDegeri = 0;
		}
	}

	// Rolls the minute over after 59, cascading into the hour.
	private void dakikayiArttir() {
		dakikaDegeri = dakikaDegeri + 1;
		if (dakikaDegeri > 59) {
			dakikaDegeri = 0;
			saatiArttir();
		}
	}

	// Advances one second, cascading into minute/hour as needed.
	public void saniyeyiArttir() {
		saniyeDegeri = saniyeDegeri + 1;
		if (saniyeDegeri > 59) {
			saniyeDegeri = 0;
			dakikayiArttir();
		}
	}

	// Directly overwrites the clock with a new time.
	public void saatiGuncelle(int saatDegeri, int dakikaDegeri, int saniyeDegeri) {
		this.saatDegeri = saatDegeri;
		this.dakikaDegeri = dakikaDegeri;
		this.saniyeDegeri = saniyeDegeri;
	}

	public static void main(String[] args) {
		DijitalSaat saatNesnesi = new DijitalSaat();

		saatNesnesi.saatiGuncelle(10, 58, 50);
		System.out.println("Baslangic saati:");
		saatNesnesi.goster();

		for (int adim = 0; adim < 70; adim++) {
			saatNesnesi.saniyeyiArttir();
			System.out.print("Saniye " + (adim + 1) + ": ");
			saatNesnesi.goster();
		}

		System.out.println("\nSaati bir saat ileri aliyoruz...");
		for (int adim = 0; adim < 120; adim++) {
			saatNesnesi.saniyeyiArttir();
		}
		System.out.print("Yeni saat: ");
		saatNesnesi.goster();
	}
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;

/**
 * Hopcroft–Karp algorithm for maximum bipartite matching.
 *
 * Left part: vertices [0,nLeft-1], Right part: [0,nRight-1].
 * Adjacency list: for each left vertex u, list right vertices v it connects to.
 *
 * Time complexity: O(E * sqrt(V)).
 *
 * @see <a href="https://en.wikipedia.org/wiki/Hopcroft%E2%80%93Karp_algorithm">
 *      Wikipedia: Hopcroft–Karp algorithm</a>
 * @author ptzecher
 */
public class HopcroftKarp {

    private final int nLeft;
    private final List<List<Integer>> adj;

    private final int[] pairU;
    private final int[] pairV;
    private final int[] dist;

    public HopcroftKarp(int nLeft, int nRight, List<List<Integer>> adj) {
        this.nLeft = nLeft;
        this.adj = adj;

        this.pairU = new int[nLeft];
        this.pairV = new int[nRight];
        this.dist = new int[nLeft];

        Arrays.fill(pairU, -1);
        Arrays.fill(pairV, -1);
    }

    /** Returns the size of the maximum matching. */
    public int maxMatching() {
        int matching = 0;
        while (bfs()) {
            for (int u = 0; u < nLeft; u++) {
                if (pairU[u] == -1 && dfs(u)) {
                    matching++;
                }
            }
        }
        return matching;
    }

    // BFS to build layers
    private boolean bfs() {
        Queue<Integer> queue = new ArrayDeque<>();
        Arrays.fill(dist, -1);

        for (int u = 0; u < nLeft; u++) {
            if (pairU[u] == -1) {
                dist[u] = 0;
                queue.add(u);
            }
        }

        boolean foundAugPath = false;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : adj.get(u)) {
                int matchedLeft = pairV[v];
                if (matchedLeft == -1) {
                    foundAugPath = true;
                } else if (dist[matchedLeft] == -1) {
                    dist[matchedLeft] = dist[u] + 1;
                    queue.add(matchedLeft);
                }
            }
        }
        return foundAugPath;
    }

    // DFS to find augmenting paths within the BFS layering
    private boolean dfs(int u) {
        for (int v : adj.get(u)) {
            int matchedLeft = pairV[v];
            if (matchedLeft == -1 || (dist[matchedLeft] == dist[u] + 1 && dfs(matchedLeft))) {
                pairU[u] = v;
                pairV[v] = u;
                return true;
            }
        }
        dist[u] = -1;
        return false;
    }

    public int[] getLeftMatches() {
        return pairU.clone();
    }

    public int[] getRightMatches() {
        return pairV.clone();
    }
}

