package com.thealgorithms.datastructures.graphs;

import java.util.Comparator;
import java.util.HashSet;
import java.util.PriorityQueue;

/**
 * The Kruskal class implements Kruskal's Algorithm to find the Minimum Spanning Tree (MST)
 * of a connected, undirected graph. The algorithm constructs the MST by selecting edges
 * with the least weight, ensuring no cycles are formed, and using union-find to track the
 * connected components.
 *
 * <p><strong>Key Features:</strong></p>
 * <ul>
 *   <li>The graph is represented using an adjacency list, where each node points to a set of edges.</li>
 *   <li>Each edge is processed in ascending order of weight using a priority queue.</li>
 *   <li>The algorithm stops when all nodes are connected or no more edges are available.</li>
 * </ul>
 *
 * <p><strong>Time Complexity:</strong> O(E log V), where E is the number of edges and V is the number of vertices.</p>
 */
@SuppressWarnings({"rawtypes", "unchecked"})
public class Kruskal {

    /**
     * Represents an edge in the graph with a source, destination, and weight.
     */
    static class Edge {

        int from;
        int to;
        int weight;

        Edge(int from, int to, int weight) {
            this.from = from;
            this.to = to;
            this.weight = weight;
        }
    }

    /**
     * Adds an edge to the graph.
     *
     * @param graph the adjacency list representing the graph
     * @param from the source vertex of the edge
     * @param to the destination vertex of the edge
     * @param weight the weight of the edge
     */
    static void addEdge(HashSet<Edge>[] graph, int from, int to, int weight) {
        graph[from].add(new Edge(from, to, weight));
    }

    /**
     * Kruskal's algorithm to find the Minimum Spanning Tree (MST) of a graph.
     *
     * @param graph the adjacency list representing the input graph
     * @return the adjacency list representing the MST
     */
    public HashSet<Edge>[] kruskal(HashSet<Edge>[] graph) {
        int nodes = graph.length;
        int[] captain = new int[nodes]; // Stores the "leader" of each node's connected component
        HashSet<Integer>[] connectedGroups = new HashSet[nodes];
        HashSet<Edge>[] minGraph = new HashSet[nodes];
        PriorityQueue<Edge> edges = new PriorityQueue<>(Comparator.comparingInt(edge -> edge.weight));
        for (int i = 0; i < nodes; i++) {
            minGraph[i] = new HashSet<>();
            connectedGroups[i] = new HashSet<>();
            connectedGroups[i].add(i);
            captain[i] = i;
            edges.addAll(graph[i]);
        }
        int connectedElements = 0;
        while (connectedElements != nodes && !edges.isEmpty()) {
            Edge edge = edges.poll();

            // Avoid forming cycles by checking if the nodes belong to different connected components
            if (!connectedGroups[captain[edge.from]].contains(edge.to) && !connectedGroups[captain[edge.to]].contains(edge.from)) {
                // Merge the two sets of nodes connected by the edge
                connectedGroups[captain[edge.from]].addAll(connectedGroups[captain[edge.to]]);

                // Update the captain for each merged node
                connectedGroups[captain[edge.from]].forEach(i -> captain[i] = captain[edge.from]);

                // Add the edge to the resulting MST graph
                addEdge(minGraph, edge.from, edge.to, edge.weight);

                // Update the count of connected nodes
                connectedElements = connectedGroups[captain[edge.from]].size();
            }
        }
        return minGraph;
    }
}

package com.thealgorithms.conversions;

/**
 * Utility class for converting hexadecimal numbers to binary representation.
 * <p>
 * A hexadecimal number consists of digits from {@code [0-9]} and {@code [A-F]} (case-insensitive),
 * while binary representation uses only {@code [0, 1]}.
 * <p>
 * This class provides methods to:
 * <ul>
 *   <li>Convert a hexadecimal string to its binary string equivalent.</li>
 *   <li>Ensure the binary output is padded to 8 bits (1 byte).</li>
 * </ul>
 * <p>
 * Example:
 * <ul>
 *   <li>{@code "A1"} → {@code "10100001"}</li>
 *   <li>{@code "1"} → {@code "00000001"}</li>
 * </ul>
 *
 * <p>This class assumes that the input hexadecimal string is valid.</p>
 */
public class HexaDecimalToBinary {

/**
 * Converts a hexadecimal string to its binary string equivalent.
 * The binary output is padded to a minimum of 8 bits (1 byte).
 * Steps:
 * <ol>
 *     <li>Convert the hexadecimal string to an integer.</li>
 *     <li>Convert the integer to a binary string.</li>
 *     <li>Pad the binary string to ensure it is at least 8 bits long.</li>
 *     <li>Return the padded binary string.</li>
 * </ol>
 *
 * @param hexInput the hexadecimal string (e.g., "A1", "7F")
 * @throws NumberFormatException if the input string is not a valid hexadecimal number
 * @return the binary string representation, padded to 8 bits (e.g., "10100001")
 */
public String convert(String hexInput) {
int decimalValue = Integer.parseInt(hexInput, 16);
String binaryValue = Integer.toBinaryString(decimalValue);
return padBinaryString(binaryValue);
}

/**
 * Pads the binary string to ensure it is at least 8 bits long.
 * If the binary string is shorter than 8 bits, it adds leading zeros.
 *
 * @param binarySegment the binary string to pad
 * @return the padded binary string with a minimum length of 8
 */
public String padBinaryString(String binarySegment) {
final int MIN_BITS = 8;
StringBuilder paddedResult = new StringBuilder(binarySegment);
while (paddedResult.length() < MIN_BITS) {
paddedResult.insert(0, "0");
}
return paddedResult.toString();
}
}

/*
 * Fills an array with random integers, then reports the total,
 * mean, median and mode of the generated values.
 */
public class DiziyiRastgeleDoldur {

    private static final int BOYUT = 20;
    private static final int UST_SINIR = 20;

    public static void main(String[] args) {
        Random uretici = new Random();
        int[] veriler = new int[BOYUT];

        System.out.print("Rastgele Dizi Elemanlari: ");
        for (int i = 0; i < BOYUT; i++) {
            veriler[i] = uretici.nextInt(UST_SINIR);
            System.out.print(veriler[i] + " ");
        }

        System.out.println("\nDizinin Toplami: " + toplamHesapla(veriler));
        System.out.println("Dizinin Ortalamasi: " + ortalamaHesapla(veriler));
        System.out.println("Dizinin Ortancasi: " + medyanHesapla(veriler));
        System.out.println("Dizinin Modu: " + modHesapla(veriler));
    }

    public static int toplamHesapla(int[] veriler) {
        int toplam = 0;
        for (int deger : veriler) {
            toplam += deger;
        }
        return toplam;
    }

    public static double ortalamaHesapla(int[] veriler) {
        return (double) toplamHesapla(veriler) / veriler.length;
    }

    public static double medyanHesapla(int[] veriler) {
        Arrays.sort(veriler);
        System.out.println("Sirali Dizi Elemanlari: " + Arrays.toString(veriler));

        int orta = veriler.length / 2;
        if (veriler.length % 2 == 0) {
            return (veriler[orta - 1] + veriler[orta]) / 2.0;
        }
        return veriler[orta];
    }

    public static int modHesapla(int[] veriler) {
        Arrays.sort(veriler);

        int enSikGorulen = veriler[0];
        int enYuksekTekrar = 1;
        int suankiTekrar = 1;

        for (int i = 1; i < veriler.length; i++) {
            if (veriler[i] == veriler[i - 1]) {
                suankiTekrar++;
            } else {
                suankiTekrar = 1;
            }

            if (suankiTekrar > enYuksekTekrar) {
                enYuksekTekrar = suankiTekrar;
                enSikGorulen = veriler[i];
            }
        }

        return enSikGorulen;
    }
}

/*
 * Models a 24-hour digital clock that can tick forward second by
 * second, cascading into minutes and hours as needed.
 */
public class DijitalSaat {

	private int saatDegeri = 0;
	private int dakikaDegeri = 0;
	private int saniyeDegeri = 0;

	public int getSaniye() {
		return this.saniyeDegeri;
	}

	// Only accepts values within the valid 0-59 range.
	public void setSaniye(int saniyeDegeri) {
		if (saniyeDegeri >= 0 && saniyeDegeri < 60) {
			this.saniyeDegeri = saniyeDegeri;
		}
	}

	// Prints the current time as saat:dakika:saniye.
	public void goster() {
		System.out.println(saatDegeri + ":" + dakikaDegeri + ":" + saniyeDegeri);
	}

	// Rolls the hour over back to 0 after 23.
	private void saatiArttir() {
		saatDegeri = saatDegeri + 1;
		if (saatDegeri > 23) {
			saatDegeri = 0;
		}
	}

	// Rolls the minute over after 59, cascading into the hour.
	private void dakikayiArttir() {
		dakikaDegeri = dakikaDegeri + 1;
		if (dakikaDegeri > 59) {
			dakikaDegeri = 0;
			saatiArttir();
		}
	}

	// Advances one second, cascading into minute/hour as needed.
	public void saniyeyiArttir() {
		saniyeDegeri = saniyeDegeri + 1;
		if (saniyeDegeri > 59) {
			saniyeDegeri = 0;
			dakikayiArttir();
		}
	}

	// Directly overwrites the clock with a new time.
	public void saatiGuncelle(int saatDegeri, int dakikaDegeri, int saniyeDegeri) {
		this.saatDegeri = saatDegeri;
		this.dakikaDegeri = dakikaDegeri;
		this.saniyeDegeri = saniyeDegeri;
	}

	public static void main(String[] args) {
		DijitalSaat saatNesnesi = new DijitalSaat();

		saatNesnesi.saatiGuncelle(10, 58, 50);
		System.out.println("Baslangic saati:");
		saatNesnesi.goster();

		for (int adim = 0; adim < 70; adim++) {
			saatNesnesi.saniyeyiArttir();
			System.out.print("Saniye " + (adim + 1) + ": ");
			saatNesnesi.goster();
		}

		System.out.println("\nSaati bir saat ileri aliyoruz...");
		for (int adim = 0; adim < 120; adim++) {
			saatNesnesi.saniyeyiArttir();
		}
		System.out.print("Yeni saat: ");
		saatNesnesi.goster();
	}
}

public class CapitalizeClient {

	public static void main(String[] args) throws Exception {

		// Sunucuya baglanmak icin soket olusturuluyor
		try (var socket = new Socket("localhost", 59898)) {

			// Kullaniciya metin girmesi icin bilgi verilir
			System.out.println("Metin satirlarini girin, cikis yapmak icin Ctrl+D veya Ctrl+C kullanin");

			// Kullanicidan input almak icin Scanner nesnesi olusturuluyor
			try (var scanner = new Scanner(System.in)) {

				// Sunucudan gelen veriyi okumak icin Scanner nesnesi olusturuluyor
				var in = new Scanner(socket.getInputStream());

				// Sunucuya veri gonderebilmek icin PrintWriter nesnesi olusturuluyor
				var out = new PrintWriter(socket.getOutputStream(), true);

				// Kullanicidan metin alindikca, bu metin sunucuya gonderiliyor ve cevabi yazdiriliyor
				while (scanner.hasNextLine()) {
					out.println(scanner.nextLine()); // Kullanicinin girdigi metin sunucuya gonderilir

					// Sunucudan gelen cevabi alir ve ekrana yazdirir
					System.out.println(in.nextLine());
				}
			}
		}
	}
}

public class AnagramChecker {
    /**
     * Determines if two strings are anagrams of each other.
     */
    public static boolean areAnagrams(String first, String second) {
        String a = first.toLowerCase().replaceAll("\\s", "");
        String b = second.toLowerCase().replaceAll("\\s", "");

        if (a.length() != b.length()) {
            return false;
        }

        int[] counts = new int[26];
        for (int i = 0; i < a.length(); i++) {
            counts[a.charAt(i) - 'a']++;
            counts[b.charAt(i) - 'a']--;
        }

        for (int count : counts) {
            if (count != 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(areAnagrams("listen", "silent"));
        System.out.println(areAnagrams("hello", "world"));
    }
}

