public class BubbleSortExample {
    /**
     * Sorts the given array in ascending order using bubble sort.
     * Time complexity: O(n^2), space complexity: O(1).
     */
    public static void bubbleSort(int[] arr) {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            // After each pass, the largest element bubbles to the end
            for (int j = 0; j < n - i - 1; j++) {
                if (arr[j] > arr[j + 1]) {
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }
    }

    public static void main(String[] args) {
        int[] numbers = {64, 34, 25, 12, 22, 11, 90};
        bubbleSort(numbers);
        for (int num : numbers) {
            System.out.print(num + " ");
        }
    }
}

package com.thealgorithms.datastructures.caches;

import java.util.HashMap;
import java.util.Map;

/**
 * Represents a Most Recently Used (MRU) Cache.
 * <p>
 * In contrast to the Least Recently Used (LRU) strategy, the MRU caching policy
 * evicts the most recently accessed items first. This class provides methods to
 * store key-value pairs and manage cache eviction based on this policy.
 *
 * For more information, refer to:
 * <a href="https://en.wikipedia.org/wiki/Cache_replacement_policies#Most_recently_used_(MRU)">MRU on Wikipedia</a>.
 *
 * @param <KeyType> the type of keys maintained by this cache
 * @param <ValueType> the type of values associated with the keys
 */
public class MRUCache<KeyType, ValueType> {

private final Map<KeyType, CacheEntry<KeyType, ValueType>> storageMap = new HashMap<>();
private CacheEntry<KeyType, ValueType> headNode;
private CacheEntry<KeyType, ValueType> tailNode;
private int maxCapacity;
private static final int DEFAULT_CAPACITY = 100;

/**
 * Creates an MRUCache with the default capacity.
 */
public MRUCache() {
setMaxCapacity(DEFAULT_CAPACITY);
}

/**
 * Creates an MRUCache with a specified capacity.
 *
 * @param capacityValue the maximum number of items the cache can hold
 */
public MRUCache(int capacityValue) {
setMaxCapacity(capacityValue);
}

/**
 * Sets the capacity of the cache and evicts items if the new capacity
 * is less than the current number of items.
 *
 * @param newCapacity the new capacity to set
 */
private void setMaxCapacity(int newCapacity) {
validateCapacity(newCapacity);
while (storageMap.size() > newCapacity) {
CacheEntry<KeyType, ValueType> removedEntry = evictMostRecent();
storageMap.remove(removedEntry.getStoredKey());
}
this.maxCapacity = newCapacity;
}

/**
 * Checks if the specified capacity is valid.
 *
 * @param capacityValue the capacity to check
 * @throws IllegalArgumentException if the capacity is less than or equal to zero
 */
private void validateCapacity(int capacityValue) {
if (capacityValue <= 0) {
throw new IllegalArgumentException("Capacity must be greater than 0!");
}
}

/**
 * Evicts the most recently used entry from the cache.
 *
 * @return the evicted entry
 * @throws RuntimeException if the cache is empty
 */
private CacheEntry<KeyType, ValueType> evictMostRecent() {
if (headNode == null) {
throw new RuntimeException("Cache cannot be empty!");
}
final CacheEntry<KeyType, ValueType> removedEntry = this.tailNode;
tailNode = removedEntry.getPreviousEntry();
if (tailNode != null) {
tailNode.setNextEntry(null);
}
removedEntry.setNextEntry(null);
return removedEntry;
}

/**
 * Retrieves the value associated with the specified key.
 *
 * @param searchKey the key whose associated value is to be returned
 * @return the value associated with the specified key, or null if the key does not exist
 */
public ValueType get(KeyType searchKey) {
if (!storageMap.containsKey(searchKey)) {
return null;
}
final CacheEntry<KeyType, ValueType> targetEntry = storageMap.get(searchKey);
moveEntryToEnd(targetEntry);
return targetEntry.getStoredValue();
}

/**
 * Associates the specified value with the specified key in the cache.
 * If the key already exists, its value is updated and the entry is moved to the most recently used position.
 * If the cache is full, the most recently used entry is evicted before adding the new entry.
 *
 * @param insertKey   the key with which the specified value is to be associated
 * @param insertValue the value to be associated with the specified key
 */
public void put(KeyType insertKey, ValueType insertValue) {
if (storageMap.containsKey(insertKey)) {
final CacheEntry<KeyType, ValueType> existingEntry = storageMap.get(insertKey);
existingEntry.setStoredValue(insertValue);
moveEntryToEnd(existingEntry);
return;
}
CacheEntry<KeyType, ValueType> newEntry;
if (storageMap.size() == maxCapacity) {
newEntry = evictMostRecent();
storageMap.remove(newEntry.getStoredKey());
} else {
newEntry = new CacheEntry<>();
}
newEntry.setStoredKey(insertKey);
newEntry.setStoredValue(insertValue);
insertNewEntry(newEntry);
storageMap.put(insertKey, newEntry);
}

/**
 * Adds a new entry to the cache and updates the head and tail pointers accordingly.
 *
 * @param newEntry the new entry to be added
 */
private void insertNewEntry(CacheEntry<KeyType, ValueType> newEntry) {
if (storageMap.isEmpty()) {
headNode = newEntry;
tailNode = newEntry;
return;
}
tailNode.setNextEntry(newEntry);
newEntry.setPreviousEntry(tailNode);
newEntry.setNextEntry(null);
tailNode = newEntry;
}

/**
 * Moves the specified entry to the most recently used position in the cache.
 *
 * @param targetEntry the entry to be moved
 */
private void moveEntryToEnd(CacheEntry<KeyType, ValueType> targetEntry) {
if (tailNode == targetEntry) {
return;
}
final CacheEntry<KeyType, ValueType> previousItem = targetEntry.getPreviousEntry();
final CacheEntry<KeyType, ValueType> nextItem = targetEntry.getNextEntry();
if (previousItem != null) {
previousItem.setNextEntry(nextItem);
}
if (nextItem != null) {
nextItem.setPreviousEntry(previousItem);
}
if (headNode == targetEntry) {
headNode = nextItem;
}
tailNode.setNextEntry(targetEntry);
targetEntry.setPreviousEntry(tailNode);
targetEntry.setNextEntry(null);
tailNode = targetEntry;
}

/**
 * A nested class representing an entry in the cache, which holds a key-value pair
 * and references to the previous and next entries in the linked list structure.
 *
 * @param <KeyType> the type of the key
 * @param <ValueType> the type of the value
 */
static final class CacheEntry<KeyType, ValueType> {
private CacheEntry<KeyType, ValueType> previousEntry;
private CacheEntry<KeyType, ValueType> nextEntry;
private KeyType storedKey;
private ValueType storedValue;

CacheEntry() {
}

CacheEntry(CacheEntry<KeyType, ValueType> previousEntry, CacheEntry<KeyType, ValueType> nextEntry, KeyType storedKey, ValueType storedValue) {
this.previousEntry = previousEntry;
this.nextEntry = nextEntry;
this.storedKey = storedKey;
this.storedValue = storedValue;
}

public CacheEntry<KeyType, ValueType> getPreviousEntry() {
return previousEntry;
}

public void setPreviousEntry(CacheEntry<KeyType, ValueType> previousEntry) {
this.previousEntry = previousEntry;
}

public CacheEntry<KeyType, ValueType> getNextEntry() {
return nextEntry;
}

public void setNextEntry(CacheEntry<KeyType, ValueType> nextEntry) {
this.nextEntry = nextEntry;
}

public KeyType getStoredKey() {
return storedKey;
}

public void setStoredKey(KeyType storedKey) {
this.storedKey = storedKey;
}

public ValueType getStoredValue() {
return storedValue;
}

public void setStoredValue(ValueType storedValue) {
this.storedValue = storedValue;
}
}
}

/**
 * The MatrixChainRecursiveTopDownMemoisation class implements the matrix-chain
 * multiplication problem using a top-down recursive approach with memoization.
 *
 * <p>Given a chain of matrices A1, A2, ..., An, where matrix Ai has dimensions
 * pi-1 × pi, this algorithm finds the optimal way to fully parenthesize the
 * product A1A2...An in a way that minimizes the total number of scalar
 * multiplications required.</p>
 *
 * <p>This implementation uses a memoization technique to store the results of
 * subproblems, which significantly reduces the number of recursive calls and
 * improves performance compared to a naive recursive approach.</p>
 */
public final class MatrixChainRecursiveTopDownMemoisation {
    private MatrixChainRecursiveTopDownMemoisation() {
    }

    /**
     * Calculates the minimum number of scalar multiplications needed to multiply
     * a chain of matrices.
     *
     * @param p an array of integers representing the dimensions of the matrices.
     *          The length of the array is n + 1, where n is the number of matrices.
     * @return the minimum number of multiplications required to multiply the chain
     *         of matrices.
     */
    static int memoizedMatrixChain(int[] p) {
        int n = p.length;
        int[][] m = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                m[i][j] = Integer.MAX_VALUE;
            }
        }
        return lookupChain(m, p, 1, n - 1);
    }

    /**
     * A recursive helper method to lookup the minimum number of multiplications
     * for multiplying matrices from index i to index j.
     *
     * @param m the memoization table storing the results of subproblems.
     * @param p an array of integers representing the dimensions of the matrices.
     * @param i the starting index of the matrix chain.
     * @param j the ending index of the matrix chain.
     * @return the minimum number of multiplications needed to multiply matrices
     *         from i to j.
     */
    static int lookupChain(int[][] m, int[] p, int i, int j) {
        if (i == j) {
            m[i][j] = 0;
            return m[i][j];
        }
        if (m[i][j] < Integer.MAX_VALUE) {
            return m[i][j];
        } else {
            for (int k = i; k < j; k++) {
                int q = lookupChain(m, p, i, k) + lookupChain(m, p, k + 1, j) + (p[i - 1] * p[k] * p[j]);
                if (q < m[i][j]) {
                    m[i][j] = q;
                }
            }
        }
        return m[i][j];
    }
}

/**
 * ORSet (Observed-Removed Set) is a state-based CRDT (Conflict-free Replicated Data Type)
 * that supports both addition and removal of elements. This particular implementation follows
 * the Add-Wins strategy, meaning that in case of conflicting add and remove operations,
 * the add operation takes precedence. The merge operation of two OR-Sets ensures that
 * elements added at any replica are eventually observed at all replicas. Removed elements,
 * once observed, are never reintroduced.
 * This OR-Set implementation provides methods for adding elements, removing elements,
 * checking for element existence, retrieving the set of elements, comparing with other OR-Sets,
 * and merging with another OR-Set to create a new OR-Set containing all unique elements
 * from both sets.
 *
 * @author itakurah (Niklas Hoefflin) (https://github.com/itakurah)
 * @see <a href="https://en.wikipedia.org/wiki/Conflict-free_replicated_data_type">Conflict-free_replicated_data_type</a>
 * @see <a href="https://github.com/itakurah">itakurah (Niklas Hoefflin)</a>
 */

public class ORSet<ElementType> {

private final Set<VersionedPair<ElementType>> activeElements;
private final Set<VersionedPair<ElementType>> removedMarkers;

/**
 * Constructs an empty OR-Set.
 */
public ORSet() {
this.activeElements = new HashSet<>();
this.removedMarkers = new HashSet<>();
}

/**
 * Checks if the set contains the specified element.
 *
 * @param targetElement the element to check for
 * @return true if the set contains the element, false otherwise
 */
public boolean contains(ElementType targetElement) {
return activeElements.stream().anyMatch(pair -> pair.getElementValue().equals(targetElement));
}

/**
 * Retrieves the elements in the set.
 *
 * @return a set containing the elements
 */
public Set<ElementType> getCurrentElements() {
Set<ElementType> resultSet = new HashSet<>();
activeElements.forEach(pair -> resultSet.add(pair.getElementValue()));
return resultSet;
}

/**
 * Adds the specified element to the set.
 *
 * @param elementToAdd the element to add
 */
public void add(ElementType elementToAdd) {
String uniqueToken = generateUniqueToken();
applyAddOperation(elementToAdd, uniqueToken);
}

/**
 * Removes the specified element from the set.
 *
 * @param elementToRemove the element to remove
 */
public void remove(ElementType elementToRemove) {
Set<VersionedPair<ElementType>> pairsToRemove = findPairsForElement(elementToRemove);
applyRemoveOperation(pairsToRemove);
}

/**
 * Collect all pairs with the specified element.
 *
 * @param targetElement the element to collect pairs for
 * @return a set of pairs with the specified element to be removed
 */
private Set<VersionedPair<ElementType>> findPairsForElement(ElementType targetElement) {
Set<VersionedPair<ElementType>> matchingPairs = new HashSet<>();
for (VersionedPair<ElementType> currentPair : activeElements) {
if (currentPair.getElementValue().equals(targetElement)) {
matchingPairs.add(currentPair);
}
}
return matchingPairs;
}

/**
 * Generates a unique tag for the element.
 *
 * @return the unique tag
 */
private String generateUniqueToken() {
return UUID.randomUUID().toString();
}

/**
 * Adds the element with the specified unique tag to the set.
 *
 * @param elementValue the element to add
 * @param uniqueToken       the unique tag associated with the element
 */
private void applyAddOperation(ElementType elementValue, String uniqueToken) {
VersionedPair<ElementType> newPair = new VersionedPair<>(elementValue, uniqueToken);
activeElements.add(newPair);
activeElements.removeAll(removedMarkers);
}

/**
 * Removes the specified pairs from the set.
 *
 * @param pairsToRemove the pairs to remove
 */
private void applyRemoveOperation(Set<VersionedPair<ElementType>> pairsToRemove) {
activeElements.removeAll(pairsToRemove);
removedMarkers.addAll(pairsToRemove);
}

/**
 * Compares this Add-Wins OR-Set with another OR-Set to check if elements and tombstones are a subset.
 *
 * @param otherSet the other OR-Set to compare
 * @return true if the sets are subset, false otherwise
 */
public boolean isSubsetOf(ORSet<ElementType> otherSet) {
Set<VersionedPair<ElementType>> combinedSelf = new HashSet<>(activeElements);
combinedSelf.addAll(removedMarkers);
Set<VersionedPair<ElementType>> combinedOther = new HashSet<>(otherSet.activeElements);
combinedOther.addAll(otherSet.removedMarkers);
return combinedOther.containsAll(combinedSelf) && otherSet.removedMarkers.containsAll(removedMarkers);
}

/**
 * Merges this Add-Wins OR-Set with another OR-Set.
 *
 * @param otherSet the other OR-Set to merge
 */
public void mergeWith(ORSet<ElementType> otherSet) {
activeElements.removeAll(otherSet.removedMarkers);
otherSet.activeElements.removeAll(removedMarkers);
activeElements.addAll(otherSet.activeElements);
removedMarkers.addAll(otherSet.removedMarkers);
}

/**
 * Represents a pair containing an element and a unique tag.
 *
 * @param <ElementType> the type of the element in the pair
 */
public static class VersionedPair<ElementType> {
private final ElementType elementValue;
private final String uniqueIdentifier;

/**
 * Constructs a pair with the specified element and unique tag.
 *
 * @param elementValue   the element in the pair
 * @param uniqueIdentifier the unique tag associated with the element
 */
public VersionedPair(ElementType elementValue, String uniqueIdentifier) {
this.elementValue = elementValue;
this.uniqueIdentifier = uniqueIdentifier;
}

/**
 * Gets the element from the pair.
 *
 * @return the element
 */
public ElementType getElementValue() {
return elementValue;
}
}
}

/**
 * Problem Statement Ceil value for any number x in a collection is a number y
 * which is either equal to x or the least greater number than x.
 *
 * Problem: Given a binary search tree containing positive integer values. Find
 * ceil value for a given key in O(lg(n)) time. In case if it is not present
 * return -1.
 *
 * Ex.1. [30,20,40,10,25,35,50] represents level order traversal of a binary
 * search tree. Find ceil for 10. Answer: 20
 *
 * Ex.2. [30,20,40,10,25,35,50] represents level order traversal of a binary
 * search tree. Find ceil for 22 Answer: 25
 *
 * Ex.2. [30,20,40,10,25,35,50] represents level order traversal of a binary
 * search tree. Find ceil for 52 Answer: -1
 *
 * Solution 1: Brute Force Solution: Do an inorder traversal and save result
 * into an array. Iterate over the array to get an element equal to or greater
 * than current key. Time Complexity: O(n) Space Complexity: O(n) for auxiliary
 * array to save inorder representation of tree.
 * <p>
 * <p>
 * Solution 2: Brute Force Solution: Do an inorder traversal and save result
 * into an array.Since array is sorted do a binary search over the array to get
 * an element equal to or greater than current key. Time Complexity: O(n) for
 * traversal of tree and O(lg(n)) for binary search in array. Total = O(n) Space
 * Complexity: O(n) for auxiliary array to save inorder representation of tree.
 * <p>
 * <p>
 * Solution 3: Optimal We can do a DFS search on given tree in following
 * fashion. i) if root is null then return null because then ceil doesn't exist
 * ii) If key is lesser than root value than ceil will be in right subtree so
 * call recursively on right subtree iii) if key is greater than current root,
 * then either a) the root is ceil b) ceil is in left subtree: call for left
 * subtree. If left subtree returns a non-null value then that will be ceil
 * otherwise the root is ceil
 */
public final class CeilInBinarySearchTree {
    private CeilInBinarySearchTree() {
    }

    public static Node getCeil(Node root, int key) {
        if (root == null) {
            return null;
        }

        // if root value is same as key than root is the ceiling
        if (root.data == key) {
            return root;
        }

        // if root value is lesser than key then ceil must be in right subtree
        if (root.data < key) {
            return getCeil(root.right, key);
        }

        // if root value is greater than key then ceil can be in left subtree or if
        // it is not in left subtree then current node will be ceil
        Node result = getCeil(root.left, key);

        // if result is null it means that there is no ceil in children subtrees
        // and the root is the ceil otherwise the returned node is the ceil.
        return result == null ? root : result;
    }
}

/**
 * @author moksedursohan
 * @since 10/4/24
 */
public class Point {

    public double x;
    public double y;

    public Point() {
    }

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Point point)) {
            return false;
        }

        return Double.compare(x, point.x) == 0 && Double.compare(y, point.y) == 0;
    }

    @Override
    public int hashCode() {
        return Objects.hash(x, y);
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * Given a string containing just the characters '(' and ')', find the length of
 * the longest valid (well-formed) parentheses substring.
 *
 * @author Libin Yang (https://github.com/yanglbme)
 * @since 2018/10/5
 */
public final class LongestValidParentheses {
    private LongestValidParentheses() {
    }

    public static int getLongestValidParentheses(String s) {
        if (s == null || s.length() < 2) {
            return 0;
        }
        char[] chars = s.toCharArray();
        int n = chars.length;
        int[] res = new int[n];
        res[0] = 0;
        res[1] = chars[1] == ')' && chars[0] == '(' ? 2 : 0;

        int max = res[1];

        for (int i = 2; i < n; ++i) {
            if (chars[i] == ')') {
                if (chars[i - 1] == '(') {
                    res[i] = res[i - 2] + 2;
                } else {
                    int index = i - res[i - 1] - 1;
                    if (index >= 0 && chars[index] == '(') {
                        // ()(())
                        res[i] = res[i - 1] + 2 + (index - 1 >= 0 ? res[index - 1] : 0);
                    }
                }
            }
            max = Math.max(max, res[i]);
        }

        return max;
    }
}

