/**
 * A utility class to perform affine transformations of the form:
 * transformedValue = slopeValue * originalValue + interceptValue.
 *
 * This class supports inversion and composition of affine transformations.
 * It is immutable, meaning each instance represents a fixed transformation.
 */
public final class AffineConverter {
private final double slopeValue;
private final double interceptValue;

/**
 * Constructs an AffineConverter with the given slope and intercept.
 *
 * @param inputSlope The slope of the affine transformation.
 * @param inputIntercept The intercept (constant term) of the affine transformation.
 * @throws IllegalArgumentException if either parameter is NaN.
 */
public AffineConverter(final double inputSlope, final double inputIntercept) {
if (Double.isNaN(inputSlope) || Double.isNaN(inputIntercept)) {
throw new IllegalArgumentException("Slope and intercept must be valid numbers.");
}
slopeValue = inputSlope;
interceptValue = inputIntercept;
}

/**
 * Converts the given input value using the affine transformation:
 * result = slopeValue * inputValue + interceptValue.
 *
 * @param inputValue The input value to convert.
 * @return The transformed value.
 */
public double convert(final double inputValue) {
return slopeValue * inputValue + interceptValue;
}

/**
 * Returns a new AffineConverter representing the inverse of the current transformation.
 * The inverse of transformedValue = slopeValue * originalValue + interceptValue
 * is originalValue = (transformedValue - interceptValue) / slopeValue.
 *
 * @return A new AffineConverter representing the inverse transformation.
 * @throws AssertionError if the slope is zero, as the inverse would be undefined.
 */
public AffineConverter invert() {
assert slopeValue != 0.0 : "Slope cannot be zero for inversion.";
return new AffineConverter(1.0 / slopeValue, -interceptValue / slopeValue);
}

/**
 * Composes this affine transformation with another, returning a new AffineConverter.
 * If this transformation is f(x) and the other is g(x), the result is f(g(x)).
 *
 * @param otherTransform Another AffineConverter to compose with.
 * @return A new AffineConverter representing the composition of the two transformations.
 */
public AffineConverter compose(final AffineConverter otherTransform) {
double combinedSlope = slopeValue * otherTransform.slopeValue;
double combinedIntercept = slopeValue * otherTransform.interceptValue + interceptValue;
return new AffineConverter(combinedSlope, combinedIntercept);
}
}

