/**
 * This class implements a GenericArrayListQueue, a queue data structure that
 * holds elements of any type specified at runtime, allowing flexibility in the type
 * of elements it stores.
 *
 * <p>The GenericArrayListQueue operates on a First-In-First-Out (FIFO) basis, where
 * elements added first are the first to be removed. New elements are added to the back
 * (or rear) of the queue, while removal of elements occurs from the front.
 *
 * @param <T> The type of elements held in this queue.
 */
public class GenericArrayListQueue<T> {

    /**
     * A list that stores the queue's elements in insertion order.
     */
    private final List<T> elementList = new ArrayList<>();

    /**
     * Checks if the queue is empty.
     *
     * @return {@code true} if the queue has no elements; {@code false} otherwise.
     */
    public boolean isEmpty() {
        return elementList.isEmpty();
    }

    /**
     * Retrieves, but does not remove, the element at the front of the queue.
     *
     * @return The element at the front of the queue, or {@code null} if the queue is empty.
     */
    public T peek() {
        return isEmpty() ? null : elementList.getFirst();
    }

    /**
     * Inserts an element at the back of the queue.
     *
     * @param element The element to be added to the queue.
     * @return {@code true} if the element was successfully added.
     */
    public boolean add(T element) {
        return elementList.add(element);
    }

    /**
     * Retrieves and removes the element at the front of the queue.
     *
     * @return The element removed from the front of the queue, or {@code null} if the queue is empty.
     */
    public T poll() {
        return isEmpty() ? null : elementList.removeFirst();
    }
}

package com.thealgorithms.maths;

/**
 * The Bell numbers count the number of partitions of a set.
 * The n-th Bell number is the number of ways a set of n elements can be partitioned
 * into nonempty subsets.
 *
 * <p>
 * This implementation uses the Bell Triangle (Aitken's array) method.
 * Time Complexity: O(n^2)
 * Space Complexity: O(n^2)
 * </p>
 *
 * @author Chahat Sandhu, <a href="https://github.com/singhc7">singhc7</a>
 * @see <a href="https://en.wikipedia.org/wiki/Bell_number">Bell Number (Wikipedia)</a>
 */
public final class BellNumbers {

    private BellNumbers() {
    }

    /**
     * Calculates the n-th Bell number using the Bell Triangle.
     *
     * @param n the index of the Bell number (must be non-negative)
     * @return the n-th Bell number
     * @throws IllegalArgumentException if n is negative or n > 25
     */
    public static long compute(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        if (n == 0) {
            return 1;
        }
        if (n > 25) {
            throw new IllegalArgumentException("n must be <= 25. For larger n, use BigInteger implementation.");
        }

        // We use a 2D array to visualize the Bell Triangle
        long[][] bellTriangle = new long[n + 1][n + 1];

        // Base case: The triangle starts with 1
        bellTriangle[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            // Rule 1: The first number in a new row is the LAST number of the previous row
            bellTriangle[i][0] = bellTriangle[i - 1][i - 1];

            // Rule 2: Fill the rest of the row by adding the previous neighbor and the upper-left neighbor
            for (int j = 1; j <= i; j++) {
                bellTriangle[i][j] = bellTriangle[i][j - 1] + bellTriangle[i - 1][j - 1];
            }
        }

        // The Bell number B_n is the first number in the n-th row
        return bellTriangle[n][0];
    }
}

package eamples;
import java.util.Scanner; // Kullanicidan veri girisi almak icin Scanner sinifini ice aktarir.

public class Fibonacci { // Ana sinif

    public static void main(String[] args) {

        // Kullanicidan bir sayi girisi almak icin Scanner nesnesi olusturur.
        Scanner scanner = new Scanner(System.in);

        // Kullanicidan bir sayi girmesini ister, bu sayi Fibonacci dizisinin kacinci elemanini hesaplayacagini belirtir.
        System.out.println("Bir sayi giriniz:");
        int sayi = scanner.nextInt(); // Kullanicinin girdigi sayiyi okur ve 'sayi' degiskenine atar.

        // Fibonacci dizisinin ilk iki elemanini baslatir. Fibonacci dizisi 1, 1, 2, 3, 5... sekilinde ilerler.
        int sayi1 = 1; // Ilk Fibonacci sayisi
        int sayi2 = 1; // Ikinci Fibonacci sayisi

        // Ilk iki Fibonacci sayisini ekrana yazdirir.
        System.out.print(sayi1 + " ");
        System.out.print(sayi2 + " ");

        // Sonraki Fibonacci sayisini hesaplamak icin 'sonuc' degiskeni olusturulur.
        int sonuc = 0;

        // Dongu, Fibonacci dizisinin ilk iki elemani zaten yazdirildigindan, 2. indisten baslar ve
        // kullanicinin belirttigi 'sayi' degerine kadar devam eder.
        for(int i = 2; i < sayi; i++) {

            // 'sonuc', bir onceki iki Fibonacci sayisinin toplami olarak hesaplanir.
            sonuc = sayi1 + sayi2;

            // 'sayi1' bir sonraki adim icin 'sayi2' olur.
            sayi1 = sayi2;

            // 'sayi2' ise yeni hesaplanan Fibonacci sayisi olan 'sonuc' olur.
            sayi2 = sonuc;

            // Hesaplanan Fibonacci sayisini ekrana yazdirir.
            System.out.print(sonuc + " ");

            // Altin oran, ardisik iki Fibonacci sayisi arasindaki oran olarak hesaplanir ve ekrana yazdirilir.
            // Oran hesaplamasi sayi2/sayi1 seklindedir ve sonuclar double olarak yazdirilir.
            System.out.println("\tAltin oran = " + (double)((double)sayi2 / sayi1));
        }

        // Scanner nesnesini kapatir. Kaynak yonetimi acisindan onemli bir adimdir.
        scanner.close();
    }
}

