package com.thealgorithms.ciphers;

/**
 * The Atbash cipher is a classic substitution cipher that substitutes each letter
 * with its opposite letter in the alphabet.
 *
 * For example:
 * - 'A' becomes 'Z', 'B' becomes 'Y', 'C' becomes 'X', and so on.
 * - Similarly, 'a' becomes 'z', 'b' becomes 'y', and so on.
 *
 * The cipher works identically for both uppercase and lowercase letters.
 * Non-alphabetical characters remain unchanged in the output.
 *
 * This cipher is symmetric, meaning that applying the cipher twice will return
 * the original text. Therefore, the same function is used for both encryption and decryption.
 *
 * <p>Usage Example:</p>
 * <pre>
 * AtbashCipher cipher = new AtbashCipher("Hello World!");
 * String encrypted = cipher.convert(); // Output: "Svool Dliow!"
 * </pre>
 *
 * @author <a href="https://github.com/Krounosity">Krounosity</a>
 * @see <a href="https://en.wikipedia.org/wiki/Atbash">Atbash Cipher (Wikipedia)</a>
 */
public class AtbashCipher {

private String inputString;

public AtbashCipher() {
}

/**
 * Constructor with a string parameter.
 *
 * @param rawText The string to be converted using the Atbash cipher
 */
public AtbashCipher(String rawText) {
this.inputString = rawText;
}

/**
 * Returns the current string set for conversion.
 *
 * @return The string to be converted
 */
public String getString() {
return inputString;
}

/**
 * Sets the string to be converted using the Atbash cipher.
 *
 * @param rawText The new string to convert
 */
public void setString(String rawText) {
this.inputString = rawText;
}

/**
 * Checks if a character is uppercase.
 *
 * @param symbol The character to check
 * @return {@code true} if the character is uppercase, {@code false} otherwise
 */
private boolean isCapital(char symbol) {
return symbol >= 'A' && symbol <= 'Z';
}

/**
 * Checks if a character is lowercase.
 *
 * @param symbol The character to check
 * @return {@code true} if the character is lowercase, {@code false} otherwise
 */
private boolean isSmall(char symbol) {
return symbol >= 'a' && symbol <= 'z';
}

/**
 * Converts the input string using the Atbash cipher.
 * Alphabetic characters are substituted with their opposite in the alphabet,
 * while non-alphabetic characters remain unchanged.
 *
 * @return The converted string after applying the Atbash cipher
 */
public String convert() {
StringBuilder convertedResult = new StringBuilder();
for (char currentSymbol : inputString.toCharArray()) {
if (isSmall(currentSymbol)) {
convertedResult.append((char) ('z' - (currentSymbol - 'a')));
} else if (isCapital(currentSymbol)) {
convertedResult.append((char) ('Z' - (currentSymbol - 'A')));
} else {
convertedResult.append(currentSymbol);
}
}
return convertedResult.toString();
}
}

package com.ankan.staticExample;

public class Human { // Class defining the blueprint for Human objects

    // Instance variables (each Human object has its own copy)
    int age;           // Age of the human (in years)
    String name;       // Name of the human
    int salary;        // Annual salary in local currency
    boolean isMarried; // Marital status (true = married, false = single/unmarried)

    // Static variable (shared across ALL instances of the Human class)
    // 'static' is used when a variable does NOT depend on any specific object
    // but is common to all objects of that class
    // When a member is declared static, it can be accessed before any objects
    // of the class are created, without referencing any particular object
    static long totalPopulationCount = 0; // Tracks the total number of Human objects created

    // Constructor - called when a new Human object is instantiated
    public Human(int personAge, String personName, int personSalary, boolean maritalStatus) {
        this.age = personAge;
        this.name = personName;
        this.salary = personSalary;
        this.isMarried = maritalStatus;

        // Increment the shared population counter
        // Using class name (Human) instead of 'this' because 'population' is static/common
        // 'this' refers to a particular object, but population belongs to the class itself
        Human.totalPopulationCount += 1;
    }

    // Static method to display total population (belongs to class, not instances)
    public static void displayTotalPopulation() {
        System.out.println("Total human population: " + totalPopulationCount);
        // Note: Cannot access instance variables (age, name, salary, isMarried) here
        // because static methods don't have access to 'this'
    }

    // Instance method to display individual human details
    public void displayIndividualDetails() {
        System.out.println("Name: " + name);
        System.out.println("Age: " + age);
        System.out.println("Salary: " + salary);
        System.out.println("Married: " + isMarried);
        // Can access static variable from instance method
        System.out.println("Total population (from instance): " + totalPopulationCount);
    }
}

public class A {
    // Nested interface - declared inside class A
    // Can be public, private, protected, or package-private
    // Useful for grouping related interfaces or when the interface is tightly coupled with the class
    public interface NumberParityChecker {
        boolean checkIfNumberIsOdd(int inputNumber);
    }
}

// Class B implements the nested interface using fully qualified name A.NestedInterface
class B implements A.NumberParityChecker {

    @Override
    public boolean checkIfNumberIsOdd(int inputNumber) {
        // Using bitwise AND operator for efficient odd/even detection
        // (num & 1) returns 1 for odd numbers, 0 for even numbers
        return (inputNumber & 1) == 1;
    }

    // Optional: Demonstration method
    public static void main(String[] args) {
        B parityChecker = new B();

        // Test the isOdd functionality
        System.out.println("--- Odd Number Checker Demonstration ---");
        System.out.println("Is 7 odd? " + parityChecker.checkIfNumberIsOdd(7));   // true
        System.out.println("Is 10 odd? " + parityChecker.checkIfNumberIsOdd(10)); // false
        System.out.println("Is -3 odd? " + parityChecker.checkIfNumberIsOdd(-3)); // true (negative odd)

        // Polymorphic reference using nested interface type
        A.NumberParityChecker interfaceReference = parityChecker;
        System.out.println("\nUsing interface reference - Is 5 odd? " + interfaceReference.checkIfNumberIsOdd(5));

        // Educational note:
        // Nested interfaces are implicitly static (even without the static keyword)
        // They can be accessed using the outer class name: A.NestedInterface
    }
}

import java.io.BufferedReader;
