package whileloop;

public class BasamakDegeri {

	public static void main(String[] args) {

		basamaklariYazdir();

		System.out.println("Basamak Sayisi: " + basamakSayisi(345987));

		System.out.println("Rakamlar Toplami: " + rakamlarToplami(24653));

	}

	// Basamaklari yazdirmak icin bir fonksiyon
	public static void basamaklariYazdir() {
		// Onlar ve birler basamagini gezmek icin donguler
		for (int onlar = 0; onlar <= 4; onlar++) {
			for (int birler = 1; birler <= 9; birler++) {
				// Onlar ve birler basamagini birlestirerek sayiyi olustur
				int sayi = onlar * 10 + birler;
				// Sayiyi ve basamaklari ekrana yazdir
				System.out.println("Onlar basamagi: " + onlar + ", Birler basamagi: " + birler + " --> " + sayi);
			}
		}
	}

	// Rakamlar toplamini bulan fonksiyon
	public static int rakamlarToplami(int sayi) {
		int toplam = 0;
		// Sayinin her rakamini toplamak icin while dongusu
		while (sayi > 0) {
			int kalan = sayi % 10;  // Sayinin son rakamini al
			toplam += kalan;  // Rakami toplam degiskenine ekle
			sayi /= 10;  // Sayiyi bir basamak kucult
		}
		// Hesaplanan toplami dondur
		return toplam;
	}

	// Basamak sayisini bulan fonksiyon
	public static int basamakSayisi(int sayi) {
		int basamak = 0;
		// Sayinin her basamagini saymak icin while dongusu
		while (sayi > 0) {
			basamak++;  // basamak degerini bir arttir
			sayi /= 10;  // Sayiyi bir basamak kucult
		}
		// Hesaplanan basamak sayisini dondur
		return basamak;
	}
}

package com.thealgorithms.divideandconquer;

// Java Program to Implement Binary Exponentiation (power in log n)

// Reference Link: https://en.wikipedia.org/wiki/Exponentiation_by_squaring

/*
 * Binary Exponentiation is a method to calculate a to the power of b.
 * It is used to calculate a^n in O(log n) time.
 *
 * Reference:
 * https://iq.opengenus.org/binary-exponentiation/
 */

public class BinaryExponentiation {

    // recursive function to calculate a to the power of b
    public static long calculatePower(long x, long y) {
        // Base Case
        if (y == 0) {
            return 1;
        }
        if (y % 2 == 1) { // odd power
            return x * calculatePower(x, y - 1);
        }
        return calculatePower(x * x, y / 2); // even power
    }

    // iterative function to calculate a to the power of b
    long power(long n, long m) {
        long power = n;
        long sum = 1;
        while (m > 0) {
            if ((m & 1) == 1) {
                sum *= power;
            }
            power = power * power;
            m = m >> 1;
        }
        return sum;
    }
}

package com.ankan.generics;

import java.util.ArrayList;
import java.util.Arrays;

public class CustomGenArrayList<T> {
// Here we created a custom ArrayList with a Generic <T>
    private Object[] data;
    private static int DEFAULT_SIZE = 10;
    private int size = 0; // also working as index value

    public CustomGenArrayList() {
        this.data = new Object[DEFAULT_SIZE];
    }

    public void add(T num) {
        if (isFull()) {
            resize();
        }
        data[size++] = num;
    }

    private void resize() {
        Object[] temp = new Object[data.length * 2];

        // copy the new items in the new array
        for (int i = 0; i < data.length; i++) {
            temp[i] = data[i];
        }
        data = temp;
    }

    private boolean isFull() {
        return size == data.length;
    }

    public T remove() {
        T removed = (T) data[--size];
        return removed;
    }

    public T get(int index) {
        return (T) data[index];
    }

    public int size() {
        return size;
    }

    public void set (int index, T value) {
        data[index] = value;
    }

    @Override
    public String toString() {
        return "CustomGenArrayList{" +
                "data=" + Arrays.toString(data) +
                ", size=" + size +
                '}';
    }

    public static void main(String[] args) {
//        ArrayList list = new ArrayList();
        CustomGenArrayList list = new CustomGenArrayList();
//        list.add(3);
//        list.add(5);
//        list.add(9);

//        for (int i = 0; i < 14; i++) {
//            list.add(2 * i);
//        }
//
//        System.out.println(list);

        ArrayList<String> list2 = new ArrayList<>();
//        list2.add("dfgg");
        // Generics help us in providing a parameterized type for stuff like <Integer> and all.

        CustomGenArrayList<Double> list3 = new CustomGenArrayList<>();
        for (double i = 0; i < 14; i++) {
         list3.add(2.5 * i);
        }
        System.out.println(list3);
        System.out.println(list3.get(5));
        System.out.println(list3.remove());
    }
}

package com.thealgorithms.lineclipping.utils;

import java.util.Objects;

/**
 * @author moksedursohan
 * @since 10/4/24
 */
public class Point {

    public double x;
    public double y;

    public Point() {
    }

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Point point)) {
            return false;
        }

        return Double.compare(x, point.x) == 0 && Double.compare(y, point.y) == 0;
    }

    @Override
    public int hashCode() {
        return Objects.hash(x, y);
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}

package com.thealgorithms.maths.Prime;

/*
 * Authors:
 * (1) Aitor Fidalgo Sánchez (https://github.com/aitorfi)
 * (2) Akshay Dubey (https://github.com/itsAkshayDubey)
 */

import java.util.ArrayList;
import java.util.List;

public final class PrimeFactorization {
    private PrimeFactorization() {
    }

    public static List<Integer> pfactors(int n) {
        List<Integer> primeFactors = new ArrayList<>();

        if (n == 0) {
            return primeFactors;
        }

        while (n % 2 == 0) {
            primeFactors.add(2);
            n /= 2;
        }

        for (int i = 3; i <= Math.sqrt(n); i += 2) {
            while (n % i == 0) {
                primeFactors.add(i);
                n /= i;
            }
        }

        if (n > 2) {
            primeFactors.add(n);
        }
        return primeFactors;
    }
}

/**
 * A mutable complex number with basic arithmetic operations.
 */
public class MyComplex {
    private double re;
    private double im;

    public MyComplex() {
    }

    public MyComplex(double re, double im) {
        this.re = re;
        this.im = im;
    }

    public double getReal() {
        return re;
    }

    public void setReal(double re) {
        this.re = re;
    }

    public double getImag() {
        return im;
    }

    public void setImag(double im) {
        this.im = im;
    }

    @Override
    public String toString() {
        return "(" + re + "+" + im + "i)";
    }

    public boolean isReal() {
        return re == 0;
    }

    public boolean isImaginary() {
        return im == 0;
    }

    public boolean equals(double re, double im) {
        return this.re == re && this.im == im;
    }

    public boolean equals(MyComplex other) {
        return this.re == other.re && this.im == other.im;
    }

    public double Magnitude() {
        return Math.sqrt(re * re + im * im);
    }

    public double argument() {
        return Math.atan2(im, re);
    }

    public MyComplex addInto(MyComplex right) {
        re += right.re;
        im += right.im;
        return this;
    }

    public MyComplex add(MyComplex right) {
        re += right.re;
        im += right.im;
        return this;
    }

    public MyComplex addNew(MyComplex right) {
        return new MyComplex(re + right.re, im + right.im);
    }

    public MyComplex subtract(MyComplex right) {
        re -= right.re;
        im -= right.im;
        return this;
    }

    public MyComplex subtractNew(MyComplex right) {
        return new MyComplex(re - right.re, im - right.im);
    }

    public MyComplex multiply(MyComplex right) {
        // Note: mirrors the original's order of updates, where the
        // imaginary part is computed from the already-updated real part.
        re = re * right.re - im * right.im;
        im = re * right.im + im * right.re;
        return this;
    }

    public MyComplex divide(MyComplex right) {
        double denom = Math.pow(right.re, 2) + Math.pow(right.im, 2);
        re = (re * right.re + im * right.im) / denom;
        im -= (im * right.re - re * right.im) / denom;
        return this;
    }

    public MyComplex conjugate() {
        im *= -1;
        return this;
    }
}

