// Kisi sinifi
public class Kisi {

    private String ad;
    private int yas;

    // Kisi yapilandirici metodu
    public Kisi(String ad, int yas) {
        this.ad = ad;
        this.yas = yas;
    }

    // Equals metodu ozellestirilmistir
    @Override
    public boolean equals(Object obj) {
        // Ayni referansa sahipse, esittir
        if (this == obj) return true;

        // Null kontrolu yapilir ve nesne turu karsilastirilir
        if (obj == null || getClass() != obj.getClass()) return false;

        // Kisi nesnelerinin alanlari karsilastirilir
        Kisi kisi = (Kisi) obj;
        return yas == kisi.yas && ad.equals(kisi.ad);
    }

    // Ad alani icin getter metodu
    public String getAd() {
        return ad;
    }

    // Yas alani icin getter metodu
    public int getYas() {
        return yas;
    }

    // toString metodu
    @Override
    public String toString() {
        return "Kisi[Ad=" + ad + ", Yas=" + yas + "]";
    }

    public static void main(String[] args) {
        // Iki farkli Kisi nesnesi olusturulur
        Kisi kisi1 = new Kisi("Ali", 25);
        Kisi kisi2 = new Kisi("Ali", 25);

        // == operatoru ile esitlik kontrolu yapilir
        if (kisi1 == kisi2) {
            System.out.println("Iki kisi nesnesi esittir.");
        } else {
            System.out.println("Iki kisi nesnesi esit degildir.");
        }

        // equals metodu kullanilarak esitlik kontrolu yapilir
        if (kisi1.equals(kisi2)) {
            System.out.println("Iki kisi nesnesi esittir.");
        } else {
            System.out.println("Iki kisi nesnesi esit degildir.");
        }

        // Kisi nesnesinin bilgileri yazdirilir
        System.out.println(kisi1.toString());
    }
}

package com.thealgorithms.ciphers.a5;

import java.util.BitSet;

/**
 * The A5KeyStreamGenerator class is responsible for generating key streams
 * for the A5/1 encryption algorithm using a combination of Linear Feedback Shift Registers (LFSRs).
 *
 * <p>
 * This class extends the CompositeLFSR and initializes a set of LFSRs with
 * a session key and a frame counter to produce a pseudo-random key stream.
 * </p>
 *
 * <p>
 * Note: Proper exception handling for invalid usage is to be implemented.
 * </p>
 */
public class A5KeyStreamGenerator extends CompositeLFSR {

private BitSet storedFrameCounter;
private BitSet currentFrameCounter;
private BitSet sessionKeyData;
private static final int INITIAL_CLOCK_CYCLES = 100;
private static final int GENERATED_STREAM_LENGTH = 228;

/**
 * Initializes the A5KeyStreamGenerator with the specified session key and frame counter.
 *
 * <p>
 * This method sets up the internal state of the LFSRs using the provided
 * session key and frame counter. It creates three LFSRs with specific
 * configurations and initializes them.
 * </p>
 *
 * @param keyData a BitSet representing the session key used for key stream generation.
 * @param frameData a BitSet representing the frame counter that influences the key stream.
 */
@Override
public void initialize(BitSet keyData, BitSet frameData) {
this.sessionKeyData = keyData;
this.currentFrameCounter = (BitSet) frameData.clone();
this.storedFrameCounter = (BitSet) frameData.clone();
registers.clear();
LFSR firstRegister = new LFSR(19, 8, new int[] {13, 16, 17, 18});
LFSR secondRegister = new LFSR(22, 10, new int[] {20, 21});
LFSR thirdRegister = new LFSR(23, 10, new int[] {7, 20, 21, 22});
registers.add(firstRegister);
registers.add(secondRegister);
registers.add(thirdRegister);
registers.forEach(register -> register.initialize(keyData, frameData));
}

/**
 * Re-initializes the key stream generator with the original session key
 * and frame counter. This method restores the generator to its initial
 * state.
 */
public void reInitialize() {
this.initialize(sessionKeyData, storedFrameCounter);
}

/**
 * Generates the next key stream of bits.
 *
 * <p>
 * This method performs an initial set of clocking cycles and then retrieves
 * a key stream of the specified length. After generation, it re-initializes
 * the internal registers.
 * </p>
 *
 * @return a BitSet containing the generated key stream bits.
 */
public BitSet getNextKeyStream() {
for (int cycleIndex = 1; cycleIndex <= INITIAL_CLOCK_CYCLES; ++cycleIndex) {
this.clock();
}
BitSet generatedStream = new BitSet(GENERATED_STREAM_LENGTH);
for (int bitPosition = 1; bitPosition <= GENERATED_STREAM_LENGTH; ++bitPosition) {
boolean currentBit = this.clock();
generatedStream.set(bitPosition - 1, currentBit);
}
resetInternalRegisters();
return generatedStream;
}

/**
 * Re-initializes the registers for the LFSRs.
 *
 * <p>
 * This method increments the frame counter and re-initializes each LFSR
 * with the current session key and frame counter.
 * </p>
 */
private void resetInternalRegisters() {
incrementFrameCount();
registers.forEach(register -> register.initialize(sessionKeyData, currentFrameCounter));
}

/**
 * Increments the current frame counter.
 *
 * <p>
 * This method uses a utility function to increment the frame counter,
 * which influences the key stream generation process.
 * </p>
 */
private void incrementFrameCount() {
Utils.increment(currentFrameCounter, FRAME_COUNTER_LENGTH);
}

/**
 * Retrieves the current frame counter.
 *
 * @return a BitSet representing the current state of the frame counter.
 */
public BitSet getFrameCounter() {
return currentFrameCounter;
}
}

package com.thealgorithms.bitmanipulation;

/**
 * The ParityCheck class provides a method to check the parity of a given number.
 * <p>
 * Parity is a mathematical term that describes the property of an integer's binary representation.
 * The parity of a binary number is the number of 1s in its binary representation.
 * If the number of 1s is even, the parity is even; otherwise, it is odd.
 * <p>
 * For example, the binary representation of 5 is 101, which has two 1s, so the parity of 5 is even.
 * The binary representation of 6 is 110, which has two 1s, so the parity of 6 is even.
 * The binary representation of 7 is 111, which has three 1s, so the parity of 7 is odd.
 *
 * @author Hardvan
 */
public final class ParityCheck {
    private ParityCheck() {
    }

    /**
     * This method checks the parity of the given number.
     *
     * @param n the number to check the parity of
     * @return true if the number has even parity, false otherwise
     */
    public static boolean checkParity(int n) {
        int count = 0;
        while (n > 0) {
            count += n & 1;
            n >>= 1;
        }
        return count % 2 == 0;
    }
}

/**
 * @author Md Asif Joardar
 *
 * Description: The partition problem is a classic problem in computer science
 * that asks whether a given set can be partitioned into two subsets such that
 * the sum of elements in each subset is the same.
 *
 * Example:
 * Consider nums = {1, 2, 3}
 * We can split the array "nums" into two partitions, where each having a sum of 3.
 * nums1 = {1, 2}
 * nums2 = {3}
 *
 * The time complexity of the solution is O(n × sum) and requires O(n × sum) space
 */
public final class PartitionProblem {
    private PartitionProblem() {
    }

    /**
     * Test if a set of integers can be partitioned into two subsets such that the sum of elements
     * in each subset is the same.
     *
     * @param nums the array contains integers.
     * @return {@code true} if two subset exists, otherwise {@code false}.
     */
    public static boolean partition(int[] nums) {
        // calculate the sum of all the elements in the array
        int sum = Arrays.stream(nums).sum();

        // it will return true if the sum is even and the array can be divided into two
        // subarrays/subset with equal sum. and here i reuse the SubsetSum class from dynamic
        // programming section to check if there is exists a subsetsum into nums[] array same as the
        // given sum
        return (sum & 1) == 0 && SubsetSum.subsetSum(nums, sum / 2);
    }
}

