package com.ankan.inheritance;

public class BoxPrice extends BoxWeight {
    double itemCost; // Represents the price/cost associated with this box

    // Default constructor - initializes cost to -1 (sentinel value indicating not set)
    BoxPrice() {
        super(); // Calls parent class (BoxWeight) default constructor
        this.itemCost = -1.0;
    }

    // Constructor that only sets the cost
    BoxPrice(double costValue) {
        this.itemCost = costValue;
        // Note: Other dimensions and weight remain uninitialized (will have default values)
    }

    // Copy constructor - creates a new BoxPrice based on an existing BoxPrice object
    BoxPrice(BoxPrice existingBoxPrice) {
        super(existingBoxPrice); // Calls copy constructor of BoxWeight
        this.itemCost = existingBoxPrice.itemCost;
    }

    // Fully parameterized constructor - sets all dimensions, weight, and cost
    public BoxPrice(double boxLength, double boxHeight, double boxWidth, double boxWeight, double productCost) {
        super(boxLength, boxHeight, boxWidth, boxWeight); // Pass all dimensions and weight to parent
        this.itemCost = productCost;
    }

    // Constructor for cube-shaped boxes (all dimensions equal) with weight and cost
    BoxPrice(double sideLength, double boxWeight, double productCost) {
        super(sideLength, boxWeight); // Calls BoxWeight(side, weight) constructor
        this.itemCost = productCost;
    }

    // Additional method to display box pricing information (educational enhancement)
    public void displayPriceInfo() {
        System.out.println("Box cost: $" + itemCost);
    }
}

public class UsAlma {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Tabani gir:");
        int base = input.nextInt();

        System.out.println("Ussu gir:");
        int exponent = input.nextInt();

        input.close();

        // Multiply the base into the accumulator using a while-loop and a
        // separate countdown variable, instead of the original for-loop.
        int result = 1;
        int remainingMultiplications = exponent;
        while (remainingMultiplications > 0) {
            result = result * base;
            remainingMultiplications--;
        }

        System.out.println(base + "^" + exponent + " = " + result);
    }
}

public class CustomGenArrayList<T> {
// Here we created a custom ArrayList with a Generic <T>
    private Object[] data;
    private static int DEFAULT_SIZE = 10;
    private int size = 0; // also working as index value

    public CustomGenArrayList() {
        this.data = new Object[DEFAULT_SIZE];
    }

    public void add(T num) {
        if (isFull()) {
            resize();
        }
        data[size++] = num;
    }

    private void resize() {
        Object[] temp = new Object[data.length * 2];

        // copy the new items in the new array
        for (int i = 0; i < data.length; i++) {
            temp[i] = data[i];
        }
        data = temp;
    }

    private boolean isFull() {
        return size == data.length;
    }

    public T remove() {
        T removed = (T) data[--size];
        return removed;
    }

    public T get(int index) {
        return (T) data[index];
    }

    public int size() {
        return size;
    }

    public void set (int index, T value) {
        data[index] = value;
    }

    @Override
    public String toString() {
        return "CustomGenArrayList{" +
                "data=" + Arrays.toString(data) +
                ", size=" + size +
                '}';
    }

    public static void main(String[] args) {
//        ArrayList list = new ArrayList();
        CustomGenArrayList list = new CustomGenArrayList();
//        list.add(3);
//        list.add(5);
//        list.add(9);

//        for (int i = 0; i < 14; i++) {
//            list.add(2 * i);
//        }
//
//        System.out.println(list);

        ArrayList<String> list2 = new ArrayList<>();
//        list2.add("dfgg");
        // Generics help us in providing a parameterized type for stuff like <Integer> and all.

        CustomGenArrayList<Double> list3 = new CustomGenArrayList<>();
        for (double i = 0; i < 14; i++) {
         list3.add(2.5 * i);
        }
        System.out.println(list3);
        System.out.println(list3.get(5));
        System.out.println(list3.remove());
    }
}

package com.thealgorithms.datastructures.caches;

import java.util.HashMap;
import java.util.Map;

/**
 * A Least Recently Used (LRU) Cache implementation.
 *
 * <p>An LRU cache is a fixed-size cache that maintains items in order of use. When the cache reaches
 * its capacity and a new item needs to be added, it removes the least recently used item first.
 * This implementation provides O(1) time complexity for both get and put operations.</p>
 *
 * <p>Features:</p>
 * <ul>
 *   <li>Fixed-size cache with configurable capacity</li>
 *   <li>Constant time O(1) operations for get and put</li>
 *   <li>Thread-unsafe - should be externally synchronized if used in concurrent environments</li>
 *   <li>Supports null values but not null keys</li>
 * </ul>
 *
 * <p>Implementation Details:</p>
 * <ul>
 *   <li>Uses a HashMap for O(1) key-value lookups</li>
 *   <li>Maintains a doubly-linked list for tracking access order</li>
 *   <li>The head of the list contains the least recently used item</li>
 *   <li>The tail of the list contains the most recently used item</li>
 * </ul>
 *
 * <p>Example usage:</p>
 * <pre>
 * LRUCache<String, Integer> cache = new LRUCache<>(3); // Create cache with capacity 3
 * cache.put("A", 1); // Cache: A=1
 * cache.put("B", 2); // Cache: A=1, B=2
 * cache.put("C", 3); // Cache: A=1, B=2, C=3
 * cache.get("A");    // Cache: B=2, C=3, A=1 (A moved to end)
 * cache.put("D", 4); // Cache: C=3, A=1, D=4 (B evicted)
 * </pre>
 *
 * @param <K> the type of keys maintained by this cache
 * @param <V> the type of mapped values
 */
public class LRUCache<K, V> {

    private final Map<K, Entry<K, V>> data = new HashMap<>();
    private Entry<K, V> head;
    private Entry<K, V> tail;
    private int cap;
    private static final int DEFAULT_CAP = 100;

    public LRUCache() {
        setCapacity(DEFAULT_CAP);
    }

    public LRUCache(int cap) {
        setCapacity(cap);
    }

    /**
     * Returns the current capacity of the cache.
     *
     * @param newCapacity the new capacity of the cache
     */
    private void setCapacity(int newCapacity) {
        checkCapacity(newCapacity);
        for (int i = data.size(); i > newCapacity; i--) {
            Entry<K, V> evicted = evict();
            data.remove(evicted.getKey());
        }
        this.cap = newCapacity;
    }

    /**
     * Evicts the least recently used item from the cache.
     *
     * @return the evicted entry
     */
    private Entry<K, V> evict() {
        if (head == null) {
            throw new RuntimeException("cache cannot be empty!");
        }
        Entry<K, V> evicted = head;
        head = evicted.getNextEntry();
        head.setPreEntry(null);
        evicted.setNextEntry(null);
        return evicted;
    }

    /**
     * Checks if the capacity is valid.
     *
     * @param capacity the capacity to check
     */
    private void checkCapacity(int capacity) {
        if (capacity <= 0) {
            throw new RuntimeException("capacity must greater than 0!");
        }
    }

    /**
     * Returns the value to which the specified key is mapped, or null if this cache contains no
     * mapping for the key.
     *
     * @param key the key whose associated value is to be returned
     * @return the value to which the specified key is mapped, or null if this cache contains no
     * mapping for the key
     */
    public V get(K key) {
        if (!data.containsKey(key)) {
            return null;
        }
        final Entry<K, V> entry = data.get(key);
        moveNodeToLast(entry);
        return entry.getValue();
    }

    /**
     * Moves the specified entry to the end of the list.
     *
     * @param entry the entry to move
     */
    private void moveNodeToLast(Entry<K, V> entry) {
        if (tail == entry) {
            return;
        }
        final Entry<K, V> preEntry = entry.getPreEntry();
        final Entry<K, V> nextEntry = entry.getNextEntry();
        if (preEntry != null) {
            preEntry.setNextEntry(nextEntry);
        }
        if (nextEntry != null) {
            nextEntry.setPreEntry(preEntry);
        }
        if (head == entry) {
            head = nextEntry;
        }
        tail.setNextEntry(entry);
        entry.setPreEntry(tail);
        entry.setNextEntry(null);
        tail = entry;
    }

    /**
     * Associates the specified value with the specified key in this cache.
     *
     * @param key the key with which the specified value is to be associated
     * @param value the value to be associated with the specified key
     */
    public void put(K key, V value) {
        if (data.containsKey(key)) {
            final Entry<K, V> existingEntry = data.get(key);
            existingEntry.setValue(value);
            moveNodeToLast(existingEntry);
            return;
        }
        Entry<K, V> newEntry;
        if (data.size() == cap) {
            newEntry = evict();
            data.remove(newEntry.getKey());
        } else {
            newEntry = new Entry<>();
        }

        newEntry.setKey(key);
        newEntry.setValue(value);
        addNewEntry(newEntry);
        data.put(key, newEntry);
    }

    /**
     * Adds a new entry to the end of the list.
     *
     * @param newEntry the entry to add
     */
    private void addNewEntry(Entry<K, V> newEntry) {
        if (data.isEmpty()) {
            head = newEntry;
            tail = newEntry;
            return;
        }
        tail.setNextEntry(newEntry);
        newEntry.setPreEntry(tail);
        newEntry.setNextEntry(null);
        tail = newEntry;
    }

    static final class Entry<I, J> {

        private Entry<I, J> preEntry;
        private Entry<I, J> nextEntry;
        private I key;
        private J value;

        Entry() {
        }

        Entry(Entry<I, J> preEntry, Entry<I, J> nextEntry, I key, J value) {
            this.preEntry = preEntry;
            this.nextEntry = nextEntry;
            this.key = key;
            this.value = value;
        }

        public Entry<I, J> getPreEntry() {
            return preEntry;
        }

        public void setPreEntry(Entry<I, J> preEntry) {
            this.preEntry = preEntry;
        }

        public Entry<I, J> getNextEntry() {
            return nextEntry;
        }

        public void setNextEntry(Entry<I, J> nextEntry) {
            this.nextEntry = nextEntry;
        }

        public I getKey() {
            return key;
        }

        public void setKey(I key) {
            this.key = key;
        }

        public J getValue() {
            return value;
        }

        public void setValue(J value) {
            this.value = value;
        }
    }
}

/**
 * Small interactive CRUD demo against a MySQL "users" table: insert,
 * update, delete, or list rows depending on a menu choice.
 */
public class MySQLDemo {

    private static final String JDBC_URL = "jdbc:mysql://localhost:3306/testdb";
    private static final String DB_USER = "root";
    private static final String DB_PASSWORD = "password";

    public static void main(String[] args) throws SQLException, ClassNotFoundException {

        Class.forName("com.mysql.jdbc.Driver");

        try (Connection db = DriverManager.getConnection(JDBC_URL, DB_USER, DB_PASSWORD);
             Statement generalStatement = db.createStatement();
             Scanner console = new Scanner(System.in)) {

            System.out.println("Yapmak istediginiz islemi secin: ");
            System.out.println("1 - Yeni kayit ekle");
            System.out.println("2 - Kayit guncelle");
            System.out.println("3 - Kayit sil");
            System.out.println("4 - Tum kayitlari listele");
            System.out.print("Seciminizi yapin: ");
            int menuChoice = console.nextInt();
            console.nextLine();

            switch (menuChoice) {
                case 1:
                    insertUser(db, console);
                    break;
                case 2:
                    updateUser(db, console);
                    break;
                case 3:
                    deleteUser(db, console);
                    break;
                case 4:
                    listUsers(generalStatement);
                    break;
                default:
                    System.out.println("Gecersiz secim.");
            }
        }
    }

    private static void insertUser(Connection db, Scanner console) throws SQLException {
        System.out.print("Adinizi girin: ");
        String name = console.nextLine();
        System.out.print("Email adresinizi girin: ");
        String email = console.nextLine();
        String sql = "iNSERT iNTO users (name, email) VALUES (?, ?)";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setString(1, name);
            stmt.setString(2, email);
            stmt.executeUpdate();
            System.out.println("Yeni kayit basariyla eklendi.");
        }
    }

    private static void updateUser(Connection db, Scanner console) throws SQLException {
        System.out.print("Guncellemek istediginiz kullanicinin iD'sini girin: ");
        int targetId = console.nextInt();
        console.nextLine();
        System.out.print("Yeni ad girin: ");
        String newName = console.nextLine();
        System.out.print("Yeni email adresi girin: ");
        String newEmail = console.nextLine();
        String sql = "UPDATE users SET name = ?, email = ? WHERE id = ?";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setString(1, newName);
            stmt.setString(2, newEmail);
            stmt.setInt(3, targetId);
            int affected = stmt.executeUpdate();
            System.out.println(affected > 0 ? "Kullanici guncellendi." : "Kullanici bulunamadi.");
        }
    }

    private static void deleteUser(Connection db, Scanner console) throws SQLException {
        System.out.print("Silmek istediginiz kullanicinin iD'sini girin: ");
        int targetId = console.nextInt();
        String sql = "DELETE FROM users WHERE id = ?";
        try (PreparedStatement stmt = db.prepareStatement(sql)) {
            stmt.setInt(1, targetId);
            int affected = stmt.executeUpdate();
            System.out.println(affected > 0 ? "Kullanici silindi." : "Kullanici bulunamadi.");
        }
    }

    private static void listUsers(Statement generalStatement) throws SQLException {
        String sql = "SELECT * FROM users";
        try (ResultSet rows = generalStatement.executeQuery(sql)) {
            while (rows.next()) {
                int id = rows.getInt("id");
                String name = rows.getString("name");
                String email = rows.getString("email");
                System.out.println("iD: " + id + ", Name: " + name + ", Email: " + email);
            }
        }
    }
}

package eamples;
import java.util.Scanner; // Kullanicidan veri almak icin Scanner sinifini ice aktarir.

public class UsAlma {

	public static void main(String[] args) {

		// Kullanicidan veri almak icin Scanner objesi olusturur.
		Scanner scanner = new Scanner(System.in);

		// Kullanicidan taban degerini girmesini ister.
		System.out.println("Tabani gir:");
		int taban = scanner.nextInt(); // Girilen taban degerini okur ve 'taban' degiskenine atar.

		// Kullanicidan us degerini girmesini ister.
		System.out.println("Ussu gir:");
		int us = scanner.nextInt(); // Girilen us degerini okur ve 'us' degiskenine atar.

		scanner.close();

		// Sonucu hesaplamak icin baslangic degeri 1 olan bir 'sonuc' degiskeni tanimlar.
		int sonuc = 1;

		// 'us' degeri kadar dongu calisir. Her adimda 'taban' degeri ile 'sonuc' carpilir.
		for(int i = 0; i < us; i++) { // Dongu, us sayisi kadar tekrar eder.
			sonuc = sonuc * taban; // Her adimda 'sonuc', 'taban' ile carpilir.
		}

		// Hesaplanan us alma islemine sonucu ekrana yazdirir.
		System.out.println(taban + "^" + us + " = " + sonuc); // Sonucu ekrana yazdirir.
	}
}

/**
 * Converts text to Morse code and vice-versa.
 * Text to Morse code: Each letter is separated by a space and each word is separated by a pipe (|).
 * Example: "HELLO WORLD" -> ".... . .-.. .-.. --- | .-- --- .-. .-.. -.."
 *
 * Morse code to text: Each letter is separated by a space and each word is separated by a pipe (|).
 * Example: ".... . .-.. .-.. --- | .-- --- .-. .-.. -.." -> "HELLO WORLD"
 *
 * Applications: Used in radio communications and algorithmic challenges.
 *
 * @author Hardvan
 */
public final class MorseCodeConverter {
private MorseCodeConverter() {
}

private static final Map<Character, String> ENCODE_MAP = new HashMap<>();
private static final Map<String, Character> DECODE_MAP = new HashMap<>();

static {
ENCODE_MAP.put('A', ".-");
ENCODE_MAP.put('B', "-...");
ENCODE_MAP.put('C', "-.-.");
ENCODE_MAP.put('D', "-..");
ENCODE_MAP.put('E', ".");
ENCODE_MAP.put('F', "..-.");
ENCODE_MAP.put('G', "--.");
ENCODE_MAP.put('H', "....");
ENCODE_MAP.put('I', "..");
ENCODE_MAP.put('J', ".---");
ENCODE_MAP.put('K', "-.-");
ENCODE_MAP.put('L', ".-..");
ENCODE_MAP.put('M', "--");
ENCODE_MAP.put('N', "-.");
ENCODE_MAP.put('O', "---");
ENCODE_MAP.put('P', ".--.");
ENCODE_MAP.put('Q', "--.-");
ENCODE_MAP.put('R', ".-.");
ENCODE_MAP.put('S', "...");
ENCODE_MAP.put('T', "-");
ENCODE_MAP.put('U', "..-");
ENCODE_MAP.put('V', "...-");
ENCODE_MAP.put('W', ".--");
ENCODE_MAP.put('X', "-..-");
ENCODE_MAP.put('Y', "-.--");
ENCODE_MAP.put('Z', "--..");
ENCODE_MAP.forEach((keySymbol, codeValue) -> DECODE_MAP.put(codeValue, keySymbol));
}

/**
 * Converts text to Morse code.
 * Each letter is separated by a space and each word is separated by a pipe (|).
 *
 * @param sourceText The text to convert to Morse code.
 * @return The Morse code representation of the text.
 */
public static String textToMorse(String sourceText) {
StringBuilder encodedResult = new StringBuilder();
String[] wordSegments = sourceText.toUpperCase().split(" ");
for (int segmentPos = 0; segmentPos < wordSegments.length; segmentPos++) {
for (char currentChar : wordSegments[segmentPos].toCharArray()) {
encodedResult.append(ENCODE_MAP.getOrDefault(currentChar, "")).append(" ");
}
if (segmentPos < wordSegments.length - 1) {
encodedResult.append("| ");
}
}
return encodedResult.toString().trim();
}

/**
 * Converts Morse code to text.
 * Each letter is separated by a space and each word is separated by a pipe (|).
 *
 * @param encodedData The Morse code to convert to text.
 * @return The text representation of the Morse code.
 */
public static String morseToText(String encodedData) {
StringBuilder decodedResult = new StringBuilder();
String[] wordCodes = encodedData.split(" \\| ");
for (int wordPos = 0; wordPos < wordCodes.length; wordPos++) {
for (String symbolCode : wordCodes[wordPos].split(" ")) {
decodedResult.append(DECODE_MAP.getOrDefault(symbolCode, '?'));
}
if (wordPos < wordCodes.length - 1) {
decodedResult.append(" ");
}
}
return decodedResult.toString();
}
}

/**
 * A class that handles unit conversions using affine transformations.
 *
 * <p>The {@code UnitsConverter} allows converting values between different units using
 * pre-defined affine conversion formulas. Each conversion is represented by an
 * {@link AffineConverter} that defines the scaling and offset for the conversion.
 *
 * <p>For each unit, both direct conversions (e.g., Celsius to Fahrenheit) and inverse
 * conversions (e.g., Fahrenheit to Celsius) are generated automatically. It also computes
 * transitive conversions (e.g., Celsius to Kelvin via Fahrenheit if both conversions exist).
 *
 * <p>Key features include:
 * <ul>
 *   <li>Automatic handling of inverse conversions (e.g., Fahrenheit to Celsius).</li>
 *   <li>Compositional conversions, meaning if conversions between A -> B and B -> C exist,
 *       it can automatically generate A -> C conversion.</li>
 *   <li>Supports multiple unit systems as long as conversions are provided in pairs.</li>
 * </ul>
 *
 * <h2>Example Usage</h2>
 * <pre>
 * Map&lt;Pair&lt;String, String&gt;, AffineConverter&gt; basicConversions = Map.ofEntries(
 *     entry(Pair.of("Celsius", "Fahrenheit"), new AffineConverter(9.0 / 5.0, 32.0)),
 *     entry(Pair.of("Kelvin", "Celsius"), new AffineConverter(1.0, -273.15))
 * );
 *
 * UnitsConverter converter = new UnitsConverter(basicConversions);
 * double result = converter.convert("Celsius", "Fahrenheit", 100.0);
 * // Output: 212.0 (Celsius to Fahrenheit conversion of 100°C)
 * </pre>
 *
 * <h2>Exception Handling</h2>
 * <ul>
 *   <li>If the input unit and output unit are the same, an {@link IllegalArgumentException} is thrown.</li>
 *   <li>If a conversion between the requested units does not exist, a {@link NoSuchElementException} is thrown.</li>
 * </ul>
 */
public final class UnitsConverter {
private final Map<Pair<String, String>, AffineConverter> conversionMap;
private final Set<String> unitSet;

private static void addIfNeeded(Map<Pair<String, String>, AffineConverter> targetMap, final String fromUnit, final String toUnit, final AffineConverter conversionRule) {
if (!fromUnit.equals(toUnit)) {
final var keyPair = Pair.of(fromUnit, toUnit);
targetMap.putIfAbsent(keyPair, conversionRule);
}
}

private static Map<Pair<String, String>, AffineConverter> includeInversePairs(final Map<Pair<String, String>, AffineConverter> sourceConversions) {
Map<Pair<String, String>, AffineConverter> extendedMap = new HashMap<>();
for (final var entry : sourceConversions.entrySet()) {
final var fromUnit = entry.getKey().getKey();
final var toUnit = entry.getKey().getValue();
addIfNeeded(extendedMap, fromUnit, toUnit, entry.getValue());
addIfNeeded(extendedMap, toUnit, fromUnit, entry.getValue().invert());
}
return extendedMap;
}

private static Map<Pair<String, String>, AffineConverter> includeCompositePairs(final Map<Pair<String, String>, AffineConverter> sourceConversions) {
Map<Pair<String, String>, AffineConverter> extendedMap = new HashMap<>();
for (final var firstEntry : sourceConversions.entrySet()) {
final var firstKey = firstEntry.getKey();
addIfNeeded(extendedMap, firstKey.getKey(), firstKey.getValue(), firstEntry.getValue());
for (final var secondEntry : sourceConversions.entrySet()) {
final var secondKey = secondEntry.getKey();
if (firstKey.getValue().equals(secondKey.getKey())) {
final var combinedConversion = secondEntry.getValue().compose(firstEntry.getValue());
addIfNeeded(extendedMap, firstKey.getKey(), secondKey.getValue(), combinedConversion);
}
}
}
return extendedMap;
}

private static Map<Pair<String, String>, AffineConverter> computeAllTransforms(final Map<Pair<String, String>, AffineConverter> initialConversions) {
var currentMap = includeInversePairs(initialConversions);
var nextMap = includeCompositePairs(currentMap);
while (nextMap.size() != currentMap.size()) {
currentMap = nextMap;
nextMap = includeCompositePairs(currentMap);
}
return nextMap;
}

private static Set<String> extractUnitSet(final Map<Pair<String, String>, AffineConverter> conversionData) {
Set<String> unitNames = new HashSet<>();
for (final var entry : conversionData.entrySet()) {
unitNames.add(entry.getKey().getKey());
}
return unitNames;
}

/**
 * Constructor for {@code UnitsConverter}.
 *
 * <p>Accepts a map of basic conversions and automatically generates inverse and
 * transitive conversions.
 *
 * @param baseConversions the initial set of unit conversions to add.
 */
public UnitsConverter(final Map<Pair<String, String>, AffineConverter> baseConversions) {
conversionMap = computeAllTransforms(baseConversions);
unitSet = extractUnitSet(conversionMap);
}

/**
 * Converts a value from one unit to another.
 *
 * @param fromUnit the unit of the input value.
 * @param toUnit the unit to convert the value into.
 * @param numericValue the value to convert.
 * @return the converted value in the target unit.
 * @throws IllegalArgumentException if fromUnit equals toUnit.
 * @throws NoSuchElementException if no conversion exists between the units.
 */
public double convert(final String fromUnit, final String toUnit, final double numericValue) {
if (fromUnit.equals(toUnit)) {
throw new IllegalArgumentException("fromUnit must be different from toUnit.");
}
final var conversionKey = Pair.of(fromUnit, toUnit);
return conversionMap.computeIfAbsent(conversionKey, key -> { throw new NoSuchElementException("No converter for: " + key); }).convert(numericValue);
}

/**
 * Retrieves the set of all units supported by this converter.
 *
 * @return a set of available units.
 */
public Set<String> getAvailableUnits() {
return unitSet;
}
}

package com.thealgorithms.datastructures.heaps;

/**
 * A MinPriorityQueue is a specialized data structure that maintains the
 * min-heap property, where the smallest element has the highest priority.
 *
 * <p>In a min-priority queue, every parent node is less than or equal
 * to its child nodes, which ensures that the smallest element can
 * always be efficiently retrieved.</p>
 *
 * <p>Functions:</p>
 * <ul>
 *     <li><b>insert(int key)</b>: Inserts a new key into the queue.</li>
 *     <li><b>delete()</b>: Removes and returns the highest priority value (the minimum).</li>
 *     <li><b>peek()</b>: Returns the highest priority value without removing it.</li>
 *     <li><b>isEmpty()</b>: Checks if the queue is empty.</li>
 *     <li><b>isFull()</b>: Checks if the queue is full.</li>
 *     <li><b>heapSort()</b>: Sorts the elements in ascending order.</li>
 *     <li><b>print()</b>: Prints the current elements in the queue.</li>
 * </ul>
 */
public class MinPriorityQueue {

    private final int[] heap;
    private final int capacity;
    private int size;

    /**
     * Initializes a new MinPriorityQueue with a specified capacity.
     *
     * @param c the maximum number of elements the queue can hold
     */
    public MinPriorityQueue(int c) {
        this.capacity = c;
        this.size = 0;
        this.heap = new int[c + 1];
    }

    /**
     * Inserts a new key into the min-priority queue.
     *
     * @param key the value to be inserted
     */
    public void insert(int key) {
        if (this.isFull()) {
            throw new IllegalStateException("MinPriorityQueue is full. Cannot insert new element.");
        }
        this.heap[this.size + 1] = key;
        int k = this.size + 1;
        while (k > 1) {
            if (this.heap[k] < this.heap[k / 2]) {
                int temp = this.heap[k];
                this.heap[k] = this.heap[k / 2];
                this.heap[k / 2] = temp;
            }
            k = k / 2;
        }
        this.size++;
    }

    /**
     * Retrieves the highest priority value (the minimum) without removing it.
     *
     * @return the minimum value in the queue
     * @throws IllegalStateException if the queue is empty
     */
    public int peek() {
        if (isEmpty()) {
            throw new IllegalStateException("MinPriorityQueue is empty. Cannot peek.");
        }
        return this.heap[1];
    }

    /**
     * Checks whether the queue is empty.
     *
     * @return true if the queue is empty, false otherwise
     */
    public boolean isEmpty() {
        return size == 0;
    }

    /**
     * Checks whether the queue is full.
     *
     * @return true if the queue is full, false otherwise
     */
    public boolean isFull() {
        return size == capacity;
    }

    /**
     * Prints the elements of the queue.
     */
    public void print() {
        for (int i = 1; i <= this.size; i++) {
            System.out.print(this.heap[i] + " ");
        }
        System.out.println();
    }

    /**
     * Sorts the elements in the queue using heap sort.
     */
    public void heapSort() {
        for (int i = 1; i <= this.size; i++) {
            this.delete();
        }
    }

    /**
     * Reorders the heap after a deletion to maintain the heap property.
     */
    private void sink() {
        int k = 1;
        while (2 * k <= this.size) {
            int minIndex = k; // Assume current index is the minimum

            if (2 * k <= this.size && this.heap[2 * k] < this.heap[minIndex]) {
                minIndex = 2 * k; // Left child is smaller
            }
            if (2 * k + 1 <= this.size && this.heap[2 * k + 1] < this.heap[minIndex]) {
                minIndex = 2 * k + 1; // Right child is smaller
            }

            if (minIndex == k) {
                break; // No swap needed, heap property is satisfied
            }

            // Swap with the smallest child
            int temp = this.heap[k];
            this.heap[k] = this.heap[minIndex];
            this.heap[minIndex] = temp;

            k = minIndex; // Move down to the smallest child
        }
    }

    /**
     * Deletes and returns the highest priority value (the minimum) from the queue.
     *
     * @return the minimum value from the queue
     * @throws IllegalStateException if the queue is empty
     */
    public int delete() {
        if (isEmpty()) {
            throw new IllegalStateException("MinPriorityQueue is empty. Cannot delete.");
        }
        int min = this.heap[1];
        this.heap[1] = this.heap[this.size]; // Move last element to the root
        this.size--;
        this.sink();
        return min;
    }
}

