package MovableCircle;

/**
 *
 * @author GIA KINH
 */
public class MovableCircle implements Movable{
    private int radius;
    private MovablePoint center;

    public MovableCircle() {
    }

    public MovableCircle(int radius, MovablePoint center) {
        this.radius = radius;
        this.center = center;
    }

    public MovableCircle(int x, int y, int xSpeed, int ySpeed,int radius) {
        this.radius = radius;
        this.center = new MovablePoint(x, y, xSpeed, ySpeed);
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }

    public MovablePoint getCenter() {
        return center;
    }

    public void setCenter(MovablePoint center) {
        this.center = center;
    }

    @Override
    public String toString() {
        return  center + ",radius=" + radius;
    }

    @Override
    public void moveUp() {
       this.center.setY(this.center.getY()-this.center.getySpeed());
    }

    @Override
    public void moveDown() {
        this.center.setY(this.center.getY()+this.center.getySpeed());
    }

    @Override
    public void moveLeft() {
        this.center.setX(this.center.getX()-this.center.getxSpeed());
    }

    @Override
    public void moveRight() {
        this.center.setX(this.center.getX()+this.center.getxSpeed());
    } 
}

/**
 * Grafiksel Hanoi Kuleleri gosterimi: cubuklar ve diskler JPanel
 * bilesenleriyle temsil edilir, cozum rekursif algoritma ile
 * adim adim animasyona donusturulur.
 */
public class HanoiKuleleri extends JFrame {

    private static final long serialVersionUID = 1L;
    private static final int FRAME_GENISLIK = 600;
    private static final int FRAME_YUKSEKLIK = 400;

    private static final int DIREK_GENISLIK = 100;
    private static final int DIREK_YUKSEKLIK = 300;

    private static final int KATMAN_YUKSEKLIK = 20;
    private static final int TOPLAM_DISK = 4;
    private static final int TOPLAM_DIREK = 3;

    private final int[] direkDoluluk = new int[TOPLAM_DIREK];
    private final JPanel[] direkler = new JPanel[TOPLAM_DIREK];
    private final JPanel[] diskKatmanlari = new JPanel[TOPLAM_DISK];

    public HanoiKuleleri() {
        direkleriHazirla();
        diskleriHazirla();
        ilkDirekeDiskleriYerlestir();

        JPanel govdePaneli = new JPanel(new FlowLayout(FlowLayout.CENTER, 10, 10));
        for (JPanel direk : direkler) {
            govdePaneli.add(direk);
        }

        setTitle("Tower of Hanoi");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(FRAME_GENISLIK, FRAME_YUKSEKLIK);
        setLocationRelativeTo(null);
        setResizable(false);
        add(govdePaneli);
    }

    private void direkleriHazirla() {
        for (int i = 0; i < TOPLAM_DIREK; i++) {
            direkler[i] = new JPanel();
            direkler[i].setPreferredSize(new Dimension(DIREK_GENISLIK, DIREK_YUKSEKLIK));
            direkler[i].setBackground(new Color(144, 238, 144));
        }
    }

    private void diskleriHazirla() {
        for (int i = 0; i < TOPLAM_DISK; i++) {
            int genislik = (TOPLAM_DISK - i + 1) * KATMAN_YUKSEKLIK;
            diskKatmanlari[i] = new JPanel();
            diskKatmanlari[i].setPreferredSize(new Dimension(genislik, KATMAN_YUKSEKLIK));
            diskKatmanlari[i].setBackground(Color.RED);
        }
    }

    private void ilkDirekeDiskleriYerlestir() {
        direkDoluluk[0] = TOPLAM_DISK;
        for (int i = 0; i < TOPLAM_DISK; i++) {
            direkler[0].add(diskKatmanlari[i]);
        }
    }

    /** Bir diregin en ustundeki diski baska bir direge tasir ve ekrani gunceller. */
    public void diskTasi(int kaynakDirek, int hedefDirek) {
        JPanel tasinanDisk = (JPanel) direkler[kaynakDirek].getComponent(--direkDoluluk[kaynakDirek]);
        direkler[kaynakDirek].remove(tasinanDisk);

        direkler[hedefDirek].add(tasinanDisk, direkDoluluk[hedefDirek]++);

        revalidate();
        repaint();
    }

    public static void main(String[] args) throws InterruptedException {
        HanoiKuleleri arayuz = new HanoiKuleleri();
        arayuz.setVisible(true);

        hanoiCoz(TOPLAM_DISK, 0, 2, 1, arayuz);
    }

    /** Klasik rekursif Hanoi cozumu; her tasima islemi arayuzde animasyona donusturulur. */
    public static void hanoiCoz(int diskAdedi, int kaynak, int hedef, int yardimci, HanoiKuleleri arayuz)
            throws InterruptedException {
        if (diskAdedi == 1) {
            arayuz.diskTasi(kaynak, hedef);
            Thread.sleep(500);
        } else {
            hanoiCoz(diskAdedi - 1, kaynak, yardimci, hedef, arayuz);
            arayuz.diskTasi(kaynak, hedef);
            Thread.sleep(500);
            hanoiCoz(diskAdedi - 1, yardimci, hedef, kaynak, arayuz);
        }
    }
}

