package Workshop6;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Scanner;
import java.util.StringTokenizer;

/**
 * A menu of string-processing exercises applied to one input string.
 */
public class Number_String {

    public static void menu() {
        System.out.println("1. search words \"me\", \"why\", \"well\"");
        System.out.println("2. \"you\" word appear in @str how many times?");
        System.out.println("3. Replace the first character of each word by its UPPER CASE");
        System.out.println("4. Replace the first character of each word by its LOWER CASE, and the last character of each word by its UPPER CASE");
        System.out.println("5. Extract @str string to an array of words, then display those words by increasing order.");
        System.out.println("6. Give a character named c, remove from @str the first character which is equals to c. ");
        System.out.println("7. Count how many words in @str, display “empty string” if @str is an empty string.");
        System.out.println("8. Print all letters of @str only.");
        System.out.println("9. Reserve @str.");
        System.out.println("10. Replace all letter ‘a’ by ‘A’ and ‘b’ by ‘B’.");
        System.out.println("11. How many upper letters in @str?");
        System.out.println("12. Show menu");
        System.out.println("0. exit");
    }

    public static boolean checkMeWhyWell(String string) {
        String lower = string.toLowerCase();
        return lower.contains("me") && lower.contains("why") && lower.contains("well");
    }

    public static int countWordYou(String string) {
        StringTokenizer tokenizer = new StringTokenizer(string, " ");
        int count = 0;
        while (tokenizer.hasMoreTokens()) {
            if (tokenizer.nextToken().equalsIgnoreCase("you")) {
                count++;
            }
        }
        return count;
    }

    public static String upperFisrtCharWord(String string) {
        StringTokenizer tokenizer = new StringTokenizer(string, " ");
        StringBuilder result = new StringBuilder();
        while (tokenizer.hasMoreTokens()) {
            String word = tokenizer.nextToken();
            result.append(word.substring(0, 1).toUpperCase()).append(word.substring(1).toLowerCase()).append(" ");
        }
        return result.toString().trim();
    }

    public static String upperLastCharWord(String string) {
        StringTokenizer tokenizer = new StringTokenizer(string, " ");
        StringBuilder result = new StringBuilder();
        while (tokenizer.hasMoreTokens()) {
            String word = tokenizer.nextToken();
            result.append(word.substring(0, word.length() - 1).toLowerCase())
                    .append(word.substring(word.length() - 1).toUpperCase())
                    .append(" ");
        }
        return result.toString().trim();
    }

    public static void sortWord(String string) {
        String[] words = string.trim().replaceAll("\\s+", " ").split(" ");
        ArrayList<String> list = new ArrayList<>(Arrays.asList(words));
        Collections.sort(list);
        System.out.println("After string sort word: " + list.toString());
    }

    public static String removeCharString(String string, char c) {
        StringBuilder builder = new StringBuilder(string);
        int index = string.indexOf(c);
        if (index != -1) {
            builder.deleteCharAt(index);
            return builder.toString();
        }
        System.out.println("Can not found character");
        return string;
    }

    public static int countWords(String string) {
        if (string.isEmpty()) {
            System.out.println("Empty String");
            return 0;
        }
        return string.trim().split("\\s+").length;
    }

    public static void showAllLetters(String string) {
        char[] chars = string.replaceAll("[^a-zA-Z]", "").toCharArray();
        ArrayList<Character> seen = new ArrayList<>();
        for (char c : chars) {
            if (!seen.contains(c)) {
                seen.add(c);
            }
        }
        System.out.println("All letters: " + Arrays.toString(seen.toArray()));
    }

    public static String reserveString(String string) {
        return new StringBuilder(string).reverse().toString();
    }

    public static String replaceLetterAandB(String string) {
        return string.replaceAll("a", "A").replaceAll("b", "B");
    }

    public static int countUpperLetter(String string) {
        String[] parts = string.trim().replaceAll("[^A-Z]", " ").replaceAll("\\s+", " ").split(" ");
        return parts.length;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String string = scanner.nextLine();
        menu();
        while (true) {
            System.out.print("Select option: ");
            int choice = scanner.nextInt();
            switch (choice) {
                case 1:
                    System.out.println("String have contains \"me\", \"why\", \"well\"? " + checkMeWhyWell(string));
                    break;
                case 2:
                    System.out.println("Have " + countWordYou(string) + " word \"you\" in string");
                    break;
                case 3:
                    string = upperFisrtCharWord(string);
                    System.out.println("After String: " + string);
                    break;
                case 4:
                    string = upperLastCharWord(string);
                    System.out.println("After String: " + string);
                    break;
                case 5:
                    sortWord(string);
                    break;
                case 6:
                    System.out.print("Enter char: ");
                    char c = scanner.next().charAt(0);
                    string = removeCharString(string, c);
                    System.out.println("After string remove char: " + string);
                    break;
                case 7:
                    int count = countWords(string);
                    if (count > 0) {
                        System.out.println("Words in string: " + count);
                    }
                    break;
                case 8:
                    showAllLetters(string);
                    break;
                case 9:
                    System.out.println("Reserve string: " + reserveString(string));
                    break;
                case 10:
                    string = replaceLetterAandB(string);
                    System.out.println("After string: " + string);
                    break;
                case 11:
                    System.out.println("Have upper letter: " + countUpperLetter(string));
                    break;
                case 12:
                    menu();
                    break;
                case 0:
                    break;
                default:
                    System.out.println("Please enter [0->12]");
                    break;
            }
            if (choice == 0) {
                break;
            }
        }
    }
}

public class UsAlma {

	// Bir tabani, verilen kuvvete yukseltir ve sonucu geri verir
	long kuvvetHesapla(int taban, int kuvvet) {
		long birikenCarpim = 1; // Carpma islemine notr elemandan basliyoruz

		int sayac = 0;
		// kuvvet kadar donerek tabani kendisiyle carpiyoruz
		while (sayac < kuvvet) {
			birikenCarpim = birikenCarpim * taban;
			sayac++;
		}

		return birikenCarpim;
	}

	public static void main(String[] args) {

		Scanner giris = new Scanner(System.in);

		System.out.println("Lutfen tabani giriniz:");
		int taban = giris.nextInt();

		System.out.println("Lutfen ussu giriniz:");
		int us = giris.nextInt();

		UsAlma hesaplayici = new UsAlma();
		long sonuc = hesaplayici.kuvvetHesapla(taban, us);

		System.out.println("Sonuc = " + sonuc);

		giris.close();
	}
}

package com.thealgorithms.datastructures.trees;

/*
* Avl is algo that balance itself while adding new values to tree
* by rotating branches of binary tree and make itself Binary seaarch tree
* there are four cases which has to tackle
* rotating - left right ,left left,right right,right left

Test Case:

AVLTree tree=new AVLTree();
                tree.insert(20);
                tree.insert(25);
                tree.insert(30);
                tree.insert(10);
                tree.insert(5);
                tree.insert(15);
                tree.insert(27);
                tree.insert(19);
                tree.insert(16);

                tree.display();




*/

public class AVLSimple {

    private class Node {

        int data;
        int height;
        Node left;
        Node right;

        Node(int data) {
            this.data = data;
            this.height = 1;
        }
    }

    private Node root;

    public void insert(int data) {
        this.root = insert(this.root, data);
    }

    private Node insert(Node node, int item) {
        if (node == null) {
            return new Node(item);
        }
        if (node.data > item) {
            node.left = insert(node.left, item);
        }
        if (node.data < item) {
            node.right = insert(node.right, item);
        }
        node.height = Math.max(height(node.left), height(node.right)) + 1;
        int bf = bf(node);
        // LL case
        if (bf > 1 && item < node.left.data) {
            return rightRotate(node);
        }
        // RR case
        if (bf < -1 && item > node.right.data) {
            return leftRotate(node);
        }
        // RL case
        if (bf < -1 && item < node.right.data) {
            node.right = rightRotate(node.right);
            return leftRotate(node);
        }
        // LR case
        if (bf > 1 && item > node.left.data) {
            node.left = leftRotate(node.left);
            return rightRotate(node);
        }

        return node;
    }

    public void display() {
        this.display(this.root);
        System.out.println(this.root.height);
    }

    private void display(Node node) {
        String str = "";
        if (node.left != null) {
            str += node.left.data + "=>";
        } else {
            str += "END=>";
        }
        str += node.data + "";
        if (node.right != null) {
            str += "<=" + node.right.data;
        } else {
            str += "<=END";
        }
        System.out.println(str);
        if (node.left != null) {
            display(node.left);
        }
        if (node.right != null) {
            display(node.right);
        }
    }

    private int height(Node node) {
        if (node == null) {
            return 0;
        }
        return node.height;
    }

    private int bf(Node node) {
        if (node == null) {
            return 0;
        }
        return height(node.left) - height(node.right);
    }

    private Node rightRotate(Node c) {
        Node b = c.left;
        Node t3 = b.right;

        b.right = c;
        c.left = t3;
        c.height = Math.max(height(c.left), height(c.right)) + 1;
        b.height = Math.max(height(b.left), height(b.right)) + 1;
        return b;
    }

    private Node leftRotate(Node c) {
        Node b = c.right;
        Node t3 = b.left;

        b.left = c;
        c.right = t3;
        c.height = Math.max(height(c.left), height(c.right)) + 1;
        b.height = Math.max(height(b.left), height(b.right)) + 1;
        return b;
    }
}

/**
 * A DynamicProgramming based solution for Edit Distance problem In Java
 * Description of Edit Distance with an Example:
 *
 * <p>
 * Edit distance is a way of quantifying how dissimilar two strings (e.g.,
 * words) are to one another, by counting the minimum number of operations
 * required to transform one string into the other. The distance operations are
 * the removal, insertion, or substitution of a character in the string.
 *
 * <p>
 *
 * <p>
 * The Distance between "kitten" and "sitting" is 3. A minimal edit script that
 * transforms the former into the latter is:
 *
 * <p>
 * kitten → sitten (substitution of "s" for "k") sitten → sittin (substitution
 * of "i" for "e") sittin → sitting (insertion of "g" at the end).
 *
 * @author SUBHAM SANGHAI
 */
public final class EditDistance {
    private EditDistance() {
    }

    public static int minDistance(String word1, String word2) {
        int len1 = word1.length();
        int len2 = word2.length();
        // len1+1, len2+1, because finally return dp[len1][len2]
        int[][] dp = new int[len1 + 1][len2 + 1];
        /* If second string is empty, the only option is to
    insert all characters of first string into second*/
        for (int i = 0; i <= len1; i++) {
            dp[i][0] = i;
        }
        /* If first string is empty, the only option is to
    insert all characters of second string into first*/
        for (int j = 0; j <= len2; j++) {
            dp[0][j] = j;
        }
        // iterate though, and check last char
        for (int i = 0; i < len1; i++) {
            char c1 = word1.charAt(i);
            for (int j = 0; j < len2; j++) {
                char c2 = word2.charAt(j);
                // if last two chars equal
                if (c1 == c2) {
                    // update dp value for +1 length
                    dp[i + 1][j + 1] = dp[i][j];
                } else {
                    /* if two characters are different ,
          then take the minimum of the various operations(i.e insertion,removal,substitution)*/
                    int replace = dp[i][j] + 1;
                    int insert = dp[i][j + 1] + 1;
                    int delete = dp[i + 1][j] + 1;

                    int min = Math.min(replace, insert);
                    min = Math.min(delete, min);
                    dp[i + 1][j + 1] = min;
                }
            }
        }
        /* return the final answer , after traversing through both the strings*/
        return dp[len1][len2];
    }

    // edit distance problem
    public static int editDistance(String s1, String s2) {
        int[][] storage = new int[s1.length() + 1][s2.length() + 1];
        return editDistance(s1, s2, storage);
    }

    public static int editDistance(String s1, String s2, int[][] storage) {
        int m = s1.length();
        int n = s2.length();
        if (storage[m][n] > 0) {
            return storage[m][n];
        }
        if (m == 0) {
            storage[m][n] = n;
            return storage[m][n];
        }
        if (n == 0) {
            storage[m][n] = m;
            return storage[m][n];
        }
        if (s1.charAt(0) == s2.charAt(0)) {
            storage[m][n] = editDistance(s1.substring(1), s2.substring(1), storage);
        } else {
            int op1 = editDistance(s1, s2.substring(1), storage);
            int op2 = editDistance(s1.substring(1), s2, storage);
            int op3 = editDistance(s1.substring(1), s2.substring(1), storage);
            storage[m][n] = 1 + Math.min(op1, Math.min(op2, op3));
        }
        return storage[m][n];
    }
}

