/*
 * Randomized maze generator.
 *
 * This class fills a 2D grid with either wall cells ('#') or open path
 * cells ('.') using a simple probability check for each position, then
 * prints the resulting grid to standard output.
 */

public class Labirent {

    private static final int COLUMN_COUNT = 10;      // how many columns the grid has
    private static final int ROW_COUNT = 10;          // how many rows the grid has
    private static final char WALL_SYMBOL = '#';       // symbol used for blocked cells
    private static final char PATH_SYMBOL = '.';       // symbol used for open cells
    private static final double WALL_CHANCE = 0.3;     // probability a cell becomes a wall

    private static char[][] grid; // holds the generated maze layout

    public static void main(String[] args) {
        grid = buildRandomGrid();
        renderGrid();
    }

    // Builds a grid where each cell is randomly chosen to be a wall or a path.
    private static char[][] buildRandomGrid() {
        Random randomizer = new Random();
        char[][] freshGrid = new char[ROW_COUNT][COLUMN_COUNT];

        for (int row = 0; row < ROW_COUNT; row++) {
            for (int col = 0; col < COLUMN_COUNT; col++) {
                boolean isWall = randomizer.nextDouble() < WALL_CHANCE;
                freshGrid[row][col] = isWall ? WALL_SYMBOL : PATH_SYMBOL;
            }
        }

        return freshGrid;
    }

    // Prints every row of the grid, separating cells with a single space.
    private static void renderGrid() {
        StringBuilder lineBuffer;
        for (int row = 0; row < ROW_COUNT; row++) {
            lineBuffer = new StringBuilder();
            for (int col = 0; col < COLUMN_COUNT; col++) {
                lineBuffer.append(grid[row][col]).append(' ');
            }
            System.out.println(lineBuffer.toString().trim());
        }
    }
}

package com.thealgorithms.bitmanipulation;

/**
 * Utility class for performing circular bit rotations on 32-bit integers.
 * Bit rotation is a circular shift operation where bits shifted out on one end
 * are reinserted on the opposite end.
 *
 * <p>This class provides methods for both left and right circular rotations,
 * supporting only 32-bit integer operations with proper shift normalization
 * and error handling.</p>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Bit_rotation">Bit Rotation</a>
 */
public final class BitRotate {

    /**
     * Private constructor to prevent instantiation.
     * This is a utility class with only static methods.
     */
    private BitRotate() {
        throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
    }

    /**
     * Performs a circular left rotation (left shift) on a 32-bit integer.
     * Bits shifted out from the left side are inserted on the right side.
     *
     * @param value the 32-bit integer value to rotate
     * @param shift the number of positions to rotate left (must be non-negative)
     * @return the result of left rotating the value by the specified shift amount
     * @throws IllegalArgumentException if shift is negative
     *
     * @example
     * // Binary: 10000000 00000000 00000000 00000001
     * rotateLeft(0x80000001, 1)
     * // Returns: 3 (binary: 00000000 00000000 00000000 00000011)
     */
    public static int rotateLeft(int value, int shift) {
        if (shift < 0) {
            throw new IllegalArgumentException("Shift amount cannot be negative: " + shift);
        }

        // Normalize shift to the range [0, 31] using modulo 32
        shift = shift % 32;

        if (shift == 0) {
            return value;
        }

        // Left rotation: (value << shift) | (value >>> (32 - shift))
        return (value << shift) | (value >>> (32 - shift));
    }

    /**
     * Performs a circular right rotation (right shift) on a 32-bit integer.
     * Bits shifted out from the right side are inserted on the left side.
     *
     * @param value the 32-bit integer value to rotate
     * @param shift the number of positions to rotate right (must be non-negative)
     * @return the result of right rotating the value by the specified shift amount
     * @throws IllegalArgumentException if shift is negative
     *
     * @example
     * // Binary: 00000000 00000000 00000000 00000011
     * rotateRight(3, 1)
     * // Returns: -2147483647 (binary: 10000000 00000000 00000000 00000001)
     */
    public static int rotateRight(int value, int shift) {
        if (shift < 0) {
            throw new IllegalArgumentException("Shift amount cannot be negative: " + shift);
        }

        // Normalize shift to the range [0, 31] using modulo 32
        shift = shift % 32;

        if (shift == 0) {
            return value;
        }

        // Right rotation: (value >>> shift) | (value << (32 - shift))
        return (value >>> shift) | (value << (32 - shift));
    }
}

public class StringReverser {
    // Reverses a string without using StringBuilder
    public static String reverse(String input) {
        char[] characters = input.toCharArray();
        int left = 0;
        int right = characters.length - 1;
        while (left < right) {
            char temp = characters[left];
            characters[left] = characters[right];
            characters[right] = temp;
            left++;
            right--;
        }
        return new String(characters);
    }

    public static void main(String[] args) {
        String original = "Hello, Java!";
        System.out.println("Original: " + original);
        System.out.println("Reversed: " + reverse(original));
    }
}

package com.thealgorithms.datastructures.graphs;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;

/**
 * AStar class implements the A* pathfinding algorithm to find the shortest path in a graph.
 * The graph is represented using an adjacency list, and the algorithm uses a heuristic to estimate
 * the cost to reach the destination node.
 * Time Complexity = O(E), where E is equal to the number of edges
 */
public final class AStar {
    private AStar() {
    }

    /**
     * Represents a graph using an adjacency list.
     */
    static class Graph {
        private ArrayList<ArrayList<Edge>> graph;

        Graph(int size) {
            this.graph = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                this.graph.add(new ArrayList<>());
            }
        }

        private ArrayList<Edge> getNeighbours(int from) {
            return this.graph.get(from);
        }

        // Add a bidirectional edge to the graph
        private void addEdge(Edge edge) {
            this.graph.get(edge.getFrom()).add(new Edge(edge.getFrom(), edge.getTo(), edge.getWeight()));
            this.graph.get(edge.getTo()).add(new Edge(edge.getTo(), edge.getFrom(), edge.getWeight()));
        }
    }

    /**
     * Represents an edge in the graph with a start node, end node, and weight.
     */
    private static class Edge {
        private int from;
        private int to;
        private int weight;

        Edge(int from, int to, int weight) {
            this.from = from;
            this.to = to;
            this.weight = weight;
        }

        public int getFrom() {
            return from;
        }

        public int getTo() {
            return to;
        }

        public int getWeight() {
            return weight;
        }
    }

    /**
     * Contains information about the path and its total distance.
     */
    static class PathAndDistance {
        private int distance; // total distance from the start node
        private ArrayList<Integer> path; // list of nodes in the path
        private int estimated; // heuristic estimate for reaching the destination

        PathAndDistance(int distance, ArrayList<Integer> path, int estimated) {
            this.distance = distance;
            this.path = path;
            this.estimated = estimated;
        }

        public int getDistance() {
            return distance;
        }

        public ArrayList<Integer> getPath() {
            return path;
        }

        public int getEstimated() {
            return estimated;
        }
    }

    // Initializes the graph with edges defined in the input data
    static void initializeGraph(Graph graph, List<Integer> data) {
        for (int i = 0; i < data.size(); i += 4) {
            graph.addEdge(new Edge(data.get(i), data.get(i + 1), data.get(i + 2)));
        }
    }

    /**
     * Implements the A* pathfinding algorithm to find the shortest path from a start node to a destination node.
     *
     * @param from     the starting node
     * @param to       the destination node
     * @param graph    the graph representation of the problem
     * @param heuristic the heuristic estimates for each node
     * @return a PathAndDistance object containing the shortest path and its distance
     */
    public static PathAndDistance aStar(int from, int to, Graph graph, int[] heuristic) {
        // PriorityQueue to explore nodes based on their distance and estimated cost to reach the destination
        PriorityQueue<PathAndDistance> queue = new PriorityQueue<>(Comparator.comparingInt(a -> (a.getDistance() + a.getEstimated())));

        // Start with the initial node
        queue.add(new PathAndDistance(0, new ArrayList<>(List.of(from)), heuristic[from]));

        boolean solutionFound = false;
        PathAndDistance currentData = new PathAndDistance(-1, null, -1);

        while (!queue.isEmpty() && !solutionFound) {
            currentData = queue.poll(); // get the best node from the queue
            int currentPosition = currentData.getPath().get(currentData.getPath().size() - 1); // current node

            // Check if the destination has been reached
            if (currentPosition == to) {
                solutionFound = true;
            } else {
                for (Edge edge : graph.getNeighbours(currentPosition)) {
                    // Avoid cycles by checking if the next node is already in the path
                    if (!currentData.getPath().contains(edge.getTo())) {
                        ArrayList<Integer> updatedPath = new ArrayList<>(currentData.getPath());
                        updatedPath.add(edge.getTo());

                        // Update the distance and heuristic for the new path
                        queue.add(new PathAndDistance(currentData.getDistance() + edge.getWeight(), updatedPath, heuristic[edge.getTo()]));
                    }
                }
            }
        }
        return (solutionFound) ? currentData : new PathAndDistance(-1, null, -1);
    }
}

package workshop6;

/**
 * A student record comparable by mark (descending).
 */
public class Student implements Comparable<Student> {
    String code;
    String name;
    int mark;

    public Student() {
        code = "";
        name = "";
        mark = 0;
    }

    public Student(String code, String name, int mark) {
        this.code = code.toUpperCase();
        this.name = name.toUpperCase();
        this.mark = (mark >= 0 && mark <= 10) ? mark : 0;
    }

    public String getCode() {
        return code;
    }

    public void setCode(String code) {
        this.code = code;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        if (name.length() > 0) {
            this.name = name.trim().toUpperCase();
        }
    }

    public int getMark() {
        return mark;
    }

    public void setMark(int mark) {
        this.mark = (mark >= 0 && mark <= 10) ? mark : 0;
    }

    @Override
    public String toString() {
        return code + ", " + name + ", " + mark;
    }

    @Override
    public int compareTo(Student other) {
        return -(mark - other.getMark());
    }
}

