//        // Example 3: Reading from a file using BufferedReader (commented)
//        try (BufferedReader fileBufferedReader = new BufferedReader(new FileReader("note.txt"))) {
//            while (fileBufferedReader.readLine() != null) {
//                System.out.println(fileBufferedReader.readLine());
//            }
//        } catch (IOException error) {
//            System.out.println(error.getMessage());
//        }

        // Section: Output Writers and Byte Streams

        OutputStream byteOutputStream = System.out;
//      byteOutputStream.write(😘); // emoji exceeds byte range (0-255), causes compilation error
        byteOutputStream.write(10); // ASCII 10 corresponds to newline character

        // Example: OutputStreamWriter converts character stream to byte stream
        try(OutputStreamWriter characterToByteWriter = new OutputStreamWriter(System.out)) {
            characterToByteWriter.write("Hello World \n");
            characterToByteWriter.write(97);  // 'a' in ASCII
            characterToByteWriter.write("\n");
            char[] characterArray = "Hello World".toCharArray();
            characterToByteWriter.write(characterArray);
            characterToByteWriter.write("😘");  // Unicode emoji
            characterToByteWriter.write(10);   // newline character
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }

        // Appending to a file using FileWriter
        try(FileWriter fileWriter = new FileWriter("note.txt", true)) {
            fileWriter.write(" I am currently in my 4th semester");
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }

        // Writing to a file using BufferedWriter
        try(BufferedWriter bufferedFileWriter = new BufferedWriter(new FileWriter("note.txt"))) {
            bufferedFileWriter.write("Hare Krishna");
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }
    }

/*
Important Note: Keyboard input (System.in) provides byte-based data. InputStreamReader converts this byte stream
into a character stream so that BufferedReader can read it line by line using readLine().
Character stream classes cannot directly handle byte input without this conversion.
 */
}

package com.thealgorithms.graph;

import java.util.Arrays;

/**
 * Hungarian algorithm (a.k.a. Kuhn–Munkres) for the Assignment Problem.
 *
 * <p>Given an n x m cost matrix (n tasks, m workers), finds a minimum-cost
 * one-to-one assignment. If the matrix is rectangular, the algorithm pads to a
 * square internally. Costs must be finite non-negative integers.
 *
 * <p>Time complexity: O(n^3) with n = max(rows, cols).
 *
 * <p>API returns the assignment as an array where {@code assignment[i]} is the
 * column chosen for row i (or -1 if unassigned when rows != cols), and a total
 * minimal cost.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Hungarian_algorithm">Wikipedia: Hungarian algorithm</a>
 */
public final class HungarianAlgorithm {

    private HungarianAlgorithm() {
    }

    /** Result holder for the Hungarian algorithm. */
    public static final class Result {
        public final int[] assignment; // assignment[row] = col or -1
        public final int minCost;

        public Result(int[] assignment, int minCost) {
            this.assignment = assignment;
            this.minCost = minCost;
        }
    }

    /**
     * Solves the assignment problem for a non-negative cost matrix.
     *
     * @param cost an r x c matrix of non-negative costs
     * @return Result with row-to-column assignment and minimal total cost
     * @throws IllegalArgumentException for null/empty or negative costs
     */
    public static Result solve(int[][] cost) {
        validate(cost);
        int rows = cost.length;
        int cols = cost[0].length;
        int n = Math.max(rows, cols);

        // Build square matrix with padding 0 for missing cells
        int[][] a = new int[n][n];
        for (int i = 0; i < n; i++) {
            if (i < rows) {
                for (int j = 0; j < n; j++) {
                    a[i][j] = (j < cols) ? cost[i][j] : 0;
                }
            } else {
                Arrays.fill(a[i], 0);
            }
        }

        // Potentials and matching arrays
        int[] u = new int[n + 1];
        int[] v = new int[n + 1];
        int[] p = new int[n + 1];
        int[] way = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            p[0] = i;
            int j0 = 0;
            int[] minv = new int[n + 1];
            boolean[] used = new boolean[n + 1];
            Arrays.fill(minv, Integer.MAX_VALUE);
            Arrays.fill(used, false);
            do {
                used[j0] = true;
                int i0 = p[j0];
                int delta = Integer.MAX_VALUE;
                int j1 = 0;
                for (int j = 1; j <= n; j++) {
                    if (!used[j]) {
                        int cur = a[i0 - 1][j - 1] - u[i0] - v[j];
                        if (cur < minv[j]) {
                            minv[j] = cur;
                            way[j] = j0;
                        }
                        if (minv[j] < delta) {
                            delta = minv[j];
                            j1 = j;
                        }
                    }
                }
                for (int j = 0; j <= n; j++) {
                    if (used[j]) {
                        u[p[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }
                j0 = j1;
            } while (p[j0] != 0);
            do {
                int j1 = way[j0];
                p[j0] = p[j1];
                j0 = j1;
            } while (j0 != 0);
        }

        int[] matchColForRow = new int[n];
        Arrays.fill(matchColForRow, -1);
        for (int j = 1; j <= n; j++) {
            if (p[j] != 0) {
                matchColForRow[p[j] - 1] = j - 1;
            }
        }

        // Build assignment for original rows only, ignore padded rows
        int[] assignment = new int[rows];
        Arrays.fill(assignment, -1);
        int total = 0;
        for (int i = 0; i < rows; i++) {
            int j = matchColForRow[i];
            if (j >= 0 && j < cols) {
                assignment[i] = j;
                total += cost[i][j];
            }
        }
        return new Result(assignment, total);
    }

    private static void validate(int[][] cost) {
        if (cost == null || cost.length == 0) {
            throw new IllegalArgumentException("Cost matrix must not be null or empty");
        }
        int c = cost[0].length;
        if (c == 0) {
            throw new IllegalArgumentException("Cost matrix must have at least 1 column");
        }
        for (int i = 0; i < cost.length; i++) {
            if (cost[i] == null || cost[i].length != c) {
                throw new IllegalArgumentException("Cost matrix must be rectangular with equal row lengths");
            }
            for (int j = 0; j < c; j++) {
                if (cost[i][j] < 0) {
                    throw new IllegalArgumentException("Costs must be non-negative");
                }
            }
        }
    }
}

package com.thealgorithms.dynamicprogramming;

/**
 * The WineProblem class provides a solution to the wine selling problem.
 * Given a collection of N wines with different prices, the objective is to maximize profit by selling
 * one wine each year, considering the constraint that only the leftmost or rightmost wine can be sold
 * at any given time.
 *
 * The price of the ith wine is pi, and the selling price increases by a factor of the year in which
 * it is sold. This class implements three approaches to solve the problem:
 *
 * 1. **Recursion**: A straightforward recursive method that computes the maximum profit.
 *    - Time Complexity: O(2^N)
 *    - Space Complexity: O(N) due to recursive calls.
 *
 * 2. **Top-Down Dynamic Programming (Memoization)**: This approach caches the results of subproblems
 *    to avoid redundant computations.
 *    - Time Complexity: O(N^2)
 *    - Space Complexity: O(N^2) for the storage of results and O(N) for recursion stack.
 *
 * 3. **Bottom-Up Dynamic Programming (Tabulation)**: This method builds a table iteratively to
 *    compute the maximum profit for all possible subproblems.
 *    - Time Complexity: O(N^2)
 *    - Space Complexity: O(N^2) for the table.
 */
public final class WineProblem {
    private WineProblem() {
    }

    /**
     * Calculate maximum profit using recursion.
     *
     * @param arr Array of wine prices.
     * @param si  Start index of the wine to consider.
     * @param ei  End index of the wine to consider.
     * @return Maximum profit obtainable by selling the wines.
     */
    public static int wpRecursion(int[] arr, int si, int ei) {
        int n = arr.length;
        int year = (n - (ei - si + 1)) + 1;
        if (si == ei) {
            return arr[si] * year;
        }

        int start = wpRecursion(arr, si + 1, ei) + arr[si] * year;
        int end = wpRecursion(arr, si, ei - 1) + arr[ei] * year;

        return Math.max(start, end);
    }

    /**
     * Calculate maximum profit using top-down dynamic programming with memoization.
     *
     * @param arr  Array of wine prices.
     * @param si   Start index of the wine to consider.
     * @param ei   End index of the wine to consider.
     * @param strg 2D array to store results of subproblems.
     * @return Maximum profit obtainable by selling the wines.
     */
    public static int wptd(int[] arr, int si, int ei, int[][] strg) {
        int n = arr.length;
        int year = (n - (ei - si + 1)) + 1;
        if (si == ei) {
            return arr[si] * year;
        }

        if (strg[si][ei] != 0) {
            return strg[si][ei];
        }
        int start = wptd(arr, si + 1, ei, strg) + arr[si] * year;
        int end = wptd(arr, si, ei - 1, strg) + arr[ei] * year;

        int ans = Math.max(start, end);
        strg[si][ei] = ans;

        return ans;
    }

    /**
     * Calculate maximum profit using bottom-up dynamic programming with tabulation.
     *
     * @param arr Array of wine prices.
     * @throws IllegalArgumentException if the input array is null or empty.
     * @return Maximum profit obtainable by selling the wines.
     */
    public static int wpbu(int[] arr) {
        if (arr == null || arr.length == 0) {
            throw new IllegalArgumentException("Input array cannot be null or empty.");
        }
        int n = arr.length;
        int[][] strg = new int[n][n];

        for (int slide = 0; slide <= n - 1; slide++) {
            for (int si = 0; si <= n - slide - 1; si++) {
                int ei = si + slide;
                int year = (n - (ei - si + 1)) + 1;
                if (si == ei) {
                    strg[si][ei] = arr[si] * year;
                } else {
                    int start = strg[si + 1][ei] + arr[si] * year;
                    int end = strg[si][ei - 1] + arr[ei] * year;

                    strg[si][ei] = Math.max(start, end);
                }
            }
        }
        return strg[0][n - 1];
    }
}

