package com.thealgorithms.ciphers.a5;

import java.util.BitSet;

public class LFSR implements BaseLFSR {

private final BitSet internalRegister;
private final int registerLength;
private final int clockBitPosition;
private final int[] tapBitPositions;

public LFSR(int lengthValue, int clockPosition, int[] tapPositions) {
this.registerLength = lengthValue;
this.clockBitPosition = clockPosition;
this.tapBitPositions = tapPositions;
internalRegister = new BitSet(lengthValue);
}

@Override
public void initialize(BitSet keyData, BitSet frameData) {
internalRegister.clear();
loadBits(keyData, SESSION_KEY_LENGTH);
loadBits(frameData, FRAME_COUNTER_LENGTH);
}

private void loadBits(BitSet sourceData, int dataLength) {
for (int position = dataLength - 1; position >= 0; --position) {
boolean newBitValue = sourceData.get(position) ^ computeXorTap();
shiftAndInsert(newBitValue);
}
}

@Override
public boolean clock() {
return shiftAndInsert(computeXorTap());
}

public boolean getClockBit() {
return internalRegister.get(clockBitPosition);
}

public boolean get(int bitPosition) {
return internalRegister.get(bitPosition);
}

public boolean getLastBit() {
return internalRegister.get(registerLength - 1);
}

private boolean computeXorTap() {
boolean xorResult = false;
for (int tapPosition : tapBitPositions) {
xorResult ^= internalRegister.get(tapPosition);
}
return xorResult;
}

private boolean shiftAndInsert(boolean inputBit) {
boolean droppedBit = shiftRight();
internalRegister.set(0, inputBit);
return droppedBit;
}

private boolean shiftRight() {
boolean discarded = get(registerLength - 1);
for (int index = registerLength - 1; index > 0; --index) {
internalRegister.set(index, get(index - 1));
}
internalRegister.set(0, false);
return discarded;
}

@Override
public String toString() {
return internalRegister.toString();
}
}

/**
 * Given tree is traversed in a 'post-order' way: LEFT -> RIGHT -> ROOT.
 * Below are given the recursive and iterative implementations.
 * <p>
 * Complexities:
 * Recursive: O(n) - time, O(n) - space, where 'n' is the number of nodes in a tree.
 * <p>
 * Iterative: O(n) - time, O(h) - space, where 'n' is the number of nodes in a tree
 * and 'h' is the height of a binary tree.
 * In the worst case 'h' can be O(n) if tree is completely unbalanced, for instance:
 * 5
 *  \
 *   6
 *    \
 *     7
 *      \
 *       8
 *
 * @author Albina Gimaletdinova on 21/02/2023
 */
public final class PostOrderTraversal {
    private PostOrderTraversal() {
    }
    public static List<Integer> recursivePostOrder(BinaryTree.Node root) {
        List<Integer> result = new ArrayList<>();
        recursivePostOrder(root, result);
        return result;
    }

    public static List<Integer> iterativePostOrder(BinaryTree.Node root) {
        LinkedList<Integer> result = new LinkedList<>();
        if (root == null) {
            return result;
        }

        Deque<BinaryTree.Node> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            BinaryTree.Node node = stack.pop();
            result.addFirst(node.data);
            if (node.left != null) {
                stack.push(node.left);
            }
            if (node.right != null) {
                stack.push(node.right);
            }
        }

        return result;
    }

    private static void recursivePostOrder(BinaryTree.Node root, List<Integer> result) {
        if (root == null) {
            return;
        }
        recursivePostOrder(root.left, result);
        recursivePostOrder(root.right, result);
        result.add(root.data);
    }
}

/**
 * A utility class to swap every pair of adjacent bits in a given integer.
 * This operation shifts the even-positioned bits to odd positions and vice versa.
 *
 * Example:
 * - Input: 2 (binary: `10`) → Output: 1 (binary: `01`)
 * - Input: 43 (binary: `101011`) → Output: 23 (binary: `010111`)
 *
 * **Explanation of the Algorithm:**
 * 1. Mask even-positioned bits: Using `0xAAAAAAAA` (binary: `101010...`),
 *    which selects bits in even positions.
 * 2. Mask odd-positioned bits: Using `0x55555555` (binary: `010101...`),
 *    which selects bits in odd positions.
 * 3. Shift bits:
 *    - Right-shift even-positioned bits by 1 to move them to odd positions.
 *    - Left-shift odd-positioned bits by 1 to move them to even positions.
 * 4. Combine both shifted results using bitwise OR (`|`) to produce the final result.
 *
 * Use Case: This algorithm can be useful in applications involving low-level bit manipulation,
 * such as encoding, data compression, or cryptographic transformations.
 *
 * Time Complexity: O(1) (constant time, since operations are bitwise).
 *
 * Author: Lakshyajeet Singh Goyal (https://github.com/DarkMatter-999)
 */
public final class SwapAdjacentBits {
    private SwapAdjacentBits() {
    }

    /**
     * Swaps every pair of adjacent bits of a given integer.
     * Steps:
     * 1. Mask the even-positioned bits.
     * 2. Mask the odd-positioned bits.
     * 3. Shift the even bits to the right and the odd bits to the left.
     * 4. Combine the shifted bits.
     *
     * @param num the integer whose bits are to be swapped
     * @return the integer after swapping every pair of adjacent bits
     */
    public static int swapAdjacentBits(int num) {
        // mask the even bits (0xAAAAAAAA => 10101010...)
        int evenBits = num & 0xAAAAAAAA;

        // mask the odd bits (0x55555555 => 01010101...)
        int oddBits = num & 0x55555555;

        // right shift even bits and left shift odd bits
        evenBits >>= 1;
        oddBits <<= 1;

        // combine shifted bits
        return evenBits | oddBits;
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.Arrays;

/**
 * 0/1 Knapsack Problem - Dynamic Programming solution.
 *
 * This algorithm solves the classic optimization problem where we have n items,
 * each with a weight and a value. The goal is to maximize the total value
 * without exceeding the knapsack's weight capacity.
 *
 * Time Complexity: O(n * W)
 * Space Complexity: O(W)
 *
 * Example:
 * values = {60, 100, 120}
 * weights = {10, 20, 30}
 * W = 50
 * Output: 220
 *
 * @author Arpita
 * @see <a href="https://en.wikipedia.org/wiki/Knapsack_problem">Knapsack Problem</a>
 */
public final class Knapsack {

    private Knapsack() {
    }

    /**
     * Validates the input to ensure correct constraints.
     */
    private static void throwIfInvalidInput(final int weightCapacity, final int[] weights, final int[] values) {
        if (weightCapacity < 0) {
            throw new IllegalArgumentException("Weight capacity should not be negative.");
        }
        if (weights == null || values == null || weights.length != values.length) {
            throw new IllegalArgumentException("Weights and values must be non-null and of the same length.");
        }
        if (Arrays.stream(weights).anyMatch(w -> w <= 0)) {
            throw new IllegalArgumentException("Weights must be positive.");
        }
    }

    /**
     * Solves the 0/1 Knapsack problem using Dynamic Programming (bottom-up approach).
     *
     * @param weightCapacity The maximum weight capacity of the knapsack.
     * @param weights        The array of item weights.
     * @param values         The array of item values.
     * @return The maximum total value achievable without exceeding capacity.
     */
    public static int knapSack(final int weightCapacity, final int[] weights, final int[] values) {
        throwIfInvalidInput(weightCapacity, weights, values);

        int[] dp = new int[weightCapacity + 1];

        // Fill dp[] array iteratively
        for (int i = 0; i < values.length; i++) {
            for (int w = weightCapacity; w >= weights[i]; w--) {
                dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
            }
        }

        return dp[weightCapacity];
    }

    /*
    // Example main method for local testing only.
    public static void main(String[] args) {
        int[] values = {60, 100, 120};
        int[] weights = {10, 20, 30};
        int weightCapacity = 50;

        int maxValue = knapSack(weightCapacity, weights, values);
        System.out.println("Maximum value = " + maxValue); // Output: 220
    }
    */
}

public class Main {
    public static void main(String[] args) {

        // Step 1: Create a new file
        try{
            File newFile = new File("new-file.txt");
            newFile.createNewFile();
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }

        // Step 2: Write content into the file
        try{
            FileWriter fileWriter = new FileWriter("new-file.txt");
            fileWriter.write("सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज |\n" + "अहं त्वां सर्वपापेभ्यो मोक्षयिष्यामि मा शुच:");
            fileWriter.close();
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }

        // Step 3: Read the contents of the file
        try {
            BufferedReader bufferedReader = new BufferedReader(new FileReader("new-file.txt"));
            while (bufferedReader.ready()) {
                System.out.println(bufferedReader.readLine());
            }
        } catch (IOException error) {
            System.out.println(error.getMessage());
        }

        // Step 4: Create a temporary file and then delete it
        try{
