}

package com.thealgorithms.dynamicprogramming;

/**
 * A DynamicProgramming based solution for Edit Distance problem In Java
 * Description of Edit Distance with an Example:
 *
 * <p>
 * Edit distance is a way of quantifying how dissimilar two strings (e.g.,
 * words) are to one another, by counting the minimum number of operations
 * required to transform one string into the other. The distance operations are
 * the removal, insertion, or substitution of a character in the string.
 *
 * <p>
 *
 * <p>
 * The Distance between "kitten" and "sitting" is 3. A minimal edit script that
 * transforms the former into the latter is:
 *
 * <p>
 * kitten → sitten (substitution of "s" for "k") sitten → sittin (substitution
 * of "i" for "e") sittin → sitting (insertion of "g" at the end).
 *
 * @author SUBHAM SANGHAI
 */
public final class EditDistance {
    private EditDistance() {
    }

    public static int minDistance(String word1, String word2) {
        int len1 = word1.length();
        int len2 = word2.length();
        // len1+1, len2+1, because finally return dp[len1][len2]
        int[][] dp = new int[len1 + 1][len2 + 1];
        /* If second string is empty, the only option is to
    insert all characters of first string into second*/
        for (int i = 0; i <= len1; i++) {
            dp[i][0] = i;
        }
        /* If first string is empty, the only option is to
    insert all characters of second string into first*/
        for (int j = 0; j <= len2; j++) {
            dp[0][j] = j;
        }
        // iterate though, and check last char
        for (int i = 0; i < len1; i++) {
            char c1 = word1.charAt(i);
            for (int j = 0; j < len2; j++) {
                char c2 = word2.charAt(j);
                // if last two chars equal
                if (c1 == c2) {
                    // update dp value for +1 length
                    dp[i + 1][j + 1] = dp[i][j];
                } else {
                    /* if two characters are different ,
          then take the minimum of the various operations(i.e insertion,removal,substitution)*/
                    int replace = dp[i][j] + 1;
                    int insert = dp[i][j + 1] + 1;
                    int delete = dp[i + 1][j] + 1;

                    int min = Math.min(replace, insert);
                    min = Math.min(delete, min);
                    dp[i + 1][j + 1] = min;
                }
            }
        }
        /* return the final answer , after traversing through both the strings*/
        return dp[len1][len2];
    }

    // edit distance problem
    public static int editDistance(String s1, String s2) {
        int[][] storage = new int[s1.length() + 1][s2.length() + 1];
        return editDistance(s1, s2, storage);
    }

    public static int editDistance(String s1, String s2, int[][] storage) {
        int m = s1.length();
        int n = s2.length();
        if (storage[m][n] > 0) {
            return storage[m][n];
        }
        if (m == 0) {
            storage[m][n] = n;
            return storage[m][n];
        }
        if (n == 0) {
            storage[m][n] = m;
            return storage[m][n];
        }
        if (s1.charAt(0) == s2.charAt(0)) {
            storage[m][n] = editDistance(s1.substring(1), s2.substring(1), storage);
        } else {
            int op1 = editDistance(s1, s2.substring(1), storage);
            int op2 = editDistance(s1.substring(1), s2, storage);
            int op3 = editDistance(s1.substring(1), s2.substring(1), storage);
            storage[m][n] = 1 + Math.min(op1, Math.min(op2, op3));
        }
        return storage[m][n];
    }
}

package com.thealgorithms.conversions;

import java.math.BigDecimal;

/**
 A Java-based utility for converting numeric values into their English word
 representations. Whether you need to convert a small number, a large number
 with millions and billions, or even a number with decimal places, this utility
 has you covered.
 *
 */
public final class NumberToWords {

private NumberToWords() {
}

private static final String[] BASIC_UNITS = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"};
private static final String[] DECADE_NAMES = {"", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};
private static final String[] MAGNITUDE_SUFFIX = {"", "Thousand", "Million", "Billion", "Trillion"};
private static final String ZERO_TEXT = "Zero";
private static final String DECIMAL_MARKER = " Point";
private static final String NEGATIVE_PREFIX = "Negative ";

public static String convert(BigDecimal numericValue) {
if (numericValue == null) {
return "Invalid Input";
}
boolean hasNegativeSign = numericValue.signum() < 0;
BigDecimal[] integerFractionParts = numericValue.abs().divideAndRemainder(BigDecimal.ONE);
BigDecimal integerComponent = integerFractionParts[0];
String fractionComponent = integerFractionParts[1].compareTo(BigDecimal.ZERO) > 0 ? integerFractionParts[1].toPlainString().substring(2) : "";
StringBuilder outputText = new StringBuilder();
if (hasNegativeSign) {
outputText.append(NEGATIVE_PREFIX);
}
outputText.append(convertIntegerPart(integerComponent));
if (!fractionComponent.isEmpty()) {
outputText.append(DECIMAL_MARKER);
for (char digitChar : fractionComponent.toCharArray()) {
int digitValue = Character.getNumericValue(digitChar);
outputText.append(" ").append(digitValue == 0 ? ZERO_TEXT : BASIC_UNITS[digitValue]);
}
}
return outputText.toString().trim();
}

private static String convertIntegerPart(BigDecimal integerValue) {
if (integerValue.compareTo(BigDecimal.ZERO) == 0) {
return ZERO_TEXT;
}
StringBuilder wordResult = new StringBuilder();
int magnitudeIndex = 0;
BigDecimal remainingValue = integerValue;
while (remainingValue.compareTo(BigDecimal.ZERO) > 0) {
BigDecimal[] divisionResult = remainingValue.divideAndRemainder(BigDecimal.valueOf(1000));
int threeDigitGroup = divisionResult[1].intValue();
if (threeDigitGroup > 0) {
String groupWords = convertThreeDigitGroup(threeDigitGroup);
if (magnitudeIndex > 0) {
wordResult.insert(0, MAGNITUDE_SUFFIX[magnitudeIndex] + " ");
}
wordResult.insert(0, groupWords + " ");
}
remainingValue = divisionResult[0];
magnitudeIndex++;
}
return wordResult.toString().trim();
}

private static String convertThreeDigitGroup(int groupValue) {
String resultSegment;
if (groupValue < 20) {
resultSegment = BASIC_UNITS[groupValue];
} else if (groupValue < 100) {
resultSegment = DECADE_NAMES[groupValue / 10] + (groupValue % 10 > 0 ? " " + BASIC_UNITS[groupValue % 10] : "");
} else {
resultSegment = BASIC_UNITS[groupValue / 100] + " Hundred" + (groupValue % 100 > 0 ? " " + convertThreeDigitGroup(groupValue % 100) : "");
}
return resultSegment;
}
}

package com.thealgorithms.backtracking;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

/**
 * A class to solve a crossword puzzle using backtracking.
 * 
 * <p>This algorithm attempts to fill a crossword grid with given words
 * by trying different placements (horizontal/vertical) at empty positions
 * and backtracking when a placement leads to a dead end.</p>
 * 
 * <p><b>Example:</b>
 * <pre>
 * Input:
 *   puzzle = {
 *       {' ', ' ', ' '},
 *       {' ', ' ', ' '},
 *       {' ', ' ', ' '}
 *   }
 *   words = List.of("cat", "dog")
 *
 * Output (possible solution):
 *   {
 *       {'c', 'a', 't'},
 *       {' ', ' ', ' '},
 *       {'d', 'o', 'g'}
 *   }
 * </pre>
 * 
 * <p><b>Key Features:</b></p>
 * <ul>
 *   <li>Handles both horizontal and vertical word placement</li>
 *   <li>Uses backtracking to explore all possible placements</li>
 *   <li>Automatically determines optimal word placement order</li>
 *   <li>Preserves original puzzle structure</li>
 * </ul>
 * 
 * @see <a href="https://en.wikipedia.org/wiki/Crossword">Crossword Puzzle</a>
 * @see <a href="https://en.wikipedia.org/wiki/Backtracking">Backtracking Algorithm</a>
 */
public final class CrosswordSolver {

    // Private constructor to prevent instantiation (utility class)
    private CrosswordSolver() {
        throw new UnsupportedOperationException("This is a utility class and cannot be instantiated");
    }

    /**
     * Checks if a word can be placed at the specified position in the crossword.
     * 
     * <p>The placement is valid if:</p>
     * <ul>
     *   <li>The word fits within the puzzle boundaries</li>
     *   <li>All positions where the word would be placed are empty (' ')</li>
     *   <li>No existing letters conflict with the word</li>
     * </ul>
     *
     * @param puzzle The crossword puzzle represented as a 2D char array
     * @param word The word to be placed (must not be null or empty)
     * @param row The row index where the word might be placed (0-based)
     * @param col The column index where the word might be placed (0-based)
     * @param placeVertically If true, the word is placed vertically (top to bottom);
     *                        if false, placed horizontally (left to right)
     * @return true if the word can be placed at the specified position, false otherwise
     * @throws NullPointerException if puzzle or word is null
     * @throws IndexOutOfBoundsException if row or col is negative
     */
    public static boolean canPlaceWord(char[][] puzzle, String word, int row, int col, boolean placeVertically) {
        // Validate inputs
        if (puzzle == null || word == null) {
            throw new NullPointerException("Puzzle and word cannot be null");
        }
        if (row < 0 || col < 0) {
            throw new IndexOutOfBoundsException("Row and column indices must be non-negative");
        }
        if (word.isEmpty()) {
            return false; // Empty words cannot be placed
        }

        // Check boundaries and empty spaces
        for (int charIndex = 0; charIndex < word.length(); charIndex++) {
            if (placeVertically) {
                // Check vertical placement: moving down rows
                if (row + charIndex >= puzzle.length) {
                    return false; // Word extends beyond puzzle bottom
                }
                if (puzzle[row + charIndex][col] != ' ') {
                    return false; // Position already occupied
                }
            } else {
                // Check horizontal placement: moving right columns
                if (col + charIndex >= puzzle[0].length) {
                    return false; // Word extends beyond puzzle right edge
                }
                if (puzzle[row][col + charIndex] != ' ') {
                    return false; // Position already occupied
                }
            }
        }
        return true;
    }

    /**
     * Places a word at the specified position in the crossword.
     * 
     * <p>This method modifies the puzzle by filling in the characters of the word
     * at the given position and orientation. It assumes that {@link #canPlaceWord}
     * has been called and returned true.</p>
     *
     * @param puzzle The crossword puzzle represented as a 2D char array (modified in-place)
     * @param word The word to be placed
     * @param row The row index where the word will be placed
     * @param col The column index where the word will be placed
     * @param placeVertically If true, the word is placed vertically; otherwise, horizontally
     */
    public static void insertWord(char[][] puzzle, String word, int row, int col, boolean placeVertically) {
        for (int charIndex = 0; charIndex < word.length(); charIndex++) {
            if (placeVertically) {
                puzzle[row + charIndex][col] = word.charAt(charIndex);
            } else {
                puzzle[row][col + charIndex] = word.charAt(charIndex);
            }
        }
    }

    /**
     * Removes a word from the specified position in the crossword (backtracking step).
     * 
     * <p>This method clears the characters of the word by replacing them with empty spaces (' ').
     * It is used during backtracking to undo a previous placement.</p>
     *
     * @param puzzle The crossword puzzle represented as a 2D char array (modified in-place)
     * @param word The word to be removed (must be the same word that was placed)
     * @param row The row index where the word was placed
     * @param col The column index where the word was placed
     * @param placeVertically If true, the word was placed vertically; otherwise, horizontally
     */
    public static void eraseWord(char[][] puzzle, String word, int row, int col, boolean placeVertically) {
        for (int charIndex = 0; charIndex < word.length(); charIndex++) {
            if (placeVertically) {
                puzzle[row + charIndex][col] = ' ';
            } else {
                puzzle[row][col + charIndex] = ' ';
            }
        }
    }

    /**
     * Solves the crossword puzzle using backtracking.
     * 
     * <p>This is the main solving algorithm:</p>
     * <ol>
     *   <li>Find the first empty cell in the puzzle</li>
     *   <li>Try each remaining word in both horizontal and vertical orientations</li>
     *   <li>If a word can be placed, place it and recursively try to solve the rest</li>
     *   <li>If recursion fails, backtrack by removing the word and try another</li>
     *   <li>Continue until all empty cells are filled</li>
     * </ol>
     *
     * @param puzzle The crossword puzzle represented as a 2D char array (modified in-place)
     * @param availableWords The collection of words to be placed
     * @return true if the crossword is solved successfully, false otherwise
     */
    public static boolean fillCrossword(char[][] puzzle, Collection<String> availableWords) {
        // Create a mutable copy of the words list for backtracking
        List<String> remainingWords = new ArrayList<>(availableWords);

        // Find first empty cell
        for (int rowIndex = 0; rowIndex < puzzle.length; rowIndex++) {
            for (int colIndex = 0; colIndex < puzzle[0].length; colIndex++) {
                if (puzzle[rowIndex][colIndex] == ' ') {
                    // Try each remaining word at this empty cell
                    for (String currentWord : new ArrayList<>(remainingWords)) {
                        // Try both orientations
                        for (boolean placeVertically : new boolean[]{true, false}) {
                            if (canPlaceWord(puzzle, currentWord, rowIndex, colIndex, placeVertically)) {
                                // Place the word
                                insertWord(puzzle, currentWord, rowIndex, colIndex, placeVertically);
                                remainingWords.remove(currentWord);

                                // Recursively solve the rest of the puzzle
                                if (fillCrossword(puzzle, remainingWords)) {
                                    return true; // Success
                                }

                                // Backtrack: undo placement
                                remainingWords.add(currentWord);
                                eraseWord(puzzle, currentWord, rowIndex, colIndex, placeVertically);
                            }
                        }
                    }
                    return false; // No word can be placed at this cell → dead end
                }
            }
        }
        return true; // Puzzle completely filled
    }

    /**
     * Utility method to print the crossword puzzle in a readable format.
     *
     * @param puzzle The crossword puzzle to print
     */
    public static void printPuzzle(char[][] puzzle) {
        if (puzzle == null) {
            System.out.println("Puzzle is null");
            return;
        }

        System.out.println("Crossword Puzzle:");
        for (int rowIndex = 0; rowIndex < puzzle.length; rowIndex++) {
            for (int colIndex = 0; colIndex < puzzle[0].length; colIndex++) {
                System.out.print(puzzle[rowIndex][colIndex] + " ");
            }
            System.out.println();
        }
    }

    /**
     * Converts the crossword puzzle to a string representation.
     *
     * @param puzzle The crossword puzzle
     * @return String representation of the puzzle
     */
    public static String puzzleToString(char[][] puzzle) {
        if (puzzle == null) {
            return "null";
        }

        StringBuilder result = new StringBuilder();
        for (int rowIndex = 0; rowIndex < puzzle.length; rowIndex++) {
            for (int colIndex = 0; colIndex < puzzle[0].length; colIndex++) {
                result.append(puzzle[rowIndex][colIndex]);
                if (colIndex < puzzle[0].length - 1) {
                    result.append(" ");
                }
            }
            if (rowIndex < puzzle.length - 1) {
                result.append("\n");
            }
        }
        return result.toString();
    }
}

/*
COMPREHENSIVE DOCUMENTATION
===========================

ALGORITHM EXPLANATION
---------------------

How Crossword Solving Works:
===========================
1. Find the first empty cell (with space ' ')
2. Try placing every unused word in that cell horizontally and vertically
3. If placement is valid, place it and recurse
4. If recursion returns true, puzzle is solved
5. If recursion returns false, backtrack: remove the word and try another

Backtracking Tree Visualization (2x2 puzzle with 2 words):
=========================================================

                              start
                                |
                    +-----------+-----------+
                    |           |           |
                place "cat"   place "dog"   ... (other words)
                    H/V         H/V
                    |           |
            [c a t] ...     [d o g] ...
                    |           |
                find next    find next
                empty cell   empty cell
                    |           |
                place "dog"  place "cat"
                    |           |
                   ✓/✗          ✓/✗

LEGEND:
- H = Horizontal placement
- V = Vertical placement
- ✓ = Success
- ✗ = Failure (backtrack)

IMPORTANT ALGORITHM CHARACTERISTICS
===================================

| Feature | Description |
|---------|-------------|
| Search Strategy | Depth-First Search (DFS) with backtracking |
| Placement Order | First empty cell, first fit |
| Word Selection | Tries all remaining words |
| Orientation | Tries both horizontal and vertical |
| State Management | In-place mutation with backtracking |

COMPLEXITY ANALYSIS
===================

Time Complexity:
---------------
- Worst Case: O(W! × 2^W × N) where:
  * W = number of words
  * N = number of empty cells
  * 2^W = orientation combinations
  * W! = word permutations

- Space Complexity: O(W + N) where:
  * W = recursion stack depth
  * N = puzzle size for in-place modifications

MEMORY USAGE EXAMPLE
===================
Puzzle: 10×10 grid, 5 words
- Puzzle storage: 100 bytes
- Remaining words list: ~5 references
- Recursion stack: up to 5 levels
- Total: ~200 bytes + overhead

PRACTICAL APPLICATIONS
======================

1. Newspaper Crossword Generation
   - Automatically create crossword puzzles from word lists
   - Optimize for interlocking words

2. Word Game AI
   - Solver for Scrabble, Words With Friends
   - Find optimal word placements

3. Puzzle Game Development
   - Generate solvable crossword puzzles
   - Provide hint systems

4. Natural Language Processing
   - Word placement in constrained spaces
   - Grid-based text layout

5. Educational Software
   - Teach vocabulary through crossword puzzles
   - Auto-generate practice puzzles

COMMON OPTIMIZATIONS
===================

1. Word Length Heuristic:
   Try longer words first (they have fewer placement options)

2. Intersection Checking:
   When placing words, check intersection points with existing letters

3. Constraint Propagation:
   Pre-compute possible word positions before backtracking

4. Caching:
   Store previously attempted placements to avoid repetition

OPTIMIZED VERSION OF VALIDATION (with intersection support)
==========================================================

public static boolean canPlaceWordWithIntersections(char[][] puzzle, String word, 
                                                     int row, int col, boolean vertical) {
    for (int i = 0; i < word.length(); i++) {
        int r = vertical ? row + i : row;
        int c = vertical ? col : col + i;

        if (r >= puzzle.length || c >= puzzle[0].length) return false;

        char puzzleChar = puzzle[r][c];
        if (puzzleChar != ' ' && puzzleChar != word.charAt(i)) {
            return false; // Conflict with existing letter
        }
    }
    return true;
}

EDGE CASES AND LIMITATIONS
==========================

| Scenario | Behavior | Solution |
|----------|----------|----------|
| Empty puzzle | May always return true | Check if words list empty |
| Impossible puzzle | Returns false | Need to verify solvability |
| Words too long | Never placed | Filter words by max dimension |
| Single letter words | Works fine | Valid placement |
| No empty cells | Immediately returns true | Assuming all words placed |

DEBUGGING TIPS
==============

1. Print puzzle after each placement:
   System.out.println("Placed " + word + " at (" + row + ", " + col + ") " + 
                      (vertical ? "vertically" : "horizontally"));
   printPuzzle(puzzle);

2. Track backtracking steps:
   System.out.println("Backtracking: removing " + word);

3. Count recursion depth:
   private static int depth = 0;
   System.out.println("  ".repeat(depth) + "Trying " + word);

SAMPLE USAGE
===========

public static void main(String[] args) {
    // Create 3x3 crossword puzzle
    char[][] puzzle = {
        {' ', ' ', ' '},
        {' ', ' ', ' '},
        {' ', ' ', ' '}
    };

    // List of words to place
    List<String> words = List.of("cat", "dog", "bat");

    // Solve the puzzle
    if (fillCrossword(puzzle, words)) {
        System.out.println("Puzzle solved:");
        printPuzzle(puzzle);
    } else {
        System.out.println("No solution exists");
    }
}

RELATED ALGORITHMS
=================

1. Word Search - Find words in grid (different problem)
2. Sudoku Solver - Similar backtracking on grid
3. N-Queens - Backtracking with placement constraints
4. Knight's Tour - Path finding with backtracking
5. Boggle Solver - Word finding in random letters

FUTURE IMPROVEMENTS
==================

1. Add support for pre-filled letters
2. Implement constraint propagation for better performance
3. Add heuristic for word ordering (longest first)
4. Support for intersecting words validation
5. Add solution caching for multiple puzzles
6. Implement iterative version to avoid recursion depth limits
*/

