package syntax;

import java.util.Scanner;

public class KarsilastirmaIslemleri {

	public static void main(String[] args) {

		// Sayilar ile karsilastirma islemleri
		int sayi1 = 10; // sayi1 degiskeni 10 olarak atandi
		int sayi2 = 20; // sayi2 degiskeni 20 olarak atandi

		// Esitlik karsilastirmasi
		boolean esitMi = (sayi1 == sayi2); // sayi1, sayi2'ye esit mi kontrolu
		System.out.println("sayi1, sayi2'ye esit mi? " + esitMi); // false

		// Esit degil karsilastirmasi
		boolean esitDegilMi = (sayi1 != sayi2); // sayi1, sayi2'ye esit degil mi kontrolu
		System.out.println("sayi1, sayi2'ye esit degil mi? " + esitDegilMi); // true

		// Buyukluk karsilastirmasi
		boolean buyukMu = (sayi1 > sayi2); // sayi1, sayi2'den buyuk mu kontrolu
		System.out.println("sayi1, sayi2'den buyuk mu? " + buyukMu); // false

		// Kucukluk karsilastirmasi
		boolean kucukMu = (sayi1 < sayi2); // sayi1, sayi2'den kucuk mu kontrolu
		System.out.println("sayi1, sayi2'den kucuk mu? " + kucukMu); // true

		// Buyuk veya esit karsilastirmasi
		boolean buyukVeyaEsitMi = (sayi1 >= sayi2); // sayi1, sayi2'den buyuk veya esit mi kontrolu
		System.out.println("sayi1, sayi2'den buyuk veya esit mi? " + buyukVeyaEsitMi); // false

		// Kucuk veya esit karsilastirmasi
		boolean kucukVeyaEsitMi = (sayi1 <= sayi2); // sayi1, sayi2'den kucuk veya esit mi kontrolu
		System.out.println("sayi1, sayi2'den kucuk veya esit mi? " + kucukVeyaEsitMi); // true

		// Kullanici girdisi ile karsilastirma
		Scanner scanner = new Scanner(System.in);

		// Kullaniciya yasini sormak
		System.out.println("Lutfen yasinizi girin:");
		int kullaniciYasi = scanner.nextInt();

		// 18 yas ile karsilastirma
		boolean buyukMu18 = (kullaniciYasi > 18); // Kullanici 18 yasindan buyuk mu kontrolu
		System.out.println("Yasiniz 18'den buyuk mu? " + buyukMu18);

		// Kullaniciya ismini sormak
		System.out.println("Lutfen adinizi girin:");
		String kullaniciismi = scanner.next();

		// Kullanici ismi ile karsilastirma (ornegin, 'Ali' ile)
		boolean isimKontrol = kullaniciismi.equals("Ali"); // Kullanicinin ismi 'Ali' ile mi esit?
		System.out.println("Adiniz Ali mi? " + isimKontrol);

		// Kullanicidan bir sayi girmesini iste
		System.out.println("Lutfen 5 ile 15 arasinda bir sayi girin:");
		int kullaniciSayisi = scanner.nextInt();

		// Kullanici sayisi ile karsilastirma
		boolean sayiBuyuk = (kullaniciSayisi > 5); // Girilen sayi 5'ten buyuk mu?
		boolean sayiKucuk = (kullaniciSayisi < 15); // Girilen sayi 15'ten kucuk mu?
		System.out.println("Girilen sayi 5'ten buyuk mu? " + sayiBuyuk); // true/false
		System.out.println("Girilen sayi 15'ten kucuk mu? " + sayiKucuk); // true/false

		// Karakter karsilastirma
		System.out.println("Lutfen bir karakter girin:");
		char kullaniciKarakter = scanner.next().charAt(0); // Kullanicidan bir karakter al
		boolean karakterEsitMi = (kullaniciKarakter == 'A'); // Girilen karakter 'A' ile esit mi?
		System.out.println("Girilen karakter A mi? " + karakterEsitMi); // true/false

		scanner.close(); // Scanner'i kapat
	}
}

package com.thealgorithms.conversions;

import java.util.Locale;
import java.util.Map;

/**
 * A utility class to convert between different units of time.
 *
 * <p>This class supports conversions between the following units:
 * <ul>
 *   <li>seconds</li>
 *   <li>minutes</li>
 *   <li>hours</li>
 *   <li>days</li>
 *   <li>weeks</li>
 *   <li>months (approximated as 30.44 days)</li>
 *   <li>years (approximated as 365.25 days)</li>
 * </ul>
 *
 * <p>The conversion is based on predefined constants in seconds.
 * Results are rounded to three decimal places for consistency.
 *
 * <p>This class is final and cannot be instantiated.
 *
 * @see <a href="https://en.wikipedia.org/wiki/Unit_of_time">Wikipedia: Unit of time</a>
 */
public final class TimeConverter {

private TimeConverter() {
}

private enum TimeMeasurement {
SECONDS(1.0),
MINUTES(60.0),
HOURS(3600.0),
DAYS(86400.0),
WEEKS(604800.0),
MONTHS(2629800.0),
YEARS(31557600.0);

private final double baseSeconds;

TimeMeasurement(double baseSeconds) {
this.baseSeconds = baseSeconds;
}

public double toSeconds(double sourceValue) {
return sourceValue * baseSeconds;
}

public double fromSeconds(double secondsValue) {
return secondsValue / baseSeconds;
}
}

private static final Map<String, TimeMeasurement> UNIT_MAPPING = Map.ofEntries(
Map.entry("seconds", TimeMeasurement.SECONDS),
Map.entry("minutes", TimeMeasurement.MINUTES),
Map.entry("hours", TimeMeasurement.HOURS),
Map.entry("days", TimeMeasurement.DAYS),
Map.entry("weeks", TimeMeasurement.WEEKS),
Map.entry("months", TimeMeasurement.MONTHS),
Map.entry("years", TimeMeasurement.YEARS)
);

/**
 * Converts a time value from one unit to another.
 *
 * @param numericValue the numeric value of time to convert; must be non-negative
 * @param sourceUnit the unit of the input value (e.g., "minutes", "hours")
 * @param targetUnit the unit to convert into (e.g., "seconds", "days")
 * @return the converted value in the target unit, rounded to three decimals
 * @throws IllegalArgumentException if {@code numericValue} is negative
 * @throws IllegalArgumentException if either {@code sourceUnit} or {@code targetUnit} is not supported
 */
public static double convertTime(double numericValue, String sourceUnit, String targetUnit) {
if (numericValue < 0) {
throw new IllegalArgumentException("timeValue must be a non-negative number.");
}
TimeMeasurement sourceMeasurement = resolveUnit(sourceUnit);
TimeMeasurement targetMeasurement = resolveUnit(targetUnit);
double intermediateSeconds = sourceMeasurement.toSeconds(numericValue);
double convertedValue = targetMeasurement.fromSeconds(intermediateSeconds);
return Math.round(convertedValue * 1000.0) / 1000.0;
}

private static TimeMeasurement resolveUnit(String unitName) {
if (unitName == null) {
throw new IllegalArgumentException("Unit cannot be null.");
}
TimeMeasurement matchedUnit = UNIT_MAPPING.get(unitName.toLowerCase(Locale.ROOT));
if (matchedUnit == null) {
throw new IllegalArgumentException("Invalid unit '" + unitName + "'. Supported units are: " + UNIT_MAPPING.keySet());
}
return matchedUnit;
}
}

/**
 * The A5KeyStreamGenerator class is responsible for generating key streams
 * for the A5/1 encryption algorithm using a combination of Linear Feedback Shift Registers (LFSRs).
 *
 * <p>
 * This class extends the CompositeLFSR and initializes a set of LFSRs with
 * a session key and a frame counter to produce a pseudo-random key stream.
 * </p>
 *
 * <p>
 * Note: Proper exception handling for invalid usage is to be implemented.
 * </p>
 */
public class A5KeyStreamGenerator extends CompositeLFSR {

    private BitSet initialFrameCounter;
    private BitSet frameCounter;
    private BitSet sessionKey;
    private static final int INITIAL_CLOCKING_CYCLES = 100;
    private static final int KEY_STREAM_LENGTH = 228;

    /**
     * Initializes the A5KeyStreamGenerator with the specified session key and frame counter.
     *
     * <p>
     * This method sets up the internal state of the LFSRs using the provided
     * session key and frame counter. It creates three LFSRs with specific
     * configurations and initializes them.
     * </p>
     *
     * @param sessionKey a BitSet representing the session key used for key stream generation.
     * @param frameCounter a BitSet representing the frame counter that influences the key stream.
     */
    @Override
    public void initialize(BitSet sessionKey, BitSet frameCounter) {
        this.sessionKey = sessionKey;
        this.frameCounter = (BitSet) frameCounter.clone();
        this.initialFrameCounter = (BitSet) frameCounter.clone();
        registers.clear();
        LFSR lfsr1 = new LFSR(19, 8, new int[] {13, 16, 17, 18});
        LFSR lfsr2 = new LFSR(22, 10, new int[] {20, 21});
        LFSR lfsr3 = new LFSR(23, 10, new int[] {7, 20, 21, 22});
        registers.add(lfsr1);
        registers.add(lfsr2);
        registers.add(lfsr3);
        registers.forEach(lfsr -> lfsr.initialize(sessionKey, frameCounter));
    }

    /**
     * Re-initializes the key stream generator with the original session key
     * and frame counter. This method restores the generator to its initial
     * state.
     */
    public void reInitialize() {
        this.initialize(sessionKey, initialFrameCounter);
    }

    /**
     * Generates the next key stream of bits.
     *
     * <p>
     * This method performs an initial set of clocking cycles and then retrieves
     * a key stream of the specified length. After generation, it re-initializes
     * the internal registers.
     * </p>
     *
     * @return a BitSet containing the generated key stream bits.
     */
    public BitSet getNextKeyStream() {
        for (int cycle = 1; cycle <= INITIAL_CLOCKING_CYCLES; ++cycle) {
            this.clock();
        }

        BitSet result = new BitSet(KEY_STREAM_LENGTH);
        for (int cycle = 1; cycle <= KEY_STREAM_LENGTH; ++cycle) {
            boolean outputBit = this.clock();
            result.set(cycle - 1, outputBit);
        }

        reInitializeRegisters();
        return result;
    }

    /**
     * Re-initializes the registers for the LFSRs.
     *
     * <p>
     * This method increments the frame counter and re-initializes each LFSR
     * with the current session key and frame counter.
     * </p>
     */
    private void reInitializeRegisters() {
        incrementFrameCounter();
        registers.forEach(lfsr -> lfsr.initialize(sessionKey, frameCounter));
    }

    /**
     * Increments the current frame counter.
     *
     * <p>
     * This method uses a utility function to increment the frame counter,
     * which influences the key stream generation process.
     * </p>
     */
    private void incrementFrameCounter() {
        Utils.increment(frameCounter, FRAME_COUNTER_LENGTH);
    }

    /**
     * Retrieves the current frame counter.
     *
     * @return a BitSet representing the current state of the frame counter.
     */
    public BitSet getFrameCounter() {
        return frameCounter;
    }
}

