package com.thealgorithms.conversions;

/**
 * A utility class to convert integers into Roman numerals.
 *
 * <p>Roman numerals follow these rules:
 * <ul>
 *   <li>I = 1</li>
 *   <li>IV = 4</li>
 *   <li>V = 5</li>
 *   <li>IX = 9</li>
 *   <li>X = 10</li>
 *   <li>XL = 40</li>
 *   <li>L = 50</li>
 *   <li>XC = 90</li>
 *   <li>C = 100</li>
 *   <li>D = 500</li>
 *   <li>M = 1000</li>
 * </ul>
 *
 * <p>Conversion is based on repeatedly subtracting the largest possible Roman numeral value
 * from the input number until it reaches zero. For example, 1994 is converted as:
 * <pre>
 *   1994 -> MCMXCIV (1000 + 900 + 90 + 4)
 * </pre>
 */
public final class IntegerToRoman {

private static final int[] ARABIC_VALUES = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
private static final String[] ROMAN_SYMBOLS = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};

private IntegerToRoman() {
}

/**
 * Converts an integer to its Roman numeral representation.
 * Steps:
 * <ol>
 *     <li>Iterate over the Roman numeral values in descending order</li>
 *     <li>Calculate how many times a numeral fits</li>
 *     <li>Append the corresponding symbol</li>
 *     <li>Subtract the value from the number</li>
 *     <li>Repeat until the number is zero</li>
 *     <li>Return the Roman numeral representation</li>
 * </ol>
 *
 * @param inputNumber the integer value to convert (must be greater than 0)
 * @return the Roman numeral representation of the input integer
 *         or an empty string if the input is non-positive
 */
public static String integerToRoman(int inputNumber) {
if (inputNumber <= 0) {
return "";
}
StringBuilder romanResult = new StringBuilder();
int remainingValue = inputNumber;
for (int position = 0; position < ARABIC_VALUES.length; position++) {
int repeatCount = remainingValue / ARABIC_VALUES[position];
romanResult.append(String.valueOf(ROMAN_SYMBOLS[position]).repeat(Math.max(0, repeatCount)));
remainingValue -= repeatCount * ARABIC_VALUES[position];
}
return romanResult.toString();
}
}

package com.thealgorithms.dynamicprogramming;

/**
 * The {@code Tribonacci} class provides a method to compute the n-th number in the Tribonacci sequence.
 * N-th Tribonacci Number - https://leetcode.com/problems/n-th-tribonacci-number/description/
 */
public final class Tribonacci {
    private Tribonacci() {
    }

    /**
     * Computes the n-th Tribonacci number.
     *
     * @param n the index of the Tribonacci number to compute
     * @return the n-th Tribonacci number
     */
    public static int compute(int n) {
        if (n == 0) {
            return 0;
        }
        if (n == 1 || n == 2) {
            return 1;
        }

        int first = 0;
        int second = 1;
        int third = 1;

        for (int i = 3; i <= n; i++) {
            int next = first + second + third;
            first = second;
            second = third;
            third = next;
        }

        return third;
    }
}

package com.thealgorithms.lineclipping.utils;

import java.util.Objects;

/**
 * @author moksedursohan
 * @since 10/4/24
 */
public class Line {

    public Point start;
    public Point end;

    public Line() {
    }

    public Line(Point start, Point end) {
        this.start = start;
        this.end = end;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Line line)) {
            return false;
        }

        return Objects.equals(start, line.start) && Objects.equals(end, line.end);
    }

    @Override
    public int hashCode() {
        return Objects.hash(start, end);
    }

    @Override
    public String toString() {
        return "Line from " + start + " to " + end;
    }
}

public class Human { // Class defining the blueprint for Human objects

    // Instance variables (each Human object has its own copy)
    int age;           // Age of the human (in years)
    String name;       // Name of the human
    int salary;        // Annual salary in local currency
    boolean isMarried; // Marital status (true = married, false = single/unmarried)

    // Static variable (shared across ALL instances of the Human class)
    // 'static' is used when a variable does NOT depend on any specific object
    // but is common to all objects of that class
    // When a member is declared static, it can be accessed before any objects
    // of the class are created, without referencing any particular object
    static long totalPopulationCount = 0; // Tracks the total number of Human objects created

    // Constructor - called when a new Human object is instantiated
    public Human(int personAge, String personName, int personSalary, boolean maritalStatus) {
        this.age = personAge;
        this.name = personName;
        this.salary = personSalary;
        this.isMarried = maritalStatus;

        // Increment the shared population counter
        // Using class name (Human) instead of 'this' because 'population' is static/common
        // 'this' refers to a particular object, but population belongs to the class itself
        Human.totalPopulationCount += 1;
    }

    // Static method to display total population (belongs to class, not instances)
    public static void displayTotalPopulation() {
        System.out.println("Total human population: " + totalPopulationCount);
        // Note: Cannot access instance variables (age, name, salary, isMarried) here
        // because static methods don't have access to 'this'
    }

    // Instance method to display individual human details
    public void displayIndividualDetails() {
        System.out.println("Name: " + name);
        System.out.println("Age: " + age);
        System.out.println("Salary: " + salary);
        System.out.println("Married: " + isMarried);
        // Can access static variable from instance method
        System.out.println("Total population (from instance): " + totalPopulationCount);
    }
}

package com.thealgorithms.datastructures.heaps;

import java.util.PriorityQueue;

/**
 * This class provides methods to find the Kth largest or Kth smallest element
 * in an array using heaps. It leverages a min-heap to find the Kth largest element
 * and a max-heap to find the Kth smallest element efficiently.
 *
 * @author Hardvan
 */
public final class KthElementFinder {
    private KthElementFinder() {
    }

    /**
     * Finds the Kth largest element in the given array.
     * Uses a min-heap of size K to track the largest K elements.
     *
     * Time Complexity: O(n * log(k)), where n is the size of the input array.
     * Space Complexity: O(k), as we maintain a heap of size K.
     *
     * @param nums the input array of integers
     * @param k the desired Kth position (1-indexed, i.e., 1 means the largest element)
     * @return the Kth largest element in the array
     */
    public static int findKthLargest(int[] nums, int k) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>(k);
        for (int num : nums) {
            minHeap.offer(num);
            if (minHeap.size() > k) {
                minHeap.poll();
            }
        }
        return minHeap.peek();
    }

    /**
     * Finds the Kth smallest element in the given array.
     * Uses a max-heap of size K to track the smallest K elements.
     *
     * Time Complexity: O(n * log(k)), where n is the size of the input array.
     * Space Complexity: O(k), as we maintain a heap of size K.
     *
     * @param nums the input array of integers
     * @param k the desired Kth position (1-indexed, i.e., 1 means the smallest element)
     * @return the Kth smallest element in the array
     */
    public static int findKthSmallest(int[] nums, int k) {
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);
        for (int num : nums) {
            maxHeap.offer(num);
            if (maxHeap.size() > k) {
                maxHeap.poll();
            }
        }
        return maxHeap.peek();
    }
}

