        System.out.print("Input number 1: ");
        double number1 = scanner.nextDouble();
        System.out.print("Input number 2: ");
        double number2 = scanner.nextDouble();
        scanner.nextLine();
        System.out.print("Enter the operator(+-*/): ");
        char op = scanner.nextLine().charAt(0);
        switch (op) {
            case '+':
                System.out.println("The result of: " + number1 + op + number2 + "=" + (number1 + number2));
                break;
            case '-':
                System.out.println("The result of: " + number1 + op + number2 + "=" + (number1 - number2));
                break;
            case '*':
                System.out.println("The result of: " + number1 + op + number2 + "=" + (number1 * number2));
                break;
            case '/':
                System.out.println("The result of: " + number1 + op + number2 + "=" + (number1 / number2));
                break;
            default:
                System.out.println("Please enter operator");
                break;
        }
    }
}

public final class AbsoluteMax {
    private AbsoluteMax() {
    }

    /**
     * Finds the absolute maximum value among the given numbers.
     *
     * @param numbers The numbers to compare.
     * @return The absolute maximum value.
     * @throws IllegalArgumentException If the input array is empty or null.
     */
    public static int getMaxValue(int... numbers) {
        if (numbers == null || numbers.length == 0) {
            throw new IllegalArgumentException("Numbers array cannot be empty or null");
        }
        int absMax = numbers[0];
        for (int i = 1; i < numbers.length; i++) {
            if (Math.abs(numbers[i]) > Math.abs(absMax) || (Math.abs(numbers[i]) == Math.abs(absMax) && numbers[i] > absMax)) {
                absMax = numbers[i];
            }
        }
        return absMax;
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;

/**
 * Demonstrates line-based text I/O with the buffered reader/writer pair:
 * reads an existing text file line by line and prints it, then produces
 * a fresh output file with a couple of sample lines.
 */
public class MetinDosyasiOkuma {

    private static final String KAYNAK = "girdi.txt";
    private static final String HEDEF = "cikti.txt";

    public static void main(String[] args) {
        kaynakDosyayiEkraniBas();
        hedefDosyayiOlustur();
    }

    /** girdi.txt dosyasini satir satir okuyup konsola yansitir. */
    private static void kaynakDosyayiEkraniBas() {
        try (BufferedReader giris = new BufferedReader(new FileReader(KAYNAK))) {
            String mevcutSatir;
            while ((mevcutSatir = giris.readLine()) != null) {
                System.out.println(mevcutSatir);
            }
        } catch (IOException hata) {
            hata.printStackTrace();
        }
    }

    /** cikti.txt dosyasina iki ornek satir yazar. */
    private static void hedefDosyayiOlustur() {
        try (BufferedWriter cikis = new BufferedWriter(new FileWriter(HEDEF))) {
            cikis.write("Bu bir metin satiridir.");
            cikis.newLine();
            cikis.write("Bu da baska bir metin satiridir.");
        } catch (IOException hata) {
            hata.printStackTrace();
        }
    }
}

package com.thealgorithms.compression;

import java.util.ArrayList;
import java.util.List;

/**
 * An implementation of the Lempel-Ziv 77 (LZ77) compression algorithm.
 * <p>
 * LZ77 is a lossless data compression algorithm that works by finding repeated
 * occurrences of data in a sliding window. It replaces subsequent occurrences
 * with references (offset, length) to the first occurrence within the window.
 * </p>
 * <p>
 * This implementation uses a simple sliding window and lookahead buffer approach.
 * Output format is a sequence of tuples (offset, length, next_character).
 * </p>
 * <p>
 * Time Complexity: O(n*W) in this naive implementation, where n is the input length
 * and W is the window size, due to the search for the longest match. More advanced
 * data structures (like suffix trees) can improve this.
 * </p>
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/LZ77_and_LZ78#LZ77">Wikipedia: LZ77</a></li>
 * </ul>
 * </p>
 */
public final class LZ77 {

private static final int DEFAULT_WINDOW_SIZE = 4096;
private static final int DEFAULT_LOOKAHEAD_BUFFER_SIZE = 16;
private static final char END_MARKER = '\u0000';

private LZ77() {
}

/**
 * Represents a token in the LZ77 compressed output.
 * Stores the offset back into the window, the length of the match,
 * and the next character after the match (or END_MARKER if at end).
 */
public record CompressionToken(int distanceOffset, int matchLength, char nextCharacter) {
}

/**
 * Compresses the input text using the LZ77 algorithm.
 *
 * @param sourceText The input string to compress. Must not be null.
 * @param windowSize The size of the sliding window (search buffer). Must be positive.
 * @param lookaheadSize The size of the lookahead buffer. Must be positive.
 * @return A list of {@link CompressionToken} objects representing the compressed data.
 * @throws IllegalArgumentException if windowSize or lookaheadSize are not positive.
 */
public static List<CompressionToken> compress(String sourceText, int windowSize, int lookaheadSize) {
if (sourceText == null) {
return new ArrayList<>();
}
if (windowSize <= 0 || lookaheadSize <= 0) {
throw new IllegalArgumentException("Window size and lookahead buffer size must be positive.");
}
List<CompressionToken> encodedTokens = new ArrayList<>();
int currentPos = 0;
while (currentPos < sourceText.length()) {
int bestOffset = 0;
int bestLen = 0;
int searchStart = Math.max(0, currentPos - windowSize);
int lookaheadEnd = Math.min(currentPos + lookaheadSize, sourceText.length());
for (int searchPos = searchStart; searchPos < currentPos; searchPos++) {
int currentLen = 0;
while (currentPos + currentLen < lookaheadEnd) {
int sourceIdx = searchPos + currentLen;
if (sourceIdx >= currentPos) {
int relativeOffset = currentPos - searchPos;
sourceIdx = searchPos + (currentLen % relativeOffset);
}
if (sourceText.charAt(sourceIdx) == sourceText.charAt(currentPos + currentLen)) {
currentLen++;
} else {
break;
}
}
if (currentLen > bestLen) {
bestLen = currentLen;
bestOffset = currentPos - searchPos;
}
}
char nextChar;
if (currentPos + bestLen < sourceText.length()) {
nextChar = sourceText.charAt(currentPos + bestLen);
} else {
nextChar = END_MARKER;
}
encodedTokens.add(new CompressionToken(bestOffset, bestLen, nextChar));
if (nextChar == END_MARKER) {
currentPos += bestLen;
} else {
currentPos += bestLen + 1;
}
}
return encodedTokens;
}

/**
 * Compresses the input text using the LZ77 algorithm with default buffer sizes.
 *
 * @param sourceText The input string to compress. Must not be null.
 * @return A list of {@link CompressionToken} objects representing the compressed data.
 */
public static List<CompressionToken> compress(String sourceText) {
return compress(sourceText, DEFAULT_WINDOW_SIZE, DEFAULT_LOOKAHEAD_BUFFER_SIZE);
}

/**
 * Decompresses a list of LZ77 tokens back into the original string.
 *
 * @param encodedData The list of {@link CompressionToken} objects. Must not be null.
 * @return The original, uncompressed string.
 */
public static String decompress(List<CompressionToken> encodedData) {
if (encodedData == null) {
return "";
}
StringBuilder decodedText = new StringBuilder();
for (CompressionToken currentToken : encodedData) {
if (currentToken.matchLength() > 0) {
int startIndex = decodedText.length() - currentToken.distanceOffset();
for (int copyPos = 0; copyPos < currentToken.matchLength(); copyPos++) {
decodedText.append(decodedText.charAt(startIndex + copyPos));
}
}
if (currentToken.nextCharacter() != END_MARKER) {
decodedText.append(currentToken.nextCharacter());
}
}
return decodedText.toString();
}
}

// Dikdortgen sinifi, Sekil sinifini genisletir

public class Dikdortgen extends Sekil {
	private double genislik;
	private double yukseklik;

	// Yapilandirici
	public Dikdortgen(double genislik, double yukseklik) {
		super("Dikdortgen");
		this.genislik = genislik;
		this.yukseklik = yukseklik;
	}

	// Genislik ve yukseklik icin getter ve setter metodlari
	public double getGenislik() {
		return genislik;
	}

	public void setGenislik(double genislik) {
		this.genislik = genislik;
	}

	public double getYukseklik() {
		return yukseklik;
	}

	public void setYukseklik(double yukseklik) {
		this.yukseklik = yukseklik;
	}

	// alanHesapla metodu override edilir
	@Override
	public double alanHesapla() {
		return genislik * yukseklik;
	}

	// cevreHesapla metodu override edilir
	@Override
	public double cevreHesapla() {
		return 2 * (genislik + yukseklik);
	}

	// ciz metodu override edilir
	@Override
	public void ciz() {
		System.out.println("Dikdortgen ciziliyor: Genislik " + genislik + ", Yukseklik " + yukseklik);
	}
}

package polymorphism;

// Soyut sinif: Sekil
abstract class Sekil {
	private String isim;

	// Yapilandirici
	public Sekil(String isim) {
		this.isim = isim;
	}

	// Isim alani icin getter metodu
	public String getIsim() {
		return isim;
	}

	// Isim alani icin setter metodu
	public void setIsim(String isim) {
		this.isim = isim;
	}

	// Soyut metot: Seklin alanini hesapla (alt siniflar override etmek zorunda)
	public abstract double alanHesapla();

	// Soyut metot: Seklin cevresini hesapla (alt siniflar override etmek zorunda)
	public abstract double cevreHesapla();

	// Somut metot: Sekli ciz (alt siniflar istege bagli override edebilir)
	public void ciz() {
		System.out.println(isim + " ciziliyor.");
	}

	public static void main(String[] args) {
		// Sekil nesnelerini diziye koyuyoruz
		Sekil[] sekiller = new Sekil[3];
		sekiller[0] = new Kare(5);          // Kare nesnesi
		sekiller[1] = new Dikdortgen(4, 6); // Dikdortgen nesnesi
		sekiller[2] = new Cember(7);        // Cember nesnesi

		// Dizideki her bir Sekil nesnesi icin alan ve cevre hesaplamalari
		for (Sekil sekil : sekiller) {
			System.out.println(sekil.getIsim() + " alani: " + sekil.alanHesapla());
			System.out.println(sekil.getIsim() + " cevresi: " + sekil.cevreHesapla());
			sekil.ciz();
		}
	}
}

