        tarayici.close();
    }
}

package com.ankan.generics;

import java.util.ArrayList;
import java.util.Arrays;

public class CustomGenArrayList<T> {
    // Custom generic ArrayList implementation - allows any reference type <T>
    private Object[] internalDataStore;
    private static int INITIAL_DEFAULT_CAPACITY = 10;
    private int currentElementCount = 0; // also serves as the next available index position

    public CustomGenArrayList() {
        this.internalDataStore = new Object[INITIAL_DEFAULT_CAPACITY];
    }

    public void addElement(T elementToInsert) {
        if (isStorageFull()) {
            expandStorageCapacity();
        }
        internalDataStore[currentElementCount++] = elementToInsert;
    }

    private void expandStorageCapacity() {
        Object[] largerStorageArray = new Object[internalDataStore.length * 2];

        // Copy all existing elements into the newly created larger array
        for (int indexPosition = 0; indexPosition < internalDataStore.length; indexPosition++) {
            largerStorageArray[indexPosition] = internalDataStore[indexPosition];
        }
        internalDataStore = largerStorageArray;
    }

    private boolean isStorageFull() {
        return currentElementCount == internalDataStore.length;
    }

    public T removeLastElement() {
        T removedElementValue = (T) internalDataStore[--currentElementCount];
        return removedElementValue;
    }

    public T getElementAtIndex(int targetIndex) {
        return (T) internalDataStore[targetIndex];
    }

    public int getCurrentElementCount() {
        return currentElementCount;
    }

    public void updateValueAtIndex(int targetIndex, T updatedValue) {
        internalDataStore[targetIndex] = updatedValue;
    }

    @Override
    public String toString() {
        return "CustomGenArrayList{" +
                "internalDataStore=" + Arrays.toString(internalDataStore) +
                ", currentElementCount=" + currentElementCount +
                '}';
    }

    public static void main(String[] args) {
        // Standard Java ArrayList example (commented)
        // ArrayList list = new ArrayList();

        // Raw type usage (not recommended - shown for demonstration)
        CustomGenArrayList rawTypeList = new CustomGenArrayList();
//        rawTypeList.add(3);
//        rawTypeList.add(5);
//        rawTypeList.add(9);

//        // Integer example with for loop (commented)
//        for (int iterationValue = 0; iterationValue < 14; iterationValue++) {
//            rawTypeList.add(2 * iterationValue);
//        }
//        System.out.println(rawTypeList);

        // Standard generic ArrayList with String type
        ArrayList<String> stringTypeArrayList = new ArrayList<>();
//        stringTypeArrayList.add("sample text");
        // Note: Generics provide compile-time type safety - e.g., ArrayList<Integer>, ArrayList<Double>

        // Demonstrating CustomGenArrayList with Double type parameter
        CustomGenArrayList<Double> doubleTypeArrayList = new CustomGenArrayList<>();
        for (double incrementalValue = 0; incrementalValue < 14; incrementalValue++) {
            doubleTypeArrayList.addElement(2.5 * incrementalValue);
        }

        System.out.println("Complete Double ArrayList: " + doubleTypeArrayList);
        System.out.println("Element at index 5: " + doubleTypeArrayList.getElementAtIndex(5));
        System.out.println("Removed last element: " + doubleTypeArrayList.removeLastElement());
        System.out.println("ArrayList after removal: " + doubleTypeArrayList);
    }
}

/**
 * Reads workers/officers until choice 0, then prints only workers.
 */
public class TestMain {
    public static void main(String[] args) {
        Person[] people = new Person[10];
        int count = 0;
        int choice;
        do {
            System.out.println("Worker (1); Officer(2): ");
            Scanner in = new Scanner(System.in);
            choice = in.nextInt();
            if (choice == 1) {
                System.out.print("Enter worker name: ");
                String name = in.next();
                System.out.print("Enter worker working hours: ");
                int hrs = in.nextInt();
                people[count] = new Worker(name, hrs);
                count++;
            } else if (choice == 2) {
                System.out.print("Enter Officer name: ");
                String name = in.next();
                System.out.print("Enter officer salary: ");
                double salary = in.nextDouble();
                people[count] = new Officer(name, salary);
                count++;
            }
        } while (choice != 0);
        for (int i = 0; i < count; i++) {
            if (people[i] instanceof Worker) {
                people[i].display();
            }
        }
    }
}

