        // Display original unsorted array
        System.out.println("Original list: " + Arrays.toString(studentList));

        // Sort in descending order of marks using lambda expression
        Arrays.sort(studentList, (firstStudent, secondStudent) -> -(int)(firstStudent.marks - secondStudent.marks));

