/**
 * This class provides methods to convert a decimal number to a binary number.
 */
final class DecimalToBinary {
private static final int BINARY_RADIX = 2;
private static final int DECIMAL_PLACE_FACTOR = 10;

private DecimalToBinary() {
}

/**
 * Converts a decimal number to a binary number using a conventional algorithm.
 * @param decimalInput the decimal number to convert
 * @return the binary representation of the decimal number
 */
public static int convertUsingConventionalAlgorithm(int decimalInput) {
int binaryOutput = 0;
int placeMultiplier = 1;
int tempValue = decimalInput;
while (tempValue > 0) {
int remainderBit = tempValue % BINARY_RADIX;
binaryOutput += remainderBit * placeMultiplier;
placeMultiplier *= DECIMAL_PLACE_FACTOR;
tempValue /= BINARY_RADIX;
}
return binaryOutput;
}

/**
 * Converts a decimal number to a binary number using a bitwise algorithm.
 * @param decimalInput the decimal number to convert
 * @return the binary representation of the decimal number
 */
public static int convertUsingBitwiseAlgorithm(int decimalInput) {
int binaryOutput = 0;
int placeMultiplier = 1;
int tempValue = decimalInput;
while (tempValue > 0) {
int lowestBit = tempValue & 1;
binaryOutput += lowestBit * placeMultiplier;
placeMultiplier *= DECIMAL_PLACE_FACTOR;
tempValue >>= 1;
}
return binaryOutput;
}
}
