/**
 * Columnar Transposition Cipher Encryption and Decryption.
 *
 * @author <a href="https://github.com/freitzzz">freitzzz</a>
 */
public final class ColumnarTranspositionCipher {
    private ColumnarTranspositionCipher() {
    }

    private static String keyword;
    private static Object[][] table;
    private static String abecedarium;
    public static final String ABECEDARIUM = "abcdefghijklmnopqrstuvwxyzABCDEFG"
        + "HIJKLMNOPQRSTUVWXYZ0123456789,.;:-@";
    private static final String ENCRYPTION_FIELD = "≈";
    private static final char ENCRYPTION_FIELD_CHAR = '≈';

    /**
     * Encrypts a certain String with the Columnar Transposition Cipher Rule
     *
     * @param word Word being encrypted
     * @param keyword String with keyword being used
     * @return a String with the word encrypted by the Columnar Transposition
     * Cipher Rule
     */
    public static String encrypt(final String word, final String keyword) {
        ColumnarTranspositionCipher.keyword = keyword;
        abecedariumBuilder();
        table = tableBuilder(word);
        Object[][] sortedTable = sortTable(table);
        StringBuilder wordEncrypted = new StringBuilder();
        for (int i = 0; i < sortedTable[0].length; i++) {
            for (int j = 1; j < sortedTable.length; j++) {
                wordEncrypted.append(sortedTable[j][i]);
            }
        }
        return wordEncrypted.toString();
    }

    /**
     * Encrypts a certain String with the Columnar Transposition Cipher Rule
     *
     * @param word Word being encrypted
     * @param keyword String with keyword being used
     * @param abecedarium String with the abecedarium being used. null for
     * default one
     * @return a String with the word encrypted by the Columnar Transposition
     * Cipher Rule
     */
    public static String encrypt(String word, String keyword, String abecedarium) {
        ColumnarTranspositionCipher.keyword = keyword;
        ColumnarTranspositionCipher.abecedarium = Objects.requireNonNullElse(abecedarium, ABECEDARIUM);
        table = tableBuilder(word);
        Object[][] sortedTable = sortTable(table);

        StringBuilder wordEncrypted = new StringBuilder();
        for (int i = 0; i < sortedTable[0].length; i++) {
            for (int j = 1; j < sortedTable.length; j++) {
                wordEncrypted.append(sortedTable[j][i]);
            }
        }
        return wordEncrypted.toString();
    }

    /**
     * Decrypts a certain encrypted String with the Columnar Transposition
     * Cipher Rule
     *
     * @return a String decrypted with the word encrypted by the Columnar
     * Transposition Cipher Rule
     */
    public static String decrypt() {
        StringBuilder wordDecrypted = new StringBuilder();
        for (int i = 1; i < table.length; i++) {
            for (Object item : table[i]) {
                wordDecrypted.append(item);
            }
        }
        return wordDecrypted.toString().replaceAll(ENCRYPTION_FIELD, "");
    }

    /**
     * Builds a table with the word to be encrypted in rows by the Columnar
     * Transposition Cipher Rule
     *
     * @return An Object[][] with the word to be encrypted filled in rows and
     * columns
     */
    private static Object[][] tableBuilder(String word) {
        Object[][] table = new Object[numberOfRows(word) + 1][keyword.length()];
        char[] wordInChars = word.toCharArray();
        // Fills in the respective numbers for the column
        table[0] = findElements();
        int charElement = 0;
        for (int i = 1; i < table.length; i++) {
            for (int j = 0; j < table[i].length; j++) {
                if (charElement < wordInChars.length) {
                    table[i][j] = wordInChars[charElement];
                    charElement++;
                } else {
                    table[i][j] = ENCRYPTION_FIELD_CHAR;
                }
            }
        }
        return table;
    }

    /**
     * Determines the number of rows the table should have regarding the
     * Columnar Transposition Cipher Rule
     *
     * @return an int with the number of rows that the table should have in
     * order to respect the Columnar Transposition Cipher Rule.
     */
    private static int numberOfRows(String word) {
        if (word.length() % keyword.length() != 0) {
            return (word.length() / keyword.length()) + 1;
        } else {
            return word.length() / keyword.length();
        }
    }

    /**
     * @return charValues
     */
    private static Object[] findElements() {
        Object[] charValues = new Object[keyword.length()];
        for (int i = 0; i < charValues.length; i++) {
            int charValueIndex = abecedarium.indexOf(keyword.charAt(i));
            charValues[i] = charValueIndex > -1 ? charValueIndex : null;
        }
        return charValues;
    }

    /**
     * @return tableSorted
     */
    private static Object[][] sortTable(Object[][] table) {
        Object[][] tableSorted = new Object[table.length][table[0].length];
        for (int i = 0; i < tableSorted.length; i++) {
            System.arraycopy(table[i], 0, tableSorted[i], 0, tableSorted[i].length);
        }
        for (int i = 0; i < tableSorted[0].length; i++) {
            for (int j = i + 1; j < tableSorted[0].length; j++) {
                if ((int) tableSorted[0][i] > (int) table[0][j]) {
                    Object[] column = getColumn(tableSorted, tableSorted.length, i);
                    switchColumns(tableSorted, j, i, column);
                }
            }
        }
        return tableSorted;
    }

    /**
     * @return columnArray
     */
    private static Object[] getColumn(Object[][] table, int rows, int column) {
        Object[] columnArray = new Object[rows];
        for (int i = 0; i < rows; i++) {
            columnArray[i] = table[i][column];
        }
        return columnArray;
    }

    private static void switchColumns(Object[][] table, int firstColumnIndex, int secondColumnIndex, Object[] columnToSwitch) {
        for (int i = 0; i < table.length; i++) {
            table[i][secondColumnIndex] = table[i][firstColumnIndex];
            table[i][firstColumnIndex] = columnToSwitch[i];
        }
    }

    /**
     * Creates an abecedarium with all available ascii values.
     */
    private static void abecedariumBuilder() {
        StringBuilder t = new StringBuilder();
        for (int i = 0; i < 256; i++) {
            t.append((char) i);
        }
        abecedarium = t.toString();
    }
}

package com.thealgorithms.datastructures.lists;

/**
 * CountSinglyLinkedListRecursion extends a singly linked list to include a
 * recursive count method, which calculates the number of nodes in the list.
 */
public class CountSinglyLinkedListRecursion extends SinglyLinkedList {

    /**
     * Recursively calculates the number of nodes in the list.
     *
     * @param head the head node of the list segment being counted.
     * @return the count of nodes from the given head node onward.
     */
    private int countRecursion(SinglyLinkedListNode head) {
        return head == null ? 0 : 1 + countRecursion(head.next);
    }

    /**
     * Returns the total number of nodes in the list by invoking the recursive
     * count helper method.
     *
     * @return the total node count in the list.
     */
    @Override
    public int count() {
        return countRecursion(getHead());
    }
}

package array;

public class SecmeliSiralama {

    public static void main(String[] args) {
        // Ornek bir dizi olustur
        int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        // Secmeli siralama uygula
        secimSiralama(dizi);

        // Siralanmis diziyi ekrana yazdir
        System.out.println("Siralanmis Dizi:");
        for (int i = 0; i < dizi.length; i++) {
            System.out.print(dizi[i] + " ");
        }
    }

    public static void secimSiralama(int[] dizi) {

        // Her eleman icin uygun yeri bul
        for (int i = 0; i < dizi.length - 1; i++) {
            int minIndis = i;

            // Kalan elemanlar arasinda minimumu bul
            for (int j = i + 1; j < dizi.length; j++) {
                if (dizi[j] < dizi[minIndis]) {
                    minIndis = j;
                }
            }

            // Minimum elemani yer degistir
            int gecici = dizi[minIndis];
            dizi[minIndis] = dizi[i];
            dizi[i] = gecici;
        }
    }
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

/**
 * Implementation of Hierholzer's Algorithm for finding an Eulerian Path or Circuit
 * in a directed graph.
 *
 * <p>
 * An <b>Eulerian Circuit</b> is a path that starts and ends at the same vertex
 * and visits every edge exactly once.
 * </p>
 *
 * <p>
 * An <b>Eulerian Path</b> visits every edge exactly once but may start and end
 * at different vertices.
 * </p>
 *
 * <p>
 * <b>Algorithm Summary:</b><br>
 * 1. Compute indegree and outdegree for all vertices.<br>
 * 2. Check if the graph satisfies Eulerian path or circuit conditions.<br>
 * 3. Verify that all vertices with non-zero degree are weakly connected (undirected connectivity).<br>
 * 4. Use Hierholzer’s algorithm to build the path by exploring unused edges iteratively.
 * </p>
 *
 * <p>
 * <b>Time Complexity:</b> O(E + V).<br>
 * <b>Space Complexity:</b> O(V + E).
 * </p>
 *
 * @author <a href="https://en.wikipedia.org/wiki/Eulerian_path#Hierholzer's_algorithm">Wikipedia: Hierholzer algorithm</a>
 */
public class HierholzerEulerianPath {

    /**
     * Simple directed graph represented by adjacency lists.
     */
    public static class Graph {
        private final List<List<Integer>> adjacencyList;

        /**
         * Constructs a graph with a given number of vertices.
         *
         * @param numNodes number of vertices
         */
        public Graph(int numNodes) {
            adjacencyList = new ArrayList<>();
            for (int i = 0; i < numNodes; i++) {
                adjacencyList.add(new ArrayList<>());
            }
        }

        /**
         * Adds a directed edge from vertex {@code from} to vertex {@code to}.
         *
         * @param from source vertex
         * @param to   destination vertex
         */
        public void addEdge(int from, int to) {
            adjacencyList.get(from).add(to);
        }

        /**
         * Returns a list of outgoing edges from the given vertex.
         *
         * @param node vertex index
         * @return list of destination vertices
         */
        public List<Integer> getEdges(int node) {
            return adjacencyList.get(node);
        }

        /**
         * Returns the number of vertices in the graph.
         *
         * @return number of vertices
         */
        public int getNumNodes() {
            return adjacencyList.size();
        }
    }

    private final Graph graph;

    /**
     * Creates a Hierholzer solver for the given graph.
     *
     * @param graph directed graph
     */
    public HierholzerEulerianPath(Graph graph) {
        this.graph = graph;
    }

    /**
     * Finds an Eulerian Path or Circuit using Hierholzer’s Algorithm.
     *
     * @return list of vertices representing the Eulerian Path/Circuit,
     *         or an empty list if none exists
     */
    public List<Integer> findEulerianPath() {
        int n = graph.getNumNodes();

        // empty graph -> no path
        if (n == 0) {
            return new ArrayList<>();
        }

        int[] inDegree = new int[n];
        int[] outDegree = new int[n];
        int edgeCount = computeDegrees(inDegree, outDegree);

        // no edges -> single vertex response requested by tests: [0]
        if (edgeCount == 0) {
            return Collections.singletonList(0);
        }

        int startNode = determineStartNode(inDegree, outDegree);
        if (startNode == -1) {
            return new ArrayList<>();
        }

        if (!allNonZeroDegreeVerticesWeaklyConnected(startNode, n, outDegree, inDegree)) {
            return new ArrayList<>();
        }

        List<Integer> path = buildHierholzerPath(startNode, n);
        if (path.size() != edgeCount + 1) {
            return new ArrayList<>();
        }

        return rotateEulerianCircuitIfNeeded(path, outDegree, inDegree);
    }

    private int computeDegrees(int[] inDegree, int[] outDegree) {
        int edgeCount = 0;
        for (int u = 0; u < graph.getNumNodes(); u++) {
            for (int v : graph.getEdges(u)) {
                outDegree[u]++;
                inDegree[v]++;
                edgeCount++;
            }
        }
        return edgeCount;
    }

    private int determineStartNode(int[] inDegree, int[] outDegree) {
        int n = graph.getNumNodes();
        int startNode = -1;
        int startCount = 0;
        int endCount = 0;

        for (int i = 0; i < n; i++) {
            int diff = outDegree[i] - inDegree[i];
            if (diff == 1) {
                startNode = i;
                startCount++;
            } else if (diff == -1) {
                endCount++;
            } else if (Math.abs(diff) > 1) {
                return -1;
            }
        }

        if (!((startCount == 1 && endCount == 1) || (startCount == 0 && endCount == 0))) {
            return -1;
        }

        if (startNode == -1) {
            for (int i = 0; i < n; i++) {
                if (outDegree[i] > 0) {
                    startNode = i;
                    break;
                }
            }
        }
        return startNode;
    }

    private List<Integer> buildHierholzerPath(int startNode, int n) {
        List<Deque<Integer>> tempAdj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            tempAdj.add(new ArrayDeque<>(graph.getEdges(i)));
        }

        Deque<Integer> stack = new ArrayDeque<>();
        List<Integer> path = new ArrayList<>();
        stack.push(startNode);

        while (!stack.isEmpty()) {
            int u = stack.peek();
            if (!tempAdj.get(u).isEmpty()) {
                stack.push(tempAdj.get(u).pollFirst());
            } else {
                path.add(stack.pop());
            }
        }

        Collections.reverse(path);
        return path;
    }

    private List<Integer> rotateEulerianCircuitIfNeeded(List<Integer> path, int[] outDegree, int[] inDegree) {
        int startCount = 0;
        int endCount = 0;
        for (int i = 0; i < outDegree.length; i++) {
            int diff = outDegree[i] - inDegree[i];
            if (diff == 1) {
                startCount++;
            } else if (diff == -1) {
                endCount++;
            }
        }

        if (startCount == 0 && endCount == 0 && !path.isEmpty()) {
            int preferredStart = -1;
            for (int i = 0; i < outDegree.length; i++) {
                if (outDegree[i] > 0) {
                    preferredStart = i;
                    break;
                }
            }

            if (preferredStart != -1 && path.get(0) != preferredStart) {
                int idx = 0;
                for (Integer node : path) { // replaced indexed loop
                    if (node == preferredStart) {
                        break;
                    }
                    idx++;
                }

                if (idx > 0) {
                    List<Integer> rotated = new ArrayList<>();
                    int currentIndex = 0;
                    for (Integer node : path) { // replaced indexed loop
                        if (currentIndex >= idx) {
                            rotated.add(node);
                        }
                        currentIndex++;
                    }
                    currentIndex = 0;
                    for (Integer node : path) { // replaced indexed loop
                        if (currentIndex < idx) {
                            rotated.add(node);
                        }
                        currentIndex++;
                    }
                    path = rotated;
                }
            }
        }
        return path;
    }

    /**
     * Checks weak connectivity (undirected) among vertices that have non-zero degree.
     *
     * @param startNode node to start DFS from (must be a vertex with non-zero degree)
     * @param n number of vertices
     * @param outDegree out-degree array
     * @param inDegree in-degree array
     * @return true if all vertices having non-zero degree belong to a single weak component
     */
    private boolean allNonZeroDegreeVerticesWeaklyConnected(int startNode, int n, int[] outDegree, int[] inDegree) {
        boolean[] visited = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(startNode);
        visited[startNode] = true;

        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int v : graph.getEdges(u)) {
                if (!visited[v]) {
                    visited[v] = true;
                    stack.push(v);
                }
            }
            for (int x = 0; x < n; x++) {
                if (!visited[x]) {
                    for (int y : graph.getEdges(x)) {
                        if (y == u) {
                            visited[x] = true;
                            stack.push(x);
                            break;
                        }
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (outDegree[i] + inDegree[i] > 0 && !visited[i]) {
                return false;
            }
        }
        return true;
    }
}

package com.thealgorithms.datastructures.lists;

/**
 * The RotateSinglyLinkedLists class provides a method to rotate a singly linked list
 * to the right by a specified number of positions.
 * <p>
 * In a right rotation by `k` steps, each node in the list moves `k` positions to the right.
 * Nodes that are rotated off the end of the list are placed back at the beginning.
 * </p>
 * <p>
 * Example:
 * Given linked list: 1 -> 2 -> 3 -> 4 -> 5 and k = 2, the output will be:
 * 4 -> 5 -> 1 -> 2 -> 3.
 * </p>
 * <p>
 * Edge Cases:
 * <ul>
 *   <li>If the list is empty, returns null.</li>
 *   <li>If `k` is 0 or a multiple of the list length, the list remains unchanged.</li>
 * </ul>
 * </p>
 * <p>
 * Complexity:
 * <ul>
 *   <li>Time Complexity: O(n), where n is the number of nodes in the linked list.</li>
 *   <li>Space Complexity: O(1), as we only use a constant amount of additional space.</li>
 * </ul>
 * </p>
 *
 * Author: Bama Charan Chhandogi (https://github.com/BamaCharanChhandogi)
 */
public class RotateSinglyLinkedLists {

    /**
     * Rotates a singly linked list to the right by `k` positions.
     *
     * @param head The head node of the singly linked list.
     * @param k The number of positions to rotate the list to the right.
     * @return The head of the rotated linked list.
     */
    public SinglyLinkedListNode rotateRight(SinglyLinkedListNode head, int k) {
        if (head == null || head.next == null || k == 0) {
            return head;
        }

        SinglyLinkedListNode curr = head;
        int len = 1;
        while (curr.next != null) {
            curr = curr.next;
            len++;
        }

        curr.next = head;
        k = k % len;
        k = len - k;
        while (k > 0) {
            curr = curr.next;
            k--;
        }

        head = curr.next;
        curr.next = null;
        return head;
    }
}

