package array;

public class HizliSiralama {

    public static void sirala(int[] dizi, int sol, int sag) {

        // Pivot degeri ve indeksini belirle
        int pivotIndeks = sol + (sag - sol) / 2;
        int pivotDegeri = dizi[pivotIndeks];
        int i = sol;
        int j = sag;

        while (i <= j) {
            // Pivot degerinden kucuk elemanlar bulunur
            while (dizi[i] < pivotDegeri) {
                i++;
            }
            // Pivot degerinden buyuk elemanlar bulunur
            while (dizi[j] > pivotDegeri) {
                j--;
            }
            // Elemanlar yer degistirilir
            if (i <= j) {
                int gecici = dizi[i];
                dizi[i] = dizi[j];
                dizi[j] = gecici;
                i++;
                j--;
            }
            // Sol alt diziyi sirala
            if (sol < i) {
                sirala(dizi, sol, j);
            }
            // Sag alt diziyi sirala
            if (sag > i) {
                sirala(dizi, i, sag);
            }
        }
    }

    public static void main(String[] args) {
        // Ornek bir dizi olustur
        int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        // Dizi hizli siralama ile siralanir
        HizliSiralama.sirala(dizi, 0, dizi.length - 1);

        // Siralanmis dizi ekrana yazdirilir
        for (int i = 0; i < dizi.length; i++) {
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }
}

/**
 * A moving ball that bounces off boundaries.
 */
public class Ball {
    private float posX;
    private float posY;
    private int radius;
    private float speedX;
    private float speedY;

    public Ball(float posX, float posY, int radius, float speedX, float speedY) {
        this.posX = posX;
        this.posY = posY;
        this.radius = radius;
        this.speedX = speedX;
        this.speedY = speedY;
    }

    public float getX() {
        return posX;
    }

    public void setX(float posX) {
        this.posX = posX;
    }

    public float getY() {
        return posY;
    }

    public void setY(float posY) {
        this.posY = posY;
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }

    public float getXDelta() {
        return speedX;
    }

    public void setXDelta(float speedX) {
        this.speedX = speedX;
    }

    public float getYDelta() {
        return speedY;
    }

    public void setYDelta(float speedY) {
        this.speedY = speedY;
    }

    public void move() {
        posX += speedX;
        posY += speedY;
    }

    public void reflectHorizontal() {
        speedX = -speedX;
    }

    public void reflectVertical() {
        speedY = -speedY;
    }

    @Override
    public String toString() {
        return "Ball[(" + posX + "," + posY + "),speed=(" + speedX + "," + speedY + ")]";
    }
}

class TestMain {
    public static void main(String[] args) {
        Ball ball = new Ball(1.1f, 2.2f, 10, 3.3f, 4.4f);
        System.out.println(ball);

        ball.setX(80.0f);
        ball.setY(35.0f);
        ball.setRadius(5);
        ball.setXDelta(4.0f);
        ball.setYDelta(6.0f);
        System.out.println(ball);
        System.out.println("x is: " + ball.getX());
        System.out.println("y is: " + ball.getY());
        System.out.println("radius is: " + ball.getRadius());
        System.out.println("xDelta is: " + ball.getXDelta());
        System.out.println("yDelta is: " + ball.getYDelta());

        final float xMin = 0.0f;
        final float xMax = 100.0f;
        final float yMin = 0.0f;
        final float yMax = 50.0f;

        int bounces = 0;
        while (bounces < 15) {
            ball.move();
            System.out.println(ball);
            float xNew = ball.getX();
            float yNew = ball.getY();
            int radius = ball.getRadius();
            if (xNew + radius > xMax || xNew - radius < xMin) {
                ball.reflectHorizontal();
            }
            if (yNew + radius > yMax || yNew - radius < yMin) {
                ball.reflectVertical();
            }
            bounces++;
        }
    }
}

package com.thealgorithms.devutils.searches;

/**
 * The common interface of most searching algorithms that search in matrixes.
 *
 * @author Aitor Fidalgo (https://github.com/aitorfi)
 */
public interface MatrixSearchAlgorithm {
    /**
     * @param key is an element which should be found
     * @param matrix is a matrix where the element should be found
     * @param <T> Comparable type
     * @return array containing the first found coordinates of the element
     */
    <T extends Comparable<T>> int[] find(T[][] matrix, T key);
}

/**
 * This class implements the Longest Common Subsequence (LCS) problem.
 * The LCS of two sequences is the longest sequence that appears in both
 * sequences
 * in the same order, but not necessarily consecutively.
 *
 * This implementation uses dynamic programming to find the LCS of two strings.
 */
final class LongestCommonSubsequence {

    private LongestCommonSubsequence() {
    }

    /**
     * Returns the Longest Common Subsequence (LCS) of two given strings.
     *
     * @param str1 The first string.
     * @param str2 The second string.
     * @return The LCS of the two strings, or null if one of the strings is null.
     */
    public static String getLCS(String str1, String str2) {
        // If either string is null, return null as LCS can't be computed.
        if (str1 == null || str2 == null) {
            return null;
        }
        // If either string is empty, return an empty string as LCS.
        if (str1.length() == 0 || str2.length() == 0) {
            return "";
        }

        // Convert the strings into arrays of characters
        String[] arr1 = str1.split("");
        String[] arr2 = str2.split("");

        // lcsMatrix[i][j] = LCS(first i characters of str1, first j characters of str2)
        int[][] lcsMatrix = new int[arr1.length + 1][arr2.length + 1];

        // Base Case: Fill the LCS matrix 0th row & 0th column with 0s
        // as LCS of any string with an empty string is 0.
        for (int i = 0; i < arr1.length + 1; i++) {
            lcsMatrix[i][0] = 0;
        }
        for (int j = 1; j < arr2.length + 1; j++) {
            lcsMatrix[0][j] = 0;
        }

        // Build the LCS matrix by comparing characters of str1 & str2
        for (int i = 1; i < arr1.length + 1; i++) {
            for (int j = 1; j < arr2.length + 1; j++) {
                // If characters match, the LCS increases by 1
                if (arr1[i - 1].equals(arr2[j - 1])) {
                    lcsMatrix[i][j] = lcsMatrix[i - 1][j - 1] + 1;
                } else {
                    // Otherwise, take the maximum of the left or above values
                    lcsMatrix[i][j] = Math.max(lcsMatrix[i - 1][j], lcsMatrix[i][j - 1]);
                }
            }
        }

        // Call helper function to reconstruct the LCS from the matrix
        return lcsString(str1, str2, lcsMatrix);
    }

    /**
     * Reconstructs the LCS string from the LCS matrix.
     *
     * @param str1      The first string.
     * @param str2      The second string.
     * @param lcsMatrix The matrix storing the lengths of LCSs
     *                  of substrings of str1 and str2.
     * @return The LCS string.
     */
    public static String lcsString(String str1, String str2, int[][] lcsMatrix) {
        StringBuilder lcs = new StringBuilder(); // Hold the LCS characters.
        int i = str1.length(); // Start from the end of str1.
        int j = str2.length(); // Start from the end of str2.

        // Trace back through the LCS matrix to reconstruct the LCS
        while (i > 0 && j > 0) {
            // If characters match, add to the LCS and move diagonally in the matrix
            if (str1.charAt(i - 1) == str2.charAt(j - 1)) {
                lcs.append(str1.charAt(i - 1));
                i--;
                j--;
            } else if (lcsMatrix[i - 1][j] > lcsMatrix[i][j - 1]) {
                // If the value above is larger, move up
                i--;
            } else {
                // If the value to the left is larger, move left
                j--;
            }
        }

        return lcs.reverse().toString(); // LCS built in reverse, so reverse it back
    }
}

/**
 * Merges account records using Disjoint Set Union (Union-Find) on shared emails.
 *
 * <p>Input format: each account is a list where the first element is the user name and the
 * remaining elements are emails.
 */
public final class AccountMerge {
    private AccountMerge() {
    }

    public static List<List<String>> mergeAccounts(List<List<String>> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return List.of();
        }

        UnionFind dsu = new UnionFind(accounts.size());
        Map<String, Integer> emailToAccount = new HashMap<>();

        for (int i = 0; i < accounts.size(); i++) {
            List<String> account = accounts.get(i);
            for (int j = 1; j < account.size(); j++) {
                String email = account.get(j);
                Integer previous = emailToAccount.putIfAbsent(email, i);
                if (previous != null) {
                    dsu.union(i, previous);
                }
            }
        }

        Map<Integer, List<String>> rootToEmails = new LinkedHashMap<>();
        for (Map.Entry<String, Integer> entry : emailToAccount.entrySet()) {
            int root = dsu.find(entry.getValue());
            rootToEmails.computeIfAbsent(root, ignored -> new ArrayList<>()).add(entry.getKey());
        }
        for (int i = 0; i < accounts.size(); i++) {
            if (accounts.get(i).size() <= 1) {
                int root = dsu.find(i);
                rootToEmails.computeIfAbsent(root, ignored -> new ArrayList<>());
            }
        }

        List<List<String>> merged = new ArrayList<>();
        for (Map.Entry<Integer, List<String>> entry : rootToEmails.entrySet()) {
            int root = entry.getKey();
            List<String> emails = entry.getValue();
            Collections.sort(emails);

            List<String> mergedAccount = new ArrayList<>();
            mergedAccount.add(accounts.get(root).getFirst());
            mergedAccount.addAll(emails);
            merged.add(mergedAccount);
        }

        merged.sort((a, b) -> {
            int cmp = a.getFirst().compareTo(b.getFirst());
            if (cmp != 0) {
                return cmp;
            }
            if (a.size() == 1 || b.size() == 1) {
                return Integer.compare(a.size(), b.size());
            }
            return a.get(1).compareTo(b.get(1));
        });
        return merged;
    }

    private static final class UnionFind {
        private final int[] parent;
        private final int[] rank;

        private UnionFind(int size) {
            this.parent = new int[size];
            this.rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        private int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        private void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return;
            }

            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * The AssignmentUsingBitmask class is used to calculate the total number of ways
 * tasks can be distributed among people, given specific constraints on who can perform which tasks.
 * The approach uses bitmasking and dynamic programming to efficiently solve the problem.
 *
 * @author Hardvan
 */
public final class AssignmentUsingBitmask {

    private final int totalTasks;
    private final int[][] dp;
    private final List<List<Integer>> task;
    private final int finalMask;

    /**
     * Constructor for the AssignmentUsingBitmask class.
     *
     * @param taskPerformed a list of lists, where each inner list contains the tasks that a person can perform.
     * @param total        the total number of tasks.
     */
    public AssignmentUsingBitmask(List<List<Integer>> taskPerformed, int total) {
        this.totalTasks = total;
        this.dp = new int[1 << taskPerformed.size()][total + 1];
        for (int[] row : dp) {
            Arrays.fill(row, -1);
        }

        this.task = new ArrayList<>(totalTasks + 1);
        for (int i = 0; i <= totalTasks; i++) {
            this.task.add(new ArrayList<>());
        }

        // Final mask to check if all persons are included
        this.finalMask = (1 << taskPerformed.size()) - 1;

        // Fill the task list
        for (int i = 0; i < taskPerformed.size(); i++) {
            for (int j : taskPerformed.get(i)) {
                this.task.get(j).add(i);
            }
        }
    }

    /**
     * Counts the ways to assign tasks until the given task number with the specified mask.
     *
     * @param mask     the bitmask representing the current state of assignments.
     * @param taskNo   the current task number being processed.
     * @return the number of ways to assign tasks.
     */
    private int countWaysUntil(int mask, int taskNo) {
        if (mask == finalMask) {
            return 1;
        }
        if (taskNo > totalTasks) {
            return 0;
        }
        if (dp[mask][taskNo] != -1) {
            return dp[mask][taskNo];
        }

        int totalWays = countWaysUntil(mask, taskNo + 1);

        // Assign tasks to all possible persons
        for (int p : task.get(taskNo)) {
            // If the person is already assigned a task
            if ((mask & (1 << p)) != 0) {
                continue;
            }
            totalWays += countWaysUntil(mask | (1 << p), taskNo + 1);
        }

        dp[mask][taskNo] = totalWays;
        return dp[mask][taskNo];
    }

    /**
     * Counts the total number of ways to distribute tasks among persons.
     *
     * @return the total number of ways to distribute tasks.
     */
    public int countNoOfWays() {
        return countWaysUntil(0, 1);
    }
}

public final class MainCuckooHashing {
    private MainCuckooHashing() {
    }

    public static void main(String[] args) {
        int choice;
        int key;

        HashMapCuckooHashing h = new HashMapCuckooHashing(7);
        Scanner scan = new Scanner(System.in);

        while (true) {
            System.out.println("_________________________");
            System.out.println("Enter your Choice :");
            System.out.println("1. Add Key");
            System.out.println("2. Delete Key");
            System.out.println("3. Print Table");
            System.out.println("4. Exit");
            System.out.println("5. Search and print key index");
            System.out.println("6. Check load factor");
            System.out.println("7. Rehash Current Table");

            choice = scan.nextInt();

            switch (choice) {
            case 1:
                System.out.println("Enter the Key: ");
                key = scan.nextInt();
                h.insertKey2HashTable(key);
                break;

            case 2:
                System.out.println("Enter the Key delete:  ");
                key = scan.nextInt();
                h.deleteKeyFromHashTable(key);
                break;

            case 3:
                System.out.println("Print table:\n");
                h.displayHashtable();
                break;

            case 4:
                scan.close();
                return;

            case 5:
                System.out.println("Enter the Key to find and print:  ");
                key = scan.nextInt();
                System.out.println("Key: " + key + " is at index: " + h.findKeyInTable(key) + "\n");
                break;

            case 6:
                System.out.printf("Load factor is: %.2f%n", h.checkLoadFactor());
                break;

            case 7:
                h.reHashTableIncreasesTableSize();
                break;

            default:
                throw new IllegalArgumentException("Unexpected value: " + choice);
            }
        }
    }
}

