import java.util.Scanner;

/*
 * Bu program, bir topun ziplamasini simule eder ve her saniyede yuksekligini hesaplar:
 * 
 * Topun hizi, yer cekimi ivmesine ve gecen zamana orantili olarak azalir. 
 * Topun yuksekligi negatif oldugunda, program topun hizini ters cevirir 
 * ve hizini %50 azaltarak ziplamayi simule eder.
 * 
 */

public class Ziplama {

  public static void main(String[] args) {

    Scanner sc = new Scanner(System.in);

    // Kullanicidan ilk hizi girmesi istenir
    System.out.print("Ilk hizi giriniz: ");
    double hiz = sc.nextDouble();
    sc.close();

    // Baslangic yuksekligi 0 olarak ayarlanir
    double yukseklik = 0;

    // Baslangic zamani 0 olarak ayarlanir
    double zaman = 0;

    // Ziplamalari saymak icin sayac
    int ziplama = 0;

    // Topun besinci ziplamasina kadar simule edilir
    while (ziplama < 5) {
      // Mevcut zaman, yukseklik ve hiz yazdirilir
      System.out.println("Zaman: " + zaman + " saniye " + " Yukseklik: " + yukseklik + " feet " + " Hiz: " + hiz);

      // Yukseklik ve hiz guncellenir
      yukseklik += hiz;
      hiz -= 32;

      // Topun yere carpip carpamadigi kontrol edilir
      if (yukseklik < 0) {
        // Hiz ters cevrilir ve %50 azaltilir
        hiz *= -0.5;

        // Yukseklik sifira resetlenir
        yukseklik = 0;

        // Ziplama sayaci bir artirilir
        ziplama++;
      }

      // Zaman bir artirilir
      zaman++;
    }
  }
}

/**
 * A simple student management example demonstrating
 * classes, lists and basic CRUD operations.
 */
class Student {
    private final int id;
    private String name;
    private double grade;

    public Student(int id, String name, double grade) {
        this.id = id;
        this.name = name;
        this.grade = grade;
    }

    public int getId() { return id; }
    public String getName() { return name; }
    public double getGrade() { return grade; }

    @Override
    public String toString() {
        return String.format("Student{id=%d, name='%s', grade=%.1f}", id, name, grade);
    }
}

public class StudentManager {
    private final List<Student> students = new ArrayList<>();

    public void addStudent(Student student) {
        students.add(student);
    }

    public Student findById(int id) {
        for (Student student : students) {
            if (student.getId() == id) {
                return student;
            }
        }
        return null;
    }

    public double averageGrade() {
        if (students.isEmpty()) {
            return 0;
        }
        double sum = 0;
        for (Student student : students) {
            sum += student.getGrade();
        }
        return sum / students.size();
    }

    public static void main(String[] args) {
        StudentManager manager = new StudentManager();
        manager.addStudent(new Student(1, "Alice", 4.5));
        manager.addStudent(new Student(2, "Bob", 3.8));
        manager.addStudent(new Student(3, "Charlie", 4.9));

        System.out.println("Found: " + manager.findById(2));
        System.out.printf("Average grade: %.2f%n", manager.averageGrade());
    }
}

