/**
 * <a href="https://en.wikipedia.org/wiki/Linked_list">wikipedia</a>
 */
public class SinglyLinkedList implements Iterable<Integer> {

    /**
     * Head refer to the front of the list
     */
    private SinglyLinkedListNode head;

    /**
     * Size of SinglyLinkedList
     */
    private int size;

    /**
     * Init SinglyLinkedList
     */
    public SinglyLinkedList() {
        head = null;
        size = 0;
    }

    /**
     * Init SinglyLinkedList with specified head node and size
     *
     * @param head the head node of list
     * @param size the size of list
     */
    public SinglyLinkedList(SinglyLinkedListNode head, int size) {
        this.head = head;
        this.size = size;
    }

    /**
     * Detects if there is a loop in the singly linked list using floy'd turtle
     * and hare algorithm.
     *
     */
    public boolean detectLoop() {
        SinglyLinkedListNode currentNodeFast = head;
        SinglyLinkedListNode currentNodeSlow = head;
        while (currentNodeFast != null && currentNodeFast.next != null) {
            currentNodeFast = currentNodeFast.next.next;
            currentNodeSlow = currentNodeSlow.next;
            if (currentNodeFast == currentNodeSlow) {
                return true;
            }
        }
        return false;
    }

    /**
     * Return the node in the middle of the list
     * If the length of the list is even then return item number length/2
     * @return middle node of the list
     */
    public SinglyLinkedListNode middle() {
        if (head == null) {
            return null;
        }
        SinglyLinkedListNode firstCounter = head;
        SinglyLinkedListNode secondCounter = firstCounter.next;
        while (secondCounter != null && secondCounter.next != null) {
            firstCounter = firstCounter.next;
            secondCounter = secondCounter.next.next;
        }
        return firstCounter;
    }

    /**
     * Swaps nodes of two given values a and b.
     *
     */
    public void swapNodes(int valueFirst, int valueSecond) {
        if (valueFirst == valueSecond) {
            return;
        }
        SinglyLinkedListNode previousA = null;
        SinglyLinkedListNode currentA = head;
        while (currentA != null && currentA.value != valueFirst) {
            previousA = currentA;
            currentA = currentA.next;
        }

        SinglyLinkedListNode previousB = null;
        SinglyLinkedListNode currentB = head;
        while (currentB != null && currentB.value != valueSecond) {
            previousB = currentB;
            currentB = currentB.next;
        }
        /* If either of 'a' or 'b' is not present, then return */
        if (currentA == null || currentB == null) {
            return;
        }

        // If 'a' is not head node of list
        if (previousA != null) {
            previousA.next = currentB;
        } else {
            // make 'b' as the new head
            head = currentB;
        }

        // If 'b' is not head node of list
        if (previousB != null) {
            previousB.next = currentA;
        } else {
            // Make 'a' as new head
            head = currentA;
        }
        // Swap next pointer

        var temp = currentA.next;
        currentA.next = currentB.next;
        currentB.next = temp;
    }

    /**
     * Reverse a singly linked list[Iterative] from a given node till the end
     *
     */
    public SinglyLinkedListNode reverseListIter(SinglyLinkedListNode node) {
        SinglyLinkedListNode prev = null;
        SinglyLinkedListNode curr = node;

        while (curr != null && curr.next != null) {
            var next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        // when curr.next==null, the current element is left without pointing it to its prev,so
        if (curr != null) {
            curr.next = prev;
            prev = curr;
        }
        // prev will be pointing to the last element in the Linkedlist, it will be the new head of
        // the reversed linkedlist
        return prev;
    }
    /**
     * Reverse a singly linked list[Recursive] from a given node till the end
     *
     */
    public SinglyLinkedListNode reverseListRec(SinglyLinkedListNode head) {
        if (head == null || head.next == null) {
            return head;
        }

        SinglyLinkedListNode prev = null;
        SinglyLinkedListNode h2 = reverseListRec(head.next);

        head.next.next = head;
        head.next = prev;

        return h2;
    }

    /**
     * Clear all nodes in the list
     */
    public void clear() {
        SinglyLinkedListNode cur = head;
        while (cur != null) {
            cur = cur.next;
        }
        head = null;
        size = 0;
    }

    /**
     * Checks if the list is empty
     *
     * @return {@code true} if list is empty, otherwise {@code false}.
     */
    public boolean isEmpty() {
        return size == 0;
    }

    /**
     * Returns the size of the linked list.
     *
     * @return the size of the list.
     */
    public int size() {
        return size;
    }

    /**
     * Get head of the list.
     *
     * @return head of the list.
     */
    public SinglyLinkedListNode getHead() {
        return head;
    }

    /**
     * Set head of the list.
     *
     */
    public void setHead(SinglyLinkedListNode head) {
        this.head = head;
    }

    /**
     * Calculate the count of the list manually
     *
     * @return count of the list
     */
    public int count() {
        int count = 0;
        for (final var element : this) {
            ++count;
        }
        return count;
    }

    /**
     * Test if the value key is present in the list.
     *
     * @param key the value to be searched.
     * @return {@code true} if key is present in the list, otherwise
     * {@code false}.
     */
    public boolean search(final int key) {
        for (final var element : this) {
            if (element == key) {
                return true;
            }
        }
        return false;
    }

    @Override
    public String toString() {
        StringJoiner joiner = new StringJoiner("->");
        for (final var element : this) {
            joiner.add(element + "");
        }
        return joiner.toString();
    }

    public void deleteDuplicates() {
        SinglyLinkedListNode pred = head;
        // predecessor = the node
        // having sublist of its duplicates
        SinglyLinkedListNode newHead = head;
        while (newHead != null) {
            // if it's a beginning of duplicates sublist
            // skip all duplicates
            if (newHead.next != null && newHead.value == newHead.next.value) {
                // move till the end of duplicates sublist
                while (newHead.next != null && newHead.value == newHead.next.value) {
                    newHead = newHead.next;
                }
                // skip all duplicates
                pred.next = newHead.next;
                newHead = null;
                // otherwise, move predecessor
            }
            // move forward
            pred = pred.next;
            newHead = pred;
        }
    }

    public void print() {
        SinglyLinkedListNode temp = head;
        while (temp != null && temp.next != null) {
            System.out.print(temp.value + "->");
            temp = temp.next;
        }
        if (temp != null) {
            System.out.print(temp.value);
            System.out.println();
        }
    }

    /**
     * Inserts an element at the head of the list
     *
     * @param x element to be added
     */
    public void insertHead(int x) {
        insertNth(x, 0);
    }

    /**
     * Insert an element at the tail of the list
     *
     * @param data element to be added
     */
    public void insert(int data) {
        insertNth(data, size);
    }

    /**
     * Inserts a new node at a specified position of the list
     *
     * @param data data to be stored in a new node
     * @param position position at which a new node is to be inserted
     */
    public void insertNth(int data, int position) {
        checkBounds(position, 0, size);
        SinglyLinkedListNode newNode = new SinglyLinkedListNode(data);
        if (head == null) {
            /* the list is empty */
            head = newNode;
            size++;
            return;
        }
        if (position == 0) {
            /* insert at the head of the list */
            newNode.next = head;
            head = newNode;
            size++;
            return;
        }

        SinglyLinkedListNode cur = head;
        for (int i = 0; i < position - 1; ++i) {
            cur = cur.next;
        }
        newNode.next = cur.next;
        cur.next = newNode;
        size++;
    }

    /**
     * Deletes a node at the head
     */
    public void deleteHead() {
        deleteNth(0);
    }

    /**
     * Deletes an element at the tail
     */
    public void delete() {
        deleteNth(size - 1);
    }

    /**
     * Deletes an element at Nth position
     */
    public void deleteNth(int position) {
        checkBounds(position, 0, size - 1);
        if (position == 0) {
            head = head.next;
            /* clear to let GC do its work */
            size--;
            return;
        }
        SinglyLinkedListNode cur = head;
        for (int i = 0; i < position - 1; ++i) {
            cur = cur.next;
        }

        cur.next = cur.next.next;
        size--;
    }

    /**
     * Return element at special index.
     *
     * @param index given index of element
     * @return element at special index.
     */
    public int getNth(int index) {
        checkBounds(index, 0, size - 1);
        SinglyLinkedListNode cur = head;
        for (int i = 0; i < index; ++i) {
            cur = cur.next;
        }
        return cur.value;
    }

    /**
     * @param position to check position
     * @param low low index
     * @param high high index
     * @throws IndexOutOfBoundsException if {@code position} not in range
     * {@code low} to {@code high}
     */
    public void checkBounds(int position, int low, int high) {
        if (position > high || position < low) {
            throw new IndexOutOfBoundsException(position + "");
        }
    }

    /**
     * Driver Code
     */
    public static void main(String[] arg) {
        SinglyLinkedList list = new SinglyLinkedList();
        assert list.isEmpty();
        assert list.size() == 0 && list.count() == 0;
        assert list.toString().isEmpty();

        /* Test insert function */
        list.insertHead(5);
        list.insertHead(7);
        list.insertHead(10);
        list.insert(3);
        list.insertNth(1, 4);
        assert list.toString().equals("10->7->5->3->1");
        System.out.println(list);
        /* Test search function */
        assert list.search(10) && list.search(5) && list.search(1) && !list.search(100);

        /* Test get function */
        assert list.getNth(0) == 10 && list.getNth(2) == 5 && list.getNth(4) == 1;

        /* Test delete function */
        list.deleteHead();
        list.deleteNth(1);
        list.delete();
        assert list.toString().equals("7->3");
        System.out.println(list);
        assert list.size == 2 && list.size() == list.count();

        list.clear();
        assert list.isEmpty();

        try {
            list.delete();
            assert false;
            /* this should not happen */
        } catch (Exception e) {
            assert true;
            /* this should happen */
        }

        SinglyLinkedList instance = new SinglyLinkedList();
        SinglyLinkedListNode head = new SinglyLinkedListNode(0, new SinglyLinkedListNode(2, new SinglyLinkedListNode(3, new SinglyLinkedListNode(3, new SinglyLinkedListNode(4)))));
        instance.setHead(head);
        instance.deleteDuplicates();
        instance.print();
    }

    @Override
    public Iterator<Integer> iterator() {
        return new SinglyLinkedListIterator();
    }

    private class SinglyLinkedListIterator implements Iterator<Integer> {
        private SinglyLinkedListNode current;

        SinglyLinkedListIterator() {
            current = head;
        }

        @Override
        public boolean hasNext() {
            return current != null;
        }

        @Override
        public Integer next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            final var value = current.value;
            current = current.next;
            return value;
        }
    }
}

public class RunnableOrnegi implements Runnable {

    private String mesaj; // Yazdirilacak mesaj
    private int gecikme; // Gecikme suresi (milisaniye cinsinden)
    private volatile boolean calisiyor = true; // Thread'in calisma durumu

    // Constructor: Mesaj ve gecikme suresi ile nesne olusturur
    public RunnableOrnegi(String mesaj, int gecikme) {
        this.mesaj = mesaj;
        this.gecikme = gecikme;
    }

    // Thread'in calisacak metodu
    public void run() {
        while (calisiyor) {
            System.out.println(Thread.currentThread().getName() + ": " + mesaj); // Mesaji yazdir
            try {
                Thread.sleep(gecikme); // Belirtilen sure kadar bekle
            } catch (InterruptedException e) {
                System.out.println(Thread.currentThread().getName() + " kesildi.");
                return; // Kesinti durumunda thread sonlandirilir
            }
        }
        System.out.println(Thread.currentThread().getName() + " durduruldu.");
    }

    // Thread'i durdurma metodu
    public void durdur() {
        calisiyor = false;
    }

    // Ana metod
    public static void main(String[] args) {
        // Thread nesnelerini tutmak icin
        RunnableOrnegi runnable1 = new RunnableOrnegi("ali", 1000);
        Thread t1 = new Thread(runnable1, "Thread-1");

        RunnableOrnegi runnable2 = new RunnableOrnegi("veli", 2000);
        Thread t2 = new Thread(runnable2, "Thread-2");

        RunnableOrnegi runnable3 = new RunnableOrnegi("ayse", 3000);
        Thread t3 = new Thread(runnable3, "Thread-3");

        // Thread'leri baslat
        t1.start();
        t2.start();
        t3.start();

        // Belirli bir sure sonra tum thread'leri durdur
        try {
            Thread.sleep(10000); // 10 saniye bekle
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("Thread'ler durduruluyor...");
        runnable1.durdur();
        runnable2.durdur();
        runnable3.durdur();

        try {
            t1.join(); // Thread-1'in bitmesini bekle
            t2.join(); // Thread-2'nin bitmesini bekle
            t3.join(); // Thread-3'un bitmesini bekle
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("Program sonlandi.");
    }
}

/**
 * @author shikarisohan
 * @since 10/5/24
 *
 *  * The Liang-Barsky line clipping algorithm is an efficient algorithm for
 *  * line clipping against a rectangular window. It is based on the parametric
 *  * equation of a line and checks the intersections of the line with the
 *  * window boundaries. This algorithm calculates the intersection points,
 *  * if any, and returns the clipped line that lies inside the window.
 *  *
 *  * Reference:
 *  * https://en.wikipedia.org/wiki/Liang%E2%80%93Barsky_algorithm
 *
 * Clipping window boundaries are defined as (xMin, yMin) and (xMax, yMax).
 * The algorithm computes the clipped line segment if it's partially or
 * fully inside the clipping window.
 */
public class LiangBarsky {

    // Define the clipping window
    double xMin;
    double xMax;
    double yMin;
    double yMax;

    public LiangBarsky(double xMin, double yMin, double xMax, double yMax) {
        this.xMin = xMin;
        this.yMin = yMin;
        this.xMax = xMax;
        this.yMax = yMax;
    }

    // Liang-Barsky algorithm to return the clipped line
    public Line liangBarskyClip(Line line) {
        double dx = line.end.x - line.start.x;
        double dy = line.end.y - line.start.y;

        double[] p = {-dx, dx, -dy, dy};
        double[] q = {line.start.x - xMin, xMax - line.start.x, line.start.y - yMin, yMax - line.start.y};

        double[] resultT = clipLine(p, q);

        if (resultT == null) {
            return null; // Line is outside the clipping window
        }

        return calculateClippedLine(line, resultT[0], resultT[1], dx, dy);
    }

    // clip the line by adjusting t0 and t1 for each edge
    private double[] clipLine(double[] p, double[] q) {
        double t0 = 0.0;
        double t1 = 1.0;

        for (int i = 0; i < 4; i++) {
            double t = q[i] / p[i];
            if (p[i] == 0 && q[i] < 0) {
                return null; // Line is outside the boundary
            } else if (p[i] < 0) {
                if (t > t1) {
                    return null;
                } // Line is outside
                if (t > t0) {
                    t0 = t;
                } // Update t0
            } else if (p[i] > 0) {
                if (t < t0) {
                    return null;
                } // Line is outside
                if (t < t1) {
                    t1 = t;
                } // Update t1
            }
        }

        return new double[] {t0, t1}; // Return valid t0 and t1
    }

    // calculate the clipped line based on t0 and t1
    private Line calculateClippedLine(Line line, double t0, double t1, double dx, double dy) {
        double clippedX1 = line.start.x + t0 * dx;
        double clippedY1 = line.start.y + t0 * dy;
        double clippedX2 = line.start.x + t1 * dx;
        double clippedY2 = line.start.y + t1 * dy;

        return new Line(new Point(clippedX1, clippedY1), new Point(clippedX2, clippedY2));
    }
}

public class SayiTahminOyunu {

    public static void main(String[] args) {

        // Draw the secret number from the inclusive range 1..10.
        Random rng = new Random();
        int secret = rng.nextInt(10) + 1;

        Scanner input = new Scanner(System.in);
        System.out.println("Tahmininizi girin (1-10):");
        int guess = input.nextInt();
        input.close();

        boolean isCorrect = guess == secret;

        if (isCorrect) {
            System.out.println("Tebrikler! Dogru sayiyi tahmin ettiniz!");
        } else {
            System.out.println("Uzgunum, dogru sayi " + secret + " idi.");
        }
    }
}

/**
 * A Java program that computes the convex hull using the Graham Scan algorithm.
 * The time complexity is O(n) in the best case and O(n log(n)) in the worst case.
 * The space complexity is O(n).
 * This algorithm is applicable only to integral coordinates.
 *
 * References:
 * https://github.com/TheAlgorithms/C-Plus-Plus/blob/master/geometry/graham_scan_algorithm.cpp
 * https://github.com/TheAlgorithms/C-Plus-Plus/blob/master/geometry/graham_scan_functions.hpp
 * https://algs4.cs.princeton.edu/99hull/GrahamScan.java.html
 */
public class GrahamScan {

    private final Stack<Point> hull = new Stack<>();

    public GrahamScan(Point[] points) {
        // Pre-process points: sort by y-coordinate, then by polar order with respect to the first point
        Arrays.sort(points);
        Arrays.sort(points, 1, points.length, points[0].polarOrder());

        hull.push(points[0]);

        // Find the first point not equal to points[0] (firstNonEqualIndex)
        // and the first point not collinear firstNonCollinearIndex with the previous points
        int firstNonEqualIndex;
        for (firstNonEqualIndex = 1; firstNonEqualIndex < points.length; firstNonEqualIndex++) {
            if (!points[0].equals(points[firstNonEqualIndex])) {
                break;
            }
        }

        if (firstNonEqualIndex == points.length) {
            return;
        }

        int firstNonCollinearIndex;
        for (firstNonCollinearIndex = firstNonEqualIndex + 1; firstNonCollinearIndex < points.length; firstNonCollinearIndex++) {
            if (Point.orientation(points[0], points[firstNonEqualIndex], points[firstNonCollinearIndex]) != 0) {
                break;
            }
        }

        hull.push(points[firstNonCollinearIndex - 1]);

        // Process the remaining points and update the hull
        for (int i = firstNonCollinearIndex; i < points.length; i++) {
            Point top = hull.pop();
            while (Point.orientation(hull.peek(), top, points[i]) <= 0) {
                top = hull.pop();
            }
            hull.push(top);
            hull.push(points[i]);
        }
    }

    /**
     * @return An iterable collection of points representing the convex hull.
     */
    public Iterable<Point> hull() {
        return new ArrayList<>(hull);
    }
}

