package tankgame;

import java.awt.Color;

public abstract class Tanksavar {
	int x, y, genislik, yukseklik;
	Color renk;
	Top top;

	public Tanksavar(int x, int y, Color renk) {
		this.x = x;
		this.y = y;
		this.genislik = 40;
		this.yukseklik = 30;
		this.renk = renk;
	}

	public abstract Top topAt();
}

/**
 * Counts occurrences of each lowercase word in a line of input.
 */
public class WordCount {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String line = scanner.nextLine().trim();
        StringTokenizer tokenizer = new StringTokenizer(line, " ");
        Hashtable<String, Integer> counts = new Hashtable<>(100, 0.2f);
        while (tokenizer.hasMoreTokens()) {
            String word = tokenizer.nextToken().toLowerCase();
            int newCount = counts.containsKey(word) ? counts.get(word) + 1 : 1;
            counts.put(word, newCount);
        }
        counts.forEach((key, value) -> System.out.println(key + " " + value));
    }
}

package com.thealgorithms.datastructures.hashmap.hashing;

import java.util.Scanner;

public final class MainCuckooHashing {
    private MainCuckooHashing() {
    }

    public static void main(String[] args) {
        int choice;
        int key;

        HashMapCuckooHashing h = new HashMapCuckooHashing(7);
        Scanner scan = new Scanner(System.in);

        while (true) {
            System.out.println("_________________________");
            System.out.println("Enter your Choice :");
            System.out.println("1. Add Key");
            System.out.println("2. Delete Key");
            System.out.println("3. Print Table");
            System.out.println("4. Exit");
            System.out.println("5. Search and print key index");
            System.out.println("6. Check load factor");
            System.out.println("7. Rehash Current Table");

            choice = scan.nextInt();

            switch (choice) {
            case 1:
