package ifcondition; 
import java.util.Scanner;

public class NotHesaplama {

	// 'harfNotunaCevir' metodu, girilen sayisal notu harf notuna cevirir
	public static void harfNotunaCevir(int not) {
		// Not 90 veya daha yuksekse 'A' harf notu verilir
		if (not >= 90) {
			System.out.println("A");
		} 
		// Not 80 veya daha yuksekse 'B' harf notu verilir
		else if (not >= 80) {
			System.out.println("B");
		} 
		// Not 70 veya daha yuksekse 'C' harf notu verilir
		else if (not >= 70) {
			System.out.println("C");
		} 
		// Not 60 veya daha yuksekse 'D' harf notu verilir
		else if (not >= 60) {
			System.out.println("D");
		} 
		// Diger durumlar icin 'F' harf notu verilir
		else {
			System.out.println("F");
		}
	}

	public static void main(String[] args) {

		Scanner scanner = new Scanner(System.in);

		// Kullaniciya notunu girmesini iste
		System.out.print("Notunuzu girin: ");
		int not = scanner.nextInt();

		// 'harfNotunaCevir' metodu ile sayisal not harf notuna cevir
		harfNotunaCevir(not);

		// Scanner nesnesi kapat
		scanner.close();
	}
}

/**
 * Mimics the actions of the Original buffered reader
 * implements other actions, such as peek(n) to lookahead,
 * block() to read a chunk of size {BUFFER SIZE}
 * <p>
 * Author: Kumaraswamy B.G (Xoma Dev)
 */
public class BufferedReader {

    private static final int DEFAULT_BUFFER_SIZE = 5;

    /**
     * The maximum number of bytes the buffer can hold.
     * Value is changed when encountered Eof to not
     * cause overflow read of 0 bytes
     */

    private int bufferSize;
    private final byte[] buffer;

    /**
     * posRead -> indicates the next byte to read
     */
    private int posRead = 0;
    private int bufferPos = 0;

    private boolean foundEof = false;

    private InputStream input;

    public BufferedReader(byte[] input) throws IOException {
        this(new ByteArrayInputStream(input));
    }

    public BufferedReader(InputStream input) throws IOException {
        this(input, DEFAULT_BUFFER_SIZE);
    }

    public BufferedReader(InputStream input, int bufferSize) throws IOException {
        this.input = input;
        if (input.available() == -1) {
            throw new IOException("Empty or already closed stream provided");
        }

        this.bufferSize = bufferSize;
        buffer = new byte[bufferSize];
    }

    /**
     * Reads a single byte from the stream
     */
    public int read() throws IOException {
        if (needsRefill()) {
            if (foundEof) {
                return -1;
            }
            // the buffer is empty, or the buffer has
            // been completely read and needs to be refilled
            refill();
        }
        return buffer[posRead++] & 0xff; // read and un-sign it
    }

    /**
     * Number of bytes not yet been read
     */

    public int available() throws IOException {
        int available = input.available();
        if (needsRefill()) {
            // since the block is already empty,
            // we have no responsibility yet
            return available;
        }
        return bufferPos - posRead + available;
    }

    /**
     * Returns the next character
     */

    public int peek() throws IOException {
        return peek(1);
    }

    /**
     * Peeks and returns a value located at next {n}
     */

    public int peek(int n) throws IOException {
        int available = available();
        if (n >= available) {
            throw new IOException("Out of range, available %d, but trying with %d".formatted(available, n));
        }
        pushRefreshData();

        if (n >= bufferSize) {
            throw new IllegalAccessError("Cannot peek %s, maximum upto %s (Buffer Limit)".formatted(n, bufferSize));
        }
        return buffer[n];
    }

    /**
     * Removes the already read bytes from the buffer
     * in-order to make space for new bytes to be filled up.
     * <p>
     * This may also do the job to read first time data (the whole buffer is empty)
     */

    private void pushRefreshData() throws IOException {
        for (int i = posRead, j = 0; i < bufferSize; i++, j++) {
            buffer[j] = buffer[i];
        }

        bufferPos -= posRead;
        posRead = 0;

        // fill out the spaces that we've
        // emptied
        justRefill();
    }

    /**
     * Reads one complete block of size {bufferSize}
     * if found eof, the total length of an array will
     * be that of what's available
     *
     * @return a completed block
     */
    public byte[] readBlock() throws IOException {
        pushRefreshData();

        byte[] cloned = new byte[bufferSize];
        // arraycopy() function is better than clone()
        if (bufferPos >= 0) {
            System.arraycopy(buffer, 0, cloned, 0,
                // important to note that, bufferSize does not stay constant
                // once the class is defined. See justRefill() function
                bufferSize);
        }
        // we assume that already a chunk
        // has been read
        refill();
        return cloned;
    }

    private boolean needsRefill() {
        return bufferPos == 0 || posRead == bufferSize;
    }

    private void refill() throws IOException {
        posRead = 0;
        bufferPos = 0;
        justRefill();
    }

    private void justRefill() throws IOException {
        assertStreamOpen();

        // try to fill in the maximum we can until
        // we reach EOF
        while (bufferPos < bufferSize) {
            int read = input.read();
            if (read == -1) {
                // reached end-of-file, no more data left
                // to be read
                foundEof = true;
                // rewrite the BUFFER_SIZE, to know that we've reached
                // EOF when requested refill
                bufferSize = bufferPos;
            }
            buffer[bufferPos++] = (byte) read;
        }
    }

    private void assertStreamOpen() {
        if (input == null) {
            throw new IllegalStateException("Input Stream already closed!");
        }
    }

    public void close() throws IOException {
        if (input != null) {
            try {
                input.close();
            } finally {
                input = null;
            }
        }
    }
}

// java.awt.Robot kullanarak ekran goruntusu yakalayan yardimci sinif
import java.awt.AWTException;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.awt.Robot;
import java.awt.Toolkit;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;

/** Tum ekranin goruntusunu yakalayip PNG olarak diske kaydeder. */
public class EkranGoruntusuAlma {

    /** Ekran boyutunu tespit edip Robot ile anlik goruntu alarak dosyaya yazar. */
    public static void yakalaVeKaydet(String hedefDosyaAdi) throws AWTException, IOException {
        Dimension boyut = Toolkit.getDefaultToolkit().getScreenSize();
        System.out.println("Ekran Boyutu: " + boyut);

        Rectangle tamEkranAlani = new Rectangle(boyut);

        Robot yakalayici = new Robot();
        BufferedImage anlikGoruntu = yakalayici.createScreenCapture(tamEkranAlani);

        ImageIO.write(anlikGoruntu, "png", new File(hedefDosyaAdi));
    }

    public static void main(String[] args) throws AWTException, IOException {
        yakalaVeKaydet("ekran.png");
    }
}

package recursive;
import java.util.Scanner;

public class EnBuyukOrtakBolen {

	// Iki sayinin ortak bolenlerinin en buyugunu Oklid algoritmasiyla hesaplar
	public static int ortakBolenBul(int birinci, int ikinci) {
		int x = birinci;
		int y = ikinci;
		// ikinci deger sifira dusene kadar kalanla islem tekrarlanir
		while (y != 0) {
			int kalan = x % y;
			x = y;
			y = kalan;
		}
		return x;
	}

	public static void main(String[] args) {

		Scanner tarayici = new Scanner(System.in);
		System.out.print("Ebobu bulmak icin bir sayi girin: ");
		int ilkSayi = tarayici.nextInt();
		System.out.print("Ebob bulmak icin bir sayi daha girin: ");
		int ikinciSayi = tarayici.nextInt();
		tarayici.close();

		int ebobSonucu = ortakBolenBul(ilkSayi, ikinciSayi);
		System.out.print("En buyuk ortak bolen: " + ebobSonucu);
	}
}

public class KartNumarasiDogrulayici {

    // Bir sayinin rakamlarinin toplamini hesaplayan yontem
    // Ornek: 123 -> 1+2+3 = 6
    static int rakamlarToplami(int sayi) {
        int toplam = 0;
        while (sayi > 0) {
            toplam += sayi % 10; // Sayinin son rakamini toplama ekle
            sayi = sayi / 10; // Sayinin son rakamini at
        }
        return toplam;
    }

    // Bir diziyi ekrana yazdiran yardimci yontem (debug icin kullanilir)
    // Ornek: [1, 2, 3, 4] -> Dizi: 1 2 3 4
    static void ekranaYazdir(int[] dizi) {
        System.out.print("Dizi: ");
        for (int i = 0; i < dizi.length; i++) {
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }

    // Kart numarasini tamsayi dizisine donusturur
    // Ornek: "4532" -> [4, 5, 3, 2]
    static int[] tamsayiDizisineCevir(String kartNumarasi) {
        int[] dizi = new int[kartNumarasi.length()];

        for (int i = 0; i < dizi.length; i++) {
            dizi[i] = Integer.parseInt(kartNumarasi.charAt(i) + ""); // Her karakteri sayiya cevir ve diziye ekle
        }

        // Debug icin diziyi yazdiriyoruz
        ekranaYazdir(dizi);
        return dizi;
    }

    // Her ikinci haneyi (sagdan baslamak uzere) ikiyle carpar
    // Luhn algoritmasina gore islem yapar
    static int[] ciftHaneleriIkiyleCarp(int[] dizi) {
        for (int i = dizi.length - 2; i >= 0; i -= 2) { // Sagdan ikinci elemandan baslayarak sola dogru ilerle
            dizi[i] *= 2; // Elemani ikiyle carp
        }

        // Debug icin diziyi yazdiriyoruz
        ekranaYazdir(dizi);
        return dizi;
    }

    // Bir dizinin tum elemanlarinin toplamini hesaplar
    // Ornek: [1, 2, 3] -> 1+2+3 = 6
    static int elemanlarToplami(int[] dizi) {
        int toplam = 0;
        for (int i = 0; i < dizi.length; i++) {
            toplam += dizi[i]; // Her elemani toplama ekle
        }

        System.out.println("Dizi elemanlar toplami: " + toplam);
        return toplam;
    }

    // Kart numarasini dogrulayan yontem
    // Luhn algoritmasina gore kartin gecerli olup olmadigini kontrol eder
    static boolean kartGecerliMi(String kartNumarasi) {
        int[] dizi = tamsayiDizisineCevir(kartNumarasi); // Kart numarasini tamsayi dizisine cevir
        dizi = ciftHaneleriIkiyleCarp(dizi); // Her ikinci haneyi ikiyle carp

        for (int i = 0; i < dizi.length; i++) {
            dizi[i] = rakamlarToplami(dizi[i]); // Elemanlarin rakamlar toplamini hesapla
        }

        int toplam = elemanlarToplami(dizi); // Elemanlarin toplamini hesapla
        return toplam % 10 == 0; // Toplamin 10'a bolumunden kalan 0 ise gecerlidir
    }

    // Test ve kullanici giris islemleri
    // Ornek kart numaralari ile test islemi yapar ve kullanicidan kart numarasi ister
    static void kartDogrulamaTesti() {
        // Ornek kart numaralari
        String[] kartNumaralari = {"4532015112830366", "6011514433546201", "378282246310005", "1234567890123456", "1111222333334444"};

        for (String kart : kartNumaralari) {
            System.out.println(kart + " -> " + (kartGecerliMi(kart) ? "Gecerli" : "Gecersiz"));
            System.out.println();
        }
    }

    // Kullanicidan kart numarasi alir ve dogrulugunu kontrol eder
    static void kullaniciGirisi() {
        // Kullanicidan kart numarasi isteme
        Scanner klavye = new Scanner(System.in);
        System.out.println("\nKart numaranizi giriniz:");
        String kartNumarasi = klavye.next();

        while (!kartNumarasi.matches("\\d{13,19}")) { // Kart numarasinin 13-19 haneli olup olmadigini kontrol et
            System.out.println("Lutfen gecerli bir kart numarasi giriniz (13-19 hane):");
            kartNumarasi = klavye.next();
        }
        klavye.close();

        // Kartin dogrulugunu kontrol etme
        if (kartGecerliMi(kartNumarasi)) {
            System.out.println("Kart numarasi dogru.");
        } else {
            System.out.println("Kart numarasi yanlis.");
        }
    }

    public static void main(String[] args) {
        kartDogrulamaTesti(); // Ornek kart numaralarini test et
        kullaniciGirisi(); // Kullanicidan kart numarasi al ve dogrulugunu kontrol et
    }
}

public class KabarcikSiralama {

    public static void main(String[] args) {

        int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        // Kabarcik siralama uygula
        kabarcikSiralama(dizi);

        // Siralanmis diziyi ekrana yazdir
        System.out.println("Siralanmis Dizi:");
        for (int i = 0; i < dizi.length; i++) {
            System.out.print(dizi[i] + " ");
        }
    }

    static void kabarcikSiralama(int[] dizi) {

        for (int i = 0; i < dizi.length - 1; i++) {
            // Siralama islemi icin tekrar et
            for (int j = 0; j < dizi.length - i - 1; j++) {
                if (dizi[j] > dizi[j + 1]) {
                    // Elemanlari yer degistir
                    int gecici = dizi[j];
                    dizi[j] = dizi[j + 1];
                    dizi[j + 1] = gecici;
                }
            }
        }
    }
}

