public class Part3 {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        ArrayList<Student> listStudents = new ArrayList<Student>();
        System.out.print("Enter number student: ");
        int n=scanner.nextInt();
        scanner.nextLine();
        for(int i=0 ; i<n;i++){
            System.out.print("Enter name student " + (i+1) + ": ");
            String name=scanner.nextLine();
            name=name.trim().replaceAll("\\s+", " ");
            StringTokenizer token = new StringTokenizer(name, " ");
            name="";
            while(token.hasMoreTokens()){
                String newName =token.nextToken();
                name+=newName.substring(0,1).toUpperCase() + newName.substring(1) + " ";
            }
            Student student = new Student(name.trim());
            listStudents.add(student);
        }
        for (Student student : listStudents) {
            System.out.println(student.toString());
        }
    }
}

public class KuvvetTablosu {

    public static void main(String[] args) {

        // Tablo basligini yazdir
        System.out.printf("%8s %8s %8s %8s %8s %8s%n", "Sayi", "^1", "^2", "^3", "^4", "^5");
        // Baslik altina bir ayirac cizgisi ekle
        System.out.println("-------------------------------------------------------");

        // 1'den 10'a kadar olan sayilar icin dongu
        for (int sayi = 1; sayi <= 10; sayi++) {
            // Sayiyi yazdir
            System.out.printf("%9d", sayi);
            // 1'den 5. kuvvete kadar olan degerleri hesaplamak icin ic dongu
            for (int kuvvet = 1; kuvvet <= 5; kuvvet++) {
                // Kuvvet degerini hesapla ve yazdir
                System.out.printf("%9d", (int) Math.pow(sayi, kuvvet));
            }
            // Her sayinin hesaplamasi tamamlandiktan sonra bir alt satira gec
            System.out.println();
        }
    }
}

/**
 * @author Varun Upadhyay (<a href="https://github.com/varunu28">...</a>)
 */
public final class AnyBaseToDecimal {
private static final int DIGIT_OFFSET = '0';
private static final int UPPERCASE_OFFSET = 'A' - 10;

private AnyBaseToDecimal() {
}

/**
 * Convert any radix to a decimal number.
 *
 * @param sourceString the string to be converted
 * @param sourceBase the radix (base) of the input string
 * @return the decimal equivalent of the input string
 * @throws NumberFormatException if the input string or radix is invalid
 */
public static int convertToDecimal(String sourceString, int sourceBase) {
int decimalResult = 0;
int positionalMultiplier = 1;
for (int index = sourceString.length() - 1; index >= 0; index--) {
int digitValue = getNumericValue(sourceString.charAt(index));
if (digitValue >= sourceBase) {
throw new NumberFormatException("For input string: " + sourceString);
}
decimalResult += digitValue * positionalMultiplier;
positionalMultiplier *= sourceBase;
}
return decimalResult;
}

/**
 * Convert a character to its integer value.
 *
 * @param inputSymbol the character to be converted
 * @return the integer value represented by the character
 * @throws NumberFormatException if the character is not an uppercase letter or a digit
 */
private static int getNumericValue(char inputSymbol) {
if (Character.isDigit(inputSymbol)) {
return inputSymbol - DIGIT_OFFSET;
} else if (Character.isUpperCase(inputSymbol)) {
return inputSymbol - UPPERCASE_OFFSET;
} else {
throw new NumberFormatException("invalid character:" + inputSymbol);
}
}
}

package com.thealgorithms.datastructures.crdt;

import java.util.HashSet;
import java.util.Set;

/**
 * GSet (Grow-only Set) is a state-based CRDT (Conflict-free Replicated Data Type)
 * that allows only the addition of elements and ensures that once an element is added,
 * it cannot be removed. The merge operation of two G-Sets is their union.
 * This implementation supports adding elements, looking up elements, comparing with other G-Sets,
 * and merging with another G-Set to create a new G-Set containing all unique elements from both sets.
 * (https://en.wikipedia.org/wiki/Conflict-free_replicated_data_type)
 *
 * @author itakurah (Niklas Hoefflin) (https://github.com/itakurah)
 */

public class GSet<T> {
    private final Set<T> elements;

    /**
     * Constructs an empty G-Set.
     */
    public GSet() {
        this.elements = new HashSet<>();
    }

    /**
     * Adds an element to the G-Set.
     *
     * @param e the element to be added
     */
    public void addElement(T e) {
        elements.add(e);
    }

    /**
     * Checks if the given element is present in the G-Set.
     *
     * @param e the element to be checked
     * @return true if the element is present, false otherwise
     */
    public boolean lookup(T e) {
        return elements.contains(e);
    }

    /**
     * Compares the G-Set with another G-Set to check if it is a subset.
     *
     * @param other the other G-Set to compare with
     * @return true if the current G-Set is a subset of the other, false otherwise
     */
    public boolean compare(GSet<T> other) {
        return other.elements.containsAll(elements);
    }

    /**
     * Merges the current G-Set with another G-Set, creating a new G-Set
     * containing all unique elements from both sets.
     *
     * @param other the G-Set to merge with
     */
    public void merge(GSet<T> other) {
        elements.addAll(other.elements);
    }
}

/**
 * @author moksedursohan
 * @since 10/4/24
 */
public class Line {

    public Point start;
    public Point end;

    public Line() {
    }

    public Line(Point start, Point end) {
        this.start = start;
        this.end = end;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Line line)) {
            return false;
        }

        return Objects.equals(start, line.start) && Objects.equals(end, line.end);
    }

    @Override
    public int hashCode() {
        return Objects.hash(start, end);
    }

    @Override
    public String toString() {
        return "Line from " + start + " to " + end;
    }
}

