// package tanimlamasi
package overloading;

// HesapMakinesi sinifini tanimla
public class HesapMakinesi {

    int hafiza = 0; // Bellek degiskeni, son islemin sonucunu tutar

    // iki tamsayiyi topla
    public int topla(int sayi1, int sayi2) {
        hafiza = sayi1 + sayi2; // Hafizaya sonucu kaydet
        return hafiza; // Sonucu dondur
    }

    // iki double sayiyi topla
    public double topla(double sayi1, double sayi2) {
        return sayi1 + sayi2; // Sonucu direkt dondur
    }

    // uc tamsayiyi topla
    public int topla(int sayi1, int sayi2, int sayi3) {
        return sayi1 + sayi2 + sayi3; // Sonucu direkt dondur
    }

    // Bir tamsayi dizisinin elemanlarini topla
    public int topla(int[] sayilar) {
        int toplam = 0;
        for (int sayi : sayilar) {
            toplam += sayi; // Dizideki her elemani toplama ekle
        }
        return toplam; // Toplam sonucu dondur
    }

    // iki tamsayiyi cikar
    public int cikar(int sayi1, int sayi2) {
        return sayi1 - sayi2; // Sonucu dondur
    }

    // iki double sayiyi cikar
    public double cikar(double sayi1, double sayi2) {
        return sayi1 - sayi2; // Sonucu dondur
    }

    // iki tamsayiyi carp
    public int carp(int sayi1, int sayi2) {
        return sayi1 * sayi2; // Sonucu dondur
    }

    // iki double sayiyi carp
    public double carp(double sayi1, double sayi2) {
        return sayi1 * sayi2; // Sonucu dondur
    }

    // iki tamsayiyi bol
    public int bol(int sayi1, int sayi2) {
        if (sayi2 == 0) {
            throw new ArithmeticException("Bolme islemi icin bolen sifir olamaz!"); // Hata durumu
        }
        return sayi1 / sayi2; // Sonucu dondur
    }

    // iki double sayiyi bol
    public double bol(double sayi1, double sayi2) {
        if (sayi2 == 0.0) {
            throw new ArithmeticException("Bolme islemi icin bolen sifir olamaz!"); // Hata durumu
        }
        return sayi1 / sayi2; // Sonucu dondur
    }

    // Ana metot (main method)
    public static void main(String[] args) {
        // HesapMakinesi sinifindan nesne olustur
        HesapMakinesi hesapMakinesi = new HesapMakinesi();

        // Overloading kullanimi
        int sonuc1 = hesapMakinesi.topla(5, 3); // iki tamsayi toplama
        double sonuc2 = hesapMakinesi.topla(3.5, 2.7); // iki double sayi toplama
        int sonuc3 = hesapMakinesi.topla(4, 6, 8); // uc tamsayi toplama

        int[] sayilar = {1, 2, 3, 4, 5};
        int sonuc4 = hesapMakinesi.topla(sayilar); // Tamsayi dizisi toplama

        int sonuc5 = hesapMakinesi.cikar(10, 4); // iki tamsayi cikarma
        double sonuc6 = hesapMakinesi.cikar(7.8, 2.4); // iki double sayi cikarma

        int sonuc7 = hesapMakinesi.carp(3, 5); // iki tamsayi carpma
        double sonuc8 = hesapMakinesi.carp(2.5, 4.0); // iki double sayi carpma

        int sonuc9 = hesapMakinesi.bol(20, 4); // iki tamsayi bolme
        double sonuc10 = hesapMakinesi.bol(9.0, 3.0); // iki double sayi bolme

        // Sonuclari ekrana yazdir
        System.out.println("Sonuc 1: " + sonuc1);
        System.out.println("Sonuc 2: " + sonuc2);
        System.out.println("Sonuc 3: " + sonuc3);
        System.out.println("Sonuc 4 (Dizi toplama): " + sonuc4);
        System.out.println("Sonuc 5 (cikarma): " + sonuc5);
        System.out.println("Sonuc 6 (Double cikarma): " + sonuc6);
        System.out.println("Sonuc 7 (carpma): " + sonuc7);
        System.out.println("Sonuc 8 (Double carpma): " + sonuc8);
        System.out.println("Sonuc 9 (Bolme): " + sonuc9);
        System.out.println("Sonuc 10 (Double bolme): " + sonuc10);
    }
}

/**
 * Listens for client connections and hands each one off to a pooled
 * worker that echoes back every line in upper case.
 */
public class CapitalizeServer {

    private static final int PORT = 59898;
    private static final int MAX_WORKERS = 20;

    public static void main(String[] args) throws Exception {
        try (var serverSocket = new ServerSocket(PORT)) {
            System.out.println("Buyuk harfe cevirme sunucusu calisiyor...");

            ExecutorService workers = Executors.newFixedThreadPool(MAX_WORKERS);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                workers.execute(new UppercaseWorker(clientSocket));
            }
        }
    }

    // Handles a single client connection: reads lines, replies uppercased
    private static class UppercaseWorker implements Runnable {
        private final Socket clientSocket;

        UppercaseWorker(Socket clientSocket) {
            this.clientSocket = clientSocket;
        }

        @Override
        public void run() {
            System.out.println("Baglantili: " + clientSocket);
            try (var reader = new Scanner(clientSocket.getInputStream())) {
                var writer = new PrintWriter(clientSocket.getOutputStream(), true);

                while (reader.hasNextLine()) {
                    writer.println(reader.nextLine().toUpperCase());
                }
            } catch (Exception e) {
                System.out.println("Hata: " + clientSocket);
            } finally {
                try {
                    clientSocket.close();
                } catch (IOException e) {
                    System.out.println("Hata: " + clientSocket);
                }
                System.out.println("Kapatildi: " + clientSocket);
            }
        }
    }
}

/**
 * The CompositeLFSR class represents a composite implementation of
 * Linear Feedback Shift Registers (LFSRs) for cryptographic purposes.
 *
 * <p>
 * This abstract class manages a collection of LFSR instances and
 * provides a mechanism for irregular clocking based on the
 * majority bit among the registers. It implements the BaseLFSR
 * interface, requiring subclasses to define specific LFSR behaviors.
 * </p>
 */
public abstract class CompositeLFSR implements BaseLFSR {

    protected final List<LFSR> registers = new ArrayList<>();

    /**
     * Performs a clocking operation on the composite LFSR.
     *
     * <p>
     * This method determines the majority bit across all registers and
     * clocks each register based on its clock bit. If a register's
     * clock bit matches the majority bit, it is clocked (shifted).
     * The method also computes and returns the XOR of the last bits
     * of all registers.
     * </p>
     *
     * @return the XOR value of the last bits of all registers.
     */
    @Override
    public boolean clock() {
        boolean majorityBit = getMajorityBit();
        boolean result = false;
        for (var register : registers) {
            result ^= register.getLastBit();
            if (register.getClockBit() == majorityBit) {
                register.clock();
            }
        }
        return result;
    }

    /**
     * Calculates the majority bit among all registers.
     *
     * <p>
     * This private method counts the number of true and false clock bits
     * across all LFSR registers. It returns true if the count of true
     * bits is greater than or equal to the count of false bits; otherwise,
     * it returns false.
     * </p>
     *
     * @return true if the majority clock bits are true; false otherwise.
     */
    private boolean getMajorityBit() {
        Map<Boolean, Integer> bitCount = new TreeMap<>();
        bitCount.put(Boolean.FALSE, 0);
        bitCount.put(Boolean.TRUE, 0);

        registers.forEach(lfsr -> bitCount.put(lfsr.getClockBit(), bitCount.get(lfsr.getClockBit()) + 1));
        return bitCount.get(Boolean.FALSE) <= bitCount.get(Boolean.TRUE);
    }
}

// Digital Root: Bir sayinin basamaklarini tekrarli olarak toplar ve tek bir basamak kalana kadar devam eder.


public class DijitalKok {

    public static void main(String[] args) {

        // Kullanicidan bir sayi girdisi al
        Scanner tarayici = new Scanner(System.in);
        System.out.print("Bir sayi giriniz: ");
        int sayi = tarayici.nextInt();

        // Dijital kok hesaplama
        int dijitalKok = sayi;

        // Tek basamak kalana kadar dongu
        while (dijitalKok >= 10) {
            int gecici = dijitalKok; // Gecici degisken
            int toplam = 0; // Basamak toplami

            // Basamaklari toplama islemi
            while (gecici > 0) {
                toplam += gecici % 10; // Son basamagi toplama ekle
                gecici /= 10; // Son basamagi cikar
            }

            dijitalKok = toplam; // Yeni dijital kok degerini guncelle
        }

        // Sonuc yazdir
        System.out.println("Dijital kok: " + dijitalKok);

        tarayici.close(); // Kaynaklari serbest birak
    }
}

/**
 * In number theory, the aliquot sum s(n) of a positive integer n is the sum of
 * all proper divisors of n, that is, all divisors of n other than n itself. For
 * example, the proper divisors of 15 (that is, the positive divisors of 15 that
 * are not equal to 15) are 1, 3 and 5, so the aliquot sum of 15 is 9 i.e. (1 +
 * 3 + 5). Wikipedia: https://en.wikipedia.org/wiki/Aliquot_sum
 */
public final class AliquotSum {
    private AliquotSum() {
    }

    /**
     * Finds the aliquot sum of an integer number.
     *
     * @param number a positive integer
     * @return aliquot sum of given {@code number}
     */
    public static int getAliquotValue(int number) {
        var sumWrapper = new Object() { int value = 0; };

        IntStream.iterate(1, i -> ++i).limit(number / 2).filter(i -> number % i == 0).forEach(i -> sumWrapper.value += i);

        return sumWrapper.value;
    }

    /**
     * Function to calculate the aliquot sum of an integer number
     *
     * @param n a positive integer
     * @return aliquot sum of given {@code number}
     */
    public static int getAliquotSum(int n) {
        if (n <= 0) {
            return -1;
        }
        int sum = 1;
        double root = Math.sqrt(n);
        /*
         * We can get the factors after the root by dividing number by its factors
         * before the root.
         * Ex- Factors of 100 are 1, 2, 4, 5, 10, 20, 25, 50 and 100.
         * Root of 100 is 10. So factors before 10 are 1, 2, 4 and 5.
         * Now by dividing 100 by each factor before 10 we get:
         * 100/1 = 100, 100/2 = 50, 100/4 = 25 and 100/5 = 20
         * So we get 100, 50, 25 and 20 which are factors of 100 after 10
         */
        for (int i = 2; i <= root; i++) {
            if (n % i == 0) {
                sum += i + n / i;
            }
        }
        // if n is a perfect square then its root was added twice in above loop, so subtracting root
        // from sum
        if (root == (int) root) {
            sum -= (int) root;
        }
        return sum;
    }
}

package com.ankan.staticExample;

// Example of a regular class (outside class cannot be static)
// Only inner classes can be static

// class Test { 
//     static String sharedName;  // Static variable - shared across ALL instances
//     public Test(String personName) {
//         Test.sharedName = personName;  // PROBLEM: This overwrites for ALL objects
//     }
// }

public class InnerClasses { 
    // Outer classes cannot be declared static in Java
    // Only inner classes (classes defined inside another class) can be static

    // Static Inner Class Example
    // When an inner class is static, it does NOT depend on the instance of the parent class
    // It can be instantiated independently without creating an outer class object first
    static class Person {
        String personName;  // Instance variable - each Person object has its own copy

        // Constructor for the static inner class
        public Person(String name) {
            this.personName = name;  // 'this' refers to the current Person object
        }

        // Method to display person's name
        public void displayName() {
            System.out.println("Person name: " + personName);
        }
    }

    public static void main(String[] args) {
        // Creating independent objects of the static inner class
        // No outer class instance needed because the inner class is static
        Person firstPerson = new Person("Kunal");
        Person secondPerson = new Person("Rahul");

        // Each object has its own independent 'personName' field
        // Unlike the commented example at the top (which used static variable causing overwrite)
        System.out.println("--- Static Inner Class Demonstration ---");
        System.out.println("First person's name: " + firstPerson.personName);   // Output: Kunal
        System.out.println("Second person's name: " + secondPerson.personName); // Output: Rahul

        // Demonstrating that they are independent objects
        System.out.println("\nAre both references pointing to same object? " + (firstPerson == secondPerson));
        System.out.println("First person hashcode: " + firstPerson.hashCode());
        System.out.println("Second person hashcode: " + secondPerson.hashCode());

        /* 
        Important Difference: Static vs Non-Static Inner Classes
        ========================================================

        When the inner class (Test) is NOT static, we need an instance of the enclosing class:

        InnerClasses outerInstance = new InnerClasses();
        InnerClasses.Person personObject = outerInstance.new Person("Kunal");

        Why? Because non-static inner classes have an implicit reference to the outer class instance.

        Static inner classes do NOT have this reference, so they can be created independently.
        */

        // Demonstration of why static variables can cause problems (commented)
        // If we used static String name (like in commented Test class above):
        // Test first = new Test("Kunal");
        // Test second = new Test("Rahul");
        // System.out.println(first.name);  // Would print "Rahul" (overwritten!)
        // System.out.println(second.name); // Would print "Rahul"

        /*
        Key Concepts Explained:
        =======================

        1. Static Inner Classes:
           - Can be instantiated without an outer class instance
           - Cannot access non-static members of the outer class directly
           - Are independent of the outer class instance

        2. Non-Static Inner Classes:
           - Require an instance of the outer class to be created
           - Have access to all members (including non-static) of the outer class
           - Maintain an implicit reference to the outer class instance

        3. Static Variables in Regular Classes:
           - Static variables are SHARED across all instances of a class
           - Modifying a static variable affects ALL objects
           - Belong to the class itself, not to any specific object

        4. Why Outer Classes Cannot Be Static:
           - 'static' at class level only makes sense for inner classes
           - Top-level classes are implicitly at the package level
           - Making a top-level class static would be redundant
        */
    }
}

public class SubClass extends A{
    public SubClass(int numValue, String objectName) {
        super(numValue, objectName);
    }

    public static void main(String[] args) {
        SubClass childObject = new SubClass(45, "SampleName");
        int retrievedValue = childObject.numValue;

        System.out.println(childObject instanceof SubClass);
        System.out.println(childObject instanceof A);
        System.out.println(childObject instanceof Object);
    }
}

package array;

import java.util.Scanner;

public class KartNumarasiDogrulayici {

    // Bir sayinin rakamlarinin toplamini hesaplayan yontem
    // Ornek: 123 -> 1+2+3 = 6
    static int rakamlarToplami(int sayi) {
        int toplam = 0;
        while (sayi > 0) {
            toplam += sayi % 10; // Sayinin son rakamini toplama ekle
            sayi = sayi / 10; // Sayinin son rakamini at
        }
        return toplam;
    }

    // Bir diziyi ekrana yazdiran yardimci yontem (debug icin kullanilir)
    // Ornek: [1, 2, 3, 4] -> Dizi: 1 2 3 4
    static void ekranaYazdir(int[] dizi) {
        System.out.print("Dizi: ");
        for (int i = 0; i < dizi.length; i++) {
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }

    // Kart numarasini tamsayi dizisine donusturur
    // Ornek: "4532" -> [4, 5, 3, 2]
    static int[] tamsayiDizisineCevir(String kartNumarasi) {
        int[] dizi = new int[kartNumarasi.length()];

        for (int i = 0; i < dizi.length; i++) {
            dizi[i] = Integer.parseInt(kartNumarasi.charAt(i) + ""); // Her karakteri sayiya cevir ve diziye ekle
        }

        // Debug icin diziyi yazdiriyoruz
        ekranaYazdir(dizi);
        return dizi;
    }

    // Her ikinci haneyi (sagdan baslamak uzere) ikiyle carpar
    // Luhn algoritmasina gore islem yapar
    static int[] ciftHaneleriIkiyleCarp(int[] dizi) {
        for (int i = dizi.length - 2; i >= 0; i -= 2) { // Sagdan ikinci elemandan baslayarak sola dogru ilerle
            dizi[i] *= 2; // Elemani ikiyle carp
        }

        // Debug icin diziyi yazdiriyoruz
        ekranaYazdir(dizi);
        return dizi;
    }

    // Bir dizinin tum elemanlarinin toplamini hesaplar
    // Ornek: [1, 2, 3] -> 1+2+3 = 6
    static int elemanlarToplami(int[] dizi) {
        int toplam = 0;
        for (int i = 0; i < dizi.length; i++) {
            toplam += dizi[i]; // Her elemani toplama ekle
        }

        System.out.println("Dizi elemanlar toplami: " + toplam);
        return toplam;
    }

    // Kart numarasini dogrulayan yontem
    // Luhn algoritmasina gore kartin gecerli olup olmadigini kontrol eder
    static boolean kartGecerliMi(String kartNumarasi) {
        int[] dizi = tamsayiDizisineCevir(kartNumarasi); // Kart numarasini tamsayi dizisine cevir
        dizi = ciftHaneleriIkiyleCarp(dizi); // Her ikinci haneyi ikiyle carp

        for (int i = 0; i < dizi.length; i++) {
            dizi[i] = rakamlarToplami(dizi[i]); // Elemanlarin rakamlar toplamini hesapla
        }

        int toplam = elemanlarToplami(dizi); // Elemanlarin toplamini hesapla
        return toplam % 10 == 0; // Toplamin 10'a bolumunden kalan 0 ise gecerlidir
    }

    // Test ve kullanici giris islemleri
    // Ornek kart numaralari ile test islemi yapar ve kullanicidan kart numarasi ister
    static void kartDogrulamaTesti() {
        // Ornek kart numaralari
        String[] kartNumaralari = {"4532015112830366", "6011514433546201", "378282246310005", "1234567890123456", "1111222333334444"};

        for (String kart : kartNumaralari) {
            System.out.println(kart + " -> " + (kartGecerliMi(kart) ? "Gecerli" : "Gecersiz"));
            System.out.println();
        }
    }

    // Kullanicidan kart numarasi alir ve dogrulugunu kontrol eder
    static void kullaniciGirisi() {
        // Kullanicidan kart numarasi isteme
        Scanner klavye = new Scanner(System.in);
        System.out.println("\nKart numaranizi giriniz:");
        String kartNumarasi = klavye.next();

        while (!kartNumarasi.matches("\\d{13,19}")) { // Kart numarasinin 13-19 haneli olup olmadigini kontrol et
            System.out.println("Lutfen gecerli bir kart numarasi giriniz (13-19 hane):");
            kartNumarasi = klavye.next();
        }
        klavye.close();

        // Kartin dogrulugunu kontrol etme
        if (kartGecerliMi(kartNumarasi)) {
            System.out.println("Kart numarasi dogru.");
        } else {
            System.out.println("Kart numarasi yanlis.");
        }
    }

    public static void main(String[] args) {
        kartDogrulamaTesti(); // Ornek kart numaralarini test et
        kullaniciGirisi(); // Kullanicidan kart numarasi al ve dogrulugunu kontrol et
    }
}

package com.thealgorithms.graph;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * This class provides solutions to the Traveling Salesman Problem (TSP) using both brute-force and dynamic programming approaches.
 * For more information, see <a href="https://en.wikipedia.org/wiki/Travelling_salesman_problem">Wikipedia</a>.
 * @author  <a href="https://github.com/DenizAltunkapan">Deniz Altunkapan</a>
 */

public final class TravelingSalesman {

    // Private constructor to prevent instantiation
    private TravelingSalesman() {
    }

    /**
     * Solves the Traveling Salesman Problem (TSP) using brute-force approach.
     * This method generates all possible permutations of cities, calculates the total distance for each route, and returns the shortest distance found.
     *
     * @param distanceMatrix A square matrix where element [i][j] represents the distance from city i to city j.
     * @return The shortest possible route distance visiting all cities exactly once and returning to the starting city.
     */
    public static int bruteForce(int[][] distanceMatrix) {
        if (distanceMatrix.length <= 1) {
            return 0;
        }

        List<Integer> cities = new ArrayList<>();
        for (int i = 1; i < distanceMatrix.length; i++) {
            cities.add(i);
        }

        List<List<Integer>> permutations = generatePermutations(cities);
        int minDistance = Integer.MAX_VALUE;

        for (List<Integer> permutation : permutations) {
            List<Integer> route = new ArrayList<>();
            route.add(0);
            route.addAll(permutation);
            int currentDistance = calculateDistance(distanceMatrix, route);
            if (currentDistance < minDistance) {
                minDistance = currentDistance;
            }
        }

        return minDistance;
    }

    /**
     * Computes the total distance of a given route.
     *
     * @param distanceMatrix A square matrix where element [i][j] represents the
     *                       distance from city i to city j.
     * @param route          A list representing the order in which the cities are visited.
     * @return The total distance of the route, or Integer.MAX_VALUE if the route is invalid.
     */
    public static int calculateDistance(int[][] distanceMatrix, List<Integer> route) {
        int distance = 0;
        for (int i = 0; i < route.size() - 1; i++) {
            int d = distanceMatrix[route.get(i)][route.get(i + 1)];
            if (d == Integer.MAX_VALUE) {
                return Integer.MAX_VALUE;
            }
            distance += d;
        }
        int returnDist = distanceMatrix[route.get(route.size() - 1)][route.get(0)];
        return (returnDist == Integer.MAX_VALUE) ? Integer.MAX_VALUE : distance + returnDist;
    }

    /**
     * Generates all permutations of a given list of cities.
     *
     * @param cities A list of cities to permute.
     * @return A list of all possible permutations.
     */
    private static List<List<Integer>> generatePermutations(List<Integer> cities) {
        List<List<Integer>> permutations = new ArrayList<>();
        permute(cities, 0, permutations);
        return permutations;
    }

    /**
     * Recursively generates permutations using backtracking.
     *
     * @param arr     The list of cities.
     * @param k       The current index in the permutation process.
     * @param output  The list to store generated permutations.
     */
    private static void permute(List<Integer> arr, int k, List<List<Integer>> output) {
        if (k == arr.size()) {
            output.add(new ArrayList<>(arr));
            return;
        }
        for (int i = k; i < arr.size(); i++) {
            Collections.swap(arr, i, k);
            permute(arr, k + 1, output);
            Collections.swap(arr, i, k);
        }
    }

    /**
     * Solves the Traveling Salesman Problem (TSP) using dynamic programming with the Held-Karp algorithm.
     *
     * @param distanceMatrix A square matrix where element [i][j] represents the distance from city i to city j.
     * @return The shortest possible route distance visiting all cities exactly once and returning to the starting city.
     * @throws IllegalArgumentException if the input matrix is not square.
     */
    public static int dynamicProgramming(int[][] distanceMatrix) {
        if (distanceMatrix.length == 0) {
            return 0;
        }
        int n = distanceMatrix.length;

        for (int[] row : distanceMatrix) {
            if (row.length != n) {
                throw new IllegalArgumentException("Matrix must be square");
            }
        }

        int[][] dp = new int[n][1 << n];
        for (int[] row : dp) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        dp[0][1] = 0;

        for (int mask = 1; mask < (1 << n); mask++) {
            for (int u = 0; u < n; u++) {
                if ((mask & (1 << u)) == 0 || dp[u][mask] == Integer.MAX_VALUE) {
                    continue;
                }
                for (int v = 0; v < n; v++) {
                    if ((mask & (1 << v)) != 0 || distanceMatrix[u][v] == Integer.MAX_VALUE) {
                        continue;
                    }
                    int newMask = mask | (1 << v);
                    dp[v][newMask] = Math.min(dp[v][newMask], dp[u][mask] + distanceMatrix[u][v]);
                }
            }
        }

        int minDistance = Integer.MAX_VALUE;
        int fullMask = (1 << n) - 1;
        for (int i = 1; i < n; i++) {
            if (dp[i][fullMask] != Integer.MAX_VALUE && distanceMatrix[i][0] != Integer.MAX_VALUE) {
                minDistance = Math.min(minDistance, dp[i][fullMask] + distanceMatrix[i][0]);
            }
        }

        return minDistance == Integer.MAX_VALUE ? 0 : minDistance;
    }
}

