// Hayvan sinifi
package inheritance;

public class Hayvan {

	private String isim;  // Hayvanin ismi
	private int yas;      // Hayvanin yasi
	private double saglik;  // Hayvanin saglik durumu

	// Hayvan sinifi kurucusu (constructor)
	public Hayvan(String isim, int yas) {
		this.isim = isim;
		this.yas = yas;
		this.saglik = 100.0; // Varsayilan saglik degeri 100
	}

	// Hayvanin ismini almak icin getter metodu
	public String getIsim() {
		return isim;
	}

	// Hayvanin yasini almak icin getter metodu
	public int getYas() {
		return yas;
	}

	// Hayvanin sagligini almak icin getter metodu
	public double getSaglik() {
		return saglik;
	}

	// Hayvani konusturma metodu
	public void konus() {
		System.out.println("Bu hayvan konusur.");
	}

	// Hayvani yemek yedirme metodu
	public void yemekYe(double miktar) {
		if (miktar > 0) {
			saglik += miktar;  // Saglik miktar kadar artar
			System.out.println(isim + " yemek yedi. Saglik: " + saglik);
		} else {
			System.out.println("Gecersiz miktar.");
		}
	}

	// Hayvani uyutma metodu
	public void uyu() {
		saglik += 5;  // Uyuma saglik uzerine artirma
		System.out.println(isim + " uyudu. Saglik: " + saglik);
	}

	// Hayvanin yasini gosterme
	public void yasHesapla() {
		System.out.println(isim + " " + yas + " yasinda.");
	}

	// ToString metodu - Hayvanin ozelliklerini string olarak dondurur
	@Override
	public String toString() {
		return "Hayvan Ismi: " + isim + ", Yas: " + yas + ", Saglik Durumu: " + saglik;
	}
}

package string; 
import java.util.Scanner;

public class PalindromKontrol {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        // Kullanicidan bir kelime veya cumle girmesini iste
        System.out.print("Bir kelime veya cumle girin: ");
        String metin = scanner.nextLine();

        scanner.close(); // Scanner'i kapat

        // Metni temizleme: Harf olmayan karakterleri kaldir ve kucuk harfe donustur
        metin = metin.replaceAll("[^a-zA-Z]", "").toLowerCase();

        // Metni ters cevirme islemini bir dongu ile yap
        String tersMetin = "";
        for (int i = metin.length() - 1; i >= 0; i--) {
            tersMetin += metin.charAt(i); // Metindeki karakterleri sondan basa dogru ekle
        }

        // Palindrom kontrolu
        if (metin.equals(tersMetin)) {
            // Eger metin ile tersMetin ayniysa palindromdur
            System.out.println("Girdi bir palindromdur.");
        } else {
            // Eger metin ile tersMetin farkliysa palindrom degildir
            System.out.println("Girdi bir palindrom degildir.");
        }
    }
}

package com.thealgorithms.conversions;

import java.util.HashMap;
import java.util.Map;

/**
 * Converts text to Morse code and vice-versa.
 * Text to Morse code: Each letter is separated by a space and each word is separated by a pipe (|).
 * Example: "HELLO WORLD" -> ".... . .-.. .-.. --- | .-- --- .-. .-.. -.."
 *
 * Morse code to text: Each letter is separated by a space and each word is separated by a pipe (|).
 * Example: ".... . .-.. .-.. --- | .-- --- .-. .-.. -.." -> "HELLO WORLD"
 *
 * Applications: Used in radio communications and algorithmic challenges.
 *
 * @author Hardvan
 */
public final class MorseCodeConverter {
private MorseCodeConverter() {
}

private static final Map<Character, String> ENCODE_MAP = new HashMap<>();
private static final Map<String, Character> DECODE_MAP = new HashMap<>();

static {
ENCODE_MAP.put('A', ".-");
ENCODE_MAP.put('B', "-...");
ENCODE_MAP.put('C', "-.-.");
ENCODE_MAP.put('D', "-..");
ENCODE_MAP.put('E', ".");
ENCODE_MAP.put('F', "..-.");
ENCODE_MAP.put('G', "--.");
ENCODE_MAP.put('H', "....");
ENCODE_MAP.put('I', "..");
ENCODE_MAP.put('J', ".---");
ENCODE_MAP.put('K', "-.-");
ENCODE_MAP.put('L', ".-..");
ENCODE_MAP.put('M', "--");
ENCODE_MAP.put('N', "-.");
ENCODE_MAP.put('O', "---");
ENCODE_MAP.put('P', ".--.");
ENCODE_MAP.put('Q', "--.-");
ENCODE_MAP.put('R', ".-.");
ENCODE_MAP.put('S', "...");
ENCODE_MAP.put('T', "-");
ENCODE_MAP.put('U', "..-");
ENCODE_MAP.put('V', "...-");
ENCODE_MAP.put('W', ".--");
ENCODE_MAP.put('X', "-..-");
ENCODE_MAP.put('Y', "-.--");
ENCODE_MAP.put('Z', "--..");
ENCODE_MAP.forEach((keySymbol, codeValue) -> DECODE_MAP.put(codeValue, keySymbol));
}

/**
 * Converts text to Morse code.
 * Each letter is separated by a space and each word is separated by a pipe (|).
 *
 * @param sourceText The text to convert to Morse code.
 * @return The Morse code representation of the text.
 */
public static String textToMorse(String sourceText) {
StringBuilder encodedResult = new StringBuilder();
String[] wordSegments = sourceText.toUpperCase().split(" ");
for (int segmentPos = 0; segmentPos < wordSegments.length; segmentPos++) {
for (char currentChar : wordSegments[segmentPos].toCharArray()) {
encodedResult.append(ENCODE_MAP.getOrDefault(currentChar, "")).append(" ");
}
if (segmentPos < wordSegments.length - 1) {
encodedResult.append("| ");
}
}
return encodedResult.toString().trim();
}

/**
 * Converts Morse code to text.
 * Each letter is separated by a space and each word is separated by a pipe (|).
 *
 * @param encodedData The Morse code to convert to text.
 * @return The text representation of the Morse code.
 */
public static String morseToText(String encodedData) {
StringBuilder decodedResult = new StringBuilder();
String[] wordCodes = encodedData.split(" \\| ");
for (int wordPos = 0; wordPos < wordCodes.length; wordPos++) {
for (String symbolCode : wordCodes[wordPos].split(" ")) {
decodedResult.append(DECODE_MAP.getOrDefault(symbolCode, '?'));
}
if (wordPos < wordCodes.length - 1) {
decodedResult.append(" ");
}
}
return decodedResult.toString();
}
}

/**
 * 2D Segment Tree (Tree of Trees) implementation.
 * This data structure supports point updates and submatrix sum queries
 * in a 2D grid. It achieves this by nesting 1D Segment Trees within a 1D Segment Tree.
 *
 * Time Complexity:
 * - Build/Initialization: O(N * M)
 * - Point Update: O(log N * log M)
 * - Submatrix Query: O(log N * log M)
 *
 * @see <a href="https://cp-algorithms.com/data_structures/segment_tree.html#2d-segment-tree">2D Segment Tree</a>
 */
public class SegmentTree2D {

    /**
     * Represents a 1D Segment Tree.
     * This is equivalent to your 'Sagara' struct. It manages the columns (X-axis).
     */
    public static class SegmentTree1D {
        private int n;
        private final int[] tree;

        /**
         * Initializes the 1D Segment Tree with the nearest power of 2.
         *
         * @param size The expected number of elements (columns).
         */
        public SegmentTree1D(int size) {
            n = 1;
            while (n < size) {
                n *= 2;
            }
            tree = new int[n * 2];
        }

        /**
         * Recursively updates a point in the 1D tree.
         */
        private void update(int index, int val, int node, int lx, int rx) {
            if (rx - lx == 1) {
                tree[node] = val;
                return;
            }

            int mid = lx + (rx - lx) / 2;
            int leftChild = node * 2 + 1;
            int rightChild = node * 2 + 2;

            if (index < mid) {
                update(index, val, leftChild, lx, mid);
            } else {
                update(index, val, rightChild, mid, rx);
            }

            tree[node] = tree[leftChild] + tree[rightChild];
        }

        /**
         * Public wrapper to update a specific index.
         *
         * @param index The column index to update.
         * @param val   The new value.
         */
        public void update(int index, int val) {
            update(index, val, 0, 0, n);
        }

        /**
         * Retrieves the exact value at a specific leaf node.
         *
         * @param index The column index.
         * @return The value at the given index.
         */
        public int get(int index) {
            return query(index, index + 1, 0, 0, n);
        }

        /**
         * Recursively queries the sum in a 1D range.
         */
        private int query(int l, int r, int node, int lx, int rx) {
            if (lx >= r || rx <= l) {
                return 0; // Out of bounds
            }
            if (lx >= l && rx <= r) {
                return tree[node]; // Fully inside
            }

            int mid = lx + (rx - lx) / 2;
            int leftSum = query(l, r, node * 2 + 1, lx, mid);
            int rightSum = query(l, r, node * 2 + 2, mid, rx);

            return leftSum + rightSum;
        }

        /**
         * Public wrapper to query the sum in the range [l, r).
         *
         * @param l Left boundary (inclusive).
         * @param r Right boundary (exclusive).
         * @return The sum of the range.
         */
        public int query(int l, int r) {
            return query(l, r, 0, 0, n);
        }
    }

    // --- Start of 2D Segment Tree (equivalent to 'Sagara2D') ---

    private int n;
    private final SegmentTree1D[] tree;

    /**
     * Initializes the 2D Segment Tree.
     *
     * @param rows The number of rows in the matrix.
     * @param cols The number of columns in the matrix.
     */
    public SegmentTree2D(int rows, int cols) {
        n = 1;
        while (n < rows) {
            n *= 2;
        }
        tree = new SegmentTree1D[n * 2];
        for (int i = 0; i < n * 2; i++) {
            // Every node in the outer tree is a full 1D tree!
            tree[i] = new SegmentTree1D(cols);
        }
    }

    /**
     * Recursively updates a point in the 2D grid.
     */
    private void update(int row, int col, int val, int node, int lx, int rx) {
        if (rx - lx == 1) {
            tree[node].update(col, val);
            return;
        }

        int mid = lx + (rx - lx) / 2;
        int leftChild = node * 2 + 1;
        int rightChild = node * 2 + 2;

        if (row < mid) {
            update(row, col, val, leftChild, lx, mid);
        } else {
            update(row, col, val, rightChild, mid, rx);
        }

        // The value of the current node's column is the sum of its children's column values
        int leftVal = tree[leftChild].get(col);
        int rightVal = tree[rightChild].get(col);
        tree[node].update(col, leftVal + rightVal);
    }

    /**
     * Public wrapper to update a specific point (row, col).
     *
     * @param row The row index.
     * @param col The column index.
     * @param val The new value.
     */
    public void update(int row, int col, int val) {
        update(row, col, val, 0, 0, n);
    }

    /**
     * Recursively queries the sum in a submatrix.
     */
    private int query(int top, int bottom, int left, int right, int node, int lx, int rx) {
        if (lx >= bottom || rx <= top) {
            return 0; // Out of bounds
        }
        if (lx >= top && rx <= bottom) {
            // Fully inside the row range, so delegate the column query to the 1D tree
            return tree[node].query(left, right);
        }

        int mid = lx + (rx - lx) / 2;
        int leftSum = query(top, bottom, left, right, node * 2 + 1, lx, mid);
        int rightSum = query(top, bottom, left, right, node * 2 + 2, mid, rx);

        return leftSum + rightSum;
    }

    /**
     * Public wrapper to query the sum of a submatrix.
     * Note: boundaries are [top, bottom) and [left, right).
     *
     * @param top    Top row index (inclusive).
     * @param bottom Bottom row index (exclusive).
     * @param left   Left column index (inclusive).
     * @param right  Right column index (exclusive).
     * @return The sum of the submatrix.
     */
    public int query(int top, int bottom, int left, int right) {
        return query(top, bottom, left, right, 0, 0, n);
    }
}

public class HizliSiralama {

    public static void sirala(int[] dizi, int sol, int sag) {

        // Pivot degeri ve indeksini belirle
        int pivotIndeks = sol + (sag - sol) / 2;
        int pivotDegeri = dizi[pivotIndeks];
        int i = sol;
        int j = sag;

        while (i <= j) {
            // Pivot degerinden kucuk elemanlar bulunur
            while (dizi[i] < pivotDegeri) {
                i++;
            }
            // Pivot degerinden buyuk elemanlar bulunur
            while (dizi[j] > pivotDegeri) {
                j--;
            }
            // Elemanlar yer degistirilir
            if (i <= j) {
                int gecici = dizi[i];
                dizi[i] = dizi[j];
                dizi[j] = gecici;
                i++;
                j--;
            }
            // Sol alt diziyi sirala
            if (sol < i) {
                sirala(dizi, sol, j);
            }
            // Sag alt diziyi sirala
            if (sag > i) {
                sirala(dizi, i, sag);
            }
        }
    }

    public static void main(String[] args) {
        // Ornek bir dizi olustur
        int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        // Dizi hizli siralama ile siralanir
        HizliSiralama.sirala(dizi, 0, dizi.length - 1);

        // Siralanmis dizi ekrana yazdirilir
        for (int i = 0; i < dizi.length; i++) {
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }
}

