public class MyDate {

    private int year;
    private int month;
    private int day;

    public MyDate(int year, int month, int day) {
        this.year = year;
        this.month = month;
        this.day = day;
    }

    public int getYear() {
        return year;
    }

    public void setYear(int year) {
        this.year = year;
    }

    public int getMonth() {
        return month;
    }

    public void setMonth(int month) {
        this.month = month;
    }

    public int getDay() {
        return day;
    }

    public void setDay(int day) {
        this.day = day;
    }

    @Override
    public String toString() {
        String dateString = String.format("%d-%d-%d", year, month, day);
        Date date = null;
        try {
            date = new SimpleDateFormat("yyyy-MM-dd").parse(dateString);
        } catch (ParseException ex) {
            Logger.getLogger(MyDate.class.getName()).log(Level.SEVERE, null, ex);
        }
        dateString = new SimpleDateFormat("EEEE d MMM yyyy").format(date);
        return dateString;
    }

    public MyDate nextYear() {
        this.year++;
        return this;
    }

    public MyDate nextMonth() {
        this.month++;
        return this;
    }

    public MyDate nextDay() {
        this.day++;
        return this;
    }

    public MyDate previousYear() {
        this.year--;
        return this;
    }

    public MyDate previousMonth() {
        this.month--;
        return this;
    }

    public MyDate previousDay() {
        this.day--;
        return this;
    }
}

class TestMyDate {

    public static boolean isLeapYear(int year) {
        if(year % 400 == 0){
            return true; 
        }
        if (year % 4 == 0 && year % 100 != 0){
             return true;
        }
        return false;
    }

    public static boolean isValidDate(int year, int month, int day) {
        String dateString = String.format("%d-%d-%d", year, month, day);
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");
        dateFormat.setLenient(false);
        try {
            dateFormat.parse(dateString);
        } catch (ParseException pe) {
            return false;
        }
        return true;
    }

    public static int getDayOfWeek(int year, int month, int day) {
        String[] weeks = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

        String dateString = String.format("%d-%d-%d", year, month, day);
        Date date = null;
        try {
            date = new SimpleDateFormat("yyyy-MM-dd").parse(dateString);

        } catch (ParseException ex) {
            Logger.getLogger(MyDate.class
                    .getName()).log(Level.SEVERE, null, ex);
        }
        dateString = new SimpleDateFormat("EEEE").format(date);
        int d=0;
        for(String week: weeks){
            if(week.equals(dateString)) break;
            d++;
        }
        return d;
    }

    public static void main(String[] args) {
        MyDate d1 = new MyDate(2012, 2, 28);
        System.out.println(d1);             // Tuesday 28 Feb 2012
        System.out.println(d1.nextDay());   // Wednesday 29 Feb 2012
        System.out.println(d1.nextDay());   // Thursday 1 Mar 2012
        System.out.println(d1.nextMonth()); // Sunday 1 Apr 2012
        System.out.println(d1.nextYear());  // Monday 1 Apr 2013

        MyDate d2 = new MyDate(2012, 1, 2);
        System.out.println(d2);                 // Monday 2 Jan 2012
        System.out.println(d2.previousDay());   // Sunday 1 Jan 2012
        System.out.println(d2.previousDay());   // Saturday 31 Dec 2011
        System.out.println(d2.previousMonth()); // Wednesday 30 Nov 2011
        System.out.println(d2.previousYear());  // Tuesday 30 Nov 2010

        MyDate d3 = new MyDate(2012, 2, 29);
        System.out.println(d3.previousYear());  // Monday 28 Feb 2011  
        MyDate d4 = new MyDate(2099, 11, 31); // Invalid year, month, or day!
        MyDate d5 = new MyDate(2011, 2, 29);  // Invalid year, month, or day!
        System.out.println(d4);
        System.out.println(d5);
        System.out.println(getDayOfWeek(2099, 10, 31));
        System.out.println(isValidDate(2099, 10, 32));
    }
}

/**
 *
 *
 * <h1>Binary Search Tree (Iterative)</h1>
 *
 * <p>
 * An implementation of BST iteratively. Binary Search Tree is a binary tree
 * which satisfies three properties: left child is less than root node, right
 * child is grater than root node, both left and right child must themselves be
 * a BST.
 *
 * @author [Lakhan Nad](<a href="https://github.com/Lakhan-Nad">git-Lakhan Nad</a>)
 */

public class BSTIterative {

    /**
     * Reference for the node of BST.
     */
    private Node root;

    /**
     * Default Constructor Initializes the root of BST with null.
     */
    BSTIterative() {
        root = null;
    }

    public Node getRoot() {
        return root;
    }

    /**
     * A method to insert a new value in BST. If the given value is already
     * present in BST the insertion is ignored.
     *
     * @param data the value to be inserted
     */
    public void add(int data) {
        Node parent = null;
        Node temp = this.root;
        int rightOrLeft = -1;
        /* Finds the proper place this node can
         * be placed in according to rules of BST.
         */
        while (temp != null) {
            if (temp.data > data) {
                parent = temp;
                temp = parent.left;
                rightOrLeft = 0;
            } else if (temp.data < data) {
                parent = temp;
                temp = parent.right;
                rightOrLeft = 1;
            } else {
                System.out.println(data + " is already present in BST.");
                return; // if data already present we ignore insertion
            }
        }
        /* Creates a newNode with the value passed
         * Since this data doesn't already exists
         */
        Node newNode = new Node(data);
        /* If the parent node is null
         * then the insertion is to be done in
         * root itself.
         */
        if (parent == null) {
            this.root = newNode;
        } else {
            /* Check if insertion is to be made in
             * left or right subtree.
             */
            if (rightOrLeft == 0) {
                parent.left = newNode;
            } else {
                parent.right = newNode;
            }
        }
    }

    /**
     * A method to delete the node in BST. If node is present it will be deleted
     *
     * @param data the value that needs to be deleted
     */
    public void remove(int data) {
        Node parent = null;
        Node temp = this.root;
        int rightOrLeft = -1;
        /* Find the parent of the node and node itself
         * That is to be deleted.
         * parent variable store parent
         * temp stores node itself.
         * rightOrLeft use to keep track weather child
         * is left or right subtree
         */
        while (temp != null) {
            if (temp.data == data) {
                break;
            } else if (temp.data > data) {
                parent = temp;
                temp = parent.left;
                rightOrLeft = 0;
            } else {
                parent = temp;
                temp = parent.right;
                rightOrLeft = 1;
            }
        }
        /* If temp is null than node with given value is not
         * present in our tree.
         */
        if (temp != null) {
            Node replacement; // used to store the new values for replacing nodes
            if (temp.right == null && temp.left == null) { // Leaf node Case
                replacement = null;
            } else if (temp.right == null) { // Node with only right child
                replacement = temp.left;
                temp.left = null;
            } else if (temp.left == null) { // Node with only left child
                replacement = temp.right;
                temp.right = null;
            } else {
                /* If both left and right child are present
                 * we replace this nodes data with
                 * leftmost node's data in its right subtree
                 * to maintain the balance of BST.
                 * And then delete that node
                 */
                if (temp.right.left == null) {
                    temp.data = temp.right.data;
                    replacement = temp;
                    temp.right = temp.right.right;
                } else {
                    Node parent2 = temp.right;
                    Node child = temp.right.left;
                    while (child.left != null) {
                        parent2 = child;
                        child = parent2.left;
                    }
                    temp.data = child.data;
                    parent2.left = child.right;
                    replacement = temp;
                }
            }
            /* Change references of parent after
             * deleting the child.
             */
            if (parent == null) {
                this.root = replacement;
            } else {
                if (rightOrLeft == 0) {
                    parent.left = replacement;
                } else {
                    parent.right = replacement;
                }
            }
        }
    }

    /**
     * A method to check if given data exists in out Binary Search Tree.
     *
     * @param data the value that needs to be searched for
     * @return boolean representing if the value was find
     */
    public boolean find(int data) {
        Node temp = this.root;
        /* Check if node exists
         */
        while (temp != null) {
            if (temp.data > data) {
                temp = temp.left;
            } else if (temp.data < data) {
                temp = temp.right;
            } else {
                /* If found return true
                 */
                System.out.println(data + " is present in the BST.");
                return true;
            }
        }
        System.out.println(data + " not found.");
        return false;
    }
}

package com.ankan.introduction;

public class WrapperClass {
    public static void main(String[] args) {
        // Primitive variables demonstration (commented)
        // int firstValue = 10;
        // int secondValue = 30;

        // Wrapper class demonstration
        // Integer numberWrapper = 45;  // Autoboxing: int → Integer

        // Creating a Pair object to demonstrate swap functionality
        Pair numberPair = new Pair(10, 30);
        swapValues(numberPair);  // Pass by reference (object reference is passed)

        // Swap actually works because we're modifying object fields, not primitive variables
        System.out.println("After swap - first value: " + numberPair.firstValue + 
                           ", second value: " + numberPair.secondValue);

        // 'final' keyword demonstration with primitive type
        final int FIXED_BONUS_AMOUNT = 2;  // Using final makes the variable constant
        // BONUS_AMOUNT = 3;  // Compilation error: cannot reassign a final variable

        // 'final' with non-primitive objects demonstration (commented)
        // final Student kunalStudent = new Student("Kunal Kushwaha");
        // kunalStudent.studentName = "Ankan Chatterjee";  // Valid: Can modify object's internal state
        // kunalStudent = new Student("New Student");      // Compilation error: Cannot reassign final reference

        // Explanation:
        // For non-primitive types, 'final' prevents reassigning the reference variable
        // BUT the object's internal fields CAN still be modified
    }

    // Swap method that modifies the Pair object's fields
    // This works because objects are passed by reference (the reference is passed by value)
    static void swapValues(Pair numberPairs) {
        int temporaryStorage = numberPairs.firstValue;
        numberPairs.firstValue = numberPairs.secondValue;
        numberPairs.secondValue = temporaryStorage;
    }
}

// Wrapper class that holds two integer values
class Pair {
    // Instance variables (wrapped in a container object)
    Integer firstValue;   // Wrapper class for int (can be null)
    Integer secondValue;  // Wrapper class for int (can be null)

    // Constructor to initialize the Pair object
    public Pair(Integer firstNumber, Integer secondNumber) {
        this.firstValue = firstNumber;
        this.secondValue = secondNumber;
    }

    // Final variable demonstration (commented)
    // final int CONSTANT_VALUE = 10;  // Must be initialized when declared
    // For primitives: 'final' prevents value modification
    // For non-primitives: 'final' prevents reference reassignment (but object state can change)

    // Garbage collection demonstration method
    @Override
    protected void finalize() throws Throwable {
        System.out.println("Pair object has been destroyed by garbage collector");
        super.finalize();
    }
}

// Additional educational notes:
// 
// 1. Wrapper Classes (Integer, Double, Boolean, etc.):
//    - Convert primitives to objects
//    - Provide utility methods (parsing, conversion, etc.)
//    - Enable use of primitives in Collections (ArrayList<Integer>, etc.)
//
// 2. Autoboxing: Automatic conversion primitive → wrapper (int → Integer)
// 3. Unboxing: Automatic conversion wrapper → primitive (Integer → int)
//
// 4. 'final' keyword behavior:
//    - Primitive: Value cannot be changed
//    - Object reference: Reference cannot point to new object, but object's fields can be modified
//    - Method: Cannot be overridden by subclasses
//    - Class: Cannot be extended
//
// 5. Pass by Value vs Reference in Java:
//    - Primitives passed by value (copy) - original unchanged
//    - Objects passed by reference value - object contents can be modified

