public class RastgeleSayiTahmin { // Ana sinif

    public static void main(String[] args) { // Programin calismaya basladigi ana fonksiyon

        // Random sinifindan bir nesne olusturur, bu nesne ile rastgele sayilar uretilir.
        Random rastgele = new Random();

        // 1 ile 100 arasinda rastgele bir sayi uretir. 'nextInt(100)' ifadesi 0-99 arasinda bir sayi uretir,
        // bu yuzden sonuca 1 eklenir ve 1-100 araliginda bir sayi elde edilir.
        int sayi = rastgele.nextInt(100) + 1; 

        // Kullanicidan giris almak icin Scanner nesnesi olusturur.
        Scanner scanner = new Scanner(System.in);

        // Kullanicinin dogru tahmini yapana kadar donecek sonsuz bir dongu baslatilir.
        while(true) {

            // Kullanicinin girdigi sayiyi okur ve 'girilen' degiskenine atar.
            int girilen = scanner.nextInt();

            // Rastgele uretilen sayi ve kullanicinin girdigi sayiyi ekrana yazdirir.
            System.out.println("Rastgele = " + sayi + " Girilen = " + girilen);

            // Eger kullanicinin girdigi sayi, rastgele uretilen sayiya esitse, donguden cikilir.
            if(sayi == girilen) {
                // Tahmin dogru, dongu sonlanir.
                break;
            } 
            // Eger girilen sayi, rastgele sayidan kucukse, kullaniciya daha buyuk bir sayi girmesi gerektigini soyler.
            else if(girilen < sayi) {
                System.out.println("Daha buyuk bir sayi giriniz (yukari).");
            } 
            // Eger girilen sayi, rastgele sayidan buyukse, kullaniciya daha kucuk bir sayi girmesi gerektigini soyler.
            else {
                System.out.println("Daha kucuk bir sayi giriniz (asagi).");
            }
        }
        // Program burada sonlanir, scanner nesnesini kapatmayi unutmamak gerekir.
        scanner.close(); 
    }
}

/**
 * Author: Siddhant Swarup Mallick
 * Github: https://github.com/siddhant2002
 * <p>
 * Problem Description:
 * A robot is located at the top-left corner of a m x n grid (marked 'Start' in the diagram below).
 * The robot can only move either down or right at any point in time.
 * The robot is trying to reach the bottom-right corner of the grid (marked 'Finish' in the diagram below).
 * How many possible unique paths are there?
 * <p>
 * Program Description:
 * This program calculates the number of unique paths possible for a robot to reach the bottom-right corner
 * of an m x n grid using dynamic programming.
 */
public final class UniquePaths {

    private UniquePaths() {
    }

    /**
     * Calculates the number of unique paths using a 1D dynamic programming array.
     * Time complexity O(n*m)
     * Space complexity O(min(n,m))
     *
     * @param m The number of rows in the grid.
     * @param n The number of columns in the grid.
     * @return The number of unique paths.
     */
    public static int uniquePaths(final int m, final int n) {
        if (m > n) {
            return uniquePaths(n, m); // Recursive call to handle n > m cases
        }
        int[] dp = new int[n]; // Create a 1D array to store unique paths for each column
        Arrays.fill(dp, 1); // Initialize all values to 1 (one way to reach each cell)
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[j] = Math.addExact(dp[j], dp[j - 1]); // Update the number of unique paths for each cell
            }
        }
        return dp[n - 1]; // The result is stored in the last column of the array
    }

    /**
     * Calculates the number of unique paths using a 2D dynamic programming array.
     * Time complexity O(n*m)
     * Space complexity O(n*m)
     *
     * @param m The number of rows in the grid.
     * @param n The number of columns in the grid.
     * @return The number of unique paths.
     */
    public static int uniquePaths2(final int m, final int n) {
        int[][] dp = new int[m][n]; // Create a 2D array to store unique paths for each cell
        for (int i = 0; i < m; i++) {
            dp[i][0] = 1; // Initialize the first column to 1 (one way to reach each cell)
        }
        for (int j = 0; j < n; j++) {
            dp[0][j] = 1; // Initialize the first row to 1 (one way to reach each cell)
        }
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.addExact(dp[i - 1][j], dp[i][j - 1]); // Update the number of unique paths for each cell
            }
        }
        return dp[m - 1][n - 1]; // The result is stored in the bottom-right cell of the array
    }
}

/**
 * Terminal uzerinde ASCII karakterlerle sekilen, birbirinden bagimsiz
 * hareket eden birden fazla "top" gosteren basit bir animasyon dongusu.
 */
public class KonsoldaTopAnimasyonu {

    private static final int TERMINAL_GENISLIK = 50;
    private static final int TERMINAL_YUKSEKLIK = 20;
    private static final int TOP_ADEDI = 5;
    private static final int KARE_GECIKMESI_MS = 100;

    /** Konumu ve hareket vektoru olan tek bir noktasal cismi temsil eder. */
    private static class HareketliNokta {
        int yatayKonum;
        int dikeyKonum;
        int yatayYon;
        int dikeyYon;

        HareketliNokta(int yatayKonum, int dikeyKonum, int yatayYon, int dikeyYon) {
            this.yatayKonum = yatayKonum;
            this.dikeyKonum = dikeyKonum;
            this.yatayYon = yatayYon;
            this.dikeyYon = dikeyYon;
        }

        void birAdimIlerle() {
            yatayKonum += yatayYon;
            dikeyKonum += dikeyYon;

            if (yatayKonum <= 0 || yatayKonum >= TERMINAL_GENISLIK - 1) {
                yatayYon *= -1;
            }
            if (dikeyKonum <= 0 || dikeyKonum >= TERMINAL_YUKSEKLIK - 1) {
                dikeyYon *= -1;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        List<HareketliNokta> noktalar = rastgeleNoktalarUret();

        while (true) {
            noktalar.forEach(HareketliNokta::birAdimIlerle);
            terminaleCiz(noktalar);
            Thread.sleep(KARE_GECIKMESI_MS);
        }
    }

    private static List<HareketliNokta> rastgeleNoktalarUret() {
        Random rng = new Random();
        List<HareketliNokta> liste = new ArrayList<>();
        for (int i = 0; i < TOP_ADEDI; i++) {
            liste.add(new HareketliNokta(
                    rng.nextInt(TERMINAL_GENISLIK),
                    rng.nextInt(TERMINAL_YUKSEKLIK),
                    rng.nextBoolean() ? 1 : -1,
                    rng.nextBoolean() ? 1 : -1
            ));
        }
        return liste;
    }

    private static void terminaleCiz(List<HareketliNokta> noktalar) {
        System.out.print("\033[H\033[2J");
        StringBuilder kare = new StringBuilder();
        for (int satir = 0; satir < TERMINAL_YUKSEKLIK; satir++) {
            for (int sutun = 0; sutun < TERMINAL_GENISLIK; sutun++) {
                kare.append(hucreSembolu(noktalar, sutun, satir));
            }
            kare.append('\n');
        }
        System.out.print(kare);
    }

    private static char hucreSembolu(List<HareketliNokta> noktalar, int sutun, int satir) {
        for (HareketliNokta n : noktalar) {
            if (n.yatayKonum == sutun && n.dikeyKonum == satir) {
                return 'O';
            }
        }
        return ' ';
    }
}

public class Main {
    public static void main(String[] args) {
        // Creating a standard Box object with custom dimensions
        Box regularBox = new Box(51, 31, 77);
        System.out.println("Regular Box dimensions: " + regularBox.length + " x " + regularBox.width + " x " + regularBox.height);
        // System.out.println(regularBox.boxWeight); // ERROR: Parent class reference cannot access child class fields

        // Creating BoxWeight objects using different constructors
        BoxWeight defaultWeightBox = new BoxWeight();  // Uses default constructor
        BoxWeight fullyParameterizedBox = new BoxWeight(2, 3, 4, 8);  // Sets all dimensions and weight

        System.out.println("BoxWeight object - Weight: " + defaultWeightBox.boxWeight + 
                           ", Dimensions: " + defaultWeightBox.length + " x " + 
                           defaultWeightBox.width + " x " + defaultWeightBox.height);

        // Demonstrating upcasting: Child object referenced by Parent reference variable
        Box upcastedBoxReference = new BoxWeight(2, 3, 4, 8);
        // System.out.println(upcastedBoxReference.boxWeight); // COMPILE ERROR: Parent reference cannot see child fields
        // Explanation: The reference variable type (Box) determines which members are accessible at compile time
        // Even though the actual heap object is BoxWeight, the stack reference upcastedBoxReference is of type Box
        System.out.println("Upcasted Box can only access parent fields: width = " + upcastedBoxReference.width);

        /*
        Important Inheritance Rules:
        =============================
        1. Parent class references CANNOT access child-specific fields/methods
        2. The reference type (not object type) determines compile-time accessibility
        3. Downcasting (Child ref = (Child) parentRef) requires explicit cast and may fail at runtime

        Invalid Example (would cause compilation error):
        BoxWeight invalidDowncast = new Box(2, 3, 4);
        Reason: Cannot assign parent object to child reference without proper casting
        */

        // Creating BoxPrice object (demonstrates multi-level inheritance)
        BoxPrice pricedBox = new BoxPrice(5, 8, 90);

        // Demonstrating static method behavior (cannot be overridden)
        Box staticMethodDemoParent = new BoxWeight();
        staticMethodDemoParent.displayGreeting();  // Calls Box version (reference type determines which static method)

        BoxWeight staticMethodDemoChild = new BoxWeight();
        staticMethodDemoChild.displayGreeting();   // Calls inherited static method from Box (not overridden)

        // Educational Note:
        // Static methods are associated with the CLASS, not with individual objects
        // Therefore, method overriding (which is runtime polymorphism) does NOT apply to static methods
        // Static methods can be inherited from parent classes but cannot be overridden in child classes
        // The method called depends on the reference type, not the actual object type

        System.out.println("\n--- Key Takeaways ---");
        System.out.println("✅ Parent references can point to child objects (Upcasting)");
        System.out.println("❌ Parent references cannot access child-specific fields");
        System.out.println("📌 Reference type determines compile-time member access");
        System.out.println("⚡ Static methods are inherited but NOT overridden");
        System.out.println("🎯 Overloading = compile-time | Overriding = runtime");
    }
}

package com.thealgorithms.graph;

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

/**
 * Implementation of the Edmonds–Karp algorithm for computing the maximum flow of a directed graph.
 * <p>
 * The algorithm runs in O(V * E^2) time and is a specific implementation of the Ford–Fulkerson
 * method where the augmenting paths are found using breadth-first search (BFS) to ensure the
 * shortest augmenting paths (in terms of the number of edges) are used.
 * </p>
 *
 * <p>The graph is represented with a capacity matrix where {@code capacity[u][v]} denotes the
 * capacity of the edge from {@code u} to {@code v}. Negative capacities are not allowed.</p>
 *
 * @author <a href="https://en.wikipedia.org/wiki/Edmonds%E2%80%93Karp_algorithm">Wikipedia: EdmondsKarp algorithm</a>
 */
public final class EdmondsKarp {

    private EdmondsKarp() {
    }

    /**
     * Computes the maximum flow from {@code source} to {@code sink} in the provided capacity matrix.
     *
     * @param capacity the capacity matrix representing the directed graph; must be square and non-null
     * @param source the source vertex index
     * @param sink the sink vertex index
     * @return the value of the maximum flow between {@code source} and {@code sink}
     * @throws IllegalArgumentException if the matrix is {@code null}, not square, contains negative
     *         capacities, or if {@code source} / {@code sink} indices are invalid
     */
    public static int maxFlow(int[][] capacity, int source, int sink) {
        if (capacity == null || capacity.length == 0) {
            throw new IllegalArgumentException("Capacity matrix must not be null or empty");
        }

        final int n = capacity.length;
        for (int row = 0; row < n; row++) {
            if (capacity[row] == null || capacity[row].length != n) {
                throw new IllegalArgumentException("Capacity matrix must be square");
            }
            for (int col = 0; col < n; col++) {
                if (capacity[row][col] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative");
                }
            }
        }

        if (source < 0 || source >= n || sink < 0 || sink >= n) {
            throw new IllegalArgumentException("Source and sink must be valid vertex indices");
        }
        if (source == sink) {
            return 0;
        }

        final int[][] residual = new int[n][n];
        for (int i = 0; i < n; i++) {
            residual[i] = Arrays.copyOf(capacity[i], n);
        }

        final int[] parent = new int[n];
        int maxFlow = 0;

        while (bfs(residual, source, sink, parent)) {
            int pathFlow = Integer.MAX_VALUE;
            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                pathFlow = Math.min(pathFlow, residual[u][v]);
            }

            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                residual[u][v] -= pathFlow;
                residual[v][u] += pathFlow;
            }

            maxFlow += pathFlow;
        }

        return maxFlow;
    }

    private static boolean bfs(int[][] residual, int source, int sink, int[] parent) {
        Arrays.fill(parent, -1);
        parent[source] = source;

        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(source);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v = 0; v < residual.length; v++) {
                if (residual[u][v] > 0 && parent[v] == -1) {
                    parent[v] = u;
                    if (v == sink) {
                        return true;
                    }
                    queue.add(v);
                }
            }
        }
        return false;
    }
}

/**
 * 0-1 BFS for shortest paths on graphs with edges weighted 0 or 1.
 *
 * <p>Time Complexity: O(V + E). Space Complexity: O(V).
 *
 * <p>References:
 * <ul>
 *   <li>https://cp-algorithms.com/graph/01_bfs.html</li>
 * </ul>
 */
public final class ZeroOneBfs {

    private ZeroOneBfs() {
        // Utility class; do not instantiate.
    }

    /**
     * Computes shortest distances from {@code src} in a graph whose edges have weight 0 or 1.
     *
     * @param n the number of vertices, labeled {@code 0..n-1}
     * @param adj adjacency list; for each vertex u, {@code adj.get(u)} is a list of pairs
     *            {@code (v, w)} where {@code v} is a neighbor and {@code w} is 0 or 1
     * @param src the source vertex
     * @return an array of distances; {@code Integer.MAX_VALUE} denotes unreachable
     * @throws IllegalArgumentException if {@code n < 0}, {@code src} is out of range,
     *                                  or any edge has weight other than 0 or 1
     */
    public static int[] shortestPaths(int n, List<List<int[]>> adj, int src) {
        if (n < 0 || src < 0 || src >= n) {
            throw new IllegalArgumentException("Invalid n or src");
        }
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        Deque<Integer> dq = new ArrayDeque<>();

        dist[src] = 0;
        dq.addFirst(src);

        while (!dq.isEmpty()) {
            int u = dq.pollFirst();
            List<int[]> edges = adj.get(u);
            if (edges == null) {
                continue;
            }
            for (int[] e : edges) {
                if (e == null || e.length < 2) {
                    continue;
                }
                int v = e[0];
                int w = e[1];
                if (v < 0 || v >= n) {
                    continue; // ignore bad edges
                }
                if (w != 0 && w != 1) {
                    throw new IllegalArgumentException("Edge weight must be 0 or 1");
                }
                int nd = dist[u] + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    if (w == 0) {
                        dq.addFirst(v);
                    } else {
                        dq.addLast(v);
                    }
                }
            }
        }
        return dist;
    }
}

