/*
 * Prompts the user for a target value and scans a fixed sample
 * array left-to-right looking for a match.
 */
public class DogrusalArama {

    void ara(int[] veri, int hedef) {
        boolean eslesmeVarMi = false;

        for (int idx = 0; idx < veri.length; idx++) {
            if (veri[idx] == hedef) {
                eslesmeVarMi = true;
                System.out.println("Aranan oge bulundu: Indis " + idx);
                break;
            }
        }

        if (!eslesmeVarMi) {
            System.out.println("Aranan oge bulunamadi");
        }
    }

    public static void main(String[] args) {
        Scanner girdi = new Scanner(System.in);

        int[] veri = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        System.out.print("Aranacak degeri girin: ");
        int hedef = girdi.nextInt();

        DogrusalArama araci = new DogrusalArama();
        araci.ara(veri, hedef);

        girdi.close();
    }
}

public class SinifBulunamadiHatasi {

	public static void main(String[] args) {
		try {
			// Belirtilen sinifi yuklemeye calis
			String sinifAdi = "java.util.Scanner"; // Mevcut bir sinif
			Class<?> sinif = Class.forName(sinifAdi); // Sinifi yukle
			System.out.println(sinifAdi + " sinifi basariyla yuklendi.");

			// Belirtilen sinifi yuklemeye calis
			sinifAdi = "checked.DosyaOkumaHatasi"; // Mevcut bir sinif
			sinif = Class.forName(sinifAdi); // Sinifi yukle
			System.out.println(sinifAdi + " sinifi basariyla yuklendi.");

			// Mevcut olmayan bir sinifi yuklemeyi dene
			String olmayanSinifAdi = "com.ornek.Sinif";
			Class<?> olmayanSinif = Class.forName(olmayanSinifAdi); // Hata olusur
			System.out.println(olmayanSinifAdi + " sinifi basariyla yuklendi.");

		} catch (ClassNotFoundException e) {
			// Eger belirtilen sinif bulunamazsa bu blok calisir
