			// Kaynak temizleme veya islemin tamamlandigini bildirmek icin kullanilir
			System.out.println("Islem tamamlandi.");
		}
	}
}

package com.thealgorithms.bitmanipulation;

/**
 * This class provides a method to compute the remainder
 * of a number when divided by a power of two (2^n)
 * without using division or modulo operations.
 *
 * @author Hardvan
 */
public final class ModuloPowerOfTwo {
private ModuloPowerOfTwo() {
}

/**
 * Computes the remainder of a given integer when divided by 2^n.
 *
 * @param inputValue the input number
 * @param exponentValue the exponent (power of two)
 * @return the remainder of inputValue divided by 2^exponentValue
 */
public static int moduloPowerOfTwo(int inputValue, int exponentValue) {
if (exponentValue <= 0) {
throw new IllegalArgumentException("The exponent must be positive");
}
return inputValue & ((1 << exponentValue) - 1);
}
}

public class IntVeriTuruOrnegi {

    public static void main(String[] args) {

        // short ve int turunde birer degisken
        short kucukDeger = 32000;
        int genisDeger = 2147483647;

        System.out.println("Kisa Sayi: " + kucukDeger);
        System.out.println("Tam Sayi: " + genisDeger);

        // short + int islemi otomatik olarak int'e genisler
        int toplamSonuc = kucukDeger + genisDeger;
        System.out.println("Toplam: " + toplamSonuc);

        // iki short'un toplami da int turunde degerlendirilir
        short ikinciKucukDeger = 30000;
        int ikinciToplam = ikinciKucukDeger + ikinciKucukDeger;
        System.out.println("Toplam 2: " + ikinciToplam);

        // int turu uzerinde temel aritmetik islemler
        int farkSonuc = genisDeger - kucukDeger;
        int carpimSonuc = genisDeger * kucukDeger;
        int bolumSonuc = genisDeger / kucukDeger;
        int kalanSonuc = genisDeger % kucukDeger;

        System.out.println("Fark: " + farkSonuc);
        System.out.println("Carpim: " + carpimSonuc);
        System.out.println("Bolum: " + bolumSonuc);
        System.out.println("Kalan: " + kalanSonuc);

        // short ve int turlerinin sinir degerleri
        System.out.println("Short veri turunun maksimum degeri: " + Short.MAX_VALUE);
        System.out.println("Short veri turunun minimum degeri: " + Short.MIN_VALUE);
        System.out.println("Int veri turunun maksimum degeri: " + Integer.MAX_VALUE);
        System.out.println("Int veri turunun minimum degeri: " + Integer.MIN_VALUE);
    }
}

/**
 * Looks up a known "code1;code2;rate" entry and converts an amount.
 */
public class Exchange {

    public static ArrayList<String> listRates = new ArrayList<>();

    public static void createRete() {
        listRates.add("USD;VND;17000");
        listRates.add("EUR;USD;1.2");
        listRates.add("USD;IDN;15789");
        listRates.add("USD;EUR;0.83");
        listRates.add("CAD;IDN;16869");
    }

    public double convert(String code1, String code2, double amount) {
        createRete();
        for (String entry : listRates) {
            StringTokenizer tokenizer = new StringTokenizer(entry, ";");
            String fromCode = tokenizer.nextToken();
            String toCode = tokenizer.nextToken();
            double knownRate = Double.parseDouble(tokenizer.nextToken());
            if (code1.equalsIgnoreCase(fromCode) && code2.equalsIgnoreCase(toCode)) {
                return knownRate * amount;
            }
        }
        System.out.println("Can not found code!!!!");
        return amount;
    }
}

package com.thealgorithms.datastructures.heaps;

import java.util.ArrayList;

/**
 * This class implements a Leftist Heap, which is a type of priority queue
 * that follows similar operations to a binary min-heap but allows for
 * unbalanced structures based on the leftist property.
 *
 * <p>
 * A Leftist Heap maintains the leftist property, which ensures that the
 * left subtree is heavier than the right subtree based on the
 * null-path length (npl) values. This allows for efficient merging
 * of heaps and supports operations like insertion, extraction of
 * the minimum element, and in-order traversal.
 * </p>
 *
 * <p>
 * For more information on Leftist Heaps, visit:
 * <a href="https://iq.opengenus.org/leftist-heap/">OpenGenus</a>
 * </p>
 */
public class LeftistHeap {
    // Node class representing each element in the Leftist Heap
    private static final class Node {
        private final int element;
        private int npl;
        private Node left;
        private Node right;

        // Node constructor that initializes the element and sets child pointers to null
        private Node(int element) {
            this.element = element;
            left = null;
            right = null;
            npl = 0;
        }
    }

    private Node root;

    // Constructor initializing an empty Leftist Heap
    public LeftistHeap() {
        root = null;
    }

    /**
     * Checks if the heap is empty.
     *
     * @return true if the heap is empty; false otherwise
     */
    public boolean isEmpty() {
        return root == null;
    }

    /**
     * Resets the heap to its initial state, effectively clearing all elements.
     */
    public void clear() {
        root = null; // Set root to null to clear the heap
    }

    /**
     * Merges the contents of another Leftist Heap into this one.
     *
     * @param h1 the LeftistHeap to be merged into this heap
     */
    public void merge(LeftistHeap h1) {
        // Merge the current heap with the provided heap and set the provided heap's root to null
        root = merge(root, h1.root);
        h1.root = null;
    }

    /**
     * Merges two nodes, maintaining the leftist property.
     *
     * @param a the first node
     * @param b the second node
     * @return the merged node maintaining the leftist property
     */
    public Node merge(Node a, Node b) {
        if (a == null) {
            return b;
        }

        if (b == null) {
            return a;
        }

        // Ensure that the leftist property is maintained
        if (a.element > b.element) {
            Node temp = a;
            a = b;
            b = temp;
        }

        // Merge the right child of node a with node b
        a.right = merge(a.right, b);

        // If left child is null, make right child the left child
        if (a.left == null) {
            a.left = a.right;
            a.right = null;
        } else {
            if (a.left.npl < a.right.npl) {
                Node temp = a.left;
                a.left = a.right;
                a.right = temp;
            }
            a.npl = a.right.npl + 1;
        }
        return a;
    }

    /**
     * Inserts a new element into the Leftist Heap.
     *
     * @param a the element to be inserted
     */
    public void insert(int a) {
        root = merge(new Node(a), root);
    }

    /**
     * Extracts and removes the minimum element from the heap.
     *
     * @return the minimum element in the heap, or -1 if the heap is empty
     */
    public int extractMin() {
        if (isEmpty()) {
            return -1;
        }

        int min = root.element;
        root = merge(root.left, root.right);
        return min;
    }

    /**
     * Returns a list of the elements in the heap in in-order traversal.
     *
     * @return an ArrayList containing the elements in in-order
     */
    public ArrayList<Integer> inOrder() {
        ArrayList<Integer> lst = new ArrayList<>();
        inOrderAux(root, lst);
        return new ArrayList<>(lst);
    }

    /**
     * Auxiliary function for in-order traversal
     *
     * @param n the current node
     * @param lst the list to store the elements in in-order
     */
    private void inOrderAux(Node n, ArrayList<Integer> lst) {
        if (n == null) {
            return;
        }
        inOrderAux(n.left, lst);
        lst.add(n.element);
        inOrderAux(n.right, lst);
    }
}

public class IsimlendirmeKurallari {

    public static void main(String[] args) {

        // A rundown of legal Java identifiers across the primitive types.
        long phoneNumber;   // valid: simple long variable
        char gender;        // valid: meaningful single-word name
        boolean isMarried;  // valid: meaningful boolean name
        double salaryCalc;  // valid: multi-word, descriptive name
        String fullName;    // valid: identifiers may combine several words
        int age;            // valid: minimal but clear variable name

        // Constants are conventionally written in all caps.
        final double PI_VALUE = 3.14159;

        // Java forbids special characters and whitespace inside identifiers:
        // int 2age;               // invalid: cannot start with a digit
        // String @fullName;       // invalid: cannot start with a special character
        // double salary calc;     // invalid: no spaces allowed
        // boolean is married;     // invalid: no spaces allowed

        // Identifiers should always be descriptive rather than arbitrary.
        String cityName = "Istanbul";
        int studentCount = 100;

        // Identifiers must not start with an uppercase letter by convention:
        // String FullName; // discouraged: should not start with a capital letter

        // camelCase is the standard convention for variable and method names.
        String studentFullName = "Ali Veli";
        double totalSalary = 5000.0;

        // Even so, constant fields are still written in uppercase snake case.
        final int MAX_COUNT = 100;
    }
}

/*
 * Represents a post office with a name and phone number, and
 * demonstrates wiring it together with Kisi and Adres objects.
 */
public class Postane {

	private String kurumAdi;
	private String iletisimNumarasi;

	public Postane(String kurumAdi, String iletisimNumarasi) {
		this.kurumAdi = kurumAdi;
		this.iletisimNumarasi = iletisimNumarasi;
	}

	public String getAd() {
		return kurumAdi;
	}

	public String getTelefonNumarasi() {
		return iletisimNumarasi;
	}

	// Prints the post office's name and contact number.
	public void postaneyiTanit() {
		System.out.println("Postane Adi: " + kurumAdi + ", Telefon Numarasi: " + iletisimNumarasi);
	}

	public static void main(String[] args) {

		// Person details
		String kisiIsmi = "Ahmet";
		int kisiYasi = 30;

		// Address details
		String caddeBilgisi = "Mevlana Caddesi No:5";
		String sehirBilgisi = "Konya";
		String postaKoduBilgisi = "42030";
		String ulkeBilgisi = "Turkiye";

		Adres adresBilgisi = new Adres(caddeBilgisi, sehirBilgisi, postaKoduBilgisi, ulkeBilgisi);

		Kisi kisiBilgisi = new Kisi(kisiIsmi, kisiYasi, adresBilgisi);

		kisiBilgisi.kisiyiTanit();

		// Post office details
		String postaneIsmi = "Konya Postanesi";
		String postaneTelefonu = "0332 123 45 67";

		Postane postaneBilgisi = new Postane(postaneIsmi, postaneTelefonu);

		postaneBilgisi.postaneyiTanit();

		adresBilgisi.adresiYazdir();

		System.out.println("Kisinin yasini kontrol edelim. 18 yasindan buyuk mu?");
		if (kisiBilgisi.getYas() > 18) {
			System.out.println(kisiBilgisi.getIsim() + " 18 yasindan buyuk.");
		} else {
			System.out.println(kisiBilgisi.getIsim() + " 18 yasindan kucuk.");
		}
	}
}

/*
 * Demonstrates overriding equals()/toString(): two Person
 * objects with identical field values compare equal via equals(),
 * even though they are different references.
 */
public class Kisi {

    private String isim;
    private int yasi;

    public Kisi(String isim, int yasi) {
        this.isim = isim;
        this.yasi = yasi;
    }

    // Value-based equality: same class, same name and age.
    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || getClass() != other.getClass()) {
            return false;
        }
        Kisi diger = (Kisi) other;
        return yasi == diger.yasi && isim.equals(diger.isim);
    }

    public String getAd() {
        return isim;
    }

    public int getYas() {
        return yasi;
    }

    @Override
    public String toString() {
        return "Kisi[Ad=" + isim + ", Yas=" + yasi + "]";
    }

    public static void main(String[] args) {
        Kisi kisiA = new Kisi("Ali", 25);
        Kisi kisiB = new Kisi("Ali", 25);

        // Reference comparison - expected to differ since they're distinct objects.
        if (kisiA == kisiB) {
            System.out.println("Iki kisi nesnesi esittir.");
        } else {
            System.out.println("Iki kisi nesnesi esit degildir.");
        }

        // Logical comparison via the overridden equals().
        if (kisiA.equals(kisiB)) {
            System.out.println("Iki kisi nesnesi esittir.");
        } else {
            System.out.println("Iki kisi nesnesi esit degildir.");
        }

        System.out.println(kisiA.toString());
    }
}

/**
 * Returns the middle node of a singly linked list using the two-pointer technique.
 *
 * <p>The {@code slow} pointer advances by one node per iteration while {@code fast} advances by two.
 * When {@code fast == null} or {@code fast.next == null}, {@code slow} points to the middle node.
 * For even-length lists, this returns the <em>second</em> middle node.</p>
 *
 * <p>This method does not modify the input list.</p>
 *
 * <p>Reference: https://en.wikipedia.org/wiki/Cycle_detection#Floyd's_tortoise_and_hare</p>
 *
 * <p>Complexity:</p>
 * <ul>
 *   <li>Time: {@code O(n)}</li>
 *   <li>Space: {@code O(1)}</li>
 * </ul>
 */
public final class MiddleOfLinkedList {

    private MiddleOfLinkedList() {
    }

    /**
     * Returns the middle node of the list.
     *
     * @param head the head of the singly linked list; may be {@code null}
     * @return the middle node (second middle for even-sized lists), or {@code null} if {@code head} is {@code null}
     */
    public static SinglyLinkedListNode middleNode(final SinglyLinkedListNode head) {
        if (head == null) {
            return null;
        }

        SinglyLinkedListNode slow = head;
        SinglyLinkedListNode fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        return slow;
    }
}

public class ChatSunucu {

    public static void main(String[] args) throws IOException {
        try (ServerSocket listener = new ServerSocket(8000)) {
            System.out.println("Sunucu baslatildi");

            // Block until a client connects
            Socket client = listener.accept();

            System.out.println("Istemci baglandi");

            DataInputStream fromClient = new DataInputStream(client.getInputStream());
            DataOutputStream toClient = new DataOutputStream(client.getOutputStream());

            while (true) {
                String message = fromClient.readUTF();
                toClient.writeUTF(message); // simple echo back to the client
            }
        }
    }
}

/**
 * Implementation of the Move-to-Front (MTF) transform and its inverse.
 * <p>
 * MTF is a data transformation algorithm that encodes each symbol in the input
 * as its current position in a dynamically-maintained list, then moves that symbol
 * to the front of the list. This transformation is particularly effective when used
 * after the Burrows-Wheeler Transform (BWT), as BWT groups similar characters together.
 * </p>
 *
 * <p>The transform converts runs of repeated characters into sequences of small integers
 * (often zeros), which are highly compressible by subsequent entropy encoding algorithms
 * like Run-Length Encoding (RLE) or Huffman coding. This technique is used in the
 * bzip2 compression algorithm.
 * </p>
 *
 * <p><b>How it works:</b>
 * <ol>
 *   <li>Maintain a list of symbols (the alphabet), initially in a fixed order</li>
 *   <li>For each input symbol:
 *     <ul>
 *       <li>Output its current index in the list</li>
 *       <li>Move that symbol to the front of the list</li>
 *     </ul>
 *   </li>
 * </ol>
 * This means frequently occurring symbols quickly move to the front and are encoded
 * with small indices (often 0), while rare symbols remain near the back.
 * </p>
 *
 * <p><b>Time Complexity:</b>
 * <ul>
 *   <li>Forward transform: O(n × m) where n is input length and m is alphabet size</li>
 *   <li>Inverse transform: O(n × m)</li>
 * </ul>
 * Note: Using {@link LinkedList} for O(1) insertions and O(m) search operations.
 * </p>
 *
 * <p><b>Example:</b></p>
 * <pre>
 * Input:    "annb$aa"
 * Alphabet: "$abn" (initial order)
 * Output:   [1, 3, 0, 3, 3, 3, 0]
 *
 * Step-by-step:
 * - 'a': index 1 in [$,a,b,n] → output 1, list becomes [a,$,b,n]
 * - 'n': index 3 in [a,$,b,n] → output 3, list becomes [n,a,$,b]
 * - 'n': index 0 in [n,a,$,b] → output 0, list stays [n,a,$,b]
 * - 'b': index 3 in [n,a,$,b] → output 3, list becomes [b,n,a,$]
 * - etc.
 *
 * Notice how repeated 'n' characters produce zeros after the first occurrence!
 * </pre>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Move-to-front_transform">Move-to-front transform (Wikipedia)</a>
 */
public final class MoveToFront {

    private MoveToFront() {
    }

    /**
     * Performs the forward Move-to-Front transform.
     * <p>
     * Converts the input string into a list of integers, where each integer represents
     * the position of the corresponding character in a dynamically-maintained alphabet list.
     * </p>
     *
     * <p><b>Note:</b> All characters in the input text must exist in the provided alphabet,
     * otherwise an {@link IllegalArgumentException} is thrown. The alphabet should contain
     * all unique characters that may appear in the input.</p>
     *
     * @param text the input string to transform; if empty, returns an empty list
     * @param initialAlphabet a string containing the initial ordered set of symbols
     *                        (e.g., "$abn" or the full ASCII set); must not be empty
     *                        when {@code text} is non-empty
     * @return a list of integers representing the transformed data, where each integer
     *         is the index of the corresponding input character in the current alphabet state
     * @throws IllegalArgumentException if {@code text} is non-empty and {@code initialAlphabet}
     *                                  is {@code null} or empty
     * @throws IllegalArgumentException if any character in {@code text} is not found in
     *                                  {@code initialAlphabet}
     */
    public static List<Integer> transform(String text, String initialAlphabet) {
        if (text == null || text.isEmpty()) {
            return new ArrayList<>();
        }
        if (initialAlphabet == null || initialAlphabet.isEmpty()) {
            throw new IllegalArgumentException("Alphabet cannot be null or empty when text is not empty.");
        }

        List<Integer> output = new ArrayList<>(text.length());

        // Use LinkedList for O(1) add-to-front and O(n) remove operations
        // This is more efficient than ArrayList for the move-to-front pattern
        List<Character> alphabet = initialAlphabet.chars().mapToObj(c -> (char) c).collect(Collectors.toCollection(LinkedList::new));

        for (char c : text.toCharArray()) {
            int index = alphabet.indexOf(c);
            if (index == -1) {
                throw new IllegalArgumentException("Symbol '" + c + "' not found in the initial alphabet.");
            }

            output.add(index);

            // Move the character to the front
            Character symbol = alphabet.remove(index);
            alphabet.addFirst(symbol);
        }
        return output;
    }

    /**
     * Performs the inverse Move-to-Front transform.
     * <p>
     * Reconstructs the original string from the list of indices produced by the
     * forward transform. This requires the exact same initial alphabet that was
     * used in the forward transform.
     * </p>
     *
     * <p><b>Important:</b> The {@code initialAlphabet} parameter must be identical
     * to the one used in the forward transform, including character order, or the
     * output will be incorrect.</p>
     *
     * @param indices The list of integers from the forward transform.
     * @param initialAlphabet the exact same initial alphabet string used for the forward transform;
     *                        if {@code null} or empty, returns an empty string
     * @return the original, untransformed string
     * @throws IllegalArgumentException if any index in {@code indices} is negative or
     *                                  exceeds the current alphabet size
     */
    public static String inverseTransform(Collection<Integer> indices, String initialAlphabet) {
        if (indices == null || indices.isEmpty() || initialAlphabet == null || initialAlphabet.isEmpty()) {
            return "";
        }

        StringBuilder output = new StringBuilder(indices.size());

        // Use LinkedList for O(1) add-to-front and O(n) remove operations
        List<Character> alphabet = initialAlphabet.chars().mapToObj(c -> (char) c).collect(Collectors.toCollection(LinkedList::new));

        for (int index : indices) {
            if (index < 0 || index >= alphabet.size()) {
                throw new IllegalArgumentException("Index " + index + " is out of bounds for the current alphabet of size " + alphabet.size() + ".");
            }

            // Get the symbol at the index
            char symbol = alphabet.get(index);
            output.append(symbol);

            // Move the symbol to the front (mirroring the forward transform)
            alphabet.remove(index);
            alphabet.addFirst(symbol);
        }
        return output.toString();
    }
}

public class ThreadOrnegi extends Thread {

    private String mesaj; // Yazdirilacak mesaj
    private int gecikme; // Gecikme suresi (milisaniye cinsinden)
    private volatile boolean calisiyor = true; // Thread'in calisma durumu

    // Constructor: Mesaj ve gecikme suresi ile nesne olusturur
    public ThreadOrnegi(String mesaj, int gecikme) {
        this.mesaj = mesaj;
        this.gecikme = gecikme;
    }

    // Thread'in calisacak metodu
    public void run() {
        int sayac = 0;
        while (calisiyor) {
            System.out.println(Thread.currentThread().getName() + ": " + mesaj + " [" + sayac + "]");
            try {
                Thread.sleep(gecikme); // Belirtilen sure kadar bekle
            } catch (InterruptedException e) {
                System.out.println(Thread.currentThread().getName() + " kesildi.");
                return; // Thread sonlandirilir
            }
            sayac++;
        }
        System.out.println(Thread.currentThread().getName() + " durduruldu.");
    }

    // Thread'i durdurma metodu
    public void durdur() {
        calisiyor = false;
    }

    // Ana metod
    public static void main(String[] args) {
        // Thread nesnelerini olustur ve adlandir
    	ThreadOrnegi thread1 = new ThreadOrnegi("ali", 1000);
        Thread t1 = new Thread(thread1, "Thread-1");

        ThreadOrnegi thread2 = new ThreadOrnegi("veli", 2000);
        Thread t2 = new Thread(thread2, "Thread-2");

        ThreadOrnegi thread3 = new ThreadOrnegi("ayse", 3000);
        Thread t3 = new Thread(thread3, "Thread-3");

        // Thread'leri baslat
        t1.start();
        t2.start();
        t3.start();

        // Ana thread'de baska isler yap
        for (int i = 0; i < 5; i++) {
            System.out.println("Ana thread is yapiyor: " + i);
            try {
                Thread.sleep(500); // 0.5 saniye uyur
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }

        // Belirli bir sure sonra tum thread'leri durdur
        try {
            Thread.sleep(10000); // 10 saniye bekle
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("Tum thread'ler durduruluyor...");
        thread1.durdur();
        thread2.durdur();
        thread3.durdur();

        // Tum thread'lerin tamamlanmasini bekle
        try {
            t1.join();
            t2.join();
            t3.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("Program tamamlandi.");
    }
}

