package com.thealgorithms.conversions;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * Base64 is a group of binary-to-text encoding schemes that represent binary data
 * in an ASCII string format by translating it into a radix-64 representation.
 * Each base64 digit represents exactly 6 bits of data.
 *
 * Base64 encoding is commonly used when there is a need to encode binary data
 * that needs to be stored and transferred over media that are designed to deal
 * with textual data.
 *
 * Wikipedia Reference: https://en.wikipedia.org/wiki/Base64
 * Author: Nithin U.
 * Github: https://github.com/NithinU2802
 */

public final class Base64 {

private static final String ENCODING_TABLE = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
private static final char PADDING_SYMBOL = '=';

private Base64() {
}

/**
 * Encodes the given byte array to a Base64 encoded string.
 *
 * @param sourceData the byte array to encode
 * @return the Base64 encoded string
 * @throws IllegalArgumentException if sourceData is null
 */
public static String encode(byte[] sourceData) {
if (sourceData == null) {
throw new IllegalArgumentException("Input cannot be null");
}
if (sourceData.length == 0) {
return "";
}
StringBuilder encodedOutput = new StringBuilder();
int paddingCount = 0;
for (int offset = 0; offset < sourceData.length; offset += 3) {
int firstByte = sourceData[offset] & 0xFF;
int secondByte = (offset + 1 < sourceData.length) ? (sourceData[offset + 1] & 0xFF) : 0;
int thirdByte = (offset + 2 < sourceData.length) ? (sourceData[offset + 2] & 0xFF) : 0;
if (offset + 1 >= sourceData.length) {
paddingCount = 2;
} else if (offset + 2 >= sourceData.length) {
paddingCount = 1;
}
int combinedValue = (firstByte << 16) | (secondByte << 8) | thirdByte;
encodedOutput.append(ENCODING_TABLE.charAt((combinedValue >> 18) & 0x3F));
encodedOutput.append(ENCODING_TABLE.charAt((combinedValue >> 12) & 0x3F));
encodedOutput.append(ENCODING_TABLE.charAt((combinedValue >> 6) & 0x3F));
encodedOutput.append(ENCODING_TABLE.charAt(combinedValue & 0x3F));
}
if (paddingCount > 0) {
encodedOutput.setLength(encodedOutput.length() - paddingCount);
for (int padIndex = 0; padIndex < paddingCount; padIndex++) {
encodedOutput.append(PADDING_SYMBOL);
}
}
return encodedOutput.toString();
}

/**
 * Encodes the given string to a Base64 encoded string using UTF-8 encoding.
 *
 * @param sourceText the string to encode
 * @return the Base64 encoded string
 * @throws IllegalArgumentException if sourceText is null
 */
public static String encode(String sourceText) {
if (sourceText == null) {
throw new IllegalArgumentException("Input cannot be null");
}
return encode(sourceText.getBytes(StandardCharsets.UTF_8));
}

/**
 * Decodes the given Base64 encoded string to a byte array.
 *
 * @param encodedText the Base64 encoded string to decode
 * @return the decoded byte array
 * @throws IllegalArgumentException if encodedText is null or contains invalid Base64 characters
 */
public static byte[] decode(String encodedText) {
if (encodedText == null) {
throw new IllegalArgumentException("Input cannot be null");
}
if (encodedText.isEmpty()) {
return new byte[0];
}
if (encodedText.length() % 4 != 0) {
throw new IllegalArgumentException("Invalid Base64 input length; must be multiple of 4");
}
int firstPaddingPos = encodedText.indexOf('=');
if (firstPaddingPos != -1 && firstPaddingPos < encodedText.length() - 2) {
throw new IllegalArgumentException("Padding '=' can only appear at the end (last 1 or 2 characters)");
}
List<Byte> decodedBytes = new ArrayList<>();
for (int segmentStart = 0; segmentStart < encodedText.length(); segmentStart += 4) {
int firstChar = getNumericValue(encodedText.charAt(segmentStart));
int secondChar = getNumericValue(encodedText.charAt(segmentStart + 1));
int thirdChar = encodedText.charAt(segmentStart + 2) == '=' ? 0 : getNumericValue(encodedText.charAt(segmentStart + 2));
int fourthChar = encodedText.charAt(segmentStart + 3) == '=' ? 0 : getNumericValue(encodedText.charAt(segmentStart + 3));
int combinedValue = (firstChar << 18) | (secondChar << 12) | (thirdChar << 6) | fourthChar;
decodedBytes.add((byte) ((combinedValue >> 16) & 0xFF));
if (encodedText.charAt(segmentStart + 2) != '=') {
decodedBytes.add((byte) ((combinedValue >> 8) & 0xFF));
}
if (encodedText.charAt(segmentStart + 3) != '=') {
decodedBytes.add((byte) (combinedValue & 0xFF));
}
}
byte[] resultArray = new byte[decodedBytes.size()];
for (int index = 0; index < decodedBytes.size(); index++) {
resultArray[index] = decodedBytes.get(index);
}
return resultArray;
}

/**
 * Decodes the given Base64 encoded string to a string using UTF-8 encoding.
 *
 * @param encodedText the Base64 encoded string to decode
 * @return the decoded string
 * @throws IllegalArgumentException if encodedText is null or contains invalid Base64 characters
 */
public static String decodeToString(String encodedText) {
if (encodedText == null) {
throw new IllegalArgumentException("Input cannot be null");
}
byte[] decodedData = decode(encodedText);
return new String(decodedData, StandardCharsets.UTF_8);
}

/**
 * Gets the numeric value of a Base64 character.
 *
 * @param inputChar the Base64 character
 * @return the numeric value (0-63)
 * @throws IllegalArgumentException if character is not a valid Base64 character
 */
private static int getNumericValue(char inputChar) {
if (inputChar >= 'A' && inputChar <= 'Z') {
return inputChar - 'A';
} else if (inputChar >= 'a' && inputChar <= 'z') {
return inputChar - 'a' + 26;
} else if (inputChar >= '0' && inputChar <= '9') {
return inputChar - '0' + 52;
} else if (inputChar == '+') {
return 62;
} else if (inputChar == '/') {
return 63;
} else {
throw new IllegalArgumentException("Invalid Base64 character: " + inputChar);
}
}
}

