/**
 * A Java program for Prim's Minimum Spanning Tree (MST) algorithm.
 * Adjacency matrix representation of the graph.
 */
public class PrimMST {

private static final int MAX_VERTICES = 5;

int findMinimumVertex(int[] distanceValues, Boolean[] visitedSet) {
int minimumWeight = Integer.MAX_VALUE;
int minVertexIndex = -1;
for (int vertexIndex = 0; vertexIndex < MAX_VERTICES; vertexIndex++) {
if (!visitedSet[vertexIndex] && distanceValues[vertexIndex] < minimumWeight) {
minimumWeight = distanceValues[vertexIndex];
minVertexIndex = vertexIndex;
}
}
return minVertexIndex;
}

public int[] computeMST(int[][] weightMatrix) {
int[] parentNodes = new int[MAX_VERTICES];
int[] minEdgeWeight = new int[MAX_VERTICES];
Boolean[] mstIncluded = new Boolean[MAX_VERTICES];
for (int nodeIndex = 0; nodeIndex < MAX_VERTICES; nodeIndex++) {
minEdgeWeight[nodeIndex] = Integer.MAX_VALUE;
mstIncluded[nodeIndex] = Boolean.FALSE;
}
minEdgeWeight[0] = 0;
parentNodes[0] = -1;
for (int stepCount = 0; stepCount < MAX_VERTICES - 1; stepCount++) {
int selectedVertex = findMinimumVertex(minEdgeWeight, mstIncluded);
mstIncluded[selectedVertex] = Boolean.TRUE;
for (int neighborIndex = 0; neighborIndex < MAX_VERTICES; neighborIndex++) {
if (weightMatrix[selectedVertex][neighborIndex] != 0 &&
!mstIncluded[neighborIndex] &&
weightMatrix[selectedVertex][neighborIndex] < minEdgeWeight[neighborIndex]) {
parentNodes[neighborIndex] = selectedVertex;
minEdgeWeight[neighborIndex] = weightMatrix[selectedVertex][neighborIndex];
}
}
}
return parentNodes;
}
}
