/**
 * A utility class to convert an octal (base-8) number into its binary (base-2) representation.
 *
 * <p>This class provides methods to:
 * <ul>
 *     <li>Convert an octal number to its binary equivalent</li>
 *     <li>Convert individual octal digits to binary</li>
 * </ul>
 *
 * <h2>Octal to Binary Conversion:</h2>
 * <p>An octal number is converted to binary by converting each octal digit to its 3-bit binary equivalent.
 * The result is a long representing the full binary equivalent of the octal number.</p>
 *
 * <h2>Example Usage</h2>
 * <pre>
 *   long binary = OctalToBinary.convertOctalToBinary(52); // Output: 101010 (52 in octal is 101010 in binary)
 * </pre>
 *
 * @author Bama Charan Chhandogi
 * @see <a href="https://en.wikipedia.org/wiki/Octal">Octal Number System</a>
 * @see <a href="https://en.wikipedia.org/wiki/Binary_number">Binary Number System</a>
 */
public final class OctalToBinary {
private OctalToBinary() {
}

/**
 * Converts an octal number to its binary representation.
 *
 * <p>Each octal digit is individually converted to its 3-bit binary equivalent, and the binary
 * digits are concatenated to form the final binary number.</p>
 *
 * @param octalInput the octal number to convert (non-negative integer)
 * @return the binary equivalent as a long
 */
public static long convertOctalToBinary(int octalInput) {
long binaryResult = 0;
int placeMultiplier = 1;
int remainingOctal = octalInput;
while (remainingOctal != 0) {
int currentDigit = remainingOctal % 10;
long binarySegment = convertDigitToBinary(currentDigit);
binaryResult += binarySegment * placeMultiplier;
remainingOctal /= 10;
placeMultiplier *= 1000;
}
return binaryResult;
}

/**
 * Converts a single octal digit (0-7) to its binary equivalent.
 *
 * <p>For example:
 * <ul>
 *     <li>Octal digit 7 is converted to binary 111</li>
 *     <li>Octal digit 3 is converted to binary 011</li>
 * </ul>
 * </p>
 *
 * @param digitValue a single octal digit (0-7)
 * @return the binary equivalent as a long
 */
public static long convertDigitToBinary(int digitValue) {
long binaryEquivalent = 0;
int positionWeight = 1;
int tempValue = digitValue;
while (tempValue != 0) {
int remainderBit = tempValue % 2;
binaryEquivalent += remainderBit * positionWeight;
tempValue /= 2;
positionWeight *= 10;
}
return binaryEquivalent;
}
}

/**
 * Check if a binary tree is symmetric or not.
 * A binary tree is a symmetric tree if the left and right subtree of root are mirror image.
 * Below is a symmetric tree
 *                               1
 *                   /                         \
 *                2                           2
 *         /                \             /             \
 *      3                    4         4                3
 *
 * Below is not symmetric because values is different in last level
 *                               1
 *                   /                         \
 *                 2                           2
 *         /                \             /             \
 *      3                    5         4                3
 * <p>
 * Approach:
 * Recursively check for left and right subtree of root
 * 1. left subtrees root's values should be equal right subtree's root value
 * 2. recursively check with left subtrees' left child VS right subtree's right child AND
 * left subtree's right child VS right subtree left child
 * Complexity
 * 1. Time: O(n)
 * 2. Space: O(lg(n)) for height of tree
 *
 * @author kumanoit on 10/10/22 IST 12:52 AM
 */
public final class CheckTreeIsSymmetric {
    private CheckTreeIsSymmetric() {
    }

    public static boolean isSymmetric(Node root) {
        if (root == null) {
            return true;
        }
        return isSymmetric(root.left, root.right);
    }

    private static boolean isSymmetric(Node leftSubtreeRoot, Node rightSubtreeRoot) {
        if (leftSubtreeRoot == null && rightSubtreeRoot == null) {
            return true;
        }

        if (isInvalidSubtree(leftSubtreeRoot, rightSubtreeRoot)) {
            return false;
        }

        return isSymmetric(leftSubtreeRoot.right, rightSubtreeRoot.left) && isSymmetric(leftSubtreeRoot.left, rightSubtreeRoot.right);
    }

    private static boolean isInvalidSubtree(Node leftSubtreeRoot, Node rightSubtreeRoot) {
        return leftSubtreeRoot == null || rightSubtreeRoot == null || leftSubtreeRoot.data != rightSubtreeRoot.data;
    }
}

public class Human implements Cloneable {
    int ageValue;
    String fullName;
    int[] dataArray;

    public Human(int ageValue, String fullName) {
        this.ageValue = ageValue;
        this.fullName = fullName;
        this.dataArray = new int[]{3, 4, 5, 6, 7};
    }

//    public Human(Human otherInstance) {
//        this.ageValue = otherInstance.ageValue;
//        this.fullName = otherInstance.fullName;
//    }

//    public Object clone() throws  CloneNotSupportedException {
//        // this is shallow copy as twin points to the original array in object ankan.
//        return super.clone();
//    }

    public Object clone() throws  CloneNotSupportedException {
        // this is deep copy implementation
        Human clonedInstance = (Human)super.clone(); // this performs shallow copy initially

        // create a deep copy of the array to avoid shared reference
        clonedInstance.dataArray = new int[clonedInstance.dataArray.length];
        for (int idx = 0; idx < clonedInstance.dataArray.length; idx++) {
            clonedInstance.dataArray[idx] = this.dataArray[idx];
        }
        return clonedInstance;
    }

}

