    private static void arayuzuOlusturVeGoster() {
        JTextArea duzenlemeAlani = new JTextArea("Java Programlama", 8, 50);

        JButton kucultmeTusu = new JButton("Kucuk Harfe Cevir");
        kucultmeTusu.addActionListener(e ->
