        pencere.pack();
        pencere.setVisible(true);
    }
}

package com.thealgorithms.greedyalgorithms;

import java.util.Arrays;

/**
 * The MinimumWaitingTime class provides a method to calculate the minimum
 * waiting time for a list of queries using a greedy algorithm.
 *
 * @author Hardvan
 */
public final class MinimumWaitingTime {
    private MinimumWaitingTime() {
    }

    /**
     * Calculates the minimum waiting time for a list of queries.
     * The function sorts the queries in non-decreasing order and then calculates
     * the waiting time for each query based on its position in the sorted list.
     *
     * @param queries an array of integers representing the query times in picoseconds
     * @return the minimum waiting time in picoseconds
     */
    public static int minimumWaitingTime(int[] queries) {
        int n = queries.length;
        if (n <= 1) {
            return 0;
        }

        Arrays.sort(queries);

        int totalWaitingTime = 0;
        for (int i = 0; i < n; i++) {
            totalWaitingTime += queries[i] * (n - i - 1);
        }
        return totalWaitingTime;
    }
}

public class ChatSunucu {

    public static void main(String[] args) throws IOException {
        try (// Bir sunucu soketi olustur
		ServerSocket sunucuSoketi = new ServerSocket(8000)) {
			System.out.println("Sunucu baslatildi");

			// Bir baglanti istegi bekle
			Socket soket = sunucuSoketi.accept();

			System.out.println("Istemci baglandi");

			// Veri alisverisi icin girdi ve cikti akislari olustur
			DataInputStream istemcidenGelenVeri = new DataInputStream(soket.getInputStream());
			DataOutputStream istemciyeGidenVeri = new DataOutputStream(soket.getOutputStream());

			while (true) {
			    // Istemciden bir mesaj oku
			    String mesaj = istemcidenGelenVeri.readUTF();

			    // Mesaji geri gonder
			    istemciyeGidenVeri.writeUTF(mesaj);
			}
		}
    }
}

/**
 * An implementation of the Arithmetic Coding algorithm.
 *
 * <p>
 * Arithmetic coding is a form of entropy encoding used in lossless data
 * compression. It encodes an entire message into a single number, a fraction n
 * where (0.0 <= n < 1.0). Unlike Huffman coding, which assigns a specific
 * bit sequence to each symbol, arithmetic coding represents the message as a
 * sub-interval of the [0, 1) interval.
 * </p>
 *
 * <p>
 * This implementation uses BigDecimal for precision to handle the shrinking
 * intervals, making it suitable for educational purposes to demonstrate the
 * core logic.
 * </p>
 *
 * <p>
 * Time Complexity: O(n*m) for compression and decompression where n is the
 * length of the input and m is the number of unique symbols, due to the need
 * to calculate symbol probabilities.
 * </p>
 *
 * <p>
 * References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Arithmetic_coding">Wikipedia:
 * Arithmetic coding</a></li>
 * </ul>
 * </p>
 */
public final class ArithmeticCoding {

private ArithmeticCoding() {
}

/**
 * Compresses a string using the Arithmetic Coding algorithm.
 *
 * @param inputData The string to be compressed.
 * @return The compressed representation as a BigDecimal number.
 * @throws IllegalArgumentException if the input string is null or empty.
 */
public static BigDecimal compress(String inputData) {
if (inputData == null || inputData.isEmpty()) {
throw new IllegalArgumentException("Input string cannot be null or empty.");
}
Map<Character, SymbolValue> probabilityMap = buildProbabilityTable(inputData);
BigDecimal intervalLow = BigDecimal.ZERO;
BigDecimal intervalHigh = BigDecimal.ONE;
for (char currentSymbol : inputData.toCharArray()) {
BigDecimal currentRange = intervalHigh.subtract(intervalLow);
SymbolValue symbolData = probabilityMap.get(currentSymbol);
intervalHigh = intervalLow.add(currentRange.multiply(symbolData.upperBound()));
intervalLow = intervalLow.add(currentRange.multiply(symbolData.lowerBound()));
}
return intervalLow;
}

/**
 * Decompresses a BigDecimal number back into the original string.
 *
 * @param compressedData The compressed BigDecimal number.
 * @param originalLength The length of the original uncompressed string.
 * @param probabilityMap The probability table used during compression.
 * @return The original, uncompressed string.
 */
public static String decompress(BigDecimal compressedData, int originalLength, Map<Character, SymbolValue> probabilityMap) {
StringBuilder restoredText = new StringBuilder();
List<Map.Entry<Character, SymbolValue>> sortedEntries = new ArrayList<>(probabilityMap.entrySet());
sortedEntries.sort(Map.Entry.comparingByKey());
BigDecimal currentLow = BigDecimal.ZERO;
BigDecimal currentHigh = BigDecimal.ONE;
for (int step = 0; step < originalLength; step++) {
BigDecimal rangeSize = currentHigh.subtract(currentLow);
for (Map.Entry<Character, SymbolValue> entry : sortedEntries) {
SymbolValue symbolData = entry.getValue();
BigDecimal symbolLower = currentLow.add(rangeSize.multiply(symbolData.lowerBound()));
BigDecimal symbolUpper = currentLow.add(rangeSize.multiply(symbolData.upperBound()));
if (compressedData.compareTo(symbolLower) >= 0 && compressedData.compareTo(symbolUpper) < 0) {
restoredText.append(entry.getKey());
currentLow = symbolLower;
currentHigh = symbolUpper;
break;
}
}
}
return restoredText.toString();
}

/**
 * Calculates the frequency and probability range for each character in the
 * input string in a deterministic order.
 *
 * @param sourceText The input string.
 * @return A map from each character to a Symbol object containing its
 * probability range.
 */
public static Map<Character, SymbolValue> buildProbabilityTable(String sourceText) {
Map<Character, Integer> frequencyMap = new HashMap<>();
for (char currentChar : sourceText.toCharArray()) {
frequencyMap.put(currentChar, frequencyMap.getOrDefault(currentChar, 0) + 1);
}
List<Character> sortedKeys = new ArrayList<>(frequencyMap.keySet());
Collections.sort(sortedKeys);
Map<Character, SymbolValue> probabilityMap = new HashMap<>();
BigDecimal cumulativeLower = BigDecimal.ZERO;
int totalChars = sourceText.length();
for (char currentSymbol : sortedKeys) {
BigDecimal symbolProbability = BigDecimal.valueOf(frequencyMap.get(currentSymbol)).divide(BigDecimal.valueOf(totalChars), MathContext.DECIMAL128);
BigDecimal cumulativeUpper = cumulativeLower.add(symbolProbability);
probabilityMap.put(currentSymbol, new SymbolValue(cumulativeLower, cumulativeUpper));
cumulativeLower = cumulativeUpper;
}
return probabilityMap;
}

/**
 * Helper class to store the probability range [low, high) for a symbol.
 */
public record SymbolValue(BigDecimal lowerBound, BigDecimal upperBound) {
}
}

package com.thealgorithms.greedyalgorithms;

import java.util.Collections;

/**
 * BinaryAddition class to perform binary addition of two binary strings.
 */
public class BinaryAddition {
    /**
     * Computes the sum of two binary characters and a carry.
     * @param a First binary character ('0' or '1').
     * @param b Second binary character ('0' or '1').
     * @param carry The carry from the previous operation ('0' or '1').
     * @return The sum as a binary character ('0' or '1').
     */
    public char sum(char a, char b, char carry) {
        int count = 0;
        if (a == '1') {
            count++;
        }
        if (b == '1') {
            count++;
        }
        if (carry == '1') {
            count++;
        }
        return count % 2 == 0 ? '0' : '1';
    }
    /**
     * Computes the carry for the next higher bit from two binary characters and a carry.
     * @param a First binary character ('0' or '1').
     * @param b Second binary character ('0' or '1').
     * @param carry The carry from the previous operation ('0' or '1').
     * @return The carry for the next bit ('0' or '1').
     */
    public char carry(char a, char b, char carry) {
        int count = 0;
        if (a == '1') {
            count++;
        }
        if (b == '1') {
            count++;
        }
        if (carry == '1') {
            count++;
        }
        return count >= 2 ? '1' : '0';
    }
    /**
     * Adds two binary strings and returns their sum as a binary string.
     * @param a First binary string.
     * @param b Second binary string.
     * @return Binary string representing the sum of the two binary inputs.
     */
    public String addBinary(String a, String b) {
        // Padding the shorter string with leading zeros
        int maxLength = Math.max(a.length(), b.length());
        a = String.join("", Collections.nCopies(maxLength - a.length(), "0")) + a;
        b = String.join("", Collections.nCopies(maxLength - b.length(), "0")) + b;
        StringBuilder result = new StringBuilder();
        char carry = '0';
        // Iterating over the binary strings from the least significant to the most significant bit
        for (int i = maxLength - 1; i >= 0; i--) {
            char sum = sum(a.charAt(i), b.charAt(i), carry);
            carry = carry(a.charAt(i), b.charAt(i), carry);
            result.append(sum);
        }
        // If there's a remaining carry, append it
        if (carry == '1') {
            result.append('1');
        }
        // Reverse the result as we constructed it from the least significant bit
        return result.reverse().toString();
    }
}

public class BasamakDegeri {

	public static void main(String[] args) {

		basamaklariYazdir();

		System.out.println("Basamak Sayisi: " + basamakSayisi(345987));

		System.out.println("Rakamlar Toplami: " + rakamlarToplami(24653));

	}

	// Basamaklari yazdirmak icin bir fonksiyon
	public static void basamaklariYazdir() {
		// Onlar ve birler basamagini gezmek icin donguler
		for (int onlar = 0; onlar <= 4; onlar++) {
			for (int birler = 1; birler <= 9; birler++) {
				// Onlar ve birler basamagini birlestirerek sayiyi olustur
				int sayi = onlar * 10 + birler;
				// Sayiyi ve basamaklari ekrana yazdir
				System.out.println("Onlar basamagi: " + onlar + ", Birler basamagi: " + birler + " --> " + sayi);
			}
		}
	}

	// Rakamlar toplamini bulan fonksiyon
	public static int rakamlarToplami(int sayi) {
		int toplam = 0;
		// Sayinin her rakamini toplamak icin while dongusu
		while (sayi > 0) {
			int kalan = sayi % 10;  // Sayinin son rakamini al
			toplam += kalan;  // Rakami toplam degiskenine ekle
			sayi /= 10;  // Sayiyi bir basamak kucult
		}
		// Hesaplanan toplami dondur
		return toplam;
	}

	// Basamak sayisini bulan fonksiyon
	public static int basamakSayisi(int sayi) {
		int basamak = 0;
		// Sayinin her basamagini saymak icin while dongusu
		while (sayi > 0) {
			basamak++;  // basamak degerini bir arttir
			sayi /= 10;  // Sayiyi bir basamak kucult
		}
		// Hesaplanan basamak sayisini dondur
		return basamak;
	}
}

package forloop;

public class CarpimTablosu {

    public static void main(String[] args) {

        // Baslik yazdirilir
        System.out.println("Carpim Tablosu:");

        // Dis dongu: Satirlari temsil eder
        for (int i = 1; i <= 10; i++) {

            // Ic dongu: Sutunlari temsil eder
            for (int j = 1; j <= 10; j++) {

                // Carpim sonucu yazdirilir, tab ile hizalama yapilir
                System.out.print(i + "x" + j + "=" + (i * j) + "\t");
            }

            // Her satir tamamlandiginda yeni satira gecilir
            System.out.println();
        }
    }
}

/**
 *  Class that provides methods to convert a decimal number to a string representation
 *  in any specified base between 2 and 36.
 *
 * @author Varun Upadhyay (<a href="https://github.com/varunu28">...</a>)
 */
public final class DecimalToAnyBase {
    private static final int MIN_BASE = 2;
    private static final int MAX_BASE = 36;
    private static final char ZERO_CHAR = '0';
    private static final char A_CHAR = 'A';
    private static final int DIGIT_OFFSET = 10;

    private DecimalToAnyBase() {
    }

    /**
     * Converts a decimal number to a string representation in the specified base.
     * For example, converting the decimal number 10 to base 2 would return "1010".
     *
     * @param decimal the decimal number to convert
     * @param base    the base to convert to (must be between {@value #MIN_BASE} and {@value #MAX_BASE})
     * @return the string representation of the number in the specified base
     * @throws IllegalArgumentException if the base is out of the supported range
     */
    public static String convertToAnyBase(int decimal, int base) {
        if (base < MIN_BASE || base > MAX_BASE) {
            throw new IllegalArgumentException("Base must be between " + MIN_BASE + " and " + MAX_BASE);
        }

        if (decimal == 0) {
            return String.valueOf(ZERO_CHAR);
        }

        List<Character> digits = new ArrayList<>();
        while (decimal > 0) {
            digits.add(convertToChar(decimal % base));
            decimal /= base;
        }

        StringBuilder result = new StringBuilder(digits.size());
        for (int i = digits.size() - 1; i >= 0; i--) {
            result.append(digits.get(i));
        }

        return result.toString();
    }

    /**
     * Converts an integer value to its corresponding character in the specified base.
     * This method is used to convert values from 0 to 35 into their appropriate character representation.
     * For example, 0-9 are represented as '0'-'9', and 10-35 are represented as 'A'-'Z'.
     *
     * @param value the integer value to convert (should be less than the base value)
     * @return the character representing the value in the specified base
     */
    private static char convertToChar(int value) {
        if (value >= 0 && value <= 9) {
            return (char) (ZERO_CHAR + value);
        } else {
            return (char) (A_CHAR + value - DIGIT_OFFSET);
        }
    }
}

package com.thealgorithms.maths;

/**
 * In number theory, an abundant number or excessive number is a positive integer for which
 * the sum of its proper divisors is greater than the number.
 * Equivalently, it is a number for which the sum of proper divisors (or aliquot sum) is greater than n.
 *
 * The integer 12 is the first abundant number. Its proper divisors are 1, 2, 3, 4 and 6 for a total of 16.
 *
 * Wiki: https://en.wikipedia.org/wiki/Abundant_number
 */
public final class AbundantNumber {

    private AbundantNumber() {
    }

    // Function to calculate sum of all divisors including n
    private static int sumOfDivisors(int n) {
        int sum = 1 + n; // 1 and n are always divisors
        for (int i = 2; i <= n / 2; i++) {
            if (n % i == 0) {
                sum += i; // adding divisor to sum
            }
        }
        return sum;
    }

    // Common validation method
    private static void validatePositiveNumber(int number) {
        if (number <= 0) {
            throw new IllegalArgumentException("Number must be positive.");
        }
    }

    /**
     * Check if {@code number} is an Abundant number or not by checking sum of divisors > 2n
     *
     * @param number the number
     * @return {@code true} if {@code number} is an Abundant number, otherwise false
     */
    public static boolean isAbundant(int number) {
        validatePositiveNumber(number);

        return sumOfDivisors(number) > 2 * number;
    }

    /**
     * Check if {@code number} is an Abundant number or not by checking Aliquot Sum > n
     *
     * @param number the number
     * @return {@code true} if {@code number} is a Abundant number, otherwise false
     */
    public static boolean isAbundantNumber(int number) {
        validatePositiveNumber(number);

        return AliquotSum.getAliquotSum(number) > number;
    }
}

