/**
 * The MatrixChainMultiplication class provides functionality to compute the
 * optimal way to multiply a sequence of matrices. The optimal multiplication
 * order is determined using dynamic programming, which minimizes the total
 * number of scalar multiplications required.
 */
public final class MatrixChainMultiplication {
    private MatrixChainMultiplication() {
    }

    // Matrices to store minimum multiplication costs and split points
    private static int[][] m;
    private static int[][] s;
    private static int[] p;

    /**
     * Calculates the optimal order for multiplying a given list of matrices.
     *
     * @param matrices an ArrayList of Matrix objects representing the matrices
     *                 to be multiplied.
     * @return a Result object containing the matrices of minimum costs and
     *         optimal splits.
     */
    public static Result calculateMatrixChainOrder(ArrayList<Matrix> matrices) {
        int size = matrices.size();
        m = new int[size + 1][size + 1];
        s = new int[size + 1][size + 1];
        p = new int[size + 1];

        for (int i = 0; i < size + 1; i++) {
            Arrays.fill(m[i], -1);
            Arrays.fill(s[i], -1);
        }

        for (int i = 0; i < p.length; i++) {
            p[i] = i == 0 ? matrices.get(i).col() : matrices.get(i - 1).row();
        }

        matrixChainOrder(size);
        return new Result(m, s);
    }

    /**
     * A helper method that computes the minimum cost of multiplying
     * the matrices using dynamic programming.
     *
     * @param size the number of matrices in the multiplication sequence.
     */
    private static void matrixChainOrder(int size) {
        for (int i = 1; i < size + 1; i++) {
            m[i][i] = 0;
        }

        for (int l = 2; l < size + 1; l++) {
            for (int i = 1; i < size - l + 2; i++) {
                int j = i + l - 1;
                m[i][j] = Integer.MAX_VALUE;

                for (int k = i; k < j; k++) {
                    int q = m[i][k] + m[k + 1][j] + p[i - 1] * p[k] * p[j];
                    if (q < m[i][j]) {
                        m[i][j] = q;
                        s[i][j] = k;
                    }
                }
            }
        }
    }

    /**
     * The Result class holds the results of the matrix chain multiplication
     * calculation, including the matrix of minimum costs and split points.
     */
    public static class Result {
        private final int[][] m;
        private final int[][] s;

        /**
         * Constructs a Result object with the specified matrices of minimum
         * costs and split points.
         *
         * @param m the matrix of minimum multiplication costs.
         * @param s the matrix of optimal split points.
         */
        public Result(int[][] m, int[][] s) {
            this.m = m;
            this.s = s;
        }

        /**
         * Returns the matrix of minimum multiplication costs.
         *
         * @return the matrix of minimum multiplication costs.
         */
        public int[][] getM() {
            return m;
        }

        /**
         * Returns the matrix of optimal split points.
         *
         * @return the matrix of optimal split points.
         */
        public int[][] getS() {
            return s;
        }
    }

    /**
     * The Matrix class represents a matrix with its dimensions and count.
     */
    public static class Matrix {
        private final int count;
        private final int col;
        private final int row;

        /**
         * Constructs a Matrix object with the specified count, number of columns,
         * and number of rows.
         *
         * @param count the identifier for the matrix.
         * @param col   the number of columns in the matrix.
         * @param row   the number of rows in the matrix.
         */
        public Matrix(int count, int col, int row) {
            this.count = count;
            this.col = col;
            this.row = row;
        }

        /**
         * Returns the identifier of the matrix.
         *
         * @return the identifier of the matrix.
         */
        public int count() {
            return count;
        }

        /**
         * Returns the number of columns in the matrix.
         *
         * @return the number of columns in the matrix.
         */
        public int col() {
            return col;
        }

        /**
         * Returns the number of rows in the matrix.
         *
         * @return the number of rows in the matrix.
         */
        public int row() {
            return row;
        }
    }
}

package com.thealgorithms.datastructures.trees;

import java.util.ArrayList;
import java.util.List;

/**
 * Represents an AVL Tree, a self-balancing binary search tree.
 * In an AVL tree, the heights of the two child subtrees of any node
 * differ by at most one. If they differ by more than one at any time,
 * rebalancing is performed to restore this property.
 */
public class AVLTree {

    private Node root;

    private static class Node {
        private int key;
        private int balance;
        private int height;
        private Node left;
        private Node right;
        private Node parent;

        Node(int k, Node p) {
            key = k;
            parent = p;
        }

        public Integer getBalance() {
            return balance;
        }
    }

    /**
     * Inserts a new key into the AVL tree.
     *
     * @param key the key to be inserted
     * @return {@code true} if the key was inserted, {@code false} if the key already exists
     */
    public boolean insert(int key) {
        if (root == null) {
            root = new Node(key, null);
        } else {
            Node n = root;
            Node parent;
            while (true) {
                if (n.key == key) {
                    return false;
                }

                parent = n;
                boolean goLeft = n.key > key;
                n = goLeft ? n.left : n.right;

                if (n == null) {
                    if (goLeft) {
                        parent.left = new Node(key, parent);
                    } else {
                        parent.right = new Node(key, parent);
                    }
                    rebalance(parent);
                    break;
                }
            }
        }
        return true;
    }

    /**
     * Deletes a key from the AVL tree.
     *
     * @param delKey the key to be deleted
     */
    public void delete(int delKey) {
        if (root == null) {
            return;
        }

        // Find the node to be deleted
        Node node = root;
        Node child = root;
        while (child != null) {
            node = child;
            child = delKey >= node.key ? node.right : node.left;
            if (delKey == node.key) {
                delete(node);
                return;
            }
        }
    }

    private void delete(Node node) {
        if (node.left == null && node.right == null) {
            // Leaf node
            if (node.parent == null) {
                root = null;
            } else {
                Node parent = node.parent;
                if (parent.left == node) {
                    parent.left = null;
                } else {
                    parent.right = null;
                }
                rebalance(parent);
            }
            return;
        }

        // Node has one or two children
        Node child;
        if (node.left != null) {
            child = node.left;
            while (child.right != null) {
                child = child.right;
            }
        } else {
            child = node.right;
            while (child.left != null) {
                child = child.left;
            }
        }
        node.key = child.key;
        delete(child);
    }

    /**
     * Returns a list of balance factors for each node in the tree.
     *
     * @return a list of integers representing the balance factors of the nodes
     */
    public List<Integer> returnBalance() {
        List<Integer> balances = new ArrayList<>();
        returnBalance(root, balances);
        return balances;
    }

    private void returnBalance(Node n, List<Integer> balances) {
        if (n != null) {
            returnBalance(n.left, balances);
            balances.add(n.getBalance());
            returnBalance(n.right, balances);
        }
    }

    /**
     * Searches for a key in the AVL tree.
     *
     * @param key the key to be searched
     * @return true if the key is found, false otherwise
     */
    public boolean search(int key) {
        Node result = searchHelper(this.root, key);
        return result != null;
    }

    private Node searchHelper(Node root, int key) {
        if (root == null || root.key == key) {
            return root;
        }

        if (root.key > key) {
            return searchHelper(root.left, key);
        }
        return searchHelper(root.right, key);
    }

    private void rebalance(Node n) {
        setBalance(n);
        if (n.balance == -2) {
            if (height(n.left.left) >= height(n.left.right)) {
                n = rotateRight(n);
            } else {
                n = rotateLeftThenRight(n);
            }
        } else if (n.balance == 2) {
            if (height(n.right.right) >= height(n.right.left)) {
                n = rotateLeft(n);
            } else {
                n = rotateRightThenLeft(n);
            }
        }

        if (n.parent != null) {
            rebalance(n.parent);
        } else {
            root = n;
        }
    }

    private Node rotateLeft(Node a) {
        Node b = a.right;
        b.parent = a.parent;

        a.right = b.left;

        if (a.right != null) {
            a.right.parent = a;
        }

        b.left = a;
        a.parent = b;

        if (b.parent != null) {
            if (b.parent.right == a) {
                b.parent.right = b;
            } else {
                b.parent.left = b;
            }
        }

        setBalance(a, b);
        return b;
    }

    private Node rotateRight(Node a) {
        Node b = a.left;
        b.parent = a.parent;

        a.left = b.right;

        if (a.left != null) {
            a.left.parent = a;
        }

        b.right = a;
        a.parent = b;

        if (b.parent != null) {
            if (b.parent.right == a) {
                b.parent.right = b;
            } else {
                b.parent.left = b;
            }
        }

        setBalance(a, b);
        return b;
    }

    private Node rotateLeftThenRight(Node n) {
        n.left = rotateLeft(n.left);
        return rotateRight(n);
    }

    private Node rotateRightThenLeft(Node n) {
        n.right = rotateRight(n.right);
        return rotateLeft(n);
    }

    private int height(Node n) {
        if (n == null) {
            return -1;
        }
        return n.height;
    }

    private void setBalance(Node... nodes) {
        for (Node n : nodes) {
            reheight(n);
            n.balance = height(n.right) - height(n.left);
        }
    }

    private void reheight(Node node) {
        if (node != null) {
            node.height = 1 + Math.max(height(node.left), height(node.right));
        }
    }
}

/*
 * Bu program, bir topun ziplamasini simule eder ve her saniyede yuksekligini hesaplar:
 * 
 * Topun hizi, yer cekimi ivmesine ve gecen zamana orantili olarak azalir. 
 * Topun yuksekligi negatif oldugunda, program topun hizini ters cevirir 
 * ve hizini %50 azaltarak ziplamayi simule eder.
 * 
 */

public class Ziplama {

  public static void main(String[] args) {

    Scanner sc = new Scanner(System.in);

    // Kullanicidan ilk hizi girmesi istenir
    System.out.print("Ilk hizi giriniz: ");
    double hiz = sc.nextDouble();
    sc.close();

    // Baslangic yuksekligi 0 olarak ayarlanir
    double yukseklik = 0;

    // Baslangic zamani 0 olarak ayarlanir
    double zaman = 0;

    // Ziplamalari saymak icin sayac
    int ziplama = 0;

    // Topun besinci ziplamasina kadar simule edilir
    while (ziplama < 5) {
      // Mevcut zaman, yukseklik ve hiz yazdirilir
      System.out.println("Zaman: " + zaman + " saniye " + " Yukseklik: " + yukseklik + " feet " + " Hiz: " + hiz);

      // Yukseklik ve hiz guncellenir
      yukseklik += hiz;
      hiz -= 32;

      // Topun yere carpip carpamadigi kontrol edilir
      if (yukseklik < 0) {
        // Hiz ters cevrilir ve %50 azaltilir
        hiz *= -0.5;

        // Yukseklik sifira resetlenir
        yukseklik = 0;

        // Ziplama sayaci bir artirilir
        ziplama++;
      }

      // Zaman bir artirilir
      zaman++;
    }
  }
}

