/**
 * Disjoint Set Union (DSU), also known as Union-Find, is a data structure that tracks a set of elements
 * partitioned into disjoint (non-overlapping) subsets. It supports two primary operations efficiently:
 *
 * <ul>
 *     <li>Find: Determine which subset a particular element belongs to.</li>
 *     <li>Union: Merge two subsets into a single subset.</li>
 * </ul>
 *
 * @see <a href="https://en.wikipedia.org/wiki/Disjoint-set_data_structure">Disjoint Set Union (Wikipedia)</a>
 */
public class DisjointSetUnion<T> {

    /**
     * Creates a new disjoint set containing the single specified element.
     *
     * @param value the element to be placed in a new singleton set
     * @return a node representing the new set
     */
    public Node<T> makeSet(final T value) {
        return new Node<>(value);
    }

    /**
     * Finds and returns the representative (root) of the set containing the given node.
     * This method applies path compression to flatten the tree structure for future efficiency.
     *
     * @param node the node whose set representative is to be found
     * @return the representative (root) node of the set
     */
    public Node<T> findSet(Node<T> node) {
        if (node != node.parent) {
            node.parent = findSet(node.parent);
        }
        return node.parent;
    }

    /**
     * Merges the sets containing the two given nodes. Union by rank is used to attach the smaller tree under the larger one.
     * If both sets have the same rank, one becomes the parent and its rank is incremented.
     *
     * @param x a node in the first set
     * @param y a node in the second set
     */
    public void unionSets(Node<T> x, Node<T> y) {
        Node<T> rootX = findSet(x);
        Node<T> rootY = findSet(y);

        if (rootX == rootY) {
            return; // They are already in the same set
        }
        // Merging happens based on rank of node, this is done to avoid long chaining of nodes and reduce time
        // to find root of the component. Idea is to attach small components in big, instead of other way around.
        if (rootX.rank > rootY.rank) {
            rootY.parent = rootX;
        } else if (rootY.rank > rootX.rank) {
            rootX.parent = rootY;
        } else {
            rootY.parent = rootX;
            rootX.rank++;
        }
    }
}

public class Faktoriyel {

	// Rekursif olarak faktoriyel hesaplayan metod
	public static int recursiveFaktoriyel(int sayi) {
		int sonuc = 0; // Baslangic degeri
		// Eger sayi 0 ise, faktoriyel 1 olarak kabul edilir
		if (sayi == sonuc) {
			return sonuc + 1;
		}
		// Aksi takdirde, ozyinelemeli olarak sayi * (sayi-1)'in faktoriyeli hesaplanir
		return sayi * recursiveFaktoriyel(sayi - 1);
	}

	// Dongu ile faktoriyel hesaplayan metod
	public static int iterativeFaktoriyel(int sayi) {
		int sonuc = 1; // Sonuc 1 olarak alinir

		// 1'den sayiya kadar olan sayilari carpip faktoriyel hesaplanir
		for (int i = 1; i <= sayi; i++) {
			sonuc *= i;
		}
		return sonuc;
	}

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		System.out.print("Faktoriyelini hesaplamak icin bir sayi girin: ");
		int sayi = sc.nextInt();
		sc.close();

		// Sonucu ekrana yazdir
		System.out.println(sayi + " sayisinin faktoriyeli (iterative): " + iterativeFaktoriyel(sayi));
		System.out.println(sayi + " sayisinin faktoriyeli (rekursive): " + recursiveFaktoriyel(sayi));
	}
}

/**
 * An implementation of the Run-Length Encoding (RLE) algorithm.
 *
 * <p>Run-Length Encoding is a simple form of lossless data compression in which
 * runs of data (sequences in which the same data value occurs in many
 * consecutive data elements) are stored as a single data value and count,
 * rather than as the original run.
 *
 * <p>This implementation provides methods for both compressing and decompressing
 * a string. For example:
 * <ul>
 * <li>Compressing "AAAABBBCCDAA" results in "4A3B2C1D2A".</li>
 * <li>Decompressing "4A3B2C1D2A" results in "AAAABBBCCDAA".</li>
 * </ul>
 *
 * <p>Time Complexity: O(n) for both compression and decompression, where n is the
 * length of the input string.
 *
 * <p>References:
 * <ul>
 * <li><a href="https://en.wikipedia.org/wiki/Run-length_encoding">Wikipedia: Run-length encoding</a></li>
 * </ul>
 */
public final class RunLengthEncoding {

/**
 * Private constructor to prevent instantiation of this utility class.
 */
private RunLengthEncoding() {
}

/**
 * Compresses a string using the Run-Length Encoding algorithm.
 *
 * @param sourceText The string to be compressed. Must not be null.
 * @return The compressed string. Returns an empty string if the input is empty.
 */
public static String compress(String sourceText) {
if (sourceText == null || sourceText.isEmpty()) {
return "";
}
StringBuilder encodedResult = new StringBuilder();
int repeatCount = 1;
for (int position = 0; position < sourceText.length(); position++) {
if (position == sourceText.length() - 1 || sourceText.charAt(position) != sourceText.charAt(position + 1)) {
encodedResult.append(repeatCount);
encodedResult.append(sourceText.charAt(position));
repeatCount = 1;
} else {
repeatCount++;
}
}
return encodedResult.toString();
}

/**
 * Decompresses a string that was compressed using the Run-Length Encoding algorithm.
 *
 * @param encodedData The compressed string. Must not be null.
 * @return The original, uncompressed string.
 */
public static String decompress(String encodedData) {
if (encodedData == null || encodedData.isEmpty()) {
return "";
}
StringBuilder decodedResult = new StringBuilder();
int numberBuffer = 0;
for (char currentSymbol : encodedData.toCharArray()) {
if (Character.isDigit(currentSymbol)) {
numberBuffer = numberBuffer * 10 + (currentSymbol - '0');
} else {
decodedResult.append(String.valueOf(currentSymbol).repeat(Math.max(0, numberBuffer)));
numberBuffer = 0;
}
}
return decodedResult.toString();
}
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

/*
 * Reads arithmetic expressions line by line from "islemler.txt". Each line
 * holds two numbers and an operator separated by spaces; the computed
 * result for each line is printed to the console.
 */

public class HesapMakinesi {

    public static void main(String[] args) {

        try {
            BufferedReader lineSource = new BufferedReader(new FileReader("islemler.txt"));
            String line;

            while ((line = lineSource.readLine()) != null) {
                String[] tokens = line.split(" ");
                int operandA = Integer.parseInt(tokens[0]);
                int operandB = Integer.parseInt(tokens[2]);
                char operator = tokens[1].charAt(0);
                int result;

                switch (operator) {
                    case '+':
                        result = operandA + operandB;
                        break;
                    case '-':
                        result = operandA - operandB;
                        break;
                    case '*':
                        result = operandA * operandB;
                        break;
                    case '/':
                        if (operandB == 0) {
                            System.out.println("Hata: Sifira bolme yapilamaz!");
                            continue; // skip printing, move to the next line
                        }
                        result = operandA / operandB;
                        break;
                    default:
                        result = 0;
                        break;
                }

                System.out.println(operandA + " " + operator + " " + operandB + " = " + result);
            }

            lineSource.close();
        } catch (IOException fileEx) {
            System.out.println("Dosya okunurken bir hata olustu: " + fileEx.getMessage());
        } catch (NumberFormatException parseEx) {
            System.out.println("Sayilari parse ederken bir hata olustu: " + parseEx.getMessage());
        }
    }
}

/**
 * A utility class to convert between Cartesian and Polar coordinate systems.
 *
 * <p>This class provides methods to perform the following conversions:
 * <ul>
 *   <li>Cartesian to Polar coordinates</li>
 *   <li>Polar to Cartesian coordinates</li>
 * </ul>
 *
 * <p>The class is final and cannot be instantiated.
 */
public final class CoordinateConverter {

private CoordinateConverter() {
}

/**
 * Converts Cartesian coordinates to Polar coordinates.
 *
 * @param coordX the x-coordinate in the Cartesian system; must be a finite number
 * @param coordY the y-coordinate in the Cartesian system; must be a finite number
 * @return an array where the first element is the radius (r) and the second element is the angle (theta) in degrees
 * @throws IllegalArgumentException if coordX or coordY is not a finite number
 */
public static double[] cartesianToPolar(double coordX, double coordY) {
if (!Double.isFinite(coordX) || !Double.isFinite(coordY)) {
throw new IllegalArgumentException("x and y must be finite numbers.");
}
double radiusValue = Math.sqrt(coordX * coordX + coordY * coordY);
double angleDegrees = Math.toDegrees(Math.atan2(coordY, coordX));
return new double[] {radiusValue, angleDegrees};
}

/**
 * Converts Polar coordinates to Cartesian coordinates.
 *
 * @param radiusValue the radius in the Polar system; must be non-negative
 * @param angleDegrees the angle (theta) in degrees in the Polar system; must be a finite number
 * @return an array where the first element is the x-coordinate and the second element is the y-coordinate in the Cartesian system
 * @throws IllegalArgumentException if radiusValue is negative or angleDegrees is not a finite number
 */
public static double[] polarToCartesian(double radiusValue, double angleDegrees) {
if (radiusValue < 0) {
throw new IllegalArgumentException("Radius (r) must be non-negative.");
}
if (!Double.isFinite(angleDegrees)) {
throw new IllegalArgumentException("Theta (angle) must be a finite number.");
}
double angleRadians = Math.toRadians(angleDegrees);
double coordX = radiusValue * Math.cos(angleRadians);
double coordY = radiusValue * Math.sin(angleRadians);
return new double[] {coordX, coordY};
}
}

/**
 * This class implements the algorithm for calculating the maximum weighted matching in a tree.
 * The tree is represented as an undirected graph with weighted edges.
 *
 * Problem Description:
 *  Given an undirected tree G = (V, E) with edge weights γ: E → N and a root r ∈ V,
 *  the goal is to find a maximum weight matching M ⊆ E such that no two edges in M
 *  share a common vertex. The sum of the weights of the edges in M, ∑ e∈M γ(e), should be maximized.
 *  For more Information: <a href="https://en.wikipedia.org/wiki/Matching_(graph_theory)">Matching (graph theory)</a>
 *
 * @author  <a href="https://github.com/DenizAltunkapan">Deniz Altunkapan</a>
 */
public class TreeMatching {

    private UndirectedAdjacencyListGraph graph;
    private int[][] dp;

    /**
     * Constructor that initializes the graph and the DP table.
     *
     * @param graph The graph that represents the tree and is used for the matching algorithm.
     */
    public TreeMatching(UndirectedAdjacencyListGraph graph) {
        this.graph = graph;
        this.dp = new int[graph.size()][2];
    }

    /**
     * Calculates the maximum weighted matching for the tree, starting from the given root node.
     *
     * @param root The index of the root node of the tree.
     * @param parent The index of the parent node (used for recursion).
     * @return The maximum weighted matching for the tree, starting from the root node.
     *
     */
    public int getMaxMatching(int root, int parent) {
        if (root < 0 || root >= graph.size()) {
            throw new IllegalArgumentException("Invalid root: " + root);
        }
        maxMatching(root, parent);
        return Math.max(dp[root][0], dp[root][1]);
    }

    /**
     * Recursively computes the maximum weighted matching for a node, assuming that the node
     * can either be included or excluded from the matching.
     *
     * @param node The index of the current node for which the matching is calculated.
     * @param parent The index of the parent node (to avoid revisiting the parent node during recursion).
     */
    private void maxMatching(int node, int parent) {
        dp[node][0] = 0;
        dp[node][1] = 0;

        int sumWithoutEdge = 0;
        for (int adjNode : graph.getNeighbors(node)) {
            if (adjNode == parent) {
                continue;
            }
            maxMatching(adjNode, node);
            sumWithoutEdge += Math.max(dp[adjNode][0], dp[adjNode][1]);
        }

        dp[node][0] = sumWithoutEdge;

        for (int adjNode : graph.getNeighbors(node)) {
            if (adjNode == parent) {
                continue;
            }
            int weight = graph.getEdgeWeight(node, adjNode);
            dp[node][1] = Math.max(dp[node][1], sumWithoutEdge - Math.max(dp[adjNode][0], dp[adjNode][1]) + dp[adjNode][0] + weight);
        }
    }
}

