public class SayiOkuma {

    public static void main(String[] args) {
        int[] denemeler = {1234, 7248, 297, 505, 300};
        for (int deger : denemeler) {
            System.out.println(sozeCevir(deger));
        }
    }

    // Verilen sayiyi Turkce okunusuna cevirir (0-9999 araligi icin)
    public static String sozeCevir(int sayi) {
        if (sayi == 0) {
            return "sifir";
        }

        final String[] TEK_BASAMAK = {"", "bir", "iki", "uc", "dort", "bes", "alti", "yedi", "sekiz", "dokuz"};
        final String[] ON_KATLARI = {"", "on", "yirmi", "otuz", "kirk", "elli", "altmis", "yetmis", "seksen", "doksan"};

        int binlik = sayi / 1000;
        int yuzlukHane = (sayi / 100) % 10;
        int onlukHane = (sayi / 10) % 10;
        int birlikHane = sayi % 10;

        StringBuilder metin = new StringBuilder();

        if (binlik > 0) {
            if (binlik > 1) {
                metin.append(TEK_BASAMAK[binlik]).append(' ');
            }
            metin.append("bin").append(' ');
        }

        if (yuzlukHane > 0) {
            if (yuzlukHane > 1) {
                metin.append(TEK_BASAMAK[yuzlukHane]).append(' ');
            }
            metin.append("yuz").append(' ');
        }

        if (onlukHane > 0) {
            metin.append(ON_KATLARI[onlukHane]).append(' ');
        }

        if (birlikHane > 0) {
            metin.append(TEK_BASAMAK[birlikHane]);
        }

        return metin.toString();
    }
}

