package com.thealgorithms.ciphers;

/**
 * The AffineCipher class implements the Affine cipher, a type of monoalphabetic substitution cipher.
 * It encrypts and decrypts messages using a linear transformation defined by the formula:
 *
 *     E(x) = (a * x + b) mod m
 *     D(y) = a^-1 * (y - b) mod m
 *
 * where:
 * - E(x) is the encrypted character,
 * - D(y) is the decrypted character,
 * - a is the multiplicative key (must be coprime to m),
 * - b is the additive key,
 * - x is the index of the plaintext character,
 * - y is the index of the ciphertext character,
 * - m is the size of the alphabet (26 for the English alphabet).
 *
 * The class provides methods for encrypting and decrypting messages, as well as a main method to demonstrate its usage.
 */
final class AffineCipher {
    private AffineCipher() {
    }

    // Key values of a and b
    static int a = 17;
    static int b = 20;

    /**
     * Encrypts a message using the Affine cipher.
     *
     * @param msg the plaintext message as a character array
     * @return the encrypted ciphertext
     */
    static String encryptMessage(char[] msg) {
        // Cipher Text initially empty
        StringBuilder cipher = new StringBuilder();
        for (int i = 0; i < msg.length; i++) {
            // Avoid space to be encrypted
            /* applying encryption formula ( a * x + b ) mod m
            {here x is msg[i] and m is 26} and added 'A' to
            bring it in the range of ASCII alphabet [65-90 | A-Z] */
            if (msg[i] != ' ') {
                cipher.append((char) ((((a * (msg[i] - 'A')) + b) % 26) + 'A'));
            } else { // else simply append space character
                cipher.append(msg[i]);
            }
        }
        return cipher.toString();
    }

    /**
     * Decrypts a ciphertext using the Affine cipher.
     *
     * @param cipher the ciphertext to decrypt
     * @return the decrypted plaintext message
     */
    static String decryptCipher(String cipher) {
        StringBuilder msg = new StringBuilder();
        int aInv = 0;
        int flag;

        // Find a^-1 (the multiplicative inverse of a in the group of integers modulo m.)
        for (int i = 0; i < 26; i++) {
            flag = (a * i) % 26;

            // Check if (a * i) % 26 == 1,
            // then i will be the multiplicative inverse of a
            if (flag == 1) {
                aInv = i;
                break;
            }
        }
        for (int i = 0; i < cipher.length(); i++) {
            /* Applying decryption formula a^-1 * (x - b) mod m
            {here x is cipher[i] and m is 26} and added 'A'
            to bring it in the range of ASCII alphabet [65-90 | A-Z] */
            if (cipher.charAt(i) != ' ') {
                msg.append((char) (((aInv * ((cipher.charAt(i) - 'A') - b + 26)) % 26) + 'A'));
            } else { // else simply append space character
                msg.append(cipher.charAt(i));
            }
        }

        return msg.toString();
    }
}

/* The following class implements a vertical order traversal
in a tree from top to bottom and left to right, so for a tree :
           1
          / \
         2   3
        / \   \
       4   5   6
        \     / \
         7   8   10
          \
           9
 the sequence will be :
 4 2 7 1 5 9 3 8 6 10
 */
public final class VerticalOrderTraversal {
    private VerticalOrderTraversal() {
    }

    /*Function that receives a root Node and prints the tree
        in Vertical Order.*/
    public static ArrayList<Integer> verticalTraversal(BinaryTree.Node root) {
        if (root == null) {
            return new ArrayList<>();
        }

        /*Queue to store the Nodes.*/
        Queue<BinaryTree.Node> queue = new LinkedList<>();

        /*Queue to store the index of particular vertical
                 column of a tree , with root at 0, Nodes on left
                 with negative index and Nodes on right with positive
                 index. */
        Queue<Integer> index = new LinkedList<>();

        /*Map of Integer and ArrayList to store all the
                 elements in a particular index in a single arrayList
                 that will have a key equal to the index itself. */
        Map<Integer, ArrayList<Integer>> map = new HashMap<>();

        /* min and max stores leftmost and right most index to
                 later print the tree in vertical fashion.*/
        int max = 0;
        int min = 0;
        queue.offer(root);
        index.offer(0);

        while (!queue.isEmpty()) {
            if (queue.peek().left != null) {
                /*Adding the left Node if it is not null
                                and its index by subtracting 1 from it's
                                parent's index*/
                queue.offer(queue.peek().left);
                index.offer(index.peek() - 1);
            }
            if (queue.peek().right != null) {
                /*Adding the right Node if it is not null
                                and its index by adding 1 from it's
                                parent's index*/
                queue.offer(queue.peek().right);
                index.offer(index.peek() + 1);
            }
            /*If the map does not contains the index a new
                         ArrayList is created with the index as key.*/
            if (!map.containsKey(index.peek())) {
                ArrayList<Integer> a = new ArrayList<>();
                map.put(index.peek(), a);
            }
            /*For a index, corresponding Node data is added
                         to the respective ArrayList present at that
                         index. */
            map.get(index.peek()).add(queue.peek().data);
            max = Math.max(max, index.peek());
            min = Math.min(min, index.peek());
            /*The Node and its index are removed
                         from their respective queues.*/
            index.poll();
            queue.poll();
        }
        /*Finally map data is printed here which has keys
                from min to max. Each ArrayList represents a
                vertical column that is added in ans ArrayList.*/
        ArrayList<Integer> ans = new ArrayList<>();
        for (int i = min; i <= max; i++) {
            ans.addAll(map.get(i));
        }
        return ans;
    }
}

package datatypes;

public class CharVeBooleanOrnegi {

    public static void main(String[] args) {

        // Temel char ve boolean degiskenler
        char harf = 'A';
        boolean durum = true;

        System.out.println("Karakter: " + harf);
        System.out.println("Boolean Degeri: " + durum);

        // char -> int donusumu ASCII kodunu verir
        int asciiKodu = harf;
        System.out.println("Karakterin ASCII Degeri: " + asciiKodu);

        // Boolean degere gore dallanma
        String yorum = durum ? "Bu ifade dogru." : "Bu ifade yanlis.";
        System.out.println(yorum);

        // int -> char donusumu (explicit cast)
        int kodDegeri = 66;
        char harfeDonusen = (char) kodDegeri;
        System.out.println("ASCII Degerinden Karakter: " + harfeDonusen);

        // iki karakterin ASCII degerlerinin toplanmasi
        char birinciHarf = 'B';
        char ikinciHarf = 'C';
        int harfToplami = birinciHarf + ikinciHarf;
        System.out.println("Char1 ve Char2'nin toplami (ASCII Degerleri): " + harfToplami);

        // Mantiksal degil (NOT) islemi
        boolean tersDurum = !durum;
        System.out.println("Ters deger: " + tersDurum);

        // iki kosulun VE ile birlikte degerlendirilmesi
        if (durum && !tersDurum) {
            System.out.println("Her iki kosul dogru.");
        } else {
            System.out.println("Kosullardan biri yanlis.");
        }

        // Buyuk/kucuk harf donusumleri
        char kucukHali = Character.toLowerCase(harf);
        System.out.println("Karakterin kucuk harfi: " + kucukHali);

        char buyukHali = Character.toUpperCase(kucukHali);
        System.out.println("Char'in buyuk harfi: " + buyukHali);
    }
}

