    public void output() {
        System.out.println("Colour: " + colour);
        System.out.println("EnginePower: " + enginePower);
        // mirrors the original's bug: prints enginePower instead of convertible
        System.out.println("Convertible: " + enginePower);
        System.out.println("ParkingBrake: " + parkingBrake);
    }

    @Override
    public String toString() {
        return "Car{colour=" + colour + ", enginePower=" + enginePower + ", convertible=" + convertible + ", parkingBrake=" + parkingBrake + '}';
    }
}

package com.thealgorithms.maths;

/**
 * This class checks whether a given number is an Armstrong number or not.
 * An Armstrong number is a number that is equal to the sum of its own digits,
 * each raised to the power of the number of digits.
 *
 * For example, 370 is an Armstrong number because 3^3 + 7^3 + 0^3 = 370.
 * 1634 is an Armstrong number because 1^4 + 6^4 + 3^4 + 4^4 = 1634.
 * An Armstrong number is often called a Narcissistic number.
 *
 * @author satyabarghav
 * @modifier rahul katteda - (13/01/2025) - [updated the logic for getting total number of digits]
 */
public class Armstrong {

    /**
     * Checks whether a given number is an Armstrong number or not.
     *
     * @param number the number to check
     * @return {@code true} if the given number is an Armstrong number, {@code false} otherwise
     */
    public boolean isArmstrong(int number) {
        if (number < 0) {
            return false; // Negative numbers cannot be Armstrong numbers
        }
        long sum = 0;
        int totalDigits = (int) Math.log10(number) + 1; // get the length of the number (number of digits)
        long originalNumber = number;

        while (originalNumber > 0) {
            long digit = originalNumber % 10;
            sum += (long) Math.pow(digit, totalDigits); // The digit raised to the power of total number of digits and added to the sum.
            originalNumber /= 10;
        }

        return sum == number;
    }
}

/**
 * @author Varun Upadhyay (https://github.com/varunu28)
 */
public final class CoinChange {
    private CoinChange() {
    }

    /**
     * This method finds the number of combinations of getting change for a
     * given amount and change coins
     *
     * @param coins The list of coins
     * @param amount The amount for which we need to find the change Finds the
     * number of combinations of change
     */
    public static int change(int[] coins, int amount) {
        int[] combinations = new int[amount + 1];
        combinations[0] = 1;

        for (int coin : coins) {
            for (int i = coin; i < amount + 1; i++) {
                combinations[i] += combinations[i - coin];
            }
        }

        return combinations[amount];
    }

    /**
     * This method finds the minimum number of coins needed for a given amount.
     *
     * @param coins The list of coins
     * @param amount The amount for which we need to find the minimum number of
     * coins. Finds the minimum number of coins that make a given value.
     */
    public static int minimumCoins(int[] coins, int amount) {
        // minimumCoins[i] will store the minimum coins needed for amount i
        int[] minimumCoins = new int[amount + 1];

        minimumCoins[0] = 0;

        for (int i = 1; i <= amount; i++) {
            minimumCoins[i] = Integer.MAX_VALUE;
        }
        for (int i = 1; i <= amount; i++) {
            for (int coin : coins) {
                if (coin <= i) {
                    int subRes = minimumCoins[i - coin];
                    if (subRes != Integer.MAX_VALUE && subRes + 1 < minimumCoins[i]) {
                        minimumCoins[i] = subRes + 1;
                    }
                }
            }
        }

        return minimumCoins[amount];
    }
}

