public class HanoiKuleleri extends JFrame {

    private static final long serialVersionUID = 1L;
    private static final int PENCERE_GENISLIGI = 600; // Pencere genisligi
    private static final int PENCERE_YUKSEKLIGI = 400; // Pencere yuksekligi

    private static final int CUBUK_GENISLIGI = 100; // cubuk genisligi (daha genis)
    private static final int CUBUK_YUKSEKLIGI = 300; // cubuk yuksekligi

    private static final int DISK_YUKSEKLIGI = 20; // Disk yuksekligi
    private static final int DISK_SAYISI = 4; // Disk sayisi
    private static final int CUBUK_SAYISI = 3; // cubuk sayisi

    private int[] cubukYukseklikleri; // cubuklarin yukseklikleri
    private JPanel[] cubuklar; // cubuklar
    private JPanel[] diskler; // Diskler

    public HanoiKuleleri() {
        cubukYukseklikleri = new int[CUBUK_SAYISI];

        // cubuklari dikey paneller olarak olustur
        cubuklar = new JPanel[CUBUK_SAYISI];
        for (int i = 0; i < CUBUK_SAYISI; i++) {
            cubuklar[i] = new JPanel();
            cubuklar[i].setPreferredSize(new Dimension(CUBUK_GENISLIGI, CUBUK_YUKSEKLIGI));
            cubuklar[i].setBackground(new Color(144, 238, 144)); // cubugun rengi acik yesil
        }

        // Diskleri yatay paneller olarak olustur, genisliklerini farkli yap
        diskler = new JPanel[DISK_SAYISI];
        for (int i = 0; i < DISK_SAYISI; i++) {
            // ilk disk daha dar, son disk daha genis olacak sekilde genislik ayarlandi
            int diskWidth = (DISK_SAYISI - i + 1) * DISK_YUKSEKLIGI; // Genislik, her bir disk icin farkli olacak
            diskler[i] = new JPanel();
            diskler[i].setPreferredSize(new Dimension(diskWidth, DISK_YUKSEKLIGI)); // Farkli genislikte diskler
            diskler[i].setBackground(Color.RED); // Disklerin rengi kirmizi
        }

        // Diskleri ilk cubuga ekle
        cubukYukseklikleri[0] = DISK_SAYISI;
        for (int i = 0; i < DISK_SAYISI; i++) {
            cubuklar[0].add(diskler[i]);
        }

        // cubuklari ana panele ekle
        JPanel mainPanel = new JPanel();
        mainPanel.setLayout(new FlowLayout(FlowLayout.CENTER, 10, 10));
        for (int i = 0; i < CUBUK_SAYISI; i++) {
            mainPanel.add(cubuklar[i]);
        }

        // Ana pencereyi ayarla
        setTitle("Tower of Hanoi");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(PENCERE_GENISLIGI, PENCERE_YUKSEKLIGI);
        setLocationRelativeTo(null);
        setResizable(false); // Pencereyi yeniden boyutlandirilamaz yap
        add(mainPanel);
    }

    // Diski bir cubuktan digerine tasiyan metod
    public void moveDisk(int kaynak, int hedef) {
        // "kaynak" cubugundaki en ust diski cikar
        JPanel disk = (JPanel) cubuklar[kaynak].getComponent(--cubukYukseklikleri[kaynak]);
        cubuklar[kaynak].remove(disk);

        // Diski "hedef" cubuguna ekle
        cubuklar[hedef].add(disk, cubukYukseklikleri[hedef]++);

        // Ekrani guncelle
        revalidate();
        repaint();
    }

    // Ana metod
    public static void main(String[] args) throws InterruptedException {
    	HanoiKuleleri gui = new HanoiKuleleri();
        gui.setVisible(true);

        // Rekursif algoritma ile bulmacayi coz
        coz(DISK_SAYISI, 0, 2, 1, gui);
    }

    // Tower of Hanoi'yu cozmek icin rekursif metod
    public static void coz(int diskSayisi, int kaynak, int hedef, int yardimci, HanoiKuleleri gui) throws InterruptedException {
        if (diskSayisi == 1) {
            // En ust diski "kaynak" cubugundan "hedef" cubuguna tasi
            gui.moveDisk(kaynak, hedef);
            Thread.sleep(500); // 1 saniye bekle
        } else {
            // "kaynak" cubugundaki diskSayisi - 1 diski "yardimci" cubuguna tasi, "hedef" cubugunu yardimci olarak kullan
        	coz(diskSayisi - 1, kaynak, yardimci, hedef, gui);

            // Kalan diski "kaynak" cubugundan "hedef" cubuguna tasi
            gui.moveDisk(kaynak, hedef);

            Thread.sleep(500); // 1 saniye bekle

            // diskSayisi - 1 diski "yardimci" cubugundan "hedef" cubuguna tasi, "kaynak" cubugunu yardimci olarak kullan
            coz(diskSayisi - 1, yardimci, hedef, kaynak, gui);
        }
    }
}

/**
 * DFS that visits a successor only when all its predecessors are already visited,
 * emitting VISIT and SKIP events.
 * <p>
 *     This class includes a DFS variant that visits a successor only when all of its
 *     predecessors have already been visited
 * </p>
 * <p>Related reading:
 * <ul>
 *   <li><a href="https://en.wikipedia.org/wiki/Topological_sorting">Topological sorting</a></li>
 *   <li><a href="https://en.wikipedia.org/wiki/Depth-first_search">Depth-first search</a></li>
 * </ul>
 * </p>
 */

public final class PredecessorConstrainedDfs {

    private PredecessorConstrainedDfs() {
        // utility class
    }

    /** An event emitted by the traversal: either a VISIT with an order, or a SKIP with a note. */
    public record TraversalEvent<T>(T node,
        Integer order, // non-null for visit, null for skip
        String note // non-null for skip, null for visit
    ) {
        public TraversalEvent {
            Objects.requireNonNull(node);
            // order and note can be null based on event type
        }

        /** A visit event with an increasing order (0,1,2,...) */
        public static <T> TraversalEvent<T> visit(T node, int order) {
            return new TraversalEvent<>(node, order, null);
        }

        /** A skip event with an explanatory note (e.g., not all parents visited yet). */
        public static <T> TraversalEvent<T> skip(T node, String note) {
            return new TraversalEvent<>(node, null, Objects.requireNonNull(note));
        }

        public boolean isVisit() {
            return order != null;
        }

        public boolean isSkip() {
            return order == null;
        }

        @Override
        public String toString() {
            return isVisit() ? "VISIT(" + node + ", order=" + order + ")" : "SKIP(" + node + ", " + note + ")";
        }
    }

    /**
     * DFS (recursive) that records the order of first visit starting at {@code start},
     * but only recurses to a child when <b>all</b> its predecessors have been visited.
     * If a child is encountered early (some parent unvisited), a SKIP event is recorded.
     *
     * <p>Equivalent idea to the Python pseudo in the user's description (with successors and predecessors),
     * but implemented in Java and returning a sequence of {@link TraversalEvent}s.</p>
     *
     * @param successors adjacency list: for each node, its outgoing neighbors
     * @param start start node
     * @return immutable list of traversal events (VISITs with monotonically increasing order and SKIPs with messages)
     * @throws IllegalArgumentException if {@code successors} is null
     */
    public static <T> List<TraversalEvent<T>> dfsRecursiveOrder(Map<T, List<T>> successors, T start) {
        if (successors == null) {
            throw new IllegalArgumentException("successors must not be null");
        }
        // derive predecessors once
        Map<T, List<T>> predecessors = derivePredecessors(successors);
        return dfsRecursiveOrder(successors, predecessors, start);
    }

    /**
     * Same as {@link #dfsRecursiveOrder(Map, Object)} but with an explicit predecessors map.
     */
    public static <T> List<TraversalEvent<T>> dfsRecursiveOrder(Map<T, List<T>> successors, Map<T, List<T>> predecessors, T start) {

        if (successors == null || predecessors == null) {
            throw new IllegalArgumentException("successors and predecessors must not be null");
        }
        if (start == null) {
            return List.of();
        }
        if (!successors.containsKey(start) && !appearsAnywhere(successors, start)) {
            return List.of(); // start not present in graph
        }

        List<TraversalEvent<T>> events = new ArrayList<>();
        Set<T> visited = new HashSet<>();
        int[] order = {0};
        dfs(start, successors, predecessors, visited, order, events);
        return Collections.unmodifiableList(events);
    }

    private static <T> void dfs(T currentNode, Map<T, List<T>> successors, Map<T, List<T>> predecessors, Set<T> visited, int[] order, List<TraversalEvent<T>> result) {

        if (!visited.add(currentNode)) {
            return; // already visited
        }
        result.add(TraversalEvent.visit(currentNode, order[0]++)); // record visit and increment

        for (T childNode : successors.getOrDefault(currentNode, List.of())) {
            if (visited.contains(childNode)) {
                continue;
            }
            if (allParentsVisited(childNode, visited, predecessors)) {
                dfs(childNode, successors, predecessors, visited, order, result);
            } else {
                result.add(TraversalEvent.skip(childNode, "⛔ Skipping " + childNode + ": not all parents are visited yet."));
                // do not mark visited; it may be visited later from another parent
            }
        }
    }

    private static <T> boolean allParentsVisited(T node, Set<T> visited, Map<T, List<T>> predecessors) {
        for (T parent : predecessors.getOrDefault(node, List.of())) {
            if (!visited.contains(parent)) {
                return false;
            }
        }
        return true;
    }

    private static <T> boolean appearsAnywhere(Map<T, List<T>> successors, T node) {
        if (successors.containsKey(node)) {
            return true;
        }
        for (List<T> neighbours : successors.values()) {
            if (neighbours != null && neighbours.contains(node)) {
                return true;
            }
        }
        return false;
    }

    private static <T> Map<T, List<T>> derivePredecessors(Map<T, List<T>> successors) {
        Map<T, List<T>> predecessors = new HashMap<>();
        // ensure keys exist for all nodes appearing anywhere
        for (Map.Entry<T, List<T>> entry : successors.entrySet()) {
            predecessors.computeIfAbsent(entry.getKey(), key -> new ArrayList<>());
            for (T childNode : entry.getValue()) {
                predecessors.computeIfAbsent(childNode, key -> new ArrayList<>()).add(entry.getKey());
            }
        }
        return predecessors;
    }
}

package com.thealgorithms.ciphers;

import java.math.BigInteger;
import java.security.SecureRandom;

/**
 * RSA is an asymmetric cryptographic algorithm used for secure data encryption and decryption.
 * It relies on a pair of keys: a public key (used for encryption) and a private key
 * (used for decryption). The algorithm is based on the difficulty of factoring large prime numbers.
 *
 * This implementation includes key generation, encryption, and decryption methods that can handle both
 * text-based messages and BigInteger inputs. For more details on RSA:
 * <a href="https://en.wikipedia.org/wiki/RSA_(cryptosystem)">RSA Cryptosystem - Wikipedia</a>.
 *
 * Example Usage:
 * <pre>
 * RSA rsa = new RSA(1024);
 * String encryptedMessage = rsa.encrypt("Hello RSA!");
 * String decryptedMessage = rsa.decrypt(encryptedMessage);
 * System.out.println(decryptedMessage);  // Output: Hello RSA!
 * </pre>
 *
 * Note: The key size directly affects the security and performance of the RSA algorithm.
 * Larger keys are more secure but slower to compute.
 *
 * @author Nguyen Duy Tiep
 * @version 23-Oct-17
 */
public class RSA {

    private BigInteger modulus;
    private BigInteger privateKey;
    private BigInteger publicKey;

    /**
     * Constructor that generates RSA keys with the specified number of bits.
     *
     * @param bits The bit length of the keys to be generated. Common sizes include 512, 1024, 2048, etc.
     */
    public RSA(int bits) {
        generateKeys(bits);
    }

    /**
     * Encrypts a text message using the RSA public key.
     *
     * @param message The plaintext message to be encrypted.
     * @throws IllegalArgumentException If the message is empty.
     * @return The encrypted message represented as a String.
     */
    public synchronized String encrypt(String message) {
        if (message.isEmpty()) {
            throw new IllegalArgumentException("Message is empty");
        }
        return (new BigInteger(message.getBytes())).modPow(publicKey, modulus).toString();
    }

    /**
     * Encrypts a BigInteger message using the RSA public key.
     *
     * @param message The plaintext message as a BigInteger.
     * @return The encrypted message as a BigInteger.
     */
    public synchronized BigInteger encrypt(BigInteger message) {
        return message.modPow(publicKey, modulus);
    }

    /**
     * Decrypts an encrypted message (as String) using the RSA private key.
     *
     * @param encryptedMessage The encrypted message to be decrypted, represented as a String.
     * @throws IllegalArgumentException If the message is empty.
     * @return The decrypted plaintext message as a String.
     */
    public synchronized String decrypt(String encryptedMessage) {
        if (encryptedMessage.isEmpty()) {
            throw new IllegalArgumentException("Message is empty");
        }
        return new String((new BigInteger(encryptedMessage)).modPow(privateKey, modulus).toByteArray());
    }

    /**
     * Decrypts an encrypted BigInteger message using the RSA private key.
     *
     * @param encryptedMessage The encrypted message as a BigInteger.
     * @return The decrypted plaintext message as a BigInteger.
     */
    public synchronized BigInteger decrypt(BigInteger encryptedMessage) {
        return encryptedMessage.modPow(privateKey, modulus);
    }

    /**
     * Generates a new RSA key pair (public and private keys) with the specified bit length.
     * Steps:
     * 1. Generate two large prime numbers p and q.
     * 2. Compute the modulus n = p * q.
     * 3. Compute Euler's totient function: φ(n) = (p-1) * (q-1).
     * 4. Choose a public key e (starting from 3) that is coprime with φ(n).
     * 5. Compute the private key d as the modular inverse of e mod φ(n).
     * The public key is (e, n) and the private key is (d, n).
     *
     * @param bits The bit length of the keys to be generated.
     */
    public final synchronized void generateKeys(int bits) {
        SecureRandom random = new SecureRandom();
        BigInteger p = new BigInteger(bits / 2, 100, random);
        BigInteger q = new BigInteger(bits / 2, 100, random);
        modulus = p.multiply(q);

        BigInteger phi = (p.subtract(BigInteger.ONE)).multiply(q.subtract(BigInteger.ONE));

        publicKey = BigInteger.valueOf(3L);
        while (phi.gcd(publicKey).intValue() > 1) {
            publicKey = publicKey.add(BigInteger.TWO);
        }

        privateKey = publicKey.modInverse(phi);
    }
}

